export interface MCQItem {
  id: string;
  section: string;
  unit: string;
  chapter: string;
  questionNumber: string;
  question: string;
  options: {
    A: string;
    B: string;
    C: string;
    D: string;
  };
  correctOption: "A" | "B" | "C" | "D";
  correctAnswer: string;
  questionType: "MCQ";
  explanation: {
    correct_reason: string;
    distractor_reasons: {
      A: string;
      B: string;
      C: string;
      D: string;
    };
  };
}

export const MCQ_BANK_5: MCQItem[] = [{"id":"P1_U5_MCQ_001","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_001","question":"A newly opened artisan bakery needs finance to pay weekly staff wages and buy flour and sugar before customers pay for their orders. Which type of finance need does this describe?","options":{"A":"Start-up capital for non-current assets","B":"Working capital for day-to-day operations","C":"Long-term capital for international expansion","D":"Capital for replacing worn-out machinery"},"correctOption":"B","correctAnswer":"Working capital for day-to-day operations","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because working capital is the finance needed to pay for everyday running expenses such as wages, raw materials, and utility bills.","distractor_reasons":{"A":"Incorrect because start-up capital for non-current assets funds long-term items like ovens and premises rather than recurring weekly wages and ingredients.","B":"Option B is correct because working capital is the finance needed to pay for everyday running expenses such as wages, raw materials, and utility bills.","C":"Incorrect because expansion capital is used to grow operations into new markets rather than covering routine daily trading costs.","D":"Incorrect because replacing machinery involves purchasing non-current assets rather than funding short-term operational expenses."}}},{"id":"P1_U5_MCQ_002","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_002","question":"A profitable private limited company plans to build three new regional distribution warehouses over the next eight years. Which external source of finance is most appropriate for this expansion?","options":{"A":"A bank overdraft","B":"Trade credit from suppliers","C":"A long-term bank loan","D":"Selling shares on the stock exchange"},"correctOption":"C","correctAnswer":"A long-term bank loan","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a long-term bank loan provides a large sum of finance repaid over several years, matching the long-term nature of building warehouses.","distractor_reasons":{"A":"Incorrect because a bank overdraft is a short-term facility for temporary working capital deficits and can be recalled by the bank at short notice.","B":"Incorrect because trade credit only delays payment for inventory by a few weeks and cannot fund major construction projects.","C":"Option C is correct because a long-term bank loan provides a large sum of finance repaid over several years, matching the long-term nature of building warehouses.","D":"Incorrect because a private limited company is legally prohibited from selling shares to the general public on a stock exchange."}}},{"id":"P1_U5_MCQ_003","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_003","question":"A courier company needs to replace ten ageing delivery vans immediately without paying a large upfront lump sum, and it prefers the finance provider to handle maintenance and repairs. Which source of finance should the company choose?","options":{"A":"Leasing","B":"Retained profit","C":"Government grants","D":"Issuing new ordinary shares"},"correctOption":"A","correctAnswer":"Leasing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing allows a business to use non-current assets in return for regular rental payments without a large upfront outlay, and maintenance is usually included.","distractor_reasons":{"A":"Option A is correct because leasing allows a business to use non-current assets in return for regular rental payments without a large upfront outlay, and maintenance is usually included.","B":"Incorrect because buying ten vans outright with retained profit would require a large immediate cash outflow and leave the courier responsible for maintenance.","C":"Incorrect because government grants are typically awarded for job creation or relocating to deprived areas rather than routine vehicle replacement.","D":"Incorrect because issuing shares is slow, costly, and dilutes ownership control for a medium-term vehicle replacement need."}}},{"id":"P1_U5_MCQ_004","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_004","question":"A car parts manufacturer wants to invest $800,000 in automated robotic welding equipment to improve efficiency over the next decade. Why would trade credit be unsuitable for financing this investment?","options":{"A":"Trade credit requires giving up equity ownership to suppliers","B":"Trade credit charges a higher annual interest rate than a bank overdraft","C":"Trade credit is only available to public limited companies","D":"Trade credit only provides short-term delayed payment for raw materials and inventory"},"correctOption":"D","correctAnswer":"Trade credit only provides short-term delayed payment for raw materials and inventory","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade credit is a short-term arrangement with suppliers for purchasing materials or goods for resale, not for funding expensive long-term machinery.","distractor_reasons":{"A":"Incorrect because trade credit is a supplier payment arrangement and does not involve selling shares or giving up ownership.","B":"Incorrect because trade credit is usually interest-free during the agreed credit period, though early-payment discounts may be lost.","C":"Incorrect because sole traders, partnerships, and companies can all receive trade credit from suppliers.","D":"Option D is correct because trade credit is a short-term arrangement with suppliers for purchasing materials or goods for resale, not for funding expensive long-term machinery."}}},{"id":"P1_U5_MCQ_005","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_005","question":"A small furniture workshop has plenty of customer orders, but it cannot pay its electricity bill or purchase timber because all of its cash is tied up in unpaid customer invoices. What does this situation demonstrate about working capital?","options":{"A":"Working capital is only needed during the first month of trading","B":"Insufficient working capital can prevent a business from paying short-term debts and operating smoothly","C":"Working capital is used solely to purchase property and machinery","D":"High customer orders automatically guarantee sufficient working capital"},"correctOption":"B","correctAnswer":"Insufficient working capital can prevent a business from paying short-term debts and operating smoothly","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because adequate working capital is essential to pay day-to-day operational expenses and short-term liabilities on time.","distractor_reasons":{"A":"Incorrect because working capital is needed continuously throughout the life of a business, not just at start-up.","B":"Option B is correct because adequate working capital is essential to pay day-to-day operational expenses and short-term liabilities on time.","C":"Incorrect because property and machinery are funded by long-term capital, whereas working capital funds short-term current operations.","D":"Incorrect because credit sales increase trade receivables rather than immediate cash, which can strain working capital."}}},{"id":"P1_U5_MCQ_006","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_006","question":"A seasonal gift retailer needs $12,000 for six weeks to buy extra inventory ahead of a national festival, after which cash from sales will quickly repay the amount borrowed. Which source of finance is most suitable?","options":{"A":"A 10-year bank loan","B":"Venture capital","C":"A bank overdraft","D":"Hire purchase"},"correctOption":"C","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a bank overdraft is flexible and short-term, allowing the retailer to borrow only what is needed for six weeks and pay interest only on the daily overdrawn balance.","distractor_reasons":{"A":"Incorrect because a 10-year bank loan commits the business to long-term interest payments for a temporary six-week need.","B":"Incorrect because venture capital is long-term equity finance for high-growth companies rather than short-term seasonal inventory.","C":"Option C is correct because a bank overdraft is flexible and short-term, allowing the retailer to borrow only what is needed for six weeks and pay interest only on the daily overdrawn balance.","D":"Incorrect because hire purchase is used to acquire non-current assets over several years, not inventory for resale."}}},{"id":"P1_U5_MCQ_007","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_007","question":"An entrepreneur uses $15,000 of her own personal savings to launch a mobile pet-grooming business as a sole trader. What is a key advantage of using this internal source of finance?","options":{"A":"No interest has to be paid and the owner retains full control of the business","B":"The amount of capital available is unlimited","C":"The entrepreneur's personal wealth is protected by limited liability","D":"The money is guaranteed to be refunded by the government if the business fails"},"correctOption":"A","correctAnswer":"No interest has to be paid and the owner retains full control of the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because owners' investment is an internal source of finance that incurs no interest charges and avoids sharing ownership or decision-making control.","distractor_reasons":{"A":"Option A is correct because owners' investment is an internal source of finance that incurs no interest charges and avoids sharing ownership or decision-making control.","B":"Incorrect because personal savings are usually strictly limited, which is a disadvantage of relying solely on owners' investment.","C":"Incorrect because a sole trader has unlimited liability regardless of how the business is financed.","D":"Incorrect because owners' investment carries personal financial risk and is lost if the business fails."}}},{"id":"P1_U5_MCQ_008","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_008","question":"A well-established software company has accumulated $400,000 in retained profit over the last three years and uses it to fund the development of a new mobile app. What is a potential disadvantage of using retained profit for this project?","options":{"A":"The company must pay high monthly interest charges to its bank","B":"Existing shareholders will lose voting control to new external investors","C":"The company must provide non-current assets as collateral","D":"Shareholders may receive lower dividends in the short term"},"correctOption":"D","correctAnswer":"Shareholders may receive lower dividends in the short term","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because reinvesting profit back into the business reduces the amount of after-tax profit available to distribute as dividends to shareholders.","distractor_reasons":{"A":"Incorrect because retained profit is an internal source of finance with no interest charges.","B":"Incorrect because retained profit does not involve issuing new shares to external investors.","C":"Incorrect because collateral is required for secured bank loans, not for using internal retained profit.","D":"Option D is correct because reinvesting profit back into the business reduces the amount of after-tax profit available to distribute as dividends to shareholders."}}},{"id":"P1_U5_MCQ_009","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_009","question":"A textile manufacturer closes an outdated storage depot and sells the surplus land and old forklifts to help pay for new sewing machines. Which internal source of finance is the business using?","options":{"A":"Reducing working capital","B":"Sale of unwanted assets","C":"Owners' investment","D":"Crowdfunding"},"correctOption":"B","correctAnswer":"Sale of unwanted assets","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because selling surplus non-current assets such as unused land and old equipment generates cash internally without increasing debt.","distractor_reasons":{"A":"Incorrect because reducing working capital involves lowering inventory levels or collecting trade receivables faster rather than selling non-current assets.","B":"Option B is correct because selling surplus non-current assets such as unused land and old equipment generates cash internally without increasing debt.","C":"Incorrect because owners' investment involves owners injecting new personal capital into the business.","D":"Incorrect because crowdfunding is an external source of finance raised from the public online."}}},{"id":"P1_U5_MCQ_010","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_010","question":"An electronics retailer needs $30,000 to upgrade its website and decides to raise the cash internally by holding less inventory in its warehouse and chasing overdue payments from business customers. Which source of finance is being used?","options":{"A":"Retained profit","B":"Sale of non-current assets","C":"Working capital","D":"Trade credit"},"correctOption":"C","correctAnswer":"Working capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because freeing up cash tied up in inventory and trade receivables is using working capital as an internal source of finance.","distractor_reasons":{"A":"Incorrect because retained profit comes from past trading surpluses rather than converting existing current assets into cash.","B":"Incorrect because inventory held for resale is a current asset, not a non-current asset.","C":"Option C is correct because freeing up cash tied up in inventory and trade receivables is using working capital as an internal source of finance.","D":"Incorrect because trade credit is an external source obtained by delaying payments to suppliers, not collecting from customers."}}},{"id":"P1_U5_MCQ_011","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_011","question":"A large public limited company wants to raise $25 million to enter overseas markets without increasing its debt or interest obligations. Why might the directors choose to issue new shares?","options":{"A":"Share capital is permanent finance that does not have to be repaid and incurs no interest","B":"Issuing new shares guarantees that existing majority shareholders keep 100% control","C":"Share capital can be arranged within 24 hours with zero legal or administrative costs","D":"Dividends paid to new shareholders are legally fixed regardless of company profit"},"correctOption":"A","correctAnswer":"Share capital is permanent finance that does not have to be repaid and incurs no interest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because share capital raises large sums permanently without contractual repayment dates or interest expenses.","distractor_reasons":{"A":"Option A is correct because share capital raises large sums permanently without contractual repayment dates or interest expenses.","B":"Incorrect because issuing new shares to the public dilutes the ownership percentage and control of existing shareholders.","C":"Incorrect because issuing shares on a stock exchange involves high administrative, legal, and advertising costs and takes considerable time.","D":"Incorrect because ordinary dividends are not fixed and are only paid if the company makes sufficient profit and directors declare them."}}},{"id":"P1_U5_MCQ_012","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_012","question":"A profitable partnership running three dental clinics wants to raise $600,000 to open a fourth clinic, but its bank refuses a loan due to lack of collateral. Why can the partners not raise this money by issuing shares on the stock exchange?","options":{"A":"Issuing shares is only allowed for businesses in the secondary sector","B":"Partnerships are only permitted to use internal sources of finance","C":"Stock exchanges only provide short-term working capital","D":"Only public limited companies can sell shares to the general public"},"correctOption":"D","correctAnswer":"Only public limited companies can sell shares to the general public","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because legal form restricts share issues; unincorporated partnerships cannot issue shares, and only public limited companies can offer shares on a stock exchange.","distractor_reasons":{"A":"Incorrect because service-sector public limited companies can also issue shares on a stock exchange.","B":"Incorrect because partnerships can use external finance such as bank loans, overdrafts, leasing, and trade credit.","C":"Incorrect because share capital raised on a stock exchange is permanent long-term finance.","D":"Option D is correct because legal form restricts share issues; unincorporated partnerships cannot issue shares, and only public limited companies can offer shares on a stock exchange."}}},{"id":"P1_U5_MCQ_013","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_013","question":"A young biotechnology private limited company has developed a promising medical device but has no track record of profit, so traditional banks consider lending to it too risky. Which external finance providers specialise in investing capital in such high-risk, high-growth businesses in exchange for an ownership stake?","options":{"A":"Commercial overdraft providers","B":"Venture capitalists","C":"Trade creditors","D":"Hire purchase companies"},"correctOption":"B","correctAnswer":"Venture capitalists","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because venture capitalists invest capital and specialist business expertise into small or medium-sized high-growth companies in return for equity shares.","distractor_reasons":{"A":"Incorrect because commercial banks avoid high-risk start-ups without collateral or steady cash flows.","B":"Option B is correct because venture capitalists invest capital and specialist business expertise into small or medium-sized high-growth companies in return for equity shares.","C":"Incorrect because trade creditors are suppliers providing short-term credit on goods, not equity investors.","D":"Incorrect because hire purchase firms finance specific physical assets rather than investing equity into R&D companies."}}},{"id":"P1_U5_MCQ_014","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_014","question":"A wholesale fruit distributor experiences unpredictable weekly gaps between paying farmers and receiving payments from supermarkets. Why is a bank overdraft more suitable than a bank loan for managing this cash flow pattern?","options":{"A":"A bank overdraft has a lower annual interest rate than a secured bank loan","B":"A bank overdraft never needs to be repaid to the bank","C":"Interest is only paid on the exact amount overdrawn each day, making it flexible for fluctuating needs","D":"A bank overdraft guarantees a fixed interest rate for ten years"},"correctOption":"C","correctAnswer":"Interest is only paid on the exact amount overdrawn each day, making it flexible for fluctuating needs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an overdraft allows a business to overdraw its current account up to an agreed limit and pay interest only on the daily overdrawn balance.","distractor_reasons":{"A":"Incorrect because overdraft interest rates are typically higher than those on long-term secured bank loans.","B":"Incorrect because an overdraft is repayable on demand by the bank and is meant to be cleared regularly.","C":"Option C is correct because an overdraft allows a business to overdraw its current account up to an agreed limit and pay interest only on the daily overdrawn balance.","D":"Incorrect because overdrafts are short-term facilities with variable interest rates, not 10-year fixed-rate agreements."}}},{"id":"P1_U5_MCQ_015","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_015","question":"A printing company wants to acquire a high-speed digital press worth $90,000, pay for it in monthly instalments over four years, and legally own the machine once the final payment is made. Which source of finance matches this requirement?","options":{"A":"Bank overdraft","B":"Operating leasing","C":"Hire purchase","D":"Working capital"},"correctOption":"C","correctAnswer":"Hire purchase","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because hire purchase allows a business to buy a non-current asset via regular instalments and become the legal owner upon making the final payment.","distractor_reasons":{"A":"Incorrect because an overdraft is a short-term working capital facility rather than an asset-purchase instalment agreement.","B":"Incorrect because under leasing, legal ownership of the asset remains with the leasing company rather than transferring to the user.","C":"Option C is correct because hire purchase allows a business to buy a non-current asset via regular instalments and become the legal owner upon making the final payment.","D":"Incorrect because working capital refers to short-term funds for daily expenses, not buying a $90,000 printing press."}}},{"id":"P1_U5_MCQ_016","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_016","question":"A café owner borrows $30,000 from a bank to renovate her premises, agreeing to repay the principal plus interest in fixed monthly amounts over five years. What is a major advantage of this bank loan compared with a bank overdraft?","options":{"A":"No interest is charged on a bank loan","B":"The bank does not require any financial forecasts or collateral","C":"The café owner can vary the repayment amount every month depending on sales","D":"Fixed monthly repayments make financial planning and budgeting easier"},"correctOption":"D","correctAnswer":"Fixed monthly repayments make financial planning and budgeting easier","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a bank loan has a set repayment schedule over an agreed period, allowing the business to plan its cash outflows accurately.","distractor_reasons":{"A":"Incorrect because banks charge interest on loans as their return for lending money.","B":"Incorrect because banks usually require a business plan, cash flow forecast, and collateral before approving a loan.","C":"Incorrect because bank loans require fixed regular repayments rather than flexible daily adjustments.","D":"Option D is correct because a bank loan has a set repayment schedule over an agreed period, allowing the business to plan its cash outflows accurately."}}},{"id":"P1_U5_MCQ_017","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_017","question":"A clothing store negotiates with its fabric supplier to delay paying a $10,000 invoice for 60 days so it can sell the clothes before paying for them. What is a potential drawback of relying heavily on this source of finance?","options":{"A":"The supplier becomes a part-owner of the clothing store","B":"The store may lose early-payment discounts or damage supplier relationships if payments are late","C":"The store must offer its shop premises as security to the supplier","D":"Trade credit counts as a non-current liability on the statement of financial position"},"correctOption":"B","correctAnswer":"The store may lose early-payment discounts or damage supplier relationships if payments are late","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because taking extended trade credit often means forfeiting discounts for prompt payment, and paying late can lead suppliers to refuse future deliveries.","distractor_reasons":{"A":"Incorrect because trade credit is a commercial debt arrangement and does not grant equity ownership.","B":"Option B is correct because taking extended trade credit often means forfeiting discounts for prompt payment, and paying late can lead suppliers to refuse future deliveries.","C":"Incorrect because trade credit is unsecured short-term credit rather than a secured mortgage.","D":"Incorrect because trade payables are due within 12 months and are recorded as current liabilities."}}},{"id":"P1_U5_MCQ_018","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_018","question":"A solar panel manufacturer plans to build a new assembly plant in an economically depressed region where the government wants to create jobs. Which external source of finance might the manufacturer obtain that does not need to be repaid?","options":{"A":"Venture capital","B":"A bank loan","C":"A government grant","D":"Hire purchase"},"correctOption":"C","correctAnswer":"A government grant","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because government grants are financial awards given to businesses—often to encourage job creation or investment in specific regions—that do not require repayment if conditions are met.","distractor_reasons":{"A":"Incorrect because venture capitalists expect shares in the business and a high financial return when exiting.","B":"Incorrect because a bank loan must be repaid in full with interest.","C":"Option C is correct because government grants are financial awards given to businesses—often to encourage job creation or investment in specific regions—that do not require repayment if conditions are met.","D":"Incorrect because hire purchase requires paying full instalments plus interest to acquire an asset."}}},{"id":"P1_U5_MCQ_019","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_019","question":"An independent designer creates a prototype for an eco-friendly backpack and uses an online platform to collect small contributions from 2,500 supporters in exchange for early delivery of the product. Which source of finance is the designer using?","options":{"A":"Trade credit","B":"Retained profit","C":"Leasing","D":"Crowdfunding"},"correctOption":"D","correctAnswer":"Crowdfunding","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because crowdfunding involves raising small sums of money from a large number of people, usually via the internet, to finance a new venture or product.","distractor_reasons":{"A":"Incorrect because trade credit is delayed payment granted by suppliers.","B":"Incorrect because retained profit comes from past profits of an existing business rather than external public backers.","C":"Incorrect because leasing is renting non-current assets from a finance company.","D":"Option D is correct because crowdfunding involves raising small sums of money from a large number of people, usually via the internet, to finance a new venture or product."}}},{"id":"P1_U5_MCQ_020","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_020","question":"A medium-sized manufacturing company already has large existing bank loans and high monthly interest repayments. Why would the finance director advise against taking out another large bank loan to fund factory expansion?","options":{"A":"Bank loans reduce the company's total assets","B":"Taking another loan forces the company to convert into a sole trader","C":"Bank loans cannot be used to purchase factory buildings","D":"Additional debt increases financial risk and interest costs, making banks reluctant to lend further"},"correctOption":"D","correctAnswer":"Additional debt increases financial risk and interest costs, making banks reluctant to lend further","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because existing loans are a key factor when choosing finance; high existing debt raises default risk, increases interest burdens, and reduces the likelihood of loan approval.","distractor_reasons":{"A":"Incorrect because a bank loan increases cash or non-current assets alongside increasing liabilities.","B":"Incorrect because borrowing from a bank does not alter a business's legal structure.","C":"Incorrect because long-term bank loans and mortgages are commonly used to purchase factory buildings.","D":"Option D is correct because existing loans are a key factor when choosing finance; high existing debt raises default risk, increases interest burdens, and reduces the likelihood of loan approval."}}},{"id":"P1_U5_MCQ_021","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_021","question":"A small family-owned restaurant wants to buy a $4,000 commercial dishwasher. Which factor best explains why issuing shares is NOT a realistic option for raising this finance?","options":{"A":"Commercial dishwashers must legally be bought using retained profit","B":"The amount required is too small to justify the legal and administrative costs of a share issue","C":"Share capital can only be used to pay employee wages","D":"Restaurants are not allowed to raise external finance"},"correctOption":"B","correctAnswer":"The amount required is too small to justify the legal and administrative costs of a share issue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the amount required ($4,000) is far too small to justify the time, legal formalities, and expense of issuing shares.","distractor_reasons":{"A":"Incorrect because equipment can be bought using cash, loans, leasing, or hire purchase.","B":"Option B is correct because the amount required ($4,000) is far too small to justify the time, legal formalities, and expense of issuing shares.","C":"Incorrect because share capital is long-term finance typically used for expansion and non-current assets, not routine wages.","D":"Incorrect because restaurants can use external sources such as bank loans, overdrafts, leasing, and hire purchase."}}},{"id":"P1_U5_MCQ_022","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_022","question":"A logistics company is comparing a bank loan and a share issue to raise $2 million for a new warehouse. If the company's main priority is to minimise the ongoing cost of finance and avoid paying regular interest, which option aligns best with this factor?","options":{"A":"Arranging a $2 million bank overdraft","B":"Taking a variable-rate bank loan","C":"Issuing new ordinary shares","D":"Using 30-day trade credit"},"correctOption":"C","correctAnswer":"Issuing new ordinary shares","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because issuing ordinary shares carries no fixed interest payments, and dividends only need to be paid if the company earns sufficient profit.","distractor_reasons":{"A":"Incorrect because a bank overdraft is short-term and charges high interest rates.","B":"Incorrect because a bank loan requires mandatory regular interest payments regardless of profit levels.","C":"Option C is correct because issuing ordinary shares carries no fixed interest payments, and dividends only need to be paid if the company earns sufficient profit.","D":"Incorrect because trade credit is only for short-term inventory purchases, not a $2 million warehouse."}}},{"id":"P1_U5_MCQ_023","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_023","question":"The owners of a private limited company want to expand rapidly by opening ten new stores, but they strongly refuse to lose majority control over business decisions. Why might they prefer a long-term bank loan over selling a 45% stake to venture capitalists?","options":{"A":"A bank loan does not dilute ownership or give the lender voting rights in the company","B":"A bank loan never requires any collateral or security","C":"Venture capitalists charge higher daily interest than a bank overdraft","D":"Private limited companies are not permitted to accept venture capital"},"correctOption":"A","correctAnswer":"A bank loan does not dilute ownership or give the lender voting rights in the company","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lenders provide debt finance without becoming shareholders, allowing existing owners to retain full voting control over the business.","distractor_reasons":{"A":"Option A is correct because lenders provide debt finance without becoming shareholders, allowing existing owners to retain full voting control over the business.","B":"Incorrect because banks normally require collateral (such as property) for large long-term loans.","C":"Incorrect because venture capitalists take an equity share and seek capital growth/dividends rather than charging daily interest.","D":"Incorrect because private limited companies can sell shares privately to venture capitalists."}}},{"id":"P1_U5_MCQ_024","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_024","question":"A sole trader operates a small carpentry business from a rented workshop and needs $2,500 to buy timber for a large customer order that will be paid in 45 days. Which combination of factors most strongly points toward using trade credit or a short-term overdraft?","options":{"A":"Large amount required and public limited legal status","B":"Long-term time period and purchase of land","C":"High existing retained profit and international expansion","D":"Small amount required, unincorporated legal form, and short-term working capital purpose"},"correctOption":"D","correctAnswer":"Small amount required, unincorporated legal form, and short-term working capital purpose","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the small sum ($2,500), sole trader status, and 45-day working capital purpose directly match short-term sources like trade credit or an overdraft.","distractor_reasons":{"A":"Incorrect because $2,500 is a small amount and a sole trader is unincorporated, not a public limited company.","B":"Incorrect because the finance is needed for 45 days to buy raw materials (timber), not long-term land.","C":"Incorrect because the business is a small local workshop funding a single order, not expanding internationally.","D":"Option D is correct because the small sum ($2,500), sole trader status, and 45-day working capital purpose directly match short-term sources like trade credit or an overdraft."}}},{"id":"P1_U5_MCQ_025","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_025","question":"To launch a new catering business, an entrepreneur invests $32,000 of personal savings, raises $6,000 by selling an unused personal delivery van to the business, and secures a $10,000 government start-up grant. How much of this start-up finance comes from internal sources?","options":{"A":"$48,000","B":"$32,000","C":"$38,000","D":"$16,000"},"correctOption":"C","correctAnswer":"$38,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal sources of finance include the owner's personal investment ($32,000) and the sale of unwanted assets ($6,000), totalling $38,000, whereas the government grant is external.","distractor_reasons":{"A":"Incorrect because $48,000 includes the $10,000 government grant, which is an external source of finance.","B":"Incorrect because $32,000 omits the $6,000 raised from the sale of the unwanted asset.","C":"Option C is correct because internal sources of finance include the owner's personal investment ($32,000) and the sale of unwanted assets ($6,000), totalling $38,000, whereas the government grant is external.","D":"Incorrect because $16,000 adds the asset sale and external grant while omitting the owner's $32,000 investment."}}},{"id":"P1_U5_MCQ_026","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_026","question":"A profitable building contractor is forced to cease trading because it has no money in its bank account to pay its bricklayers' weekly wages or buy cement. Why is cash so vital to the survival of a business?","options":{"A":"Cash is needed to pay day-to-day obligations such as wages, suppliers, and bills as they fall due","B":"Cash is the only figure reported on a statement of profit or loss","C":"Businesses cannot legally make credit sales unless they hold large cash reserves","D":"Cash held in a current account always earns a higher return than investing in machinery"},"correctOption":"A","correctAnswer":"Cash is needed to pay day-to-day obligations such as wages, suppliers, and bills as they fall due","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because without sufficient cash (liquidity), a business cannot pay employees, suppliers, or landlords on time and may be forced into liquidation even if it is profitable.","distractor_reasons":{"A":"Option A is correct because without sufficient cash (liquidity), a business cannot pay employees, suppliers, or landlords on time and may be forced into liquidation even if it is profitable.","B":"Incorrect because the statement of profit or loss records revenue, cost of sales, expenses, and profit, not cash balances.","C":"Incorrect because there is no legal rule requiring cash reserves before offering trade credit to customers.","D":"Incorrect because cash in a bank account typically earns very low interest compared to productive non-current assets."}}},{"id":"P1_U5_MCQ_027","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_027","question":"Before approving a $40,000 loan for a new restaurant, a bank manager asks the entrepreneur to submit a cash flow forecast for the first 12 months. What does a cash flow forecast show?","options":{"A":"The historical revenue and expenses of the business over the past 12 months","B":"The market value of all non-current assets and equity at the end of the year","C":"An estimate of expected monthly cash inflows, cash outflows, and closing cash balances over a future period","D":"The exact amount of corporation tax the business paid last year"},"correctOption":"C","correctAnswer":"An estimate of expected monthly cash inflows, cash outflows, and closing cash balances over a future period","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a cash flow forecast is a forward-looking financial plan estimating expected cash receipts and payments month by month to predict surpluses or deficits.","distractor_reasons":{"A":"Incorrect because historical revenue and expenses are shown in a past statement of profit or loss, not a future cash flow forecast.","B":"Incorrect because assets, liabilities, and equity at a point in time are shown on a statement of financial position.","C":"Option C is correct because a cash flow forecast is a forward-looking financial plan estimating expected cash receipts and payments month by month to predict surpluses or deficits.","D":"Incorrect because past tax payments are historical records rather than a forecast of future monthly cash flows."}}},{"id":"P1_U5_MCQ_028","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_028","question":"The finance manager of a toy manufacturer prepares a six-month cash flow forecast every quarter. How does this forecast most directly help management make financial decisions?","options":{"A":"It calculates the exact gross profit margin on every toy sold","B":"It identifies future months with potential cash deficits in advance so an overdraft can be arranged","C":"It guarantees that all customers will pay their invoices on time","D":"It eliminates the need to prepare a statement of financial position"},"correctOption":"B","correctAnswer":"It identifies future months with potential cash deficits in advance so an overdraft can be arranged","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because forecasting future cash balances alerts managers early to potential cash shortfalls, giving them time to arrange an overdraft or adjust spending.","distractor_reasons":{"A":"Incorrect because gross profit margin is calculated from revenue and cost of sales in the statement of profit or loss.","B":"Option B is correct because forecasting future cash balances alerts managers early to potential cash shortfalls, giving them time to arrange an overdraft or adjust spending.","C":"Incorrect because a forecast estimates expected receipts; it does not legally force customers to pay promptly.","D":"Incorrect because limited companies are still legally required to produce end-of-year financial statements."}}},{"id":"P1_U5_MCQ_029","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_029","question":"A bicycle retailer records several transactions in October: $12,000 in cash sales, $8,000 in goods sold on 30-day credit, $5,000 received from September credit customers, and $7,000 paid to suppliers. Which items are recorded as October cash inflows?","options":{"A":"$12,000 cash sales and $8,000 October credit sales","B":"$12,000 cash sales, $8,000 October credit sales, and $5,000 from September customers","C":"$8,000 October credit sales and $7,000 paid to suppliers","D":"$12,000 cash sales and $5,000 received from September credit customers"},"correctOption":"D","correctAnswer":"$12,000 cash sales and $5,000 received from September credit customers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash inflows only record money actually entering the business during October ($12,000 cash sales + $5,000 collected from previous credit customers = $17,000).","distractor_reasons":{"A":"Incorrect because the $8,000 credit sales made in October will not generate a cash inflow until November.","B":"Incorrect because including both October credit sales and September receipts double-counts credit transactions before cash arrives.","C":"Incorrect because $8,000 is an unpaid credit sale and $7,000 paid to suppliers is a cash outflow.","D":"Option D is correct because cash inflows only record money actually entering the business during October ($12,000 cash sales + $5,000 collected from previous credit customers = $17,000)."}}},{"id":"P1_U5_MCQ_030","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_030","question":"During November, a printing business pays $6,500 in staff wages, receives a $15,000 bank loan, orders $4,000 of paper on 60-day trade credit, and pays $2,000 in workshop rent. Which items are November cash outflows?","options":{"A":"$15,000 bank loan and $6,500 wages","B":"$6,500 wages, $2,000 rent, and $4,000 paper ordered on 60-day credit","C":"$6,500 wages and $2,000 workshop rent","D":"$4,000 paper ordered on 60-day credit and $15,000 bank loan"},"correctOption":"C","correctAnswer":"$6,500 wages and $2,000 workshop rent","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash outflows only include money actually leaving the business in November ($6,500 wages + $2,000 rent = $8,500).","distractor_reasons":{"A":"Incorrect because receiving a $15,000 bank loan is a cash inflow, not an outflow.","B":"Incorrect because the $4,000 paper ordered on 60-day trade credit will not be a cash outflow until January.","C":"Option C is correct because cash outflows only include money actually leaving the business in November ($6,500 wages + $2,000 rent = $8,500).","D":"Incorrect because the loan is an inflow and the credit order has no cash movement in November."}}},{"id":"P1_U5_MCQ_031","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_031","question":"In July, a garden centre forecasts total cash inflows of $24,500 and total cash outflows of $28,200, with an opening bank balance of $5,000. What is the forecast net cash flow for July?","options":{"A":"$1,300","B":"$3,700","C":"-$3,700","D":"$52,700"},"correctOption":"C","correctAnswer":"-$3,700","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because net cash flow equals cash inflows minus cash outflows ($24,500 - $28,200 = -$3,700).","distractor_reasons":{"A":"Incorrect because $1,300 is the closing balance ($5,000 opening balance + (-$3,700) net cash flow), not the net cash flow.","B":"Incorrect because outflows exceed inflows, making the net cash flow negative (-$3,700) rather than positive.","C":"Option C is correct because net cash flow equals cash inflows minus cash outflows ($24,500 - $28,200 = -$3,700).","D":"Incorrect because $52,700 adds inflows and outflows together instead of subtracting outflows from inflows."}}},{"id":"P1_U5_MCQ_032","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_032","question":"A florist starts August with an opening cash balance of $3,200. During August, total cash inflows are $19,800 and total cash outflows are $16,400. What is the florist's closing cash balance at the end of August?","options":{"A":"$3,400","B":"$6,600","C":"-$200","D":"$23,000"},"correctOption":"B","correctAnswer":"$6,600","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because net cash flow is $19,800 - $16,400 = $3,400, and closing balance equals opening balance plus net cash flow ($3,200 + $3,400 = $6,600).","distractor_reasons":{"A":"Incorrect because $3,400 is the net cash flow for August and ignores the $3,200 opening balance.","B":"Option B is correct because net cash flow is $19,800 - $16,400 = $3,400, and closing balance equals opening balance plus net cash flow ($3,200 + $3,400 = $6,600).","C":"Incorrect because -$200 subtracts net cash flow from the opening balance instead of adding it.","D":"Incorrect because $23,000 adds opening balance and inflows without deducting the $16,400 cash outflows."}}},{"id":"P1_U5_MCQ_033","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_033","question":"A small hotel begins September with an overdrawn opening cash balance of -$2,400. During September, cash inflows are $31,000 and cash outflows are $27,500. What is the closing cash balance at the end of September?","options":{"A":"$3,500","B":"-$5,900","C":"$5,900","D":"$1,100"},"correctOption":"D","correctAnswer":"$1,100","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because September's net cash flow is $31,000 - $27,500 = +$3,500, and adding this to the -$2,400 opening balance gives a positive closing balance of $1,100.","distractor_reasons":{"A":"Incorrect because $3,500 is the net cash flow and ignores the -$2,400 overdrawn opening balance.","B":"Incorrect because -$5,900 subtracts the positive net cash flow from -$2,400 instead of adding it.","C":"Incorrect because $5,900 treats the -$2,400 overdraft as a positive opening balance.","D":"Option D is correct because September's net cash flow is $31,000 - $27,500 = +$3,500, and adding this to the -$2,400 opening balance gives a positive closing balance of $1,100."}}},{"id":"P1_U5_MCQ_034","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_034","question":"A courier business completes its cash flow forecast for Quarter 1 and finds that February ends with a closing balance of -$4,150. How is this figure used when preparing the forecast for March?","options":{"A":"It is recorded as a March cash outflow of $4,150","B":"It is entered as March's opening balance of -$4,150","C":"It is ignored so that March begins with an opening balance of $0","D":"It is deducted from March's total revenue on the statement of profit or loss"},"correctOption":"B","correctAnswer":"It is entered as March's opening balance of -$4,150","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the closing cash balance at the end of one month automatically carries forward to become the opening cash balance at the start of the next month.","distractor_reasons":{"A":"Incorrect because carrying a balance forward is not a new cash outflow transaction in March.","B":"Option B is correct because the closing cash balance at the end of one month automatically carries forward to become the opening cash balance at the start of the next month.","C":"Incorrect because resetting the opening balance to $0 would hide the existing overdraft and distort March's closing cash position.","D":"Incorrect because cash balances are not deducted from revenue in the statement of profit or loss."}}},{"id":"P1_U5_MCQ_035","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_035","question":"A coffee shop's April cash flow forecast shows an opening balance of $2,500, inflows of $14,000, and outflows of $13,000. The owner then decides to pay $4,800 cash in April for a new espresso machine. What is the amended April closing balance?","options":{"A":"$3,500","B":"$8,300","C":"-$1,300","D":"-$3,800"},"correctOption":"C","correctAnswer":"-$1,300","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because original outflows of $13,000 rise to $17,800 ($13,000 + $4,800), resulting in a net cash flow of -$3,800 ($14,000 - $17,800) and a closing balance of -$1,300 ($2,500 - $3,800).","distractor_reasons":{"A":"Incorrect because $3,500 is the original closing balance before including the $4,800 cash outflow for the espresso machine.","B":"Incorrect because $8,300 adds the $4,800 equipment purchase as a cash inflow instead of an outflow.","C":"Option C is correct because original outflows of $13,000 rise to $17,800 ($13,000 + $4,800), resulting in a net cash flow of -$3,800 ($14,000 - $17,800) and a closing balance of -$1,300 ($2,500 - $3,800).","D":"Incorrect because -$3,800 is the amended net cash flow and ignores the $2,500 opening balance."}}},{"id":"P1_U5_MCQ_036","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_036","question":"A ski-resort hotel's annual cash flow forecast shows positive closing balances from December to April, followed by negative closing balances in May and June, before returning to strong positive balances from July onward. What is the most sensible action for the hotel manager to take?","options":{"A":"Permanently close the hotel because it will never survive","B":"Arrange a short-term bank overdraft to cover the temporary cash deficit in May and June","C":"Issue new ordinary shares on the stock exchange to cover the two-month gap","D":"Double room prices in May and June when tourist demand is lowest"},"correctOption":"B","correctAnswer":"Arrange a short-term bank overdraft to cover the temporary cash deficit in May and June","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the cash deficit is temporary and seasonal, making a short-term overdraft ideal until positive cash flows resume in July.","distractor_reasons":{"A":"Incorrect because the hotel generates strong positive cash flows during most of the year and only faces a brief seasonal dip.","B":"Option B is correct because the cash deficit is temporary and seasonal, making a short-term overdraft ideal until positive cash flows resume in July.","C":"Incorrect because issuing shares is a permanent, expensive long-term measure unsuitable for a two-month seasonal shortfall.","D":"Incorrect because doubling prices during low-demand months would likely reduce bookings and worsen cash inflows."}}},{"id":"P1_U5_MCQ_037","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_037","question":"An ice-cream manufacturer spends heavily on ingredients, packaging, and wages in March and April to build up inventory, resulting in negative net cash flows, before collecting large cash receipts from supermarkets in June and July. What does this pattern illustrate?","options":{"A":"The business is making a severe financial loss and is bankrupt","B":"Cash outflows for production often occur months before cash inflows from seasonal sales","C":"Supermarkets are refusing to pay for the ice cream delivered","D":"A cash flow forecast is unnecessary for seasonal manufacturers"},"correctOption":"B","correctAnswer":"Cash outflows for production often occur months before cash inflows from seasonal sales","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because seasonal businesses frequently incur production cash outflows ahead of peak selling seasons, creating temporary negative net cash flows before sales receipts arrive.","distractor_reasons":{"A":"Incorrect because temporary negative net cash flows while building seasonal inventory do not mean the business is unprofitable or insolvent.","B":"Option B is correct because seasonal businesses frequently incur production cash outflows ahead of peak selling seasons, creating temporary negative net cash flows before sales receipts arrive.","C":"Incorrect because the scenario states large cash receipts arrive from supermarkets in June and July.","D":"Incorrect because seasonal businesses need cash flow forecasts even more to plan financing for off-peak months."}}},{"id":"P1_U5_MCQ_038","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_038","question":"A retail business overcomes a one-month cash flow deficit by using an agreed bank overdraft. What is a significant risk of relying on a bank overdraft to solve cash flow problems?","options":{"A":"The business must give the bank a share of all future profits","B":"The bank charges relatively high interest and can demand immediate repayment at any time","C":"An overdraft locks the business into fixed repayments for 15 years","D":"Using an overdraft prevents the business from making credit sales"},"correctOption":"B","correctAnswer":"The bank charges relatively high interest and can demand immediate repayment at any time","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because bank overdrafts usually carry high interest rates and are technically repayable on demand if the bank withdraws the facility.","distractor_reasons":{"A":"Incorrect because a bank is a lender charging interest, not an equity shareholder receiving profit shares.","B":"Option B is correct because bank overdrafts usually carry high interest rates and are technically repayable on demand if the bank withdraws the facility.","C":"Incorrect because an overdraft is a flexible short-term facility, unlike a 15-year mortgage.","D":"Incorrect because an overdraft has no restriction on how a business sells to its customers."}}},{"id":"P1_U5_MCQ_039","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_039","question":"To resolve a temporary cash shortage, a furniture retailer negotiates with its timber suppliers to extend payment terms from 30 days to 60 days. What is a likely disadvantage of delaying payments to suppliers?","options":{"A":"The retailer's current assets will immediately fall by half","B":"The retailer will have to pay higher interest to its own bank","C":"Suppliers may refuse future deliveries, charge higher prices, or withdraw early-payment discounts","D":"Customers will stop buying furniture from the retailer"},"correctOption":"C","correctAnswer":"Suppliers may refuse future deliveries, charge higher prices, or withdraw early-payment discounts","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because delaying supplier payments can strain relationships, result in the loss of prompt-payment discounts, or cause suppliers to withhold future supplies.","distractor_reasons":{"A":"Incorrect because delaying payment keeps cash in the business rather than reducing current assets.","B":"Incorrect because trade credit is provided by suppliers, not the retailer's bank.","C":"Option C is correct because delaying supplier payments can strain relationships, result in the loss of prompt-payment discounts, or cause suppliers to withhold future supplies.","D":"Incorrect because extending payment terms with suppliers does not directly affect customers unless supplies run out."}}},{"id":"P1_U5_MCQ_040","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_040","question":"An industrial cleaning company is short of cash because its business clients take 60 days to pay invoices. To speed up cash inflows, the company reduces its credit period to 30 days and offers a 2% discount for immediate payment. What is a possible drawback of this strategy?","options":{"A":"It increases the company's non-current liabilities","B":"Customers may switch to competitors offering longer credit periods, and discounts reduce profit margins","C":"It delays when cash inflows appear on the cash flow forecast","D":"Suppliers will demand immediate cash payment for cleaning materials"},"correctOption":"B","correctAnswer":"Customers may switch to competitors offering longer credit periods, and discounts reduce profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because tightening credit terms can drive customers to rivals with more generous terms, while offering discounts reduces revenue and profit per sale.","distractor_reasons":{"A":"Incorrect because changing customer credit policies affects trade receivables and cash, not long-term debt.","B":"Option B is correct because tightening credit terms can drive customers to rivals with more generous terms, while offering discounts reduces revenue and profit per sale.","C":"Incorrect because shorter credit periods accelerate cash inflows rather than delaying them.","D":"Incorrect because customer credit policies do not automatically alter supplier payment agreements."}}},{"id":"P1_U5_MCQ_041","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_041","question":"A catering firm facing a short-term cash flow deficit decides to postpone buying a $22,000 refrigerated delivery van for six months. What is a potential disadvantage of delaying the purchase of this non-current asset?","options":{"A":"The firm's immediate cash outflows will increase","B":"The firm will lose control to external shareholders","C":"The firm will have to pay higher corporation tax immediately","D":"The existing old van may break down, leading to higher repair costs and lost customer orders"},"correctOption":"D","correctAnswer":"The existing old van may break down, leading to higher repair costs and lost customer orders","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because postponing the replacement of ageing equipment can result in higher maintenance bills, lower efficiency, and unreliable deliveries.","distractor_reasons":{"A":"Incorrect because delaying the purchase reduces immediate cash outflows rather than increasing them.","B":"Incorrect because postponing capital expenditure does not involve issuing shares.","C":"Incorrect because delaying an asset purchase does not trigger an immediate tax penalty.","D":"Option D is correct because postponing the replacement of ageing equipment can result in higher maintenance bills, lower efficiency, and unreliable deliveries."}}},{"id":"P1_U5_MCQ_042","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_042","question":"A wholesaler has a forecast closing cash balance of -$9,000 next month and wants to improve its short-term cash position immediately. Which action would actually WORSEN the wholesaler's short-term cash flow problem?","options":{"A":"Buying extra inventory for cash to take advantage of a supplier bulk discount","B":"Arranging a temporary $12,000 overdraft facility with its bank","C":"Chasing overdue trade receivables to pay their invoices within seven days","D":"Postponing the cash purchase of new warehouse shelving"},"correctOption":"A","correctAnswer":"Buying extra inventory for cash to take advantage of a supplier bulk discount","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because spending cash immediately to buy extra inventory increases cash outflows right away, making the -$9,000 deficit even larger.","distractor_reasons":{"A":"Option A is correct because spending cash immediately to buy extra inventory increases cash outflows right away, making the -$9,000 deficit even larger.","B":"Incorrect because an overdraft provides immediate short-term funding to cover the cash shortfall.","C":"Incorrect because collecting trade receivables faster accelerates cash inflows.","D":"Incorrect because delaying the cash purchase of non-current assets reduces cash outflows."}}},{"id":"P1_U5_MCQ_043","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_043","question":"In March, an office furniture manufacturer sells $95,000 worth of desks on 60-day credit after paying $55,000 in cash for wood, metal, and factory wages. Why does the manufacturer show a profit of $40,000 for March despite having a negative net cash flow of -$55,000?","options":{"A":"Profit is only calculated at the end of ten years of trading","B":"Wages and raw materials are excluded from the statement of profit or loss","C":"Revenue is recorded when the credit sale is made, whereas cash inflows will not arrive until May","D":"Credit sales are never included in revenue until the customer pays cash"},"correctOption":"C","correctAnswer":"Revenue is recorded when the credit sale is made, whereas cash inflows will not arrive until May","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because profit is calculated from revenue earned minus costs incurred during the period, whereas cash flow only records actual cash movements—and the $95,000 cash will not arrive for 60 days.","distractor_reasons":{"A":"Incorrect because profit is normally calculated annually (or monthly/quarterly), not every ten years.","B":"Incorrect because wages and raw materials are deducted as costs when calculating profit.","C":"Option C is correct because profit is calculated from revenue earned minus costs incurred during the period, whereas cash flow only records actual cash movements—and the $95,000 cash will not arrive for 60 days.","D":"Incorrect because revenue includes both cash and credit sales made during the trading period."}}},{"id":"P1_U5_MCQ_044","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_044","question":"A clothing retailer makes a trading loss of -$8,000 in January, yet its bank balance increases by $15,000 during the same month. Which event best explains how a loss-making business can experience a positive net cash flow?","options":{"A":"The retailer sold all of its January goods on 90-day credit to customers","B":"The retailer received a $25,000 bank loan and sold off old inventory for cash","C":"The retailer paid all of its annual rent and insurance bills in cash during January","D":"The retailer purchased new shop fittings for cash in January"},"correctOption":"B","correctAnswer":"The retailer received a $25,000 bank loan and sold off old inventory for cash","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because receiving a bank loan is a cash inflow that does not count as trading revenue, allowing cash balances to rise even while the business makes a trading loss.","distractor_reasons":{"A":"Incorrect because selling on 90-day credit delays cash inflows and would worsen January's cash balance.","B":"Option B is correct because receiving a bank loan is a cash inflow that does not count as trading revenue, allowing cash balances to rise even while the business makes a trading loss.","C":"Incorrect because paying annual bills upfront causes large cash outflows, reducing the bank balance.","D":"Incorrect because buying shop fittings for cash is a cash outflow that lowers the bank balance."}}},{"id":"P1_U5_MCQ_045","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_045","question":"A stationery wholesaler sells $15,000 of paper to a school on 1-month trade credit in April, and the school pays the invoice in full in May. In which month should the $15,000 appear as a cash inflow on the wholesaler's cash flow forecast?","options":{"A":"April, because that is when the paper was delivered","B":"Split equally with $7,500 in April and $7,500 in May","C":"Neither April nor May, because credit sales are excluded from cash flow forecasts","D":"May, because that is when the cash actually enters the wholesaler's bank account"},"correctOption":"D","correctAnswer":"May, because that is when the cash actually enters the wholesaler's bank account","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a cash flow forecast records cash inflows in the month the payment is actually received (May), not when the credit sale occurred.","distractor_reasons":{"A":"Incorrect because recording the sale in April applies to revenue on the statement of profit or loss, not the cash flow forecast.","B":"Incorrect because the school paid the full $15,000 in May rather than in two instalments.","C":"Incorrect because credit sales do appear on the cash flow forecast once the customer pays cash.","D":"Option D is correct because a cash flow forecast records cash inflows in the month the payment is actually received (May), not when the credit sale occurred."}}},{"id":"P1_U5_MCQ_046","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_046","question":"A logistics startup needs a $60,000 truck and chooses to lease it for $1,400 per month instead of buying it outright for cash. How does this decision affect the startup's Month 1 cash flow forecast?","options":{"A":"The startup's closing balance in Month 1 becomes negative by $60,000","B":"Cash inflows in Month 1 increase by $60,000","C":"Month 1 net cash flow is completely unaffected by how the truck is financed","D":"Cash outflows in Month 1 are $58,600 lower, improving the opening liquidity position"},"correctOption":"D","correctAnswer":"Cash outflows in Month 1 are $58,600 lower, improving the opening liquidity position","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because leasing requires only a $1,400 monthly payment instead of a $60,000 cash outflow in Month 1, preserving $58,600 of cash.","distractor_reasons":{"A":"Incorrect because leasing avoids the large $60,000 upfront cash drain.","B":"Incorrect because leasing a truck is a cash outflow (rental expense), not a cash inflow.","C":"Incorrect because an outright purchase creates a $60,000 outflow immediately, whereas leasing spreads outflows over time.","D":"Option D is correct because leasing requires only a $1,400 monthly payment instead of a $60,000 cash outflow in Month 1, preserving $58,600 of cash."}}},{"id":"P1_U5_MCQ_047","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_047","question":"At the end of the year, a café owner notices that her actual closing bank balance is $6,000 lower than predicted in her original cash flow forecast. What is a common limitation of cash flow forecasts that explains this difference?","options":{"A":"Cash flow forecasts are legally forbidden from including variable costs","B":"Cash flow forecasts only record non-cash items like depreciation","C":"Forecasts rely on estimates, so unexpected cost increases or lower-than-expected sales cause inaccuracies","D":"Cash flow forecasts ignore all cash inflows from customers"},"correctOption":"C","correctAnswer":"Forecasts rely on estimates, so unexpected cost increases or lower-than-expected sales cause inaccuracies","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash flow forecasts are based on predictions of future sales, customer payment times, and costs, which can change unexpectedly in reality.","distractor_reasons":{"A":"Incorrect because all expected cash outflows, including variable material and wage costs, are included in a cash flow forecast.","B":"Incorrect because cash flow forecasts exclude non-cash items and only record actual cash movements.","C":"Option C is correct because cash flow forecasts are based on predictions of future sales, customer payment times, and costs, which can change unexpectedly in reality.","D":"Incorrect because customer receipts are the primary cash inflows in a cash flow forecast."}}},{"id":"P1_U5_MCQ_048","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_048","question":"A struggling bookstore's cash flow forecast predicts a negative net cash flow every single month for the next two years, causing its overdraft to grow continuously. Why is increasing its bank overdraft NOT an appropriate long-term solution?","options":{"A":"Bank overdrafts cannot be used to pay employee wages","B":"An overdraft is expensive, repayable on demand, and will not fix a fundamental lack of sales or excessive costs","C":"Overdrafts automatically convert into government grants after 12 months","D":"Banks legally forbid businesses from using overdrafts for more than two days"},"correctOption":"B","correctAnswer":"An overdraft is expensive, repayable on demand, and will not fix a fundamental lack of sales or excessive costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because continuous negative net cash flows indicate a long-term profitability or structural issue that requires raising prices, cutting costs, or securing long-term finance rather than relying on costly short-term overdraft debt.","distractor_reasons":{"A":"Incorrect because overdraft funds in a current account can be used to pay wages and other expenses.","B":"Option B is correct because continuous negative net cash flows indicate a long-term profitability or structural issue that requires raising prices, cutting costs, or securing long-term finance rather than relying on costly short-term overdraft debt.","C":"Incorrect because overdrafts are repayable debts that accrue interest, not non-repayable grants.","D":"Incorrect because businesses can use an agreed overdraft facility throughout the year, though it is meant for temporary deficits."}}},{"id":"P1_U5_MCQ_049","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_049","question":"A manufacturer's cash flow forecast shows closing balances of +$4,000 in January, -$2,500 in February, -$7,800 in March, and -$1,200 in April. When arranging a flexible overdraft facility with its bank, what minimum overdraft limit must the manufacturer secure?","options":{"A":"$1,200","B":"$2,500","C":"$4,000","D":"$7,800"},"correctOption":"D","correctAnswer":"$7,800","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the largest forecast negative closing balance occurs in March at -$7,800, so the overdraft limit must be at least $7,800 to cover peak borrowing needs.","distractor_reasons":{"A":"Incorrect because a $1,200 limit would only cover April and leave the business unable to pay bills in February and March.","B":"Incorrect because a $2,500 limit would cover February but fall short of March's -$7,800 deficit.","C":"Incorrect because $4,000 is January's positive cash surplus, not the peak overdraft needed in March.","D":"Option D is correct because the largest forecast negative closing balance occurs in March at -$7,800, so the overdraft limit must be at least $7,800 to cover peak borrowing needs."}}},{"id":"P1_U5_MCQ_050","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_050","question":"A fast-growing electronics assembler wins several huge contracts from retail chains, requiring it to buy triple its normal volume of components and hire extra staff months before the retailers pay their 60-day invoices. Why does rapid expansion frequently cause a cash flow crisis?","options":{"A":"Winning large contracts makes a business immediately unprofitable","B":"Rapid growth causes fixed costs to fall to zero","C":"Cash outflows for materials and wages rise immediately, while cash inflows from credit sales are delayed","D":"Banks automatically freeze the accounts of fast-growing companies"},"correctOption":"C","correctAnswer":"Cash outflows for materials and wages rise immediately, while cash inflows from credit sales are delayed","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because expanding output requires immediate cash outflows for extra inventory and labour long before cash is collected from new credit customers (overtrading).","distractor_reasons":{"A":"Incorrect because the contracts can be highly profitable on paper while still causing a temporary cash shortfall.","B":"Incorrect because rapid expansion typically increases total costs rather than reducing fixed costs to zero.","C":"Option C is correct because expanding output requires immediate cash outflows for extra inventory and labour long before cash is collected from new credit customers (overtrading).","D":"Incorrect because banks do not automatically freeze accounts simply because sales are growing."}}},{"id":"P1_U5_MCQ_051","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_051","question":"At the end of its financial year, a sole trader's total revenue is $180,000 and total costs are $145,000, leaving a surplus of $35,000. Which statement accurately defines this $35,000 profit?","options":{"A":"It is the exact amount of physical cash sitting in the business's bank account","B":"It is the financial surplus remaining after total costs have been subtracted from total revenue","C":"It is the total value of all property and machinery owned by the sole trader","D":"It is the gross revenue earned before deducting any cost of sales"},"correctOption":"B","correctAnswer":"It is the financial surplus remaining after total costs have been subtracted from total revenue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profit is defined as total revenue minus total costs (or gross profit minus expenses) over a trading period.","distractor_reasons":{"A":"Incorrect because profit includes credit sales and non-cash adjustments and rarely equals the exact bank balance.","B":"Option B is correct because profit is defined as total revenue minus total costs (or gross profit minus expenses) over a trading period.","C":"Incorrect because property and machinery are non-current assets shown on the statement of financial position.","D":"Incorrect because revenue before deducting cost of sales is $180,000, whereas $35,000 is the final profit after all costs."}}},{"id":"P1_U5_MCQ_052","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_052","question":"An entrepreneur leaves a secure salaried job and invests $50,000 of personal savings to launch a speciality coffee roastery. Why is making a profit essential to this private sector entrepreneur?","options":{"A":"Profit eliminates all business risks automatically","B":"Profit is legally required by the government for every sole trader in Year 1","C":"Profit reduces the business's gross profit margin to zero","D":"Profit acts as the financial reward for risk-taking and investing capital"},"correctOption":"D","correctAnswer":"Profit acts as the financial reward for risk-taking and investing capital","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because private sector entrepreneurs risk their own savings and foregone salary, so profit provides the essential reward for taking those risks.","distractor_reasons":{"A":"Incorrect because making a profit does not eliminate future market or economic risks.","B":"Incorrect because many new businesses make a loss in their first year without breaking any law.","C":"Incorrect because higher profit increases profitability rather than reducing gross profit margin.","D":"Option D is correct because private sector entrepreneurs risk their own savings and foregone salary, so profit provides the essential reward for taking those risks."}}},{"id":"P1_U5_MCQ_053","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_053","question":"A family-owned private limited company wants to open two new bakeries without taking out bank loans or selling shares to outsiders. How does making a healthy annual profit help the company achieve this goal?","options":{"A":"Retained profit provides an interest-free internal source of finance for expansion","B":"Profit increases the company's current liabilities on the statement of financial position","C":"Profit forces suppliers to provide free raw materials","D":"Profit allows the company to avoid paying employee wages"},"correctOption":"A","correctAnswer":"Retained profit provides an interest-free internal source of finance for expansion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit retained in the business after tax and dividends serves as an internal source of finance for growth without interest or loss of control.","distractor_reasons":{"A":"Option A is correct because profit retained in the business after tax and dividends serves as an internal source of finance for growth without interest or loss of control.","B":"Incorrect because retained profit increases equity/capital employed rather than current liabilities.","C":"Incorrect because profitable businesses still have to pay suppliers for materials.","D":"Incorrect because employee wages are a contractual expense that must be paid regardless of profit."}}},{"id":"P1_U5_MCQ_054","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_054","question":"The directors of a sporting goods company compare this year's profit of $320,000 against last year's profit of $240,000 and against a rival's profit of $280,000. Which role of profit is illustrated by this comparison?","options":{"A":"Using profit as a measure of short-term liquidity","B":"Using profit to calculate the company's current ratio","C":"Using profit as an indicator and measure of business success","D":"Using profit to determine the exact number of employees"},"correctOption":"C","correctAnswer":"Using profit as an indicator and measure of business success","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because profit is a primary indicator used by owners and managers to measure how successful a business is over time and relative to competitors.","distractor_reasons":{"A":"Incorrect because liquidity is measured using cash flow and liquidity ratios, not profit alone.","B":"Incorrect because the current ratio compares current assets to current liabilities.","C":"Option C is correct because profit is a primary indicator used by owners and managers to measure how successful a business is over time and relative to competitors.","D":"Incorrect because employee numbers are a measure of business size, not profit."}}},{"id":"P1_U5_MCQ_055","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_055","question":"A growing public limited company announces three consecutive years of rising profits and higher dividend payouts. Why is this profit performance important when the company decides to issue new shares?","options":{"A":"High profits legally exempt the company from publishing annual accounts","B":"Strong profits attract investors who expect reliable dividends and rising share prices","C":"High profits reduce the company's revenue on the statement of profit or loss","D":"Profitable companies do not need to pay for raw materials"},"correctOption":"B","correctAnswer":"Strong profits attract investors who expect reliable dividends and rising share prices","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consistent profits demonstrate financial strength and the ability to pay dividends, attracting new investors to buy shares.","distractor_reasons":{"A":"Incorrect because all limited companies must legally file and publish annual accounts regardless of profit.","B":"Option B is correct because consistent profits demonstrate financial strength and the ability to pay dividends, attracting new investors to buy shares.","C":"Incorrect because higher profits usually result from higher revenue or lower costs, not reduced revenue.","D":"Incorrect because cost of sales is still incurred when producing goods."}}},{"id":"P1_U5_MCQ_056","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_056","question":"A social enterprise that employs disadvantaged workers to recycle plastic waste makes an annual profit of $45,000. How does the importance of profit for this social enterprise differ from that of a typical public limited company?","options":{"A":"Social enterprises are legally prohibited from making any profit","B":"Social enterprises distribute 100% of their profit as cash dividends to stock exchange investors","C":"Social enterprises do not record revenue or expenses on a statement of profit or loss","D":"Profit is mainly reinvested back into the business to expand its social and environmental impact rather than maximising shareholder dividends"},"correctOption":"D","correctAnswer":"Profit is mainly reinvested back into the business to expand its social and environmental impact rather than maximising shareholder dividends","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because social enterprises aim to make a profit primarily to reinvest in achieving their social and environmental objectives rather than paying high dividends to private shareholders.","distractor_reasons":{"A":"Incorrect because social enterprises do aim to make a profit in order to remain financially sustainable and grow.","B":"Incorrect because social enterprises are not focused on maximising dividend payouts to stock market shareholders.","C":"Incorrect because social enterprises still track revenue, costs, and profit on their financial statements.","D":"Option D is correct because social enterprises aim to make a profit primarily to reinvest in achieving their social and environmental objectives rather than paying high dividends to private shareholders."}}},{"id":"P1_U5_MCQ_057","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_057","question":"During June, an online t-shirt store sells 3,500 t-shirts at an average selling price of $14 each, while spending $21,000 on blank t-shirts and printing ink. What is the store's revenue for June?","options":{"A":"$3,500","B":"$28,000","C":"$70,000","D":"$49,000"},"correctOption":"D","correctAnswer":"$49,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because revenue equals selling price per unit multiplied by number of units sold ($14 × 3,500 = $49,000).","distractor_reasons":{"A":"Incorrect because 3,500 is the sales volume in units, not the dollar sales revenue.","B":"Incorrect because $28,000 is the gross profit ($49,000 revenue - $21,000 cost of sales), not total revenue.","C":"Incorrect because $70,000 adds cost of sales to revenue instead of keeping revenue separate.","D":"Option D is correct because revenue equals selling price per unit multiplied by number of units sold ($14 × 3,500 = $49,000)."}}},{"id":"P1_U5_MCQ_058","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_058","question":"A supermarket chain is preparing its annual statement of profit or loss. Which item should be classified under 'cost of sales' rather than 'expenses'?","options":{"A":"Head office administrative salaries","B":"Television advertising campaigns","C":"Wholesale cost of groceries bought from suppliers for resale","D":"Interest paid on a long-term bank loan"},"correctOption":"C","correctAnswer":"Wholesale cost of groceries bought from suppliers for resale","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cost of sales represents the direct cost of purchasing or manufacturing the goods that were actually sold during the period.","distractor_reasons":{"A":"Incorrect because head office salaries are indirect overhead expenses deducted after gross profit.","B":"Incorrect because advertising is a marketing overhead expense rather than a direct product cost.","C":"Option C is correct because cost of sales represents the direct cost of purchasing or manufacturing the goods that were actually sold during the period.","D":"Incorrect because loan interest is a finance expense deducted after gross profit."}}},{"id":"P1_U5_MCQ_059","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_059","question":"An electronics shop records annual revenue of $340,000, cost of sales of $215,000, and overhead expenses of $75,000. What is the shop's gross profit?","options":{"A":"$50,000","B":"$125,000","C":"$265,000","D":"$555,000"},"correctOption":"B","correctAnswer":"$125,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because gross profit equals revenue minus cost of sales ($340,000 - $215,000 = $125,000).","distractor_reasons":{"A":"Incorrect because $50,000 is the final profit after deducting both cost of sales and $75,000 of overhead expenses.","B":"Option B is correct because gross profit equals revenue minus cost of sales ($340,000 - $215,000 = $125,000).","C":"Incorrect because $265,000 subtracts overhead expenses from revenue instead of cost of sales.","D":"Incorrect because $555,000 adds revenue and cost of sales together."}}},{"id":"P1_U5_MCQ_060","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_060","question":"A bakery's statement of profit or loss shows revenue of $160,000, cost of sales of $65,000, and total overhead expenses (rent, shop wages, and utilities) of $58,000. What is the bakery's profit?","options":{"A":"$95,000","B":"$102,000","C":"$123,000","D":"$37,000"},"correctOption":"D","correctAnswer":"$37,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because gross profit is $160,000 - $65,000 = $95,000, and profit equals gross profit minus overhead expenses ($95,000 - $58,000 = $37,000).","distractor_reasons":{"A":"Incorrect because $95,000 is the gross profit before deducting the $58,000 of overhead expenses.","B":"Incorrect because $102,000 deducts only expenses from revenue and ignores cost of sales.","C":"Incorrect because $123,000 adds cost of sales and expenses together ($65,000 + $58,000).","D":"Option D is correct because gross profit is $160,000 - $65,000 = $95,000, and profit equals gross profit minus overhead expenses ($95,000 - $58,000 = $37,000)."}}},{"id":"P1_U5_MCQ_061","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_061","question":"In a statement of profit or loss, gross profit is calculated first, and then overhead expenses are subtracted to find profit. Which of the following is an example of an overhead expense?","options":{"A":"Office rent, insurance, and marketing salaries","B":"Raw materials used directly on the factory assembly line","C":"Total revenue from selling finished products","D":"Share capital invested by the founders"},"correctOption":"A","correctAnswer":"Office rent, insurance, and marketing salaries","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because office rent, insurance, and marketing salaries are indirect running costs (expenses) subtracted from gross profit.","distractor_reasons":{"A":"Option A is correct because office rent, insurance, and marketing salaries are indirect running costs (expenses) subtracted from gross profit.","B":"Incorrect because direct raw materials are part of cost of sales, deducted before gross profit.","C":"Incorrect because sales revenue is the top line of the statement of profit or loss, not an expense.","D":"Incorrect because share capital is equity recorded on the statement of financial position."}}},{"id":"P1_U5_MCQ_062","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_062","question":"A private limited company earns a profit after tax of $110,000, and its directors decide to pay $40,000 in dividends to shareholders. What happens to the remaining $70,000?","options":{"A":"It is recorded as a current liability owed to customers","B":"It is paid to the government as an additional sales tax","C":"It becomes retained profit, which is kept in the business to help finance future operations","D":"It is added to cost of sales for the following year"},"correctOption":"C","correctAnswer":"It becomes retained profit, which is kept in the business to help finance future operations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because any profit remaining after tax and dividend distributions is retained profit, reinvested in the business as an internal source of finance.","distractor_reasons":{"A":"Incorrect because retained profit belongs to the equity of the business, not to customers.","B":"Incorrect because the $110,000 figure is already profit after tax.","C":"Option C is correct because any profit remaining after tax and dividend distributions is retained profit, reinvested in the business as an internal source of finance.","D":"Incorrect because retained profit is an equity reserve on the statement of financial position, not an expense."}}},{"id":"P1_U5_MCQ_063","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_063","question":"A global coffee shortage forces a café chain to pay 20% more for coffee beans, while the chain keeps its menu prices and overhead expenses unchanged. How will this affect the chain's statement of profit or loss?","options":{"A":"Revenue will increase and gross profit will rise","B":"Cost of sales will increase, causing both gross profit and final profit to fall","C":"Gross profit will stay the same, but overhead expenses will increase","D":"Cost of sales will fall, increasing final profit"},"correctOption":"B","correctAnswer":"Cost of sales will increase, causing both gross profit and final profit to fall","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because coffee beans are a direct ingredient in cost of sales; higher bean prices raise cost of sales, which lowers gross profit and consequently reduces final profit.","distractor_reasons":{"A":"Incorrect because menu prices and sales volume did not increase, so revenue does not rise.","B":"Option B is correct because coffee beans are a direct ingredient in cost of sales; higher bean prices raise cost of sales, which lowers gross profit and consequently reduces final profit.","C":"Incorrect because coffee beans are part of cost of sales rather than indirect overhead expenses, so gross profit falls.","D":"Incorrect because paying 20% more for beans increases costs rather than reducing them."}}},{"id":"P1_U5_MCQ_064","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_064","question":"A stationery retailer spends an extra $12,000 on local radio advertising during December, but its sales revenue and cost of sales remain completely unchanged. What is the impact on its statement of profit or loss?","options":{"A":"Both gross profit and final profit fall by $12,000","B":"Gross profit falls by $12,000, while final profit stays the same","C":"Cost of sales increases by $12,000, reducing gross profit","D":"Gross profit stays the same, while expenses rise by $12,000 and final profit falls by $12,000"},"correctOption":"D","correctAnswer":"Gross profit stays the same, while expenses rise by $12,000 and final profit falls by $12,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because advertising is an overhead expense deducted after gross profit; therefore, gross profit is unaffected while final profit decreases by $12,000.","distractor_reasons":{"A":"Incorrect because gross profit only depends on revenue minus cost of sales, neither of which changed.","B":"Incorrect because final profit is calculated after deducting overhead expenses like advertising.","C":"Incorrect because advertising is an overhead expense, not a direct cost of sales.","D":"Option D is correct because advertising is an overhead expense deducted after gross profit; therefore, gross profit is unaffected while final profit decreases by $12,000."}}},{"id":"P1_U5_MCQ_065","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_065","question":"A furniture manufacturer wants to increase its profit without raising prices to customers. Which action directly reduces cost of sales while aiming to protect product quality?","options":{"A":"Switching to cheaper, low-grade wood that splinters easily","B":"Reducing the marketing budget for social media advertisements","C":"Subletting unused office space to another small business","D":"Negotiating bulk-buying discounts with existing reliable timber suppliers"},"correctOption":"D","correctAnswer":"Negotiating bulk-buying discounts with existing reliable timber suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because negotiating bulk discounts with existing quality suppliers lowers direct material costs (cost of sales) without compromising product quality.","distractor_reasons":{"A":"Incorrect because low-grade wood damages product quality and customer satisfaction, risking lower future sales.","B":"Incorrect because reducing marketing lowers overhead expenses rather than cost of sales.","C":"Incorrect because subletting office space reduces overhead rent expense rather than direct cost of sales.","D":"Option D is correct because negotiating bulk discounts with existing quality suppliers lowers direct material costs (cost of sales) without compromising product quality."}}},{"id":"P1_U5_MCQ_066","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_066","question":"A call-centre company keeps its client fees and direct service costs constant, but installs energy-efficient lighting and negotiates a cheaper office lease. How does this increase the company's profit?","options":{"A":"It increases total revenue on the statement of profit or loss","B":"It lowers cost of sales and increases gross profit","C":"It reduces overhead expenses, leaving a larger profit after deducting expenses from gross profit","D":"It increases the company's non-current liabilities"},"correctOption":"C","correctAnswer":"It reduces overhead expenses, leaving a larger profit after deducting expenses from gross profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because electricity and office rent are overhead expenses; reducing them increases final profit even when gross profit stays constant.","distractor_reasons":{"A":"Incorrect because client fees and sales volume did not change.","B":"Incorrect because office rent and lighting are indirect expenses rather than direct cost of sales.","C":"Option C is correct because electricity and office rent are overhead expenses; reducing them increases final profit even when gross profit stays constant.","D":"Incorrect because lowering rent and utility bills reduces expenses rather than increasing long-term debt."}}},{"id":"P1_U5_MCQ_067","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_067","question":"A budget airline raises its ticket prices by 25% in an effort to boost profit, only to find that its annual profit actually falls sharply. What is the most likely reason this price increase failed to raise profit?","options":{"A":"Higher ticket prices automatically increased the cost of aviation fuel","B":"Customers switched to rival airlines, causing passenger numbers and total revenue to fall","C":"Raising prices is illegal under consumer protection laws","D":"Higher prices increased the airline's current liabilities"},"correctOption":"B","correctAnswer":"Customers switched to rival airlines, causing passenger numbers and total revenue to fall","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because in a competitive market, a large price rise can cause customers to switch to rivals, reducing sales volume and total revenue by more than the price gain.","distractor_reasons":{"A":"Incorrect because ticket prices do not determine the market price of aviation fuel.","B":"Option B is correct because in a competitive market, a large price rise can cause customers to switch to rivals, reducing sales volume and total revenue by more than the price gain.","C":"Incorrect because private sector airlines are free to set their own ticket prices.","D":"Incorrect because changing ticket prices does not create short-term debts."}}},{"id":"P1_U5_MCQ_068","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_068","question":"A cinema chain lowers ticket prices by 15% on quiet weekday afternoons, and its total profit increases. Under what condition does lowering selling prices successfully increase profit?","options":{"A":"When the number of tickets sold stays completely unchanged","B":"When fixed costs rise faster than ticket sales","C":"When cost of sales per ticket increases by 20%","D":"When the percentage increase in ticket sales volume more than offsets the lower price per ticket while costs remain controlled"},"correctOption":"D","correctAnswer":"When the percentage increase in ticket sales volume more than offsets the lower price per ticket while costs remain controlled","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because if demand responds strongly to a price cut, the rise in sales volume increases total revenue and gross profit above any extra variable costs.","distractor_reasons":{"A":"Incorrect because if ticket volume stays unchanged, a 15% price cut reduces revenue and lowers profit.","B":"Incorrect because rising fixed costs reduce profit rather than increasing it.","C":"Incorrect because higher unit costs alongside lower prices would squeeze profit margins.","D":"Option D is correct because if demand responds strongly to a price cut, the rise in sales volume increases total revenue and gross profit above any extra variable costs."}}},{"id":"P1_U5_MCQ_069","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_069","question":"A sports retailer compares two product lines: Running Shoes generate $150,000 in revenue with $110,000 in cost of sales, while Tennis Rackets generate $120,000 in revenue with $65,000 in cost of sales. Which decision is best supported by this statement of profit or loss data?","options":{"A":"Discontinue Tennis Rackets immediately because their revenue is $30,000 lower","B":"Focus more promotion on Tennis Rackets because they generate $55,000 in gross profit compared to $40,000 for Running Shoes","C":"Focus exclusively on Running Shoes because higher revenue always means higher profit","D":"Stop tracking cost of sales because only total revenue matters"},"correctOption":"B","correctAnswer":"Focus more promotion on Tennis Rackets because they generate $55,000 in gross profit compared to $40,000 for Running Shoes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Tennis Rackets earn a higher gross profit ($120,000 - $65,000 = $55,000) than Running Shoes ($150,000 - $110,000 = $40,000) despite lower revenue.","distractor_reasons":{"A":"Incorrect because discontinuing the product with higher gross profit would reduce total business profit.","B":"Option B is correct because Tennis Rackets earn a higher gross profit ($120,000 - $65,000 = $55,000) than Running Shoes ($150,000 - $110,000 = $40,000) despite lower revenue.","C":"Incorrect because high revenue does not guarantee high profit when cost of sales is disproportionately high.","D":"Incorrect because ignoring cost of sales hides which products actually contribute most to profit."}}},{"id":"P1_U5_MCQ_070","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_070","question":"Comparing its statement of profit or loss with last year, a clothing brand sees that revenue rose by 12% and gross profit also rose by 12%, yet final profit fell by 10%. What is the most likely explanation for this result?","options":{"A":"The cost of raw cotton and fabric increased sharply","B":"The brand sold fewer items than in the previous year","C":"Overhead expenses such as store rents and head-office salaries increased significantly","D":"The brand reduced its selling prices by 12%"},"correctOption":"C","correctAnswer":"Overhead expenses such as store rents and head-office salaries increased significantly","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because gross profit grew in line with revenue (12%), meaning the drop in final profit must have been caused by a sharp rise in overhead expenses deducted below gross profit.","distractor_reasons":{"A":"Incorrect because higher fabric costs would increase cost of sales and cause gross profit to grow slower than revenue.","B":"Incorrect because revenue increased by 12%, indicating strong sales rather than a decline.","C":"Option C is correct because gross profit grew in line with revenue (12%), meaning the drop in final profit must have been caused by a sharp rise in overhead expenses deducted below gross profit.","D":"Incorrect because a 12% price cut with constant unit costs would have reduced gross profit relative to revenue."}}},{"id":"P1_U5_MCQ_071","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_071","question":"An incomplete extract from a toy company's statement of profit or loss shows revenue of $280,000, gross profit of $115,000, and final profit of $42,000. What were the company's total overhead expenses for the year?","options":{"A":"$165,000","B":"$73,000","C":"$238,000","D":"$157,000"},"correctOption":"B","correctAnswer":"$73,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Profit = Gross profit - Expenses, so Expenses = Gross profit - Profit ($115,000 - $42,000 = $73,000).","distractor_reasons":{"A":"Incorrect because $165,000 is the cost of sales ($280,000 revenue - $115,000 gross profit), not overhead expenses.","B":"Option B is correct because Profit = Gross profit - Expenses, so Expenses = Gross profit - Profit ($115,000 - $42,000 = $73,000).","C":"Incorrect because $238,000 subtracts final profit from total revenue ($280,000 - $42,000), which combines cost of sales and expenses.","D":"Incorrect because $157,000 adds gross profit and final profit together ($115,000 + $42,000)."}}},{"id":"P1_U5_MCQ_072","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_072","question":"A construction company reports an annual profit of $90,000 on its statement of profit or loss, yet its bank balance is only $4,000 at year-end. Why can the directors NOT immediately pay a $90,000 cash dividend to shareholders?","options":{"A":"Dividends can only be paid out of non-current liabilities","B":"The statement of profit or loss never includes credit sales","C":"Private sector companies are legally banned from paying dividends","D":"Much of the profit is tied up in unpaid trade receivables, inventory, or equipment purchases rather than available cash"},"correctOption":"D","correctAnswer":"Much of the profit is tied up in unpaid trade receivables, inventory, or equipment purchases rather than available cash","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit is not the same as cash; a profitable company may have its funds tied up in trade receivables, inventory, or capital expenditure and lack the cash to pay large dividends.","distractor_reasons":{"A":"Incorrect because dividends are distributed from after-tax profit and paid using available cash, not long-term debt.","B":"Incorrect because credit sales are included in revenue when calculating profit, which is precisely why profit can exceed cash.","C":"Incorrect because limited companies regularly pay dividends when both profit and cash are sufficient.","D":"Option D is correct because profit is not the same as cash; a profitable company may have its funds tied up in trade receivables, inventory, or capital expenditure and lack the cash to pay large dividends."}}},{"id":"P1_U5_MCQ_073","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_073","question":"In July, a packaging company pays $70,000 in cash to buy a new automated box-folding machine that will be used for ten years. How is this $70,000 purchase treated in July's cash flow records compared with the statement of profit or loss?","options":{"A":"It is recorded as a $70,000 cash outflow in July, but is NOT deducted in full as a $70,000 cost of sales in that year's statement of profit or loss","B":"It is recorded as $70,000 of revenue on the statement of profit or loss","C":"It is ignored in both the cash flow forecast and the statement of financial position","D":"It is recorded as a $70,000 cash inflow because the company gained a machine"},"correctOption":"A","correctAnswer":"It is recorded as a $70,000 cash outflow in July, but is NOT deducted in full as a $70,000 cost of sales in that year's statement of profit or loss","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because purchasing a non-current asset creates an immediate $70,000 cash outflow, whereas on the statement of financial position it appears as a non-current asset rather than being expensed all at once as cost of sales.","distractor_reasons":{"A":"Option A is correct because purchasing a non-current asset creates an immediate $70,000 cash outflow, whereas on the statement of financial position it appears as a non-current asset rather than being expensed all at once as cost of sales.","B":"Incorrect because buying a machine is capital expenditure, not sales revenue.","C":"Incorrect because the cash payment is a cash outflow and the machine is a non-current asset on the statement of financial position.","D":"Incorrect because cash left the business to pay for the machine, making it a cash outflow."}}},{"id":"P1_U5_MCQ_074","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_074","question":"To boost this year's profit, the manager of a luxury hotel cuts staff training budgets and replaces high-quality toiletries with cheap alternatives. What is the main risk of using these cost-cutting methods to raise profit?","options":{"A":"The hotel's current assets will immediately exceed its non-current assets","B":"Cost of sales will automatically double next month","C":"Service standards and brand image may decline, leading to fewer repeat guests and lower future profit","D":"The hotel will no longer be able to calculate gross profit"},"correctOption":"C","correctAnswer":"Service standards and brand image may decline, leading to fewer repeat guests and lower future profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cutting training and product quality in a luxury business can disappoint guests, damage reputation, and reduce future revenue and profit.","distractor_reasons":{"A":"Incorrect because reducing expenses does not alter the ratio of current to non-current assets in this way.","B":"Incorrect because using cheaper toiletries lowers direct costs in the short term rather than doubling them.","C":"Option C is correct because cutting training and product quality in a luxury business can disappoint guests, damage reputation, and reduce future revenue and profit.","D":"Incorrect because gross profit can still be calculated normally from revenue and cost of sales."}}},{"id":"P1_U5_MCQ_075","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_075","question":"Every quarter, the senior managers of a retail chain review the statement of profit or loss for each store branch. How does this financial statement assist managers in operational decision-making?","options":{"A":"It shows the exact maturity dates of every bank loan held by the chain","B":"It lists the names and addresses of all trade payables","C":"It proves whether every store has enough cash to pay tomorrow's electricity bill","D":"It highlights underperforming branches where cost of sales or expenses are too high relative to revenue"},"correctOption":"D","correctAnswer":"It highlights underperforming branches where cost of sales or expenses are too high relative to revenue","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because reviewing revenue, gross profit, expenses, and profit across branches helps managers pinpoint high costs or weak sales and take corrective action.","distractor_reasons":{"A":"Incorrect because loan maturity details are related to liabilities on the statement of financial position, not the statement of profit or loss.","B":"Incorrect because supplier details are kept in purchase ledgers, not on the statement of profit or loss.","C":"Incorrect because short-term cash availability is tracked through cash flow records, not the statement of profit or loss.","D":"Option D is correct because reviewing revenue, gross profit, expenses, and profit across branches helps managers pinpoint high costs or weak sales and take corrective action."}}},{"id":"P1_U5_MCQ_076","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_076","question":"At the close of business on 31 December, an accountant prepares a statement of financial position for a manufacturing company. What does this financial statement show?","options":{"A":"The total revenue and expenses earned by the business over the entire 12-month period","B":"The value of the business's assets, liabilities, and equity at that specific point in time","C":"The monthly forecast of cash inflows and outflows for the upcoming year","D":"The break-even level of output required to cover fixed costs"},"correctOption":"B","correctAnswer":"The value of the business's assets, liabilities, and equity at that specific point in time","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the statement of financial position provides a financial 'snapshot' of what a business owns (assets), owes (liabilities), and its equity on a specific date.","distractor_reasons":{"A":"Incorrect because revenue and expenses over a period are shown on the statement of profit or loss.","B":"Option B is correct because the statement of financial position provides a financial 'snapshot' of what a business owns (assets), owes (liabilities), and its equity on a specific date.","C":"Incorrect because future monthly cash receipts and payments are shown on a cash flow forecast.","D":"Incorrect because break-even output is determined through break-even analysis, not the statement of financial position."}}},{"id":"P1_U5_MCQ_077","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_077","question":"A food-processing company owns a factory building, automated bottling machinery, delivery trucks, raw fruit inventory, and cash in the bank. Which items are classified as non-current assets on its statement of financial position?","options":{"A":"Raw fruit inventory and cash in the bank","B":"Factory building, raw fruit inventory, and cash in the bank","C":"Factory building, automated bottling machinery, and delivery trucks","D":"Delivery trucks and unpaid supplier invoices"},"correctOption":"C","correctAnswer":"Factory building, automated bottling machinery, and delivery trucks","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because non-current assets are resources owned by the business and used for more than one year to generate output, such as property, machinery, and vehicles.","distractor_reasons":{"A":"Incorrect because inventory and cash are current assets expected to be used or converted within 12 months.","B":"Incorrect because raw fruit inventory and cash are current assets, not non-current assets.","C":"Option C is correct because non-current assets are resources owned by the business and used for more than one year to generate output, such as property, machinery, and vehicles.","D":"Incorrect because unpaid supplier invoices are trade payables (current liabilities)."}}},{"id":"P1_U5_MCQ_078","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_078","question":"A wholesale electronics distributor is listing its current assets on its statement of financial position. Which group of items consists entirely of current assets?","options":{"A":"Warehouse property, delivery vans, and machinery","B":"Inventory, trade receivables, and cash","C":"Trade payables, bank overdraft, and 5-year bank loan","D":"Share capital, retained profit, and cash"},"correctOption":"B","correctAnswer":"Inventory, trade receivables, and cash","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because current assets are short-term resources held for less than one year that will soon turn into cash: inventory, trade receivables, and cash.","distractor_reasons":{"A":"Incorrect because warehouse property, vans, and machinery are non-current assets.","B":"Option B is correct because current assets are short-term resources held for less than one year that will soon turn into cash: inventory, trade receivables, and cash.","C":"Incorrect because trade payables, overdrafts, and bank loans are liabilities (debts owed by the business).","D":"Incorrect because share capital and retained profit are equity items, not current assets."}}},{"id":"P1_U5_MCQ_079","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_079","question":"A stationery supplier delivers $9,000 of paper to an office firm on 30-day credit, so the office firm has not yet paid for the goods. How is this $9,000 recorded on the stationery supplier's statement of financial position?","options":{"A":"As a current liability under trade payables","B":"As a non-current asset under property and equipment","C":"As a non-current liability under bank loans","D":"As a current asset under trade receivables"},"correctOption":"D","correctAnswer":"As a current asset under trade receivables","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because money owed to the business by customers who bought goods on credit is recorded as trade receivables, which is a current asset.","distractor_reasons":{"A":"Incorrect because trade payables represent money the business owes to its suppliers, whereas here the customer owes the supplier.","B":"Incorrect because amounts owed by credit customers are short-term current assets, not physical non-current assets.","C":"Incorrect because trade receivables are assets owed to the business, not long-term debts.","D":"Option D is correct because money owed to the business by customers who bought goods on credit is recorded as trade receivables, which is a current asset."}}},{"id":"P1_U5_MCQ_080","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_080","question":"A retail clothing chain owes $28,000 to garment suppliers due within 30 days and has an overdrawn bank account of $7,000. Under which heading on the statement of financial position are both of these amounts recorded?","options":{"A":"Current liabilities","B":"Non-current liabilities","C":"Current assets","D":"Shareholders' equity"},"correctOption":"A","correctAnswer":"Current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade payables and bank overdrafts are short-term debts that must be repaid within 12 months, classifying them as current liabilities.","distractor_reasons":{"A":"Option A is correct because trade payables and bank overdrafts are short-term debts that must be repaid within 12 months, classifying them as current liabilities.","B":"Incorrect because non-current liabilities are long-term debts due after more than one year, such as multi-year bank loans.","C":"Incorrect because debts owed to suppliers and banks are liabilities, not assets owned by the business.","D":"Incorrect because equity represents the owners' stake in the business, not short-term debts."}}},{"id":"P1_U5_MCQ_081","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_081","question":"A hotel group takes out a $450,000 mortgage loan from a commercial bank to be repaid over 12 years. Where does this $450,000 appear on the hotel group's statement of financial position?","options":{"A":"Current liabilities","B":"Non-current assets","C":"Non-current liabilities","D":"Working capital"},"correctOption":"C","correctAnswer":"Non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a 12-year bank loan is a long-term debt repayable over more than one year, making it a non-current liability.","distractor_reasons":{"A":"Incorrect because current liabilities only include debts due within one year.","B":"Incorrect because the hotel building purchased is a non-current asset, whereas the loan owed to the bank is a non-current liability.","C":"Option C is correct because a 12-year bank loan is a long-term debt repayable over more than one year, making it a non-current liability.","D":"Incorrect because working capital is current assets minus current liabilities and excludes long-term loans."}}},{"id":"P1_U5_MCQ_082","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_082","question":"A hardware store's statement of financial position shows inventory of $22,000, trade receivables of $15,000, cash of $8,000, trade payables of $21,000, and a bank overdraft of $6,000. What is the store's working capital?","options":{"A":"$24,000","B":"$18,000","C":"$72,000","D":"$37,000"},"correctOption":"B","correctAnswer":"$18,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total current assets are $45,000 ($22,000 + $15,000 + $8,000) and total current liabilities are $27,000 ($21,000 + $6,000), giving working capital of $18,000 ($45,000 - $27,000).","distractor_reasons":{"A":"Incorrect because $24,000 omits the $6,000 bank overdraft from current liabilities ($45,000 - $21,000).","B":"Option B is correct because total current assets are $45,000 ($22,000 + $15,000 + $8,000) and total current liabilities are $27,000 ($21,000 + $6,000), giving working capital of $18,000 ($45,000 - $27,000).","C":"Incorrect because $72,000 adds current assets and current liabilities together ($45,000 + $27,000).","D":"Incorrect because $37,000 omits the $8,000 cash balance from current assets before deducting liabilities."}}},{"id":"P1_U5_MCQ_083","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_083","question":"A printing company owns premises valued at $310,000, printing presses valued at $95,000, inventory worth $28,000, trade receivables of $19,000, and cash of $8,000. What is the value of the company's total assets?","options":{"A":"$405,000","B":"$55,000","C":"$350,000","D":"$460,000"},"correctOption":"D","correctAnswer":"$460,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because total assets equal non-current assets ($310,000 + $95,000 = $405,000) plus current assets ($28,000 + $19,000 + $8,000 = $55,000), totalling $460,000.","distractor_reasons":{"A":"Incorrect because $405,000 includes only non-current assets and omits current assets.","B":"Incorrect because $55,000 includes only current assets and omits non-current assets.","C":"Incorrect because $350,000 subtracts current assets from non-current assets instead of adding them.","D":"Option D is correct because total assets equal non-current assets ($310,000 + $95,000 = $405,000) plus current assets ($28,000 + $19,000 + $8,000 = $55,000), totalling $460,000."}}},{"id":"P1_U5_MCQ_084","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_084","question":"A manufacturing business has a long-term bank loan of $165,000, trade payables of $38,000, a bank overdraft of $12,000, and share capital of $200,000. What are the business's total liabilities?","options":{"A":"$215,000","B":"$50,000","C":"$415,000","D":"$165,000"},"correctOption":"A","correctAnswer":"$215,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because total liabilities equal non-current liabilities ($165,000) plus current liabilities ($38,000 + $12,000 = $50,000), giving $215,000.","distractor_reasons":{"A":"Option A is correct because total liabilities equal non-current liabilities ($165,000) plus current liabilities ($38,000 + $12,000 = $50,000), giving $215,000.","B":"Incorrect because $50,000 includes only current liabilities and omits the $165,000 non-current bank loan.","C":"Incorrect because $415,000 wrongly includes $200,000 of share capital (equity) as a liability.","D":"Incorrect because $165,000 includes only non-current liabilities and omits current liabilities."}}},{"id":"P1_U5_MCQ_085","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_085","question":"When calculating Return on Capital Employed (ROCE), an analyst checks the statement of financial position to determine the business's 'capital employed'. What does capital employed represent?","options":{"A":"Only the cash held in the business's current bank account","B":"Total current assets plus total current liabilities","C":"The total long-term finance invested in the business, equal to shareholders' equity plus non-current liabilities","D":"Total revenue minus cost of sales for the financial year"},"correctOption":"C","correctAnswer":"The total long-term finance invested in the business, equal to shareholders' equity plus non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed is the total amount of capital invested in a business for generating profits, calculated as total equity plus non-current liabilities (or total assets minus current liabilities).","distractor_reasons":{"A":"Incorrect because cash is only one small component of current assets, not total capital invested.","B":"Incorrect because working capital is current assets minus current liabilities, whereas capital employed measures long-term invested capital.","C":"Option C is correct because capital employed is the total amount of capital invested in a business for generating profits, calculated as total equity plus non-current liabilities (or total assets minus current liabilities).","D":"Incorrect because revenue minus cost of sales is gross profit on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_086","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_086","question":"A private limited company's statement of financial position reports share capital of $180,000, retained profit of $75,000, a 10-year bank loan of $120,000, and trade payables of $30,000. What is the company's capital employed?","options":{"A":"$255,000","B":"$375,000","C":"$405,000","D":"$300,000"},"correctOption":"B","correctAnswer":"$375,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because capital employed equals shareholders' equity ($180,000 share capital + $75,000 retained profit = $255,000) plus non-current liabilities ($120,000 bank loan) = $375,000.","distractor_reasons":{"A":"Incorrect because $255,000 is total shareholders' equity and omits the $120,000 non-current bank loan.","B":"Option B is correct because capital employed equals shareholders' equity ($180,000 share capital + $75,000 retained profit = $255,000) plus non-current liabilities ($120,000 bank loan) = $375,000.","C":"Incorrect because $405,000 wrongly includes $30,000 of short-term trade payables (current liabilities).","D":"Incorrect because $300,000 omits the $75,000 retained profit from shareholders' equity."}}},{"id":"P1_U5_MCQ_087","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_087","question":"On a company's statement of financial position, total assets equal $540,000 and total liabilities equal $210,000. Why must total shareholders' equity equal $330,000?","options":{"A":"Because shareholders' equity is always equal to current liabilities plus cash","B":"Because non-current assets must always equal non-current liabilities","C":"Because gross profit is added directly to total assets every month","D":"Because net assets (total assets minus total liabilities) are funded by and equal to total equity"},"correctOption":"D","correctAnswer":"Because net assets (total assets minus total liabilities) are funded by and equal to total equity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the statement of financial position always balances: Net assets (Total assets - Total liabilities = $330,000) equal Total equity ($330,000).","distractor_reasons":{"A":"Incorrect because equity consists of share capital and retained profit, not current liabilities plus cash.","B":"Incorrect because non-current assets rarely equal non-current liabilities.","C":"Incorrect because the statement balances due to accounting identity (Assets - Liabilities = Equity), not monthly gross profit additions.","D":"Option D is correct because the statement of financial position always balances: Net assets (Total assets - Total liabilities = $330,000) equal Total equity ($330,000)."}}},{"id":"P1_U5_MCQ_088","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_088","question":"A supermarket buys $15,000 of canned food from a wholesaler on 30-day trade credit. How does this transaction immediately affect the supermarket's statement of financial position?","options":{"A":"Non-current assets increase by $15,000 and equity increases by $15,000","B":"Current assets (inventory) increase by $15,000 and current liabilities (trade payables) increase by $15,000","C":"Current assets decrease by $15,000 and working capital falls by $15,000","D":"Non-current liabilities increase by $15,000 and cash increases by $15,000"},"correctOption":"B","correctAnswer":"Current assets (inventory) increase by $15,000 and current liabilities (trade payables) increase by $15,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because receiving inventory adds $15,000 to current assets while owing the supplier adds $15,000 to current liabilities (trade payables), keeping the statement balanced.","distractor_reasons":{"A":"Incorrect because inventory held for resale is a current asset, and buying goods on credit does not increase equity.","B":"Option B is correct because receiving inventory adds $15,000 to current assets while owing the supplier adds $15,000 to current liabilities (trade payables), keeping the statement balanced.","C":"Incorrect because inventory increases current assets, and working capital remains unchanged since both current assets and current liabilities rise by $15,000.","D":"Incorrect because 30-day trade credit is a current liability and no cash was received."}}},{"id":"P1_U5_MCQ_089","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_089","question":"A furniture retailer uses $10,000 from its bank current account to pay off overdue trade payables. What is the immediate effect of this payment on the retailer's working capital?","options":{"A":"Working capital increases by $10,000","B":"Working capital decreases by $10,000","C":"Working capital remains unchanged because current assets and current liabilities both fall by $10,000","D":"Working capital doubles because trade payables are eliminated"},"correctOption":"C","correctAnswer":"Working capital remains unchanged because current assets and current liabilities both fall by $10,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash (a current asset) decreases by $10,000 and trade payables (a current liability) also decrease by $10,000, leaving working capital (Current assets - Current liabilities) unchanged.","distractor_reasons":{"A":"Incorrect because paying a supplier reduces cash by the same amount that liabilities fall.","B":"Incorrect because although cash falls by $10,000, current liabilities also drop by $10,000.","C":"Option C is correct because cash (a current asset) decreases by $10,000 and trade payables (a current liability) also decrease by $10,000, leaving working capital (Current assets - Current liabilities) unchanged.","D":"Incorrect because reducing both current assets and current liabilities equally leaves their difference constant."}}},{"id":"P1_U5_MCQ_090","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_090","question":"A delivery business purchases a new van for $35,000 financed entirely by a 5-year bank loan. Which two items on the statement of financial position increase by $35,000?","options":{"A":"Current assets and current liabilities","B":"Non-current assets and non-current liabilities","C":"Non-current assets and shareholders' equity","D":"Current assets and retained profit"},"correctOption":"B","correctAnswer":"Non-current assets and non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the delivery van is a non-current asset (+$35,000) and the 5-year bank loan is a non-current liability (+$35,000).","distractor_reasons":{"A":"Incorrect because both the van and the 5-year loan are long-term items (over one year), not current items.","B":"Option B is correct because the delivery van is a non-current asset (+$35,000) and the 5-year bank loan is a non-current liability (+$35,000).","C":"Incorrect because financing an asset with a bank loan creates a liability rather than increasing owners' equity.","D":"Incorrect because the van is a non-current asset and borrowing a loan does not generate retained profit."}}},{"id":"P1_U5_MCQ_091","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_091","question":"A manufacturing firm uses $50,000 of its cash reserves to buy a new CNC cutting machine outright. How does this purchase affect the firm's working capital?","options":{"A":"Working capital increases by $50,000","B":"Working capital is unaffected because both items are non-current assets","C":"Working capital increases because current liabilities fall by $50,000","D":"Working capital decreases by $50,000 because cash (a current asset) falls while current liabilities stay the same"},"correctOption":"D","correctAnswer":"Working capital decreases by $50,000 because cash (a current asset) falls while current liabilities stay the same","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash (a current asset) decreases by $50,000 to buy a non-current asset, reducing Current assets - Current liabilities (working capital) by $50,000.","distractor_reasons":{"A":"Incorrect because cash leaves current assets to become a non-current asset, lowering working capital.","B":"Incorrect because cash is a current asset, whereas the machine is a non-current asset.","C":"Incorrect because paying cash outright does not reduce existing current liabilities.","D":"Option D is correct because cash (a current asset) decreases by $50,000 to buy a non-current asset, reducing Current assets - Current liabilities (working capital) by $50,000."}}},{"id":"P1_U5_MCQ_092","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_092","question":"A restaurant's statement of financial position shows current assets of $18,000 and current liabilities of $34,000, giving negative working capital of -$16,000. What major risk does this indicate for the restaurant?","options":{"A":"It is guaranteed to have the highest gross profit margin in the industry","B":"It has too much idle cash sitting unproductive in its bank account","C":"Its non-current assets are worth less than zero","D":"It faces a high risk of being unable to pay short-term debts such as suppliers and overdrafts as they fall due"},"correctOption":"D","correctAnswer":"It faces a high risk of being unable to pay short-term debts such as suppliers and overdrafts as they fall due","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because negative working capital means short-term debts due within 12 months exceed short-term assets, signalling a serious liquidity risk.","distractor_reasons":{"A":"Incorrect because liquidity on the statement of financial position does not measure gross profit margin.","B":"Incorrect because negative working capital indicates a shortage of liquid assets, not an excess of idle cash.","C":"Incorrect because working capital only compares current assets and current liabilities, not non-current assets.","D":"Option D is correct because negative working capital means short-term debts due within 12 months exceed short-term assets, signalling a serious liquidity risk."}}},{"id":"P1_U5_MCQ_093","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_093","question":"A fashion retailer's total current assets increased from $60,000 to $95,000 over the past year, but $80,000 of this total consists of unsold seasonal clothing inventory while cash is only $2,000. Why might the retailer still struggle to pay urgent bills?","options":{"A":"Inventory is classified as a non-current liability","B":"Trade payables cannot legally be paid using cash from inventory sales","C":"Inventory is the least liquid current asset and may take time or heavy discounting to turn into cash","D":"Current assets are never used to pay current liabilities"},"correctOption":"C","correctAnswer":"Inventory is the least liquid current asset and may take time or heavy discounting to turn into cash","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because inventory must first be sold and converted into cash before it can pay bills, and out-of-season fashion inventory may be difficult to sell quickly.","distractor_reasons":{"A":"Incorrect because inventory is a current asset, not a liability.","B":"Incorrect because cash generated from selling inventory is the normal way retailers pay trade payables.","C":"Option C is correct because inventory must first be sold and converted into cash before it can pay bills, and out-of-season fashion inventory may be difficult to sell quickly.","D":"Incorrect because current assets are the primary source used to settle current liabilities."}}},{"id":"P1_U5_MCQ_094","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_094","question":"Examining two consecutive statements of financial position, a wholesale business notices that its trade receivables rose from $30,000 to $75,000 while annual sales revenue grew by only 5%. What does this change most likely indicate?","options":{"A":"The business has paid off all of its long-term bank loans","B":"Credit customers are taking much longer to pay their invoices, tying up the business's working capital","C":"The business has reduced its inventory to zero","D":"Suppliers are demanding faster cash payments from the business"},"correctOption":"B","correctAnswer":"Credit customers are taking much longer to pay their invoices, tying up the business's working capital","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a 150% jump in trade receivables alongside a 5% rise in sales means customers are delaying payments, reducing cash availability.","distractor_reasons":{"A":"Incorrect because trade receivables reflect unpaid customer invoices, not bank loan repayments.","B":"Option B is correct because a 150% jump in trade receivables alongside a 5% rise in sales means customers are delaying payments, reducing cash availability.","C":"Incorrect because rising trade receivables do not imply inventory has fallen to zero.","D":"Incorrect because supplier payment speed affects trade payables, whereas trade receivables track customer payments."}}},{"id":"P1_U5_MCQ_095","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_095","question":"At the end of the financial year, a profitable company retains $65,000 of its profit after paying tax and dividends. How does this retained profit appear on the company's statement of financial position?","options":{"A":"It is deducted from non-current assets","B":"It is added to current liabilities under trade payables","C":"It is recorded as a non-current liability owed to directors","D":"It is added to shareholders' equity, increasing total equity and capital employed"},"correctOption":"D","correctAnswer":"It is added to shareholders' equity, increasing total equity and capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retained profit belongs to the owners/shareholders and is added to equity (reserves) on the statement of financial position, increasing capital employed.","distractor_reasons":{"A":"Incorrect because retained profit increases the net worth of the business rather than reducing assets.","B":"Incorrect because retained profit is internal equity, not an external debt owed to suppliers.","C":"Incorrect because retained profit is owned by shareholders, not a loan owed to directors.","D":"Option D is correct because retained profit belongs to the owners/shareholders and is added to equity (reserves) on the statement of financial position, increasing capital employed."}}},{"id":"P1_U5_MCQ_096","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_096","question":"A student comparing a company's annual financial statements asks why the statement of profit or loss covers 'the year ended 31 March', whereas the statement of financial position is headed 'as at 31 March'. What explains this difference?","options":{"A":"The statement of profit or loss only records transactions that happen on the final day of the year","B":"The statement of financial position is only prepared once every ten years","C":"The statement of profit or loss measures trading performance over a period of time, while the statement of financial position shows assets, liabilities, and equity at a single date","D":"The statement of financial position excludes all current assets and current liabilities"},"correctOption":"C","correctAnswer":"The statement of profit or loss measures trading performance over a period of time, while the statement of financial position shows assets, liabilities, and equity at a single date","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because revenue, costs, and profit accumulate over an entire trading period (flow), whereas assets, liabilities, and equity are measured at one specific moment in time (snapshot).","distractor_reasons":{"A":"Incorrect because the statement of profit or loss totals all revenue and costs across the full 12-month period.","B":"Incorrect because limited companies prepare a statement of financial position every year.","C":"Option C is correct because revenue, costs, and profit accumulate over an entire trading period (flow), whereas assets, liabilities, and equity are measured at one specific moment in time (snapshot).","D":"Incorrect because current assets and current liabilities are essential sections of the statement of financial position."}}},{"id":"P1_U5_MCQ_097","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_097","question":"Over three years, a logistics company's non-current liabilities increased from $80,000 to $420,000 while its total equity remained at $140,000. Why might a bank hesitate to approve another large loan after reviewing this statement of financial position?","options":{"A":"The company has zero non-current liabilities to show borrowing experience","B":"High existing long-term debt relative to equity increases financial risk and fixed interest commitments","C":"Non-current liabilities are automatically deducted from the company's gross profit","D":"The company's working capital must be equal to its non-current liabilities"},"correctOption":"B","correctAnswer":"High existing long-term debt relative to equity increases financial risk and fixed interest commitments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a high level of non-current liabilities compared with equity means heavy interest and repayment obligations, increasing the risk of default if sales dip.","distractor_reasons":{"A":"Incorrect because the company already has $420,000 in non-current liabilities.","B":"Option B is correct because a high level of non-current liabilities compared with equity means heavy interest and repayment obligations, increasing the risk of default if sales dip.","C":"Incorrect because loan principal balances sit on the statement of financial position, not as deductions from gross profit.","D":"Incorrect because there is no requirement for working capital to equal non-current liabilities."}}},{"id":"P1_U5_MCQ_098","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_098","question":"A profitable company pays out $30,000 in cash dividends to its shareholders at the end of the year. How does paying these cash dividends affect the company's statement of financial position?","options":{"A":"Non-current assets increase by $30,000 and non-current liabilities decrease by $30,000","B":"Current assets (cash) increase by $30,000 and equity increases by $30,000","C":"Current assets (cash) decrease by $30,000 and equity (retained profit) decreases by $30,000","D":"Current liabilities increase by $30,000 and non-current assets decrease by $30,000"},"correctOption":"C","correctAnswer":"Current assets (cash) decrease by $30,000 and equity (retained profit) decreases by $30,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because paying cash dividends reduces the company's bank cash (current assets) by $30,000 and reduces retained profit within equity by $30,000.","distractor_reasons":{"A":"Incorrect because dividends are paid in cash (current asset) out of equity, not non-current items.","B":"Incorrect because paying dividends sends cash out of the company to shareholders, reducing both cash and retained profit.","C":"Option C is correct because paying cash dividends reduces the company's bank cash (current assets) by $30,000 and reduces retained profit within equity by $30,000.","D":"Incorrect because once paid in cash, no liability remains and non-current assets are unaffected."}}},{"id":"P1_U5_MCQ_099","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_099","question":"A manufacturing company's statement of financial position lists its factory machinery at a value of $220,000, but when the directors try to sell the machinery, buyers offer only $140,000. What does this illustrate about interpreting a statement of financial position?","options":{"A":"Machinery should always be listed under current liabilities","B":"Asset values recorded in accounts are based on historical/book values and may differ from current market resale values","C":"The company's accountant made an illegal error by recording the machinery","D":"Non-current assets always sell for more than their recorded value"},"correctOption":"B","correctAnswer":"Asset values recorded in accounts are based on historical/book values and may differ from current market resale values","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because asset values shown on a statement of financial position reflect accounting valuations (historical cost less depreciation) rather than guaranteed market liquidation prices.","distractor_reasons":{"A":"Incorrect because machinery is a non-current asset, not a liability.","B":"Option B is correct because asset values shown on a statement of financial position reflect accounting valuations (historical cost less depreciation) rather than guaranteed market liquidation prices.","C":"Incorrect because recording assets at book value follows standard accounting rules, even if market demand changes.","D":"Incorrect because specialised machinery often loses resale value faster than its accounting book value."}}},{"id":"P1_U5_MCQ_100","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_100","question":"A growing bakery chain applies for a $150,000 bank loan to purchase new ovens. Looking at the bakery's statement of financial position, which feature would most reassure the bank manager that the loan is low-risk?","options":{"A":"The bakery owns $400,000 in unmortgaged freehold property (non-current assets) that can be offered as collateral","B":"The bakery has negative working capital of -$45,000","C":"The bakery already has $600,000 in overdue trade payables","D":"The bakery's current assets consist entirely of perishable bread inventory"},"correctOption":"A","correctAnswer":"The bakery owns $400,000 in unmortgaged freehold property (non-current assets) that can be offered as collateral","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because owning $400,000 of debt-free property provides strong collateral/security that the bank could claim if the bakery defaulted on the loan.","distractor_reasons":{"A":"Option A is correct because owning $400,000 of debt-free property provides strong collateral/security that the bank could claim if the bakery defaulted on the loan.","B":"Incorrect because negative working capital signals severe short-term liquidity risk, alarming lenders.","C":"Incorrect because overdue trade payables show the business is already struggling to pay its creditors.","D":"Incorrect because perishable inventory is illiquid and cannot serve as reliable security for a long-term loan."}}},{"id":"P1_U5_MCQ_101","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_101","question":"A retail business achieves a 22% profit margin for the year, yet it struggles to pay its monthly utility bills and supplier invoices on time. What is the key difference between profitability and liquidity?","options":{"A":"Profitability measures cash in the bank, whereas liquidity measures total sales revenue","B":"Profitability measures profit made relative to sales or capital invested, whereas liquidity measures the ability to pay short-term debts as they fall due","C":"Profitability only applies to sole traders, whereas liquidity only applies to public limited companies","D":"Profitability is calculated from the statement of financial position, whereas liquidity is calculated solely from the statement of profit or loss"},"correctOption":"B","correctAnswer":"Profitability measures profit made relative to sales or capital invested, whereas liquidity measures the ability to pay short-term debts as they fall due","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profitability evaluates profit performance relative to revenue or capital employed, while liquidity assesses whether current assets can cover immediate short-term liabilities.","distractor_reasons":{"A":"Incorrect because this reverses the two concepts; liquidity relates to cash and short-term assets, while profitability relates to profit.","B":"Option B is correct because profitability evaluates profit performance relative to revenue or capital employed, while liquidity assesses whether current assets can cover immediate short-term liabilities.","C":"Incorrect because both profitability and liquidity are vital for businesses of all legal structures.","D":"Incorrect because profitability uses the statement of profit or loss (and capital employed), while liquidity uses current assets and current liabilities from the statement of financial position."}}},{"id":"P1_U5_MCQ_102","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_102","question":"A furniture retailer reports annual sales revenue of $500,000, cost of sales of $320,000, and final profit of $60,000. What is the retailer's gross profit margin?","options":{"A":"12%","B":"64%","C":"36%","D":"56.25%"},"correctOption":"C","correctAnswer":"36%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = $500,000 - $320,000 = $180,000, and Gross profit margin = ($180,000 / $500,000) × 100 = 36%.","distractor_reasons":{"A":"Incorrect because 12% is the profit margin ($60,000 / $500,000 × 100), not the gross profit margin.","B":"Incorrect because 64% is the ratio of cost of sales to revenue ($320,000 / $500,000 × 100).","C":"Option C is correct because Gross profit = $500,000 - $320,000 = $180,000, and Gross profit margin = ($180,000 / $500,000) × 100 = 36%.","D":"Incorrect because 56.25% divides gross profit by cost of sales ($180,000 / $320,000 × 100) instead of dividing by revenue."}}},{"id":"P1_U5_MCQ_103","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_103","question":"A supermarket's annual revenue increased by 10%, yet its gross profit margin fell from 28% to 22% over the same period. What is the most likely reason for this fall in gross profit margin?","options":{"A":"The supermarket spent more on head-office administrative salaries","B":"Supplier prices for goods rose faster than the supermarket's selling prices, or the supermarket cut prices to attract shoppers","C":"The supermarket took out a larger long-term bank loan","D":"Customers paid their credit accounts faster than last year"},"correctOption":"B","correctAnswer":"Supplier prices for goods rose faster than the supermarket's selling prices, or the supermarket cut prices to attract shoppers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because gross profit margin depends on the gap between selling prices and cost of sales; higher supplier costs or price discounts shrink this percentage margin.","distractor_reasons":{"A":"Incorrect because administrative salaries are overhead expenses deducted after gross profit, so they affect profit margin rather than gross profit margin.","B":"Option B is correct because gross profit margin depends on the gap between selling prices and cost of sales; higher supplier costs or price discounts shrink this percentage margin.","C":"Incorrect because bank loans and interest do not affect gross profit margin.","D":"Incorrect because faster customer payments improve cash flow, not gross profit margin."}}},{"id":"P1_U5_MCQ_104","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_104","question":"A software consultancy generates annual revenue of $600,000, gross profit of $420,000, and final profit of $90,000. What is the consultancy's profit margin?","options":{"A":"70%","B":"21.4%","C":"55%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Profit margin = (Profit / Revenue) × 100 = ($90,000 / $600,000) × 100 = 15%.","distractor_reasons":{"A":"Incorrect because 70% is the gross profit margin ($420,000 / $600,000 × 100), not the profit margin.","B":"Incorrect because 21.4% divides profit by gross profit ($90,000 / $420,000 × 100) instead of dividing by revenue.","C":"Incorrect because 55% subtracts profit margin from gross profit margin (70% - 15%).","D":"Option D is correct because Profit margin = (Profit / Revenue) × 100 = ($90,000 / $600,000) × 100 = 15%."}}},{"id":"P1_U5_MCQ_105","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_105","question":"Between 2025 and 2026, a cosmetics brand's gross profit margin improved from 50% to 56%, while its profit margin fell from 18% to 13%. What does this divergence reveal about the brand's performance?","options":{"A":"Cost of sales rose sharply while overhead expenses fell","B":"The brand improved its direct product margin, but overhead expenses such as marketing or rent grew much faster than revenue","C":"The brand's liquidity ratios have fallen below 0.5 : 1","D":"Revenue fell by 50% during 2026"},"correctOption":"B","correctAnswer":"The brand improved its direct product margin, but overhead expenses such as marketing or rent grew much faster than revenue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a higher gross profit margin shows improved control over cost of sales/pricing, whereas a lower profit margin indicates that indirect overhead expenses increased disproportionately.","distractor_reasons":{"A":"Incorrect because if cost of sales rose and expenses fell, gross profit margin would fall rather than rise.","B":"Option B is correct because a higher gross profit margin shows improved control over cost of sales/pricing, whereas a lower profit margin indicates that indirect overhead expenses increased disproportionately.","C":"Incorrect because profitability margins do not measure liquidity ratios.","D":"Incorrect because profit margins measure percentages of revenue and do not imply a 50% drop in sales."}}},{"id":"P1_U5_MCQ_106","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_106","question":"A logistics company earns an annual profit of $120,000 and has capital employed of $800,000 (comprising $550,000 equity and $250,000 non-current liabilities). What is the company's Return on Capital Employed (ROCE)?","options":{"A":"21.8%","B":"48%","C":"15%","D":"12%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ROCE = (Profit / Capital employed) × 100 = ($120,000 / $800,000) × 100 = 15%.","distractor_reasons":{"A":"Incorrect because 21.8% divides profit only by equity ($120,000 / $550,000 × 100), omitting non-current liabilities from capital employed.","B":"Incorrect because 48% divides profit only by non-current liabilities ($120,000 / $250,000 × 100).","C":"Option C is correct because ROCE = (Profit / Capital employed) × 100 = ($120,000 / $800,000) × 100 = 15%.","D":"Incorrect because 12% miscalculates the percentage by dividing by $1,000,000."}}},{"id":"P1_U5_MCQ_107","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_107","question":"An investor sees that Company X achieved a Return on Capital Employed (ROCE) of 16% this year, compared with 11% last year, a bank savings interest rate of 4%, and an industry average ROCE of 14%. How should the investor interpret Company X's ROCE?","options":{"A":"Company X is generating a strong and improving return on invested capital that outperforms both bank interest rates and industry rivals","B":"Company X is losing money because 16% is below 50%","C":"Company X has too much cash and should immediately repay all shareholders","D":"Company X's current liabilities exceed its current assets by 16%"},"correctOption":"A","correctAnswer":"Company X is generating a strong and improving return on invested capital that outperforms both bank interest rates and industry rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ROCE measures how efficiently a business uses invested capital to generate profit; 16% improves on last year (11%), exceeds the risk-free bank rate (4%), and beats competitors (14%).","distractor_reasons":{"A":"Option A is correct because ROCE measures how efficiently a business uses invested capital to generate profit; 16% improves on last year (11%), exceeds the risk-free bank rate (4%), and beats competitors (14%).","B":"Incorrect because an ROCE of 16% represents a healthy positive return on capital, not a loss.","C":"Incorrect because a high ROCE indicates effective use of capital rather than excess idle cash.","D":"Incorrect because ROCE is a profitability ratio and does not measure current assets against current liabilities."}}},{"id":"P1_U5_MCQ_108","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_108","question":"A manufacturing company wants to increase its Return on Capital Employed (ROCE) next year. Which action would directly improve the company's ROCE?","options":{"A":"Taking out a large new long-term bank loan to hold as idle cash in the bank","B":"Increasing overhead expenses while keeping revenue and capital employed constant","C":"Issuing $500,000 of new shares without generating any extra profit","D":"Cutting production waste to increase annual profit while keeping capital employed unchanged"},"correctOption":"D","correctAnswer":"Cutting production waste to increase annual profit while keeping capital employed unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ROCE = (Profit / Capital employed) × 100; increasing profit (the numerator) without increasing capital employed (the denominator) directly raises ROCE.","distractor_reasons":{"A":"Incorrect because adding a new long-term loan increases capital employed without raising operating profit, lowering ROCE.","B":"Incorrect because higher expenses reduce profit, which lowers ROCE.","C":"Incorrect because raising share capital increases capital employed; if profit does not rise, ROCE falls.","D":"Option D is correct because ROCE = (Profit / Capital employed) × 100; increasing profit (the numerator) without increasing capital employed (the denominator) directly raises ROCE."}}},{"id":"P1_U5_MCQ_109","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_109","question":"A wholesale distributor has current assets of $135,000 (including $55,000 of inventory) and current liabilities of $75,000. What is the distributor's current ratio?","options":{"A":"1.07 : 1","B":"1.8 : 1","C":"0.56 : 1","D":"2.53 : 1"},"correctOption":"B","correctAnswer":"1.8 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Current ratio = Current assets / Current liabilities = $135,000 / $75,000 = 1.8 : 1.","distractor_reasons":{"A":"Incorrect because 1.07 : 1 deducts inventory first (($135,000 - $55,000) / $75,000), which is the acid-test ratio.","B":"Option B is correct because Current ratio = Current assets / Current liabilities = $135,000 / $75,000 = 1.8 : 1.","C":"Incorrect because 0.56 : 1 inverts the formula by dividing current liabilities by current assets ($75,000 / $135,000).","D":"Incorrect because 2.53 : 1 adds inventory to current assets instead of recognising it is already included ($190,000 / $75,000)."}}},{"id":"P1_U5_MCQ_110","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_110","question":"Over the past two years, a construction firm's current ratio has fallen from 1.9 : 1 to 0.75 : 1. What does a current ratio of 0.75 : 1 indicate?","options":{"A":"The firm's profit margin has increased to 75%","B":"The firm holds $1.75 of current assets for every $1 of current liabilities","C":"The firm has only $0.75 of current assets for every $1 of current liabilities, indicating a serious liquidity problem","D":"The firm has zero non-current assets on its statement of financial position"},"correctOption":"C","correctAnswer":"The firm has only $0.75 of current assets for every $1 of current liabilities, indicating a serious liquidity problem","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a current ratio below 1 : 1 means current liabilities exceed current assets, so the business may not be able to pay its short-term debts on time.","distractor_reasons":{"A":"Incorrect because the current ratio measures liquidity, not profit margin.","B":"Incorrect because 0.75 : 1 means $0.75 of current assets per $1 of current liabilities, not $1.75.","C":"Option C is correct because a current ratio below 1 : 1 means current liabilities exceed current assets, so the business may not be able to pay its short-term debts on time.","D":"Incorrect because the current ratio excludes non-current assets."}}},{"id":"P1_U5_MCQ_111","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_111","question":"A garden furniture retailer has a current ratio of 4.8 : 1, which is far above the typical safe benchmark of 1.5 : 1 to 2 : 1. Why might the retailer's finance manager view a current ratio of 4.8 : 1 as a concern?","options":{"A":"Too much capital is tied up unproductively in excess inventory, uncollected trade receivables, or low-interest cash","B":"The retailer is about to run out of cash to pay its short-term suppliers","C":"A current ratio above 2 : 1 is illegal for retail businesses","D":"It proves the retailer's gross profit margin is negative"},"correctOption":"A","correctAnswer":"Too much capital is tied up unproductively in excess inventory, uncollected trade receivables, or low-interest cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an excessively high current ratio suggests inefficient working capital management, with funds sitting idle in unsold inventory, overdue receivables, or low-return cash instead of being invested profitably.","distractor_reasons":{"A":"Option A is correct because an excessively high current ratio suggests inefficient working capital management, with funds sitting idle in unsold inventory, overdue receivables, or low-return cash instead of being invested profitably.","B":"Incorrect because a ratio of 4.8 : 1 indicates abundant current assets relative to short-term debts, not a liquidity shortage.","C":"Incorrect because there is no legal upper limit on a company's current ratio.","D":"Incorrect because the current ratio does not measure gross profit margin."}}},{"id":"P1_U5_MCQ_112","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_112","question":"A clothing wholesaler's statement of financial position shows current assets of $110,000, inventory of $50,000, and current liabilities of $40,000. What is the wholesaler's acid-test ratio?","options":{"A":"2.75 : 1","B":"1.25 : 1","C":"0.67 : 1","D":"1.5 : 1"},"correctOption":"D","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($110,000 - $50,000) / $40,000 = $60,000 / $40,000 = 1.5 : 1.","distractor_reasons":{"A":"Incorrect because 2.75 : 1 is the current ratio ($110,000 / $40,000), which fails to subtract inventory.","B":"Incorrect because 1.25 : 1 divides inventory by current liabilities ($50,000 / $40,000).","C":"Incorrect because 0.67 : 1 inverts the acid-test formula ($40,000 / $60,000).","D":"Option D is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($110,000 - $50,000) / $40,000 = $60,000 / $40,000 = 1.5 : 1."}}},{"id":"P1_U5_MCQ_113","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_113","question":"When assessing whether a car dealership can pay its urgent short-term bills, a bank manager calculates the acid-test ratio in addition to the current ratio. Why is inventory subtracted from current assets in the acid-test ratio?","options":{"A":"Because inventory is a non-current liability","B":"Because inventory is the least liquid current asset and cannot always be turned into cash quickly at full value","C":"Because businesses are legally forbidden from selling inventory to pay debts","D":"Because inventory is already included inside cash and trade receivables"},"correctOption":"B","correctAnswer":"Because inventory is the least liquid current asset and cannot always be turned into cash quickly at full value","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inventory must be sold first before generating cash and may take months to sell (especially high-value items like cars), so excluding it tests immediate liquidity.","distractor_reasons":{"A":"Incorrect because inventory is a current asset, not a liability.","B":"Option B is correct because inventory must be sold first before generating cash and may take months to sell (especially high-value items like cars), so excluding it tests immediate liquidity.","C":"Incorrect because selling inventory is the primary way trading businesses generate cash.","D":"Incorrect because inventory is a separate current asset line item, not part of cash or trade receivables."}}},{"id":"P1_U5_MCQ_114","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_114","question":"A toy manufacturer has a current ratio of 2.4 : 1, which looks healthy, but its acid-test ratio is only 0.55 : 1. What does the large gap between these two liquidity ratios reveal?","options":{"A":"The manufacturer has no current liabilities","B":"The manufacturer's profit margin is 55%","C":"A very high proportion of the manufacturer's current assets is tied up in unsold inventory","D":"The manufacturer has too much cash sitting in its bank account"},"correctOption":"C","correctAnswer":"A very high proportion of the manufacturer's current assets is tied up in unsold inventory","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the only difference between the current ratio and the acid-test ratio is inventory; a sharp drop when inventory is removed shows the business is holding excessive inventory.","distractor_reasons":{"A":"Incorrect because if current liabilities were zero, neither ratio could be calculated as finite numbers.","B":"Incorrect because liquidity ratios do not measure profit margins.","C":"Option C is correct because the only difference between the current ratio and the acid-test ratio is inventory; a sharp drop when inventory is removed shows the business is holding excessive inventory.","D":"Incorrect because high cash balances would keep the acid-test ratio high alongside the current ratio."}}},{"id":"P1_U5_MCQ_115","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_115","question":"A retail company's current ratio has dropped to 0.9 : 1 and its acid-test ratio is 0.5 : 1, causing concern among suppliers. Which action would improve both liquidity ratios?","options":{"A":"Selling unwanted non-current assets for cash or replacing a short-term overdraft with a long-term bank loan","B":"Using existing bank cash to buy a new delivery van","C":"Paying out all available cash as dividends to shareholders","D":"Buying more inventory on 30-day trade credit"},"correctOption":"A","correctAnswer":"Selling unwanted non-current assets for cash or replacing a short-term overdraft with a long-term bank loan","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because selling unwanted non-current assets increases cash (current assets) while converting an overdraft into a long-term loan reduces current liabilities, raising both liquidity ratios.","distractor_reasons":{"A":"Option A is correct because selling unwanted non-current assets increases cash (current assets) while converting an overdraft into a long-term loan reduces current liabilities, raising both liquidity ratios.","B":"Incorrect because spending cash on a non-current asset reduces current assets and lowers both liquidity ratios.","C":"Incorrect because paying cash dividends reduces current assets and worsens liquidity ratios.","D":"Incorrect because buying inventory on credit increases both current assets (inventory) and current liabilities, lowering the acid-test ratio."}}},{"id":"P1_U5_MCQ_116","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_116","question":"Internal and external stakeholders analyse a company's published financial statements for different reasons. How do internal managers primarily use ratio analysis?","options":{"A":"To calculate how much corporation tax the government should collect from rival firms","B":"To decide whether to supply raw materials on trade credit to their own company","C":"To determine whether to approve a personal mortgage for a customer","D":"To monitor business performance against targets, control costs, and make pricing or investment decisions"},"correctOption":"D","correctAnswer":"To monitor business performance against targets, control costs, and make pricing or investment decisions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because managers are internal users who analyse profitability and liquidity ratios to evaluate efficiency, spot rising costs, and guide strategic decisions.","distractor_reasons":{"A":"Incorrect because tax assessment is carried out by external government tax authorities.","B":"Incorrect because trade credit decisions are made by external suppliers.","C":"Incorrect because personal mortgages are assessed by external banks.","D":"Option D is correct because managers are internal users who analyse profitability and liquidity ratios to evaluate efficiency, spot rising costs, and guide strategic decisions."}}},{"id":"P1_U5_MCQ_117","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_117","question":"Before attending the Annual General Meeting (AGM) of a public limited company, a shareholder examines the company's profit margin, ROCE, and dividend per share compared with previous years. Why is this financial information important to shareholders?","options":{"A":"It allows shareholders to set the daily work rotas for factory employees","B":"It helps shareholders judge the return on their investment, decide whether to buy or sell shares, and assess directors' performance","C":"It determines whether the shareholder has unlimited liability for company debts","D":"It shows shareholders the exact credit score of every individual customer"},"correctOption":"B","correctAnswer":"It helps shareholders judge the return on their investment, decide whether to buy or sell shares, and assess directors' performance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because shareholders own the company and use profitability ratios and profit trends to evaluate management effectiveness and decide whether to retain or sell their shares.","distractor_reasons":{"A":"Incorrect because operational work rotas are handled by managers and supervisors, not shareholders.","B":"Option B is correct because shareholders own the company and use profitability ratios and profit trends to evaluate management effectiveness and decide whether to retain or sell their shares.","C":"Incorrect because shareholders in a limited company always have limited liability regardless of financial ratios.","D":"Incorrect because individual customer credit details are not published in company accounts."}}},{"id":"P1_U5_MCQ_118","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_118","question":"Trade union representatives representing factory workers study the employer's latest statement of profit or loss and liquidity ratios ahead of annual pay talks. How are employees and unions likely to use this financial data?","options":{"A":"To decide whether to grant the company a 10-year bank loan","B":"To calculate the company's import tariff obligations","C":"To assess job security and argue for higher wages if profits and profitability margins have risen","D":"To value the company's shares for a hostile takeover"},"correctOption":"C","correctAnswer":"To assess job security and argue for higher wages if profits and profitability margins have risen","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because employees are internal stakeholders who check profitability and liquidity to gauge whether their jobs are safe and whether the business can afford wage increases.","distractor_reasons":{"A":"Incorrect because bank loans are granted by external lenders/banks, not employees.","B":"Incorrect because import tariffs are customs taxes administered by government authorities.","C":"Option C is correct because employees are internal stakeholders who check profitability and liquidity to gauge whether their jobs are safe and whether the business can afford wage increases.","D":"Incorrect because hostile takeovers are conducted by rival companies or external investors."}}},{"id":"P1_U5_MCQ_119","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_119","question":"A packaging company applies to a commercial bank for a $250,000 loan to buy new machinery. Why will the bank manager carefully analyse the company's liquidity ratios and existing non-current liabilities before approving the loan?","options":{"A":"To ensure the company has enough cash flow and liquid assets to pay interest and repay the loan on time without defaulting","B":"To check whether the company's employees are members of a trade union","C":"To decide what retail price the packaging company should charge its customers","D":"To calculate how many shares the bank will receive as dividends"},"correctOption":"A","correctAnswer":"To ensure the company has enough cash flow and liquid assets to pay interest and repay the loan on time without defaulting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because banks are external lenders whose primary objective is ensuring the borrower can meet regular interest payments and repay the loan principal.","distractor_reasons":{"A":"Option A is correct because banks are external lenders whose primary objective is ensuring the borrower can meet regular interest payments and repay the loan principal.","B":"Incorrect because trade union membership is not reported in financial ratios or used to assess loan repayment capacity.","C":"Incorrect because pricing decisions are made by the company's own marketing and finance managers.","D":"Incorrect because banks earn interest on loans rather than receiving shareholder dividends."}}},{"id":"P1_U5_MCQ_120","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_120","question":"A new retail chain asks a fabric manufacturer to supply $40,000 of goods on 60-day trade credit. Which ratios from the retail chain's accounts will the fabric manufacturer examine most closely before agreeing to offer trade credit?","options":{"A":"Gross profit margin and return on capital employed only","B":"Labour productivity and margin of safety","C":"Market share and break-even output","D":"Current ratio and acid-test ratio to verify whether the retailer can pay its short-term debts on time"},"correctOption":"D","correctAnswer":"Current ratio and acid-test ratio to verify whether the retailer can pay its short-term debts on time","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because suppliers are external stakeholders who need reassurance that a credit customer has sufficient short-term liquidity to pay invoices when they fall due.","distractor_reasons":{"A":"Incorrect because a profitable company can still run out of cash; suppliers prioritise liquidity ratios to ensure prompt payment.","B":"Incorrect because labour productivity and margin of safety are internal operational metrics not published in financial statements.","C":"Incorrect because market share and break-even output do not tell a supplier whether cash is available to pay invoices in 60 days.","D":"Option D is correct because suppliers are external stakeholders who need reassurance that a credit customer has sufficient short-term liquidity to pay invoices when they fall due."}}},{"id":"P1_U5_MCQ_121","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_121","question":"Every year, incorporated businesses must submit their audited financial statements to government authorities. How does the government use this financial information?","options":{"A":"To set the business's internal marketing strategy and advertising budget","B":"To calculate the amount of corporation tax owed and monitor the health of key industries","C":"To decide which suppliers the business must buy raw materials from","D":"To vote for new directors at the company's Annual General Meeting"},"correctOption":"B","correctAnswer":"To calculate the amount of corporation tax owed and monitor the health of key industries","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because government tax authorities use reported profits to assess tax liabilities, while economic departments track business growth and employment trends.","distractor_reasons":{"A":"Incorrect because private sector businesses decide their own marketing strategies.","B":"Option B is correct because government tax authorities use reported profits to assess tax liabilities, while economic departments track business growth and employment trends.","C":"Incorrect because supplier selection is an operational business decision, not a government function.","D":"Incorrect because only shareholders vote at an AGM unless the business is state-owned."}}},{"id":"P1_U5_MCQ_122","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_122","question":"An investor buys shares in an airline solely because its published accounts show a high ROCE and profit margin for the previous year, only for the airline to suffer heavy losses three months later due to a sudden fuel crisis. Which limitation of ratio analysis does this highlight?","options":{"A":"Ratios can only be calculated by government accountants","B":"Financial accounts deliberately exclude all expenses to make companies look profitable","C":"Accounts and ratios are based on historical data from the past and cannot predict sudden future market or economic changes","D":"Profitability ratios are always identical across every year"},"correctOption":"C","correctAnswer":"Accounts and ratios are based on historical data from the past and cannot predict sudden future market or economic changes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because published financial statements report past trading performance, which is not a guarantee of future results when external conditions change.","distractor_reasons":{"A":"Incorrect because any student, investor, or manager can calculate ratios from published accounts.","B":"Incorrect because audited accounts must legally include all expenses.","C":"Option C is correct because published financial statements report past trading performance, which is not a guarantee of future results when external conditions change.","D":"Incorrect because ratios fluctuate every year as revenue, costs, and assets change."}}},{"id":"P1_U5_MCQ_123","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_123","question":"A student compares the current ratio of a high-street supermarket (0.85 : 1) with that of a luxury yacht builder (2.6 : 1) and concludes that the supermarket is badly managed. Why is this comparison misleading?","options":{"A":"Liquidity ratios can only be compared across companies in different countries","B":"Supermarkets are not permitted to calculate liquidity ratios","C":"Yacht builders do not have any current liabilities","D":"Businesses in different industries have very different operating cycles, inventory speeds, and working capital structures"},"correctOption":"D","correctAnswer":"Businesses in different industries have very different operating cycles, inventory speeds, and working capital structures","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ratio comparisons are only meaningful between businesses in the same industry; supermarkets turn inventory into cash daily and safely operate with lower current ratios than yacht builders.","distractor_reasons":{"A":"Incorrect because ratios should be compared with competitors in the same industry or with the business's own past performance.","B":"Incorrect because supermarkets regularly calculate and monitor liquidity ratios.","C":"Incorrect because yacht builders have substantial trade payables and customer deposits as current liabilities.","D":"Option D is correct because ratio comparisons are only meaningful between businesses in the same industry; supermarkets turn inventory into cash daily and safely operate with lower current ratios than yacht builders."}}},{"id":"P1_U5_MCQ_124","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_124","question":"A manufacturing company's profit margin and ROCE improved slightly this year, yet its most experienced engineers are resigning due to poor working conditions and customers are complaining about declining product quality. What limitation of using accounts and ratio analysis does this demonstrate?","options":{"A":"Ratios only measure short-term cash inflows and outflows","B":"Companies are allowed to invent fake revenue figures on their statement of profit or loss","C":"Ratio analysis automatically calculates employee absenteeism rates","D":"Financial ratios ignore qualitative non-financial factors such as staff morale, product quality, and brand reputation that affect future success"},"correctOption":"D","correctAnswer":"Financial ratios ignore qualitative non-financial factors such as staff morale, product quality, and brand reputation that affect future success","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because financial accounts only capture numerical data and omit vital non-financial factors like workforce motivation, customer satisfaction, and environmental impact.","distractor_reasons":{"A":"Incorrect because profitability ratios measure profit relative to revenue or capital, not cash flows.","B":"Incorrect because falsifying revenue is illegal fraud, not a standard limitation of ratio analysis.","C":"Incorrect because absenteeism is an HR metric, not a financial ratio.","D":"Option D is correct because financial accounts only capture numerical data and omit vital non-financial factors like workforce motivation, customer satisfaction, and environmental impact."}}},{"id":"P1_U5_MCQ_125","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_125","question":"An analyst compares the ROCE of two rival engineering firms, Firm A and Firm B, and finds that Firm A values its factory land at its original purchase price from 20 years ago whereas Firm B revalued its land to current market prices this year. Why does this complicate ratio comparison between the two firms?","options":{"A":"Land is recorded as a current liability on both statements of financial position","B":"Different accounting valuation methods and inflation distort asset values and capital employed, making direct ratio comparisons less reliable","C":"ROCE is calculated using gross profit for Firm A and revenue for Firm B","D":"Revaluing land increases Firm B's cost of sales on the statement of profit or loss"},"correctOption":"B","correctAnswer":"Different accounting valuation methods and inflation distort asset values and capital employed, making direct ratio comparisons less reliable","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because differences in accounting policies (such as asset valuation) and inflation over time can artificially inflate or deflate capital employed, distorting ROCE comparisons.","distractor_reasons":{"A":"Incorrect because land is a non-current asset, not a liability.","B":"Option B is correct because differences in accounting policies (such as asset valuation) and inflation over time can artificially inflate or deflate capital employed, distorting ROCE comparisons.","C":"Incorrect because the standard ROCE formula uses profit divided by capital employed for all businesses.","D":"Incorrect because revaluing land changes non-current assets and equity on the statement of financial position, not cost of sales."}}},{"id":"P1_U5_MCQ_126","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_126","question":"An entrepreneur is setting up a new hairdressing salon and needs $25,000 to pay a premises lease deposit, install styling chairs, and buy hairdryers before opening to customers. Which type of finance need does this describe?","options":{"A":"Start-up capital","B":"Working capital","C":"Export credit","D":"Debt factoring"},"correctOption":"A","correctAnswer":"Start-up capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because start-up capital is the finance needed by an entrepreneur to pay for essential non-current assets and initial set-up costs before a new business begins trading.","distractor_reasons":{"A":"Option A is correct because start-up capital is the finance needed by an entrepreneur to pay for essential non-current assets and initial set-up costs before a new business begins trading.","B":"Incorrect because working capital funds recurring day-to-day running costs such as weekly wages and electricity bills once trading begins.","C":"Incorrect because export credit finances international trade transactions rather than launching a local salon.","D":"Incorrect because debt factoring involves selling unpaid customer invoices to raise immediate cash."}}},{"id":"P1_U5_MCQ_127","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_127","question":"A toy retailer needs $18,000 in October to purchase extra inventory and pay temporary shop assistants ahead of the December holiday rush. Which financial need is the retailer funding?","options":{"A":"Purchase of freehold land","B":"Takeover of a rival chain","C":"Working capital for seasonal trading","D":"Start-up capital for a new company"},"correctOption":"C","correctAnswer":"Working capital for seasonal trading","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because funding temporary inventory increases and short-term staff wages is a classic working capital requirement.","distractor_reasons":{"A":"Incorrect because freehold land is a long-term non-current asset rather than seasonal inventory and wages.","B":"Incorrect because acquiring another business is long-term external expansion.","C":"Option C is correct because funding temporary inventory increases and short-term staff wages is a classic working capital requirement.","D":"Incorrect because the toy retailer is an existing business preparing for peak seasonal demand, not a start-up."}}},{"id":"P1_U5_MCQ_128","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_128","question":"A profitable cloud-software company plans to acquire a smaller cybersecurity firm and open sales offices in three new countries. Which reason for needing finance applies to this situation?","options":{"A":"Covering daily petty cash expenses","B":"Financing long-term business expansion","C":"Replacing broken office printers","D":"Paying last month's utility bill"},"correctOption":"B","correctAnswer":"Financing long-term business expansion","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because acquiring other businesses and entering overseas markets require substantial long-term finance for expansion.","distractor_reasons":{"A":"Incorrect because petty cash covers minor routine expenses, not corporate acquisitions.","B":"Option B is correct because acquiring other businesses and entering overseas markets require substantial long-term finance for expansion.","C":"Incorrect because replacing printers is minor routine asset replacement rather than international growth.","D":"Incorrect because utility bills are short-term working capital expenses."}}},{"id":"P1_U5_MCQ_129","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_129","question":"A commercial arable farm has used its combine harvester for twelve years, and frequent breakdowns are delaying grain harvests. What business need is driving the farm's request for $140,000 in finance?","options":{"A":"Funding short-term working capital","B":"Paying annual shareholder dividends","C":"Launching a new start-up business","D":"Replacing worn-out non-current assets"},"correctOption":"D","correctAnswer":"Replacing worn-out non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because established businesses frequently require long-term finance to replace ageing or obsolete machinery and vehicles.","distractor_reasons":{"A":"Incorrect because a combine harvester is a long-term non-current asset, not a short-term working capital item.","B":"Incorrect because dividends are paid out of after-tax profits rather than borrowed to replace machinery.","C":"Incorrect because the farm has already been operating for at least twelve years.","D":"Option D is correct because established businesses frequently require long-term finance to replace ageing or obsolete machinery and vehicles."}}},{"id":"P1_U5_MCQ_130","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_130","question":"A brand-new start-up café wants to buy an additional delivery scooter after two months of trading, but the owner cannot use retained profit to pay for it. Why is retained profit unavailable to this business?","options":{"A":"Retained profit can only be used by public limited companies","B":"A brand-new business has not traded long enough to accumulate past profits","C":"Retained profit is legally restricted to paying bank interest","D":"Sole traders are not allowed to retain profits in their business"},"correctOption":"B","correctAnswer":"A brand-new business has not traded long enough to accumulate past profits","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retained profit comes from past trading surpluses kept in the business, which newly formed start-ups do not yet possess.","distractor_reasons":{"A":"Incorrect because businesses of any legal structure can retain profits once they become profitable.","B":"Option B is correct because retained profit comes from past trading surpluses kept in the business, which newly formed start-ups do not yet possess.","C":"Incorrect because retained profit can be used for any legitimate business investment, including equipment.","D":"Incorrect because sole traders regularly reinvest their profits back into their businesses."}}},{"id":"P1_U5_MCQ_131","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_131","question":"A resort hotel owns an unused plot of land beside its car park and sells it for $95,000 to help pay for renovating its guest bedrooms. What is a major advantage of raising finance in this way?","options":{"A":"The hotel retains legal ownership of the land after selling it","B":"It makes better use of idle capital without incurring debt or interest charges","C":"It increases the hotel's non-current liabilities","D":"It can be repeated every month indefinitely"},"correctOption":"B","correctAnswer":"It makes better use of idle capital without incurring debt or interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because selling unwanted assets converts idle resources into immediate cash internally without adding debt or interest costs.","distractor_reasons":{"A":"Incorrect because selling an asset transfers legal ownership to the buyer.","B":"Option B is correct because selling unwanted assets converts idle resources into immediate cash internally without adding debt or interest costs.","C":"Incorrect because selling an asset reduces non-current assets and does not create any loan liability.","D":"Incorrect because a business has a limited supply of surplus assets to sell."}}},{"id":"P1_U5_MCQ_132","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_132","question":"An electronics manufacturer holds $120,000 of excess microchips in its storeroom and decides to reduce its inventory buffer to release $50,000 of cash for upgrading factory computers. What is a potential risk of using working capital as an internal source of finance in this way?","options":{"A":"The manufacturer must pay high interest to its shareholders","B":"Running down inventory too far may cause production stoppages if supplier deliveries are delayed","C":"Reducing inventory increases the company's long-term bank loans","D":"The manufacturer loses control of the business to external lenders"},"correctOption":"B","correctAnswer":"Running down inventory too far may cause production stoppages if supplier deliveries are delayed","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reducing inventory levels frees up cash, but holding too little stock risks shortages and halted production if demand spikes or deliveries are late.","distractor_reasons":{"A":"Incorrect because using internal working capital incurs no interest charges.","B":"Option B is correct because reducing inventory levels frees up cash, but holding too little stock risks shortages and halted production if demand spikes or deliveries are late.","C":"Incorrect because reducing inventory converts current assets into cash without increasing debt.","D":"Incorrect because internal finance does not involve external lenders or equity dilution."}}},{"id":"P1_U5_MCQ_133","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_133","question":"Three accountants running a partnership decide to expand into tax consultancy and each partner invests an extra $20,000 of personal savings into the firm. How is this $60,000 classified?","options":{"A":"External short-term finance","B":"Trade credit","C":"Internal finance through owners' investment","D":"Venture capital"},"correctOption":"C","correctAnswer":"Internal finance through owners' investment","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital contributed directly by the existing owners or partners from their own funds is an internal source of finance.","distractor_reasons":{"A":"Incorrect because the funds come from the owners themselves, not external institutions, and are permanent.","B":"Incorrect because trade credit is delayed payment granted by suppliers.","C":"Option C is correct because capital contributed directly by the existing owners or partners from their own funds is an internal source of finance.","D":"Incorrect because venture capital comes from outside specialist investment firms rather than existing partners."}}},{"id":"P1_U5_MCQ_134","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_134","question":"A public limited company issues 5 million new ordinary shares on the stock exchange to raise $40 million for building a clean-energy power plant. What is a significant disadvantage of issuing shares to raise this finance?","options":{"A":"The $40 million must be repaid to shareholders within five years","B":"The company must pay fixed monthly interest even if it makes a loss","C":"Existing shareholders' voting control is diluted and dividends are expected from future profits","D":"Share capital reduces the company's total equity on the statement of financial position"},"correctOption":"C","correctAnswer":"Existing shareholders' voting control is diluted and dividends are expected from future profits","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because issuing new shares spreads ownership across more shareholders, diluting original control and creating expectations for future dividend payouts.","distractor_reasons":{"A":"Incorrect because ordinary share capital is permanent finance with no repayment date.","B":"Incorrect because ordinary shares carry dividends (which are not paid if profits are insufficient), not fixed interest.","C":"Option C is correct because issuing new shares spreads ownership across more shareholders, diluting original control and creating expectations for future dividend payouts.","D":"Incorrect because issuing shares increases share capital and total equity."}}},{"id":"P1_U5_MCQ_135","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_135","question":"A private limited company needs $500,000 to purchase a new warehouse and is comparing a 10-year bank loan with issuing shares to a new private investor. Which statement correctly contrasts these two options?","options":{"A":"The bank loan gives the bank permanent voting rights, whereas shares must be repaid in 12 months","B":"The bank loan requires regular interest and principal repayments, whereas share capital does not have to be repaid","C":"Both options are internal sources of finance","D":"Neither option affects the company's statement of financial position"},"correctOption":"B","correctAnswer":"The bank loan requires regular interest and principal repayments, whereas share capital does not have to be repaid","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a bank loan is debt that must be repaid with interest over an agreed term, whereas share capital is permanent equity finance.","distractor_reasons":{"A":"Incorrect because banks do not gain voting shares from a loan, and share capital is permanent rather than 12-month debt.","B":"Option B is correct because a bank loan is debt that must be repaid with interest over an agreed term, whereas share capital is permanent equity finance.","C":"Incorrect because both bank loans and new share issues are external sources of finance.","D":"Incorrect because both increase cash/assets alongside either non-current liabilities (loan) or equity (shares)."}}},{"id":"P1_U5_MCQ_136","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_136","question":"A small events-management agency uses a $15,000 bank overdraft continuously for two years to cover its everyday expenses. Why is using an overdraft in this way poor financial management?","options":{"A":"Overdrafts require the agency to give up 50% of its shares to the bank","B":"Overdrafts charge high variable interest rates and the bank can demand immediate repayment at short notice","C":"Overdrafts can only be used to buy freehold property","D":"Overdrafts are classified as non-current assets"},"correctOption":"B","correctAnswer":"Overdrafts charge high variable interest rates and the bank can demand immediate repayment at short notice","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because overdrafts are designed for brief, temporary cash deficits; using one permanently incurs high interest and exposes the firm to sudden recall by the bank.","distractor_reasons":{"A":"Incorrect because an overdraft is short-term borrowing, not an equity stake.","B":"Option B is correct because overdrafts are designed for brief, temporary cash deficits; using one permanently incurs high interest and exposes the firm to sudden recall by the bank.","C":"Incorrect because overdrafts are meant for short-term working capital, not buying property.","D":"Incorrect because an overdrawn bank balance is a current liability."}}},{"id":"P1_U5_MCQ_137","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_137","question":"An entrepreneur applies for a $75,000 five-year bank loan to open a fitness gym, and the bank asks for collateral before approving the loan. What does the bank mean by collateral?","options":{"A":"A list of all potential gym members who have promised to join","B":"An asset such as property or equipment that the bank can sell if the borrower fails to repay the loan","C":"A guarantee from the government to pay the entrepreneur's staff wages","D":"The entrepreneur's personal university degree certificate"},"correctOption":"B","correctAnswer":"An asset such as property or equipment that the bank can sell if the borrower fails to repay the loan","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because collateral (security) is a valuable asset pledged by the borrower that the lender can seize and sell to recover its money in case of default.","distractor_reasons":{"A":"Incorrect because customer interest lists do not provide physical security for a loan.","B":"Option B is correct because collateral (security) is a valuable asset pledged by the borrower that the lender can seize and sell to recover its money in case of default.","C":"Incorrect because collateral is pledged by the borrower, not a government wage subsidy.","D":"Incorrect because academic qualifications have no resale value to cover a defaulted loan."}}},{"id":"P1_U5_MCQ_138","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_138","question":"A newly opened convenience store asks food wholesalers for 45 days of trade credit on its first stock delivery, but the wholesalers insist on cash on delivery. Why do suppliers often refuse trade credit to brand-new businesses?","options":{"A":"Trade credit is illegal for businesses trading for less than one year","B":"Wholesalers are not allowed to record trade receivables","C":"New businesses lack a proven trading history, creating a high risk that they may fail before paying","D":"Trade credit can only be used to purchase non-current assets"},"correctOption":"C","correctAnswer":"New businesses lack a proven trading history, creating a high risk that they may fail before paying","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because suppliers face a high risk of non-payment when lending goods on credit to unproven start-ups with high failure rates.","distractor_reasons":{"A":"Incorrect because there is no law banning suppliers from offering credit to new businesses.","B":"Incorrect because wholesalers routinely record trade receivables for established credit customers.","C":"Option C is correct because suppliers face a high risk of non-payment when lending goods on credit to unproven start-ups with high failure rates.","D":"Incorrect because trade credit is specifically used for purchasing raw materials and inventory."}}},{"id":"P1_U5_MCQ_139","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_139","question":"A self-employed tailor in a low-income rural community needs $350 to buy an electric sewing machine, but commercial banks refuse to lend such a small sum without property collateral. Which source of finance is specifically designed to help entrepreneurs in this situation?","options":{"A":"Issuing debentures on the stock exchange","B":"Microfinance","C":"Venture capital","D":"Sale and leaseback of factories"},"correctOption":"B","correctAnswer":"Microfinance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because microfinance institutions provide very small loans (microloans) to low-income entrepreneurs who lack traditional collateral or access to commercial banks.","distractor_reasons":{"A":"Incorrect because stock exchange issues raise millions of dollars for large public limited companies.","B":"Option B is correct because microfinance institutions provide very small loans (microloans) to low-income entrepreneurs who lack traditional collateral or access to commercial banks.","C":"Incorrect because venture capitalists invest large sums into high-growth technology or scalable companies.","D":"Incorrect because sale and leaseback applies to businesses that already own expensive property."}}},{"id":"P1_U5_MCQ_140","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_140","question":"An independent game developer uses a crowdfunding website to raise $35,000 from 1,400 backers to manufacture a new strategy board game. Aside from raising cash, what is a key benefit of crowdfunding for the developer?","options":{"A":"It tests market demand and builds an early customer base before full production begins","B":"It guarantees that no competitors can ever copy the game idea","C":"It exempts the developer from paying any taxes on future sales","D":"It provides unlimited long-term finance without needing to deliver any rewards"},"correctOption":"A","correctAnswer":"It tests market demand and builds an early customer base before full production begins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reaching a crowdfunding target proves that real customers are willing to pay for the product and generates publicity before mass production.","distractor_reasons":{"A":"Option A is correct because reaching a crowdfunding target proves that real customers are willing to pay for the product and generates publicity before mass production.","B":"Incorrect because publishing a prototype online actually exposes the concept to public view rather than preventing copying.","C":"Incorrect because crowdfunding campaigns do not grant tax exemptions.","D":"Incorrect because reward-based crowdfunding requires delivering promised products or perks to backers."}}},{"id":"P1_U5_MCQ_141","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_141","question":"A fast-growing electric bicycle start-up accepts $1.2 million from a venture capital firm in exchange for a 30% shareholding. What is a major advantage of venture capital compared with a bank loan for this start-up?","options":{"A":"The founders keep 100% ownership and never have to consult the investors","B":"Venture capitalists provide specialist business advice and contacts, and require no fixed monthly interest payments","C":"Venture capital is completely free and investors expect zero financial return","D":"Venture capital can be arranged within one hour without a business plan"},"correctOption":"B","correctAnswer":"Venture capitalists provide specialist business advice and contacts, and require no fixed monthly interest payments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because venture capitalists bring strategic mentorship and industry networks alongside risk capital that does not burden a young firm with fixed monthly loan repayments.","distractor_reasons":{"A":"Incorrect because the founders gave up 30% equity and venture capitalists usually expect board representation.","B":"Option B is correct because venture capitalists bring strategic mentorship and industry networks alongside risk capital that does not burden a young firm with fixed monthly loan repayments.","C":"Incorrect because venture capitalists expect high capital growth or dividends when they eventually sell their stake.","D":"Incorrect because venture capitalists conduct thorough due diligence on the business plan before investing."}}},{"id":"P1_U5_MCQ_142","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_142","question":"A private diagnostic clinic needs a $450,000 medical scanner, where technology advances rapidly every three to four years. Why would leasing be preferable to buying the scanner outright?","options":{"A":"Leasing transfers immediate legal ownership of the scanner to the clinic on Day 1","B":"Leasing eliminates all monthly cash outflows","C":"The clinic avoids a huge upfront cash outlay and can upgrade to newer models when the lease ends","D":"Leasing is always cheaper over 20 years than buying an asset outright"},"correctOption":"C","correctAnswer":"The clinic avoids a huge upfront cash outlay and can upgrade to newer models when the lease ends","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because leasing preserves cash flow and protects the clinic against technological obsolescence by allowing easy replacement at the end of the lease term.","distractor_reasons":{"A":"Incorrect because legal ownership remains with the leasing company throughout the lease.","B":"Incorrect because leasing requires regular monthly or quarterly rental payments.","C":"Option C is correct because leasing preserves cash flow and protects the clinic against technological obsolescence by allowing easy replacement at the end of the lease term.","D":"Incorrect because over a very long period, total lease payments usually exceed the cash purchase price."}}},{"id":"P1_U5_MCQ_143","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_143","question":"A civil engineering contractor acquires a bulldozer via hire purchase over four years instead of leasing it. How does hire purchase differ from leasing?","options":{"A":"Hire purchase requires no deposit and zero interest charges","B":"Under hire purchase, the contractor becomes the legal owner of the bulldozer once the final instalment is paid","C":"Hire purchase is an internal source of finance","D":"Hire purchase can only be used for buying raw materials and inventory"},"correctOption":"B","correctAnswer":"Under hire purchase, the contractor becomes the legal owner of the bulldozer once the final instalment is paid","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because hire purchase is an instalment purchase agreement where ownership passes to the buyer upon completion of all payments, whereas leased assets remain owned by the lessor.","distractor_reasons":{"A":"Incorrect because hire purchase usually requires an initial deposit and includes interest within the instalments.","B":"Option B is correct because hire purchase is an instalment purchase agreement where ownership passes to the buyer upon completion of all payments, whereas leased assets remain owned by the lessor.","C":"Incorrect because hire purchase is provided by an external finance company.","D":"Incorrect because hire purchase is used to buy durable non-current assets such as vehicles and machinery."}}},{"id":"P1_U5_MCQ_144","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_144","question":"A textile factory receives a $60,000 government grant to install solar panels and retrain 40 workers in green manufacturing. What condition is typically attached to such a government grant?","options":{"A":"The factory must repay the $60,000 with 12% annual interest within two years","B":"The government becomes the majority shareholder of the factory","C":"The factory must use the funds for the agreed purpose, such as meeting environmental or training targets","D":"The factory must sell all of its products exclusively to government departments"},"correctOption":"C","correctAnswer":"The factory must use the funds for the agreed purpose, such as meeting environmental or training targets","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because government grants do not have to be repaid provided the business meets specific conditions like creating jobs, training staff, or investing in green technology.","distractor_reasons":{"A":"Incorrect because grants are non-repayable financial awards unless the business breaches the grant conditions.","B":"Incorrect because grants do not give the government equity ownership in private businesses.","C":"Option C is correct because government grants do not have to be repaid provided the business meets specific conditions like creating jobs, training staff, or investing in green technology.","D":"Incorrect because grant recipients continue selling to their normal commercial customers."}}},{"id":"P1_U5_MCQ_145","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_145","question":"A food-processing company finances the $900,000 construction of a new canning factory using a short-term bank overdraft. Why is this choice of finance risky?","options":{"A":"The factory will take years to generate enough cash to repay the debt, while the bank could recall the overdraft at any time","B":"Bank overdrafts cannot be recorded in a company's accounting books","C":"Using an overdraft forces the company to pay dividends every week","D":"A factory cannot be used until all bank debts are completely repaid"},"correctOption":"A","correctAnswer":"The factory will take years to generate enough cash to repay the debt, while the bank could recall the overdraft at any time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because long-term assets like factories should be matched with long-term finance; funding one with an on-demand overdraft creates severe liquidity and interest-rate risk.","distractor_reasons":{"A":"Option A is correct because long-term assets like factories should be matched with long-term finance; funding one with an on-demand overdraft creates severe liquidity and interest-rate risk.","B":"Incorrect because overdrafts are always recorded as current liabilities.","C":"Incorrect because overdrafts incur interest, not weekly dividends.","D":"Incorrect because businesses routinely operate factories financed by long-term mortgages or loans."}}},{"id":"P1_U5_MCQ_146","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_146","question":"Why does a public limited company have access to a wider range of external finance sources than a sole trader?","options":{"A":"Sole traders are legally prohibited from opening business bank accounts","B":"Public limited companies can sell shares to the general public on a stock exchange and usually have more assets for collateral","C":"Public limited companies never have to pay interest on bank loans","D":"Sole traders are banned from using trade credit or leasing"},"correctOption":"B","correctAnswer":"Public limited companies can sell shares to the general public on a stock exchange and usually have more assets for collateral","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because legal form and business size allow public limited companies to issue shares publicly and secure large loans against substantial assets.","distractor_reasons":{"A":"Incorrect because sole traders can open business bank accounts and apply for loans or overdrafts.","B":"Option B is correct because legal form and business size allow public limited companies to issue shares publicly and secure large loans against substantial assets.","C":"Incorrect because public limited companies still pay interest on borrowed debt.","D":"Incorrect because sole traders can use both trade credit and leasing."}}},{"id":"P1_U5_MCQ_147","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_147","question":"A small bakery needs $900 urgently to repair a broken dough mixer so it can fulfill tomorrow's orders. Which factor makes a bank overdraft or personal savings far more suitable than a 5-year bank loan?","options":{"A":"The requirement to dilute shareholder ownership","B":"The bakery's status as a multinational public limited company","C":"The 15-year lifespan of the repair","D":"The small amount required and the need for immediate speed"},"correctOption":"D","correctAnswer":"The small amount required and the need for immediate speed","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because $900 is too small for formal long-term loan paperwork and is needed immediately, making an existing overdraft or owner's cash ideal.","distractor_reasons":{"A":"Incorrect because a small bakery does not want to dilute ownership for a $900 repair.","B":"Incorrect because the scenario describes a small bakery, not a multinational plc.","C":"Incorrect because a minor repair is a short-term operational expense, not a 15-year capital project.","D":"Option D is correct because $900 is too small for formal long-term loan paperwork and is needed immediately, making an existing overdraft or owner's cash ideal."}}},{"id":"P1_U5_MCQ_148","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_148","question":"A market-stall holder uses her own savings to buy a second-hand van for her business. Which source of finance is this?","options":{"A":"Internal finance (personal savings)","B":"A bank loan","C":"Trade credit","D":"Crowdfunding"},"correctOption":"A","correctAnswer":"Internal finance (personal savings)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because using the owner's own savings is internal finance, coming from within the business or its owner rather than an outside body.","distractor_reasons":{"A":"Option A is correct because using the owner's own savings is internal finance, coming from within the business or its owner rather than an outside body.","B":"Incorrect because a bank loan is borrowing from an external lender and must be repaid with interest.","C":"Incorrect because trade credit means obtaining goods now and paying the supplier later, not using personal savings.","D":"Incorrect because crowdfunding raises small amounts from many outside investors, typically through an online platform."}}},{"id":"P1_U5_MCQ_149","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_149","question":"A construction company needs $300,000 for new cranes and compares two finance options: Option 1 is retained profit, and Option 2 is a 7-year bank loan at 8% annual interest. Which factor is the finance director evaluating when comparing the 8% interest charge against zero interest?","options":{"A":"The legal form of the business","B":"The cost of finance","C":"The location of the construction site","D":"The number of employees in the firm"},"correctOption":"B","correctAnswer":"The cost of finance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because comparing interest rates, arrangement fees, and dividend expectations evaluates the cost of each source of finance.","distractor_reasons":{"A":"Incorrect because both retained profit and a bank loan are available to the company regardless of legal structure.","B":"Option B is correct because comparing interest rates, arrangement fees, and dividend expectations evaluates the cost of each source of finance.","C":"Incorrect because site location does not determine interest rate comparisons.","D":"Incorrect because workforce size is not what is being compared by the 8% interest rate."}}},{"id":"P1_U5_MCQ_150","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_150","question":"A manufacturing company raises $500,000 for factory modernisation from four sources: $180,000 from retained profit, $45,000 from selling old machinery, $200,000 from a 6-year bank loan, and $75,000 from a government grant. How much of this finance was raised from external sources?","options":{"A":"$225,000","B":"$275,000","C":"$200,000","D":"$500,000"},"correctOption":"B","correctAnswer":"$275,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because external sources come from outside the business: the bank loan ($200,000) plus the government grant ($75,000) = $275,000.","distractor_reasons":{"A":"Incorrect because $225,000 is the total from internal sources ($180,000 retained profit + $45,000 asset sale).","B":"Option B is correct because external sources come from outside the business: the bank loan ($200,000) plus the government grant ($75,000) = $275,000.","C":"Incorrect because $200,000 only counts the bank loan and omits the $75,000 government grant.","D":"Incorrect because $500,000 is the total finance raised from both internal and external sources combined."}}},{"id":"P1_U5_MCQ_151","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_151","question":"A wholesale bakery generates high sales revenue on paper, yet it is shut down by creditors because it cannot pay its flour suppliers or staff wages at the end of the month. What does this demonstrate about the importance of cash?","options":{"A":"Without sufficient cash liquidity to pay immediate bills, even a profitable business cannot survive","B":"Cash is less important than non-current assets for paying weekly wages","C":"Businesses only need cash at the end of their financial year","D":"High sales revenue automatically guarantees cash in the bank"},"correctOption":"A","correctAnswer":"Without sufficient cash liquidity to pay immediate bills, even a profitable business cannot survive","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash is required to settle immediate day-to-day obligations like wages and supplier invoices; running out of cash leads to insolvency.","distractor_reasons":{"A":"Option A is correct because cash is required to settle immediate day-to-day obligations like wages and supplier invoices; running out of cash leads to insolvency.","B":"Incorrect because workers and suppliers must be paid in cash, not with machinery or property.","C":"Incorrect because cash is required continuously every week and month to pay ongoing expenses.","D":"Incorrect because sales made on credit do not immediately provide cash."}}},{"id":"P1_U5_MCQ_152","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_152","question":"Which statement accurately describes the cash flow of a business over a trading period?","options":{"A":"The total value of all buildings and machinery owned by the business","B":"The movement of money into and out of the business over a given period of time","C":"The difference between gross profit and overhead expenses","D":"The total amount of share capital invested by founders"},"correctOption":"B","correctAnswer":"The movement of money into and out of the business over a given period of time","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cash flow refers to the actual cash inflows (receipts) entering and cash outflows (payments) leaving a business during a specific timeframe.","distractor_reasons":{"A":"Incorrect because buildings and machinery are non-current assets on the statement of financial position.","B":"Option B is correct because cash flow refers to the actual cash inflows (receipts) entering and cash outflows (payments) leaving a business during a specific timeframe.","C":"Incorrect because gross profit minus expenses equals profit, not cash flow.","D":"Incorrect because share capital is equity finance rather than ongoing cash movement."}}},{"id":"P1_U5_MCQ_153","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_153","question":"A gardening business records the following items for May: $9,000 received from cash customers, $4,500 collected from April credit clients, a $10,000 bank loan deposited into its account, and $6,000 paid for new lawnmowers. What are the total cash inflows for May?","options":{"A":"$13,500","B":"$19,000","C":"$23,500","D":"$17,500"},"correctOption":"C","correctAnswer":"$23,500","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because all money entering the bank account counts as cash inflows: $9,000 cash sales + $4,500 credit receipts + $10,000 bank loan = $23,500.","distractor_reasons":{"A":"Incorrect because $13,500 omits the $10,000 bank loan inflow.","B":"Incorrect because $19,000 omits the $4,500 collected from April credit clients.","C":"Option C is correct because all money entering the bank account counts as cash inflows: $9,000 cash sales + $4,500 credit receipts + $10,000 bank loan = $23,500.","D":"Incorrect because $17,500 subtracts the $6,000 lawnmower outflow from total inflows."}}},{"id":"P1_U5_MCQ_154","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_154","question":"During June, an engineering workshop pays $11,000 in wages, pays $3,500 in factory rent, repays $1,500 of bank loan principal, and orders $5,000 of steel on 60-day trade credit. What are the workshop's total cash outflows for June?","options":{"A":"$21,000","B":"$16,000","C":"$14,500","D":"$19,500"},"correctOption":"B","correctAnswer":"$16,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because June cash outflows include only actual payments made in June: $11,000 wages + $3,500 rent + $1,500 loan repayment = $16,000 (the steel on 60-day credit is paid in August).","distractor_reasons":{"A":"Incorrect because $21,000 wrongly includes the $5,000 steel ordered on 60-day credit.","B":"Option B is correct because June cash outflows include only actual payments made in June: $11,000 wages + $3,500 rent + $1,500 loan repayment = $16,000 (the steel on 60-day credit is paid in August).","C":"Incorrect because $14,500 omits the $1,500 loan repayment cash outflow.","D":"Incorrect because $19,500 includes the credit order and omits the loan repayment."}}},{"id":"P1_U5_MCQ_155","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_155","question":"Which item should NEVER be entered into a monthly cash flow forecast?","options":{"A":"Cash receipts from customers paying their invoices","B":"Monthly rent paid to the landlord","C":"Sales made on credit where the customer will not pay until next year","D":"Proceeds from issuing new shares for cash"},"correctOption":"C","correctAnswer":"Sales made on credit where the customer will not pay until next year","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a cash flow forecast only records actual cash inflows and outflows during the forecast period, excluding unpaid credit transactions.","distractor_reasons":{"A":"Incorrect because cash received from credit customers is a genuine cash inflow.","B":"Incorrect because rent paid is a regular cash outflow.","C":"Option C is correct because a cash flow forecast only records actual cash inflows and outflows during the forecast period, excluding unpaid credit transactions.","D":"Incorrect because cash received from issuing shares is a cash inflow."}}},{"id":"P1_U5_MCQ_156","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_156","question":"A furniture wholesaler makes total sales of $30,000 in January and $40,000 in February. Half (50%) of all sales are paid in cash immediately, and the remaining 50% are paid one month later. What is the wholesaler's total cash inflow in February?","options":{"A":"$40,000","B":"$35,000","C":"$20,000","D":"$70,000"},"correctOption":"B","correctAnswer":"$35,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because February cash inflows consist of 50% of February's sales paid immediately ($20,000) plus 50% of January's credit sales collected one month later ($15,000) = $35,000.","distractor_reasons":{"A":"Incorrect because $40,000 is total February sales revenue, half of which will not be collected until March.","B":"Option B is correct because February cash inflows consist of 50% of February's sales paid immediately ($20,000) plus 50% of January's credit sales collected one month later ($15,000) = $35,000.","C":"Incorrect because $20,000 only counts February cash sales and ignores the $15,000 collected from January credit customers.","D":"Incorrect because $70,000 adds total January and February revenue together."}}},{"id":"P1_U5_MCQ_157","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_157","question":"A clothing manufacturer buys $16,000 of fabric in March on 1-month trade credit and $22,000 of fabric in April on 1-month trade credit, while paying $9,000 in factory wages each month. What are the manufacturer's total cash outflows in April?","options":{"A":"$31,000","B":"$25,000","C":"$16,000","D":"$47,000"},"correctOption":"B","correctAnswer":"$25,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because in April the manufacturer pays for March's fabric purchase ($16,000) plus April's wages ($9,000) = $25,000 (April's $22,000 fabric purchase is paid in May).","distractor_reasons":{"A":"Incorrect because $31,000 uses April's $22,000 credit fabric purchase instead of March's $16,000 invoice due in April.","B":"Option B is correct because in April the manufacturer pays for March's fabric purchase ($16,000) plus April's wages ($9,000) = $25,000 (April's $22,000 fabric purchase is paid in May).","C":"Incorrect because $16,000 omits the $9,000 April wages outflow.","D":"Incorrect because $47,000 includes both March and April fabric purchases in April."}}},{"id":"P1_U5_MCQ_158","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_158","question":"In September, a bookstore forecasts total cash inflows of $42,600 and total cash outflows of $36,900. What is the bookstore's forecast net cash flow for September?","options":{"A":"$6,700","B":"-$5,700","C":"$79,500","D":"$5,700"},"correctOption":"D","correctAnswer":"$5,700","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Net cash flow = Cash inflows - Cash outflows ($42,600 - $36,900 = $5,700).","distractor_reasons":{"A":"Incorrect due to a subtraction error ($42,600 - $36,900 = $5,700, not $6,700).","B":"Incorrect because inflows exceed outflows, so net cash flow is positive rather than negative.","C":"Incorrect because $79,500 adds inflows and outflows together instead of subtracting outflows.","D":"Option D is correct because Net cash flow = Cash inflows - Cash outflows ($42,600 - $36,900 = $5,700)."}}},{"id":"P1_U5_MCQ_159","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_159","question":"During February, a swimming pool maintenance business expects cash inflows of $11,200 and cash outflows of $15,850. What is the forecast net cash flow for February?","options":{"A":"$4,650","B":"$27,050","C":"-$4,650","D":"-$4,450"},"correctOption":"C","correctAnswer":"-$4,650","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Net cash flow = Cash inflows - Cash outflows ($11,200 - $15,850 = -$4,650).","distractor_reasons":{"A":"Incorrect because outflows exceed inflows, making the net cash flow negative (-$4,650).","B":"Incorrect because $27,050 adds inflows and outflows together.","C":"Option C is correct because Net cash flow = Cash inflows - Cash outflows ($11,200 - $15,850 = -$4,650).","D":"Incorrect due to a subtraction error ($15,850 - $11,200 = $4,650)."}}},{"id":"P1_U5_MCQ_160","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_160","question":"A travel agency begins November with an opening cash balance of $6,400. During November, cash inflows are $21,000 and cash outflows are $25,300. What is the agency's closing cash balance at the end of November?","options":{"A":"-$4,300","B":"$10,700","C":"$2,100","D":"-$2,100"},"correctOption":"C","correctAnswer":"$2,100","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because November's net cash flow is $21,000 - $25,300 = -$4,300, and adding this to the $6,400 opening balance gives a closing balance of $2,100.","distractor_reasons":{"A":"Incorrect because -$4,300 is the net cash flow and ignores the $6,400 opening balance.","B":"Incorrect because $10,700 adds $4,300 to the opening balance instead of subtracting the deficit.","C":"Option C is correct because November's net cash flow is $21,000 - $25,300 = -$4,300, and adding this to the $6,400 opening balance gives a closing balance of $2,100.","D":"Incorrect because $6,400 - $4,300 is positive $2,100, not negative."}}},{"id":"P1_U5_MCQ_161","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_161","question":"A printing firm starts December with an overdrawn opening balance of -$3,800. During December, cash inflows are $29,000 and cash outflows are $31,200. What is the firm's closing cash balance at the end of December?","options":{"A":"-$2,200","B":"-$6,000","C":"$1,600","D":"-$1,600"},"correctOption":"B","correctAnswer":"-$6,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because December's net cash flow is $29,000 - $31,200 = -$2,200, and combining this with the -$3,800 opening overdraft yields -$6,000.","distractor_reasons":{"A":"Incorrect because -$2,200 is only December's net cash flow and omits the -$3,800 opening overdraft.","B":"Option B is correct because December's net cash flow is $29,000 - $31,200 = -$2,200, and combining this with the -$3,800 opening overdraft yields -$6,000.","C":"Incorrect because $1,600 treats the -$3,800 overdraft as a positive opening balance (+$3,800 - $2,200).","D":"Incorrect because -$3,800 + (-$2,200) deepens the overdraft to -$6,000 rather than reducing it."}}},{"id":"P1_U5_MCQ_162","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_162","question":"A café has an opening balance of $1,500 in January. In January, inflows are $12,000 and outflows are $10,500. In February, inflows are $11,000 and outflows are $13,200. What is the café's closing cash balance at the end of February?","options":{"A":"-$2,200","B":"$3,000","C":"$800","D":"-$700"},"correctOption":"C","correctAnswer":"$800","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because January closing balance = $1,500 + ($12,000 - $10,500) = $3,000, which becomes February's opening balance; February closing balance = $3,000 + ($11,000 - $13,200) = $800.","distractor_reasons":{"A":"Incorrect because -$2,200 is February's net cash flow alone.","B":"Incorrect because $3,000 is January's closing balance (February's opening balance), not February's closing balance.","C":"Option C is correct because January closing balance = $1,500 + ($12,000 - $10,500) = $3,000, which becomes February's opening balance; February closing balance = $3,000 + ($11,000 - $13,200) = $800.","D":"Incorrect because -$700 ignores January's net cash flow of +$1,500."}}},{"id":"P1_U5_MCQ_163","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_163","question":"A gift shop forecasts July cash inflows of $20,000, cash outflows of $18,500, and an opening balance of $1,000. If actual July cash inflows turn out to be 15% lower than forecast while outflows stay unchanged, what will the July closing balance be?","options":{"A":"$2,500","B":"-$500","C":"-$1,500","D":"$5,500"},"correctOption":"B","correctAnswer":"-$500","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a 15% drop reduces inflows from $20,000 to $17,000; net cash flow becomes $17,000 - $18,500 = -$1,500, and adding the $1,000 opening balance gives -$500.","distractor_reasons":{"A":"Incorrect because $2,500 is the original closing balance before the 15% fall in cash inflows.","B":"Option B is correct because a 15% drop reduces inflows from $20,000 to $17,000; net cash flow becomes $17,000 - $18,500 = -$1,500, and adding the $1,000 opening balance gives -$500.","C":"Incorrect because -$1,500 is the revised net cash flow and ignores the $1,000 opening balance.","D":"Incorrect because $5,500 adds the $3,000 variance instead of subtracting it."}}},{"id":"P1_U5_MCQ_164","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_164","question":"A restaurant normally pays its meat supplier $4,000 per month on 1-month trade credit, so in August it planned to pay July's $4,000 bill. However, the supplier suddenly demands immediate cash payment on delivery for August's $4,500 order as well. By how much will the restaurant's August cash outflows increase?","options":{"A":"$4,000","B":"$8,500","C":"$500","D":"$4,500"},"correctOption":"D","correctAnswer":"$4,500","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the restaurant must still pay July's $4,000 invoice in August AND now also pay August's $4,500 order in cash, increasing August cash outflows by $4,500.","distractor_reasons":{"A":"Incorrect because the $4,000 for July was already included in August's forecast outflows.","B":"Incorrect because $8,500 is the new total paid to the supplier in August, not the increase above the original forecast.","C":"Incorrect because the restaurant is paying both invoices in August rather than replacing one with the other.","D":"Option D is correct because the restaurant must still pay July's $4,000 invoice in August AND now also pay August's $4,500 order in cash, increasing August cash outflows by $4,500."}}},{"id":"P1_U5_MCQ_165","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_165","question":"When an entrepreneur applies for a bank loan to start a new business, why does the bank manager insist on reviewing a 12-month cash flow forecast?","options":{"A":"To verify that the business will generate enough monthly cash inflows to afford loan interest and repayments on time","B":"To calculate the exact market value of the entrepreneur's personal home","C":"To confirm that the entrepreneur has paid corporation tax for the last five years","D":"To determine how many shares the bank will own in the start-up"},"correctOption":"A","correctAnswer":"To verify that the business will generate enough monthly cash inflows to afford loan interest and repayments on time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lenders use cash flow forecasts to judge whether the new business is realistically planned and will have sufficient cash liquidity to repay the loan.","distractor_reasons":{"A":"Option A is correct because lenders use cash flow forecasts to judge whether the new business is realistically planned and will have sufficient cash liquidity to repay the loan.","B":"Incorrect because property valuations are assessed separately for collateral, not via a cash flow forecast.","C":"Incorrect because a new start-up does not have five years of past tax records.","D":"Incorrect because banks lend money for interest rather than taking share ownership."}}},{"id":"P1_U5_MCQ_166","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_166","question":"A software company's cash flow forecast reveals that its positive closing cash balance will grow steadily from $25,000 in January to $95,000 by June. How can management best use this forecast information?","options":{"A":"Arrange an emergency high-interest bank overdraft","B":"Plan to invest the surplus cash in higher-interest accounts, repay existing loans early, or fund new equipment","C":"Stop collecting payments from credit customers","D":"Delay paying staff salaries for six months"},"correctOption":"B","correctAnswer":"Plan to invest the surplus cash in higher-interest accounts, repay existing loans early, or fund new equipment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cash flow forecasts do not only spot deficits; they also highlight large cash surpluses so managers can put idle cash to productive use.","distractor_reasons":{"A":"Incorrect because a growing positive balance means no overdraft is needed.","B":"Option B is correct because cash flow forecasts do not only spot deficits; they also highlight large cash surpluses so managers can put idle cash to productive use.","C":"Incorrect because businesses should always collect money owed by customers promptly.","D":"Incorrect because withholding wages is illegal and unnecessary when cash is abundant."}}},{"id":"P1_U5_MCQ_167","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_167","question":"A manufacturing firm predicts a temporary cash shortfall of -$6,000 in April before large customer payments arrive in May. Why is arranging a short-term bank overdraft a widely used solution for this problem?","options":{"A":"It permanently increases the firm's share capital","B":"The bank never charges any interest or arrangement fees on overdrafts","C":"It quickly covers the temporary deficit without damaging supplier relationships, and interest is only paid for one month","D":"It eliminates the need to collect money from May customers"},"correctOption":"C","correctAnswer":"It quickly covers the temporary deficit without damaging supplier relationships, and interest is only paid for one month","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an overdraft bridges short-term timing gaps cleanly so bills are paid on time, and it is cleared as soon as May receipts arrive.","distractor_reasons":{"A":"Incorrect because an overdraft is temporary debt, not share capital.","B":"Incorrect because banks charge relatively high interest rates and often an arrangement fee on overdrafts.","C":"Option C is correct because an overdraft bridges short-term timing gaps cleanly so bills are paid on time, and it is cleared as soon as May receipts arrive.","D":"Incorrect because May customer receipts are needed to pay off the overdraft."}}},{"id":"P1_U5_MCQ_168","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_168","question":"To ease a cash shortage this month, an electrical contractor asks its cable suppliers for an extra 30 days to pay outstanding invoices. How does this action immediately improve the contractor's cash flow?","options":{"A":"It increases this month's cash inflows from customers","B":"It reduces or delays this month's cash outflows, keeping cash in the bank for longer","C":"It permanently cancels the debt owed to the cable suppliers","D":"It lowers the contractor's cost of sales on the statement of profit or loss"},"correctOption":"B","correctAnswer":"It reduces or delays this month's cash outflows, keeping cash in the bank for longer","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because extending trade credit postpones cash outflows into a later month, improving the current month's closing cash balance.","distractor_reasons":{"A":"Incorrect because supplier payment terms affect cash outflows, not customer inflows.","B":"Option B is correct because extending trade credit postpones cash outflows into a later month, improving the current month's closing cash balance.","C":"Incorrect because the invoice still has to be paid 30 days later.","D":"Incorrect because delaying payment does not reduce the purchase price of the cables (and may even forfeit early-payment discounts)."}}},{"id":"P1_U5_MCQ_169","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_169","question":"A wholesale distributor has $50,000 tied up in unpaid trade receivables and faces an urgent cash shortage. Instead of waiting 60 days for customers to pay, the distributor uses debt factoring, receiving 85% of the invoice value immediately from a finance company. What is the main disadvantage of this cash flow solution?","options":{"A":"The distributor receives less than the full invoice value (losing 15% as a fee), reducing its overall profit","B":"The distributor must wait an extra 60 days before receiving any cash","C":"The distributor must offer its factory building as collateral","D":"Suppliers will refuse to sell goods to the distributor"},"correctOption":"A","correctAnswer":"The distributor receives less than the full invoice value (losing 15% as a fee), reducing its overall profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because while debt factoring provides immediate cash inflows, the factor deducts a substantial fee/discount, reducing the business's revenue collected and profit.","distractor_reasons":{"A":"Option A is correct because while debt factoring provides immediate cash inflows, the factor deducts a substantial fee/discount, reducing the business's revenue collected and profit.","B":"Incorrect because debt factoring accelerates cash inflows immediately rather than delaying them.","C":"Incorrect because factoring is based on the value of unpaid customer invoices rather than property collateral.","D":"Incorrect because getting cash faster actually helps the distributor pay its suppliers on time."}}},{"id":"P1_U5_MCQ_170","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_170","question":"A printing company facing a six-month cash crunch decides to lease a new $45,000 binding machine for $950 a month instead of paying $45,000 cash upfront. How does this decision help solve its short-term cash flow problem?","options":{"A":"It spreads the cash outflows over several years instead of causing a large immediate cash drain","B":"It increases monthly cash inflows from printing customers","C":"It turns the binding machine into a current asset","D":"It makes the machine completely free over a ten-year period"},"correctOption":"A","correctAnswer":"It spreads the cash outflows over several years instead of causing a large immediate cash drain","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing replaces a large lump-sum capital cash outflow with manageable monthly rental payments.","distractor_reasons":{"A":"Option A is correct because leasing replaces a large lump-sum capital cash outflow with manageable monthly rental payments.","B":"Incorrect because leasing reduces cash outflows rather than increasing customer inflows.","C":"Incorrect because leased assets are owned by the lessor and are not current assets.","D":"Incorrect because lease rentals must be paid every month throughout the contract."}}},{"id":"P1_U5_MCQ_171","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_171","question":"A fitness centre expects a cash deficit next month. Which action would directly reduce its cash outflows in that month?","options":{"A":"Negotiating with suppliers to delay payment of bills until the following month","B":"Raising the monthly membership fee for new customers","C":"Arranging a short-term bank overdraft","D":"Selling unused gym equipment for cash"},"correctOption":"A","correctAnswer":"Negotiating with suppliers to delay payment of bills until the following month","questionType":"MCQ","explanation":{"correct_reason":"Delaying supplier payments postpones cash leaving the business, so it lowers cash outflows in the deficit month.","distractor_reasons":{"A":"Correct: paying suppliers later keeps cash in the business during the deficit month.","B":"Higher fees affect cash inflows from customers, not the outflows the centre needs to cut.","C":"An overdraft brings extra borrowed cash into the business; it does not reduce spending.","D":"Selling equipment is a one-off cash inflow from asset disposal, not a reduction in outflows."}}},{"id":"P1_U5_MCQ_172","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_172","question":"During its first year, an architectural firm records $240,000 in completed client fee revenue and $150,000 in expenses, giving a profit of $90,000, yet its bank balance falls by -$35,000. Which combination of factors best explains how the firm is profitable yet cash-negative?","options":{"A":"Expenses were paid on 12-month credit so no cash left the bank","B":"All clients paid in cash on Day 1 and the firm had zero equipment purchases","C":"The firm received a $100,000 cash grant that was excluded from profit","D":"Clients were given 90 days to pay their invoices and the firm bought $60,000 of computer equipment for cash"},"correctOption":"D","correctAnswer":"Clients were given 90 days to pay their invoices and the firm bought $60,000 of computer equipment for cash","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because credit revenue is counted in profit before cash arrives, while cash spent on non-current computer equipment reduces cash without being deducted in full from profit.","distractor_reasons":{"A":"Incorrect because delaying cash outflows would keep the bank balance positive.","B":"Incorrect because immediate cash receipts and no capital spending would result in a strongly positive cash balance.","C":"Incorrect because receiving a $100,000 cash grant would increase the bank balance rather than reducing it.","D":"Option D is correct because credit revenue is counted in profit before cash arrives, while cash spent on non-current computer equipment reduces cash without being deducted in full from profit."}}},{"id":"P1_U5_MCQ_173","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_173","question":"A struggling retail chain makes an annual loss of -$45,000, yet its net cash flow for the year is +$30,000. Which transaction explains how a loss-making business can generate positive net cash flow?","options":{"A":"The chain sold two unused delivery trucks for $85,000 cash","B":"The chain paid all its suppliers 60 days early","C":"The chain allowed customers to take six months to pay for goods","D":"The chain bought $90,000 of new display shelves for cash"},"correctOption":"A","correctAnswer":"The chain sold two unused delivery trucks for $85,000 cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because selling non-current assets generates a large cash inflow ($85,000) that boosts cash balances even when normal trading makes a loss.","distractor_reasons":{"A":"Option A is correct because selling non-current assets generates a large cash inflow ($85,000) that boosts cash balances even when normal trading makes a loss.","B":"Incorrect because paying suppliers early accelerates cash outflows and reduces cash.","C":"Incorrect because giving customers six months to pay delays cash inflows.","D":"Incorrect because buying shelves for cash creates a large cash outflow."}}},{"id":"P1_U5_MCQ_174","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_174","question":"A small biscuit manufacturer wins a contract to supply a national supermarket chain, doubling its production volume overnight, but runs out of cash two months later despite strong profit margins. What caused this 'overtrading' cash flow crisis?","options":{"A":"The manufacturer's profit margin became negative when output doubled","B":"Supermarkets are legally prohibited from paying for biscuits","C":"Doubling output automatically reduced the manufacturer's revenue to zero","D":"The manufacturer had to pay cash immediately for extra flour, packaging, and overtime wages long before the supermarket paid its 60-day invoices"},"correctOption":"D","correctAnswer":"The manufacturer had to pay cash immediately for extra flour, packaging, and overtime wages long before the supermarket paid its 60-day invoices","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because expanding output rapidly requires immediate working capital outflows for materials and labour before cash inflows from new credit sales arrive.","distractor_reasons":{"A":"Incorrect because the scenario states the manufacturer had strong profit margins.","B":"Incorrect because supermarkets pay invoices after the agreed credit period.","C":"Incorrect because doubling output doubled sales revenue, even though cash collection was delayed.","D":"Option D is correct because expanding output rapidly requires immediate working capital outflows for materials and labour before cash inflows from new credit sales arrive."}}},{"id":"P1_U5_MCQ_175","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_175","question":"A new café owner prepares a cash flow forecast assuming 150 customers per day, but a rival coffee chain opens next door in Month 3, cutting daily customers to 80. What limitation of cash flow forecasts does this illustrate?","options":{"A":"Cash flow forecasts ignore all cash payments to suppliers","B":"Cash flow forecasts are only allowed to include fixed costs","C":"A cash flow forecast legally prevents a business from changing its prices","D":"Forecasts are based on estimates and assumptions that can be invalidated by unexpected changes in competition or market conditions"},"correctOption":"D","correctAnswer":"Forecasts are based on estimates and assumptions that can be invalidated by unexpected changes in competition or market conditions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because forecasts rely on predictions of future sales and costs; sudden external events like a new competitor make the original numbers inaccurate unless updated.","distractor_reasons":{"A":"Incorrect because supplier payments are included as cash outflows.","B":"Incorrect because forecasts include both fixed and variable cash outflows.","C":"Incorrect because a forecast is a planning tool, not a legal restriction on pricing.","D":"Option D is correct because forecasts rely on predictions of future sales and costs; sudden external events like a new competitor make the original numbers inaccurate unless updated."}}},{"id":"P1_U5_MCQ_176","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_176","question":"Over a 12-month financial year, a local cinema earns $410,000 from ticket and snack sales while incurring total costs of $435,000. Which financial outcome has the cinema experienced?","options":{"A":"A profit of $25,000","B":"A loss of $25,000","C":"A gross profit of $410,000","D":"A positive net cash flow of $25,000"},"correctOption":"B","correctAnswer":"A loss of $25,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when total costs ($435,000) exceed total revenue ($410,000), the business makes a loss ($410,000 - $435,000 = -$25,000).","distractor_reasons":{"A":"Incorrect because costs are higher than revenue, resulting in a loss rather than a profit.","B":"Option B is correct because when total costs ($435,000) exceed total revenue ($410,000), the business makes a loss ($410,000 - $435,000 = -$25,000).","C":"Incorrect because $410,000 is total revenue before deducting cost of sales.","D":"Incorrect because revenue minus costs measures profit/loss, not net cash flow."}}},{"id":"P1_U5_MCQ_177","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_177","question":"Why is making a profit essential for the long-term survival of a private sector business?","options":{"A":"Without profit, owners have no reward for risking their capital and the business lacks internal funds to reinvest or survive downturns","B":"Profit is the only item recorded on a statement of financial position","C":"Private sector businesses are fined by the government every month they do not make a profit","D":"Profit guarantees that the business will never face competition"},"correctOption":"A","correctAnswer":"Without profit, owners have no reward for risking their capital and the business lacks internal funds to reinvest or survive downturns","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit rewards entrepreneurs for risk-taking and provides retained profit to finance growth and cushion against tough trading periods.","distractor_reasons":{"A":"Option A is correct because profit rewards entrepreneurs for risk-taking and provides retained profit to finance growth and cushion against tough trading periods.","B":"Incorrect because the statement of financial position lists assets, liabilities, and equity.","C":"Incorrect because governments do not fine businesses for making a loss (in fact, loss-making firms pay no corporation tax).","D":"Incorrect because high profits often attract new competitors into an industry."}}},{"id":"P1_U5_MCQ_178","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_178","question":"A medium-sized packaging company plans to automate its production line over the next five years without taking on heavy bank debt. How does making consistent profits enable this strategy?","options":{"A":"Profit automatically reduces the purchase price of machinery by 50%","B":"Retained profit can be accumulated as an interest-free internal source of finance to buy the automated machinery","C":"Profit increases the company's trade payables","D":"Profit allows the company to stop paying utility bills"},"correctOption":"B","correctAnswer":"Retained profit can be accumulated as an interest-free internal source of finance to buy the automated machinery","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retained profit is one of the cheapest and safest sources of finance for funding long-term capital investment.","distractor_reasons":{"A":"Incorrect because machinery suppliers charge the same price regardless of the buyer's profit.","B":"Option B is correct because retained profit is one of the cheapest and safest sources of finance for funding long-term capital investment.","C":"Incorrect because retained profit increases equity, not short-term supplier debts.","D":"Incorrect because profitable businesses still have to pay all operating expenses."}}},{"id":"P1_U5_MCQ_179","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_179","question":"A start-up software firm is deciding between two mobile app concepts: App X is expected to generate $80,000 in annual profit, while App Y is expected to generate $35,000. How is profit being used by the management team here?","options":{"A":"As a measure of short-term bank liquidity","B":"As a criterion for comparing options and deciding which project offers the best financial return","C":"As a way to calculate the firm's acid-test ratio","D":"As a method for valuing non-current liabilities"},"correctOption":"B","correctAnswer":"As a criterion for comparing options and deciding which project offers the best financial return","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because expected profit serves as a key benchmark for managers when comparing investment projects and allocating resources.","distractor_reasons":{"A":"Incorrect because liquidity measures cash availability, not projected project profit.","B":"Option B is correct because expected profit serves as a key benchmark for managers when comparing investment projects and allocating resources.","C":"Incorrect because the acid-test ratio uses current assets, inventory, and current liabilities.","D":"Incorrect because projected profit does not value long-term liabilities."}}},{"id":"P1_U5_MCQ_180","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_180","question":"A community-owned bakery operates as a social enterprise, training unemployed young people while selling artisan bread. Why does this social enterprise still aim to make a profit?","options":{"A":"To maximise cash dividends for wealthy stock exchange investors","B":"To avoid having to pay its bakers any wages","C":"To remain financially self-sustaining and reinvest surpluses into training more young people","D":"Because social enterprises are legally required to pay 90% of profit to banks"},"correctOption":"C","correctAnswer":"To remain financially self-sustaining and reinvest surpluses into training more young people","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social enterprises need profit to survive without relying solely on donations and to reinvest in expanding their social mission.","distractor_reasons":{"A":"Incorrect because social enterprises prioritise social/environmental objectives over private shareholder dividends.","B":"Incorrect because social enterprises pay fair wages to their employees.","C":"Option C is correct because social enterprises need profit to survive without relying solely on donations and to reinvest in expanding their social mission.","D":"Incorrect because there is no law requiring social enterprises to pay 90% of profits to banks."}}},{"id":"P1_U5_MCQ_181","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_181","question":"Why is 'profit' on a statement of profit or loss rarely equal to the 'closing cash balance' on a cash flow statement for the same year?","options":{"A":"Because profit is only calculated for cash sales","B":"Because accountants are allowed to guess revenue figures on the statement of profit or loss","C":"Because cash flow statements never include wages or rent","D":"Because credit sales are included in revenue before cash is received, and cash inflows like loans or outflows like asset purchases are excluded from profit"},"correctOption":"D","correctAnswer":"Because credit sales are included in revenue before cash is received, and cash inflows like loans or outflows like asset purchases are excluded from profit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit follows accrual accounting (matching revenue earned with costs incurred), whereas cash flow tracks actual money entering and leaving the bank.","distractor_reasons":{"A":"Incorrect because profit includes both cash and credit sales.","B":"Incorrect because revenue must be accurately recorded from invoices and sales records.","C":"Incorrect because wages and rent paid are major cash outflows on a cash flow statement.","D":"Option D is correct because profit follows accrual accounting (matching revenue earned with costs incurred), whereas cash flow tracks actual money entering and leaving the bank."}}},{"id":"P1_U5_MCQ_182","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_182","question":"During the financial year, a bicycle manufacturer sells 1,200 mountain bikes at $450 each and 800 road bikes at $600 each. What is the manufacturer's total revenue for the year?","options":{"A":"$540,000","B":"$480,000","C":"$1,020,000","D":"$2,000"},"correctOption":"C","correctAnswer":"$1,020,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total revenue = (1,200 × $450) + (800 × $600) = $540,000 + $480,000 = $1,020,000.","distractor_reasons":{"A":"Incorrect because $540,000 only counts revenue from mountain bikes.","B":"Incorrect because $480,000 only counts revenue from road bikes.","C":"Option C is correct because total revenue = (1,200 × $450) + (800 × $600) = $540,000 + $480,000 = $1,020,000.","D":"Incorrect because 2,000 is the total number of bicycles sold, not the dollar revenue."}}},{"id":"P1_U5_MCQ_183","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_183","question":"A shoe manufacturer is preparing its statement of profit or loss. Which item should be included in 'cost of sales'?","options":{"A":"Interest paid on a long-term bank mortgage","B":"Salaries of the human resources and accounting departments","C":"Leather, rubber soles, and wages of factory machine operators making the shoes","D":"Rent paid for the head office building"},"correctOption":"C","correctAnswer":"Leather, rubber soles, and wages of factory machine operators making the shoes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cost of sales comprises the direct materials and direct production labour costs involved in making the goods sold.","distractor_reasons":{"A":"Incorrect because loan interest is a finance expense deducted after gross profit.","B":"Incorrect because HR and accounting salaries are indirect administrative expenses.","C":"Option C is correct because cost of sales comprises the direct materials and direct production labour costs involved in making the goods sold.","D":"Incorrect because head office rent is an indirect overhead expense."}}},{"id":"P1_U5_MCQ_184","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_184","question":"A sporting goods retailer records annual revenue of $720,000, cost of sales of $430,000, and overhead expenses of $195,000. What is the retailer's gross profit?","options":{"A":"$95,000","B":"$290,000","C":"$525,000","D":"$235,000"},"correctOption":"B","correctAnswer":"$290,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Gross profit = Revenue - Cost of sales ($720,000 - $430,000 = $290,000).","distractor_reasons":{"A":"Incorrect because $95,000 is the final profit after deducting both cost of sales and $195,000 of overhead expenses.","B":"Option B is correct because Gross profit = Revenue - Cost of sales ($720,000 - $430,000 = $290,000).","C":"Incorrect because $525,000 subtracts expenses from revenue instead of cost of sales.","D":"Incorrect because $235,000 subtracts expenses from cost of sales ($430,000 - $195,000)."}}},{"id":"P1_U5_MCQ_185","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_185","question":"Which group of costs consists solely of indirect 'expenses' (overheads) deducted from gross profit on a statement of profit or loss?","options":{"A":"Direct raw materials, packaging for products, and piece-rate factory wages","B":"Office electricity, delivery van insurance, and marketing salaries","C":"Wholesale purchase price of goods bought for resale","D":"Revenue from online sales and cash register sales"},"correctOption":"B","correctAnswer":"Office electricity, delivery van insurance, and marketing salaries","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because office electricity, vehicle insurance, and marketing salaries are indirect running expenses deducted from gross profit to calculate profit.","distractor_reasons":{"A":"Incorrect because direct raw materials, product packaging, and piece-rate production wages are direct costs included in cost of sales.","B":"Option B is correct because office electricity, vehicle insurance, and marketing salaries are indirect running expenses deducted from gross profit to calculate profit.","C":"Incorrect because goods bought for resale form part of cost of sales.","D":"Incorrect because sales figures represent revenue, not expenses."}}},{"id":"P1_U5_MCQ_186","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_186","question":"A florist shop has annual revenue of $210,000, cost of sales of $88,000, and overhead expenses of $74,000. What is the shop's profit for the year?","options":{"A":"$122,000","B":"$136,000","C":"$48,000","D":"$162,000"},"correctOption":"C","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = $210,000 - $88,000 = $122,000, and Profit = Gross profit - Expenses ($122,000 - $74,000 = $48,000).","distractor_reasons":{"A":"Incorrect because $122,000 is the gross profit before deducting $74,000 of overhead expenses.","B":"Incorrect because $136,000 deducts only expenses from revenue and ignores cost of sales.","C":"Option C is correct because Gross profit = $210,000 - $88,000 = $122,000, and Profit = Gross profit - Expenses ($122,000 - $74,000 = $48,000).","D":"Incorrect because $162,000 adds cost of sales and expenses together ($88,000 + $74,000)."}}},{"id":"P1_U5_MCQ_187","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_187","question":"A limited company earns a profit before tax of $200,000. Corporation tax is $40,000, and the directors pay $55,000 in dividends to shareholders. How much retained profit is added to the company's equity?","options":{"A":"$160,000","B":"$145,000","C":"$105,000","D":"$95,000"},"correctOption":"C","correctAnswer":"$105,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Profit after tax = $200,000 - $40,000 = $160,000, and Retained profit = Profit after tax - Dividends ($160,000 - $55,000 = $105,000).","distractor_reasons":{"A":"Incorrect because $160,000 is profit after tax before subtracting the $55,000 dividend payout.","B":"Incorrect because $145,000 subtracts dividends ($55,000) from profit before tax and forgets the $40,000 tax.","C":"Option C is correct because Profit after tax = $200,000 - $40,000 = $160,000, and Retained profit = Profit after tax - Dividends ($160,000 - $55,000 = $105,000).","D":"Incorrect because $95,000 is the sum of tax and dividends paid out ($40,000 + $55,000)."}}},{"id":"P1_U5_MCQ_188","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_188","question":"An extract from a bakery's statement of profit or loss shows cost of sales of $135,000, gross profit of $195,000, and overhead expenses of $110,000. What was the bakery's total revenue?","options":{"A":"$440,000","B":"$60,000","C":"$85,000","D":"$330,000"},"correctOption":"D","correctAnswer":"$330,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Gross profit = Revenue - Cost of sales, so Revenue = Gross profit + Cost of sales ($195,000 + $135,000 = $330,000).","distractor_reasons":{"A":"Incorrect because $440,000 adds overhead expenses to revenue ($330,000 + $110,000).","B":"Incorrect because $60,000 subtracts cost of sales from gross profit instead of adding them.","C":"Incorrect because $85,000 is the final profit ($195,000 gross profit - $110,000 expenses).","D":"Option D is correct because Gross profit = Revenue - Cost of sales, so Revenue = Gross profit + Cost of sales ($195,000 + $135,000 = $330,000)."}}},{"id":"P1_U5_MCQ_189","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_189","question":"A hardware store reports annual revenue of $450,000, overhead expenses of $95,000, and a final profit of $65,000. What was the store's cost of sales?","options":{"A":"$160,000","B":"$290,000","C":"$385,000","D":"$355,000"},"correctOption":"B","correctAnswer":"$290,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Gross profit = Profit + Expenses ($65,000 + $95,000 = $160,000), and Cost of sales = Revenue - Gross profit ($450,000 - $160,000 = $290,000).","distractor_reasons":{"A":"Incorrect because $160,000 is the gross profit, not the cost of sales.","B":"Option B is correct because Gross profit = Profit + Expenses ($65,000 + $95,000 = $160,000), and Cost of sales = Revenue - Gross profit ($450,000 - $160,000 = $290,000).","C":"Incorrect because $385,000 subtracts only final profit from revenue ($450,000 - $65,000), failing to remove overhead expenses.","D":"Incorrect because $355,000 subtracts only overhead expenses from revenue ($450,000 - $95,000)."}}},{"id":"P1_U5_MCQ_190","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_190","question":"A steel tariff raises the cost of sheet metal for a washing-machine manufacturer by $35,000, while the manufacturer's sales revenue and overhead expenses remain unchanged. How does this tariff affect the statement of profit or loss?","options":{"A":"Revenue increases by $35,000 and gross profit stays unchanged","B":"Gross profit stays unchanged, while final profit falls by $35,000","C":"Gross profit falls by $35,000 and final profit also falls by $35,000","D":"Cost of sales falls by $35,000 and gross profit rises by $35,000"},"correctOption":"C","correctAnswer":"Gross profit falls by $35,000 and final profit also falls by $35,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sheet metal is a direct raw material in cost of sales; raising cost of sales by $35,000 lowers gross profit by $35,000 and flows through to lower final profit by $35,000.","distractor_reasons":{"A":"Incorrect because higher material costs do not automatically increase sales revenue.","B":"Incorrect because sheet metal is part of cost of sales rather than an indirect overhead expense, so gross profit decreases.","C":"Option C is correct because sheet metal is a direct raw material in cost of sales; raising cost of sales by $35,000 lowers gross profit by $35,000 and flows through to lower final profit by $35,000.","D":"Incorrect because a tariff increases the cost of sheet metal rather than reducing it."}}},{"id":"P1_U5_MCQ_191","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_191","question":"An accounting firm's landlord increases annual office rent by $18,000, while client fee revenue and direct costs remain unchanged. What is the effect on the firm's statement of profit or loss?","options":{"A":"Gross profit falls by $18,000 and profit falls by $18,000","B":"Gross profit is unchanged, while overhead expenses rise by $18,000 and profit falls by $18,000","C":"Cost of sales rises by $18,000 and profit stays unchanged","D":"Both gross profit and profit increase by $18,000"},"correctOption":"B","correctAnswer":"Gross profit is unchanged, while overhead expenses rise by $18,000 and profit falls by $18,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because office rent is an indirect overhead expense deducted after gross profit; gross profit is unaffected, but final profit drops by $18,000.","distractor_reasons":{"A":"Incorrect because office rent is not part of cost of sales, so gross profit does not change.","B":"Option B is correct because office rent is an indirect overhead expense deducted after gross profit; gross profit is unaffected, but final profit drops by $18,000.","C":"Incorrect because higher rent increases expenses and reduces final profit.","D":"Incorrect because higher rent is a cost increase, not a gain."}}},{"id":"P1_U5_MCQ_192","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_192","question":"A chocolate manufacturer wants to increase its profit by 15% next year by increasing its revenue. Which strategy aims to increase revenue without raising selling prices?","options":{"A":"Selling off an unused storage warehouse","B":"Switching to cheaper cocoa beans from a new supplier","C":"Reducing head-office administrative staff numbers","D":"Launching a targeted advertising campaign and selling through new online retail channels to boost sales volume"},"correctOption":"D","correctAnswer":"Launching a targeted advertising campaign and selling through new online retail channels to boost sales volume","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because revenue equals price multiplied by quantity sold; expanding distribution and promotion increases sales volume and revenue at existing prices.","distractor_reasons":{"A":"Incorrect because selling a warehouse is a one-off asset disposal, not sales revenue.","B":"Incorrect because cheaper cocoa beans reduce cost of sales rather than increasing revenue.","C":"Incorrect because cutting office staff reduces overhead expenses rather than increasing revenue.","D":"Option D is correct because revenue equals price multiplied by quantity sold; expanding distribution and promotion increases sales volume and revenue at existing prices."}}},{"id":"P1_U5_MCQ_193","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_193","question":"A clothing retailer spends $25,000 on an influencer marketing campaign that boosts revenue by $60,000, with associated cost of sales of $20,000. How does this campaign affect the retailer's profit?","options":{"A":"Profit increases by $60,000","B":"Profit decreases by $25,000","C":"Profit increases by $15,000","D":"Profit increases by $40,000"},"correctOption":"C","correctAnswer":"Profit increases by $15,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extra gross profit is $60,000 revenue - $20,000 cost of sales = $40,000, and subtracting the $25,000 marketing expense gives a net profit gain of $15,000.","distractor_reasons":{"A":"Incorrect because $60,000 is the extra revenue before deducting cost of sales and marketing expenses.","B":"Incorrect because the extra gross profit ($40,000) exceeds the $25,000 marketing cost.","C":"Option C is correct because extra gross profit is $60,000 revenue - $20,000 cost of sales = $40,000, and subtracting the $25,000 marketing expense gives a net profit gain of $15,000.","D":"Incorrect because $40,000 is the extra gross profit before deducting the $25,000 marketing expense."}}},{"id":"P1_U5_MCQ_194","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_194","question":"To reduce its cost of sales, a smartphone maker replaces a reliable precision-lens supplier with a much cheaper, untested supplier. What is the main danger of this cost-cutting approach?","options":{"A":"Faulty lenses may increase product returns and damage brand reputation, causing future sales and profit to fall","B":"Lower lens prices will immediately increase the smartphone maker's overhead expenses","C":"Cost of sales will increase because cheaper components cost more","D":"Gross profit will fall immediately even if sales stay constant"},"correctOption":"A","correctAnswer":"Faulty lenses may increase product returns and damage brand reputation, causing future sales and profit to fall","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting direct material costs by sacrificing component quality often leads to defects, warranty claims, and lost customer trust.","distractor_reasons":{"A":"Option A is correct because cutting direct material costs by sacrificing component quality often leads to defects, warranty claims, and lost customer trust.","B":"Incorrect because component prices affect cost of sales rather than indirect overheads.","C":"Incorrect because cheaper lenses lower direct cost per unit in the short term.","D":"Incorrect because if sales stay constant and unit costs fall, gross profit rises initially before quality issues emerge."}}},{"id":"P1_U5_MCQ_195","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_195","question":"A nationwide insurance company reduces its indirect expenses by moving customer-service teams from expensive city-centre offices to smaller regional hubs and allowing remote work. How does this decision affect its statement of profit or loss?","options":{"A":"It lowers overhead expenses, increasing final profit while leaving gross profit unchanged","B":"It increases cost of sales and lowers gross profit","C":"It increases revenue and decreases retained profit","D":"It eliminates the need to pay corporation tax on profits"},"correctOption":"A","correctAnswer":"It lowers overhead expenses, increasing final profit while leaving gross profit unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because office rent and facility bills are overhead expenses deducted below gross profit; cutting them raises profit without altering gross profit.","distractor_reasons":{"A":"Option A is correct because office rent and facility bills are overhead expenses deducted below gross profit; cutting them raises profit without altering gross profit.","B":"Incorrect because office rent is an indirect expense, not cost of sales.","C":"Incorrect because cutting rent expenses raises profit and potential retained profit rather than reducing them.","D":"Incorrect because higher profit actually increases corporation tax obligations."}}},{"id":"P1_U5_MCQ_196","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_196","question":"Reviewing its statement of profit or loss, a restaurant group finds that its City Branch generated $500,000 in revenue with $380,000 in cost of sales and $140,000 in expenses, resulting in a loss of -$20,000. Before deciding to close the City Branch, what should senior managers consider?","options":{"A":"Whether the City Branch contributes towards shared head-office fixed costs and whether cost controls or menu changes could restore it to profit","B":"Closing any branch that makes a small loss is always mandatory by law","C":"A loss-making branch always has a positive cash flow that cannot be replaced","D":"Closing the branch will automatically increase revenue at all other branches by 100%"},"correctOption":"A","correctAnswer":"Whether the City Branch contributes towards shared head-office fixed costs and whether cost controls or menu changes could restore it to profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers use profit statements alongside strategic judgement: the branch earns a positive gross profit ($120,000) that helps cover shared overheads and might be turned around.","distractor_reasons":{"A":"Option A is correct because managers use profit statements alongside strategic judgement: the branch earns a positive gross profit ($120,000) that helps cover shared overheads and might be turned around.","B":"Incorrect because businesses often keep temporarily unprofitable branches open while restructuring them.","C":"Incorrect because a loss-making branch does not automatically generate positive cash flow.","D":"Incorrect because closing a branch usually loses local customers rather than doubling sales elsewhere."}}},{"id":"P1_U5_MCQ_197","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_197","question":"Between Year 1 and Year 2, a bicycle shop's revenue stayed constant at $300,000, its gross profit fell from $120,000 to $90,000, and its overhead expenses remained constant at $70,000. What caused the shop's final profit to fall from $50,000 to $20,000?","options":{"A":"Cost of sales increased by $30,000","B":"Overhead expenses increased by $30,000","C":"Sales revenue fell by $30,000","D":"Dividend payments increased by $30,000"},"correctOption":"A","correctAnswer":"Cost of sales increased by $30,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because revenue stayed at $300,000 while gross profit dropped by $30,000 ($120,000 to $90,000), meaning cost of sales must have risen from $180,000 to $210,000.","distractor_reasons":{"A":"Option A is correct because revenue stayed at $300,000 while gross profit dropped by $30,000 ($120,000 to $90,000), meaning cost of sales must have risen from $180,000 to $210,000.","B":"Incorrect because the question states overhead expenses remained constant at $70,000.","C":"Incorrect because revenue remained constant at $300,000.","D":"Incorrect because dividends are distributed out of profit after tax rather than deducted before profit."}}},{"id":"P1_U5_MCQ_198","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_198","question":"A luxury watch retailer achieves a very high gross profit of $600,000 on $1,000,000 of revenue, yet its final profit is a loss of -$50,000. How can a business earn a large gross profit and still make an overall loss?","options":{"A":"Its cost of sales was higher than its $1,000,000 revenue","B":"Its indirect overhead expenses (such as flagship store rent and marketing) exceeded its $600,000 gross profit","C":"Its current assets were lower than its current liabilities","D":"It paid too much corporation tax before calculating gross profit"},"correctOption":"B","correctAnswer":"Its indirect overhead expenses (such as flagship store rent and marketing) exceeded its $600,000 gross profit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Profit = Gross profit - Expenses; if indirect expenses total $650,000, a $600,000 gross profit becomes a -$50,000 loss.","distractor_reasons":{"A":"Incorrect because gross profit was +$600,000, proving cost of sales was $400,000 (less than revenue).","B":"Option B is correct because Profit = Gross profit - Expenses; if indirect expenses total $650,000, a $600,000 gross profit becomes a -$50,000 loss.","C":"Incorrect because liquidity ratios on the statement of financial position do not determine trading loss.","D":"Incorrect because corporation tax is only charged when a business makes a positive profit."}}},{"id":"P1_U5_MCQ_199","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_199","question":"When reviewing a supplier's statement of profit or loss, why should a business NOT rely solely on the profit figure to judge whether the supplier is financially safe?","options":{"A":"Because a business with high reported profit can still face a severe cash shortage and go bankrupt if customers fail to pay","B":"Because the statement of profit or loss never includes sales revenue","C":"Because profit figures are legally allowed to be invented by directors","D":"Because cost of sales is always excluded from profit calculations"},"correctOption":"A","correctAnswer":"Because a business with high reported profit can still face a severe cash shortage and go bankrupt if customers fail to pay","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the statement of profit or loss measures profitability rather than cash liquidity; a profitable supplier can still collapse from poor cash flow.","distractor_reasons":{"A":"Option A is correct because the statement of profit or loss measures profitability rather than cash liquidity; a profitable supplier can still collapse from poor cash flow.","B":"Incorrect because sales revenue is the very first line of the statement of profit or loss.","C":"Incorrect because directors are legally required to present true and fair accounts.","D":"Incorrect because cost of sales is always deducted from revenue to find gross profit."}}},{"id":"P1_U5_MCQ_200","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_200","question":"A public limited company's statement of profit or loss shows revenue of $2.4m, cost of sales of $1.5m, expenses of $500,000, tax of $80,000, and dividends of $120,000. What is the company's retained profit for the year?","options":{"A":"$400,000","B":"$320,000","C":"$200,000","D":"$900,000"},"correctOption":"C","correctAnswer":"$200,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = $2.4m - $1.5m = $900,000; Profit before tax = $900,000 - $500,000 = $400,000; Profit after tax = $400,000 - $80,000 = $320,000; Retained profit = $320,000 - $120,000 = $200,000.","distractor_reasons":{"A":"Incorrect because $400,000 is profit before tax and dividends.","B":"Incorrect because $320,000 is profit after tax before deducting the $120,000 dividend payout.","C":"Option C is correct because Gross profit = $2.4m - $1.5m = $900,000; Profit before tax = $900,000 - $500,000 = $400,000; Profit after tax = $400,000 - $80,000 = $320,000; Retained profit = $320,000 - $120,000 = $200,000.","D":"Incorrect because $900,000 is the gross profit."}}},{"id":"P1_U5_MCQ_201","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_201","question":"Which financial statement acts like a photograph of a business's financial health at one exact date, showing everything it owns, everything it owes, and the owners' stake?","options":{"A":"Monthly cash flow forecast","B":"Statement of profit or loss","C":"Statement of financial position","D":"Break-even chart"},"correctOption":"C","correctAnswer":"Statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the statement of financial position records assets, liabilities, and equity at a specific point in time.","distractor_reasons":{"A":"Incorrect because a cash flow forecast estimates future monthly cash inflows and outflows.","B":"Incorrect because the statement of profit or loss records trading revenue, costs, and profit over an entire accounting period.","C":"Option C is correct because the statement of financial position records assets, liabilities, and equity at a specific point in time.","D":"Incorrect because a break-even chart shows costs, revenue, and break-even output levels."}}},{"id":"P1_U5_MCQ_202","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_202","question":"An airline owns passenger aircraft, airport hangar buildings, spare jet engines held in storage for maintenance, and cash in its bank accounts. Which items are classified as non-current assets?","options":{"A":"Airport hangar buildings and unpaid fuel supplier invoices","B":"Cash in bank accounts and unpaid ticket receivables","C":"Passenger aircraft and bank overdrafts","D":"Passenger aircraft and airport hangar buildings"},"correctOption":"D","correctAnswer":"Passenger aircraft and airport hangar buildings","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because passenger aircraft and hangar buildings are long-term physical resources owned and used by the airline for more than one year.","distractor_reasons":{"A":"Incorrect because unpaid fuel supplier invoices are trade payables (current liabilities).","B":"Incorrect because cash and trade receivables are short-term current assets.","C":"Incorrect because bank overdrafts are current liabilities.","D":"Option D is correct because passenger aircraft and hangar buildings are long-term physical resources owned and used by the airline for more than one year."}}},{"id":"P1_U5_MCQ_203","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_203","question":"Why are inventory, trade receivables, and cash grouped together as 'current assets' on a statement of financial position?","options":{"A":"Because they are owned permanently and will never be sold or used up","B":"Because they are held for less than one year and are expected to be converted into cash during normal trading","C":"Because they represent debts that the business must repay to suppliers within 30 days","D":"Because they are excluded when calculating a business's total assets"},"correctOption":"B","correctAnswer":"Because they are held for less than one year and are expected to be converted into cash during normal trading","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because current assets are short-term resources that circulate continuously within a 12-month trading cycle into cash.","distractor_reasons":{"A":"Incorrect because permanent long-term resources are non-current assets.","B":"Option B is correct because current assets are short-term resources that circulate continuously within a 12-month trading cycle into cash.","C":"Incorrect because debts owed to suppliers within 30 days are current liabilities (trade payables).","D":"Incorrect because total assets equal non-current assets plus current assets."}}},{"id":"P1_U5_MCQ_204","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_204","question":"When listing current assets in order of increasing liquidity (from hardest to turn into cash quickly to easiest), which sequence is correct?","options":{"A":"Cash → Trade receivables → Inventory","B":"Trade receivables → Cash → Inventory","C":"Inventory → Trade receivables → Cash","D":"Inventory → Cash → Trade receivables"},"correctOption":"C","correctAnswer":"Inventory → Trade receivables → Cash","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because inventory must first be sold to create a trade receivable, which must then be collected to become cash—making cash the most liquid asset.","distractor_reasons":{"A":"Incorrect because this lists current assets from most liquid to least liquid.","B":"Incorrect because cash is more liquid than both trade receivables and inventory.","C":"Option C is correct because inventory must first be sold to create a trade receivable, which must then be collected to become cash—making cash the most liquid asset.","D":"Incorrect because cash is already liquid money, whereas trade receivables still await customer payment."}}},{"id":"P1_U5_MCQ_205","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_205","question":"Which list contains ONLY current liabilities on a company's statement of financial position?","options":{"A":"Trade payables, bank overdraft, and corporation tax payable within 6 months","B":"10-year bank loan, share capital, and retained profit","C":"Trade receivables, inventory, and cash at bank","D":"Freehold factory, delivery vans, and 15-year mortgage"},"correctOption":"A","correctAnswer":"Trade payables, bank overdraft, and corporation tax payable within 6 months","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade payables, overdrafts, and tax due within a year are short-term obligations classified as current liabilities.","distractor_reasons":{"A":"Option A is correct because trade payables, overdrafts, and tax due within a year are short-term obligations classified as current liabilities.","B":"Incorrect because a 10-year loan is a non-current liability, while share capital and retained profit are equity.","C":"Incorrect because trade receivables, inventory, and cash are current assets.","D":"Incorrect because factory and vans are non-current assets, and a 15-year mortgage is a non-current liability."}}},{"id":"P1_U5_MCQ_206","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_206","question":"A shipping company borrows $2.5 million via a 15-year mortgage to buy a new cargo vessel. How is this $2.5 million debt classified on the shipping company's statement of financial position?","options":{"A":"Non-current liability","B":"Current liability","C":"Non-current asset","D":"Shareholders' equity"},"correctOption":"A","correctAnswer":"Non-current liability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because debts that are due to be repaid over more than 12 months are recorded as non-current liabilities.","distractor_reasons":{"A":"Option A is correct because debts that are due to be repaid over more than 12 months are recorded as non-current liabilities.","B":"Incorrect because current liabilities only include debts falling due within one year.","C":"Incorrect because the cargo vessel is the non-current asset, whereas the mortgage owed to the lender is a non-current liability.","D":"Incorrect because a mortgage is borrowed debt, not owners' equity."}}},{"id":"P1_U5_MCQ_207","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_207","question":"On a limited company's statement of financial position, which two items are combined to show total shareholders' equity?","options":{"A":"Trade receivables and trade payables","B":"Non-current assets and current assets","C":"Share capital and retained profit","D":"Bank loans and bank overdrafts"},"correctOption":"C","correctAnswer":"Share capital and retained profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because shareholders' equity represents the owners' stake in the company, consisting of original share capital invested plus accumulated retained profits.","distractor_reasons":{"A":"Incorrect because trade receivables are current assets and trade payables are current liabilities.","B":"Incorrect because non-current assets plus current assets equals total assets.","C":"Option C is correct because shareholders' equity represents the owners' stake in the company, consisting of original share capital invested plus accumulated retained profits.","D":"Incorrect because bank loans and overdrafts are debt liabilities."}}},{"id":"P1_U5_MCQ_208","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_208","question":"A bakery's statement of financial position shows premises of $240,000, ovens of $60,000, inventory of $12,000, trade receivables of $9,000, and cash of $5,000. What is the value of the bakery's total current assets?","options":{"A":"$300,000","B":"$26,000","C":"$326,000","D":"$21,000"},"correctOption":"B","correctAnswer":"$26,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Current assets = Inventory ($12,000) + Trade receivables ($9,000) + Cash ($5,000) = $26,000.","distractor_reasons":{"A":"Incorrect because $300,000 is the total of non-current assets ($240,000 + $60,000).","B":"Option B is correct because Current assets = Inventory ($12,000) + Trade receivables ($9,000) + Cash ($5,000) = $26,000.","C":"Incorrect because $326,000 is total assets (both non-current and current combined).","D":"Incorrect because $21,000 omits the $5,000 cash balance."}}},{"id":"P1_U5_MCQ_209","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_209","question":"A toy wholesaler has current assets of $84,000 and current liabilities of $51,000, alongside non-current assets of $190,000 and non-current liabilities of $70,000. What is the wholesaler's net current assets (working capital)?","options":{"A":"$33,000","B":"$135,000","C":"$153,000","D":"$274,000"},"correctOption":"A","correctAnswer":"$33,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net current assets (working capital) = Current assets - Current liabilities ($84,000 - $51,000 = $33,000).","distractor_reasons":{"A":"Option A is correct because Net current assets (working capital) = Current assets - Current liabilities ($84,000 - $51,000 = $33,000).","B":"Incorrect because $135,000 adds current assets and current liabilities together ($84,000 + $51,000).","C":"Incorrect because $153,000 is total net assets ($190,000 + $84,000 - $51,000 - $70,000).","D":"Incorrect because $274,000 is total assets ($190,000 + $84,000)."}}},{"id":"P1_U5_MCQ_210","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_210","question":"A logistics firm reports non-current assets of $420,000, current assets of $95,000, current liabilities of $55,000, and non-current liabilities of $160,000. What is the value of the firm's net assets?","options":{"A":"$515,000","B":"$460,000","C":"$300,000","D":"$215,000"},"correctOption":"C","correctAnswer":"$300,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Total assets = $420,000 + $95,000 = $515,000, Total liabilities = $55,000 + $160,000 = $215,000, and Net assets = Total assets - Total liabilities ($515,000 - $215,000 = $300,000).","distractor_reasons":{"A":"Incorrect because $515,000 is total assets before deducting any liabilities.","B":"Incorrect because $460,000 is capital employed (Total assets - Current liabilities), which does not subtract non-current liabilities.","C":"Option C is correct because Total assets = $420,000 + $95,000 = $515,000, Total liabilities = $55,000 + $160,000 = $215,000, and Net assets = Total assets - Total liabilities ($515,000 - $215,000 = $300,000).","D":"Incorrect because $215,000 is total liabilities."}}},{"id":"P1_U5_MCQ_211","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_211","question":"A company's statement of financial position shows non-current assets of $500,000, working capital (net current assets) of $80,000, non-current liabilities of $180,000, share capital of $250,000, and retained profit of $150,000. What is the company's capital employed?","options":{"A":"$400,000","B":"$580,000","C":"$430,000","D":"$660,000"},"correctOption":"B","correctAnswer":"$580,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Capital employed = Total equity ($250,000 + $150,000 = $400,000) + Non-current liabilities ($180,000) = $580,000 (which also equals Non-current assets $500,000 + Working capital $80,000).","distractor_reasons":{"A":"Incorrect because $400,000 is shareholders' equity alone and omits the $180,000 non-current liabilities.","B":"Option B is correct because Capital employed = Total equity ($250,000 + $150,000 = $400,000) + Non-current liabilities ($180,000) = $580,000 (which also equals Non-current assets $500,000 + Working capital $80,000).","C":"Incorrect because $430,000 omits the $150,000 retained profit.","D":"Incorrect because $660,000 adds working capital twice."}}},{"id":"P1_U5_MCQ_212","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_212","question":"On a company's statement of financial position, total assets are $620,000, total liabilities are $245,000, and share capital is $250,000. What must the company's retained profit be for the statement to balance?","options":{"A":"$375,000","B":"$125,000","C":"$120,000","D":"$495,000"},"correctOption":"B","correctAnswer":"$125,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Net assets = Total assets - Total liabilities ($620,000 - $245,000 = $375,000), which must equal Total equity (Share capital $250,000 + Retained profit), giving Retained profit = $375,000 - $250,000 = $125,000.","distractor_reasons":{"A":"Incorrect because $375,000 is total shareholders' equity, not retained profit alone.","B":"Option B is correct because Net assets = Total assets - Total liabilities ($620,000 - $245,000 = $375,000), which must equal Total equity (Share capital $250,000 + Retained profit), giving Retained profit = $375,000 - $250,000 = $125,000.","C":"Incorrect due to a subtraction error ($375,000 - $250,000 = $125,000).","D":"Incorrect because $495,000 adds liabilities and share capital together."}}},{"id":"P1_U5_MCQ_213","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_213","question":"A public limited company issues new ordinary shares and receives $1,000,000 in cash into its bank account. How does this transaction immediately change the company's statement of financial position?","options":{"A":"Current assets (cash) increase by $1,000,000 and shareholders' equity (share capital) increases by $1,000,000","B":"Non-current assets increase by $1,000,000 and current liabilities increase by $1,000,000","C":"Current liabilities decrease by $1,000,000 and retained profit decreases by $1,000,000","D":"Current assets decrease by $1,000,000 and non-current liabilities increase by $1,000,000"},"correctOption":"A","correctAnswer":"Current assets (cash) increase by $1,000,000 and shareholders' equity (share capital) increases by $1,000,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receiving cash increases current assets by $1,000,000 while issuing shares increases share capital within equity by $1,000,000.","distractor_reasons":{"A":"Option A is correct because receiving cash increases current assets by $1,000,000 while issuing shares increases share capital within equity by $1,000,000.","B":"Incorrect because cash is a current asset and share issues create equity rather than liabilities.","C":"Incorrect because share issues bring money into the company rather than reducing liabilities or retained profit.","D":"Incorrect because cash increases rather than decreases, and share capital is equity rather than debt."}}},{"id":"P1_U5_MCQ_214","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_214","question":"A wholesaler collects $14,000 in cash from credit customers who owed money for earlier deliveries. What is the immediate impact on the wholesaler's total current assets?","options":{"A":"Total current assets increase by $14,000","B":"Total current assets decrease by $14,000","C":"Total current assets remain unchanged because cash rises by $14,000 while trade receivables fall by $14,000","D":"Total current assets increase by $28,000"},"correctOption":"C","correctAnswer":"Total current assets remain unchanged because cash rises by $14,000 while trade receivables fall by $14,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because both cash and trade receivables are current assets; converting $14,000 of receivables into cash leaves total current assets unchanged.","distractor_reasons":{"A":"Incorrect because trade receivables drop by the exact same amount that cash rises.","B":"Incorrect because the cash remains inside current assets.","C":"Option C is correct because both cash and trade receivables are current assets; converting $14,000 of receivables into cash leaves total current assets unchanged.","D":"Incorrect because collecting a receivable does not double current assets."}}},{"id":"P1_U5_MCQ_215","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_215","question":"A company uses $40,000 of its cash balance to pay off part of its long-term bank loan. Which two sections of the statement of financial position decrease by $40,000?","options":{"A":"Non-current assets and current liabilities","B":"Current assets and non-current liabilities","C":"Current assets and shareholders' equity","D":"Non-current assets and shareholders' equity"},"correctOption":"B","correctAnswer":"Current assets and non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cash (a current asset) decreases by $40,000 and the long-term bank loan (a non-current liability) also decreases by $40,000.","distractor_reasons":{"A":"Incorrect because cash is a current asset and a long-term loan is a non-current liability.","B":"Option B is correct because cash (a current asset) decreases by $40,000 and the long-term bank loan (a non-current liability) also decreases by $40,000.","C":"Incorrect because repaying a bank loan reduces debt liabilities rather than owners' equity.","D":"Incorrect because neither non-current assets nor equity changes when cash repays a long-term loan."}}},{"id":"P1_U5_MCQ_216","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_216","question":"A supermarket pays $12,000 in cash to purchase fresh produce inventory from farmers. How does this purchase affect the supermarket's working capital?","options":{"A":"Working capital decreases by $12,000","B":"Working capital increases by $12,000","C":"Working capital remains unchanged because cash falls by $12,000 while inventory rises by $12,000","D":"Working capital becomes negative by $12,000"},"correctOption":"C","correctAnswer":"Working capital remains unchanged because cash falls by $12,000 while inventory rises by $12,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because both cash and inventory are current assets; swapping one current asset for another leaves total current assets and working capital unchanged.","distractor_reasons":{"A":"Incorrect because inventory increases by the same $12,000 that cash decreases.","B":"Incorrect because total current assets do not increase when cash is spent on inventory.","C":"Option C is correct because both cash and inventory are current assets; swapping one current asset for another leaves total current assets and working capital unchanged.","D":"Incorrect because swapping cash for inventory does not alter working capital."}}},{"id":"P1_U5_MCQ_217","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_217","question":"Comparing its statement of financial position over two years, a consumer electronics retailer sees its inventory value jump from $45,000 to $140,000 while annual sales fell by 10%. What problem does this data highlight?","options":{"A":"The retailer is accumulating unsold, potentially obsolete stock that ties up cash and risks write-downs","B":"The retailer has paid off all of its trade payables","C":"The retailer's non-current liabilities have fallen to zero","D":"The retailer has too much cash in its bank account"},"correctOption":"A","correctAnswer":"The retailer is accumulating unsold, potentially obsolete stock that ties up cash and risks write-downs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because surging inventory during falling sales indicates poor stock control and slow-moving products that tie up working capital.","distractor_reasons":{"A":"Option A is correct because surging inventory during falling sales indicates poor stock control and slow-moving products that tie up working capital.","B":"Incorrect because rising inventory does not mean trade payables are zero.","C":"Incorrect because inventory levels do not show non-current liabilities.","D":"Incorrect because buying excess inventory drains cash rather than creating excess cash."}}},{"id":"P1_U5_MCQ_218","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_218","question":"A catering firm's statement of financial position shows cash of $1,000, trade receivables of $9,000, inventory of $8,000, trade payables of $22,000, and a bank overdraft of $11,000. What is the firm's working capital?","options":{"A":"$15,000","B":"-$15,000","C":"-$4,000","D":"$51,000"},"correctOption":"B","correctAnswer":"-$15,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Current assets = $1,000 + $9,000 + $8,000 = $18,000 and Current liabilities = $22,000 + $11,000 = $33,000, giving working capital of $18,000 - $33,000 = -$15,000.","distractor_reasons":{"A":"Incorrect because current liabilities exceed current assets, making working capital negative (-$15,000).","B":"Option B is correct because Current assets = $1,000 + $9,000 + $8,000 = $18,000 and Current liabilities = $22,000 + $11,000 = $33,000, giving working capital of $18,000 - $33,000 = -$15,000.","C":"Incorrect because -$4,000 omits the $11,000 bank overdraft from current liabilities ($18,000 - $22,000).","D":"Incorrect because $51,000 adds current assets and current liabilities together."}}},{"id":"P1_U5_MCQ_219","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_219","question":"A company's statement of financial position lists equipment, delivery vehicles and a purchased patent. How should these items be classified?","options":{"A":"Shareholders' equity","B":"Current assets","C":"Current liabilities","D":"Non-current assets"},"correctOption":"D","correctAnswer":"Non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because equipment, vehicles and patents are long-term resources expected to benefit the business for more than one year.","distractor_reasons":{"A":"Incorrect because shareholders' equity represents the owners' claim on the business, not the long-term assets themselves.","B":"Incorrect because current assets are short-term items such as cash, inventories and receivables, not long-term equipment or patents.","C":"Incorrect because these items are assets owned by the business, not debts or obligations that must be paid.","D":"Option D is correct because equipment, vehicles and patents are long-term resources expected to benefit the business for more than one year."}}},{"id":"P1_U5_MCQ_220","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_220","question":"Over five profitable years, a private limited company never issues any new shares and keeps its bank loans unchanged, yet its total assets grow from $300,000 to $580,000. Which item on the statement of financial position must have increased by $280,000 to fund this growth?","options":{"A":"Retained profit within shareholders' equity","B":"Original share capital","C":"Non-current liabilities","D":"Cost of sales"},"correctOption":"A","correctAnswer":"Retained profit within shareholders' equity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because with share capital and liabilities unchanged, the $280,000 increase in net assets must have been funded by accumulated retained profits in equity.","distractor_reasons":{"A":"Option A is correct because with share capital and liabilities unchanged, the $280,000 increase in net assets must have been funded by accumulated retained profits in equity.","B":"Incorrect because the scenario states no new shares were issued.","C":"Incorrect because the scenario states bank loans remained unchanged.","D":"Incorrect because cost of sales appears on the statement of profit or loss, not the statement of financial position."}}},{"id":"P1_U5_MCQ_221","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_221","question":"What is the exact difference between 'trade receivables' and 'trade payables' on a business's statement of financial position?","options":{"A":"Trade receivables are money owed TO the business by credit customers (current asset), whereas trade payables are money owed BY the business to credit suppliers (current liability)","B":"Trade receivables are long-term loans, whereas trade payables are non-current assets","C":"Trade receivables are paid to the government, whereas trade payables are paid to shareholders","D":"Trade receivables are non-current assets, whereas trade payables are shareholders' equity"},"correctOption":"A","correctAnswer":"Trade receivables are money owed TO the business by credit customers (current asset), whereas trade payables are money owed BY the business to credit suppliers (current liability)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade receivables represent incoming cash owed by customers, while trade payables represent outgoing cash owed to suppliers.","distractor_reasons":{"A":"Option A is correct because trade receivables represent incoming cash owed by customers, while trade payables represent outgoing cash owed to suppliers.","B":"Incorrect because both are short-term working capital items, not long-term loans or non-current assets.","C":"Incorrect because taxes and dividends are separate items from trade credit with customers and suppliers.","D":"Incorrect because trade receivables are current assets and trade payables are current liabilities."}}},{"id":"P1_U5_MCQ_222","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_222","question":"Which item appears on the statement of profit or loss, rather than on the statement of financial position?","options":{"A":"Cost of sales","B":"Trade receivables","C":"Non-current liabilities","D":"Share capital"},"correctOption":"A","correctAnswer":"Cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost of sales is a trading cost deducted from revenue on the statement of profit or loss, whereas the other three items sit on the statement of financial position.","distractor_reasons":{"A":"Option A is correct because cost of sales is a trading cost deducted from revenue on the statement of profit or loss, whereas the other three items sit on the statement of financial position.","B":"Incorrect because trade receivables are current assets on the statement of financial position.","C":"Incorrect because non-current liabilities appear on the statement of financial position.","D":"Incorrect because share capital is part of equity on the statement of financial position."}}},{"id":"P1_U5_MCQ_223","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_223","question":"The directors of a logistics firm want to spend $120,000 in cash to buy three new vans. Before approving the purchase, they check the statement of financial position and see cash of $130,000, inventory of $20,000, and current liabilities of $145,000. Why should the directors NOT pay $120,000 cash outright?","options":{"A":"Buying vans for cash reduces total assets to zero","B":"Vans cannot legally be recorded as non-current assets","C":"Spending $120,000 cash would leave only $10,000 cash and $20,000 inventory to cover $145,000 of short-term debts, triggering a severe liquidity crisis","D":"Current liabilities are automatically cancelled when non-current assets are bought"},"correctOption":"C","correctAnswer":"Spending $120,000 cash would leave only $10,000 cash and $20,000 inventory to cover $145,000 of short-term debts, triggering a severe liquidity crisis","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the firm barely has enough current assets ($150,000) to cover current liabilities ($145,000); draining $120,000 of cash would leave it unable to pay short-term creditors.","distractor_reasons":{"A":"Incorrect because buying vans converts cash (current asset) into vans (non-current asset) without reducing total assets.","B":"Incorrect because delivery vans are standard non-current assets.","C":"Option C is correct because the firm barely has enough current assets ($150,000) to cover current liabilities ($145,000); draining $120,000 of cash would leave it unable to pay short-term creditors.","D":"Incorrect because current liabilities must still be paid regardless of van purchases."}}},{"id":"P1_U5_MCQ_224","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_224","question":"A commercial bank is reviewing a hotel company's statement of financial position before deciding on a $500,000 loan application. Which detail on the statement helps the bank check if the company has sufficient assets to back the loan?","options":{"A":"The gross profit margin percentage","B":"The company's annual marketing expenditure","C":"The number of guests who stayed at the hotel in July","D":"The value of unmortgaged freehold hotel buildings under non-current assets"},"correctOption":"D","correctAnswer":"The value of unmortgaged freehold hotel buildings under non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because non-current assets like debt-free freehold property are shown on the statement of financial position and can be used as loan collateral.","distractor_reasons":{"A":"Incorrect because gross profit margin is a profitability ratio, not a physical asset for security.","B":"Incorrect because marketing expenditure is an expense on the statement of profit or loss, not collateral.","C":"Incorrect because guest numbers are operational statistics, not on the statement of financial position.","D":"Option D is correct because non-current assets like debt-free freehold property are shown on the statement of financial position and can be used as loan collateral."}}},{"id":"P1_U5_MCQ_225","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_225","question":"A retail company delays paying its suppliers until the day after its financial year-end so that its year-end cash balance looks unusually high on its published statement of financial position. What limitation of the statement of financial position does this illustrate?","options":{"A":"The statement of financial position never includes cash balances","B":"Because it is a snapshot taken on a single date, figures can be temporarily manipulated ('window-dressed') and may not reflect typical daily liquidity","C":"Supplier invoices are permanently erased if not paid before year-end","D":"Current liabilities are always excluded from published accounts"},"correctOption":"B","correctAnswer":"Because it is a snapshot taken on a single date, figures can be temporarily manipulated ('window-dressed') and may not reflect typical daily liquidity","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a single-day snapshot reflects balances only on that exact date and may not represent normal cash levels throughout the rest of the year.","distractor_reasons":{"A":"Incorrect because cash is always listed under current assets.","B":"Option B is correct because a single-day snapshot reflects balances only on that exact date and may not represent normal cash levels throughout the rest of the year.","C":"Incorrect because unpaid supplier invoices remain recorded as trade payables (current liabilities).","D":"Incorrect because current liabilities are a required part of the statement of financial position."}}},{"id":"P1_U5_MCQ_226","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_226","question":"Why do financial analysts calculate BOTH profitability ratios and liquidity ratios when evaluating a business's annual accounts?","options":{"A":"Because liquidity ratios measure total revenue and profitability ratios measure total liabilities","B":"Because profitability ratios are only for sole traders and liquidity ratios are only for companies","C":"Because profitability ratios always equal liquidity ratios","D":"Because profitability ratios show how effectively the business generates profit from sales and capital, whereas liquidity ratios show whether it can pay short-term debts on time"},"correctOption":"D","correctAnswer":"Because profitability ratios show how effectively the business generates profit from sales and capital, whereas liquidity ratios show whether it can pay short-term debts on time","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a business needs both long-term profitability to reward owners and short-term liquidity to survive and pay immediate bills.","distractor_reasons":{"A":"Incorrect because neither set of ratios simply reports raw revenue or total liabilities.","B":"Incorrect because both sets of ratios are used across all types of businesses.","C":"Incorrect because profitability is expressed as a percentage and liquidity as a ratio, measuring completely different aspects of performance.","D":"Option D is correct because a business needs both long-term profitability to reward owners and short-term liquidity to survive and pay immediate bills."}}},{"id":"P1_U5_MCQ_227","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_227","question":"An organic food wholesaler reports annual sales revenue of $800,000, cost of sales of $520,000, and overhead expenses of $160,000. What is the wholesaler's gross profit margin?","options":{"A":"15%","B":"65%","C":"35%","D":"20%"},"correctOption":"C","correctAnswer":"35%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = $800,000 - $520,000 = $280,000, and Gross profit margin = ($280,000 / $800,000) × 100 = 35%.","distractor_reasons":{"A":"Incorrect because 15% is the profit margin ($120,000 / $800,000 × 100).","B":"Incorrect because 65% is cost of sales as a percentage of revenue ($520,000 / $800,000 × 100).","C":"Option C is correct because Gross profit = $800,000 - $520,000 = $280,000, and Gross profit margin = ($280,000 / $800,000) × 100 = 35%.","D":"Incorrect because 20% is overhead expenses as a percentage of revenue ($160,000 / $800,000 × 100)."}}},{"id":"P1_U5_MCQ_228","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_228","question":"A footwear chain's gross profit margin dropped from 44% last year to 38% this year. Which change best explains this decline?","options":{"A":"The chain reduced its store advertising budget","B":"The chain spent more on head-office IT support staff","C":"The chain repaid a long-term bank loan early","D":"The chain offered frequent 20% 'flash sale' price discounts to clear stock while supplier shoe costs stayed the same"},"correctOption":"D","correctAnswer":"The chain offered frequent 20% 'flash sale' price discounts to clear stock while supplier shoe costs stayed the same","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cutting selling prices while unit cost of sales stays unchanged shrinks the gross profit earned on every dollar of sales.","distractor_reasons":{"A":"Incorrect because advertising is an overhead expense and reducing it would increase profit margin, not lower gross profit margin.","B":"Incorrect because head-office IT salaries are indirect overhead expenses deducted after gross profit.","C":"Incorrect because repaying a bank loan does not affect gross profit margin.","D":"Option D is correct because cutting selling prices while unit cost of sales stays unchanged shrinks the gross profit earned on every dollar of sales."}}},{"id":"P1_U5_MCQ_229","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_229","question":"A bakery wants to raise its gross profit margin from 45% to 50%. Which action directly increases the gross profit margin?","options":{"A":"Reducing flour wastage during baking and negotiating a 5% bulk discount from flour suppliers without lowering bread prices","B":"Reducing the bakery's annual accounting audit fee","C":"Replacing a short-term overdraft with a long-term loan","D":"Selling an unused delivery van for cash"},"correctOption":"A","correctAnswer":"Reducing flour wastage during baking and negotiating a 5% bulk discount from flour suppliers without lowering bread prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lowering direct ingredient costs (cost of sales) relative to selling price directly widens the gross profit margin.","distractor_reasons":{"A":"Option A is correct because lowering direct ingredient costs (cost of sales) relative to selling price directly widens the gross profit margin.","B":"Incorrect because audit fees are indirect overhead expenses that affect profit margin rather than gross profit margin.","C":"Incorrect because restructuring debt affects liquidity ratios, not gross profit margin.","D":"Incorrect because selling a non-current asset affects cash flow and assets, not gross profit margin."}}},{"id":"P1_U5_MCQ_230","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_230","question":"A digital marketing agency earns annual revenue of $450,000, gross profit of $315,000, and final profit of $63,000. What is the agency's profit margin?","options":{"A":"70%","B":"14%","C":"20%","D":"56%"},"correctOption":"B","correctAnswer":"14%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Profit margin = (Profit / Revenue) × 100 = ($63,000 / $450,000) × 100 = 14%.","distractor_reasons":{"A":"Incorrect because 70% is the gross profit margin ($315,000 / $450,000 × 100).","B":"Option B is correct because Profit margin = (Profit / Revenue) × 100 = ($63,000 / $450,000) × 100 = 14%.","C":"Incorrect because 20% divides profit by gross profit ($63,000 / $315,000 × 100) instead of dividing by revenue.","D":"Incorrect because 56% is overhead expenses as a percentage of revenue ($252,000 / $450,000 × 100)."}}},{"id":"P1_U5_MCQ_231","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_231","question":"A hotel chain's gross profit margin remained steady at 65% over two years, while its profit margin rose from 12% to 17%. What does this improvement indicate?","options":{"A":"The hotel chain controlled its indirect overhead expenses more effectively relative to revenue","B":"The cost of food and beverages bought for guests fell by half","C":"The hotel chain's current ratio fell below 1 : 1","D":"Room prices were cut by 50%"},"correctOption":"A","correctAnswer":"The hotel chain controlled its indirect overhead expenses more effectively relative to revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an unchanged gross profit margin paired with a rising profit margin proves that indirect expenses took up a smaller share of revenue.","distractor_reasons":{"A":"Option A is correct because an unchanged gross profit margin paired with a rising profit margin proves that indirect expenses took up a smaller share of revenue.","B":"Incorrect because lower direct food/beverage costs would have increased the gross profit margin.","C":"Incorrect because profitability margins do not measure the current ratio.","D":"Incorrect because a 50% room price cut would have reduced both gross profit margin and profit margin."}}},{"id":"P1_U5_MCQ_232","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_232","question":"A courier company wants to improve its profit margin without changing customer delivery prices or driver wages. Which action would achieve this?","options":{"A":"Holding larger inventories of spare tires","B":"Issuing new ordinary shares on the stock exchange","C":"Extending customer credit terms from 30 days to 90 days","D":"Using route-optimisation software to cut overhead fuel and administrative office costs"},"correctOption":"D","correctAnswer":"Using route-optimisation software to cut overhead fuel and administrative office costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because reducing running expenses leaves a larger profit from the same revenue, directly raising the profit margin.","distractor_reasons":{"A":"Incorrect because holding extra tire inventory ties up working capital without lowering expenses.","B":"Incorrect because issuing shares affects equity and capital employed, not profit margin.","C":"Incorrect because longer customer credit terms slow down cash flow rather than raising profit margin.","D":"Option D is correct because reducing running expenses leaves a larger profit from the same revenue, directly raising the profit margin."}}},{"id":"P1_U5_MCQ_233","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_233","question":"A manufacturing business generates an annual profit of $180,000, and its statement of financial position shows shareholders' equity of $750,000 and non-current liabilities of $250,000. What is the business's Return on Capital Employed (ROCE)?","options":{"A":"24%","B":"72%","C":"18%","D":"36%"},"correctOption":"C","correctAnswer":"18%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Capital employed = Equity ($750,000) + Non-current liabilities ($250,000) = $1,000,000, and ROCE = ($180,000 / $1,000,000) × 100 = 18%.","distractor_reasons":{"A":"Incorrect because 24% divides profit only by equity ($180,000 / $750,000 × 100), omitting non-current liabilities.","B":"Incorrect because 72% divides profit only by non-current liabilities ($180,000 / $250,000 × 100).","C":"Option C is correct because Capital employed = Equity ($750,000) + Non-current liabilities ($250,000) = $1,000,000, and ROCE = ($180,000 / $1,000,000) × 100 = 18%.","D":"Incorrect because 36% divides profit by the difference between equity and debt ($180,000 / $500,000 × 100)."}}},{"id":"P1_U5_MCQ_234","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_234","question":"An entrepreneur invests $200,000 of her own savings into a retail business that earns a profit of $6,000 for the year (an ROCE of 3%), while safe government bonds pay 5% annual interest. How would a financial adviser interpret this 3% ROCE?","options":{"A":"The return on capital invested is weak because the entrepreneur is earning less than she could earn risk-free from government bonds","B":"The business has an ideal liquidity ratio","C":"The business is earning a high return because any positive ROCE is automatically successful","D":"The business has zero non-current assets"},"correctOption":"A","correctAnswer":"The return on capital invested is weak because the entrepreneur is earning less than she could earn risk-free from government bonds","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ROCE should be compared against alternative risk-free returns such as bank deposit or bond interest rates; earning 3% while taking business risk is poor compared to 5% risk-free.","distractor_reasons":{"A":"Option A is correct because ROCE should be compared against alternative risk-free returns such as bank deposit or bond interest rates; earning 3% while taking business risk is poor compared to 5% risk-free.","B":"Incorrect because ROCE measures return on invested capital, not short-term liquidity.","C":"Incorrect because a 3% return fails to compensate for the financial risk of running a business when safe interest rates are 5%.","D":"Incorrect because ROCE does not indicate whether non-current assets are zero."}}},{"id":"P1_U5_MCQ_235","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_235","question":"A logistics company sells an underused, empty depot for $300,000 cash and uses the proceeds to pay off a $300,000 non-current bank loan, while its annual operating profit stays unchanged at $90,000. How does this affect the company's ROCE?","options":{"A":"ROCE falls to 0%","B":"ROCE decreases because non-current assets fell","C":"ROCE stays completely unchanged","D":"ROCE increases because the same profit is generated using $300,000 less capital employed"},"correctOption":"D","correctAnswer":"ROCE increases because the same profit is generated using $300,000 less capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repaying the $300,000 non-current loan reduces capital employed (the denominator in ROCE) while profit stays constant, raising ROCE.","distractor_reasons":{"A":"Incorrect because profit is still $90,000, so ROCE remains positive and higher than before.","B":"Incorrect because reducing unproductive capital employed improves capital efficiency and raises ROCE.","C":"Incorrect because capital employed decreased by $300,000 while profit remained $90,000.","D":"Option D is correct because repaying the $300,000 non-current loan reduces capital employed (the denominator in ROCE) while profit stays constant, raising ROCE."}}},{"id":"P1_U5_MCQ_236","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_236","question":"A hardware wholesaler has inventory of $48,000, trade receivables of $32,000, cash of $10,000, trade payables of $35,000, and a bank overdraft of $15,000. What is the wholesaler's current ratio?","options":{"A":"0.84 : 1","B":"1.8 : 1","C":"0.56 : 1","D":"2.57 : 1"},"correctOption":"B","correctAnswer":"1.8 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Current assets = $48,000 + $32,000 + $10,000 = $90,000 and Current liabilities = $35,000 + $15,000 = $50,000, giving Current ratio = $90,000 / $50,000 = 1.8 : 1.","distractor_reasons":{"A":"Incorrect because 0.84 : 1 is the acid-test ratio (($90,000 - $48,000) / $50,000).","B":"Option B is correct because Current assets = $48,000 + $32,000 + $10,000 = $90,000 and Current liabilities = $35,000 + $15,000 = $50,000, giving Current ratio = $90,000 / $50,000 = 1.8 : 1.","C":"Incorrect because 0.56 : 1 divides current liabilities by current assets ($50,000 / $90,000).","D":"Incorrect because 2.57 : 1 omits the $15,000 bank overdraft from current liabilities ($90,000 / $35,000)."}}},{"id":"P1_U5_MCQ_237","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_237","question":"Which current ratio figure generally indicates a healthy, balanced liquidity position for a typical manufacturing or trading business?","options":{"A":"0.4 : 1","B":"1.7 : 1","C":"6.5 : 1","D":"0.85 : 1"},"correctOption":"B","correctAnswer":"1.7 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a current ratio between 1.5 : 1 and 2 : 1 shows the business can comfortably cover short-term liabilities without tying up excessive unproductive funds.","distractor_reasons":{"A":"Incorrect because 0.4 : 1 means current liabilities are 2.5 times larger than current assets, signalling acute insolvency risk.","B":"Option B is correct because a current ratio between 1.5 : 1 and 2 : 1 shows the business can comfortably cover short-term liabilities without tying up excessive unproductive funds.","C":"Incorrect because 6.5 : 1 is excessively high, indicating huge amounts of idle cash, uncollected receivables, or excess inventory.","D":"Incorrect because 0.85 : 1 is below 1 : 1, meaning short-term debts exceed current assets."}}},{"id":"P1_U5_MCQ_238","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_238","question":"A furniture retailer has current assets of $160,000, which includes $95,000 of sofa and table inventory, and current liabilities of $50,000. What is the retailer's acid-test ratio?","options":{"A":"3.2 : 1","B":"1.9 : 1","C":"1.3 : 1","D":"0.77 : 1"},"correctOption":"C","correctAnswer":"1.3 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($160,000 - $95,000) / $50,000 = $65,000 / $50,000 = 1.3 : 1.","distractor_reasons":{"A":"Incorrect because 3.2 : 1 is the current ratio ($160,000 / $50,000), which fails to deduct inventory.","B":"Incorrect because 1.9 : 1 divides inventory by current liabilities ($95,000 / $50,000).","C":"Option C is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($160,000 - $95,000) / $50,000 = $65,000 / $50,000 = 1.3 : 1.","D":"Incorrect because 0.77 : 1 inverts the formula ($50,000 / $65,000)."}}},{"id":"P1_U5_MCQ_239","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_239","question":"Why is the acid-test ratio considered a stricter test of a business's immediate liquidity than the current ratio?","options":{"A":"Because it uses gross profit instead of current assets","B":"Because it includes non-current assets such as factory buildings","C":"Because it deducts long-term bank loans from cash","D":"Because it excludes inventory, which cannot always be quickly converted into cash to pay urgent bills"},"correctOption":"D","correctAnswer":"Because it excludes inventory, which cannot always be quickly converted into cash to pay urgent bills","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because inventory is the least liquid current asset and may take months to sell, so removing it shows whether cash and receivables alone can pay short-term debts.","distractor_reasons":{"A":"Incorrect because gross profit is a profitability figure, not used in the acid-test ratio.","B":"Incorrect because non-current assets are excluded from both liquidity ratios.","C":"Incorrect because long-term bank loans are non-current liabilities and are excluded from both ratios.","D":"Option D is correct because inventory is the least liquid current asset and may take months to sell, so removing it shows whether cash and receivables alone can pay short-term debts."}}},{"id":"P1_U5_MCQ_240","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_240","question":"A winter coat retailer's current ratio is 2.8 : 1, while its acid-test ratio is 0.45 : 1. What action should the retailer take to address the issue revealed by these two ratios?","options":{"A":"Run promotions to clear excess unsold coat inventory and turn it into cash","B":"Order twice as much coat inventory on 30-day credit","C":"Use all remaining bank cash to buy a new delivery van","D":"Take out a new short-term bank overdraft to buy more stock"},"correctOption":"A","correctAnswer":"Run promotions to clear excess unsold coat inventory and turn it into cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the huge drop from 2.8 : 1 to 0.45 : 1 shows that almost all current assets are stuck in unsold inventory, which needs to be converted into cash.","distractor_reasons":{"A":"Option A is correct because the huge drop from 2.8 : 1 to 0.45 : 1 shows that almost all current assets are stuck in unsold inventory, which needs to be converted into cash.","B":"Incorrect because buying even more stock on credit would worsen overstocking and push the acid-test ratio even lower.","C":"Incorrect because spending cash on a van would reduce liquid assets even further.","D":"Incorrect because increasing an overdraft and buying more inventory would deepen the liquidity problem."}}},{"id":"P1_U5_MCQ_241","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_241","question":"A printing company has a weak current ratio of 0.85 : 1 and wants to raise it above 1.2 : 1. Which action will increase the company's current ratio?","options":{"A":"Buying $10,000 of paper inventory for cash","B":"Using $20,000 cash to buy a new printing press","C":"Paying $15,000 cash in dividends to shareholders","D":"Converting a $30,000 short-term bank overdraft into a 5-year long-term bank loan"},"correctOption":"D","correctAnswer":"Converting a $30,000 short-term bank overdraft into a 5-year long-term bank loan","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because replacing a short-term overdraft (current liability) with a 5-year loan (non-current liability) reduces current liabilities while keeping current assets unchanged, raising the current ratio.","distractor_reasons":{"A":"Incorrect because swapping cash for inventory leaves total current assets and the current ratio unchanged.","B":"Incorrect because spending cash on a non-current asset reduces current assets and lowers the current ratio.","C":"Incorrect because paying cash dividends reduces current assets and lowers the current ratio.","D":"Option D is correct because replacing a short-term overdraft (current liability) with a 5-year loan (non-current liability) reduces current liabilities while keeping current assets unchanged, raising the current ratio."}}},{"id":"P1_U5_MCQ_242","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_242","question":"A retailer currently has current assets of $80,000 (including $30,000 of inventory) and current liabilities of $50,000, giving an acid-test ratio of 1.0 : 1. If the retailer buys $10,000 of extra inventory on 30-day trade credit, what happens to its acid-test ratio?","options":{"A":"It falls from 1.0 : 1 to 0.83 : 1 because current liabilities rise by $10,000 while liquid assets (excluding inventory) stay at $50,000","B":"It rises from 1.0 : 1 to 1.2 : 1 because current assets increase","C":"It stays completely unchanged at 1.0 : 1","D":"It rises to 1.5 : 1"},"correctOption":"A","correctAnswer":"It falls from 1.0 : 1 to 0.83 : 1 because current liabilities rise by $10,000 while liquid assets (excluding inventory) stay at $50,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because liquid assets (Current assets - Inventory) stay at $50,000, while current liabilities rise from $50,000 to $60,000, reducing the acid-test ratio to $50,000 / $60,000 = 0.83 : 1.","distractor_reasons":{"A":"Option A is correct because liquid assets (Current assets - Inventory) stay at $50,000, while current liabilities rise from $50,000 to $60,000, reducing the acid-test ratio to $50,000 / $60,000 = 0.83 : 1.","B":"Incorrect because the $10,000 increase in current assets is inventory, which is excluded from the acid-test numerator.","C":"Incorrect because current liabilities increase while the numerator does not.","D":"Incorrect because buying inventory on credit weakens rather than improves the acid-test ratio."}}},{"id":"P1_U5_MCQ_243","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_243","question":"Which stakeholder group is an INTERNAL user of a company's financial accounts and ratios?","options":{"A":"Government tax authorities","B":"Commercial bank loan officers","C":"Senior managers and department heads","D":"External raw material suppliers"},"correctOption":"C","correctAnswer":"Senior managers and department heads","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because managers work inside the business and use accounting ratios to monitor efficiency, control costs, and make daily strategic decisions.","distractor_reasons":{"A":"Incorrect because government tax authorities are external regulators.","B":"Incorrect because commercial banks are external lenders.","C":"Option C is correct because managers work inside the business and use accounting ratios to monitor efficiency, control costs, and make daily strategic decisions.","D":"Incorrect because suppliers are external trade creditors."}}},{"id":"P1_U5_MCQ_244","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_244","question":"A potential investor is comparing two public limited companies in the same sector, Alpha plc (ROCE 19%, profit margin 14%) and Beta plc (ROCE 8%, profit margin 6%), before buying shares. How does this ratio analysis help the investor?","options":{"A":"It shows that Alpha plc generates a much higher return on capital and sales, indicating stronger dividend and share-price growth potential","B":"It guarantees that Alpha plc will never face a cash flow deficit","C":"It proves that Beta plc has higher current assets than Alpha plc","D":"It allows the investor to set Alpha plc's employee wages"},"correctOption":"A","correctAnswer":"It shows that Alpha plc generates a much higher return on capital and sales, indicating stronger dividend and share-price growth potential","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external investors compare profitability ratios across rival firms to identify which company uses capital more effectively to reward shareholders.","distractor_reasons":{"A":"Option A is correct because external investors compare profitability ratios across rival firms to identify which company uses capital more effectively to reward shareholders.","B":"Incorrect because profitability ratios do not measure cash liquidity.","C":"Incorrect because ROCE and profit margin do not indicate the size of current assets.","D":"Incorrect because ordinary shareholders do not set operational employee wages."}}},{"id":"P1_U5_MCQ_245","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_245","question":"Before approving a $400,000 expansion loan for a food manufacturer, a bank manager inspects the manufacturer's current ratio, acid-test ratio, and existing non-current liabilities. Why are these specific figures most important to the bank?","options":{"A":"They determine how many shares the bank will receive instead of interest","B":"They tell the bank what flavours of food the manufacturer should launch next","C":"They show whether the manufacturer already carries heavy debt and whether it has enough liquid assets to pay interest and loan instalments on time","D":"They show the exact customer satisfaction score of the manufacturer"},"correctOption":"C","correctAnswer":"They show whether the manufacturer already carries heavy debt and whether it has enough liquid assets to pay interest and loan instalments on time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lenders focus on default risk, assessing existing debt commitments and short-term liquidity to ensure timely repayment.","distractor_reasons":{"A":"Incorrect because banks earn interest on loans rather than receiving shares.","B":"Incorrect because product development decisions are made by the manufacturer's marketing team.","C":"Option C is correct because lenders focus on default risk, assessing existing debt commitments and short-term liquidity to ensure timely repayment.","D":"Incorrect because customer satisfaction is a non-financial metric not shown in liquidity ratios."}}},{"id":"P1_U5_MCQ_246","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_246","question":"A timber wholesaler is asked by a furniture maker to supply $25,000 of wood on 60-day trade credit. After checking the furniture maker's accounts and finding an acid-test ratio of 0.35 : 1, what decision is the wholesaler most likely to make?","options":{"A":"Refuse 60-day trade credit and insist on cash on delivery because the furniture maker lacks liquid assets to pay short-term bills","B":"Offer 180 days of interest-free trade credit immediately","C":"Buy shares in the furniture maker to increase its ROCE","D":"Ignore the acid-test ratio because suppliers never care when they get paid"},"correctOption":"A","correctAnswer":"Refuse 60-day trade credit and insist on cash on delivery because the furniture maker lacks liquid assets to pay short-term bills","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an acid-test ratio of 0.35 : 1 signals severe short-term liquidity weakness, warning suppliers that invoices may go unpaid.","distractor_reasons":{"A":"Option A is correct because an acid-test ratio of 0.35 : 1 signals severe short-term liquidity weakness, warning suppliers that invoices may go unpaid.","B":"Incorrect because extending longer credit to a cash-strapped customer increases bad-debt risk.","C":"Incorrect because a timber supplier wants prompt payment for goods, not equity ownership in a struggling customer.","D":"Incorrect because suppliers depend on timely invoice payments to manage their own cash flow."}}},{"id":"P1_U5_MCQ_247","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_247","question":"Why do employees and trade unions examine a company's published statement of profit or loss and statement of financial position?","options":{"A":"To value the company's inventory for resale","B":"To calculate the exact amount of corporation tax owed to the government","C":"To decide whether to grant the company a 15-year mortgage","D":"To assess whether the business is profitable and financially secure enough to protect jobs and fund pay rises"},"correctOption":"D","correctAnswer":"To assess whether the business is profitable and financially secure enough to protect jobs and fund pay rises","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because workers rely on the business for employment and income, so strong profits and liquidity support job security and wage claims.","distractor_reasons":{"A":"Incorrect because inventory valuation is performed by accountants and auditors.","B":"Incorrect because tax assessment is conducted by government tax authorities.","C":"Incorrect because mortgages are provided by banks and lenders.","D":"Option D is correct because workers rely on the business for employment and income, so strong profits and liquidity support job security and wage claims."}}},{"id":"P1_U5_MCQ_248","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_248","question":"Aside from tax authorities, which external group studies a rival company's published gross profit margin, profit margin, and ROCE to benchmark its own performance?","options":{"A":"Local primary school students","B":"Competitors in the same industry","C":"Internal factory supervisors","D":"The company's own board of directors"},"correctOption":"B","correctAnswer":"Competitors in the same industry","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because rival firms analyse published accounts of competitors to compare profit margins, efficiency, and financial strength.","distractor_reasons":{"A":"Incorrect because primary school students are not business stakeholders analysing industry benchmarks.","B":"Option B is correct because rival firms analyse published accounts of competitors to compare profit margins, efficiency, and financial strength.","C":"Incorrect because internal supervisors work inside the company rather than being external competitors.","D":"Incorrect because the board of directors is internal to the company."}}},{"id":"P1_U5_MCQ_249","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_249","question":"When comparing a company's profit margin and ROCE from 2016 with its ratios in 2026, why can high inflation over that ten-year period make comparisons misleading?","options":{"A":"Inflation removes all current liabilities from the statement of financial position","B":"Inflation makes it illegal to calculate percentages over more than two years","C":"Inflation pushes up current sales revenues and profits in nominal dollar terms while older non-current assets remain recorded at lower historical purchase prices","D":"Inflation automatically forces gross profit margins to equal 100%"},"correctOption":"C","correctAnswer":"Inflation pushes up current sales revenues and profits in nominal dollar terms while older non-current assets remain recorded at lower historical purchase prices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because inflation inflates current prices and profits relative to historical asset book values, artificially boosting ROCE over long time spans.","distractor_reasons":{"A":"Incorrect because current liabilities remain on the statement of financial position regardless of inflation.","B":"Incorrect because multi-year ratio analysis is completely legal and common.","C":"Option C is correct because inflation inflates current prices and profits relative to historical asset book values, artificially boosting ROCE over long time spans.","D":"Incorrect because inflation raises both costs and revenues rather than making gross profit margin 100%."}}},{"id":"P1_U5_MCQ_250","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_250","question":"A company reports an impressive ROCE of 22% and a profit margin of 16%, but published accounts provide no details on its high staff turnover, polluting factory emissions, or falling customer loyalty scores. Which major limitation of accounting ratios does this illustrate?","options":{"A":"Financial accounts only measure quantitative historical numbers and ignore crucial qualitative non-financial factors that threaten long-term success","B":"Published accounts are forbidden from reporting profit margins above 10%","C":"Ratios only use forecast numbers from future years rather than real data","D":"ROCE and profit margin cannot be calculated for manufacturing companies"},"correctOption":"A","correctAnswer":"Financial accounts only measure quantitative historical numbers and ignore crucial qualitative non-financial factors that threaten long-term success","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ratio analysis relies exclusively on historical financial figures and overlooks qualitative factors like workforce morale, environmental impact, and brand reputation.","distractor_reasons":{"A":"Option A is correct because ratio analysis relies exclusively on historical financial figures and overlooks qualitative factors like workforce morale, environmental impact, and brand reputation.","B":"Incorrect because there is no legal cap on reported profit margins.","C":"Incorrect because published financial ratios are calculated from historical past accounts, not future forecasts.","D":"Incorrect because ROCE and profit margin are routinely calculated for manufacturing firms."}}},{"id":"P1_U5_MCQ_251","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_251","question":"Two software engineers are leaving their jobs to form a private limited company developing educational games. They need $40,000 to register the company, buy high-specification computers, and rent an office before releasing their first game. What type of finance do they need?","options":{"A":"Working capital","B":"Start-up capital","C":"Trade credit","D":"Debt factoring"},"correctOption":"B","correctAnswer":"Start-up capital","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because start-up capital is the finance required by entrepreneurs to pay for initial set-up costs and essential non-current assets before a new business starts trading.","distractor_reasons":{"A":"Incorrect because working capital covers ongoing day-to-day running expenses once trading is underway.","B":"Option B is correct because start-up capital is the finance required by entrepreneurs to pay for initial set-up costs and essential non-current assets before a new business starts trading.","C":"Incorrect because trade credit is delayed payment on inventory purchased from suppliers.","D":"Incorrect because debt factoring sells unpaid customer invoices for immediate cash."}}},{"id":"P1_U5_MCQ_252","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_252","question":"A thriving regional supermarket chain plans to buy out a smaller competitor with 12 stores and build a new automated cold-storage hub. Which financial need is driving this capital requirement?","options":{"A":"Funding long-term business expansion","B":"Paying weekly cashier wages","C":"Covering a three-day bank timing gap","D":"Replacing a broken checkout scanner"},"correctOption":"A","correctAnswer":"Funding long-term business expansion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because acquiring rival businesses and building major distribution facilities require substantial long-term expansion capital.","distractor_reasons":{"A":"Option A is correct because acquiring rival businesses and building major distribution facilities require substantial long-term expansion capital.","B":"Incorrect because weekly wages are short-term working capital expenses.","C":"Incorrect because a three-day cash gap is a temporary working capital timing issue.","D":"Incorrect because replacing a single scanner is minor routine equipment maintenance."}}},{"id":"P1_U5_MCQ_253","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_253","question":"A busy print shop has plenty of profitable orders from corporate clients, but it lacks cash to buy paper rolls and pay electricity bills because clients take 45 days to pay. Which financial need does this highlight?","options":{"A":"Start-up capital for premises","B":"Long-term capital for international takeovers","C":"Working capital for day-to-day trading operations","D":"Capital for buying freehold land"},"correctOption":"C","correctAnswer":"Working capital for day-to-day trading operations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because working capital is needed to pay routine running costs such as raw materials and utility bills while waiting for credit customers to pay.","distractor_reasons":{"A":"Incorrect because the print shop is already an established trading business.","B":"Incorrect because international takeovers require long-term expansion finance, not money for paper and electricity.","C":"Option C is correct because working capital is needed to pay routine running costs such as raw materials and utility bills while waiting for credit customers to pay.","D":"Incorrect because freehold land is a long-term non-current asset."}}},{"id":"P1_U5_MCQ_254","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_254","question":"A profitable food-packaging company has accumulated $350,000 in retained profit over the last four years and uses $280,000 of it to buy a new automated laminating machine. What is a major advantage of using retained profit for this purchase?","options":{"A":"It does not have to be repaid and incurs zero interest charges","B":"It increases the company's non-current liabilities","C":"It gives the company's bank a share of future profits","D":"It guarantees lower corporation tax next year"},"correctOption":"A","correctAnswer":"It does not have to be repaid and incurs zero interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit is an internal source of finance that carries no interest payments, arrangement fees, or repayment deadlines.","distractor_reasons":{"A":"Option A is correct because retained profit is an internal source of finance that carries no interest payments, arrangement fees, or repayment deadlines.","B":"Incorrect because using internal retained profit creates no external loan debt.","C":"Incorrect because retained profit comes from inside the business without involving a bank.","D":"Incorrect because funding machinery from retained profit does not automatically lower tax rates."}}},{"id":"P1_U5_MCQ_255","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_255","question":"A haulage company upgrades its fleet and sells four older trucks that are no longer needed, raising $68,000 in cash to help pay for a new warehouse loading bay. Which type of finance is this?","options":{"A":"External short-term finance","B":"Internal finance from the sale of unwanted assets","C":"External equity finance","D":"Working capital reduction"},"correctOption":"B","correctAnswer":"Internal finance from the sale of unwanted assets","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because selling surplus non-current assets such as old trucks generates cash internally without borrowing or issuing shares.","distractor_reasons":{"A":"Incorrect because the cash comes from selling the company's own assets rather than external borrowing.","B":"Option B is correct because selling surplus non-current assets such as old trucks generates cash internally without borrowing or issuing shares.","C":"Incorrect because no shares were issued to external investors.","D":"Incorrect because trucks are non-current assets, whereas working capital relates to current assets like inventory."}}},{"id":"P1_U5_MCQ_256","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_256","question":"A home-appliance wholesaler needs $45,000 to pay for a software upgrade and decides to raise the cash internally by tightening credit collection from retail stores and holding smaller warehouse stocks of washing machines. Which internal source of finance is being used?","options":{"A":"Sale of non-current assets","B":"Retained profit","C":"Owners' personal savings","D":"Reducing working capital"},"correctOption":"D","correctAnswer":"Reducing working capital","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because converting trade receivables and excess inventory into cash frees up funds tied up in working capital.","distractor_reasons":{"A":"Incorrect because washing machine inventory is a current asset, not a non-current asset.","B":"Incorrect because retained profit comes from past profits rather than releasing cash from inventory and receivables.","C":"Incorrect because the owners did not inject new personal money into the business.","D":"Option D is correct because converting trade receivables and excess inventory into cash frees up funds tied up in working capital."}}},{"id":"P1_U5_MCQ_257","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_257","question":"A sole trader running a mobile car-valeting van needs $8,000 to buy a second van and decides to invest $8,000 from her personal savings account. What is a common limitation of relying on owners' investment as a source of finance?","options":{"A":"The owner must pay high monthly interest to the bank","B":"The amount of personal savings available to owners is often limited","C":"The sole trader loses decision-making control to external investors","D":"Personal savings can only be used to pay utility bills"},"correctOption":"B","correctAnswer":"The amount of personal savings available to owners is often limited","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because individual owners usually have limited personal wealth, restricting how much finance can be raised internally for major expansion.","distractor_reasons":{"A":"Incorrect because owners' investment is internal and incurs no interest charges.","B":"Option B is correct because individual owners usually have limited personal wealth, restricting how much finance can be raised internally for major expansion.","C":"Incorrect because investing personal savings keeps 100% control with the sole trader.","D":"Incorrect because owners' investment can be used for any business purpose, including buying vehicles."}}},{"id":"P1_U5_MCQ_258","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_258","question":"A large public limited supermarket group wants to raise $60 million to build a national automated distribution network without taking on any new debt. Why is issuing new ordinary shares on the stock exchange suitable for this goal?","options":{"A":"It allows the company to avoid publishing annual financial statements","B":"It guarantees that existing shareholders retain the exact same percentage of voting control","C":"It requires zero legal fees or administrative paperwork","D":"It can raise very large sums of permanent capital with no repayment date and no contractual interest charges"},"correctOption":"D","correctAnswer":"It can raise very large sums of permanent capital with no repayment date and no contractual interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because public share issues allow plcs to raise substantial long-term funds permanently without fixed interest obligations.","distractor_reasons":{"A":"Incorrect because all public limited companies must publish audited annual accounts.","B":"Incorrect because issuing new shares to the public dilutes the ownership percentage of existing shareholders.","C":"Incorrect because a public share issue is costly and requires extensive legal and regulatory compliance.","D":"Option D is correct because public share issues allow plcs to raise substantial long-term funds permanently without fixed interest obligations."}}},{"id":"P1_U5_MCQ_259","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_259","question":"Why is a private limited company (Ltd) unable to raise finance by selling shares to the general public on a stock exchange?","options":{"A":"Private limited companies have unlimited liability","B":"Private limited companies are legally restricted to selling shares privately with the agreement of existing shareholders","C":"Private limited companies are not permitted to make a profit","D":"Private limited companies can only use internal sources of finance"},"correctOption":"B","correctAnswer":"Private limited companies are legally restricted to selling shares privately with the agreement of existing shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because legal restrictions prevent private limited companies from offering shares to the public; only public limited companies (plcs) can list on a stock exchange.","distractor_reasons":{"A":"Incorrect because shareholders in both private and public limited companies have limited liability.","B":"Option B is correct because legal restrictions prevent private limited companies from offering shares to the public; only public limited companies (plcs) can list on a stock exchange.","C":"Incorrect because private limited companies are private sector profit-seeking businesses.","D":"Incorrect because private limited companies can use external debt, leasing, grants, and private share issues."}}},{"id":"P1_U5_MCQ_260","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_260","question":"A restaurant group borrows $200,000 from a bank to refurbish four restaurants, agreeing to repay the amount in fixed monthly instalments over six years. What is a potential disadvantage of this bank loan?","options":{"A":"The loan must be repaid in full within 30 days","B":"The bank becomes a 50% owner of the restaurant group","C":"Interest must be paid regularly regardless of whether the restaurants make a profit, and collateral is usually required","D":"The restaurant group cannot claim loan interest as a business expense"},"correctOption":"C","correctAnswer":"Interest must be paid regularly regardless of whether the restaurants make a profit, and collateral is usually required","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because bank loans impose mandatory interest and repayment commitments even during weak trading periods, and banks typically require assets as security.","distractor_reasons":{"A":"Incorrect because a six-year bank loan is repaid over six years, unlike an on-demand overdraft.","B":"Incorrect because lenders do not take equity ownership when granting a loan.","C":"Option C is correct because bank loans impose mandatory interest and repayment commitments even during weak trading periods, and banks typically require assets as security.","D":"Incorrect because interest paid is a legitimate business expense."}}},{"id":"P1_U5_MCQ_261","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_261","question":"A florist faces fluctuating weekly cash balances, occasionally dipping -$1,500 into the negative for ten days before corporate clients pay their monthly bills. Why is a bank overdraft better suited than a bank loan for this situation?","options":{"A":"An overdraft is flexible, allowing the florist to borrow only when needed and pay interest only for the ten days overdrawn","B":"An overdraft has a lower interest rate than a secured mortgage","C":"An overdraft never has to be repaid","D":"An overdraft is recorded as a non-current asset"},"correctOption":"A","correctAnswer":"An overdraft is flexible, allowing the florist to borrow only when needed and pay interest only for the ten days overdrawn","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an overdraft is tailored to short-term, fluctuating working capital gaps and charges interest strictly on the daily overdrawn amount.","distractor_reasons":{"A":"Option A is correct because an overdraft is tailored to short-term, fluctuating working capital gaps and charges interest strictly on the daily overdrawn amount.","B":"Incorrect because overdraft interest rates are normally higher than secured long-term loan rates.","C":"Incorrect because an overdraft is a repayable short-term liability.","D":"Incorrect because an overdrawn bank balance is a current liability."}}},{"id":"P1_U5_MCQ_262","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_262","question":"A hardware store buys $15,000 of paint and tools from a wholesaler with 45 days to pay the invoice. How does this trade credit benefit the hardware store?","options":{"A":"It acts as a short-term, usually interest-free source of finance that lets the store sell the goods before paying the supplier","B":"It permanently reduces the store's cost of sales to zero","C":"It allows the store to buy freehold shop premises on 10-year terms","D":"It increases the store's shareholders' equity"},"correctOption":"A","correctAnswer":"It acts as a short-term, usually interest-free source of finance that lets the store sell the goods before paying the supplier","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade credit delays cash outflows for inventory, giving the retailer time to generate cash from sales first.","distractor_reasons":{"A":"Option A is correct because trade credit delays cash outflows for inventory, giving the retailer time to generate cash from sales first.","B":"Incorrect because the goods must still be paid for after 45 days, so cost of sales is unchanged.","C":"Incorrect because trade credit applies only to short-term purchases of raw materials or goods for resale.","D":"Incorrect because trade credit creates a current liability (trade payable), not equity."}}},{"id":"P1_U5_MCQ_263","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_263","question":"An accounting firm needs 40 new desktop computers and chooses to lease them for three years rather than buying them outright. What happens to the computers at the end of the 3-year lease agreement?","options":{"A":"They remain the property of the leasing company, and the firm can return them or upgrade to newer models","B":"They automatically become the permanent legal property of the accounting firm","C":"They are transferred to the government as tax payment","D":"They are recorded as trade receivables on the firm's accounts"},"correctOption":"A","correctAnswer":"They remain the property of the leasing company, and the firm can return them or upgrade to newer models","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because under a lease, legal ownership never transfers to the user; the leasing company owns the asset and often replaces it with updated equipment at renewal.","distractor_reasons":{"A":"Option A is correct because under a lease, legal ownership never transfers to the user; the leasing company owns the asset and often replaces it with updated equipment at renewal.","B":"Incorrect because transfer of ownership upon final payment is a feature of hire purchase, not leasing.","C":"Incorrect because leased assets belong to the finance/leasing company.","D":"Incorrect because trade receivables represent money owed by customers."}}},{"id":"P1_U5_MCQ_264","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_264","question":"A farmer acquires a $70,000 tractor through a hire purchase agreement over five years. What is a disadvantage of using hire purchase compared with buying the tractor outright with retained profit?","options":{"A":"Total payments over five years will exceed $70,000 because interest charges are added to the instalments","B":"The farmer never gains legal ownership of the tractor even after paying all instalments","C":"Hire purchase requires giving up voting shares in the farm","D":"The farmer cannot use the tractor until the final instalment is paid"},"correctOption":"A","correctAnswer":"Total payments over five years will exceed $70,000 because interest charges are added to the instalments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because hire purchase includes finance/interest charges in the regular instalments, making the total cost higher than paying cash upfront.","distractor_reasons":{"A":"Option A is correct because hire purchase includes finance/interest charges in the regular instalments, making the total cost higher than paying cash upfront.","B":"Incorrect because under hire purchase, legal ownership passes to the buyer once the final payment is completed.","C":"Incorrect because hire purchase is asset-backed instalment credit, not equity finance.","D":"Incorrect because the buyer uses the asset immediately upon paying the initial deposit."}}},{"id":"P1_U5_MCQ_265","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_265","question":"A small group of female artisans in a developing rural town needs $600 to buy looms and natural dyes to start a weaving cooperative, but commercial banks reject their application due to lack of collateral. Which source of finance is designed specifically for this situation?","options":{"A":"Commercial trade credit","B":"Issuing ordinary shares on a stock exchange","C":"Venture capital","D":"Microfinance"},"correctOption":"D","correctAnswer":"Microfinance","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because microfinance provides small loans to low-income entrepreneurs who lack collateral and cannot access traditional commercial banks.","distractor_reasons":{"A":"Incorrect because new rural cooperatives without a trading record rarely qualify for supplier trade credit.","B":"Incorrect because stock exchange listings are only for large public limited companies.","C":"Incorrect because venture capitalists invest large sums into high-growth scalable firms.","D":"Option D is correct because microfinance provides small loans to low-income entrepreneurs who lack collateral and cannot access traditional commercial banks."}}},{"id":"P1_U5_MCQ_266","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_266","question":"An inventor designs a smart water bottle and raises $45,000 online from 900 individuals who each contribute $50 in advance to receive one of the first bottles produced. What is a potential disadvantage of using crowdfunding in this way?","options":{"A":"Publishing the product design online before launch may allow competitors to copy the idea, and if the funding target is missed, no money may be received","B":"The inventor must pay 25% monthly interest to a commercial bank","C":"Crowdfunding is illegal for start-up businesses","D":"The inventor must immediately repay all $45,000 in cash within seven days"},"correctOption":"A","correctAnswer":"Publishing the product design online before launch may allow competitors to copy the idea, and if the funding target is missed, no money may be received","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because crowdfunding exposes innovative concepts publicly before patenting/launch and carries the risk of failing to reach the campaign target.","distractor_reasons":{"A":"Option A is correct because crowdfunding exposes innovative concepts publicly before patenting/launch and carries the risk of failing to reach the campaign target.","B":"Incorrect because reward-based crowdfunding does not involve commercial bank interest.","C":"Incorrect because crowdfunding is a widely used legal funding method for start-ups.","D":"Incorrect because backers receive the promised product reward rather than cash repayment."}}},{"id":"P1_U5_MCQ_267","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_267","question":"A promising clean-tech private limited company has developed a new battery recycling process and receives $2 million from a venture capital firm. Why might the founders hesitate before accepting venture capital?","options":{"A":"Venture capitalists require the company to repay the $2 million within 30 days","B":"Venture capitalists demand a significant share of ownership and influence over major business decisions","C":"Venture capitalists provide zero business advice or industry contacts","D":"Venture capital can only be used to buy office stationery"},"correctOption":"B","correctAnswer":"Venture capitalists demand a significant share of ownership and influence over major business decisions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because venture capitalists invest in return for an equity stake and board influence, meaning founders give up partial ownership and autonomy.","distractor_reasons":{"A":"Incorrect because venture capital is long-term equity investment rather than a 30-day loan.","B":"Option B is correct because venture capitalists invest in return for an equity stake and board influence, meaning founders give up partial ownership and autonomy.","C":"Incorrect because providing specialist expertise and contacts is actually an advantage of venture capital.","D":"Incorrect because venture capital funds major growth, R&D, and expansion."}}},{"id":"P1_U5_MCQ_268","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_268","question":"An automotive components manufacturer builds a new research centre in a high-unemployment region and receives a $150,000 government grant. Why is a government grant attractive compared with a bank loan?","options":{"A":"It does not need to be repaid and incurs no interest, provided the manufacturer meets the grant's job-creation conditions","B":"It is guaranteed to be approved within 24 hours for every applicant","C":"It has no conditions attached and can be spent on executive bonuses","D":"It gives the government permanent ownership of the factory"},"correctOption":"A","correctAnswer":"It does not need to be repaid and incurs no interest, provided the manufacturer meets the grant's job-creation conditions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because government grants are non-repayable subsidies designed to encourage regional investment, training, or innovation when specific criteria are met.","distractor_reasons":{"A":"Option A is correct because government grants are non-repayable subsidies designed to encourage regional investment, training, or innovation when specific criteria are met.","B":"Incorrect because grant applications are competitive and often involve lengthy approval processes.","C":"Incorrect because grants have strict conditions on how the money is spent.","D":"Incorrect because grants do not transfer private business ownership to the state."}}},{"id":"P1_U5_MCQ_269","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_269","question":"A bakery needs $3,000 to pay flour suppliers this week and $180,000 to buy an adjacent shop unit for long-term expansion. Which pairing correctly matches the time period and source of finance for these two needs?","options":{"A":"Overdraft or trade credit for the $3,000; long-term bank loan or retained profit for the $180,000","B":"Issuing shares on the stock exchange for the $3,000; 30-day trade credit for the $180,000","C":"15-year mortgage for the $3,000; bank overdraft for the $180,000","D":"Hire purchase for the $3,000; microfinance for the $180,000"},"correctOption":"A","correctAnswer":"Overdraft or trade credit for the $3,000; long-term bank loan or retained profit for the $180,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because short-term working capital ($3,000) should be funded by short-term sources (overdraft/trade credit), while a long-term property purchase ($180,000) requires long-term finance.","distractor_reasons":{"A":"Option A is correct because short-term working capital ($3,000) should be funded by short-term sources (overdraft/trade credit), while a long-term property purchase ($180,000) requires long-term finance.","B":"Incorrect because share issues are for massive long-term sums and trade credit cannot buy property.","C":"Incorrect because this reverses short-term and long-term finance matching.","D":"Incorrect because hire purchase is for physical equipment and microfinance provides very small loans."}}},{"id":"P1_U5_MCQ_270","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_270","question":"Which of the following is an example of working capital?","options":{"A":"Proceeds from selling a company patent","B":"Money borrowed to construct a new factory","C":"Cash used to pay weekly wages and buy stock","D":"Shares issued to new investors"},"correctOption":"C","correctAnswer":"Cash used to pay weekly wages and buy stock","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because working capital is the day-to-day finance needed for items such as wages, stock and other short-term operating costs.","distractor_reasons":{"A":"Incorrect because selling a patent is a one-off disposal of a non-current asset rather than routine working capital.","B":"Incorrect because borrowing to build a factory finances a long-term non-current asset, not day-to-day operations.","C":"Option C is correct because working capital is the day-to-day finance needed for items such as wages, stock and other short-term operating costs.","D":"Incorrect because issuing shares raises long-term equity finance and does not describe working capital."}}},{"id":"P1_U5_MCQ_271","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_271","question":"A small partnership running two dental surgeries wants to raise $90,000 for new X-ray equipment. Why is issuing shares on a stock exchange NOT an option for this business?","options":{"A":"Stock exchanges only lend money for 30 days","B":"Dental equipment cannot be financed using external sources","C":"Partnerships are legally required to use only microfinance","D":"Legal form: partnerships are unincorporated and cannot issue shares"},"correctOption":"D","correctAnswer":"Legal form: partnerships are unincorporated and cannot issue shares","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a business's legal structure determines its finance options; only incorporated public limited companies can offer shares on a stock exchange.","distractor_reasons":{"A":"Incorrect because share capital raised on a stock exchange is permanent long-term finance.","B":"Incorrect because dental surgeries can use bank loans, leasing, or hire purchase.","C":"Incorrect because partnerships have access to standard commercial bank finance.","D":"Option D is correct because a business's legal structure determines its finance options; only incorporated public limited companies can offer shares on a stock exchange."}}},{"id":"P1_U5_MCQ_272","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_272","question":"A small courier firm obtains its delivery vans by leasing them instead of buying them outright. What is the main advantage of leasing for this firm?","options":{"A":"It removes all financial risk from the business","B":"It gives the firm legal ownership of the vans straight away","C":"It always reduces the total amount paid over the vehicles' lives","D":"It avoids a large immediate cash outlay while still providing use of the vans"},"correctOption":"D","correctAnswer":"It avoids a large immediate cash outlay while still providing use of the vans","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because leasing spreads the cost into regular payments, preserving cash while allowing the firm to use the asset.","distractor_reasons":{"A":"Incorrect because the firm still has contractual payment obligations, so financial risk is not removed.","B":"Incorrect because with a lease the lessor normally retains ownership; the firm only rents the use of the vans.","C":"Incorrect because leasing can cost more overall than buying, so it does not guarantee lower total payments.","D":"Option D is correct because leasing spreads the cost into regular payments, preserving cash while allowing the firm to use the asset."}}},{"id":"P1_U5_MCQ_273","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_273","question":"A tech start-up needs $5,000 for an urgent server upgrade. Why would the finance manager choose a bank overdraft or retained profit over a public share issue?","options":{"A":"Overdrafts never incur any interest charges","B":"Tech companies are not allowed to have shareholders","C":"The amount needed is too small to justify the high legal, administrative, and underwriting costs of issuing shares","D":"Server upgrades are paid for by government tax refunds"},"correctOption":"C","correctAnswer":"The amount needed is too small to justify the high legal, administrative, and underwriting costs of issuing shares","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the amount required ($5,000) is a key factor; issuing shares is slow and expensive and only worthwhile for raising large sums.","distractor_reasons":{"A":"Incorrect because overdrafts do charge interest on overdrawn balances.","B":"Incorrect because incorporated tech companies do have shareholders.","C":"Option C is correct because the amount required ($5,000) is a key factor; issuing shares is slow and expensive and only worthwhile for raising large sums.","D":"Incorrect because businesses pay for their own IT upgrades."}}},{"id":"P1_U5_MCQ_274","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_274","question":"Which list contains ONLY external sources of finance?","options":{"A":"Bank loan, trade credit, leasing, and venture capital","B":"Retained profit, bank loan, sale of unwanted assets, and overdraft","C":"Owners' savings, retained profit, and reducing inventory","D":"Sale of surplus land, hire purchase, and government grant"},"correctOption":"A","correctAnswer":"Bank loan, trade credit, leasing, and venture capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bank loans, trade credit, leasing, and venture capital all obtain funds from outside the business.","distractor_reasons":{"A":"Option A is correct because bank loans, trade credit, leasing, and venture capital all obtain funds from outside the business.","B":"Incorrect because retained profit and sale of unwanted assets are internal sources.","C":"Incorrect because owners' savings, retained profit, and reducing inventory are all internal sources.","D":"Incorrect because selling surplus land is an internal source of finance."}}},{"id":"P1_U5_MCQ_275","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_275","question":"A logistics company raises $320,000 to build a new depot: $110,000 from retained profit, $30,000 from selling old forklifts, $140,000 from a 7-year bank loan, and $40,000 from a regional development grant. How much finance was raised from internal sources?","options":{"A":"$140,000","B":"$180,000","C":"$110,000","D":"$320,000"},"correctOption":"A","correctAnswer":"$140,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal sources are retained profit ($110,000) plus the sale of old forklifts ($30,000) = $140,000 (while the loan and grant are external).","distractor_reasons":{"A":"Option A is correct because internal sources are retained profit ($110,000) plus the sale of old forklifts ($30,000) = $140,000 (while the loan and grant are external).","B":"Incorrect because $180,000 is the sum of the external sources ($140,000 bank loan + $40,000 grant).","C":"Incorrect because $110,000 omits the $30,000 raised from selling old forklifts.","D":"Incorrect because $320,000 is the total of all internal and external finance combined."}}},{"id":"P1_U5_MCQ_276","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_276","question":"A newly launched furniture maker has full order books and high projected profits, yet it goes bankrupt in Month 4 because it cannot pay carpenters' weekly wages or timber bills. What does this illustrate?","options":{"A":"High profit automatically prevents any cash outflows","B":"Profitable businesses never need to monitor their bank balances","C":"Wages and timber can be paid using unpaid customer invoices","D":"Cash is essential to pay day-to-day obligations as they fall due; lack of cash causes insolvency even in profitable firms"},"correctOption":"D","correctAnswer":"Cash is essential to pay day-to-day obligations as they fall due; lack of cash causes insolvency even in profitable firms","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because businesses must hold enough liquid cash to pay immediate bills like wages and suppliers; without cash, a business cannot continue operating.","distractor_reasons":{"A":"Incorrect because producing goods requires immediate cash outflows for labour and materials.","B":"Incorrect because profitable firms frequently suffer cash crises if credit customers pay slowly.","C":"Incorrect because employees and suppliers require payment in cash, not uncollected receivables.","D":"Option D is correct because businesses must hold enough liquid cash to pay immediate bills like wages and suppliers; without cash, a business cannot continue operating."}}},{"id":"P1_U5_MCQ_277","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_277","question":"What is the main purpose of preparing a cash flow forecast before starting a new business?","options":{"A":"To estimate future monthly cash inflows and outflows so potential cash shortages can be spotted early and financing arranged","B":"To calculate the historical corporation tax paid over the last five years","C":"To record the exact resale value of all non-current assets at year-end","D":"To replace the legal requirement to keep sales receipts"},"correctOption":"A","correctAnswer":"To estimate future monthly cash inflows and outflows so potential cash shortages can be spotted early and financing arranged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a cash flow forecast predicts expected cash receipts and payments month by month, helping founders and banks plan overdrafts or loans before deficits occur.","distractor_reasons":{"A":"Option A is correct because a cash flow forecast predicts expected cash receipts and payments month by month, helping founders and banks plan overdrafts or loans before deficits occur.","B":"Incorrect because a start-up has no historical tax records and a forecast looks forward.","C":"Incorrect because assets at a point in time are shown on a statement of financial position.","D":"Incorrect because businesses must still keep accurate accounting records of all transactions."}}},{"id":"P1_U5_MCQ_278","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_278","question":"During July, a sports equipment shop makes $18,000 in cash sales, sells $12,000 of goods to schools on 30-day credit, collects $9,500 from June credit customers, and pays $14,000 for rent and wages. What are the shop's total cash inflows in July?","options":{"A":"$30,000","B":"$27,500","C":"$39,500","D":"$13,500"},"correctOption":"B","correctAnswer":"$27,500","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because July cash inflows include actual cash received in July: $18,000 cash sales + $9,500 collected from June credit customers = $27,500 (July credit sales arrive in August).","distractor_reasons":{"A":"Incorrect because $30,000 adds July cash sales and July unpaid credit sales ($18,000 + $12,000).","B":"Option B is correct because July cash inflows include actual cash received in July: $18,000 cash sales + $9,500 collected from June credit customers = $27,500 (July credit sales arrive in August).","C":"Incorrect because $39,500 wrongly includes the $12,000 unpaid July credit sales.","D":"Incorrect because $13,500 is net cash flow ($27,500 inflows - $14,000 outflows), not total cash inflows."}}},{"id":"P1_U5_MCQ_279","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_279","question":"In August, a bakery pays $7,200 in wages, pays $3,800 to flour suppliers for July's credit delivery, orders $4,500 of sugar on 30-day trade credit, and pays $1,500 in electricity bills. What are the bakery's total cash outflows in August?","options":{"A":"$12,500","B":"$17,000","C":"$13,200","D":"$8,700"},"correctOption":"A","correctAnswer":"$12,500","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because August cash outflows include actual cash payments made in August: $7,200 wages + $3,800 paid for July flour + $1,500 electricity = $12,500 (August's sugar order is paid in September).","distractor_reasons":{"A":"Option A is correct because August cash outflows include actual cash payments made in August: $7,200 wages + $3,800 paid for July flour + $1,500 electricity = $12,500 (August's sugar order is paid in September).","B":"Incorrect because $17,000 wrongly includes the $4,500 sugar ordered on 30-day credit.","C":"Incorrect because $13,200 uses August's $4,500 credit order instead of July's $3,800 invoice paid in August.","D":"Incorrect because $8,700 omits the $3,800 payment to flour suppliers."}}},{"id":"P1_U5_MCQ_280","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_280","question":"A wholesale distributor sells $50,000 of goods in March and $60,000 in April. Customers pay 40% in cash immediately and 60% one month later. What is the distributor's total cash inflow from sales in April?","options":{"A":"$24,000","B":"$60,000","C":"$54,000","D":"$56,000"},"correctOption":"C","correctAnswer":"$54,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because April cash inflows consist of 40% of April sales paid immediately ($24,000) plus 60% of March sales collected one month later ($30,000) = $54,000.","distractor_reasons":{"A":"Incorrect because $24,000 only counts April immediate cash sales and ignores March credit receipts.","B":"Incorrect because $60,000 is total April sales revenue, 60% of which is collected in May.","C":"Option C is correct because April cash inflows consist of 40% of April sales paid immediately ($24,000) plus 60% of March sales collected one month later ($30,000) = $54,000.","D":"Incorrect because $56,000 reverses the percentages (60% of April + 40% of March)."}}},{"id":"P1_U5_MCQ_281","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_281","question":"In October, a garden centre forecasts total cash inflows of $33,400 and total cash outflows of $29,150, with an opening balance of $4,000. What is the forecast net cash flow for October?","options":{"A":"-$4,250","B":"$8,250","C":"$4,250","D":"$62,550"},"correctOption":"C","correctAnswer":"$4,250","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Net cash flow = Cash inflows - Cash outflows ($33,400 - $29,150 = $4,250).","distractor_reasons":{"A":"Incorrect because inflows exceed outflows, making net cash flow positive.","B":"Incorrect because $8,250 is the closing balance ($4,000 opening + $4,250 net cash flow), not the net cash flow.","C":"Option C is correct because Net cash flow = Cash inflows - Cash outflows ($33,400 - $29,150 = $4,250).","D":"Incorrect because $62,550 adds inflows and outflows together."}}},{"id":"P1_U5_MCQ_282","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_282","question":"A boutique hotel starts May with an opening cash balance of $7,500. During May, total cash inflows are $41,000 and total cash outflows are $44,800. What is the hotel's closing cash balance at the end of May?","options":{"A":"-$3,700","B":"-$3,800","C":"$11,300","D":"$3,700"},"correctOption":"D","correctAnswer":"$3,700","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because May net cash flow = $41,000 - $44,800 = -$3,800, and Closing balance = Opening balance + Net cash flow ($7,500 + (-$3,800) = $3,700).","distractor_reasons":{"A":"Incorrect because $7,500 - $3,800 leaves a positive balance of +$3,700.","B":"Incorrect because -$3,800 is the net cash flow and ignores the $7,500 opening balance.","C":"Incorrect because $11,300 adds the $3,800 deficit instead of subtracting it.","D":"Option D is correct because May net cash flow = $41,000 - $44,800 = -$3,800, and Closing balance = Opening balance + Net cash flow ($7,500 + (-$3,800) = $3,700)."}}},{"id":"P1_U5_MCQ_283","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_283","question":"A courier firm starts March with an overdrawn opening balance of -$1,900. During March, cash inflows are $26,500 and cash outflows are $23,800. What is the firm's closing cash balance at the end of March?","options":{"A":"$800","B":"$2,700","C":"$4,600","D":"-$4,600"},"correctOption":"A","correctAnswer":"$800","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because March net cash flow = $26,500 - $23,800 = +$2,700, and adding this to the -$1,900 overdrawn opening balance gives a positive closing balance of $800.","distractor_reasons":{"A":"Option A is correct because March net cash flow = $26,500 - $23,800 = +$2,700, and adding this to the -$1,900 overdrawn opening balance gives a positive closing balance of $800.","B":"Incorrect because $2,700 is the net cash flow and ignores the -$1,900 opening overdraft.","C":"Incorrect because $4,600 treats the -$1,900 overdraft as a positive opening balance (+$1,900 + $2,700).","D":"Incorrect because -$4,600 subtracts the positive net cash flow from -$1,900."}}},{"id":"P1_U5_MCQ_284","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_284","question":"A café has an opening cash balance of $2,000 in June. In June, cash inflows are $15,000 and cash outflows are $16,500. In July, cash inflows are $18,000 and cash outflows are $14,200. What is the café's closing cash balance at the end of July?","options":{"A":"$4,300","B":"$500","C":"$3,800","D":"$7,300"},"correctOption":"A","correctAnswer":"$4,300","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because June closing balance = $2,000 + ($15,000 - $16,500) = $500, which becomes July's opening balance; July closing balance = $500 + ($18,000 - $14,200) = $4,300.","distractor_reasons":{"A":"Option A is correct because June closing balance = $2,000 + ($15,000 - $16,500) = $500, which becomes July's opening balance; July closing balance = $500 + ($18,000 - $14,200) = $4,300.","B":"Incorrect because $500 is June's closing balance (July's opening balance), not July's closing balance.","C":"Incorrect because $3,800 is July's net cash flow alone and ignores the $500 opening balance.","D":"Incorrect because $7,300 adds June's $1,500 deficit instead of subtracting it."}}},{"id":"P1_U5_MCQ_285","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_285","question":"A clothing store forecasts September inflows of $30,000, outflows of $27,000, and an opening balance of $1,500. If an unexpected repair bill increases September outflows by 20%, what will the new September closing balance be?","options":{"A":"-$2,400","B":"$4,500","C":"-$900","D":"$9,900"},"correctOption":"C","correctAnswer":"-$900","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a 20% rise increases outflows from $27,000 to $32,400 ($27,000 × 1.2); net cash flow becomes $30,000 - $32,400 = -$2,400, and adding the $1,500 opening balance gives -$900.","distractor_reasons":{"A":"Incorrect because -$2,400 is the revised net cash flow and ignores the $1,500 opening balance.","B":"Incorrect because $4,500 is the original closing balance before the 20% cost increase.","C":"Option C is correct because a 20% rise increases outflows from $27,000 to $32,400 ($27,000 × 1.2); net cash flow becomes $30,000 - $32,400 = -$2,400, and adding the $1,500 opening balance gives -$900.","D":"Incorrect because $9,900 subtracts 20% from outflows instead of adding 20%."}}},{"id":"P1_U5_MCQ_286","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_286","question":"A toy manufacturer's cash flow forecast predicts closing balances of +$8,000 in August, -$3,200 in September, -$9,400 in October, -$4,100 in November, and +$12,000 in December. What is the minimum bank overdraft limit the manufacturer must arrange?","options":{"A":"$4,100","B":"$3,200","C":"$9,400","D":"$16,700"},"correctOption":"C","correctAnswer":"$9,400","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because closing balances are cumulative; the peak negative closing balance occurs in October at -$9,400, so the overdraft limit must be at least $9,400.","distractor_reasons":{"A":"Incorrect because $4,100 only covers November and falls short in October.","B":"Incorrect because $3,200 only covers September and would be exceeded in October and November.","C":"Option C is correct because closing balances are cumulative; the peak negative closing balance occurs in October at -$9,400, so the overdraft limit must be at least $9,400.","D":"Incorrect because $16,700 mistakenly adds all negative closing balances together, even though closing balances already carry forward month to month."}}},{"id":"P1_U5_MCQ_287","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_287","question":"To overcome a short-term cash deficit, an office supply company stops offering 60-day trade credit and requires all customers to pay within 14 days. What is a likely drawback of this action?","options":{"A":"Regular business customers may switch to competitors that still offer 60-day credit terms, reducing future sales","B":"The company's current liabilities will immediately double","C":"The company will have to pay higher interest to its suppliers","D":"Cash inflows will be delayed by an extra 46 days"},"correctOption":"A","correctAnswer":"Regular business customers may switch to competitors that still offer 60-day credit terms, reducing future sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tightening credit terms speeds up cash inflows from paying customers, but risks losing price- and credit-sensitive buyers to rivals.","distractor_reasons":{"A":"Option A is correct because tightening credit terms speeds up cash inflows from paying customers, but risks losing price- and credit-sensitive buyers to rivals.","B":"Incorrect because changing customer credit terms affects trade receivables, not supplier liabilities.","C":"Incorrect because customer credit policies do not alter supplier interest rates.","D":"Incorrect because shortening credit from 60 to 14 days accelerates cash inflows rather than delaying them."}}},{"id":"P1_U5_MCQ_288","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_288","question":"A restaurant facing a two-month cash shortfall delays paying its kitchen equipment and food suppliers by an extra 30 days without their agreement. What is a major risk of delaying supplier payments?","options":{"A":"Suppliers may refuse future deliveries, demand cash on delivery, or withdraw bulk discounts","B":"The restaurant's gross profit margin will immediately rise to 100%","C":"Customers will stop paying for their meals in cash","D":"The restaurant's non-current assets will lose all value"},"correctOption":"A","correctAnswer":"Suppliers may refuse future deliveries, demand cash on delivery, or withdraw bulk discounts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because paying suppliers late damages trust and can halt essential raw material deliveries.","distractor_reasons":{"A":"Option A is correct because paying suppliers late damages trust and can halt essential raw material deliveries.","B":"Incorrect because delaying payment does not reduce cost of sales to zero.","C":"Incorrect because supplier payment delays do not prevent restaurant diners from paying.","D":"Incorrect because late supplier payments do not erase non-current asset values."}}},{"id":"P1_U5_MCQ_289","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_289","question":"A wholesaler has $80,000 in unpaid customer invoices due in 60 days and needs cash immediately to pay staff wages. It sells the invoices to a debt factoring company for $68,000 cash today. How does debt factoring affect the business?","options":{"A":"It delays cash inflows by another 60 days","B":"It increases total profit by $12,000","C":"It forces the wholesaler to give up 50% of its ordinary shares","D":"It provides $68,000 of immediate cash inflow to solve the liquidity shortage, but reduces profit by $12,000 due to the factor's fee"},"correctOption":"D","correctAnswer":"It provides $68,000 of immediate cash inflow to solve the liquidity shortage, but reduces profit by $12,000 due to the factor's fee","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because debt factoring turns trade receivables into instant cash, but the finance firm keeps a percentage fee ($12,000), lowering overall profit.","distractor_reasons":{"A":"Incorrect because factoring accelerates cash collection immediately.","B":"Incorrect because receiving $68,000 for $80,000 of invoices reduces profit by $12,000 rather than increasing it.","C":"Incorrect because factoring involves selling invoices, not issuing shares.","D":"Option D is correct because debt factoring turns trade receivables into instant cash, but the finance firm keeps a percentage fee ($12,000), lowering overall profit."}}},{"id":"P1_U5_MCQ_290","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_290","question":"A haulage company experiencing temporary cash flow pressure decides to postpone replacing two five-year-old lorries until next year. How does this decision help short-term cash flow, and what is its main risk?","options":{"A":"It avoids large immediate capital cash outflows, but the older lorries may suffer costly breakdowns and delay customer deliveries","B":"It increases immediate cash inflows from customers, but reduces shareholders' equity","C":"It eliminates all fuel and driver wage expenses, but increases current liabilities","D":"It converts non-current assets into current liabilities"},"correctOption":"A","correctAnswer":"It avoids large immediate capital cash outflows, but the older lorries may suffer costly breakdowns and delay customer deliveries","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delaying capital expenditure keeps cash in the bank in the short run, though ageing vehicles risk higher repair costs and lower reliability.","distractor_reasons":{"A":"Option A is correct because delaying capital expenditure keeps cash in the bank in the short run, though ageing vehicles risk higher repair costs and lower reliability.","B":"Incorrect because postponing a purchase reduces cash outflows rather than increasing customer inflows.","C":"Incorrect because existing lorries still require fuel and drivers.","D":"Incorrect because delaying a purchase does not convert assets into liabilities."}}},{"id":"P1_U5_MCQ_291","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_291","question":"A furniture retailer has a forecast closing cash balance of -$7,500 at the end of November. Which action would help solve this November cash deficit?","options":{"A":"Extending customer credit periods from 30 days to 90 days","B":"Paying December's warehouse rent one month early in November","C":"Buying $10,000 of new display computers for cash in November","D":"Running a promotional clearance sale on slow-moving sofa inventory for cash"},"correctOption":"D","correctAnswer":"Running a promotional clearance sale on slow-moving sofa inventory for cash","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because selling existing inventory for cash generates immediate cash inflows without requiring new cash outflows for stock.","distractor_reasons":{"A":"Incorrect because extending customer credit delays cash inflows.","B":"Incorrect because paying rent early increases November cash outflows and worsens the deficit.","C":"Incorrect because buying computers for cash increases November outflows.","D":"Option D is correct because selling existing inventory for cash generates immediate cash inflows without requiring new cash outflows for stock."}}},{"id":"P1_U5_MCQ_292","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_292","question":"In Year 1, a commercial cleaning business earns $180,000 in revenue and incurs $120,000 in costs, reporting a profit of $60,000. However, its closing bank balance is -$15,000 because corporate clients owe $55,000 in unpaid invoices and the firm bought $30,000 of floor-polishing machines for cash. What does this demonstrate?","options":{"A":"A business can be profitable on its statement of profit or loss while simultaneously suffering a negative cash balance","B":"The accountant made an error because profit and closing cash must always be identical","C":"Equipment purchases are always deducted in full from gross profit","D":"Unpaid customer invoices are never counted as revenue"},"correctOption":"A","correctAnswer":"A business can be profitable on its statement of profit or loss while simultaneously suffering a negative cash balance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because credit revenue boosts profit before cash arrives, while cash spent on non-current equipment drains cash without reducing profit immediately.","distractor_reasons":{"A":"Option A is correct because credit revenue boosts profit before cash arrives, while cash spent on non-current equipment drains cash without reducing profit immediately.","B":"Incorrect because profit and cash flow measure different things and rarely equal each other.","C":"Incorrect because non-current equipment sits on the statement of financial position rather than being deducted from gross profit.","D":"Incorrect because credit sales are included in revenue when the service is delivered."}}},{"id":"P1_U5_MCQ_293","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_293","question":"A fashion retailer makes a trading loss of -$12,000 in February, yet its bank balance rises by +$28,000 during February. Which event explains how a loss-making business can experience positive net cash flow?","options":{"A":"The retailer received a $45,000 long-term bank loan into its current account in February","B":"The retailer bought $45,000 of new shop fittings for cash in February","C":"All February customers bought clothes on 60-day credit","D":"The retailer paid off a $45,000 bank loan in February"},"correctOption":"A","correctAnswer":"The retailer received a $45,000 long-term bank loan into its current account in February","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receiving a bank loan is a cash inflow that boosts the bank balance even though loans are liabilities, not trading revenue.","distractor_reasons":{"A":"Option A is correct because receiving a bank loan is a cash inflow that boosts the bank balance even though loans are liabilities, not trading revenue.","B":"Incorrect because buying shop fittings for cash is a cash outflow that reduces the bank balance.","C":"Incorrect because selling on 60-day credit delays cash inflows and worsens February's cash flow.","D":"Incorrect because repaying a loan is a cash outflow."}}},{"id":"P1_U5_MCQ_294","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_294","question":"Why does a cash flow forecast become less reliable the further into the future it projects (for example, Month 11 compared with Month 1)?","options":{"A":"Banks prohibit businesses from forecasting beyond three months","B":"Cash outflows are legally excluded from forecasts after Month 6","C":"Opening balances reset to zero every six months","D":"Economic conditions, competitor actions, supplier prices, and customer demand become harder to predict accurately over longer periods"},"correctOption":"D","correctAnswer":"Economic conditions, competitor actions, supplier prices, and customer demand become harder to predict accurately over longer periods","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash flow forecasts rely on assumptions about future sales and costs, and uncertainty increases over longer time horizons.","distractor_reasons":{"A":"Incorrect because banks often require 12-month or multi-year cash flow forecasts for loans.","B":"Incorrect because all expected cash outflows are included throughout the forecast period.","C":"Incorrect because closing balances carry forward continuously from month to month.","D":"Option D is correct because cash flow forecasts rely on assumptions about future sales and costs, and uncertainty increases over longer time horizons."}}},{"id":"P1_U5_MCQ_295","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_295","question":"A gift-wrap printer experiences negative net cash flows every month from January to August while printing holiday stock, followed by huge positive net cash flows from September to December when retail chains pay for deliveries. What should the printer do?","options":{"A":"Issue new shares every single month from January to August","B":"Close the factory permanently in February because net cash flow is negative","C":"Stop printing gift wrap until September so no costs are incurred in spring","D":"Use the cash flow forecast to arrange a seasonal overdraft or working capital loan from January to August that is repaid from September–December receipts"},"correctOption":"D","correctAnswer":"Use the cash flow forecast to arrange a seasonal overdraft or working capital loan from January to August that is repaid from September–December receipts","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because predictable seasonal cash cycles are best managed by arranging planned short-term finance during production months and clearing it during peak sales receipts.","distractor_reasons":{"A":"Incorrect because issuing shares monthly is impractical, expensive, and unnecessary for a seasonal working capital cycle.","B":"Incorrect because the business is viable over the full year once seasonal sales receipts arrive.","C":"Incorrect because waiting until September to start printing would leave insufficient time to fulfill retail orders.","D":"Option D is correct because predictable seasonal cash cycles are best managed by arranging planned short-term finance during production months and clearing it during peak sales receipts."}}},{"id":"P1_U5_MCQ_296","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_296","question":"A small electronics company buys $20,000 of components in May on 60-day trade credit. In which month will this $20,000 be recorded as a cash outflow on its cash flow forecast?","options":{"A":"July","B":"May","C":"June","D":"August"},"correctOption":"A","correctAnswer":"July","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 60 days (two months) after May is July, when cash actually leaves the company's bank account to pay the supplier.","distractor_reasons":{"A":"Option A is correct because 60 days (two months) after May is July, when cash actually leaves the company's bank account to pay the supplier.","B":"Incorrect because May is when the order is received on credit, with no cash paid yet.","C":"Incorrect because June is only 30 days after May.","D":"Incorrect because August is 90 days after May."}}},{"id":"P1_U5_MCQ_297","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_297","question":"A restaurant owner is deciding whether to buy a $36,000 pizza oven outright for cash or acquire it via hire purchase with a $6,000 deposit and $600 monthly payments. How does choosing hire purchase improve the restaurant's Month 1 cash flow forecast?","options":{"A":"Month 1 cash outflows drop to $0","B":"Month 1 cash inflows increase by $36,000","C":"Month 1 cash outflows are $29,400 lower ($6,600 instead of $36,000), preserving immediate cash liquidity","D":"Hire purchase eliminates all future cash outflows for the oven"},"correctOption":"C","correctAnswer":"Month 1 cash outflows are $29,400 lower ($6,600 instead of $36,000), preserving immediate cash liquidity","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because paying $6,000 deposit plus the first $600 instalment ($6,600) instead of $36,000 cash saves $29,400 of cash in Month 1.","distractor_reasons":{"A":"Incorrect because the $6,000 deposit and $600 first instalment still leave the bank in Month 1.","B":"Incorrect because acquiring an oven involves cash outflows, not cash inflows.","C":"Option C is correct because paying $6,000 deposit plus the first $600 instalment ($6,600) instead of $36,000 cash saves $29,400 of cash in Month 1.","D":"Incorrect because monthly instalments continue as cash outflows over the agreement term."}}},{"id":"P1_U5_MCQ_298","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_298","question":"During a review of its quarterly cash flow forecast, a clothing manufacturer notices that actual cash outflows were $8,000 higher than forecast while actual cash inflows matched the forecast. What is the direct effect on the closing cash balance?","options":{"A":"The closing cash balance is $8,000 higher than originally forecast","B":"The closing cash balance is $8,000 lower than originally forecast","C":"The closing cash balance is unaffected because inflows matched the forecast","D":"The opening cash balance for that quarter increases by $8,000"},"correctOption":"B","correctAnswer":"The closing cash balance is $8,000 lower than originally forecast","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher cash outflows reduce net cash flow by $8,000, directly lowering the closing cash balance by $8,000.","distractor_reasons":{"A":"Incorrect because higher outflows drain cash rather than increasing the balance.","B":"Option B is correct because higher cash outflows reduce net cash flow by $8,000, directly lowering the closing cash balance by $8,000.","C":"Incorrect because net cash flow depends on both inflows and outflows.","D":"Incorrect because the opening balance at the start of the quarter is already fixed."}}},{"id":"P1_U5_MCQ_299","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_299","question":"Why do established businesses update their cash flow forecasts regularly (for example, every month) rather than creating one forecast at the start of the year and ignoring it?","options":{"A":"Because bank overdraft limits automatically double every time a forecast is updated","B":"Because government tax laws require monthly forecasts to be published in newspapers","C":"To ensure that actual profit always equals closing cash","D":"To compare actual cash flows against forecast figures, spot variances early, and adjust spending or financing plans promptly"},"correctOption":"D","correctAnswer":"To compare actual cash flows against forecast figures, spot variances early, and adjust spending or financing plans promptly","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because regular monitoring lets managers identify unexpected drops in receipts or rises in costs early enough to take corrective action.","distractor_reasons":{"A":"Incorrect because banks do not automatically double overdraft limits without formal approval.","B":"Incorrect because cash flow forecasts are internal planning documents, not publicly mandated newspaper filings.","C":"Incorrect because updating a forecast does not make profit equal cash.","D":"Option D is correct because regular monitoring lets managers identify unexpected drops in receipts or rises in costs early enough to take corrective action."}}},{"id":"P1_U5_MCQ_300","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_300","question":"A wholesale beverage distributor has a forecast closing balance of -$14,000 in April, -$16,500 in May, and -$19,000 in June, with no recovery expected later in the year. Why is simply asking suppliers for 15 extra days of credit insufficient to solve this problem?","options":{"A":"A growing, persistent deficit indicates a fundamental profitability or cost issue that requires long-term restructuring, higher revenue, or permanent finance","B":"Suppliers are legally prohibited from extending credit by 15 days","C":"Extending supplier credit increases monthly cash outflows","D":"Cash flow deficits can only be solved by issuing shares on a stock exchange"},"correctOption":"A","correctAnswer":"A growing, persistent deficit indicates a fundamental profitability or cost issue that requires long-term restructuring, higher revenue, or permanent finance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because short-term cash flow tactics only delay payments temporarily; when deficits worsen month after month, the underlying business model or long-term funding must be fixed.","distractor_reasons":{"A":"Option A is correct because short-term cash flow tactics only delay payments temporarily; when deficits worsen month after month, the underlying business model or long-term funding must be fixed.","B":"Incorrect because suppliers can agree to extend credit terms if they choose.","C":"Incorrect because extending credit delays outflows rather than increasing them.","D":"Incorrect because businesses can also raise prices, cut costs, sell assets, or secure long-term loans."}}},{"id":"P1_U5_MCQ_301","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_301","question":"In a market economy, why are entrepreneurs willing to invest their personal savings and take financial risks to launch new businesses?","options":{"A":"Because profit serves as the financial reward for risk-taking and enterprise","B":"Because the government reimburses all losses made by private companies","C":"Because profit is guaranteed for every business within six months","D":"Because entrepreneurs are not allowed to earn a salary anywhere else"},"correctOption":"A","correctAnswer":"Because profit serves as the financial reward for risk-taking and enterprise","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the prospect of earning profit compensates entrepreneurs for risking their capital and effort.","distractor_reasons":{"A":"Option A is correct because the prospect of earning profit compensates entrepreneurs for risking their capital and effort.","B":"Incorrect because private sector owners bear the financial risk of failure themselves.","C":"Incorrect because many new ventures make losses initially or fail.","D":"Incorrect because entrepreneurs choose self-employment despite having salaried alternatives."}}},{"id":"P1_U5_MCQ_302","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_302","question":"Besides rewarding business owners, what are two other major reasons why profit is important to a private sector business?","options":{"A":"It acts as a key internal source of finance (retained profit) for expansion and serves as a measure of business success","B":"It eliminates all current liabilities and removes the need for a bank account","C":"It guarantees zero competition and fixes raw material prices permanently","D":"It replaces the need to prepare a statement of financial position"},"correctOption":"A","correctAnswer":"It acts as a key internal source of finance (retained profit) for expansion and serves as a measure of business success","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit funds growth without debt or dilution, and profit levels allow owners, investors, and lenders to judge performance.","distractor_reasons":{"A":"Option A is correct because retained profit funds growth without debt or dilution, and profit levels allow owners, investors, and lenders to judge performance.","B":"Incorrect because profitable businesses still have trade payables and need bank accounts.","C":"Incorrect because high profits actually attract competitors and do not freeze supplier prices.","D":"Incorrect because limited companies must still produce a statement of financial position."}}},{"id":"P1_U5_MCQ_303","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_303","question":"A social enterprise runs a café that trains and employs people recovering from homelessness. Why does this organisation aim to make a profit even though its primary mission is social?","options":{"A":"To survive without depending on charity grants and reinvest profit into expanding its social training programmes","B":"To pay maximum cash dividends to private stock-market shareholders","C":"To avoid paying any wages to its café staff","D":"Because social enterprises are legally fined if their profit margin is below 30%"},"correctOption":"A","correctAnswer":"To survive without depending on charity grants and reinvest profit into expanding its social training programmes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social enterprises need profit to remain financially independent and reinvest surpluses into achieving their social goals.","distractor_reasons":{"A":"Option A is correct because social enterprises need profit to remain financially independent and reinvest surpluses into achieving their social goals.","B":"Incorrect because social enterprises reinvest most profits into their social mission rather than maximising private shareholder dividends.","C":"Incorrect because social enterprises pay fair wages to employees.","D":"Incorrect because there is no statutory 30% profit margin requirement."}}},{"id":"P1_U5_MCQ_304","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_304","question":"During the year, a pottery studio sells 4,000 ceramic mugs at $15 each and 1,500 bowls at $24 each. What is the studio's total revenue?","options":{"A":"$5,500","B":"$60,000","C":"$36,000","D":"$96,000"},"correctOption":"D","correctAnswer":"$96,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because total revenue = (4,000 × $15) + (1,500 × $24) = $60,000 + $36,000 = $96,000.","distractor_reasons":{"A":"Incorrect because 5,500 is the total number of items sold, not the dollar revenue.","B":"Incorrect because $60,000 is only the revenue from mugs.","C":"Incorrect because $36,000 is only the revenue from bowls.","D":"Option D is correct because total revenue = (4,000 × $15) + (1,500 × $24) = $60,000 + $36,000 = $96,000."}}},{"id":"P1_U5_MCQ_305","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_305","question":"In a manufacturing business's statement of profit or loss, which cost is included in 'cost of sales' rather than 'overhead expenses'?","options":{"A":"Raw steel and direct assembly-line worker wages used to produce the goods sold","B":"Annual rent for the corporate head office","C":"Salaries of the marketing and human resources managers","D":"Interest paid on a 10-year bank mortgage"},"correctOption":"A","correctAnswer":"Raw steel and direct assembly-line worker wages used to produce the goods sold","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost of sales measures the direct production or purchase costs of the products sold during the period.","distractor_reasons":{"A":"Option A is correct because cost of sales measures the direct production or purchase costs of the products sold during the period.","B":"Incorrect because head office rent is an indirect overhead expense.","C":"Incorrect because marketing and HR salaries are indirect administrative expenses.","D":"Incorrect because mortgage interest is a finance expense deducted after gross profit."}}},{"id":"P1_U5_MCQ_306","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_306","question":"A bookshop records annual revenue of $390,000, cost of sales of $225,000, and overhead expenses of $105,000. What is the bookshop's gross profit?","options":{"A":"$120,000","B":"$60,000","C":"$285,000","D":"$165,000"},"correctOption":"D","correctAnswer":"$165,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Gross profit = Revenue - Cost of sales ($390,000 - $225,000 = $165,000).","distractor_reasons":{"A":"Incorrect because $120,000 subtracts expenses from cost of sales ($225,000 - $105,000).","B":"Incorrect because $60,000 is the final profit after deducting both cost of sales and $105,000 of expenses.","C":"Incorrect because $285,000 subtracts expenses from revenue instead of cost of sales.","D":"Option D is correct because Gross profit = Revenue - Cost of sales ($390,000 - $225,000 = $165,000)."}}},{"id":"P1_U5_MCQ_307","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_307","question":"A toy store has annual revenue of $510,000, cost of sales of $290,000, and indirect overhead expenses of $145,000. What is the toy store's profit?","options":{"A":"$75,000","B":"$220,000","C":"$365,000","D":"$435,000"},"correctOption":"A","correctAnswer":"$75,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = $510,000 - $290,000 = $220,000, and Profit = Gross profit - Overhead expenses ($220,000 - $145,000 = $75,000).","distractor_reasons":{"A":"Option A is correct because Gross profit = $510,000 - $290,000 = $220,000, and Profit = Gross profit - Overhead expenses ($220,000 - $145,000 = $75,000).","B":"Incorrect because $220,000 is the gross profit before deducting $145,000 of overhead expenses.","C":"Incorrect because $365,000 deducts only expenses from revenue and omits cost of sales.","D":"Incorrect because $435,000 adds cost of sales and expenses together ($290,000 + $145,000)."}}},{"id":"P1_U5_MCQ_308","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_308","question":"An incomplete statement of profit or loss for a garden centre shows cost of sales of $185,000, gross profit of $145,000, and overhead expenses of $92,000. What were the garden centre's total revenue and final profit?","options":{"A":"Revenue: $330,000; Final profit: $53,000","B":"Revenue: $40,000; Final profit: $53,000","C":"Revenue: $330,000; Final profit: $237,000","D":"Revenue: $277,000; Final profit: $53,000"},"correctOption":"A","correctAnswer":"Revenue: $330,000; Final profit: $53,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Revenue = Gross profit + Cost of sales ($145,000 + $185,000 = $330,000), and Final profit = Gross profit - Expenses ($145,000 - $92,000 = $53,000).","distractor_reasons":{"A":"Option A is correct because Revenue = Gross profit + Cost of sales ($145,000 + $185,000 = $330,000), and Final profit = Gross profit - Expenses ($145,000 - $92,000 = $53,000).","B":"Incorrect because $40,000 subtracts gross profit from cost of sales instead of adding them.","C":"Incorrect because $237,000 adds overhead expenses to gross profit instead of subtracting them.","D":"Incorrect because $277,000 adds cost of sales and expenses instead of cost of sales and gross profit."}}},{"id":"P1_U5_MCQ_309","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_309","question":"A private limited company earns a profit before tax of $300,000. It pays $60,000 in corporation tax and distributes $90,000 in dividends to shareholders. How much retained profit remains in the business?","options":{"A":"$390,000","B":"$240,000","C":"$210,000","D":"$150,000"},"correctOption":"D","correctAnswer":"$150,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Profit after tax = $300,000 - $60,000 = $240,000, and Retained profit = Profit after tax - Dividends ($240,000 - $90,000 = $150,000).","distractor_reasons":{"A":"Incorrect because $390,000 adds dividends to profit before tax instead of subtracting tax and dividends.","B":"Incorrect because $240,000 is profit after tax before deducting the $90,000 dividend payment.","C":"Incorrect because $210,000 subtracts dividends from profit before tax and ignores the $60,000 tax.","D":"Option D is correct because Profit after tax = $300,000 - $60,000 = $240,000, and Retained profit = Profit after tax - Dividends ($240,000 - $90,000 = $150,000)."}}},{"id":"P1_U5_MCQ_310","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_310","question":"A bakery's flour supplier raises prices by 15%, increasing the bakery's cost of sales by $9,000 while bread prices, sales volume, and overhead expenses stay unchanged. How does this affect the bakery's statement of profit or loss?","options":{"A":"Both gross profit and final profit fall by $9,000","B":"Gross profit stays unchanged, while final profit falls by $9,000","C":"Revenue rises by $9,000 and gross profit stays unchanged","D":"Overhead expenses rise by $9,000 and gross profit rises by $9,000"},"correctOption":"A","correctAnswer":"Both gross profit and final profit fall by $9,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because flour is a direct ingredient in cost of sales; raising cost of sales by $9,000 directly reduces gross profit by $9,000 and final profit by $9,000.","distractor_reasons":{"A":"Option A is correct because flour is a direct ingredient in cost of sales; raising cost of sales by $9,000 directly reduces gross profit by $9,000 and final profit by $9,000.","B":"Incorrect because flour is part of cost of sales rather than an overhead expense, so gross profit falls.","C":"Incorrect because bread prices and sales volume did not increase.","D":"Incorrect because higher ingredient costs reduce rather than increase gross profit."}}},{"id":"P1_U5_MCQ_311","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_311","question":"An insurance broker's electricity and office cleaning bills increase by $6,500 over the year, while fee revenue and direct costs remain unchanged. What is the impact on the broker's statement of profit or loss?","options":{"A":"Gross profit falls by $6,500 and final profit stays unchanged","B":"Gross profit remains unchanged, while overhead expenses rise by $6,500 and final profit falls by $6,500","C":"Cost of sales rises by $6,500 and gross profit falls by $6,500","D":"Both gross profit and final profit rise by $6,500"},"correctOption":"B","correctAnswer":"Gross profit remains unchanged, while overhead expenses rise by $6,500 and final profit falls by $6,500","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because electricity and office cleaning are indirect overhead expenses deducted after gross profit; gross profit is unaffected, while final profit drops by $6,500.","distractor_reasons":{"A":"Incorrect because overhead expenses are deducted from gross profit to find final profit.","B":"Option B is correct because electricity and office cleaning are indirect overhead expenses deducted after gross profit; gross profit is unaffected, while final profit drops by $6,500.","C":"Incorrect because office utilities and cleaning are indirect expenses, not cost of sales.","D":"Incorrect because higher utility bills represent an increase in costs, reducing final profit."}}},{"id":"P1_U5_MCQ_312","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_312","question":"A restaurant wants to increase its annual profit without raising menu prices. Which action directly reduces its cost of sales?","options":{"A":"Reducing kitchen food spoilage through better portion control and negotiating bulk discounts with vegetable wholesalers","B":"Switching to a cheaper accountant for annual tax filings","C":"Reducing expenditure on local newspaper advertisements","D":"Subletting an unused upstairs office room"},"correctOption":"A","correctAnswer":"Reducing kitchen food spoilage through better portion control and negotiating bulk discounts with vegetable wholesalers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ingredients and food waste form part of cost of sales; reducing waste and ingredient purchase prices lowers cost of sales and boosts gross profit.","distractor_reasons":{"A":"Option A is correct because ingredients and food waste form part of cost of sales; reducing waste and ingredient purchase prices lowers cost of sales and boosts gross profit.","B":"Incorrect because accounting fees are indirect overhead expenses.","C":"Incorrect because advertising is an indirect marketing expense.","D":"Incorrect because subletting reduces indirect rent overhead rather than direct food cost of sales."}}},{"id":"P1_U5_MCQ_313","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_313","question":"A clothing manufacturer keeps its selling prices and fabric costs unchanged, but installs automated heating controls and renegotiates lower warehouse insurance premiums. How does this increase profit?","options":{"A":"It lowers overhead expenses, increasing final profit while leaving gross profit unchanged","B":"It increases total revenue on the statement of profit or loss","C":"It lowers cost of sales and increases gross profit","D":"It increases current assets on the statement of financial position"},"correctOption":"A","correctAnswer":"It lowers overhead expenses, increasing final profit while leaving gross profit unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because heating and insurance are overhead expenses deducted below gross profit; lowering them directly raises final profit.","distractor_reasons":{"A":"Option A is correct because heating and insurance are overhead expenses deducted below gross profit; lowering them directly raises final profit.","B":"Incorrect because selling prices and sales volume did not change.","C":"Incorrect because heating and insurance are indirect overheads, not direct cost of sales.","D":"Incorrect because reducing expenses improves profit rather than automatically creating current assets."}}},{"id":"P1_U5_MCQ_314","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_314","question":"A coffee shop raises the price of its lattes by 30% to boost profit, only to find that its monthly profit falls by half. Why did raising the selling price reduce profit?","options":{"A":"Raising prices is illegal for small cafés","B":"Higher latte prices automatically doubled the shop's fixed rent","C":"Many regular customers switched to nearby rival cafés, causing sales volume and total revenue to fall sharply","D":"Higher prices increased the cost of coffee beans per cup"},"correctOption":"C","correctAnswer":"Many regular customers switched to nearby rival cafés, causing sales volume and total revenue to fall sharply","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because in a competitive market with many substitutes, a steep price hike drives away customers, reducing quantity sold and total revenue.","distractor_reasons":{"A":"Incorrect because private cafés set their own menu prices freely.","B":"Incorrect because fixed rent is unaffected by menu prices.","C":"Option C is correct because in a competitive market with many substitutes, a steep price hike drives away customers, reducing quantity sold and total revenue.","D":"Incorrect because supplier bean costs do not depend on retail latte prices."}}},{"id":"P1_U5_MCQ_315","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_315","question":"To boost profit quickly, a factory manager cancels all preventative machinery maintenance and cuts worker safety training. What is the main long-term risk of this cost-cutting strategy?","options":{"A":"Gross profit will immediately fall to zero this month","B":"Frequent machinery breakdowns, workplace accidents, and lower product quality will disrupt output and reduce future profits","C":"The factory's non-current liabilities will double","D":"Suppliers will raise raw material prices because training was cut"},"correctOption":"B","correctAnswer":"Frequent machinery breakdowns, workplace accidents, and lower product quality will disrupt output and reduce future profits","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cutting essential maintenance and training saves expenses briefly but leads to costly equipment failures, lower productivity, and damaged reputation.","distractor_reasons":{"A":"Incorrect because cutting overhead expenses actually makes short-term profit look higher before problems emerge.","B":"Option B is correct because cutting essential maintenance and training saves expenses briefly but leads to costly equipment failures, lower productivity, and damaged reputation.","C":"Incorrect because cutting expenses does not create long-term debt.","D":"Incorrect because suppliers do not set raw material prices based on a buyer's training budget."}}},{"id":"P1_U5_MCQ_316","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_316","question":"A supermarket compares two bakery products: Artisan Bread generates $90,000 in revenue with $40,000 in cost of sales, whereas Standard Loaves generate $140,000 in revenue with $105,000 in cost of sales. Which conclusion is supported by this statement of profit or loss data?","options":{"A":"Artisan Bread generates more gross profit ($50,000) than Standard Loaves ($35,000) despite lower sales revenue","B":"Standard Loaves are more profitable because their revenue is $50,000 higher","C":"Artisan Bread should be discontinued immediately because its revenue is under $100,000","D":"Both products generate the exact same gross profit"},"correctOption":"A","correctAnswer":"Artisan Bread generates more gross profit ($50,000) than Standard Loaves ($35,000) despite lower sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Artisan Bread earns $50,000 gross profit ($90,000 - $40,000), exceeding Standard Loaves' $35,000 gross profit ($140,000 - $105,000).","distractor_reasons":{"A":"Option A is correct because Artisan Bread earns $50,000 gross profit ($90,000 - $40,000), exceeding Standard Loaves' $35,000 gross profit ($140,000 - $105,000).","B":"Incorrect because higher revenue does not produce higher profit when cost of sales is much higher.","C":"Incorrect because discontinuing the higher-gross-profit product would reduce total profit.","D":"Incorrect because $50,000 is greater than $35,000."}}},{"id":"P1_U5_MCQ_317","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_317","question":"Between Year 1 and Year 2, a hardware retailer's revenue rose from $400,000 to $460,000 and its gross profit rose from $160,000 to $184,000, yet its final profit fell from $60,000 to $44,000. What caused final profit to fall despite higher sales and gross profit?","options":{"A":"Cost of sales increased as a percentage of revenue","B":"Overhead expenses rose sharply from $100,000 to $140,000","C":"Sales revenue fell by $60,000","D":"The retailer paid out too much share capital"},"correctOption":"B","correctAnswer":"Overhead expenses rose sharply from $100,000 to $140,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Gross profit - Expenses = Profit; in Year 1 expenses were $100,000 ($160,000 - $60,000), whereas in Year 2 expenses jumped to $140,000 ($184,000 - $44,000).","distractor_reasons":{"A":"Incorrect because gross profit remained at 40% of revenue in both years ($160k/$400k and $184k/$460k).","B":"Option B is correct because Gross profit - Expenses = Profit; in Year 1 expenses were $100,000 ($160,000 - $60,000), whereas in Year 2 expenses jumped to $140,000 ($184,000 - $44,000).","C":"Incorrect because revenue increased from $400,000 to $460,000.","D":"Incorrect because share capital is not deducted as an expense on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_318","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_318","question":"An electronics manufacturer reports a profit of $250,000 on its statement of profit or loss, yet it cannot pay a $200,000 cash dividend to shareholders because its bank account holds only $15,000. What does this illustrate?","options":{"A":"Companies are legally prohibited from paying dividends out of profits","B":"Profit is not the same as cash; a business can be profitable while having its funds tied up in trade receivables, inventory, or equipment","C":"The statement of profit or loss only records cash transactions","D":"Dividends must always be paid using bank overdrafts"},"correctOption":"B","correctAnswer":"Profit is not the same as cash; a business can be profitable while having its funds tied up in trade receivables, inventory, or equipment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profit includes credit sales and excludes capital expenditure, so high profit does not guarantee sufficient cash in the bank to pay large cash dividends.","distractor_reasons":{"A":"Incorrect because dividends are normally distributed from after-tax profits when cash is available.","B":"Option B is correct because profit includes credit sales and excludes capital expenditure, so high profit does not guarantee sufficient cash in the bank to pay large cash dividends.","C":"Incorrect because the statement of profit or loss includes credit sales and accrued expenses.","D":"Incorrect because companies should avoid borrowing via overdrafts just to pay dividends."}}},{"id":"P1_U5_MCQ_319","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_319","question":"A courier company spends $40,000 on a new digital parcel-tracking app campaign that increases revenue by $95,000 and incurs $30,000 in extra direct delivery costs (cost of sales). What is the net effect on the company's profit?","options":{"A":"Profit decreases by $40,000","B":"Profit increases by $65,000","C":"Profit increases by $95,000","D":"Profit increases by $25,000"},"correctOption":"D","correctAnswer":"Profit increases by $25,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because extra gross profit = $95,000 revenue - $30,000 cost of sales = $65,000, and subtracting the $40,000 campaign expense yields a net profit gain of $25,000.","distractor_reasons":{"A":"Incorrect because the extra gross profit ($65,000) exceeds the $40,000 campaign cost.","B":"Incorrect because $65,000 is the increase in gross profit before deducting the $40,000 campaign expense.","C":"Incorrect because $95,000 is the increase in revenue before deducting direct delivery costs and campaign expenses.","D":"Option D is correct because extra gross profit = $95,000 revenue - $30,000 cost of sales = $65,000, and subtracting the $40,000 campaign expense yields a net profit gain of $25,000."}}},{"id":"P1_U5_MCQ_320","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_320","question":"Why is a statement of profit or loss useful to a commercial bank when a small business applies for a loan?","options":{"A":"It proves the business will never face new competitors","B":"It lists the exact resale value of the owner's personal house","C":"It shows the business's track record of generating revenue, controlling costs, and earning profits over recent trading periods","D":"It shows the exact daily bank balance for the next five years"},"correctOption":"C","correctAnswer":"It shows the business's track record of generating revenue, controlling costs, and earning profits over recent trading periods","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because banks review past statements of profit or loss to assess whether the business is viable, well-managed, and capable of earning profits to service debt.","distractor_reasons":{"A":"Incorrect because historical profit statements cannot prevent future competition.","B":"Incorrect because personal property values are not shown on a business statement of profit or loss.","C":"Option C is correct because banks review past statements of profit or loss to assess whether the business is viable, well-managed, and capable of earning profits to service debt.","D":"Incorrect because future daily/monthly cash balances are projected in a cash flow forecast."}}},{"id":"P1_U5_MCQ_321","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_321","question":"A toy company's statement of profit or loss shows revenue of $620,000, overhead expenses of $140,000, and final profit of $85,000. What was the company's cost of sales?","options":{"A":"$395,000","B":"$225,000","C":"$535,000","D":"$480,000"},"correctOption":"A","correctAnswer":"$395,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = Final profit + Overhead expenses ($85,000 + $140,000 = $225,000), and Cost of sales = Revenue - Gross profit ($620,000 - $225,000 = $395,000).","distractor_reasons":{"A":"Option A is correct because Gross profit = Final profit + Overhead expenses ($85,000 + $140,000 = $225,000), and Cost of sales = Revenue - Gross profit ($620,000 - $225,000 = $395,000).","B":"Incorrect because $225,000 is the gross profit, not cost of sales.","C":"Incorrect because $535,000 subtracts only final profit from revenue ($620,000 - $85,000), failing to remove overhead expenses.","D":"Incorrect because $480,000 subtracts only overhead expenses from revenue ($620,000 - $140,000)."}}},{"id":"P1_U5_MCQ_322","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_322","question":"A car-rental firm sells five old rental cars for $55,000 cash. Why is this $55,000 NOT recorded as 'sales revenue' on the firm's statement of profit or loss?","options":{"A":"Because cash receipts are never recorded anywhere in company accounts","B":"Because car-rental firms are legally forbidden from selling used cars","C":"Because sales revenue only records income from the business's main trading activities (renting cars), whereas selling old vehicles is disposing of non-current assets","D":"Because selling old cars is recorded under cost of sales"},"correctOption":"C","correctAnswer":"Because sales revenue only records income from the business's main trading activities (renting cars), whereas selling old vehicles is disposing of non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because revenue represents normal trading turnover from selling goods or services, whereas selling used vehicles reduces non-current assets on the statement of financial position.","distractor_reasons":{"A":"Incorrect because cash receipts are recorded in cash flow records and on the statement of financial position.","B":"Incorrect because car-rental companies routinely sell off older fleet vehicles.","C":"Option C is correct because revenue represents normal trading turnover from selling goods or services, whereas selling used vehicles reduces non-current assets on the statement of financial position.","D":"Incorrect because cost of sales records direct costs of goods sold, not asset disposals."}}},{"id":"P1_U5_MCQ_323","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_323","question":"When a business makes a loss (where total costs exceed total revenue), what happens to its retained profit reserve on the statement of financial position?","options":{"A":"The loss is added to non-current assets","B":"The loss reduces accumulated retained profit (shareholders' equity), shrinking the net worth of the business","C":"The loss increases share capital automatically","D":"The loss is paid to shareholders as a negative dividend"},"correctOption":"B","correctAnswer":"The loss reduces accumulated retained profit (shareholders' equity), shrinking the net worth of the business","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because just as retained profits increase equity, trading losses erode accumulated reserves and reduce total shareholders' equity.","distractor_reasons":{"A":"Incorrect because a trading loss reduces net assets rather than increasing non-current assets.","B":"Option B is correct because just as retained profits increase equity, trading losses erode accumulated reserves and reduce total shareholders' equity.","C":"Incorrect because share capital only changes when new shares are issued or bought back.","D":"Incorrect because shareholders cannot be forced to pay negative dividends due to limited liability."}}},{"id":"P1_U5_MCQ_324","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_324","question":"A chain of gyms sees its annual profit fall from $190,000 to $110,000 despite opening two new branches. Which step should the directors take first using their statement of profit or loss?","options":{"A":"Compare revenue, cost of sales, and overhead expenses across individual branches to identify whether weak membership sales or rising running costs caused the drop","B":"Immediately close all gyms across the country","C":"Stop recording overhead expenses on future statements of profit or loss","D":"Double membership prices at every branch without researching competitors"},"correctOption":"A","correctAnswer":"Compare revenue, cost of sales, and overhead expenses across individual branches to identify whether weak membership sales or rising running costs caused the drop","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers use detailed profit and loss breakdowns to diagnose whether low revenue or excessive costs caused profit to decline before choosing corrective action.","distractor_reasons":{"A":"Option A is correct because managers use detailed profit and loss breakdowns to diagnose whether low revenue or excessive costs caused profit to decline before choosing corrective action.","B":"Incorrect because the chain is still making $110,000 profit, so closing everything would destroy a profitable business.","C":"Incorrect because omitting expenses would falsify the financial statements.","D":"Incorrect because doubling prices blindly could drive away members and worsen profit."}}},{"id":"P1_U5_MCQ_325","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_325","question":"A bakery's statement of profit or loss shows revenue of $480,000, cost of sales of $210,000, overhead expenses of $170,000, tax of $20,000, and dividends of $35,000. What is the bakery's retained profit for the year?","options":{"A":"$45,000","B":"$100,000","C":"$80,000","D":"$270,000"},"correctOption":"A","correctAnswer":"$45,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = $480,000 - $210,000 = $270,000; Profit before tax = $270,000 - $170,000 = $100,000; Profit after tax = $100,000 - $20,000 = $80,000; Retained profit = $80,000 - $35,000 = $45,000.","distractor_reasons":{"A":"Option A is correct because Gross profit = $480,000 - $210,000 = $270,000; Profit before tax = $270,000 - $170,000 = $100,000; Profit after tax = $100,000 - $20,000 = $80,000; Retained profit = $80,000 - $35,000 = $45,000.","B":"Incorrect because $100,000 is profit before tax and dividends.","C":"Incorrect because $80,000 is profit after tax before deducting the $35,000 dividend payout.","D":"Incorrect because $270,000 is the gross profit."}}},{"id":"P1_U5_MCQ_326","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_326","question":"Which statement accurately defines an 'asset' on a business's statement of financial position?","options":{"A":"Any resource or item of value owned by the business that is expected to provide future economic benefit","B":"Any debt or financial obligation that the business owes to external lenders or suppliers","C":"The total sales revenue earned by the business during the financial year","D":"The annual electricity and wage expenses paid by the business"},"correctOption":"A","correctAnswer":"Any resource or item of value owned by the business that is expected to provide future economic benefit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because assets are items of value owned by a business, divided into non-current assets (held >1 year) and current assets (held <1 year).","distractor_reasons":{"A":"Option A is correct because assets are items of value owned by a business, divided into non-current assets (held >1 year) and current assets (held <1 year).","B":"Incorrect because debts owed by the business are liabilities, not assets.","C":"Incorrect because sales revenue appears on the statement of profit or loss.","D":"Incorrect because running expenses appear on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_327","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_327","question":"Which group of items consists ENTIRELY of non-current assets on a manufacturing company's statement of financial position?","options":{"A":"Factory premises, raw steel inventory, and bank overdraft","B":"Finished goods inventory, trade receivables, and cash","C":"Factory premises, CNC lathes, and company delivery trucks","D":"10-year bank loan, share capital, and retained profit"},"correctOption":"C","correctAnswer":"Factory premises, CNC lathes, and company delivery trucks","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because factory premises, machinery, and vehicles are long-term physical resources owned and used by the business for more than 12 months.","distractor_reasons":{"A":"Incorrect because raw steel inventory is a current asset and a bank overdraft is a current liability.","B":"Incorrect because inventory, trade receivables, and cash are short-term current assets.","C":"Option C is correct because factory premises, machinery, and vehicles are long-term physical resources owned and used by the business for more than 12 months.","D":"Incorrect because a 10-year loan is a non-current liability, while share capital and retained profit are equity."}}},{"id":"P1_U5_MCQ_328","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_328","question":"Why are 'trade receivables' classified as a current asset on a statement of financial position?","options":{"A":"Because they represent money the business owes to its raw material suppliers","B":"Because they represent money owed to the business by credit customers that is expected to be collected in cash within 12 months","C":"Because they are permanent factory buildings owned by the business","D":"Because they are long-term loans borrowed from a commercial bank"},"correctOption":"B","correctAnswer":"Because they represent money owed to the business by credit customers that is expected to be collected in cash within 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because trade receivables are short-term claims on credit customers that normally convert into cash within 30 to 90 days.","distractor_reasons":{"A":"Incorrect because money owed to suppliers is recorded as trade payables (a current liability).","B":"Option B is correct because trade receivables are short-term claims on credit customers that normally convert into cash within 30 to 90 days.","C":"Incorrect because factory buildings are non-current assets.","D":"Incorrect because long-term loans are non-current liabilities."}}},{"id":"P1_U5_MCQ_329","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_329","question":"Which item is classified as a 'current liability' on a retail business's statement of financial position?","options":{"A":"Trade payables owed to clothing suppliers due in 30 days","B":"A 15-year commercial mortgage on the store building","C":"Cash held in the store's safe and bank current account","D":"Share capital invested by the company's founders"},"correctOption":"A","correctAnswer":"Trade payables owed to clothing suppliers due in 30 days","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because current liabilities are short-term debts that must be repaid within one year, such as trade payables and bank overdrafts.","distractor_reasons":{"A":"Option A is correct because current liabilities are short-term debts that must be repaid within one year, such as trade payables and bank overdrafts.","B":"Incorrect because a 15-year mortgage is a long-term non-current liability.","C":"Incorrect because cash is a current asset.","D":"Incorrect because share capital is part of shareholders' equity."}}},{"id":"P1_U5_MCQ_330","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_330","question":"What distinguishes a 'non-current liability' from a 'current liability' on a statement of financial position?","options":{"A":"A non-current liability is a debt repayable after more than one year, whereas a current liability is due within one year","B":"A non-current liability never has to be repaid, whereas a current liability must be repaid","C":"A non-current liability is owned by the business, whereas a current liability is owed to the business","D":"A non-current liability is part of share capital, whereas a current liability is part of retained profit"},"correctOption":"A","correctAnswer":"A non-current liability is a debt repayable after more than one year, whereas a current liability is due within one year","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because liabilities are separated by repayment timeframe: current liabilities fall due within 12 months, while non-current liabilities (like multi-year loans) are due after 12 months.","distractor_reasons":{"A":"Option A is correct because liabilities are separated by repayment timeframe: current liabilities fall due within 12 months, while non-current liabilities (like multi-year loans) are due after 12 months.","B":"Incorrect because both current and non-current liabilities are legally binding debts that must be repaid.","C":"Incorrect because all liabilities are debts owed by the business to external parties.","D":"Incorrect because share capital and retained profit are equity, not liabilities."}}},{"id":"P1_U5_MCQ_331","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_331","question":"A florist's statement of financial position shows inventory of $9,500, trade receivables of $6,500, cash of $4,000, trade payables of $8,200, and a bank overdraft of $2,800. What is the florist's working capital (net current assets)?","options":{"A":"$9,000","B":"$11,800","C":"$31,000","D":"$5,000"},"correctOption":"A","correctAnswer":"$9,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Current assets = $9,500 + $6,500 + $4,000 = $20,000 and Current liabilities = $8,200 + $2,800 = $11,000, giving working capital of $20,000 - $11,000 = $9,000.","distractor_reasons":{"A":"Option A is correct because Current assets = $9,500 + $6,500 + $4,000 = $20,000 and Current liabilities = $8,200 + $2,800 = $11,000, giving working capital of $20,000 - $11,000 = $9,000.","B":"Incorrect because $11,800 omits the $2,800 bank overdraft from current liabilities ($20,000 - $8,200).","C":"Incorrect because $31,000 adds current assets and current liabilities together ($20,000 + $11,000).","D":"Incorrect because $5,000 omits the $4,000 cash balance from current assets ($16,000 - $11,000)."}}},{"id":"P1_U5_MCQ_332","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_332","question":"A carpentry workshop owns buildings valued at $260,000, woodworking machinery valued at $75,000, timber inventory of $19,000, trade receivables of $14,000, and cash of $7,000. What is the value of the workshop's total assets?","options":{"A":"$375,000","B":"$335,000","C":"$40,000","D":"$295,000"},"correctOption":"A","correctAnswer":"$375,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Total assets = Non-current assets ($260,000 + $75,000 = $335,000) + Current assets ($19,000 + $14,000 + $7,000 = $40,000) = $375,000.","distractor_reasons":{"A":"Option A is correct because Total assets = Non-current assets ($260,000 + $75,000 = $335,000) + Current assets ($19,000 + $14,000 + $7,000 = $40,000) = $375,000.","B":"Incorrect because $335,000 is non-current assets alone.","C":"Incorrect because $40,000 is current assets alone.","D":"Incorrect because $295,000 subtracts current assets from non-current assets."}}},{"id":"P1_U5_MCQ_333","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_333","question":"A logistics company's statement of financial position shows non-current assets of $640,000, current assets of $120,000, current liabilities of $70,000, and non-current liabilities of $240,000. What is the company's capital employed?","options":{"A":"$690,000","B":"$450,000","C":"$760,000","D":"$520,000"},"correctOption":"A","correctAnswer":"$690,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Capital employed = Total assets - Current liabilities ($640,000 + $120,000 - $70,000 = $690,000), which also equals Total equity ($450,000) + Non-current liabilities ($240,000).","distractor_reasons":{"A":"Option A is correct because Capital employed = Total assets - Current liabilities ($640,000 + $120,000 - $70,000 = $690,000), which also equals Total equity ($450,000) + Non-current liabilities ($240,000).","B":"Incorrect because $450,000 is net assets / total shareholders' equity, which deducts non-current liabilities as well.","C":"Incorrect because $760,000 is total assets without deducting current liabilities.","D":"Incorrect because $520,000 omits current assets ($640,000 - $120,000)."}}},{"id":"P1_U5_MCQ_334","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_334","question":"On a private limited company's statement of financial position, non-current assets are $380,000, current assets are $95,000, current liabilities are $45,000, non-current liabilities are $130,000, and share capital is $200,000. What must the company's retained profit be?","options":{"A":"$100,000","B":"$300,000","C":"$230,000","D":"$145,000"},"correctOption":"A","correctAnswer":"$100,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Total assets = $380,000 + $95,000 = $475,000; Total liabilities = $45,000 + $130,000 = $175,000; Total equity (Net assets) = $475,000 - $175,000 = $300,000; Retained profit = $300,000 - $200,000 share capital = $100,000.","distractor_reasons":{"A":"Option A is correct because Total assets = $380,000 + $95,000 = $475,000; Total liabilities = $45,000 + $130,000 = $175,000; Total equity (Net assets) = $475,000 - $175,000 = $300,000; Retained profit = $300,000 - $200,000 share capital = $100,000.","B":"Incorrect because $300,000 is total shareholders' equity, not retained profit alone.","C":"Incorrect because $230,000 forgets to subtract the $130,000 non-current liabilities.","D":"Incorrect because $145,000 forgets to subtract the $45,000 current liabilities."}}},{"id":"P1_U5_MCQ_335","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_335","question":"A toy retailer takes out a $25,000 short-term bank loan (repayable in 9 months) and deposits the cash into its bank current account. How does this transaction immediately affect the retailer's statement of financial position?","options":{"A":"Current assets increase by $25,000 and non-current liabilities increase by $25,000","B":"Non-current assets increase by $25,000 and shareholders' equity increases by $25,000","C":"Current assets (cash) increase by $25,000 and current liabilities increase by $25,000","D":"Working capital increases by $25,000"},"correctOption":"C","correctAnswer":"Current assets (cash) increase by $25,000 and current liabilities increase by $25,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash in the bank rises by $25,000 (current asset) while a 9-month loan is due within one year, increasing current liabilities by $25,000.","distractor_reasons":{"A":"Incorrect because a 9-month loan is repayable within 12 months, making it a current liability rather than non-current.","B":"Incorrect because cash is a current asset and a loan creates a liability rather than equity.","C":"Option C is correct because cash in the bank rises by $25,000 (current asset) while a 9-month loan is due within one year, increasing current liabilities by $25,000.","D":"Incorrect because both current assets and current liabilities rise by $25,000, leaving working capital unchanged."}}},{"id":"P1_U5_MCQ_336","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_336","question":"A wholesaler sells $18,000 of inventory (at cost) to a retail chain on 30-day credit for $18,000 (ignoring profit margin for simplicity). How does this transaction immediately change the wholesaler's current assets?","options":{"A":"Non-current assets increase by $18,000","B":"Cash increases by $18,000 and inventory increases by $18,000","C":"Current liabilities increase by $18,000 and total current assets fall by $18,000","D":"Inventory decreases by $18,000 and trade receivables increase by $18,000, leaving total current assets unchanged"},"correctOption":"D","correctAnswer":"Inventory decreases by $18,000 and trade receivables increase by $18,000, leaving total current assets unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because inventory leaves the warehouse (-$18,000) and is replaced by an unpaid customer invoice under trade receivables (+$18,000), both within current assets.","distractor_reasons":{"A":"Incorrect because inventory and trade receivables are both current assets.","B":"Incorrect because the sale was on 30-day credit (no cash yet) and inventory decreased.","C":"Incorrect because selling to a customer creates a trade receivable (asset), not a liability.","D":"Option D is correct because inventory leaves the warehouse (-$18,000) and is replaced by an unpaid customer invoice under trade receivables (+$18,000), both within current assets."}}},{"id":"P1_U5_MCQ_337","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_337","question":"A construction company uses $75,000 of its cash balance to buy a new excavator machine. What is the immediate effect on the company's total assets and working capital?","options":{"A":"Total assets remain unchanged, while working capital decreases by $75,000","B":"Total assets increase by $75,000 and working capital increases by $75,000","C":"Total assets decrease by $75,000 and working capital stays unchanged","D":"Both total assets and working capital decrease by $75,000"},"correctOption":"A","correctAnswer":"Total assets remain unchanged, while working capital decreases by $75,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash (-$75,000 current asset) is exchanged for an excavator (+$75,000 non-current asset), keeping total assets constant while lowering current assets and working capital by $75,000.","distractor_reasons":{"A":"Option A is correct because cash (-$75,000 current asset) is exchanged for an excavator (+$75,000 non-current asset), keeping total assets constant while lowering current assets and working capital by $75,000.","B":"Incorrect because cash was spent to acquire the machine, so total assets do not increase.","C":"Incorrect because the excavator is added to non-current assets, keeping total assets unchanged.","D":"Incorrect because total assets stay the same when one asset is exchanged for another of equal value."}}},{"id":"P1_U5_MCQ_338","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_338","question":"Examining a boutique clothing brand's statement of financial position, an analyst sees current assets of $42,000 and current liabilities of $68,000. What does this negative working capital of -$26,000 signal?","options":{"A":"The brand does not have enough short-term assets to cover debts due within 12 months, creating a serious risk of liquidity failure","B":"The brand has $26,000 in surplus cash ready to pay dividends","C":"The brand's gross profit margin is 26%","D":"The brand has zero long-term bank loans"},"correctOption":"A","correctAnswer":"The brand does not have enough short-term assets to cover debts due within 12 months, creating a serious risk of liquidity failure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because negative working capital means current liabilities exceed current assets, warning that the business may be unable to pay suppliers and short-term creditors on time.","distractor_reasons":{"A":"Option A is correct because negative working capital means current liabilities exceed current assets, warning that the business may be unable to pay suppliers and short-term creditors on time.","B":"Incorrect because negative working capital indicates a liquidity deficit, not a cash surplus.","C":"Incorrect because working capital does not measure gross profit margin.","D":"Incorrect because working capital excludes non-current liabilities."}}},{"id":"P1_U5_MCQ_339","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_339","question":"Why is it important for a business to maintain positive working capital, yet avoid holding excessively high working capital?","options":{"A":"Negative working capital is required by law for all public limited companies","B":"High working capital increases corporation tax rates to 80%","C":"Too little working capital risks inability to pay short-term bills, while excessive working capital ties up funds unproductively in idle cash, excess stock, or slow receivables","D":"Working capital is deducted from revenue when calculating gross profit"},"correctOption":"C","correctAnswer":"Too little working capital risks inability to pay short-term bills, while excessive working capital ties up funds unproductively in idle cash, excess stock, or slow receivables","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because effective working capital management balances liquidity safety (paying bills on time) against efficiency (avoiding idle resources).","distractor_reasons":{"A":"Incorrect because businesses aim for positive working capital to stay solvent.","B":"Incorrect because tax rates are based on taxable profit, not working capital levels.","C":"Option C is correct because effective working capital management balances liquidity safety (paying bills on time) against efficiency (avoiding idle resources).","D":"Incorrect because working capital sits on the statement of financial position, not on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_340","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_340","question":"Over three years, a supermarket chain's trade payables grew from $90,000 to $210,000 while its cash balance fell from $50,000 to $4,000. What is the most likely interpretation of this trend on its statement of financial position?","options":{"A":"The supermarket is running short of cash and delaying payments to suppliers, risking supply disruptions","B":"The supermarket has eliminated all of its current liabilities","C":"The supermarket has become completely debt-free","D":"Customers are paying for groceries in cash faster than ever before"},"correctOption":"A","correctAnswer":"The supermarket is running short of cash and delaying payments to suppliers, risking supply disruptions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sharply rising trade payables paired with plummeting cash indicates worsening liquidity and reliance on unpaid supplier credit.","distractor_reasons":{"A":"Option A is correct because sharply rising trade payables paired with plummeting cash indicates worsening liquidity and reliance on unpaid supplier credit.","B":"Incorrect because trade payables are current liabilities and more than doubled.","C":"Incorrect because trade payables represent short-term commercial debt owed to suppliers.","D":"Incorrect because faster customer cash payments would increase rather than drain the cash balance."}}},{"id":"P1_U5_MCQ_341","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_341","question":"A tech company's statement of financial position lists 'share capital' at $500,000. What does this $500,000 figure represent?","options":{"A":"The total amount of loans owed to commercial banks","B":"The amount of cash currently sitting in the company's bank account","C":"The total value of unsold computer inventory in the warehouse","D":"The total amount of money originally invested into the company by shareholders in exchange for shares"},"correctOption":"D","correctAnswer":"The total amount of money originally invested into the company by shareholders in exchange for shares","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because share capital records the permanent capital raised by issuing shares to owners, forming part of shareholders' equity.","distractor_reasons":{"A":"Incorrect because bank loans are debt liabilities, not share capital.","B":"Incorrect because cash raised from shares is spent on assets and operations, so share capital rarely equals the bank balance.","C":"Incorrect because inventory is recorded under current assets.","D":"Option D is correct because share capital records the permanent capital raised by issuing shares to owners, forming part of shareholders' equity."}}},{"id":"P1_U5_MCQ_342","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_342","question":"Which statement explains why a statement of financial position must always balance (Total assets = Total liabilities + Shareholders' equity)?","options":{"A":"Because every asset owned by the business must be financed either by borrowing from external creditors (liabilities) or by funds belonging to the owners (equity)","B":"Because cash inflows always equal cash outflows every single day","C":"Because non-current assets must always equal current assets","D":"Because accountants adjust revenue figures until both sides match"},"correctOption":"A","correctAnswer":"Because every asset owned by the business must be financed either by borrowing from external creditors (liabilities) or by funds belonging to the owners (equity)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the accounting equation reflects that all business resources (assets) are funded by external claims (liabilities) plus owners' claims (equity).","distractor_reasons":{"A":"Option A is correct because the accounting equation reflects that all business resources (assets) are funded by external claims (liabilities) plus owners' claims (equity).","B":"Incorrect because daily cash inflows and outflows rarely equal each other.","C":"Incorrect because non-current assets and current assets rarely have identical values.","D":"Incorrect because revenue is not on the statement of financial position, and accounts balance naturally through double-entry bookkeeping."}}},{"id":"P1_U5_MCQ_343","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_343","question":"A solar energy company's statement of financial position shows non-current assets of $850,000, working capital of $150,000, and non-current liabilities of $400,000. What is the value of total shareholders' equity?","options":{"A":"$600,000","B":"$1,000,000","C":"$1,400,000","D":"$300,000"},"correctOption":"A","correctAnswer":"$600,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net assets = Non-current assets ($850,000) + Working capital ($150,000) - Non-current liabilities ($400,000) = $600,000, which equals Total shareholders' equity.","distractor_reasons":{"A":"Option A is correct because Net assets = Non-current assets ($850,000) + Working capital ($150,000) - Non-current liabilities ($400,000) = $600,000, which equals Total shareholders' equity.","B":"Incorrect because $1,000,000 is capital employed ($850,000 + $150,000), which has not yet deducted the $400,000 non-current liabilities.","C":"Incorrect because $1,400,000 adds non-current liabilities instead of subtracting them.","D":"Incorrect because $300,000 subtracts working capital instead of adding it."}}},{"id":"P1_U5_MCQ_344","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_344","question":"How do shareholders use a company's statement of financial position at the end of the financial year?","options":{"A":"To check whether the net worth (equity) of the business has grown and whether debt levels (non-current liabilities) are safely managed","B":"To calculate the exact hourly wage rate of every factory worker","C":"To decide which raw material suppliers offer the best bulk discounts","D":"To replace the statement of profit or loss when calculating gross profit margin"},"correctOption":"A","correctAnswer":"To check whether the net worth (equity) of the business has grown and whether debt levels (non-current liabilities) are safely managed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholders track changes in equity/retained profit and debt levels to see if their investment is growing safely in value.","distractor_reasons":{"A":"Option A is correct because shareholders track changes in equity/retained profit and debt levels to see if their investment is growing safely in value.","B":"Incorrect because hourly wage rates are operational payroll details, not shown on the statement of financial position.","C":"Incorrect because supplier procurement decisions are made by purchasing managers.","D":"Incorrect because gross profit margin is calculated from the statement of profit or loss."}}},{"id":"P1_U5_MCQ_345","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_345","question":"A packaging supplier asks to inspect a new retail customer's statement of financial position before offering $30,000 of goods on 60-day credit. Which figures will the supplier examine most closely?","options":{"A":"The historical date when the retail company's founders were born","B":"Current assets (especially cash and trade receivables) compared with current liabilities to ensure short-term bills can be paid","C":"The retail customer's annual advertising budget","D":"The retail customer's total share capital alone"},"correctOption":"B","correctAnswer":"Current assets (especially cash and trade receivables) compared with current liabilities to ensure short-term bills can be paid","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because trade suppliers need to know whether a credit customer holds enough liquid current assets to settle short-term liabilities within 60 days.","distractor_reasons":{"A":"Incorrect because personal biographical dates are irrelevant and not in financial statements.","B":"Option B is correct because trade suppliers need to know whether a credit customer holds enough liquid current assets to settle short-term liabilities within 60 days.","C":"Incorrect because advertising expenditure appears on the statement of profit or loss and does not prove short-term liquidity.","D":"Incorrect because high historical share capital could still be tied up in illiquid buildings while the firm lacks cash."}}},{"id":"P1_U5_MCQ_346","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_346","question":"Why are intangible assets like brand reputation, customer loyalty, and skilled employees usually NOT shown with a dollar value on a standard statement of financial position?","options":{"A":"Because they are difficult to measure objectively in reliable monetary terms, which is a limitation of financial statements","B":"Because brand reputation and skilled staff have zero impact on business success","C":"Because they are classified as current liabilities","D":"Because companies are fined if they employ skilled workers"},"correctOption":"A","correctAnswer":"Because they are difficult to measure objectively in reliable monetary terms, which is a limitation of financial statements","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because accounting statements primarily record verifiable financial transactions and physical/monetary assets, omitting qualitative strengths like staff talent and brand loyalty.","distractor_reasons":{"A":"Option A is correct because accounting statements primarily record verifiable financial transactions and physical/monetary assets, omitting qualitative strengths like staff talent and brand loyalty.","B":"Incorrect because brand reputation and skilled staff are major drivers of competitive advantage.","C":"Incorrect because they are intangible strengths, not financial debts.","D":"Incorrect because skilled staff are an asset to operations, never penalized."}}},{"id":"P1_U5_MCQ_347","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_347","question":"A toy manufacturer buys $30,000 of plastic pellets on 45-day trade credit. How does this purchase affect the manufacturer's statement of financial position?","options":{"A":"Non-current liabilities increase by $30,000 and working capital falls by $30,000","B":"Current assets (cash) decrease by $30,000 and non-current assets increase by $30,000","C":"Shareholders' equity increases by $30,000 and current liabilities decrease by $30,000","D":"Current assets (inventory) increase by $30,000 and current liabilities (trade payables) increase by $30,000"},"correctOption":"D","correctAnswer":"Current assets (inventory) increase by $30,000 and current liabilities (trade payables) increase by $30,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because raw material inventory rises by $30,000 (current asset) and money owed to suppliers rises by $30,000 (current liability).","distractor_reasons":{"A":"Incorrect because 45-day trade credit is a current liability, and working capital remains unchanged.","B":"Incorrect because no cash was paid yet and plastic pellets are inventory (current asset), not a non-current asset.","C":"Incorrect because buying materials on credit creates a liability rather than increasing equity.","D":"Option D is correct because raw material inventory rises by $30,000 (current asset) and money owed to suppliers rises by $30,000 (current liability)."}}},{"id":"P1_U5_MCQ_348","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_348","question":"A hotel group's statement of financial position shows non-current assets of $1,200,000, inventory of $30,000, trade receivables of $45,000, cash of $25,000, current liabilities of $80,000, and non-current liabilities of $520,000. What is the hotel group's total assets?","options":{"A":"$700,000","B":"$1,200,000","C":"$100,000","D":"$1,300,000"},"correctOption":"D","correctAnswer":"$1,300,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Total assets = Non-current assets ($1,200,000) + Current assets ($30,000 + $45,000 + $25,000 = $100,000) = $1,300,000.","distractor_reasons":{"A":"Incorrect because $700,000 is total shareholders' equity / net assets ($1,300,000 - $80,000 - $520,000).","B":"Incorrect because $1,200,000 includes only non-current assets.","C":"Incorrect because $100,000 includes only current assets.","D":"Option D is correct because Total assets = Non-current assets ($1,200,000) + Current assets ($30,000 + $45,000 + $25,000 = $100,000) = $1,300,000."}}},{"id":"P1_U5_MCQ_349","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_349","question":"A wholesale distributor receives a $20,000 payment from a credit customer and immediately uses that $20,000 cash to pay a supplier invoice. What is the combined net effect of these two transactions on the statement of financial position?","options":{"A":"Working capital increases by $20,000","B":"Cash increases by $40,000 and equity increases by $40,000","C":"Non-current assets increase by $20,000 and non-current liabilities decrease by $20,000","D":"Trade receivables decrease by $20,000 and trade payables decrease by $20,000, while cash returns to its original level"},"correctOption":"D","correctAnswer":"Trade receivables decrease by $20,000 and trade payables decrease by $20,000, while cash returns to its original level","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because collecting from the customer reduces trade receivables (-$20,000) and adds cash (+$20,000), and paying the supplier removes that cash (-$20,000) and reduces trade payables (-$20,000).","distractor_reasons":{"A":"Incorrect because current assets fall by $20,000 and current liabilities also fall by $20,000, leaving working capital unchanged.","B":"Incorrect because the cash received was immediately paid out to the supplier.","C":"Incorrect because neither non-current assets nor non-current liabilities are involved.","D":"Option D is correct because collecting from the customer reduces trade receivables (-$20,000) and adds cash (+$20,000), and paying the supplier removes that cash (-$20,000) and reduces trade payables (-$20,000)."}}},{"id":"P1_U5_MCQ_350","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_350","question":"An agricultural cooperative's statement of financial position shows that 90% of its total assets are tied up in specialized grain silos and farmland, while its current liabilities exceed its current assets. What challenge does this asset structure create?","options":{"A":"An inability to calculate gross profit margin","B":"Excessive idle cash sitting in current accounts","C":"Zero collateral available for long-term mortgages","D":"Low liquidity: farmland and silos cannot be quickly turned into cash to pay urgent short-term bills"},"correctOption":"D","correctAnswer":"Low liquidity: farmland and silos cannot be quickly turned into cash to pay urgent short-term bills","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because non-current assets like farmland and silos are illiquid and take months to sell, leaving the cooperative vulnerable to short-term cash shortages.","distractor_reasons":{"A":"Incorrect because gross profit margin is calculated from the statement of profit or loss.","B":"Incorrect because current liabilities exceed current assets, indicating a shortage of cash rather than excess cash.","C":"Incorrect because farmland and silos actually provide strong collateral for long-term loans.","D":"Option D is correct because non-current assets like farmland and silos are illiquid and take months to sell, leaving the cooperative vulnerable to short-term cash shortages."}}},{"id":"P1_U5_MCQ_351","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_351","question":"Why is calculating ratios (such as profit margin or current ratio) often more informative than simply looking at raw dollar figures in a company's accounts?","options":{"A":"Ratios are legally guaranteed to remain constant every year","B":"Ratios eliminate the need to record revenue or expenses accurately","C":"Ratios allow meaningful comparisons across businesses of different sizes and across different years by relating one figure to another","D":"Ratios convert non-current liabilities into shareholders' equity"},"correctOption":"C","correctAnswer":"Ratios allow meaningful comparisons across businesses of different sizes and across different years by relating one figure to another","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because raw profit of $100,000 means very different things for a small shop versus a giant supermarket; ratios express performance relative to sales, capital, or debts.","distractor_reasons":{"A":"Incorrect because ratios change whenever trading performance or asset balances shift.","B":"Incorrect because accurate underlying financial data is essential to compute valid ratios.","C":"Option C is correct because raw profit of $100,000 means very different things for a small shop versus a giant supermarket; ratios express performance relative to sales, capital, or debts.","D":"Incorrect because ratios are analytical tools and do not alter accounting classifications."}}},{"id":"P1_U5_MCQ_352","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_352","question":"A stationery retailer reports annual revenue of $650,000, cost of sales of $390,000, and overhead expenses of $162,500. What is the retailer's gross profit margin?","options":{"A":"25%","B":"15%","C":"60%","D":"40%"},"correctOption":"D","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Gross profit = $650,000 - $390,000 = $260,000, and Gross profit margin = ($260,000 / $650,000) × 100 = 40%.","distractor_reasons":{"A":"Incorrect because 25% is overhead expenses as a percentage of revenue ($162,500 / $650,000 × 100).","B":"Incorrect because 15% is the profit margin ($97,500 / $650,000 × 100).","C":"Incorrect because 60% is cost of sales as a percentage of revenue ($390,000 / $650,000 × 100).","D":"Option D is correct because Gross profit = $650,000 - $390,000 = $260,000, and Gross profit margin = ($260,000 / $650,000) × 100 = 40%."}}},{"id":"P1_U5_MCQ_353","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_353","question":"A café chain's gross profit margin rose from 58% to 64% over the past year. Which change best explains this improvement?","options":{"A":"The chain negotiated cheaper wholesale coffee and food ingredient contracts while slightly raising menu prices","B":"The chain reduced its head-office marketing budget","C":"The chain repaid a 5-year bank loan early","D":"The chain sold an unused delivery van for cash"},"correctOption":"A","correctAnswer":"The chain negotiated cheaper wholesale coffee and food ingredient contracts while slightly raising menu prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because gross profit margin increases when selling prices rise relative to direct cost of sales (ingredients).","distractor_reasons":{"A":"Option A is correct because gross profit margin increases when selling prices rise relative to direct cost of sales (ingredients).","B":"Incorrect because marketing is an indirect overhead expense that affects profit margin, not gross profit margin.","C":"Incorrect because repaying a bank loan does not affect gross profit margin.","D":"Incorrect because selling a non-current asset does not affect gross profit margin."}}},{"id":"P1_U5_MCQ_354","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_354","question":"An interior design company generates annual revenue of $750,000, gross profit of $450,000, and final profit of $135,000. What is the company's profit margin?","options":{"A":"42%","B":"60%","C":"30%","D":"18%"},"correctOption":"D","correctAnswer":"18%","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Profit margin = (Profit / Revenue) × 100 = ($135,000 / $750,000) × 100 = 18%.","distractor_reasons":{"A":"Incorrect because 42% subtracts profit margin from gross profit margin (60% - 18%).","B":"Incorrect because 60% is the gross profit margin ($450,000 / $750,000 × 100).","C":"Incorrect because 30% divides profit by gross profit ($135,000 / $450,000 × 100) instead of dividing by revenue.","D":"Option D is correct because Profit margin = (Profit / Revenue) × 100 = ($135,000 / $750,000) × 100 = 18%."}}},{"id":"P1_U5_MCQ_355","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_355","question":"A supermarket's gross profit margin stayed unchanged at 26% for two consecutive years, yet its profit margin dropped from 8% to 4.5%. What does this indicate?","options":{"A":"Indirect overhead expenses such as store wages, energy bills, or rent increased faster than sales revenue","B":"The cost of groceries bought from suppliers doubled","C":"The supermarket's current ratio rose above 2 : 1","D":"The supermarket cut its retail grocery prices by half"},"correctOption":"A","correctAnswer":"Indirect overhead expenses such as store wages, energy bills, or rent increased faster than sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a steady gross profit margin paired with a falling profit margin shows that expenses deducted below gross profit grew disproportionately.","distractor_reasons":{"A":"Option A is correct because a steady gross profit margin paired with a falling profit margin shows that expenses deducted below gross profit grew disproportionately.","B":"Incorrect because doubling supplier grocery costs would have reduced the gross profit margin.","C":"Incorrect because profitability margins do not measure the current ratio.","D":"Incorrect because cutting retail prices in half would have collapsed the gross profit margin."}}},{"id":"P1_U5_MCQ_356","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_356","question":"A packaging company earns an annual profit of $210,000, and its statement of financial position shows shareholders' equity of $900,000 and non-current liabilities of $500,000. What is the company's Return on Capital Employed (ROCE)?","options":{"A":"52.5%","B":"23.3%","C":"42%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Capital employed = Equity ($900,000) + Non-current liabilities ($500,000) = $1,400,000, and ROCE = ($210,000 / $1,400,000) × 100 = 15%.","distractor_reasons":{"A":"Incorrect because 52.5% divides profit by the difference between equity and debt ($210,000 / $400,000 × 100).","B":"Incorrect because 23.3% divides profit only by equity ($210,000 / $900,000 × 100), omitting non-current liabilities.","C":"Incorrect because 42% divides profit only by non-current liabilities ($210,000 / $500,000 × 100).","D":"Option D is correct because Capital employed = Equity ($900,000) + Non-current liabilities ($500,000) = $1,400,000, and ROCE = ($210,000 / $1,400,000) × 100 = 15%."}}},{"id":"P1_U5_MCQ_357","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_357","question":"A business has current assets of $90,000, of which $30,000 is inventory, and current liabilities of $50,000. What is its acid-test ratio?","options":{"A":"0.6:1","B":"1.2:1","C":"1.8:1","D":"2:1"},"correctOption":"B","correctAnswer":"1.2:1","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the acid-test ratio is (current assets minus inventory) divided by current liabilities, so ($90,000 - $30,000)/$50,000 = 1.2:1.","distractor_reasons":{"B":"Option B is correct because the acid-test ratio is (current assets minus inventory) divided by current liabilities, so ($90,000 - $30,000)/$50,000 = 1.2:1.","A":"Incorrect because 0.6:1 comes from dividing the $30,000 of inventory by current liabilities instead of using liquid assets.","C":"Incorrect because 1.8:1 comes from dividing total current assets by current liabilities, which gives the current ratio, not the acid-test ratio.","D":"Incorrect because 2:1 would require liquid assets of $100,000 with liabilities of $50,000, which is not the case here."}}},{"id":"P1_U5_MCQ_358","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_358","question":"A retail chain increases its annual profit from $150,000 to $195,000 while keeping its capital employed unchanged at $1,000,000. How does its ROCE change?","options":{"A":"ROCE rises from 15% to 19.5%","B":"ROCE falls from 19.5% to 15%","C":"ROCE stays unchanged at 15%","D":"ROCE rises to 45%"},"correctOption":"A","correctAnswer":"ROCE rises from 15% to 19.5%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Year 1 ROCE = ($150,000 / $1,000,000) × 100 = 15%, and Year 2 ROCE = ($195,000 / $1,000,000) × 100 = 19.5%.","distractor_reasons":{"A":"Option A is correct because Year 1 ROCE = ($150,000 / $1,000,000) × 100 = 15%, and Year 2 ROCE = ($195,000 / $1,000,000) × 100 = 19.5%.","B":"Incorrect because profit increased rather than decreased, so ROCE improved.","C":"Incorrect because higher profit with constant capital employed raises ROCE.","D":"Incorrect because $45,000 is the dollar profit increase, which represents a 4.5 percentage point rise, not 45%."}}},{"id":"P1_U5_MCQ_359","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_359","question":"An electronics wholesaler has inventory of $60,000, trade receivables of $45,000, cash of $15,000, trade payables of $50,000, and a bank overdraft of $30,000. What is the wholesaler's current ratio?","options":{"A":"1.5 : 1","B":"0.75 : 1","C":"0.67 : 1","D":"2.4 : 1"},"correctOption":"A","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Current assets = $60,000 + $45,000 + $15,000 = $120,000 and Current liabilities = $50,000 + $30,000 = $80,000, giving Current ratio = $120,000 / $80,000 = 1.5 : 1.","distractor_reasons":{"A":"Option A is correct because Current assets = $60,000 + $45,000 + $15,000 = $120,000 and Current liabilities = $50,000 + $30,000 = $80,000, giving Current ratio = $120,000 / $80,000 = 1.5 : 1.","B":"Incorrect because 0.75 : 1 is the acid-test ratio (($120,000 - $60,000) / $80,000).","C":"Incorrect because 0.67 : 1 divides current liabilities by current assets ($80,000 / $120,000).","D":"Incorrect because 2.4 : 1 omits the $30,000 bank overdraft from current liabilities ($120,000 / $50,000)."}}},{"id":"P1_U5_MCQ_360","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_360","question":"A restaurant group's current ratio has declined steadily over three years from 1.8 : 1 to 1.2 : 1 and now stands at 0.8 : 1. What does this trend show?","options":{"A":"The group's gross profit margin has risen to 80%","B":"The group's liquidity is deteriorating, and its short-term debts now exceed its current assets","C":"The group holds $1.80 of cash for every $1 of debt","D":"The group has paid off all of its trade payables"},"correctOption":"B","correctAnswer":"The group's liquidity is deteriorating, and its short-term debts now exceed its current assets","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a falling current ratio that drops below 1 : 1 warns that short-term liabilities are growing faster than current assets, creating insolvency risk.","distractor_reasons":{"A":"Incorrect because the current ratio measures liquidity, not gross profit margin.","B":"Option B is correct because a falling current ratio that drops below 1 : 1 warns that short-term liabilities are growing faster than current assets, creating insolvency risk.","C":"Incorrect because 0.8 : 1 means $0.80 of current assets per $1 of current liabilities.","D":"Incorrect because paying off trade payables would improve rather than reduce a low current ratio."}}},{"id":"P1_U5_MCQ_361","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_361","question":"A furniture distributor has current assets of $195,000 (including $105,000 of inventory) and current liabilities of $75,000. What is the distributor's acid-test ratio?","options":{"A":"1.4 : 1","B":"2.6 : 1","C":"1.2 : 1","D":"0.83 : 1"},"correctOption":"C","correctAnswer":"1.2 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($195,000 - $105,000) / $75,000 = $90,000 / $75,000 = 1.2 : 1.","distractor_reasons":{"A":"Incorrect because 1.4 : 1 divides inventory by current liabilities ($105,000 / $75,000).","B":"Incorrect because 2.6 : 1 is the current ratio ($195,000 / $75,000), which fails to remove inventory.","C":"Option C is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($195,000 - $105,000) / $75,000 = $90,000 / $75,000 = 1.2 : 1.","D":"Incorrect because 0.83 : 1 inverts the formula ($75,000 / $90,000)."}}},{"id":"P1_U5_MCQ_362","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_362","question":"A jeweller has a current ratio of 3.5 : 1, but its acid-test ratio is only 0.4 : 1. Why is the acid-test ratio so much lower than the current ratio?","options":{"A":"Because almost all of the jeweller's current assets consist of expensive, slow-moving inventory rather than cash or receivables","B":"Because the jeweller has zero current liabilities","C":"Because non-current assets are included in the current ratio","D":"Because the jeweller's profit margin is negative"},"correctOption":"A","correctAnswer":"Because almost all of the jeweller's current assets consist of expensive, slow-moving inventory rather than cash or receivables","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because subtracting inventory causes the ratio to plunge from 3.5 : 1 to 0.4 : 1, proving that high-value stock accounts for the vast majority of current assets.","distractor_reasons":{"A":"Option A is correct because subtracting inventory causes the ratio to plunge from 3.5 : 1 to 0.4 : 1, proving that high-value stock accounts for the vast majority of current assets.","B":"Incorrect because current liabilities are the denominator in both ratios.","C":"Incorrect because non-current assets are excluded from both liquidity ratios.","D":"Incorrect because liquidity ratios do not measure profit margins."}}},{"id":"P1_U5_MCQ_363","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_363","question":"An engineering firm's acid-test ratio has dropped to 0.65 : 1, worrying its bank manager. Which action would directly improve the firm's acid-test ratio?","options":{"A":"Buying more steel inventory on 30-day trade credit","B":"Using existing cash to purchase extra steel inventory","C":"Selling unused factory machinery for cash or taking a long-term loan to pay off a short-term bank overdraft","D":"Paying cash dividends to shareholders"},"correctOption":"C","correctAnswer":"Selling unused factory machinery for cash or taking a long-term loan to pay off a short-term bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because selling unwanted non-current assets increases cash (liquid assets), while replacing a short-term overdraft with a long-term loan reduces current liabilities.","distractor_reasons":{"A":"Incorrect because buying inventory on credit increases current liabilities without raising liquid assets.","B":"Incorrect because turning cash into inventory reduces the acid-test numerator (since inventory is excluded).","C":"Option C is correct because selling unwanted non-current assets increases cash (liquid assets), while replacing a short-term overdraft with a long-term loan reduces current liabilities.","D":"Incorrect because paying cash dividends reduces cash and lowers the acid-test ratio."}}},{"id":"P1_U5_MCQ_364","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_364","question":"A supermarket currently has liquid assets (cash + receivables) of $90,000 and current liabilities of $90,000, giving an acid-test ratio of 1.0 : 1. If the supermarket uses $20,000 of its cash to buy fresh food inventory, what happens to its acid-test ratio?","options":{"A":"It falls from 1.0 : 1 to 0.78 : 1 because cash decreases by $20,000 while inventory is excluded from the acid-test numerator","B":"It stays at 1.0 : 1 because cash and inventory are both current assets","C":"It rises to 1.22 : 1","D":"It falls to 0 : 1"},"correctOption":"A","correctAnswer":"It falls from 1.0 : 1 to 0.78 : 1 because cash decreases by $20,000 while inventory is excluded from the acid-test numerator","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because liquid assets (excluding inventory) drop from $90,000 to $70,000 while current liabilities stay at $90,000, giving $70,000 / $90,000 = 0.78 : 1.","distractor_reasons":{"A":"Option A is correct because liquid assets (excluding inventory) drop from $90,000 to $70,000 while current liabilities stay at $90,000, giving $70,000 / $90,000 = 0.78 : 1.","B":"Incorrect because while the current ratio stays at 1.0 : 1, the acid-test ratio excludes inventory.","C":"Incorrect because spending cash on inventory lowers rather than raises the acid-test ratio.","D":"Incorrect because $70,000 of liquid assets still remain."}}},{"id":"P1_U5_MCQ_365","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_365","question":"How do internal managers use profitability and liquidity ratios when planning next year's business strategy?","options":{"A":"To decide whether to approve personal bank loans for customers","B":"To calculate how much corporation tax rival companies owe","C":"To spot falling profit margins caused by rising costs, identify weak liquidity before cash runs out, and set departmental financial targets","D":"To replace the need for market research when launching new products"},"correctOption":"C","correctAnswer":"To spot falling profit margins caused by rising costs, identify weak liquidity before cash runs out, and set departmental financial targets","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because managers are internal users who rely on ratio trends to diagnose operational weaknesses, control expenses, and safeguard liquidity.","distractor_reasons":{"A":"Incorrect because personal loans are assessed by external commercial banks.","B":"Incorrect because tax assessment is carried out by external government tax authorities.","C":"Option C is correct because managers are internal users who rely on ratio trends to diagnose operational weaknesses, control expenses, and safeguard liquidity.","D":"Incorrect because financial ratios cannot replace primary or secondary market research."}}},{"id":"P1_U5_MCQ_366","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_366","question":"An investor owns shares in a pharmaceutical company and notices that its ROCE has fallen from 21% to 9% over two years while its profit margin halved. How is this ratio analysis likely to influence the investor?","options":{"A":"The investor may sell their shares and invest in a rival company offering a higher return on capital","B":"The investor will immediately increase the company's inventory levels","C":"The investor will grant the company a 10-year commercial mortgage","D":"The investor will reduce the company's corporation tax rate"},"correctOption":"A","correctAnswer":"The investor may sell their shares and invest in a rival company offering a higher return on capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholders use profitability ratios to judge returns and management performance; falling ROCE often prompts investors to sell shares.","distractor_reasons":{"A":"Option A is correct because shareholders use profitability ratios to judge returns and management performance; falling ROCE often prompts investors to sell shares.","B":"Incorrect because outside shareholders do not manage day-to-day inventory levels.","C":"Incorrect because mortgages are provided by banks, not ordinary shareholders.","D":"Incorrect because tax rates are set by the government."}}},{"id":"P1_U5_MCQ_367","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_367","question":"A commercial bank is evaluating loan applications from two delivery firms: Firm X has a current ratio of 1.8 : 1 and an acid-test ratio of 1.3 : 1, while Firm Y has a current ratio of 0.7 : 1 and an acid-test ratio of 0.4 : 1. Which firm is a safer lending prospect for the bank?","options":{"A":"Firm X, because its strong liquidity ratios show it can comfortably pay short-term debts and regular loan interest","B":"Firm Y, because banks prefer lending to firms with liquidity ratios below 1 : 1","C":"Firm Y, because lower liquidity ratios automatically mean higher profit margins","D":"Neither firm, because banks never look at liquidity ratios when lending"},"correctOption":"A","correctAnswer":"Firm X, because its strong liquidity ratios show it can comfortably pay short-term debts and regular loan interest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Firm X has healthy liquidity ratios within safe benchmarks, demonstrating lower risk of defaulting on loan repayments.","distractor_reasons":{"A":"Option A is correct because Firm X has healthy liquidity ratios within safe benchmarks, demonstrating lower risk of defaulting on loan repayments.","B":"Incorrect because ratios below 1 : 1 signal high default risk, which banks avoid.","C":"Incorrect because low liquidity ratios do not imply higher profit margins.","D":"Incorrect because liquidity ratios and existing debt are central to bank credit assessments."}}},{"id":"P1_U5_MCQ_368","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_368","question":"A flour mill receives a large credit order from a new bakery chain. Before granting 60 days of trade credit, the flour mill's credit controller checks the bakery's current ratio and acid-test ratio. Why?","options":{"A":"To calculate how many loaves of bread the bakery bakes per hour","B":"To check whether the bakery has enough liquid assets to pay the flour invoice on time in 60 days","C":"To decide whether to buy ordinary shares in the bakery","D":"To determine the bakery's corporation tax bill"},"correctOption":"B","correctAnswer":"To check whether the bakery has enough liquid assets to pay the flour invoice on time in 60 days","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because suppliers are external trade creditors who rely on a customer's short-term liquidity to ensure invoices are paid without bad-debt losses.","distractor_reasons":{"A":"Incorrect because hourly baking output is an internal production metric.","B":"Option B is correct because suppliers are external trade creditors who rely on a customer's short-term liquidity to ensure invoices are paid without bad-debt losses.","C":"Incorrect because a supplier wants prompt payment for goods, not equity ownership.","D":"Incorrect because tax calculations are handled by government tax authorities."}}},{"id":"P1_U5_MCQ_369","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_369","question":"During annual wage negotiations, a factory's trade union points to the company's rising profit margin (up from 9% to 15%) and strong liquidity ratios. How are employees using these financial accounts?","options":{"A":"To demonstrate that the company is financially secure and can afford to pay higher wages without threatening jobs","B":"To approve a new 15-year mortgage for the company","C":"To calculate the company's import customs duties","D":"To value the company's machinery for resale"},"correctOption":"A","correctAnswer":"To demonstrate that the company is financially secure and can afford to pay higher wages without threatening jobs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employees and unions examine profitability and liquidity to assess job security and negotiate fair pay increases when profits grow.","distractor_reasons":{"A":"Option A is correct because employees and unions examine profitability and liquidity to assess job security and negotiate fair pay increases when profits grow.","B":"Incorrect because mortgages are approved by banks.","C":"Incorrect because customs duties are assessed by government authorities.","D":"Incorrect because machinery valuation is performed by accountants/valuers."}}},{"id":"P1_U5_MCQ_370","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_370","question":"Why do government departments and tax authorities require incorporated businesses to submit annual financial statements?","options":{"A":"To verify reported profits so the correct amount of corporation tax is collected and to monitor economic activity across industries","B":"To set the retail prices that private businesses must charge customers","C":"To decide which employees should be promoted inside private companies","D":"To guarantee that every company achieves an ROCE of at least 20%"},"correctOption":"A","correctAnswer":"To verify reported profits so the correct amount of corporation tax is collected and to monitor economic activity across industries","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because governments use company accounts to assess taxes accurately and track business sector performance and compliance.","distractor_reasons":{"A":"Option A is correct because governments use company accounts to assess taxes accurately and track business sector performance and compliance.","B":"Incorrect because private firms set their own prices in market economies.","C":"Incorrect because internal promotions are HR decisions made by company managers.","D":"Incorrect because governments do not guarantee private sector ROCE."}}},{"id":"P1_U5_MCQ_371","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_371","question":"A company's current ratio is 2.5:1 and its acid-test ratio is 1.5:1. What can be concluded from these two figures?","options":{"A":"Inventories make up a significant part of its current assets","B":"Its profitability has improved compared with last year","C":"It has no current liabilities to worry about","D":"Its sales revenue has fallen sharply"},"correctOption":"A","correctAnswer":"Inventories make up a significant part of its current assets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the acid-test ratio is lower than the current ratio, and the difference is caused by inventories being excluded from liquid assets.","distractor_reasons":{"A":"Option A is correct because the acid-test ratio is lower than the current ratio, and the difference is caused by inventories being excluded from liquid assets.","B":"Incorrect because both ratios measure liquidity and cannot reveal whether profitability has improved.","C":"Incorrect because both ratios are calculated using current liabilities, which clearly exist and are non-zero.","D":"Incorrect because these liquidity ratios provide no information about changes in sales revenue."}}},{"id":"P1_U5_MCQ_372","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_372","question":"A travel agency published strong profit margins and liquidity ratios for the year ended 31 December, yet by March of the following year it entered bankruptcy after a volcanic eruption halted all international flights. Which limitation of accounting analysis does this demonstrate?","options":{"A":"Profit margins are calculated using future estimated sales","B":"Published accounts are allowed to hide all current liabilities","C":"Ratio analysis only applies to manufacturing businesses","D":"Financial accounts are historical records of past performance and cannot foresee sudden external shocks or guarantee future success"},"correctOption":"D","correctAnswer":"Financial accounts are historical records of past performance and cannot foresee sudden external shocks or guarantee future success","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because published financial statements look backward at past periods and cannot predict unexpected external disruptions.","distractor_reasons":{"A":"Incorrect because published profit margins are based on historical actual results.","B":"Incorrect because hiding liabilities in published accounts is illegal.","C":"Incorrect because ratio analysis is used across service, retail, and manufacturing sectors.","D":"Option D is correct because published financial statements look backward at past periods and cannot predict unexpected external disruptions."}}},{"id":"P1_U5_MCQ_373","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_373","question":"Two rival logistics companies, FastFreight Ltd and SwiftHaul Ltd, earn identical annual profits of $120,000, but FastFreight values its older warehouses at historical cost ($400,000) while SwiftHaul revalues its identical warehouses at current market value ($800,000). How does this affect their ROCE comparison?","options":{"A":"FastFreight appears to have double the ROCE (30% vs 15%) purely due to different asset valuation methods rather than superior operational performance","B":"Both companies will still show the exact same ROCE","C":"SwiftHaul's gross profit margin will be twice as high as FastFreight's","D":"Asset valuation differences only affect the acid-test ratio"},"correctOption":"A","correctAnswer":"FastFreight appears to have double the ROCE (30% vs 15%) purely due to different asset valuation methods rather than superior operational performance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because different accounting policies for valuing non-current assets change capital employed, distorting ROCE comparisons between firms.","distractor_reasons":{"A":"Option A is correct because different accounting policies for valuing non-current assets change capital employed, distorting ROCE comparisons between firms.","B":"Incorrect because capital employed differs ($400,000 vs $800,000), producing different ROCE percentages.","C":"Incorrect because warehouse valuation sits on the statement of financial position and does not alter gross profit margin.","D":"Incorrect because non-current warehouse values are excluded from the acid-test ratio."}}},{"id":"P1_U5_MCQ_374","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_374","question":"A chemical manufacturer reports rising ROCE and healthy liquidity ratios, yet local communities are protesting toxic river pollution and customers are boycotting its products on social media. What limitation of relying purely on financial ratios does this highlight?","options":{"A":"Liquidity ratios automatically include social media sentiment scores","B":"Ratios only measure short-term cash outflows","C":"Published accounts are prohibited from showing profit margins","D":"Financial accounts ignore qualitative non-financial factors such as environmental impact, ethical reputation, and customer sentiment"},"correctOption":"D","correctAnswer":"Financial accounts ignore qualitative non-financial factors such as environmental impact, ethical reputation, and customer sentiment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because accounting ratios capture purely quantitative financial data and miss critical non-financial risks like environmental damage and reputational backlash.","distractor_reasons":{"A":"Incorrect because liquidity ratios only use current assets, inventory, and current liabilities.","B":"Incorrect because profitability ratios measure profit relative to revenue or capital, not cash outflows.","C":"Incorrect because profit margins are routinely calculated from published statements.","D":"Option D is correct because accounting ratios capture purely quantitative financial data and miss critical non-financial risks like environmental damage and reputational backlash."}}},{"id":"P1_U5_MCQ_375","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_375","question":"A company borrows a short-term cash sum the day before its financial year-end to inflate its closing cash balance on the statement of financial position, then repays it the next day. Why is this practice ('window dressing') a limitation when external stakeholders analyse accounts?","options":{"A":"It turns current liabilities into retained profit","B":"It permanently increases the company's gross profit margin by 50%","C":"It eliminates all non-current assets from the accounts","D":"It makes the business's liquidity appear stronger on the reporting date than it actually is during normal daily operations"},"correctOption":"D","correctAnswer":"It makes the business's liquidity appear stronger on the reporting date than it actually is during normal daily operations","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a statement of financial position is a single-day snapshot, so temporary year-end adjustments can distort liquidity ratios and mislead lenders or suppliers.","distractor_reasons":{"A":"Incorrect because borrowed funds are liabilities, not retained profit.","B":"Incorrect because borrowing cash does not affect gross profit margin.","C":"Incorrect because non-current assets remain unaffected on the statement of financial position.","D":"Option D is correct because a statement of financial position is a single-day snapshot, so temporary year-end adjustments can distort liquidity ratios and mislead lenders or suppliers."}}},{"id":"P1_U5_MCQ_376","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_376","question":"An entrepreneur is launching a mobile pet-grooming business and needs $22,000 to register the business, buy grooming tables and clippers, and purchase initial shampoo supplies before serving her first client. What type of finance does she require?","options":{"A":"Trade credit from corporate customers","B":"Start-up capital","C":"Debt factoring finance","D":"Long-term expansion equity"},"correctOption":"B","correctAnswer":"Start-up capital","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because start-up capital is the finance needed by an entrepreneur to pay for initial set-up costs, essential equipment, and opening inventory before trading begins.","distractor_reasons":{"A":"Incorrect because trade credit is granted by suppliers to established buyers, not by customers.","B":"Option B is correct because start-up capital is the finance needed by an entrepreneur to pay for initial set-up costs, essential equipment, and opening inventory before trading begins.","C":"Incorrect because debt factoring sells existing unpaid customer invoices, which a pre-launch business does not yet have.","D":"Incorrect because expansion finance is used by established firms to grow, not to launch a new start-up."}}},{"id":"P1_U5_MCQ_377","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_377","question":"A profitable regional bakery chain plans to acquire a rival pastry manufacturer and build a new automated distribution warehouse. Which business financial need does this represent?","options":{"A":"Funding routine weekly wage bills","B":"Covering a temporary three-day overdraft","C":"Funding long-term business expansion","D":"Replacing a broken shop cash register"},"correctOption":"C","correctAnswer":"Funding long-term business expansion","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because taking over rival firms and constructing major facilities require large sums of long-term finance for business growth.","distractor_reasons":{"A":"Incorrect because weekly wages are short-term day-to-day working capital expenses.","B":"Incorrect because a three-day cash gap is a minor short-term liquidity fluctuation.","C":"Option C is correct because taking over rival firms and constructing major facilities require large sums of long-term finance for business growth.","D":"Incorrect because replacing a single register is minor routine maintenance."}}},{"id":"P1_U5_MCQ_378","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_378","question":"Every October, a toy wholesaler must spend $90,000 extra on stock and temporary warehouse staff to prepare for peak holiday orders, even though retail stores will not pay their invoices until January. What type of finance is needed here?","options":{"A":"Additional working capital","B":"Start-up capital","C":"Freehold property mortgage","D":"Permanent share capital"},"correctOption":"A","correctAnswer":"Additional working capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because additional working capital is needed to fund seasonal increases in inventory and running costs while waiting for credit customers to pay.","distractor_reasons":{"A":"Option A is correct because additional working capital is needed to fund seasonal increases in inventory and running costs while waiting for credit customers to pay.","B":"Incorrect because the wholesaler is an established seasonal business, not a new start-up.","C":"Incorrect because a mortgage is used to purchase long-term land or buildings.","D":"Incorrect because permanent share capital is unsuitable for a temporary three-month seasonal cash gap."}}},{"id":"P1_U5_MCQ_379","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_379","question":"How do accountants and business managers distinguish between short-term finance and long-term finance?","options":{"A":"Short-term finance is used only by sole traders, while long-term finance is used only by public limited companies","B":"Short-term finance never incurs interest, while long-term finance always incurs interest","C":"Short-term finance is internal, while long-term finance is always external","D":"Short-term finance is required for up to one year to cover day-to-day operations, while long-term finance is required for more than one year to fund non-current assets or growth"},"correctOption":"D","correctAnswer":"Short-term finance is required for up to one year to cover day-to-day operations, while long-term finance is required for more than one year to fund non-current assets or growth","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the standard financial distinction is a one-year time horizon: under 12 months for working capital needs versus over 12 months for capital investment.","distractor_reasons":{"A":"Incorrect because businesses of all legal structures use both short-term and long-term finance.","B":"Incorrect because short-term sources like bank overdrafts do charge interest.","C":"Incorrect because short-term finance includes external sources like overdrafts and trade credit, while long-term finance includes internal retained profit.","D":"Option D is correct because the standard financial distinction is a one-year time horizon: under 12 months for working capital needs versus over 12 months for capital investment."}}},{"id":"P1_U5_MCQ_380","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_380","question":"Why is retained profit unavailable as a source of finance for a brand-new start-up business?","options":{"A":"Retained profit is legally classified as a current liability","B":"Government regulations forbid new businesses from keeping any profit for three years","C":"Retained profit can only be used to pay bank overdraft interest","D":"New businesses have not yet traded long enough to earn and accumulate past profits"},"correctOption":"D","correctAnswer":"New businesses have not yet traded long enough to earn and accumulate past profits","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retained profit comes from profits earned in previous trading years after tax and dividends, which a newly formed business does not yet possess.","distractor_reasons":{"A":"Incorrect because retained profit forms part of owners' or shareholders' equity.","B":"Incorrect because there is no law preventing new businesses from retaining profits once earned.","C":"Incorrect because retained profit can be reinvested in any area of the business.","D":"Option D is correct because retained profit comes from profits earned in previous trading years after tax and dividends, which a newly formed business does not yet possess."}}},{"id":"P1_U5_MCQ_381","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_381","question":"A manufacturing firm raises $55,000 internally by selling off surplus machinery and an unused storage yard. What is a potential disadvantage of raising finance through the sale of existing assets?","options":{"A":"The firm must pay high annual interest on the cash received","B":"It can take a long time to find a buyer, and the assets may sell for less than their book value","C":"The buyer gains voting shares in the manufacturing firm","D":"The cash received must be repaid to the buyer within 12 months"},"correctOption":"B","correctAnswer":"It can take a long time to find a buyer, and the assets may sell for less than their book value","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-current assets like machinery and property can be slow to sell, may fetch lower prices in urgent sales, and are no longer available if needed later.","distractor_reasons":{"A":"Incorrect because selling owned assets is internal finance and incurs no interest.","B":"Option B is correct because non-current assets like machinery and property can be slow to sell, may fetch lower prices in urgent sales, and are no longer available if needed later.","C":"Incorrect because asset buyers acquire physical equipment or land, not company shares.","D":"Incorrect because an outright asset sale generates permanent cash with no repayment obligation."}}},{"id":"P1_U5_MCQ_382","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_382","question":"A building supplies merchant frees up $40,000 of internal cash by reducing its warehouse inventory of bricks and timber to lower levels. What is a major risk of relying on inventory reduction to raise finance?","options":{"A":"The merchant may run out of stock during sudden demand surges and lose customers to rivals","B":"Warehouse storage and insurance costs will double","C":"The merchant's non-current liabilities will increase by $40,000","D":"Suppliers will be forced to pay interest to the merchant"},"correctOption":"A","correctAnswer":"The merchant may run out of stock during sudden demand surges and lose customers to rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting inventory levels releases working capital cash and saves storage costs, but leaves less buffer stock to meet unexpected orders.","distractor_reasons":{"A":"Option A is correct because cutting inventory levels releases working capital cash and saves storage costs, but leaves less buffer stock to meet unexpected orders.","B":"Incorrect because holding smaller inventory lowers rather than increases storage and insurance costs.","C":"Incorrect because reducing inventory is an internal working capital adjustment that creates no debt.","D":"Incorrect because reducing inventory does not obligate suppliers to pay interest."}}},{"id":"P1_U5_MCQ_383","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_383","question":"Two partners running an independent architecture practice each invest $15,000 of their personal savings to buy new 3D-printing equipment. What is a key advantage of using owners' savings as a source of finance?","options":{"A":"It is quickly available without complex bank loan applications, incurs no interest charges, and keeps full control with the partners","B":"It gives the partners limited liability for all partnership debts","C":"It guarantees unlimited amounts of capital whenever the practice expands","D":"It is tax-deductible as an immediate operating expense"},"correctOption":"A","correctAnswer":"It is quickly available without complex bank loan applications, incurs no interest charges, and keeps full control with the partners","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because owners' personal savings are an internal source that avoids borrowing costs, collateral requirements, and external interference.","distractor_reasons":{"A":"Option A is correct because owners' personal savings are an internal source that avoids borrowing costs, collateral requirements, and external interference.","B":"Incorrect because ordinary partnerships still have unlimited liability regardless of how equipment is funded.","C":"Incorrect because owners' personal savings are usually limited in amount.","D":"Incorrect because capital injected by owners is equity, not an operating expense."}}},{"id":"P1_U5_MCQ_384","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_384","question":"A regional government offers new businesses low-interest loans that must be repaid over five years. Which source of finance is being offered?","options":{"A":"A grant that does not need repaying","B":"A loan from an external body","C":"Retained profit","D":"Trade credit"},"correctOption":"B","correctAnswer":"A loan from an external body","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a low-interest loan is external finance provided by an outside organisation and must be repaid.","distractor_reasons":{"B":"Option B is correct because a low-interest loan is external finance provided by an outside organisation and must be repaid.","A":"Incorrect because a grant is a gift of money that does not have to be repaid, unlike this loan.","C":"Incorrect because retained profit is money generated within the business, not money offered by a government body.","D":"Incorrect because trade credit is an agreement to pay suppliers later and is not a government loan."}}},{"id":"P1_U5_MCQ_385","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_385","question":"A logistics company takes out a 7-year bank loan of $300,000 at a fixed interest rate to buy four refrigerated trucks. What is a major advantage of a fixed-rate bank loan for the company's financial planning?","options":{"A":"Monthly repayments remain predictable throughout the seven years, making cash flow budgeting easier, and ownership control is unaffected","B":"The loan never has to be repaid if profits fall","C":"No collateral or security is ever requested by banks for large loans","D":"The company pays zero interest over the seven-year period"},"correctOption":"A","correctAnswer":"Monthly repayments remain predictable throughout the seven years, making cash flow budgeting easier, and ownership control is unaffected","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a fixed-rate loan provides certainty over regular repayment amounts for cash flow forecasting while keeping 100% ownership with the business.","distractor_reasons":{"A":"Option A is correct because a fixed-rate loan provides certainty over regular repayment amounts for cash flow forecasting while keeping 100% ownership with the business.","B":"Incorrect because bank loans are legally binding obligations that must be repaid regardless of profit.","C":"Incorrect because banks usually require collateral (such as property or the trucks) to secure large loans.","D":"Incorrect because commercial bank loans always charge interest."}}},{"id":"P1_U5_MCQ_386","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_386","question":"A large public limited energy company raises $15 million by issuing debentures that pay 6% annual interest and mature in 12 years. How do debentures differ from ordinary shares?","options":{"A":"Debentures are non-repayable government grants","B":"Debenture holders become part-owners of the company with full voting rights at the AGM","C":"Debentures are short-term supplier invoices due within 30 days","D":"Debentures are long-term loan certificates that carry no voting rights and must be repaid at maturity with fixed interest"},"correctOption":"D","correctAnswer":"Debentures are long-term loan certificates that carry no voting rights and must be repaid at maturity with fixed interest","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because debentures are long-term debt instruments issued by companies; holders are creditors earning fixed interest rather than voting shareholders.","distractor_reasons":{"A":"Incorrect because debentures are repayable long-term debt raised from investors.","B":"Incorrect because ordinary shareholders hold voting ownership, whereas debenture holders are lenders.","C":"Incorrect because 30-day supplier invoices are trade credit.","D":"Option D is correct because debentures are long-term debt instruments issued by companies; holders are creditors earning fixed interest rather than voting shareholders."}}},{"id":"P1_U5_MCQ_387","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_387","question":"A clothing manufacturer sells $100,000 of unpaid retail store invoices to a debt factoring firm, receiving $85,000 in immediate cash while the factor collects the full $100,000 from the stores. Besides reducing profit by $15,000, what is another potential disadvantage of debt factoring?","options":{"A":"The manufacturer must wait an extra 90 days before receiving any cash","B":"The manufacturer must give the factoring firm 40% of its ordinary shares","C":"Aggressive debt collection methods used by the factoring firm could damage goodwill with loyal retail customers","D":"Debt factoring increases the manufacturer's non-current liabilities"},"correctOption":"C","correctAnswer":"Aggressive debt collection methods used by the factoring firm could damage goodwill with loyal retail customers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because handing customer invoice collection over to a third-party factor risks harsh payment chasing that can alienate valued buyers.","distractor_reasons":{"A":"Incorrect because factoring provides immediate cash upfront rather than delaying cash.","B":"Incorrect because debt factoring is a commercial service fee arrangement, not an equity investment.","C":"Option C is correct because handing customer invoice collection over to a third-party factor risks harsh payment chasing that can alienate valued buyers.","D":"Incorrect because factoring converts trade receivables into cash without creating long-term debt."}}},{"id":"P1_U5_MCQ_388","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_388","question":"A recycling company receives a $120,000 grant from a national environmental agency to install solar-powered sorting machinery. Which condition typically applies to grants from outside agencies?","options":{"A":"The money does not have to be repaid as long as the business uses it strictly for the approved project and meets set criteria","B":"The company must repay the grant with 12% compound interest over five years","C":"The agency takes permanent majority ownership of the recycling company","D":"The grant can be spent freely on shareholder dividends or executive cars"},"correctOption":"A","correctAnswer":"The money does not have to be repaid as long as the business uses it strictly for the approved project and meets set criteria","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because grants are non-repayable funds awarded by governments or agencies to support specific economic, social, or environmental goals.","distractor_reasons":{"A":"Option A is correct because grants are non-repayable funds awarded by governments or agencies to support specific economic, social, or environmental goals.","B":"Incorrect because grants do not require repayment or interest unless the recipient breaches the grant conditions.","C":"Incorrect because grants are subsidies rather than equity purchases.","D":"Incorrect because grants are strictly ring-fenced for approved purposes such as green equipment or job creation."}}},{"id":"P1_U5_MCQ_389","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_389","question":"A small printing company relies heavily on a $25,000 bank overdraft throughout the year to pay staff and suppliers. Why is relying permanently on a large bank overdraft risky?","options":{"A":"Overdrafts are legally banned for private limited companies","B":"Overdrafts require giving the bank a seat on the board of directors","C":"Overdrafts can only be used to buy freehold land and buildings","D":"The bank can demand full repayment of the overdraft at very short notice, and overdraft interest rates are usually high and variable"},"correctOption":"D","correctAnswer":"The bank can demand full repayment of the overdraft at very short notice, and overdraft interest rates are usually high and variable","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because overdrafts are repayable on demand and carry relatively high variable interest rates, making them dangerous for long-term funding.","distractor_reasons":{"A":"Incorrect because private limited companies routinely use bank overdrafts.","B":"Incorrect because banks do not join the board of directors when granting an overdraft.","C":"Incorrect because overdrafts are meant for short-term working capital, not long-term property purchases.","D":"Option D is correct because overdrafts are repayable on demand and carry relatively high variable interest rates, making them dangerous for long-term funding."}}},{"id":"P1_U5_MCQ_390","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_390","question":"A supermarket chain buys $200,000 of packaged food on 60-day trade credit from a supplier instead of paying immediately, thereby forfeiting a 3% early-payment discount. What is the hidden cost of using this trade credit?","options":{"A":"The supplier becomes a shareholder in the supermarket","B":"The supermarket must pay 20% bank interest to the supplier","C":"The supermarket's non-current assets fall by $200,000","D":"The supermarket loses the $6,000 cash discount it would have saved by paying immediately"},"correctOption":"D","correctAnswer":"The supermarket loses the $6,000 cash discount it would have saved by paying immediately","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because while trade credit appears 'interest-free', missing out on a 3% prompt-payment discount ($200,000 × 3% = $6,000) is an effective financing cost.","distractor_reasons":{"A":"Incorrect because trade credit creates a trade payable liability, not share ownership.","B":"Incorrect because suppliers offer early-settlement discounts rather than charging 20% bank interest.","C":"Incorrect because packaged food is current inventory, not a non-current asset.","D":"Option D is correct because while trade credit appears 'interest-free', missing out on a 3% prompt-payment discount ($200,000 × 3% = $6,000) is an effective financing cost."}}},{"id":"P1_U5_MCQ_391","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_391","question":"Which comparison accurately distinguishes between a bank overdraft and debt factoring as short-term sources of finance?","options":{"A":"An overdraft is only available to plcs, whereas debt factoring is only available to sole traders","B":"An overdraft is a long-term mortgage, whereas debt factoring is an internal source of finance","C":"An overdraft borrows extra cash from a bank up to an agreed limit, whereas debt factoring sells existing unpaid customer invoices to a specialist firm for immediate cash","D":"An overdraft never charges interest, whereas debt factoring never charges a fee"},"correctOption":"C","correctAnswer":"An overdraft borrows extra cash from a bank up to an agreed limit, whereas debt factoring sells existing unpaid customer invoices to a specialist firm for immediate cash","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an overdraft is short-term bank borrowing, whereas debt factoring converts existing trade receivables into immediate cash at a discount.","distractor_reasons":{"A":"Incorrect because both are widely used by small and medium-sized trading businesses.","B":"Incorrect because both are short-term external sources of finance.","C":"Option C is correct because an overdraft is short-term bank borrowing, whereas debt factoring converts existing trade receivables into immediate cash at a discount.","D":"Incorrect because overdrafts charge interest and factors charge service/discount fees."}}},{"id":"P1_U5_MCQ_392","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_392","question":"A hospital needs high-tech diagnostic scanners that become technologically outdated every four years, and it wants maintenance and repairs included in its monthly payments. Why is leasing better than hire purchase for this hospital?","options":{"A":"Leasing requires paying the entire purchase price upfront in cash","B":"Leasing transfers permanent legal ownership of the scanners to the hospital on Day 1","C":"Leasing normally includes maintenance and lets the hospital upgrade to newer scanners at the end of the contract without owning obsolete equipment","D":"Leasing is an internal source of finance"},"correctOption":"C","correctAnswer":"Leasing normally includes maintenance and lets the hospital upgrade to newer scanners at the end of the contract without owning obsolete equipment","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because leasing avoids obsolescence risk and includes servicing, whereas hire purchase results in owning equipment that may soon be outdated.","distractor_reasons":{"A":"Incorrect because leasing spreads payments over time with no large upfront capital outlay.","B":"Incorrect because legal ownership remains with the leasing company throughout and after the lease.","C":"Option C is correct because leasing avoids obsolescence risk and includes servicing, whereas hire purchase results in owning equipment that may soon be outdated.","D":"Incorrect because leasing is provided by an external finance/leasing company."}}},{"id":"P1_U5_MCQ_393","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_393","question":"A microfinance institution lends $400 to a street-food vendor in a developing economy to buy a refrigerated cart. Why do microfinance loans often carry higher percentage interest rates than large corporate bank loans?","options":{"A":"Microfinance loans last for 50 years without any repayments","B":"Microfinance institutions are legally required to charge at least 90% interest","C":"Street-food vendors receive $400 in free company shares alongside the loan","D":"Managing and collecting many tiny, unsecured loans involves high administrative costs relative to the small loan size"},"correctOption":"D","correctAnswer":"Managing and collecting many tiny, unsecured loans involves high administrative costs relative to the small loan size","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because processing, monitoring, and collecting numerous small loans without collateral incurs high per-dollar administrative expenses.","distractor_reasons":{"A":"Incorrect because microfinance loans are typically repaid in frequent small instalments over short periods.","B":"Incorrect because there is no statutory 90% interest floor.","C":"Incorrect because microfinance provides small loans, not share issues.","D":"Option D is correct because processing, monitoring, and collecting numerous small loans without collateral incurs high per-dollar administrative expenses."}}},{"id":"P1_U5_MCQ_394","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_394","question":"A start-up board-game designer launches a crowdfunding campaign to raise $30,000, offering backers an early copy of the game in exchange for pledges. Beyond raising money, what is a major marketing benefit of crowdfunding?","options":{"A":"It tests market demand before mass production and builds an engaged community of early customers","B":"It guarantees that competitors will never see the product idea","C":"It eliminates the need to manufacture or ship the board games","D":"It converts the start-up into a public limited company on a stock exchange"},"correctOption":"A","correctAnswer":"It tests market demand before mass production and builds an engaged community of early customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because strong crowdfunding pledges prove genuine customer interest before committing to factory production and create word-of-mouth promotion.","distractor_reasons":{"A":"Option A is correct because strong crowdfunding pledges prove genuine customer interest before committing to factory production and create word-of-mouth promotion.","B":"Incorrect because listing on a public crowdfunding platform exposes the idea to competitors.","C":"Incorrect because the creator still must produce and deliver the promised rewards to backers.","D":"Incorrect because reward-based crowdfunding does not list shares on a stock exchange."}}},{"id":"P1_U5_MCQ_395","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_395","question":"A property developer borrows money using a 6-month bank overdraft to buy land and construct an apartment block that will take three years to build and sell. Why is this a poor financing choice?","options":{"A":"Overdrafts can only be used by public limited companies","B":"Apartment blocks are classified as short-term current assets","C":"Mismatch of time period: a long-term 3-year project should be funded with long-term finance, as the overdraft could be recalled before apartments are sold","D":"Construction materials cannot be paid for using bank accounts"},"correctOption":"C","correctAnswer":"Mismatch of time period: a long-term 3-year project should be funded with long-term finance, as the overdraft could be recalled before apartments are sold","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because matching the time period of finance to the life of the project is vital; funding a multi-year build with short-term recallable debt creates severe liquidity risk.","distractor_reasons":{"A":"Incorrect because businesses of any legal structure can use overdrafts.","B":"Incorrect because a 3-year construction project requires long-term capital.","C":"Option C is correct because matching the time period of finance to the life of the project is vital; funding a multi-year build with short-term recallable debt creates severe liquidity risk.","D":"Incorrect because suppliers are routinely paid via bank transfers."}}},{"id":"P1_U5_MCQ_396","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_396","question":"A multinational airline wants to raise $800 million to purchase 15 new passenger aircraft. Why would a public share issue or debenture issue be considered instead of a bank overdraft or microfinance?","options":{"A":"Amount required: only capital markets (shares or debentures) can supply $800 million in long-term funds","B":"Airlines are legally forbidden from holding bank accounts","C":"Microfinance loans are restricted to amounts above $1 billion","D":"Share issues take less than 10 minutes to arrange with zero fees"},"correctOption":"A","correctAnswer":"Amount required: only capital markets (shares or debentures) can supply $800 million in long-term funds","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the scale of finance needed ($800 million) rules out small short-term facilities like overdrafts or microfinance.","distractor_reasons":{"A":"Option A is correct because the scale of finance needed ($800 million) rules out small short-term facilities like overdrafts or microfinance.","B":"Incorrect because airlines obviously use commercial bank accounts.","C":"Incorrect because microfinance provides very small loans (typically hundreds or a few thousand dollars).","D":"Incorrect because public share and debenture issues involve substantial legal costs and preparation time."}}},{"id":"P1_U5_MCQ_397","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_397","question":"Why do commercial banks often charge higher interest rates—or demand personal collateral—when lending to a small newly established sole trader compared with an established public limited company?","options":{"A":"Sole traders are not allowed to earn profits","B":"Sole traders are legally prohibited from repaying loans early","C":"Public limited companies are owned by the central bank","D":"Small start-ups lack a proven trading track record and have higher failure rates, making lending riskier for the bank"},"correctOption":"D","correctAnswer":"Small start-ups lack a proven trading track record and have higher failure rates, making lending riskier for the bank","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because size and trading history influence perceived risk; smaller new firms pose higher default risk, prompting banks to charge higher rates or seek security.","distractor_reasons":{"A":"Incorrect because sole traders are profit-seeking private businesses.","B":"Incorrect because loan repayment terms are contractual, not banned by law.","C":"Incorrect because public limited companies are owned by private sector shareholders.","D":"Option D is correct because size and trading history influence perceived risk; smaller new firms pose higher default risk, prompting banks to charge higher rates or seek security."}}},{"id":"P1_U5_MCQ_398","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_398","question":"The founders of a family-owned software company want to raise $500,000 for expansion, but they refuse to issue new shares to outside investors or accept venture capital. Which factor is driving their financing decision?","options":{"A":"Maintaining full ownership and decision-making control within the founding family","B":"A legal ban on private limited companies having retained profit","C":"A desire to maximize annual interest expenses","D":"The fact that software companies cannot take bank loans"},"correctOption":"A","correctAnswer":"Maintaining full ownership and decision-making control within the founding family","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because issuing external equity dilutes voting control, so owners prioritizing control favor retained profit or debt finance.","distractor_reasons":{"A":"Option A is correct because issuing external equity dilutes voting control, so owners prioritizing control favor retained profit or debt finance.","B":"Incorrect because private limited companies regularly use retained profit.","C":"Incorrect because businesses aim to minimize, not maximize, interest costs.","D":"Incorrect because software companies can apply for bank loans."}}},{"id":"P1_U5_MCQ_399","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_399","question":"Which factor would most encourage a business to choose a bank loan rather than issuing new shares?","options":{"A":"The owners want to keep full control and the sum needed is modest","B":"The owners want to spread ownership among many investors","C":"The business has no existing borrowings at all","D":"The owners want to share the risk with outside shareholders"},"correctOption":"A","correctAnswer":"The owners want to keep full control and the sum needed is modest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a loan does not dilute ownership or control, making it attractive when the sum required is manageable.","distractor_reasons":{"A":"Option A is correct because a loan does not dilute ownership or control, making it attractive when the sum required is manageable.","B":"Incorrect because spreading ownership among investors is an argument for issuing shares, not for taking a loan.","C":"Incorrect because having no existing borrowings might make borrowing easier but is not the main reason compared with retaining control.","D":"Incorrect because sharing risk with shareholders is a feature of equity finance, not of a bank loan."}}},{"id":"P1_U5_MCQ_400","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_400","question":"A food-processing company funds a $500,000 factory upgrade using $180,000 of retained profit, $40,000 from selling old vans, $200,000 from a 10-year bank loan, $50,000 from a 6-month bank overdraft, and $30,000 from 30-day trade credit. How much external short-term finance was used?","options":{"A":"$80,000","B":"$280,000","C":"$220,000","D":"$50,000"},"correctOption":"A","correctAnswer":"$80,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external short-term sources (repayable within one year) are the 6-month bank overdraft ($50,000) plus 30-day trade credit ($30,000) = $80,000.","distractor_reasons":{"A":"Option A is correct because external short-term sources (repayable within one year) are the 6-month bank overdraft ($50,000) plus 30-day trade credit ($30,000) = $80,000.","B":"Incorrect because $280,000 is total external finance, including the 10-year long-term bank loan ($200,000).","C":"Incorrect because $220,000 is total internal finance ($180,000 retained profit + $40,000 van sales).","D":"Incorrect because $50,000 omits the $30,000 of short-term trade credit."}}},{"id":"P1_U5_MCQ_401","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_401","question":"Why can a business with strong annual profits still be forced into liquidation if it runs out of cash?","options":{"A":"Workers, suppliers, and utility companies demand immediate payment in cash, not promises of future customer payments","B":"Profitable businesses are legally barred from using bank overdrafts","C":"Cash outflows are always double sales revenue in profitable firms","D":"Liquidation occurs automatically whenever gross profit exceeds $50,000"},"correctOption":"A","correctAnswer":"Workers, suppliers, and utility companies demand immediate payment in cash, not promises of future customer payments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash is the liquid medium required to settle immediate day-to-day obligations; if a business cannot pay debts as they fall due, creditors can force liquidation.","distractor_reasons":{"A":"Option A is correct because cash is the liquid medium required to settle immediate day-to-day obligations; if a business cannot pay debts as they fall due, creditors can force liquidation.","B":"Incorrect because profitable businesses frequently use overdrafts to bridge working capital gaps.","C":"Incorrect because in profitable firms, total revenue exceeds total costs.","D":"Incorrect because earning a gross profit above $50,000 is positive, not a trigger for liquidation."}}},{"id":"P1_U5_MCQ_402","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_402","question":"Which list contains ONLY items that would be recorded as cash inflows on a manufacturing company's cash flow forecast?","options":{"A":"Cash sales, payments received from trade receivables, and receipt of a new bank loan","B":"Credit sales due in 60 days, depreciation of machinery, and retained profit","C":"Cash sales, wages paid to factory workers, and purchase of raw materials","D":"Payments to trade payables, corporation tax paid, and dividends paid"},"correctOption":"A","correctAnswer":"Cash sales, payments received from trade receivables, and receipt of a new bank loan","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash sales, collections from credit customers, and bank loan drawdowns all bring actual money into the business's bank account.","distractor_reasons":{"A":"Option A is correct because cash sales, collections from credit customers, and bank loan drawdowns all bring actual money into the business's bank account.","B":"Incorrect because uncollected credit sales, depreciation (a non-cash accounting charge), and retained profit are not cash inflows.","C":"Incorrect because wages paid and raw material purchases are cash outflows.","D":"Incorrect because payments to suppliers, tax, and dividends are all cash outflows."}}},{"id":"P1_U5_MCQ_403","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_403","question":"Which list contains ONLY items that would be recorded as cash outflows on a retail store's cash flow forecast?","options":{"A":"Inventory ordered on 60-day credit (not yet paid), wages paid, and electricity bills paid","B":"Cash sales, rent paid, and receipt of a government grant","C":"Rent paid, wages paid, cash paid for inventory, and purchase of new checkout computers","D":"Payments from credit customers, bank loan interest paid, and owner's capital injection"},"correctOption":"C","correctAnswer":"Rent paid, wages paid, cash paid for inventory, and purchase of new checkout computers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because rent, wages, cash stock purchases, and equipment purchases all represent money leaving the business's bank account.","distractor_reasons":{"A":"Incorrect because inventory ordered on 60-day credit does not create a cash outflow until paid two months later.","B":"Incorrect because cash sales and government grants are cash inflows.","C":"Option C is correct because rent, wages, cash stock purchases, and equipment purchases all represent money leaving the business's bank account.","D":"Incorrect because payments from credit customers and owner capital injections are cash inflows."}}},{"id":"P1_U5_MCQ_404","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_404","question":"In January, an IT consultancy invoices clients for $40,000 of work on 60-day credit terms, receives $15,000 from November credit clients, and records $2,000 of computer depreciation. How much cash inflow is entered on January's cash flow forecast?","options":{"A":"$15,000","B":"$55,000","C":"$57,000","D":"$40,000"},"correctOption":"A","correctAnswer":"$15,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because only the $15,000 collected from November clients enters the bank in January; January's $40,000 credit invoices arrive in March, and depreciation is non-cash.","distractor_reasons":{"A":"Option A is correct because only the $15,000 collected from November clients enters the bank in January; January's $40,000 credit invoices arrive in March, and depreciation is non-cash.","B":"Incorrect because $55,000 wrongly counts January's uncollected $40,000 credit invoices.","C":"Incorrect because $57,000 includes both uncollected credit invoices and non-cash depreciation.","D":"Incorrect because $40,000 is January credit revenue, not cash received in January."}}},{"id":"P1_U5_MCQ_405","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_405","question":"A stationery wholesaler forecasts total sales of $40,000 in April, $50,000 in May, and $60,000 in June. Customers pay 50% in cash at purchase, 30% one month later, and 20% two months later. What is the forecast cash inflow from sales in June?","options":{"A":"$53,000","B":"$60,000","C":"$45,000","D":"$30,000"},"correctOption":"A","correctAnswer":"$53,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because June receipts = 50% of June ($30,000) + 30% of May ($15,000) + 20% of April ($8,000) = $53,000.","distractor_reasons":{"A":"Option A is correct because June receipts = 50% of June ($30,000) + 30% of May ($15,000) + 20% of April ($8,000) = $53,000.","B":"Incorrect because $60,000 is total June sales revenue, half of which is collected in July and August.","C":"Incorrect because $45,000 omits the 20% collected from April sales ($8,000).","D":"Incorrect because $30,000 counts only June's immediate cash sales."}}},{"id":"P1_U5_MCQ_406","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_406","question":"A restaurant orders $10,000 of food ingredients in August on 30-day trade credit, pays $8,500 for July's food order, pays $9,000 in August staff wages, and pays $4,000 cash for a new commercial dishwasher in August. What are total cash outflows in August?","options":{"A":"$17,500","B":"$23,000","C":"$31,500","D":"$21,500"},"correctOption":"D","correctAnswer":"$21,500","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because August cash outflows = $8,500 (July food paid) + $9,000 (wages) + $4,000 (dishwasher) = $21,500 (August's $10,000 credit food order is paid in September).","distractor_reasons":{"A":"Incorrect because $17,500 omits the $4,000 cash paid for the dishwasher.","B":"Incorrect because $23,000 uses August's $10,000 credit order instead of July's $8,500 invoice paid in August.","C":"Incorrect because $31,500 counts both July's and August's food orders.","D":"Option D is correct because August cash outflows = $8,500 (July food paid) + $9,000 (wages) + $4,000 (dishwasher) = $21,500 (August's $10,000 credit food order is paid in September)."}}},{"id":"P1_U5_MCQ_407","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_407","question":"In February, a ski-equipment shop forecasts total cash inflows of $28,400 and total cash outflows of $34,900, starting with an opening balance of $9,000. What is the forecast net cash flow for February?","options":{"A":"-$6,500","B":"$2,500","C":"$6,500","D":"$63,300"},"correctOption":"A","correctAnswer":"-$6,500","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net cash flow = Cash inflows - Cash outflows ($28,400 - $34,900 = -$6,500).","distractor_reasons":{"A":"Option A is correct because Net cash flow = Cash inflows - Cash outflows ($28,400 - $34,900 = -$6,500).","B":"Incorrect because $2,500 is the closing balance ($9,000 opening - $6,500 net cash flow), not net cash flow.","C":"Incorrect because outflows exceed inflows, so net cash flow must be negative.","D":"Incorrect because $63,300 adds inflows and outflows together."}}},{"id":"P1_U5_MCQ_408","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_408","question":"A garden landscaping firm starts April with an opening cash balance of $3,200. During April, forecast cash inflows are $19,500 and cash outflows are $24,100. What is the firm's forecast closing cash balance at the end of April?","options":{"A":"-$1,400","B":"-$4,600","C":"$7,800","D":"$1,400"},"correctOption":"A","correctAnswer":"-$1,400","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because April net cash flow = $19,500 - $24,100 = -$4,600, and Closing balance = Opening balance + Net cash flow ($3,200 + (-$4,600) = -$1,400).","distractor_reasons":{"A":"Option A is correct because April net cash flow = $19,500 - $24,100 = -$4,600, and Closing balance = Opening balance + Net cash flow ($3,200 + (-$4,600) = -$1,400).","B":"Incorrect because -$4,600 is April's net cash flow and ignores the $3,200 opening balance.","C":"Incorrect because $7,800 adds the $4,600 deficit to the $3,200 opening balance.","D":"Incorrect because $3,200 - $4,600 results in a negative (overdrawn) balance of -$1,400."}}},{"id":"P1_U5_MCQ_409","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_409","question":"A small print shop starts November with an overdrawn opening balance of -$2,400. During November, cash inflows are $14,000 and cash outflows are $16,300. What is the closing cash balance at the end of November?","options":{"A":"$100","B":"-$2,300","C":"-$4,700","D":"$4,700"},"correctOption":"C","correctAnswer":"-$4,700","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because November net cash flow = $14,000 - $16,300 = -$2,300, and adding this to the -$2,400 opening overdraft gives a closing balance of -$4,700.","distractor_reasons":{"A":"Incorrect because $100 treats the opening overdraft as +$2,400 instead of -$2,400.","B":"Incorrect because -$2,300 is November's net cash flow and ignores the -$2,400 opening overdraft.","C":"Option C is correct because November net cash flow = $14,000 - $16,300 = -$2,300, and adding this to the -$2,400 opening overdraft gives a closing balance of -$4,700.","D":"Incorrect because both the opening balance and net cash flow are negative, making the closing balance -$4,700."}}},{"id":"P1_U5_MCQ_410","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_410","question":"A juice bar starts Month 1 with $5,000 cash. Net cash flow is +$1,200 in Month 1, -$2,800 in Month 2, and +$900 in Month 3. What is the juice bar's closing cash balance at the end of Month 3?","options":{"A":"-$700","B":"$3,400","C":"$6,200","D":"$4,300"},"correctOption":"D","correctAnswer":"$4,300","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Month 1 closing = $5,000 + $1,200 = $6,200; Month 2 closing = $6,200 - $2,800 = $3,400; Month 3 closing = $3,400 + $900 = $4,300.","distractor_reasons":{"A":"Incorrect because -$700 omits the $5,000 initial opening balance.","B":"Incorrect because $3,400 is Month 2's closing balance before adding Month 3's +$900 net cash flow.","C":"Incorrect because $6,200 is Month 1's closing balance.","D":"Option D is correct because Month 1 closing = $5,000 + $1,200 = $6,200; Month 2 closing = $6,200 - $2,800 = $3,400; Month 3 closing = $3,400 + $900 = $4,300."}}},{"id":"P1_U5_MCQ_411","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_411","question":"In August, a bookstore has an opening cash balance of $4,500, total cash inflows of $21,000, and a closing cash balance of $6,200. What were the bookstore's total cash outflows in August?","options":{"A":"$19,300","B":"$22,700","C":"$14,800","D":"$25,500"},"correctOption":"A","correctAnswer":"$19,300","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net cash flow = Closing balance - Opening balance ($6,200 - $4,500 = +$1,700), and Cash outflows = Cash inflows - Net cash flow ($21,000 - $1,700 = $19,300).","distractor_reasons":{"A":"Option A is correct because Net cash flow = Closing balance - Opening balance ($6,200 - $4,500 = +$1,700), and Cash outflows = Cash inflows - Net cash flow ($21,000 - $1,700 = $19,300).","B":"Incorrect because $22,700 adds the $1,700 net cash inflow to $21,000 instead of subtracting it.","C":"Incorrect because $14,800 subtracts closing balance from inflows ($21,000 - $6,200) and ignores the opening balance.","D":"Incorrect because $25,500 adds opening balance and inflows ($4,500 + $21,000)."}}},{"id":"P1_U5_MCQ_412","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_412","question":"Why is a cash flow forecast an essential part of a business plan when starting up a new company?","options":{"A":"It shows how much initial working capital is needed to survive early months before customer receipts cover ongoing costs","B":"It guarantees that the new company will earn a profit in Month 1","C":"It replaces the legal requirement to register the company with authorities","D":"It fixes supplier raw material prices for the next ten years"},"correctOption":"A","correctAnswer":"It shows how much initial working capital is needed to survive early months before customer receipts cover ongoing costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because start-ups experience high initial outflows and slow early receipts; a forecast calculates how much cash buffer is required to avoid early failure.","distractor_reasons":{"A":"Option A is correct because start-ups experience high initial outflows and slow early receipts; a forecast calculates how much cash buffer is required to avoid early failure.","B":"Incorrect because a forecast projects cash movements and cannot guarantee profitability.","C":"Incorrect because company registration is a separate legal obligation.","D":"Incorrect because forecasts estimate future costs rather than locking in supplier prices."}}},{"id":"P1_U5_MCQ_413","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_413","question":"A toy manufacturer's cash flow forecast shows large surplus cash balances of +$85,000 accumulating between January and April. How can managers use this forecast information effectively?","options":{"A":"Ask the bank for an emergency high-interest overdraft","B":"Stop invoicing credit customers until May","C":"Ignore the surplus because cash balances reset to zero every quarter","D":"Plan to pay off expensive loans early, buy raw materials in bulk for discounts, or place the surplus cash in an interest-earning deposit account"},"correctOption":"D","correctAnswer":"Plan to pay off expensive loans early, buy raw materials in bulk for discounts, or place the surplus cash in an interest-earning deposit account","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash flow forecasts do not just spot deficits—they also reveal surplus cash so managers can put idle funds to productive use.","distractor_reasons":{"A":"Incorrect because a business with an $85,000 cash surplus does not need an emergency overdraft.","B":"Incorrect because delaying customer invoicing would harm liquidity and increase bad debt risk.","C":"Incorrect because cash balances carry forward continuously from month to month.","D":"Option D is correct because cash flow forecasts do not just spot deficits—they also reveal surplus cash so managers can put idle funds to productive use."}}},{"id":"P1_U5_MCQ_414","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_414","question":"Why do commercial banks almost always insist on seeing a 12-month cash flow forecast before approving a business loan or overdraft facility?","options":{"A":"Because banks are legally forbidden from reading statements of profit or loss","B":"To calculate the exact resale value of the owner's personal car","C":"To check the size and timing of expected cash deficits and verify that the business will generate enough future cash inflows to repay the debt","D":"To set the retail prices the business must charge its customers"},"correctOption":"C","correctAnswer":"To check the size and timing of expected cash deficits and verify that the business will generate enough future cash inflows to repay the debt","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because banks lend based on repayment ability; a credible cash flow forecast demonstrates how much borrowing is needed and when cash will be available for repayments.","distractor_reasons":{"A":"Incorrect because banks examine both historical profit statements and forward-looking cash flow forecasts.","B":"Incorrect because personal vehicle values are not shown on a business cash flow forecast.","C":"Option C is correct because banks lend based on repayment ability; a credible cash flow forecast demonstrates how much borrowing is needed and when cash will be available for repayments.","D":"Incorrect because banks do not dictate a borrower's retail pricing."}}},{"id":"P1_U5_MCQ_415","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_415","question":"A kitchenware distributor discovers through its cash flow forecast that even though sales are rising, its cash balance is shrinking because credit customers take 75 days to pay while suppliers demand payment in 30 days. How is the forecast helping management?","options":{"A":"By highlighting an unsustainable working capital timing gap so managers can tighten customer credit control or negotiate longer supplier terms","B":"By proving that the distributor should stop selling kitchenware immediately","C":"By showing that gross profit margin has fallen to zero","D":"By eliminating the need to pay supplier invoices"},"correctOption":"A","correctAnswer":"By highlighting an unsustainable working capital timing gap so managers can tighten customer credit control or negotiate longer supplier terms","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because monitoring cash flow forecasts exposes cash trapped in slow trade receivables and guides timely corrective action.","distractor_reasons":{"A":"Option A is correct because monitoring cash flow forecasts exposes cash trapped in slow trade receivables and guides timely corrective action.","B":"Incorrect because rising sales are positive once the credit timing gap is managed.","C":"Incorrect because cash timing differences do not mean gross profit margin is zero.","D":"Incorrect because supplier invoices remain legally payable."}}},{"id":"P1_U5_MCQ_416","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_416","question":"A building contractor takes out a new short-term bank loan to cover a three-month cash flow deficit. What is a limitation of using a bank loan to solve a cash flow problem?","options":{"A":"It immediately reduces the contractor's sales revenue","B":"While it provides an immediate cash inflow, it increases future cash outflows through interest payments and principal repayments","C":"It forces the contractor to give 50% of its profits to the bank forever","D":"Bank loans never improve short-term cash balances"},"correctOption":"B","correctAnswer":"While it provides an immediate cash inflow, it increases future cash outflows through interest payments and principal repayments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a bank loan injects cash today, but the debt must be repaid with interest in subsequent months, adding future cash outflows.","distractor_reasons":{"A":"Incorrect because taking a loan does not lower sales revenue.","B":"Option B is correct because a bank loan injects cash today, but the debt must be repaid with interest in subsequent months, adding future cash outflows.","C":"Incorrect because loans charge interest rather than taking a permanent share of equity profits.","D":"Incorrect because receiving loan funds directly increases the immediate cash balance."}}},{"id":"P1_U5_MCQ_417","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_417","question":"To overcome a forecast cash deficit in May, a bakery negotiates with its flour and butter suppliers to extend payment terms from 30 days to 60 days. How does this resolve the May cash shortfall?","options":{"A":"It delays cash outflows into June, keeping cash inside the bakery during May","B":"It increases May cash inflows from bakery customers","C":"It permanently cancels the cost of flour and butter","D":"It converts trade payables into non-current assets"},"correctOption":"A","correctAnswer":"It delays cash outflows into June, keeping cash inside the bakery during May","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because extending supplier credit pushes cash outflows into a later month, relieving immediate liquidity pressure.","distractor_reasons":{"A":"Option A is correct because extending supplier credit pushes cash outflows into a later month, relieving immediate liquidity pressure.","B":"Incorrect because supplier credit terms affect cash outflows, not customer cash inflows.","C":"Incorrect because the invoices must still be paid in full after 60 days.","D":"Incorrect because trade payables remain current liabilities until settled."}}},{"id":"P1_U5_MCQ_418","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_418","question":"An electrical wholesaler offers its credit customers a 2% cash discount if they settle their invoices within 7 days instead of waiting 45 days. How does this affect the wholesaler's cash flow and profit?","options":{"A":"It accelerates cash inflows into the business sooner, though the 2% discount slightly reduces profit margin","B":"It delays cash inflows by 38 days and doubles profit margin","C":"It increases monthly cash outflows for raw materials","D":"It eliminates all trade payables on the statement of financial position"},"correctOption":"A","correctAnswer":"It accelerates cash inflows into the business sooner, though the 2% discount slightly reduces profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because prompt-payment discounts incentivize trade receivables to pay faster, boosting short-term liquidity at the minor cost of the 2% discount.","distractor_reasons":{"A":"Option A is correct because prompt-payment discounts incentivize trade receivables to pay faster, boosting short-term liquidity at the minor cost of the 2% discount.","B":"Incorrect because cash arrives 38 days earlier, and giving a discount slightly lowers rather than doubles profit.","C":"Incorrect because customer discounts do not increase supplier material costs.","D":"Incorrect because customer discounts affect trade receivables, not trade payables."}}},{"id":"P1_U5_MCQ_419","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_419","question":"Facing a projected cash deficit over the next two quarters, a printing firm cancels its plan to buy a $65,000 digital press for cash and continues using its existing machines. What is the immediate impact on its cash flow forecast?","options":{"A":"Forecast cash outflows are reduced by $65,000, preventing or shrinking the cash deficit","B":"Forecast cash inflows rise by $65,000","C":"The firm's current liabilities double immediately","D":"The firm's gross profit falls by $65,000 this month"},"correctOption":"A","correctAnswer":"Forecast cash outflows are reduced by $65,000, preventing or shrinking the cash deficit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delaying or cancelling capital expenditure eliminates a major cash outflow, directly improving net cash flow and closing cash balances.","distractor_reasons":{"A":"Option A is correct because delaying or cancelling capital expenditure eliminates a major cash outflow, directly improving net cash flow and closing cash balances.","B":"Incorrect because cancelling an equipment purchase avoids a cash outflow rather than generating a cash inflow.","C":"Incorrect because cancelling a cash purchase creates no new liabilities.","D":"Incorrect because non-current asset purchases do not reduce gross profit."}}},{"id":"P1_U5_MCQ_420","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_420","question":"A courier company needs three new delivery vans costing $90,000 total, but buying them for cash would push its bank balance into a -$50,000 deficit. Instead, it leases the vans for $2,200 per month. How does leasing help manage cash flow?","options":{"A":"It replaces a single $90,000 cash outflow with smaller, predictable monthly outflows that can be funded from ongoing delivery receipts","B":"It increases monthly cash inflows by $90,000","C":"It eliminates all fuel and driver wage outflows","D":"It makes the total multi-year cost of the vans lower than buying them for cash"},"correctOption":"A","correctAnswer":"It replaces a single $90,000 cash outflow with smaller, predictable monthly outflows that can be funded from ongoing delivery receipts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing spreads payments evenly over time, avoiding a huge upfront capital drain on working capital.","distractor_reasons":{"A":"Option A is correct because leasing spreads payments evenly over time, avoiding a huge upfront capital drain on working capital.","B":"Incorrect because leasing involves rental outflows, not cash inflows.","C":"Incorrect because leased vans still require fuel and drivers.","D":"Incorrect because over the full term, total lease rentals usually exceed the cash purchase price."}}},{"id":"P1_U5_MCQ_421","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_421","question":"A supermarket chain facing severe short-term liquidity pressure sells its freehold store buildings to a property investment firm for $4 million cash and immediately signs a 20-year lease to continue operating in the same stores. How does this 'sale and leaseback' affect cash flow?","options":{"A":"It generates an immediate $4 million cash inflow to resolve the liquidity crisis, while introducing regular future rent outflows","B":"It eliminates all future rent and property expenses permanently","C":"It forces the supermarket to close all its stores immediately","D":"It increases current liabilities by $4 million"},"correctOption":"A","correctAnswer":"It generates an immediate $4 million cash inflow to resolve the liquidity crisis, while introducing regular future rent outflows","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sale and leaseback unlocks cash tied up in non-current property assets without disrupting operations, though ongoing lease rent increases future outflows.","distractor_reasons":{"A":"Option A is correct because sale and leaseback unlocks cash tied up in non-current property assets without disrupting operations, though ongoing lease rent increases future outflows.","B":"Incorrect because leasing the buildings back creates new annual rent payments.","C":"Incorrect because the supermarket continues trading in the exact same stores.","D":"Incorrect because selling an asset for cash boosts current assets (cash) rather than increasing current liabilities."}}},{"id":"P1_U5_MCQ_422","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_422","question":"Which sequence accurately illustrates the working capital cycle of a manufacturing business?","options":{"A":"Cash -> purchase raw materials -> produce finished goods -> sell on credit (trade receivables) -> collect cash from customers","B":"Cash -> issue ordinary shares -> buy freehold land -> pay corporation tax -> close factory","C":"Trade payables -> non-current liabilities -> depreciation -> retained profit -> dividends","D":"Customer cash -> bank overdraft -> fixed assets -> marketing -> liquidation"},"correctOption":"A","correctAnswer":"Cash -> purchase raw materials -> produce finished goods -> sell on credit (trade receivables) -> collect cash from customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the working capital cycle shows how cash flows into materials and production, becomes inventory and trade receivables, and returns as cash when customers pay.","distractor_reasons":{"A":"Option A is correct because the working capital cycle shows how cash flows into materials and production, becomes inventory and trade receivables, and returns as cash when customers pay.","B":"Incorrect because share issues and freehold land are long-term capital transactions, not the routine working capital cycle.","C":"Incorrect because non-current liabilities and depreciation are not part of the short-term trading cash cycle.","D":"Incorrect because this does not represent the operational flow of current assets."}}},{"id":"P1_U5_MCQ_423","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_423","question":"In June, a carpentry business receives a $30,000 long-term bank loan into its bank account. How is this $30,000 treated in the cash flow forecast versus the statement of profit or loss?","options":{"A":"It is recorded as a $30,000 cash inflow in the cash flow forecast, but it is NOT recorded as revenue or profit on the statement of profit or loss","B":"It is recorded as $30,000 of sales revenue on the statement of profit or loss, but omitted from the cash flow forecast","C":"It is recorded as both $30,000 of profit and $30,000 of cash inflow","D":"It is recorded as a $30,000 cash outflow in the cash flow forecast"},"correctOption":"A","correctAnswer":"It is recorded as a $30,000 cash inflow in the cash flow forecast, but it is NOT recorded as revenue or profit on the statement of profit or loss","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receiving a loan brings cash into the bank (cash inflow) while creating a repayable debt liability rather than earned trading revenue.","distractor_reasons":{"A":"Option A is correct because receiving a loan brings cash into the bank (cash inflow) while creating a repayable debt liability rather than earned trading revenue.","B":"Incorrect because loans are borrowed debt, not sales revenue.","C":"Incorrect because borrowing money does not generate profit.","D":"Incorrect because receiving loan funds increases cash (inflow), whereas repaying a loan is an outflow."}}},{"id":"P1_U5_MCQ_424","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_424","question":"A bakery spends $42,000 in cash to purchase a new delivery van. Why does this $42,000 payment reduce the bakery's closing cash balance immediately without reducing its gross profit by $42,000?","options":{"A":"Accountants ignore vehicle purchases until the van is sold","B":"Delivery vans are paid for using trade receivables rather than cash","C":"Gross profit is calculated before deducting any costs at all","D":"Buying a van is a capital cash outflow on the cash flow forecast, whereas on the statement of financial position it simply exchanges cash for a non-current asset rather than being a direct cost of sales"},"correctOption":"D","correctAnswer":"Buying a van is a capital cash outflow on the cash flow forecast, whereas on the statement of financial position it simply exchanges cash for a non-current asset rather than being a direct cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because purchasing a non-current asset drains cash immediately on the cash flow forecast, while only gradual depreciation (not the full $42,000 purchase price) is charged as an expense over the van's life.","distractor_reasons":{"A":"Incorrect because the van is recorded immediately under non-current assets on the statement of financial position.","B":"Incorrect because the scenario states the van was purchased in cash.","C":"Incorrect because gross profit deducts direct cost of sales from revenue.","D":"Option D is correct because purchasing a non-current asset drains cash immediately on the cash flow forecast, while only gradual depreciation (not the full $42,000 purchase price) is charged as an expense over the van's life."}}},{"id":"P1_U5_MCQ_425","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_425","question":"A travel company's actual closing cash balance in August turns out to be -$11,000 instead of the +$6,000 predicted in its cash flow forecast prepared six months earlier. Which factor best explains why such variances occur?","options":{"A":"Cash flow forecasts rely on estimates of future sales and costs, which can be disrupted by unexpected fuel price spikes, currency shifts, or slower customer payments","B":"Cash flow forecasts are legally required to exclude utility bills and wages","C":"Closing balances on a cash flow forecast never include opening balances","D":"Banks randomly change a company's historical sales figures"},"correctOption":"A","correctAnswer":"Cash flow forecasts rely on estimates of future sales and costs, which can be disrupted by unexpected fuel price spikes, currency shifts, or slower customer payments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because forecasts are projections based on assumptions; unforeseen market or cost changes cause actual cash flows to differ from estimates.","distractor_reasons":{"A":"Option A is correct because forecasts are projections based on assumptions; unforeseen market or cost changes cause actual cash flows to differ from estimates.","B":"Incorrect because wages and utility bills are always included in forecast outflows.","C":"Incorrect because closing balance always equals opening balance plus net cash flow.","D":"Incorrect because banks do not alter a company's accounting records."}}},{"id":"P1_U5_MCQ_426","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_426","question":"How is 'profit' fundamentally defined for a trading business over a financial year?","options":{"A":"The total amount of money borrowed from commercial banks during the year","B":"The exact amount of physical cash sitting in the business's safe on 31 December","C":"The positive financial surplus remaining when total revenue exceeds total costs over a trading period","D":"Total revenue minus only the cost of buying non-current assets"},"correctOption":"C","correctAnswer":"The positive financial surplus remaining when total revenue exceeds total costs over a trading period","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because profit measures trading surplus (Total revenue - Total costs) over an accounting period.","distractor_reasons":{"A":"Incorrect because borrowed loans are liabilities, not profit.","B":"Incorrect because cash in the safe is a liquid asset, whereas profit includes credit transactions and excludes loans or asset purchases.","C":"Option C is correct because profit measures trading surplus (Total revenue - Total costs) over an accounting period.","D":"Incorrect because non-current asset purchases are capital expenditure, not deducted from revenue to find profit."}}},{"id":"P1_U5_MCQ_427","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_427","question":"Why is earning consistent profit crucial for a private limited company seeking to grow without taking on heavy debt?","options":{"A":"High profit forces competitors to leave the industry by law","B":"Earning profit automatically exempts the company from paying corporation tax","C":"Profit guarantees that the company will never face a cash shortage","D":"Retained profit provides an interest-free internal source of finance for expansion and demonstrates business success to attract investors"},"correctOption":"D","correctAnswer":"Retained profit provides an interest-free internal source of finance for expansion and demonstrates business success to attract investors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit rewards owners, signals viability, and generates retained profit to fund growth internally without debt or dilution.","distractor_reasons":{"A":"Incorrect because high profits actually attract new competitors into a market.","B":"Incorrect because profitable companies must pay corporation tax on their profits.","C":"Incorrect because profitable firms can still suffer cash crises if receivables pay late.","D":"Option D is correct because profit rewards owners, signals viability, and generates retained profit to fund growth internally without debt or dilution."}}},{"id":"P1_U5_MCQ_428","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_428","question":"A fair-trade chocolate social enterprise reinvests 85% of its annual surplus into building schools for cocoa-farming communities. Why is generating profit still vital to this organisation?","options":{"A":"Without profit, the social enterprise cannot remain financially self-sustaining or fund its community school-building mission","B":"Social enterprises are legally required to pay 100% of profits to stock-market speculators","C":"Profit allows social enterprises to pay workers below the legal minimum wage","D":"Social enterprises are fined by the government if they break even"},"correctOption":"A","correctAnswer":"Without profit, the social enterprise cannot remain financially self-sustaining or fund its community school-building mission","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social enterprises use business trading profits to survive independently and finance their social or environmental objectives.","distractor_reasons":{"A":"Option A is correct because social enterprises use business trading profits to survive independently and finance their social or environmental objectives.","B":"Incorrect because social enterprises reinvest surpluses into their social mission rather than maximizing private dividends.","C":"Incorrect because social enterprises must obey employment laws and typically prioritize fair wages.","D":"Incorrect because breaking even is not penalized by law."}}},{"id":"P1_U5_MCQ_429","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_429","question":"During the year, a bicycle shop sells 600 mountain bikes at $450 each and 300 road bikes at $700 each, while also receiving a $50,000 bank loan. What is the shop's revenue on its statement of profit or loss?","options":{"A":"$480,000","B":"$530,000","C":"$270,000","D":"$210,000"},"correctOption":"A","correctAnswer":"$480,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Revenue = (600 × $450) + (300 × $700) = $270,000 + $210,000 = $480,000 (the $50,000 bank loan is a liability, not sales revenue).","distractor_reasons":{"A":"Option A is correct because Revenue = (600 × $450) + (300 × $700) = $270,000 + $210,000 = $480,000 (the $50,000 bank loan is a liability, not sales revenue).","B":"Incorrect because $530,000 wrongly includes the $50,000 bank loan in sales revenue.","C":"Incorrect because $270,000 is only the revenue from mountain bikes.","D":"Incorrect because $210,000 is only the revenue from road bikes."}}},{"id":"P1_U5_MCQ_430","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_430","question":"On a retail clothing store's statement of profit or loss, what does 'cost of sales' represent?","options":{"A":"The direct purchase cost to the store of the specific garments sold to customers during the year","B":"The annual salary of the store's human resources director","C":"The cost of buying a new freehold shop building","D":"Interest paid on a long-term bank loan"},"correctOption":"A","correctAnswer":"The direct purchase cost to the store of the specific garments sold to customers during the year","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because for a retailer, cost of sales is the direct wholesale cost of the goods actually sold during the trading period.","distractor_reasons":{"A":"Option A is correct because for a retailer, cost of sales is the direct wholesale cost of the goods actually sold during the trading period.","B":"Incorrect because HR salaries are indirect overhead expenses.","C":"Incorrect because buying a freehold shop is capital expenditure on a non-current asset.","D":"Incorrect because loan interest is a finance expense deducted after gross profit."}}},{"id":"P1_U5_MCQ_431","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_431","question":"At the start of the year, a hardware shop held opening inventory worth $35,000. During the year, it purchased $190,000 of goods for resale, and at year-end it held closing inventory worth $45,000. What was the shop's cost of sales for the year?","options":{"A":"$190,000","B":"$200,000","C":"$270,000","D":"$180,000"},"correctOption":"D","correctAnswer":"$180,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Cost of sales = Opening inventory + Purchases - Closing inventory ($35,000 + $190,000 - $45,000 = $180,000).","distractor_reasons":{"A":"Incorrect because $190,000 is purchases alone and ignores the $10,000 net increase in unsold inventory.","B":"Incorrect because $200,000 subtracts opening inventory and adds closing inventory ($190,000 - $35,000 + $45,000).","C":"Incorrect because $270,000 adds all three figures together instead of subtracting unsold closing inventory.","D":"Option D is correct because Cost of sales = Opening inventory + Purchases - Closing inventory ($35,000 + $190,000 - $45,000 = $180,000)."}}},{"id":"P1_U5_MCQ_432","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_432","question":"A furniture retailer records annual sales revenue of $840,000, opening inventory of $60,000, purchases of $490,000, closing inventory of $70,000, and overhead expenses of $210,000. What is the retailer's gross profit?","options":{"A":"$630,000","B":"$150,000","C":"$350,000","D":"$360,000"},"correctOption":"D","correctAnswer":"$360,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Cost of sales = $60,000 + $490,000 - $70,000 = $480,000, and Gross profit = Revenue - Cost of sales ($840,000 - $480,000 = $360,000).","distractor_reasons":{"A":"Incorrect because $630,000 subtracts overhead expenses from revenue instead of cost of sales.","B":"Incorrect because $150,000 is the final profit after deducting $210,000 of overhead expenses ($360,000 - $210,000).","C":"Incorrect because $350,000 subtracts purchases ($490,000) directly from revenue without adjusting for opening and closing inventory.","D":"Option D is correct because Cost of sales = $60,000 + $490,000 - $70,000 = $480,000, and Gross profit = Revenue - Cost of sales ($840,000 - $480,000 = $360,000)."}}},{"id":"P1_U5_MCQ_433","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_433","question":"Which group of costs is classified under 'overhead expenses' (rather than cost of sales) on a manufacturer's statement of profit or loss?","options":{"A":"Opening inventory of finished goods and raw material purchases","B":"Direct raw steel and direct factory assembly wages","C":"Head-office administrative salaries, marketing campaigns, and warehouse insurance","D":"Purchase of a new freehold factory building"},"correctOption":"C","correctAnswer":"Head-office administrative salaries, marketing campaigns, and warehouse insurance","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because administrative salaries, advertising, and insurance are indirect running expenses deducted from gross profit to find profit.","distractor_reasons":{"A":"Incorrect because inventory and material purchases form part of cost of sales.","B":"Incorrect because direct raw materials and direct production wages are part of cost of sales.","C":"Option C is correct because administrative salaries, advertising, and insurance are indirect running expenses deducted from gross profit to find profit.","D":"Incorrect because buying a freehold factory is capital expenditure on a non-current asset."}}},{"id":"P1_U5_MCQ_434","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_434","question":"A sports retailer achieves revenue of $920,000, cost of sales of $540,000, and indirect overhead expenses of $265,000. What is the retailer's profit for the year?","options":{"A":"$655,000","B":"$380,000","C":"$115,000","D":"$805,000"},"correctOption":"C","correctAnswer":"$115,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = $920,000 - $540,000 = $380,000, and Profit = Gross profit - Overhead expenses ($380,000 - $265,000 = $115,000).","distractor_reasons":{"A":"Incorrect because $655,000 deducts only overhead expenses from revenue and omits cost of sales.","B":"Incorrect because $380,000 is gross profit before deducting $265,000 of overhead expenses.","C":"Option C is correct because Gross profit = $920,000 - $540,000 = $380,000, and Profit = Gross profit - Overhead expenses ($380,000 - $265,000 = $115,000).","D":"Incorrect because $805,000 adds cost of sales and overhead expenses together ($540,000 + $265,000)."}}},{"id":"P1_U5_MCQ_435","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_435","question":"At the bottom of a public limited company's statement of profit or loss, how is profit after tax divided (appropriated)?","options":{"A":"Between dividends paid out to shareholders and retained profit kept inside the company for reinvestment","B":"Between cost of sales and overhead expenses","C":"Between current assets and current liabilities","D":"Between opening inventory and closing inventory"},"correctOption":"A","correctAnswer":"Between dividends paid out to shareholders and retained profit kept inside the company for reinvestment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because after corporation tax is deducted, remaining profit is either distributed to shareholders as dividends or retained in the business as retained profit.","distractor_reasons":{"A":"Option A is correct because after corporation tax is deducted, remaining profit is either distributed to shareholders as dividends or retained in the business as retained profit.","B":"Incorrect because cost of sales and overhead expenses are deducted earlier to arrive at profit before tax.","C":"Incorrect because assets and liabilities appear on the statement of financial position.","D":"Incorrect because inventories are used earlier to calculate cost of sales."}}},{"id":"P1_U5_MCQ_436","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_436","question":"A packaging company reports revenue of $1,200,000, cost of sales of $720,000, overhead expenses of $280,000, corporation tax of $40,000, and dividends paid of $65,000. What is the company's retained profit for the year?","options":{"A":"$200,000","B":"$160,000","C":"$95,000","D":"$480,000"},"correctOption":"C","correctAnswer":"$95,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = $1,200,000 - $720,000 = $480,000; Profit before tax = $480,000 - $280,000 = $200,000; Profit after tax = $200,000 - $40,000 = $160,000; Retained profit = $160,000 - $65,000 = $95,000.","distractor_reasons":{"A":"Incorrect because $200,000 is profit before tax and dividends.","B":"Incorrect because $160,000 is profit after tax before deducting $65,000 of dividends.","C":"Option C is correct because Gross profit = $1,200,000 - $720,000 = $480,000; Profit before tax = $480,000 - $280,000 = $200,000; Profit after tax = $200,000 - $40,000 = $160,000; Retained profit = $160,000 - $65,000 = $95,000.","D":"Incorrect because $480,000 is gross profit."}}},{"id":"P1_U5_MCQ_437","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_437","question":"A damaged statement of profit or loss shows cost of sales of $310,000, overhead expenses of $115,000, and final profit of $65,000. What were the business's gross profit and total revenue?","options":{"A":"Gross profit: $375,000; Revenue: $490,000","B":"Gross profit: $50,000; Revenue: $360,000","C":"Gross profit: $180,000; Revenue: $130,000","D":"Gross profit: $180,000; Revenue: $490,000"},"correctOption":"D","correctAnswer":"Gross profit: $180,000; Revenue: $490,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Gross profit = Final profit + Overhead expenses ($65,000 + $115,000 = $180,000), and Revenue = Gross profit + Cost of sales ($180,000 + $310,000 = $490,000).","distractor_reasons":{"A":"Incorrect because $375,000 adds cost of sales and final profit ($310,000 + $65,000) instead of overhead expenses and final profit.","B":"Incorrect because $50,000 subtracts final profit from overhead expenses instead of adding them.","C":"Incorrect because $130,000 subtracts gross profit from cost of sales instead of adding them.","D":"Option D is correct because Gross profit = Final profit + Overhead expenses ($65,000 + $115,000 = $180,000), and Revenue = Gross profit + Cost of sales ($180,000 + $310,000 = $490,000)."}}},{"id":"P1_U5_MCQ_438","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_438","question":"A clothing shop had revenue of $60,000 and cost of sales of $36,000 last year. Its operating expenses were $9,000. What was its profit for the year?","options":{"A":"$24,000","B":"$15,000","C":"$33,000","D":"$69,000"},"correctOption":"B","correctAnswer":"$15,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $60,000 − $36,000 = $24,000; deducting operating expenses of $9,000 leaves profit for the year of $15,000.","distractor_reasons":{"A":"$24,000 is the gross profit before operating expenses are subtracted.","B":"Correct: revenue minus cost of sales minus expenses equals $15,000.","C":"$33,000 ignores cost of sales, so it is not a valid profit figure.","D":"$69,000 wrongly adds expenses to gross profit instead of subtracting them."}}},{"id":"P1_U5_MCQ_439","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_439","question":"To reduce cost of sales and boost gross profit, a gourmet burger chain switches to a much cheaper beef supplier. What is the main commercial risk of this cost-cutting measure?","options":{"A":"Lower meat quality may disappoint regular diners, harming brand reputation and causing future sales revenue to fall","B":"Cheaper beef automatically doubles fixed restaurant rent","C":"Gross profit margin will immediately drop to 0%","D":"The burger chain will have to pay more corporation tax even if revenue collapses"},"correctOption":"A","correctAnswer":"Lower meat quality may disappoint regular diners, harming brand reputation and causing future sales revenue to fall","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting direct material costs can improve short-term gross margin, but sacrificing quality drives away repeat customers.","distractor_reasons":{"A":"Option A is correct because cutting direct material costs can improve short-term gross margin, but sacrificing quality drives away repeat customers.","B":"Incorrect because supplier beef prices do not change fixed property rent.","C":"Incorrect because cheaper beef lowers cost of sales and raises gross profit margin initially.","D":"Incorrect because corporation tax is charged as a percentage of actual profit earned."}}},{"id":"P1_U5_MCQ_440","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_440","question":"An accounting consultancy reduces its annual profit decline by moving from an expensive city-centre office to a lower-rent suburban office park. How does this decision affect its statement of profit or loss?","options":{"A":"Share capital increases on the statement of profit or loss","B":"Cost of sales decreases and gross profit rises","C":"Sales revenue increases automatically","D":"Overhead expenses decrease, increasing final profit while leaving gross profit unchanged"},"correctOption":"D","correctAnswer":"Overhead expenses decrease, increasing final profit while leaving gross profit unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because office rent is an indirect overhead expense; lowering it directly increases final profit without altering gross profit.","distractor_reasons":{"A":"Incorrect because share capital appears on the statement of financial position, not the statement of profit or loss.","B":"Incorrect because office rent is an indirect overhead rather than a direct cost of sales.","C":"Incorrect because moving to a cheaper office does not automatically increase client fee revenue.","D":"Option D is correct because office rent is an indirect overhead expense; lowering it directly increases final profit without altering gross profit."}}},{"id":"P1_U5_MCQ_441","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_441","question":"A fitness equipment brand spends $25,000 on an online advertising campaign. As a result, sales revenue rises by $80,000, while direct manufacturing cost of sales rises by $42,000. What is the net impact on the brand's final profit?","options":{"A":"Final profit increases by $13,000","B":"Final profit increases by $38,000","C":"Final profit increases by $55,000","D":"Final profit decreases by $25,000"},"correctOption":"A","correctAnswer":"Final profit increases by $13,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because extra gross profit = $80,000 revenue - $42,000 cost of sales = $38,000, and subtracting the $25,000 advertising expense yields a net profit gain of $13,000.","distractor_reasons":{"A":"Option A is correct because extra gross profit = $80,000 revenue - $42,000 cost of sales = $38,000, and subtracting the $25,000 advertising expense yields a net profit gain of $13,000.","B":"Incorrect because $38,000 is the increase in gross profit before deducting the $25,000 advertising expense.","C":"Incorrect because $55,000 subtracts advertising from revenue ($80,000 - $25,000) and forgets the $42,000 extra cost of sales.","D":"Incorrect because the $38,000 gross profit gain exceeds the $25,000 ad spend."}}},{"id":"P1_U5_MCQ_442","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_442","question":"Comparing Year 1 and Year 2 statements of profit or loss, a clothing retailer sees revenue stay constant at $500,000, overhead expenses stay constant at $120,000, and final profit fall from $130,000 to $90,000. What caused the $40,000 drop in profit?","options":{"A":"Overhead expenses increased by $40,000","B":"Cost of sales increased by $40,000 (from $250,000 to $290,000), reducing gross profit by $40,000","C":"Revenue fell by $40,000","D":"Shareholders withdrew $40,000 in share capital"},"correctOption":"B","correctAnswer":"Cost of sales increased by $40,000 (from $250,000 to $290,000), reducing gross profit by $40,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because since revenue ($500,000) and overhead expenses ($120,000) were unchanged, the $40,000 fall in profit must have come from a $40,000 rise in cost of sales.","distractor_reasons":{"A":"Incorrect because the question states overhead expenses stayed constant at $120,000.","B":"Option B is correct because since revenue ($500,000) and overhead expenses ($120,000) were unchanged, the $40,000 fall in profit must have come from a $40,000 rise in cost of sales.","C":"Incorrect because the question states revenue stayed constant at $500,000.","D":"Incorrect because share capital changes do not appear on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_443","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_443","question":"A restaurant group reviews branch-level profit statements: City Bistro earns $400,000 revenue, $140,000 cost of sales, and $190,000 branch expenses; Airport Café earns $350,000 revenue, $120,000 cost of sales, and $140,000 branch expenses. Which branch contributes more final profit?","options":{"A":"Both branches contribute the exact same final profit of $70,000","B":"City Bistro contributes $260,000 profit compared with $230,000 from Airport Café","C":"Airport Café contributes $90,000 profit compared with $70,000 from City Bistro","D":"City Bistro is making a loss of -$50,000"},"correctOption":"C","correctAnswer":"Airport Café contributes $90,000 profit compared with $70,000 from City Bistro","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Airport Café profit = $350,000 - $120,000 - $140,000 = $90,000, exceeding City Bistro's profit of $400,000 - $140,000 - $190,000 = $70,000.","distractor_reasons":{"A":"Incorrect because $90,000 is $20,000 higher than $70,000.","B":"Incorrect because $260,000 and $230,000 are gross profits before deducting branch overhead expenses.","C":"Option C is correct because Airport Café profit = $350,000 - $120,000 - $140,000 = $90,000, exceeding City Bistro's profit of $400,000 - $140,000 - $190,000 = $70,000.","D":"Incorrect because City Bistro earns a positive profit of $70,000."}}},{"id":"P1_U5_MCQ_444","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_444","question":"A phone-case seller currently sells 10,000 cases at $20 each (unit cost of sales $8, fixed overheads $70,000). If cutting the price to $16 boosts sales volume to 15,000 cases while unit cost and fixed overheads stay unchanged, how does profit change?","options":{"A":"Profit stays unchanged at $50,000 ($120,000 gross profit minus $70,000 overheads in both cases)","B":"Profit rises from $50,000 to $90,000","C":"Profit falls from $50,000 to $10,000","D":"Profit rises from $120,000 to $170,000"},"correctOption":"A","correctAnswer":"Profit stays unchanged at $50,000 ($120,000 gross profit minus $70,000 overheads in both cases)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because initially: ($200,000 revenue - $80,000 cost of sales) - $70,000 overheads = $50,000 profit; after price cut: ($240,000 revenue - $120,000 cost of sales) - $70,000 overheads = $50,000 profit.","distractor_reasons":{"A":"Option A is correct because initially: ($200,000 revenue - $80,000 cost of sales) - $70,000 overheads = $50,000 profit; after price cut: ($240,000 revenue - $120,000 cost of sales) - $70,000 overheads = $50,000 profit.","B":"Incorrect because $90,000 forgets that unit cost of sales ($8) applies to the 5,000 extra cases sold ($40,000 extra cost).","C":"Incorrect because total gross profit stayed at $120,000 (($16 - $8) × 15,000).","D":"Incorrect because $120,000 is gross profit before deducting $70,000 of overheads."}}},{"id":"P1_U5_MCQ_445","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_445","question":"When deciding how to divide profit after tax between dividends and retained profit, what conflict must a public limited company's directors balance?","options":{"A":"Paying generous dividends keeps current shareholders happy and supports the share price, whereas retaining profit funds long-term growth without borrowing","B":"Paying dividends increases corporation tax to 100%","C":"Retained profit must be handed over to competitors at year-end","D":"Dividends are subtracted before calculating gross profit"},"correctOption":"A","correctAnswer":"Paying generous dividends keeps current shareholders happy and supports the share price, whereas retaining profit funds long-term growth without borrowing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because directors must balance shareholders' desire for immediate dividend income against the company's need for internal retained capital to invest in future expansion.","distractor_reasons":{"A":"Option A is correct because directors must balance shareholders' desire for immediate dividend income against the company's need for internal retained capital to invest in future expansion.","B":"Incorrect because dividends are paid out of after-tax profit and do not raise corporation tax rates.","C":"Incorrect because retained profit stays inside the company as reserves.","D":"Incorrect because dividends are appropriated at the very bottom after profit after tax."}}},{"id":"P1_U5_MCQ_446","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_446","question":"How do potential investors use a company's statement of profit or loss before deciding whether to buy its shares?","options":{"A":"To examine revenue growth, cost control, and after-tax profit trends to judge likely future dividends and share value growth","B":"To verify the exact street addresses of all retail suppliers","C":"To check whether the company has any physical premises","D":"To replace the statement of financial position when checking long-term mortgages"},"correctOption":"A","correctAnswer":"To examine revenue growth, cost control, and after-tax profit trends to judge likely future dividends and share value growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because investors evaluate historical profitability trends to assess management efficiency and expected returns on their investment.","distractor_reasons":{"A":"Option A is correct because investors evaluate historical profitability trends to assess management efficiency and expected returns on their investment.","B":"Incorrect because supplier street addresses are not listed in financial statements.","C":"Incorrect because physical property assets appear on the statement of financial position.","D":"Incorrect because mortgages appear on the statement of financial position."}}},{"id":"P1_U5_MCQ_447","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_447","question":"When reviewing a statement of profit or loss, why does a bank manager check profit before interest and tax alongside existing loan interest expenses?","options":{"A":"To calculate how many employees work in the marketing department","B":"To see whether the business generates enough operating profit to comfortably cover existing and proposed interest charges","C":"To determine whether the business holds enough raw material inventory","D":"To set the government's national corporation tax rate"},"correctOption":"B","correctAnswer":"To see whether the business generates enough operating profit to comfortably cover existing and proposed interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because lenders assess whether trading profits provide a safe margin above contractual interest obligations.","distractor_reasons":{"A":"Incorrect because headcount is not calculated from interest figures.","B":"Option B is correct because lenders assess whether trading profits provide a safe margin above contractual interest obligations.","C":"Incorrect because inventory levels are shown on the statement of financial position.","D":"Incorrect because governments set tax rates, not commercial bank managers."}}},{"id":"P1_U5_MCQ_448","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_448","question":"Why do employees and trade unions examine their employer's annual statement of profit or loss?","options":{"A":"To assess job security and use strong profit growth as evidence when negotiating higher pay or bonuses","B":"To decide whether to approve a new share issue on the stock exchange","C":"To calculate the exact depreciation rate of factory computers","D":"To assess whether the company's customers are paying on 30-day credit"},"correctOption":"A","correctAnswer":"To assess job security and use strong profit growth as evidence when negotiating higher pay or bonuses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustained profits reassure workers about job stability and strengthen union arguments for pay rises.","distractor_reasons":{"A":"Option A is correct because sustained profits reassure workers about job stability and strengthen union arguments for pay rises.","B":"Incorrect because new share issues are approved by shareholders and directors, not employees.","C":"Incorrect because depreciation policies are set by company accountants.","D":"Incorrect because customer credit periods are analyzed from trade receivables on the statement of financial position."}}},{"id":"P1_U5_MCQ_449","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_449","question":"Why is a raw-material supplier interested in a customer's statement of profit or loss in addition to its statement of financial position?","options":{"A":"A profitable customer is likely to stay in business and continue placing repeat orders over the long term","B":"Suppliers collect a percentage of their customers' retained profit by law","C":"The statement of profit or loss shows the customer's exact daily bank balance","D":"Suppliers use it to calculate their own corporation tax bill"},"correctOption":"A","correctAnswer":"A profitable customer is likely to stay in business and continue placing repeat orders over the long term","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because suppliers want reliable, ongoing trading partners; consistent profitability signals long-term business survival and repeat orders.","distractor_reasons":{"A":"Option A is correct because suppliers want reliable, ongoing trading partners; consistent profitability signals long-term business survival and repeat orders.","B":"Incorrect because suppliers are paid for goods delivered, not a share of customer profits.","C":"Incorrect because bank balances appear on the statement of financial position and cash records.","D":"Incorrect because a supplier pays tax on its own profits, not its customers' profits."}}},{"id":"P1_U5_MCQ_450","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_450","question":"Which statement describes a key limitation of relying solely on a company's statement of profit or loss to judge its overall health?","options":{"A":"It can only be prepared once every five years","B":"It illegally omits all overhead expenses in public limited companies","C":"It only records transactions where physical banknotes changed hands","D":"It records past trading profit rather than cash liquidity, so a company reporting high profits could still be close to running out of cash"},"correctOption":"D","correctAnswer":"It records past trading profit rather than cash liquidity, so a company reporting high profits could still be close to running out of cash","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the statement of profit or loss measures profitability over a past period and does not show cash balances, liquidity, or debt obligations.","distractor_reasons":{"A":"Incorrect because statements of profit or loss are prepared at least annually.","B":"Incorrect because all overhead expenses must be included by law.","C":"Incorrect because credit sales and accrued expenses are included regardless of when cash moves.","D":"Option D is correct because the statement of profit or loss measures profitability over a past period and does not show cash balances, liquidity, or debt obligations."}}},{"id":"P1_U5_MCQ_451","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_451","question":"Why is a statement of financial position often described as a 'financial snapshot' rather than a video of the whole year?","options":{"A":"Because it records the exact value of a business's assets, liabilities, and equity at one specific point in time (such as 31 December)","B":"Because it only includes photographs of the company's factories and vehicles","C":"Because it measures total sales revenue earned across all 12 months","D":"Because its figures never change from one year to the next"},"correctOption":"A","correctAnswer":"Because it records the exact value of a business's assets, liabilities, and equity at one specific point in time (such as 31 December)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unlike the statement of profit or loss (which covers a period of time), the statement of financial position shows balances on a single reporting date.","distractor_reasons":{"A":"Option A is correct because unlike the statement of profit or loss (which covers a period of time), the statement of financial position shows balances on a single reporting date.","B":"Incorrect because it is a numerical financial statement, not a collection of photographs.","C":"Incorrect because total sales revenue over 12 months appears on the statement of profit or loss.","D":"Incorrect because asset, liability, and reserve balances change continuously as the business trades."}}},{"id":"P1_U5_MCQ_452","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_452","question":"Which item on an airline's statement of financial position is classified as a 'non-current asset'?","options":{"A":"Passenger aircraft and airport maintenance hangars owned by the airline","B":"Jet fuel inventory stored for next week's flights","C":"Ticket payments owed by corporate travel agencies within 30 days","D":"A 12-year bank loan used to finance fleet expansion"},"correctOption":"A","correctAnswer":"Passenger aircraft and airport maintenance hangars owned by the airline","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because aircraft and hangars are long-term physical resources owned and used for more than 12 months to generate revenue.","distractor_reasons":{"A":"Option A is correct because aircraft and hangars are long-term physical resources owned and used for more than 12 months to generate revenue.","B":"Incorrect because jet fuel inventory is a short-term current asset.","C":"Incorrect because money owed by travel agencies is trade receivables (a current asset).","D":"Incorrect because a 12-year bank loan is a non-current liability."}}},{"id":"P1_U5_MCQ_453","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_453","question":"Which group consists ENTIRELY of 'current assets' on a manufacturing business's statement of financial position?","options":{"A":"Trade receivables, trade payables, and cash in hand","B":"Factory land, delivery vans, and cash at bank","C":"Raw material inventory, finished goods inventory, trade receivables, and cash at bank","D":"Bank overdraft, raw material inventory, and retained profit"},"correctOption":"C","correctAnswer":"Raw material inventory, finished goods inventory, trade receivables, and cash at bank","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because inventories, trade receivables, and cash are all short-term resources expected to be used or converted into cash within one year.","distractor_reasons":{"A":"Incorrect because trade payables are a current liability, not an asset.","B":"Incorrect because factory land and delivery vans are non-current assets.","C":"Option C is correct because inventories, trade receivables, and cash are all short-term resources expected to be used or converted into cash within one year.","D":"Incorrect because a bank overdraft is a current liability and retained profit is equity."}}},{"id":"P1_U5_MCQ_454","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_454","question":"In what order are current assets normally listed on a standard statement of financial position from least liquid to most liquid?","options":{"A":"Trade receivables -> Cash and cash equivalents -> Inventories","B":"Cash and cash equivalents -> Trade receivables -> Inventories","C":"Inventories -> Trade receivables -> Cash and cash equivalents","D":"Inventories -> Cash and cash equivalents -> Trade receivables"},"correctOption":"C","correctAnswer":"Inventories -> Trade receivables -> Cash and cash equivalents","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because inventories must first be sold (often on credit) to become trade receivables, which are then collected to become cash—the most liquid asset.","distractor_reasons":{"A":"Incorrect because cash is more liquid than both trade receivables and inventories.","B":"Incorrect because this lists them from most liquid to least liquid.","C":"Option C is correct because inventories must first be sold (often on credit) to become trade receivables, which are then collected to become cash—the most liquid asset.","D":"Incorrect because trade receivables convert into cash sooner than unsold inventories."}}},{"id":"P1_U5_MCQ_455","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_455","question":"Which pair of items represents 'current liabilities' on a retail company's statement of financial position?","options":{"A":"Trade payables owed to stock suppliers and a short-term bank overdraft","B":"Trade receivables owed by customers and cash in the till","C":"A 20-year mortgage and issued share capital","D":"Shop display shelving and retained profit"},"correctOption":"A","correctAnswer":"Trade payables owed to stock suppliers and a short-term bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade payables and bank overdrafts are short-term debts that must be settled within 12 months.","distractor_reasons":{"A":"Option A is correct because trade payables and bank overdrafts are short-term debts that must be settled within 12 months.","B":"Incorrect because trade receivables and cash are current assets.","C":"Incorrect because a 20-year mortgage is a non-current liability and share capital is equity.","D":"Incorrect because display shelving is a non-current asset and retained profit is equity."}}},{"id":"P1_U5_MCQ_456","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_456","question":"Which item is classified as a 'non-current liability' on a company's statement of financial position?","options":{"A":"A 10-year commercial mortgage borrowed to purchase a warehouse","B":"Unpaid electricity bills due next month","C":"Retained profit accumulated over five years","D":"Freehold land owned by the company"},"correctOption":"A","correctAnswer":"A 10-year commercial mortgage borrowed to purchase a warehouse","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a 10-year mortgage is a long-term debt obligation repayable over more than one year.","distractor_reasons":{"A":"Option A is correct because a 10-year mortgage is a long-term debt obligation repayable over more than one year.","B":"Incorrect because bills due next month are current liabilities.","C":"Incorrect because retained profit is part of shareholders' equity, not a debt.","D":"Incorrect because freehold land is a non-current asset."}}},{"id":"P1_U5_MCQ_457","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_457","question":"On a limited company's statement of financial position, which two items are added together to calculate 'Total shareholders' equity'?","options":{"A":"Gross profit and overhead expenses","B":"Non-current assets and current assets","C":"Current liabilities and non-current liabilities","D":"Share capital and retained profit (reserves)"},"correctOption":"D","correctAnswer":"Share capital and retained profit (reserves)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shareholders' equity represents the owners' total financial stake in the company, comprising original share capital plus accumulated retained profits.","distractor_reasons":{"A":"Incorrect because gross profit and overhead expenses appear on the statement of profit or loss.","B":"Incorrect because non-current assets plus current assets equals total assets.","C":"Incorrect because current liabilities plus non-current liabilities equals total liabilities.","D":"Option D is correct because shareholders' equity represents the owners' total financial stake in the company, comprising original share capital plus accumulated retained profits."}}},{"id":"P1_U5_MCQ_458","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_458","question":"A bakery's statement of financial position shows inventories of $12,000, trade receivables of $8,500, cash of $4,500, trade payables of $11,000, and a bank overdraft of $3,500. What is the bakery's net current assets (working capital)?","options":{"A":"$6,000","B":"$14,000","C":"$39,500","D":"$10,500"},"correctOption":"D","correctAnswer":"$10,500","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Current assets = $12,000 + $8,500 + $4,500 = $25,000 and Current liabilities = $11,000 + $3,500 = $14,500, so Working capital = $25,000 - $14,500 = $10,500.","distractor_reasons":{"A":"Incorrect because $6,000 omits the $4,500 cash balance from current assets ($20,500 - $14,500).","B":"Incorrect because $14,000 omits the $3,500 bank overdraft from current liabilities ($25,000 - $11,000).","C":"Incorrect because $39,500 adds current assets and current liabilities ($25,000 + $14,500).","D":"Option D is correct because Current assets = $12,000 + $8,500 + $4,500 = $25,000 and Current liabilities = $11,000 + $3,500 = $14,500, so Working capital = $25,000 - $14,500 = $10,500."}}},{"id":"P1_U5_MCQ_459","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_459","question":"A printing company has non-current assets of $520,000, current assets of $110,000, current liabilities of $65,000, and non-current liabilities of $195,000. What is the value of the company's net assets?","options":{"A":"$630,000","B":"$565,000","C":"$370,000","D":"$260,000"},"correctOption":"C","correctAnswer":"$370,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Net assets = Total assets ($520,000 + $110,000 = $630,000) - Total liabilities ($65,000 + $195,000 = $260,000) = $370,000.","distractor_reasons":{"A":"Incorrect because $630,000 is total assets before deducting any liabilities.","B":"Incorrect because $565,000 is capital employed ($630,000 - $65,000), which has not deducted non-current liabilities.","C":"Option C is correct because Net assets = Total assets ($520,000 + $110,000 = $630,000) - Total liabilities ($65,000 + $195,000 = $260,000) = $370,000.","D":"Incorrect because $260,000 is total liabilities, not net assets."}}},{"id":"P1_U5_MCQ_460","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_460","question":"A food-processing company has share capital of $400,000, retained profit of $250,000, non-current liabilities of $350,000, and current liabilities of $90,000. What is the company's capital employed?","options":{"A":"$1,000,000","B":"$650,000","C":"$1,090,000","D":"$750,000"},"correctOption":"A","correctAnswer":"$1,000,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Capital employed = Total shareholders' equity ($400,000 + $250,000 = $650,000) + Non-current liabilities ($350,000) = $1,000,000.","distractor_reasons":{"A":"Option A is correct because Capital employed = Total shareholders' equity ($400,000 + $250,000 = $650,000) + Non-current liabilities ($350,000) = $1,000,000.","B":"Incorrect because $650,000 is shareholders' equity alone, omitting non-current liabilities.","C":"Incorrect because $1,090,000 wrongly includes short-term current liabilities ($90,000).","D":"Incorrect because $750,000 omits retained profit ($400,000 + $350,000)."}}},{"id":"P1_U5_MCQ_461","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_461","question":"On a company's statement of financial position, non-current assets are $410,000, inventories are $30,000, trade receivables are $25,000, current liabilities are $40,000, non-current liabilities are $120,000, share capital is $200,000, and retained profit is $120,000. What must the missing cash balance be for the statement to balance?","options":{"A":"$15,000","B":"$55,000","C":"$70,000","D":"$0"},"correctOption":"A","correctAnswer":"$15,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Total equity = $200,000 + $120,000 = $320,000; Net assets must equal $320,000, so Total assets = $320,000 + $120,000 + $40,000 = $480,000; Cash = $480,000 - ($410,000 + $30,000 + $25,000) = $15,000.","distractor_reasons":{"A":"Option A is correct because Total equity = $200,000 + $120,000 = $320,000; Net assets must equal $320,000, so Total assets = $320,000 + $120,000 + $40,000 = $480,000; Cash = $480,000 - ($410,000 + $30,000 + $25,000) = $15,000.","B":"Incorrect because $55,000 forgets to include the $40,000 current liabilities in total assets.","C":"Incorrect because $70,000 is total current assets ($30,000 + $25,000 + $15,000), not cash alone.","D":"Incorrect because without $15,000 of cash, total assets ($465,000) would not match total liabilities and equity ($480,000)."}}},{"id":"P1_U5_MCQ_462","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_462","question":"A private limited company issues 50,000 new ordinary shares at $2 each, receiving $100,000 cash into its bank current account. How does this transaction immediately change the company's statement of financial position?","options":{"A":"Current assets (cash) increase by $100,000 and non-current liabilities increase by $100,000","B":"Current assets (cash) increase by $100,000 and shareholders' equity (share capital) increases by $100,000","C":"Non-current assets increase by $100,000 and current liabilities increase by $100,000","D":"Working capital decreases by $100,000"},"correctOption":"B","correctAnswer":"Current assets (cash) increase by $100,000 and shareholders' equity (share capital) increases by $100,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because receiving cash from shareholders boosts cash (+$100,000 current asset) and increases issued share capital (+$100,000 equity).","distractor_reasons":{"A":"Incorrect because issuing ordinary shares raises equity, not long-term debt liabilities.","B":"Option B is correct because receiving cash from shareholders boosts cash (+$100,000 current asset) and increases issued share capital (+$100,000 equity).","C":"Incorrect because cash is a current asset and share capital is equity.","D":"Incorrect because current assets rise by $100,000 while current liabilities stay unchanged, so working capital increases by $100,000."}}},{"id":"P1_U5_MCQ_463","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_463","question":"A manufacturing firm borrows $160,000 via a 6-year bank loan and immediately spends the entire $160,000 to buy automated packaging machinery. What is the net effect on the statement of financial position?","options":{"A":"Working capital increases by $160,000","B":"Current assets increase by $160,000 and shareholders' equity increases by $160,000","C":"Non-current assets increase by $160,000 and non-current liabilities increase by $160,000","D":"Non-current assets increase by $160,000 and current liabilities increase by $160,000"},"correctOption":"C","correctAnswer":"Non-current assets increase by $160,000 and non-current liabilities increase by $160,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the packaging machinery adds $160,000 to non-current assets, while the 6-year loan adds $160,000 to non-current liabilities.","distractor_reasons":{"A":"Incorrect because neither current assets nor current liabilities changed on net.","B":"Incorrect because the cash was spent on machinery, and loans create liabilities rather than equity.","C":"Option C is correct because the packaging machinery adds $160,000 to non-current assets, while the 6-year loan adds $160,000 to non-current liabilities.","D":"Incorrect because a 6-year bank loan is a non-current liability, not a current liability."}}},{"id":"P1_U5_MCQ_464","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_464","question":"A clothing store uses $14,000 from its bank current account to pay off an overdue supplier invoice (trade payable). How does this payment affect the store's statement of financial position?","options":{"A":"Non-current assets decrease by $14,000","B":"Working capital decreases by $14,000","C":"Shareholders' equity decreases by $14,000","D":"Current assets (cash) decrease by $14,000 and current liabilities (trade payables) decrease by $14,000, leaving working capital unchanged"},"correctOption":"D","correctAnswer":"Current assets (cash) decrease by $14,000 and current liabilities (trade payables) decrease by $14,000, leaving working capital unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because paying a supplier reduces cash (-$14,000 current asset) and eliminates the debt (-$14,000 current liability), leaving Net current assets unchanged.","distractor_reasons":{"A":"Incorrect because cash is a current asset, not a non-current asset.","B":"Incorrect because both current assets and current liabilities fall by the exact same $14,000.","C":"Incorrect because paying an existing liability does not reduce shareholders' equity.","D":"Option D is correct because paying a supplier reduces cash (-$14,000 current asset) and eliminates the debt (-$14,000 current liability), leaving Net current assets unchanged."}}},{"id":"P1_U5_MCQ_465","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_465","question":"During the year, a profitable design agency earns $45,000 in retained profit, all of which stays in its bank current account at year-end. How does this retained profit appear on the year-end statement of financial position?","options":{"A":"It is recorded only as a current liability owed to customers","B":"It increases non-current liabilities by $45,000","C":"It reduces share capital by $45,000","D":"It increases the cash balance under current assets by $45,000 and increases the retained profit reserve under shareholders' equity by $45,000"},"correctOption":"D","correctAnswer":"It increases the cash balance under current assets by $45,000 and increases the retained profit reserve under shareholders' equity by $45,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retained profit belongs to the owners (increasing equity reserves) while the cash earned sits in current assets (or other assets acquired).","distractor_reasons":{"A":"Incorrect because retained profit is not owed to customers.","B":"Incorrect because retained profit is owners' equity, not an external debt liability.","C":"Incorrect because retained profit adds to equity rather than reducing share capital.","D":"Option D is correct because retained profit belongs to the owners (increasing equity reserves) while the cash earned sits in current assets (or other assets acquired)."}}},{"id":"P1_U5_MCQ_466","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_466","question":"An electronics shop sells a batch of laptops that cost $10,000 for $14,000 in immediate cash. How does this sale change the shop's statement of financial position?","options":{"A":"Inventory falls by $10,000, cash rises by $14,000, and retained profit (equity) rises by the $4,000 profit","B":"Inventory falls by $14,000 and cash rises by $10,000","C":"Total assets remain completely unchanged","D":"Current liabilities increase by $4,000"},"correctOption":"A","correctAnswer":"Inventory falls by $10,000, cash rises by $14,000, and retained profit (equity) rises by the $4,000 profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because total assets rise by $4,000 net (+$14,000 cash minus -$10,000 inventory at cost), balanced by the $4,000 profit added to shareholders' equity.","distractor_reasons":{"A":"Option A is correct because total assets rise by $4,000 net (+$14,000 cash minus -$10,000 inventory at cost), balanced by the $4,000 profit added to shareholders' equity.","B":"Incorrect because inventory is valued at its $10,000 cost, while cash received is the $14,000 selling price.","C":"Incorrect because total assets increase by $4,000 when goods are sold above cost.","D":"Incorrect because selling goods for cash creates no liability."}}},{"id":"P1_U5_MCQ_467","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_467","question":"A toy retailer's statement of financial position shows inventories of $180,000, trade receivables of $15,000, cash of $2,000, and a bank overdraft of $95,000. What liquidity issue does this reveal?","options":{"A":"The retailer has too much cash tied up in unsold toy inventory and lacks liquid cash to cover its large bank overdraft","B":"The retailer holds excessive idle cash in its bank current account","C":"The retailer has zero short-term liabilities","D":"The retailer's non-current liabilities exceed its non-current assets"},"correctOption":"A","correctAnswer":"The retailer has too much cash tied up in unsold toy inventory and lacks liquid cash to cover its large bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because $180,000 is locked in slow-moving stock while cash is only $2,000 against a $95,000 overdraft, signaling overstocking and poor liquidity.","distractor_reasons":{"A":"Option A is correct because $180,000 is locked in slow-moving stock while cash is only $2,000 against a $95,000 overdraft, signaling overstocking and poor liquidity.","B":"Incorrect because cash is only $2,000 alongside a $95,000 overdraft.","C":"Incorrect because a $95,000 bank overdraft is a substantial current liability.","D":"Incorrect because non-current figures are not mentioned and the problem lies in working capital."}}},{"id":"P1_U5_MCQ_468","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_468","question":"Which of the following would increase a company's working capital, assuming all other items remain unchanged?","options":{"A":"Receiving a two-year bank loan credited directly to the business's current account","B":"Buying a new delivery van using cash from the business account","C":"Using cash to pay an outstanding trade payable","D":"Buying extra inventory on credit from a supplier"},"correctOption":"A","correctAnswer":"Receiving a two-year bank loan credited directly to the business's current account","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the loan raises current assets (cash) without creating a current liability, so working capital increases.","distractor_reasons":{"A":"Option A is correct because the loan raises current assets (cash) without creating a current liability, so working capital increases.","B":"Incorrect because buying a van with cash swaps one asset for a non-current one, reducing current assets and working capital.","C":"Incorrect because paying a trade payable reduces cash and current liabilities by the same amount, leaving working capital unchanged.","D":"Incorrect because buying inventory on credit increases both current assets and current liabilities equally, so working capital is unchanged."}}},{"id":"P1_U5_MCQ_469","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_469","question":"Over four years, a software company's retained profit reserve on its statement of financial position grew steadily from $80,000 to $490,000 while its bank loans fell to zero. What does this trend show?","options":{"A":"The company has been consistently profitable, reinvested earnings to grow its net worth, and strengthened its financial stability","B":"The company has been making continuous losses every year","C":"The company paid out 100% of its profits as dividends every year","D":"The company's current liabilities have quadrupled"},"correctOption":"A","correctAnswer":"The company has been consistently profitable, reinvested earnings to grow its net worth, and strengthened its financial stability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising retained profit reserves paired with eliminated debt demonstrate sustained profitability and internal wealth accumulation.","distractor_reasons":{"A":"Option A is correct because rising retained profit reserves paired with eliminated debt demonstrate sustained profitability and internal wealth accumulation.","B":"Incorrect because losses erode rather than build retained profit reserves.","C":"Incorrect because paying out 100% of profits as dividends would leave retained profit unchanged.","D":"Incorrect because bank loans fell to zero rather than quadrupling."}}},{"id":"P1_U5_MCQ_470","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_470","question":"Before approving a $500,000 10-year loan for a haulage company, why does a bank inspect the company's non-current assets and non-current liabilities on its statement of financial position?","options":{"A":"To check whether the company owns valuable unencumbered property or vehicles to act as collateral and how much long-term debt it already owes","B":"To calculate the company's gross profit margin on fuel sales","C":"To decide which truck drivers should receive annual bonuses","D":"To replace the need for a cash flow forecast"},"correctOption":"A","correctAnswer":"To check whether the company owns valuable unencumbered property or vehicles to act as collateral and how much long-term debt it already owes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because banks assess non-current assets for potential loan security and non-current liabilities to measure existing long-term debt burdens.","distractor_reasons":{"A":"Option A is correct because banks assess non-current assets for potential loan security and non-current liabilities to measure existing long-term debt burdens.","B":"Incorrect because gross profit margin is calculated from the statement of profit or loss.","C":"Incorrect because driver bonuses are internal HR decisions.","D":"Incorrect because banks examine both the statement of financial position and cash flow forecasts."}}},{"id":"P1_U5_MCQ_471","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_471","question":"A timber wholesaler is deciding whether to extend 60-day trade credit to a furniture manufacturer. Looking at the manufacturer's statement of financial position, which combination would reassure the wholesaler?","options":{"A":"Zero current assets and large overdue trade payables","B":"Current assets that comfortably exceed current liabilities, including a healthy cash balance","C":"A large bank overdraft exceeding total current assets","D":"Negative working capital of -$80,000"},"correctOption":"B","correctAnswer":"Current assets that comfortably exceed current liabilities, including a healthy cash balance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because positive working capital and strong cash reserves indicate the manufacturer can pay supplier invoices on time.","distractor_reasons":{"A":"Incorrect because zero current assets and overdue payables signal high default risk.","B":"Option B is correct because positive working capital and strong cash reserves indicate the manufacturer can pay supplier invoices on time.","C":"Incorrect because a massive overdraft indicates severe cash strain.","D":"Incorrect because negative working capital warns that short-term debts exceed short-term assets."}}},{"id":"P1_U5_MCQ_472","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_472","question":"A multinational food group is considering buying out a smaller snack-food company. How does the snack-food company's statement of financial position assist the buyer?","options":{"A":"It shows the personal bank balances of the target company's factory workers","B":"It guarantees how many new snack flavours customers will buy next year","C":"It shows the net asset value of the target company's factories, equipment, inventory, and cash minus all debts that the buyer will inherit","D":"It eliminates the need to negotiate a takeover price"},"correctOption":"C","correctAnswer":"It shows the net asset value of the target company's factories, equipment, inventory, and cash minus all debts that the buyer will inherit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because acquiring a company means taking over its assets and liabilities; net assets provide a baseline valuation of the business.","distractor_reasons":{"A":"Incorrect because employee personal finances are not part of company accounts.","B":"Incorrect because historical financial positions do not guarantee future product demand.","C":"Option C is correct because acquiring a company means taking over its assets and liabilities; net assets provide a baseline valuation of the business.","D":"Incorrect because net asset value informs valuation negotiations rather than replacing them."}}},{"id":"P1_U5_MCQ_473","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_473","question":"A family bakery bought its freehold shop building 25 years ago for $120,000, and it is still listed at that historical cost on its statement of financial position, even though local property prices have tripled. What limitation of financial statements does this illustrate?","options":{"A":"Freehold buildings are illegally omitted from statements of financial position","B":"Assets recorded at historical cost minus depreciation may differ significantly from their true current market resale value","C":"Buildings are classified as short-term current liabilities","D":"Historical cost accounting overstates cash in the bank"},"correctOption":"B","correctAnswer":"Assets recorded at historical cost minus depreciation may differ significantly from their true current market resale value","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because accounting conventions often value non-current assets based on historical purchase cost rather than current market prices, understating true property worth.","distractor_reasons":{"A":"Incorrect because freehold buildings are included under non-current assets.","B":"Option B is correct because accounting conventions often value non-current assets based on historical purchase cost rather than current market prices, understating true property worth.","C":"Incorrect because owned buildings are non-current assets, not liabilities.","D":"Incorrect because historical property valuation does not alter the cash balance."}}},{"id":"P1_U5_MCQ_474","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_474","question":"Why might a statement of financial position dated 31 December give a misleading impression of a seasonal ski-resort hotel's typical financial position?","options":{"A":"Because hotels are legally allowed to omit all bank loans on 31 December","B":"Because 31 December falls during peak winter holiday season when cash balances are unusually high compared with quiet summer months","C":"Because non-current assets disappear during winter months","D":"Because statements of financial position never balance on 31 December"},"correctOption":"B","correctAnswer":"Because 31 December falls during peak winter holiday season when cash balances are unusually high compared with quiet summer months","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a single-day snapshot reflects seasonal peaks or troughs and may not represent average liquidity throughout the year.","distractor_reasons":{"A":"Incorrect because all liabilities must be reported accurately on the balance sheet date.","B":"Option B is correct because a single-day snapshot reflects seasonal peaks or troughs and may not represent average liquidity throughout the year.","C":"Incorrect because hotel buildings and equipment remain throughout the year.","D":"Incorrect because statements of financial position always balance regardless of the date."}}},{"id":"P1_U5_MCQ_475","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_475","question":"A world-famous software firm's most valuable competitive strengths are its patented algorithms, loyal user base, and highly skilled engineers, yet these do not appear fully on its statement of financial position. Why?","options":{"A":"Customer loyalty is deducted from gross profit on the statement of profit or loss","B":"Software firms are legally prohibited from preparing statements of financial position","C":"Skilled engineers are recorded as non-current liabilities","D":"Financial statements only record items that can be reliably measured in monetary terms, omitting qualitative human capital and internally built brand loyalty"},"correctOption":"D","correctAnswer":"Financial statements only record items that can be reliably measured in monetary terms, omitting qualitative human capital and internally built brand loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because standard accounting statements capture tangible and quantifiable monetary figures while excluding intangible human and reputational strengths.","distractor_reasons":{"A":"Incorrect because customer loyalty is not an expense.","B":"Incorrect because incorporated software firms must prepare full financial statements.","C":"Incorrect because employees are not recorded as liabilities on the balance sheet.","D":"Option D is correct because standard accounting statements capture tangible and quantifiable monetary figures while excluding intangible human and reputational strengths."}}},{"id":"P1_U5_MCQ_476","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_476","question":"What are the two main types of comparison that businesses and investors perform using financial ratios?","options":{"A":"Comparing historical share prices with employee birthdays","B":"Comparing a local bakery's ratios with a multinational oil company and a hospital","C":"Comparing cash inflows with the number of factory windows","D":"Comparing a business's ratios over time (trend analysis) and comparing them with competitors in the same industry (inter-firm comparison)"},"correctOption":"D","correctAnswer":"Comparing a business's ratios over time (trend analysis) and comparing them with competitors in the same industry (inter-firm comparison)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ratios become meaningful when tracked across consecutive years for the same firm or benchmarked against direct industry rivals.","distractor_reasons":{"A":"Incorrect because personal biographical dates are irrelevant to financial analysis.","B":"Incorrect because comparing businesses across completely different industries is invalid.","C":"Incorrect because physical building features are not financial ratio benchmarks.","D":"Option D is correct because ratios become meaningful when tracked across consecutive years for the same firm or benchmarked against direct industry rivals."}}},{"id":"P1_U5_MCQ_477","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_477","question":"A book retailer reports annual revenue of $480,000, cost of sales of $264,000, and overhead expenses of $144,000. What is the retailer's gross profit margin?","options":{"A":"45%","B":"15%","C":"55%","D":"30%"},"correctOption":"A","correctAnswer":"45%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = $480,000 - $264,000 = $216,000, and Gross profit margin = ($216,000 / $480,000) × 100 = 45%.","distractor_reasons":{"A":"Option A is correct because Gross profit = $480,000 - $264,000 = $216,000, and Gross profit margin = ($216,000 / $480,000) × 100 = 45%.","B":"Incorrect because 15% is the profit margin ($72,000 / $480,000 × 100).","C":"Incorrect because 55% is cost of sales as a percentage of revenue ($264,000 / $480,000 × 100).","D":"Incorrect because 30% is overhead expenses as a percentage of revenue ($144,000 / $480,000 × 100)."}}},{"id":"P1_U5_MCQ_478","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_478","question":"A kitchenware store achieves a gross profit margin of 35% on annual sales revenue of $600,000. What was the store's cost of sales for the year?","options":{"A":"$810,000","B":"$210,000","C":"$390,000","D":"$350,000"},"correctOption":"C","correctAnswer":"$390,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = 35% × $600,000 = $210,000, so Cost of sales = Revenue - Gross profit ($600,000 - $210,000 = $390,000).","distractor_reasons":{"A":"Incorrect because $810,000 adds gross profit to revenue instead of subtracting it.","B":"Incorrect because $210,000 is the gross profit, not the cost of sales.","C":"Option C is correct because Gross profit = 35% × $600,000 = $210,000, so Cost of sales = Revenue - Gross profit ($600,000 - $210,000 = $390,000).","D":"Incorrect because 35% of $600,000 is $210,000, leaving $390,000 rather than $350,000."}}},{"id":"P1_U5_MCQ_479","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_479","question":"Over the last year, a bakery's gross profit margin fell from 52% to 44%. Which event most likely caused this decline?","options":{"A":"The bakery's head-office accounting fees doubled","B":"Wholesale flour and butter prices jumped sharply, and the bakery held promotional 'buy-one-get-one-free' discounts on bread","C":"The bakery took out a new 5-year bank loan","D":"The bakery sold an old delivery van for cash"},"correctOption":"B","correctAnswer":"Wholesale flour and butter prices jumped sharply, and the bakery held promotional 'buy-one-get-one-free' discounts on bread","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher ingredient costs (raising cost of sales) and promotional price cuts (lowering revenue per unit) directly compress gross profit margin.","distractor_reasons":{"A":"Incorrect because accounting fees are indirect overheads that reduce profit margin, not gross profit margin.","B":"Option B is correct because higher ingredient costs (raising cost of sales) and promotional price cuts (lowering revenue per unit) directly compress gross profit margin.","C":"Incorrect because taking a bank loan does not affect gross profit margin.","D":"Incorrect because selling a non-current asset does not affect gross profit margin."}}},{"id":"P1_U5_MCQ_480","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_480","question":"A travel agency generates annual revenue of $850,000, gross profit of $340,000, and final profit of $102,000. What is the agency's profit margin?","options":{"A":"30%","B":"40%","C":"12%","D":"28%"},"correctOption":"C","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Profit margin = (Profit / Revenue) × 100 = ($102,000 / $850,000) × 100 = 12%.","distractor_reasons":{"A":"Incorrect because 30% divides profit by gross profit ($102,000 / $340,000 × 100) instead of revenue.","B":"Incorrect because 40% is the gross profit margin ($340,000 / $850,000 × 100).","C":"Option C is correct because Profit margin = (Profit / Revenue) × 100 = ($102,000 / $850,000) × 100 = 12%.","D":"Incorrect because 28% subtracts profit margin from gross profit margin (40% - 12%)."}}},{"id":"P1_U5_MCQ_481","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_481","question":"A furniture retailer reports annual revenue of $900,000, a gross profit margin of 40%, and a profit margin of 14%. How much were the retailer's indirect overhead expenses for the year?","options":{"A":"$234,000","B":"$360,000","C":"$126,000","D":"$540,000"},"correctOption":"A","correctAnswer":"$234,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = 40% × $900,000 = $360,000 and Profit = 14% × $900,000 = $126,000, so Overhead expenses = $360,000 - $126,000 = $234,000.","distractor_reasons":{"A":"Option A is correct because Gross profit = 40% × $900,000 = $360,000 and Profit = 14% × $900,000 = $126,000, so Overhead expenses = $360,000 - $126,000 = $234,000.","B":"Incorrect because $360,000 is gross profit, not overhead expenses.","C":"Incorrect because $126,000 is final profit, not overhead expenses.","D":"Incorrect because $540,000 is cost of sales ($900,000 - $360,000)."}}},{"id":"P1_U5_MCQ_482","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_482","question":"Two rival courier firms have identical gross profit margins of 50%, yet Firm A has a profit margin of 22% while Firm B has a profit margin of only 9%. What does this comparison reveal?","options":{"A":"Firm B pays twice as much for direct fuel and driver wages as Firm A","B":"Firm B has much higher indirect overhead expenses (such as head-office admin, rent, or marketing) relative to its revenue than Firm A","C":"Firm A has a lower current ratio than Firm B","D":"Firm B earns higher total dollar profit than Firm A"},"correctOption":"B","correctAnswer":"Firm B has much higher indirect overhead expenses (such as head-office admin, rent, or marketing) relative to its revenue than Firm A","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the difference between gross profit margin and profit margin reflects indirect overhead expenses as a share of revenue.","distractor_reasons":{"A":"Incorrect because identical gross profit margins (50%) show that direct cost of sales as a percentage of revenue is the same for both firms.","B":"Option B is correct because the difference between gross profit margin and profit margin reflects indirect overhead expenses as a share of revenue.","C":"Incorrect because profit margins do not measure liquidity ratios.","D":"Incorrect because margins are percentages and do not prove higher total dollar profit."}}},{"id":"P1_U5_MCQ_483","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_483","question":"An engineering company earns an annual profit of $270,000. Its statement of financial position shows non-current assets of $1,350,000, current assets of $300,000, and current liabilities of $150,000. What is the company's Return on Capital Employed (ROCE)?","options":{"A":"18%","B":"20%","C":"16.4%","D":"15%"},"correctOption":"A","correctAnswer":"18%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Capital employed = Non-current assets + Current assets - Current liabilities ($1,350,000 + $300,000 - $150,000 = $1,500,000), and ROCE = ($270,000 / $1,500,000) × 100 = 18%.","distractor_reasons":{"A":"Option A is correct because Capital employed = Non-current assets + Current assets - Current liabilities ($1,350,000 + $300,000 - $150,000 = $1,500,000), and ROCE = ($270,000 / $1,500,000) × 100 = 18%.","B":"Incorrect because 20% divides profit only by non-current assets ($270,000 / $1,350,000 × 100), omitting working capital.","C":"Incorrect because 16.4% divides profit by total assets ($270,000 / $1,650,000 × 100) without subtracting current liabilities.","D":"Incorrect because 15% divides profit by $1,800,000 (adding current liabilities instead of subtracting them)."}}},{"id":"P1_U5_MCQ_484","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_484","question":"A retail chain achieves an ROCE of 4.5%, while risk-free commercial bank savings accounts pay 5.5% interest and bank business loans cost 8% interest. How will shareholders interpret this 4.5% ROCE?","options":{"A":"Poor performance: the business is generating a lower return than risk-free bank interest and less than the cost of borrowing capital","B":"Outstanding performance because any positive ROCE above 1% is considered high","C":"Proof that the retail chain has a current ratio above 3 : 1","D":"Proof that the retail chain pays zero corporation tax"},"correctOption":"A","correctAnswer":"Poor performance: the business is generating a lower return than risk-free bank interest and less than the cost of borrowing capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because investors benchmark ROCE against safe deposit interest rates and borrowing costs; earning less than a bank deposit signals inefficient capital use.","distractor_reasons":{"A":"Option A is correct because investors benchmark ROCE against safe deposit interest rates and borrowing costs; earning less than a bank deposit signals inefficient capital use.","B":"Incorrect because investors take business risks expecting returns well above safe bank interest rates.","C":"Incorrect because ROCE measures profitability, not liquidity.","D":"Incorrect because ROCE does not measure tax exemptions."}}},{"id":"P1_U5_MCQ_485","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_485","question":"A logistics company wants to increase its Return on Capital Employed (ROCE) without raising delivery prices. Which action would directly raise its ROCE?","options":{"A":"Issuing $500,000 of new shares without investing the money in profitable projects","B":"Borrowing $1 million in new long-term loans to hold as idle cash in a zero-interest account","C":"Increasing head-office administrative salaries by 20%","D":"Selling off idle, underused warehouse land and using the cash to repay long-term bank loans while maintaining existing profits"},"correctOption":"D","correctAnswer":"Selling off idle, underused warehouse land and using the cash to repay long-term bank loans while maintaining existing profits","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because reducing capital employed (repaying non-current debt via unused asset sales) while keeping profit steady increases the ratio Profit / Capital employed.","distractor_reasons":{"A":"Incorrect because raising share capital increases capital employed and lowers ROCE if profit stays flat.","B":"Incorrect because increasing capital employed without generating extra profit lowers ROCE.","C":"Incorrect because higher admin salaries reduce profit and lower ROCE.","D":"Option D is correct because reducing capital employed (repaying non-current debt via unused asset sales) while keeping profit steady increases the ratio Profit / Capital employed."}}},{"id":"P1_U5_MCQ_486","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_486","question":"A hardware distributor has inventory of $85,000, trade receivables of $55,000, cash of $20,000, trade payables of $60,000, and a bank overdraft of $20,000. What is the distributor's current ratio?","options":{"A":"2.0 : 1","B":"0.94 : 1","C":"0.5 : 1","D":"2.67 : 1"},"correctOption":"A","correctAnswer":"2.0 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Current assets = $85,000 + $55,000 + $20,000 = $160,000 and Current liabilities = $60,000 + $20,000 = $80,000, giving Current ratio = $160,000 / $80,000 = 2.0 : 1.","distractor_reasons":{"A":"Option A is correct because Current assets = $85,000 + $55,000 + $20,000 = $160,000 and Current liabilities = $60,000 + $20,000 = $80,000, giving Current ratio = $160,000 / $80,000 = 2.0 : 1.","B":"Incorrect because 0.94 : 1 is the acid-test ratio (($160,000 - $85,000) / $80,000).","C":"Incorrect because 0.5 : 1 inverts the ratio ($80,000 / $160,000).","D":"Incorrect because 2.67 : 1 omits the $20,000 bank overdraft from current liabilities ($160,000 / $60,000)."}}},{"id":"P1_U5_MCQ_487","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_487","question":"A furniture wholesaler has a current ratio of 4.8 : 1, far above the typical industry benchmark of 1.5 : 1 to 2.0 : 1. Why might financial analysts criticize such a high current ratio?","options":{"A":"It suggests funds are tied up unproductively in excessive unsold inventory, slow-paying receivables, or idle low-interest cash rather than being invested for growth","B":"It means the wholesaler is about to run out of cash next week","C":"It proves the wholesaler has too many non-current liabilities","D":"It indicates that gross profit margin is negative"},"correctOption":"A","correctAnswer":"It suggests funds are tied up unproductively in excessive unsold inventory, slow-paying receivables, or idle low-interest cash rather than being invested for growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an excessively high current ratio indicates inefficient working capital management and lost opportunity to earn higher returns.","distractor_reasons":{"A":"Option A is correct because an excessively high current ratio indicates inefficient working capital management and lost opportunity to earn higher returns.","B":"Incorrect because a high current ratio indicates abundant current assets, not an immediate cash shortage.","C":"Incorrect because non-current liabilities are not part of the current ratio.","D":"Incorrect because the current ratio does not measure gross profit margin."}}},{"id":"P1_U5_MCQ_488","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_488","question":"A construction supplier's current ratio is 0.85 : 1. What does this ratio specifically tell the supplier's managers?","options":{"A":"The business has only $0.85 of current assets for every $1.00 of short-term liabilities, indicating a high risk of being unable to pay bills on time","B":"The business earns $0.85 of profit on every $1.00 of sales revenue","C":"The business holds $85,000 in physical cash","D":"The business has zero inventory in its warehouse"},"correctOption":"A","correctAnswer":"The business has only $0.85 of current assets for every $1.00 of short-term liabilities, indicating a high risk of being unable to pay bills on time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a current ratio below 1 : 1 means current liabilities exceed current assets (negative working capital), creating serious liquidity danger.","distractor_reasons":{"A":"Option A is correct because a current ratio below 1 : 1 means current liabilities exceed current assets (negative working capital), creating serious liquidity danger.","B":"Incorrect because profit per dollar of sales is measured by profit margin, not current ratio.","C":"Incorrect because a ratio shows a relative proportion, not a specific dollar balance.","D":"Incorrect because current assets include inventory, receivables, and cash."}}},{"id":"P1_U5_MCQ_489","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_489","question":"A toy distributor has current assets of $240,000 (including $135,000 of inventory) and current liabilities of $70,000. What is the distributor's acid-test ratio?","options":{"A":"1.5 : 1","B":"3.43 : 1","C":"1.93 : 1","D":"0.67 : 1"},"correctOption":"A","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($240,000 - $135,000) / $70,000 = $105,000 / $70,000 = 1.5 : 1.","distractor_reasons":{"A":"Option A is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($240,000 - $135,000) / $70,000 = $105,000 / $70,000 = 1.5 : 1.","B":"Incorrect because 3.43 : 1 is the current ratio ($240,000 / $70,000) without subtracting inventory.","C":"Incorrect because 1.93 : 1 divides inventory by current liabilities ($135,000 / $70,000).","D":"Incorrect because 0.67 : 1 inverts the acid-test formula ($70,000 / $105,000)."}}},{"id":"P1_U5_MCQ_490","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_490","question":"Firm X and Firm Y both have a current ratio of 2.0 : 1. However, Firm X has an acid-test ratio of 1.6 : 1 while Firm Y has an acid-test ratio of 0.5 : 1. Which firm is in a stronger short-term liquidity position?","options":{"A":"Firm Y, because a lower acid-test ratio means higher profit margins","B":"Firm Y, because holding large amounts of unsold inventory guarantees instant cash","C":"Both firms have identical liquidity because their current ratios are both 2.0 : 1","D":"Firm X, because most of its current assets are already in liquid cash and receivables, whereas Firm Y relies heavily on selling inventory to pay short-term debts"},"correctOption":"D","correctAnswer":"Firm X, because most of its current assets are already in liquid cash and receivables, whereas Firm Y relies heavily on selling inventory to pay short-term debts","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the acid-test ratio excludes inventory (the least liquid current asset), showing that Firm X can easily pay immediate bills without needing emergency stock clearances.","distractor_reasons":{"A":"Incorrect because liquidity ratios do not measure profit margins.","B":"Incorrect because inventory can be slow or difficult to convert quickly into cash.","C":"Incorrect because two firms with equal current ratios can have very different liquidity depending on how much stock they hold.","D":"Option D is correct because the acid-test ratio excludes inventory (the least liquid current asset), showing that Firm X can easily pay immediate bills without needing emergency stock clearances."}}},{"id":"P1_U5_MCQ_491","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_491","question":"Why is the acid-test ratio considered a much more reliable liquidity test than the current ratio for a high-fashion clothing boutique or a fresh-seafood wholesaler?","options":{"A":"Because non-current assets are included in the acid-test ratio","B":"Because fashion boutiques and seafood wholesalers are not allowed to hold bank accounts","C":"Because current liabilities are excluded from the acid-test ratio","D":"Because fashion clothing can suddenly go out of style and fresh seafood can spoil, meaning inventory may not easily convert into cash at full value"},"correctOption":"D","correctAnswer":"Because fashion clothing can suddenly go out of style and fresh seafood can spoil, meaning inventory may not easily convert into cash at full value","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because perishable or trend-sensitive inventory carries high risk of obsolescence or spoilage, so excluding inventory tests whether truly liquid assets cover short-term debts.","distractor_reasons":{"A":"Incorrect because non-current assets are excluded from both liquidity ratios.","B":"Incorrect because both types of businesses hold standard bank accounts.","C":"Incorrect because current liabilities are the denominator in both ratios.","D":"Option D is correct because perishable or trend-sensitive inventory carries high risk of obsolescence or spoilage, so excluding inventory tests whether truly liquid assets cover short-term debts."}}},{"id":"P1_U5_MCQ_492","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_492","question":"A retail business currently has current assets of $100,000 and current liabilities of $50,000 (a current ratio of 2.0 : 1). If it uses $25,000 of its cash to pay off $25,000 of trade payables, what happens to its current ratio?","options":{"A":"It rises from 2.0 : 1 to 3.0 : 1 ($75,000 / $25,000)","B":"It stays unchanged at 2.0 : 1","C":"It falls from 2.0 : 1 to 1.5 : 1","D":"It falls to 0.5 : 1"},"correctOption":"A","correctAnswer":"It rises from 2.0 : 1 to 3.0 : 1 ($75,000 / $25,000)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because current assets fall to $75,000 ($100,000 - $25,000) and current liabilities fall to $25,000 ($50,000 - $25,000), raising the ratio to $75,000 / $25,000 = 3.0 : 1.","distractor_reasons":{"A":"Option A is correct because current assets fall to $75,000 ($100,000 - $25,000) and current liabilities fall to $25,000 ($50,000 - $25,000), raising the ratio to $75,000 / $25,000 = 3.0 : 1.","B":"Incorrect because subtracting equal amounts from numerator and denominator changes the ratio whenever the initial ratio is not 1 : 1.","C":"Incorrect because paying off debt when current assets exceed current liabilities increases rather than decreases the current ratio.","D":"Incorrect because $75,000 is three times $25,000, not half."}}},{"id":"P1_U5_MCQ_493","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_493","question":"A wholesaler has liquid assets of $40,000 cash and $60,000 trade receivables, against $80,000 of current liabilities (an acid-test ratio of 1.25 : 1). If credit customers pay $30,000 in cash, what happens to the acid-test ratio?","options":{"A":"It remains unchanged at 1.25 : 1 because cash rises by $30,000 while trade receivables fall by $30,000, leaving total liquid assets at $100,000","B":"It rises to 1.625 : 1","C":"It falls to 0.875 : 1","D":"It doubles to 2.5 : 1"},"correctOption":"A","correctAnswer":"It remains unchanged at 1.25 : 1 because cash rises by $30,000 while trade receivables fall by $30,000, leaving total liquid assets at $100,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because both cash and trade receivables are included in the acid-test numerator; shifting $30,000 from receivables to cash leaves $100,000 / $80,000 = 1.25 : 1.","distractor_reasons":{"A":"Option A is correct because both cash and trade receivables are included in the acid-test numerator; shifting $30,000 from receivables to cash leaves $100,000 / $80,000 = 1.25 : 1.","B":"Incorrect because $130,000 double-counts the $30,000 cash without reducing trade receivables.","C":"Incorrect because collecting receivables does not reduce total liquid assets.","D":"Incorrect because total liquid assets remain $100,000."}}},{"id":"P1_U5_MCQ_494","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_494","question":"Why do internal department managers calculate gross profit margin and profit margin every quarter?","options":{"A":"To spot rising direct costs or overhead overspending early and take corrective action before year-end accounts are finalized","B":"To calculate the exact market share price on the stock exchange","C":"To decide whether government tax authorities should audit rival firms","D":"To replace the need for quality control on the factory floor"},"correctOption":"A","correctAnswer":"To spot rising direct costs or overhead overspending early and take corrective action before year-end accounts are finalized","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal managers use regular ratio tracking as an early-warning diagnostic tool to control costs and protect margins.","distractor_reasons":{"A":"Option A is correct because internal managers use regular ratio tracking as an early-warning diagnostic tool to control costs and protect margins.","B":"Incorrect because share prices are determined by supply and demand on the stock exchange.","C":"Incorrect because tax audits are decided by government tax agencies.","D":"Incorrect because financial ratios complement rather than replace operational quality control."}}},{"id":"P1_U5_MCQ_495","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_495","question":"Which of the following would be of most interest to a bank considering whether to lend money to a business?","options":{"A":"Whether the business can meet its short-term obligations from its available assets","B":"The number of different products in the business's range","C":"The colours used in the company's logo","D":"The personal hobbies of the directors"},"correctOption":"A","correctAnswer":"Whether the business can meet its short-term obligations from its available assets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a lender needs to judge liquidity and the ability to repay debts as they fall due from available assets.","distractor_reasons":{"A":"Option A is correct because a lender needs to judge liquidity and the ability to repay debts as they fall due from available assets.","B":"Incorrect because the size of the product range does not directly show whether the business can repay a loan.","C":"Incorrect because branding colours are irrelevant to the creditworthiness of the borrower.","D":"Incorrect because the personal hobbies of directors have no bearing on the business's ability to service debt."}}},{"id":"P1_U5_MCQ_496","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_496","question":"Why do both commercial banks and trade suppliers focus heavily on liquidity ratios (current ratio and acid-test ratio) when analyzing a business's accounts?","options":{"A":"Because creditors need assurance that the business holds enough liquid assets to pay invoices and loan interest on time without defaulting","B":"Because banks and suppliers receive a percentage of the business's gross profit instead of cash payments","C":"Because liquidity ratios measure employee motivation and product quality","D":"Because liquidity ratios tell creditors how much corporation tax the government owes"},"correctOption":"A","correctAnswer":"Because creditors need assurance that the business holds enough liquid assets to pay invoices and loan interest on time without defaulting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external lenders and trade creditors face direct financial loss if a customer lacks short-term liquidity to pay debts as they fall due.","distractor_reasons":{"A":"Option A is correct because external lenders and trade creditors face direct financial loss if a customer lacks short-term liquidity to pay debts as they fall due.","B":"Incorrect because banks and suppliers require contractual cash repayments, not profit shares.","C":"Incorrect because liquidity ratios measure short-term financial solvency, not qualitative factors.","D":"Incorrect because businesses pay tax to governments, not the reverse."}}},{"id":"P1_U5_MCQ_497","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_497","question":"How do government tax authorities and trade unions differ in their reasons for analyzing a large corporation's financial accounts?","options":{"A":"Tax authorities negotiate employee wage rises, whereas trade unions collect corporation tax","B":"Tax authorities verify profit figures to collect accurate corporation tax, whereas trade unions check profitability and liquidity to assess job security and negotiate pay rises","C":"Tax authorities approve bank overdrafts, whereas trade unions set retail product prices","D":"Neither group is legally permitted to view published public limited company accounts"},"correctOption":"B","correctAnswer":"Tax authorities verify profit figures to collect accurate corporation tax, whereas trade unions check profitability and liquidity to assess job security and negotiate pay rises","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because different external stakeholders analyze the same published statements for distinct purposes—tax compliance for government versus pay and employment security for unions.","distractor_reasons":{"A":"Incorrect because this reverses the roles of tax authorities and trade unions.","B":"Option B is correct because different external stakeholders analyze the same published statements for distinct purposes—tax compliance for government versus pay and employment security for unions.","C":"Incorrect because banks approve overdrafts and company managers set retail prices.","D":"Incorrect because public limited companies must publish their annual accounts publicly."}}},{"id":"P1_U5_MCQ_498","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_498","question":"Over a five-year period of high inflation, a supermarket's sales revenue rose by 35%, making its financial growth look impressive at first glance. Why is inflation a limitation when comparing accounts across several years?","options":{"A":"Inflation automatically doubles a company's acid-test ratio every year","B":"Higher revenue and asset figures may simply reflect rising general price levels rather than genuine growth in sales volume or real efficiency","C":"Accountants are legally required to divide all figures by ten during inflation","D":"Inflation eliminates all overhead expenses on the statement of profit or loss"},"correctOption":"B","correctAnswer":"Higher revenue and asset figures may simply reflect rising general price levels rather than genuine growth in sales volume or real efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inflation inflates nominal monetary figures over time, making historical comparisons misleading unless price increases are accounted for.","distractor_reasons":{"A":"Incorrect because inflation does not automatically double liquidity ratios.","B":"Option B is correct because inflation inflates nominal monetary figures over time, making historical comparisons misleading unless price increases are accounted for.","C":"Incorrect because no such accounting rule exists.","D":"Incorrect because inflation actually raises overhead expenses such as wages, rent, and energy."}}},{"id":"P1_U5_MCQ_499","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_499","question":"Two competing car-rental companies use different accounting policies for valuing their vehicle fleets and calculating depreciation. How does this limit inter-firm ratio comparisons?","options":{"A":"Different accounting policies only affect sole traders, never limited companies","B":"Companies using different accounting policies are banned from calculating ROCE","C":"Depreciation policies change a company's daily bank cash balance","D":"Differences in profit and capital employed figures may reflect different accounting methods rather than true differences in operational performance"},"correctOption":"D","correctAnswer":"Differences in profit and capital employed figures may reflect different accounting methods rather than true differences in operational performance","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because variations in asset valuation, inventory valuation, or depreciation methods alter reported profits and asset totals, distorting ratio comparisons between firms.","distractor_reasons":{"A":"Incorrect because limited companies also exercise judgment within accounting standards.","B":"Incorrect because any company can calculate ROCE, though analysts must interpret differences carefully.","C":"Incorrect because depreciation is a non-cash accounting charge that does not alter cash in the bank.","D":"Option D is correct because variations in asset valuation, inventory valuation, or depreciation methods alter reported profits and asset totals, distorting ratio comparisons between firms."}}},{"id":"P1_U5_MCQ_500","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_500","question":"An analyst calculates that a retailer's profit margin fell from 14% to 8%, its current ratio dropped from 1.9 : 1 to 1.1 : 1, and its ROCE fell from 18% to 10%. What is a fundamental limitation of ratio analysis when deciding how to fix the business?","options":{"A":"Ratios highlight financial symptoms (such as falling margins or weaker liquidity), but they do not explain the underlying operational causes or qualitative issues like poor customer service or rising competition","B":"Ratios can only be calculated if a business has zero liabilities","C":"Ratios guarantee that next year's profit margin will return to 14%","D":"Ratios are illegal to use for internal management decision-making"},"correctOption":"A","correctAnswer":"Ratios highlight financial symptoms (such as falling margins or weaker liquidity), but they do not explain the underlying operational causes or qualitative issues like poor customer service or rising competition","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ratios diagnose where performance has weakened, but managers must investigate market conditions, product quality, and staff motivation to uncover root causes.","distractor_reasons":{"A":"Option A is correct because ratios diagnose where performance has weakened, but managers must investigate market conditions, product quality, and staff motivation to uncover root causes.","B":"Incorrect because liquidity ratios specifically require current liabilities in the denominator.","C":"Incorrect because ratios analyze past data and cannot guarantee future recovery.","D":"Incorrect because internal ratio analysis is a core management tool."}}},{"id":"P1_U5_MCQ_501","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_501","question":"What is meant by the term 'start-up capital'?","options":{"A":"The finance needed by an entrepreneur to pay for essential non-current assets and initial inventories before trading begins","B":"The profit kept inside an established company after corporation tax and dividends have been paid","C":"The short-term money owed to a business by customers who have bought goods on credit","D":"The annual interest paid to commercial banks on long-term commercial mortgages"},"correctOption":"A","correctAnswer":"The finance needed by an entrepreneur to pay for essential non-current assets and initial inventories before trading begins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because start-up capital is the initial finance required to set up a new business, purchase essential premises or equipment, and acquire opening stock before revenue flows in.","distractor_reasons":{"A":"Option A is correct because start-up capital is the initial finance required to set up a new business, purchase essential premises or equipment, and acquire opening stock before revenue flows in.","B":"Incorrect because profit kept inside an established business is retained profit, which a new start-up does not yet have.","C":"Incorrect because amounts owed by credit customers are trade receivables.","D":"Incorrect because interest paid on loans is a finance expense, not start-up capital."}}},{"id":"P1_U5_MCQ_502","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_502","question":"Why does a trading business require 'working capital'?","options":{"A":"To purchase freehold land and construct new manufacturing factories","B":"To pay for day-to-day running costs such as wages, raw materials, and utility bills","C":"To distribute annual cash dividends to ordinary shareholders","D":"To pay off 25-year debentures upon maturity"},"correctOption":"B","correctAnswer":"To pay for day-to-day running costs such as wages, raw materials, and utility bills","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because working capital is the finance needed for everyday operational expenses and to bridge the time gap between paying suppliers and receiving cash from customers.","distractor_reasons":{"A":"Incorrect because buying freehold land and factories is long-term capital expenditure.","B":"Option B is correct because working capital is the finance needed for everyday operational expenses and to bridge the time gap between paying suppliers and receiving cash from customers.","C":"Incorrect because dividends are distributed out of after-tax profits rather than being the purpose of working capital.","D":"Incorrect because repaying 25-year debentures is a long-term financing obligation."}}},{"id":"P1_U5_MCQ_503","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_503","question":"Which of the following is the best definition of 'capital expenditure'?","options":{"A":"Money spent on day-to-day running expenses such as electricity, stationery, and fuel","B":"Money spent on purchasing raw materials that will be turned into finished goods within a week","C":"Money spent on acquiring or upgrading non-current assets that will be used in the business for more than one year","D":"Money repaid to suppliers to settle 30-day trade credit invoices"},"correctOption":"C","correctAnswer":"Money spent on acquiring or upgrading non-current assets that will be used in the business for more than one year","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital expenditure involves spending on long-term physical or intangible assets (such as machinery, vehicles, or buildings) that last more than 12 months.","distractor_reasons":{"A":"Incorrect because spending on day-to-day running expenses is revenue expenditure.","B":"Incorrect because spending on short-term raw materials is revenue expenditure.","C":"Option C is correct because capital expenditure involves spending on long-term physical or intangible assets (such as machinery, vehicles, or buildings) that last more than 12 months.","D":"Incorrect because settling short-term supplier invoices is a working capital cash outflow, not capital expenditure."}}},{"id":"P1_U5_MCQ_504","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_504","question":"Which of the following is classified as 'revenue expenditure'?","options":{"A":"Buying a new fleet of refrigerated delivery trucks","B":"Purchasing an adjoining plot of land to build a warehouse","C":"Installing a permanent automated assembly line in a factory","D":"Paying monthly rent, staff wages, and routine equipment repairs"},"correctOption":"D","correctAnswer":"Paying monthly rent, staff wages, and routine equipment repairs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because revenue expenditure refers to spending on day-to-day operational items that are consumed within the current accounting year.","distractor_reasons":{"A":"Incorrect because delivery trucks are long-term non-current assets (capital expenditure).","B":"Incorrect because purchasing land is long-term capital expenditure.","C":"Incorrect because installing a permanent assembly line is capital expenditure.","D":"Option D is correct because revenue expenditure refers to spending on day-to-day operational items that are consumed within the current accounting year."}}},{"id":"P1_U5_MCQ_505","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_505","question":"What is meant by 'internal sources of finance'?","options":{"A":"Funds raised by issuing new ordinary shares to investors on a public stock exchange","B":"Funds borrowed from commercial banks using long-term mortgages or short-term overdrafts","C":"Funds obtained from within the business itself, such as retained profit, sale of existing assets, or reducing inventory levels","D":"Non-repayable funds awarded by government agencies to encourage regional job creation"},"correctOption":"C","correctAnswer":"Funds obtained from within the business itself, such as retained profit, sale of existing assets, or reducing inventory levels","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal finance is generated from the business's own resources without involving outside lenders or external investors.","distractor_reasons":{"A":"Incorrect because issuing shares to outside investors is an external source of finance.","B":"Incorrect because bank loans and overdrafts are external sources of finance.","C":"Option C is correct because internal finance is generated from the business's own resources without involving outside lenders or external investors.","D":"Incorrect because government grants come from an outside agency and are external finance."}}},{"id":"P1_U5_MCQ_506","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_506","question":"Which list contains ONLY 'external sources of finance'?","options":{"A":"Retained profit, owners' savings, and sale of surplus machinery","B":"Bank loans, issue of shares, debentures, and trade credit","C":"Reducing inventory levels, retained profit, and crowdfunding","D":"Sale of existing assets, bank overdraft, and debt factoring"},"correctOption":"B","correctAnswer":"Bank loans, issue of shares, debentures, and trade credit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because bank loans, share issues, debentures, and trade credit all bring funds or credit into the business from outside parties.","distractor_reasons":{"A":"Incorrect because retained profit, owners' savings, and asset sales are all internal sources.","B":"Option B is correct because bank loans, share issues, debentures, and trade credit all bring funds or credit into the business from outside parties.","C":"Incorrect because reducing inventory levels and retained profit are internal sources.","D":"Incorrect because the sale of existing assets is an internal source of finance."}}},{"id":"P1_U5_MCQ_507","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_507","question":"What is a major limitation of relying on 'retained profit' as a source of finance?","options":{"A":"It must be repaid to commercial banks with high compound interest within one year","B":"It dilutes the voting control of existing ordinary shareholders","C":"It is unavailable to newly formed businesses and may be too small if past profits were low","D":"It requires offering freehold property as collateral to external lenders"},"correctOption":"C","correctAnswer":"It is unavailable to newly formed businesses and may be too small if past profits were low","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because new start-ups have no trading history to accumulate retained profit, and low-margin firms may not retain enough profit to fund major projects.","distractor_reasons":{"A":"Incorrect because retained profit is internal equity and incurs no interest or repayment obligation.","B":"Incorrect because retaining profit keeps ownership intact without issuing new voting shares.","C":"Option C is correct because new start-ups have no trading history to accumulate retained profit, and low-margin firms may not retain enough profit to fund major projects.","D":"Incorrect because collateral is required for secured external loans, not internal retained profit."}}},{"id":"P1_U5_MCQ_508","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_508","question":"What is a key disadvantage of raising internal finance through the 'sale of existing assets'?","options":{"A":"The business must pay annual dividends to the buyer of the assets","B":"The funds raised must be repaid within 30 days","C":"The business immediately loses its status as a limited company","D":"It can take a long time to find a buyer, and the assets may sell for less than their true value"},"correctOption":"D","correctAnswer":"It can take a long time to find a buyer, and the assets may sell for less than their true value","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because non-current assets such as property or specialized machinery are illiquid, slow to sell, and no longer available for future production once sold.","distractor_reasons":{"A":"Incorrect because asset buyers purchase physical items rather than shares.","B":"Incorrect because outright asset sales generate permanent cash with no repayment.","C":"Incorrect because selling surplus assets does not alter a company's legal structure.","D":"Option D is correct because non-current assets such as property or specialized machinery are illiquid, slow to sell, and no longer available for future production once sold."}}},{"id":"P1_U5_MCQ_509","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_509","question":"A new gym must buy exercise equipment and install changing rooms before it can open its doors to members. Which category of finance does this describe?","options":{"A":"Start-up capital for non-current assets","B":"Working capital for day-to-day operations","C":"Short-term trade credit from suppliers","D":"Revenue from future sales"},"correctOption":"A","correctAnswer":"Start-up capital for non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because start-up capital is needed to buy the fixed assets and set up the premises before a business begins trading.","distractor_reasons":{"A":"Option A is correct because start-up capital is needed to buy the fixed assets and set up the premises before a business begins trading.","B":"Incorrect because working capital funds day-to-day items such as wages and stock, not the purchase of long-term equipment.","C":"Incorrect because trade credit is a short-term arrangement for buying goods and paying later, not finance for fitting-out a gym.","D":"Incorrect because sales revenue has not yet been earned; the gym needs finance before it can open."}}},{"id":"P1_U5_MCQ_510","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_510","question":"Why is 'owners' savings' a particularly common source of finance for sole traders and partnerships?","options":{"A":"It legally grants unincorporated owners limited liability for business debts","B":"It is quickly available without complex bank loan applications and incurs no interest charges","C":"It provides unlimited amounts of capital for multinational expansion","D":"It is guaranteed by the government against any trading losses"},"correctOption":"B","correctAnswer":"It is quickly available without complex bank loan applications and incurs no interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sole traders and partnerships cannot issue shares and often struggle to obtain bank loans without a track record, making personal savings fast and interest-free.","distractor_reasons":{"A":"Incorrect because sole traders and ordinary partners retain unlimited liability regardless of how they fund the business.","B":"Option B is correct because sole traders and partnerships cannot issue shares and often struggle to obtain bank loans without a track record, making personal savings fast and interest-free.","C":"Incorrect because personal savings are usually limited in size.","D":"Incorrect because owners bear the full risk of losing their personal savings if the business fails."}}},{"id":"P1_U5_MCQ_511","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_511","question":"Which statement accurately describes 'issue of shares' as a source of finance?","options":{"A":"It is available to sole traders and partnerships to raise short-term working capital","B":"It is a short-term loan that must be repaid to shareholders within 12 months","C":"It is available only to limited companies and provides permanent capital that does not have to be repaid","D":"It guarantees fixed annual interest payments to investors even when the company makes a loss"},"correctOption":"C","correctAnswer":"It is available only to limited companies and provides permanent capital that does not have to be repaid","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because only incorporated limited companies (Ltd and plc) can issue shares, and ordinary share capital is permanent finance with no repayment date.","distractor_reasons":{"A":"Incorrect because unincorporated businesses (sole traders and partnerships) cannot issue shares.","B":"Incorrect because share capital is permanent long-term equity, not a short-term loan.","C":"Option C is correct because only incorporated limited companies (Ltd and plc) can issue shares, and ordinary share capital is permanent finance with no repayment date.","D":"Incorrect because ordinary shareholders receive variable dividends only if profits allow, unlike fixed loan interest."}}},{"id":"P1_U5_MCQ_512","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_512","question":"What is a major disadvantage to existing owners of raising finance by issuing new ordinary shares to outside investors?","options":{"A":"The company must provide physical property as collateral to the new shareholders","B":"The company's interest expenses immediately double","C":"The new shares must be bought back by the company within five years","D":"Existing owners' percentage ownership and voting control are diluted, and future profits must be shared among more shareholders"},"correctOption":"D","correctAnswer":"Existing owners' percentage ownership and voting control are diluted, and future profits must be shared among more shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because issuing additional voting shares reduces the proportion of control held by original shareholders and spreads future dividend payouts.","distractor_reasons":{"A":"Incorrect because equity investors share business risk rather than taking collateral.","B":"Incorrect because shares carry dividends rather than interest expenses.","C":"Incorrect because ordinary shares have no maturity or mandatory buy-back date.","D":"Option D is correct because issuing additional voting shares reduces the proportion of control held by original shareholders and spreads future dividend payouts."}}},{"id":"P1_U5_MCQ_513","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_513","question":"Which characteristic applies to a 'bank loan' as a source of business finance?","options":{"A":"It provides a lump sum repaid in regular instalments with interest over an agreed period, and does not dilute ownership control","B":"It gives the lending bank voting rights at the company's Annual General Meeting","C":"It is an internal source of finance that requires no formal application","D":"It never requires collateral or security regardless of the amount borrowed"},"correctOption":"A","correctAnswer":"It provides a lump sum repaid in regular instalments with interest over an agreed period, and does not dilute ownership control","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a bank loan delivers an agreed sum upfront, is repaid with interest over a fixed term, and leaves full ownership with the business owners.","distractor_reasons":{"A":"Option A is correct because a bank loan delivers an agreed sum upfront, is repaid with interest over a fixed term, and leaves full ownership with the business owners.","B":"Incorrect because banks are external creditors, not voting shareholders.","C":"Incorrect because bank loans are external finance requiring financial forecasts and approval.","D":"Incorrect because banks frequently demand security/collateral for medium- and long-term loans."}}},{"id":"P1_U5_MCQ_514","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_514","question":"What are 'debentures'?","options":{"A":"Short-term supplier invoices that must be paid within 30 days","B":"Long-term loan certificates issued by limited companies that pay fixed interest and must be repaid at a set maturity date","C":"Non-repayable government subsidies awarded for exporting goods","D":"Voting equity shares sold to the general public on a stock exchange"},"correctOption":"B","correctAnswer":"Long-term loan certificates issued by limited companies that pay fixed interest and must be repaid at a set maturity date","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because debentures are long-term debt instruments issued by companies; debenture holders are creditors earning fixed interest rather than voting owners.","distractor_reasons":{"A":"Incorrect because 30-day supplier invoices are trade credit.","B":"Option B is correct because debentures are long-term debt instruments issued by companies; debenture holders are creditors earning fixed interest rather than voting owners.","C":"Incorrect because non-repayable government funds are grants.","D":"Incorrect because voting equity instruments are ordinary shares, whereas debentures carry no voting rights."}}},{"id":"P1_U5_MCQ_515","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_515","question":"How does 'debt factoring' work as a short-term source of finance?","options":{"A":"A business borrows money from a bank by mortgaging its freehold factory","B":"A business delays paying its own suppliers for up to 90 days","C":"A specialist financial firm buys a business's unpaid customer invoices at a discount in exchange for immediate cash","D":"A business raises small donations from thousands of online supporters"},"correctOption":"C","correctAnswer":"A specialist financial firm buys a business's unpaid customer invoices at a discount in exchange for immediate cash","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because debt factoring converts trade receivables into immediate liquidity by selling the invoices to a factor, which collects the full debt from customers.","distractor_reasons":{"A":"Incorrect because borrowing against property is a commercial mortgage.","B":"Incorrect because delaying supplier payments is trade credit.","C":"Option C is correct because debt factoring converts trade receivables into immediate liquidity by selling the invoices to a factor, which collects the full debt from customers.","D":"Incorrect because raising small sums online from the public is crowdfunding."}}},{"id":"P1_U5_MCQ_516","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_516","question":"What is a potential disadvantage of using 'debt factoring'?","options":{"A":"The business must wait an extra six months before receiving any cash","B":"The factoring company becomes the majority owner of the business","C":"The business's non-current liabilities increase substantially","D":"The business receives less than the full face value of its invoices, and aggressive collection by the factor may harm customer relationships"},"correctOption":"D","correctAnswer":"The business receives less than the full face value of its invoices, and aggressive collection by the factor may harm customer relationships","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the factor deducts a service fee/discount (reducing the business's profit) and takes over chasing customers for payment.","distractor_reasons":{"A":"Incorrect because debt factoring provides immediate cash upfront.","B":"Incorrect because debt factoring is a commercial fee service, not an equity purchase.","C":"Incorrect because factoring converts an existing current asset (receivables) into cash without adding long-term debt.","D":"Option D is correct because the factor deducts a service fee/discount (reducing the business's profit) and takes over chasing customers for payment."}}},{"id":"P1_U5_MCQ_517","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_517","question":"What is a defining feature of 'grants and subsidies from outside agencies'?","options":{"A":"They do not have to be repaid, provided the business meets specific conditions such as creating jobs or locating in a target region","B":"They carry higher interest rates than commercial bank overdrafts","C":"They are automatically granted to every profitable business upon request","D":"They require the recipient business to list its shares on a stock exchange"},"correctOption":"A","correctAnswer":"They do not have to be repaid, provided the business meets specific conditions such as creating jobs or locating in a target region","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because grants are non-repayable funds offered by governments or development agencies to achieve specific economic or social policy objectives.","distractor_reasons":{"A":"Option A is correct because grants are non-repayable funds offered by governments or development agencies to achieve specific economic or social policy objectives.","B":"Incorrect because grants do not require repayment or interest unless conditions are breached.","C":"Incorrect because grants are selective, competitive, and subject to strict eligibility criteria.","D":"Incorrect because small private businesses can receive grants without becoming public limited companies."}}},{"id":"P1_U5_MCQ_518","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_518","question":"What is 'microfinance'?","options":{"A":"The issue of multi-million-dollar corporate bonds by multinational corporations","B":"The provision of very small loans and basic financial services to low-income entrepreneurs who lack access to traditional commercial banks","C":"The practice of selling unpaid corporate invoices to international investment banks","D":"Internal retained profit accumulated by small retail shops"},"correctOption":"B","correctAnswer":"The provision of very small loans and basic financial services to low-income entrepreneurs who lack access to traditional commercial banks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because microfinance institutions provide small-scale credit (often without traditional collateral) to help low-income individuals start or expand micro-enterprises.","distractor_reasons":{"A":"Incorrect because multi-million-dollar corporate bonds are large capital-market instruments.","B":"Option B is correct because microfinance institutions provide small-scale credit (often without traditional collateral) to help low-income individuals start or expand micro-enterprises.","C":"Incorrect because selling unpaid invoices is debt factoring.","D":"Incorrect because microfinance is an external lending service, not internal retained profit."}}},{"id":"P1_U5_MCQ_519","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_519","question":"How does 'crowdfunding' operate, and what is a key secondary benefit for an entrepreneur?","options":{"A":"It borrows funds from a single central bank and eliminates all production costs","B":"It sells company assets to competitors and guarantees monopoly power","C":"It raises small sums of money from a large number of people via online platforms, while also testing market demand and building early customer awareness","D":"It provides interest-free overdrafts from commercial banks without any public disclosure"},"correctOption":"C","correctAnswer":"It raises small sums of money from a large number of people via online platforms, while also testing market demand and building early customer awareness","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because crowdfunding pools small pledges from the public online and serves as valuable market validation and promotion before full launch.","distractor_reasons":{"A":"Incorrect because central banks do not lend directly to individual entrepreneurs via crowdfunding.","B":"Incorrect because crowdfunding raises funds from online backers rather than selling assets to rivals.","C":"Option C is correct because crowdfunding pools small pledges from the public online and serves as valuable market validation and promotion before full launch.","D":"Incorrect because crowdfunding is publicly visible on internet platforms, which actually carries the risk of idea imitation."}}},{"id":"P1_U5_MCQ_520","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_520","question":"Why is a 'bank overdraft' considered risky if used to finance long-term capital projects?","options":{"A":"Overdrafts require issuing voting shares to the bank","B":"Overdrafts have a fixed 20-year repayment schedule that cannot be changed","C":"Overdrafts can only be used to pay corporation tax","D":"The bank can demand full repayment at very short notice, and interest rates are usually high and variable"},"correctOption":"D","correctAnswer":"The bank can demand full repayment at very short notice, and interest rates are usually high and variable","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because overdrafts are flexible short-term facilities repayable on demand with high daily interest, making them dangerous for funding long-term investments.","distractor_reasons":{"A":"Incorrect because bank overdrafts are debt facilities and do not involve issuing shares.","B":"Incorrect because a fixed 20-year repayment schedule describes a mortgage or long-term loan, not an overdraft.","C":"Incorrect because overdrafts can cover any routine current account payments.","D":"Option D is correct because overdrafts are flexible short-term facilities repayable on demand with high daily interest, making them dangerous for funding long-term investments."}}},{"id":"P1_U5_MCQ_521","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_521","question":"What is 'trade credit' and what is a common hidden cost of using it?","options":{"A":"Leasing machinery from a finance firm; the business never owns the asset","B":"Borrowing cash from customers before delivering goods; the business must pay high bank arrangement fees","C":"Selling unpaid invoices to a factor; the business loses control over its bank account","D":"Delaying payment to suppliers for goods already received; the business may lose out on early-payment cash discounts"},"correctOption":"D","correctAnswer":"Delaying payment to suppliers for goods already received; the business may lose out on early-payment cash discounts","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade credit allows a buyer to purchase inventory now and pay later (e.g., in 30 or 60 days), though suppliers often offer prompt-payment discounts that are forfeited.","distractor_reasons":{"A":"Incorrect because renting equipment describes leasing.","B":"Incorrect because trade credit is granted by suppliers to buyers, not by customers.","C":"Incorrect because selling unpaid invoices describes debt factoring.","D":"Option D is correct because trade credit allows a buyer to purchase inventory now and pay later (e.g., in 30 or 60 days), though suppliers often offer prompt-payment discounts that are forfeited."}}},{"id":"P1_U5_MCQ_522","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_522","question":"How does 'leasing' differ from 'hire purchase' when acquiring a non-current asset?","options":{"A":"Leasing transfers immediate legal ownership on Day 1, whereas hire purchase never transfers ownership","B":"With leasing, legal ownership remains with the leasing company and maintenance is often included, whereas with hire purchase, ownership passes to the buyer once the final instalment is paid","C":"Leasing is an internal source of finance, whereas hire purchase is an external source","D":"Leasing requires paying the full purchase price upfront in cash, whereas hire purchase requires no payments"},"correctOption":"B","correctAnswer":"With leasing, legal ownership remains with the leasing company and maintenance is often included, whereas with hire purchase, ownership passes to the buyer once the final instalment is paid","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because leasing is a rental agreement where the lessor retains ownership and handles servicing, while hire purchase is an instalment purchase ending in ownership.","distractor_reasons":{"A":"Incorrect because this reverses the ownership rules of leasing and hire purchase.","B":"Option B is correct because leasing is a rental agreement where the lessor retains ownership and handles servicing, while hire purchase is an instalment purchase ending in ownership.","C":"Incorrect because both leasing and hire purchase are external asset-finance arrangements.","D":"Incorrect because neither option requires paying the full purchase price upfront in cash."}}},{"id":"P1_U5_MCQ_523","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_523","question":"What is a key advantage of 'hire purchase' for a business acquiring expensive equipment?","options":{"A":"It avoids paying any interest over the life of the agreement","B":"It is recorded as an internal reserve on the statement of financial position","C":"It avoids a large immediate cash outflow by spreading payments over time while leading to eventual ownership of the asset","D":"It allows the business to return the asset at any time without penalty"},"correctOption":"C","correctAnswer":"It avoids a large immediate cash outflow by spreading payments over time while leading to eventual ownership of the asset","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because hire purchase preserves working capital by paying in instalments while building toward full asset ownership.","distractor_reasons":{"A":"Incorrect because hire purchase includes interest charges, making total payments higher than the cash price.","B":"Incorrect because hire purchase is an external liability, not an internal equity reserve.","C":"Option C is correct because hire purchase preserves working capital by paying in instalments while building toward full asset ownership.","D":"Incorrect because hire purchase commits the buyer to the instalment contract."}}},{"id":"P1_U5_MCQ_524","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_524","question":"How do accountants distinguish between 'short-term finance' and 'long-term finance'?","options":{"A":"Short-term finance is used only by unincorporated businesses, while long-term finance is used only by limited companies","B":"Short-term finance is always interest-free, while long-term finance always carries variable interest","C":"Short-term finance is always internal, while long-term finance is always external","D":"Short-term finance is required for up to one year to fund working capital, while long-term finance is required for more than one year to fund non-current assets or expansion"},"correctOption":"D","correctAnswer":"Short-term finance is required for up to one year to fund working capital, while long-term finance is required for more than one year to fund non-current assets or expansion","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the standard financial dividing line is 12 months: under one year for short-term operational needs versus over one year for long-term capital investment.","distractor_reasons":{"A":"Incorrect because businesses of all legal forms use both short-term and long-term finance.","B":"Incorrect because short-term sources such as bank overdrafts charge interest.","C":"Incorrect because short-term finance includes external sources (e.g., overdrafts, trade credit) and long-term finance includes internal retained profit.","D":"Option D is correct because the standard financial dividing line is 12 months: under one year for short-term operational needs versus over one year for long-term capital investment."}}},{"id":"P1_U5_MCQ_525","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_525","question":"Which of the following is an internal source of finance for an established sole trader?","options":{"A":"An issue of shares","B":"A bank loan","C":"A bank overdraft","D":"Profits retained from earlier years"},"correctOption":"D","correctAnswer":"Profits retained from earlier years","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retained profit is generated inside the business and is therefore an internal source of finance.","distractor_reasons":{"A":"Incorrect because a sole trader cannot issue shares, and share issues are in any case external equity finance.","B":"Incorrect because a bank loan comes from an outside lender and is an external source of finance that must be repaid.","C":"Incorrect because a bank overdraft is also borrowing from an external financial institution, not internal finance.","D":"Option D is correct because retained profit is generated inside the business and is therefore an internal source of finance."}}},{"id":"P1_U5_MCQ_526","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_526","question":"What is meant by the term 'cash flow'?","options":{"A":"The total profit remaining after all operating expenses and taxes are deducted from revenue","B":"The movement of cash inflows into and cash outflows out of a business over a period of time","C":"The total value of non-current assets owned by a business on a specific date","D":"The total amount of share capital invested by ordinary shareholders"},"correctOption":"B","correctAnswer":"The movement of cash inflows into and cash outflows out of a business over a period of time","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cash flow tracks the actual receipts (inflows) and payments (outflows) moving through a business's bank and cash balances over time.","distractor_reasons":{"A":"Incorrect because total profit is calculated on the statement of profit or loss and differs from cash flow.","B":"Option B is correct because cash flow tracks the actual receipts (inflows) and payments (outflows) moving through a business's bank and cash balances over time.","C":"Incorrect because non-current asset values appear on the statement of financial position.","D":"Incorrect because share capital is owners' equity on the statement of financial position."}}},{"id":"P1_U5_MCQ_527","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_527","question":"Which of the following is an example of a 'cash inflow' for a business?","options":{"A":"Paying monthly wages to production workers","B":"Purchasing raw materials from suppliers for immediate cash","C":"Receiving payments from trade receivables (credit customers) who have settled their invoices","D":"Paying corporation tax to government tax authorities"},"correctOption":"C","correctAnswer":"Receiving payments from trade receivables (credit customers) who have settled their invoices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because collecting payments owed by credit customers brings actual money into the business's bank account.","distractor_reasons":{"A":"Incorrect because paying wages is a cash outflow.","B":"Incorrect because paying suppliers for raw materials is a cash outflow.","C":"Option C is correct because collecting payments owed by credit customers brings actual money into the business's bank account.","D":"Incorrect because paying corporation tax is a cash outflow."}}},{"id":"P1_U5_MCQ_528","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_528","question":"Which of the following is an example of a 'cash outflow' for a business?","options":{"A":"Receiving a new long-term loan from a commercial bank","B":"Collecting cash sales from retail customers at the checkout","C":"Receiving a non-repayable government grant into the bank account","D":"Paying suppliers for inventory, paying rent, and purchasing new equipment for cash"},"correctOption":"D","correctAnswer":"Paying suppliers for inventory, paying rent, and purchasing new equipment for cash","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because payments to suppliers, rent expenses, and cash asset purchases all result in money leaving the business.","distractor_reasons":{"A":"Incorrect because receiving loan funds brings money into the business (cash inflow).","B":"Incorrect because cash sales generate a cash inflow.","C":"Incorrect because receiving a grant is a cash inflow.","D":"Option D is correct because payments to suppliers, rent expenses, and cash asset purchases all result in money leaving the business."}}},{"id":"P1_U5_MCQ_529","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_529","question":"Why is a sale made on 60-day credit NOT recorded as a cash inflow in the month the goods are delivered?","options":{"A":"Because no actual money enters the business's bank account until the customer pays the invoice two months later","B":"Because credit sales are excluded from all accounting records until the financial year ends","C":"Because credit sales are classified as non-current liabilities","D":"Because credit sales reduce the business's gross profit"},"correctOption":"A","correctAnswer":"Because no actual money enters the business's bank account until the customer pays the invoice two months later","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash flow forecasts strictly record cash movements when money actually enters or leaves the bank, whereas revenue is recognized on the income statement at the point of sale.","distractor_reasons":{"A":"Option A is correct because cash flow forecasts strictly record cash movements when money actually enters or leaves the bank, whereas revenue is recognized on the income statement at the point of sale.","B":"Incorrect because credit sales are recorded immediately as revenue on the statement of profit or loss and as trade receivables on the statement of financial position.","C":"Incorrect because unpaid credit sales are trade receivables (current assets).","D":"Incorrect because credit sales add to revenue and gross profit."}}},{"id":"P1_U5_MCQ_530","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_530","question":"Why is 'depreciation' excluded from a cash flow forecast?","options":{"A":"Because depreciation is illegal to calculate in limited companies","B":"Because depreciation is a non-cash accounting charge that spreads an asset's cost over time without any money leaving the bank","C":"Because depreciation is recorded as a cash inflow at the end of each year","D":"Because depreciation only applies to raw material inventories"},"correctOption":"B","correctAnswer":"Because depreciation is a non-cash accounting charge that spreads an asset's cost over time without any money leaving the bank","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the cash outflow happens when the non-current asset is paid for; subsequent annual depreciation charges do not involve physical cash movements.","distractor_reasons":{"A":"Incorrect because depreciation is a standard accounting requirement.","B":"Option B is correct because the cash outflow happens when the non-current asset is paid for; subsequent annual depreciation charges do not involve physical cash movements.","C":"Incorrect because depreciation is an expense on the statement of profit or loss, never a cash inflow.","D":"Incorrect because depreciation applies to non-current assets such as machinery and vehicles, not inventories."}}},{"id":"P1_U5_MCQ_531","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_531","question":"How is 'net cash flow' calculated for a given month?","options":{"A":"Opening cash balance + Closing cash balance","B":"Sales revenue - Cost of sales","C":"Total cash inflows - Total cash outflows","D":"Current assets - Current liabilities"},"correctOption":"C","correctAnswer":"Total cash inflows - Total cash outflows","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because net cash flow measures the net gain or loss of cash during a specific period by subtracting total cash outflows from total cash inflows.","distractor_reasons":{"A":"Incorrect because opening and closing balances are stock positions at the start and end of the month.","B":"Incorrect because sales revenue minus cost of sales calculates gross profit.","C":"Option C is correct because net cash flow measures the net gain or loss of cash during a specific period by subtracting total cash outflows from total cash inflows.","D":"Incorrect because current assets minus current liabilities calculates working capital."}}},{"id":"P1_U5_MCQ_532","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_532","question":"How is the 'closing cash balance' at the end of a month calculated?","options":{"A":"Total cash inflows + Total cash outflows","B":"Opening cash balance - Total cash inflows","C":"Gross profit + Net cash flow","D":"Opening cash balance + Net cash flow"},"correctOption":"D","correctAnswer":"Opening cash balance + Net cash flow","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the closing balance reflects the cash held at the start of the month adjusted by the month's net cash flow (inflows minus outflows).","distractor_reasons":{"A":"Incorrect because adding inflows and outflows ignores the direction of cash movement and the opening balance.","B":"Incorrect because inflows add to cash rather than being subtracted.","C":"Incorrect because gross profit is an income statement figure, not a cash balance.","D":"Option D is correct because the closing balance reflects the cash held at the start of the month adjusted by the month's net cash flow (inflows minus outflows)."}}},{"id":"P1_U5_MCQ_533","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_533","question":"On a multi-month cash flow forecast, how does the 'closing balance' of one month relate to the following month?","options":{"A":"The closing cash balance at the end of one month becomes the opening cash balance at the start of the next month","B":"The closing cash balance is reset to zero at the start of every new month","C":"The closing cash balance is transferred to retained profit and removed from the bank account","D":"The closing cash balance becomes the next month's total cash outflows"},"correctOption":"A","correctAnswer":"The closing cash balance at the end of one month becomes the opening cash balance at the start of the next month","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash balances carry forward continuously from the end of one accounting period into the start of the next.","distractor_reasons":{"A":"Option A is correct because cash balances carry forward continuously from the end of one accounting period into the start of the next.","B":"Incorrect because cash in a bank account does not vanish at month-end.","C":"Incorrect because retained profit is an accounting equity figure, not a physical removal of bank cash.","D":"Incorrect because an opening balance is a starting cash position, not an expense."}}},{"id":"P1_U5_MCQ_534","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_534","question":"What does a negative closing cash balance on a cash flow forecast indicate?","options":{"A":"The business has earned a net loss on its statement of profit or loss","B":"The business is forecast to have a cash deficit and will need a bank overdraft or alternative cash injection to pay its bills","C":"The business has zero non-current assets","D":"The business has paid off all its long-term liabilities"},"correctOption":"B","correctAnswer":"The business is forecast to have a cash deficit and will need a bank overdraft or alternative cash injection to pay its bills","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a negative closing balance signals that cash outflows have exceeded available cash plus inflows, requiring an overdraft facility or corrective action.","distractor_reasons":{"A":"Incorrect because a business can be profitable while experiencing a temporary cash deficit.","B":"Option B is correct because a negative closing balance signals that cash outflows have exceeded available cash plus inflows, requiring an overdraft facility or corrective action.","C":"Incorrect because negative cash balances often result from heavy spending on non-current assets.","D":"Incorrect because a negative cash balance indicates a cash shortfall, not debt elimination."}}},{"id":"P1_U5_MCQ_535","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_535","question":"What is a 'cash flow forecast'?","options":{"A":"A historical record of all assets and liabilities held by a company at the end of last year","B":"A legal tax return submitted to calculate corporation tax on past profits","C":"An estimate of future cash inflows and cash outflows for a business, usually broken down on a month-by-month basis","D":"A list of all shareholders and the number of voting shares they hold"},"correctOption":"C","correctAnswer":"An estimate of future cash inflows and cash outflows for a business, usually broken down on a month-by-month basis","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a cash flow forecast is a forward-looking financial planning tool projecting expected monthly receipts, payments, and cash balances.","distractor_reasons":{"A":"Incorrect because a historical record of assets and liabilities is a statement of financial position.","B":"Incorrect because tax calculations rely on historical profit statements.","C":"Option C is correct because a cash flow forecast is a forward-looking financial planning tool projecting expected monthly receipts, payments, and cash balances.","D":"Incorrect because shareholder ownership records are maintained in a company's share register."}}},{"id":"P1_U5_MCQ_536","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_536","question":"Why is preparing a cash flow forecast particularly important when starting up a new business?","options":{"A":"It guarantees that customers will pay immediately in cash rather than asking for credit","B":"It legally exempts the start-up from paying value-added taxes","C":"It fixes supplier raw material prices for the first three years of trading","D":"It helps the entrepreneur calculate how much initial working capital is needed to survive early months before sales receipts cover expenses"},"correctOption":"D","correctAnswer":"It helps the entrepreneur calculate how much initial working capital is needed to survive early months before sales receipts cover expenses","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because new businesses face heavy upfront outflows and slow initial inflows; forecasting shows the minimum cash buffer required to avoid early failure.","distractor_reasons":{"A":"Incorrect because a forecast estimates customer behavior rather than forcing cash payments.","B":"Incorrect because forecasts provide no tax exemptions.","C":"Incorrect because forecasts estimate future costs rather than locking in supplier contracts.","D":"Option D is correct because new businesses face heavy upfront outflows and slow initial inflows; forecasting shows the minimum cash buffer required to avoid early failure."}}},{"id":"P1_U5_MCQ_537","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_537","question":"Why do commercial banks require a cash flow forecast before approving a business loan or overdraft?","options":{"A":"Because banks are legally forbidden from viewing statements of profit or loss","B":"To calculate the exact depreciation rate of the business's office furniture","C":"To check the size and timing of expected cash shortages and verify that the business will generate enough future cash inflows to repay the borrowing","D":"To determine how many employees the business should hire"},"correctOption":"C","correctAnswer":"To check the size and timing of expected cash shortages and verify that the business will generate enough future cash inflows to repay the borrowing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lenders evaluate repayment capacity and credit risk by examining when cash deficits occur and when surpluses return.","distractor_reasons":{"A":"Incorrect because banks review historical profit statements alongside cash flow forecasts.","B":"Incorrect because depreciation is non-cash and is not shown on a cash flow forecast.","C":"Option C is correct because lenders evaluate repayment capacity and credit risk by examining when cash deficits occur and when surpluses return.","D":"Incorrect because staffing decisions belong to business managers, not the bank."}}},{"id":"P1_U5_MCQ_538","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_538","question":"How can managers use a cash flow forecast when it predicts large positive cash surpluses accumulating over several months?","options":{"A":"Stop sending invoices to credit customers until the surplus disappears","B":"Plan productive uses for idle cash, such as repaying high-interest debt early, buying stock in bulk for discounts, or placing funds in interest-earning deposits","C":"Ask the bank for an emergency short-term overdraft","D":"Ignore the surplus because positive cash balances cannot be spent"},"correctOption":"B","correctAnswer":"Plan productive uses for idle cash, such as repaying high-interest debt early, buying stock in bulk for discounts, or placing funds in interest-earning deposits","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because holding excessive idle cash in a zero-interest current account incurs an opportunity cost; forecasting surpluses allows smart treasury planning.","distractor_reasons":{"A":"Incorrect because delaying invoices weakens credit control and increases bad-debt risk.","B":"Option B is correct because holding excessive idle cash in a zero-interest current account incurs an opportunity cost; forecasting surpluses allows smart treasury planning.","C":"Incorrect because an overdraft is needed for cash deficits, not cash surpluses.","D":"Incorrect because positive cash balances are liquid funds available for business use."}}},{"id":"P1_U5_MCQ_539","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_539","question":"How does regular monitoring of a cash flow forecast help prevent business failure?","options":{"A":"It automatically converts all trade payables into shareholders' equity","B":"It guarantees that gross profit margin will rise every quarter","C":"It gives managers advance warning of upcoming cash deficits so they can arrange overdrafts, delay capital spending, or tighten credit control in time","D":"It eliminates the legal obligation to pay employee wages during slow months"},"correctOption":"C","correctAnswer":"It gives managers advance warning of upcoming cash deficits so they can arrange overdrafts, delay capital spending, or tighten credit control in time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because spotting a forecast cash shortage months ahead allows proactive corrective measures before the business runs out of cash.","distractor_reasons":{"A":"Incorrect because supplier debts remain liabilities until paid.","B":"Incorrect because a cash flow forecast monitors liquidity rather than guaranteeing profit margins.","C":"Option C is correct because spotting a forecast cash shortage months ahead allows proactive corrective measures before the business runs out of cash.","D":"Incorrect because wages remain legally payable regardless of seasonal trading."}}},{"id":"P1_U5_MCQ_540","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_540","question":"Which statement accurately describes the difference between 'cash' and 'profit'?","options":{"A":"Cash and profit are always identical at the end of every trading month","B":"Cash is recorded only on the statement of profit or loss, whereas profit is recorded only on the cash flow forecast","C":"Profit includes bank loans received, whereas cash excludes bank loans received","D":"Profit is the surplus of revenue over costs over a trading period, whereas cash is the liquid money held by the business at a point in time"},"correctOption":"D","correctAnswer":"Profit is the surplus of revenue over costs over a trading period, whereas cash is the liquid money held by the business at a point in time","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit measures trading performance (including credit transactions and non-cash depreciation), whereas cash measures actual liquid funds available to pay bills.","distractor_reasons":{"A":"Incorrect because credit terms, asset purchases, and loan movements cause cash and profit to diverge.","B":"Incorrect because this reverses where cash and profit are recorded.","C":"Incorrect because bank loans received are cash inflows, not trading profit.","D":"Option D is correct because profit measures trading performance (including credit transactions and non-cash depreciation), whereas cash measures actual liquid funds available to pay bills."}}},{"id":"P1_U5_MCQ_541","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_541","question":"How can a business that reports a healthy profit on its statement of profit or loss still run out of cash and face liquidation?","options":{"A":"By receiving all customer payments upfront in cash before incurring any costs","B":"Because profitable businesses are legally prohibited from holding positive bank balances","C":"Because gross profit is always subtracted from the bank current account","D":"By selling goods on long credit terms to customers while having to pay suppliers, wages, and capital expenditure immediately in cash"},"correctOption":"D","correctAnswer":"By selling goods on long credit terms to customers while having to pay suppliers, wages, and capital expenditure immediately in cash","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because credit sales count toward revenue and profit immediately, but if cash is tied up in slow-paying trade receivables or heavy capital purchases, the business can run out of liquid cash.","distractor_reasons":{"A":"Incorrect because collecting cash upfront before paying costs creates strong positive cash flow.","B":"Incorrect because profitable firms routinely hold positive bank balances.","C":"Incorrect because gross profit is a calculation, not a cash deduction.","D":"Option D is correct because credit sales count toward revenue and profit immediately, but if cash is tied up in slow-paying trade receivables or heavy capital purchases, the business can run out of liquid cash."}}},{"id":"P1_U5_MCQ_542","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_542","question":"How can a business that makes a trading loss during a period still record a positive net cash flow?","options":{"A":"By paying all suppliers upfront in cash while giving customers 90-day credit","B":"By receiving a large cash inflow from a new bank loan, share issue, or sale of non-current assets, or by collecting past trade receivables","C":"Because trading losses are automatically added to the bank current account","D":"By purchasing expensive freehold land using physical cash"},"correctOption":"B","correctAnswer":"By receiving a large cash inflow from a new bank loan, share issue, or sale of non-current assets, or by collecting past trade receivables","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-trading cash inflows (loans, equity injections, asset sales) and collections from previous credit sales boost cash without counting as current-period profit.","distractor_reasons":{"A":"Incorrect because paying upfront and granting long credit worsens cash flow.","B":"Option B is correct because non-trading cash inflows (loans, equity injections, asset sales) and collections from previous credit sales boost cash without counting as current-period profit.","C":"Incorrect because trading losses drain rather than increase cash.","D":"Incorrect because buying freehold land for cash causes a large cash outflow."}}},{"id":"P1_U5_MCQ_543","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_543","question":"Which sequence accurately represents the 'working capital cycle'?","options":{"A":"Cash -> issue shares -> buy freehold land -> pay dividends","B":"Trade payables -> depreciation -> non-current liabilities -> retained profit","C":"Cash -> purchase inventories -> produce and sell goods on credit -> collect cash from trade receivables","D":"Bank overdraft -> fixed assets -> corporation tax -> liquidation"},"correctOption":"C","correctAnswer":"Cash -> purchase inventories -> produce and sell goods on credit -> collect cash from trade receivables","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the working capital cycle shows how cash is spent on stock and production, converted into trade receivables upon credit sale, and returned as cash when customers pay.","distractor_reasons":{"A":"Incorrect because share issues and land purchases are long-term capital transactions.","B":"Incorrect because depreciation and non-current liabilities are not part of the short-term trading cash cycle.","C":"Option C is correct because the working capital cycle shows how cash is spent on stock and production, converted into trade receivables upon credit sale, and returned as cash when customers pay.","D":"Incorrect because this does not represent the operational flow of current assets."}}},{"id":"P1_U5_MCQ_544","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_544","question":"Why is arranging or increasing a 'bank overdraft' often used to overcome a temporary, short-term cash flow deficit?","options":{"A":"It eliminates all future business costs permanently","B":"It increases sales revenue on the statement of profit or loss","C":"It converts short-term trade payables into permanent share capital","D":"It is flexible, quick to arrange, and allows the business to spend more than its current account balance up to an agreed limit, paying interest only on the overdrawn amount"},"correctOption":"D","correctAnswer":"It is flexible, quick to arrange, and allows the business to spend more than its current account balance up to an agreed limit, paying interest only on the overdrawn amount","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an overdraft is specifically designed to bridge brief seasonal or timing gaps in cash flow without taking on a rigid multi-year loan.","distractor_reasons":{"A":"Incorrect because an overdraft adds interest expenses rather than eliminating costs.","B":"Incorrect because borrowing via an overdraft does not generate sales revenue.","C":"Incorrect because an overdraft is a short-term debt liability, not share capital.","D":"Option D is correct because an overdraft is specifically designed to bridge brief seasonal or timing gaps in cash flow without taking on a rigid multi-year loan."}}},{"id":"P1_U5_MCQ_545","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_545","question":"How does 'delaying payments to suppliers' (extending trade credit) help resolve a short-term cash shortage?","options":{"A":"It increases the business's gross profit margin","B":"It increases immediate cash inflows from retail customers","C":"It permanently cancels the legal obligation to pay for raw materials","D":"It postpones cash outflows into a later month, keeping cash inside the business during the deficit period"},"correctOption":"D","correctAnswer":"It postpones cash outflows into a later month, keeping cash inside the business during the deficit period","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because negotiating longer payment terms with trade payables slows down cash outflows and preserves immediate liquidity.","distractor_reasons":{"A":"Incorrect because delaying payment does not reduce the purchase cost of goods sold.","B":"Incorrect because supplier credit affects cash outflows, not customer inflows.","C":"Incorrect because supplier invoices must still be paid at the end of the extended credit period.","D":"Option D is correct because negotiating longer payment terms with trade payables slows down cash outflows and preserves immediate liquidity."}}},{"id":"P1_U5_MCQ_546","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_546","question":"How does 'asking credit customers to pay more quickly' or 'offering a prompt-payment discount' improve a business's cash flow?","options":{"A":"It delays cash outflows for staff wages and factory rent","B":"It accelerates cash inflows from trade receivables so cash enters the bank account sooner","C":"It increases the value of unsold inventories on the statement of financial position","D":"It reduces the business's non-current liabilities"},"correctOption":"B","correctAnswer":"It accelerates cash inflows from trade receivables so cash enters the bank account sooner","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because shortening the credit collection period converts trade receivables into liquid cash faster, though offering a cash discount slightly reduces profit.","distractor_reasons":{"A":"Incorrect because customer credit policies influence cash inflows rather than wage or rent outflows.","B":"Option B is correct because shortening the credit collection period converts trade receivables into liquid cash faster, though offering a cash discount slightly reduces profit.","C":"Incorrect because collecting receivables reduces trade receivables and increases cash, leaving inventory unchanged.","D":"Incorrect because customer collections affect current assets, not non-current liabilities."}}},{"id":"P1_U5_MCQ_547","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_547","question":"How does 'delaying or cancelling planned capital expenditure' (such as postponing the purchase of new machinery) help solve a forecast cash deficit?","options":{"A":"It generates immediate cash inflows from external investors","B":"It increases monthly sales revenue","C":"It avoids a large cash outflow in the short term, preserving cash to cover essential day-to-day running costs","D":"It reduces the business's trade payables to zero"},"correctOption":"C","correctAnswer":"It avoids a large cash outflow in the short term, preserving cash to cover essential day-to-day running costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital equipment purchases involve substantial cash outflows; deferring non-urgent capital spending immediately relieves pressure on cash balances.","distractor_reasons":{"A":"Incorrect because postponing spending avoids an outflow rather than creating an external inflow.","B":"Incorrect because delaying machinery purchases does not directly raise sales revenue.","C":"Option C is correct because capital equipment purchases involve substantial cash outflows; deferring non-urgent capital spending immediately relieves pressure on cash balances.","D":"Incorrect because existing supplier bills still have to be paid."}}},{"id":"P1_U5_MCQ_548","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_548","question":"What is a major limitation of taking out a 'short-term bank loan' to solve a recurring cash flow shortage?","options":{"A":"It never increases the business's immediate cash balance","B":"It immediately reduces the business's gross profit margin","C":"It forces the business to give up its limited liability status","D":"While it provides a temporary cash inflow, it creates future cash outflows through interest charges and principal repayments, without fixing underlying trading problems"},"correctOption":"D","correctAnswer":"While it provides a temporary cash inflow, it creates future cash outflows through interest charges and principal repayments, without fixing underlying trading problems","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because borrowing bridges a short-term cash gap, but the debt must be repaid with interest later and does not resolve poor credit control or unprofitability.","distractor_reasons":{"A":"Incorrect because receiving loan funds directly increases the immediate cash balance.","B":"Incorrect because loan interest is a finance expense deducted after gross profit.","C":"Incorrect because borrowing does not alter legal structure.","D":"Option D is correct because borrowing bridges a short-term cash gap, but the debt must be repaid with interest later and does not resolve poor credit control or unprofitability."}}},{"id":"P1_U5_MCQ_549","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_549","question":"What is a major risk of repeatedly 'delaying payments to suppliers' without their agreement in order to improve cash flow?","options":{"A":"The business's non-current assets will lose all market value","B":"The business's corporation tax bill will automatically double","C":"Credit customers will stop paying their invoices","D":"Suppliers may refuse future deliveries, withdraw trade credit, charge late-payment penalties, or take legal action to recover the debt"},"correctOption":"D","correctAnswer":"Suppliers may refuse future deliveries, withdraw trade credit, charge late-payment penalties, or take legal action to recover the debt","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because damaging supplier goodwill by paying late can cut off vital raw material supplies and force the business to pay cash on delivery in the future.","distractor_reasons":{"A":"Incorrect because late supplier payments do not alter non-current asset values.","B":"Incorrect because late supplier payments do not double corporation tax rates.","C":"Incorrect because supplier relationships do not dictate whether customers pay.","D":"Option D is correct because damaging supplier goodwill by paying late can cut off vital raw material supplies and force the business to pay cash on delivery in the future."}}},{"id":"P1_U5_MCQ_550","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_550","question":"What is a key limitation of all 'cash flow forecasts'?","options":{"A":"They are legally forbidden from including cash inflows from credit customers","B":"They rely on estimates and assumptions about future sales, costs, and payment timings, which may prove inaccurate due to unexpected market changes","C":"They can only be prepared after the financial year has completely ended","D":"They ignore all cash outflows such as rent, wages, and loan repayments"},"correctOption":"B","correctAnswer":"They rely on estimates and assumptions about future sales, costs, and payment timings, which may prove inaccurate due to unexpected market changes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because forecasts project future events; sudden shifts in demand, raw material prices, interest rates, or customer defaults can cause actual cash flows to differ from forecasts.","distractor_reasons":{"A":"Incorrect because expected receipts from credit customers are a central component of cash flow forecasts.","B":"Option B is correct because forecasts project future events; sudden shifts in demand, raw material prices, interest rates, or customer defaults can cause actual cash flows to differ from forecasts.","C":"Incorrect because cash flow forecasts are forward-looking planning tools prepared before or during a trading period.","D":"Incorrect because all expected cash outflows are included in a cash flow forecast."}}},{"id":"P1_U5_MCQ_551","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_551","question":"How is 'profit' defined for a business over a trading period?","options":{"A":"The total physical cash held in the business's bank account at year-end","B":"The total value of all assets minus all liabilities on the statement of financial position","C":"The positive financial surplus remaining when total revenue exceeds total costs over a period of time","D":"The total amount of money raised by issuing shares and taking bank loans"},"correctOption":"C","correctAnswer":"The positive financial surplus remaining when total revenue exceeds total costs over a period of time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because profit is a flow measure over an accounting period calculated as Total revenue minus Total costs.","distractor_reasons":{"A":"Incorrect because physical cash in the bank is liquidity, not profit.","B":"Incorrect because total assets minus total liabilities equals net assets (equity).","C":"Option C is correct because profit is a flow measure over an accounting period calculated as Total revenue minus Total costs.","D":"Incorrect because share issues and loans are financing inflows, not trading profit."}}},{"id":"P1_U5_MCQ_552","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_552","question":"Why is earning profit vital for private sector businesses?","options":{"A":"Because earning profit legally exempts a business from paying wages during recessions","B":"Because profit is the only item recorded on a cash flow forecast","C":"Because earning profit guarantees that a business will never run out of cash","D":"Because it rewards entrepreneurs and shareholders for taking risks, provides retained profit for reinvestment, and signals success to attract external investors"},"correctOption":"D","correctAnswer":"Because it rewards entrepreneurs and shareholders for taking risks, provides retained profit for reinvestment, and signals success to attract external investors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit serves as the incentive for risk-taking, a primary internal source of expansion capital, and a key indicator of business viability.","distractor_reasons":{"A":"Incorrect because profitable businesses must still pay full contracted wages.","B":"Incorrect because profit is calculated on the statement of profit or loss, not the cash flow forecast.","C":"Incorrect because profitable firms can still suffer cash crises if working capital is poorly managed.","D":"Option D is correct because profit serves as the incentive for risk-taking, a primary internal source of expansion capital, and a key indicator of business viability."}}},{"id":"P1_U5_MCQ_553","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_553","question":"Why is generating a financial surplus (profit) still important for a 'social enterprise'?","options":{"A":"To remain financially self-sustaining without relying solely on donations and to reinvest surpluses into its social or environmental mission","B":"To maximize dividend payouts to wealthy stock-market speculators","C":"Because social enterprises are fined by the government if they break even","D":"Because social enterprises are prohibited from paying staff salaries"},"correctOption":"A","correctAnswer":"To remain financially self-sustaining without relying solely on donations and to reinvest surpluses into its social or environmental mission","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social enterprises operate commercially to earn profits that are reinvested to achieve social, community, or environmental goals.","distractor_reasons":{"A":"Option A is correct because social enterprises operate commercially to earn profits that are reinvested to achieve social, community, or environmental goals.","B":"Incorrect because social enterprises prioritize social objectives over maximizing private shareholder dividends.","C":"Incorrect because breaking even is not penalized by law.","D":"Incorrect because social enterprises employ paid staff alongside any volunteers."}}},{"id":"P1_U5_MCQ_554","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_554","question":"How does the purchase of a new non-current asset (such as a delivery van) for cash affect 'cash flow' versus 'profit' at the time of purchase?","options":{"A":"It reduces profit immediately by the full purchase price, but has zero effect on cash flow","B":"It reduces cash flow immediately by the full purchase price, whereas only gradual annual depreciation reduces profit over the asset's useful life","C":"It increases both cash flow and profit immediately by the purchase price","D":"It is omitted from both the cash flow forecast and the statement of financial position"},"correctOption":"B","correctAnswer":"It reduces cash flow immediately by the full purchase price, whereas only gradual annual depreciation reduces profit over the asset's useful life","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because buying a non-current asset drains cash immediately on the cash flow statement, while on the statement of profit or loss its cost is spread out via annual depreciation.","distractor_reasons":{"A":"Incorrect because paying cash immediately reduces the cash balance, while the full asset cost is not expensed at once.","B":"Option B is correct because buying a non-current asset drains cash immediately on the cash flow statement, while on the statement of profit or loss its cost is spread out via annual depreciation.","C":"Incorrect because buying an asset is a cash outflow, not an inflow or profit.","D":"Incorrect because the cash outflow appears on the cash flow statement and the asset appears on the statement of financial position."}}},{"id":"P1_U5_MCQ_555","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_555","question":"What is the purpose of a 'statement of profit or loss' (income statement)?","options":{"A":"To show the assets, liabilities, and equity of a business on a single day","B":"To project monthly cash inflows and outflows for the upcoming year","C":"To record the revenue, costs, and profit or loss made by a business over a trading period (usually one year)","D":"To list the personal bank balances of the company's directors"},"correctOption":"C","correctAnswer":"To record the revenue, costs, and profit or loss made by a business over a trading period (usually one year)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the statement of profit or loss summarizes trading income and expenses across a financial period to show gross profit, profit for the year, and retained profit.","distractor_reasons":{"A":"Incorrect because showing assets, liabilities, and equity on a single date is the role of the statement of financial position.","B":"Incorrect because projecting future monthly cash movements is the role of a cash flow forecast.","C":"Option C is correct because the statement of profit or loss summarizes trading income and expenses across a financial period to show gross profit, profit for the year, and retained profit.","D":"Incorrect because directors' personal finances are separate from company financial statements."}}},{"id":"P1_U5_MCQ_556","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_556","question":"What is meant by 'revenue' (sales revenue) on a statement of profit or loss?","options":{"A":"The total cash received from bank loans and share issues during the year","B":"The profit remaining after deducting cost of sales from total sales","C":"The total value of unsold goods held in the warehouse at year-end","D":"The total income earned by a business from selling its goods or services during a period (Selling price × Quantity sold)"},"correctOption":"D","correctAnswer":"The total income earned by a business from selling its goods or services during a period (Selling price × Quantity sold)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because revenue represents total trading turnover generated from sales of products or services, whether sold for cash or on credit.","distractor_reasons":{"A":"Incorrect because bank loans and share issues are financing receipts, not trading revenue.","B":"Incorrect because sales minus cost of sales defines gross profit.","C":"Incorrect because unsold goods at year-end are closing inventory.","D":"Option D is correct because revenue represents total trading turnover generated from sales of products or services, whether sold for cash or on credit."}}},{"id":"P1_U5_MCQ_557","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_557","question":"What is meant by 'cost of sales' on a statement of profit or loss?","options":{"A":"Corporation tax paid to the government on annual profits","B":"All indirect overhead expenses such as head-office rent, marketing, and administrative salaries","C":"The purchase price of new freehold land and factory buildings","D":"The direct costs of producing or purchasing the specific goods that were actually sold during the trading period"},"correctOption":"D","correctAnswer":"The direct costs of producing or purchasing the specific goods that were actually sold during the trading period","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cost of sales measures direct variable/production costs (such as raw materials, direct factory wages, or wholesale cost of goods resold) linked to items sold.","distractor_reasons":{"A":"Incorrect because corporation tax is deducted after operating profit is calculated.","B":"Incorrect because indirect running costs are overhead expenses deducted after gross profit.","C":"Incorrect because freehold land and buildings are non-current assets (capital expenditure).","D":"Option D is correct because cost of sales measures direct variable/production costs (such as raw materials, direct factory wages, or wholesale cost of goods resold) linked to items sold."}}},{"id":"P1_U5_MCQ_558","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_558","question":"How is 'cost of sales' calculated for a retail business that holds inventory?","options":{"A":"Closing inventory + Purchases - Opening inventory","B":"Opening inventory + Purchases - Closing inventory","C":"Revenue - Gross profit - Overhead expenses","D":"Opening inventory + Closing inventory + Purchases"},"correctOption":"B","correctAnswer":"Opening inventory + Purchases - Closing inventory","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total goods available for sale (Opening inventory + Purchases) minus unsold goods left at year-end (Closing inventory) equals the cost of goods actually sold.","distractor_reasons":{"A":"Incorrect because opening inventory was available to sell and closing inventory remains unsold, so signs are reversed.","B":"Option B is correct because total goods available for sale (Opening inventory + Purchases) minus unsold goods left at year-end (Closing inventory) equals the cost of goods actually sold.","C":"Incorrect because revenue minus gross profit equals cost of sales; subtracting overhead expenses as well gives an incorrect figure.","D":"Incorrect because adding unsold closing inventory overstates the cost of items sold."}}},{"id":"P1_U5_MCQ_559","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_559","question":"How is 'gross profit' calculated on a statement of profit or loss?","options":{"A":"Revenue - Total overhead expenses","B":"Revenue - Cost of sales - Overhead expenses - Tax","C":"Revenue - Cost of sales","D":"Gross profit margin × Cost of sales"},"correctOption":"C","correctAnswer":"Revenue - Cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because gross profit measures the trading surplus made purely from buying/producing and selling goods before indirect overhead expenses are deducted.","distractor_reasons":{"A":"Incorrect because gross profit deducts direct cost of sales, not indirect overhead expenses.","B":"Incorrect because deducting overhead expenses and tax gives profit after tax, not gross profit.","C":"Option C is correct because gross profit measures the trading surplus made purely from buying/producing and selling goods before indirect overhead expenses are deducted.","D":"Incorrect because gross profit margin is a percentage of revenue, not cost of sales."}}},{"id":"P1_U5_MCQ_560","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_560","question":"Which of the following best defines 'overhead expenses' (indirect expenses) on a statement of profit or loss?","options":{"A":"The direct purchase cost of raw materials incorporated into finished products","B":"The money spent buying long-term non-current assets such as delivery vans","C":"The cash dividends distributed to shareholders at the end of the year","D":"The day-to-day running costs of the business that are not directly tied to making a specific unit of output, such as office salaries, rent, and advertising"},"correctOption":"D","correctAnswer":"The day-to-day running costs of the business that are not directly tied to making a specific unit of output, such as office salaries, rent, and advertising","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because overhead expenses are indirect operational costs deducted from gross profit to calculate profit for the year.","distractor_reasons":{"A":"Incorrect because direct raw materials form part of cost of sales.","B":"Incorrect because delivery vans are capital expenditure on non-current assets.","C":"Incorrect because dividends are an appropriation of after-tax profit, not an operating expense.","D":"Option D is correct because overhead expenses are indirect operational costs deducted from gross profit to calculate profit for the year."}}},{"id":"P1_U5_MCQ_561","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_561","question":"Which item would be recorded under 'cost of sales' rather than 'overhead expenses' for a manufacturing business?","options":{"A":"Insurance and electricity bills for the administrative head office","B":"Salaries paid to head-office human resources and accounting staff","C":"Annual television and social media advertising costs","D":"Wages paid to factory assembly-line workers directly making the product"},"correctOption":"D","correctAnswer":"Wages paid to factory assembly-line workers directly making the product","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because direct production labor is directly involved in manufacturing the goods sold and therefore belongs in cost of sales.","distractor_reasons":{"A":"Incorrect because head-office utilities and insurance are indirect overhead expenses.","B":"Incorrect because administrative salaries are indirect overhead expenses.","C":"Incorrect because marketing and advertising costs are indirect overhead expenses.","D":"Option D is correct because direct production labor is directly involved in manufacturing the goods sold and therefore belongs in cost of sales."}}},{"id":"P1_U5_MCQ_562","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_562","question":"How is 'profit' (operating profit / profit before tax) calculated on a statement of profit or loss?","options":{"A":"Revenue - Cost of sales","B":"Gross profit - Overhead expenses","C":"Gross profit + Overhead expenses","D":"Profit after tax - Dividends"},"correctOption":"B","correctAnswer":"Gross profit - Overhead expenses","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because deducting all indirect overhead running expenses from gross profit yields the business's operating profit.","distractor_reasons":{"A":"Incorrect because revenue minus cost of sales calculates gross profit.","B":"Option B is correct because deducting all indirect overhead running expenses from gross profit yields the business's operating profit.","C":"Incorrect because overhead expenses are costs that must be subtracted, not added.","D":"Incorrect because profit after tax minus dividends calculates retained profit."}}},{"id":"P1_U5_MCQ_563","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_563","question":"Where does 'corporation tax' appear on a limited company's statement of profit or loss?","options":{"A":"It is added to sales revenue at the top of the statement","B":"It is included inside cost of sales before gross profit is calculated","C":"It is deducted from profit before tax to arrive at profit after tax","D":"It is deducted after retained profit has already been calculated"},"correctOption":"C","correctAnswer":"It is deducted from profit before tax to arrive at profit after tax","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because corporation tax is levied by the government as a percentage of a company's profit before tax, leaving profit after tax available for dividends or retention.","distractor_reasons":{"A":"Incorrect because tax is a compulsory payment, not revenue.","B":"Incorrect because corporation tax is calculated on final profit, not direct production costs.","C":"Option C is correct because corporation tax is levied by the government as a percentage of a company's profit before tax, leaving profit after tax available for dividends or retention.","D":"Incorrect because tax is paid before the company decides how much profit to retain or distribute as dividends."}}},{"id":"P1_U5_MCQ_564","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_564","question":"What are 'dividends' on a limited company's statement of profit or loss?","options":{"A":"Fixed interest payments legally owed to commercial banks on long-term loans","B":"Direct wages paid to factory production staff","C":"Taxes paid to the government on sales revenue","D":"The share of profit after tax distributed to shareholders as a return on their investment"},"correctOption":"D","correctAnswer":"The share of profit after tax distributed to shareholders as a return on their investment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dividends represent the portion of after-tax earnings paid out to ordinary shareholders, as recommended by the board of directors.","distractor_reasons":{"A":"Incorrect because contractual payments to banks are loan interest expenses.","B":"Incorrect because worker pay is wages/salaries.","C":"Incorrect because government levies on company profits are corporation tax.","D":"Option D is correct because dividends represent the portion of after-tax earnings paid out to ordinary shareholders, as recommended by the board of directors."}}},{"id":"P1_U5_MCQ_565","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_565","question":"What is 'retained profit'?","options":{"A":"The profit after tax remaining inside a business after dividends have been paid out to shareholders, kept for reinvestment","B":"The total cash sitting in the business's safe on the last day of the year","C":"The difference between sales revenue and cost of sales","D":"The total amount of money borrowed from banks over the past five years"},"correctOption":"A","correctAnswer":"The profit after tax remaining inside a business after dividends have been paid out to shareholders, kept for reinvestment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit is the undistributed portion of after-tax profit ploughed back into the business to fund future growth.","distractor_reasons":{"A":"Option A is correct because retained profit is the undistributed portion of after-tax profit ploughed back into the business to fund future growth.","B":"Incorrect because retained profit is an accounting equity figure, not physical cash in a safe.","C":"Incorrect because sales revenue minus cost of sales is gross profit.","D":"Incorrect because borrowed funds are liabilities, not retained profit."}}},{"id":"P1_U5_MCQ_566","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_566","question":"How is 'retained profit' calculated at the bottom of a company's statement of profit or loss?","options":{"A":"Gross profit - Dividends","B":"Profit after tax - Dividends","C":"Revenue - Cost of sales - Dividends","D":"Profit before tax + Dividends"},"correctOption":"B","correctAnswer":"Profit after tax - Dividends","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because once corporation tax has been subtracted from profit, the remaining profit after tax is split between dividends paid and retained profit kept.","distractor_reasons":{"A":"Incorrect because overhead expenses and corporation tax must be deducted before dividends.","B":"Option B is correct because once corporation tax has been subtracted from profit, the remaining profit after tax is split between dividends paid and retained profit kept.","C":"Incorrect because this omits overhead expenses and corporation tax.","D":"Incorrect because dividends are paid out (subtracted) from after-tax profit, not added."}}},{"id":"P1_U5_MCQ_567","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_567","question":"Which sequence shows the correct top-to-bottom order of items on a limited company's statement of profit or loss?","options":{"A":"Gross profit -> Revenue -> Cost of sales -> Overhead expenses -> Retained profit","B":"Revenue -> Overhead expenses -> Gross profit -> Cost of sales -> Profit after tax","C":"Revenue -> Cost of sales -> Gross profit -> Overhead expenses -> Profit before tax -> Tax -> Profit after tax -> Dividends -> Retained profit","D":"Retained profit -> Dividends -> Profit after tax -> Overhead expenses -> Gross profit -> Revenue"},"correctOption":"C","correctAnswer":"Revenue -> Cost of sales -> Gross profit -> Overhead expenses -> Profit before tax -> Tax -> Profit after tax -> Dividends -> Retained profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a standard income statement starts with revenue, deducts cost of sales to find gross profit, deducts overheads to find profit, deducts tax, and finally appropriates after-tax profit into dividends and retained profit.","distractor_reasons":{"A":"Incorrect because revenue must appear before cost of sales and gross profit.","B":"Incorrect because cost of sales is deducted before gross profit, while overhead expenses are deducted after gross profit.","C":"Option C is correct because a standard income statement starts with revenue, deducts cost of sales to find gross profit, deducts overheads to find profit, deducts tax, and finally appropriates after-tax profit into dividends and retained profit.","D":"Incorrect because this reverses the entire statement from bottom to top."}}},{"id":"P1_U5_MCQ_568","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_568","question":"If a manufacturer negotiates lower raw material prices from suppliers while keeping selling prices and sales volume unchanged, what happens on its statement of profit or loss?","options":{"A":"Revenue rises and overhead expenses fall","B":"Cost of sales rises and gross profit falls","C":"Gross profit stays unchanged while retained profit falls","D":"Cost of sales falls, which increases both gross profit and profit for the year"},"correctOption":"D","correctAnswer":"Cost of sales falls, which increases both gross profit and profit for the year","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because raw materials are a direct cost of sales; lowering them boosts gross profit directly, which flows down to increase final profit.","distractor_reasons":{"A":"Incorrect because unchanged selling prices and volume leave revenue unchanged, and raw materials are not overhead expenses.","B":"Incorrect because lower material prices reduce cost of sales and increase gross profit.","C":"Incorrect because lower direct costs directly increase gross profit.","D":"Option D is correct because raw materials are a direct cost of sales; lowering them boosts gross profit directly, which flows down to increase final profit."}}},{"id":"P1_U5_MCQ_569","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_569","question":"If a business reduces its head-office administrative salaries while revenue and direct production costs stay constant, how are gross profit and profit for the year affected?","options":{"A":"Both gross profit and profit for the year decrease","B":"Both gross profit and profit for the year increase","C":"Gross profit increases, while profit for the year stays unchanged","D":"Gross profit stays unchanged, while profit for the year increases"},"correctOption":"D","correctAnswer":"Gross profit stays unchanged, while profit for the year increases","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because administrative salaries are indirect overhead expenses deducted after gross profit; reducing them leaves gross profit untouched while raising final profit.","distractor_reasons":{"A":"Incorrect because lowering expenses increases rather than decreases profit.","B":"Incorrect because gross profit only depends on revenue and cost of sales.","C":"Incorrect because gross profit does not change when indirect overheads fall.","D":"Option D is correct because administrative salaries are indirect overhead expenses deducted after gross profit; reducing them leaves gross profit untouched while raising final profit."}}},{"id":"P1_U5_MCQ_570","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_570","question":"A stationery firm raises the selling price of its notebooks. Which situation would cause its total revenue from notebooks to fall?","options":{"A":"Unit sales fall by a larger percentage than the rise in selling price","B":"The firm's annual fixed costs increase","C":"The price the firm pays for paper rises","D":"The firm lowers the cost of its packaging per notebook"},"correctOption":"A","correctAnswer":"Unit sales fall by a larger percentage than the rise in selling price","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals selling price multiplied by units sold. If the drop in units sold is proportionally larger than the price increase, lost sales outweigh the extra revenue per item and total revenue falls.","distractor_reasons":{"A":"Correct: a proportionally larger fall in units sold reduces total revenue despite the higher price.","B":"Higher fixed costs affect profit, not the revenue earned from selling notebooks.","C":"A higher paper price raises production costs but does not change sales revenue.","D":"Cheaper packaging reduces costs, not the revenue received from customers."}}},{"id":"P1_U5_MCQ_571","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_571","question":"What strategic trade-off do company directors face when deciding how to divide profit after tax between dividends and retained profit?","options":{"A":"Paying dividends increases corporation tax rates, whereas retaining profit reduces sales revenue","B":"Retained profit must be paid to commercial banks, whereas dividends are paid to suppliers","C":"Paying higher dividends satisfies current shareholders and supports share demand, whereas retaining more profit provides interest-free internal finance for future growth","D":"Dividends are deducted before gross profit, whereas retained profit is deducted before operating profit"},"correctOption":"C","correctAnswer":"Paying higher dividends satisfies current shareholders and supports share demand, whereas retaining more profit provides interest-free internal finance for future growth","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because every dollar paid out as a dividend is a dollar unavailable for internal reinvestment, requiring directors to balance short-term shareholder rewards against long-term expansion.","distractor_reasons":{"A":"Incorrect because dividend choices do not alter tax rates or sales revenue.","B":"Incorrect because retained profit stays inside the company and dividends go to shareholders.","C":"Option C is correct because every dollar paid out as a dividend is a dollar unavailable for internal reinvestment, requiring directors to balance short-term shareholder rewards against long-term expansion.","D":"Incorrect because both dividends and retained profit appear at the very bottom after profit after tax."}}},{"id":"P1_U5_MCQ_572","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_572","question":"How do existing shareholders and potential investors primarily use a company's statement of profit or loss?","options":{"A":"To check the exact daily cash balance held in the company's till","B":"To verify whether the company owns freehold land free of mortgages","C":"To calculate the company's current ratio and acid-test ratio","D":"To assess revenue growth, cost control, and profit trends in order to judge management performance and likely future dividends"},"correctOption":"D","correctAnswer":"To assess revenue growth, cost control, and profit trends in order to judge management performance and likely future dividends","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shareholders focus on profitability trends over time and against rivals to evaluate returns on their equity investment.","distractor_reasons":{"A":"Incorrect because cash balances appear on the statement of financial position, not the income statement.","B":"Incorrect because freehold property and mortgages appear on the statement of financial position.","C":"Incorrect because liquidity ratios are calculated using current assets and current liabilities from the statement of financial position.","D":"Option D is correct because shareholders focus on profitability trends over time and against rivals to evaluate returns on their equity investment."}}},{"id":"P1_U5_MCQ_573","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_573","question":"Why do commercial banks examine a business's statement of profit or loss when evaluating a loan application?","options":{"A":"To decide which suppliers the business should purchase raw materials from","B":"To determine the exact resale value of the business's existing machinery","C":"To calculate how much inventory the business holds in its warehouse","D":"To check whether the business generates sufficient operating profit to afford interest payments and remain viable over the loan period"},"correctOption":"D","correctAnswer":"To check whether the business generates sufficient operating profit to afford interest payments and remain viable over the loan period","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sustained profitability gives lenders confidence that the borrower can service interest obligations and survive long term.","distractor_reasons":{"A":"Incorrect because supplier selection is an operational decision for business managers.","B":"Incorrect because non-current asset values appear on the statement of financial position.","C":"Incorrect because closing inventory values appear on the statement of financial position.","D":"Option D is correct because sustained profitability gives lenders confidence that the borrower can service interest obligations and survive long term."}}},{"id":"P1_U5_MCQ_574","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_574","question":"Why are employees and trade unions interested in reading a company's annual statement of profit or loss?","options":{"A":"To calculate the company's acid-test ratio before approving a share issue","B":"To assess job security and use strong profit figures as evidence when negotiating wage increases or bonuses","C":"To verify whether the company has paid its suppliers within 30 days","D":"To set the government's corporation tax rate for the upcoming year"},"correctOption":"B","correctAnswer":"To assess job security and use strong profit figures as evidence when negotiating wage increases or bonuses","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because rising profits reassure workers that their jobs are safe and strengthen trade union arguments that the employer can afford higher pay.","distractor_reasons":{"A":"Incorrect because liquidity ratios come from the statement of financial position, and share issues are approved by shareholders.","B":"Option B is correct because rising profits reassure workers that their jobs are safe and strengthen trade union arguments that the employer can afford higher pay.","C":"Incorrect because trade payables appear on the statement of financial position.","D":"Incorrect because governments set tax rates, not trade unions."}}},{"id":"P1_U5_MCQ_575","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_575","question":"What is a major limitation of using only a statement of profit or loss to judge a business's financial health?","options":{"A":"It omits all indirect overhead expenses and corporation tax","B":"It only records transactions where physical banknotes changed hands","C":"It shows past profitability rather than cash liquidity or debt burdens, so a highly profitable business could still be close to running out of cash","D":"It is prepared only once every ten years by public limited companies"},"correctOption":"C","correctAnswer":"It shows past profitability rather than cash liquidity or debt burdens, so a highly profitable business could still be close to running out of cash","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the statement of profit or loss does not display cash balances, working capital, or long-term debt liabilities, requiring analysis alongside the statement of financial position.","distractor_reasons":{"A":"Incorrect because overhead expenses and tax are always included on the statement of profit or loss.","B":"Incorrect because credit transactions are included on an accruals basis.","C":"Option C is correct because the statement of profit or loss does not display cash balances, working capital, or long-term debt liabilities, requiring analysis alongside the statement of financial position.","D":"Incorrect because limited companies must prepare financial statements annually."}}},{"id":"P1_U5_MCQ_576","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_576","question":"What is the primary purpose of a 'statement of financial position' (balance sheet)?","options":{"A":"To record total sales revenue, cost of sales, and profit earned across an entire year","B":"To forecast expected monthly cash inflows and outflows for the next 12 months","C":"To calculate the exact break-even level of output for a new product","D":"To show the value of a business's assets, liabilities, and owners' equity at one specific point in time"},"correctOption":"D","correctAnswer":"To show the value of a business's assets, liabilities, and owners' equity at one specific point in time","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the statement of financial position details what the business owns (assets), what it owes (liabilities), and how it is financed (equity) on the reporting date.","distractor_reasons":{"A":"Incorrect because revenue and profit over a year are shown on the statement of profit or loss.","B":"Incorrect because future monthly cash movements are shown on a cash flow forecast.","C":"Incorrect because break-even analysis is a separate cost-volume-profit management tool.","D":"Option D is correct because the statement of financial position details what the business owns (assets), what it owes (liabilities), and how it is financed (equity) on the reporting date."}}},{"id":"P1_U5_MCQ_577","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_577","question":"Why is a statement of financial position often described as a 'financial snapshot'?","options":{"A":"Because its numbers are legally fixed and never change across consecutive years","B":"Because it includes photographs of all factories and vehicles owned by the firm","C":"Because it only measures transactions that take place during a single 24-hour trading day","D":"Because its figures are only valid on the exact date it is drawn up, since trading transactions change asset, liability, and cash balances the very next day"},"correctOption":"D","correctAnswer":"Because its figures are only valid on the exact date it is drawn up, since trading transactions change asset, liability, and cash balances the very next day","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because unlike flow statements (income statement and cash flow forecast) that cover a period, the statement of financial position captures balances at a single instant in time.","distractor_reasons":{"A":"Incorrect because asset, debt, and reserve balances change continuously as the business operates.","B":"Incorrect because it is a quantitative financial table, not a set of photographs.","C":"Incorrect because the balances reflect cumulative positions built up over time up to that date.","D":"Option D is correct because unlike flow statements (income statement and cash flow forecast) that cover a period, the statement of financial position captures balances at a single instant in time."}}},{"id":"P1_U5_MCQ_578","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_578","question":"What are 'assets' on a statement of financial position?","options":{"A":"Debts and financial obligations that the business owes to external creditors and banks","B":"Items of monetary value that are owned by the business, such as property, equipment, inventories, trade receivables, and cash","C":"The indirect overhead expenses incurred in running the business during the year","D":"Dividends paid out to ordinary shareholders"},"correctOption":"B","correctAnswer":"Items of monetary value that are owned by the business, such as property, equipment, inventories, trade receivables, and cash","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because assets are economic resources controlled/owned by the business that provide future economic benefit.","distractor_reasons":{"A":"Incorrect because amounts owed to external parties are liabilities.","B":"Option B is correct because assets are economic resources controlled/owned by the business that provide future economic benefit.","C":"Incorrect because running costs are expenses on the statement of profit or loss.","D":"Incorrect because dividends are distributions of profit to owners."}}},{"id":"P1_U5_MCQ_579","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_579","question":"What are 'liabilities' on a statement of financial position?","options":{"A":"Physical resources owned by the business for more than one year","B":"Unpaid invoices owed to the business by its credit customers","C":"Debts and financial obligations owed by the business to outside parties, such as suppliers, banks, and tax authorities","D":"The retained profits accumulated inside the business over previous years"},"correctOption":"C","correctAnswer":"Debts and financial obligations owed by the business to outside parties, such as suppliers, banks, and tax authorities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because liabilities represent external claims against the business's assets that must be settled in the short or long term.","distractor_reasons":{"A":"Incorrect because long-term physical resources owned by the business are non-current assets.","B":"Incorrect because money owed by customers is trade receivables (a current asset).","C":"Option C is correct because liabilities represent external claims against the business's assets that must be settled in the short or long term.","D":"Incorrect because retained profit forms part of owners' equity, not an external debt liability."}}},{"id":"P1_U5_MCQ_580","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_580","question":"How are 'non-current assets' (fixed assets) defined?","options":{"A":"Short-term assets that are expected to be converted into cash within 12 months","B":"Debts that must be repaid to suppliers within 30 days","C":"The share capital invested by the founders of the company","D":"Long-term resources owned and used by a business for more than one year to generate income, rather than held for immediate resale"},"correctOption":"D","correctAnswer":"Long-term resources owned and used by a business for more than one year to generate income, rather than held for immediate resale","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because non-current assets have a useful life exceeding one year and support ongoing operations (such as land, buildings, vehicles, and machinery).","distractor_reasons":{"A":"Incorrect because assets converted into cash within 12 months are current assets.","B":"Incorrect because short-term supplier debts are current liabilities (trade payables).","C":"Incorrect because share capital is equity.","D":"Option D is correct because non-current assets have a useful life exceeding one year and support ongoing operations (such as land, buildings, vehicles, and machinery)."}}},{"id":"P1_U5_MCQ_581","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_581","question":"Which group consists ENTIRELY of 'non-current assets'?","options":{"A":"Production machinery, 10-year bank loan, and freehold land","B":"Delivery vehicles, raw material inventory, and cash at bank","C":"Factory buildings, trade receivables, and office computers","D":"Freehold factory land, warehouse buildings, production machinery, and delivery vehicles"},"correctOption":"D","correctAnswer":"Freehold factory land, warehouse buildings, production machinery, and delivery vehicles","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because land, buildings, machinery, and vehicles are all long-term assets retained in the business for more than one year.","distractor_reasons":{"A":"Incorrect because a 10-year bank loan is a non-current liability.","B":"Incorrect because raw material inventory and cash at bank are current assets.","C":"Incorrect because trade receivables are current assets.","D":"Option D is correct because land, buildings, machinery, and vehicles are all long-term assets retained in the business for more than one year."}}},{"id":"P1_U5_MCQ_582","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_582","question":"Why are non-current assets such as machinery and vehicles reduced in value each year on a statement of financial position through 'depreciation'?","options":{"A":"Because the business sells a small percentage of its machinery every month","B":"Because non-current assets lose value over time due to wear and tear, usage, and technological obsolescence","C":"Because inflation automatically lowers the market price of all machinery every year","D":"Because depreciation increases the cash balance in the bank account"},"correctOption":"B","correctAnswer":"Because non-current assets lose value over time due to wear and tear, usage, and technological obsolescence","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because depreciation allocates the cost of a non-current asset over its useful working life to reflect loss of value from aging, wear, and newer technology.","distractor_reasons":{"A":"Incorrect because the business keeps using the machinery; depreciation is an accounting valuation adjustment.","B":"Option B is correct because depreciation allocates the cost of a non-current asset over its useful working life to reflect loss of value from aging, wear, and newer technology.","C":"Incorrect because inflation generally pushes prices up, whereas depreciation accounts for asset wear and obsolescence.","D":"Incorrect because depreciation is a non-cash expense that has no effect on cash."}}},{"id":"P1_U5_MCQ_583","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_583","question":"How are 'current assets' defined on a statement of financial position?","options":{"A":"Long-term property and machinery used for more than five years","B":"Short-term debts owed by the business that must be paid within 12 months","C":"Assets owned by the business that are already cash or are expected to be sold or converted into cash within 12 months","D":"Permanent capital contributed by ordinary shareholders"},"correctOption":"C","correctAnswer":"Assets owned by the business that are already cash or are expected to be sold or converted into cash within 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because current assets are short-term working resources (inventories, trade receivables, and cash) that circulate continuously within a one-year trading cycle.","distractor_reasons":{"A":"Incorrect because long-term property and machinery are non-current assets.","B":"Incorrect because short-term debts owed by the business are current liabilities.","C":"Option C is correct because current assets are short-term working resources (inventories, trade receivables, and cash) that circulate continuously within a one-year trading cycle.","D":"Incorrect because shareholder contributions are share capital (equity)."}}},{"id":"P1_U5_MCQ_584","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_584","question":"In what order are 'current assets' normally listed on a statement of financial position from least liquid to most liquid?","options":{"A":"Cash -> Trade receivables -> Inventories","B":"Trade receivables -> Cash -> Inventories","C":"Inventories -> Cash -> Trade receivables","D":"Inventories -> Trade receivables -> Cash"},"correctOption":"D","correctAnswer":"Inventories -> Trade receivables -> Cash","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because inventories must first be sold (often on credit) to become trade receivables, which are then collected to become cash, the most liquid asset.","distractor_reasons":{"A":"Incorrect because this lists current assets from most liquid to least liquid.","B":"Incorrect because cash is already completely liquid, whereas receivables still await collection.","C":"Incorrect because trade receivables convert into cash sooner than unsold inventories.","D":"Option D is correct because inventories must first be sold (often on credit) to become trade receivables, which are then collected to become cash, the most liquid asset."}}},{"id":"P1_U5_MCQ_585","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_585","question":"What are 'trade receivables' (debtors) on a statement of financial position?","options":{"A":"Unsold finished goods stored in the business's warehouse","B":"Amounts of money owed by the business to its raw-material suppliers, classified as a current liability","C":"Long-term loans owed by the business to commercial banks","D":"Amounts of money owed to the business by customers who have purchased goods on credit, classified as a current asset"},"correctOption":"D","correctAnswer":"Amounts of money owed to the business by customers who have purchased goods on credit, classified as a current asset","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade receivables represent short-term sums due from credit customers that will convert into cash within the credit period.","distractor_reasons":{"A":"Incorrect because unsold finished goods are inventories.","B":"Incorrect because amounts owed to suppliers are trade payables (current liabilities).","C":"Incorrect because long-term bank loans are non-current liabilities.","D":"Option D is correct because trade receivables represent short-term sums due from credit customers that will convert into cash within the credit period."}}},{"id":"P1_U5_MCQ_586","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_586","question":"Which items are included under 'inventories' (stock) on a manufacturing company's statement of financial position?","options":{"A":"Factory machinery, delivery vans, and office computers","B":"Raw materials, work-in-progress (part-finished goods), and unsold finished goods","C":"Unpaid customer invoices and bank overdrafts","D":"Issued share capital and retained profit reserves"},"correctOption":"B","correctAnswer":"Raw materials, work-in-progress (part-finished goods), and unsold finished goods","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a manufacturer holds inventory across three stages of production: raw materials awaiting use, semi-finished work-in-progress, and finished goods ready for sale.","distractor_reasons":{"A":"Incorrect because machinery, vans, and computers are non-current assets.","B":"Option B is correct because a manufacturer holds inventory across three stages of production: raw materials awaiting use, semi-finished work-in-progress, and finished goods ready for sale.","C":"Incorrect because unpaid customer invoices are trade receivables and bank overdrafts are current liabilities.","D":"Incorrect because share capital and retained profit are shareholders' equity."}}},{"id":"P1_U5_MCQ_587","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_587","question":"How are 'current liabilities' defined?","options":{"A":"Long-term mortgages and debentures repayable over more than one year","B":"Short-term assets such as cash and trade receivables","C":"Short-term debts and financial obligations owed by a business that must be paid within 12 months","D":"The total amount of money invested in the business by its owners"},"correctOption":"C","correctAnswer":"Short-term debts and financial obligations owed by a business that must be paid within 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because current liabilities are obligations falling due within the next accounting year, such as trade payables and bank overdrafts.","distractor_reasons":{"A":"Incorrect because debts repayable over more than one year are non-current liabilities.","B":"Incorrect because cash and trade receivables are current assets.","C":"Option C is correct because current liabilities are obligations falling due within the next accounting year, such as trade payables and bank overdrafts.","D":"Incorrect because owner investments form equity."}}},{"id":"P1_U5_MCQ_588","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_588","question":"Which group consists ENTIRELY of 'current liabilities'?","options":{"A":"Trade payables, trade receivables, and cash at bank","B":"Bank overdraft, 15-year mortgage, and unpaid corporation tax","C":"Retained profit, trade payables, and bank overdraft","D":"Trade payables, bank overdraft, and unpaid short-term tax or utility bills"},"correctOption":"D","correctAnswer":"Trade payables, bank overdraft, and unpaid short-term tax or utility bills","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade payables, bank overdrafts, and unpaid short-term bills are all debts due for settlement within one year.","distractor_reasons":{"A":"Incorrect because trade receivables and cash at bank are current assets.","B":"Incorrect because a 15-year mortgage is a non-current liability.","C":"Incorrect because retained profit is shareholders' equity.","D":"Option D is correct because trade payables, bank overdrafts, and unpaid short-term bills are all debts due for settlement within one year."}}},{"id":"P1_U5_MCQ_589","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_589","question":"What are 'trade payables' (creditors) on a statement of financial position?","options":{"A":"Amounts of money owed by the business to suppliers for goods or raw materials bought on credit, classified as a current liability","B":"Amounts of money owed to the business by customers who bought goods on credit, classified as a current asset","C":"Dividends owed to shareholders from five years ago","D":"Freehold property owned by the business"},"correctOption":"A","correctAnswer":"Amounts of money owed by the business to suppliers for goods or raw materials bought on credit, classified as a current liability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade payables arise when a business uses trade credit from suppliers and must settle those invoices within the agreed short-term credit period.","distractor_reasons":{"A":"Option A is correct because trade payables arise when a business uses trade credit from suppliers and must settle those invoices within the agreed short-term credit period.","B":"Incorrect because amounts owed by credit customers are trade receivables (current assets).","C":"Incorrect because trade payables relate to commercial supplier purchases, not historical dividends.","D":"Incorrect because freehold property is a non-current asset."}}},{"id":"P1_U5_MCQ_590","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_590","question":"How are 'non-current liabilities' defined?","options":{"A":"Supplier invoices that must be paid within 30 days","B":"Long-term debts owed by a business that are repayable over a period of more than one year","C":"Long-term physical machinery owned by the business","D":"Permanent share capital issued to ordinary shareholders"},"correctOption":"B","correctAnswer":"Long-term debts owed by a business that are repayable over a period of more than one year","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-current liabilities represent long-term borrowed funds (repayable after more than 12 months) used to finance long-term business operations.","distractor_reasons":{"A":"Incorrect because 30-day supplier invoices are current liabilities (trade payables).","B":"Option B is correct because non-current liabilities represent long-term borrowed funds (repayable after more than 12 months) used to finance long-term business operations.","C":"Incorrect because machinery owned by the business is a non-current asset.","D":"Incorrect because share capital is equity, which never has to be repaid."}}},{"id":"P1_U5_MCQ_591","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_591","question":"Which group consists ENTIRELY of 'non-current liabilities'?","options":{"A":"Bank overdraft, trade payables, and long-term bank loan","B":"Share capital, retained profit, and debentures","C":"Long-term bank loans, commercial property mortgages, and debentures","D":"Freehold land, commercial mortgages, and delivery vehicles"},"correctOption":"C","correctAnswer":"Long-term bank loans, commercial property mortgages, and debentures","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because long-term bank loans, mortgages, and debentures are all long-term external debt obligations repayable over more than one year.","distractor_reasons":{"A":"Incorrect because a bank overdraft and trade payables are current liabilities.","B":"Incorrect because share capital and retained profit are shareholders' equity.","C":"Option C is correct because long-term bank loans, mortgages, and debentures are all long-term external debt obligations repayable over more than one year.","D":"Incorrect because freehold land and delivery vehicles are non-current assets."}}},{"id":"P1_U5_MCQ_592","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_592","question":"How is 'working capital' (net current assets) calculated on a statement of financial position?","options":{"A":"Non-current assets - Non-current liabilities","B":"Total assets - Total liabilities","C":"Current assets + Current liabilities","D":"Current assets - Current liabilities"},"correctOption":"D","correctAnswer":"Current assets - Current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because working capital (net current assets) measures the short-term liquid resources remaining after covering all short-term liabilities due within 12 months.","distractor_reasons":{"A":"Incorrect because working capital only involves short-term current items, not non-current items.","B":"Incorrect because total assets minus total liabilities calculates net assets.","C":"Incorrect because current liabilities must be subtracted from current assets, not added.","D":"Option D is correct because working capital (net current assets) measures the short-term liquid resources remaining after covering all short-term liabilities due within 12 months."}}},{"id":"P1_U5_MCQ_593","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_593","question":"How is 'net assets' calculated on a statement of financial position?","options":{"A":"Total assets - Total liabilities (or Non-current assets + Working capital - Non-current liabilities)","B":"Non-current assets + Current assets","C":"Current assets - Current liabilities","D":"Non-current liabilities + Current liabilities"},"correctOption":"A","correctAnswer":"Total assets - Total liabilities (or Non-current assets + Working capital - Non-current liabilities)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because net assets represents the net wealth of the business belonging to its owners after deducting all short-term and long-term debts from total assets.","distractor_reasons":{"A":"Option A is correct because net assets represents the net wealth of the business belonging to its owners after deducting all short-term and long-term debts from total assets.","B":"Incorrect because non-current assets plus current assets equals total assets before deducting liabilities.","C":"Incorrect because current assets minus current liabilities calculates working capital (net current assets).","D":"Incorrect because adding non-current and current liabilities equals total liabilities."}}},{"id":"P1_U5_MCQ_594","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_594","question":"What are the two main components of 'total shareholders' equity' on a limited company's statement of financial position?","options":{"A":"Non-current assets and current assets","B":"Share capital and retained profit (reserves)","C":"Current liabilities and non-current liabilities","D":"Trade receivables and trade payables"},"correctOption":"B","correctAnswer":"Share capital and retained profit (reserves)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total shareholders' equity represents the owners' total stake in the business, consisting of original share capital plus accumulated retained profits.","distractor_reasons":{"A":"Incorrect because non-current and current assets make up total assets.","B":"Option B is correct because total shareholders' equity represents the owners' total stake in the business, consisting of original share capital plus accumulated retained profits.","C":"Incorrect because current and non-current liabilities make up total external debt.","D":"Incorrect because trade receivables are current assets and trade payables are current liabilities."}}},{"id":"P1_U5_MCQ_595","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_595","question":"How is 'capital employed' calculated from a statement of financial position?","options":{"A":"Current assets - Current liabilities","B":"Share capital + Current liabilities","C":"Total shareholders' equity + Non-current liabilities (which also equals Non-current assets + Working capital)","D":"Total revenue - Cost of sales"},"correctOption":"C","correctAnswer":"Total shareholders' equity + Non-current liabilities (which also equals Non-current assets + Working capital)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed represents all long-term permanent funds invested in the business (owners' equity plus long-term borrowing).","distractor_reasons":{"A":"Incorrect because current assets minus current liabilities is working capital.","B":"Incorrect because short-term current liabilities are excluded from long-term capital employed.","C":"Option C is correct because capital employed represents all long-term permanent funds invested in the business (owners' equity plus long-term borrowing).","D":"Incorrect because revenue minus cost of sales is gross profit."}}},{"id":"P1_U5_MCQ_596","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_596","question":"Why must a statement of financial position always 'balance'?","options":{"A":"Because cash inflows must always equal cash outflows every year","B":"Because gross profit must always equal overhead expenses","C":"Because current assets must always equal current liabilities","D":"Because every asset owned by the business is financed either by external liabilities or by owners' equity (Net assets = Total equity)"},"correctOption":"D","correctAnswer":"Because every asset owned by the business is financed either by external liabilities or by owners' equity (Net assets = Total equity)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because of the fundamental accounting identity (Assets = Liabilities + Equity, or Net assets = Total equity), reflecting dual-entry bookkeeping.","distractor_reasons":{"A":"Incorrect because cash inflows rarely equal outflows; differences change the closing cash balance.","B":"Incorrect because if gross profit equaled overheads, profit would always be zero.","C":"Incorrect because healthy businesses normally have current assets greater than current liabilities.","D":"Option D is correct because of the fundamental accounting identity (Assets = Liabilities + Equity, or Net assets = Total equity), reflecting dual-entry bookkeeping."}}},{"id":"P1_U5_MCQ_597","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_597","question":"How are the statement of profit or loss and the statement of financial position directly linked at the end of a financial year?","options":{"A":"The sales revenue figure replaces the cash balance on the statement of financial position","B":"The gross profit figure is recorded as a non-current liability on the statement of financial position","C":"The total overhead expenses are added to non-current assets on the statement of financial position","D":"The retained profit calculated at the bottom of the statement of profit or loss is added to the retained profit reserve under shareholders' equity on the statement of financial position"},"correctOption":"D","correctAnswer":"The retained profit calculated at the bottom of the statement of profit or loss is added to the retained profit reserve under shareholders' equity on the statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retained profit earned during the year increases the accumulated equity reserves owned by shareholders on the year-end statement of financial position.","distractor_reasons":{"A":"Incorrect because revenue includes credit sales and is not the year-end cash balance.","B":"Incorrect because gross profit is an income statement subtotal, not a debt liability.","C":"Incorrect because overhead expenses reduce profit rather than creating non-current assets.","D":"Option D is correct because retained profit earned during the year increases the accumulated equity reserves owned by shareholders on the year-end statement of financial position."}}},{"id":"P1_U5_MCQ_598","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_598","question":"Why do commercial banks examine a company's statement of financial position before approving a long-term loan?","options":{"A":"To check the company's gross profit margin on individual product lines","B":"To see what valuable non-current assets could serve as loan security (collateral) and how much debt the company already owes","C":"To calculate how many employees work in the company's marketing department","D":"To replace the need for a forward-looking cash flow forecast"},"correctOption":"B","correctAnswer":"To see what valuable non-current assets could serve as loan security (collateral) and how much debt the company already owes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because banks assess asset backing for collateral and inspect existing current and non-current liabilities to judge default risk.","distractor_reasons":{"A":"Incorrect because gross profit margin is calculated from the statement of profit or loss.","B":"Option B is correct because banks assess asset backing for collateral and inspect existing current and non-current liabilities to judge default risk.","C":"Incorrect because headcount is not reported on the statement of financial position.","D":"Incorrect because lenders examine both the statement of financial position and cash flow forecasts."}}},{"id":"P1_U5_MCQ_599","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_599","question":"Why do trade suppliers inspect a customer's statement of financial position before granting 60-day trade credit?","options":{"A":"To calculate the customer's annual corporation tax liability","B":"To check whether the customer's shareholders receive high dividends","C":"To verify that the customer holds enough liquid current assets (such as cash and receivables) relative to current liabilities to pay invoices on time","D":"To determine the customer's exact advertising budget"},"correctOption":"C","correctAnswer":"To verify that the customer holds enough liquid current assets (such as cash and receivables) relative to current liabilities to pay invoices on time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because suppliers risk non-payment if a buyer has negative working capital or severe short-term liquidity shortages.","distractor_reasons":{"A":"Incorrect because tax calculations belong to tax authorities.","B":"Incorrect because suppliers care about short-term bill-paying ability rather than shareholder dividend payouts.","C":"Option C is correct because suppliers risk non-payment if a buyer has negative working capital or severe short-term liquidity shortages.","D":"Incorrect because advertising budgets are internal marketing figures."}}},{"id":"P1_U5_MCQ_600","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_600","question":"What is a major limitation of a statement of financial position when judging the true worth of a business?","options":{"A":"It omits all current liabilities and bank overdrafts","B":"It records assets at their exact future selling prices ten years from now","C":"It is legally required to exclude cash and trade receivables","D":"Non-current assets are recorded at historical cost minus depreciation rather than current market value, and valuable intangible strengths like brand reputation or skilled staff are omitted"},"correctOption":"D","correctAnswer":"Non-current assets are recorded at historical cost minus depreciation rather than current market value, and valuable intangible strengths like brand reputation or skilled staff are omitted","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because historical cost accounting can understate rising property values, and financial statements exclude non-monetary qualitative assets such as workforce skill and brand loyalty.","distractor_reasons":{"A":"Incorrect because all current liabilities and overdrafts must be included.","B":"Incorrect because statements record historical cost values rather than speculative future prices.","C":"Incorrect because cash and trade receivables are core components of current assets.","D":"Option D is correct because historical cost accounting can understate rising property values, and financial statements exclude non-monetary qualitative assets such as workforce skill and brand loyalty."}}},{"id":"P1_U5_MCQ_601","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_601","question":"What is the main purpose of calculating 'financial ratios' from a business's accounts?","options":{"A":"To convert raw dollar figures into relative percentages or proportions so performance and liquidity can be meaningfully compared across time and against competitors","B":"To replace the legal requirement to prepare a statement of profit or loss and statement of financial position","C":"To guarantee that the business will earn higher profits next year","D":"To eliminate all corporation tax and interest expenses"},"correctOption":"A","correctAnswer":"To convert raw dollar figures into relative percentages or proportions so performance and liquidity can be meaningfully compared across time and against competitors","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because raw dollar profit or asset totals mean little in isolation; ratios standardize performance relative to revenue, capital, or liabilities.","distractor_reasons":{"A":"Option A is correct because raw dollar profit or asset totals mean little in isolation; ratios standardize performance relative to revenue, capital, or liabilities.","B":"Incorrect because ratios are calculated from completed financial statements rather than replacing them.","C":"Incorrect because ratios are analytical tools that cannot guarantee future financial results.","D":"Incorrect because ratios measure financial figures without altering tax or interest obligations."}}},{"id":"P1_U5_MCQ_602","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_602","question":"Which two comparisons make financial ratio analysis most useful to managers and investors?","options":{"A":"Comparing a local retail shop's ratios with a multinational oil corporation and a public hospital","B":"Comparing a business's ratios over several consecutive years (trend analysis) and comparing them with competitors in the same industry (inter-firm comparison)","C":"Comparing gross profit margin with the number of factory employees","D":"Comparing current ratio with the company's total share price"},"correctOption":"B","correctAnswer":"Comparing a business's ratios over several consecutive years (trend analysis) and comparing them with competitors in the same industry (inter-firm comparison)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because tracking trends over time reveals whether performance is improving or deteriorating, while benchmarking against same-industry rivals shows competitive standing.","distractor_reasons":{"A":"Incorrect because valid inter-firm comparisons must compare businesses of similar size in the same industry.","B":"Option B is correct because tracking trends over time reveals whether performance is improving or deteriorating, while benchmarking against same-industry rivals shows competitive standing.","C":"Incorrect because comparing a percentage margin to headcount is not a meaningful financial benchmark.","D":"Incorrect because liquidity ratios are benchmarked against standard norms (such as 1.5 : 1 to 2 : 1) and industry peers, not share prices."}}},{"id":"P1_U5_MCQ_603","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_603","question":"What is the correct formula for calculating 'Gross profit margin (%)'?","options":{"A":"(Profit / Revenue) × 100","B":"(Cost of sales / Revenue) × 100","C":"(Gross profit / Revenue) × 100","D":"(Gross profit / Capital employed) × 100"},"correctOption":"C","correctAnswer":"(Gross profit / Revenue) × 100","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because gross profit margin expresses gross profit as a percentage of total sales revenue.","distractor_reasons":{"A":"Incorrect because (Profit / Revenue) × 100 is the formula for profit margin.","B":"Incorrect because (Cost of sales / Revenue) × 100 measures direct costs as a share of sales.","C":"Option C is correct because gross profit margin expresses gross profit as a percentage of total sales revenue.","D":"Incorrect because capital employed is the denominator in Return on Capital Employed (ROCE)."}}},{"id":"P1_U5_MCQ_604","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_604","question":"What does a business's 'gross profit margin' specifically measure?","options":{"A":"How quickly the business can convert its current assets into cash to pay short-term bills","B":"The percentage return generated on all long-term capital invested in the business","C":"The percentage of revenue left after paying all indirect overheads and corporation tax","D":"How much gross profit is earned on every $100 of sales revenue after covering direct cost of sales"},"correctOption":"D","correctAnswer":"How much gross profit is earned on every $100 of sales revenue after covering direct cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because gross profit margin reflects pricing strength and direct production/purchasing cost efficiency before indirect overheads are considered.","distractor_reasons":{"A":"Incorrect because short-term bill-paying ability is measured by liquidity ratios (current and acid-test ratios).","B":"Incorrect because return on invested capital is measured by ROCE.","C":"Incorrect because profit after overheads is measured by profit margin.","D":"Option D is correct because gross profit margin reflects pricing strength and direct production/purchasing cost efficiency before indirect overheads are considered."}}},{"id":"P1_U5_MCQ_605","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_605","question":"What is the correct formula for calculating 'Profit margin (%)'?","options":{"A":"(Overhead expenses / Revenue) × 100","B":"(Gross profit / Revenue) × 100","C":"(Profit / Capital employed) × 100","D":"(Profit / Revenue) × 100"},"correctOption":"D","correctAnswer":"(Profit / Revenue) × 100","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit margin expresses final operating profit (after deducting both cost of sales and overhead expenses) as a percentage of sales revenue.","distractor_reasons":{"A":"Incorrect because this measures overhead expenses as a proportion of sales.","B":"Incorrect because (Gross profit / Revenue) × 100 calculates gross profit margin.","C":"Incorrect because (Profit / Capital employed) × 100 calculates Return on Capital Employed (ROCE).","D":"Option D is correct because profit margin expresses final operating profit (after deducting both cost of sales and overhead expenses) as a percentage of sales revenue."}}},{"id":"P1_U5_MCQ_606","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_606","question":"If a business's gross profit margin remains steady over two years while its profit margin falls significantly, what does this indicate?","options":{"A":"Direct raw material prices have doubled while indirect overheads fell","B":"Indirect overhead expenses (such as rent, marketing, or administrative salaries) have risen faster than sales revenue","C":"The business has taken on too many long-term non-current liabilities","D":"The business's current ratio has risen above 2 : 1"},"correctOption":"B","correctAnswer":"Indirect overhead expenses (such as rent, marketing, or administrative salaries) have risen faster than sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the gap between gross profit margin and profit margin represents indirect overhead expenses as a percentage of revenue.","distractor_reasons":{"A":"Incorrect because higher raw material prices would have reduced gross profit margin.","B":"Option B is correct because the gap between gross profit margin and profit margin represents indirect overhead expenses as a percentage of revenue.","C":"Incorrect because non-current liabilities affect ROCE rather than operating profit margin.","D":"Incorrect because liquidity ratios do not explain the gap between gross profit margin and profit margin."}}},{"id":"P1_U5_MCQ_607","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_607","question":"What is the correct formula for calculating 'Return on Capital Employed (ROCE) (%)'?","options":{"A":"(Gross profit / Revenue) × 100","B":"(Profit / Current assets) × 100","C":"(Profit / Capital employed) × 100","D":"(Capital employed / Profit) × 100"},"correctOption":"C","correctAnswer":"(Profit / Capital employed) × 100","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ROCE measures the percentage profit generated relative to the total long-term capital invested in the business (Shareholders' equity + Non-current liabilities).","distractor_reasons":{"A":"Incorrect because this is the formula for gross profit margin.","B":"Incorrect because ROCE uses total long-term capital employed, not short-term current assets.","C":"Option C is correct because ROCE measures the percentage profit generated relative to the total long-term capital invested in the business (Shareholders' equity + Non-current liabilities).","D":"Incorrect because this inverts the ROCE formula."}}},{"id":"P1_U5_MCQ_608","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_608","question":"Why is 'Return on Capital Employed (ROCE)' often regarded as the most comprehensive indicator of a business's overall profitability?","options":{"A":"Because it measures whether the business holds enough physical cash to pay next week's supplier bills","B":"Because it ignores all overhead expenses and taxes","C":"Because it measures only the direct mark-up on goods sold","D":"Because it compares profit earned against the total amount of capital invested, allowing comparison across businesses of different sizes and with alternative investments"},"correctOption":"D","correctAnswer":"Because it compares profit earned against the total amount of capital invested, allowing comparison across businesses of different sizes and with alternative investments","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ROCE shows how efficiently management uses all funds invested by owners and long-term lenders to generate profit.","distractor_reasons":{"A":"Incorrect because short-term liquidity is measured by the current and acid-test ratios.","B":"Incorrect because operating profit in the numerator already deducts overhead expenses.","C":"Incorrect because direct trading mark-up is reflected in gross profit margin.","D":"Option D is correct because ROCE shows how efficiently management uses all funds invested by owners and long-term lenders to generate profit."}}},{"id":"P1_U5_MCQ_609","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_609","question":"How do shareholders and managers judge whether a calculated 'ROCE' percentage is satisfactory?","options":{"A":"By comparing it with the business's ROCE in previous years, the ROCE of competitors in the same industry, and prevailing bank deposit or borrowing interest rates","B":"By checking whether it is lower than the interest rate paid on a risk-free bank savings account","C":"By checking whether it is identical to the business's current ratio","D":"By ensuring it is always below 1%"},"correctOption":"A","correctAnswer":"By comparing it with the business's ROCE in previous years, the ROCE of competitors in the same industry, and prevailing bank deposit or borrowing interest rates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a satisfactory ROCE should rise over time, compare well with industry rivals, and comfortably exceed risk-free savings rates and loan interest costs.","distractor_reasons":{"A":"Option A is correct because a satisfactory ROCE should rise over time, compare well with industry rivals, and comfortably exceed risk-free savings rates and loan interest costs.","B":"Incorrect because earning less than a safe bank deposit indicates poor capital efficiency.","C":"Incorrect because ROCE is a percentage return on capital, whereas the current ratio is a liquidity proportion.","D":"Incorrect because an ROCE below 1% is extremely weak."}}},{"id":"P1_U5_MCQ_610","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_610","question":"What is meant by 'liquidity' in financial analysis?","options":{"A":"The total amount of profit retained in the business over ten years","B":"The ability of a business to pay its short-term debts and day-to-day bills as they fall due using cash and assets that can quickly be converted into cash","C":"The total value of freehold land and factories owned by a company","D":"The percentage of sales revenue left after deducting cost of sales"},"correctOption":"B","correctAnswer":"The ability of a business to pay its short-term debts and day-to-day bills as they fall due using cash and assets that can quickly be converted into cash","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because liquidity measures short-term solvency—having sufficient accessible cash or near-cash current assets to meet immediate liabilities.","distractor_reasons":{"A":"Incorrect because retained profit is an equity reserve, not liquidity.","B":"Option B is correct because liquidity measures short-term solvency—having sufficient accessible cash or near-cash current assets to meet immediate liabilities.","C":"Incorrect because freehold land and factories are illiquid non-current assets.","D":"Incorrect because revenue minus cost of sales percentage is gross profit margin."}}},{"id":"P1_U5_MCQ_611","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_611","question":"What is the correct formula for calculating the 'Current ratio'?","options":{"A":"Current liabilities / Current assets","B":"(Current assets - Inventories) / Current liabilities","C":"Current assets / Current liabilities","D":"Total assets / Total liabilities"},"correctOption":"C","correctAnswer":"Current assets / Current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the current ratio compares all current assets against all current liabilities (usually expressed as X : 1).","distractor_reasons":{"A":"Incorrect because this inverts the current ratio formula.","B":"Incorrect because subtracting inventories gives the acid-test (quick) ratio.","C":"Option C is correct because the current ratio compares all current assets against all current liabilities (usually expressed as X : 1).","D":"Incorrect because total assets and total liabilities include non-current items excluded from short-term liquidity ratios."}}},{"id":"P1_U5_MCQ_612","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_612","question":"What does a 'current ratio' below 1 : 1 indicate about a business's financial position?","options":{"A":"The business is earning exceptionally high gross profit margins","B":"The business holds excessive idle cash in its bank current account","C":"The business has zero short-term debts","D":"The business's current liabilities exceed its current assets (negative working capital), creating a high risk of cash flow and bill-paying difficulties"},"correctOption":"D","correctAnswer":"The business's current liabilities exceed its current assets (negative working capital), creating a high risk of cash flow and bill-paying difficulties","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a current ratio under 1 : 1 means that even if all short-term assets were turned into cash, they would not cover debts due within 12 months.","distractor_reasons":{"A":"Incorrect because liquidity ratios do not measure gross profit margins.","B":"Incorrect because a ratio below 1 : 1 signals a shortage, not an excess, of current assets.","C":"Incorrect because zero current liabilities would make the denominator zero, not produce a ratio under 1 : 1.","D":"Option D is correct because a current ratio under 1 : 1 means that even if all short-term assets were turned into cash, they would not cover debts due within 12 months."}}},{"id":"P1_U5_MCQ_613","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_613","question":"Why might financial analysts criticize a business whose 'current ratio' is excessively high (for example, well above 2 : 1)?","options":{"A":"It indicates that the business is making a trading loss","B":"It proves the business is about to go bankrupt within a month","C":"It means the business has too many non-current liabilities","D":"It suggests too much working capital is tied up unproductively in excessive inventories, slow-paying receivables, or low-interest cash instead of being invested to earn higher returns"},"correctOption":"D","correctAnswer":"It suggests too much working capital is tied up unproductively in excessive inventories, slow-paying receivables, or low-interest cash instead of being invested to earn higher returns","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because holding far more current assets than needed to cover short-term bills creates an opportunity cost and reduces overall ROCE.","distractor_reasons":{"A":"Incorrect because liquidity ratios do not measure trading profit or loss.","B":"Incorrect because a high current ratio indicates ample short-term asset coverage, not imminent insolvency.","C":"Incorrect because non-current liabilities do not enter the current ratio.","D":"Option D is correct because holding far more current assets than needed to cover short-term bills creates an opportunity cost and reduces overall ROCE."}}},{"id":"P1_U5_MCQ_614","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_614","question":"What is the correct formula for calculating the 'Acid-test (quick) ratio'?","options":{"A":"Current assets / Current liabilities","B":"(Current assets - Inventories) / Current liabilities","C":"(Current assets - Trade receivables) / Current liabilities","D":"Cash / Non-current liabilities"},"correctOption":"B","correctAnswer":"(Current assets - Inventories) / Current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the acid-test ratio strips out inventories from current assets to compare only the most liquid assets (cash and trade receivables) against current liabilities.","distractor_reasons":{"A":"Incorrect because including inventories gives the current ratio.","B":"Option B is correct because the acid-test ratio strips out inventories from current assets to compare only the most liquid assets (cash and trade receivables) against current liabilities.","C":"Incorrect because trade receivables are liquid assets retained in the numerator, whereas inventories are subtracted.","D":"Incorrect because liquidity ratios use current liabilities, not non-current liabilities, as the denominator."}}},{"id":"P1_U5_MCQ_615","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_615","question":"Why are 'inventories' subtracted from current assets when calculating the 'acid-test ratio'?","options":{"A":"Because inventories are classified as non-current assets on the statement of financial position","B":"Because inventories are actually a current liability owed to suppliers","C":"Because inventories are the least liquid current asset and cannot always be quickly converted into cash without heavy discounting or risk of spoilage/obsolescence","D":"Because inventories are never insured against theft or fire"},"correctOption":"C","correctAnswer":"Because inventories are the least liquid current asset and cannot always be quickly converted into cash without heavy discounting or risk of spoilage/obsolescence","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unsold stock must first find buyers before generating cash, making the acid-test ratio a stricter test of immediate liquidity.","distractor_reasons":{"A":"Incorrect because inventories are current assets, just the least liquid ones.","B":"Incorrect because inventories are assets owned by the business, not liabilities.","C":"Option C is correct because unsold stock must first find buyers before generating cash, making the acid-test ratio a stricter test of immediate liquidity.","D":"Incorrect because businesses routinely insure their inventories."}}},{"id":"P1_U5_MCQ_616","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_616","question":"If a business has a healthy current ratio (around 2 : 1) but a very low acid-test ratio (well below 1 : 1), what does this reveal?","options":{"A":"The business holds almost all of its current assets in physical bank cash","B":"The business has zero trade payables or bank overdrafts","C":"The business's non-current assets are worth less than its current liabilities","D":"A large proportion of the business's current assets is tied up in unsold inventories, leaving insufficient liquid cash and receivables to pay immediate short-term debts"},"correctOption":"D","correctAnswer":"A large proportion of the business's current assets is tied up in unsold inventories, leaving insufficient liquid cash and receivables to pay immediate short-term debts","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the large drop between the current ratio and the acid-test ratio is entirely caused by high inventory levels.","distractor_reasons":{"A":"Incorrect because high bank cash would produce a high acid-test ratio as well.","B":"Incorrect because zero current liabilities would not yield a low acid-test ratio.","C":"Incorrect because neither ratio includes non-current assets.","D":"Option D is correct because the large drop between the current ratio and the acid-test ratio is entirely caused by high inventory levels."}}},{"id":"P1_U5_MCQ_617","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_617","question":"Which of the following ratios is used to assess the liquidity, or short-term financial health, of a business?","options":{"A":"The current ratio","B":"The profit margin","C":"The gross profit margin","D":"Return on capital employed (ROCE)"},"correctOption":"A","correctAnswer":"The current ratio","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the current ratio compares current assets with current liabilities and indicates the ability to meet short-term debts.","distractor_reasons":{"A":"Option A is correct because the current ratio compares current assets with current liabilities and indicates the ability to meet short-term debts.","B":"Incorrect because profit margin measures profitability by comparing profit with sales revenue, not short-term liquidity.","C":"Incorrect because gross profit margin measures profitability relative to revenue and says nothing about short-term debts.","D":"Incorrect because ROCE measures how efficiently capital is used to generate profit, which is a profitability measure."}}},{"id":"P1_U5_MCQ_618","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_618","question":"Why do commercial banks and trade suppliers pay close attention to a business's 'liquidity ratios' (current ratio and acid-test ratio)?","options":{"A":"Because banks and suppliers earn a percentage of the business's gross profit instead of fixed payments","B":"To check whether the business holds enough liquid assets to pay invoices, loan interest, and principal repayments on time without defaulting","C":"To decide whether the business should launch a new advertising campaign","D":"To calculate how much corporation tax the business owes the government"},"correctOption":"B","correctAnswer":"To check whether the business holds enough liquid assets to pay invoices, loan interest, and principal repayments on time without defaulting","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because creditors face direct financial loss if a borrowing customer lacks short-term liquidity to honor debts as they fall due.","distractor_reasons":{"A":"Incorrect because creditors receive contractual debt repayments, not equity profit shares.","B":"Option B is correct because creditors face direct financial loss if a borrowing customer lacks short-term liquidity to honor debts as they fall due.","C":"Incorrect because marketing decisions belong to company managers.","D":"Incorrect because corporation tax is calculated from profit figures, not liquidity ratios."}}},{"id":"P1_U5_MCQ_619","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_619","question":"How do internal business managers use financial ratio analysis in decision-making?","options":{"A":"To set national interest rates across the economy","B":"To audit the tax returns of competing companies","C":"To monitor cost control, pricing effectiveness, capital efficiency, and working capital liquidity so corrective action can be taken early","D":"To eliminate the need for market research before launching products"},"correctOption":"C","correctAnswer":"To monitor cost control, pricing effectiveness, capital efficiency, and working capital liquidity so corrective action can be taken early","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal managers track profitability and liquidity ratios regularly to diagnose weaknesses and guide operational and strategic adjustments.","distractor_reasons":{"A":"Incorrect because central banks set national interest rates.","B":"Incorrect because government tax authorities conduct tax audits.","C":"Option C is correct because internal managers track profitability and liquidity ratios regularly to diagnose weaknesses and guide operational and strategic adjustments.","D":"Incorrect because financial ratios complement rather than replace market research."}}},{"id":"P1_U5_MCQ_620","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_620","question":"Why do government tax authorities examine a business's financial accounts?","options":{"A":"To decide whether to grant the business a commercial bank overdraft","B":"To negotiate annual pay increases on behalf of factory workers","C":"To set the retail prices of the business's products","D":"To verify declared profit figures and ensure the correct amount of corporation tax is assessed and collected"},"correctOption":"D","correctAnswer":"To verify declared profit figures and ensure the correct amount of corporation tax is assessed and collected","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because tax authorities rely on accurate income statements to calculate and verify business tax liabilities.","distractor_reasons":{"A":"Incorrect because commercial banks decide on overdraft facilities.","B":"Incorrect because trade unions negotiate worker wages.","C":"Incorrect because businesses set their own retail prices in free markets.","D":"Option D is correct because tax authorities rely on accurate income statements to calculate and verify business tax liabilities."}}},{"id":"P1_U5_MCQ_621","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_621","question":"How can 'competitors' use the published annual accounts of a public limited company (plc)?","options":{"A":"To benchmark their own profit margins, sales growth, and efficiency against the rival firm and identify industry trends","B":"To legally force the rival firm to lower its selling prices","C":"To access the confidential personal bank details of the rival firm's customers","D":"To rewrite the rival firm's statement of financial position"},"correctOption":"A","correctAnswer":"To benchmark their own profit margins, sales growth, and efficiency against the rival firm and identify industry trends","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public limited companies must publish their annual accounts, allowing rivals to compare margins, ROCE, and growth rates.","distractor_reasons":{"A":"Option A is correct because public limited companies must publish their annual accounts, allowing rivals to compare margins, ROCE, and growth rates.","B":"Incorrect because competitors cannot legally dictate a rival's pricing.","C":"Incorrect because published accounts contain summarized corporate totals, not individual customer data.","D":"Incorrect because competitors have no authority over a rival's accounting records."}}},{"id":"P1_U5_MCQ_622","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_622","question":"Why is the 'historical nature' of financial accounts considered a limitation of ratio analysis?","options":{"A":"Because historical accounts omit all sales revenue and cost of sales","B":"Because ratios are calculated from past trading data and cannot guarantee future performance if market conditions, competition, or interest rates change","C":"Because historical accounts are never audited or checked for accuracy","D":"Because historical ratios can only be calculated for businesses that have closed down"},"correctOption":"B","correctAnswer":"Because ratios are calculated from past trading data and cannot guarantee future performance if market conditions, competition, or interest rates change","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because financial statements look backward at completed periods; rapid technological or economic shifts can quickly make past ratios outdated.","distractor_reasons":{"A":"Incorrect because revenue and cost of sales are core figures in historical accounts.","B":"Option B is correct because financial statements look backward at completed periods; rapid technological or economic shifts can quickly make past ratios outdated.","C":"Incorrect because public limited company accounts undergo independent external audits.","D":"Incorrect because ratios are routinely calculated for active, ongoing businesses."}}},{"id":"P1_U5_MCQ_623","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_623","question":"How does 'inflation' limit the reliability of comparing financial accounts over several years?","options":{"A":"Inflation automatically doubles a company's acid-test ratio every year","B":"Inflation forces accountants to omit all overhead expenses","C":"Rising general price levels inflate nominal revenue and asset values over time, making growth appear larger than real increases in sales volume or efficiency","D":"Inflation eliminates all non-current liabilities from the statement of financial position"},"correctOption":"C","correctAnswer":"Rising general price levels inflate nominal revenue and asset values over time, making growth appear larger than real increases in sales volume or efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when prices rise across the economy, higher dollar sales or profit figures may simply reflect inflation rather than genuine real-terms growth.","distractor_reasons":{"A":"Incorrect because inflation does not automatically double liquidity ratios.","B":"Incorrect because all expenses remain recorded during inflation.","C":"Option C is correct because when prices rise across the economy, higher dollar sales or profit figures may simply reflect inflation rather than genuine real-terms growth.","D":"Incorrect because debt obligations remain on the statement of financial position."}}},{"id":"P1_U5_MCQ_624","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_624","question":"Why can differences in 'accounting policies' between two companies distort inter-firm ratio comparisons?","options":{"A":"Because companies using different accounting policies are forbidden from calculating gross profit margin","B":"Because accounting policies determine a company's daily bank cash balance","C":"Because accounting policies only apply to sole traders","D":"Because different methods of valuing inventories or depreciating non-current assets alter reported profit and asset values even when underlying operations are similar"},"correctOption":"D","correctAnswer":"Because different methods of valuing inventories or depreciating non-current assets alter reported profit and asset values even when underlying operations are similar","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because variations in depreciation rates or inventory valuation rules directly affect profit and capital employed, making like-for-like comparison harder.","distractor_reasons":{"A":"Incorrect because all trading businesses can calculate gross profit margin.","B":"Incorrect because accounting valuation policies do not change physical bank cash.","C":"Incorrect because limited companies also apply accounting policies within accounting standards.","D":"Option D is correct because variations in depreciation rates or inventory valuation rules directly affect profit and capital employed, making like-for-like comparison harder."}}},{"id":"P1_U5_MCQ_625","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_625","question":"What is a fundamental limitation of financial ratios when managers are trying to solve declining business performance?","options":{"A":"Ratios are invalid whenever a business holds both current assets and non-current assets","B":"Ratios can only be calculated by external government officials","C":"Ratios ignore all figures from the statement of profit or loss","D":"Ratios identify financial symptoms (such as falling profit margins or weaker liquidity), but do not explain underlying operational causes or qualitative issues like poor product quality or low staff morale"},"correctOption":"D","correctAnswer":"Ratios identify financial symptoms (such as falling profit margins or weaker liquidity), but do not explain underlying operational causes or qualitative issues like poor product quality or low staff morale","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ratios act like a thermometer showing that a problem exists, requiring managers to investigate qualitative operational and market factors to find the root cause.","distractor_reasons":{"A":"Incorrect because virtually all businesses hold both current and non-current assets.","B":"Incorrect because internal managers, investors, and analysts routinely calculate ratios.","C":"Incorrect because profitability ratios rely directly on the statement of profit or loss.","D":"Option D is correct because ratios act like a thermometer showing that a problem exists, requiring managers to investigate qualitative operational and market factors to find the root cause."}}},{"id":"P1_U5_MCQ_626","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_626","question":"Besides starting up a business and funding day-to-day working capital, why do established businesses commonly require finance?","options":{"A":"To fund long-term business expansion, replace worn-out non-current assets, and invest in research and development","B":"To avoid having to prepare annual statements of profit or loss","C":"To eliminate the legal obligation to pay employee wages and salaries","D":"To convert all current liabilities into non-current assets"},"correctOption":"A","correctAnswer":"To fund long-term business expansion, replace worn-out non-current assets, and invest in research and development","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because established firms need capital to grow into new markets, take over rivals, upgrade aging machinery, and develop new products.","distractor_reasons":{"A":"Option A is correct because established firms need capital to grow into new markets, take over rivals, upgrade aging machinery, and develop new products.","B":"Incorrect because raising finance does not exempt a business from statutory financial reporting.","C":"Incorrect because businesses must always pay contracted wages regardless of their financing.","D":"Incorrect because liabilities are debts owed and cannot simply be converted into assets."}}},{"id":"P1_U5_MCQ_627","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_627","question":"How does 'expansion capital' differ from 'start-up capital'?","options":{"A":"Expansion capital is always short-term, whereas start-up capital is always repaid within 30 days","B":"Expansion capital is raised by established businesses to grow operations or acquire other firms, whereas start-up capital is needed before a new business begins trading","C":"Expansion capital can only come from personal savings, whereas start-up capital can only come from stock market share issues","D":"Expansion capital is used only for paying electricity bills, whereas start-up capital is used only for paying dividends"},"correctOption":"B","correctAnswer":"Expansion capital is raised by established businesses to grow operations or acquire other firms, whereas start-up capital is needed before a new business begins trading","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because start-up capital funds initial set-up before trading begins, whereas expansion capital funds growth once a business is established.","distractor_reasons":{"A":"Incorrect because both start-up capital and expansion capital are typically long-term funding needs.","B":"Option B is correct because start-up capital funds initial set-up before trading begins, whereas expansion capital funds growth once a business is established.","C":"Incorrect because start-ups cannot issue shares on a public stock exchange, while established firms can use retained profit, loans, or share issues.","D":"Incorrect because electricity bills are working capital expenses and new start-ups do not pay dividends before trading."}}},{"id":"P1_U5_MCQ_628","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_628","question":"Why is 'working capital' essential for bridging the time gap in a trading business?","options":{"A":"Because customers always pay months before raw materials are purchased","B":"Because commercial banks forbid businesses from holding cash in current accounts","C":"Because a business must pay for raw materials, wages, and running costs before it receives cash payments from customers who buy on credit","D":"Because working capital is used exclusively to buy freehold land and factories"},"correctOption":"C","correctAnswer":"Because a business must pay for raw materials, wages, and running costs before it receives cash payments from customers who buy on credit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash outflows for production and stock occur before cash inflows arrive from sales, requiring working capital to keep operations running smoothly.","distractor_reasons":{"A":"Incorrect because in most industries, businesses spend cash on inputs before collecting cash from customers.","B":"Incorrect because businesses routinely hold cash in current accounts to pay daily bills.","C":"Option C is correct because cash outflows for production and stock occur before cash inflows arrive from sales, requiring working capital to keep operations running smoothly.","D":"Incorrect because buying freehold land and factories is long-term capital expenditure, not working capital."}}},{"id":"P1_U5_MCQ_629","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_629","question":"Which pairing correctly distinguishes an example of 'capital expenditure' from an example of 'revenue expenditure'?","options":{"A":"Capital expenditure: paying monthly factory rent; Revenue expenditure: buying freehold factory land","B":"Capital expenditure: purchasing raw materials for resale; Revenue expenditure: purchasing commercial delivery vans","C":"Capital expenditure: paying weekly staff wages; Revenue expenditure: installing permanent automated machinery","D":"Capital expenditure: buying new production machinery; Revenue expenditure: paying routine machine maintenance and electricity"},"correctOption":"D","correctAnswer":"Capital expenditure: buying new production machinery; Revenue expenditure: paying routine machine maintenance and electricity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because buying long-term machinery is capital expenditure (lasting over one year), whereas routine maintenance and electricity are day-to-day revenue expenditure.","distractor_reasons":{"A":"Incorrect because this reverses capital expenditure and revenue expenditure.","B":"Incorrect because raw materials are revenue expenditure and delivery vans are capital expenditure.","C":"Incorrect because weekly wages are revenue expenditure and automated machinery is capital expenditure.","D":"Option D is correct because buying long-term machinery is capital expenditure (lasting over one year), whereas routine maintenance and electricity are day-to-day revenue expenditure."}}},{"id":"P1_U5_MCQ_630","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_630","question":"Although 'retained profit' incurs no interest charges, what is the 'opportunity cost' of using retained profit to finance expansion?","options":{"A":"The collateral seized by creditors if sales revenue falls","B":"The mandatory fixed interest payments owed to commercial banks every month","C":"The dilution of voting control caused by issuing new shares to outside investors","D":"The forgone alternative uses of those funds, such as paying higher dividends to shareholders or earning interest in a deposit account"},"correctOption":"D","correctAnswer":"The forgone alternative uses of those funds, such as paying higher dividends to shareholders or earning interest in a deposit account","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retaining profit inside the business means shareholders miss out on immediate dividend payouts or external interest returns.","distractor_reasons":{"A":"Incorrect because retained profit is an internal reserve and requires no collateral.","B":"Incorrect because retained profit is internal equity and involves no bank interest payments.","C":"Incorrect because retaining profit does not involve issuing new voting shares.","D":"Option D is correct because retaining profit inside the business means shareholders miss out on immediate dividend payouts or external interest returns."}}},{"id":"P1_U5_MCQ_631","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_631","question":"How does 'sale and leaseback' of existing property raise finance, and what is its main long-term disadvantage?","options":{"A":"The business buys a rival's factory for cash, which eliminates all future rent expenses","B":"The business sells its freehold premises for an immediate lump sum of cash and rents them back, but loses asset ownership and faces ongoing future lease payments","C":"The business issues new ordinary shares to property investors, which doubles its non-current liabilities","D":"The business borrows a short-term overdraft, which must be repaid within seven days"},"correctOption":"B","correctAnswer":"The business sells its freehold premises for an immediate lump sum of cash and rents them back, but loses asset ownership and faces ongoing future lease payments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sale and leaseback unlocks capital tied up in owned buildings without disrupting operations, at the cost of permanent ownership and future rent outflows.","distractor_reasons":{"A":"Incorrect because sale and leaseback sells rather than buys property, creating new rent outflows.","B":"Option B is correct because sale and leaseback unlocks capital tied up in owned buildings without disrupting operations, at the cost of permanent ownership and future rent outflows.","C":"Incorrect because sale and leaseback involves selling physical property, not issuing shares.","D":"Incorrect because sale and leaseback is a long-term property arrangement, not a short-term bank overdraft."}}},{"id":"P1_U5_MCQ_632","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_632","question":"Why is 'reducing inventory levels' considered only a temporary, one-off way to generate internal cash rather than a continuous source of finance?","options":{"A":"Because inventory can only be sold once every five years by law","B":"Because reducing inventory increases warehouse rent and insurance costs","C":"Because once stock is reduced to the minimum buffer needed to meet customer orders, it cannot be reduced further without causing stockouts","D":"Because cash released from selling inventory must be handed over to the government"},"correctOption":"C","correctAnswer":"Because once stock is reduced to the minimum buffer needed to meet customer orders, it cannot be reduced further without causing stockouts","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because trimming excess stock releases cash once, after which the business must maintain sufficient inventory to continue trading normally.","distractor_reasons":{"A":"Incorrect because there is no law restricting how often inventory is sold.","B":"Incorrect because holding less inventory reduces rather than increases storage and insurance costs.","C":"Option C is correct because trimming excess stock releases cash once, after which the business must maintain sufficient inventory to continue trading normally.","D":"Incorrect because cash freed from working capital stays within the business."}}},{"id":"P1_U5_MCQ_633","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_633","question":"What is a major limitation of relying on 'owners' savings' when an unincorporated business wants to fund rapid, large-scale expansion?","options":{"A":"Owners' savings incur higher interest rates than commercial bank overdrafts","B":"Using personal savings forces the business to become a public limited company","C":"Personal savings must be repaid to outside investors within 12 months","D":"The personal wealth of sole traders or partners is usually limited and may be insufficient to finance major capital projects"},"correctOption":"D","correctAnswer":"The personal wealth of sole traders or partners is usually limited and may be insufficient to finance major capital projects","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because while personal savings are quick and interest-free, individual owners rarely possess enough personal funds for large-scale growth.","distractor_reasons":{"A":"Incorrect because personal savings are an internal source with no interest charges.","B":"Incorrect because using personal savings does not change a business's legal structure.","C":"Incorrect because owners' capital involves no repayment obligation to outside lenders.","D":"Option D is correct because while personal savings are quick and interest-free, individual owners rarely possess enough personal funds for large-scale growth."}}},{"id":"P1_U5_MCQ_634","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_634","question":"How does raising finance through 'issue of shares' differ between a private limited company (Ltd) and a public limited company (plc)?","options":{"A":"Shares issued by a plc must be repaid in cash after five years, whereas Ltd shares are permanent","B":"An Ltd can sell shares to the general public on a stock exchange, whereas a plc cannot issue any shares","C":"A plc can advertise and sell shares to the general public on a stock exchange to raise huge sums, whereas an Ltd can only sell shares privately with existing shareholders' agreement","D":"Only an Ltd has limited liability, whereas a plc has unlimited liability"},"correctOption":"C","correctAnswer":"A plc can advertise and sell shares to the general public on a stock exchange to raise huge sums, whereas an Ltd can only sell shares privately with existing shareholders' agreement","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because public limited companies have access to public stock markets for large capital issues, whereas private limited companies are restricted to private share placements.","distractor_reasons":{"A":"Incorrect because ordinary shares in both Ltds and plcs are permanent capital.","B":"Incorrect because this reverses the legal rules for Ltds and plcs.","C":"Option C is correct because public limited companies have access to public stock markets for large capital issues, whereas private limited companies are restricted to private share placements.","D":"Incorrect because shareholders in both Ltds and plcs enjoy limited liability."}}},{"id":"P1_U5_MCQ_635","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_635","question":"Why do 'ordinary shares' carry higher risk for investors than 'debentures', yet remain attractive to equity investors?","options":{"A":"Ordinary shareholders never receive any dividends even when the company earns record profits","B":"Ordinary dividends are not guaranteed and shareholders are paid last if the company fails, but they gain voting rights and potentially unlimited dividend and share-price growth","C":"Ordinary shareholders are personally liable for all company debts beyond their investment","D":"Debenture holders control the board of directors through majority voting rights"},"correctOption":"B","correctAnswer":"Ordinary dividends are not guaranteed and shareholders are paid last if the company fails, but they gain voting rights and potentially unlimited dividend and share-price growth","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ordinary shareholders bear residual business risk (variable dividends and last claim in liquidation) in exchange for voting control and capital appreciation.","distractor_reasons":{"A":"Incorrect because ordinary shareholders receive dividends when profits and board decisions allow.","B":"Option B is correct because ordinary shareholders bear residual business risk (variable dividends and last claim in liquidation) in exchange for voting control and capital appreciation.","C":"Incorrect because limited company shareholders have limited liability.","D":"Incorrect because debenture holders are lenders with no voting rights."}}},{"id":"P1_U5_MCQ_636","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_636","question":"What is the role of 'collateral' (security) when a business applies for a large bank loan?","options":{"A":"It is the non-repayable grant given by the bank to help the business start up","B":"It is the annual dividend paid by the borrower to the bank's shareholders","C":"It is a valuable asset (such as property or equipment) pledged by the borrower that the bank can seize and sell if the loan is not repaid","D":"It is the short-term trade credit offered by raw-material suppliers"},"correctOption":"C","correctAnswer":"It is a valuable asset (such as property or equipment) pledged by the borrower that the bank can seize and sell if the loan is not repaid","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because collateral reduces the bank's lending risk by providing an asset to recover the unpaid debt in case of borrower default.","distractor_reasons":{"A":"Incorrect because banks provide repayable loans rather than non-repayable grants.","B":"Incorrect because borrowers pay loan interest, not dividends, to banks.","C":"Option C is correct because collateral reduces the bank's lending risk by providing an asset to recover the unpaid debt in case of borrower default.","D":"Incorrect because trade credit is provided by commercial suppliers, not lending banks."}}},{"id":"P1_U5_MCQ_637","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_637","question":"What is a 'commercial mortgage'?","options":{"A":"A short-term facility allowing a business to overdraw its current account for a few days","B":"An internal source of finance generated by selling unsold inventory","C":"A non-repayable government subsidy for hiring apprentices","D":"A very long-term loan (often 15 to 25 years) specifically used to buy land or buildings, with the property itself acting as security"},"correctOption":"D","correctAnswer":"A very long-term loan (often 15 to 25 years) specifically used to buy land or buildings, with the property itself acting as security","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a mortgage is a long-term secured loan tied directly to purchasing real estate/property.","distractor_reasons":{"A":"Incorrect because overdrawing a current account is a bank overdraft.","B":"Incorrect because a mortgage is external long-term debt.","C":"Incorrect because a mortgage must be repaid with interest.","D":"Option D is correct because a mortgage is a long-term secured loan tied directly to purchasing real estate/property."}}},{"id":"P1_U5_MCQ_638","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_638","question":"Why might a large public limited company choose to issue 'debentures' rather than new 'ordinary shares' to raise long-term capital?","options":{"A":"Debentures never have to be repaid at maturity","B":"Issuing debentures raises long-term funds without diluting existing shareholders' voting control, and interest costs are fixed and predictable","C":"Debentures require zero interest payments even when the company is highly profitable","D":"Debentures can be issued by sole traders and partnerships"},"correctOption":"B","correctAnswer":"Issuing debentures raises long-term funds without diluting existing shareholders' voting control, and interest costs are fixed and predictable","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because debenture holders are creditors without voting rights, allowing existing shareholders to retain full control while raising long-term debt.","distractor_reasons":{"A":"Incorrect because debentures have a fixed maturity date when the principal must be repaid.","B":"Option B is correct because debenture holders are creditors without voting rights, allowing existing shareholders to retain full control while raising long-term debt.","C":"Incorrect because debentures carry contractual fixed interest that must be paid regardless of profit.","D":"Incorrect because only limited companies can issue debentures."}}},{"id":"P1_U5_MCQ_639","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_639","question":"How does 'debt factoring' differ from using a 'bank overdraft'?","options":{"A":"Debt factoring is a long-term mortgage, whereas a bank overdraft is internal retained profit","B":"Debt factoring releases cash from existing unpaid customer invoices sold to a specialist firm, whereas a bank overdraft borrows additional money from a bank up to an agreed limit","C":"Debt factoring increases non-current liabilities, whereas a bank overdraft increases share capital","D":"Debt factoring is free of any fees, whereas a bank overdraft charges dividends"},"correctOption":"B","correctAnswer":"Debt factoring releases cash from existing unpaid customer invoices sold to a specialist firm, whereas a bank overdraft borrows additional money from a bank up to an agreed limit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because debt factoring monetizes existing trade receivables at a discount, whereas an overdraft is short-term bank credit on a current account.","distractor_reasons":{"A":"Incorrect because both are short-term external working capital solutions.","B":"Option B is correct because debt factoring monetizes existing trade receivables at a discount, whereas an overdraft is short-term bank credit on a current account.","C":"Incorrect because neither increases non-current liabilities or share capital.","D":"Incorrect because factors charge a discount/service fee and overdrafts charge interest."}}},{"id":"P1_U5_MCQ_640","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_640","question":"What is a common limitation or restriction attached to 'government grants and subsidies'?","options":{"A":"They carry higher interest rates than commercial credit cards","B":"They force the recipient business to shut down after two years","C":"They often come with strict conditions (such as locating in a high-unemployment area or matching the grant with private funds) and lengthy application processes","D":"They require handing over 100% of company voting shares to the government"},"correctOption":"C","correctAnswer":"They often come with strict conditions (such as locating in a high-unemployment area or matching the grant with private funds) and lengthy application processes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because grants are conditional public funds; failure to meet agreed criteria can require repaying the grant, and approval can be slow and competitive.","distractor_reasons":{"A":"Incorrect because grants are non-repayable subsidies without interest.","B":"Incorrect because grants aim to support long-term business survival and regional growth.","C":"Option C is correct because grants are conditional public funds; failure to meet agreed criteria can require repaying the grant, and approval can be slow and competitive.","D":"Incorrect because grants do not transfer private business ownership to the state."}}},{"id":"P1_U5_MCQ_641","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_641","question":"Why do 'microfinance' loans often carry higher percentage interest rates than large corporate bank loans?","options":{"A":"Because microfinance institutions are owned by stock-market speculators who ban small repayments","B":"Because microfinance loans last for 40 years without any instalments","C":"Because microfinance borrowers receive free equity shares with every loan","D":"Because processing, monitoring, and collecting many tiny, unsecured loans involves high administrative costs relative to the small loan amount"},"correctOption":"D","correctAnswer":"Because processing, monitoring, and collecting many tiny, unsecured loans involves high administrative costs relative to the small loan amount","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lending very small sums without traditional collateral requires intensive field administration per dollar lent.","distractor_reasons":{"A":"Incorrect because microfinance typically involves frequent small repayments tailored to micro-entrepreneurs.","B":"Incorrect because microfinance loans are generally short-term.","C":"Incorrect because microfinance provides small loans, not share issues.","D":"Option D is correct because lending very small sums without traditional collateral requires intensive field administration per dollar lent."}}},{"id":"P1_U5_MCQ_642","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_642","question":"What is the key difference between 'reward-based crowdfunding' and 'equity-based crowdfunding'?","options":{"A":"Reward-based crowdfunding gives backers voting seats on the board, whereas equity-based crowdfunding gives backers free t-shirts","B":"Reward-based crowdfunding is only for plcs, whereas equity-based crowdfunding is only for sole traders","C":"Reward-based crowdfunding requires paying monthly bank interest, whereas equity-based crowdfunding is a government grant","D":"Reward-based backers receive a product, perk, or early access in return for pledges, whereas equity-based backers receive shares and a stake in future profits"},"correctOption":"D","correctAnswer":"Reward-based backers receive a product, perk, or early access in return for pledges, whereas equity-based backers receive shares and a stake in future profits","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because reward crowdfunding pre-sells perks or products without diluting ownership, whereas equity crowdfunding sells small shareholdings to online investors.","distractor_reasons":{"A":"Incorrect because this reverses the rewards and ownership rights of the two models.","B":"Incorrect because sole traders cannot issue equity shares.","C":"Incorrect because neither form involves commercial bank interest or government grants.","D":"Option D is correct because reward crowdfunding pre-sells perks or products without diluting ownership, whereas equity crowdfunding sells small shareholdings to online investors."}}},{"id":"P1_U5_MCQ_643","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_643","question":"What is a major risk for an entrepreneur who uses a public 'crowdfunding' website to raise start-up capital for a new invention?","options":{"A":"The entrepreneur must offer freehold land as collateral to every online backer","B":"Publishing the product idea online exposes it to competitors who may copy the concept before it is patented or launched, and if the funding target is missed, pledges may be returned","C":"Crowdfunding platforms automatically take 90% of the company's annual sales revenue forever","D":"Crowdfunding is legally banned for all consumer products"},"correctOption":"B","correctAnswer":"Publishing the product idea online exposes it to competitors who may copy the concept before it is patented or launched, and if the funding target is missed, pledges may be returned","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public online pitches reveal product designs early, risking imitation, and 'all-or-nothing' platforms return funds if the goal is not reached.","distractor_reasons":{"A":"Incorrect because crowdfunding does not require property collateral.","B":"Option B is correct because public online pitches reveal product designs early, risking imitation, and 'all-or-nothing' platforms return funds if the goal is not reached.","C":"Incorrect because platforms charge a modest percentage fee on funds raised, not 90% of ongoing revenue.","D":"Incorrect because consumer products are the most common category on crowdfunding sites."}}},{"id":"P1_U5_MCQ_644","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_644","question":"Why can a 'bank overdraft' be more cost-effective than a 'bank loan' for covering brief, fluctuating cash shortages?","options":{"A":"Because an overdraft never charges any interest regardless of how long it is used","B":"Because an overdraft converts into non-repayable retained profit after six months","C":"Because interest is paid only on the exact amount overdrawn and only for the specific days the account is in deficit, rather than on a full fixed lump sum","D":"Because an overdraft always has a lower annual interest rate than a long-term mortgage"},"correctOption":"C","correctAnswer":"Because interest is paid only on the exact amount overdrawn and only for the specific days the account is in deficit, rather than on a full fixed lump sum","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because overdraft interest is calculated daily on the actual negative balance, avoiding paying interest on idle borrowed cash.","distractor_reasons":{"A":"Incorrect because overdrafts charge interest whenever the account is overdrawn.","B":"Incorrect because an overdraft remains a repayable short-term liability.","C":"Option C is correct because overdraft interest is calculated daily on the actual negative balance, avoiding paying interest on idle borrowed cash.","D":"Incorrect because overdraft annual interest rates are typically higher than secured long-term loans."}}},{"id":"P1_U5_MCQ_645","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_645","question":"Why do suppliers offer 'trade credit' to business customers, and what happens if a buyer abuses these terms by repeatedly paying late?","options":{"A":"Suppliers offer credit to win repeat orders, but late payment damages supplier goodwill and may cause the supplier to refuse future credit or demand cash on delivery","B":"Suppliers offer credit because they are legally forbidden from accepting immediate cash","C":"Late payment forces the supplier to issue free shares to the buyer","D":"Suppliers offer credit so they can double the buyer's corporation tax bill"},"correctOption":"A","correctAnswer":"Suppliers offer credit to win repeat orders, but late payment damages supplier goodwill and may cause the supplier to refuse future credit or demand cash on delivery","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade credit is a competitive selling tool for suppliers, but relying on delayed payment harms trust and risks supply disruption.","distractor_reasons":{"A":"Option A is correct because trade credit is a competitive selling tool for suppliers, but relying on delayed payment harms trust and risks supply disruption.","B":"Incorrect because suppliers prefer cash on delivery when possible and extend credit to attract B2B buyers.","C":"Incorrect because trade credit is a commercial debt arrangement, not a share transaction.","D":"Incorrect because suppliers have no control over a buyer's tax liabilities."}}},{"id":"P1_U5_MCQ_646","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_646","question":"Why is 'leasing' particularly suitable for acquiring high-technology equipment such as computers or medical scanners?","options":{"A":"Because leasing makes the business the permanent owner on Day 1","B":"Because the business avoids a large upfront cash outlay and can upgrade to newer models at the end of the lease without being stuck with obsolete equipment","C":"Because leasing is an internal source of finance that requires zero monthly payments","D":"Because leased equipment appears as share capital on the statement of financial position"},"correctOption":"B","correctAnswer":"Because the business avoids a large upfront cash outlay and can upgrade to newer models at the end of the lease without being stuck with obsolete equipment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because leasing transfers obsolescence risk and maintenance responsibilities to the leasing company while preserving working capital.","distractor_reasons":{"A":"Incorrect because the leasing company retains legal ownership throughout and after the lease.","B":"Option B is correct because leasing transfers obsolescence risk and maintenance responsibilities to the leasing company while preserving working capital.","C":"Incorrect because leasing is external finance requiring regular rental payments.","D":"Incorrect because leased assets are rented, not share capital."}}},{"id":"P1_U5_MCQ_647","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_647","question":"What is a common disadvantage shared by both 'leasing' and 'hire purchase' compared with buying an asset outright for cash?","options":{"A":"Neither option allows the business to use the asset until the final year","B":"Both options immediately dilute the voting control of existing shareholders","C":"The total cumulative amount paid over the contract period is higher than the outright cash purchase price due to finance/interest charges","D":"Both options require listing the business on a public stock exchange"},"correctOption":"C","correctAnswer":"The total cumulative amount paid over the contract period is higher than the outright cash purchase price due to finance/interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because spreading payments over time incurs interest and administrative margins charged by the finance or leasing company.","distractor_reasons":{"A":"Incorrect because the business gets immediate operational use of the asset from the start of the agreement.","B":"Incorrect because neither leasing nor hire purchase involves issuing equity shares.","C":"Option C is correct because spreading payments over time incurs interest and administrative margins charged by the finance or leasing company.","D":"Incorrect because businesses of any legal structure can use leasing or hire purchase."}}},{"id":"P1_U5_MCQ_648","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_648","question":"According to the principle of matching the 'time period' of finance to the purpose, how should a business finance a new factory building expected to last 20 years?","options":{"A":"Using a 30-day supplier trade credit facility","B":"Using a short-term bank overdraft repayable on demand","C":"Using microfinance loans due within three months","D":"Using long-term finance such as retained profit, a share issue, debentures, or a long-term commercial mortgage"},"correctOption":"D","correctAnswer":"Using long-term finance such as retained profit, a share issue, debentures, or a long-term commercial mortgage","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because long-term capital investments take many years to generate returns and should be matched with long-term funding sources to avoid liquidity crises.","distractor_reasons":{"A":"Incorrect because 30-day trade credit is for short-term stock purchases.","B":"Incorrect because an overdraft can be recalled at short notice before the factory pays for itself.","C":"Incorrect because microfinance provides tiny short-term loans unsuitable for factory construction.","D":"Option D is correct because long-term capital investments take many years to generate returns and should be matched with long-term funding sources to avoid liquidity crises."}}},{"id":"P1_U5_MCQ_649","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_649","question":"How does a business's 'legal structure' restrict its choice of sources of finance?","options":{"A":"Sole traders and partnerships cannot raise capital by issuing shares or debentures, whereas limited companies can","B":"Public limited companies are legally forbidden from using retained profit or bank loans","C":"Sole traders are legally prohibited from using their own personal savings","D":"Private limited companies can sell shares freely to the public on a stock exchange, whereas plcs cannot"},"correctOption":"A","correctAnswer":"Sole traders and partnerships cannot raise capital by issuing shares or debentures, whereas limited companies can","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because only incorporated limited companies have share capital and can issue shares or corporate debentures.","distractor_reasons":{"A":"Option A is correct because only incorporated limited companies have share capital and can issue shares or corporate debentures.","B":"Incorrect because public limited companies frequently use retained profit and bank loans.","C":"Incorrect because sole traders commonly rely on personal savings.","D":"Incorrect because only plcs can float shares on a public stock exchange."}}},{"id":"P1_U5_MCQ_650","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_650","question":"Why does the 'size of a business' influence its ability to access external sources of finance?","options":{"A":"Small businesses always pay lower interest rates than large multinational corporations","B":"Large established businesses have greater asset collateral, proven profit track records, and access to capital markets, making lenders view them as lower risk","C":"Large businesses are legally barred from applying for commercial bank loans","D":"Small businesses have unlimited access to public stock market share issues"},"correctOption":"B","correctAnswer":"Large established businesses have greater asset collateral, proven profit track records, and access to capital markets, making lenders view them as lower risk","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because larger firms offer stronger collateral and lower default risk, giving them broader finance options at lower interest rates.","distractor_reasons":{"A":"Incorrect because small businesses are riskier to lenders and generally face higher interest rates.","B":"Option B is correct because larger firms offer stronger collateral and lower default risk, giving them broader finance options at lower interest rates.","C":"Incorrect because large businesses regularly borrow from commercial banks.","D":"Incorrect because small businesses are rarely plcs and cannot afford stock exchange listing costs."}}},{"id":"P1_U5_MCQ_651","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_651","question":"Why is 'cash' described as the most liquid asset a business holds?","options":{"A":"Because cash earns the highest rate of profit of any asset","B":"Because cash never changes value during periods of inflation","C":"Because cash is already in spendable money form and can be used immediately to pay wages, suppliers, and bills without needing to be sold or converted","D":"Because cash is classified as a non-current asset on the statement of financial position"},"correctOption":"C","correctAnswer":"Because cash is already in spendable money form and can be used immediately to pay wages, suppliers, and bills without needing to be sold or converted","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because liquidity measures how quickly an asset can be used to settle obligations, and cash is immediately spendable.","distractor_reasons":{"A":"Incorrect because idle cash earns little or no return compared with productive assets.","B":"Incorrect because inflation reduces the purchasing power of cash.","C":"Option C is correct because liquidity measures how quickly an asset can be used to settle obligations, and cash is immediately spendable.","D":"Incorrect because cash is a current asset."}}},{"id":"P1_U5_MCQ_652","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_652","question":"What happens if a business runs out of cash and cannot arrange an overdraft or emergency funds to pay its immediate debts?","options":{"A":"It automatically converts its trade payables into retained profit","B":"It is exempt from paying suppliers until the next financial year","C":"It becomes a public limited company on the stock exchange","D":"It becomes insolvent and may be forced into liquidation by unpaid creditors, even if it has profitable orders"},"correctOption":"D","correctAnswer":"It becomes insolvent and may be forced into liquidation by unpaid creditors, even if it has profitable orders","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because businesses pay employees, suppliers, and banks in cash; inability to pay debts as they fall due causes insolvency.","distractor_reasons":{"A":"Incorrect because supplier debts remain legal liabilities until settled.","B":"Incorrect because creditors can demand payment on agreed due dates and take legal action.","C":"Incorrect because insolvency leads to closure or restructuring, not a stock exchange listing.","D":"Option D is correct because businesses pay employees, suppliers, and banks in cash; inability to pay debts as they fall due causes insolvency."}}},{"id":"P1_U5_MCQ_653","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_653","question":"Which group contains ONLY 'financing cash inflows' (rather than day-to-day trading cash inflows) on a cash flow forecast?","options":{"A":"Payments to raw-material suppliers and monthly staff wages","B":"Cash sales at the till and collections from credit customers","C":"Receipt of a new bank loan, cash from issuing new shares, and owners' capital injections","D":"Retained profit and annual depreciation charges"},"correctOption":"C","correctAnswer":"Receipt of a new bank loan, cash from issuing new shares, and owners' capital injections","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because bank loans, share issues, and owner capital injections bring external or owner funding into the bank account rather than coming from product sales.","distractor_reasons":{"A":"Incorrect because payments to suppliers and wages are operating cash outflows.","B":"Incorrect because cash sales and collections from trade receivables are operating trading inflows.","C":"Option C is correct because bank loans, share issues, and owner capital injections bring external or owner funding into the bank account rather than coming from product sales.","D":"Incorrect because retained profit and depreciation are non-cash accounting figures."}}},{"id":"P1_U5_MCQ_654","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_654","question":"Which item represents a 'capital expenditure cash outflow' on a cash flow forecast?","options":{"A":"Paying monthly electricity and water bills for the office","B":"Paying cash to purchase new factory machinery or delivery vehicles","C":"Paying weekly wages to warehouse staff","D":"Receiving payment from a customer who bought goods on credit"},"correctOption":"B","correctAnswer":"Paying cash to purchase new factory machinery or delivery vehicles","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because buying long-term non-current assets for cash creates an immediate capital cash outflow on the cash flow forecast.","distractor_reasons":{"A":"Incorrect because utility bills are routine revenue expenditure outflows.","B":"Option B is correct because buying long-term non-current assets for cash creates an immediate capital cash outflow on the cash flow forecast.","C":"Incorrect because weekly wages are routine revenue expenditure outflows.","D":"Incorrect because receiving customer payments is a cash inflow."}}},{"id":"P1_U5_MCQ_655","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_655","question":"When a business purchases raw materials on 30-day trade credit in March and pays the supplier in April, how is this recorded on the cash flow forecast?","options":{"A":"As a cash outflow in March when the raw materials are delivered","B":"As a cash inflow in March and a cash outflow in April","C":"As zero cash outflow in March, and as a cash outflow in April when the payment actually leaves the bank account","D":"It is omitted from the cash flow forecast completely because it was bought on credit"},"correctOption":"C","correctAnswer":"As zero cash outflow in March, and as a cash outflow in April when the payment actually leaves the bank account","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a cash flow forecast records money strictly in the month cash actually moves out of or into the bank.","distractor_reasons":{"A":"Incorrect because no cash leaves the bank in March when buying on 30-day credit.","B":"Incorrect because buying materials never generates a cash inflow.","C":"Option C is correct because a cash flow forecast records money strictly in the month cash actually moves out of or into the bank.","D":"Incorrect because credit purchases still result in a cash outflow when paid in April."}}},{"id":"P1_U5_MCQ_656","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_656","question":"Why is 'retained profit' NOT entered as a cash inflow line on a monthly cash flow forecast?","options":{"A":"Because retained profit is a current liability owed to commercial banks","B":"Because retained profit is illegal for limited companies to calculate","C":"Because retained profit is always paid out to shareholders in cash","D":"Because retained profit is an accounting profit figure already reflected through actual cash sales inflows minus cash cost outflows"},"correctOption":"D","correctAnswer":"Because retained profit is an accounting profit figure already reflected through actual cash sales inflows minus cash cost outflows","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash flow forecasts track actual cash receipts and payments directly; including retained profit separately would double-count cash already captured via sales and expenses.","distractor_reasons":{"A":"Incorrect because retained profit is owners' equity, not a bank liability.","B":"Incorrect because retained profit is a standard line on a company's statement of profit or loss.","C":"Incorrect because dividends are paid out to shareholders, whereas retained profit is kept in the business.","D":"Option D is correct because cash flow forecasts track actual cash receipts and payments directly; including retained profit separately would double-count cash already captured via sales and expenses."}}},{"id":"P1_U5_MCQ_657","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_657","question":"What does a 'negative net cash flow' in a single month indicate?","options":{"A":"The business has definitely made an annual net loss on its statement of profit or loss","B":"Cash outflows exceeded cash inflows during that month, causing the cash balance to fall (or an overdraft to grow)","C":"The business's closing cash balance must automatically be negative","D":"The business had zero sales revenue during that month"},"correctOption":"B","correctAnswer":"Cash outflows exceeded cash inflows during that month, causing the cash balance to fall (or an overdraft to grow)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because negative net cash flow means more cash left the business than entered during that month, reducing the opening cash balance.","distractor_reasons":{"A":"Incorrect because a single month's negative net cash flow could simply reflect buying equipment or seasonal stock while still being profitable overall.","B":"Option B is correct because negative net cash flow means more cash left the business than entered during that month, reducing the opening cash balance.","C":"Incorrect because if the opening cash balance was larger than the monthly deficit, the closing balance can still remain positive.","D":"Incorrect because a business can have substantial sales revenue (especially on credit) and still have outflows exceed inflows in a given month."}}},{"id":"P1_U5_MCQ_658","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_658","question":"If a business starts a month with an overdrawn (negative) opening cash balance and experiences a negative net cash flow during that month, what happens to its closing cash balance?","options":{"A":"The closing cash balance becomes positive","B":"The closing cash balance becomes even more negative (a larger bank overdraft)","C":"The closing cash balance resets to zero","D":"The closing cash balance equals total cash inflows"},"correctOption":"B","correctAnswer":"The closing cash balance becomes even more negative (a larger bank overdraft)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Closing balance = Opening balance + Net cash flow; adding a negative net cash flow to an already negative opening balance deepens the overdraft.","distractor_reasons":{"A":"Incorrect because a negative net cash flow drains cash further rather than turning a deficit positive.","B":"Option B is correct because Closing balance = Opening balance + Net cash flow; adding a negative net cash flow to an already negative opening balance deepens the overdraft.","C":"Incorrect because bank overdraft balances carry forward continuously.","D":"Incorrect because closing balance accounts for opening balance, inflows, and outflows."}}},{"id":"P1_U5_MCQ_659","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_659","question":"How does including a 12-month cash flow forecast strengthen an entrepreneur's 'business plan'?","options":{"A":"It legally guarantees that customers will buy the forecast quantity of goods","B":"It eliminates the need to register the business with tax authorities","C":"It demonstrates financial foresight to banks and investors by identifying peak borrowing needs and proving when cash surpluses will repay finance","D":"It fixes interest rates on all commercial loans for ten years"},"correctOption":"C","correctAnswer":"It demonstrates financial foresight to banks and investors by identifying peak borrowing needs and proving when cash surpluses will repay finance","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lenders and investors look for realistic cash flow projections to verify that the entrepreneur understands working capital timing and repayment capacity.","distractor_reasons":{"A":"Incorrect because forecasts are estimates and cannot force customers to buy.","B":"Incorrect because legal registration is mandatory regardless of business plans.","C":"Option C is correct because lenders and investors look for realistic cash flow projections to verify that the entrepreneur understands working capital timing and repayment capacity.","D":"Incorrect because interest rates are determined by lenders and financial markets."}}},{"id":"P1_U5_MCQ_660","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_660","question":"Why do 'seasonal businesses' (such as ski resorts, toy manufacturers, or agricultural farms) rely especially heavily on monthly cash flow forecasts?","options":{"A":"Because seasonal businesses are exempt from paying taxes during off-peak months","B":"Because seasonal businesses never have any fixed overhead costs","C":"Because seasonal businesses only sell goods for immediate cash","D":"Because they incur heavy cash outflows for stock and preparation months before peak seasonal sales inflows arrive, requiring planned overdraft facilities"},"correctOption":"D","correctAnswer":"Because they incur heavy cash outflows for stock and preparation months before peak seasonal sales inflows arrive, requiring planned overdraft facilities","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because seasonal mismatches between production outflows and peak sales receipts create predictable cash troughs that must be financed in advance.","distractor_reasons":{"A":"Incorrect because seasonal businesses pay taxes on their annual profits like any other firm.","B":"Incorrect because seasonal businesses still pay fixed rent, insurance, and core salaries year-round.","C":"Incorrect because seasonal manufacturers often sell on credit to retailers.","D":"Option D is correct because seasonal mismatches between production outflows and peak sales receipts create predictable cash troughs that must be financed in advance."}}},{"id":"P1_U5_MCQ_661","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_661","question":"How does a cash flow forecast help managers set an appropriate 'bank overdraft limit'?","options":{"A":"By revealing the largest forecast negative closing cash balance during the year so the business can negotiate a sufficient overdraft facility before the deficit hits","B":"By calculating the exact gross profit margin on every product sold","C":"By eliminating all cash outflows during winter months","D":"By converting all current liabilities into ordinary share capital"},"correctOption":"A","correctAnswer":"By revealing the largest forecast negative closing cash balance during the year so the business can negotiate a sufficient overdraft facility before the deficit hits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because knowing the maximum projected cash deficit allows management to arrange an adequate overdraft ceiling in advance rather than having payments bounce.","distractor_reasons":{"A":"Option A is correct because knowing the maximum projected cash deficit allows management to arrange an adequate overdraft ceiling in advance rather than having payments bounce.","B":"Incorrect because gross profit margin is calculated from the statement of profit or loss.","C":"Incorrect because forecasts predict outflows rather than eliminating them.","D":"Incorrect because overdrafts are debt facilities, not share capital."}}},{"id":"P1_U5_MCQ_662","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_662","question":"Why do commercial banks react much more favorably when a business uses a cash flow forecast to request an overdraft *before* a deficit occurs, rather than exceeding its limit unannounced?","options":{"A":"Because banks are legally forbidden from charging interest on pre-arranged overdrafts","B":"Because presenting a forecast shows competent financial control and proves the deficit is temporary, whereas unarranged overdrafts signal poor management and incur penalty fees","C":"Because pre-arranged overdrafts never have to be repaid","D":"Because banks receive 50% of the borrower's retained profit"},"correctOption":"B","correctAnswer":"Because presenting a forecast shows competent financial control and proves the deficit is temporary, whereas unarranged overdrafts signal poor management and incur penalty fees","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because advance planning builds lender trust and secures lower agreed overdraft rates, whereas sudden cash emergencies risk refusal or high penalty charges.","distractor_reasons":{"A":"Incorrect because banks still charge interest on pre-arranged overdrafts, just at lower rates than unauthorized overdrafts.","B":"Option B is correct because advance planning builds lender trust and secures lower agreed overdraft rates, whereas sudden cash emergencies risk refusal or high penalty charges.","C":"Incorrect because overdrafts remain repayable on demand.","D":"Incorrect because banks earn interest and fees, not equity profit shares."}}},{"id":"P1_U5_MCQ_663","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_663","question":"How can a cash flow forecast help managers decide *when* to buy expensive new equipment for cash?","options":{"A":"By showing which months have large accumulated cash surpluses capable of absorbing the capital outflow without pushing the bank balance into deficit","B":"By forcing equipment suppliers to reduce their prices by 50%","C":"By recording equipment purchases as sales revenue","D":"By eliminating depreciation expenses on the statement of profit or loss"},"correctOption":"A","correctAnswer":"By showing which months have large accumulated cash surpluses capable of absorbing the capital outflow without pushing the bank balance into deficit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because timing capital expenditure to coincide with peak cash balances prevents liquidity strain.","distractor_reasons":{"A":"Option A is correct because timing capital expenditure to coincide with peak cash balances prevents liquidity strain.","B":"Incorrect because a forecast does not force suppliers to cut prices.","C":"Incorrect because buying equipment is an asset purchase and cash outflow, not revenue.","D":"Incorrect because non-current assets are still depreciated over their useful lives."}}},{"id":"P1_U5_MCQ_664","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_664","question":"Why do 'profit' and 'cash flow' differ when a business sells most of its goods on 60-day credit terms?","options":{"A":"Because credit sales are excluded from the statement of profit or loss","B":"Because credit sales increase revenue and profit immediately when goods are invoiced, whereas cash inflow is delayed for 60 days until customers pay","C":"Because credit sales are recorded as cash outflows on the cash flow forecast","D":"Because credit customers never pay for the goods they buy"},"correctOption":"B","correctAnswer":"Because credit sales increase revenue and profit immediately when goods are invoiced, whereas cash inflow is delayed for 60 days until customers pay","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profit follows the accruals principle (recognizing revenue at sale), whereas cash flow records actual receipt of funds two months later.","distractor_reasons":{"A":"Incorrect because credit sales are included in revenue on the statement of profit or loss.","B":"Option B is correct because profit follows the accruals principle (recognizing revenue at sale), whereas cash flow records actual receipt of funds two months later.","C":"Incorrect because customer payments are cash inflows once received.","D":"Incorrect because most credit customers pay within the agreed credit period (only rare bad debts go unpaid)."}}},{"id":"P1_U5_MCQ_665","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_665","question":"How does repaying the principal amount of a bank loan affect 'cash flow' versus 'profit'?","options":{"A":"Both the principal repayment and the interest reduce profit immediately","B":"Neither the principal repayment nor the interest appears on the cash flow forecast","C":"Repaying the loan principal creates a cash outflow that reduces cash, but only the interest charge reduces profit on the statement of profit or loss","D":"Repaying the loan principal increases gross profit"},"correctOption":"C","correctAnswer":"Repaying the loan principal creates a cash outflow that reduces cash, but only the interest charge reduces profit on the statement of profit or loss","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because repaying borrowed principal reduces cash and reduces the loan liability on the balance sheet without being a trading expense, whereas interest is an expense reducing profit.","distractor_reasons":{"A":"Incorrect because only the interest portion is an expense on the statement of profit or loss.","B":"Incorrect because both principal and interest payments involve cash leaving the bank and appear as cash outflows.","C":"Option C is correct because repaying borrowed principal reduces cash and reduces the loan liability on the balance sheet without being a trading expense, whereas interest is an expense reducing profit.","D":"Incorrect because loan repayments have no effect on gross profit."}}},{"id":"P1_U5_MCQ_666","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_666","question":"When a company issues new ordinary shares for cash, how does this transaction affect 'cash flow' and 'profit'?","options":{"A":"It increases both cash flow and gross profit by the share issue amount","B":"It reduces cash flow and increases overhead expenses","C":"It has no effect on either cash flow or the statement of financial position","D":"It creates a cash inflow that increases the cash balance, but it has zero effect on profit on the statement of profit or loss"},"correctOption":"D","correctAnswer":"It creates a cash inflow that increases the cash balance, but it has zero effect on profit on the statement of profit or loss","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because issuing shares brings financing cash into the business (increasing cash and share capital) rather than earning trading revenue.","distractor_reasons":{"A":"Incorrect because share proceeds are capital raised from owners, not sales revenue or gross profit.","B":"Incorrect because issuing shares brings cash into the business.","C":"Incorrect because it increases cash and share capital on the statement of financial position.","D":"Option D is correct because issuing shares brings financing cash into the business (increasing cash and share capital) rather than earning trading revenue."}}},{"id":"P1_U5_MCQ_667","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_667","question":"Why can rapid sales expansion without sufficient working capital (known as 'overtrading') cause a profitable business to run out of cash?","options":{"A":"Because expanding output requires immediate cash outflows for extra raw materials, stock, and wages before cash inflows arrive from new credit customers","B":"Because rapid sales growth automatically reduces gross profit margin to zero","C":"Because commercial banks cancel all overdrafts whenever sales increase","D":"Because rapid sales growth eliminates all trade receivables"},"correctOption":"A","correctAnswer":"Because expanding output requires immediate cash outflows for extra raw materials, stock, and wages before cash inflows arrive from new credit customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fulfilling surging orders absorbs large amounts of working capital upfront while cash remains tied up in higher inventories and trade receivables.","distractor_reasons":{"A":"Option A is correct because fulfilling surging orders absorbs large amounts of working capital upfront while cash remains tied up in higher inventories and trade receivables.","B":"Incorrect because higher sales volume can generate strong profit margins while still draining cash.","C":"Incorrect because banks do not automatically cancel overdrafts when sales rise.","D":"Incorrect because rapid credit sales increase rather than eliminate trade receivables."}}},{"id":"P1_U5_MCQ_668","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_668","question":"What is a potential drawback of relying on a 'bank overdraft' to fix a cash flow deficit?","options":{"A":"It forces the business to give up voting shares to the bank","B":"Interest rates are relatively high and variable, and the bank has the legal right to demand immediate repayment at short notice","C":"It takes several years to arrange and cannot be used for paying wages","D":"It permanently reduces the business's sales revenue"},"correctOption":"B","correctAnswer":"Interest rates are relatively high and variable, and the bank has the legal right to demand immediate repayment at short notice","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because overdrafts are short-term, recallable facilities with high daily interest rates if relied upon continuously.","distractor_reasons":{"A":"Incorrect because banks do not receive equity shares when granting an overdraft.","B":"Option B is correct because overdrafts are short-term, recallable facilities with high daily interest rates if relied upon continuously.","C":"Incorrect because overdrafts are quick to arrange and cover routine current account outflows like wages.","D":"Incorrect because an overdraft does not reduce sales revenue."}}},{"id":"P1_U5_MCQ_669","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_669","question":"What is a commercial risk of 'reducing the credit period' offered to customers (for example, from 60 days to 15 days) to speed up cash inflows?","options":{"A":"The business's non-current liabilities will double","B":"Suppliers will refuse to deliver raw materials","C":"Customers may switch to rival suppliers that still offer more generous 60-day credit terms, causing sales revenue to fall","D":"The business's gross profit margin will automatically drop to zero"},"correctOption":"C","correctAnswer":"Customers may switch to rival suppliers that still offer more generous 60-day credit terms, causing sales revenue to fall","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because trade credit is an important competitive factor in business-to-business sales; tightening credit terms too aggressively can drive buyers to competitors.","distractor_reasons":{"A":"Incorrect because tightening customer credit affects current assets, not non-current liabilities.","B":"Incorrect because customer credit terms do not dictate supplier willingness to sell.","C":"Option C is correct because trade credit is an important competitive factor in business-to-business sales; tightening credit terms too aggressively can drive buyers to competitors.","D":"Incorrect because shortening credit terms does not reduce unit selling prices or raise direct costs."}}},{"id":"P1_U5_MCQ_670","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_670","question":"How does using 'debt factoring' to overcome a cash shortage affect a business's cash flow versus its profit?","options":{"A":"It delays cash inflows by three months and increases profit","B":"It reduces cash inflows and doubles retained profit","C":"It has no effect on either cash flow or profit","D":"It accelerates immediate cash inflows into the bank account, but reduces profit because the factor deducts a service fee/discount"},"correctOption":"D","correctAnswer":"It accelerates immediate cash inflows into the bank account, but reduces profit because the factor deducts a service fee/discount","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because debt factoring trades a small portion of profit margin (the factor's discount fee) for immediate cash liquidity.","distractor_reasons":{"A":"Incorrect because factoring accelerates rather than delays cash inflows, and reduces rather than increases profit.","B":"Incorrect because factoring increases immediate cash inflows and lowers profit.","C":"Incorrect because factoring directly boosts short-term cash while charging a fee expense.","D":"Option D is correct because debt factoring trades a small portion of profit margin (the factor's discount fee) for immediate cash liquidity."}}},{"id":"P1_U5_MCQ_671","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_671","question":"How does choosing to 'lease' a new machine instead of buying it outright for cash help solve a forecast cash deficit?","options":{"A":"It creates a large immediate cash inflow from the leasing company","B":"It replaces a single large capital cash outflow with smaller, predictable monthly rental outflows that can be paid from ongoing revenue","C":"It eliminates all monthly cash outflows for the next five years","D":"It increases the value of freehold property on the statement of financial position"},"correctOption":"B","correctAnswer":"It replaces a single large capital cash outflow with smaller, predictable monthly rental outflows that can be paid from ongoing revenue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because leasing spreads payments over time, protecting short-term working capital from a major upfront cash drain.","distractor_reasons":{"A":"Incorrect because leasing involves rental outflows, not cash inflows.","B":"Option B is correct because leasing spreads payments over time, protecting short-term working capital from a major upfront cash drain.","C":"Incorrect because monthly lease rentals are ongoing cash outflows.","D":"Incorrect because leased assets are not owned by the business."}}},{"id":"P1_U5_MCQ_672","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_672","question":"What is the long-term cash flow consequence of using 'sale and leaseback' of freehold buildings to resolve an immediate liquidity crisis?","options":{"A":"Future annual cash outflows decrease permanently because rent is eliminated","B":"While it generates a large immediate cash inflow today, it introduces regular ongoing rent outflows for many years into the future","C":"The business receives the buildings back free of charge after 12 months","D":"The business's current liabilities increase by the value of the buildings"},"correctOption":"B","correctAnswer":"While it generates a large immediate cash inflow today, it introduces regular ongoing rent outflows for many years into the future","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sale and leaseback exchanges a one-off capital inflow now for recurring rental outflows over the lease term.","distractor_reasons":{"A":"Incorrect because the business now has to pay rent on buildings it previously owned outright.","B":"Option B is correct because sale and leaseback exchanges a one-off capital inflow now for recurring rental outflows over the lease term.","C":"Incorrect because ownership transfers permanently to the buyer/lessor.","D":"Incorrect because selling property for cash increases current assets (cash) rather than current liabilities."}}},{"id":"P1_U5_MCQ_673","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_673","question":"How does 'reducing inventory levels' (such as adopting just-in-time ordering) improve a business's cash flow?","options":{"A":"It doubles the selling price of every finished product","B":"It delays payments from credit customers by 60 days","C":"It reduces immediate cash outflows spent on purchasing and storing excess stock while converting existing stock into cash sales","D":"It eliminates all employee wage outflows"},"correctOption":"C","correctAnswer":"It reduces immediate cash outflows spent on purchasing and storing excess stock while converting existing stock into cash sales","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because holding less inventory frees cash previously locked up in warehouse shelves and lowers storage/insurance cash outflows.","distractor_reasons":{"A":"Incorrect because inventory management does not double retail prices.","B":"Incorrect because delaying customer payments would worsen rather than improve cash flow.","C":"Option C is correct because holding less inventory frees cash previously locked up in warehouse shelves and lowers storage/insurance cash outflows.","D":"Incorrect because staff wages are still paid."}}},{"id":"P1_U5_MCQ_674","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_674","question":"Why is taking out a '5-year bank loan' generally unsuitable for solving a brief, one-month seasonal cash shortage?","options":{"A":"Because 5-year bank loans never provide any cash inflows","B":"Because banks prohibit businesses from using loan funds to pay suppliers","C":"Because 5-year bank loans dilute shareholders' voting rights","D":"Because the business would be locked into paying interest over five years for funds it only needed for a few weeks, whereas an overdraft is far more flexible"},"correctOption":"D","correctAnswer":"Because the business would be locked into paying interest over five years for funds it only needed for a few weeks, whereas an overdraft is far more flexible","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because matching finance duration to need avoids unnecessary multi-year interest costs on idle funds once seasonal cash inflows return.","distractor_reasons":{"A":"Incorrect because bank loans provide a lump-sum cash inflow upon approval.","B":"Incorrect because working capital loans can be used for operating payments.","C":"Incorrect because bank loans are debt and do not affect share ownership.","D":"Option D is correct because matching finance duration to need avoids unnecessary multi-year interest costs on idle funds once seasonal cash inflows return."}}},{"id":"P1_U5_MCQ_675","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_675","question":"Why should managers regularly update a 'cash flow forecast' with actual figures throughout the year?","options":{"A":"Because comparing actual cash flows against forecast figures identifies variances early (such as slower customer payments or rising supplier costs) so revised projections and corrective actions remain accurate","B":"Because updating a forecast automatically increases annual profit","C":"Because tax authorities fine businesses that do not change their forecasts every week","D":"Because updating a forecast converts all trade receivables into cash immediately"},"correctOption":"A","correctAnswer":"Because comparing actual cash flows against forecast figures identifies variances early (such as slower customer payments or rising supplier costs) so revised projections and corrective actions remain accurate","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because variance analysis between forecast and actual cash flows keeps liquidity planning realistic in changing market conditions.","distractor_reasons":{"A":"Option A is correct because variance analysis between forecast and actual cash flows keeps liquidity planning realistic in changing market conditions.","B":"Incorrect because updating a planning document does not by itself create profit.","C":"Incorrect because cash flow forecasts are internal management and lending tools, not weekly tax filings.","D":"Incorrect because updating numbers on paper does not force customers to pay faster."}}},{"id":"P1_U5_MCQ_676","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_676","question":"What is the key conceptual difference between 'revenue' and 'profit'?","options":{"A":"Revenue is calculated after deducting all costs, whereas profit is calculated before deducting any costs","B":"Revenue is the total income earned from sales before deducting any costs, whereas profit is the surplus remaining after all costs have been subtracted from revenue","C":"Revenue is recorded on the statement of financial position, whereas profit is recorded only on the cash flow forecast","D":"Revenue and profit are always identical for every business"},"correctOption":"B","correctAnswer":"Revenue is the total income earned from sales before deducting any costs, whereas profit is the surplus remaining after all costs have been subtracted from revenue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because revenue is total sales turnover (Price × Quantity), whereas profit is net earnings after deducting cost of sales and overhead expenses.","distractor_reasons":{"A":"Incorrect because this reverses revenue and profit.","B":"Option B is correct because revenue is total sales turnover (Price × Quantity), whereas profit is net earnings after deducting cost of sales and overhead expenses.","C":"Incorrect because both revenue and profit are reported on the statement of profit or loss.","D":"Incorrect because revenue and profit could only be equal if a business had zero costs."}}},{"id":"P1_U5_MCQ_677","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_677","question":"How does a 'charity or non-profit organization' treat a financial surplus compared with a 'public limited company'?","options":{"A":"A charity distributes its surplus as cash dividends to private shareholders, whereas a plc cannot pay dividends","B":"Charities are legally forbidden from earning more income than their expenses","C":"A charity reinvests any surplus entirely back into its charitable cause rather than paying dividends to private owners, whereas a plc distributes dividends to shareholders and retains profit for growth","D":"A plc donates 100% of its profit to the government, whereas a charity keeps 100% for directors"},"correctOption":"C","correctAnswer":"A charity reinvests any surplus entirely back into its charitable cause rather than paying dividends to private owners, whereas a plc distributes dividends to shareholders and retains profit for growth","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because non-profit organizations have no private shareholders to receive dividends and plough surpluses back into their mission.","distractor_reasons":{"A":"Incorrect because charities have no private shareholders and cannot pay dividends.","B":"Incorrect because charities aim to generate surpluses to fund their charitable activities.","C":"Option C is correct because non-profit organizations have no private shareholders to receive dividends and plough surpluses back into their mission.","D":"Incorrect because plcs pay corporation tax on profits and distribute dividends to shareholders."}}},{"id":"P1_U5_MCQ_678","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_678","question":"How does 'profit' serve as a measure of business success and efficiency?","options":{"A":"It measures the exact number of employees hired during the year","B":"It proves that the business holds zero debt on its statement of financial position","C":"It guarantees that the business will never face competition","D":"It shows whether the value of output sold exceeds the total cost of resources used to produce and market it, allowing comparisons over time and against rivals"},"correctOption":"D","correctAnswer":"It shows whether the value of output sold exceeds the total cost of resources used to produce and market it, allowing comparisons over time and against rivals","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit reflects how effectively management turns inputs into valued customer outputs while controlling costs.","distractor_reasons":{"A":"Incorrect because profit is a financial surplus, not a headcount figure.","B":"Incorrect because profitable businesses frequently use debt financing.","C":"Incorrect because high profits actually attract competitors into the market.","D":"Option D is correct because profit reflects how effectively management turns inputs into valued customer outputs while controlling costs."}}},{"id":"P1_U5_MCQ_679","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_679","question":"In a market economy, what role does 'high profit' in a particular industry play as an economic signal?","options":{"A":"It eliminates all raw material costs for firms in that industry","B":"It forces existing businesses in that industry to shut down immediately","C":"It proves that consumers dislike the products being sold","D":"It attracts new businesses and investment capital into that industry to supply goods that consumers strongly demand"},"correctOption":"D","correctAnswer":"It attracts new businesses and investment capital into that industry to supply goods that consumers strongly demand","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because high profitability signals strong consumer demand and attractive returns, encouraging entrepreneurs and capital to enter the market.","distractor_reasons":{"A":"Incorrect because raw material costs still apply regardless of industry profitability.","B":"Incorrect because persistent losses, not high profits, force firms to exit an industry.","C":"Incorrect because strong profits indicate customers value the product above its production cost.","D":"Option D is correct because high profitability signals strong consumer demand and attractive returns, encouraging entrepreneurs and capital to enter the market."}}},{"id":"P1_U5_MCQ_680","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_680","question":"Why are proceeds from a 'new bank loan' or 'selling an old company van' excluded from 'sales revenue' on a statement of profit or loss?","options":{"A":"Because bank loans and van sales are illegal in limited companies","B":"Because sales revenue only records income earned from selling the business's regular goods or services, whereas loans are liabilities and van sales are asset disposals","C":"Because bank loans and van sales are recorded inside cost of sales","D":"Because sales revenue only includes cash received in banknotes"},"correctOption":"B","correctAnswer":"Because sales revenue only records income earned from selling the business's regular goods or services, whereas loans are liabilities and van sales are asset disposals","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because trading revenue reflects core operational sales, keeping financing and capital asset transactions separate.","distractor_reasons":{"A":"Incorrect because both are normal, legal business transactions.","B":"Option B is correct because trading revenue reflects core operational sales, keeping financing and capital asset transactions separate.","C":"Incorrect because neither is a direct cost of producing goods sold.","D":"Incorrect because sales revenue includes both cash sales and credit sales."}}},{"id":"P1_U5_MCQ_681","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_681","question":"How do the components of 'cost of sales' typically differ between a 'retail shop' and a 'manufacturing factory'?","options":{"A":"A retail shop has zero cost of sales, whereas a factory includes head-office advertising in cost of sales","B":"A retail shop includes corporation tax in cost of sales, whereas a factory includes dividends","C":"A retail shop's cost of sales is the wholesale purchase cost of finished goods resold, whereas a factory's cost of sales includes direct raw materials and direct production wages","D":"Both retail shops and factories include only head-office administrative salaries in cost of sales"},"correctOption":"C","correctAnswer":"A retail shop's cost of sales is the wholesale purchase cost of finished goods resold, whereas a factory's cost of sales includes direct raw materials and direct production wages","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because retailers buy finished goods for resale, while manufacturers incur direct material and direct factory labor costs to make goods.","distractor_reasons":{"A":"Incorrect because retailers incur the wholesale cost of stock sold, and advertising is an overhead expense.","B":"Incorrect because corporation tax and dividends appear at the bottom of the income statement.","C":"Option C is correct because retailers buy finished goods for resale, while manufacturers incur direct material and direct factory labor costs to make goods.","D":"Incorrect because administrative salaries are indirect overhead expenses."}}},{"id":"P1_U5_MCQ_682","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_682","question":"Why is 'closing inventory' subtracted when calculating 'cost of sales' (Opening inventory + Purchases - Closing inventory)?","options":{"A":"Because closing inventory was stolen during the year","B":"Because closing inventory is a non-current liability owed to banks","C":"Because closing inventory has already been sold to credit customers","D":"Because closing inventory remains unsold at year-end, so its cost must be excluded from the cost of goods actually sold during the current year"},"correctOption":"D","correctAnswer":"Because closing inventory remains unsold at year-end, so its cost must be excluded from the cost of goods actually sold during the current year","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the matching principle matches the revenue from goods sold during the period strictly against the cost of those same sold goods.","distractor_reasons":{"A":"Incorrect because closing inventory represents valid unsold stock still held by the business.","B":"Incorrect because closing inventory is a current asset.","C":"Incorrect because goods sold to customers are no longer in closing inventory.","D":"Option D is correct because the matching principle matches the revenue from goods sold during the period strictly against the cost of those same sold goods."}}},{"id":"P1_U5_MCQ_683","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_683","question":"How does 'closing inventory' at the end of Year 1 appear in Year 2's statement of profit or loss?","options":{"A":"It becomes the 'opening inventory' at the start of Year 2","B":"It is added to Year 2's sales revenue","C":"It is deducted as an overhead expense in Year 2","D":"It disappears completely from all Year 2 accounting records"},"correctOption":"A","correctAnswer":"It becomes the 'opening inventory' at the start of Year 2","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unsold goods sitting in the warehouse at 11:59 PM on the last day of Year 1 are the exact same goods on hand at the start of Day 1 of Year 2.","distractor_reasons":{"A":"Option A is correct because unsold goods sitting in the warehouse at 11:59 PM on the last day of Year 1 are the exact same goods on hand at the start of Day 1 of Year 2.","B":"Incorrect because inventory is stock held, not sales revenue.","C":"Incorrect because opening inventory is part of cost of sales, not an overhead expense.","D":"Incorrect because inventory carries continuously from one accounting year to the next."}}},{"id":"P1_U5_MCQ_684","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_684","question":"What is the structural difference between 'gross profit' and 'profit for the year' (operating profit)?","options":{"A":"Gross profit deducts indirect overheads, whereas profit for the year deducts direct cost of sales","B":"Gross profit deducts only direct cost of sales from revenue, whereas profit for the year also deducts all indirect overhead expenses","C":"Gross profit includes dividends paid, whereas profit for the year excludes dividends","D":"Gross profit is calculated on the statement of financial position, whereas profit for the year is calculated on the cash flow forecast"},"correctOption":"B","correctAnswer":"Gross profit deducts only direct cost of sales from revenue, whereas profit for the year also deducts all indirect overhead expenses","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Gross profit = Revenue - Cost of sales, while Profit for the year = Gross profit - Overhead expenses.","distractor_reasons":{"A":"Incorrect because this reverses cost of sales and overhead expenses.","B":"Option B is correct because Gross profit = Revenue - Cost of sales, while Profit for the year = Gross profit - Overhead expenses.","C":"Incorrect because dividends are deducted at the very bottom after profit after tax.","D":"Incorrect because both figures appear on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_685","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_685","question":"How can a business earn a substantial 'gross profit' yet still end up with a 'net loss' for the year?","options":{"A":"When direct cost of sales is greater than total sales revenue","B":"When the business holds zero inventory at year-end","C":"When indirect overhead expenses (such as rent, marketing, salaries, and interest) exceed the gross profit earned","D":"When credit customers pay their invoices early"},"correctOption":"C","correctAnswer":"When indirect overhead expenses (such as rent, marketing, salaries, and interest) exceed the gross profit earned","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Profit = Gross profit - Overhead expenses; if indirect running costs are larger than gross profit, final profit becomes negative (a loss).","distractor_reasons":{"A":"Incorrect because if cost of sales exceeded revenue, gross profit itself would already be negative.","B":"Incorrect because holding zero closing inventory does not automatically cause a net loss.","C":"Option C is correct because Profit = Gross profit - Overhead expenses; if indirect running costs are larger than gross profit, final profit becomes negative (a loss).","D":"Incorrect because early customer payments improve cash flow and do not cause a trading loss."}}},{"id":"P1_U5_MCQ_686","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_686","question":"Which cost is classified as a 'direct cost' (part of cost of sales) rather than an 'indirect overhead expense'?","options":{"A":"Annual audit fees paid to external accountants","B":"Salary of the company's chief executive officer","C":"Rent and business rates for the administrative head office","D":"Packaging materials used directly on each unit of product manufactured and sold"},"correctOption":"D","correctAnswer":"Packaging materials used directly on each unit of product manufactured and sold","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because direct product packaging varies directly with units produced and sold, forming part of cost of sales.","distractor_reasons":{"A":"Incorrect because audit fees are indirect administrative overhead expenses.","B":"Incorrect because executive salaries are indirect overhead expenses.","C":"Incorrect because head-office rent and rates are indirect overhead expenses.","D":"Option D is correct because direct product packaging varies directly with units produced and sold, forming part of cost of sales."}}},{"id":"P1_U5_MCQ_687","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_687","question":"Which group contains ONLY 'indirect overhead expenses' deducted from gross profit on a statement of profit or loss?","options":{"A":"Office administrative salaries, marketing and advertising, shop rent, and annual depreciation of office equipment","B":"Opening inventory, raw material purchases, and direct factory assembly wages","C":"Purchase of freehold factory land and issuance of ordinary shares","D":"Dividends paid to shareholders and corporation tax"},"correctOption":"A","correctAnswer":"Office administrative salaries, marketing and advertising, shop rent, and annual depreciation of office equipment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because administrative salaries, advertising, rent, and office depreciation are all indirect running costs deducted after gross profit.","distractor_reasons":{"A":"Option A is correct because administrative salaries, advertising, rent, and office depreciation are all indirect running costs deducted after gross profit.","B":"Incorrect because inventory, purchases, and direct production wages belong in cost of sales.","C":"Incorrect because freehold land is a non-current asset and share issues are equity.","D":"Incorrect because tax and dividends are deducted after operating profit."}}},{"id":"P1_U5_MCQ_688","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_688","question":"Where is 'interest paid' on bank loans and debentures accounted for on a statement of profit or loss?","options":{"A":"It is added to sales revenue at the top of the statement","B":"It is deducted after operating profit (profit before interest and tax) to calculate profit before tax","C":"It is included in opening inventory","D":"It is omitted completely because interest is a cash flow item"},"correctOption":"B","correctAnswer":"It is deducted after operating profit (profit before interest and tax) to calculate profit before tax","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because finance costs (loan and debenture interest) are deducted from operating profit before corporation tax is calculated.","distractor_reasons":{"A":"Incorrect because interest paid is an expense, not revenue.","B":"Option B is correct because finance costs (loan and debenture interest) are deducted from operating profit before corporation tax is calculated.","C":"Incorrect because interest is a finance cost, not physical inventory.","D":"Incorrect because interest is a genuine expense reducing profit before tax."}}},{"id":"P1_U5_MCQ_689","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_689","question":"What is the difference between 'profit before tax' and 'profit after tax' for a limited company?","options":{"A":"Profit before tax has not yet deducted overhead expenses","B":"Profit after tax has already deducted dividends paid to shareholders","C":"Profit after tax is the profit remaining once government corporation tax has been subtracted from profit before tax","D":"Profit before tax is calculated on the statement of financial position"},"correctOption":"C","correctAnswer":"Profit after tax is the profit remaining once government corporation tax has been subtracted from profit before tax","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because corporation tax is assessed on profit before tax; deducting that tax leaves profit after tax.","distractor_reasons":{"A":"Incorrect because overhead expenses are deducted earlier to arrive at profit before tax.","B":"Incorrect because dividends are deducted *after* profit after tax to find retained profit.","C":"Option C is correct because corporation tax is assessed on profit before tax; deducting that tax leaves profit after tax.","D":"Incorrect because both figures appear on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_690","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_690","question":"Why do 'corporation tax' and 'dividends' appear on a limited company's statement of profit or loss, whereas they do NOT appear on a sole trader's statement of profit or loss?","options":{"A":"Because sole traders are legally prohibited from earning any profit","B":"Because sole traders do not have to pay any taxes to the government","C":"Because sole traders are owned by public stock market shareholders","D":"Because a limited company is a separate legal entity paying corporation tax and shareholder dividends, whereas a sole trader is unincorporated and pays personal income tax while taking 'drawings'"},"correctOption":"D","correctAnswer":"Because a limited company is a separate legal entity paying corporation tax and shareholder dividends, whereas a sole trader is unincorporated and pays personal income tax while taking 'drawings'","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because unincorporated businesses do not have separate corporate legal personality, share capital, or corporation tax.","distractor_reasons":{"A":"Incorrect because sole traders are profit-seeking private businesses.","B":"Incorrect because sole traders pay personal income tax on their business profits.","C":"Incorrect because sole traders are owned by one individual, not stock market shareholders.","D":"Option D is correct because unincorporated businesses do not have separate corporate legal personality, share capital, or corporation tax."}}},{"id":"P1_U5_MCQ_691","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_691","question":"What is the difference between 'drawings' and 'dividends'?","options":{"A":"Drawings are cash or goods withdrawn by a sole trader or partner for personal use, whereas dividends are shares of after-tax profit distributed to a limited company's shareholders","B":"Drawings are paid to commercial banks, whereas dividends are paid to suppliers","C":"Drawings are deducted before gross profit, whereas dividends are added to sales revenue","D":"Drawings apply only to public limited companies, whereas dividends apply only to sole traders"},"correctOption":"A","correctAnswer":"Drawings are cash or goods withdrawn by a sole trader or partner for personal use, whereas dividends are shares of after-tax profit distributed to a limited company's shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because drawings represent owner withdrawals in unincorporated firms, whereas dividends are corporate profit distributions to shareholders.","distractor_reasons":{"A":"Option A is correct because drawings represent owner withdrawals in unincorporated firms, whereas dividends are corporate profit distributions to shareholders.","B":"Incorrect because neither drawings nor dividends are payments to banks or suppliers.","C":"Incorrect because neither is an operating expense or revenue item.","D":"Incorrect because this reverses unincorporated and incorporated legal structures."}}},{"id":"P1_U5_MCQ_692","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_692","question":"Why might a company's board of directors choose to pay 'zero dividends' in a year when the company made only a modest profit?","options":{"A":"Because paying dividends is illegal whenever profit is below $1 million","B":"Because ordinary dividends are discretionary, and directors may prefer to retain all profit to preserve cash liquidity or fund essential investments","C":"Because paying dividends increases the company's cost of sales","D":"Because zero dividends automatically turns the company into a charity"},"correctOption":"B","correctAnswer":"Because ordinary dividends are discretionary, and directors may prefer to retain all profit to preserve cash liquidity or fund essential investments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unlike mandatory loan interest, ordinary dividends are flexible and can be reduced or suspended to protect cash flow and reserves.","distractor_reasons":{"A":"Incorrect because there is no statutory minimum profit threshold for paying dividends.","B":"Option B is correct because unlike mandatory loan interest, ordinary dividends are flexible and can be reduced or suspended to protect cash flow and reserves.","C":"Incorrect because dividends are appropriated after tax and do not affect cost of sales.","D":"Incorrect because skipping a dividend does not alter a company's commercial legal status."}}},{"id":"P1_U5_MCQ_693","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_693","question":"A business records revenue of $200,000, cost of sales of $120,000 and overheads of $50,000 for the year. What is its gross profit?","options":{"A":"$30,000","B":"$50,000","C":"$80,000","D":"$200,000"},"correctOption":"C","correctAnswer":"$80,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because gross profit equals revenue minus cost of sales, that is $200,000 minus $120,000, giving $80,000.","distractor_reasons":{"C":"Option C is correct because gross profit equals revenue minus cost of sales, that is $200,000 minus $120,000, giving $80,000.","A":"Incorrect because $30,000 is the profit left after overheads are also deducted, not the gross profit.","B":"Incorrect because $50,000 is simply the amount of overheads, which are subtracted after gross profit has been calculated.","D":"Incorrect because $200,000 is the revenue figure and does not deduct the direct cost of making the sales."}}},{"id":"P1_U5_MCQ_694","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_694","question":"A company made a profit after tax of $48,000 and paid dividends of $12,000 to its shareholders. What was its retained profit?","options":{"A":"$12,000","B":"$36,000","C":"$48,000","D":"$60,000"},"correctOption":"B","correctAnswer":"$36,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is the profit left in the business after dividends are paid: $48,000 − $12,000 = $36,000.","distractor_reasons":{"A":"$12,000 is the dividend paid out, not the amount kept in the business.","B":"Correct: profit after tax minus dividends gives retained profit of $36,000.","C":"$48,000 is profit after tax before dividends have been deducted.","D":"$60,000 wrongly adds dividends to profit instead of subtracting them."}}},{"id":"P1_U5_MCQ_695","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_695","question":"Riverside Bakery reported revenue of $80,000, cost of sales of $50,000 and operating expenses of $20,000 for the year. What was the bakery's profit for the year?","options":{"A":"$10,000","B":"$30,000","C":"$60,000","D":"$100,000"},"correctOption":"A","correctAnswer":"$10,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales ($30,000); subtracting operating expenses of $20,000 leaves a profit of $10,000.","distractor_reasons":{"A":"Gross profit is revenue minus cost of sales ($30,000); subtracting operating expenses of $20,000 leaves a profit of $10,000.","B":"$30,000 is only the gross profit; operating expenses still have to be deducted.","C":"$60,000 wrongly subtracts expenses from revenue and ignores cost of sales.","D":"$100,000 incorrectly adds expenses to revenue instead of deducting the costs."}}},{"id":"P1_U5_MCQ_696","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_696","question":"What is a potential trade-off when a business tries to increase gross profit by switching to a cheaper raw-material supplier?","options":{"A":"Cheaper raw materials automatically increase head-office rent","B":"Lower material quality may increase defect rates, damage brand reputation, and reduce repeat customer sales in the long run","C":"Cheaper raw materials increase cost of sales","D":"Switching suppliers converts equity into non-current liabilities"},"correctOption":"B","correctAnswer":"Lower material quality may increase defect rates, damage brand reputation, and reduce repeat customer sales in the long run","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reducing direct input costs boosts gross margin initially, but sacrificing product quality can alienate customers.","distractor_reasons":{"A":"Incorrect because raw material prices do not change fixed office rent.","B":"Option B is correct because reducing direct input costs boosts gross margin initially, but sacrificing product quality can alienate customers.","C":"Incorrect because cheaper raw materials reduce rather than increase cost of sales.","D":"Incorrect because supplier changes do not alter capital structure."}}},{"id":"P1_U5_MCQ_697","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_697","question":"What is a major risk of cutting 'overhead expenses' such as marketing budgets or staff training in order to boost short-term profit?","options":{"A":"Gross profit margin will immediately fall to zero","B":"Current liabilities will double overnight","C":"While profit increases immediately due to lower expenses, future brand awareness, customer loyalty, and workforce productivity may decline","D":"The business will have to pay corporation tax even if it makes a loss"},"correctOption":"C","correctAnswer":"While profit increases immediately due to lower expenses, future brand awareness, customer loyalty, and workforce productivity may decline","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because slashing discretionary overheads like advertising and training improves this year's bottom line at the expense of future competitiveness.","distractor_reasons":{"A":"Incorrect because marketing and training are indirect overheads, not part of gross profit.","B":"Incorrect because reducing expenses does not double current liabilities.","C":"Option C is correct because slashing discretionary overheads like advertising and training improves this year's bottom line at the expense of future competitiveness.","D":"Incorrect because corporation tax is charged only when positive profit is earned."}}},{"id":"P1_U5_MCQ_698","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_698","question":"Why do 'suppliers' examine a business customer's statement of profit or loss in addition to its statement of financial position?","options":{"A":"To calculate how much corporation tax the supplier owes","B":"To check the customer's exact daily physical cash balance","C":"To set the customer's retail selling prices","D":"To see whether the customer is consistently profitable and growing, indicating it will remain a reliable long-term buyer placing repeat orders"},"correctOption":"D","correctAnswer":"To see whether the customer is consistently profitable and growing, indicating it will remain a reliable long-term buyer placing repeat orders","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because suppliers value profitable customers who are likely to survive, grow, and generate ongoing B2B sales.","distractor_reasons":{"A":"Incorrect because a supplier pays tax on its own profit, not its customer's profit.","B":"Incorrect because cash balances appear on the statement of financial position, not the income statement.","C":"Incorrect because businesses set their own retail prices.","D":"Option D is correct because suppliers value profitable customers who are likely to survive, grow, and generate ongoing B2B sales."}}},{"id":"P1_U5_MCQ_699","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_699","question":"Besides assessing corporation tax, why does the 'government' review the published statements of profit or loss of major corporations?","options":{"A":"To approve every routine purchase of raw materials","B":"To decide which dividends individual private shareholders should spend","C":"To monitor overall economic growth, industry profitability, and employment stability across the economy","D":"To guarantee that no company ever makes a loss"},"correctOption":"C","correctAnswer":"To monitor overall economic growth, industry profitability, and employment stability across the economy","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because corporate profit trends help governments forecast tax revenues and gauge macroeconomic health.","distractor_reasons":{"A":"Incorrect because governments do not approve routine commercial purchases.","B":"Incorrect because shareholders freely decide how to use their dividend income.","C":"Option C is correct because corporate profit trends help governments forecast tax revenues and gauge macroeconomic health.","D":"Incorrect because private businesses bear commercial risk in market economies."}}},{"id":"P1_U5_MCQ_700","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_700","question":"Why can comparing raw dollar profit figures between a large multinational corporation and a small local business be misleading?","options":{"A":"Because small businesses are legally forbidden from preparing statements of profit or loss","B":"Because a large corporation invests far more capital and generates much higher revenue, so relative profitability ratios (like profit margin and ROCE) are needed to judge efficiency fairly","C":"Because multinational corporations do not deduct cost of sales","D":"Because raw dollar profit is always equal to cash in the bank"},"correctOption":"B","correctAnswer":"Because a large corporation invests far more capital and generates much higher revenue, so relative profitability ratios (like profit margin and ROCE) are needed to judge efficiency fairly","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because absolute profit reflects business scale; percentage ratios standardize performance relative to sales and capital employed.","distractor_reasons":{"A":"Incorrect because all businesses track revenue, costs, and profit.","B":"Option B is correct because absolute profit reflects business scale; percentage ratios standardize performance relative to sales and capital employed.","C":"Incorrect because all trading businesses deduct cost of sales.","D":"Incorrect because profit differs from cash flow due to credit terms, non-cash items, and capital spending."}}},{"id":"P1_U5_MCQ_701","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_701","question":"Why was the 'statement of financial position' traditionally called a 'balance sheet'?","options":{"A":"Because cash inflows must always equal cash outflows on the statement","B":"Because gross profit must always equal indirect overhead expenses","C":"Because total assets minus total liabilities (net assets) must always equal total owners' equity, meaning both sides of the accounting equation balance","D":"Because non-current assets must always equal current liabilities"},"correctOption":"C","correctAnswer":"Because total assets minus total liabilities (net assets) must always equal total owners' equity, meaning both sides of the accounting equation balance","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because double-entry accounting ensures that Net assets = Total equity (or Total assets = Total liabilities + Total equity) at all times.","distractor_reasons":{"A":"Incorrect because cash inflows and outflows appear on the cash flow statement and rarely equal each other.","B":"Incorrect because gross profit and overheads appear on the statement of profit or loss.","C":"Option C is correct because double-entry accounting ensures that Net assets = Total equity (or Total assets = Total liabilities + Total equity) at all times.","D":"Incorrect because non-current assets and current liabilities have no requirement to be equal."}}},{"id":"P1_U5_MCQ_702","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_702","question":"How does the time horizon of a 'statement of profit or loss' differ from that of a 'statement of financial position'?","options":{"A":"A statement of profit or loss covers one single day, whereas a statement of financial position covers ten years","B":"Both statements cover only a single 24-hour trading day","C":"A statement of profit or loss projects the future, whereas a statement of financial position records only cash","D":"A statement of profit or loss measures financial flows over a period of time (e.g., 12 months), whereas a statement of financial position records asset, liability, and equity balances at one specific date"},"correctOption":"D","correctAnswer":"A statement of profit or loss measures financial flows over a period of time (e.g., 12 months), whereas a statement of financial position records asset, liability, and equity balances at one specific date","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the income statement is a period flow report ('For the year ended...'), while the statement of financial position is a point-in-time snapshot ('As at...').","distractor_reasons":{"A":"Incorrect because this reverses the period vs point-in-time distinction.","B":"Incorrect because the income statement covers an entire accounting period.","C":"Incorrect because both statements are historical financial reports.","D":"Option D is correct because the income statement is a period flow report ('For the year ended...'), while the statement of financial position is a point-in-time snapshot ('As at...')."}}},{"id":"P1_U5_MCQ_703","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_703","question":"Which pairing correctly distinguishes a 'tangible non-current asset' from an 'intangible non-current asset'?","options":{"A":"Tangible: factory machinery and delivery vans; Intangible: purchased patents, copyrights, and brand goodwill","B":"Tangible: trade receivables and cash; Intangible: trade payables and bank overdrafts","C":"Tangible: purchased patents; Intangible: freehold land and buildings","D":"Tangible: issued share capital; Intangible: retained profit"},"correctOption":"A","correctAnswer":"Tangible: factory machinery and delivery vans; Intangible: purchased patents, copyrights, and brand goodwill","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tangible non-current assets have physical form (machinery, vehicles, buildings), whereas intangible non-current assets are non-physical legal or commercial rights (patents, copyrights, purchased goodwill).","distractor_reasons":{"A":"Option A is correct because tangible non-current assets have physical form (machinery, vehicles, buildings), whereas intangible non-current assets are non-physical legal or commercial rights (patents, copyrights, purchased goodwill).","B":"Incorrect because receivables and cash are current assets, while payables and overdrafts are current liabilities.","C":"Incorrect because this reverses tangible and intangible assets.","D":"Incorrect because share capital and retained profit are shareholders' equity."}}},{"id":"P1_U5_MCQ_704","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_704","question":"Why does 'freehold land' generally NOT depreciate over time on a statement of financial position, whereas 'machinery and vehicles' do?","options":{"A":"Because land is classified as a current asset","B":"Because land has an unlimited useful life and does not wear out, whereas machinery and vehicles deteriorate through usage and become technologically obsolete","C":"Because businesses sell all their land at the end of every financial year","D":"Because machinery and vehicles are classified as current liabilities"},"correctOption":"B","correctAnswer":"Because land has an unlimited useful life and does not wear out, whereas machinery and vehicles deteriorate through usage and become technologically obsolete","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because depreciation spreads the cost of finite-life assets over their working lives, whereas land normally retains permanent utility.","distractor_reasons":{"A":"Incorrect because freehold land is a non-current asset.","B":"Option B is correct because depreciation spreads the cost of finite-life assets over their working lives, whereas land normally retains permanent utility.","C":"Incorrect because businesses hold freehold land for long-term operations.","D":"Incorrect because machinery and vehicles are non-current assets."}}},{"id":"P1_U5_MCQ_705","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_705","question":"How is the 'net book value' of a non-current asset (such as a delivery van) calculated on a statement of financial position?","options":{"A":"Original historical purchase cost + Accumulated depreciation","B":"Current selling price - Trade payables","C":"Original historical purchase cost - Accumulated depreciation to date","D":"Annual sales revenue - Cost of sales"},"correctOption":"C","correctAnswer":"Original historical purchase cost - Accumulated depreciation to date","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because net book value represents the remaining un-depreciated carrying value of the non-current asset on the reporting date.","distractor_reasons":{"A":"Incorrect because depreciation reduces rather than increases an asset's carrying value.","B":"Incorrect because trade payables are unrelated short-term supplier liabilities.","C":"Option C is correct because net book value represents the remaining un-depreciated carrying value of the non-current asset on the reporting date.","D":"Incorrect because revenue minus cost of sales calculates gross profit."}}},{"id":"P1_U5_MCQ_706","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_706","question":"In the context of ordering current assets on a statement of financial position, what does 'degree of liquidity' refer to?","options":{"A":"The physical weight of the assets stored in the warehouse","B":"The amount of corporation tax charged on each asset","C":"The interest rate paid on long-term commercial mortgages","D":"How quickly and easily each current asset can be converted into spendable cash without significant loss of value"},"correctOption":"D","correctAnswer":"How quickly and easily each current asset can be converted into spendable cash without significant loss of value","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because current assets are arranged in order of convertibility into cash: Inventories (least liquid) -> Trade receivables -> Cash (most liquid).","distractor_reasons":{"A":"Incorrect because liquidity is a financial concept, not a physical property.","B":"Incorrect because corporation tax is levied on profit, not individual current assets.","C":"Incorrect because mortgage rates apply to non-current debt liabilities.","D":"Option D is correct because current assets are arranged in order of convertibility into cash: Inventories (least liquid) -> Trade receivables -> Cash (most liquid)."}}},{"id":"P1_U5_MCQ_707","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_707","question":"Why are 'trade receivables' considered more liquid than 'inventories' on a statement of financial position?","options":{"A":"Because inventories are classified as non-current liabilities","B":"Because trade receivables are physical cash stored in the safe","C":"Because trade receivables represent goods already sold to customers who are contractually obligated to pay cash soon, whereas inventories still have to find buyers","D":"Because trade receivables never involve any risk of non-payment"},"correctOption":"C","correctAnswer":"Because trade receivables represent goods already sold to customers who are contractually obligated to pay cash soon, whereas inventories still have to find buyers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because receivables are one step closer to cash than unsold stock, which must still be marketed and sold.","distractor_reasons":{"A":"Incorrect because inventories are current assets.","B":"Incorrect because trade receivables are unpaid customer invoices, not physical cash yet.","C":"Option C is correct because receivables are one step closer to cash than unsold stock, which must still be marketed and sold.","D":"Incorrect because trade receivables still carry a small risk of bad debts."}}},{"id":"P1_U5_MCQ_708","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_708","question":"What financial risk arises if a business allows its 'trade receivables' balance to grow excessively large without strong credit control?","options":{"A":"The business will automatically have to pay higher dividends","B":"Cash is tied up outside the business, causing liquidity shortages, and some overdue customer invoices may turn into irrecoverable bad debts","C":"The business's non-current assets will lose all value","D":"The business will be banned from taking out long-term bank loans"},"correctOption":"B","correctAnswer":"Cash is tied up outside the business, causing liquidity shortages, and some overdue customer invoices may turn into irrecoverable bad debts","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high trade receivables starve the business of cash and increase exposure to customer defaults (bad debts).","distractor_reasons":{"A":"Incorrect because high receivables drain cash and make paying dividends harder, not mandatory.","B":"Option B is correct because high trade receivables starve the business of cash and increase exposure to customer defaults (bad debts).","C":"Incorrect because customer receivables do not affect non-current asset values.","D":"Incorrect because high receivables do not legally ban bank loans."}}},{"id":"P1_U5_MCQ_709","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_709","question":"What financial and operational risks arise when a business holds excessively high 'inventories' on its statement of financial position?","options":{"A":"High inventory guarantees instant cash liquidity whenever bills arrive","B":"High inventory eliminates all warehouse rent and insurance expenses","C":"Large amounts of working capital are tied up in unsold goods, storage and insurance costs rise, and stock risks spoiling or becoming obsolete","D":"High inventory reduces current assets and increases non-current liabilities"},"correctOption":"C","correctAnswer":"Large amounts of working capital are tied up in unsold goods, storage and insurance costs rise, and stock risks spoiling or becoming obsolete","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because overstocking drains cash liquidity and creates storage costs and write-down risks.","distractor_reasons":{"A":"Incorrect because inventory is the least liquid current asset and cannot immediately pay bills.","B":"Incorrect because holding more inventory increases warehouse storage and insurance expenses.","C":"Option C is correct because overstocking drains cash liquidity and creates storage costs and write-down risks.","D":"Incorrect because inventory is part of current assets."}}},{"id":"P1_U5_MCQ_710","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_710","question":"When does a business's bank account appear under 'current liabilities' instead of 'current assets' on a statement of financial position?","options":{"A":"Whenever the business holds positive cash savings in a deposit account","B":"Whenever the business receives payments from credit customers","C":"Whenever the business issues new ordinary shares","D":"Whenever the bank current account is overdrawn (a bank overdraft), meaning the business owes money to the bank"},"correctOption":"D","correctAnswer":"Whenever the bank current account is overdrawn (a bank overdraft), meaning the business owes money to the bank","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a positive bank balance is a current asset owned by the firm, whereas a negative (overdrawn) balance is a short-term debt owed to the bank.","distractor_reasons":{"A":"Incorrect because positive bank deposits are current assets.","B":"Incorrect because customer receipts increase positive cash assets.","C":"Incorrect because issuing shares brings cash into the bank.","D":"Option D is correct because a positive bank balance is a current asset owned by the firm, whereas a negative (overdrawn) balance is a short-term debt owed to the bank."}}},{"id":"P1_U5_MCQ_711","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_711","question":"How are 'bank overdrafts' and 'long-term bank loans' classified differently on a statement of financial position?","options":{"A":"Both are classified as non-current assets","B":"A bank overdraft is a current asset, whereas a long-term bank loan is shareholders' equity","C":"A bank overdraft is a current liability (due within 12 months), whereas a long-term bank loan is a non-current liability (repayable over more than 12 months)","D":"A bank overdraft is a non-current liability, whereas a long-term bank loan is a current liability"},"correctOption":"C","correctAnswer":"A bank overdraft is a current liability (due within 12 months), whereas a long-term bank loan is a non-current liability (repayable over more than 12 months)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because liabilities are separated by their repayment timeframe: under 12 months (current) vs over 12 months (non-current).","distractor_reasons":{"A":"Incorrect because borrowed funds are liabilities, not assets.","B":"Incorrect because both are external debt liabilities, not assets or equity.","C":"Option C is correct because liabilities are separated by their repayment timeframe: under 12 months (current) vs over 12 months (non-current).","D":"Incorrect because this reverses current and non-current classifications."}}},{"id":"P1_U5_MCQ_712","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_712","question":"Why is 'corporation tax owed' at the end of the financial year classified as a 'current liability' on a company's statement of financial position?","options":{"A":"Because corporation tax is owed to the company by government agencies","B":"Because it is a short-term financial obligation that must be paid to tax authorities within 12 months of the year-end","C":"Because corporation tax is part of issued share capital","D":"Because corporation tax is repayable over 25 years"},"correctOption":"B","correctAnswer":"Because it is a short-term financial obligation that must be paid to tax authorities within 12 months of the year-end","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unpaid tax at the reporting date is a short-term debt due within the next accounting year.","distractor_reasons":{"A":"Incorrect because the company owes tax to the government, making it a liability rather than an asset.","B":"Option B is correct because unpaid tax at the reporting date is a short-term debt due within the next accounting year.","C":"Incorrect because share capital is owners' equity.","D":"Incorrect because corporation tax is settled annually, not over 25 years."}}},{"id":"P1_U5_MCQ_713","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_713","question":"Why is the subtotal 'Current assets - Current liabilities' on a statement of financial position called both 'net current assets' and 'working capital'?","options":{"A":"Because it measures the value of all freehold buildings owned by the business","B":"Because it shows the total profit earned over the past five years","C":"Because it shows the net short-term liquid resources available to fund day-to-day operations after covering all short-term debts due within a year","D":"Because it equals the total amount of long-term mortgages owed to banks"},"correctOption":"C","correctAnswer":"Because it shows the net short-term liquid resources available to fund day-to-day operations after covering all short-term debts due within a year","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because net current assets represent the surplus of short-term trading assets over short-term trading liabilities, which forms operational working capital.","distractor_reasons":{"A":"Incorrect because freehold buildings are non-current assets.","B":"Incorrect because multi-year accumulated profit is retained profit under equity.","C":"Option C is correct because net current assets represent the surplus of short-term trading assets over short-term trading liabilities, which forms operational working capital.","D":"Incorrect because long-term mortgages are non-current liabilities."}}},{"id":"P1_U5_MCQ_714","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_714","question":"What warning sign does 'negative working capital' (where current liabilities exceed current assets) send to analysts?","options":{"A":"The business holds too much idle cash in its bank account","B":"The business has zero short-term trade payables","C":"The business is earning exceptionally high profit margins","D":"The business may struggle to pay its short-term debts as they fall due and faces serious liquidity risk"},"correctOption":"D","correctAnswer":"The business may struggle to pay its short-term debts as they fall due and faces serious liquidity risk","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because if short-term obligations exceed short-term assets, the business could run out of cash unless it has rapid cash turnover or unused overdraft facilities.","distractor_reasons":{"A":"Incorrect because negative working capital indicates a shortage, not an excess, of liquid assets.","B":"Incorrect because negative working capital occurs when short-term liabilities are high relative to current assets.","C":"Incorrect because working capital measures liquidity rather than profit margins.","D":"Option D is correct because if short-term obligations exceed short-term assets, the business could run out of cash unless it has rapid cash turnover or unused overdraft facilities."}}},{"id":"P1_U5_MCQ_715","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_715","question":"On a limited company's statement of financial position, what is 'Net assets' always equal to?","options":{"A":"Total non-current liabilities","B":"Total current liabilities","C":"Total shareholders' equity (Share capital + Retained profit reserves)","D":"Gross profit minus overhead expenses"},"correctOption":"C","correctAnswer":"Total shareholders' equity (Share capital + Retained profit reserves)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Net assets = Total assets - Total liabilities, which by the accounting equation equals Total shareholders' equity.","distractor_reasons":{"A":"Incorrect because non-current liabilities are already deducted when calculating net assets.","B":"Incorrect because current liabilities are already deducted when calculating net assets.","C":"Option C is correct because Net assets = Total assets - Total liabilities, which by the accounting equation equals Total shareholders' equity.","D":"Incorrect because gross profit minus overheads equals operating profit on the income statement."}}},{"id":"P1_U5_MCQ_716","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_716","question":"Within 'shareholders' equity' on a statement of financial position, how does 'issued share capital' differ from 'retained profit'?","options":{"A":"Issued share capital is borrowed from commercial banks, whereas retained profit is borrowed from suppliers","B":"Issued share capital is the original money invested directly by shareholders buying shares, whereas retained profit is cumulative profit earned by trading and kept inside the company","C":"Issued share capital is a current asset, whereas retained profit is a current liability","D":"Issued share capital must be repaid every year, whereas retained profit is paid to tax authorities"},"correctOption":"B","correctAnswer":"Issued share capital is the original money invested directly by shareholders buying shares, whereas retained profit is cumulative profit earned by trading and kept inside the company","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because share capital reflects external equity contributions from shareholders, while retained profit reflects internal wealth generated through profitable trading.","distractor_reasons":{"A":"Incorrect because neither is borrowed debt; both belong to shareholders.","B":"Option B is correct because share capital reflects external equity contributions from shareholders, while retained profit reflects internal wealth generated through profitable trading.","C":"Incorrect because both are components of shareholders' equity.","D":"Incorrect because share capital is permanent and retained profit remains in the business."}}},{"id":"P1_U5_MCQ_717","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_717","question":"Which two formulas are mathematically equivalent ways of expressing 'Capital employed' on a statement of financial position?","options":{"A":"'Current assets - Current liabilities' and 'Gross profit - Expenses'","B":"'Total revenue - Cost of sales' and 'Cash inflows - Cash outflows'","C":"'Total shareholders' equity + Non-current liabilities' and 'Non-current assets + Net current assets (working capital)'","D":"'Issued share capital - Retained profit' and 'Current liabilities + Non-current liabilities'"},"correctOption":"C","correctAnswer":"'Total shareholders' equity + Non-current liabilities' and 'Non-current assets + Net current assets (working capital)'","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because since Net assets (Non-current assets + Working capital - Non-current liabilities) equals Total equity, adding Non-current liabilities back to both sides gives Capital employed.","distractor_reasons":{"A":"Incorrect because these calculate working capital and operating profit respectively.","B":"Incorrect because these calculate gross profit and net cash flow respectively.","C":"Option C is correct because since Net assets (Non-current assets + Working capital - Non-current liabilities) equals Total equity, adding Non-current liabilities back to both sides gives Capital employed.","D":"Incorrect because retained profit is added to share capital, and current liabilities are excluded from capital employed."}}},{"id":"P1_U5_MCQ_718","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_718","question":"When a business purchases raw material inventory on 30-day trade credit, what is the immediate effect on its statement of financial position?","options":{"A":"Current assets (inventories) increase and current liabilities (trade payables) increase by the same amount, leaving working capital unchanged","B":"Current assets (cash) decrease and shareholders' equity decreases","C":"Non-current assets increase and non-current liabilities increase","D":"Working capital doubles immediately"},"correctOption":"A","correctAnswer":"Current assets (inventories) increase and current liabilities (trade payables) increase by the same amount, leaving working capital unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receiving stock adds to inventories (+current asset) while owing the supplier adds to trade payables (+current liability) equally.","distractor_reasons":{"A":"Option A is correct because receiving stock adds to inventories (+current asset) while owing the supplier adds to trade payables (+current liability) equally.","B":"Incorrect because buying on credit uses no cash immediately and does not reduce equity.","C":"Incorrect because raw materials are current assets and 30-day credit is a current liability.","D":"Incorrect because equal increases in current assets and current liabilities leave Net current assets unchanged."}}},{"id":"P1_U5_MCQ_719","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_719","question":"When a credit customer pays an outstanding invoice in cash, how does this transaction change the business's statement of financial position?","options":{"A":"Total current assets increase by the payment amount","B":"Cash (current asset) increases and trade receivables (current asset) decrease by the exact same amount, leaving total current assets unchanged","C":"Current liabilities (trade payables) decrease","D":"Shareholders' equity increases by the payment amount"},"correctOption":"B","correctAnswer":"Cash (current asset) increases and trade receivables (current asset) decrease by the exact same amount, leaving total current assets unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because collecting a receivable swaps one current asset (unpaid invoice) for another current asset (cash) of equal value.","distractor_reasons":{"A":"Incorrect because cash rises while trade receivables fall by the exact same figure.","B":"Option B is correct because collecting a receivable swaps one current asset (unpaid invoice) for another current asset (cash) of equal value.","C":"Incorrect because customer payments affect trade receivables, not trade payables.","D":"Incorrect because profit was already recognized when the credit sale was originally made."}}},{"id":"P1_U5_MCQ_720","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_720","question":"When a business uses cash from its bank current account to repay part of a long-term bank loan, what happens on its statement of financial position?","options":{"A":"Current assets (cash) increase and non-current liabilities increase","B":"Current liabilities decrease and shareholders' equity increases","C":"Current assets (cash) decrease and non-current liabilities decrease by the same amount, leaving net assets unchanged","D":"Non-current assets decrease and retained profit increases"},"correctOption":"C","correctAnswer":"Current assets (cash) decrease and non-current liabilities decrease by the same amount, leaving net assets unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because using cash (-current asset) to pay down long-term debt (-non-current liability) reduces assets and liabilities equally.","distractor_reasons":{"A":"Incorrect because paying off debt reduces cash and reduces debt.","B":"Incorrect because a long-term bank loan is a non-current liability, and repaying principal does not create equity.","C":"Option C is correct because using cash (-current asset) to pay down long-term debt (-non-current liability) reduces assets and liabilities equally.","D":"Incorrect because cash is a current asset and debt repayment does not create retained profit."}}},{"id":"P1_U5_MCQ_721","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_721","question":"When a business buys a new delivery vehicle using cash from its bank account, what is the net effect on 'total assets' and 'working capital'?","options":{"A":"Total assets increase and working capital increases","B":"Total assets decrease and working capital stays unchanged","C":"Non-current liabilities increase and working capital increases","D":"Non-current assets increase and current assets (cash) decrease by the same amount, so total assets stay unchanged while working capital decreases"},"correctOption":"D","correctAnswer":"Non-current assets increase and current assets (cash) decrease by the same amount, so total assets stay unchanged while working capital decreases","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash (a current asset) is converted into a vehicle (a non-current asset); total assets remain constant, but current assets—and thus working capital—fall.","distractor_reasons":{"A":"Incorrect because cash falls by the exact price of the vehicle.","B":"Incorrect because total assets are unchanged while working capital falls.","C":"Incorrect because buying for cash creates no debt liability.","D":"Option D is correct because cash (a current asset) is converted into a vehicle (a non-current asset); total assets remain constant, but current assets—and thus working capital—fall."}}},{"id":"P1_U5_MCQ_722","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_722","question":"Which of the following would be classified as a current liability on a statement of financial position?","options":{"A":"A bank loan repayable in five years","B":"Land and buildings","C":"Amounts owed to suppliers (trade payables)","D":"Share capital"},"correctOption":"C","correctAnswer":"Amounts owed to suppliers (trade payables)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because trade payables are short-term debts that must normally be settled within one year, making them current liabilities.","distractor_reasons":{"A":"Incorrect because a loan repayable in five years is a non-current (long-term) liability, not a current one.","B":"Incorrect because land and buildings are non-current assets owned by the business, not liabilities.","C":"Option C is correct because trade payables are short-term debts that must normally be settled within one year, making them current liabilities.","D":"Incorrect because share capital represents the owners' investment and appears in equity, not among liabilities."}}},{"id":"P1_U5_MCQ_723","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_723","question":"Why does a company planning to take over (acquire) another business carefully examine the target company's statement of financial position?","options":{"A":"Because the statement of financial position lists the personal savings of all rival managers","B":"Because the statement of financial position guarantees future customer demand","C":"Because acquiring the company means taking over all its non-current and current assets as well as all its short-term and long-term liabilities","D":"Because tax authorities prohibit takeovers unless current liabilities are zero"},"correctOption":"C","correctAnswer":"Because acquiring the company means taking over all its non-current and current assets as well as all its short-term and long-term liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a buyer inherits both the target's assets and its debts, making net asset value and liability obligations central to takeover valuation.","distractor_reasons":{"A":"Incorrect because personal finances of managers are excluded from company statements.","B":"Incorrect because balance sheets show historical positions, not future demand guarantees.","C":"Option C is correct because a buyer inherits both the target's assets and its debts, making net asset value and liability obligations central to takeover valuation.","D":"Incorrect because virtually all operating businesses have some current liabilities."}}},{"id":"P1_U5_MCQ_724","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_724","question":"How are 'inventories' normally valued on a statement of financial position, and why can this understate potential cash inflows?","options":{"A":"Inventories are valued at double their retail selling price, overstating cash","B":"Inventories are valued at their purchase/production cost (or lower realizable value) rather than their full retail selling price, excluding the profit margin expected upon sale","C":"Inventories are omitted completely from the statement of financial position","D":"Inventories are valued at the same price as freehold land"},"correctOption":"B","correctAnswer":"Inventories are valued at their purchase/production cost (or lower realizable value) rather than their full retail selling price, excluding the profit margin expected upon sale","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because under accounting prudence rules, unsold stock is recorded at cost rather than anticipated selling price until a sale actually takes place.","distractor_reasons":{"A":"Incorrect because accounting rules forbid recording unrealized retail profit before goods are sold.","B":"Option B is correct because under accounting prudence rules, unsold stock is recorded at cost rather than anticipated selling price until a sale actually takes place.","C":"Incorrect because inventories are a core component of current assets.","D":"Incorrect because inventories are valued based on their own purchase or manufacturing cost."}}},{"id":"P1_U5_MCQ_725","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_725","question":"Why can the year-end reporting date of a 'statement of financial position' create a slightly distorted picture of a business's typical liquidity?","options":{"A":"Because statements of financial position are legally allowed to omit all bank overdrafts on the last day of the year","B":"Because non-current assets disappear on the reporting date","C":"Because a single-day snapshot may fall right after a seasonal cash peak or temporary working capital adjustment ('window dressing') that does not reflect typical mid-year cash levels","D":"Because share capital is reset to zero on the reporting date"},"correctOption":"C","correctAnswer":"Because a single-day snapshot may fall right after a seasonal cash peak or temporary working capital adjustment ('window dressing') that does not reflect typical mid-year cash levels","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because balance sheets capture a single day's position, which may look unusually strong or weak depending on seasonal cycles or year-end payment timing.","distractor_reasons":{"A":"Incorrect because all liabilities must be reported truthfully on the reporting date.","B":"Incorrect because non-current assets remain recorded at net book value.","C":"Option C is correct because balance sheets capture a single day's position, which may look unusually strong or weak depending on seasonal cycles or year-end payment timing.","D":"Incorrect because share capital remains permanently on the statement."}}},{"id":"P1_U5_MCQ_726","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_726","question":"Which grouping correctly separates 'profitability ratios' from 'liquidity ratios'?","options":{"A":"Profitability ratios: Current ratio and Acid-test ratio; Liquidity ratios: Gross profit margin, Profit margin, and ROCE","B":"Profitability ratios: Gross profit margin and Current ratio; Liquidity ratios: Profit margin and ROCE","C":"Profitability ratios: ROCE and Acid-test ratio; Liquidity ratios: Gross profit margin and Profit margin","D":"Profitability ratios: Gross profit margin, Profit margin, and Return on Capital Employed (ROCE); Liquidity ratios: Current ratio and Acid-test ratio"},"correctOption":"D","correctAnswer":"Profitability ratios: Gross profit margin, Profit margin, and Return on Capital Employed (ROCE); Liquidity ratios: Current ratio and Acid-test ratio","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profitability ratios measure profit relative to sales or capital invested, whereas liquidity ratios measure short-term assets relative to short-term liabilities.","distractor_reasons":{"A":"Incorrect because this reverses profitability and liquidity ratios.","B":"Incorrect because the current ratio is a liquidity ratio, while profit margin and ROCE are profitability ratios.","C":"Incorrect because ROCE is a profitability ratio and the acid-test ratio is a liquidity ratio.","D":"Option D is correct because profitability ratios measure profit relative to sales or capital invested, whereas liquidity ratios measure short-term assets relative to short-term liabilities."}}},{"id":"P1_U5_MCQ_727","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_727","question":"Why is calculating 'profit margin (%)' more informative than looking at dollar profit alone when tracking a growing business over five years?","options":{"A":"Because profit margin measures the exact cash balance in the bank","B":"Because dollar profit figures are illegal to publish in annual reports","C":"Because profit margin reveals whether profit is growing faster or slower than sales revenue, showing if cost control is improving or slipping as sales expand","D":"Because profit margin automatically eliminates all overhead expenses"},"correctOption":"C","correctAnswer":"Because profit margin reveals whether profit is growing faster or slower than sales revenue, showing if cost control is improving or slipping as sales expand","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because if sales double while profit rises by only 10%, dollar profit looks higher, but a falling profit margin warns that costs are rising faster than revenue.","distractor_reasons":{"A":"Incorrect because profit margin is calculated from profit and revenue, not bank cash.","B":"Incorrect because dollar profit figures are always published in financial statements.","C":"Option C is correct because if sales double while profit rises by only 10%, dollar profit looks higher, but a falling profit margin warns that costs are rising faster than revenue.","D":"Incorrect because profit margin is calculated *after* deducting overhead expenses."}}},{"id":"P1_U5_MCQ_728","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_728","question":"Which combination of events would directly increase a business's 'gross profit margin'?","options":{"A":"Lowering selling prices while paying higher prices for raw materials","B":"Raising selling prices (without losing proportional volume) or negotiating cheaper raw material/wholesale purchase costs per unit","C":"Reducing head-office administrative salaries and television advertising","D":"Issuing new ordinary shares and repaying a long-term bank loan"},"correctOption":"B","correctAnswer":"Raising selling prices (without losing proportional volume) or negotiating cheaper raw material/wholesale purchase costs per unit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because gross profit margin depends on the spread between unit selling price and direct unit cost of sales.","distractor_reasons":{"A":"Incorrect because lower prices and higher input costs would shrink gross profit margin.","B":"Option B is correct because gross profit margin depends on the spread between unit selling price and direct unit cost of sales.","C":"Incorrect because reducing indirect overheads improves profit margin, not gross profit margin.","D":"Incorrect because financing changes do not alter gross profit margin."}}},{"id":"P1_U5_MCQ_729","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_729","question":"A company's profit after tax fell from $50,000 to $40,000 while its sales revenue stayed the same. Which measure must therefore have fallen?","options":{"A":"Acid-test ratio","B":"Gross profit margin","C":"Current ratio","D":"Profit margin"},"correctOption":"D","correctAnswer":"Profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit margin is profit divided by revenue; with revenue unchanged and profit lower, the margin must fall.","distractor_reasons":{"A":"Incorrect because the acid-test ratio measures liquidity and is unrelated to the fall in profit after tax.","B":"Incorrect because gross profit depends on cost of sales, which may have changed, so gross profit margin need not have fallen.","C":"Incorrect because the current ratio concerns current assets and liabilities, which are not affected by this profit change alone.","D":"Option D is correct because profit margin is profit divided by revenue; with revenue unchanged and profit lower, the margin must fall."}}},{"id":"P1_U5_MCQ_730","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_730","question":"How can a business improve its 'profit margin' even when its 'gross profit margin' remains completely unchanged?","options":{"A":"By increasing raw material wastage in the factory","B":"By doubling the bank overdraft limit","C":"By buying more freehold land for cash","D":"By reducing indirect overhead expenses (such as head-office admin, rent, or energy bills) relative to sales revenue"},"correctOption":"D","correctAnswer":"By reducing indirect overhead expenses (such as head-office admin, rent, or energy bills) relative to sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because controlling indirect overhead expenses allows a larger share of gross profit to convert into final operating profit.","distractor_reasons":{"A":"Incorrect because higher material wastage increases cost of sales and lowers both gross profit margin and profit margin.","B":"Incorrect because raising an overdraft limit does not reduce operating expenses.","C":"Incorrect because buying land is capital expenditure and does not improve operating profit margin.","D":"Option D is correct because controlling indirect overhead expenses allows a larger share of gross profit to convert into final operating profit."}}},{"id":"P1_U5_MCQ_731","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_731","question":"Why is 'Return on Capital Employed (ROCE)' often referred to as the 'primary ratio' when evaluating overall business performance?","options":{"A":"Because it is always equal to 100% for every limited company","B":"Because it is the only ratio that can be calculated without any financial statements","C":"Because it measures whether the business can pay next week's electricity bill","D":"Because it links profit directly to the total long-term capital invested in the business, measuring how effectively management generates returns on every dollar of capital employed"},"correctOption":"D","correctAnswer":"Because it links profit directly to the total long-term capital invested in the business, measuring how effectively management generates returns on every dollar of capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ROCE combines profitability and capital efficiency into a single benchmark comparable across firms and against interest rates.","distractor_reasons":{"A":"Incorrect because ROCE varies widely across businesses and typically ranges between 5% and 25%.","B":"Incorrect because calculating ROCE requires profit from the income statement and capital employed from the statement of financial position.","C":"Incorrect because short-term bill-paying ability is measured by liquidity ratios.","D":"Option D is correct because ROCE combines profitability and capital efficiency into a single benchmark comparable across firms and against interest rates."}}},{"id":"P1_U5_MCQ_732","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_732","question":"What happens to a company's 'Return on Capital Employed (ROCE)' if its operating profit increases while its capital employed remains unchanged?","options":{"A":"ROCE decreases","B":"ROCE increases, showing improved efficiency in generating profit from existing capital","C":"ROCE remains completely unchanged","D":"ROCE becomes negative"},"correctOption":"B","correctAnswer":"ROCE increases, showing improved efficiency in generating profit from existing capital","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ROCE = (Profit / Capital employed) × 100; a larger numerator with a constant denominator raises the percentage return.","distractor_reasons":{"A":"Incorrect because higher profit increases rather than decreases ROCE.","B":"Option B is correct because ROCE = (Profit / Capital employed) × 100; a larger numerator with a constant denominator raises the percentage return.","C":"Incorrect because ROCE changes whenever profit or capital employed changes.","D":"Incorrect because rising positive profit keeps ROCE positive."}}},{"id":"P1_U5_MCQ_733","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_733","question":"Why might a company's 'ROCE' temporarily *fall* in the year immediately after it borrows a large long-term loan to build a new factory?","options":{"A":"Because building a new factory permanently reduces sales revenue","B":"Because bank loans are subtracted from capital employed","C":"Because capital employed increases immediately by the new loan, whereas the new factory may take time to be completed and generate full additional profits","D":"Because factories are classified as current liabilities"},"correctOption":"C","correctAnswer":"Because capital employed increases immediately by the new loan, whereas the new factory may take time to be completed and generate full additional profits","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed (denominator) rises immediately upon raising long-term finance, while profit (numerator) lags until the new capacity operates fully.","distractor_reasons":{"A":"Incorrect because a new factory is built to expand future output and revenue.","B":"Incorrect because non-current liabilities are added to equity to form capital employed.","C":"Option C is correct because capital employed (denominator) rises immediately upon raising long-term finance, while profit (numerator) lags until the new capacity operates fully.","D":"Incorrect because factories are non-current assets."}}},{"id":"P1_U5_MCQ_734","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_734","question":"Why is comparing 'ROCE' between a heavy steel manufacturer and a freelance software consultancy misleading?","options":{"A":"Because software consultancies are forbidden from earning profit","B":"Because steel manufacturers do not hold any non-current assets","C":"Because ROCE can only be calculated for retail shops","D":"Because steel manufacturing is highly capital-intensive (requiring huge capital employed in plants and machinery), whereas software consultancies require minimal physical capital, naturally giving different ROCE norms"},"correctOption":"D","correctAnswer":"Because steel manufacturing is highly capital-intensive (requiring huge capital employed in plants and machinery), whereas software consultancies require minimal physical capital, naturally giving different ROCE norms","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because valid inter-firm ratio comparisons must compare businesses within the same industry and with similar capital structures.","distractor_reasons":{"A":"Incorrect because software consultancies are profit-seeking businesses.","B":"Incorrect because steel manufacturers own massive non-current assets.","C":"Incorrect because ROCE can be calculated for any business.","D":"Option D is correct because valid inter-firm ratio comparisons must compare businesses within the same industry and with similar capital structures."}}},{"id":"P1_U5_MCQ_735","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_735","question":"What is generally regarded as a safe, comfortable benchmark range for the 'current ratio' in most traditional manufacturing and trading businesses?","options":{"A":"Between 1.5 : 1 and 2.0 : 1","B":"Below 0.5 : 1","C":"Above 10.0 : 1","D":"Exactly 0 : 1"},"correctOption":"A","correctAnswer":"Between 1.5 : 1 and 2.0 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a current ratio of 1.5 : 1 to 2.0 : 1 means current assets comfortably cover short-term liabilities without tying up excessive idle working capital.","distractor_reasons":{"A":"Option A is correct because a current ratio of 1.5 : 1 to 2.0 : 1 means current assets comfortably cover short-term liabilities without tying up excessive idle working capital.","B":"Incorrect because a ratio below 0.5 : 1 indicates severe liquidity danger.","C":"Incorrect because a ratio above 10 : 1 indicates massive unproductive working capital.","D":"Incorrect because a 0 : 1 ratio would mean having zero current assets."}}},{"id":"P1_U5_MCQ_736","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_736","question":"Why can large supermarket chains often operate safely with a 'current ratio' around 1.0 : 1 or slightly lower, whereas a heavy machinery manufacturer would struggle at that level?","options":{"A":"Because supermarkets never have any current liabilities","B":"Because supermarkets sell goods immediately for cash every day while paying food suppliers on 30- to 60-day credit, generating continuous cash inflows before payables fall due","C":"Because machinery manufacturers sell all equipment for instant cash on Day 1","D":"Because supermarkets are exempt from paying their suppliers"},"correctOption":"B","correctAnswer":"Because supermarkets sell goods immediately for cash every day while paying food suppliers on 30- to 60-day credit, generating continuous cash inflows before payables fall due","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because negative or tight working capital works safely when stock turns into cash faster than supplier credit terms expire.","distractor_reasons":{"A":"Incorrect because supermarkets carry substantial trade payables.","B":"Option B is correct because negative or tight working capital works safely when stock turns into cash faster than supplier credit terms expire.","C":"Incorrect because machinery manufacturers have long production cycles and sell on credit.","D":"Incorrect because supermarkets must pay their suppliers in full."}}},{"id":"P1_U5_MCQ_737","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_737","question":"Which action would directly *improve* a business's dangerously low 'current ratio'?","options":{"A":"Using cash from the bank account to buy expensive new factory machinery","B":"Taking out a short-term bank overdraft to pay shareholder dividends","C":"Selling surplus, underused non-current assets for cash or raising long-term finance (such as a share issue or long-term loan) to boost cash and pay down short-term overdrafts","D":"Increasing the amount of cash withdrawn as owner drawings"},"correctOption":"C","correctAnswer":"Selling surplus, underused non-current assets for cash or raising long-term finance (such as a share issue or long-term loan) to boost cash and pay down short-term overdrafts","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because injecting long-term funds or converting illiquid non-current assets into cash increases current assets relative to current liabilities.","distractor_reasons":{"A":"Incorrect because spending cash on non-current assets reduces current assets and lowers the current ratio further.","B":"Incorrect because increasing an overdraft and paying out cash reduces working capital and worsens liquidity.","C":"Option C is correct because injecting long-term funds or converting illiquid non-current assets into cash increases current assets relative to current liabilities.","D":"Incorrect because higher drawings drain cash and worsen the current ratio."}}},{"id":"P1_U5_MCQ_738","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_738","question":"What does an 'acid-test ratio' of at least 1 : 1 signify about a business's short-term liquidity?","options":{"A":"The business has zero inventory in its warehouse","B":"The business earns $1 of profit for every $1 of sales revenue","C":"The business's non-current assets equal its non-current liabilities","D":"The business can cover all of its immediate current liabilities using only its liquid cash and trade receivables, without relying on selling any inventory"},"correctOption":"D","correctAnswer":"The business can cover all of its immediate current liabilities using only its liquid cash and trade receivables, without relying on selling any inventory","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an acid-test ratio of 1 : 1 or higher means liquid assets (Current assets - Inventories) equal or exceed current liabilities.","distractor_reasons":{"A":"Incorrect because a business can hold substantial inventory and still have an acid-test ratio above 1 : 1.","B":"Incorrect because profit per dollar of sales is profit margin, not the acid-test ratio.","C":"Incorrect because the acid-test ratio only examines current items.","D":"Option D is correct because an acid-test ratio of 1 : 1 or higher means liquid assets (Current assets - Inventories) equal or exceed current liabilities."}}},{"id":"P1_U5_MCQ_739","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_739","question":"Why is a business's 'acid-test ratio' always lower than (or at most equal to) its 'current ratio'?","options":{"A":"Because inventories are subtracted from the numerator in the acid-test ratio while the denominator (current liabilities) stays the same","B":"Because current liabilities are doubled in the acid-test ratio","C":"Because non-current assets are added to the current ratio","D":"Because trade receivables are subtracted from the current ratio"},"correctOption":"A","correctAnswer":"Because inventories are subtracted from the numerator in the acid-test ratio while the denominator (current liabilities) stays the same","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because subtracting non-negative inventory reduces the numerator, making the acid-test ratio smaller than the current ratio (or equal only if inventory is zero).","distractor_reasons":{"A":"Option A is correct because subtracting non-negative inventory reduces the numerator, making the acid-test ratio smaller than the current ratio (or equal only if inventory is zero).","B":"Incorrect because both ratios use the exact same current liabilities denominator.","C":"Incorrect because neither ratio includes non-current assets.","D":"Incorrect because trade receivables remain in the numerator of both ratios."}}},{"id":"P1_U5_MCQ_740","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_740","question":"If a business holds a promotional clearance sale that converts slow-moving inventory into cash, how does this affect its 'acid-test ratio'?","options":{"A":"The acid-test ratio decreases","B":"The acid-test ratio increases because cash (included in the acid-test numerator) rises while inventory (excluded from the acid-test numerator) falls","C":"The acid-test ratio remains completely unchanged","D":"The acid-test ratio becomes zero"},"correctOption":"B","correctAnswer":"The acid-test ratio increases because cash (included in the acid-test numerator) rises while inventory (excluded from the acid-test numerator) falls","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because shifting value out of excluded inventory and into liquid cash raises the acid-test numerator without changing current liabilities.","distractor_reasons":{"A":"Incorrect because increasing cash raises rather than lowers the acid-test ratio.","B":"Option B is correct because shifting value out of excluded inventory and into liquid cash raises the acid-test numerator without changing current liabilities.","C":"Incorrect because converting excluded stock into included cash changes the acid-test numerator.","D":"Incorrect because higher cash creates a positive numerator."}}},{"id":"P1_U5_MCQ_741","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_741","question":"Which list contains ONLY 'external users' of a business's financial accounts?","options":{"A":"Departmental managers, factory supervisors, and internal financial controllers","B":"Board of directors, internal accountants, and commercial banks","C":"Commercial banks, trade suppliers, government tax authorities, potential investors, and trade unions","D":"Chief executive officer, marketing director, and operations manager"},"correctOption":"C","correctAnswer":"Commercial banks, trade suppliers, government tax authorities, potential investors, and trade unions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because banks, suppliers, tax authorities, outside investors, and trade unions operate outside the company's internal management structure.","distractor_reasons":{"A":"Incorrect because departmental managers, supervisors, and financial controllers are internal users.","B":"Incorrect because the board of directors and internal accountants are internal users.","C":"Option C is correct because banks, suppliers, tax authorities, outside investors, and trade unions operate outside the company's internal management structure.","D":"Incorrect because the CEO, marketing director, and operations manager are internal executives."}}},{"id":"P1_U5_MCQ_742","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_742","question":"Why do internal managers prepare monthly or quarterly 'management accounts' rather than waiting for the annual published financial statements?","options":{"A":"Because annual published accounts are illegal for managers to read","B":"Because annual accounts omit all revenue and profit figures","C":"Because monthly management accounts replace the need to pay corporation tax","D":"Because managers need timely, product-level and branch-level data throughout the year to spot problems early and make rapid operational decisions"},"correctOption":"D","correctAnswer":"Because managers need timely, product-level and branch-level data throughout the year to spot problems early and make rapid operational decisions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because annual published statements summarize the whole business too late for day-to-day operational control.","distractor_reasons":{"A":"Incorrect because managers obviously review annual accounts as well.","B":"Incorrect because annual accounts include full revenue and profit statements.","C":"Incorrect because corporation tax is still assessed annually.","D":"Option D is correct because annual published statements summarize the whole business too late for day-to-day operational control."}}},{"id":"P1_U5_MCQ_743","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_743","question":"Why do 'commercial banks' analyze *both* profitability ratios and liquidity ratios before granting a long-term business loan?","options":{"A":"Because liquidity ratios measure employee motivation while profitability ratios measure factory size","B":"Because banks require both ratios to be identical before approving any loan","C":"Because banks take direct control of the borrower's marketing department","D":"Profitability ratios show whether the business is viable enough to earn future profits and afford interest, while liquidity ratios show whether it has enough short-term cash to pay instalments on time without defaulting"},"correctOption":"D","correctAnswer":"Profitability ratios show whether the business is viable enough to earn future profits and afford interest, while liquidity ratios show whether it has enough short-term cash to pay instalments on time without defaulting","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a business needs both long-term earning power (profitability) and immediate cash-paying capacity (liquidity) to service debt reliably.","distractor_reasons":{"A":"Incorrect because both sets of ratios measure financial performance, not motivation or factory size.","B":"Incorrect because profitability percentages and liquidity ratios are measured on completely different scales.","C":"Incorrect because banks are lenders, not operational managers.","D":"Option D is correct because a business needs both long-term earning power (profitability) and immediate cash-paying capacity (liquidity) to service debt reliably."}}},{"id":"P1_U5_MCQ_744","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_744","question":"Why do 'trade unions' examine a company's liquidity ratios alongside its profit figures during wage negotiations?","options":{"A":"To calculate the exact market value of the company's patents","B":"To check whether the company actually has enough liquid cash to afford a wage rise without triggering a cash crisis or redundancies","C":"To decide whether the company should issue debentures on the stock exchange","D":"To audit the company's supplier invoices"},"correctOption":"B","correctAnswer":"To check whether the company actually has enough liquid cash to afford a wage rise without triggering a cash crisis or redundancies","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high paper profits do not automatically mean spare cash; unions check liquidity to ensure wage demands are sustainable and protect jobs.","distractor_reasons":{"A":"Incorrect because intangible patents are not measured by liquidity ratios.","B":"Option B is correct because high paper profits do not automatically mean spare cash; unions check liquidity to ensure wage demands are sustainable and protect jobs.","C":"Incorrect because financing decisions belong to directors and shareholders.","D":"Incorrect because independent external auditors audit company accounts."}}},{"id":"P1_U5_MCQ_745","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_745","question":"Why might the 'local community' and 'pressure groups' examine the published annual reports and accounts of a large local factory?","options":{"A":"To collect corporation tax directly from the factory","B":"To approve the factory's short-term bank overdraft","C":"To assess whether the factory is financially stable enough to protect local employment and whether it invests in environmentally responsible practices","D":"To set the factory's wholesale selling prices"},"correctOption":"C","correctAnswer":"To assess whether the factory is financially stable enough to protect local employment and whether it invests in environmentally responsible practices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local residents and campaigners care about regional job stability and corporate social/environmental responsibility.","distractor_reasons":{"A":"Incorrect because only government tax authorities collect corporation tax.","B":"Incorrect because commercial banks approve overdrafts.","C":"Option C is correct because local residents and campaigners care about regional job stability and corporate social/environmental responsibility.","D":"Incorrect because company managers set selling prices."}}},{"id":"P1_U5_MCQ_746","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_746","question":"Why can comparing ratios between two businesses in the *same* industry still be misleading if one is a massive multinational and the other is a small local firm?","options":{"A":"Because small local firms never calculate gross profit","B":"Because multinational corporations are legally banned from having current liabilities","C":"Because small local firms always have higher ROCE than multinationals","D":"Because large multinationals benefit from economies of scale (such as bulk-buying discounts and lower unit overheads) that small local competitors cannot access"},"correctOption":"D","correctAnswer":"Because large multinationals benefit from economies of scale (such as bulk-buying discounts and lower unit overheads) that small local competitors cannot access","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because valid inter-firm comparison requires comparing businesses of comparable scale as well as the same industry.","distractor_reasons":{"A":"Incorrect because small firms also calculate gross profit.","B":"Incorrect because multinationals carry substantial current liabilities.","C":"Incorrect because ROCE varies depending on performance and capital structure.","D":"Option D is correct because valid inter-firm comparison requires comparing businesses of comparable scale as well as the same industry."}}},{"id":"P1_U5_MCQ_747","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_747","question":"Which of the following is a recognised limitation of using ratio analysis to compare two different businesses?","options":{"A":"Ratios can only be calculated for sole traders","B":"Ratios give a complete and certain picture of a firm's future prospects","C":"Ratios can be distorted by different accounting policies and do not explain the reasons behind the figures","D":"Ratios cannot be calculated from published financial statements"},"correctOption":"C","correctAnswer":"Ratios can be distorted by different accounting policies and do not explain the reasons behind the figures","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because differences in accounting methods and the lack of explanation behind the numbers limit comparisons between firms.","distractor_reasons":{"A":"Incorrect because ratios can be calculated for companies and other businesses, not only for sole traders.","B":"Incorrect because ratios describe past performance and cannot provide certainty about future prospects.","C":"Option C is correct because differences in accounting methods and the lack of explanation behind the numbers limit comparisons between firms.","D":"Incorrect because published statements of profit or loss and financial position provide the data needed to calculate many ratios."}}},{"id":"P1_U5_MCQ_748","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_748","question":"Why must investors and managers consider 'qualitative factors' alongside financial ratios when evaluating a business?","options":{"A":"Because financial ratios are illegal to use in business decision-making","B":"Because ratios measure only numerical accounting data and ignore crucial qualitative strengths or risks such as staff morale, customer loyalty, product innovation, and new competitors","C":"Because qualitative factors automatically calculate the acid-test ratio","D":"Because financial statements already include exact dollar values for employee motivation"},"correctOption":"B","correctAnswer":"Because ratios measure only numerical accounting data and ignore crucial qualitative strengths or risks such as staff morale, customer loyalty, product innovation, and new competitors","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-financial factors heavily drive future profitability and survival, even though they cannot be captured directly in accounting ratios.","distractor_reasons":{"A":"Incorrect because financial ratios are a standard, essential analytical tool.","B":"Option B is correct because non-financial factors heavily drive future profitability and survival, even though they cannot be captured directly in accounting ratios.","C":"Incorrect because the acid-test ratio is purely quantitative.","D":"Incorrect because employee motivation cannot be quantified in monetary terms on financial statements."}}},{"id":"P1_U5_MCQ_749","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_749","question":"How can 'different financial year-end dates' between two competing companies distort inter-firm ratio comparisons?","options":{"A":"Companies with different year-ends are prohibited from calculating ROCE","B":"Companies with a June year-end never have any trade receivables","C":"In seasonal industries, one company's reporting date may fall at peak stock/cash season while its rival's date falls in a quiet off-peak month, distorting inventory and liquidity ratios","D":"Different year-ends double a company's gross profit margin"},"correctOption":"C","correctAnswer":"In seasonal industries, one company's reporting date may fall at peak stock/cash season while its rival's date falls in a quiet off-peak month, distorting inventory and liquidity ratios","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because balance sheet figures (such as inventories and cash) fluctuate seasonally, making comparisons across different calendar dates uneven.","distractor_reasons":{"A":"Incorrect because any business can calculate ROCE regardless of its fiscal year-end.","B":"Incorrect because trade receivables exist whenever goods are sold on credit.","C":"Option C is correct because balance sheet figures (such as inventories and cash) fluctuate seasonally, making comparisons across different calendar dates uneven.","D":"Incorrect because reporting dates do not double gross profit margins."}}},{"id":"P1_U5_MCQ_750","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_750","question":"What is the best overall approach for an analyst or manager using financial information to make strategic business decisions?","options":{"A":"Rely exclusively on a single ratio such as gross profit margin and ignore all other documents","B":"Ignore all financial ratios and rely purely on intuition","C":"Look only at cash in the bank and ignore profitability and debt obligations","D":"Combine profitability ratios, liquidity ratios, multi-year trends, industry benchmarks, cash flow forecasts, and qualitative market information for a balanced evaluation"},"correctOption":"D","correctAnswer":"Combine profitability ratios, liquidity ratios, multi-year trends, industry benchmarks, cash flow forecasts, and qualitative market information for a balanced evaluation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because every financial statement and ratio has limitations in isolation; combining quantitative ratios, forward cash forecasts, and qualitative context produces sound decisions.","distractor_reasons":{"A":"Incorrect because focusing on a single ratio ignores liquidity, capital efficiency, and market context.","B":"Incorrect because ignoring financial data leads to uninformed, high-risk decisions.","C":"Incorrect because cash alone does not show whether the business is profitable or heavily indebted.","D":"Option D is correct because every financial statement and ratio has limitations in isolation; combining quantitative ratios, forward cash forecasts, and qualitative context produces sound decisions."}}},{"id":"P1_U5_MCQ_751","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_751","question":"What is the primary role of the 'finance department' within a business organization?","options":{"A":"Operating factory machinery and inspecting finished goods for quality defects","B":"Designing product packaging and running television advertising campaigns","C":"Recruiting production line workers and negotiating union wage agreements","D":"Raising funds, managing cash flows, budgeting, and recording financial transactions to support business decisions"},"correctOption":"D","correctAnswer":"Raising funds, managing cash flows, budgeting, and recording financial transactions to support business decisions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the finance function manages capital raising, liquidity, budgets, and financial accounting records across the organization.","distractor_reasons":{"A":"Incorrect because manufacturing and quality control belong to the operations department.","B":"Incorrect because product packaging and advertising belong to the marketing department.","C":"Incorrect because recruitment and industrial relations belong to the human resources department.","D":"Option D is correct because the finance function manages capital raising, liquidity, budgets, and financial accounting records across the organization."}}},{"id":"P1_U5_MCQ_752","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_752","question":"Why do established technology and pharmaceutical businesses require significant finance for 'research and development (R&D)'?","options":{"A":"To pay short-term trade payables within seven days","B":"To fund the high upfront costs of inventing, testing, and patenting new products long before any sales revenue is generated","C":"To distribute weekly cash dividends to commercial banks","D":"To avoid recording depreciation on their factory equipment"},"correctOption":"B","correctAnswer":"To fund the high upfront costs of inventing, testing, and patenting new products long before any sales revenue is generated","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because R&D involves substantial long-term expenditure with uncertain outcomes and a long delay before commercial revenue begins.","distractor_reasons":{"A":"Incorrect because paying suppliers is routine working capital management, not R&D.","B":"Option B is correct because R&D involves substantial long-term expenditure with uncertain outcomes and a long delay before commercial revenue begins.","C":"Incorrect because banks receive loan interest, not dividends, and R&D funds innovation.","D":"Incorrect because R&D does not exempt a business from depreciating its equipment."}}},{"id":"P1_U5_MCQ_753","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_753","question":"Why is 'working capital' often described by business analysts as the 'lifeblood' of a business?","options":{"A":"Because working capital is used solely to purchase freehold land","B":"Because working capital is paid out entirely to shareholders every month","C":"Because without sufficient short-term liquid funds to pay wages, suppliers, and daily bills, even a profitable business will halt operations and fail","D":"Because working capital eliminates all corporation tax obligations"},"correctOption":"C","correctAnswer":"Because without sufficient short-term liquid funds to pay wages, suppliers, and daily bills, even a profitable business will halt operations and fail","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because working capital keeps the continuous daily cycle of buying stock, paying workers, and fulfilling orders moving smoothly.","distractor_reasons":{"A":"Incorrect because purchasing freehold land is long-term capital expenditure.","B":"Incorrect because working capital must stay circulating inside the business to fund operations.","C":"Option C is correct because working capital keeps the continuous daily cycle of buying stock, paying workers, and fulfilling orders moving smoothly.","D":"Incorrect because profitable businesses still pay corporation tax."}}},{"id":"P1_U5_MCQ_754","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_754","question":"Why is purchasing a long-term 'patent' or 'commercial franchise licence' classified as 'capital expenditure'?","options":{"A":"Because it is consumed completely within a single trading week","B":"Because it is recorded as a current liability on the statement of financial position","C":"Because it is paid out of a short-term bank overdraft","D":"Because it acquires an intangible non-current asset that will generate benefits for the business over more than one year"},"correctOption":"D","correctAnswer":"Because it acquires an intangible non-current asset that will generate benefits for the business over more than one year","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because capital expenditure includes spending on both tangible and intangible long-term assets lasting beyond 12 months.","distractor_reasons":{"A":"Incorrect because items consumed within one year are revenue expenditure.","B":"Incorrect because acquired patents and licences are non-current assets, not liabilities.","C":"Incorrect because classification depends on asset lifespan, not the bank account used.","D":"Option D is correct because capital expenditure includes spending on both tangible and intangible long-term assets lasting beyond 12 months."}}},{"id":"P1_U5_MCQ_755","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_755","question":"Why are 'staff training costs' and 'routine vehicle servicing' classified as 'revenue expenditure' rather than 'capital expenditure'?","options":{"A":"Because they are ongoing operational expenses incurred within the current accounting year rather than purchases of long-term non-current assets","B":"Because they are financed exclusively by issuing ordinary shares","C":"Because they appear as non-current assets on the statement of financial position","D":"Because they never involve any cash outflow"},"correctOption":"A","correctAnswer":"Because they are ongoing operational expenses incurred within the current accounting year rather than purchases of long-term non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because day-to-day running and maintenance costs are expensed on the statement of profit or loss in the period incurred.","distractor_reasons":{"A":"Option A is correct because day-to-day running and maintenance costs are expensed on the statement of profit or loss in the period incurred.","B":"Incorrect because routine operational costs are normally funded out of ongoing sales revenue.","C":"Incorrect because revenue expenditure is recorded as an expense on the income statement, not as a balance sheet asset.","D":"Incorrect because training fees and servicing bills require cash payments."}}},{"id":"P1_U5_MCQ_756","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_756","question":"Why is 'retained profit' considered the single most important long-term source of finance for established, profitable companies?","options":{"A":"Because it is guaranteed by the government against all trading losses","B":"Because it is permanent internal finance that requires no interest payments, no debt repayments, no collateral, and causes no dilution of ownership control","C":"Because it is always equal to the physical cash balance in the bank","D":"Because it can be used by brand-new start-ups on their very first day"},"correctOption":"B","correctAnswer":"Because it is permanent internal finance that requires no interest payments, no debt repayments, no collateral, and causes no dilution of ownership control","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retained profit avoids the financial risk of debt interest and the control dilution of issuing new shares.","distractor_reasons":{"A":"Incorrect because governments do not insure private company profits.","B":"Option B is correct because retained profit avoids the financial risk of debt interest and the control dilution of issuing new shares.","C":"Incorrect because retained profit is an accounting equity figure, not necessarily equal to liquid bank cash.","D":"Incorrect because new start-ups have no prior trading history to accumulate retained profit."}}},{"id":"P1_U5_MCQ_757","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_757","question":"What is a key advantage of raising internal finance through the 'sale of surplus non-current assets' compared with taking out a bank loan?","options":{"A":"It increases the business's annual tax-deductible interest expenses","B":"It allows the business to keep using the sold machinery free of charge forever","C":"It makes better use of idle capital tied up in unneeded assets without incurring interest charges or increasing debt liabilities","D":"It immediately increases the business's gross profit margin"},"correctOption":"C","correctAnswer":"It makes better use of idle capital tied up in unneeded assets without incurring interest charges or increasing debt liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because disposing of redundant equipment or unused land unlocks cash with zero borrowing cost or repayment obligation.","distractor_reasons":{"A":"Incorrect because selling an asset creates no interest expenses.","B":"Incorrect because once an asset is sold outright, the buyer owns and takes possession of it.","C":"Option C is correct because disposing of redundant equipment or unused land unlocks cash with zero borrowing cost or repayment obligation.","D":"Incorrect because selling a non-current asset is not trading revenue and does not alter gross profit margin."}}},{"id":"P1_U5_MCQ_758","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_758","question":"How does 'tightening credit control to collect trade receivables faster' serve as an internal source of working capital?","options":{"A":"It borrows money from a commercial bank at a fixed interest rate","B":"It issues new shares to credit customers","C":"It delays paying employee wages by three months","D":"It releases cash already owed to the business by customers sooner, reducing the need for external short-term borrowing"},"correctOption":"D","correctAnswer":"It releases cash already owed to the business by customers sooner, reducing the need for external short-term borrowing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because converting unpaid invoices into cash faster unlocks internal working capital without paying bank interest.","distractor_reasons":{"A":"Incorrect because collecting receivables does not involve bank borrowing.","B":"Incorrect because collecting customer debts is not an equity share issue.","C":"Incorrect because employee wages must be paid on contractual pay dates.","D":"Option D is correct because converting unpaid invoices into cash faster unlocks internal working capital without paying bank interest."}}},{"id":"P1_U5_MCQ_759","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_759","question":"When a sole trader injects personal savings into their business, how is this finance classified?","options":{"A":"As internal owner's capital (equity) that incurs no interest charges and has no fixed repayment date","B":"As a short-term current liability repayable within 30 days","C":"As an external non-current liability carrying compound interest","D":"As sales revenue on the statement of profit or loss"},"correctOption":"A","correctAnswer":"As internal owner's capital (equity) that incurs no interest charges and has no fixed repayment date","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the owner and unincorporated business are legally the same entity, so personal savings represent internal equity capital.","distractor_reasons":{"A":"Option A is correct because the owner and unincorporated business are legally the same entity, so personal savings represent internal equity capital.","B":"Incorrect because owner's capital is equity, not a short-term external debt.","C":"Incorrect because owner's savings are internal equity, not an external loan.","D":"Incorrect because capital injections are equity funding, not revenue from selling goods."}}},{"id":"P1_U5_MCQ_760","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_760","question":"What is a 'rights issue' of shares by an existing limited company?","options":{"A":"Selling debentures to commercial banks at a fixed interest rate","B":"Offering existing shareholders the first option to buy newly issued shares in proportion to their current holdings, allowing the company to raise equity without necessarily diluting existing owners' voting percentages","C":"Forcing customers to buy company shares before purchasing products","D":"Returning all share capital to shareholders in cash"},"correctOption":"B","correctAnswer":"Offering existing shareholders the first option to buy newly issued shares in proportion to their current holdings, allowing the company to raise equity without necessarily diluting existing owners' voting percentages","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a rights issue raises new permanent share capital while giving existing shareholders the opportunity to preserve their proportional ownership.","distractor_reasons":{"A":"Incorrect because debentures are long-term debt instruments, not equity shares.","B":"Option B is correct because a rights issue raises new permanent share capital while giving existing shareholders the opportunity to preserve their proportional ownership.","C":"Incorrect because customers are not forced to buy shares.","D":"Incorrect because a rights issue brings new cash into the company rather than returning capital."}}},{"id":"P1_U5_MCQ_761","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_761","question":"What is a major financial drawback of raising capital by floating a company on a public stock exchange (an Initial Public Offering)?","options":{"A":"The funds raised must be repaid to stock market investors within 12 months","B":"The company is legally banned from earning retained profit afterward","C":"It involves very high legal, underwriting, and administrative fees, and exposes the company to takeover risks and strict public disclosure rules","D":"The company must pay fixed monthly interest to every shareholder"},"correctOption":"C","correctAnswer":"It involves very high legal, underwriting, and administrative fees, and exposes the company to takeover risks and strict public disclosure rules","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because going public is expensive, increases regulatory transparency, and leaves shares freely tradable on the open market.","distractor_reasons":{"A":"Incorrect because ordinary share capital is permanent and never repaid.","B":"Incorrect because plcs routinely accumulate retained profit.","C":"Option C is correct because going public is expensive, increases regulatory transparency, and leaves shares freely tradable on the open market.","D":"Incorrect because ordinary shares pay discretionary dividends, not fixed monthly interest."}}},{"id":"P1_U5_MCQ_762","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_762","question":"What is the key difference between a 'fixed-rate bank loan' and a 'variable-rate bank loan'?","options":{"A":"A fixed-rate loan never has to be repaid, whereas a variable-rate loan is repaid weekly","B":"A fixed-rate loan is an internal source of finance, whereas a variable-rate loan is external","C":"A fixed-rate loan gives the bank voting shares, whereas a variable-rate loan does not","D":"A fixed-rate loan keeps the interest rate and monthly repayments constant throughout the loan term (making budgeting certain), whereas a variable-rate loan changes when market interest rates move"},"correctOption":"D","correctAnswer":"A fixed-rate loan keeps the interest rate and monthly repayments constant throughout the loan term (making budgeting certain), whereas a variable-rate loan changes when market interest rates move","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fixed-rate loans protect borrowers against interest rate hikes and simplify cash flow forecasting, while variable-rate loans fluctuate with central bank rates.","distractor_reasons":{"A":"Incorrect because both fixed-rate and variable-rate loans must be repaid according to contract.","B":"Incorrect because both are external bank debt.","C":"Incorrect because neither type of bank loan gives the bank equity voting rights.","D":"Option D is correct because fixed-rate loans protect borrowers against interest rate hikes and simplify cash flow forecasting, while variable-rate loans fluctuate with central bank rates."}}},{"id":"P1_U5_MCQ_763","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_763","question":"Why are commercial banks often reluctant to grant large unsecured loans to newly established start-up businesses?","options":{"A":"Because start-ups have no trading track record of profitability, high failure rates, and little or no non-current asset collateral to secure the debt","B":"Because banks are legally forbidden from lending money to sole traders or small companies","C":"Because start-ups never need working capital","D":"Because banks prefer to invest only in loss-making charities"},"correctOption":"A","correctAnswer":"Because start-ups have no trading track record of profitability, high failure rates, and little or no non-current asset collateral to secure the debt","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because banks are risk-averse lenders that assess default risk using historical accounts and asset security.","distractor_reasons":{"A":"Option A is correct because banks are risk-averse lenders that assess default risk using historical accounts and asset security.","B":"Incorrect because banks can lend to small businesses if presented with a strong business plan and collateral.","C":"Incorrect because start-ups heavily need working capital.","D":"Incorrect because commercial banks lend to viable, creditworthy enterprises."}}},{"id":"P1_U5_MCQ_764","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_764","question":"If a limited company fails and goes into liquidation, how are 'debenture holders' treated compared with 'ordinary shareholders'?","options":{"A":"Ordinary shareholders are repaid first, while debenture holders receive nothing","B":"Debenture holders are creditors and must be repaid before ordinary shareholders receive any remaining funds","C":"Both debenture holders and ordinary shareholders are personally liable for the company's unpaid supplier bills","D":"Debenture holders take over the personal houses of the ordinary shareholders"},"correctOption":"B","correctAnswer":"Debenture holders are creditors and must be repaid before ordinary shareholders receive any remaining funds","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because debt creditors (including debenture holders) hold priority legal claims over company assets ahead of equity shareholders.","distractor_reasons":{"A":"Incorrect because ordinary shareholders are residual owners paid last in a liquidation.","B":"Option B is correct because debt creditors (including debenture holders) hold priority legal claims over company assets ahead of equity shareholders.","C":"Incorrect because limited liability protects both from personal liability for corporate debts.","D":"Incorrect because separate legal personality shields shareholders' personal assets."}}},{"id":"P1_U5_MCQ_765","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_765","question":"Besides providing immediate cash from unpaid invoices, what administrative benefit can 'debt factoring' provide to a growing business?","options":{"A":"It eliminates the need to pay corporation tax on sales","B":"It guarantees that raw material prices will never rise","C":"The factoring company often takes over managing the sales ledger and chasing credit customers for payment, saving internal administrative time","D":"It converts short-term trade payables into permanent share capital"},"correctOption":"C","correctAnswer":"The factoring company often takes over managing the sales ledger and chasing credit customers for payment, saving internal administrative time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because specialist factors administer credit collection and ledger management in addition to advancing cash.","distractor_reasons":{"A":"Incorrect because factoring does not affect corporation tax rules.","B":"Incorrect because factoring deals with customer receivables, not raw material prices.","C":"Option C is correct because specialist factors administer credit collection and ledger management in addition to advancing cash.","D":"Incorrect because factoring converts trade receivables into cash, not payables into equity."}}},{"id":"P1_U5_MCQ_766","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_766","question":"Why do governments frequently offer 'grants or subsidies' to businesses willing to locate factories in areas of high unemployment?","options":{"A":"So the government can seize 100% ownership of the business after one year","B":"Because businesses in high-unemployment areas are exempt from paying staff wages","C":"To increase the interest rates paid by small businesses","D":"To incentivize job creation, regional economic regeneration, and inward investment without burdening the business with loan repayments"},"correctOption":"D","correctAnswer":"To incentivize job creation, regional economic regeneration, and inward investment without burdening the business with loan repayments","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because non-repayable grants reduce initial capital costs and encourage firms to create employment in targeted regions.","distractor_reasons":{"A":"Incorrect because grants do not transfer private ownership to the state.","B":"Incorrect because businesses still pay wages to their workers.","C":"Incorrect because grants are interest-free, non-repayable funds.","D":"Option D is correct because non-repayable grants reduce initial capital costs and encourage firms to create employment in targeted regions."}}},{"id":"P1_U5_MCQ_767","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_767","question":"Why do many 'microfinance' institutions lend to small groups of local entrepreneurs (group lending) rather than requiring physical property collateral?","options":{"A":"Because microfinance institutions are legally banned from lending to individuals","B":"Because peer support and mutual accountability within the group encourage high repayment rates among borrowers who lack traditional collateral","C":"Because group lending eliminates all interest charges","D":"Because group borrowers are required to list their businesses on a stock exchange"},"correctOption":"B","correctAnswer":"Because peer support and mutual accountability within the group encourage high repayment rates among borrowers who lack traditional collateral","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because social collateral and peer encouragement substitute for physical assets, enabling low-income entrepreneurs to access start-up credit.","distractor_reasons":{"A":"Incorrect because microfinance providers lend to both individuals and solidarity groups.","B":"Option B is correct because social collateral and peer encouragement substitute for physical assets, enabling low-income entrepreneurs to access start-up credit.","C":"Incorrect because microfinance loans still charge interest to remain financially sustainable.","D":"Incorrect because microfinance serves tiny informal or micro-enterprises."}}},{"id":"P1_U5_MCQ_768","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_768","question":"What role does an online 'crowdfunding platform' play when an entrepreneur launches a funding campaign?","options":{"A":"It lends its own bank reserves as a 25-year commercial mortgage","B":"It acts as an internet intermediary connecting the project creator with thousands of potential backers, usually charging a percentage fee on funds successfully raised","C":"It guarantees that every campaign will reach 100% of its funding goal","D":"It buys all unsold inventory from the business at full retail price"},"correctOption":"B","correctAnswer":"It acts as an internet intermediary connecting the project creator with thousands of potential backers, usually charging a percentage fee on funds successfully raised","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because crowdfunding websites host the pitch, process small online pledges, and earn a commission fee when targets are met.","distractor_reasons":{"A":"Incorrect because crowdfunding platforms connect public backers rather than issuing bank mortgages.","B":"Option B is correct because crowdfunding websites host the pitch, process small online pledges, and earn a commission fee when targets are met.","C":"Incorrect because many crowdfunding pitches fail to reach their target funding goal.","D":"Incorrect because platforms do not purchase leftover inventory."}}},{"id":"P1_U5_MCQ_769","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_769","question":"Why is a 'bank overdraft' classified as a short-term source of finance even if a business uses it periodically over several years?","options":{"A":"Because overdrafts are an internal source of finance","B":"Because overdrafts never incur any interest charges","C":"Because the overdraft facility is reviewed annually and the bank retains the legal right to demand full repayment at very short notice","D":"Because overdrafts can only be used to buy freehold buildings"},"correctOption":"C","correctAnswer":"Because the overdraft facility is reviewed annually and the bank retains the legal right to demand full repayment at very short notice","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an overdraft is repayable on demand and intended to fluctuate with short-term working capital needs rather than provide permanent capital.","distractor_reasons":{"A":"Incorrect because an overdraft is borrowed from an outside bank (external finance).","B":"Incorrect because overdrafts carry relatively high daily interest rates.","C":"Option C is correct because an overdraft is repayable on demand and intended to fluctuate with short-term working capital needs rather than provide permanent capital.","D":"Incorrect because overdrafts are meant for short-term running costs, not long-term buildings."}}},{"id":"P1_U5_MCQ_770","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_770","question":"Why is 'trade credit' frequently described as an 'interest-free' short-term source of finance for a business buyer?","options":{"A":"Because suppliers never expect the buyer to pay the invoice at all","B":"Because commercial banks pay the supplier on the buyer's behalf","C":"Because trade credit is recorded as shareholders' equity","D":"Because suppliers normally do not charge interest during the agreed credit window (e.g., 30 days), though failing to pay on time can incur late fees or loss of discounts"},"correctOption":"D","correctAnswer":"Because suppliers normally do not charge interest during the agreed credit window (e.g., 30 days), though failing to pay on time can incur late fees or loss of discounts","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because delayed payment within agreed credit terms provides temporary working capital without explicit interest charges.","distractor_reasons":{"A":"Incorrect because the invoice must still be paid in full by the due date.","B":"Incorrect because the buyer pays the supplier directly at the end of the credit period.","C":"Incorrect because unpaid supplier invoices are current liabilities (trade payables).","D":"Option D is correct because delayed payment within agreed credit terms provides temporary working capital without explicit interest charges."}}},{"id":"P1_U5_MCQ_771","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_771","question":"Why does 'leasing' often reduce unexpected repair costs for a business using delivery vehicles or photocopiers?","options":{"A":"Because maintenance, servicing, and repairs are typically included in the lease contract and handled by the leasing company","B":"Because leased vehicles and photocopiers never break down","C":"Because the business owns the equipment outright from Day 1","D":"Because the government pays all repair bills for leased assets"},"correctOption":"A","correctAnswer":"Because maintenance, servicing, and repairs are typically included in the lease contract and handled by the leasing company","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the lessor retains ownership and usually bundles routine servicing and repairs into the fixed rental fee.","distractor_reasons":{"A":"Option A is correct because the lessor retains ownership and usually bundles routine servicing and repairs into the fixed rental fee.","B":"Incorrect because leased equipment still requires regular maintenance.","C":"Incorrect because the leasing company retains legal ownership.","D":"Incorrect because leasing is a private commercial contract."}}},{"id":"P1_U5_MCQ_772","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_772","question":"What happens if a business defaults on payments partway through a 'hire purchase' agreement?","options":{"A":"The business automatically keeps the asset free of charge","B":"The finance company retains legal ownership until the final instalment is paid and can repossess the asset","C":"The remaining instalments are converted into ordinary share capital","D":"The supplier must refund all previous instalments with interest"},"correctOption":"B","correctAnswer":"The finance company retains legal ownership until the final instalment is paid and can repossess the asset","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because under hire purchase, legal title only passes upon completion of all contracted payments.","distractor_reasons":{"A":"Incorrect because legal ownership has not yet transferred to the buyer.","B":"Option B is correct because under hire purchase, legal title only passes upon completion of all contracted payments.","C":"Incorrect because hire purchase is a debt contract, not an equity arrangement.","D":"Incorrect because defaulted agreements allow repossession rather than refunds."}}},{"id":"P1_U5_MCQ_773","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_773","question":"When choosing between 'debt finance' (such as a bank loan) and 'equity finance' (such as issuing shares), what key advantage does equity finance offer during an economic recession?","options":{"A":"Equity finance never dilutes existing owners' voting control","B":"Equity finance requires zero administrative or legal setup costs","C":"Ordinary dividends do not have to be paid when profits fall or losses occur, whereas loan interest remains a rigid legal obligation regardless of profit","D":"Equity finance must be repaid to shareholders within six months"},"correctOption":"C","correctAnswer":"Ordinary dividends do not have to be paid when profits fall or losses occur, whereas loan interest remains a rigid legal obligation regardless of profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because discretionary dividends give companies breathing room during downturns, whereas fixed debt interest can trigger insolvency.","distractor_reasons":{"A":"Incorrect because issuing new shares to outside investors does dilute existing ownership.","B":"Incorrect because issuing shares involves significant legal and administrative costs.","C":"Option C is correct because discretionary dividends give companies breathing room during downturns, whereas fixed debt interest can trigger insolvency.","D":"Incorrect because share capital is permanent and has no repayment date."}}},{"id":"P1_U5_MCQ_774","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_774","question":"Why might the founder of a family-owned private limited company (Ltd) choose a 'bank loan' rather than selling new shares to external venture capitalists?","options":{"A":"Because bank loans never charge any interest","B":"Because private limited companies are legally forbidden from issuing shares","C":"Because bank loans increase the company's retained profit","D":"To retain 100% ownership and decision-making control within the family without outside shareholder interference"},"correctOption":"D","correctAnswer":"To retain 100% ownership and decision-making control within the family without outside shareholder interference","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because preserving control is a decisive factor in finance selection; loans add debt obligations but leave ownership intact.","distractor_reasons":{"A":"Incorrect because bank loans always incur interest charges.","B":"Incorrect because Ltds can issue shares privately if existing shareholders agree.","C":"Incorrect because loan interest reduces profit rather than increasing retained profit.","D":"Option D is correct because preserving control is a decisive factor in finance selection; loans add debt obligations but leave ownership intact."}}},{"id":"P1_U5_MCQ_775","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_775","question":"A small technology company raises money by selling a percentage of its ownership to investors who will share in future profits. Which source of finance is this?","options":{"A":"A bank overdraft","B":"A share issue","C":"Trade credit","D":"Hire purchase"},"correctOption":"B","correctAnswer":"A share issue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because issuing shares raises equity finance by selling ownership stakes, with investors sharing in the profits.","distractor_reasons":{"B":"Option B is correct because issuing shares raises equity finance by selling ownership stakes, with investors sharing in the profits.","A":"Incorrect because an overdraft is short-term borrowing from a bank and does not give anyone a share of ownership.","C":"Incorrect because trade credit allows a business to buy goods now and pay later; it does not involve selling ownership.","D":"Incorrect because hire purchase is a way of acquiring assets through instalments, not raising equity from investors."}}},{"id":"P1_U5_MCQ_776","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_776","question":"Why can a business NOT pay employee wages or supplier bills using 'retained profit' unless it also holds sufficient 'cash'?","options":{"A":"Because retained profit is legally locked in a government vault for ten years","B":"Because retained profit is an accounting equity reserve recorded on paper rather than spendable physical money in a bank account","C":"Because employees are legally forbidden from accepting bank transfers","D":"Because retained profit is classified as a current liability"},"correctOption":"B","correctAnswer":"Because retained profit is an accounting equity reserve recorded on paper rather than spendable physical money in a bank account","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retained profit may already be tied up in machinery, inventories, or unpaid customer receivables rather than sitting as liquid cash.","distractor_reasons":{"A":"Incorrect because retained profit is an accounting figure, not locked physical money.","B":"Option B is correct because retained profit may already be tied up in machinery, inventories, or unpaid customer receivables rather than sitting as liquid cash.","C":"Incorrect because bank transfers are standard cash payments.","D":"Incorrect because retained profit is owners' equity."}}},{"id":"P1_U5_MCQ_777","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_777","question":"Why do 'total cash inflows' in a given month rarely equal 'sales revenue' earned during that same month?","options":{"A":"Because sales revenue is never recorded in any financial document","B":"Because some sales are made on credit (so cash arrives in later months), while non-sales cash inflows (like bank loans or asset sales) may also enter the bank","C":"Because cash sales are excluded from sales revenue","D":"Because sales revenue is always paid to suppliers"},"correctOption":"B","correctAnswer":"Because some sales are made on credit (so cash arrives in later months), while non-sales cash inflows (like bank loans or asset sales) may also enter the bank","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because timing differences from trade credit and non-operating financing inflows separate monthly cash receipts from monthly revenue.","distractor_reasons":{"A":"Incorrect because sales revenue is the top line of the statement of profit or loss.","B":"Option B is correct because timing differences from trade credit and non-operating financing inflows separate monthly cash receipts from monthly revenue.","C":"Incorrect because cash sales are included in both revenue and cash inflows.","D":"Incorrect because sales revenue comes from customers."}}},{"id":"P1_U5_MCQ_778","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_778","question":"Why do 'total cash outflows' in a given month often differ significantly from 'total expenses' on the statement of profit or loss?","options":{"A":"Because employee wages are excluded from cash outflows","B":"Because rent and electricity never require cash payments","C":"Because cash outflows include capital asset purchases, loan principal repayments, and dividends (which are not income statement expenses), while excluding non-cash depreciation","D":"Because expenses on the income statement are always zero"},"correctOption":"C","correctAnswer":"Because cash outflows include capital asset purchases, loan principal repayments, and dividends (which are not income statement expenses), while excluding non-cash depreciation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash flow tracks all cash leaving the bank, whereas the income statement includes only period operating expenses (including non-cash depreciation).","distractor_reasons":{"A":"Incorrect because wages paid are a major cash outflow.","B":"Incorrect because rent and utility bills are regular cash outflows.","C":"Option C is correct because cash flow tracks all cash leaving the bank, whereas the income statement includes only period operating expenses (including non-cash depreciation).","D":"Incorrect because all businesses incur operating expenses."}}},{"id":"P1_U5_MCQ_779","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_779","question":"How are 'dividends paid to shareholders' treated on a company's cash flow forecast?","options":{"A":"They are omitted because dividends are non-cash items","B":"They are recorded as a cash inflow from investors","C":"They are added to the opening cash balance","D":"They are recorded as a cash outflow in the month the cash payment leaves the company's bank account"},"correctOption":"D","correctAnswer":"They are recorded as a cash outflow in the month the cash payment leaves the company's bank account","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because paying cash dividends reduces the company's bank balance in the month paid, even though dividends are not an operating expense on the income statement.","distractor_reasons":{"A":"Incorrect because cash dividends involve actual money leaving the bank.","B":"Incorrect because dividends are paid *out* to shareholders, not received from them.","C":"Incorrect because outflows reduce rather than increase cash.","D":"Option D is correct because paying cash dividends reduces the company's bank balance in the month paid, even though dividends are not an operating expense on the income statement."}}},{"id":"P1_U5_MCQ_780","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_780","question":"If a credit customer goes bankrupt and defaults on an invoice (a 'bad debt'), how does this affect a cash flow forecast?","options":{"A":"The expected future cash inflow from that customer must be removed from the forecast because no cash will ever be received","B":"The unpaid invoice is recorded as an extra cash inflow","C":"The unpaid invoice is recorded as a non-current asset","D":"The unpaid invoice increases the opening cash balance"},"correctOption":"A","correctAnswer":"The expected future cash inflow from that customer must be removed from the forecast because no cash will ever be received","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a bad debt means the anticipated receipt from trade receivables fails to materialize, lowering projected cash inflows.","distractor_reasons":{"A":"Option A is correct because a bad debt means the anticipated receipt from trade receivables fails to materialize, lowering projected cash inflows.","B":"Incorrect because default prevents cash from entering the bank.","C":"Incorrect because an irrecoverable debt is written off, not turned into a non-current asset.","D":"Incorrect because an uncollected debt does not increase cash."}}},{"id":"P1_U5_MCQ_781","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_781","question":"What does a 'net cash flow of zero' in a particular month indicate?","options":{"A":"The business had zero sales and zero expenses during the month","B":"Total cash inflows equaled total cash outflows during that month, leaving the closing cash balance identical to the opening cash balance","C":"The business's bank balance has fallen to zero","D":"The business has gone into liquidation"},"correctOption":"B","correctAnswer":"Total cash inflows equaled total cash outflows during that month, leaving the closing cash balance identical to the opening cash balance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Net cash flow = Total cash inflows - Total cash outflows; when inflows match outflows, the cash balance neither rises nor falls.","distractor_reasons":{"A":"Incorrect because inflows and outflows can both be large yet equal to each other.","B":"Option B is correct because Net cash flow = Total cash inflows - Total cash outflows; when inflows match outflows, the cash balance neither rises nor falls.","C":"Incorrect because if the opening balance was positive, the closing balance remains at that same positive amount.","D":"Incorrect because breaking even on monthly cash flow is stable, not liquidation."}}},{"id":"P1_U5_MCQ_782","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_782","question":"If a business begins a month with a positive opening cash balance and has a negative net cash flow that is *smaller* than its opening balance, what will its closing cash balance be?","options":{"A":"Negative (an overdraft)","B":"Zero","C":"Still positive, though lower than the opening balance","D":"Higher than the opening balance"},"correctOption":"C","correctAnswer":"Still positive, though lower than the opening balance","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the existing cash cushion absorbs the monthly cash shortfall without pushing the bank account into overdraft.","distractor_reasons":{"A":"Incorrect because the opening cash buffer exceeds the monthly deficit.","B":"Incorrect because the closing balance only hits zero if the deficit exactly equals the opening balance.","C":"Option C is correct because the existing cash cushion absorbs the monthly cash shortfall without pushing the bank account into overdraft.","D":"Incorrect because a negative net cash flow reduces the cash balance."}}},{"id":"P1_U5_MCQ_783","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_783","question":"On a 12-month cash flow forecast running from January to December, how is the 'overall net cash flow for the entire year' verified?","options":{"A":"By adding January's opening balance to December's closing balance","B":"By multiplying gross profit by 12","C":"By subtracting current liabilities from current assets","D":"By subtracting January's opening cash balance from December's closing cash balance (which also equals total annual inflows minus total annual outflows)"},"correctOption":"D","correctAnswer":"By subtracting January's opening cash balance from December's closing cash balance (which also equals total annual inflows minus total annual outflows)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the cumulative change in cash from the start of January to the end of December reflects total annual inflows minus total annual outflows.","distractor_reasons":{"A":"Incorrect because adding opening and closing balances double-counts the starting cash.","B":"Incorrect because gross profit is an income statement figure, not cash flow.","C":"Incorrect because current assets minus current liabilities is working capital.","D":"Option D is correct because the cumulative change in cash from the start of January to the end of December reflects total annual inflows minus total annual outflows."}}},{"id":"P1_U5_MCQ_784","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_784","question":"How does preparing a realistic cash flow forecast help a new start-up avoid 'under-capitalization'?","options":{"A":"It forces suppliers to provide free raw materials for the first year","B":"It reveals the total initial cash needed to fund set-up costs and cover negative monthly net cash flows until sales receipts become self-sustaining","C":"It guarantees that the start-up will earn a profit in Month 1","D":"It eliminates all fixed overhead costs"},"correctOption":"B","correctAnswer":"It reveals the total initial cash needed to fund set-up costs and cover negative monthly net cash flows until sales receipts become self-sustaining","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because under-capitalization—starting with too little cash buffer—is a leading cause of start-up failure that forecasting directly prevents.","distractor_reasons":{"A":"Incorrect because suppliers charge normal commercial prices.","B":"Option B is correct because under-capitalization—starting with too little cash buffer—is a leading cause of start-up failure that forecasting directly prevents.","C":"Incorrect because most start-ups experience losses or cash deficits in early months.","D":"Incorrect because rent, insurance, and utilities still apply."}}},{"id":"P1_U5_MCQ_785","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_785","question":"How can a cash flow forecast be used by senior managers as a tool for 'controlling departmental spending'?","options":{"A":"By banning all departments from buying any raw materials","B":"By setting monthly cash outflow limits (budgets) for each area and investigating whenever actual outflows exceed forecast outflows","C":"By converting all departmental expenses into share capital","D":"By eliminating the need for a statement of financial position"},"correctOption":"B","correctAnswer":"By setting monthly cash outflow limits (budgets) for each area and investigating whenever actual outflows exceed forecast outflows","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because forecast cash outflows serve as spending benchmarks, enabling variance control when costs threaten to overrun.","distractor_reasons":{"A":"Incorrect because production requires purchasing raw materials.","B":"Option B is correct because forecast cash outflows serve as spending benchmarks, enabling variance control when costs threaten to overrun.","C":"Incorrect because expenses cannot be converted into share capital.","D":"Incorrect because businesses still prepare annual statements of financial position."}}},{"id":"P1_U5_MCQ_786","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_786","question":"Why do 'potential investors' (such as business angels or venture capitalists) examine a start-up's cash flow forecast before investing equity capital?","options":{"A":"To check the start-up's historical corporation tax payments over the last ten years","B":"To calculate the exact depreciation rate of office stationery","C":"To see how quickly the business will burn through invested cash ('cash burn rate') and when positive net cash flows will make the venture self-sustaining","D":"To set the government's minimum wage rate"},"correctOption":"C","correctAnswer":"To see how quickly the business will burn through invested cash ('cash burn rate') and when positive net cash flows will make the venture self-sustaining","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because investors want to ensure their equity injection is large enough to reach positive cash flow without running dry midway.","distractor_reasons":{"A":"Incorrect because a new start-up has no ten-year tax history.","B":"Incorrect because stationery is an expense, not a depreciable non-current asset.","C":"Option C is correct because investors want to ensure their equity injection is large enough to reach positive cash flow without running dry midway.","D":"Incorrect because governments set minimum wage legislation."}}},{"id":"P1_U5_MCQ_787","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_787","question":"Which statement correctly explains why 'solvency (cash liquidity)' is even more urgent for short-term business survival than 'profitability'?","options":{"A":"Because profitable businesses are forbidden from holding bank accounts","B":"Because losses are never recorded on financial statements","C":"Because cash inflows always equal sales revenue","D":"Because a business can survive temporary accounting losses if it has enough cash to pay bills, whereas running out of cash causes immediate insolvency and closure even if orders are profitable"},"correctOption":"D","correctAnswer":"Because a business can survive temporary accounting losses if it has enough cash to pay bills, whereas running out of cash causes immediate insolvency and closure even if orders are profitable","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because creditors demand cash payment on due dates; without liquidity, operations stop immediately regardless of paper profits.","distractor_reasons":{"A":"Incorrect because all businesses use bank accounts.","B":"Incorrect because losses are fully reported on the statement of profit or loss.","C":"Incorrect because credit terms separate cash inflows from revenue.","D":"Option D is correct because creditors demand cash payment on due dates; without liquidity, operations stop immediately regardless of paper profits."}}},{"id":"P1_U5_MCQ_788","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_788","question":"When a sole trader withdraws cash from the business bank account for personal living expenses ('drawings'), how does this affect 'cash flow' versus 'profit'?","options":{"A":"It creates a cash outflow that reduces the business's cash balance, but it is NOT deducted as a business expense when calculating profit","B":"It increases both cash flow and gross profit","C":"It reduces operating profit on the statement of profit or loss, but has zero effect on cash flow","D":"It is recorded as a non-current asset on the statement of financial position"},"correctOption":"A","correctAnswer":"It creates a cash outflow that reduces the business's cash balance, but it is NOT deducted as a business expense when calculating profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because owner drawings take actual cash out of the business bank account while representing an owner equity withdrawal rather than a trading cost.","distractor_reasons":{"A":"Option A is correct because owner drawings take actual cash out of the business bank account while representing an owner equity withdrawal rather than a trading cost.","B":"Incorrect because drawings drain cash and do not generate gross profit.","C":"Incorrect because drawings reduce cash and equity without reducing trading profit.","D":"Incorrect because drawings reduce owner's capital rather than creating an asset."}}},{"id":"P1_U5_MCQ_789","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_789","question":"How does offering customers longer credit terms (e.g., increasing credit from 30 days to 90 days) to win more orders create a 'cash flow trap'?","options":{"A":"It reduces sales revenue on the statement of profit or loss immediately","B":"Higher sales require immediate cash outflows for extra materials and wages, while cash inflows from those new customers are delayed for three months, worsening short-term cash deficits","C":"It forces suppliers to wait 180 days for payment automatically","D":"It converts all trade receivables into non-current liabilities"},"correctOption":"B","correctAnswer":"Higher sales require immediate cash outflows for extra materials and wages, while cash inflows from those new customers are delayed for three months, worsening short-term cash deficits","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because expanding credit sales stretches the working capital cycle, draining cash upfront while delaying receipts.","distractor_reasons":{"A":"Incorrect because winning extra orders increases reported sales revenue.","B":"Option B is correct because expanding credit sales stretches the working capital cycle, draining cash upfront while delaying receipts.","C":"Incorrect because suppliers do not automatically extend their own credit terms when a business gives longer credit to buyers.","D":"Incorrect because unpaid customer invoices remain current assets (trade receivables)."}}},{"id":"P1_U5_MCQ_790","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_790","question":"What is a key drawback of offering a 'prompt-payment cash discount' to credit customers to accelerate cash inflows?","options":{"A":"It delays cash inflows into the following financial year","B":"It increases the business's non-current liabilities","C":"While cash enters the bank faster, giving a discount reduces the net revenue collected per invoice and lowers overall profit margin","D":"It forces the business to pay higher corporation tax on uncollected invoices"},"correctOption":"C","correctAnswer":"While cash enters the bank faster, giving a discount reduces the net revenue collected per invoice and lowers overall profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sacrificing a percentage of invoice value trades slightly lower profitability for improved short-term cash liquidity.","distractor_reasons":{"A":"Incorrect because prompt-payment discounts bring cash inflows *forward*.","B":"Incorrect because discounts affect cash and profit, not long-term debt.","C":"Option C is correct because sacrificing a percentage of invoice value trades slightly lower profitability for improved short-term cash liquidity.","D":"Incorrect because lower revenue reduces rather than increases taxable profit."}}},{"id":"P1_U5_MCQ_791","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_791","question":"Why can 'arranging a larger bank overdraft limit' prevent a forecast cash crisis even though it does NOT count as a trading cash inflow?","options":{"A":"Because an overdraft eliminates all wage and rent expenses","B":"Because an overdraft increases gross profit on the income statement","C":"Because an overdraft converts trade payables into share capital","D":"Because it gives the business legal permission to spend beyond a zero bank balance up to the agreed limit so essential bills can still be paid during temporary deficits"},"correctOption":"D","correctAnswer":"Because it gives the business legal permission to spend beyond a zero bank balance up to the agreed limit so essential bills can still be paid during temporary deficits","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an overdraft facility covers negative closing cash balances smoothly until future customer inflows restore a positive balance.","distractor_reasons":{"A":"Incorrect because wages and rent still have to be paid.","B":"Incorrect because overdrafts are financing facilities and do not add to gross profit.","C":"Incorrect because overdrafts are short-term debt, not equity.","D":"Option D is correct because an overdraft facility covers negative closing cash balances smoothly until future customer inflows restore a positive balance."}}},{"id":"P1_U5_MCQ_792","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_792","question":"What is a major risk of cutting 'raw material purchases' sharply in order to reduce short-term cash outflows?","options":{"A":"The business's current liabilities will convert into non-current assets","B":"Warehouse rent and insurance costs will double immediately","C":"Production may halt due to stockouts, causing missed customer orders, lost future cash inflows, and damaged customer loyalty","D":"The business will be forced to pay higher dividends"},"correctOption":"C","correctAnswer":"Production may halt due to stockouts, causing missed customer orders, lost future cash inflows, and damaged customer loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because starving operations of essential inputs protects cash briefly at the cost of halting sales and future receipts.","distractor_reasons":{"A":"Incorrect because inventory policies do not alter liability or asset classifications.","B":"Incorrect because holding smaller stock lowers storage costs rather than doubling them.","C":"Option C is correct because starving operations of essential inputs protects cash briefly at the cost of halting sales and future receipts.","D":"Incorrect because dividends are discretionary equity payouts."}}},{"id":"P1_U5_MCQ_793","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_793","question":"Why might 'cancelling or postponing planned marketing expenditure' to save cash in the short term backfire later in the year?","options":{"A":"Because marketing expenses are classified as non-current assets","B":"Because lower promotion can reduce future customer demand and sales orders, causing cash inflows to fall in subsequent months","C":"Because cancelling marketing doubles the cost of sales per unit","D":"Because banks cancel overdrafts whenever marketing budgets are cut"},"correctOption":"B","correctAnswer":"Because lower promotion can reduce future customer demand and sales orders, causing cash inflows to fall in subsequent months","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reducing customer awareness today shrinks the pipeline of future sales receipts.","distractor_reasons":{"A":"Incorrect because marketing is revenue expenditure (an overhead expense).","B":"Option B is correct because reducing customer awareness today shrinks the pipeline of future sales receipts.","C":"Incorrect because marketing is an indirect overhead and does not change direct unit cost of sales.","D":"Incorrect because banks do not automatically cancel overdrafts over marketing changes."}}},{"id":"P1_U5_MCQ_794","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_794","question":"How does 'converting short-term borrowing (such as an overdraft) into a long-term bank loan' improve a business's monthly cash flow stability?","options":{"A":"It eliminates all interest charges permanently","B":"It increases monthly sales revenue immediately","C":"It removes the risk of sudden full repayment on demand and spreads principal repayments into smaller, predictable instalments over several years","D":"It eliminates all current assets from the balance sheet"},"correctOption":"C","correctAnswer":"It removes the risk of sudden full repayment on demand and spreads principal repayments into smaller, predictable instalments over several years","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because restructuring short-term debt into long-term debt relieves immediate liquidity pressure and improves working capital.","distractor_reasons":{"A":"Incorrect because long-term loans still carry interest charges.","B":"Incorrect because debt restructuring does not directly change sales revenue.","C":"Option C is correct because restructuring short-term debt into long-term debt relieves immediate liquidity pressure and improves working capital.","D":"Incorrect because restructuring debt improves cash stability rather than eliminating current assets."}}},{"id":"P1_U5_MCQ_795","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_795","question":"Why are 'cash flow forecasts' for brand-new start-up businesses typically less accurate than forecasts prepared by long-established firms?","options":{"A":"Because start-ups are legally forbidden from recording cash outflows","B":"Because established firms never experience unexpected changes in customer demand","C":"Because start-ups do not have bank accounts","D":"Because start-ups lack historical sales and payment data from previous years, forcing entrepreneurs to rely on market research estimates"},"correctOption":"D","correctAnswer":"Because start-ups lack historical sales and payment data from previous years, forcing entrepreneurs to rely on market research estimates","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because established businesses can base projections on proven past seasonal patterns and customer payment behavior, whereas start-ups must estimate from scratch.","distractor_reasons":{"A":"Incorrect because start-ups must include all expected cash outflows.","B":"Incorrect because established firms also face market shocks, though they have historical baselines.","C":"Incorrect because start-ups operate business bank accounts.","D":"Option D is correct because established businesses can base projections on proven past seasonal patterns and customer payment behavior, whereas start-ups must estimate from scratch."}}},{"id":"P1_U5_MCQ_796","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_796","question":"How can a sudden rise in 'raw material prices' or 'market interest rates' affect a cash flow forecast prepared six months earlier?","options":{"A":"Actual cash outflows will be higher than originally forecast, reducing net cash flow and potentially turning projected positive balances into unexpected deficits","B":"Actual cash inflows from customers will automatically double","C":"The opening cash balance from six months ago will change retroactively","D":"The business will become exempt from paying suppliers"},"correctOption":"A","correctAnswer":"Actual cash outflows will be higher than originally forecast, reducing net cash flow and potentially turning projected positive balances into unexpected deficits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external cost shocks invalidate earlier assumptions, demonstrating why forecasts must be regularly revised.","distractor_reasons":{"A":"Option A is correct because external cost shocks invalidate earlier assumptions, demonstrating why forecasts must be regularly revised.","B":"Incorrect because higher input or interest costs do not double customer receipts.","C":"Incorrect because past opening balances are historical facts.","D":"Incorrect because supplier invoices remain legally payable."}}},{"id":"P1_U5_MCQ_797","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_797","question":"If a major credit customer unexpectedly delays paying a large invoice by two months, how does this affect a business's cash flow forecast?","options":{"A":"It has no effect because credit sales are never shown on a cash flow forecast","B":"It reduces actual cash inflows in the originally expected month, creating a temporary cash shortfall until the late payment finally arrives","C":"It permanently reduces the business's non-current assets","D":"It immediately increases the business's retained profit"},"correctOption":"B","correctAnswer":"It reduces actual cash inflows in the originally expected month, creating a temporary cash shortfall until the late payment finally arrives","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because timing delays in collecting trade receivables directly disrupt projected monthly cash balances.","distractor_reasons":{"A":"Incorrect because expected receipts from credit customers are a major cash inflow line.","B":"Option B is correct because timing delays in collecting trade receivables directly disrupt projected monthly cash balances.","C":"Incorrect because late customer payments affect current assets (receivables and cash), not non-current assets.","D":"Incorrect because late payments do not increase profit."}}},{"id":"P1_U5_MCQ_798","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_798","question":"What is the key difference between a 'cash flow forecast' and a 'statement of profit or loss' regarding the time period they look at?","options":{"A":"A cash flow forecast records only past transactions, whereas a statement of profit or loss predicts future profits","B":"Both documents record only transactions from ten years ago","C":"A cash flow forecast is a forward-looking estimate of future cash movements, whereas a statement of profit or loss is a historical record of revenue, costs, and profit already earned","D":"A cash flow forecast covers one single day, whereas a statement of profit or loss covers one single hour"},"correctOption":"C","correctAnswer":"A cash flow forecast is a forward-looking estimate of future cash movements, whereas a statement of profit or loss is a historical record of revenue, costs, and profit already earned","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash flow forecasts plan ahead for liquidity management, while published income statements report completed past trading periods.","distractor_reasons":{"A":"Incorrect because this reverses forward-looking forecasts and historical financial statements.","B":"Incorrect because forecasts look forward and annual accounts cover the most recent year.","C":"Option C is correct because cash flow forecasts plan ahead for liquidity management, while published income statements report completed past trading periods.","D":"Incorrect because forecasts typically span 6–12 months and income statements cover an accounting period (usually 12 months)."}}},{"id":"P1_U5_MCQ_799","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_799","question":"Why does a cash flow forecast show 'only cash movements' rather than showing the total value of assets and liabilities owned by the business?","options":{"A":"Because assets and liabilities are illegal to record in limited companies","B":"Because businesses never own any assets or owe any liabilities","C":"Because cash flow forecasts are prepared only by government tax collectors","D":"Because tracking liquidity requires isolating actual money entering and leaving the bank, whereas assets, liabilities, and equity are reported separately on the statement of financial position"},"correctOption":"D","correctAnswer":"Because tracking liquidity requires isolating actual money entering and leaving the bank, whereas assets, liabilities, and equity are reported separately on the statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because each financial document serves a distinct analytical purpose: liquidity timing (cash flow forecast), trading profitability (income statement), and net worth/solvency (statement of financial position).","distractor_reasons":{"A":"Incorrect because assets and liabilities are always recorded on the statement of financial position.","B":"Incorrect because every operating business holds assets and liabilities.","C":"Incorrect because managers and entrepreneurs prepare cash flow forecasts.","D":"Option D is correct because each financial document serves a distinct analytical purpose: liquidity timing (cash flow forecast), trading profitability (income statement), and net worth/solvency (statement of financial position)."}}},{"id":"P1_U5_MCQ_800","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_800","question":"Which summary statement best captures why 'working capital management' is central to cash flow forecasting?","options":{"A":"Because most short-term cash inflows and outflows come from converting inventories into trade receivables and collecting cash while paying trade payables and running expenses on time","B":"Because working capital consists entirely of freehold land and 25-year mortgages","C":"Because working capital guarantees that a business will never have any overhead costs","D":"Because working capital is calculated by subtracting gross profit from sales revenue"},"correctOption":"A","correctAnswer":"Because most short-term cash inflows and outflows come from converting inventories into trade receivables and collecting cash while paying trade payables and running expenses on time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managing inventory levels, customer credit periods, and supplier credit periods directly controls the timing of operating cash inflows and outflows.","distractor_reasons":{"A":"Option A is correct because managing inventory levels, customer credit periods, and supplier credit periods directly controls the timing of operating cash inflows and outflows.","B":"Incorrect because land and mortgages are non-current items.","C":"Incorrect because working capital funds rather than eliminates overhead costs.","D":"Incorrect because sales revenue minus gross profit equals cost of sales."}}},{"id":"P1_U5_MCQ_801","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_801","question":"Why is profit described as a 'reward for enterprise and risk-taking' in a private sector economy?","options":{"A":"Because entrepreneurs invest their own capital, time, and effort without any guarantee of success, so the prospect of earning profit compensates them for bearing business risk","B":"Because governments pay a guaranteed salary to every entrepreneur who starts a shop","C":"Because entrepreneurs never risk losing their invested money if a business fails","D":"Because profit is distributed equally to all customers at the end of the year"},"correctOption":"A","correctAnswer":"Because entrepreneurs invest their own capital, time, and effort without any guarantee of success, so the prospect of earning profit compensates them for bearing business risk","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unlike salaried employees or secured lenders, owners take residual financial risk and require profit returns as an incentive.","distractor_reasons":{"A":"Option A is correct because unlike salaried employees or secured lenders, owners take residual financial risk and require profit returns as an incentive.","B":"Incorrect because private entrepreneurs earn profit only if revenue exceeds costs.","C":"Incorrect because owners lose their invested capital if the business fails.","D":"Incorrect because profits belong to the business owners/shareholders, not customers."}}},{"id":"P1_U5_MCQ_802","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_802","question":"How does earning consistent profit improve a company's ability to raise 'external finance' from banks and shareholders?","options":{"A":"It exempts the company from providing financial statements to lenders","B":"Strong profitability demonstrates financial viability, reassuring banks that loan interest can be paid and attracting equity investors seeking dividends and share growth","C":"It forces banks to lend money at a 0% interest rate","D":"It eliminates the need for working capital"},"correctOption":"B","correctAnswer":"Strong profitability demonstrates financial viability, reassuring banks that loan interest can be paid and attracting equity investors seeking dividends and share growth","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profitable businesses represent lower credit risk to lenders and higher return potential to investors.","distractor_reasons":{"A":"Incorrect because lenders still require financial statements.","B":"Option B is correct because profitable businesses represent lower credit risk to lenders and higher return potential to investors.","C":"Incorrect because banks always charge interest based on risk and market rates.","D":"Incorrect because expanding profitable firms still need working capital."}}},{"id":"P1_U5_MCQ_803","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_803","question":"Why do 'social enterprises' aim to generate a financial profit even though their primary goal is achieving social or environmental objectives?","options":{"A":"So they can distribute maximum cash dividends to stock-market speculators","B":"Because social enterprises are fined by tax authorities if they help the community","C":"So they can remain financially self-sustaining without depending solely on charity donations, reinvesting profits back into their social mission","D":"Because social enterprises are forbidden from charging customers for goods or services"},"correctOption":"C","correctAnswer":"So they can remain financially self-sustaining without depending solely on charity donations, reinvesting profits back into their social mission","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social enterprises use commercial trading surpluses to fund ongoing community or environmental programs independently.","distractor_reasons":{"A":"Incorrect because social enterprises reinvest surpluses into their mission rather than maximizing private shareholder payouts.","B":"Incorrect because social enterprises are encouraged rather than fined.","C":"Option C is correct because social enterprises use commercial trading surpluses to fund ongoing community or environmental programs independently.","D":"Incorrect because social enterprises sell goods or services commercially to earn revenue."}}},{"id":"P1_U5_MCQ_804","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_804","question":"What does a 'net loss' (negative profit) on a statement of profit or loss signify?","options":{"A":"The business has zero cash in its bank account","B":"The business's current liabilities exceed its non-current assets","C":"The business has paid too much corporation tax","D":"Total costs (cost of sales plus overhead expenses) exceeded total sales revenue during the trading period"},"correctOption":"D","correctAnswer":"Total costs (cost of sales plus overhead expenses) exceeded total sales revenue during the trading period","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when total costs are greater than total revenue over an accounting period, the business makes a trading loss.","distractor_reasons":{"A":"Incorrect because a loss-making business can still hold cash from loans, share issues, or prior balances.","B":"Incorrect because asset and liability positions appear on the statement of financial position.","C":"Incorrect because corporation tax is only charged when positive profit is earned.","D":"Option D is correct because when total costs are greater than total revenue over an accounting period, the business makes a trading loss."}}},{"id":"P1_U5_MCQ_805","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_805","question":"How are 'sales returns' (faulty or unwanted goods returned by customers for a refund) treated when calculating 'net revenue' on a statement of profit or loss?","options":{"A":"They are classified as a non-current asset","B":"They are added to sales revenue at the top of the statement","C":"They are subtracted from total gross sales revenue to show net sales revenue actually retained by the business","D":"They are deducted after retained profit has been calculated"},"correctOption":"C","correctAnswer":"They are subtracted from total gross sales revenue to show net sales revenue actually retained by the business","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because returned goods reverse a sale, so deducting sales returns gives true net revenue.","distractor_reasons":{"A":"Incorrect because returned sales reduce revenue (and go back to inventory if resalable), not non-current assets.","B":"Incorrect because returns reduce rather than increase revenue.","C":"Option C is correct because returned goods reverse a sale, so deducting sales returns gives true net revenue.","D":"Incorrect because net revenue is determined at the very top of the income statement."}}},{"id":"P1_U5_MCQ_806","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_806","question":"In the cost of sales formula ('Opening inventory + Purchases - Closing inventory'), what does 'Purchases' refer to?","options":{"A":"Buying new delivery trucks, office computers, and freehold factory buildings","B":"Buying goods for resale (in retail) or raw materials for production (in manufacturing) during the accounting year","C":"Paying monthly electricity bills and administrative salaries","D":"Buying back shares from ordinary shareholders"},"correctOption":"B","correctAnswer":"Buying goods for resale (in retail) or raw materials for production (in manufacturing) during the accounting year","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 'Purchases' in cost of sales strictly refers to inventory acquired for resale or direct manufacturing.","distractor_reasons":{"A":"Incorrect because trucks, computers, and buildings are non-current assets (capital expenditure).","B":"Option B is correct because 'Purchases' in cost of sales strictly refers to inventory acquired for resale or direct manufacturing.","C":"Incorrect because utilities and admin salaries are indirect overhead expenses.","D":"Incorrect because share buy-backs are equity financing transactions."}}},{"id":"P1_U5_MCQ_807","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_807","question":"If a business's 'closing inventory' at year-end is higher than its 'opening inventory' at the start of the year, what does this indicate about inventory movement during the year?","options":{"A":"The business sold more units than it bought/produced during the year","B":"The business had zero purchases during the year","C":"The business bought or produced more goods during the year than it sold, so unsold stock levels increased","D":"The business made a net loss for the year"},"correctOption":"C","correctAnswer":"The business bought or produced more goods during the year than it sold, so unsold stock levels increased","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when additions to inventory (purchases/production) exceed units sold, ending inventory rises above opening inventory.","distractor_reasons":{"A":"Incorrect because selling more than bought/produced reduces closing inventory below opening inventory.","B":"Incorrect because with zero purchases and any sales, closing inventory would be lower than opening inventory.","C":"Option C is correct because when additions to inventory (purchases/production) exceed units sold, ending inventory rises above opening inventory.","D":"Incorrect because inventory changes do not determine whether the business made a profit or loss."}}},{"id":"P1_U5_MCQ_808","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_808","question":"Why is 'gross profit' calculated as a separate subtotal before deducting overhead expenses on a statement of profit or loss?","options":{"A":"Because gross profit is the exact amount of cash in the bank","B":"Because gross profit is used to calculate corporation tax directly","C":"Because overhead expenses are legally optional to report","D":"Because it allows managers to evaluate the core profitability of buying/making and selling products separately from indirect administrative and marketing overheads"},"correctOption":"D","correctAnswer":"Because it allows managers to evaluate the core profitability of buying/making and selling products separately from indirect administrative and marketing overheads","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because isolating gross profit helps managers see whether pricing and direct production costs are healthy before looking at fixed overheads.","distractor_reasons":{"A":"Incorrect because gross profit is a trading calculation, not bank cash.","B":"Incorrect because corporation tax is calculated on profit before tax (after overheads and interest).","C":"Incorrect because all overhead expenses must be deducted to find true profit.","D":"Option D is correct because isolating gross profit helps managers see whether pricing and direct production costs are healthy before looking at fixed overheads."}}},{"id":"P1_U5_MCQ_809","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_809","question":"Why do pure 'service businesses' (such as a law firm or consulting agency) often have little or no physical inventory in their 'cost of sales'?","options":{"A":"Because services are intangible activities delivered directly to clients rather than physical goods held in a warehouse, so most of their costs are staff salaries and office overheads","B":"Because service businesses are legally forbidden from preparing statements of profit or loss","C":"Because service businesses never earn any revenue","D":"Because service businesses record all salaries as non-current assets"},"correctOption":"A","correctAnswer":"Because services are intangible activities delivered directly to clients rather than physical goods held in a warehouse, so most of their costs are staff salaries and office overheads","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because service providers do not buy or manufacture physical stock for resale, resulting in minimal inventory-based cost of sales.","distractor_reasons":{"A":"Option A is correct because service providers do not buy or manufacture physical stock for resale, resulting in minimal inventory-based cost of sales.","B":"Incorrect because service companies prepare full financial statements.","C":"Incorrect because service businesses earn fee revenue from clients.","D":"Incorrect because staff salaries are expenses, not non-current assets."}}},{"id":"P1_U5_MCQ_810","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_810","question":"Which cost is classified as an 'overhead expense' (indirect cost) rather than part of 'cost of sales'?","options":{"A":"Wholesale purchase cost of goods bought by a supermarket for resale","B":"Annual fire and theft insurance premiums for the company's head office","C":"Direct steel and rubber components used to assemble bicycles in a factory","D":"Piece-rate wages paid to factory workers directly assembling products"},"correctOption":"B","correctAnswer":"Annual fire and theft insurance premiums for the company's head office","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because head-office insurance is a fixed indirect running cost that does not vary directly with units produced or sold.","distractor_reasons":{"A":"Incorrect because goods bought for resale form a retailer's cost of sales.","B":"Option B is correct because head-office insurance is a fixed indirect running cost that does not vary directly with units produced or sold.","C":"Incorrect because direct raw materials form part of cost of sales.","D":"Incorrect because direct production labor forms part of cost of sales."}}},{"id":"P1_U5_MCQ_811","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_811","question":"How is the annual 'depreciation charge' on factory or office equipment recorded on a statement of profit or loss?","options":{"A":"It is added to sales revenue at the top of the statement","B":"It is omitted completely because it does not involve cash","C":"It is deducted as an expense on the statement of profit or loss, reducing reported profit for the year","D":"It is deducted from dividends after profit after tax"},"correctOption":"C","correctAnswer":"It is deducted as an expense on the statement of profit or loss, reducing reported profit for the year","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because even though depreciation is non-cash, it represents the gradual consumption of a non-current asset's value during the year and must be expensed.","distractor_reasons":{"A":"Incorrect because depreciation is a cost, not revenue.","B":"Incorrect because omitting depreciation would overstate annual profit.","C":"Option C is correct because even though depreciation is non-cash, it represents the gradual consumption of a non-current asset's value during the year and must be expensed.","D":"Incorrect because depreciation is an operating expense deducted before profit before tax."}}},{"id":"P1_U5_MCQ_812","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_812","question":"Why is 'operating profit (profit before interest and tax)' often used when calculating Return on Capital Employed (ROCE)?","options":{"A":"Because operating profit excludes all sales revenue","B":"Because operating profit is always identical to gross profit","C":"Because operating profit includes share capital raised during the year","D":"Because operating profit measures the core trading profit generated by the business's assets before financing choices (interest) and government tax rates are applied"},"correctOption":"D","correctAnswer":"Because operating profit measures the core trading profit generated by the business's assets before financing choices (interest) and government tax rates are applied","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because using operating profit enables fair comparison of operational efficiency between companies with different debt-to-equity structures or tax jurisdictions.","distractor_reasons":{"A":"Incorrect because operating profit starts from sales revenue.","B":"Incorrect because operating profit deducts overhead expenses from gross profit.","C":"Incorrect because share capital is equity on the balance sheet, not profit.","D":"Option D is correct because using operating profit enables fair comparison of operational efficiency between companies with different debt-to-equity structures or tax jurisdictions."}}},{"id":"P1_U5_MCQ_813","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_813","question":"If a company earns 'interest received' from holding cash in an interest-bearing bank deposit account, how does this affect its statement of profit or loss?","options":{"A":"It is deducted from gross profit","B":"It is added to operating profit as finance income when calculating profit before tax","C":"It is classified as a current liability","D":"It increases cost of sales"},"correctOption":"B","correctAnswer":"It is added to operating profit as finance income when calculating profit before tax","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because interest earned on bank deposits is non-trading finance income that adds to profit before tax.","distractor_reasons":{"A":"Incorrect because interest received is income, not an expense.","B":"Option B is correct because interest earned on bank deposits is non-trading finance income that adds to profit before tax.","C":"Incorrect because interest earned is income, not a debt owed.","D":"Incorrect because interest is unrelated to direct production or purchase costs."}}},{"id":"P1_U5_MCQ_814","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_814","question":"Why are 'dividends' placed *below* 'profit after tax' at the bottom of a limited company's statement of profit or loss rather than included among overhead expenses?","options":{"A":"Because dividends are paid to suppliers for raw materials","B":"Because dividends are a tax-deductible cost of production","C":"Because dividends are a distribution (appropriation) of earned profit to the company's owners, not a cost incurred in generating that profit","D":"Because dividends are owed to commercial banks"},"correctOption":"C","correctAnswer":"Because dividends are a distribution (appropriation) of earned profit to the company's owners, not a cost incurred in generating that profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because expenses are costs required to earn revenue, whereas dividends are how owners share the resulting after-tax profit.","distractor_reasons":{"A":"Incorrect because suppliers are paid for goods/services, whereas shareholders receive dividends.","B":"Incorrect because dividends are paid out of after-tax profit and are not tax-deductible expenses.","C":"Option C is correct because expenses are costs required to earn revenue, whereas dividends are how owners share the resulting after-tax profit.","D":"Incorrect because banks receive contractual loan interest, not dividends."}}},{"id":"P1_U5_MCQ_815","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_815","question":"Can a limited company legally pay a dividend to shareholders in a year when it makes a small loss, provided it has large accumulated 'retained profit' reserves from previous years?","options":{"A":"No, because paying any dividend is always illegal unless current-year profit exceeds $10 million","B":"Yes, because dividends can legally be paid out of accumulated past retained profits if cash allows, though doing so reduces total equity reserves","C":"No, because past retained profits disappear at the end of every year","D":"Yes, because dividends are paid directly by the government during loss-making years"},"correctOption":"B","correctAnswer":"Yes, because dividends can legally be paid out of accumulated past retained profits if cash allows, though doing so reduces total equity reserves","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because accumulated retained profit reserves represent undistributed historical profits available for dividends, though directors must ensure sufficient cash liquidity.","distractor_reasons":{"A":"Incorrect because company law permits dividends from accumulated distributable profits.","B":"Option B is correct because accumulated retained profit reserves represent undistributed historical profits available for dividends, though directors must ensure sufficient cash liquidity.","C":"Incorrect because retained profits accumulate over time on the statement of financial position.","D":"Incorrect because governments do not pay private corporate dividends."}}},{"id":"P1_U5_MCQ_816","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_816","question":"If a company's 'profit after tax' is completely paid out as 'dividends' to shareholders, what is the 'retained profit' for that year?","options":{"A":"Zero, meaning no internal profit from that year is kept inside the business for reinvestment","B":"Equal to gross profit","C":"Equal to total sales revenue","D":"Negative, creating a new bank overdraft"},"correctOption":"A","correctAnswer":"Zero, meaning no internal profit from that year is kept inside the business for reinvestment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Retained profit = Profit after tax - Dividends; a 100% dividend payout leaves zero retained profit for the year.","distractor_reasons":{"A":"Option A is correct because Retained profit = Profit after tax - Dividends; a 100% dividend payout leaves zero retained profit for the year.","B":"Incorrect because gross profit is before overheads, tax, and dividends.","C":"Incorrect because sales revenue is before all costs.","D":"Incorrect because distributing 100% of profit after tax leaves retained profit at zero (paying *more* than available reserves would be negative)."}}},{"id":"P1_U5_MCQ_817","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_817","question":"When a business increases its sales volume while fixed overhead expenses (such as factory rent) stay constant, why does 'operating profit' often grow at a faster percentage rate than 'gross profit'?","options":{"A":"Because fixed overhead expenses decrease whenever sales increase","B":"Because higher sales volume automatically eliminates corporation tax","C":"Because higher sales volume reduces raw material costs to zero","D":"Because fixed overhead expenses are spread over more units sold, allowing a greater proportion of additional gross profit to flow straight into operating profit"},"correctOption":"D","correctAnswer":"Because fixed overhead expenses are spread over more units sold, allowing a greater proportion of additional gross profit to flow straight into operating profit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because once fixed overheads are covered, every additional unit's gross profit contributes directly to operating profit.","distractor_reasons":{"A":"Incorrect because fixed overheads stay constant rather than falling to zero.","B":"Incorrect because higher profit actually increases the dollar amount of corporation tax paid.","C":"Incorrect because direct variable material costs still rise with output.","D":"Option D is correct because once fixed overheads are covered, every additional unit's gross profit contributes directly to operating profit."}}},{"id":"P1_U5_MCQ_818","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_818","question":"If a manufacturer replaces manual assembly workers with automated robotic machinery, how does this typically change the structure of its statement of profit or loss?","options":{"A":"Direct labor costs inside cost of sales fall (increasing gross profit), while annual depreciation expenses inside overheads increase","B":"Both direct labor costs and depreciation expenses drop to zero","C":"Sales revenue is replaced by share capital","D":"Gross profit falls while direct labor costs double"},"correctOption":"A","correctAnswer":"Direct labor costs inside cost of sales fall (increasing gross profit), while annual depreciation expenses inside overheads increase","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automation substitutes capital equipment (depreciated in overheads) for direct production wages (in cost of sales).","distractor_reasons":{"A":"Option A is correct because automation substitutes capital equipment (depreciated in overheads) for direct production wages (in cost of sales).","B":"Incorrect because new machinery incurs substantial annual depreciation charges.","C":"Incorrect because automation changes cost structure, not how sales revenue is recorded.","D":"Incorrect because reducing direct assembly wages lowers cost of sales and raises gross profit."}}},{"id":"P1_U5_MCQ_819","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_819","question":"Why do 'potential buyers of a business' examine its statements of profit or loss from the past three to five years rather than looking only at the most recent year?","options":{"A":"Because past statements of profit or loss show the exact market value of freehold land","B":"To verify whether profits are consistent and growing steadily, or whether the most recent year was a temporary one-off spike","C":"Because tax authorities prohibit buying a business with less than five years of losses","D":"To calculate the business's acid-test ratio"},"correctOption":"B","correctAnswer":"To verify whether profits are consistent and growing steadily, or whether the most recent year was a temporary one-off spike","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because multi-year profit trends reveal sustainable earning power and revenue stability.","distractor_reasons":{"A":"Incorrect because asset values appear on the statement of financial position.","B":"Option B is correct because multi-year profit trends reveal sustainable earning power and revenue stability.","C":"Incorrect because there is no such legal prohibition.","D":"Incorrect because the acid-test ratio uses current assets and current liabilities from the statement of financial position."}}},{"id":"P1_U5_MCQ_820","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_820","question":"Why can two companies with identical sales revenue and identical cash flows report slightly different 'profits for the year' on their statements of profit or loss?","options":{"A":"Because one company is legally allowed to omit all overhead expenses","B":"Because sales revenue is never included in profit calculations","C":"Because accounting judgments and estimates—such as the useful lifespan chosen for depreciating non-current assets or how closing inventory is valued—affect reported expenses and profit","D":"Because limited companies do not deduct cost of sales"},"correctOption":"C","correctAnswer":"Because accounting judgments and estimates—such as the useful lifespan chosen for depreciating non-current assets or how closing inventory is valued—affect reported expenses and profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because accrual accounting involves legitimate estimates (such as depreciation rates) that influence non-cash expenses without changing bank cash.","distractor_reasons":{"A":"Incorrect because all companies must include overhead expenses.","B":"Incorrect because sales revenue is always the starting point of the income statement.","C":"Option C is correct because accrual accounting involves legitimate estimates (such as depreciation rates) that influence non-cash expenses without changing bank cash.","D":"Incorrect because all trading companies deduct cost of sales."}}},{"id":"P1_U5_MCQ_821","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_821","question":"What happens to a company's 'retained profit' if it suffers a 'net loss' for the year?","options":{"A":"The net loss increases accumulated retained profit reserves","B":"The net loss is ignored and has no effect on shareholders' equity","C":"The net loss is transferred into non-current assets","D":"The net loss reduces accumulated retained profit reserves (and therefore reduces total shareholders' equity) on the statement of financial position"},"correctOption":"D","correctAnswer":"The net loss reduces accumulated retained profit reserves (and therefore reduces total shareholders' equity) on the statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shareholders bear business losses, eroding accumulated equity reserves on the balance sheet.","distractor_reasons":{"A":"Incorrect because profits increase equity reserves, whereas losses reduce them.","B":"Incorrect because losses directly reduce net assets and shareholders' equity.","C":"Incorrect because losses are not assets.","D":"Option D is correct because shareholders bear business losses, eroding accumulated equity reserves on the balance sheet."}}},{"id":"P1_U5_MCQ_822","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_822","question":"Which stakeholder group uses a company's statement of profit or loss primarily to check whether the company is generating sufficient profit to pay regular dividends and justify holding its shares?","options":{"A":"Shareholders (owners)","B":"Raw-material suppliers","C":"Local environmental pressure groups","D":"Commercial utility providers"},"correctOption":"A","correctAnswer":"Shareholders (owners)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholders receive dividends out of after-tax profits and rely on profit growth for share price appreciation.","distractor_reasons":{"A":"Option A is correct because shareholders receive dividends out of after-tax profits and rely on profit growth for share price appreciation.","B":"Incorrect because suppliers care primarily about short-term bill payment and repeat orders rather than shareholder dividends.","C":"Incorrect because pressure groups focus on environmental and social impacts.","D":"Incorrect because utility providers care about timely bill settlement."}}},{"id":"P1_U5_MCQ_823","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_823","question":"Why do 'business managers' compare actual figures on the statement of profit or loss against budgeted targets at year-end?","options":{"A":"To calculate the exact market value of freehold land","B":"To evaluate departmental performance, identify areas where revenue fell short or expenses overshot budgets, and set realistic targets for next year","C":"To avoid publishing annual accounts to shareholders","D":"To eliminate all current liabilities"},"correctOption":"B","correctAnswer":"To evaluate departmental performance, identify areas where revenue fell short or expenses overshot budgets, and set realistic targets for next year","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because comparing actual income statement outcomes against budgets supports accountability and strategic planning.","distractor_reasons":{"A":"Incorrect because property values are not shown on the income statement.","B":"Option B is correct because comparing actual income statement outcomes against budgets supports accountability and strategic planning.","C":"Incorrect because plcs must publish annual accounts by law.","D":"Incorrect because current liabilities are balance sheet obligations."}}},{"id":"P1_U5_MCQ_824","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_824","question":"If a business's sales revenue grows rapidly over a year, why might its 'profit for the year' still fall?","options":{"A":"Because higher sales revenue is always subtracted from gross profit","B":"Because sales revenue is never included on the statement of profit or loss","C":"Because cost of sales or overhead expenses (such as heavy promotional discounting, overtime wages, or higher rent) rose even faster than revenue","D":"Because profitable sales automatically increase corporation tax above 100%"},"correctOption":"C","correctAnswer":"Because cost of sales or overhead expenses (such as heavy promotional discounting, overtime wages, or higher rent) rose even faster than revenue","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because revenue growth without cost discipline or margin protection can compress overall profit.","distractor_reasons":{"A":"Incorrect because revenue is the starting positive figure on the income statement.","B":"Incorrect because revenue is always the top line of the income statement.","C":"Option C is correct because revenue growth without cost discipline or margin protection can compress overall profit.","D":"Incorrect because corporation tax is a percentage of profit, never exceeding 100%."}}},{"id":"P1_U5_MCQ_825","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_825","question":"Which statement accurately summarizes the relationship between 'gross profit', 'operating profit', and 'retained profit' on a company's statement of profit or loss?","options":{"A":"Retained profit is always larger than gross profit","B":"Gross profit is calculated after deducting tax and dividends","C":"Operating profit is calculated before deducting cost of sales","D":"Gross profit is after direct cost of sales; operating profit is after also deducting indirect overheads; retained profit is after further deducting interest, tax, and dividends"},"correctOption":"D","correctAnswer":"Gross profit is after direct cost of sales; operating profit is after also deducting indirect overheads; retained profit is after further deducting interest, tax, and dividends","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because each stage down the statement of profit or loss deducts successive layers of costs, taxes, and owner distributions.","distractor_reasons":{"A":"Incorrect because retained profit is smaller than gross profit after overheads, tax, and dividends are deducted.","B":"Incorrect because gross profit is near the top before overheads, tax, and dividends.","C":"Incorrect because cost of sales is deducted first to find gross profit.","D":"Option D is correct because each stage down the statement of profit or loss deducts successive layers of costs, taxes, and owner distributions."}}},{"id":"P1_U5_MCQ_826","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_826","question":"Why does the heading of a 'statement of financial position' state 'as at [specific date]' rather than 'for the year ended [specific date]'?","options":{"A":"Because it records the exact balances of assets, liabilities, and equity at one single moment in time rather than cumulative flows over a 12-month period","B":"Because businesses only operate on one single day each year","C":"Because all assets are sold on that specific date","D":"Because liabilities only exist on the final day of the financial year"},"correctOption":"A","correctAnswer":"Because it records the exact balances of assets, liabilities, and equity at one single moment in time rather than cumulative flows over a 12-month period","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because balance sheet items are point-in-time stock positions (like cash in the bank or stock on shelves on that evening), whereas revenue and expenses are period flows.","distractor_reasons":{"A":"Option A is correct because balance sheet items are point-in-time stock positions (like cash in the bank or stock on shelves on that evening), whereas revenue and expenses are period flows.","B":"Incorrect because businesses trade throughout the year.","C":"Incorrect because ongoing businesses retain their assets across years.","D":"Incorrect because debts exist continuously until paid."}}},{"id":"P1_U5_MCQ_827","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_827","question":"Which equation represents the fundamental 'accounting equation' underlying every statement of financial position?","options":{"A":"Assets = Liabilities - Equity","B":"Assets = Liabilities + Owners' Equity","C":"Assets + Liabilities = Owners' Equity","D":"Current Assets = Non-Current Liabilities"},"correctOption":"B","correctAnswer":"Assets = Liabilities + Owners' Equity","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because every resource owned by the business (Assets) is funded either by external creditors (Liabilities) or by the owners (Equity).","distractor_reasons":{"A":"Incorrect because Liabilities and Equity are added together to equal Total Assets (or Assets - Liabilities = Equity).","B":"Option B is correct because every resource owned by the business (Assets) is funded either by external creditors (Liabilities) or by the owners (Equity).","C":"Incorrect because liabilities are obligations subtracted from assets to find equity, not added to assets.","D":"Incorrect because short-term assets and long-term debts are not equal."}}},{"id":"P1_U5_MCQ_828","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_828","question":"How does the intended *purpose* of holding an item determine whether it is classified as a 'non-current asset' or 'inventory (current asset)'?","options":{"A":"Items costing over $100 are always non-current assets regardless of use","B":"Items made of metal are non-current assets, while items made of paper are current assets","C":"An item kept and used in operations for over a year (such as a delivery van used by a bakery) is a non-current asset, whereas an identical van held for immediate resale by a car dealership is inventory","D":"All vehicles are classified as current liabilities"},"correctOption":"C","correctAnswer":"An item kept and used in operations for over a year (such as a delivery van used by a bakery) is a non-current asset, whereas an identical van held for immediate resale by a car dealership is inventory","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because accounting classification depends on how the business uses the asset: long-term operational use (non-current asset) versus held for resale in ordinary trade (inventory).","distractor_reasons":{"A":"Incorrect because expensive goods held for resale (like luxury cars in a showroom) are still inventory.","B":"Incorrect because physical material does not determine accounting classification.","C":"Option C is correct because accounting classification depends on how the business uses the asset: long-term operational use (non-current asset) versus held for resale in ordinary trade (inventory).","D":"Incorrect because owned vehicles are assets, not liabilities."}}},{"id":"P1_U5_MCQ_829","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_829","question":"What is 'goodwill' when it appears as an intangible non-current asset on a company's statement of financial position?","options":{"A":"Cash donated by the company to local charities","B":"Short-term trade credit granted by friendly suppliers","C":"Physical raw materials stored in the warehouse","D":"The extra value paid above net tangible asset value when acquiring an established business, reflecting its brand reputation, loyal customer base, and skilled staff"},"correctOption":"D","correctAnswer":"The extra value paid above net tangible asset value when acquiring an established business, reflecting its brand reputation, loyal customer base, and skilled staff","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because purchased goodwill arises during a takeover when the buyer pays more than the fair value of physical net assets for the target's reputation and customer relationships.","distractor_reasons":{"A":"Incorrect because charitable donations are expenses, not assets.","B":"Incorrect because supplier credit is trade payables (a current liability).","C":"Incorrect because physical raw materials are tangible current assets (inventories).","D":"Option D is correct because purchased goodwill arises during a takeover when the buyer pays more than the fair value of physical net assets for the target's reputation and customer relationships."}}},{"id":"P1_U5_MCQ_830","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_830","question":"How does 'accumulated depreciation' affect the presentation of non-current assets on a statement of financial position?","options":{"A":"It increases issued share capital","B":"It is added to cash at bank under current assets","C":"It is recorded under non-current liabilities as a debt owed to the government","D":"It is deducted from the original historical cost of the non-current assets to show their remaining Net Book Value"},"correctOption":"D","correctAnswer":"It is deducted from the original historical cost of the non-current assets to show their remaining Net Book Value","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because showing Cost minus Accumulated depreciation equals Net Book Value informs readers of both original investment and wear-and-tear to date.","distractor_reasons":{"A":"Incorrect because depreciation does not alter share capital.","B":"Incorrect because depreciation is non-cash and does not add to bank balances.","C":"Incorrect because depreciation is an asset valuation adjustment, not a debt owed.","D":"Option D is correct because showing Cost minus Accumulated depreciation equals Net Book Value informs readers of both original investment and wear-and-tear to date."}}},{"id":"P1_U5_MCQ_831","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_831","question":"Which list contains ONLY 'current assets'?","options":{"A":"Inventories, trade payables, and cash in hand","B":"Inventories, trade receivables, and cash at bank","C":"Trade receivables, delivery vehicles, and cash at bank","D":"Cash at bank, bank overdraft, and inventories"},"correctOption":"B","correctAnswer":"Inventories, trade receivables, and cash at bank","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inventories, trade receivables, and cash are the three standard categories of short-term current assets.","distractor_reasons":{"A":"Incorrect because trade payables are current liabilities.","B":"Option B is correct because inventories, trade receivables, and cash are the three standard categories of short-term current assets.","C":"Incorrect because delivery vehicles are non-current assets.","D":"Incorrect because a bank overdraft is a current liability."}}},{"id":"P1_U5_MCQ_832","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_832","question":"Why are 'cash in hand' (notes and coins in tills/safes) and 'cash at bank' (positive current account balances) grouped together at the bottom of current assets?","options":{"A":"Because they are the least liquid assets owned by the business","B":"Because they are owed to external suppliers","C":"Because both represent immediately spendable liquid money (the highest degree of liquidity) available to settle debts on demand","D":"Because they are non-current assets lasting more than ten years"},"correctOption":"C","correctAnswer":"Because both represent immediately spendable liquid money (the highest degree of liquidity) available to settle debts on demand","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because current assets are ordered from least liquid (inventories) to most liquid (cash in hand and at bank).","distractor_reasons":{"A":"Incorrect because inventories are the least liquid current assets; cash is the most liquid.","B":"Incorrect because positive cash balances are assets owned by the business.","C":"Option C is correct because current assets are ordered from least liquid (inventories) to most liquid (cash in hand and at bank).","D":"Incorrect because cash circulates daily as a current asset."}}},{"id":"P1_U5_MCQ_833","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_833","question":"Why do 'trade receivables' appear on the statement of financial position of a B2B manufacturer, whereas a cash-only retail coffee shop may have zero trade receivables?","options":{"A":"Because retail coffee shops are legally forbidden from holding current assets","B":"Because B2B manufacturers are exempt from collecting payments from customers","C":"Because retail coffee shops record customer payments as non-current liabilities","D":"Because B2B manufacturers routinely sell goods on trade credit (creating unpaid customer invoices), whereas a coffee shop collects immediate cash/card payment at the point of sale"},"correctOption":"D","correctAnswer":"Because B2B manufacturers routinely sell goods on trade credit (creating unpaid customer invoices), whereas a coffee shop collects immediate cash/card payment at the point of sale","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade receivables only arise when goods or services are supplied on credit before cash payment is collected.","distractor_reasons":{"A":"Incorrect because coffee shops hold cash and food/drink inventories as current assets.","B":"Incorrect because manufacturers actively collect trade receivables.","C":"Incorrect because point-of-sale payments increase cash (a current asset).","D":"Option D is correct because trade receivables only arise when goods or services are supplied on credit before cash payment is collected."}}},{"id":"P1_U5_MCQ_834","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_834","question":"Within a factory's 'inventories' on its statement of financial position, what is 'work-in-progress'?","options":{"A":"Partly completed goods on the factory floor that have had some raw materials and labor applied to them, but are not yet finished products ready for sale","B":"Finished goods already delivered to credit customers","C":"Long-term factory buildings currently under construction by an outside contractor","D":"Unpaid invoices owed to raw-material suppliers"},"correctOption":"A","correctAnswer":"Partly completed goods on the factory floor that have had some raw materials and labor applied to them, but are not yet finished products ready for sale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because work-in-progress sits between raw materials and finished goods in a manufacturer's inventory valuation.","distractor_reasons":{"A":"Option A is correct because work-in-progress sits between raw materials and finished goods in a manufacturer's inventory valuation.","B":"Incorrect because goods delivered on credit become trade receivables.","C":"Incorrect because factory buildings are non-current assets.","D":"Incorrect because supplier invoices are trade payables (current liabilities)."}}},{"id":"P1_U5_MCQ_835","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_835","question":"Which feature distinguishes a 'current liability' from a 'non-current liability'?","options":{"A":"Current liabilities are owed to shareholders, whereas non-current liabilities are owed to customers","B":"Current liabilities must be settled within 12 months of the reporting date, whereas non-current liabilities are repayable over more than 12 months","C":"Current liabilities are always interest-free, whereas non-current liabilities always carry dividends","D":"Current liabilities are owned assets, whereas non-current liabilities are expenses"},"correctOption":"B","correctAnswer":"Current liabilities must be settled within 12 months of the reporting date, whereas non-current liabilities are repayable over more than 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the 12-month repayment horizon separates short-term current obligations from long-term debt.","distractor_reasons":{"A":"Incorrect because both are external debts owed to creditors (suppliers, banks, tax authorities).","B":"Option B is correct because the 12-month repayment horizon separates short-term current obligations from long-term debt.","C":"Incorrect because bank overdrafts (current liabilities) charge interest, and debt carries interest rather than dividends.","D":"Incorrect because all liabilities are debts owed by the business."}}},{"id":"P1_U5_MCQ_836","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_836","question":"Why does an increase in 'trade payables' (without exceeding supplier credit limits) help finance a business's current assets?","options":{"A":"Because suppliers pay cash directly into the business's bank account","B":"Because trade payables are added to shareholders' equity","C":"Because buying inventory on supplier credit allows the business to hold and sell stock before having to use its own cash to pay the supplier","D":"Because trade payables reduce non-current assets"},"correctOption":"C","correctAnswer":"Because buying inventory on supplier credit allows the business to hold and sell stock before having to use its own cash to pay the supplier","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because trade payables act as spontaneous short-term financing that reduces the net working capital cash needed.","distractor_reasons":{"A":"Incorrect because suppliers provide goods on credit rather than lending cash.","B":"Incorrect because trade payables are current liabilities, not equity.","C":"Option C is correct because trade payables act as spontaneous short-term financing that reduces the net working capital cash needed.","D":"Incorrect because trade payables relate to short-term stock purchases, not non-current assets."}}},{"id":"P1_U5_MCQ_837","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_837","question":"If a business has received electricity and water during the final month of the year but has not yet paid the utility bill by the reporting date, how is that unpaid bill shown on the statement of financial position?","options":{"A":"As a current asset under cash at bank","B":"As a non-current asset under property","C":"As part of issued share capital","D":"As a current liability (accrued expense / short-term payable) because it is owed within 12 months"},"correctOption":"D","correctAnswer":"As a current liability (accrued expense / short-term payable) because it is owed within 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because unpaid short-term operating bills due within one year are current liabilities.","distractor_reasons":{"A":"Incorrect because owing money is a liability, not a cash asset.","B":"Incorrect because utility bills are short-term expenses, not long-term property assets.","C":"Incorrect because unpaid bills are creditor obligations, not owner share capital.","D":"Option D is correct because unpaid short-term operating bills due within one year are current liabilities."}}},{"id":"P1_U5_MCQ_838","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_838","question":"If a business takes out a 10-year bank loan, why is the portion due over years 2 to 10 classified as a 'non-current liability'?","options":{"A":"Because bank loans are an internal source of finance","B":"Because bank loans never have to be repaid","C":"Because those repayments are due more than 12 months after the statement of financial position date","D":"Because the loan is owned by the company's customers"},"correctOption":"C","correctAnswer":"Because those repayments are due more than 12 months after the statement of financial position date","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because long-term debt obligations extending beyond one year belong under non-current liabilities.","distractor_reasons":{"A":"Incorrect because bank loans are external debt.","B":"Incorrect because all loans must be repaid according to their repayment schedule.","C":"Option C is correct because long-term debt obligations extending beyond one year belong under non-current liabilities.","D":"Incorrect because the loan is owed by the business to the bank."}}},{"id":"P1_U5_MCQ_839","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_839","question":"How are 'debentures' classified differently from 'ordinary share capital' on a company's statement of financial position?","options":{"A":"Debentures are current assets, whereas ordinary share capital is a current liability","B":"Debentures are non-current liabilities (long-term external debt), whereas ordinary share capital is part of shareholders' equity (permanent owners' funds)","C":"Debentures are shareholders' equity, whereas ordinary share capital is a non-current liability","D":"Both debentures and ordinary share capital are recorded as non-current assets"},"correctOption":"B","correctAnswer":"Debentures are non-current liabilities (long-term external debt), whereas ordinary share capital is part of shareholders' equity (permanent owners' funds)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because debenture holders are long-term creditors whose principal must be repaid, whereas ordinary shareholders are permanent owners.","distractor_reasons":{"A":"Incorrect because neither is a current asset or current liability.","B":"Option B is correct because debenture holders are long-term creditors whose principal must be repaid, whereas ordinary shareholders are permanent owners.","C":"Incorrect because this reverses debt liabilities and owners' equity.","D":"Incorrect because both appear on the financing side (liabilities and equity), not as assets."}}},{"id":"P1_U5_MCQ_840","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_840","question":"On a statement of financial position, what does a positive 'working capital' (net current assets) figure confirm?","options":{"A":"That the business has zero long-term mortgages","B":"That the business's gross profit exceeds its sales revenue","C":"That the business's short-term current assets exceed its short-term current liabilities, providing a liquidity buffer for daily operations","D":"That the business has paid out 100% of its retained profit as dividends"},"correctOption":"C","correctAnswer":"That the business's short-term current assets exceed its short-term current liabilities, providing a liquidity buffer for daily operations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Working capital = Current assets - Current liabilities; a positive figure means short-term assets cover short-term obligations.","distractor_reasons":{"A":"Incorrect because a business can have positive working capital alongside long-term mortgages.","B":"Incorrect because gross profit cannot exceed sales revenue unless cost of sales is negative.","C":"Option C is correct because Working capital = Current assets - Current liabilities; a positive figure means short-term assets cover short-term obligations.","D":"Incorrect because working capital measures current assets minus current liabilities, not dividend payout."}}},{"id":"P1_U5_MCQ_841","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_841","question":"Why can holding 'excessively high working capital' on a statement of financial position be criticized by shareholders?","options":{"A":"Because high working capital proves the business is insolvent","B":"Because high working capital increases short-term bank overdraft interest","C":"Because high working capital reduces non-current liabilities to zero automatically","D":"Because excessive funds tied up in idle cash, bloated inventory, or slow-paying trade receivables earn little or no return compared with investing in productive growth"},"correctOption":"D","correctAnswer":"Because excessive funds tied up in idle cash, bloated inventory, or slow-paying trade receivables earn little or no return compared with investing in productive growth","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because too much working capital creates an opportunity cost and drags down Return on Capital Employed (ROCE).","distractor_reasons":{"A":"Incorrect because negative working capital signals insolvency risk, whereas excessive working capital signals inefficiency.","B":"Incorrect because holding large cash reserves reduces rather than increases overdraft borrowing.","C":"Incorrect because working capital levels do not automatically pay off long-term debt.","D":"Option D is correct because too much working capital creates an opportunity cost and drags down Return on Capital Employed (ROCE)."}}},{"id":"P1_U5_MCQ_842","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_842","question":"Which formula correctly calculates 'Net assets' on a statement of financial position?","options":{"A":"Non-current assets - Current assets","B":"Non-current assets + Current assets + Current liabilities + Non-current liabilities","C":"Current assets - Current liabilities","D":"Non-current assets + Current assets - Current liabilities - Non-current liabilities"},"correctOption":"D","correctAnswer":"Non-current assets + Current assets - Current liabilities - Non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Net assets equals Total assets (Non-current + Current) minus Total liabilities (Current + Non-current).","distractor_reasons":{"A":"Incorrect because current assets are added to non-current assets to form total assets.","B":"Incorrect because liabilities must be subtracted from assets, not added.","C":"Incorrect because current assets minus current liabilities calculates working capital (net current assets).","D":"Option D is correct because Net assets equals Total assets (Non-current + Current) minus Total liabilities (Current + Non-current)."}}},{"id":"P1_U5_MCQ_843","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_843","question":"How does the 'equity' section on a sole trader's statement of financial position differ from that of a limited company?","options":{"A":"A sole trader has issued share capital and corporate dividends, whereas a limited company has drawings","B":"A sole trader shows Opening capital + Profit for the year - Drawings, whereas a limited company shows Issued share capital + Retained profit reserves","C":"A sole trader has no equity section on its statement of financial position","D":"A limited company includes bank overdrafts inside shareholders' equity"},"correctOption":"B","correctAnswer":"A sole trader shows Opening capital + Profit for the year - Drawings, whereas a limited company shows Issued share capital + Retained profit reserves","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sole traders do not issue shares and withdraw funds via drawings, whereas limited companies issue shares and accumulate retained profit.","distractor_reasons":{"A":"Incorrect because this reverses sole traders and limited companies.","B":"Option B is correct because sole traders do not issue shares and withdraw funds via drawings, whereas limited companies issue shares and accumulate retained profit.","C":"Incorrect because sole traders always record owner's capital (equity).","D":"Incorrect because bank overdrafts are current liabilities, not equity."}}},{"id":"P1_U5_MCQ_844","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_844","question":"Why are 'current liabilities' excluded when calculating 'Capital employed' (Shareholders' equity + Non-current liabilities)?","options":{"A":"Because current liabilities are assets rather than liabilities","B":"Because current liabilities are never paid by limited companies","C":"Because capital employed measures the permanent, long-term funds invested in the business, whereas current liabilities are short-term operational debts fluctuating daily","D":"Because current liabilities are already included inside issued share capital"},"correctOption":"C","correctAnswer":"Because capital employed measures the permanent, long-term funds invested in the business, whereas current liabilities are short-term operational debts fluctuating daily","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed focuses on long-term financing (equity plus long-term debt) used to generate operating profit.","distractor_reasons":{"A":"Incorrect because current liabilities are short-term debts.","B":"Incorrect because current liabilities are settled within 12 months.","C":"Option C is correct because capital employed focuses on long-term financing (equity plus long-term debt) used to generate operating profit.","D":"Incorrect because share capital and current liabilities are entirely separate sections."}}},{"id":"P1_U5_MCQ_845","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_845","question":"When a limited company issues new ordinary shares for cash and deposits the proceeds into its bank account, what is the immediate effect on its statement of financial position?","options":{"A":"Current liabilities increase and non-current assets decrease","B":"Non-current liabilities increase and retained profit decreases","C":"Working capital decreases and net assets decrease","D":"Current assets (cash) increase and shareholders' equity (issued share capital) increases by the exact same amount"},"correctOption":"D","correctAnswer":"Current assets (cash) increase and shareholders' equity (issued share capital) increases by the exact same amount","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash enters the bank (+current asset) and permanent equity expands (+share capital), keeping the balance sheet in balance.","distractor_reasons":{"A":"Incorrect because issuing shares creates equity, not debt liabilities.","B":"Incorrect because share issues increase equity rather than non-current debt.","C":"Incorrect because higher cash increases both working capital and net assets.","D":"Option D is correct because cash enters the bank (+current asset) and permanent equity expands (+share capital), keeping the balance sheet in balance."}}},{"id":"P1_U5_MCQ_846","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_846","question":"When a business uses cash from its bank current account to pay off an overdue supplier invoice ('trade payable'), what happens on its statement of financial position?","options":{"A":"Working capital increases by the payment amount","B":"Current assets (cash) decrease and current liabilities (trade payables) decrease by the exact same amount, leaving working capital unchanged","C":"Non-current assets increase and equity increases","D":"Current assets increase and current liabilities decrease"},"correctOption":"B","correctAnswer":"Current assets (cash) decrease and current liabilities (trade payables) decrease by the exact same amount, leaving working capital unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because subtracting an equal amount from both Current assets and Current liabilities leaves the difference (Current assets - Current liabilities) unchanged.","distractor_reasons":{"A":"Incorrect because both cash and trade payables fall equally, leaving net working capital constant.","B":"Option B is correct because subtracting an equal amount from both Current assets and Current liabilities leaves the difference (Current assets - Current liabilities) unchanged.","C":"Incorrect because paying a supplier does not create non-current assets or equity.","D":"Incorrect because paying cash decreases rather than increases current assets."}}},{"id":"P1_U5_MCQ_847","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_847","question":"A company's statement of financial position shows total assets of $500,000 and total liabilities of $300,000. What is the value of its net assets (shareholders' equity)?","options":{"A":"$200,000","B":"$300,000","C":"$500,000","D":"$800,000"},"correctOption":"A","correctAnswer":"$200,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because net assets equal total assets minus total liabilities, that is $500,000 minus $300,000, giving $200,000.","distractor_reasons":{"A":"Option A is correct because net assets equal total assets minus total liabilities, that is $500,000 minus $300,000, giving $200,000.","B":"Incorrect because $300,000 is the total liabilities figure, not the amount left for shareholders after liabilities are deducted.","C":"Incorrect because $500,000 is the total assets figure and ignores what the business owes to others.","D":"Incorrect because $800,000 incorrectly adds assets and liabilities instead of subtracting liabilities from assets."}}},{"id":"P1_U5_MCQ_848","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_848","question":"Why do 'suppliers' inspect both 'cash at bank' and 'existing trade payables' on a customer's statement of financial position before offering 60-day trade credit?","options":{"A":"To calculate the customer's annual corporation tax rate","B":"To check whether the customer's directors own personal cars","C":"To judge whether the customer has sufficient liquid cash to pay its bills on time or is already heavily overdue with other suppliers","D":"To decide which advertising agency the customer should hire"},"correctOption":"C","correctAnswer":"To judge whether the customer has sufficient liquid cash to pay its bills on time or is already heavily overdue with other suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extending trade credit makes the supplier an unsecured short-term creditor exposed to default if the buyer lacks liquidity.","distractor_reasons":{"A":"Incorrect because tax rates are set by the government.","B":"Incorrect because directors' personal assets are not shown on company statements.","C":"Option C is correct because extending trade credit makes the supplier an unsecured short-term creditor exposed to default if the buyer lacks liquidity.","D":"Incorrect because marketing choices belong to the customer's managers."}}},{"id":"P1_U5_MCQ_849","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_849","question":"How can 'historical cost accounting' cause a statement of financial position to understate the true market value of a long-established company's property?","options":{"A":"Because property is recorded as a current liability","B":"Because property is omitted from the statement of financial position after five years","C":"Because property is always valued at zero","D":"Because freehold land and buildings bought decades ago may have risen substantially in market value, yet remain recorded at original historical purchase cost unless formally revalued"},"correctOption":"D","correctAnswer":"Because freehold land and buildings bought decades ago may have risen substantially in market value, yet remain recorded at original historical purchase cost unless formally revalued","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because recording assets at historical purchase price rather than current market value can create a large gap between book value and resale value.","distractor_reasons":{"A":"Incorrect because owned property is a non-current asset.","B":"Incorrect because freehold property remains on the statement for as long as the company owns it.","C":"Incorrect because property is recorded at its cost/carrying value, not zero.","D":"Option D is correct because recording assets at historical purchase price rather than current market value can create a large gap between book value and resale value."}}},{"id":"P1_U5_MCQ_850","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_850","question":"Why are 'skilled employees' and 'internally built customer loyalty' NOT listed as assets on a business's statement of financial position?","options":{"A":"Because accounting rules only record assets that can be reliably measured in monetary terms and are legally owned/controlled by the business (such as purchased assets)","B":"Because employees and customers have no impact on business success","C":"Because employees are recorded as non-current liabilities","D":"Because customer loyalty is recorded inside cost of sales"},"correctOption":"A","correctAnswer":"Because accounting rules only record assets that can be reliably measured in monetary terms and are legally owned/controlled by the business (such as purchased assets)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a business does not legally own its workers and cannot objectively assign a dollar valuation to internally generated brand goodwill.","distractor_reasons":{"A":"Option A is correct because a business does not legally own its workers and cannot objectively assign a dollar valuation to internally generated brand goodwill.","B":"Incorrect because skilled staff and loyal customers are vital competitive strengths, even though omitted from financial statements.","C":"Incorrect because employees are people, not non-current debt liabilities.","D":"Incorrect because customer loyalty is a qualitative intangible strength, not a direct cost of sales."}}},{"id":"P1_U5_MCQ_851","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_851","question":"How does calculating 'financial ratios' help analysts overcome the difficulty of comparing a large business with a smaller competitor?","options":{"A":"By forcing both businesses to report identical dollar sales revenue","B":"By deleting all non-current assets from the larger business's accounts","C":"By expressing profits, costs, and assets as relative percentages or proportions rather than raw dollar totals, allowing fair efficiency comparisons regardless of business size","D":"By eliminating corporation tax for the smaller business"},"correctOption":"C","correctAnswer":"By expressing profits, costs, and assets as relative percentages or proportions rather than raw dollar totals, allowing fair efficiency comparisons regardless of business size","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because relative ratios (such as ROCE or profit margin) normalize performance for scale.","distractor_reasons":{"A":"Incorrect because ratios compare proportions rather than changing underlying revenue.","B":"Incorrect because ratios use accurate financial statement figures without deleting assets.","C":"Option C is correct because relative ratios (such as ROCE or profit margin) normalize performance for scale.","D":"Incorrect because analytical ratios do not alter tax obligations."}}},{"id":"P1_U5_MCQ_852","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_852","question":"Why is examining a single year's financial ratios in isolation rarely enough to draw reliable conclusions about a business?","options":{"A":"Because ratios can only be calculated once every ten years","B":"Because without comparing against previous years (trend analysis) and industry benchmarks, an analyst cannot tell whether a ratio is improving, deteriorating, or normal for that sector","C":"Because single-year ratios omit all revenue and current assets","D":"Because financial ratios are illegal to use without government permission"},"correctOption":"B","correctAnswer":"Because without comparing against previous years (trend analysis) and industry benchmarks, an analyst cannot tell whether a ratio is improving, deteriorating, or normal for that sector","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because context is essential: a 10% profit margin might be outstanding in grocery retailing but weak in luxury software.","distractor_reasons":{"A":"Incorrect because ratios are calculated annually (or more frequently internally).","B":"Option B is correct because context is essential: a 10% profit margin might be outstanding in grocery retailing but weak in luxury software.","C":"Incorrect because single-year ratios include the relevant figures from that year's statements.","D":"Incorrect because anyone analyzing published accounts can freely compute ratios."}}},{"id":"P1_U5_MCQ_853","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_853","question":"Which formula correctly calculates 'Gross profit margin (%)'?","options":{"A":"(Revenue / Gross profit) × 100","B":"(Profit / Revenue) × 100","C":"(Gross profit / Revenue) × 100","D":"(Gross profit / Cost of sales) × 100"},"correctOption":"C","correctAnswer":"(Gross profit / Revenue) × 100","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because gross profit margin measures gross profit as a percentage of total sales revenue.","distractor_reasons":{"A":"Incorrect because this inverts gross profit and revenue.","B":"Incorrect because (Profit / Revenue) × 100 is the formula for profit margin.","C":"Option C is correct because gross profit margin measures gross profit as a percentage of total sales revenue.","D":"Incorrect because dividing by cost of sales calculates mark-up on cost rather than gross profit margin on sales."}}},{"id":"P1_U5_MCQ_854","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_854","question":"How can a shift in 'product sales mix' cause a retailer's 'gross profit margin' to fall even if unit selling prices and supplier costs on every individual item stay unchanged?","options":{"A":"Because head-office rent increased during the year","B":"Because the retailer issued new ordinary shares","C":"Because customers paid their invoices 10 days earlier","D":"Because customers bought a higher proportion of low-margin basic items and a lower proportion of high-margin luxury items, lowering the overall weighted average gross profit margin"},"correctOption":"D","correctAnswer":"Because customers bought a higher proportion of low-margin basic items and a lower proportion of high-margin luxury items, lowering the overall weighted average gross profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because company-wide gross profit margin reflects the blended average margin across all products sold.","distractor_reasons":{"A":"Incorrect because head-office rent is an indirect overhead expense and does not affect gross profit margin.","B":"Incorrect because share issues affect equity, not gross profit margin.","C":"Incorrect because faster receivable collections improve cash flow, not gross profit margin.","D":"Option D is correct because company-wide gross profit margin reflects the blended average margin across all products sold."}}},{"id":"P1_U5_MCQ_855","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_855","question":"What does a 'profit margin' of 15% tell a business analyst?","options":{"A":"That for every $100 of sales revenue earned, $15 remains as operating profit after paying both direct cost of sales and indirect overhead expenses","B":"That the business holds $15 of cash for every $100 of current liabilities","C":"That the business generates $15 of profit for every $100 of non-current assets owned","D":"That 15% of the business's customers failed to pay their invoices"},"correctOption":"A","correctAnswer":"That for every $100 of sales revenue earned, $15 remains as operating profit after paying both direct cost of sales and indirect overhead expenses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Profit margin = (Profit / Revenue) × 100, showing final operating profit retained per $100 of sales.","distractor_reasons":{"A":"Option A is correct because Profit margin = (Profit / Revenue) × 100, showing final operating profit retained per $100 of sales.","B":"Incorrect because liquidity coverage of current liabilities is measured by the current and acid-test ratios.","C":"Incorrect because return on capital invested is measured by ROCE.","D":"Incorrect because bad debts are uncollected receivables, not profit margin."}}},{"id":"P1_U5_MCQ_856","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_856","question":"Why is a business's 'profit margin (%)' always lower than its 'gross profit margin (%)' (assuming the business has positive overhead expenses)?","options":{"A":"Because profit margin divides by capital employed instead of revenue","B":"Because profit margin deducts indirect overhead expenses in addition to direct cost of sales, making the numerator (profit) smaller than gross profit while the denominator (revenue) stays the same","C":"Because gross profit margin adds overhead expenses to revenue","D":"Because profit margin excludes sales revenue"},"correctOption":"B","correctAnswer":"Because profit margin deducts indirect overhead expenses in addition to direct cost of sales, making the numerator (profit) smaller than gross profit while the denominator (revenue) stays the same","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Profit = Gross profit - Overhead expenses; since Profit < Gross profit, (Profit / Revenue) × 100 is smaller than (Gross profit / Revenue) × 100.","distractor_reasons":{"A":"Incorrect because dividing by capital employed is ROCE; both gross profit margin and profit margin divide by revenue.","B":"Option B is correct because Profit = Gross profit - Overhead expenses; since Profit < Gross profit, (Profit / Revenue) × 100 is smaller than (Gross profit / Revenue) × 100.","C":"Incorrect because gross profit margin does not add overheads to revenue.","D":"Incorrect because revenue is the denominator in profit margin."}}},{"id":"P1_U5_MCQ_857","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_857","question":"If intense market competition prevents a business from raising its selling prices, how can management still increase its 'profit margin'?","options":{"A":"By increasing head-office administrative salaries and rent","B":"By taking out a larger short-term bank overdraft","C":"By reducing direct production wastage, negotiating bulk discounts on materials, and cutting unnecessary indirect overhead expenses","D":"By increasing inventory levels in the warehouse"},"correctOption":"C","correctAnswer":"By reducing direct production wastage, negotiating bulk discounts on materials, and cutting unnecessary indirect overhead expenses","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when selling prices are constrained by competitors, improving cost efficiency in cost of sales and overheads widens profit margins.","distractor_reasons":{"A":"Incorrect because higher salaries and rent reduce profit margin.","B":"Incorrect because an overdraft adds interest expenses and does not improve operating profit margin.","C":"Option C is correct because when selling prices are constrained by competitors, improving cost efficiency in cost of sales and overheads widens profit margins.","D":"Incorrect because holding more inventory increases storage costs without raising profit margin."}}},{"id":"P1_U5_MCQ_858","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_858","question":"Which components form the denominator 'Capital employed' in the formula 'ROCE = (Profit / Capital employed) × 100'?","options":{"A":"Current assets + Current liabilities","B":"Sales revenue - Cost of sales","C":"Cash at bank + Trade receivables","D":"Total shareholders' equity (Share capital + Retained profit) + Non-current liabilities"},"correctOption":"D","correctAnswer":"Total shareholders' equity (Share capital + Retained profit) + Non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because capital employed represents all long-term funds invested in the business by owners and long-term lenders.","distractor_reasons":{"A":"Incorrect because short-term current items do not equal capital employed.","B":"Incorrect because revenue minus cost of sales is gross profit.","C":"Incorrect because cash and receivables are liquid current assets, not long-term capital employed.","D":"Option D is correct because capital employed represents all long-term funds invested in the business by owners and long-term lenders."}}},{"id":"P1_U5_MCQ_859","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_859","question":"A manufacturing firm wants to improve its return on capital employed but cannot increase operating profit. Which action would improve this ratio?","options":{"A":"Sell underused non-current assets to reduce capital employed.","B":"Issue more shares and keep the cash inside the business.","C":"Increase operating expenses to reduce the tax bill.","D":"Borrow more and use the cash to buy extra machinery."},"correctOption":"A","correctAnswer":"Sell underused non-current assets to reduce capital employed.","questionType":"MCQ","explanation":{"correct_reason":"ROCE is operating profit divided by capital employed. With profit unchanged, reducing capital employed by selling unused assets raises the percentage.","distractor_reasons":{"A":"ROCE is operating profit divided by capital employed. With profit unchanged, reducing capital employed by selling unused assets raises the percentage.","B":"Issuing shares adds equity, increasing capital employed and so lowering ROCE.","C":"Higher operating expenses reduce operating profit, which lowers ROCE.","D":"Extra borrowing and machinery increase capital employed, so ROCE falls unless profit rises as well."}}},{"id":"P1_U5_MCQ_860","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_860","question":"Why do shareholders compare a company's 'ROCE' against the interest rate offered on safe government bonds or bank deposit accounts?","options":{"A":"Because ROCE measures whether the company can pay its short-term trade payables","B":"Because investing in company shares carries commercial risk, so shareholders expect ROCE to be significantly higher than risk-free interest rates to justify the risk","C":"Because companies are legally fined if their ROCE exceeds bank interest rates","D":"Because bank deposit interest rates determine the company's gross profit margin"},"correctOption":"B","correctAnswer":"Because investing in company shares carries commercial risk, so shareholders expect ROCE to be significantly higher than risk-free interest rates to justify the risk","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because risk-free deposit rates represent the opportunity cost of capital; if ROCE is lower than bank deposit rates, capital is being used inefficiently.","distractor_reasons":{"A":"Incorrect because short-term debt coverage is measured by liquidity ratios.","B":"Option B is correct because risk-free deposit rates represent the opportunity cost of capital; if ROCE is lower than bank deposit rates, capital is being used inefficiently.","C":"Incorrect because higher ROCE is rewarded by investors, never fined.","D":"Incorrect because deposit rates do not dictate gross profit margins."}}},{"id":"P1_U5_MCQ_861","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_861","question":"Why is 'liquidity analysis' distinct from 'profitability analysis' when judging a business's financial health?","options":{"A":"Liquidity analysis only looks at non-current assets, while profitability analysis only looks at liabilities","B":"Liquidity analysis is used only by shareholders, while profitability analysis is used only by suppliers","C":"Profitability analysis measures whether revenue exceeds costs over time, whereas liquidity analysis measures whether the business holds enough cash and near-cash assets to pay immediate short-term bills","D":"Both liquidity analysis and profitability analysis use the exact same formulas"},"correctOption":"C","correctAnswer":"Profitability analysis measures whether revenue exceeds costs over time, whereas liquidity analysis measures whether the business holds enough cash and near-cash assets to pay immediate short-term bills","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a business can be profitable on paper yet illiquid in cash, so both dimensions must be analyzed separately.","distractor_reasons":{"A":"Incorrect because liquidity focuses on current assets and current liabilities, while profitability focuses on income statement margins and ROCE.","B":"Incorrect because all major stakeholders examine both dimensions.","C":"Option C is correct because a business can be profitable on paper yet illiquid in cash, so both dimensions must be analyzed separately.","D":"Incorrect because profitability and liquidity ratios use distinct formulas."}}},{"id":"P1_U5_MCQ_862","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_862","question":"A business has an acid-test ratio of 0.8:1. What does this figure indicate?","options":{"A":"Its profitability has been rising steadily","B":"It has twice as many liquid assets as current liabilities","C":"Its liquid assets are not sufficient to cover its current liabilities","D":"Its sales revenue is growing faster than its costs"},"correctOption":"C","correctAnswer":"Its liquid assets are not sufficient to cover its current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an acid-test ratio below 1:1 means current assets excluding inventories are less than current liabilities.","distractor_reasons":{"A":"Incorrect because the acid-test ratio measures liquidity rather than profitability or changes in profit over time.","B":"Incorrect because a ratio of 2:1, not 0.8:1, would mean liquid assets were twice current liabilities.","C":"Option C is correct because an acid-test ratio below 1:1 means current assets excluding inventories are less than current liabilities.","D":"Incorrect because the acid-test ratio compares assets and liabilities and says nothing about sales growth."}}},{"id":"P1_U5_MCQ_863","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_863","question":"If a manufacturing company's 'current ratio' falls steadily over three consecutive years from 2.1 : 1 to 1.4 : 1 to 0.9 : 1, what trend does this show?","options":{"A":"Deteriorating short-term liquidity, culminating in current liabilities exceeding current assets and signaling growing risk of cash shortages","B":"Steadily improving profitability and higher gross profit margins","C":"A steady reduction in short-term debts relative to cash","D":"Excessive idle cash accumulating in the bank account"},"correctOption":"A","correctAnswer":"Deteriorating short-term liquidity, culminating in current liabilities exceeding current assets and signaling growing risk of cash shortages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a falling current ratio below 1 : 1 warns that short-term obligations are outgrowing short-term liquid resources.","distractor_reasons":{"A":"Option A is correct because a falling current ratio below 1 : 1 warns that short-term obligations are outgrowing short-term liquid resources.","B":"Incorrect because the current ratio measures liquidity, not profitability.","C":"Incorrect because a falling ratio means short-term debts are growing *faster* than current assets.","D":"Incorrect because accumulating cash would raise rather than lower the current ratio."}}},{"id":"P1_U5_MCQ_864","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_864","question":"Which transaction would cause a business's 'current ratio' to *fall* immediately?","options":{"A":"Collecting payment from a credit customer in cash","B":"Using existing cash from the bank current account to buy a new freehold factory building","C":"Issuing new ordinary shares for cash","D":"Selling surplus, unused factory machinery for cash"},"correctOption":"B","correctAnswer":"Using existing cash from the bank current account to buy a new freehold factory building","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because spending cash (a current asset) on a freehold building (a non-current asset) reduces the numerator of the current ratio while current liabilities stay unchanged.","distractor_reasons":{"A":"Incorrect because collecting a receivable swaps receivables for cash, leaving total current assets unchanged.","B":"Option B is correct because spending cash (a current asset) on a freehold building (a non-current asset) reduces the numerator of the current ratio while current liabilities stay unchanged.","C":"Incorrect because issuing shares for cash increases current assets and raises the current ratio.","D":"Incorrect because selling non-current assets for cash increases current assets and raises the current ratio."}}},{"id":"P1_U5_MCQ_865","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_865","question":"Which assets are included in the numerator of the 'Acid-test (quick) ratio' [(Current assets - Inventories) / Current liabilities]?","options":{"A":"Non-current assets and inventories","B":"Inventories and trade payables","C":"Liquid current assets only—specifically cash (in hand and at bank) and trade receivables","D":"Issued share capital and retained profit"},"correctOption":"C","correctAnswer":"Liquid current assets only—specifically cash (in hand and at bank) and trade receivables","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because removing inventories from current assets leaves cash and trade receivables as the quick assets tested against current liabilities.","distractor_reasons":{"A":"Incorrect because non-current assets and inventories are both excluded from the acid-test ratio.","B":"Incorrect because inventories are excluded and trade payables are current liabilities.","C":"Option C is correct because removing inventories from current assets leaves cash and trade receivables as the quick assets tested against current liabilities.","D":"Incorrect because share capital and retained profit are shareholders' equity."}}},{"id":"P1_U5_MCQ_866","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_866","question":"For which type of business is the 'acid-test ratio' particularly revealing compared with the 'current ratio'?","options":{"A":"A pure digital software consultancy that holds zero physical inventory","B":"A bank that holds only financial deposits","C":"A business with zero current liabilities","D":"A retailer or manufacturer holding large amounts of slow-moving or perishable inventory (such as fashion clothing or fresh food) that may be hard to sell quickly at full price"},"correctOption":"D","correctAnswer":"A retailer or manufacturer holding large amounts of slow-moving or perishable inventory (such as fashion clothing or fresh food) that may be hard to sell quickly at full price","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when inventory is large and slow-moving or perishable, the current ratio can look deceptively safe while the acid-test ratio exposes true cash tightness.","distractor_reasons":{"A":"Incorrect because when inventory is zero, the acid-test ratio and current ratio are identical.","B":"Incorrect because without physical inventories, both ratios yield the same value.","C":"Incorrect because zero current liabilities makes both ratios undefined.","D":"Option D is correct because when inventory is large and slow-moving or perishable, the current ratio can look deceptively safe while the acid-test ratio exposes true cash tightness."}}},{"id":"P1_U5_MCQ_867","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_867","question":"If a business's 'current ratio' and 'acid-test ratio' are exactly equal (for example, both equal 1.6 : 1), what must be true about the business?","options":{"A":"The business has zero trade receivables","B":"The business holds zero inventories on its statement of financial position","C":"The business has zero current liabilities","D":"The business is making a net loss"},"correctOption":"B","correctAnswer":"The business holds zero inventories on its statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Current assets / Current liabilities equals (Current assets - Inventories) / Current liabilities only when Inventories = 0.","distractor_reasons":{"A":"Incorrect because trade receivables are included in both ratios.","B":"Option B is correct because Current assets / Current liabilities equals (Current assets - Inventories) / Current liabilities only when Inventories = 0.","C":"Incorrect because zero current liabilities would prevent dividing to get 1.6 : 1.","D":"Incorrect because liquidity ratios do not indicate trading profit or loss."}}},{"id":"P1_U5_MCQ_868","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_868","question":"How do 'potential equity investors' use profitability ratios (such as ROCE and profit margin) when comparing two competing companies in the same industry?","options":{"A":"To check which company employs more factory cleaners","B":"To identify which company converts sales and invested capital into profit more efficiently, signaling stronger management and higher potential returns","C":"To calculate the national unemployment rate","D":"To force the less profitable company to lower its selling prices"},"correctOption":"B","correctAnswer":"To identify which company converts sales and invested capital into profit more efficiently, signaling stronger management and higher potential returns","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inter-firm ratio comparison helps investors allocate capital toward the best-performing company in a sector.","distractor_reasons":{"A":"Incorrect because ratios measure financial efficiency, not staffing details.","B":"Option B is correct because inter-firm ratio comparison helps investors allocate capital toward the best-performing company in a sector.","C":"Incorrect because unemployment is a macroeconomic statistic.","D":"Incorrect because outside investors cannot dictate a company's operational pricing."}}},{"id":"P1_U5_MCQ_869","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_869","question":"When a business applies to renew or increase its 'bank overdraft facility', why does the bank manager scrutinize the business's 'acid-test ratio'?","options":{"A":"Because the acid-test ratio calculates the company's annual dividend payout","B":"Because the bank wants to know the historical purchase price of freehold land","C":"Because the acid-test ratio shows whether the business can quickly generate liquid cash from receivables and existing bank balances to repay the overdraft without relying on fire-sale inventory disposals","D":"Because the acid-test ratio measures employee job satisfaction"},"correctOption":"C","correctAnswer":"Because the acid-test ratio shows whether the business can quickly generate liquid cash from receivables and existing bank balances to repay the overdraft without relying on fire-sale inventory disposals","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because overdrafts are short-term recallable facilities, making immediate near-cash liquidity crucial to the lending bank.","distractor_reasons":{"A":"Incorrect because dividends are shown on the statement of profit or loss.","B":"Incorrect because freehold land is a non-current asset excluded from the acid-test ratio.","C":"Option C is correct because overdrafts are short-term recallable facilities, making immediate near-cash liquidity crucial to the lending bank.","D":"Incorrect because ratios measure financial data, not employee morale."}}},{"id":"P1_U5_MCQ_870","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_870","question":"If a prospective business customer has a dangerously low 'acid-test ratio' (e.g., 0.4 : 1), what protective action might a cautious 'supplier' take?","options":{"A":"Offer the customer 180-day interest-free trade credit automatically","B":"Buy ordinary shares in the customer's business","C":"Double the customer's credit limit without checking references","D":"Refuse open trade credit and insist on 'cash on delivery' (or upfront payment) to avoid the risk of unpaid invoices"},"correctOption":"D","correctAnswer":"Refuse open trade credit and insist on 'cash on delivery' (or upfront payment) to avoid the risk of unpaid invoices","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a very low acid-test ratio signals severe short-term cash strain and high default risk on supplier invoices.","distractor_reasons":{"A":"Incorrect because extending generous credit to an illiquid buyer increases bad-debt risk.","B":"Incorrect because commercial suppliers sell goods rather than buying shares in struggling customers.","C":"Incorrect because a weak liquidity ratio prompts tighter, not looser, credit limits.","D":"Option D is correct because a very low acid-test ratio signals severe short-term cash strain and high default risk on supplier invoices."}}},{"id":"P1_U5_MCQ_871","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_871","question":"How can 'employees and trade unions' use a company's improving 'profit margin' and 'ROCE' during annual collective bargaining?","options":{"A":"As objective evidence that the company's financial performance and efficiency have strengthened, supporting claims for higher wages, bonuses, or improved working conditions","B":"To legally force the company to cancel all shareholder dividends","C":"To set the government's national corporation tax rate","D":"To replace the board of directors with factory supervisors"},"correctOption":"A","correctAnswer":"As objective evidence that the company's financial performance and efficiency have strengthened, supporting claims for higher wages, bonuses, or improved working conditions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising profitability ratios show the employer is generating stronger returns and can better afford pay improvements.","distractor_reasons":{"A":"Option A is correct because rising profitability ratios show the employer is generating stronger returns and can better afford pay improvements.","B":"Incorrect because dividend decisions rest with directors and shareholders.","C":"Incorrect because governments set tax rates.","D":"Incorrect because shareholders appoint directors."}}},{"id":"P1_U5_MCQ_872","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_872","question":"How do 'senior managers' use financial ratio targets (such as a target ROCE or minimum current ratio) in strategic planning?","options":{"A":"To avoid keeping accounting records during the year","B":"As clear performance benchmarks to evaluate investment proposals, control working capital, and reward managerial performance","C":"To eliminate all competitors from the industry","D":"To guarantee that inflation stays at 0%"},"correctOption":"B","correctAnswer":"As clear performance benchmarks to evaluate investment proposals, control working capital, and reward managerial performance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ratio targets translate broad financial goals into measurable criteria for capital allocation and operational discipline.","distractor_reasons":{"A":"Incorrect because accurate accounting records are required to compute ratios.","B":"Option B is correct because ratio targets translate broad financial goals into measurable criteria for capital allocation and operational discipline.","C":"Incorrect because internal targets do not eliminate market competition.","D":"Incorrect because macroeconomic inflation is outside business control."}}},{"id":"P1_U5_MCQ_873","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_873","question":"Why does 'historical lag' limit the usefulness of published financial ratios when an investor is deciding whether to buy shares today?","options":{"A":"Because published accounts only report figures from ten years ago","B":"Because published ratios exclude all profit and asset figures","C":"Because annual accounts are published months after the financial year ends and reflect past conditions, whereas new competitors, technology shifts, or economic downturns may have already altered current prospects","D":"Because historical ratios are always calculated inaccurately by external auditors"},"correctOption":"C","correctAnswer":"Because annual accounts are published months after the financial year ends and reflect past conditions, whereas new competitors, technology shifts, or economic downturns may have already altered current prospects","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because financial statements are backward-looking; strong past ratios do not guarantee future resilience in fast-changing markets.","distractor_reasons":{"A":"Incorrect because annual accounts cover the most recently completed financial year.","B":"Incorrect because published accounts include complete profit and balance sheet data.","C":"Option C is correct because financial statements are backward-looking; strong past ratios do not guarantee future resilience in fast-changing markets.","D":"Incorrect because external auditors verify numerical accuracy; the limitation is time lag and backward focus."}}},{"id":"P1_U5_MCQ_874","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_874","question":"Which critical business factor is completely invisible in financial ratio analysis, requiring decision-makers to look beyond the numbers?","options":{"A":"Sales revenue and cost of sales","B":"Current assets and current liabilities","C":"Issued share capital and non-current liabilities","D":"Qualitative factors such as employee morale, management leadership quality, brand reputation, customer satisfaction, and environmental sustainability"},"correctOption":"D","correctAnswer":"Qualitative factors such as employee morale, management leadership quality, brand reputation, customer satisfaction, and environmental sustainability","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ratios quantify financial outcomes only and cannot capture non-financial drivers that determine long-term competitiveness.","distractor_reasons":{"A":"Incorrect because revenue and cost of sales are directly measured in gross profit margin.","B":"Incorrect because current assets and current liabilities are directly measured in liquidity ratios.","C":"Incorrect because share capital and non-current liabilities are directly included in ROCE.","D":"Option D is correct because ratios quantify financial outcomes only and cannot capture non-financial drivers that determine long-term competitiveness."}}},{"id":"P1_U5_MCQ_875","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_875","question":"Which of the following measures profitability rather than liquidity?","options":{"A":"The current ratio","B":"Return on capital employed (ROCE)","C":"The acid-test ratio","D":"The difference between current assets and current liabilities"},"correctOption":"B","correctAnswer":"Return on capital employed (ROCE)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ROCE compares profit with the capital employed and therefore measures profitability, not liquidity.","distractor_reasons":{"A":"Incorrect because the current ratio is a liquidity measure comparing short-term assets with short-term liabilities.","B":"Option B is correct because ROCE compares profit with the capital employed and therefore measures profitability, not liquidity.","C":"Incorrect because the acid-test ratio is a stricter liquidity measure that excludes inventories from current assets.","D":"Incorrect because working capital is a measure of short-term liquidity, not of profitability."}}},{"id":"P1_U5_MCQ_876","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_876","question":"Why does 'expansion capital' needed by a domestic manufacturer entering overseas markets differ in purpose from 'start-up capital'?","options":{"A":"Expansion capital funds new overseas distribution hubs, export marketing, and extra production capacity for an established firm, whereas start-up capital funds initial premises, equipment, and launch inventory for a brand-new venture","B":"Expansion capital is always free of interest, whereas start-up capital always incurs corporation tax","C":"Expansion capital is only used to pay daily electricity bills, whereas start-up capital is only used to pay shareholder dividends","D":"Expansion capital is classified as a current liability, whereas start-up capital is classified as sales revenue"},"correctOption":"A","correctAnswer":"Expansion capital funds new overseas distribution hubs, export marketing, and extra production capacity for an established firm, whereas start-up capital funds initial premises, equipment, and launch inventory for a brand-new venture","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because start-up capital launches a new enterprise from scratch, whereas expansion capital scales up operations, capacity, or geographic reach for an existing business.","distractor_reasons":{"A":"Option A is correct because start-up capital launches a new enterprise from scratch, whereas expansion capital scales up operations, capacity, or geographic reach for an existing business.","B":"Incorrect because both types of capital may incur borrowing costs depending on the source used.","C":"Incorrect because expansion capital funds long-term growth investments rather than routine utility bills.","D":"Incorrect because neither is classified as sales revenue."}}},{"id":"P1_U5_MCQ_877","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_877","question":"A food-processing factory installs a $120,000 industrial refrigeration system expected to last 10 years and spends $3,500 per month on electricity to run it. How are these two outlays classified?","options":{"A":"Both outlays are revenue expenditure","B":"The $120,000 refrigeration system is capital expenditure, whereas the $3,500 monthly electricity bill is revenue expenditure","C":"The $120,000 refrigeration system is revenue expenditure, whereas the $3,500 monthly electricity bill is capital expenditure","D":"Both outlays are capital expenditure"},"correctOption":"B","correctAnswer":"The $120,000 refrigeration system is capital expenditure, whereas the $3,500 monthly electricity bill is revenue expenditure","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because acquiring a long-term non-current asset lasting over 12 months is capital expenditure, while ongoing operational utility bills are revenue expenditure.","distractor_reasons":{"A":"Incorrect because a 10-year refrigeration plant is a non-current asset (capital expenditure).","B":"Option B is correct because acquiring a long-term non-current asset lasting over 12 months is capital expenditure, while ongoing operational utility bills are revenue expenditure.","C":"Incorrect because this reverses capital and revenue expenditure.","D":"Incorrect because monthly electricity is consumed immediately in daily operations."}}},{"id":"P1_U5_MCQ_878","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_878","question":"How can adopting 'Just-in-Time (JIT) inventory management' act as an internal source of finance for a manufacturer?","options":{"A":"By borrowing extra money from a commercial bank at a variable interest rate","B":"By issuing preference shares to raw-material suppliers","C":"By drastically reducing the volume of raw materials and finished goods held in storage, freeing up cash previously tied up in working capital","D":"By increasing warehouse rent and insurance payments"},"correctOption":"C","correctAnswer":"By drastically reducing the volume of raw materials and finished goods held in storage, freeing up cash previously tied up in working capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lowering inventory levels releases cash trapped in unsold stock without incurring external borrowing costs.","distractor_reasons":{"A":"Incorrect because JIT is an internal operational efficiency method, not bank borrowing.","B":"Incorrect because JIT does not involve issuing shares.","C":"Option C is correct because lowering inventory levels releases cash trapped in unsold stock without incurring external borrowing costs.","D":"Incorrect because holding smaller inventories reduces storage and insurance costs."}}},{"id":"P1_U5_MCQ_879","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_879","question":"What is a major financial trade-off when a retail chain raises internal capital through the 'sale and leaseback' of its freehold stores?","options":{"A":"The retail chain must immediately close all its stores and stop trading","B":"The retail chain dilutes its ordinary shareholders' voting rights","C":"The retail chain must repay the sale proceeds to the buyer within 12 months","D":"It unlocks a large lump sum of cash while allowing the retailer to continue operating in the stores, but creates a permanent ongoing fixed rent outflow and forfeits future property appreciation"},"correctOption":"D","correctAnswer":"It unlocks a large lump sum of cash while allowing the retailer to continue operating in the stores, but creates a permanent ongoing fixed rent outflow and forfeits future property appreciation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sale and leaseback converts illiquid property equity into immediate cash at the expense of recurring lease payments and loss of asset ownership.","distractor_reasons":{"A":"Incorrect because the 'leaseback' clause guarantees continued operational use of the premises.","B":"Incorrect because selling property does not alter share ownership.","C":"Incorrect because the property is sold outright rather than borrowed.","D":"Option D is correct because sale and leaseback converts illiquid property equity into immediate cash at the expense of recurring lease payments and loss of asset ownership."}}},{"id":"P1_U5_MCQ_880","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_880","question":"Why might a rapidly growing profitable company still be unable to finance a $15 million automated warehouse purely from 'retained profit'?","options":{"A":"Because retained profit carries a higher interest rate than a bank overdraft","B":"Because limited companies are legally forbidden from using retained profit to buy buildings","C":"Because accumulated retained profits from previous years may be far smaller than $15 million or already tied up in existing equipment and working capital","D":"Because using retained profit transfers ownership of the warehouse to the government"},"correctOption":"C","correctAnswer":"Because accumulated retained profits from previous years may be far smaller than $15 million or already tied up in existing equipment and working capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal retained profits accumulate gradually and are often insufficient on their own for sudden, large-scale capital projects.","distractor_reasons":{"A":"Incorrect because retained profit incurs zero interest charges.","B":"Incorrect because retained profit is frequently used for capital expenditure.","C":"Option C is correct because internal retained profits accumulate gradually and are often insufficient on their own for sudden, large-scale capital projects.","D":"Incorrect because assets bought with retained profit belong entirely to the company."}}},{"id":"P1_U5_MCQ_881","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_881","question":"Besides providing equity finance to high-growth start-ups, what non-financial benefit do 'venture capitalists' often bring to an entrepreneur?","options":{"A":"A legal guarantee that the start-up will never face competitors","B":"Specialist industry expertise, strategic mentoring, and commercial contacts that help scale the business rapidly","C":"100% exemption from corporation tax and value-added tax","D":"Zero dilution of the founder's ownership share or board control"},"correctOption":"B","correctAnswer":"Specialist industry expertise, strategic mentoring, and commercial contacts that help scale the business rapidly","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because venture capital firms actively advise and network with portfolio companies to maximize growth and exit valuation.","distractor_reasons":{"A":"Incorrect because venture capitalists cannot eliminate market competition.","B":"Option B is correct because venture capital firms actively advise and network with portfolio companies to maximize growth and exit valuation.","C":"Incorrect because venture-backed firms still pay all statutory taxes.","D":"Incorrect because venture capitalists require an equity stake and board representation in return for their high-risk investment."}}},{"id":"P1_U5_MCQ_882","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_882","question":"Which external source of finance is specifically designed as a long-term loan (often 15 to 25 years) secured directly against the freehold land or commercial building being purchased?","options":{"A":"Trade credit","B":"Debt factoring","C":"A commercial mortgage","D":"A bank overdraft"},"correctOption":"C","correctAnswer":"A commercial mortgage","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a commercial mortgage uses the acquired real estate as collateral over a multi-decade repayment period.","distractor_reasons":{"A":"Incorrect because trade credit is a 30–60 day supplier facility for inventory purchases.","B":"Incorrect because debt factoring advances cash against short-term customer invoices.","C":"Option C is correct because a commercial mortgage uses the acquired real estate as collateral over a multi-decade repayment period.","D":"Incorrect because an overdraft is a short-term working capital facility."}}},{"id":"P1_U5_MCQ_883","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_883","question":"How do 'preference shares' differ from 'ordinary shares' when a limited company distributes profits?","options":{"A":"Preference shareholders control all board voting decisions, whereas ordinary shareholders cannot vote","B":"Preference shares are short-term current liabilities repaid every 30 days","C":"Preference shareholders receive dividends only after ordinary shareholders have been paid","D":"Preference shareholders receive a fixed percentage dividend ahead of ordinary shareholders, though they normally do not carry voting rights at the Annual General Meeting"},"correctOption":"D","correctAnswer":"Preference shareholders receive a fixed percentage dividend ahead of ordinary shareholders, though they normally do not carry voting rights at the Annual General Meeting","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because preference shares combine priority fixed dividend returns with limited voting control, whereas ordinary shares carry voting power and variable residual dividends.","distractor_reasons":{"A":"Incorrect because ordinary shareholders hold voting control, while preference shares are typically non-voting.","B":"Incorrect because share capital is permanent equity, not a 30-day liability.","C":"Incorrect because preference dividends have priority *before* ordinary dividends.","D":"Option D is correct because preference shares combine priority fixed dividend returns with limited voting control, whereas ordinary shares carry voting power and variable residual dividends."}}},{"id":"P1_U5_MCQ_884","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_884","question":"How does issuing 'debentures' differ from taking a standard 'commercial bank loan'?","options":{"A":"Debentures are long-term debt certificates issued directly to institutional or public investors at a fixed interest rate, allowing a large company to raise substantial long-term debt without relying on a single bank","B":"Debentures give investors permanent voting ownership of the company, whereas bank loans do not","C":"Debentures never require paying interest or repaying principal","D":"Debentures are an internal source of finance"},"correctOption":"A","correctAnswer":"Debentures are long-term debt certificates issued directly to institutional or public investors at a fixed interest rate, allowing a large company to raise substantial long-term debt without relying on a single bank","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because debentures are tradable long-term corporate debt instruments sold to bond investors rather than negotiated with one commercial bank.","distractor_reasons":{"A":"Option A is correct because debentures are tradable long-term corporate debt instruments sold to bond investors rather than negotiated with one commercial bank.","B":"Incorrect because debenture holders are creditors without voting rights.","C":"Incorrect because debentures carry fixed annual interest and a maturity repayment date.","D":"Incorrect because debentures raise funds from external investors."}}},{"id":"P1_U5_MCQ_885","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_885","question":"Why does financing the construction of a new $2 million factory using a 'short-term bank overdraft' violate sound financial management principles?","options":{"A":"Because banks are legally forbidden from offering overdrafts to manufacturers","B":"Because an overdraft carries high daily interest and can be recalled on demand by the bank long before the factory generates enough cash flows to pay for itself","C":"Because using an overdraft turns the factory into a current asset","D":"Because an overdraft dilutes existing shareholders' voting shares"},"correctOption":"B","correctAnswer":"Because an overdraft carries high daily interest and can be recalled on demand by the bank long before the factory generates enough cash flows to pay for itself","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the 'matching principle' requires long-term assets to be funded by long-term finance so asset returns match debt repayment schedules.","distractor_reasons":{"A":"Incorrect because manufacturers routinely use overdrafts for short-term working capital.","B":"Option B is correct because the 'matching principle' requires long-term assets to be funded by long-term finance so asset returns match debt repayment schedules.","C":"Incorrect because a factory remains a non-current asset regardless of how it is funded.","D":"Incorrect because overdrafts are debt facilities, not equity shares."}}},{"id":"P1_U5_MCQ_886","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_886","question":"A business sells $50,000 of unpaid customer invoices to a 'debt factor', which advances 80% immediately ($40,000) and pays the remaining 20% later minus a 4% service fee ($2,000). What is the key financial cost of this arrangement?","options":{"A":"The business is banned from offering credit to any future customers","B":"The business must give 80% of its ordinary shares to the factoring company","C":"The business loses $2,000 of its revenue in fees, reducing its net profit margin in exchange for getting $40,000 cash immediately","D":"The business's non-current liabilities increase by $50,000"},"correctOption":"C","correctAnswer":"The business loses $2,000 of its revenue in fees, reducing its net profit margin in exchange for getting $40,000 cash immediately","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because factoring trades a percentage fee (lowering profitability) for immediate working capital liquidity.","distractor_reasons":{"A":"Incorrect because factoring specifically supports businesses that sell on trade credit.","B":"Incorrect because debt factoring does not transfer equity ownership.","C":"Option C is correct because factoring trades a percentage fee (lowering profitability) for immediate working capital liquidity.","D":"Incorrect because factoring converts trade receivables into cash rather than creating long-term debt."}}},{"id":"P1_U5_MCQ_887","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_887","question":"What is a distinct commercial risk of launching a public 'crowdfunding' campaign for an innovative new product design before securing patent protection?","options":{"A":"Crowdfunding platforms take 90% of all funds raised as commission","B":"Publicly revealing detailed product prototypes and marketing plans online allows established competitors to copy the unpatented idea rapidly","C":"Backers are legally allowed to seize the entrepreneur's personal home if the product ships one week late","D":"Crowdfunding automatically converts a sole trader into a public limited company"},"correctOption":"B","correctAnswer":"Publicly revealing detailed product prototypes and marketing plans online allows established competitors to copy the unpatented idea rapidly","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public online pitches expose unpatented innovations to imitation before the start-up has scaled up.","distractor_reasons":{"A":"Incorrect because platform fees are typically around 5%–10%, not 90%.","B":"Option B is correct because public online pitches expose unpatented innovations to imitation before the start-up has scaled up.","C":"Incorrect because reward backers do not hold property liens over the creator's personal home.","D":"Incorrect because crowdfunding does not automatically change legal business structure."}}},{"id":"P1_U5_MCQ_888","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_888","question":"Why do 'microfinance' institutions typically charge higher percentage interest rates than large commercial banks, even though they aim to help low-income entrepreneurs?","options":{"A":"Because microfinance providers are owned by stock-market speculators seeking monopoly profits","B":"Because microfinance loans last for 30 years without any repayments","C":"Because administering, monitoring, and collecting thousands of very small unsecured loans incurs high per-dollar operational costs and higher default risk","D":"Because governments require microfinance banks to charge minimum rates of 100%"},"correctOption":"C","correctAnswer":"Because administering, monitoring, and collecting thousands of very small unsecured loans incurs high per-dollar operational costs and higher default risk","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because processing and field-monitoring tiny loans without physical collateral requires intensive staff administration per dollar lent.","distractor_reasons":{"A":"Incorrect because many microfinance institutions are social enterprises or NGOs focused on financial inclusion.","B":"Incorrect because microfinance loans are typically short-term with frequent weekly or monthly instalments.","C":"Option C is correct because processing and field-monitoring tiny loans without physical collateral requires intensive staff administration per dollar lent.","D":"Incorrect because governments do not mandate 100% interest rates."}}},{"id":"P1_U5_MCQ_889","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_889","question":"What is a common drawback for a business applying for a 'government grant' to fund a new green-energy manufacturing line?","options":{"A":"The grant must be repaid with compound interest within six months","B":"The government takes 51% voting control of the board of directors","C":"Grants can only be spent on paying executive bonuses","D":"Application processes are slow and bureaucratic, and the business must meet strict eligibility conditions (such as minimum job creation or carbon targets) or risk having to repay the grant"},"correctOption":"D","correctAnswer":"Application processes are slow and bureaucratic, and the business must meet strict eligibility conditions (such as minimum job creation or carbon targets) or risk having to repay the grant","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because while grants are non-repayable when conditions are met, they carry strict compliance rules and lengthy approval timelines.","distractor_reasons":{"A":"Incorrect because grants do not require repayment if conditions are fulfilled.","B":"Incorrect because grants do not transfer corporate ownership to the state.","C":"Incorrect because grants are restricted to approved capital, training, or R&D purposes.","D":"Option D is correct because while grants are non-repayable when conditions are met, they carry strict compliance rules and lengthy approval timelines."}}},{"id":"P1_U5_MCQ_890","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_890","question":"What is the fundamental difference between 'leasing' a fleet of delivery vans and acquiring them through 'hire purchase'?","options":{"A":"Under leasing, the business never owns the vans (simply renting them), whereas under hire purchase, legal ownership transfers to the business once the final instalment is paid","B":"Under leasing, the business owns the vans immediately on Day 1, whereas under hire purchase, the vans are returned after one year","C":"Leasing is an internal source of finance, whereas hire purchase is equity share capital","D":"Leasing requires paying the full purchase price upfront in cash, whereas hire purchase requires zero payments"},"correctOption":"A","correctAnswer":"Under leasing, the business never owns the vans (simply renting them), whereas under hire purchase, legal ownership transfers to the business once the final instalment is paid","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing is a pure rental arrangement (ideal for avoiding obsolescence), while hire purchase is an instalment purchase ending in ownership.","distractor_reasons":{"A":"Option A is correct because leasing is a pure rental arrangement (ideal for avoiding obsolescence), while hire purchase is an instalment purchase ending in ownership.","B":"Incorrect because this reverses leasing and hire purchase.","C":"Incorrect because both are external asset-financing arrangements.","D":"Incorrect because both spread cash outflows over time rather than requiring 100% upfront cash."}}},{"id":"P1_U5_MCQ_891","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_891","question":"Why can a '$20,000 bank overdraft limit' sometimes be cheaper in total interest cost than a '$20,000 fixed-term bank loan' for a business with fluctuating seasonal cash needs?","options":{"A":"Because bank overdrafts always have a lower annual percentage interest rate than bank loans","B":"Because overdraft interest is calculated daily only on the exact negative balance actually used on each day, whereas loan interest is paid on the full borrowed principal even when cash sits idle","C":"Because banks never charge interest on overdrafts under $50,000","D":"Because overdraft interest is paid by the government"},"correctOption":"B","correctAnswer":"Because overdraft interest is calculated daily only on the exact negative balance actually used on each day, whereas loan interest is paid on the full borrowed principal even when cash sits idle","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because if a business only dips into its overdraft for 10 days a month, it pays interest only for those 10 days on the exact deficit.","distractor_reasons":{"A":"Incorrect because overdrafts carry a *higher* annual interest rate than secured term loans.","B":"Option B is correct because if a business only dips into its overdraft for 10 days a month, it pays interest only for those 10 days on the exact deficit.","C":"Incorrect because banks charge daily interest whenever an account is overdrawn.","D":"Incorrect because the business pays its own overdraft interest."}}},{"id":"P1_U5_MCQ_892","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_892","question":"A supplier offers '2% discount for immediate cash payment, or net 30 days'. Why does taking the full 30 days of 'trade credit' carry an implicit opportunity cost?","options":{"A":"Because the business must give up the 2% early-payment discount, paying a higher net price for the goods in exchange for keeping its cash for 30 days","B":"Because the supplier automatically cancels all future deliveries","C":"Because taking 30 days of trade credit increases the business's non-current liabilities","D":"Because the business must pay 20% bank interest to the supplier"},"correctOption":"A","correctAnswer":"Because the business must give up the 2% early-payment discount, paying a higher net price for the goods in exchange for keeping its cash for 30 days","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because although no explicit interest is billed during the 30-day window, forfeiting the 2% prompt-payment discount represents an implicit financing cost.","distractor_reasons":{"A":"Option A is correct because although no explicit interest is billed during the 30-day window, forfeiting the 2% prompt-payment discount represents an implicit financing cost.","B":"Incorrect because paying within the agreed 30-day term respects the contract.","C":"Incorrect because 30-day supplier invoices are current liabilities (trade payables).","D":"Incorrect because suppliers do not charge 20% interest within normal credit terms."}}},{"id":"P1_U5_MCQ_893","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_893","question":"Why is a 'partnership' legally unable to raise expansion finance by issuing shares on a public stock exchange?","options":{"A":"Because partnerships are always loss-making businesses","B":"Because stock exchanges only accept businesses with fewer than five employees","C":"Because only incorporated public limited companies (plcs) can issue shares to the general public; partnerships are unincorporated and have no share capital","D":"Because partners have limited liability"},"correctOption":"C","correctAnswer":"Because only incorporated public limited companies (plcs) can issue shares to the general public; partnerships are unincorporated and have no share capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because legal structure dictates eligibility for equity finance: only plcs can float shares publicly.","distractor_reasons":{"A":"Incorrect because many professional partnerships (law, accounting) are highly profitable.","B":"Incorrect because stock-market listed plcs are large enterprises.","C":"Option C is correct because legal structure dictates eligibility for equity finance: only plcs can float shares publicly.","D":"Incorrect because general partners have unlimited liability, and share issuance requires incorporation as a plc."}}},{"id":"P1_U5_MCQ_894","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_894","question":"An established company wants to raise a large sum to build a new factory, but the owners are determined not to give up any control of the business. Which factor affecting the choice of finance is this?","options":{"A":"The owners' wish to retain control","B":"The rate of interest charged on all loans","C":"The amount of profit retained in previous years only","D":"The level of demand for the product"},"correctOption":"A","correctAnswer":"The owners' wish to retain control","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the desire to keep control discourages a share issue and pushes the firm towards borrowing or retained profit.","distractor_reasons":{"A":"Option A is correct because the desire to keep control discourages a share issue and pushes the firm towards borrowing or retained profit.","B":"Incorrect because interest rates affect the cost of borrowing but the stated concern is retaining ownership and control.","C":"Incorrect because retained profit is a source of finance rather than a general factor about control of the business.","D":"Incorrect because product demand may justify the investment but does not determine who controls the company."}}},{"id":"P1_U5_MCQ_895","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_895","question":"Why is 'the amount of finance required' a decisive factor when choosing between a 'bank overdraft' and a 'public share issue'?","options":{"A":"A bank overdraft is suitable for small, temporary sums (e.g., $5,000), whereas the huge legal and underwriting fees of a public share issue only make financial sense when raising millions of dollars","B":"A bank overdraft can only be used for amounts above $10 million","C":"A public share issue is only allowed for raising less than $1,000","D":"Both sources cost the exact same amount in setup fees"},"correctOption":"A","correctAnswer":"A bank overdraft is suitable for small, temporary sums (e.g., $5,000), whereas the huge legal and underwriting fees of a public share issue only make financial sense when raising millions of dollars","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high fixed transaction costs make public equity issues uneconomic for small sums, while bank limits cap overdraft size.","distractor_reasons":{"A":"Option A is correct because high fixed transaction costs make public equity issues uneconomic for small sums, while bank limits cap overdraft size.","B":"Incorrect because overdrafts are small-to-medium short-term facilities.","C":"Incorrect because stock market flotations raise very large sums.","D":"Incorrect because an IPO costs millions in fees, whereas an overdraft has minimal arrangement fees."}}},{"id":"P1_U5_MCQ_896","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_896","question":"Why might a sole trader choose to admit a 'sleeping (silent) partner' rather than converting into a private limited company and selling 60% of the shares to outside investors?","options":{"A":"Because admitting a sleeping partner grants the sole trader limited liability","B":"Because a sleeping partner contributes capital and shares profits without taking part in day-to-day management, allowing the founder to keep operational control","C":"Because sleeping partners are forbidden from receiving any share of profits","D":"Because partnerships never pay income tax"},"correctOption":"B","correctAnswer":"Because a sleeping partner contributes capital and shares profits without taking part in day-to-day management, allowing the founder to keep operational control","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because selling 60% of voting shares surrenders majority control, whereas a sleeping partner injects equity capital while leaving management to the active partner.","distractor_reasons":{"A":"Incorrect because general partners still bear unlimited liability.","B":"Option B is correct because selling 60% of voting shares surrenders majority control, whereas a sleeping partner injects equity capital while leaving management to the active partner.","C":"Incorrect because sleeping partners receive an agreed share of business profits.","D":"Incorrect because partners pay personal income tax on their profit shares."}}},{"id":"P1_U5_MCQ_897","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_897","question":"What happens if a company defaults on repayments for a loan secured by 'collateral' (such as its freehold warehouse)?","options":{"A":"The bank must lend the company an additional $1 million interest-free","B":"The bank must convert the unpaid loan into free ordinary shares","C":"The warehouse is automatically transferred to the company's customers","D":"The bank has the legal right to seize and sell the pledged warehouse to recover the unpaid loan balance"},"correctOption":"D","correctAnswer":"The bank has the legal right to seize and sell the pledged warehouse to recover the unpaid loan balance","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because collateral protects the lender against default by granting a legal claim over specific assets.","distractor_reasons":{"A":"Incorrect because defaulting borrowers lose creditworthiness rather than receiving extra loans.","B":"Incorrect because secured debt gives the lender asset repossession rights, not compulsory equity conversion.","C":"Incorrect because customers have no claim on collateralized assets.","D":"Option D is correct because collateral protects the lender against default by granting a legal claim over specific assets."}}},{"id":"P1_U5_MCQ_898","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_898","question":"How does 'peer-to-peer (P2P) business lending' differ from traditional commercial bank lending?","options":{"A":"P2P lending connects small businesses directly with individual and institutional lenders through an online platform rather than borrowing from a traditional bank's balance sheet","B":"P2P lending requires zero repayment of the borrowed principal","C":"P2P lending is operated exclusively by government tax offices","D":"P2P lending is an internal source of finance"},"correctOption":"A","correctAnswer":"P2P lending connects small businesses directly with individual and institutional lenders through an online platform rather than borrowing from a traditional bank's balance sheet","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because P2P debt crowdfunding disintermediates traditional banks by pooling smaller loans from online investors.","distractor_reasons":{"A":"Option A is correct because P2P debt crowdfunding disintermediates traditional banks by pooling smaller loans from online investors.","B":"Incorrect because P2P loans must be repaid with interest.","C":"Incorrect because P2P platforms are private financial technology intermediaries.","D":"Incorrect because P2P loans come from outside investors."}}},{"id":"P1_U5_MCQ_899","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_899","question":"What is a potential shareholder concern when a public limited company relies heavily on 'retained profit' year after year to fund expansion?","options":{"A":"Retained profit increases the company's fixed interest expenses","B":"Retaining more profit reduces immediate cash dividends paid out to shareholders, which may dissatisfy investors seeking regular dividend income","C":"Retained profit dilutes existing shareholders' voting percentages","D":"Retained profit forces the company to sell its factories"},"correctOption":"B","correctAnswer":"Retaining more profit reduces immediate cash dividends paid out to shareholders, which may dissatisfy investors seeking regular dividend income","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Profit after tax is split between dividends and retained profit; retaining more means paying out less today.","distractor_reasons":{"A":"Incorrect because retained profit is internal equity with zero interest.","B":"Option B is correct because Profit after tax is split between dividends and retained profit; retaining more means paying out less today.","C":"Incorrect because retained profit does not issue any new shares.","D":"Incorrect because retained profit keeps funds inside the business for investment."}}},{"id":"P1_U5_MCQ_900","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_900","question":"A profitable, family-owned private limited company (Ltd) needs $400,000 to buy new CNC machinery lasting 8 years. The family refuses to share ownership control with outsiders and currently holds $150,000 in retained profit. Which financing combination is most suitable?","options":{"A":"Use $150,000 of retained profit plus a $250,000 medium-term commercial bank loan secured against the machinery/premises","B":"Use a $400,000 bank overdraft repayable on demand","C":"Float the company on the public stock exchange (IPO) to raise $400,000","D":"Use 30-day trade credit from office stationery suppliers"},"correctOption":"A","correctAnswer":"Use $150,000 of retained profit plus a $250,000 medium-term commercial bank loan secured against the machinery/premises","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because blending internal retained profit with a medium-term loan matches the 8-year asset life, avoids IPO costs, and preserves 100% family ownership.","distractor_reasons":{"A":"Option A is correct because blending internal retained profit with a medium-term loan matches the 8-year asset life, avoids IPO costs, and preserves 100% family ownership.","B":"Incorrect because funding an 8-year machine with a recallable overdraft creates severe liquidity risk.","C":"Incorrect because an IPO dilutes family control and costs far too much for a $400,000 need.","D":"Incorrect because stationery suppliers do not supply or finance $400,000 CNC machines."}}},{"id":"P1_U5_MCQ_901","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_901","question":"What is the primary purpose of constructing a monthly 'cash flow forecast'?","options":{"A":"To estimate the exact timing and amounts of future cash inflows and outflows so managers can spot potential cash deficits in advance and arrange finance","B":"To calculate the exact corporation tax owed for the previous financial year","C":"To record the historical depreciation of freehold buildings","D":"To replace the statement of financial position required by company law"},"correctOption":"A","correctAnswer":"To estimate the exact timing and amounts of future cash inflows and outflows so managers can spot potential cash deficits in advance and arrange finance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because forecasting monthly cash movements gives management early warning of liquidity shortfalls or idle cash surpluses.","distractor_reasons":{"A":"Option A is correct because forecasting monthly cash movements gives management early warning of liquidity shortfalls or idle cash surpluses.","B":"Incorrect because historical corporation tax is calculated from the statement of profit or loss.","C":"Incorrect because depreciation is a non-cash accounting charge excluded from cash flow forecasts.","D":"Incorrect because a cash flow forecast is an internal planning tool, not a replacement for statutory financial statements."}}},{"id":"P1_U5_MCQ_902","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_902","question":"A wholesaler forecasts $40,000 of total sales in March. Customers pay 25% immediately in cash and 75% on one month's trade credit. How much cash inflow from March sales will appear on the cash flow forecast in March and April respectively?","options":{"A":"$40,000 in March and $0 in April","B":"$10,000 in March and $30,000 in April","C":"$30,000 in March and $10,000 in April","D":"$0 in March and $40,000 in April"},"correctOption":"B","correctAnswer":"$10,000 in March and $30,000 in April","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 25% of $40,000 ($10,000) enters the bank immediately in March, while 75% ($30,000) is received one month later in April.","distractor_reasons":{"A":"Incorrect because only 25% is paid in cash during March.","B":"Option B is correct because 25% of $40,000 ($10,000) enters the bank immediately in March, while 75% ($30,000) is received one month later in April.","C":"Incorrect because this reverses the 25% cash and 75% credit portions.","D":"Incorrect because immediate cash sales generate $10,000 in March."}}},{"id":"P1_U5_MCQ_903","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_903","question":"In June, a business forecasts an opening cash balance of $15,000, total cash inflows of $62,000, and total cash outflows of $71,000. What are June's 'net cash flow' and 'closing cash balance'?","options":{"A":"Net cash flow: +$9,000; Closing cash balance: $24,000","B":"Net cash flow: -$9,000; Closing cash balance: -$9,000","C":"Net cash flow: -$9,000; Closing cash balance: $6,000","D":"Net cash flow: -$71,000; Closing cash balance: $6,000"},"correctOption":"C","correctAnswer":"Net cash flow: -$9,000; Closing cash balance: $6,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Net cash flow = $62,000 - $71,000 = -$9,000, and Closing cash balance = $15,000 + (-$9,000) = $6,000.","distractor_reasons":{"A":"Incorrect because outflows ($71,000) exceed inflows ($62,000), resulting in a negative net cash flow.","B":"Incorrect because it forgets to add the $15,000 opening cash balance to find the closing balance.","C":"Option C is correct because Net cash flow = $62,000 - $71,000 = -$9,000, and Closing cash balance = $15,000 + (-$9,000) = $6,000.","D":"Incorrect because -$71,000 is total outflows, not net cash flow."}}},{"id":"P1_U5_MCQ_904","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_904","question":"A start-up ends January with a closing cash balance of -$4,500 (an overdraft). In February, it forecasts cash inflows of $30,000 and cash outflows of $22,000. What is February's closing cash balance?","options":{"A":"+$8,000","B":"+$12,500","C":"-$12,500","D":"+$3,500"},"correctOption":"D","correctAnswer":"+$3,500","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because January's closing balance (-$4,500) becomes February's opening balance; adding February's net cash flow of +$8,000 ($30,000 - $22,000) yields +$3,500.","distractor_reasons":{"A":"Incorrect because +$8,000 is February's net cash flow before clearing the -$4,500 opening overdraft.","B":"Incorrect because it adds $4,500 instead of subtracting the -$4,500 opening overdraft.","C":"Incorrect because February has a positive net cash flow (+$8,000) that eliminates the overdraft.","D":"Option D is correct because January's closing balance (-$4,500) becomes February's opening balance; adding February's net cash flow of +$8,000 ($30,000 - $22,000) yields +$3,500."}}},{"id":"P1_U5_MCQ_905","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_905","question":"In October, a business has an opening cash balance of $8,000, total cash inflows of $25,000, and a closing cash balance of $5,000. What were October's 'total cash outflows'?","options":{"A":"$3,000","B":"$22,000","C":"$33,000","D":"$28,000"},"correctOption":"D","correctAnswer":"$28,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the cash balance fell by $3,000 (from $8,000 to $5,000), meaning net cash flow was -$3,000, so Outflows = $25,000 + $3,000 = $28,000.","distractor_reasons":{"A":"Incorrect because $3,000 is the net cash deficit, not total cash outflows.","B":"Incorrect because $22,000 outflows would leave a closing balance of $11,000 ($8,000 + $25,000 - $22,000).","C":"Incorrect because $33,000 is Opening balance + Inflows (which would leave $0 closing balance).","D":"Option D is correct because the cash balance fell by $3,000 (from $8,000 to $5,000), meaning net cash flow was -$3,000, so Outflows = $25,000 + $3,000 = $28,000."}}},{"id":"P1_U5_MCQ_906","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_906","question":"Why is the annual 'depreciation charge' on machinery completely omitted from a cash flow forecast?","options":{"A":"Because machinery never loses value over time","B":"Because depreciation is a non-cash accounting adjustment rather than money physically leaving the bank account each month","C":"Because depreciation is recorded as a cash inflow","D":"Because limited companies are forbidden from calculating depreciation"},"correctOption":"B","correctAnswer":"Because depreciation is a non-cash accounting adjustment rather than money physically leaving the bank account each month","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the actual cash outflow occurred when the machine was paid for; subsequent depreciation entries involve zero cash movement.","distractor_reasons":{"A":"Incorrect because machinery wears out and loses value over its useful life.","B":"Option B is correct because the actual cash outflow occurred when the machine was paid for; subsequent depreciation entries involve zero cash movement.","C":"Incorrect because depreciation never brings cash into the business.","D":"Incorrect because companies must record depreciation on their statement of profit or loss."}}},{"id":"P1_U5_MCQ_907","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_907","question":"A printing company buys a $50,000 digital press in cash in April, expecting it to last 5 years ($10,000 annual depreciation). How does this purchase appear on April's cash flow forecast?","options":{"A":"As a $10,000 cash outflow in April","B":"As an $833 monthly cash outflow starting in April","C":"As a $50,000 cash outflow in April when the payment leaves the bank account","D":"It is omitted because non-current assets never appear on cash flow forecasts"},"correctOption":"C","correctAnswer":"As a $50,000 cash outflow in April when the payment leaves the bank account","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash flow forecasts record the full $50,000 cash payment in the exact month cash leaves the bank.","distractor_reasons":{"A":"Incorrect because $10,000 is annual depreciation for the income statement, not the cash paid in April.","B":"Incorrect because $833 is monthly depreciation, not the cash outflow.","C":"Option C is correct because cash flow forecasts record the full $50,000 cash payment in the exact month cash leaves the bank.","D":"Incorrect because capital expenditure paid in cash is a major cash outflow."}}},{"id":"P1_U5_MCQ_908","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_908","question":"Why do 'seasonal businesses' (such as a beach resort or a firework manufacturer) rely heavily on cash flow forecasts?","options":{"A":"Because seasonal businesses receive identical cash inflows every single week of the year","B":"Because seasonal businesses never have any fixed overhead costs","C":"Because seasonal businesses are exempt from paying bank overdraft interest","D":"Because they incur months of heavy cash outflows for wages, maintenance, and stock buildup during off-peak seasons before peak tourist or holiday cash inflows arrive"},"correctOption":"D","correctAnswer":"Because they incur months of heavy cash outflows for wages, maintenance, and stock buildup during off-peak seasons before peak tourist or holiday cash inflows arrive","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because seasonal mismatches between steady outflows and concentrated inflows require pre-arranged overdrafts or cash reserves.","distractor_reasons":{"A":"Incorrect because seasonal demand fluctuates sharply across the year.","B":"Incorrect because rent, insurance, and core staff salaries continue year-round.","C":"Incorrect because seasonal firms pay commercial overdraft rates.","D":"Option D is correct because seasonal mismatches between steady outflows and concentrated inflows require pre-arranged overdrafts or cash reserves."}}},{"id":"P1_U5_MCQ_909","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_909","question":"What is 'overtrading' in business finance?","options":{"A":"Selling products below cost price to drive competitors out of the market","B":"Expanding sales and production volume too rapidly without sufficient working capital, causing cash outflows for materials and wages to outstrip delayed receipts from credit customers","C":"Holding excessive idle cash in a bank deposit account","D":"Paying off all non-current liabilities ahead of schedule"},"correctOption":"B","correctAnswer":"Expanding sales and production volume too rapidly without sufficient working capital, causing cash outflows for materials and wages to outstrip delayed receipts from credit customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because overtrading occurs when fast growth drains liquid cash faster than credit customers pay, risking insolvency despite strong order books.","distractor_reasons":{"A":"Incorrect because selling below cost is predatory pricing, not overtrading.","B":"Option B is correct because overtrading occurs when fast growth drains liquid cash faster than credit customers pay, risking insolvency despite strong order books.","C":"Incorrect because overtrading is characterized by a severe *shortage* of liquid cash.","D":"Incorrect because overtrading strains short-term working capital rather than early debt retirement."}}},{"id":"P1_U5_MCQ_910","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_910","question":"When an entrepreneur applies for a $30,000 overdraft limit, what specific information does the bank manager look for inside the 'cash flow forecast'?","options":{"A":"The exact market value of the entrepreneur's personal jewellery","B":"The company's historical gross profit margin from five years ago","C":"The maximum negative closing cash balance (to verify $30,000 is enough) and the specific future months when positive net cash flows will bring the account back into credit","D":"The names and home addresses of all retail customers"},"correctOption":"C","correctAnswer":"The maximum negative closing cash balance (to verify $30,000 is enough) and the specific future months when positive net cash flows will bring the account back into credit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because banks check both peak borrowing need (to prevent under-funding) and the borrower's capacity to clear the overdraft.","distractor_reasons":{"A":"Incorrect because personal items are not listed in a business cash flow forecast.","B":"Incorrect because cash flow forecasts are forward-looking cash schedules, not historical income statements.","C":"Option C is correct because banks check both peak borrowing need (to prevent under-funding) and the borrower's capacity to clear the overdraft.","D":"Incorrect because forecasts summarize aggregate monthly inflows rather than customer directories."}}},{"id":"P1_U5_MCQ_911","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_911","question":"If a business negotiates to extend its 'supplier credit period' from 30 days to 60 days to relieve a forecast cash deficit, what is a potential negative consequence?","options":{"A":"The business's cash inflows will immediately drop to zero","B":"The business will have to pay higher corporation tax immediately","C":"The business's non-current assets will lose half their value","D":"Suppliers may refuse the extension, withdraw early-payment discounts, raise prices, or prioritize rival buyers who pay faster"},"correctOption":"D","correctAnswer":"Suppliers may refuse the extension, withdraw early-payment discounts, raise prices, or prioritize rival buyers who pay faster","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because stretching trade payables improves short-term cash flow only if suppliers agree without damaging supply reliability or pricing.","distractor_reasons":{"A":"Incorrect because supplier credit affects outflows, not customer inflows.","B":"Incorrect because extending payable terms does not increase corporation tax.","C":"Incorrect because supplier terms have no effect on non-current asset values.","D":"Option D is correct because stretching trade payables improves short-term cash flow only if suppliers agree without damaging supply reliability or pricing."}}},{"id":"P1_U5_MCQ_912","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_912","question":"Which action directly speeds up 'cash inflows' to resolve a temporary cash shortage without taking on new debt?","options":{"A":"Increasing cash dividends paid to shareholders","B":"Buying extra raw materials in bulk for cash","C":"Chasing overdue trade receivables more aggressively or using a debt factoring agency to unlock cash from unpaid invoices","D":"Giving credit customers an extra 60 days to pay their bills"},"correctOption":"C","correctAnswer":"Chasing overdue trade receivables more aggressively or using a debt factoring agency to unlock cash from unpaid invoices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because accelerating receivable collections brings cash into the bank faster without borrowing.","distractor_reasons":{"A":"Incorrect because paying higher dividends increases cash outflows.","B":"Incorrect because buying bulk stock increases immediate cash outflows.","C":"Option C is correct because accelerating receivable collections brings cash into the bank faster without borrowing.","D":"Incorrect because lengthening customer credit delays cash inflows further."}}},{"id":"P1_U5_MCQ_913","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_913","question":"Why is 'postponing planned non-essential capital expenditure' (such as delaying the upgrade of office computers or company cars) an effective short-term cash flow remedy?","options":{"A":"Because it converts current liabilities into shareholders' equity","B":"Because it doubles monthly sales revenue immediately","C":"Because it eliminates a large lump-sum cash outflow during the deficit month without disrupting existing daily production","D":"Because it forces customers to pay cash in advance"},"correctOption":"C","correctAnswer":"Because it eliminates a large lump-sum cash outflow during the deficit month without disrupting existing daily production","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because deferring discretionary equipment upgrades preserves vital cash until liquidity improves.","distractor_reasons":{"A":"Incorrect because postponing spending does not alter liabilities or equity.","B":"Incorrect because delaying office upgrades does not double sales revenue.","C":"Option C is correct because deferring discretionary equipment upgrades preserves vital cash until liquidity improves.","D":"Incorrect because capital spending decisions do not change customer payment terms."}}},{"id":"P1_U5_MCQ_914","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_914","question":"How does running a short-term 'clearance sale' on slow-moving warehouse inventory help a business facing a cash flow crunch?","options":{"A":"It increases the book value of non-current assets","B":"It converts stagnant stock into immediate cash inflows and reduces storage costs, even though selling at discounted prices lowers gross profit margin","C":"It increases trade payables owed to suppliers","D":"It eliminates all fixed overhead costs for the rest of the year"},"correctOption":"B","correctAnswer":"It converts stagnant stock into immediate cash inflows and reduces storage costs, even though selling at discounted prices lowers gross profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because during a liquidity emergency, generating immediate cash from excess inventory takes priority over maximizing profit margin.","distractor_reasons":{"A":"Incorrect because clearance sales sell current asset inventory, not non-current assets.","B":"Option B is correct because during a liquidity emergency, generating immediate cash from excess inventory takes priority over maximizing profit margin.","C":"Incorrect because selling existing stock does not increase supplier debts.","D":"Incorrect because fixed overheads still continue."}}},{"id":"P1_U5_MCQ_915","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_915","question":"Why is 'delaying payment of employee wages' NOT a viable strategy for solving a forecast cash flow deficit?","options":{"A":"Because employee wages are never included as cash outflows","B":"Because delaying wages is a breach of employment contracts and labor laws that destroys morale, triggers strikes or resignations, and halts operations","C":"Because delaying wages automatically increases corporation tax rates","D":"Because employee wages are paid by the company's customers directly"},"correctOption":"B","correctAnswer":"Because delaying wages is a breach of employment contracts and labor laws that destroys morale, triggers strikes or resignations, and halts operations","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because payroll is a legally binding priority obligation; non-payment rapidly destroys the business's workforce and reputation.","distractor_reasons":{"A":"Incorrect because wages are one of the largest regular cash outflows.","B":"Option B is correct because payroll is a legally binding priority obligation; non-payment rapidly destroys the business's workforce and reputation.","C":"Incorrect because tax rates are set by statute, not wage timing.","D":"Incorrect because the employer pays wages out of its own bank account."}}},{"id":"P1_U5_MCQ_916","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_916","question":"A company receives a $100,000 long-term bank loan into its current account in July. What is the immediate effect on July's 'cash flow' and July's 'operating profit'?","options":{"A":"Cash inflow increases by $100,000, while operating profit is completely unchanged","B":"Both cash inflow and operating profit increase by $100,000","C":"Cash inflow is unchanged, while operating profit increases by $100,000","D":"Cash outflow increases by $100,000, while operating profit falls by $100,000"},"correctOption":"A","correctAnswer":"Cash inflow increases by $100,000, while operating profit is completely unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because borrowing money brings cash into the bank (+cash inflow) and creates a loan liability, which is not trading revenue.","distractor_reasons":{"A":"Option A is correct because borrowing money brings cash into the bank (+cash inflow) and creates a loan liability, which is not trading revenue.","B":"Incorrect because loan proceeds are debt financing, not earned profit.","C":"Incorrect because receiving loan funds directly increases cash inflows.","D":"Incorrect because receiving a loan brings cash *in*, rather than sending cash out."}}},{"id":"P1_U5_MCQ_917","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_917","question":"A retailer buys $18,000 of inventory on two months' trade credit in May. In which months does this purchase affect the retailer's 'cash flow forecast'?","options":{"A":"$18,000 cash outflow in May","B":"$9,000 cash outflow in May and $9,000 in June","C":"$0 cash outflow in May and June, and $18,000 cash outflow in July when the supplier invoice is paid","D":"$18,000 cash inflow in July"},"correctOption":"C","correctAnswer":"$0 cash outflow in May and June, and $18,000 cash outflow in July when the supplier invoice is paid","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash flow forecasts record cash movements only when money actually leaves the bank account (two months after May = July).","distractor_reasons":{"A":"Incorrect because the goods were bought on 2-month credit rather than cash.","B":"Incorrect because the payment is due in full after two months (July), not split.","C":"Option C is correct because cash flow forecasts record cash movements only when money actually leaves the bank account (two months after May = July).","D":"Incorrect because paying a supplier is a cash outflow, not an inflow."}}},{"id":"P1_U5_MCQ_918","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_918","question":"How does comparing 'actual monthly cash flows' against 'forecast monthly cash flows' improve financial control?","options":{"A":"It automatically cancels all supplier debts if actual outflows are higher than forecast","B":"It enables managers to spot adverse variances early (such as slower customer collections or rising utility bills) and take corrective action before cash runs out","C":"It eliminates the need to prepare an annual statement of profit or loss","D":"It guarantees that next month's sales will double"},"correctOption":"B","correctAnswer":"It enables managers to spot adverse variances early (such as slower customer collections or rising utility bills) and take corrective action before cash runs out","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because monitoring forecast vs actual cash variances turns a static document into an active management control tool.","distractor_reasons":{"A":"Incorrect because legal supplier debts remain payable.","B":"Option B is correct because monitoring forecast vs actual cash variances turns a static document into an active management control tool.","C":"Incorrect because statutory financial statements are still required.","D":"Incorrect because variance monitoring diagnoses problems rather than guaranteeing sales growth."}}},{"id":"P1_U5_MCQ_919","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_919","question":"Why can external macroeconomic changes (such as an unexpected central bank interest rate hike or currency depreciation) make a 12-month cash flow forecast inaccurate?","options":{"A":"Because external shocks increase variable loan interest payments and imported raw material outflows above the figures assumed when the forecast was written","B":"Because external shocks change historical opening cash balances from last year","C":"Because businesses are forbidden from updating cash flow forecasts during the year","D":"Because external shocks eliminate all current liabilities"},"correctOption":"A","correctAnswer":"Because external shocks increase variable loan interest payments and imported raw material outflows above the figures assumed when the forecast was written","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash flow forecasts rely on assumptions about external prices and rates that can shift unexpectedly.","distractor_reasons":{"A":"Option A is correct because cash flow forecasts rely on assumptions about external prices and rates that can shift unexpectedly.","B":"Incorrect because past opening balances are fixed historical facts.","C":"Incorrect because managers should prepare rolling updates whenever assumptions change.","D":"Incorrect because macroeconomic shifts do not erase existing debts."}}},{"id":"P1_U5_MCQ_920","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_920","question":"What behavioral bias often causes new entrepreneurs to produce overly optimistic 'cash flow forecasts'?","options":{"A":"Overestimating how fast customers will buy and pay while underestimating unexpected start-up delays and overhead costs","B":"Assuming sales revenue will be zero for the first five years","C":"Multiplying all expected expenses by ten","D":"Recording share capital as a monthly cash outflow"},"correctOption":"A","correctAnswer":"Overestimating how fast customers will buy and pay while underestimating unexpected start-up delays and overhead costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneur optimism bias frequently leads to over-projected early inflows and under-budgeted costs, causing unexpected cash shortfalls.","distractor_reasons":{"A":"Option A is correct because entrepreneur optimism bias frequently leads to over-projected early inflows and under-budgeted costs, causing unexpected cash shortfalls.","B":"Incorrect because over-optimism exaggerates sales rather than assuming zero sales.","C":"Incorrect because over-optimistic forecasts underestimate rather than exaggerate expenses.","D":"Incorrect because share capital injected is a cash inflow."}}},{"id":"P1_U5_MCQ_921","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_921","question":"What is the 'working capital cycle' in a manufacturing business?","options":{"A":"The 25-year lifespan of a freehold factory building","B":"The continuous time lag between paying cash for raw materials, manufacturing and storing finished goods, selling on credit, and finally collecting cash from customers","C":"The annual election of company directors at the AGM","D":"The process of issuing new shares on a stock exchange"},"correctOption":"B","correctAnswer":"The continuous time lag between paying cash for raw materials, manufacturing and storing finished goods, selling on credit, and finally collecting cash from customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the shorter the working capital cycle, the faster cash returns to the bank and the smaller the risk of liquidity shortages.","distractor_reasons":{"A":"Incorrect because buildings are long-term non-current assets.","B":"Option B is correct because the shorter the working capital cycle, the faster cash returns to the bank and the smaller the risk of liquidity shortages.","C":"Incorrect because director elections relate to corporate governance, not cash cycles.","D":"Incorrect because share flotation is long-term equity financing."}}},{"id":"P1_U5_MCQ_922","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_922","question":"How does choosing to 'lease' delivery vans instead of buying them outright for cash improve a start-up's early cash flow forecast?","options":{"A":"It eliminates all cash outflows for vehicles permanently","B":"It turns vehicle rental payments into cash inflows","C":"It avoids a massive initial cash outflow in Month 1, replacing it with smaller, predictable monthly lease outflows that preserve working capital","D":"It increases the start-up's non-current assets on Day 1"},"correctOption":"C","correctAnswer":"It avoids a massive initial cash outflow in Month 1, replacing it with smaller, predictable monthly lease outflows that preserve working capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because spreading vehicle costs via leasing prevents draining the start-up's cash cushion upfront.","distractor_reasons":{"A":"Incorrect because monthly lease rentals are still cash outflows.","B":"Incorrect because lease payments leave the bank as outflows.","C":"Option C is correct because spreading vehicle costs via leasing prevents draining the start-up's cash cushion upfront.","D":"Incorrect because leased assets remain owned by the leasing company."}}},{"id":"P1_U5_MCQ_923","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_923","question":"How is 'corporation tax' recorded on a limited company's monthly cash flow forecast?","options":{"A":"It is omitted completely because taxes are non-cash expenses","B":"It is recorded as a cash inflow from the government","C":"It is deducted from gross profit every week","D":"It is recorded as a cash outflow in the specific month when the tax payment actually leaves the company's bank account"},"correctOption":"D","correctAnswer":"It is recorded as a cash outflow in the specific month when the tax payment actually leaves the company's bank account","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because tax payments represent real cash outflows in the month remitted to tax authorities.","distractor_reasons":{"A":"Incorrect because taxes are paid in cash.","B":"Incorrect because profitable companies pay tax *out* to the government.","C":"Incorrect because cash flow forecasts track monthly cash movements, not weekly gross profit.","D":"Option D is correct because tax payments represent real cash outflows in the month remitted to tax authorities."}}},{"id":"P1_U5_MCQ_924","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_924","question":"When a company makes a $2,500 monthly bank loan payment consisting of $1,800 principal repayment and $700 interest, how much appears as a 'cash outflow' on the cash flow forecast?","options":{"A":"The full $2,500 payment, because the entire $2,500 leaves the bank account in cash","B":"Only the $700 interest portion","C":"Only the $1,800 principal portion","D":"$0, because bank loans are excluded from cash flow forecasts"},"correctOption":"A","correctAnswer":"The full $2,500 payment, because the entire $2,500 leaves the bank account in cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because both principal repayment and interest leave the bank account in cash (whereas only the $700 interest is an expense on the income statement).","distractor_reasons":{"A":"Option A is correct because both principal repayment and interest leave the bank account in cash (whereas only the $700 interest is an expense on the income statement).","B":"Incorrect because the $1,800 principal repayment also leaves the bank in cash.","C":"Incorrect because the $700 interest charge also leaves the bank in cash.","D":"Incorrect because all debt service payments are cash outflows."}}},{"id":"P1_U5_MCQ_925","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_925","question":"Which scenario best illustrates how a profitable company can still collapse due to 'cash flow insolvency'?","options":{"A":"A company sells all goods for immediate cash and keeps low overheads","B":"A construction company wins huge profitable contracts on 90-day customer credit, spends all its cash upfront on materials and wages, and cannot pay its own overdue bills before customer payments arrive","C":"A software firm holds $5 million in cash and has zero debt","D":"A retailer sells inventory faster than its 60-day supplier credit period"},"correctOption":"B","correctAnswer":"A construction company wins huge profitable contracts on 90-day customer credit, spends all its cash upfront on materials and wages, and cannot pay its own overdue bills before customer payments arrive","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profits tied up in uncollected trade receivables cannot pay immediate wages and supplier bills, triggering insolvency.","distractor_reasons":{"A":"Incorrect because immediate cash sales and low overheads produce strong cash flow.","B":"Option B is correct because profits tied up in uncollected trade receivables cannot pay immediate wages and supplier bills, triggering insolvency.","C":"Incorrect because large cash reserves and zero debt ensure high solvency.","D":"Incorrect because collecting cash from buyers before paying suppliers generates positive cash flow."}}},{"id":"P1_U5_MCQ_926","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_926","question":"A clothing retailer starts the year with opening inventory worth $14,000, buys $86,000 of new stock during the year, and holds $18,000 of closing inventory at year-end. What is its 'cost of sales'?","options":{"A":"$100,000","B":"$82,000","C":"$90,000","D":"$118,000"},"correctOption":"B","correctAnswer":"$82,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Cost of sales = Opening inventory ($14,000) + Purchases ($86,000) - Closing inventory ($18,000) = $82,000.","distractor_reasons":{"A":"Incorrect because $100,000 forgets to subtract the $18,000 unsold closing inventory.","B":"Option B is correct because Cost of sales = Opening inventory ($14,000) + Purchases ($86,000) - Closing inventory ($18,000) = $82,000.","C":"Incorrect because $90,000 adds closing inventory ($18,000) and subtracts opening inventory ($14,000).","D":"Incorrect because $118,000 adds all three figures together instead of subtracting closing inventory."}}},{"id":"P1_U5_MCQ_927","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_927","question":"A furniture maker records annual sales revenue of $210,000, cost of sales of $135,000, and overhead expenses of $42,000. What is its 'gross profit'?","options":{"A":"$33,000","B":"$93,000","C":"$75,000","D":"$168,000"},"correctOption":"C","correctAnswer":"$75,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = Revenue ($210,000) - Cost of sales ($135,000) = $75,000 (overheads are deducted later to find operating profit).","distractor_reasons":{"A":"Incorrect because $33,000 is operating profit ($75,000 - $42,000), not gross profit.","B":"Incorrect because $93,000 subtracts overheads instead of cost of sales.","C":"Option C is correct because Gross profit = Revenue ($210,000) - Cost of sales ($135,000) = $75,000 (overheads are deducted later to find operating profit).","D":"Incorrect because $168,000 subtracts overheads from revenue."}}},{"id":"P1_U5_MCQ_928","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_928","question":"A logistics company achieves a gross profit of $90,000 and incurs indirect overhead expenses of $54,000 during the year. What is its 'operating profit'?","options":{"A":"$144,000","B":"$90,000","C":"$54,000","D":"$36,000"},"correctOption":"D","correctAnswer":"$36,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Operating profit = Gross profit ($90,000) - Overhead expenses ($54,000) = $36,000.","distractor_reasons":{"A":"Incorrect because overhead expenses must be subtracted from gross profit, not added.","B":"Incorrect because $90,000 is gross profit before deducting overheads.","C":"Incorrect because $54,000 is the overhead expense figure.","D":"Option D is correct because Operating profit = Gross profit ($90,000) - Overhead expenses ($54,000) = $36,000."}}},{"id":"P1_U5_MCQ_929","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_929","question":"A limited company reports operating profit of $50,000, loan interest of $6,000, a corporation tax rate of 25% on profit before tax, and dividends paid of $13,000. What is its 'retained profit' for the year?","options":{"A":"$20,000","B":"$33,000","C":"$44,000","D":"$31,000"},"correctOption":"A","correctAnswer":"$20,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Profit before tax = $50,000 - $6,000 = $44,000; Tax (25% of $44,000) = $11,000; Profit after tax = $33,000; Retained profit = $33,000 - $13,000 = $20,000.","distractor_reasons":{"A":"Option A is correct because Profit before tax = $50,000 - $6,000 = $44,000; Tax (25% of $44,000) = $11,000; Profit after tax = $33,000; Retained profit = $33,000 - $13,000 = $20,000.","B":"Incorrect because $33,000 is profit after tax before deducting the $13,000 dividends.","C":"Incorrect because $44,000 is profit before tax.","D":"Incorrect because $31,000 forgets to deduct the $11,000 corporation tax."}}},{"id":"P1_U5_MCQ_930","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_930","question":"If a business's cost of sales is $64,000 and its gross profit is $36,000, what was its 'sales revenue'?","options":{"A":"$28,000","B":"$100,000","C":"$64,000","D":"$36,000"},"correctOption":"B","correctAnswer":"$100,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Revenue - Cost of sales = Gross profit, so Revenue = Cost of sales ($64,000) + Gross profit ($36,000) = $100,000.","distractor_reasons":{"A":"Incorrect because subtracting gross profit from cost of sales gives $28,000 instead of total revenue.","B":"Option B is correct because Revenue - Cost of sales = Gross profit, so Revenue = Cost of sales ($64,000) + Gross profit ($36,000) = $100,000.","C":"Incorrect because $64,000 is cost of sales alone.","D":"Incorrect because $36,000 is gross profit alone."}}},{"id":"P1_U5_MCQ_931","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_931","question":"A trader had opening inventory of $10,000, made purchases of $55,000 during the year, and recorded a cost of sales of $52,000. What was the value of 'closing inventory' at year-end?","options":{"A":"$7,000","B":"$3,000","C":"$13,000","D":"$65,000"},"correctOption":"C","correctAnswer":"$13,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Goods available for sale = $10,000 + $55,000 = $65,000; subtracting Cost of sales ($52,000) leaves Closing inventory of $13,000.","distractor_reasons":{"A":"Incorrect because $7,000 subtracts opening inventory instead of adding it.","B":"Incorrect because $3,000 ignores the $10,000 opening inventory.","C":"Option C is correct because Goods available for sale = $10,000 + $55,000 = $65,000; subtracting Cost of sales ($52,000) leaves Closing inventory of $13,000.","D":"Incorrect because $65,000 is total goods available for sale before deducting cost of sales."}}},{"id":"P1_U5_MCQ_932","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_932","question":"If an accounting error causes a business to 'overvalue its closing inventory' at year-end, how does this distort its statement of profit or loss for that year?","options":{"A":"Sales revenue is reduced by the amount of closing inventory","B":"Cost of sales is overstated, which artificially reduces gross profit","C":"Cost of sales is understated, which artificially inflates both gross profit and operating profit","D":"It has zero effect on gross profit or operating profit"},"correctOption":"C","correctAnswer":"Cost of sales is understated, which artificially inflates both gross profit and operating profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Closing inventory is subtracted in Cost of sales; subtracting a larger number lowers Cost of sales and raises reported profit.","distractor_reasons":{"A":"Incorrect because inventory valuation affects cost of sales, not sales revenue.","B":"Incorrect because a higher closing inventory reduces rather than increases cost of sales.","C":"Option C is correct because Closing inventory is subtracted in Cost of sales; subtracting a larger number lowers Cost of sales and raises reported profit.","D":"Incorrect because closing inventory directly enters the cost of sales calculation."}}},{"id":"P1_U5_MCQ_933","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_933","question":"How are 'carriage inwards' (delivery charges paid to bring purchased raw materials into the factory) treated differently from 'carriage outwards' (delivery charges to ship finished goods to customers)?","options":{"A":"Both are added to sales revenue","B":"Carriage inwards is included in cost of sales (reducing gross profit), whereas carriage outwards is recorded as a distribution overhead expense below gross profit","C":"Carriage inwards is a non-current asset, whereas carriage outwards is a current liability","D":"Carriage inwards is deducted after tax, whereas carriage outwards is deducted from revenue"},"correctOption":"B","correctAnswer":"Carriage inwards is included in cost of sales (reducing gross profit), whereas carriage outwards is recorded as a distribution overhead expense below gross profit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inward freight is part of acquiring inventory for production/resale (cost of sales), while outward delivery is a selling/distribution overhead.","distractor_reasons":{"A":"Incorrect because both are business costs, not revenue.","B":"Option B is correct because inward freight is part of acquiring inventory for production/resale (cost of sales), while outward delivery is a selling/distribution overhead.","C":"Incorrect because delivery charges are operating costs, not balance sheet assets or liabilities.","D":"Incorrect because both are deducted before operating profit."}}},{"id":"P1_U5_MCQ_934","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_934","question":"When a retailer returns damaged inventory back to its wholesale supplier ('purchase returns'), how is this recorded when calculating 'cost of sales'?","options":{"A":"It is added to sales revenue","B":"It is added to purchases, increasing cost of sales","C":"It is subtracted from purchases to show net purchases actually kept by the business","D":"It is recorded under overhead expenses"},"correctOption":"C","correctAnswer":"It is subtracted from purchases to show net purchases actually kept by the business","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because returning goods to suppliers cancels that purchase cost, lowering net purchases and cost of sales.","distractor_reasons":{"A":"Incorrect because returning stock to a supplier is not a sale to a customer.","B":"Incorrect because purchase returns reduce rather than increase net purchases.","C":"Option C is correct because returning goods to suppliers cancels that purchase cost, lowering net purchases and cost of sales.","D":"Incorrect because purchase returns adjust purchases inside cost of sales."}}},{"id":"P1_U5_MCQ_935","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_935","question":"In a commercial bakery, which pair of costs belongs inside 'cost of sales' rather than 'overhead expenses'?","options":{"A":"High-street retail shop rent and local radio advertising","B":"Accountant's annual audit fee and head-office telephone bills","C":"Flour, yeast, sugar, and piece-rate wages of bakers directly making bread","D":"Delivery van insurance and managing director's fixed annual salary"},"correctOption":"C","correctAnswer":"Flour, yeast, sugar, and piece-rate wages of bakers directly making bread","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because direct ingredients and direct production labor vary with output and form cost of sales.","distractor_reasons":{"A":"Incorrect because shop rent and advertising are indirect overhead expenses.","B":"Incorrect because audit fees and office phone bills are administrative overheads.","C":"Option C is correct because direct ingredients and direct production labor vary with output and form cost of sales.","D":"Incorrect because vehicle insurance and executive salaries are fixed indirect overheads."}}},{"id":"P1_U5_MCQ_936","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_936","question":"If a company switches to a cheaper commercial electricity supplier and saves $15,000 per year on head-office lighting and heating, what happens on its statement of profit or loss?","options":{"A":"Gross profit stays unchanged, while overhead expenses fall by $15,000 and operating profit rises by $15,000","B":"Gross profit rises by $15,000, while operating profit stays unchanged","C":"Sales revenue rises by $15,000","D":"Cost of sales falls by $15,000"},"correctOption":"A","correctAnswer":"Gross profit stays unchanged, while overhead expenses fall by $15,000 and operating profit rises by $15,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because head-office electricity is an indirect overhead deducted *after* gross profit, so saving on overheads leaves gross profit unaffected while raising operating profit.","distractor_reasons":{"A":"Option A is correct because head-office electricity is an indirect overhead deducted *after* gross profit, so saving on overheads leaves gross profit unaffected while raising operating profit.","B":"Incorrect because gross profit is calculated before deducting office overheads.","C":"Incorrect because lower utility bills do not increase sales revenue.","D":"Incorrect because head-office utilities are overheads, not direct cost of sales."}}},{"id":"P1_U5_MCQ_937","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_937","question":"If a manufacturer negotiates a 10% bulk discount on direct raw materials while keeping selling prices and overheads constant, how does this affect its statement of profit or loss?","options":{"A":"Overhead expenses increase by 10%","B":"Gross profit falls, while operating profit rises","C":"Only retained profit changes, while gross profit and operating profit stay identical","D":"Cost of sales falls, causing BOTH gross profit and operating profit to increase"},"correctOption":"D","correctAnswer":"Cost of sales falls, causing BOTH gross profit and operating profit to increase","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cheaper direct materials reduce cost of sales, immediately raising gross profit and flowing down into higher operating profit.","distractor_reasons":{"A":"Incorrect because direct raw materials are in cost of sales, not overheads.","B":"Incorrect because lower cost of sales increases gross profit.","C":"Incorrect because gross profit and operating profit both rise first.","D":"Option D is correct because cheaper direct materials reduce cost of sales, immediately raising gross profit and flowing down into higher operating profit."}}},{"id":"P1_U5_MCQ_938","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_938","question":"How does profit act as a 'performance indicator' for a company's board of directors?","options":{"A":"It measures whether the company has enough cash in the till to pay today's lunch bill","B":"It summarizes how effectively management has priced products, generated revenue, and controlled costs compared with previous years and industry rivals","C":"It shows the exact market value of the company's freehold land","D":"It measures how many hours employees worked overtime"},"correctOption":"B","correctAnswer":"It summarizes how effectively management has priced products, generated revenue, and controlled costs compared with previous years and industry rivals","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profit aggregates the financial outcome of marketing, pricing, and operational cost control.","distractor_reasons":{"A":"Incorrect because daily till cash is tracked via cash management, not annual profit.","B":"Option B is correct because profit aggregates the financial outcome of marketing, pricing, and operational cost control.","C":"Incorrect because property values are recorded on the statement of financial position.","D":"Incorrect because labor hours are operational HR metrics."}}},{"id":"P1_U5_MCQ_939","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_939","question":"How does profit serve directly as a 'source of finance' for business expansion?","options":{"A":"By being retained inside the business after tax and dividends to fund new equipment, R&D, or market entry without debt interest","B":"By forcing suppliers to lend money to the business","C":"By reducing the business's issued share capital","D":"By automatically paying off all non-current liabilities overnight"},"correctOption":"A","correctAnswer":"By being retained inside the business after tax and dividends to fund new equipment, R&D, or market entry without debt interest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit is the primary internal source of long-term capital for established enterprises.","distractor_reasons":{"A":"Option A is correct because retained profit is the primary internal source of long-term capital for established enterprises.","B":"Incorrect because suppliers do not lend cash based on a buyer's profit.","C":"Incorrect because retained profit adds to equity reserves without reducing share capital.","D":"Incorrect because retained profit is an equity reserve rather than an automatic debt repayment."}}},{"id":"P1_U5_MCQ_940","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_940","question":"Why do investors often tolerate a planned 'net loss' on a tech start-up's statement of profit or loss during its first year of trading?","options":{"A":"Because start-ups are legally prohibited from earning a profit in Year 1","B":"Because heavy upfront launch marketing, software R&D, and fixed overheads are incurred before customer sales volume scales up to break-even levels","C":"Because start-ups never record sales revenue on their income statement","D":"Because making a loss exempts the start-up from paying employee wages"},"correctOption":"B","correctAnswer":"Because heavy upfront launch marketing, software R&D, and fixed overheads are incurred before customer sales volume scales up to break-even levels","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because early-stage businesses intentionally invest in customer acquisition and infrastructure ahead of scale-driven profitability.","distractor_reasons":{"A":"Incorrect because start-ups are welcome to make profits immediately if revenue exceeds costs.","B":"Option B is correct because early-stage businesses intentionally invest in customer acquisition and infrastructure ahead of scale-driven profitability.","C":"Incorrect because all earned revenue is recorded on the income statement.","D":"Incorrect because wages remain legally payable regardless of profit or loss."}}},{"id":"P1_U5_MCQ_941","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_941","question":"If a company has a large variable-rate bank loan and market interest rates rise sharply, which lines on its statement of profit or loss are directly affected?","options":{"A":"Gross profit and operating profit fall immediately","B":"Sales revenue and cost of sales fall immediately","C":"Operating profit stays unchanged, while finance costs (interest) rise, reducing profit before tax, profit after tax, and retained profit","D":"Only dividends paid to shareholders increase"},"correctOption":"C","correctAnswer":"Operating profit stays unchanged, while finance costs (interest) rise, reducing profit before tax, profit after tax, and retained profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because interest is deducted *after* operating profit (profit before interest and tax), squeezing bottom-line profit.","distractor_reasons":{"A":"Incorrect because interest is a financing cost excluded from gross profit and operating profit.","B":"Incorrect because loan interest rates do not directly change revenue or cost of sales.","C":"Option C is correct because interest is deducted *after* operating profit (profit before interest and tax), squeezing bottom-line profit.","D":"Incorrect because lower profit after tax reduces funds available for dividends."}}},{"id":"P1_U5_MCQ_942","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_942","question":"If the government raises the national 'corporation tax rate' from 20% to 25%, how does this impact a profitable company's statement of profit or loss?","options":{"A":"Gross profit, operating profit, and profit before tax remain unchanged, while the tax deduction increases, reducing profit after tax and retained profit","B":"Gross profit falls by 5%","C":"Operating profit falls by 5%","D":"Cost of sales increases by 5%"},"correctOption":"A","correctAnswer":"Gross profit, operating profit, and profit before tax remain unchanged, while the tax deduction increases, reducing profit after tax and retained profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because corporation tax is levied on profit before tax, leaving all trading profit lines above it unaffected.","distractor_reasons":{"A":"Option A is correct because corporation tax is levied on profit before tax, leaving all trading profit lines above it unaffected.","B":"Incorrect because gross profit is before tax.","C":"Incorrect because operating profit is profit before interest and tax.","D":"Incorrect because corporation tax is not part of cost of sales."}}},{"id":"P1_U5_MCQ_943","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_943","question":"Why do 'government tax authorities' examine a limited company's statement of profit or loss?","options":{"A":"To check the company's acid-test liquidity ratio","B":"To decide which products the company should stop selling","C":"To set the salary of the company's marketing manager","D":"To verify revenue, deductible expenses, and profit before tax so they can calculate and collect the accurate amount of corporation tax owed"},"correctOption":"D","correctAnswer":"To verify revenue, deductible expenses, and profit before tax so they can calculate and collect the accurate amount of corporation tax owed","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because statutory income statements provide the verified profit base for corporate taxation.","distractor_reasons":{"A":"Incorrect because tax authorities assess tax liability rather than short-term liquidity ratios.","B":"Incorrect because product portfolio decisions belong to company management.","C":"Incorrect because executive pay is set by the company's remuneration committee.","D":"Option D is correct because statutory income statements provide the verified profit base for corporate taxation."}}},{"id":"P1_U5_MCQ_944","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_944","question":"Why do 'employees and trade unions' examine an employer's statement of profit or loss?","options":{"A":"To calculate the market value of the company's freehold land","B":"To assess whether the business is profitable enough to guarantee job security and afford wage increases or performance bonuses","C":"To determine how much corporation tax the government should charge","D":"To approve the company's bank overdraft limit"},"correctOption":"B","correctAnswer":"To assess whether the business is profitable enough to guarantee job security and afford wage increases or performance bonuses","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sustained losses threaten redundancies, while strong profits strengthen union arguments for pay rises.","distractor_reasons":{"A":"Incorrect because property values are not shown on the statement of profit or loss.","B":"Option B is correct because sustained losses threaten redundancies, while strong profits strengthen union arguments for pay rises.","C":"Incorrect because tax rates are set by the government.","D":"Incorrect because banks approve overdraft facilities."}}},{"id":"P1_U5_MCQ_945","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_945","question":"Why do 'competitors' examine the published statements of profit or loss of a rival public limited company (plc)?","options":{"A":"To legally force the rival plc to reduce its dividend payouts","B":"To benchmark their own revenue growth, gross profit margins, and cost efficiency against an industry rival","C":"To audit the rival plc's inventory warehouse in person","D":"To pay the rival plc's corporation tax bill"},"correctOption":"B","correctAnswer":"To benchmark their own revenue growth, gross profit margins, and cost efficiency against an industry rival","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because published annual reports give rivals valuable competitive intelligence on relative margins and scale.","distractor_reasons":{"A":"Incorrect because competitors have no legal authority over a rival's dividends.","B":"Option B is correct because published annual reports give rivals valuable competitive intelligence on relative margins and scale.","C":"Incorrect because external auditors inspect inventory, not competitors.","D":"Incorrect because each company pays its own tax."}}},{"id":"P1_U5_MCQ_946","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_946","question":"Under accrual accounting, when is a $25,000 credit sale delivered in December (with customer payment due in February) recorded on the statement of profit or loss?","options":{"A":"In February when cash arrives in the bank","B":"In December when the goods are delivered and invoiced, because revenue is recognized when earned rather than when cash is collected","C":"Split 50% in December and 50% in February","D":"It is omitted until the customer buys a second order"},"correctOption":"B","correctAnswer":"In December when the goods are delivered and invoiced, because revenue is recognized when earned rather than when cash is collected","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because accrual accounting matches earned revenue to the period of sale regardless of credit collection timing.","distractor_reasons":{"A":"Incorrect because February is when the cash inflow appears on the cash flow statement, whereas revenue was earned in December.","B":"Option B is correct because accrual accounting matches earned revenue to the period of sale regardless of credit collection timing.","C":"Incorrect because revenue is recognized in full upon delivery/invoicing.","D":"Incorrect because all valid credit sales are recorded when earned."}}},{"id":"P1_U5_MCQ_947","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_947","question":"When a business determines that a $4,000 customer invoice is completely uncollectible ('irrecoverable bad debt') and writes it off, how does this affect its statement of profit or loss?","options":{"A":"It is recorded as an expense, reducing operating profit by $4,000","B":"It is added to gross profit","C":"It increases retained profit by $4,000","D":"It has zero effect on profit because the sale was already recorded earlier"},"correctOption":"A","correctAnswer":"It is recorded as an expense, reducing operating profit by $4,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because writing off a bad debt recognizes the loss of an expected receivable as an operating expense.","distractor_reasons":{"A":"Option A is correct because writing off a bad debt recognizes the loss of an expected receivable as an operating expense.","B":"Incorrect because a bad debt is a loss/expense, not profit.","C":"Incorrect because lower operating profit reduces retained profit.","D":"Incorrect because because the revenue was recorded earlier, failing to collect the cash requires an expense write-off to correct profit."}}},{"id":"P1_U5_MCQ_948","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_948","question":"Why are a sole trader's personal 'drawings' NOT deducted as an expense on the statement of profit or loss?","options":{"A":"Because sole traders never pay taxes","B":"Because drawings are a personal withdrawal of owner's equity (recorded on the statement of financial position), not a business operating cost incurred to earn revenue","C":"Because drawings are added to sales revenue","D":"Because drawings are classified as non-current assets"},"correctOption":"B","correctAnswer":"Because drawings are a personal withdrawal of owner's equity (recorded on the statement of financial position), not a business operating cost incurred to earn revenue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because deducting personal drawings as an expense would artificially understate true business trading profit.","distractor_reasons":{"A":"Incorrect because sole traders pay income tax on business profits.","B":"Option B is correct because deducting personal drawings as an expense would artificially understate true business trading profit.","C":"Incorrect because drawings reduce owner's capital, not add to revenue.","D":"Incorrect because drawings are equity reductions, not assets."}}},{"id":"P1_U5_MCQ_949","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_949","question":"If a bakery sells an old delivery van for $8,000 (which equals its exact Net Book Value), why is the $8,000 NOT included inside 'sales revenue' at the top of the statement of profit or loss?","options":{"A":"Because sales revenue only records income from selling the business's trading goods or services (bread and cakes), whereas disposing of a non-current asset is a capital transaction","B":"Because selling a van is illegal for a bakery","C":"Because the $8,000 is recorded as an overhead expense","D":"Because the $8,000 is recorded as a current liability"},"correctOption":"A","correctAnswer":"Because sales revenue only records income from selling the business's trading goods or services (bread and cakes), whereas disposing of a non-current asset is a capital transaction","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mixing one-off asset disposal proceeds into trading revenue would distort gross profit margin and sales trends.","distractor_reasons":{"A":"Option A is correct because mixing one-off asset disposal proceeds into trading revenue would distort gross profit margin and sales trends.","B":"Incorrect because businesses routinely sell surplus equipment.","C":"Incorrect because selling an asset at book value is neither an expense nor trading revenue.","D":"Incorrect because cash received from selling an owned asset is not a debt owed."}}},{"id":"P1_U5_MCQ_950","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_950","question":"Which sequence shows the correct top-to-bottom order of lines on a limited company's 'statement of profit or loss'?","options":{"A":"Revenue → Cost of sales → Operating profit → Gross profit → Dividends → Interest → Retained profit","B":"Revenue → Overhead expenses → Gross profit → Cost of sales → Operating profit → Dividends → Corporation tax → Retained profit","C":"Gross profit → Revenue → Cost of sales → Corporation tax → Operating profit → Dividends → Retained profit","D":"Revenue → Cost of sales → Gross profit → Overhead expenses → Operating profit → Interest → Profit before tax → Corporation tax → Profit after tax → Dividends → Retained profit"},"correctOption":"D","correctAnswer":"Revenue → Cost of sales → Gross profit → Overhead expenses → Operating profit → Interest → Profit before tax → Corporation tax → Profit after tax → Dividends → Retained profit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because it follows standard international presentation from top-line trading revenue down to final retained profit.","distractor_reasons":{"A":"Incorrect because gross profit comes before operating profit, and interest/tax come before dividends.","B":"Incorrect because cost of sales is deducted before gross profit, and tax is deducted before dividends.","C":"Incorrect because revenue comes first, and tax is deducted after operating profit and interest.","D":"Option D is correct because it follows standard international presentation from top-line trading revenue down to final retained profit."}}},{"id":"P1_U5_MCQ_951","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_951","question":"A business reports inventories of $22,000, trade receivables of $18,000, cash at bank of $5,000, trade payables of $20,000, and a bank overdraft of $7,000. What is its 'working capital (net current assets)'?","options":{"A":"$45,000","B":"$18,000","C":"$27,000","D":"$32,000"},"correctOption":"B","correctAnswer":"$18,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Current assets = $22,000 + $18,000 + $5,000 = $45,000; Current liabilities = $20,000 + $7,000 = $27,000; Working capital = $45,000 - $27,000 = $18,000.","distractor_reasons":{"A":"Incorrect because $45,000 is total current assets before subtracting current liabilities.","B":"Option B is correct because Current assets = $22,000 + $18,000 + $5,000 = $45,000; Current liabilities = $20,000 + $7,000 = $27,000; Working capital = $45,000 - $27,000 = $18,000.","C":"Incorrect because $27,000 is total current liabilities.","D":"Incorrect because $32,000 adds the $7,000 bank overdraft instead of subtracting it."}}},{"id":"P1_U5_MCQ_952","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_952","question":"On its statement of financial position, a company has non-current assets of $150,000, current assets of $60,000, current liabilities of $25,000, and non-current liabilities of $45,000. What are its 'net assets'?","options":{"A":"$210,000","B":"$185,000","C":"$140,000","D":"$35,000"},"correctOption":"C","correctAnswer":"$140,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Net assets = Total assets ($150,000 + $60,000 = $210,000) - Total liabilities ($25,000 + $45,000 = $70,000) = $140,000.","distractor_reasons":{"A":"Incorrect because $210,000 is total assets before deducting liabilities.","B":"Incorrect because $185,000 forgets to subtract the $45,000 non-current liabilities.","C":"Option C is correct because Net assets = Total assets ($150,000 + $60,000 = $210,000) - Total liabilities ($25,000 + $45,000 = $70,000) = $140,000.","D":"Incorrect because $35,000 is working capital ($60,000 - $25,000), not total net assets."}}},{"id":"P1_U5_MCQ_953","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_953","question":"A limited company has issued share capital of $100,000, retained profit reserves of $40,000, non-current liabilities of $45,000, and current liabilities of $25,000. What is its 'capital employed'?","options":{"A":"$140,000","B":"$210,000","C":"$100,000","D":"$185,000"},"correctOption":"D","correctAnswer":"$185,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Capital employed = Total shareholders' equity ($100,000 + $40,000 = $140,000) + Non-current liabilities ($45,000) = $185,000 (current liabilities are excluded).","distractor_reasons":{"A":"Incorrect because $140,000 is shareholders' equity alone without non-current liabilities.","B":"Incorrect because $210,000 mistakenly includes $25,000 of short-term current liabilities.","C":"Incorrect because $100,000 is issued share capital alone.","D":"Option D is correct because Capital employed = Total shareholders' equity ($100,000 + $40,000 = $140,000) + Non-current liabilities ($45,000) = $185,000 (current liabilities are excluded)."}}},{"id":"P1_U5_MCQ_954","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_954","question":"A sole trader begins the financial year with opening capital of $50,000, earns a profit for the year of $24,000, and takes personal drawings of $14,000. What is the sole trader's 'closing capital' on the statement of financial position?","options":{"A":"$40,000","B":"$88,000","C":"$74,000","D":"$60,000"},"correctOption":"D","correctAnswer":"$60,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Closing capital = Opening capital ($50,000) + Profit for the year ($24,000) - Drawings ($14,000) = $60,000.","distractor_reasons":{"A":"Incorrect because $40,000 subtracts profit instead of adding it.","B":"Incorrect because drawings must be subtracted rather than added.","C":"Incorrect because $74,000 forgets to subtract the $14,000 drawings.","D":"Option D is correct because Closing capital = Opening capital ($50,000) + Profit for the year ($24,000) - Drawings ($14,000) = $60,000."}}},{"id":"P1_U5_MCQ_955","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_955","question":"A factory bought CNC machinery three years ago for $80,000 and has recorded accumulated depreciation of $32,000 to date. At what 'Net Book Value' is the machinery shown on the statement of financial position?","options":{"A":"$112,000","B":"$48,000","C":"$80,000","D":"$32,000"},"correctOption":"B","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Net Book Value = Original cost ($80,000) - Accumulated depreciation ($32,000) = $48,000.","distractor_reasons":{"A":"Incorrect because accumulated depreciation is subtracted from cost, not added.","B":"Option B is correct because Net Book Value = Original cost ($80,000) - Accumulated depreciation ($32,000) = $48,000.","C":"Incorrect because $80,000 is original historical cost before depreciation.","D":"Incorrect because $32,000 is the depreciation deducted so far."}}},{"id":"P1_U5_MCQ_956","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_956","question":"How are a '$12,000 bank overdraft' and a '$90,000 five-year bank loan' presented on a statement of financial position?","options":{"A":"Both are presented under non-current liabilities","B":"The bank overdraft is a current asset, while the five-year loan is a non-current liability","C":"The bank overdraft is presented under current liabilities, while the five-year loan is presented under non-current liabilities","D":"Both are presented under shareholders' equity"},"correctOption":"C","correctAnswer":"The bank overdraft is presented under current liabilities, while the five-year loan is presented under non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an overdraft is a short-term obligation repayable within 12 months, whereas a 5-year loan is a long-term debt.","distractor_reasons":{"A":"Incorrect because an overdraft is short-term, not non-current.","B":"Incorrect because a negative bank overdraft is money owed to the bank (a liability), not an asset.","C":"Option C is correct because an overdraft is a short-term obligation repayable within 12 months, whereas a 5-year loan is a long-term debt.","D":"Incorrect because both are external bank debts, not owner equity."}}},{"id":"P1_U5_MCQ_957","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_957","question":"Which group consists entirely of 'intangible non-current assets'?","options":{"A":"Freehold land, factory buildings, and delivery vans","B":"Inventories, trade receivables, and cash at bank","C":"Trade payables, bank overdrafts, and unpaid taxes","D":"Purchased goodwill, registered patents, copyrights, and acquired brand trademarks"},"correctOption":"D","correctAnswer":"Purchased goodwill, registered patents, copyrights, and acquired brand trademarks","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because these are long-term assets lacking physical substance that confer legal or commercial rights over more than one year.","distractor_reasons":{"A":"Incorrect because land, buildings, and vans are tangible physical non-current assets.","B":"Incorrect because inventories, receivables, and cash are current assets.","C":"Incorrect because payables, overdrafts, and unpaid taxes are current liabilities.","D":"Option D is correct because these are long-term assets lacking physical substance that confer legal or commercial rights over more than one year."}}},{"id":"P1_U5_MCQ_958","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_958","question":"Which group consists entirely of 'tangible non-current assets'?","options":{"A":"Raw material inventory, work-in-progress, and finished goods","B":"Patents, copyrights, and purchased goodwill","C":"Factory premises, assembly line machinery, office computers, and commercial trucks","D":"Issued share capital, debentures, and retained profit"},"correctOption":"C","correctAnswer":"Factory premises, assembly line machinery, office computers, and commercial trucks","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because these are physical long-term operational assets held for use for more than 12 months.","distractor_reasons":{"A":"Incorrect because inventories are current assets.","B":"Incorrect because patents, copyrights, and goodwill are intangible non-current assets.","C":"Option C is correct because these are physical long-term operational assets held for use for more than 12 months.","D":"Incorrect because share capital, debentures, and retained profit are financing items (equity and non-current liabilities)."}}},{"id":"P1_U5_MCQ_959","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_959","question":"In what standard order are 'current assets' listed on a statement of financial position, moving from least liquid to most liquid?","options":{"A":"Cash at bank → Trade receivables → Inventories","B":"Inventories → Trade receivables → Cash at bank and in hand","C":"Trade receivables → Inventories → Cash at bank","D":"Inventories → Cash at bank → Trade receivables"},"correctOption":"B","correctAnswer":"Inventories → Trade receivables → Cash at bank and in hand","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inventories take longest to turn into cash, followed by trade receivables, with cash already in liquid form at the bottom.","distractor_reasons":{"A":"Incorrect because this lists from most liquid to least liquid.","B":"Option B is correct because inventories take longest to turn into cash, followed by trade receivables, with cash already in liquid form at the bottom.","C":"Incorrect because inventories are less liquid than trade receivables.","D":"Incorrect because trade receivables are less liquid than cash at bank."}}},{"id":"P1_U5_MCQ_960","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_960","question":"Why are 'inventories' considered the least liquid of all current assets?","options":{"A":"Because inventories are legally prohibited from being sold for 10 years","B":"Because inventories are owed to commercial banks","C":"Because converting inventories into cash requires two uncertain steps: first finding buyers to sell the goods, and then waiting for credit customers to pay their invoices","D":"Because inventories have zero monetary value on the balance sheet"},"correctOption":"C","correctAnswer":"Because converting inventories into cash requires two uncertain steps: first finding buyers to sell the goods, and then waiting for credit customers to pay their invoices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unsold stock may suffer slow demand, obsolescence, or price discounting before ever turning into cash.","distractor_reasons":{"A":"Incorrect because inventories are held specifically for short-term sale.","B":"Incorrect because inventories are owned assets (unless pledged as collateral).","C":"Option C is correct because unsold stock may suffer slow demand, obsolescence, or price discounting before ever turning into cash.","D":"Incorrect because inventories are valued at cost (or net realizable value if lower)."}}},{"id":"P1_U5_MCQ_961","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_961","question":"A retailer buys $12,000 of inventory on 30-day trade credit. What is the immediate effect on the retailer's statement of financial position?","options":{"A":"Non-current assets increase by $12,000 and equity increases by $12,000","B":"Working capital increases by $12,000","C":"Current assets (inventories) increase by $12,000 and current liabilities (trade payables) increase by $12,000, leaving working capital unchanged","D":"Current assets decrease by $12,000 and current liabilities increase by $12,000"},"correctOption":"C","correctAnswer":"Current assets (inventories) increase by $12,000 and current liabilities (trade payables) increase by $12,000, leaving working capital unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Current assets and Current liabilities both rise by $12,000, leaving Current assets - Current liabilities unchanged.","distractor_reasons":{"A":"Incorrect because inventory is a current asset and trade credit is a current liability.","B":"Incorrect because the rise in trade payables offsets the rise in inventories.","C":"Option C is correct because Current assets and Current liabilities both rise by $12,000, leaving Current assets - Current liabilities unchanged.","D":"Incorrect because receiving new inventory *increases* current assets."}}},{"id":"P1_U5_MCQ_962","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_962","question":"When a credit customer pays a $9,000 invoice by bank transfer, how does this transaction affect the seller's statement of financial position?","options":{"A":"Total current assets increase by $9,000","B":"Cash at bank increases by $9,000 and trade receivables decrease by $9,000, leaving total current assets and working capital unchanged","C":"Current liabilities decrease by $9,000","D":"Shareholders' equity increases by $9,000"},"correctOption":"B","correctAnswer":"Cash at bank increases by $9,000 and trade receivables decrease by $9,000, leaving total current assets and working capital unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because collecting a receivable merely swaps one current asset (receivables) for another (cash), improving liquidity quality without changing total current assets.","distractor_reasons":{"A":"Incorrect because trade receivables drop by $9,000 at the same time cash rises by $9,000.","B":"Option B is correct because collecting a receivable merely swaps one current asset (receivables) for another (cash), improving liquidity quality without changing total current assets.","C":"Incorrect because a customer paying us affects current assets, not current liabilities.","D":"Incorrect because profit/equity was already recognized when the credit sale occurred."}}},{"id":"P1_U5_MCQ_963","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_963","question":"A company borrows $50,000 via a 5-year bank loan and holds the proceeds in its bank current account. What happens to its 'working capital' and 'net assets' immediately?","options":{"A":"Working capital is unchanged, while net assets increase by $50,000","B":"Both working capital and net assets decrease by $50,000","C":"Working capital increases by $50,000 (because cash rises while current liabilities stay unchanged), while net assets remain unchanged (because non-current liabilities also rose by $50,000)","D":"Both working capital and net assets increase by $50,000"},"correctOption":"C","correctAnswer":"Working capital increases by $50,000 (because cash rises while current liabilities stay unchanged), while net assets remain unchanged (because non-current liabilities also rose by $50,000)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Current assets (+$50,000 cash) rise without any increase in Current liabilities (+working capital), while the $50,000 Non-current liability keeps Net assets constant.","distractor_reasons":{"A":"Incorrect because cash is a current asset while the 5-year loan is non-current, so working capital rises.","B":"Incorrect because receiving cash increases working capital.","C":"Option C is correct because Current assets (+$50,000 cash) rise without any increase in Current liabilities (+working capital), while the $50,000 Non-current liability keeps Net assets constant.","D":"Incorrect because borrowing money adds a $50,000 liability, leaving net assets unchanged."}}},{"id":"P1_U5_MCQ_964","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_964","question":"When a limited company retains $30,000 of its after-tax profit at year-end rather than paying it out as dividends, how is this reflected on its statement of financial position?","options":{"A":"Non-current liabilities increase by $30,000","B":"Current liabilities increase by $30,000","C":"Issued share capital decreases by $30,000","D":"Retained profit reserves inside shareholders' equity increase by $30,000, increasing total equity and net assets"},"correctOption":"D","correctAnswer":"Retained profit reserves inside shareholders' equity increase by $30,000, increasing total equity and net assets","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retained profit belongs to the shareholders and builds up internal equity reserves.","distractor_reasons":{"A":"Incorrect because retained profit is internal equity, not an external loan.","B":"Incorrect because retained profit is not a short-term debt.","C":"Incorrect because retaining profit does not reduce issued share capital.","D":"Option D is correct because retained profit belongs to the shareholders and builds up internal equity reserves."}}},{"id":"P1_U5_MCQ_965","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_965","question":"What does a 'negative working capital' figure (where current liabilities exceed current assets) on a manufacturing firm's statement of financial position warn analysts about?","options":{"A":"The manufacturer may struggle to pay its short-term debts and supplier bills over the next 12 months without arranging emergency finance or selling non-current assets","B":"The manufacturer has too much idle cash sitting in the bank","C":"The manufacturer has zero non-current assets","D":"The manufacturer's gross profit margin is above 80%"},"correctOption":"A","correctAnswer":"The manufacturer may struggle to pay its short-term debts and supplier bills over the next 12 months without arranging emergency finance or selling non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because negative working capital means short-term obligations exceed short-term liquid resources.","distractor_reasons":{"A":"Option A is correct because negative working capital means short-term obligations exceed short-term liquid resources.","B":"Incorrect because negative working capital signals a cash/current-asset *shortage*, not excess cash.","C":"Incorrect because working capital compares current assets and current liabilities only.","D":"Incorrect because working capital is a liquidity measure, not gross profit margin."}}},{"id":"P1_U5_MCQ_966","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_966","question":"Which of the following would appear as a non-current asset on a statement of financial position?","options":{"A":"Delivery vans owned by the business","B":"Cash in the till","C":"Finished goods held in the warehouse","D":"Amounts owed by customers"},"correctOption":"A","correctAnswer":"Delivery vans owned by the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delivery vans are long-term assets used in the business and are expected to benefit it for more than one year.","distractor_reasons":{"A":"Option A is correct because delivery vans are long-term assets used in the business and are expected to benefit it for more than one year.","B":"Incorrect because cash in the till is a current asset, being the most liquid form of asset.","C":"Incorrect because finished goods are inventories, which are current assets expected to be sold within the year.","D":"Incorrect because amounts owed by customers are receivables, a short-term current asset."}}},{"id":"P1_U5_MCQ_967","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_967","question":"How do 'existing shareholders' use a company's statement of financial position?","options":{"A":"To track daily customer footfall in retail stores","B":"To calculate the exact hourly wage rate of factory cleaners","C":"To check the growth in net asset value (shareholders' equity) and see how the company's assets are financed between owners' funds and external debt","D":"To set government interest rates"},"correctOption":"C","correctAnswer":"To check the growth in net asset value (shareholders' equity) and see how the company's assets are financed between owners' funds and external debt","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the statement of financial position shows the net wealth owned by shareholders and the company's capital structure.","distractor_reasons":{"A":"Incorrect because customer footfall is an operational marketing metric.","B":"Incorrect because individual wage rates are not reported on the balance sheet.","C":"Option C is correct because the statement of financial position shows the net wealth owned by shareholders and the company's capital structure.","D":"Incorrect because central banks set interest rates."}}},{"id":"P1_U5_MCQ_968","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_968","question":"Why does a company considering a 'takeover' of a rival inspect the target firm's statement of financial position closely before making an offer?","options":{"A":"To avoid paying corporation tax after the takeover","B":"To verify the target firm's advertising slogans from ten years ago","C":"To calculate the national inflation rate","D":"To see the exact value of property, patents, inventory, and cash it will acquire, as well as the existing short-term and long-term debts it will inherit"},"correctOption":"D","correctAnswer":"To see the exact value of property, patents, inventory, and cash it will acquire, as well as the existing short-term and long-term debts it will inherit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because acquiring a business means taking over both its assets and its outstanding liabilities.","distractor_reasons":{"A":"Incorrect because merged companies still pay corporation tax on profits.","B":"Incorrect because advertising slogans are not recorded on the statement of financial position.","C":"Incorrect because inflation is a macroeconomic statistic.","D":"Option D is correct because acquiring a business means taking over both its assets and its outstanding liabilities."}}},{"id":"P1_U5_MCQ_969","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_969","question":"Why must 'Net assets (Total assets minus Total liabilities)' ALWAYS equal 'Total equity' on a correctly prepared statement of financial position?","options":{"A":"Because double-entry accounting ensures that whatever residual asset value remains after paying off all external creditor claims belongs entirely to the owners (equity)","B":"Because businesses are legally forbidden from taking out loans","C":"Because current assets always equal current liabilities","D":"Because non-current assets are always worth $0"},"correctOption":"A","correctAnswer":"Because double-entry accounting ensures that whatever residual asset value remains after paying off all external creditor claims belongs entirely to the owners (equity)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Assets = Liabilities + Equity rearranges directly to Assets - Liabilities = Equity.","distractor_reasons":{"A":"Option A is correct because Assets = Liabilities + Equity rearranges directly to Assets - Liabilities = Equity.","B":"Incorrect because liabilities are subtracted from total assets in the equation.","C":"Incorrect because current assets and current liabilities rarely equal each other.","D":"Incorrect because non-current assets have positive Net Book Values."}}},{"id":"P1_U5_MCQ_970","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_970","question":"If a business pays $6,000 in advance for next year's warehouse insurance ('prepaid expense') before the reporting date, how is that $6,000 shown on the statement of financial position?","options":{"A":"As a current liability","B":"As a non-current liability","C":"As a current asset (other receivable / prepayment), because the business has already paid for a service benefit it will receive within the next 12 months","D":"As issued share capital"},"correctOption":"C","correctAnswer":"As a current asset (other receivable / prepayment), because the business has already paid for a service benefit it will receive within the next 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a prepayment represents a short-term economic benefit owed to the business over the coming year.","distractor_reasons":{"A":"Incorrect because unpaid bills owed *by* the business are liabilities, whereas prepaid bills are assets.","B":"Incorrect because annual insurance covers the next 12 months, making it current.","C":"Option C is correct because a prepayment represents a short-term economic benefit owed to the business over the coming year.","D":"Incorrect because prepayments are operational current assets, not owner share capital."}}},{"id":"P1_U5_MCQ_971","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_971","question":"Why does 'issued share capital' on a public limited company's statement of financial position rarely match the company's total 'stock market value (market capitalization)'?","options":{"A":"Because stock exchange share prices are fixed permanently by the government","B":"Because issued share capital records the original nominal/issue value paid to the company when shares were first sold, whereas market capitalization reflects the current fluctuating share price traded between investors on the stock exchange","C":"Because issued share capital is recorded under current liabilities","D":"Because public limited companies never issue shares"},"correctOption":"B","correctAnswer":"Because issued share capital records the original nominal/issue value paid to the company when shares were first sold, whereas market capitalization reflects the current fluctuating share price traded between investors on the stock exchange","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because secondary stock market trading changes share prices based on future profit expectations without changing the historical share capital figure on the company's books.","distractor_reasons":{"A":"Incorrect because stock market prices fluctuate continuously with supply and demand.","B":"Option B is correct because secondary stock market trading changes share prices based on future profit expectations without changing the historical share capital figure on the company's books.","C":"Incorrect because issued share capital is part of shareholders' equity.","D":"Incorrect because plcs raise equity by issuing shares."}}},{"id":"P1_U5_MCQ_972","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_972","question":"How does 'retained profit' on the statement of financial position differ from 'retained profit' on the statement of profit or loss?","options":{"A":"The statement of profit or loss shows the profit retained from *that single year*, whereas the statement of financial position shows the *cumulative total* of all undistributed profits accumulated over the company's entire history","B":"Both statements always show the exact same dollar figure even for a 20-year-old company","C":"The statement of financial position shows retained profit as a current liability","D":"The statement of profit or loss excludes dividends before calculating retained profit"},"correctOption":"A","correctAnswer":"The statement of profit or loss shows the profit retained from *that single year*, whereas the statement of financial position shows the *cumulative total* of all undistributed profits accumulated over the company's entire history","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because each year's retained profit flow adds to the cumulative retained profit reserve on the balance sheet.","distractor_reasons":{"A":"Option A is correct because each year's retained profit flow adds to the cumulative retained profit reserve on the balance sheet.","B":"Incorrect because for a multi-year company, cumulative reserves equal prior years' reserves plus the current year's retained profit.","C":"Incorrect because retained profit is shareholders' equity.","D":"Incorrect because dividends are deducted from profit after tax to arrive at annual retained profit."}}},{"id":"P1_U5_MCQ_973","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_973","question":"What is 'window dressing' as a limitation when analyzing a company's statement of financial position?","options":{"A":"Decorating retail shop windows to attract Christmas shoppers","B":"Taking short-term actions right before the year-end reporting date (such as delaying supplier payments or holding back equipment purchases) to make cash and liquidity look temporarily stronger than normal","C":"Hiring external auditors to verify inventory counts","D":"Revaluing freehold property upwards after an independent survey"},"correctOption":"B","correctAnswer":"Taking short-term actions right before the year-end reporting date (such as delaying supplier payments or holding back equipment purchases) to make cash and liquidity look temporarily stronger than normal","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a single year-end snapshot can be manipulated through temporary timing tactics right around the reporting date.","distractor_reasons":{"A":"Incorrect because in accounting, 'window dressing' refers to cosmetic presentation of year-end financial positions.","B":"Option B is correct because a single year-end snapshot can be manipulated through temporary timing tactics right around the reporting date.","C":"Incorrect because external audits aim to *prevent* misleading financial reporting.","D":"Incorrect because formal independent revaluation follows accounting standards rather than short-term cash manipulation."}}},{"id":"P1_U5_MCQ_974","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_974","question":"Why can two competitors owning identical machinery of the exact same age and condition show different 'non-current asset Net Book Values' on their statements of financial position?","options":{"A":"Because one company is allowed to omit machinery from its balance sheet","B":"Because one company records machinery under current liabilities","C":"Because one company may have estimated a shorter useful lifespan (recording higher annual depreciation) than the other, lowering its book value faster","D":"Because machinery never depreciates in limited companies"},"correctOption":"C","correctAnswer":"Because one company may have estimated a shorter useful lifespan (recording higher annual depreciation) than the other, lowering its book value faster","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Net Book Value depends on accounting depreciation estimates rather than real-time second-hand market valuations.","distractor_reasons":{"A":"Incorrect because all owned operational machinery must be recorded.","B":"Incorrect because owned machinery is always a non-current asset.","C":"Option C is correct because Net Book Value depends on accounting depreciation estimates rather than real-time second-hand market valuations.","D":"Incorrect because all companies depreciate machinery over its useful life."}}},{"id":"P1_U5_MCQ_975","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_975","question":"Which accounting link directly connects a limited company's 'statement of profit or loss' to its 'statement of financial position' at the end of the financial year?","options":{"A":"Gross profit is added directly to cash at bank","B":"Sales revenue is added directly to issued share capital","C":"Cost of sales is added directly to non-current liabilities","D":"The retained profit earned during the year (from the bottom of the statement of profit or loss) is added to the retained profit reserve inside shareholders' equity on the statement of financial position"},"correctOption":"D","correctAnswer":"The retained profit earned during the year (from the bottom of the statement of profit or loss) is added to the retained profit reserve inside shareholders' equity on the statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because undistributed profit earned over the year increases the owners' cumulative equity stake in the business.","distractor_reasons":{"A":"Incorrect because gross profit is not equal to bank cash.","B":"Incorrect because sales revenue does not increase share capital.","C":"Incorrect because cost of sales is an income statement cost, not a long-term debt.","D":"Option D is correct because undistributed profit earned over the year increases the owners' cumulative equity stake in the business."}}},{"id":"P1_U5_MCQ_976","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_976","question":"A retailer reports annual sales revenue of $160,000 and gross profit of $48,000. What is its 'gross profit margin'?","options":{"A":"3.33%","B":"70%","C":"42.9%","D":"30%"},"correctOption":"D","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Gross profit margin = ($48,000 / $160,000) × 100 = 30%.","distractor_reasons":{"A":"Incorrect because 3.33 is Revenue divided by Gross profit ($160,000 / $48,000).","B":"Incorrect because 70% ($112,000 / $160,000) is the cost-of-sales-to-revenue ratio.","C":"Incorrect because 42.9% ($48,000 / $112,000) is mark-up on cost of sales rather than gross profit margin on revenue.","D":"Option D is correct because Gross profit margin = ($48,000 / $160,000) × 100 = 30%."}}},{"id":"P1_U5_MCQ_977","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_977","question":"An engineering firm records annual sales revenue of $180,000, gross profit of $72,000, and operating profit of $27,000. What is its 'profit margin'?","options":{"A":"40%","B":"15%","C":"37.5%","D":"25%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Profit margin = (Operating profit / Revenue) × 100 = ($27,000 / $180,000) × 100 = 15%.","distractor_reasons":{"A":"Incorrect because 40% ($72,000 / $180,000) is the gross profit margin.","B":"Option B is correct because Profit margin = (Operating profit / Revenue) × 100 = ($27,000 / $180,000) × 100 = 15%.","C":"Incorrect because 37.5% divides operating profit by gross profit ($27,000 / $72,000) instead of revenue.","D":"Incorrect because 25% ($45,000 / $180,000) is overhead expenses as a percentage of revenue."}}},{"id":"P1_U5_MCQ_978","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_978","question":"A company generates an operating profit of $45,000 using shareholders' equity of $200,000 and non-current liabilities of $100,000. What is its 'Return on Capital Employed (ROCE)'?","options":{"A":"22.5%","B":"45%","C":"15%","D":"10%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Capital employed = $200,000 + $100,000 = $300,000; ROCE = ($45,000 / $300,000) × 100 = 15%.","distractor_reasons":{"A":"Incorrect because 22.5% ($45,000 / $200,000) omits the $100,000 non-current liabilities from capital employed.","B":"Incorrect because 45% divides by $100,000 non-current liabilities alone.","C":"Option C is correct because Capital employed = $200,000 + $100,000 = $300,000; ROCE = ($45,000 / $300,000) × 100 = 15%.","D":"Incorrect because 10% ($45,000 / $450,000) miscalculates capital employed."}}},{"id":"P1_U5_MCQ_979","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_979","question":"A business holds current assets of $90,000 (including $36,000 of inventories) and owes current liabilities of $60,000. What is its 'current ratio'?","options":{"A":"0.9 : 1","B":"0.67 : 1","C":"2.1 : 1","D":"1.5 : 1"},"correctOption":"D","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Current ratio = Current assets ($90,000) / Current liabilities ($60,000) = 1.5 : 1.","distractor_reasons":{"A":"Incorrect because 0.9 : 1 is the acid-test ratio after subtracting inventories.","B":"Incorrect because 0.67 : 1 inverts current liabilities and current assets ($60,000 / $90,000).","C":"Incorrect because 2.1 : 1 adds inventories ($90,000 + $36,000) instead of recognizing they are already inside current assets.","D":"Option D is correct because Current ratio = Current assets ($90,000) / Current liabilities ($60,000) = 1.5 : 1."}}},{"id":"P1_U5_MCQ_980","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_980","question":"Using the same business figures—current assets of $90,000, inventories of $36,000, and current liabilities of $60,000—what is its 'acid-test (quick) ratio'?","options":{"A":"0.9 : 1","B":"1.5 : 1","C":"0.6 : 1","D":"1.11 : 1"},"correctOption":"A","correctAnswer":"0.9 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Acid-test ratio = ($90,000 - $36,000) / $60,000 = $54,000 / $60,000 = 0.9 : 1.","distractor_reasons":{"A":"Option A is correct because Acid-test ratio = ($90,000 - $36,000) / $60,000 = $54,000 / $60,000 = 0.9 : 1.","B":"Incorrect because 1.5 : 1 is the current ratio before excluding inventories.","C":"Incorrect because 0.6 : 1 divides inventories ($36,000) by current liabilities ($60,000).","D":"Incorrect because 1.11 : 1 divides current liabilities by quick assets ($60,000 / $54,000)."}}},{"id":"P1_U5_MCQ_981","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_981","question":"A company reports annual sales revenue of $250,000 and achieves a 'profit margin' of 12%. What was its 'operating profit' in dollars?","options":{"A":"$20,833","B":"$30,000","C":"$220,000","D":"$12,000"},"correctOption":"B","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Operating profit = 12% × $250,000 = 0.12 × $250,000 = $30,000.","distractor_reasons":{"A":"Incorrect because $20,833 divides $250,000 by 12 instead of multiplying by 0.12.","B":"Option B is correct because Operating profit = 12% × $250,000 = 0.12 × $250,000 = $30,000.","C":"Incorrect because $220,000 is total costs ($250,000 - $30,000).","D":"Incorrect because $12,000 treats 12% as a fixed dollar sum."}}},{"id":"P1_U5_MCQ_982","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_982","question":"If a company earns an operating profit of $54,000 and achieves a 'Return on Capital Employed (ROCE)' of 18%, what is its total 'capital employed'?","options":{"A":"$9,720","B":"$540,000","C":"$300,000","D":"$360,000"},"correctOption":"C","correctAnswer":"$300,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ROCE = Operating profit / Capital employed, so Capital employed = $54,000 / 0.18 = $300,000.","distractor_reasons":{"A":"Incorrect because $9,720 multiplies $54,000 by 0.18 instead of dividing.","B":"Incorrect because $540,000 corresponds to a 10% ROCE.","C":"Option C is correct because ROCE = Operating profit / Capital employed, so Capital employed = $54,000 / 0.18 = $300,000.","D":"Incorrect because $360,000 corresponds to a 15% ROCE."}}},{"id":"P1_U5_MCQ_983","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_983","question":"What does an unusually high 'current ratio' of 4.2 : 1 suggest to a financial analyst?","options":{"A":"The business is on the verge of immediate bankruptcy","B":"The business has zero current assets","C":"The business is guaranteed to have the highest ROCE in its industry","D":"While short-term debt coverage is very safe, the business is holding excessive idle cash, bloated inventory, or slow-paying receivables that could be invested more productively"},"correctOption":"D","correctAnswer":"While short-term debt coverage is very safe, the business is holding excessive idle cash, bloated inventory, or slow-paying receivables that could be invested more productively","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because typical healthy current ratios sit around 1.5 : 1 to 2 : 1; ratios above 3 : 1 or 4 : 1 signal inefficient working capital use.","distractor_reasons":{"A":"Incorrect because a ratio below 1 : 1 signals liquidity danger, not 4.2 : 1.","B":"Incorrect because 4.2 : 1 means current assets are 4.2 times larger than current liabilities.","C":"Incorrect because idle working capital actually lowers ROCE.","D":"Option D is correct because typical healthy current ratios sit around 1.5 : 1 to 2 : 1; ratios above 3 : 1 or 4 : 1 signal inefficient working capital use."}}},{"id":"P1_U5_MCQ_984","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_984","question":"A fashion retailer has a 'current ratio' of 1.8 : 1, but its 'acid-test ratio' is only 0.5 : 1. What does this large gap reveal?","options":{"A":"Most of the retailer's current assets are tied up in unsold clothing inventory, leaving insufficient liquid cash and receivables to pay short-term bills if seasonal fashion stock fails to sell quickly","B":"The retailer holds zero clothing inventory","C":"The retailer has zero current liabilities","D":"The retailer's operating profit margin is 180%"},"correctOption":"A","correctAnswer":"Most of the retailer's current assets are tied up in unsold clothing inventory, leaving insufficient liquid cash and receivables to pay short-term bills if seasonal fashion stock fails to sell quickly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the difference between the current ratio and acid-test ratio is driven entirely by inventory levels.","distractor_reasons":{"A":"Option A is correct because the difference between the current ratio and acid-test ratio is driven entirely by inventory levels.","B":"Incorrect because zero inventory would make both ratios equal.","C":"Incorrect because current liabilities are positive in both ratios.","D":"Incorrect because liquidity ratios do not measure profit margins."}}},{"id":"P1_U5_MCQ_985","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_985","question":"What is a potential drawback of trying to boost 'gross profit margin' by switching to cheaper raw-material suppliers?","options":{"A":"Direct cost of sales will increase immediately","B":"Lower-quality materials may cause higher product defect rates, customer returns, and damage to brand reputation, ultimately hurting future sales","C":"Head-office rent will automatically double","D":"The company will be forced to pay higher corporation tax rates"},"correctOption":"B","correctAnswer":"Lower-quality materials may cause higher product defect rates, customer returns, and damage to brand reputation, ultimately hurting future sales","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cutting input costs improves unit margin only if product quality and customer loyalty are maintained.","distractor_reasons":{"A":"Incorrect because cheaper raw materials *lower* cost of sales.","B":"Option B is correct because cutting input costs improves unit margin only if product quality and customer loyalty are maintained.","C":"Incorrect because raw-material sourcing does not affect office rent.","D":"Incorrect because tax rates are set by statute."}}},{"id":"P1_U5_MCQ_986","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_986","question":"How can a business increase its 'profit margin (%)' without making any change to its 'gross profit margin (%)'?","options":{"A":"By raising product selling prices by 15%","B":"By negotiating cheaper wholesale prices on inventory for resale","C":"By reducing indirect overhead expenses (such as downsizing expensive head-office space or automating administrative paperwork)","D":"By holding larger amounts of closing inventory"},"correctOption":"C","correctAnswer":"By reducing indirect overhead expenses (such as downsizing expensive head-office space or automating administrative paperwork)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because indirect overheads sit between gross profit and operating profit; cutting overheads lifts profit margin while leaving gross profit margin unchanged.","distractor_reasons":{"A":"Incorrect because raising selling prices increases gross profit margin as well.","B":"Incorrect because cheaper inventory reduces cost of sales and raises gross profit margin.","C":"Option C is correct because indirect overheads sit between gross profit and operating profit; cutting overheads lifts profit margin while leaving gross profit margin unchanged.","D":"Incorrect because holding more inventory increases storage overheads."}}},{"id":"P1_U5_MCQ_987","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_987","question":"Over a single year, a manufacturer's 'gross profit margin' rises from 35% to 40%, yet its 'profit margin' falls from 14% to 9%. What is the most logical explanation?","options":{"A":"Direct production/material costs fell relative to sales, but indirect overhead expenses (such as heavy advertising campaigns or head-office salaries) increased even more sharply","B":"Sales revenue fell to zero during the year","C":"The company paid off all its non-current liabilities","D":"Current liabilities exceeded current assets"},"correctOption":"A","correctAnswer":"Direct production/material costs fell relative to sales, but indirect overhead expenses (such as heavy advertising campaigns or head-office salaries) increased even more sharply","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because gross profit margin reflects direct costs, whereas profit margin also reflects indirect overhead expenses.","distractor_reasons":{"A":"Option A is correct because gross profit margin reflects direct costs, whereas profit margin also reflects indirect overhead expenses.","B":"Incorrect because zero sales would eliminate both margins.","C":"Incorrect because paying off long-term debt reduces future interest rather than lowering operating profit margin.","D":"Incorrect because liquidity ratios do not cause gross and operating margins to diverge."}}},{"id":"P1_U5_MCQ_988","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_988","question":"Which action will directly improve BOTH a business's 'current ratio' and its 'acid-test ratio'?","options":{"A":"Buying extra raw materials on 30-day trade credit","B":"Using existing bank cash to buy a new freehold factory","C":"Selling surplus, unused non-current machinery for cash and keeping the cash in the bank account","D":"Paying cash dividends to ordinary shareholders"},"correctOption":"C","correctAnswer":"Selling surplus, unused non-current machinery for cash and keeping the cash in the bank account","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because selling a non-current asset for cash increases cash (raising both Current assets and Quick assets) without increasing current liabilities.","distractor_reasons":{"A":"Incorrect because buying inventory on credit raises inventories (excluded from acid-test) and raises current liabilities.","B":"Incorrect because spending cash on a building reduces cash and lowers both liquidity ratios.","C":"Option C is correct because selling a non-current asset for cash increases cash (raising both Current assets and Quick assets) without increasing current liabilities.","D":"Incorrect because paying cash dividends drains bank cash and lowers both liquidity ratios."}}},{"id":"P1_U5_MCQ_989","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_989","question":"Which action improves a retailer's 'acid-test ratio' while leaving its 'current ratio' completely unchanged?","options":{"A":"Buying $20,000 of new delivery vehicles for cash","B":"Taking out a $50,000 long-term bank loan","C":"Issuing $100,000 of new ordinary shares for cash","D":"Selling $15,000 of inventory at cost price for immediate cash"},"correctOption":"D","correctAnswer":"Selling $15,000 of inventory at cost price for immediate cash","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because swapping $15,000 of inventory for $15,000 of cash leaves total Current assets unchanged (same current ratio), while increasing quick assets (cash) in the acid-test ratio.","distractor_reasons":{"A":"Incorrect because spending cash on vehicles reduces *both* the current ratio and acid-test ratio.","B":"Incorrect because a long-term loan for cash increases *both* the current ratio and acid-test ratio.","C":"Incorrect because issuing shares for cash increases *both* the current ratio and acid-test ratio.","D":"Option D is correct because swapping $15,000 of inventory for $15,000 of cash leaves total Current assets unchanged (same current ratio), while increasing quick assets (cash) in the acid-test ratio."}}},{"id":"P1_U5_MCQ_990","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_990","question":"A business currently has $100,000 of current assets and $50,000 of current liabilities (a current ratio of 2.0 : 1). If it uses $20,000 of bank cash to pay off $20,000 of trade payables, what happens to its 'current ratio'?","options":{"A":"It stays at 2.0 : 1","B":"It rises to 2.67 : 1 ($80,000 / $30,000)","C":"It falls to 1.6 : 1","D":"It falls to 1.0 : 1"},"correctOption":"B","correctAnswer":"It rises to 2.67 : 1 ($80,000 / $30,000)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because subtracting $20,000 from both numerator and denominator changes the ratio from $100,000 / $50,000 (2.0 : 1) to $80,000 / $30,000 (2.67 : 1).","distractor_reasons":{"A":"Incorrect because working capital ($50,000) stays the same, but the *ratio* changes.","B":"Option B is correct because subtracting $20,000 from both numerator and denominator changes the ratio from $100,000 / $50,000 (2.0 : 1) to $80,000 / $30,000 (2.67 : 1).","C":"Incorrect because 1.6 : 1 divides $80,000 by the original $50,000 liabilities.","D":"Incorrect because $80,000 / $30,000 equals 2.67 : 1, not 1.0 : 1."}}},{"id":"P1_U5_MCQ_991","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_991","question":"Why can differences in 'accounting policies' between two competing companies distort an inter-firm comparison of 'profit margin' and 'ROCE'?","options":{"A":"Because one company may depreciate identical machinery faster or value inventories differently than its rival, altering reported operating profit and asset book values without any real difference in cash performance","B":"Because one company is legally allowed to omit sales revenue from its accounts","C":"Because limited companies are exempt from using double-entry bookkeeping","D":"Because accounting policies determine the government's interest rate"},"correctOption":"A","correctAnswer":"Because one company may depreciate identical machinery faster or value inventories differently than its rival, altering reported operating profit and asset book values without any real difference in cash performance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because legitimate differences in depreciation rates or inventory valuation methods affect accounting profit and capital employed.","distractor_reasons":{"A":"Option A is correct because legitimate differences in depreciation rates or inventory valuation methods affect accounting profit and capital employed.","B":"Incorrect because all companies must report full sales revenue.","C":"Incorrect because all companies use double-entry accounting.","D":"Incorrect because central banks set interest rates."}}},{"id":"P1_U5_MCQ_992","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_992","question":"Why should an analyst be cautious when comparing the liquidity ratios of two seasonal toy retailers if Retailer A prepares its accounts on 31 December and Retailer B prepares its accounts on 31 August?","options":{"A":"Because toy retailers never hold any inventory","B":"Because on 31 December Retailer A has just converted holiday stock into peak cash, whereas on 31 August Retailer B is holding maximum unsold inventory and short-term debt ahead of the holiday rush","C":"Because accounts prepared in August are legally invalid","D":"Because Retailer B is exempt from paying current liabilities"},"correctOption":"B","correctAnswer":"Because on 31 December Retailer A has just converted holiday stock into peak cash, whereas on 31 August Retailer B is holding maximum unsold inventory and short-term debt ahead of the holiday rush","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because different financial year-end dates capture seasonal businesses at completely different points in their working capital cycle.","distractor_reasons":{"A":"Incorrect because toy retailers hold substantial inventory prior to peak seasons.","B":"Option B is correct because different financial year-end dates capture seasonal businesses at completely different points in their working capital cycle.","C":"Incorrect because companies can choose different financial year-end dates.","D":"Incorrect because all businesses must settle current liabilities."}}},{"id":"P1_U5_MCQ_993","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_993","question":"How can high 'inflation' distort a five-year time-series analysis of a business's revenue and profit figures?","options":{"A":"Inflation makes dollar sales and profits appear to grow rapidly each year even if the actual physical volume of goods sold has stagnated or fallen","B":"Inflation reduces all nominal dollar revenue figures to zero","C":"Inflation automatically doubles the business's acid-test ratio","D":"Inflation eliminates all overhead expenses"},"correctOption":"A","correctAnswer":"Inflation makes dollar sales and profits appear to grow rapidly each year even if the actual physical volume of goods sold has stagnated or fallen","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising general price levels inflate nominal monetary figures over multi-year comparisons.","distractor_reasons":{"A":"Option A is correct because rising general price levels inflate nominal monetary figures over multi-year comparisons.","B":"Incorrect because inflation raises nominal prices rather than reducing revenue to zero.","C":"Incorrect because inflation does not double liquidity ratios.","D":"Incorrect because inflation increases nominal overhead costs."}}},{"id":"P1_U5_MCQ_994","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_994","question":"How do 'trade creditors (suppliers)' and 'shareholders' differ in the financial ratios they prioritize when analyzing a company's accounts?","options":{"A":"Both groups look solely at gross profit in dollars","B":"Suppliers focus only on ROCE, whereas shareholders focus only on the acid-test ratio","C":"Neither group ever looks at published financial statements","D":"Suppliers focus primarily on liquidity ratios (current and acid-test) to ensure their 30-day invoices will be paid, whereas shareholders focus primarily on profitability ratios (ROCE and profit margin) to assess long-term returns"},"correctOption":"D","correctAnswer":"Suppliers focus primarily on liquidity ratios (current and acid-test) to ensure their 30-day invoices will be paid, whereas shareholders focus primarily on profitability ratios (ROCE and profit margin) to assess long-term returns","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because each stakeholder group analyzes the ratios most relevant to its specific financial relationship with the business.","distractor_reasons":{"A":"Incorrect because raw dollar gross profit ignores scale, overheads, and short-term solvency.","B":"Incorrect because this reverses supplier and shareholder priorities.","C":"Incorrect because both groups rely heavily on financial ratio analysis.","D":"Option D is correct because each stakeholder group analyzes the ratios most relevant to its specific financial relationship with the business."}}},{"id":"P1_U5_MCQ_995","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_995","question":"A company issues $5 million of new ordinary shares in January to build a new factory that will not start producing goods until next year. Why will the company's 'ROCE' likely drop during the current year?","options":{"A":"Because building a factory reduces sales revenue from existing factories to zero","B":"Because issuing shares increases annual interest expenses","C":"Because capital employed (the denominator) increases immediately by $5 million, while the new factory has not yet generated any additional operating profit (the numerator)","D":"Because issuing shares increases current liabilities by $5 million"},"correctOption":"C","correctAnswer":"Because capital employed (the denominator) increases immediately by $5 million, while the new factory has not yet generated any additional operating profit (the numerator)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because long-term capital investments expand capital employed immediately while profit returns lag behind during construction and ramp-up.","distractor_reasons":{"A":"Incorrect because existing factories continue generating revenue.","B":"Incorrect because issuing shares is equity and incurs zero interest.","C":"Option C is correct because long-term capital investments expand capital employed immediately while profit returns lag behind during construction and ramp-up.","D":"Incorrect because issuing shares increases shareholders' equity, not current liabilities."}}},{"id":"P1_U5_MCQ_996","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_996","question":"A business reports a gross profit margin of 25% and revenue of $400,000. What was its cost of sales?","options":{"A":"$100,000","B":"$300,000","C":"$400,000","D":"$500,000"},"correctOption":"B","correctAnswer":"$300,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because gross profit is 25% of $400,000, or $100,000, so cost of sales is $400,000 minus $100,000 = $300,000.","distractor_reasons":{"B":"Option B is correct because gross profit is 25% of $400,000, or $100,000, so cost of sales is $400,000 minus $100,000 = $300,000.","A":"Incorrect because $100,000 is the gross profit itself, not the cost of sales that must be subtracted from revenue.","C":"Incorrect because $400,000 is the total revenue and includes both the cost of sales and the gross profit.","D":"Incorrect because $500,000 exceeds the revenue figure and cannot represent a cost deducted from that revenue."}}},{"id":"P1_U5_MCQ_997","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_997","question":"Why does a 'luxury diamond jeweler' typically report a high gross profit margin (e.g., 60%) and a high current ratio (e.g., 3.2 : 1), alongside a much lower acid-test ratio (e.g., 0.8 : 1)?","options":{"A":"Because luxury jewelers never hold any physical inventory","B":"Because luxury jewelers sell diamonds on 10-year interest-free credit","C":"Because luxury watches and diamonds carry high mark-ups but sit in display inventory for many months before selling, tying up most current assets in high-value stock","D":"Because luxury jewelers have zero overhead expenses"},"correctOption":"C","correctAnswer":"Because luxury watches and diamonds carry high mark-ups but sit in display inventory for many months before selling, tying up most current assets in high-value stock","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because industry business models shape normal ratio profiles: high-margin, slow-turning inventory creates a wide gap between current and acid-test ratios.","distractor_reasons":{"A":"Incorrect because jewelers hold high-value physical display stock.","B":"Incorrect because retail jewelers sell mostly at point of sale rather than 10-year receivables.","C":"Option C is correct because industry business models shape normal ratio profiles: high-margin, slow-turning inventory creates a wide gap between current and acid-test ratios.","D":"Incorrect because prime retail store rents and security overheads are substantial."}}},{"id":"P1_U5_MCQ_998","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_998","question":"A company reports an impressive ROCE of 22% and a profit margin of 16%, but its acid-test ratio has fallen to 0.45 : 1. What is the most accurate overall financial diagnosis?","options":{"A":"The company is unprofitable and inefficient, but has excess cash","B":"The company is highly profitable on its trading operations, but faces an acute short-term liquidity crisis that could force insolvency unless working capital is restructured","C":"The company is both unprofitable and insolvent","D":"The company has no current liabilities and no inventory"},"correctOption":"B","correctAnswer":"The company is highly profitable on its trading operations, but faces an acute short-term liquidity crisis that could force insolvency unless working capital is restructured","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because evaluating profitability and liquidity together exposes profitable firms suffering from severe cash tightness.","distractor_reasons":{"A":"Incorrect because 22% ROCE and 16% profit margin show strong profitability, while 0.45 : 1 shows a cash shortage.","B":"Option B is correct because evaluating profitability and liquidity together exposes profitable firms suffering from severe cash tightness.","C":"Incorrect because the company is clearly profitable.","D":"Incorrect because a 0.45 : 1 acid-test ratio implies substantial current liabilities relative to liquid assets."}}},{"id":"P1_U5_MCQ_999","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_999","question":"What role do independent 'external auditors' play in supporting the reliability of financial ratio analysis for public limited companies?","options":{"A":"They inspect accounting records and financial statements to verify that the figures present a 'true and fair view' in accordance with accounting standards","B":"They guarantee that the company's share price will rise next year","C":"They lend money to the company whenever its current ratio drops below 1 : 1","D":"They set the company's selling prices and marketing budget"},"correctOption":"A","correctAnswer":"They inspect accounting records and financial statements to verify that the figures present a 'true and fair view' in accordance with accounting standards","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ratio analysis is only as trustworthy as the underlying financial statements; external audits deter fraud and material misstatements.","distractor_reasons":{"A":"Option A is correct because ratio analysis is only as trustworthy as the underlying financial statements; external audits deter fraud and material misstatements.","B":"Incorrect because auditors verify historical statements rather than guaranteeing stock market performance.","C":"Incorrect because auditors are independent accountants, not commercial lenders.","D":"Incorrect because operational pricing and marketing belong to management."}}},{"id":"P1_U5_MCQ_1000","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1000","question":"A business has current assets of $120,000 and current liabilities of $60,000. What is its current ratio?","options":{"A":"0.5:1","B":"1:1","C":"2:1","D":"3:1"},"correctOption":"C","correctAnswer":"2:1","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the current ratio is current assets divided by current liabilities, $120,000/$60,000 = 2:1.","distractor_reasons":{"C":"Option C is correct because the current ratio is current assets divided by current liabilities, $120,000/$60,000 = 2:1.","A":"Incorrect because 0.5:1 would result from dividing current liabilities by current assets, which reverses the correct formula.","B":"Incorrect because a 1:1 ratio would require current assets and current liabilities to be equal, which they are not.","D":"Incorrect because 3:1 would require current assets of $180,000 with liabilities of $60,000, not the figures given."}}},{"id":"P1_U5_MCQ_1001","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1001","question":"Brightwell Bakery has earned steady profits for six years and now needs $40,000 to refit its shop. The owner wants finance that does not increase the bakery's debts or dilute her control. Which source of finance best matches these requirements?","options":{"A":"Retained profit held in the business","B":"A bank overdraft repayable on demand","C":"A five-year bank loan secured on the shop","D":"Issuing new shares to outside investors"},"correctOption":"A","correctAnswer":"Retained profit held in the business","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is internal finance built up from earlier profits, so the $40,000 refit adds no debt and brings in no new shareholder to dilute the owner's control.","distractor_reasons":{"A":"Retained profit is internal finance built up from earlier profits, so the $40,000 refit adds no debt and brings in no new shareholder to dilute the owner's control.","B":"An overdraft is borrowed money repayable on demand, so it increases the bakery's debts and may carry a high variable interest charge.","C":"A secured loan is external debt, so it would increase the bakery's liabilities and require regular interest payments over five years.","D":"Selling shares to outsiders brings in new part-owners, which dilutes the owner's control rather than protecting it."}}},{"id":"P1_U5_MCQ_1002","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1002","question":"Colmere Timber forecasts cash receipts of $84,000 and cash payments of $71,500 for March. The opening bank balance is $12,000. What is the forecast net cash flow for March?","options":{"A":"$2,500","B":"$12,500","C":"$24,500","D":"$155,500"},"correctOption":"B","correctAnswer":"$12,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is total inflows minus total outflows, so $84,000 receipts less $71,500 payments gives a forecast net inflow of $12,500 for March.","distractor_reasons":{"A":"$2,500 does not come from the figures given: it would need receipts of about $74,000 with payments of $71,500.","B":"Net cash flow is total inflows minus total outflows, so $84,000 receipts less $71,500 payments gives a forecast net inflow of $12,500 for March.","C":"$24,500 wrongly adds the $12,000 opening balance to the net cash flow instead of leaving it out of the net figure.","D":"$155,500 wrongly adds receipts and payments together rather than subtracting payments from receipts."}}},{"id":"P1_U5_MCQ_1003","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1003","question":"Driftway Couriers reports revenue of $180,000 for the year and cost of sales of $112,000. Its operating expenses were $41,000. What is the gross profit for the year?","options":{"A":"$27,000","B":"$41,000","C":"$68,000","D":"$292,000"},"correctOption":"C","correctAnswer":"$68,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales only, so $180,000 less $112,000 gives $68,000 before the $41,000 of operating expenses is deducted.","distractor_reasons":{"A":"$27,000 is the profit for the year after deducting the $41,000 operating expenses, not the gross profit.","B":"$41,000 is simply the operating expenses figure from the accounts and is not a profit figure.","C":"Gross profit is revenue minus cost of sales only, so $180,000 less $112,000 gives $68,000 before the $41,000 of operating expenses is deducted.","D":"$292,000 wrongly adds revenue and cost of sales instead of subtracting cost of sales from revenue."}}},{"id":"P1_U5_MCQ_1004","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1004","question":"Eastgate Furniture has current assets of $84,000, including inventory of $31,000, and current liabilities of $52,000 at the year end. What is the working capital of the business?","options":{"A":"$31,000","B":"$53,000","C":"$21,000","D":"$32,000"},"correctOption":"D","correctAnswer":"$32,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital equals current assets minus current liabilities, so $84,000 less $52,000 leaves $32,000 available to run day-to-day operations.","distractor_reasons":{"A":"$31,000 is the inventory figure alone, which is only one part of current assets and not working capital.","B":"$53,000 wrongly subtracts the $31,000 inventory from the $84,000 current assets instead of using current liabilities.","C":"$21,000 wrongly subtracts inventory of $31,000 from current liabilities of $52,000, which is not the working capital formula.","D":"Working capital equals current assets minus current liabilities, so $84,000 less $52,000 leaves $32,000 available to run day-to-day operations."}}},{"id":"P1_U5_MCQ_1005","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1005","question":"Fenwick Printing has current assets of $144,000 and current liabilities of $60,000 at the end of its financial year. What is the current ratio of the business?","options":{"A":"2.4:1","B":"0.4:1","C":"1.4:1","D":"4.8:1"},"correctOption":"A","correctAnswer":"2.4:1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets divided by current liabilities, so $144,000 divided by $60,000 gives 2.4:1, meaning $2.40 of current assets for each $1 of current liabilities.","distractor_reasons":{"A":"The current ratio is current assets divided by current liabilities, so $144,000 divided by $60,000 gives 2.4:1, meaning $2.40 of current assets for each $1 of current liabilities.","B":"0.4:1 comes from dividing current liabilities by current assets, which reverses the correct formula.","C":"1.4:1 would require current assets of $84,000 with liabilities of $60,000, which is not the position shown.","D":"4.8:1 wrongly doubles the correct answer and does not follow from the $144,000 and $60,000 figures."}}},{"id":"P1_U5_MCQ_1006","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1006","question":"Glenhurst Hotels needs an extra $15,000 for eight weeks to cover wages before the summer bookings are paid. The finance will be repaid as soon as the guests pay. Which source of short-term finance is most suitable?","options":{"A":"Issuing ordinary shares to the public","B":"A bank overdraft","C":"A ten-year bank loan","D":"A mortgage on the hotel building"},"correctOption":"B","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"An overdraft is flexible short-term finance that can cover the eight-week wage gap and be cleared when the summer bookings are paid, so interest is only paid while it is used.","distractor_reasons":{"A":"Issuing shares raises permanent capital and is far too slow and costly for a temporary eight-week cash shortage.","B":"An overdraft is flexible short-term finance that can cover the eight-week wage gap and be cleared when the summer bookings are paid, so interest is only paid while it is used.","C":"A ten-year loan is long-term debt, so the hotel would pay interest for years after the eight-week need has passed.","D":"A mortgage is secured long-term borrowing against property, which is unsuitable for a small temporary wage gap."}}},{"id":"P1_U5_MCQ_1007","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1007","question":"Hartley Clinics expects opening cash of $9,400 in April, receipts of $62,000 and payments of $58,300 during the month. What is the forecast closing cash balance at the end of April?","options":{"A":"$3,700","B":"$9,400","C":"$13,100","D":"$71,400"},"correctOption":"C","correctAnswer":"$13,100","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $62,000 less $58,300, a $3,700 inflow, and adding this to the $9,400 opening balance gives a closing balance of $13,100.","distractor_reasons":{"A":"$3,700 is only the net cash flow for April and ignores the $9,400 already held at the start.","B":"$9,400 is the opening balance and takes no account of the receipts and payments during April.","C":"Net cash flow is $62,000 less $58,300, a $3,700 inflow, and adding this to the $9,400 opening balance gives a closing balance of $13,100.","D":"$71,400 adds the opening balance to receipts without deducting the $58,300 of payments."}}},{"id":"P1_U5_MCQ_1008","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1008","question":"Inglewood Fitness recorded gross profit of $54,000 for the year. Its operating expenses were $39,500 and it paid no interest. What was the profit for the year?","options":{"A":"$93,500","B":"$54,000","C":"$39,500","D":"$14,500"},"correctOption":"D","correctAnswer":"$14,500","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is gross profit minus expenses, so $54,000 less $39,500 gives $14,500, and no interest was paid to reduce it further.","distractor_reasons":{"A":"$93,500 wrongly adds gross profit and expenses together instead of deducting expenses from gross profit.","B":"$54,000 is the gross profit and still includes the $39,500 of operating expenses that must be subtracted.","C":"$39,500 is the expense figure and is not a measure of profit for the year.","D":"Profit for the year is gross profit minus expenses, so $54,000 less $39,500 gives $14,500, and no interest was paid to reduce it further."}}},{"id":"P1_U5_MCQ_1009","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1009","question":"Jarrow Solar's statement of financial position shows inventory of $24,000, trade receivables of $18,000, cash of $6,000 and current liabilities of $29,000. What is the total value of current assets?","options":{"A":"$48,000","B":"$19,000","C":"$77,000","D":"$29,000"},"correctOption":"A","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Current assets are added together, so inventory of $24,000 plus receivables of $18,000 plus cash of $6,000 gives total current assets of $48,000.","distractor_reasons":{"A":"Current assets are added together, so inventory of $24,000 plus receivables of $18,000 plus cash of $6,000 gives total current assets of $48,000.","B":"$19,000 subtracts cash and something else from the other current assets rather than adding all three together.","C":"$77,000 wrongly adds the current liabilities of $29,000 to the current assets instead of leaving them out.","D":"$29,000 is the current liabilities figure, which is a claim on the business rather than an asset."}}},{"id":"P1_U5_MCQ_1010","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1010","question":"Kestrel Recycling has current assets of $96,000, of which inventory is $30,000, and current liabilities of $44,000 at the end of the year. What is the acid-test ratio?","options":{"A":"2.2:1","B":"1.5:1","C":"0.7:1","D":"1.2:1"},"correctOption":"B","correctAnswer":"1.5:1","questionType":"MCQ","explanation":{"correct_reason":"The acid-test ratio removes inventory from current assets, so $96,000 less $30,000 gives $66,000, and dividing by $44,000 of current liabilities gives 1.5:1.","distractor_reasons":{"A":"2.2:1 is the current ratio, which includes the $30,000 of inventory that the acid-test ratio must exclude.","B":"The acid-test ratio removes inventory from current assets, so $96,000 less $30,000 gives $66,000, and dividing by $44,000 of current liabilities gives 1.5:1.","C":"0.7:1 wrongly divides the inventory figure by current liabilities instead of the liquid current assets.","D":"1.2:1 does not follow from the figures given and appears to use a different current liabilities total."}}},{"id":"P1_U5_MCQ_1011","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1011","question":"Larkmead Dairy is a public limited company planning a $2 million expansion of its processing plant. It wants permanent finance and is willing to accept new shareholders. Which source of finance is most suitable?","options":{"A":"A short-term bank overdraft","B":"Trade credit from suppliers","C":"Issuing additional ordinary shares","D":"Retained profit from the current year"},"correctOption":"C","correctAnswer":"Issuing additional ordinary shares","questionType":"MCQ","explanation":{"correct_reason":"A public limited company can issue ordinary shares to raise large sums of permanent capital for the $2 million plant, and the new shareholders accept the risk of ownership.","distractor_reasons":{"A":"An overdraft is short-term and repayable on demand, so it cannot fund a permanent $2 million plant expansion.","B":"Trade credit only delays payment for goods bought and cannot raise $2 million of long-term investment capital.","C":"A public limited company can issue ordinary shares to raise large sums of permanent capital for the $2 million plant, and the new shareholders accept the risk of ownership.","D":"One year's retained profit is unlikely to reach $2 million and could not be relied on for a project of this size."}}},{"id":"P1_U5_MCQ_1012","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1012","question":"Mossgrove Fashion forecasts an opening bank balance of $6,200, cash inflows of $45,000 and cash outflows of $54,000 for May. What is the forecast closing bank balance?","options":{"A":"$2,800","B":"$9,000","C":"$15,200","D":"-$2,800"},"correctOption":"D","correctAnswer":"-$2,800","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $45,000 less $54,000, a $9,000 outflow, and taking this from the $6,200 opening balance leaves an overdrawn closing balance of -$2,800.","distractor_reasons":{"A":"$2,800 ignores the minus sign, but spending more than the opening balance plus receipts leaves the account overdrawn.","B":"$9,000 is the net cash flow only and does not include the $6,200 already in the bank at the start.","C":"$15,200 wrongly adds the $9,000 outflow to the opening balance instead of subtracting it.","D":"Net cash flow is $45,000 less $54,000, a $9,000 outflow, and taking this from the $6,200 opening balance leaves an overdrawn closing balance of -$2,800."}}},{"id":"P1_U5_MCQ_1013","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1013","question":"Northbury Toys had opening inventory of $18,000 and purchases of $96,000 during the year. Closing inventory was valued at $21,000. What was the cost of sales for the year?","options":{"A":"$93,000","B":"$99,000","C":"$135,000","D":"$117,000"},"correctOption":"A","correctAnswer":"$93,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is opening inventory plus purchases minus closing inventory, so $18,000 plus $96,000 less $21,000 gives $93,000.","distractor_reasons":{"A":"Cost of sales is opening inventory plus purchases minus closing inventory, so $18,000 plus $96,000 less $21,000 gives $93,000.","B":"$99,000 wrongly adds the $21,000 closing inventory instead of subtracting it from goods available for sale.","C":"$135,000 adds opening inventory, purchases and closing inventory together, which double counts the stock held.","D":"$117,000 is opening inventory plus purchases before any adjustment for the closing inventory."}}},{"id":"P1_U5_MCQ_1014","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1014","question":"Oakhill Cycles reports non-current assets of $320,000, current assets of $96,000 and current liabilities of $58,000. It has no long-term loans. What is its capital employed?","options":{"A":"$416,000","B":"$358,000","C":"$262,000","D":"$474,000"},"correctOption":"B","correctAnswer":"$358,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed equals non-current assets plus working capital, so $320,000 plus ($96,000 less $58,000) gives $358,000, which is also total assets minus current liabilities.","distractor_reasons":{"A":"$416,000 adds non-current and current assets but forgets to deduct the $58,000 of current liabilities.","B":"Capital employed equals non-current assets plus working capital, so $320,000 plus ($96,000 less $58,000) gives $358,000, which is also total assets minus current liabilities.","C":"$262,000 wrongly deducts the current liabilities from non-current assets alone and ignores current assets.","D":"$474,000 adds all three figures together instead of treating current liabilities as a deduction."}}},{"id":"P1_U5_MCQ_1015","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1015","question":"Penvale Catering earned gross profit of $84,000 on revenue of $240,000 last year, while operating expenses were $52,000 in the same period. What was its gross profit margin?","options":{"A":"15%","B":"21.7%","C":"35%","D":"65%"},"correctOption":"C","correctAnswer":"35%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit divided by revenue multiplied by 100, so $84,000 divided by $240,000 gives 35%.","distractor_reasons":{"A":"15% is the profit margin after operating expenses, not the gross profit margin based on $84,000.","B":"21.7% is the operating expenses of $52,000 expressed as a percentage of revenue, not the gross margin.","C":"Gross profit margin is gross profit divided by revenue multiplied by 100, so $84,000 divided by $240,000 gives 35%.","D":"65% is cost of sales as a percentage of revenue, which is the complement of the gross margin, not the margin itself."}}},{"id":"P1_U5_MCQ_1016","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1016","question":"Quarrystone Nurseries borrows $60,000 from its bank for one year at a fixed interest rate of 8% a year. The loan is repaid in full at the end of the year. How much interest will the business pay?","options":{"A":"$480","B":"$600","C":"$7,500","D":"$4,800"},"correctOption":"D","correctAnswer":"$4,800","questionType":"MCQ","explanation":{"correct_reason":"Interest is the loan multiplied by the annual rate, so $60,000 times 0.08 gives $4,800 of interest for the one-year loan.","distractor_reasons":{"A":"$480 is one tenth of the correct figure and would need an interest rate of about 0.8%, not 8%.","B":"$600 would need an interest rate of about 1% on the $60,000 borrowed, far below the stated 8%.","C":"$7,500 is 12.5% of the loan, not the 8% rate charged by the bank.","D":"Interest is the loan multiplied by the annual rate, so $60,000 times 0.08 gives $4,800 of interest for the one-year loan."}}},{"id":"P1_U5_MCQ_1017","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1017","question":"Redmoor Marine's cash flow forecast shows sales receipts of $40,000, $46,000 and $52,000 for the next three months. It also expects to receive a bank loan of $30,000 in the first month. What are the total forecast inflows?","options":{"A":"$168,000","B":"$138,000","C":"$198,000","D":"$30,000"},"correctOption":"A","correctAnswer":"$168,000","questionType":"MCQ","explanation":{"correct_reason":"All cash coming in counts as an inflow, so $40,000 plus $46,000 plus $52,000 plus the $30,000 loan gives $168,000.","distractor_reasons":{"A":"All cash coming in counts as an inflow, so $40,000 plus $46,000 plus $52,000 plus the $30,000 loan gives $168,000.","B":"$138,000 adds only the three months of sales receipts and leaves out the $30,000 bank loan.","C":"$198,000 double counts the $30,000 loan by adding it to a total that already includes it.","D":"$30,000 is only the loan received and ignores the sales receipts from customers."}}},{"id":"P1_U5_MCQ_1018","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1018","question":"Salterton Packaging had revenue of $240,000, opening inventory of $25,000, purchases of $130,000 and closing inventory of $20,000. It had no other cost of sales. What was its gross profit?","options":{"A":"$135,000","B":"$105,000","C":"$85,000","D":"$155,000"},"correctOption":"B","correctAnswer":"$105,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is $25,000 plus $130,000 less $20,000, which is $135,000, so gross profit is $240,000 less $135,000, giving $105,000.","distractor_reasons":{"A":"$135,000 is the cost of sales figure and still has to be subtracted from revenue to find gross profit.","B":"Cost of sales is $25,000 plus $130,000 less $20,000, which is $135,000, so gross profit is $240,000 less $135,000, giving $105,000.","C":"$85,000 does not follow from these figures and appears to deduct purchases twice.","D":"$155,000 wrongly adds the closing inventory of $20,000 to cost of sales instead of subtracting it."}}},{"id":"P1_U5_MCQ_1019","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1019","question":"Thornbeck Metals has current assets of $60,000 and current liabilities of $35,000. It then buys inventory worth $8,000 on three months' credit. What is the working capital immediately after this purchase?","options":{"A":"$33,000","B":"$17,000","C":"$25,000","D":"$28,000"},"correctOption":"C","correctAnswer":"$25,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital was $60,000 less $35,000, and buying inventory on credit adds $8,000 to both current assets and current liabilities, so it stays at $25,000.","distractor_reasons":{"A":"$33,000 adds the $8,000 to working capital even though the matching rise in current liabilities cancels the effect.","B":"$17,000 deducts the $8,000 twice, once from assets and again by adding it to liabilities.","C":"Working capital was $60,000 less $35,000, and buying inventory on credit adds $8,000 to both current assets and current liabilities, so it stays at $25,000.","D":"$28,000 results from treating the credit purchase as if it increased assets without increasing liabilities."}}},{"id":"P1_U5_MCQ_1020","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1020","question":"Uplands Chemicals made a profit for the year of $27,000 on revenue of $180,000. Its gross profit was $63,000. What was its profit margin for the year?","options":{"A":"35%","B":"63%","C":"27%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year divided by revenue, so $27,000 divided by $180,000 multiplied by 100 gives 15%.","distractor_reasons":{"A":"35% is the gross profit margin using $63,000, not the profit margin based on $27,000.","B":"63% is the gross profit figure in thousands and is not a percentage calculation at all.","C":"27% uses the profit figure of $27,000 as if it were already a percentage of revenue.","D":"Profit margin is profit for the year divided by revenue, so $27,000 divided by $180,000 multiplied by 100 gives 15%."}}},{"id":"P1_U5_MCQ_1021","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1021","question":"Valebrook Software is a small private limited company that needs $90,000 of new finance. Which statement best explains why it may find it difficult to raise this money by issuing shares to the public?","options":{"A":"Selling shares to the public requires a stock market listing, which is costly and needs a long trading record","B":"Private limited companies are legally banned from having any shareholders","C":"Shares can only be sold to commercial banks, which rarely buy them","D":"Share capital has to be repaid to shareholders after five years"},"correctOption":"A","correctAnswer":"Selling shares to the public requires a stock market listing, which is costly and needs a long trading record","questionType":"MCQ","explanation":{"correct_reason":"A public share issue requires a costly stock market listing and a substantial trading record, so a small company needing $90,000 cannot easily use this route.","distractor_reasons":{"A":"A public share issue requires a costly stock market listing and a substantial trading record, so a small company needing $90,000 cannot easily use this route.","B":"Private limited companies do have shareholders; they are simply restricted in how shares may be offered to the public.","C":"Shares are bought by investors, not by commercial banks, so this does not explain the difficulty.","D":"Share capital is permanent and is not repaid after five years, unlike a loan."}}},{"id":"P1_U5_MCQ_1022","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1022","question":"Dunton Logistics reports a profit of $28,000 for the year, yet its bank balance fell by $9,000. Which explanation is the most likely cause of this situation?","options":{"A":"Profit and cash are always the same figure in a cash flow forecast","B":"The business sold on credit and repaid a large loan, so cash left before customers paid","C":"Depreciation reduced the bank balance by the same amount as the profit","D":"The business must have made a loss on every single sale it made"},"correctOption":"B","correctAnswer":"The business sold on credit and repaid a large loan, so cash left before customers paid","questionType":"MCQ","explanation":{"correct_reason":"Profit records sales when they are made, but credit customers pay later, and repaying a large loan takes cash out, so the $28,000 profit can coexist with a $9,000 fall in the bank balance.","distractor_reasons":{"A":"Profit and cash are not the same because profit uses credit transactions while cash flow records actual money movements.","B":"Profit records sales when they are made, but credit customers pay later, and repaying a large loan takes cash out, so the $28,000 profit can coexist with a $9,000 fall in the bank balance.","C":"Depreciation is a non-cash expense, so it reduces profit but never reduces the bank balance.","D":"A reported profit of $28,000 rules out making a loss on every sale, so this cannot be the cause."}}},{"id":"P1_U5_MCQ_1023","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1023","question":"Elversfield Water has gross profit of $90,000, operating expenses of $62,000 and interest payable on a bank loan of $9,000. What is its profit for the year?","options":{"A":"$28,000","B":"$90,000","C":"$19,000","D":"$37,000"},"correctOption":"C","correctAnswer":"$19,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year deducts both operating expenses and interest, so $90,000 less $62,000 less $9,000 gives $19,000.","distractor_reasons":{"A":"$28,000 deducts only the operating expenses and forgets the $9,000 of interest payable.","B":"$90,000 is the gross profit before any expenses or interest have been deducted.","C":"Profit for the year deducts both operating expenses and interest, so $90,000 less $62,000 less $9,000 gives $19,000.","D":"$37,000 deducts only the interest and ignores the much larger operating expenses."}}},{"id":"P1_U5_MCQ_1024","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1024","question":"Foxbury Mining has current assets of $45,000 and current liabilities of $60,000 at its year end. What does this show about the size and sign of its working capital?","options":{"A":"$15,000","B":"$105,000","C":"$45,000","D":"-$15,000"},"correctOption":"D","correctAnswer":"-$15,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is $45,000 of current assets less $60,000 of current liabilities, which is a negative figure of -$15,000, showing short-term debts exceed short-term assets.","distractor_reasons":{"A":"$15,000 gives the right size but the wrong sign, hiding the fact that liabilities exceed current assets.","B":"$105,000 adds current assets and current liabilities instead of subtracting one from the other.","C":"$45,000 is the current assets figure alone and takes no account of the $60,000 owed in the short term.","D":"Working capital is $45,000 of current assets less $60,000 of current liabilities, which is a negative figure of -$15,000, showing short-term debts exceed short-term assets."}}},{"id":"P1_U5_MCQ_1025","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1025","question":"Goldcrest Coaches reports operating profit of $45,000 for the year and capital employed of $300,000 at the year end. What is its return on capital employed?","options":{"A":"15%","B":"6.7%","C":"45%","D":"4.5%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, so $45,000 divided by $300,000 multiplied by 100 gives 15%.","distractor_reasons":{"A":"Return on capital employed is operating profit divided by capital employed, so $45,000 divided by $300,000 multiplied by 100 gives 15%.","B":"6.7% divides capital employed by operating profit, which reverses the correct formula.","C":"45% treats the profit figure of $45,000 as if it were already a percentage of capital employed.","D":"4.5% misplaces the decimal point and does not follow from dividing $45,000 by $300,000."}}},{"id":"P1_U5_MCQ_1026","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1026","question":"Havenport Ferries buys fuel from a supplier that allows 30 days before payment is due. Which source of finance is the ferry company using when it delays payment until day 30?","options":{"A":"A bank overdraft","B":"Trade credit","C":"Retained profit","D":"A mortgage"},"correctOption":"B","correctAnswer":"Trade credit","questionType":"MCQ","explanation":{"correct_reason":"Trade credit is the delay a supplier allows before payment is due, so using the full 30 days gives the ferry company short-term finance from its fuel supplier.","distractor_reasons":{"A":"An overdraft is finance from a bank, not extra time to pay a supplier for fuel already delivered.","B":"Trade credit is the delay a supplier allows before payment is due, so using the full 30 days gives the ferry company short-term finance from its fuel supplier.","C":"Retained profit is money kept from earlier profits and is not created by waiting 30 days to pay a supplier.","D":"A mortgage is a long-term loan secured on property and has nothing to do with supplier payment terms."}}},{"id":"P1_U5_MCQ_1027","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1027","question":"Ironstone Engineering forecasts a closing balance of $4,000. It had planned to pay $15,000 cash for a machine in the same month but now delays the purchase. What is the revised forecast closing balance?","options":{"A":"$4,000","B":"$11,000","C":"$19,000","D":"-$11,000"},"correctOption":"C","correctAnswer":"$19,000","questionType":"MCQ","explanation":{"correct_reason":"Delaying the $15,000 cash payment removes that outflow, so the closing balance rises from $4,000 to $19,000.","distractor_reasons":{"A":"$4,000 is the original forecast and ignores the $15,000 payment that is no longer made.","B":"$11,000 wrongly subtracts the $15,000 machine payment instead of adding it back to the closing balance.","C":"Delaying the $15,000 cash payment removes that outflow, so the closing balance rises from $4,000 to $19,000.","D":"-$11,000 treats the delayed payment as an extra outflow, which is the opposite of what happens."}}},{"id":"P1_U5_MCQ_1028","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1028","question":"Juniper Restaurants made a profit before tax of $40,000 in the year. Corporation tax is charged at 22% of profit. What is the profit for the year after tax?","options":{"A":"$8,800","B":"$48,800","C":"$22,000","D":"$31,200"},"correctOption":"D","correctAnswer":"$31,200","questionType":"MCQ","explanation":{"correct_reason":"Tax is 22% of $40,000, which is $8,800, so subtracting this from the profit before tax leaves $31,200 as the profit for the year.","distractor_reasons":{"A":"$8,800 is the tax charge itself, not the profit that remains after tax has been paid.","B":"$48,800 adds the tax to the profit instead of deducting it from profit before tax.","C":"$22,000 confuses the 22% tax rate with a cash amount and is not derived from the figures.","D":"Tax is 22% of $40,000, which is $8,800, so subtracting this from the profit before tax leaves $31,200 as the profit for the year."}}},{"id":"P1_U5_MCQ_1029","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1029","question":"Kirkstone Brewing has non-current assets of $480,000 and current assets of $140,000. Its current liabilities are $70,000. What is the total value of its assets?","options":{"A":"$620,000","B":"$550,000","C":"$340,000","D":"$690,000"},"correctOption":"A","correctAnswer":"$620,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are non-current assets plus current assets, so $480,000 plus $140,000 gives $620,000, and current liabilities are not deducted.","distractor_reasons":{"A":"Total assets are non-current assets plus current assets, so $480,000 plus $140,000 gives $620,000, and current liabilities are not deducted.","B":"$550,000 wrongly deducts the $70,000 of current liabilities, which gives capital employed rather than total assets.","C":"$340,000 subtracts both current assets and current liabilities from non-current assets without any basis.","D":"$690,000 adds the $70,000 of current liabilities to total assets, but liabilities are not assets."}}},{"id":"P1_U5_MCQ_1030","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1030","question":"Longacre Vineyards has current assets of $72,000, including inventory of $24,000, and current liabilities of $40,000 at the year end. What is its acid-test ratio?","options":{"A":"1.8:1","B":"1.2:1","C":"0.6:1","D":"2.4:1"},"correctOption":"B","correctAnswer":"1.2:1","questionType":"MCQ","explanation":{"correct_reason":"Liquid current assets are $72,000 less $24,000 of inventory, which is $48,000, and dividing by $40,000 of current liabilities gives 1.2:1.","distractor_reasons":{"A":"1.8:1 is the current ratio, because it includes the $24,000 of inventory that the acid-test ratio excludes.","B":"Liquid current assets are $72,000 less $24,000 of inventory, which is $48,000, and dividing by $40,000 of current liabilities gives 1.2:1.","C":"0.6:1 wrongly divides the inventory figure by current liabilities instead of using the liquid assets.","D":"2.4:1 uses only the inventory and cash position and does not follow from the totals given."}}},{"id":"P1_U5_MCQ_1031","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1031","question":"Millbrook Fisheries borrows $150,000 for three years at a simple interest rate of 6% a year. No capital is repaid until the end of the three years. What is the total interest paid?","options":{"A":"$9,000","B":"$18,000","C":"$27,000","D":"$159,000"},"correctOption":"C","correctAnswer":"$27,000","questionType":"MCQ","explanation":{"correct_reason":"Annual interest is 6% of $150,000, which is $9,000, and over three years the total interest is $9,000 multiplied by three, giving $27,000.","distractor_reasons":{"A":"$9,000 is only one year of interest and ignores the other two years of the three-year loan.","B":"$18,000 covers only two years of interest, so it understates the total for the full three-year period.","C":"Annual interest is 6% of $150,000, which is $9,000, and over three years the total interest is $9,000 multiplied by three, giving $27,000.","D":"$159,000 adds the interest to the loan principal, which is the repayment total rather than the interest alone."}}},{"id":"P1_U5_MCQ_1032","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1032","question":"Netherby Poultry starts June with an overdraft of $3,500. Forecast receipts for June are $41,000 and forecast payments are $32,800. What is the forecast closing balance?","options":{"A":"-$12,300","B":"$8,200","C":"$3,500","D":"$4,700"},"correctOption":"D","correctAnswer":"$4,700","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $41,000 less $32,800, which is $8,200, and clearing the $3,500 overdraft from that leaves a positive closing balance of $4,700.","distractor_reasons":{"A":"-$12,300 treats the overdraft as an addition to the outflow instead of something cleared by the inflow.","B":"$8,200 is the net cash flow for June and ignores the $3,500 overdraft that must be repaid first.","C":"$3,500 is the opening overdraft and takes no account of the receipts and payments during June.","D":"Net cash flow is $41,000 less $32,800, which is $8,200, and clearing the $3,500 overdraft from that leaves a positive closing balance of $4,700."}}},{"id":"P1_U5_MCQ_1033","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1033","question":"Oldcastle Interiors had revenue of $200,000 and cost of sales of $120,000. It cuts all prices by 10% and sells the same quantity, so cost of sales is unchanged. What is the new gross profit?","options":{"A":"$60,000","B":"$80,000","C":"$72,000","D":"$100,000"},"correctOption":"A","correctAnswer":"$60,000","questionType":"MCQ","explanation":{"correct_reason":"A 10% price cut reduces revenue to $180,000, and with cost of sales still $120,000 the new gross profit is $60,000.","distractor_reasons":{"A":"A 10% price cut reduces revenue to $180,000, and with cost of sales still $120,000 the new gross profit is $60,000.","B":"$80,000 is the original gross profit before the price cut is taken into account.","C":"$72,000 wrongly cuts the gross profit by 10% instead of recalculating it from the reduced revenue.","D":"$100,000 assumes the price rise increased revenue and leaves cost of sales out of the calculation."}}},{"id":"P1_U5_MCQ_1034","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1034","question":"Primrose Kitchens has current assets of $72,000 and current liabilities of $44,000. It then pays a supplier $10,000 in cash. What is its working capital immediately afterwards?","options":{"A":"$38,000","B":"$28,000","C":"$18,000","D":"$34,000"},"correctOption":"B","correctAnswer":"$28,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital was $28,000, and paying a supplier in cash cuts current assets and current liabilities by the same $10,000, so it stays at $28,000.","distractor_reasons":{"A":"$38,000 deducts the $10,000 twice, from assets and again from the resulting working capital.","B":"Working capital was $28,000, and paying a supplier in cash cuts current assets and current liabilities by the same $10,000, so it stays at $28,000.","C":"$18,000 assumes the payment reduces working capital by $10,000, ignoring the equal fall in liabilities.","D":"$34,000 adds the $10,000 to working capital even though cash has left the business."}}},{"id":"P1_U5_MCQ_1035","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1035","question":"Quillfield Lighting had revenue of $300,000 and cost of sales of $195,000 last year. Its operating expenses were $72,000. What was its gross profit margin?","options":{"A":"30%","B":"24%","C":"35%","D":"65%"},"correctOption":"C","correctAnswer":"35%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $300,000 less $195,000, which is $105,000, and dividing this by revenue of $300,000 gives a gross profit margin of 35%.","distractor_reasons":{"A":"30% is the profit margin after the $72,000 operating expenses, not the gross profit margin.","B":"24% is the operating expenses expressed as a percentage of revenue and is not a profit margin.","C":"Gross profit is $300,000 less $195,000, which is $105,000, and dividing this by revenue of $300,000 gives a gross profit margin of 35%.","D":"65% is cost of sales as a percentage of revenue, which is the complement of the gross margin."}}},{"id":"P1_U5_MCQ_1036","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1036","question":"Ravenswood Textiles needs a new loom costing $120,000 but wants to avoid a large payment now and expects the technology to change within three years. Which source of finance best suits this need?","options":{"A":"A 15-year bank loan","B":"Issuing ordinary shares","C":"Using retained profit to buy the loom outright","D":"Leasing the loom"},"correctOption":"D","correctAnswer":"Leasing the loom","questionType":"MCQ","explanation":{"correct_reason":"Leasing avoids a large immediate payment and spreads the cost over the period of use, which suits equipment that may be outdated within three years.","distractor_reasons":{"A":"A 15-year loan commits the business to debt and interest long after the loom may have become obsolete.","B":"Issuing shares raises permanent capital and is a slow, costly way to obtain a single machine.","C":"Buying outright needs the full $120,000 immediately, which is exactly what the business wants to avoid.","D":"Leasing avoids a large immediate payment and spreads the cost over the period of use, which suits equipment that may be outdated within three years."}}},{"id":"P1_U5_MCQ_1037","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1037","question":"Stonegate Ceramics forecasts these payments for July: wages $22,000, materials $30,000, rent $8,000, loan repayment $5,000 and tax $4,000. What are the total forecast payments?","options":{"A":"$69,000","B":"$60,000","C":"$65,000","D":"$51,000"},"correctOption":"A","correctAnswer":"$69,000","questionType":"MCQ","explanation":{"correct_reason":"All cash paid out counts, so $22,000 plus $30,000 plus $8,000 plus $5,000 plus $4,000 gives total forecast payments of $69,000.","distractor_reasons":{"A":"All cash paid out counts, so $22,000 plus $30,000 plus $8,000 plus $5,000 plus $4,000 gives total forecast payments of $69,000.","B":"$60,000 leaves out the $4,000 tax payment and possibly another item from the list.","C":"$65,000 leaves out the $4,000 tax payment from the total of all five items.","D":"$51,000 omits the $8,000 rent and the $5,000 loan repayment from the total."}}},{"id":"P1_U5_MCQ_1038","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1038","question":"Tarnbrook Hardware reports revenue of $520,000 for the year, cost of sales of $338,000 and operating expenses of $121,000. What is its gross profit for the year?","options":{"A":"$61,000","B":"$182,000","C":"$459,000","D":"$338,000"},"correctOption":"B","correctAnswer":"$182,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, so $520,000 less $338,000 gives $182,000 before the $121,000 of operating expenses is considered.","distractor_reasons":{"A":"$61,000 is the profit for the year after deducting the $121,000 operating expenses from gross profit.","B":"Gross profit is revenue minus cost of sales, so $520,000 less $338,000 gives $182,000 before the $121,000 of operating expenses is considered.","C":"$459,000 wrongly subtracts operating expenses from revenue and ignores cost of sales entirely.","D":"$338,000 is the cost of sales and has not been deducted from revenue to give a profit."}}},{"id":"P1_U5_MCQ_1039","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1039","question":"Uxendon Plastics has a bank overdraft of $12,000, trade payables of $25,000 and a short-term loan of $8,000. It also has a five-year loan of $100,000. What are its current liabilities?","options":{"A":"$145,000","B":"$37,000","C":"$45,000","D":"$20,000"},"correctOption":"C","correctAnswer":"$45,000","questionType":"MCQ","explanation":{"correct_reason":"Current liabilities are those due within a year, so the $12,000 overdraft plus $25,000 payables plus $8,000 short-term loan give $45,000, and the five-year loan is excluded.","distractor_reasons":{"A":"$145,000 includes the $100,000 five-year loan, which is a non-current liability due after more than a year.","B":"$37,000 leaves out the $8,000 short-term loan, which is also payable within a year.","C":"Current liabilities are those due within a year, so the $12,000 overdraft plus $25,000 payables plus $8,000 short-term loan give $45,000, and the five-year loan is excluded.","D":"$20,000 adds the overdraft and short-term loan but leaves out trade payables of $25,000."}}},{"id":"P1_U5_MCQ_1040","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1040","question":"Verity Foods is a food wholesaler with current assets of $88,000 and current liabilities of $55,000 at 31 December 2025. What is the current ratio of the business?","options":{"A":"0.6:1","B":"2.6:1","C":"1.4:1","D":"1.6:1"},"correctOption":"D","correctAnswer":"1.6:1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets divided by current liabilities, so $88,000 divided by $55,000 gives 1.6:1.","distractor_reasons":{"A":"0.6:1 divides current liabilities by current assets, which reverses the correct formula.","B":"2.6:1 is far too high and would need current assets of about $143,000, not $88,000.","C":"1.4:1 does not follow from $88,000 and $55,000 and appears to use a different liability figure.","D":"The current ratio is current assets divided by current liabilities, so $88,000 divided by $55,000 gives 1.6:1."}}},{"id":"P1_U5_MCQ_1041","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1041","question":"Whitlock Electronics buys equipment on hire purchase, paying a deposit of $2,000 and 24 monthly instalments of $350. The cash price would have been $8,000. What is the total amount paid under the agreement?","options":{"A":"$10,400","B":"$8,400","C":"$2,350","D":"$10,000"},"correctOption":"A","correctAnswer":"$10,400","questionType":"MCQ","explanation":{"correct_reason":"The 24 instalments total $8,400, and adding the $2,000 deposit gives $10,400 paid in total, which is $2,400 more than the $8,000 cash price.","distractor_reasons":{"A":"The 24 instalments total $8,400, and adding the $2,000 deposit gives $10,400 paid in total, which is $2,400 more than the $8,000 cash price.","B":"$8,400 is only the total of the 24 monthly instalments and leaves out the $2,000 deposit.","C":"$2,350 adds the deposit to just one instalment instead of all twenty-four of them.","D":"$10,000 ignores the deposit and treats the instalments as if they totalled $10,000."}}},{"id":"P1_U5_MCQ_1042","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1042","question":"Xenwood Footwear's cash flow forecast shows a negative closing cash balance for September. Which one action would most directly improve the forecast closing balance for that month?","options":{"A":"Buying extra inventory on credit in September","B":"Arranging a short-term bank loan or delaying planned equipment payments","C":"Recording depreciation of the factory machinery in the accounts","D":"Paying suppliers earlier in order to obtain a settlement discount"},"correctOption":"B","correctAnswer":"Arranging a short-term bank loan or delaying planned equipment payments","questionType":"MCQ","explanation":{"correct_reason":"A short-term loan brings cash into September, and delaying equipment payments holds cash back, so either action directly raises the closing balance.","distractor_reasons":{"A":"Buying extra inventory on credit postpones the payment but adds to commitments and does not bring cash in.","B":"A short-term loan brings cash into September, and delaying equipment payments holds cash back, so either action directly raises the closing balance.","C":"Depreciation is a non-cash expense, so recording it has no effect on the bank balance at all.","D":"Paying suppliers earlier takes cash out sooner and would reduce the closing balance still further."}}},{"id":"P1_U5_MCQ_1043","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1043","question":"Yardley Motors has gross profit of $145,000 and a profit for the year of $38,000. It has no interest charges. What were its operating expenses?","options":{"A":"$183,000","B":"$38,000","C":"$107,000","D":"$145,000"},"correctOption":"C","correctAnswer":"$107,000","questionType":"MCQ","explanation":{"correct_reason":"With no interest, operating expenses are gross profit minus profit for the year, so $145,000 less $38,000 gives $107,000.","distractor_reasons":{"A":"$183,000 adds the gross profit and the profit for the year instead of subtracting the profit from gross profit.","B":"$38,000 is the profit for the year, not the expenses that were deducted from gross profit to reach it.","C":"With no interest, operating expenses are gross profit minus profit for the year, so $145,000 less $38,000 gives $107,000.","D":"$145,000 is the gross profit before any operating expenses have been deducted."}}},{"id":"P1_U5_MCQ_1044","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1044","question":"Zenith Aviation has non-current assets of $250,000, current assets of $70,000 and current liabilities of $40,000. What is its capital employed at the year end?","options":{"A":"$320,000","B":"$210,000","C":"$360,000","D":"$280,000"},"correctOption":"D","correctAnswer":"$280,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is non-current assets plus working capital, so $250,000 plus ($70,000 less $40,000) gives $280,000.","distractor_reasons":{"A":"$320,000 adds non-current and current assets and forgets to deduct the $40,000 of current liabilities.","B":"$210,000 deducts the current liabilities from non-current assets and leaves out current assets altogether.","C":"$360,000 adds all three figures together, treating current liabilities as an addition rather than a deduction.","D":"Capital employed is non-current assets plus working capital, so $250,000 plus ($70,000 less $40,000) gives $280,000."}}},{"id":"P1_U5_MCQ_1045","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1045","question":"Aldergrove Confectionery, a sweet manufacturer, reports operating profit of $63,000 for the year and capital employed of $420,000. What is its return on capital employed?","options":{"A":"15%","B":"6.7%","C":"63%","D":"1.5%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed divides operating profit by capital employed, so $63,000 divided by $420,000 multiplied by 100 gives 15%.","distractor_reasons":{"A":"Return on capital employed divides operating profit by capital employed, so $63,000 divided by $420,000 multiplied by 100 gives 15%.","B":"6.7% divides capital employed by operating profit and therefore reverses the correct formula.","C":"63% uses the profit in thousands as if it were already a percentage of the capital invested.","D":"1.5% misplaces the decimal point and does not follow from $63,000 divided by $420,000."}}},{"id":"P1_U5_MCQ_1046","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1046","question":"Beaconhill Cosmetics owns a delivery van that is no longer needed and is worth about $18,000. The business needs cash quickly without borrowing. Which source of finance is described here?","options":{"A":"A bank loan","B":"Sale of an unused asset","C":"Trade credit","D":"Share capital"},"correctOption":"B","correctAnswer":"Sale of an unused asset","questionType":"MCQ","explanation":{"correct_reason":"Selling the unwanted van converts an asset the business no longer uses into about $18,000 of internal finance, with no borrowing and no new shareholders.","distractor_reasons":{"A":"A bank loan is borrowed money that must be repaid with interest, which the business wants to avoid.","B":"Selling the unwanted van converts an asset the business no longer uses into about $18,000 of internal finance, with no borrowing and no new shareholders.","C":"Trade credit is extra time to pay a supplier and does not generate cash from an asset.","D":"Share capital comes from investors buying shares and does not involve selling a van."}}},{"id":"P1_U5_MCQ_1047","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1047","question":"Cloverdale Garden Centres forecasts receipts of $96,000 and payments of $88,400 in the peak month of May. What is the forecast net cash flow for May?","options":{"A":"$184,400","B":"-$7,600","C":"$7,600","D":"$8,400"},"correctOption":"C","correctAnswer":"$7,600","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is inflows minus outflows, so $96,000 less $88,400 gives a positive net cash flow of $7,600 for May.","distractor_reasons":{"A":"$184,400 adds receipts and payments together instead of subtracting payments from receipts.","B":"-$7,600 has the right size but the wrong sign, since receipts are greater than payments in May.","C":"Net cash flow is inflows minus outflows, so $96,000 less $88,400 gives a positive net cash flow of $7,600 for May.","D":"$8,400 does not follow from $96,000 and $88,400 and appears to misread one of the figures."}}},{"id":"P1_U5_MCQ_1048","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1048","question":"Dovemere Laundry has revenue of $300,000 and cost of sales of $180,000. If cost of sales rises by 12% and revenue stays the same, what is the new gross profit?","options":{"A":"$120,000","B":"$84,000","C":"$201,600","D":"$98,400"},"correctOption":"D","correctAnswer":"$98,400","questionType":"MCQ","explanation":{"correct_reason":"A 12% rise lifts cost of sales from $180,000 to $201,600, so gross profit falls from $120,000 to $300,000 less $201,600, which is $98,400.","distractor_reasons":{"A":"$120,000 is the original gross profit before the 12% rise in cost of sales is applied.","B":"$84,000 wrongly deducts the $36,000 rise from gross profit twice, overstating the fall.","C":"$201,600 is the new cost of sales figure and still has to be subtracted from revenue.","D":"A 12% rise lifts cost of sales from $180,000 to $201,600, so gross profit falls from $120,000 to $300,000 less $201,600, which is $98,400."}}},{"id":"P1_U5_MCQ_1049","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1049","question":"Elmsworth Upholstery has current assets of $75,000 in total. These include trade receivables of $30,000 and cash of $12,000. What is the value of its inventory?","options":{"A":"$33,000","B":"$45,000","C":"$42,000","D":"$63,000"},"correctOption":"A","correctAnswer":"$33,000","questionType":"MCQ","explanation":{"correct_reason":"Inventory is the current assets that remain after receivables and cash, so $75,000 less $30,000 less $12,000 gives $33,000.","distractor_reasons":{"A":"Inventory is the current assets that remain after receivables and cash, so $75,000 less $30,000 less $12,000 gives $33,000.","B":"$45,000 subtracts only the $30,000 of receivables and ignores the $12,000 of cash.","C":"$42,000 subtracts only the $12,000 of cash and ignores the $30,000 of receivables.","D":"$63,000 subtracts the $12,000 cash twice or otherwise double counts one of the deductions."}}},{"id":"P1_U5_MCQ_1050","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1050","question":"Fairhaven Chocolates made revenue of $250,000 and a profit for the year of $20,000. Its gross profit was $95,000. What was its profit margin for the year?","options":{"A":"38%","B":"8%","C":"20%","D":"12.5%"},"correctOption":"B","correctAnswer":"8%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year divided by revenue, so $20,000 divided by $250,000 multiplied by 100 gives 8%.","distractor_reasons":{"A":"38% is the gross profit margin using $95,000, not the profit margin based on $20,000.","B":"Profit margin is profit for the year divided by revenue, so $20,000 divided by $250,000 multiplied by 100 gives 8%.","C":"20% uses the $20,000 profit figure as though it were already a percentage of revenue.","D":"12.5% divides $20,000 by $160,000 rather than by the revenue figure of $250,000."}}},{"id":"P1_U5_MCQ_1051","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1051","question":"Grassington Bicycles arranges an overdraft of $18,000 at an annual interest rate of 11%. The overdraft is used for six months and then cleared in full. What total interest is charged?","options":{"A":"$1,980","B":"$198","C":"$990","D":"$1,650"},"correctOption":"C","correctAnswer":"$990","questionType":"MCQ","explanation":{"correct_reason":"A full year of interest would be 11% of $18,000, which is $1,980, so six months costs half of that, giving $990.","distractor_reasons":{"A":"$1,980 is a full year of interest on the overdraft and ignores that it is used for only six months.","B":"$198 is only one tenth of the correct half-year charge and uses the wrong rate and time period.","C":"A full year of interest would be 11% of $18,000, which is $1,980, so six months costs half of that, giving $990.","D":"$1,650 uses a rate of about 9.2% over half a year rather than the stated 11% annual rate."}}},{"id":"P1_U5_MCQ_1052","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1052","question":"Highfield Tiles starts July with $12,000 cash. Forecast net cash flow is -$5,500 in July and +$2,300 in August. What is the forecast closing balance at the end of August?","options":{"A":"$4,200","B":"$6,500","C":"$9,800","D":"$8,800"},"correctOption":"D","correctAnswer":"$8,800","questionType":"MCQ","explanation":{"correct_reason":"After July the balance is $12,000 less $5,500, which is $6,500, and adding the August inflow of $2,300 gives a closing balance of $8,800.","distractor_reasons":{"A":"$4,200 subtracts both monthly figures from the opening balance, wrongly treating the August inflow as an outflow.","B":"$6,500 is the closing balance at the end of July and ignores the August net inflow.","C":"$9,800 adds the July outflow to the opening balance instead of deducting it.","D":"After July the balance is $12,000 less $5,500, which is $6,500, and adding the August inflow of $2,300 gives a closing balance of $8,800."}}},{"id":"P1_U5_MCQ_1053","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1053","question":"Ivybridge Glass had opening inventory of $32,000, purchases of $148,000 and closing inventory of $27,000 during the year. What was its cost of sales for the year?","options":{"A":"$153,000","B":"$207,000","C":"$143,000","D":"$180,000"},"correctOption":"A","correctAnswer":"$153,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is opening inventory plus purchases minus closing inventory, so $32,000 plus $148,000 less $27,000 gives $153,000.","distractor_reasons":{"A":"Cost of sales is opening inventory plus purchases minus closing inventory, so $32,000 plus $148,000 less $27,000 gives $153,000.","B":"$207,000 adds all three figures together and so counts the closing inventory twice.","C":"$143,000 deducts both opening and closing inventory from purchases, which is incorrect.","D":"$180,000 adds opening inventory and purchases but makes no adjustment for closing inventory."}}},{"id":"P1_U5_MCQ_1054","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1054","question":"Jesmond Signage has total assets of $520,000 and total liabilities of $190,000 at its year end. What is the owners' equity (capital) of the business?","options":{"A":"$710,000","B":"$330,000","C":"$190,000","D":"$520,000"},"correctOption":"B","correctAnswer":"$330,000","questionType":"MCQ","explanation":{"correct_reason":"Owners' equity is total assets minus total liabilities, so $520,000 less $190,000 gives $330,000 as the capital belonging to the owners.","distractor_reasons":{"A":"$710,000 adds assets and liabilities together instead of deducting liabilities from assets.","B":"Owners' equity is total assets minus total liabilities, so $520,000 less $190,000 gives $330,000 as the capital belonging to the owners.","C":"$190,000 is the total liabilities figure and represents claims of lenders, not owners' capital.","D":"$520,000 is total assets and still includes the $190,000 that belongs to lenders rather than owners."}}},{"id":"P1_U5_MCQ_1055","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1055","question":"Kelvindale Steel has current assets of $120,000, including inventory of $45,000, and current liabilities of $50,000 at the year end. What is its acid-test ratio?","options":{"A":"2.4:1","B":"0.9:1","C":"1.5:1","D":"2.0:1"},"correctOption":"C","correctAnswer":"1.5:1","questionType":"MCQ","explanation":{"correct_reason":"The acid-test ratio excludes inventory, so $120,000 less $45,000 gives $75,000 of liquid assets, which divided by $50,000 of current liabilities is 1.5:1.","distractor_reasons":{"A":"2.4:1 is the current ratio, which includes the $45,000 of inventory that must be excluded.","B":"0.9:1 divides the $45,000 inventory figure by current liabilities rather than using the liquid assets.","C":"The acid-test ratio excludes inventory, so $120,000 less $45,000 gives $75,000 of liquid assets, which divided by $50,000 of current liabilities is 1.5:1.","D":"2.0:1 would need liquid current assets of $100,000 against $50,000 of current liabilities, which is not the case."}}},{"id":"P1_U5_MCQ_1056","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1056","question":"Lowmoor Boilers has retained profit of only $12,000 but needs $250,000 to build a new factory. Why is retained profit unsuitable as the only source of finance for this project?","options":{"A":"Retained profit has to be repaid to shareholders at the end of each year","B":"Retained profit may only be spent on day-to-day wages and materials","C":"Retained profit is borrowed from the bank and therefore carries interest","D":"The amount available is far below the $250,000 required, so other finance is still needed"},"correctOption":"D","correctAnswer":"The amount available is far below the $250,000 required, so other finance is still needed","questionType":"MCQ","explanation":{"correct_reason":"Retained profit of $12,000 covers less than 5% of the $250,000 factory cost, so the business would still need a loan or other external finance.","distractor_reasons":{"A":"Retained profit is not repaid each year; it is profit kept in the business instead of being distributed.","B":"Retained profit can be spent on any business purpose and is not restricted to wages and materials.","C":"Retained profit is internal money, not a bank loan, so it carries no interest charge.","D":"Retained profit of $12,000 covers less than 5% of the $250,000 factory cost, so the business would still need a loan or other external finance."}}},{"id":"P1_U5_MCQ_1057","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1057","question":"Marchmont Joinery wants a bank loan. Its manager prepares a monthly cash flow forecast covering the next twelve months. Why would the bank find this forecast useful when deciding whether to lend?","options":{"A":"It shows the expected timing of cash inflows and outflows and so the ability to repay","B":"It proves that the business will make a profit in every single month","C":"It guarantees that customers will pay exactly the amounts forecast","D":"It replaces the need for a statement of financial position entirely"},"correctOption":"A","correctAnswer":"It shows the expected timing of cash inflows and outflows and so the ability to repay","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast shows when money is expected to arrive and leave, letting the bank judge whether monthly surpluses will cover loan interest and repayments.","distractor_reasons":{"A":"A cash flow forecast shows when money is expected to arrive and leave, letting the bank judge whether monthly surpluses will cover loan interest and repayments.","B":"A forecast is only an estimate and says nothing certain about profit, which also depends on credit sales and expenses.","C":"A forecast cannot guarantee customer behaviour; it only predicts receipts based on stated assumptions.","D":"A cash flow forecast and a statement of financial position serve different purposes, so one cannot replace the other."}}},{"id":"P1_U5_MCQ_1058","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1058","question":"Newlyn Candles had revenue of $96,000, cost of sales of $61,000 and operating expenses of $22,000 for the year. What was its profit for the year?","options":{"A":"$35,000","B":"$13,000","C":"$9,000","D":"$74,000"},"correctOption":"B","correctAnswer":"$13,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $96,000 less $61,000, which is $35,000, and deducting the $22,000 of operating expenses leaves a profit for the year of $13,000.","distractor_reasons":{"A":"$35,000 is the gross profit and still has the $22,000 of operating expenses to be deducted from it.","B":"Gross profit is $96,000 less $61,000, which is $35,000, and deducting the $22,000 of operating expenses leaves a profit for the year of $13,000.","C":"$9,000 does not follow from the figures and appears to deduct one of the costs twice.","D":"$74,000 subtracts only the operating expenses from revenue and ignores the larger cost of sales."}}},{"id":"P1_U5_MCQ_1059","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1059","question":"Ormsby Tannery has current assets of $58,000 and current liabilities of $41,000. It receives a five-year bank loan of $20,000 in cash. What is its working capital immediately afterwards?","options":{"A":"$17,000","B":"$20,000","C":"$37,000","D":"$57,000"},"correctOption":"C","correctAnswer":"$37,000","questionType":"MCQ","explanation":{"correct_reason":"The loan raises cash and therefore current assets to $78,000 while current liabilities stay at $41,000, so working capital becomes $37,000.","distractor_reasons":{"A":"$17,000 is the working capital before the loan is received and takes no account of the extra cash.","B":"$20,000 is the loan itself, not the working capital after the money has been received.","C":"The loan raises cash and therefore current assets to $78,000 while current liabilities stay at $41,000, so working capital becomes $37,000.","D":"$57,000 adds the loan to current assets and then deducts nothing for current liabilities."}}},{"id":"P1_U5_MCQ_1060","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1060","question":"Pittenweem Sailmakers earned gross profit of $96,000 on revenue of $320,000 last year. Its operating expenses were $70,000. What was its gross profit margin for that year?","options":{"A":"26%","B":"70%","C":"8.1%","D":"30%"},"correctOption":"D","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is $96,000 divided by $320,000 multiplied by 100, which gives 30%.","distractor_reasons":{"A":"26% is the profit margin after deducting the $70,000 operating expenses, not the gross margin.","B":"70% is the cost of sales percentage of revenue, which is the complement of the gross margin.","C":"8.1% is the operating expenses as a percentage of revenue and is not a profit margin.","D":"Gross profit margin is $96,000 divided by $320,000 multiplied by 100, which gives 30%."}}},{"id":"P1_U5_MCQ_1061","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1061","question":"Quenington Paper is a public limited company. It issues 200,000 new ordinary shares at a price of $1.50 each to raise finance for expansion. How much capital will the issue raise before costs?","options":{"A":"$300,000","B":"$200,000","C":"$150,000","D":"$3,000,000"},"correctOption":"A","correctAnswer":"$300,000","questionType":"MCQ","explanation":{"correct_reason":"Share capital raised is the number of shares multiplied by the issue price, so 200,000 shares at $1.50 each raises $300,000.","distractor_reasons":{"A":"Share capital raised is the number of shares multiplied by the issue price, so 200,000 shares at $1.50 each raises $300,000.","B":"$200,000 is just the number of shares and ignores the $1.50 price at which they are issued.","C":"$150,000 multiplies the price by 100,000 shares instead of the 200,000 actually issued.","D":"$3,000,000 misplaces the decimal point and is ten times the correct amount raised."}}},{"id":"P1_U5_MCQ_1062","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1062","question":"Rossmere Skincare receives 60% of each month's sales in the month of sale and the remaining 40% one month later. Sales were $70,000 in January and $85,000 in February. What cash is received in February?","options":{"A":"$51,000","B":"$79,000","C":"$85,000","D":"$62,000"},"correctOption":"B","correctAnswer":"$79,000","questionType":"MCQ","explanation":{"correct_reason":"February cash is 40% of January's $70,000 sales, which is $28,000, plus 60% of February's $85,000 sales, which is $51,000, giving $79,000.","distractor_reasons":{"A":"$51,000 is only the 60% of February sales received in the month and omits January's late payers.","B":"February cash is 40% of January's $70,000 sales, which is $28,000, plus 60% of February's $85,000 sales, which is $51,000, giving $79,000.","C":"$85,000 treats all February sales as though they were paid in cash immediately.","D":"$62,000 uses the wrong percentages and does not match the 60% and 40% terms given."}}},{"id":"P1_U5_MCQ_1063","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1063","question":"Stanhope Roofing made a profit of $24,000 last year. This year sales are unchanged but operating expenses are $6,000 lower. All other figures are unchanged. What is the new profit for the year?","options":{"A":"$18,000","B":"$24,000","C":"$30,000","D":"$6,000"},"correctOption":"C","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"With sales and other figures unchanged, a $6,000 fall in operating expenses raises profit from $24,000 by $6,000 to $30,000.","distractor_reasons":{"A":"$18,000 subtracts the saving from profit, but lower expenses increase profit rather than reduce it.","B":"$24,000 is last year's profit and ignores the $6,000 cost saving achieved this year.","C":"With sales and other figures unchanged, a $6,000 fall in operating expenses raises profit from $24,000 by $6,000 to $30,000.","D":"$6,000 is the size of the saving and not the total profit for the year."}}},{"id":"P1_U5_MCQ_1064","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1064","question":"Tiverton Soft Drinks has current assets of $92,000 and working capital of $27,000 at the year end. What is the total value of its current liabilities?","options":{"A":"$119,000","B":"$27,000","C":"$92,000","D":"$65,000"},"correctOption":"D","correctAnswer":"$65,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so current liabilities equal $92,000 less $27,000, which is $65,000.","distractor_reasons":{"A":"$119,000 adds working capital to current assets instead of subtracting it to find liabilities.","B":"$27,000 is the working capital figure itself and not the amount owed in the short term.","C":"$92,000 is the current assets total and includes the working capital as well as the liabilities.","D":"Working capital is current assets minus current liabilities, so current liabilities equal $92,000 less $27,000, which is $65,000."}}},{"id":"P1_U5_MCQ_1065","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1065","question":"Ulverston Wool has current assets of $105,000 and current liabilities of $42,000 at 31 March 2026. What is the current ratio of the business at that date?","options":{"A":"2.5:1","B":"1.5:1","C":"0.4:1","D":"3.5:1"},"correctOption":"A","correctAnswer":"2.5:1","questionType":"MCQ","explanation":{"correct_reason":"Current assets of $105,000 divided by current liabilities of $42,000 gives a current ratio of 2.5:1.","distractor_reasons":{"A":"Current assets of $105,000 divided by current liabilities of $42,000 gives a current ratio of 2.5:1.","B":"1.5:1 would require current assets of only $63,000 against $42,000 of current liabilities.","C":"0.4:1 divides current liabilities by current assets and therefore reverses the formula.","D":"3.5:1 would require current assets of $147,000, which is well above the $105,000 shown."}}},{"id":"P1_U5_MCQ_1066","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1066","question":"Ventnor Guesthouses can lease new kitchen equipment instead of buying it outright. Which statement best explains a financial advantage of leasing for this seaside business?","options":{"A":"Leasing transfers ownership of the equipment to the business immediately","B":"Leasing avoids a large initial cash payment and spreads the cost over time","C":"Leasing is always cheaper in total than buying the equipment outright","D":"Leasing increases the value of non-current assets shown in the accounts"},"correctOption":"B","correctAnswer":"Leasing avoids a large initial cash payment and spreads the cost over time","questionType":"MCQ","explanation":{"correct_reason":"Leasing lets the guesthouse use the equipment for regular payments without finding a large sum upfront, which protects its cash flow during quiet months.","distractor_reasons":{"A":"Leasing does not transfer ownership; the equipment normally returns to the lessor at the end of the agreement.","B":"Leasing lets the guesthouse use the equipment for regular payments without finding a large sum upfront, which protects its cash flow during quiet months.","C":"Leasing usually costs more in total than buying because the payments include the lessor's charges.","D":"Leased equipment is not owned, so it does not increase the non-current assets shown in the accounts."}}},{"id":"P1_U5_MCQ_1067","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1067","question":"Wexcombe Cider made a profit of $46,000 last year but had to arrange an overdraft to pay its suppliers. Which statement best explains how this situation can happen?","options":{"A":"Profit is calculated before any cash is received or paid by the business","B":"An overdraft is only needed when a business has made a loss for the year","C":"Sales may be made on credit, so cash arrives later than the profit is recorded","D":"Depreciation payments use up the profit in cash during the year"},"correctOption":"C","correctAnswer":"Sales may be made on credit, so cash arrives later than the profit is recorded","questionType":"MCQ","explanation":{"correct_reason":"Profit records sales when goods are supplied, but credit customers pay later, so the $46,000 profit can be earned while cash is still short for suppliers.","distractor_reasons":{"A":"Profit does take account of cash receipts and payments in the sense that revenue and costs are recorded, but timing differences cause the gap.","B":"Overdrafts are used to cover timing gaps and are not limited to businesses that make a loss.","C":"Profit records sales when goods are supplied, but credit customers pay later, so the $46,000 profit can be earned while cash is still short for suppliers.","D":"Depreciation is a non-cash expense, so no cash payment is made for it during the year."}}},{"id":"P1_U5_MCQ_1068","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1068","question":"Yelverton Cheese reports revenue of $410,000, cost of sales of $246,000, operating expenses of $118,000 and interest payable of $14,000. What is its profit for the year?","options":{"A":"$46,000","B":"$164,000","C":"$28,000","D":"$32,000"},"correctOption":"D","correctAnswer":"$32,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $164,000, and deducting $118,000 of expenses and $14,000 of interest leaves a profit for the year of $32,000.","distractor_reasons":{"A":"$46,000 deducts the operating expenses but forgets to take off the $14,000 of interest.","B":"$164,000 is the gross profit before expenses and interest have been deducted.","C":"$28,000 deducts interest twice or otherwise double counts one of the deductions.","D":"Gross profit is $164,000, and deducting $118,000 of expenses and $14,000 of interest leaves a profit for the year of $32,000."}}},{"id":"P1_U5_MCQ_1069","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1069","question":"Zennor Pottery has current assets of $66,000 and current liabilities of $38,000. It sells inventory that cost $5,000 for $5,000 cash. What is its working capital immediately afterwards?","options":{"A":"$28,000","B":"$23,000","C":"$33,000","D":"$38,000"},"correctOption":"A","correctAnswer":"$28,000","questionType":"MCQ","explanation":{"correct_reason":"Selling inventory at cost for cash swaps one current asset for another of equal value, so current assets stay at $66,000 and working capital remains $28,000.","distractor_reasons":{"A":"Selling inventory at cost for cash swaps one current asset for another of equal value, so current assets stay at $66,000 and working capital remains $28,000.","B":"$23,000 wrongly deducts the $5,000 sale from working capital even though no value has left the business.","C":"$33,000 wrongly adds the $5,000 sale to working capital as though it created extra value.","D":"$38,000 is the current liabilities figure, not the working capital."}}},{"id":"P1_U5_MCQ_1070","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1070","question":"Aldbourne Beds reports an operating profit of $36,000 for the year and capital employed of $200,000 at the year end. What is its return on capital employed?","options":{"A":"36%","B":"18%","C":"5.6%","D":"1.8%"},"correctOption":"B","correctAnswer":"18%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, so $36,000 divided by $200,000 multiplied by 100 gives 18%.","distractor_reasons":{"A":"36% uses the profit figure as though it were already a percentage of the capital employed.","B":"Return on capital employed is operating profit divided by capital employed, so $36,000 divided by $200,000 multiplied by 100 gives 18%.","C":"5.6% divides capital employed by operating profit and therefore reverses the correct formula.","D":"1.8% misplaces the decimal point and does not follow from $36,000 divided by $200,000."}}},{"id":"P1_U5_MCQ_1071","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1071","question":"Bexhill Motor Factors borrows $90,000 at an annual interest rate of 7.2%. Interest is charged monthly on the full amount borrowed. What is the interest charge for one month?","options":{"A":"$6,480","B":"$648","C":"$540","D":"$450"},"correctOption":"C","correctAnswer":"$540","questionType":"MCQ","explanation":{"correct_reason":"Annual interest is 7.2% of $90,000, which is $6,480, and dividing this by twelve months gives a monthly charge of $540.","distractor_reasons":{"A":"$6,480 is the whole year of interest, not the charge for a single month.","B":"$648 uses a rate of about 8.6% a year and does not follow from the stated 7.2%.","C":"Annual interest is 7.2% of $90,000, which is $6,480, and dividing this by twelve months gives a monthly charge of $540.","D":"$450 would require an annual rate of 6%, not the 7.2% charged by the lender."}}},{"id":"P1_U5_MCQ_1072","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1072","question":"Caldicot Tooling forecasts an opening balance of $2,500, a net cash outflow of $6,000 from trading and a new bank loan of $20,000. What is the forecast closing balance?","options":{"A":"$28,500","B":"$11,500","C":"$14,000","D":"$16,500"},"correctOption":"D","correctAnswer":"$16,500","questionType":"MCQ","explanation":{"correct_reason":"Starting from $2,500, the $6,000 trading outflow leaves -$3,500, and adding the $20,000 loan gives a closing balance of $16,500.","distractor_reasons":{"A":"$28,500 adds the loan and the trading outflow to the opening balance instead of deducting the outflow.","B":"$11,500 deducts the $6,000 outflow and then also deducts it from the loan, double counting the outflow.","C":"$14,000 ignores the $2,500 opening balance when adding the loan to the trading position.","D":"Starting from $2,500, the $6,000 trading outflow leaves -$3,500, and adding the $20,000 loan gives a closing balance of $16,500."}}},{"id":"P1_U5_MCQ_1073","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1073","question":"Dunster Saddlery has revenue of $260,000 and cost of sales of $150,000. If cost of sales rises to $165,000 and revenue is unchanged, what is the new gross profit?","options":{"A":"$95,000","B":"$110,000","C":"$15,000","D":"$80,000"},"correctOption":"A","correctAnswer":"$95,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue of $260,000 less the new cost of sales of $165,000 gives a gross profit of $95,000, which is $15,000 lower than before.","distractor_reasons":{"A":"Revenue of $260,000 less the new cost of sales of $165,000 gives a gross profit of $95,000, which is $15,000 lower than before.","B":"$110,000 is the original gross profit before the rise in cost of sales is taken into account.","C":"$15,000 is the size of the increase in cost of sales, not the new gross profit.","D":"$80,000 deducts the $15,000 increase from gross profit twice, overstating the fall."}}},{"id":"P1_U5_MCQ_1074","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1074","question":"Elmley Turf has total assets of $610,000, of which current assets are $130,000. What is the value of its non-current assets at the year end?","options":{"A":"$740,000","B":"$480,000","C":"$130,000","D":"$610,000"},"correctOption":"B","correctAnswer":"$480,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are non-current plus current assets, so non-current assets are $610,000 less $130,000, giving $480,000.","distractor_reasons":{"A":"$740,000 adds the current assets to total assets instead of subtracting them.","B":"Total assets are non-current plus current assets, so non-current assets are $610,000 less $130,000, giving $480,000.","C":"$130,000 is the current assets figure and not the non-current assets of the business.","D":"$610,000 is the total assets and still includes the $130,000 of current assets."}}},{"id":"P1_U5_MCQ_1075","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1075","question":"Falstone Delicatessen made revenue of $480,000 and a profit for the year of $60,000. Its gross profit was $168,000. What was its profit margin for the year?","options":{"A":"35%","B":"8%","C":"12.5%","D":"60%"},"correctOption":"C","correctAnswer":"12.5%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year divided by revenue, so $60,000 divided by $480,000 multiplied by 100 gives 12.5%.","distractor_reasons":{"A":"35% is the gross profit margin using $168,000, not the profit margin based on $60,000.","B":"8% divides $60,000 by $750,000 rather than by the $480,000 of revenue.","C":"Profit margin is profit for the year divided by revenue, so $60,000 divided by $480,000 multiplied by 100 gives 12.5%.","D":"60% treats $60,000 as a percentage and ignores the revenue figure completely."}}},{"id":"P1_U5_MCQ_1076","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1076","question":"Garsdale Outdoors wants $45,000 to launch a new range of hiking packs. It raises small amounts from many supporters through an online platform in return for rewards. Which source of finance is this?","options":{"A":"A bank overdraft","B":"Trade credit","C":"Retained profit","D":"Crowdfunding"},"correctOption":"D","correctAnswer":"Crowdfunding","questionType":"MCQ","explanation":{"correct_reason":"Crowdfunding raises small sums from many individuals, usually through an online platform, and often offers rewards rather than shares, which matches the $45,000 launch funding described.","distractor_reasons":{"A":"An overdraft is borrowing from one bank and is repaid with interest, not money pledged by many supporters.","B":"Trade credit is extra time to pay a supplier and does not raise $45,000 of new launch finance.","C":"Retained profit comes from the business's own past profits, but this is a new venture with no such reserve.","D":"Crowdfunding raises small sums from many individuals, usually through an online platform, and often offers rewards rather than shares, which matches the $45,000 launch funding described."}}},{"id":"P1_U5_MCQ_1077","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1077","question":"Haslemere Pianos forecasts total cash inflows of $240,000 and total cash outflows of $198,000 for the coming year. What is its forecast net cash flow for the year?","options":{"A":"$42,000","B":"$438,000","C":"-$42,000","D":"$198,000"},"correctOption":"A","correctAnswer":"$42,000","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is total inflows minus total outflows for the year, so $240,000 less $198,000 gives a forecast net inflow of $42,000.","distractor_reasons":{"A":"Net cash flow is total inflows minus total outflows for the year, so $240,000 less $198,000 gives a forecast net inflow of $42,000.","B":"$438,000 adds inflows and outflows together instead of subtracting the outflows from the inflows.","C":"-$42,000 has the right size but the wrong sign, since inflows exceed outflows for the year.","D":"$198,000 is the total outflow figure and not the difference between inflows and outflows."}}},{"id":"P1_U5_MCQ_1078","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1078","question":"Ingram Pet Supplies had revenue of $78,000, cost of sales of $45,000 and operating expenses of $26,500 for the year. What was its profit for the year?","options":{"A":"$33,000","B":"$6,500","C":"$12,500","D":"$51,500"},"correctOption":"B","correctAnswer":"$6,500","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $78,000 less $45,000, which is $33,000, and deducting the $26,500 of operating expenses leaves a profit for the year of $6,500.","distractor_reasons":{"A":"$33,000 is the gross profit and still has the $26,500 of operating expenses to be deducted.","B":"Gross profit is $78,000 less $45,000, which is $33,000, and deducting the $26,500 of operating expenses leaves a profit for the year of $6,500.","C":"$12,500 does not follow from these figures and appears to deduct an extra amount from profit.","D":"$51,500 subtracts only the operating expenses from revenue and ignores cost of sales."}}},{"id":"P1_U5_MCQ_1079","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1079","question":"Jordanthorpe Frames has non-current assets of $395,000, current assets of $88,000 and current liabilities of $46,000. What is its capital employed at the year end?","options":{"A":"$483,000","B":"$349,000","C":"$437,000","D":"$441,000"},"correctOption":"C","correctAnswer":"$437,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is non-current assets plus working capital, so $395,000 plus ($88,000 less $46,000) gives $437,000.","distractor_reasons":{"A":"$483,000 adds non-current and current assets but ignores the $46,000 of current liabilities.","B":"$349,000 deducts current liabilities from non-current assets and leaves out current assets.","C":"Capital employed is non-current assets plus working capital, so $395,000 plus ($88,000 less $46,000) gives $437,000.","D":"$441,000 does not follow from the three figures and appears to use a different liability total."}}},{"id":"P1_U5_MCQ_1080","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1080","question":"Knebworth Party Hire earned revenue of $400,000 and gross profit of $92,000 last year. Its operating expenses were $57,000. What was its gross profit margin?","options":{"A":"14.3%","B":"77%","C":"8.8%","D":"23%"},"correctOption":"D","correctAnswer":"23%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit divided by revenue, so $92,000 divided by $400,000 multiplied by 100 gives 23%.","distractor_reasons":{"A":"14.3% is the operating expenses of $57,000 expressed as a percentage of revenue, not the gross margin.","B":"77% is cost of sales as a percentage of revenue, which is the complement of the gross margin.","C":"8.8% is the profit margin after expenses, not the gross profit margin based on $92,000.","D":"Gross profit margin is gross profit divided by revenue, so $92,000 divided by $400,000 multiplied by 100 gives 23%."}}},{"id":"P1_U5_MCQ_1081","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1081","question":"Lynmouth Aquatics needs $250,000 for a new pool. It wins a government grant covering 30% of the cost and will borrow the rest from its bank. How much must it borrow?","options":{"A":"$175,000","B":"$75,000","C":"$220,000","D":"$250,000"},"correctOption":"A","correctAnswer":"$175,000","questionType":"MCQ","explanation":{"correct_reason":"The grant covers 30% of $250,000, which is $75,000, so the remaining amount to borrow is $250,000 less $75,000, giving $175,000.","distractor_reasons":{"A":"The grant covers 30% of $250,000, which is $75,000, so the remaining amount to borrow is $250,000 less $75,000, giving $175,000.","B":"$75,000 is the value of the grant itself, not the amount that must still be borrowed.","C":"$220,000 deducts only $30,000 from the project cost and so treats 30% as a cash amount.","D":"$250,000 is the full cost of the pool and ignores the grant that reduces the borrowing needed."}}},{"id":"P1_U5_MCQ_1082","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1082","question":"Marlborough Cartridges has rising sales and a healthy profit margin, yet it cannot pay its suppliers on time. Which explanation best fits this situation for the business?","options":{"A":"Rising sales always reduce the amount of cash held by a business","B":"Customers buy on long credit terms, so cash is tied up in receivables while suppliers must be paid sooner","C":"A high profit margin means that no cash has been received from customers","D":"Suppliers refuse to accept payment from businesses that are profitable"},"correctOption":"B","correctAnswer":"Customers buy on long credit terms, so cash is tied up in receivables while suppliers must be paid sooner","questionType":"MCQ","explanation":{"correct_reason":"If customers take long credit, sales become receivables rather than cash, so a profitable business can still run short of money when supplier bills fall due.","distractor_reasons":{"A":"Rising sales do not automatically reduce cash; the problem depends on when customers actually pay.","B":"If customers take long credit, sales become receivables rather than cash, so a profitable business can still run short of money when supplier bills fall due.","C":"A high profit margin says nothing about whether customers have paid, and some cash is still received.","D":"Suppliers want to be paid and do not refuse payment from profitable customers."}}},{"id":"P1_U5_MCQ_1083","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1083","question":"Netherton Bathrooms reports revenue of $350,000 for the year and cost of sales of $210,000. Its operating expenses were $96,000. What is its gross profit?","options":{"A":"$44,000","B":"$210,000","C":"$140,000","D":"$560,000"},"correctOption":"C","correctAnswer":"$140,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, so $350,000 less $210,000 gives $140,000 before the $96,000 of operating expenses is deducted.","distractor_reasons":{"A":"$44,000 is the profit for the year after deducting the $96,000 operating expenses, not gross profit.","B":"$210,000 is the cost of sales and has not been subtracted from revenue.","C":"Gross profit is revenue minus cost of sales, so $350,000 less $210,000 gives $140,000 before the $96,000 of operating expenses is deducted.","D":"$560,000 adds revenue and cost of sales together instead of subtracting cost of sales."}}},{"id":"P1_U5_MCQ_1084","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1084","question":"Overton Bookbinders has current assets of $74,000 and current liabilities of $39,000. It buys a binding machine for $15,000 cash. What is its working capital immediately afterwards?","options":{"A":"$35,000","B":"$50,000","C":"$24,000","D":"$20,000"},"correctOption":"D","correctAnswer":"$20,000","questionType":"MCQ","explanation":{"correct_reason":"Paying $15,000 cash for a non-current asset reduces current assets to $59,000 while current liabilities stay at $39,000, so working capital falls to $20,000.","distractor_reasons":{"A":"$35,000 is the working capital before the machine is bought and ignores the cash paid out.","B":"$50,000 deducts the machine cost from current liabilities instead of from current assets.","C":"$24,000 does not follow from the figures and appears to deduct only part of the cash payment.","D":"Paying $15,000 cash for a non-current asset reduces current assets to $59,000 while current liabilities stay at $39,000, so working capital falls to $20,000."}}},{"id":"P1_U5_MCQ_1085","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1085","question":"Pearlbrook Jewellery has current assets of $132,000 and current liabilities of $60,000 at the year end. What is the current ratio of the business at that date?","options":{"A":"2.2:1","B":"1.2:1","C":"0.5:1","D":"3.2:1"},"correctOption":"A","correctAnswer":"2.2:1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio divides current assets by current liabilities, so $132,000 divided by $60,000 gives 2.2:1.","distractor_reasons":{"A":"The current ratio divides current assets by current liabilities, so $132,000 divided by $60,000 gives 2.2:1.","B":"1.2:1 would require current assets of $72,000, which is far below the $132,000 reported.","C":"0.5:1 divides current liabilities by current assets and so reverses the formula.","D":"3.2:1 would require current assets of $192,000 against the $60,000 of current liabilities."}}},{"id":"P1_U5_MCQ_1086","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1086","question":"Quinton Dry Cleaning is profitable but needs a bank loan to replace its machines. Which reason best explains why profit alone does not provide enough finance for this purchase?","options":{"A":"Profit is only earned after a bank loan has been fully repaid","B":"Profit is a surplus after costs, but much of the cash generated is used for drawings, tax and other payments","C":"Banks require every profitable business to borrow money each year","D":"Machinery can never be bought with money earned from sales"},"correctOption":"B","correctAnswer":"Profit is a surplus after costs, but much of the cash generated is used for drawings, tax and other payments","questionType":"MCQ","explanation":{"correct_reason":"Profit is an accounting surplus, and cash earned may already have gone on owners' drawings, tax and working capital, so it is rarely enough to buy machines outright.","distractor_reasons":{"A":"Profit is calculated before any loan repayment and does not depend on a loan being cleared.","B":"Profit is an accounting surplus, and cash earned may already have gone on owners' drawings, tax and working capital, so it is rarely enough to buy machines outright.","C":"Banks do not force profitable firms to borrow; borrowing is a choice based on need.","D":"Sales receipts are the main source of cash and are regularly used to buy machinery outright."}}},{"id":"P1_U5_MCQ_1087","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1087","question":"Rothbury Hampers forecasts an opening balance of $1,800, trading inflows of $50,000, trading outflows of $46,000, a new loan of $25,000 and a loan repayment of $12,000. What is the closing balance?","options":{"A":"$6,800","B":"$30,800","C":"$18,800","D":"$19,000"},"correctOption":"C","correctAnswer":"$18,800","questionType":"MCQ","explanation":{"correct_reason":"Trading gives a net inflow of $4,000, and adding the $25,000 loan and deducting the $12,000 repayment gives $17,000, which added to the $1,800 opening balance is $18,800.","distractor_reasons":{"A":"$6,800 ignores the $12,000 loan repayment and so overstates the closing balance by that amount.","B":"$30,800 adds the loan repayment instead of deducting it from the cash position.","C":"Trading gives a net inflow of $4,000, and adding the $25,000 loan and deducting the $12,000 repayment gives $17,000, which added to the $1,800 opening balance is $18,800.","D":"$19,000 leaves out the $1,800 opening balance and treats the movement as the closing figure."}}},{"id":"P1_U5_MCQ_1088","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1088","question":"Sedgefield Golf had opening inventory of $12,500, purchases of $68,000 and closing inventory of $15,000 during the year. What was its cost of sales for the year?","options":{"A":"$95,500","B":"$70,500","C":"$80,500","D":"$65,500"},"correctOption":"D","correctAnswer":"$65,500","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is $12,500 opening inventory plus $68,000 purchases less $15,000 closing inventory, which gives $65,500.","distractor_reasons":{"A":"$95,500 adds all three figures together and so counts the closing inventory twice.","B":"$70,500 deducts both opening and closing inventory from purchases, which is incorrect.","C":"$80,500 is opening inventory plus purchases before any adjustment for closing inventory.","D":"Cost of sales is $12,500 opening inventory plus $68,000 purchases less $15,000 closing inventory, which gives $65,500."}}},{"id":"P1_U5_MCQ_1089","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1089","question":"Templeton Taxis has total current assets of $108,000, including cash of $14,000 and inventory of $38,000 at the year end. What is the value of its trade receivables?","options":{"A":"$56,000","B":"$94,000","C":"$52,000","D":"$70,000"},"correctOption":"A","correctAnswer":"$56,000","questionType":"MCQ","explanation":{"correct_reason":"Receivables are what remains of current assets after cash and inventory, so $108,000 less $14,000 less $38,000 gives $56,000.","distractor_reasons":{"A":"Receivables are what remains of current assets after cash and inventory, so $108,000 less $14,000 less $38,000 gives $56,000.","B":"$94,000 subtracts only the $14,000 of cash and ignores the $38,000 of inventory.","C":"$52,000 subtracts only the $38,000 inventory and ignores the $14,000 of cash.","D":"$70,000 adds the cash to the inventory and deducts that total from current assets incorrectly."}}},{"id":"P1_U5_MCQ_1090","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1090","question":"Uffington Stables has current assets of $90,000, of which inventory is $36,000, and current liabilities of $30,000 at the year end. What is its acid-test ratio?","options":{"A":"3.0:1","B":"1.8:1","C":"1.2:1","D":"0.6:1"},"correctOption":"B","correctAnswer":"1.8:1","questionType":"MCQ","explanation":{"correct_reason":"Liquid assets are $90,000 less $36,000 of inventory, which is $54,000, and dividing by $30,000 of current liabilities gives 1.8:1.","distractor_reasons":{"A":"3.0:1 is the current ratio and includes the $36,000 of inventory that must be excluded.","B":"Liquid assets are $90,000 less $36,000 of inventory, which is $54,000, and dividing by $30,000 of current liabilities gives 1.8:1.","C":"1.2:1 wrongly divides the inventory figure by current liabilities instead of using liquid assets.","D":"0.6:1 uses an incorrect liquid asset total and does not follow from the figures given."}}},{"id":"P1_U5_MCQ_1091","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1091","question":"Vernham Music borrows $480,000 for five years at a simple interest rate of 9% a year to buy new premises. What is the total interest paid over the five years?","options":{"A":"$43,200","B":"$129,600","C":"$216,000","D":"$696,000"},"correctOption":"C","correctAnswer":"$216,000","questionType":"MCQ","explanation":{"correct_reason":"Annual interest is 9% of $480,000, which is $43,200, and multiplying this by five years gives total interest of $216,000.","distractor_reasons":{"A":"$43,200 is only one year of interest and ignores the remaining four years of the loan.","B":"$129,600 covers only three years at 9% and understates the interest for the full five years.","C":"Annual interest is 9% of $480,000, which is $43,200, and multiplying this by five years gives total interest of $216,000.","D":"$696,000 adds the interest to the $480,000 principal, which is the total repayment rather than interest."}}},{"id":"P1_U5_MCQ_1092","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1092","question":"Warkworth Kites starts April with $8,000 cash. Forecast net cash flow is +$2,500 in April and -$11,000 in May. What is the forecast closing balance at the end of May?","options":{"A":"$5,500","B":"$10,500","C":"$500","D":"-$500"},"correctOption":"D","correctAnswer":"-$500","questionType":"MCQ","explanation":{"correct_reason":"After April the balance is $10,500, and the $11,000 outflow in May takes it below zero to a closing balance of -$500.","distractor_reasons":{"A":"$5,500 subtracts the $2,500 inflow from the opening balance instead of adding it.","B":"$10,500 is the closing balance at the end of April and ignores the May outflow.","C":"$500 has the right size but the wrong sign, since the balance is overdrawn at the end of May.","D":"After April the balance is $10,500, and the $11,000 outflow in May takes it below zero to a closing balance of -$500."}}},{"id":"P1_U5_MCQ_1093","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1093","question":"Yattendon Wines made a profit before tax of $60,000 in the year. Corporation tax is charged at 25% of profit. What is the profit for the year after tax?","options":{"A":"$45,000","B":"$15,000","C":"$75,000","D":"$60,000"},"correctOption":"A","correctAnswer":"$45,000","questionType":"MCQ","explanation":{"correct_reason":"Tax is 25% of $60,000, which is $15,000, so subtracting this from profit before tax leaves a profit after tax of $45,000.","distractor_reasons":{"A":"Tax is 25% of $60,000, which is $15,000, so subtracting this from profit before tax leaves a profit after tax of $45,000.","B":"$15,000 is the tax charge and not the profit that remains in the business after tax.","C":"$75,000 adds the tax to the profit before tax instead of subtracting it.","D":"$60,000 is the profit before tax and ignores the corporation tax that must be paid."}}},{"id":"P1_U5_MCQ_1094","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1094","question":"Zeals Cameras has owners' equity of $260,000 and non-current liabilities of $90,000 at the year end. It has no other long-term finance. What is its capital employed?","options":{"A":"$170,000","B":"$350,000","C":"$260,000","D":"$90,000"},"correctOption":"B","correctAnswer":"$350,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is the total of owners' equity and non-current liabilities, so $260,000 plus $90,000 gives $350,000.","distractor_reasons":{"A":"$170,000 subtracts the non-current liabilities from equity instead of adding them.","B":"Capital employed is the total of owners' equity and non-current liabilities, so $260,000 plus $90,000 gives $350,000.","C":"$260,000 is only the owners' equity and leaves out the $90,000 of long-term borrowing.","D":"$90,000 is only the non-current liabilities and excludes the owners' capital entirely."}}},{"id":"P1_U5_MCQ_1095","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1095","question":"Ashdown Bakery reports operating profit of $52,000 for the year and capital employed of $260,000 at the year end. What is its return on capital employed?","options":{"A":"52%","B":"5%","C":"20%","D":"2%"},"correctOption":"C","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, so $52,000 divided by $260,000 multiplied by 100 gives 20%.","distractor_reasons":{"A":"52% uses the operating profit as though it were already a percentage of the capital employed.","B":"5% divides the capital employed by the profit and then misplaces the decimal point.","C":"Return on capital employed is operating profit divided by capital employed, so $52,000 divided by $260,000 multiplied by 100 gives 20%.","D":"2% misplaces the decimal point and does not follow from $52,000 divided by $260,000."}}},{"id":"P1_U5_MCQ_1096","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1096","question":"Driftwell Engineering needs finance for a machine it will use for ten years, and for stock it will sell within three months. Which approach best matches the term of the finance to the need?","options":{"A":"Use a ten-year loan for both the machine and the stock","B":"Use an overdraft for both to keep the arrangement simple","C":"Use a ten-year loan for the stock and an overdraft for the machine","D":"Use a long-term loan for the machine and a short-term overdraft for the stock"},"correctOption":"D","correctAnswer":"Use a long-term loan for the machine and a short-term overdraft for the stock","questionType":"MCQ","explanation":{"correct_reason":"The machine will be used for ten years, so long-term finance suits it, while stock sold within three months should be funded by short-term finance such as an overdraft.","distractor_reasons":{"A":"Using a ten-year loan for stock leaves the business paying interest long after the stock has been sold.","B":"An overdraft for the machine would have to be renewed or repaid while the machine is still in use.","C":"This reverses the matching principle by funding long-term assets short term and short-term assets long term.","D":"The machine will be used for ten years, so long-term finance suits it, while stock sold within three months should be funded by short-term finance such as an overdraft."}}},{"id":"P1_U5_MCQ_1097","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1097","question":"Glenmore Water's managers prepare a monthly cash flow forecast before agreeing to a large new contract. Which is the main benefit of this forecast for the business?","options":{"A":"It predicts months when cash will be short so that finance can be arranged in advance","B":"It calculates the depreciation charge that will appear in the accounts","C":"It shows the market value of the business to its shareholders","D":"It guarantees that the business will avoid all cash outflows"},"correctOption":"A","correctAnswer":"It predicts months when cash will be short so that finance can be arranged in advance","questionType":"MCQ","explanation":{"correct_reason":"A monthly forecast highlights months when payments exceed receipts, giving managers time to arrange an overdraft or delay spending before the contract starts.","distractor_reasons":{"A":"A monthly forecast highlights months when payments exceed receipts, giving managers time to arrange an overdraft or delay spending before the contract starts.","B":"Depreciation is a non-cash accounting charge and is not calculated in a cash flow forecast.","C":"A cash flow forecast deals with future cash movements, not the market value of the business.","D":"Outflows are unavoidable in business; the forecast helps manage them rather than eliminate them."}}},{"id":"P1_U5_MCQ_1098","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1098","question":"Hartwell Organs has gross profit of $210,000 and a profit for the year of $84,000. It has no interest charges. What were its operating expenses?","options":{"A":"$294,000","B":"$126,000","C":"$84,000","D":"$210,000"},"correctOption":"B","correctAnswer":"$126,000","questionType":"MCQ","explanation":{"correct_reason":"With no interest charges, expenses are gross profit minus profit for the year, so $210,000 less $84,000 gives $126,000.","distractor_reasons":{"A":"$294,000 adds the gross profit and the profit for the year instead of subtracting one from the other.","B":"With no interest charges, expenses are gross profit minus profit for the year, so $210,000 less $84,000 gives $126,000.","C":"$84,000 is the profit for the year, not the expenses deducted to reach it from gross profit.","D":"$210,000 is the gross profit before any operating expenses have been deducted."}}},{"id":"P1_U5_MCQ_1099","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1099","question":"Ingleby Marine has inventory of $42,000, trade receivables of $36,000, cash of $8,000 and current liabilities of $54,000 at the year end. What is its working capital at that date?","options":{"A":"$86,000","B":"$54,000","C":"$32,000","D":"$22,000"},"correctOption":"C","correctAnswer":"$32,000","questionType":"MCQ","explanation":{"correct_reason":"Current assets total $42,000 plus $36,000 plus $8,000, which is $86,000, and deducting $54,000 of current liabilities gives working capital of $32,000.","distractor_reasons":{"A":"$86,000 is the total of current assets and still has the $54,000 of current liabilities to be deducted.","B":"$54,000 is the current liabilities figure, which is not working capital on its own.","C":"Current assets total $42,000 plus $36,000 plus $8,000, which is $86,000, and deducting $54,000 of current liabilities gives working capital of $32,000.","D":"$22,000 leaves out the $8,000 of cash when adding up the current assets."}}},{"id":"P1_U5_MCQ_1100","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1100","question":"Larkfield Furniture reports revenue of $360,000 and a profit for the year of $45,000. Its gross profit was $126,000. What was its profit margin for the year?","options":{"A":"35%","B":"45%","C":"8%","D":"12.5%"},"correctOption":"D","correctAnswer":"12.5%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year divided by revenue, so $45,000 divided by $360,000 multiplied by 100 gives 12.5%.","distractor_reasons":{"A":"35% is the gross profit margin using $126,000, not the profit margin based on $45,000.","B":"45% treats the $45,000 profit figure as though it were already a percentage of revenue.","C":"8% divides $45,000 by $562,500 rather than by the $360,000 of revenue.","D":"Profit margin is profit for the year divided by revenue, so $45,000 divided by $360,000 multiplied by 100 gives 12.5%."}}},{"id":"P1_U5_MCQ_1101","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1101","question":"Harlowgate Furniture Ltd needs $240,000 to install an automated cutting line. It holds $85,000 in retained profit and its bank has agreed a $60,000 five-year loan. How much extra finance must the business still raise?","options":{"A":"$95,000","B":"$155,000","C":"$180,000","D":"$385,000"},"correctOption":"A","correctAnswer":"$95,000","questionType":"MCQ","explanation":{"correct_reason":"Subtracting both funds already available from the $240,000 project cost leaves $240,000 minus $85,000 minus $60,000, which equals $95,000 still to be raised.","distractor_reasons":{"A":"Subtracting both funds already available from the $240,000 project cost leaves $240,000 minus $85,000 minus $60,000, which equals $95,000 still to be raised.","B":"This deducts only the $85,000 retained profit and ignores the agreed $60,000 loan, so it overstates the shortfall as $155,000. The resulting figure therefore cannot be the correct answer to this question.","C":"This deducts only the $60,000 bank loan and ignores the $85,000 retained profit, so it overstates the finance still needed. The resulting figure therefore cannot be the correct answer to this question.","D":"This adds all three figures together instead of subtracting the funds already available from the $240,000 project cost. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1102","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1102","question":"Ravenscroft Bakery forecasts receipts of $64,000 and payments of $52,500 for April. Its opening cash balance on 1 April is $8,400. What is the forecast closing cash balance at 30 April?","options":{"A":"$11,500","B":"$19,900","C":"$3,100","D":"$8,400"},"correctOption":"B","correctAnswer":"$19,900","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $64,000 minus $52,500, giving $11,500, and adding this inflow to the $8,400 opening balance produces a closing balance of $19,900.","distractor_reasons":{"A":"This is only the net cash flow of $11,500; it forgets to add the $8,400 opening balance that the business already holds. The resulting figure therefore cannot be the correct answer to this question.","B":"Net cash flow is $64,000 minus $52,500, giving $11,500, and adding this inflow to the $8,400 opening balance produces a closing balance of $19,900.","C":"This subtracts the $8,400 opening balance instead of adding it to the $11,500 net inflow, reversing the direction of the opening balance. The resulting figure therefore cannot be the correct answer to this question.","D":"This simply repeats the opening balance and assumes receipts and payments cancel each other out during April. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1103","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1103","question":"Wexcombe Toys Ltd records revenue of $186,000 for the year. Its cost of sales is $109,000 and overhead expenses are $48,000. What is its gross profit?","options":{"A":"$29,000","B":"$138,000","C":"$77,000","D":"$109,000"},"correctOption":"C","correctAnswer":"$77,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales only: $186,000 minus $109,000 equals $77,000, with overheads deducted at a later stage.","distractor_reasons":{"A":"This is the profit for the year, found by also deducting the $48,000 overheads from the $77,000 gross profit. The resulting figure therefore cannot be the correct answer to this question.","B":"This deducts the $48,000 overheads from revenue but forgets to deduct the $109,000 cost of sales as well. The resulting figure therefore cannot be the correct answer to this question.","C":"Gross profit is revenue minus cost of sales only: $186,000 minus $109,000 equals $77,000, with overheads deducted at a later stage.","D":"This repeats the cost of sales figure rather than deducting it from revenue to find gross profit. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1104","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1104","question":"Colversham Hardware Ltd has inventories of $42,000, trade receivables of $26,000, cash of $9,000 and current liabilities of $55,000 at its year end. What is its working capital?","options":{"A":"$77,000","B":"$13,000","C":"$132,000","D":"$22,000"},"correctOption":"D","correctAnswer":"$22,000","questionType":"MCQ","explanation":{"correct_reason":"Current assets total $42,000 plus $26,000 plus $9,000, which is $77,000, and deducting current liabilities of $55,000 gives working capital of $22,000.","distractor_reasons":{"A":"This is the total of current assets before deducting the $55,000 of current liabilities owed by the business. The resulting figure therefore cannot be the correct answer to this question.","B":"This omits the $9,000 cash from current assets, giving $68,000 minus $55,000 rather than the correct $77,000 minus $55,000. The resulting figure therefore cannot be the correct answer to this question.","C":"This adds current liabilities to current assets instead of subtracting them, which wrongly inflates working capital. That is why this option does not answer the question correctly.","D":"Current assets total $42,000 plus $26,000 plus $9,000, which is $77,000, and deducting current liabilities of $55,000 gives working capital of $22,000."}}},{"id":"P1_U5_MCQ_1105","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1105","question":"Fenwick Marine Supplies has current assets of $96,000, made up of inventory $38,000, trade receivables $40,000 and cash $18,000. Current liabilities are $40,000. What is its current ratio?","options":{"A":"2.4 : 1","B":"1.45 : 1","C":"0.42 : 1","D":"1.4 : 1"},"correctOption":"A","correctAnswer":"2.4 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio divides total current assets by current liabilities, so $96,000 divided by $40,000 gives 2.4 : 1 for Fenwick Marine Supplies.","distractor_reasons":{"A":"The current ratio divides total current assets by current liabilities, so $96,000 divided by $40,000 gives 2.4 : 1 for Fenwick Marine Supplies.","B":"This is the acid-test ratio, which removes the $38,000 inventory before dividing the remaining $58,000 by $40,000. The resulting figure therefore cannot be the correct answer to this question.","C":"This inverts the calculation by dividing current liabilities of $40,000 by current assets of $96,000. The resulting figure therefore cannot be the correct answer to this question.","D":"This leaves out the $40,000 trade receivables and divides only inventory plus cash of $56,000 by $40,000. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1106","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1106","question":"Aldermere Cafes Ltd needs $15,000 for three months to cover a seasonal shortage of cash before summer trade begins. Which source of finance is most appropriate?","options":{"A":"A 15-year bank loan","B":"A bank overdraft","C":"A debenture repayable in 2040","D":"Selling a non-current asset"},"correctOption":"B","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"A three-month seasonal gap needs short-term flexible finance, and an overdraft can be repaid as summer cash returns, limiting interest charges.","distractor_reasons":{"A":"A 15-year loan would charge interest for many years to fund a need lasting only three months before summer trade. The resulting figure therefore cannot be the correct answer to this question.","B":"A three-month seasonal gap needs short-term flexible finance, and an overdraft can be repaid as summer cash returns, limiting interest charges.","C":"A debenture repayable in 2040 is long-term borrowing that is far too costly and inflexible for a three-month cash gap. The resulting figure therefore cannot be the correct answer to this question.","D":"Selling a non-current asset permanently reduces the capacity of the business to fund a short temporary shortage of cash. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1107","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1107","question":"Penngarth Dairy forecasts total receipts of $88,000 and total payments of $79,300 for June. What is the forecast net cash flow for the month, and is it an inflow or an outflow?","options":{"A":"$167,300","B":"-$8,700","C":"$8,700","D":"$79,300"},"correctOption":"C","correctAnswer":"$8,700","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is total receipts minus total payments, so $88,000 minus $79,300 gives an inflow of $8,700 for Penngarth Dairy in June.","distractor_reasons":{"A":"This adds receipts and payments together instead of subtracting the $79,300 outflow from the $88,000 inflow. The resulting figure therefore cannot be the correct answer to this question.","B":"This reverses the direction of the calculation, treating the $8,700 surplus of receipts over payments as an outflow. The resulting figure therefore cannot be the correct answer to this question.","C":"Net cash flow is total receipts minus total payments, so $88,000 minus $79,300 gives an inflow of $8,700 for Penngarth Dairy in June.","D":"This simply repeats the payments figure and ignores the $88,000 of receipts entirely. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1108","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1108","question":"Thornbury Cycles Ltd buys bicycles for resale, pays shop wages and van depreciation, and pays dividends to its owners. Which item is treated as an expense in the profit and loss account?","options":{"A":"Purchase of bicycles for resale","B":"Dividends paid to shareholders","C":"Repayment of a bank loan","D":"Depreciation of delivery vans"},"correctOption":"D","correctAnswer":"Depreciation of delivery vans","questionType":"MCQ","explanation":{"correct_reason":"Depreciation spreads the cost of the delivery vans over their useful life and is deducted as an expense when calculating Thornbury Cycles' profit.","distractor_reasons":{"A":"Bicycles bought for resale are cost of sales, deducted from revenue before gross profit rather than shown as an expense. That is why this option does not answer the question correctly.","B":"Dividends are an appropriation of profit paid to owners, not an expense charged in arriving at profit. That is why this option does not answer the question correctly.","C":"Repaying a bank loan is a movement of capital that reduces cash and liabilities, not an expense; only the interest is a cost. That is why this option does not answer the question correctly.","D":"Depreciation spreads the cost of the delivery vans over their useful life and is deducted as an expense when calculating Thornbury Cycles' profit."}}},{"id":"P1_U5_MCQ_1109","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1109","question":"Marchwood Studios Ltd has a mortgage repayable in 2038 and also owes trade payables, a bank overdraft and tax. Which of these is classified as a non-current liability?","options":{"A":"The mortgage repayable in 2038","B":"Trade payables","C":"The bank overdraft","D":"Tax payable"},"correctOption":"A","correctAnswer":"The mortgage repayable in 2038","questionType":"MCQ","explanation":{"correct_reason":"A mortgage due in 2038 is not payable within twelve months of the statement date, so it is a long-term non-current liability.","distractor_reasons":{"A":"A mortgage due in 2038 is not payable within twelve months of the statement date, so it is a long-term non-current liability.","B":"Trade payables are normally settled within weeks or months, so they are current liabilities rather than long-term borrowing. That is why this option does not answer the question correctly.","C":"A bank overdraft is repayable on demand and therefore appears among current liabilities, not non-current liabilities. That is why this option does not answer the question correctly.","D":"Tax payable falls due in the short term and is classified as a current liability on the statement of financial position. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1110","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1110","question":"Calderwick Printers reports revenue of $250,000 and a cost of sales of $175,000 for the year. Using these figures, what is its gross profit margin to one decimal place?","options":{"A":"42.9%","B":"30%","C":"70%","D":"0.3%"},"correctOption":"B","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $250,000 minus $175,000, equal to $75,000, and $75,000 divided by $250,000 multiplied by 100 gives a gross profit margin of 30%.","distractor_reasons":{"A":"This divides the $75,000 gross profit by the $175,000 cost of sales instead of by the $250,000 revenue. The resulting figure therefore cannot be the correct answer to this question.","B":"Gross profit is $250,000 minus $175,000, equal to $75,000, and $75,000 divided by $250,000 multiplied by 100 gives a gross profit margin of 30%.","C":"This expresses the $175,000 cost of sales as a percentage of revenue, which is the cost of sales percentage. The resulting figure therefore cannot be the correct answer to this question.","D":"This misplaces the decimal point when converting the ratio of 0.30 into a percentage figure. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1111","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1111","question":"Blymhill Textiles Ltd kept part of last year's profit inside the business instead of distributing it. It now uses those funds to buy a new loom. Which source of finance is this?","options":{"A":"A bank loan","B":"A debenture","C":"Retained profit","D":"Trade credit"},"correctOption":"C","correctAnswer":"Retained profit","questionType":"MCQ","explanation":{"correct_reason":"Profit kept in the business rather than paid out to owners is retained profit, an internal source that carries no interest or repayment schedule.","distractor_reasons":{"A":"A bank loan is external borrowing that must be repaid with interest, not profit already earned and kept by the firm. That is why this option does not answer the question correctly.","B":"A debenture is long-term external borrowing from investors, so it creates a new liability rather than using existing funds. That is why this option does not answer the question correctly.","C":"Profit kept in the business rather than paid out to owners is retained profit, an internal source that carries no interest or repayment schedule.","D":"Trade credit is extra time given by suppliers to pay for goods, which is external finance rather than the firm's own profit. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1112","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1112","question":"Culmstock Couriers is preparing a cash flow forecast for the next six months. Which item should be excluded because it does not involve any cash payment?","options":{"A":"Wages paid to drivers","B":"Cash from the sale of an old van","C":"Repayment of a bank loan","D":"Depreciation of the courier vans"},"correctOption":"D","correctAnswer":"Depreciation of the courier vans","questionType":"MCQ","explanation":{"correct_reason":"Depreciation is an accounting allocation of an asset's cost over its life and never involves a cash payment, so it is left out of a cash flow forecast.","distractor_reasons":{"A":"Wages paid to drivers are a regular cash outflow and must appear as a payment in the forecast. That is why this option does not answer the question correctly.","B":"Selling an old van brings cash into the business, so it is recorded as an inflow in the forecast. That is why this option does not answer the question correctly.","C":"Repaying a bank loan is a cash payment that reduces the bank balance, so it belongs in the forecast. That is why this option does not answer the question correctly.","D":"Depreciation is an accounting allocation of an asset's cost over its life and never involves a cash payment, so it is left out of a cash flow forecast."}}},{"id":"P1_U5_MCQ_1113","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1113","question":"Bexmoor Brewing Ltd reports revenue, cost of sales and expenses in its annual profit and loss account. Which formula correctly calculates the gross profit figure shown in that account?","options":{"A":"Revenue - cost of sales","B":"Revenue - expenses","C":"Revenue - cost of sales - expenses","D":"Revenue + cost of sales"},"correctOption":"A","correctAnswer":"Revenue - cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Gross profit measures the surplus after deducting only the direct cost of sales from revenue, before expenses such as rent and wages.","distractor_reasons":{"A":"Gross profit measures the surplus after deducting only the direct cost of sales from revenue, before expenses such as rent and wages.","B":"Deducting expenses from revenue but not cost of sales mixes the two stages and does not give gross profit. That is why this option does not answer the question correctly.","C":"Deducting both cost of sales and expenses gives the profit for the year, not the gross profit. That is why this option does not answer the question correctly.","D":"Adding cost of sales to revenue treats a cost as income and produces a figure larger than revenue. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1114","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1114","question":"Ashbyvale Pharmacies owns a shop, holds medicines for resale, is owed money by customers and has cash in the bank. Which group lists only current assets?","options":{"A":"The shop, medicines and cash","B":"Medicines for resale, trade receivables and cash","C":"Trade receivables, delivery vans and cash","D":"Cash, the shop and medicines"},"correctOption":"B","correctAnswer":"Medicines for resale, trade receivables and cash","questionType":"MCQ","explanation":{"correct_reason":"Inventory, trade receivables and cash will all be used or converted into cash within a year, so all three are current assets.","distractor_reasons":{"A":"The shop is a long-term non-current asset, so this group is not made up solely of current assets. That is why this option does not answer the question correctly.","B":"Inventory, trade receivables and cash will all be used or converted into cash within a year, so all three are current assets.","C":"Delivery vans are non-current assets used for several years, so including them makes this group incorrect. That is why this option does not answer the question correctly.","D":"The shop is held for long-term use rather than sale, so it is a non-current asset and not a current asset. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1115","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1115","question":"Sedgeworth Salons has an operating profit of $45,000 and capital employed of $300,000. Which ratio best shows how efficiently it has used the capital invested in the business?","options":{"A":"Gross profit margin","B":"Current ratio","C":"Return on capital employed","D":"Acid-test ratio"},"correctOption":"C","correctAnswer":"Return on capital employed","questionType":"MCQ","explanation":{"correct_reason":"ROCE compares operating profit with capital employed, so $45,000 against $300,000 shows the return earned on the funds invested in the salons.","distractor_reasons":{"A":"The gross profit margin compares gross profit with revenue, so it measures selling performance rather than capital efficiency. That is why this option does not answer the question correctly.","B":"The current ratio compares current assets with current liabilities and says nothing about the return on invested capital. That is why this option does not answer the question correctly.","C":"ROCE compares operating profit with capital employed, so $45,000 against $300,000 shows the return earned on the funds invested in the salons.","D":"The acid-test ratio is a liquidity measure based on current assets excluding inventory, not a measure of capital efficiency. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1116","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1116","question":"Dunmowe Motors Ltd borrows $150,000 from its bank at an interest rate of 8% a year to fund a showroom refit. What is the annual interest charge?","options":{"A":"$1,200","B":"$18,750","C":"$150,000","D":"$12,000"},"correctOption":"D","correctAnswer":"$12,000","questionType":"MCQ","explanation":{"correct_reason":"Annual interest is 8% of the $150,000 borrowed, and $150,000 multiplied by 0.08 equals $12,000 for each year of the loan.","distractor_reasons":{"A":"This treats 8% as 0.8%, misplacing the decimal point and producing an interest charge ten times too small. The resulting figure therefore cannot be the correct answer to this question.","B":"This divides $150,000 by 8 instead of multiplying it by 0.08, which is not how a percentage interest rate is applied. The resulting figure therefore cannot be the correct answer to this question.","C":"This repeats the loan principal and ignores the 8% interest rate that the bank charges each year. The resulting figure therefore cannot be the correct answer to this question.","D":"Annual interest is 8% of the $150,000 borrowed, and $150,000 multiplied by 0.08 equals $12,000 for each year of the loan."}}},{"id":"P1_U5_MCQ_1117","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1117","question":"Northcote Pottery Ltd made a profit of $46,000 last year but still ran out of cash in December. Which explanation best fits this apparent contradiction?","options":{"A":"It gave customers long credit while paying its suppliers quickly","B":"Its revenue exceeded its total costs","C":"It charged depreciation on its kilns","D":"It issued new shares for cash in November"},"correctOption":"A","correctAnswer":"It gave customers long credit while paying its suppliers quickly","questionType":"MCQ","explanation":{"correct_reason":"Generous customer credit delays receipts while prompt payment to suppliers speeds up outflows, so cash can run short even with a $46,000 profit.","distractor_reasons":{"A":"Generous customer credit delays receipts while prompt payment to suppliers speeds up outflows, so cash can run short even with a $46,000 profit.","B":"Revenue exceeding total costs explains why profit of $46,000 was earned, but it does not explain a cash shortage. The resulting figure therefore cannot be the correct answer to this question.","C":"Depreciation is a non-cash expense, so charging it on the kilns would reduce profit without using any cash. That is why this option does not answer the question correctly.","D":"Issuing new shares for cash brings money into the business, which would ease rather than cause a cash shortage. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1118","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1118","question":"Otterbourne Brewing Ltd buys barley, hops and bottles, pays brewery wages and repays a bank loan. Which item is part of its cost of sales rather than an expense?","options":{"A":"Wages of the office accountant","B":"Barley, hops and bottles used in brewing","C":"Interest paid on the bank loan","D":"Repayment of the bank loan"},"correctOption":"B","correctAnswer":"Barley, hops and bottles used in brewing","questionType":"MCQ","explanation":{"correct_reason":"Materials consumed directly in making the product are cost of sales, deducted from revenue to calculate gross profit for the brewery.","distractor_reasons":{"A":"The office accountant's wages are an administrative expense charged after gross profit, not a direct production cost. That is why this option does not answer the question correctly.","B":"Materials consumed directly in making the product are cost of sales, deducted from revenue to calculate gross profit for the brewery.","C":"Interest on the bank loan is a finance cost deducted after expenses, not part of the direct cost of brewing. That is why this option does not answer the question correctly.","D":"Repaying the loan principal is a capital cash movement that reduces a liability and is not a profit and loss item. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1119","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1119","question":"Stapleford Engineering Ltd buys a lathe for $80,000 and depreciates it by $16,000 in the first year. What is the effect of this depreciation on its statement of financial position?","options":{"A":"Current assets fall by $16,000","B":"Liabilities rise by $16,000","C":"Non-current assets and equity both fall by $16,000","D":"There is no effect because no cash is paid"},"correctOption":"C","correctAnswer":"Non-current assets and equity both fall by $16,000","questionType":"MCQ","explanation":{"correct_reason":"Accumulated depreciation cuts the lathe's carrying value by $16,000, and the fall in profit reduces equity by the same $16,000.","distractor_reasons":{"A":"The lathe is a non-current asset, so depreciation reduces non-current assets rather than current assets. That is why this option does not answer the question correctly.","B":"Depreciation is not owed to anyone, so it creates no liability on the statement of financial position. That is why this option does not answer the question correctly.","C":"Accumulated depreciation cuts the lathe's carrying value by $16,000, and the fall in profit reduces equity by the same $16,000.","D":"Although no cash moves, depreciation still reduces the book value of assets and the equity shown in the statement. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1120","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1120","question":"Hollinsworth Hardware Ltd has inventory of $24,000, trade receivables of $15,000, cash of $3,000 and current liabilities of $30,000 at the year end. What is its acid-test ratio?","options":{"A":"1.4 : 1","B":"0.5 : 1","C":"1.67 : 1","D":"0.6 : 1"},"correctOption":"D","correctAnswer":"0.6 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test excludes inventory, so receivables of $15,000 plus cash of $3,000 give $18,000, which divided by $30,000 equals 0.6 : 1.","distractor_reasons":{"A":"This is the current ratio, which includes the $24,000 inventory that the acid test deliberately removes. The resulting figure therefore cannot be the correct answer to this question.","B":"This divides only the $15,000 trade receivables by $30,000 and leaves out the $3,000 of cash. The resulting figure therefore cannot be the correct answer to this question.","C":"This inverts the calculation by dividing the $30,000 current liabilities by the $18,000 liquid assets. The resulting figure therefore cannot be the correct answer to this question.","D":"The acid test excludes inventory, so receivables of $15,000 plus cash of $3,000 give $18,000, which divided by $30,000 equals 0.6 : 1."}}},{"id":"P1_U5_MCQ_1121","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1121","question":"Grangeholt Hotels Ltd plans a $3 million extension that will take four years to build and will then be used for at least twenty years. Which source of finance best matches the project?","options":{"A":"A 10-year bank loan","B":"A 30-day overdraft","C":"Trade credit from building suppliers","D":"A six-month short-term loan"},"correctOption":"A","correctAnswer":"A 10-year bank loan","questionType":"MCQ","explanation":{"correct_reason":"A long-life asset should be funded with long-term finance, so a 10-year loan spreads repayment over the years in which the extension earns revenue.","distractor_reasons":{"A":"A long-life asset should be funded with long-term finance, so a 10-year loan spreads repayment over the years in which the extension earns revenue.","B":"A 30-day overdraft must be repaid almost immediately, long before a four-year building project can generate any cash. The resulting figure therefore cannot be the correct answer to this question.","C":"Trade credit from suppliers covers materials for a few weeks, so it cannot fund a $3 million project lasting four years. The resulting figure therefore cannot be the correct answer to this question.","D":"A six-month loan falls due before the extension is even finished, creating a repayment crisis rather than matching the asset. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1122","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1122","question":"Kestrelby Foods Ltd is owed $62,000 by customers who take 90 days to pay, and it is short of cash. Which action would most quickly improve its cash inflow?","options":{"A":"Extend customer credit to 120 days","B":"Ask customers to settle within 30 days","C":"Buy extra raw materials for cash","D":"Pay suppliers earlier to earn discounts"},"correctOption":"B","correctAnswer":"Ask customers to settle within 30 days","questionType":"MCQ","explanation":{"correct_reason":"Cutting customer credit from 90 days to 30 days speeds up collection of the $62,000 owed, so cash arrives two months sooner.","distractor_reasons":{"A":"Extending credit to 120 days delays receipts by another month and makes the cash shortage worse. The resulting figure therefore cannot be the correct answer to this question.","B":"Cutting customer credit from 90 days to 30 days speeds up collection of the $62,000 owed, so cash arrives two months sooner.","C":"Buying extra raw materials for cash creates an immediate outflow, reducing the cash available. That is why this option does not answer the question correctly.","D":"Paying suppliers earlier speeds up outflows, which leaves less cash in the business, not more. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1123","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1123","question":"Wrenbury Engineering Ltd has a gross profit of $148,000. Its expenses are $71,000 and interest payable on its bank loan is $9,000. What is its profit for the year?","options":{"A":"$77,000","B":"$139,000","C":"$68,000","D":"$219,000"},"correctOption":"C","correctAnswer":"$68,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is $148,000 minus $71,000 minus $9,000, which equals $68,000 after deducting both expenses and loan interest.","distractor_reasons":{"A":"This deducts the $71,000 expenses but forgets the $9,000 interest payable on the bank loan. The resulting figure therefore cannot be the correct answer to this question.","B":"This deducts the $9,000 interest but forgets the $71,000 of other expenses charged after gross profit. The resulting figure therefore cannot be the correct answer to this question.","C":"Profit for the year is $148,000 minus $71,000 minus $9,000, which equals $68,000 after deducting both expenses and loan interest.","D":"This adds the figures instead of deducting expenses and interest from the $148,000 gross profit. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1124","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1124","question":"Tarnside Software Ltd reports total assets of $720,000 and equity of $290,000 in its latest statement of financial position. What are its total liabilities at that date?","options":{"A":"$1,010,000","B":"$290,000","C":"$720,000","D":"$430,000"},"correctOption":"D","correctAnswer":"$430,000","questionType":"MCQ","explanation":{"correct_reason":"Liabilities equal total assets minus equity, so $720,000 minus $290,000 gives $430,000 owed by Tarnside Software Ltd at that date.","distractor_reasons":{"A":"This adds assets and equity together instead of subtracting equity from total assets. That is why this option does not answer the question correctly.","B":"This repeats the equity figure, which is the owners' claim rather than the amount owed to lenders. That is why this option does not answer the question correctly.","C":"This repeats total assets without deducting the $290,000 equity funded by the owners. The resulting figure therefore cannot be the correct answer to this question.","D":"Liabilities equal total assets minus equity, so $720,000 minus $290,000 gives $430,000 owed by Tarnside Software Ltd at that date."}}},{"id":"P1_U5_MCQ_1125","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1125","question":"Hollowdean Furniture Ltd has a ROCE of 18% but a profit margin of only 3% for the year. Which conclusion about its financial performance is most appropriate?","options":{"A":"It earns a strong return on capital despite keeping little profit per sale","B":"It is certain to have a liquidity problem","C":"Its gross profit margin must also be 3%","D":"It cannot be profitable at all"},"correctOption":"A","correctAnswer":"It earns a strong return on capital despite keeping little profit per sale","questionType":"MCQ","explanation":{"correct_reason":"An 18% ROCE with a 3% profit margin means the firm earns a strong return on capital even though each sale leaves little profit.","distractor_reasons":{"A":"An 18% ROCE with a 3% profit margin means the firm earns a strong return on capital even though each sale leaves little profit.","B":"Profitability ratios say nothing about cash or short-term debts, so they cannot prove a liquidity problem exists. That is why this option does not answer the question correctly.","C":"Gross profit margin is calculated before expenses, so it is normally higher than the 3% profit margin, not equal to it. The resulting figure therefore cannot be the correct answer to this question.","D":"A 3% profit margin is still a positive profit, and the 18% ROCE confirms the business is profitable. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1126","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1126","question":"Silverleigh Bakeries borrows $60,000 at 7% simple interest a year for three years to buy a second oven. What total interest will it pay over the three years?","options":{"A":"$4,200","B":"$12,600","C":"$16,800","D":"$25,200"},"correctOption":"B","correctAnswer":"$12,600","questionType":"MCQ","explanation":{"correct_reason":"Interest is $60,000 multiplied by 7%, which is $4,200 a year, and over three years the total paid is $12,600.","distractor_reasons":{"A":"This is the interest for one year only, so it ignores the two further years of the three-year loan. That is why this option does not answer the question correctly.","B":"Interest is $60,000 multiplied by 7%, which is $4,200 a year, and over three years the total paid is $12,600.","C":"This calculates interest for four years, one year more than the three-year term of the loan. That is why this option does not answer the question correctly.","D":"This calculates interest for six years, double the actual three-year term of the loan. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1127","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1127","question":"Ravensdale Foods Ltd is applying to its bank for a loan to fund a new warehouse. Why does a cash flow forecast help the business in this application?","options":{"A":"It proves the business is profitable","B":"It calculates the depreciation charge","C":"It shows the timing and size of expected cash shortages","D":"It replaces the need for a profit and loss account"},"correctOption":"C","correctAnswer":"It shows the timing and size of expected cash shortages","questionType":"MCQ","explanation":{"correct_reason":"A forecast identifies exactly when and by how much cash will fall short, helping the bank judge the size and duration of the facility needed.","distractor_reasons":{"A":"A cash flow forecast records receipts and payments, so it shows liquidity rather than whether the business is profitable. That is why this option does not answer the question correctly.","B":"Depreciation is a non-cash expense and is deliberately excluded from a cash flow forecast. That is why this option does not answer the question correctly.","C":"A forecast identifies exactly when and by how much cash will fall short, helping the bank judge the size and duration of the facility needed.","D":"The forecast and the profit and loss account serve different purposes, so one cannot replace the other. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1128","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1128","question":"Alderbury Furniture Ltd reports a cost of sales of $116,000 and a gross profit of $84,000 for the year. What was its revenue for that year?","options":{"A":"$32,000","B":"$116,000","C":"$232,000","D":"$200,000"},"correctOption":"D","correctAnswer":"$200,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals cost of sales plus gross profit, so $116,000 plus $84,000 gives revenue of $200,000 for Alderbury Furniture Ltd.","distractor_reasons":{"A":"This subtracts gross profit from cost of sales, but revenue must be larger than either figure because both are deductions from it. That is why this option does not answer the question correctly.","B":"This repeats the cost of sales figure and ignores the $84,000 gross profit that must be added to it. The resulting figure therefore cannot be the correct answer to this question.","C":"This doubles the $116,000 cost of sales instead of adding the $84,000 gross profit to it. The resulting figure therefore cannot be the correct answer to this question.","D":"Revenue equals cost of sales plus gross profit, so $116,000 plus $84,000 gives revenue of $200,000 for Alderbury Furniture Ltd."}}},{"id":"P1_U5_MCQ_1129","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1129","question":"Winstanley Optics Ltd has bought a patent for a new lens design, holds finished lenses, is owed money by opticians and keeps cash in the bank. Which item is a non-current asset?","options":{"A":"The patent for the lens design","B":"Finished lenses held for sale","C":"Money owed by opticians","D":"Cash held at the bank"},"correctOption":"A","correctAnswer":"The patent for the lens design","questionType":"MCQ","explanation":{"correct_reason":"A patent gives long-term legal rights for several years and is an intangible non-current asset rather than inventory or cash.","distractor_reasons":{"A":"A patent gives long-term legal rights for several years and is an intangible non-current asset rather than inventory or cash.","B":"Finished lenses are inventory held for resale and will be sold within a year, so they are current assets. That is why this option does not answer the question correctly.","C":"Money owed by opticians is a trade receivable expected to be collected soon, making it a current asset. That is why this option does not answer the question correctly.","D":"Cash held at the bank is the most liquid current asset and is never classified as non-current. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1130","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1130","question":"Pendlebury Bakeries Ltd wants to know whether it can pay its short-term debts as they fall due. Which pair of ratios would best help the business assess this?","options":{"A":"Gross profit margin and ROCE","B":"Current ratio and acid-test ratio","C":"ROCE and profit margin","D":"Gross profit margin and acid-test ratio"},"correctOption":"B","correctAnswer":"Current ratio and acid-test ratio","questionType":"MCQ","explanation":{"correct_reason":"Both the current ratio and the acid-test ratio compare current assets with current liabilities, so together they directly test short-term liquidity.","distractor_reasons":{"A":"These two ratios measure profitability and returns, so neither shows whether short-term debts can be paid. That is why this option does not answer the question correctly.","B":"Both the current ratio and the acid-test ratio compare current assets with current liabilities, so together they directly test short-term liquidity.","C":"Both ROCE and profit margin assess profit performance rather than the ability to meet current liabilities. That is why this option does not answer the question correctly.","D":"The gross profit margin measures selling performance, so only the acid-test ratio in this pair tests liquidity. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1131","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1131","question":"Fallowmere Engineering Ltd wants to raise $500,000 to expand without taking on a fixed interest obligation that must be paid every year. Which source best meets this aim?","options":{"A":"A bank loan","B":"A debenture","C":"Issuing ordinary shares","D":"A bank overdraft"},"correctOption":"C","correctAnswer":"Issuing ordinary shares","questionType":"MCQ","explanation":{"correct_reason":"Ordinary shareholders receive dividends only when profits allow, so issuing shares raises $500,000 without creating a fixed annual interest charge.","distractor_reasons":{"A":"A bank loan carries contractual interest that must be paid every year whatever the level of profit. That is why this option does not answer the question correctly.","B":"A debenture pays a fixed rate of interest that is legally owed each year regardless of trading results. That is why this option does not answer the question correctly.","C":"Ordinary shareholders receive dividends only when profits allow, so issuing shares raises $500,000 without creating a fixed annual interest charge.","D":"A bank overdraft charges interest and is repayable on demand, so it offers no relief from fixed finance costs. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1132","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1132","question":"Marlbrook Nurseries starts September with a cash balance of $6,200. It forecasts receipts of $41,000 and payments of $38,500 during the month. What is the forecast closing balance?","options":{"A":"$2,500","B":"$3,700","C":"$47,200","D":"$8,700"},"correctOption":"D","correctAnswer":"$8,700","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $41,000 minus $38,500, equal to $2,500, and adding the $6,200 opening balance gives a closing balance of $8,700.","distractor_reasons":{"A":"This is only the net cash flow of $2,500 and ignores the $6,200 the business already held at the start. The resulting figure therefore cannot be the correct answer to this question.","B":"This subtracts the $2,500 net inflow from the opening balance rather than adding it, reversing the direction of the flow. The resulting figure therefore cannot be the correct answer to this question.","C":"This adds the $6,200 opening balance to receipts only and ignores the $38,500 of payments made. The resulting figure therefore cannot be the correct answer to this question.","D":"Net cash flow is $41,000 minus $38,500, equal to $2,500, and adding the $6,200 opening balance gives a closing balance of $8,700."}}},{"id":"P1_U5_MCQ_1133","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1133","question":"Birkenshaw Confectionery Ltd held opening inventory of $30,000, made purchases of $90,000 and held closing inventory of $25,000. What is its cost of sales for the year?","options":{"A":"$95,000","B":"$120,000","C":"$85,000","D":"$145,000"},"correctOption":"A","correctAnswer":"$95,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales equals opening inventory plus purchases minus closing inventory, so $30,000 plus $90,000 minus $25,000 equals $95,000 for the year.","distractor_reasons":{"A":"Cost of sales equals opening inventory plus purchases minus closing inventory, so $30,000 plus $90,000 minus $25,000 equals $95,000 for the year.","B":"This adds opening inventory to purchases but forgets to deduct the $25,000 of closing inventory still held. The resulting figure therefore cannot be the correct answer to this question.","C":"This adds closing inventory of $25,000 and deducts opening inventory of $30,000, reversing the stock adjustment. The resulting figure therefore cannot be the correct answer to this question.","D":"This adds closing inventory to opening inventory and purchases instead of deducting it. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1134","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1134","question":"Cobhampton Interiors Ltd has current assets of $120,000, made up of cash of $30,000, trade receivables of $45,000 and inventory. Current liabilities are $60,000 and working capital is $60,000. What is the inventory figure?","options":{"A":"$30,000","B":"$45,000","C":"$60,000","D":"$15,000"},"correctOption":"B","correctAnswer":"$45,000","questionType":"MCQ","explanation":{"correct_reason":"Inventory equals current assets of $120,000 minus cash of $30,000 and receivables of $45,000, which leaves $45,000 of stock at the year end.","distractor_reasons":{"A":"This repeats the $30,000 cash figure rather than the balancing inventory amount. The resulting figure therefore cannot be the correct answer to this question.","B":"Inventory equals current assets of $120,000 minus cash of $30,000 and receivables of $45,000, which leaves $45,000 of stock at the year end.","C":"This uses the working capital figure, which is not itself one of the current assets making up the total. That is why this option does not answer the question correctly.","D":"This deducts both receivables and current liabilities from current assets rather than isolating the inventory figure. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1135","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1135","question":"Draycott Ceramics Ltd reports an operating profit of $96,000 and capital employed of $640,000 for the year. What is its return on capital employed percentage?","options":{"A":"6.7%","B":"96.0%","C":"15.0%","D":"9.6%"},"correctOption":"C","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"ROCE divides operating profit by capital employed, so $96,000 divided by $640,000 multiplied by 100 gives a return of 15.0%.","distractor_reasons":{"A":"This inverts the calculation by dividing the $640,000 capital employed by the $96,000 operating profit. The resulting figure therefore cannot be the correct answer to this question.","B":"This mistakes operating profit in thousands for a percentage and ignores the $640,000 of capital employed. The resulting figure therefore cannot be the correct answer to this question.","C":"ROCE divides operating profit by capital employed, so $96,000 divided by $640,000 multiplied by 100 gives a return of 15.0%.","D":"This misplaces the decimal point when converting the ratio of 0.15 into a percentage. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1136","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1136","question":"Swinbrook Pottery Ltd is considering issuing debentures to raise $2 million for expansion. Which statement best describes a disadvantage of this source of finance for the business?","options":{"A":"The loan is repaid only when profits allow","B":"Ownership of the business is diluted","C":"It can only finance day-to-day expenses","D":"Fixed interest must be paid even when profits fall"},"correctOption":"D","correctAnswer":"Fixed interest must be paid even when profits fall","questionType":"MCQ","explanation":{"correct_reason":"Debenture holders are creditors entitled to fixed interest each year, so a loss-making period still creates a compulsory finance cost.","distractor_reasons":{"A":"Debentures have a set redemption date and must be repaid regardless of whether profits are earned. That is why this option does not answer the question correctly.","B":"Debentures are debt, so they create no voting shares and do not dilute the owners' control. That is why this option does not answer the question correctly.","C":"Debentures raise long-term capital and are not limited to financing everyday running expenses. That is why this option does not answer the question correctly.","D":"Debenture holders are creditors entitled to fixed interest each year, so a loss-making period still creates a compulsory finance cost."}}},{"id":"P1_U5_MCQ_1137","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1137","question":"Thurlby Marine Ltd is preparing a cash flow forecast for the next quarter. Which of the following would be recorded as a cash inflow in that forecast?","options":{"A":"$40,000 received from a bank loan","B":"Wages paid to boat builders","C":"Payment for a new forklift","D":"Tax paid to the government"},"correctOption":"A","correctAnswer":"$40,000 received from a bank loan","questionType":"MCQ","explanation":{"correct_reason":"Borrowing brings $40,000 into the business bank account, so it is recorded as a cash inflow in Thurlby Marine's forecast.","distractor_reasons":{"A":"Borrowing brings $40,000 into the business bank account, so it is recorded as a cash inflow in Thurlby Marine's forecast.","B":"Wages paid to boat builders are money leaving the business and are therefore a cash outflow. That is why this option does not answer the question correctly.","C":"Buying a forklift is a capital payment that reduces the bank balance, so it is an outflow. That is why this option does not answer the question correctly.","D":"Tax paid is a compulsory payment out of the business and appears as a cash outflow, not an inflow. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1138","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1138","question":"Elmsworth Fashion Ltd makes a profit after tax of $70,000 and pays $20,000 to its shareholders. Which item in this appropriation is the dividend for the year?","options":{"A":"The $70,000 profit after tax","B":"$20,000 paid to shareholders","C":"The retained profit of $50,000","D":"The tax deducted from profit"},"correctOption":"B","correctAnswer":"$20,000 paid to shareholders","questionType":"MCQ","explanation":{"correct_reason":"A dividend is the share of profit distributed to the owners, so the $20,000 paid to shareholders is the dividend.","distractor_reasons":{"A":"The $70,000 profit after tax is the total amount available, not the portion handed to the owners. The resulting figure therefore cannot be the correct answer to this question.","B":"A dividend is the share of profit distributed to the owners, so the $20,000 paid to shareholders is the dividend.","C":"Retained profit is the $50,000 kept in the business after the dividend has been paid out. The resulting figure therefore cannot be the correct answer to this question.","D":"Tax is paid to the government before profit after tax is calculated and is not a distribution to owners. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1139","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1139","question":"Netherby Care Homes Ltd prepares a statement of financial position at the end of its financial year. What is the main purpose of this financial statement?","options":{"A":"To record cash receipts and payments over the year","B":"To calculate gross profit for the trading period","C":"To show assets, liabilities and equity at a particular date","D":"To forecast sales for the coming year"},"correctOption":"C","correctAnswer":"To show assets, liabilities and equity at a particular date","questionType":"MCQ","explanation":{"correct_reason":"The statement of financial position is a snapshot at one date, listing what the business owns, what it owes and the owners' equity.","distractor_reasons":{"A":"Cash receipts and payments over a period are recorded in a cash flow forecast or cash book, not the statement. That is why this option does not answer the question correctly.","B":"Gross profit is calculated in the profit and loss account by deducting cost of sales from revenue. That is why this option does not answer the question correctly.","C":"The statement of financial position is a snapshot at one date, listing what the business owns, what it owes and the owners' equity.","D":"Forecasting future sales is a marketing planning task and is not the function of the statement of financial position. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1140","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1140","question":"Stanbury Foods Ltd reports revenue of $220,000 and a cost of sales of $121,000 for the year. What is its gross profit margin to the nearest whole percentage?","options":{"A":"55%","B":"81.8%","C":"4.5%","D":"45%"},"correctOption":"D","correctAnswer":"45%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $220,000 minus $121,000, equal to $99,000, and $99,000 divided by $220,000 multiplied by 100 gives a margin of 45%.","distractor_reasons":{"A":"This is the cost of sales percentage, found by dividing $121,000 by revenue rather than using gross profit. The resulting figure therefore cannot be the correct answer to this question.","B":"This divides the $99,000 gross profit by the $121,000 cost of sales instead of by revenue, giving 81.8%. The resulting figure therefore cannot be the correct answer to this question.","C":"This misplaces the decimal point when converting the ratio of 0.45 into a percentage figure. The resulting figure therefore cannot be the correct answer to this question.","D":"Gross profit is $220,000 minus $121,000, equal to $99,000, and $99,000 divided by $220,000 multiplied by 100 gives a margin of 45%."}}},{"id":"P1_U5_MCQ_1141","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1141","question":"Brackenholme Dairy Ltd has a monthly electricity bill, a three-year van lease and a planned $400,000 refrigeration plant. Which is the most suitable use of a long-term bank loan?","options":{"A":"The refrigeration plant","B":"The monthly electricity bill","C":"The three-year van lease","D":"Paying staff wages each month"},"correctOption":"A","correctAnswer":"The refrigeration plant","questionType":"MCQ","explanation":{"correct_reason":"The refrigeration plant is a long-life asset costing $400,000, so spreading its cost over several years through a long-term loan is appropriate.","distractor_reasons":{"A":"The refrigeration plant is a long-life asset costing $400,000, so spreading its cost over several years through a long-term loan is appropriate.","B":"A monthly electricity bill is a recurring running cost best met from regular revenue rather than borrowed capital. That is why this option does not answer the question correctly.","C":"A three-year lease is a medium-term commitment usually financed by lease payments, not a long-term loan. That is why this option does not answer the question correctly.","D":"Paying wages is a short-term operating cost that recovers quickly and needs working capital, not long-term debt. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1142","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1142","question":"Redmarley Printers forecasts receipts of $75,000, payments of $71,500 and an opening cash balance of $4,200 for May. What is the closing balance at the end of May?","options":{"A":"$3,500","B":"$7,700","C":"$700","D":"$79,200"},"correctOption":"B","correctAnswer":"$7,700","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $75,000 minus $71,500, equal to $3,500, and adding this to the $4,200 opening balance gives $7,700.","distractor_reasons":{"A":"This shows only the $3,500 net inflow and omits the opening cash balance of $4,200. The resulting figure therefore cannot be the correct answer to this question.","B":"Net cash flow is $75,000 minus $71,500, equal to $3,500, and adding this to the $4,200 opening balance gives $7,700.","C":"This subtracts the $3,500 inflow from the $4,200 opening balance instead of adding it. The resulting figure therefore cannot be the correct answer to this question.","D":"This adds the $4,200 opening balance to total receipts of $75,000 but ignores the $71,500 of payments. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1143","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1143","question":"Hartleybrook Toys Ltd reports revenue of $300,000, cost of sales of $180,000 and expenses of $72,000 for the year. What is its operating profit according to these figures?","options":{"A":"$120,000","B":"$192,000","C":"$48,000","D":"$108,000"},"correctOption":"C","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Operating profit is $300,000 minus $180,000 minus $72,000, which equals $48,000 after both cost of sales and expenses are deducted.","distractor_reasons":{"A":"This is the gross profit, which deducts only the $180,000 cost of sales and ignores the $72,000 expenses. The resulting figure therefore cannot be the correct answer to this question.","B":"This deducts the $72,000 expenses from revenue but forgets to deduct the $180,000 cost of sales. The resulting figure therefore cannot be the correct answer to this question.","C":"Operating profit is $300,000 minus $180,000 minus $72,000, which equals $48,000 after both cost of sales and expenses are deducted.","D":"This deducts expenses from the $180,000 cost of sales instead of from revenue, which is not a valid calculation. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1144","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1144","question":"Barrowden Timber Ltd has non-current liabilities of $300,000, current liabilities of $150,000 and equity of $450,000 at the year end. What is the value of its total assets?","options":{"A":"$600,000","B":"$750,000","C":"$450,000","D":"$900,000"},"correctOption":"D","correctAnswer":"$900,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets equal equity plus all liabilities, so $450,000 plus $300,000 plus $150,000 gives total assets of $900,000 at the year end.","distractor_reasons":{"A":"This adds the current liabilities but omits the $300,000 of non-current liabilities from total assets. The resulting figure therefore cannot be the correct answer to this question.","B":"This adds the non-current liabilities but omits the $150,000 of current liabilities from total assets. The resulting figure therefore cannot be the correct answer to this question.","C":"This repeats the equity figure alone and ignores both categories of liabilities owed. That is why this option does not answer the question correctly.","D":"Total assets equal equity plus all liabilities, so $450,000 plus $300,000 plus $150,000 gives total assets of $900,000 at the year end."}}},{"id":"P1_U5_MCQ_1145","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1145","question":"Longmarsh Packaging Ltd has current assets of $118,000 including inventory of $58,000, and current liabilities of $64,000. Which statement about its liquidity is most accurate?","options":{"A":"The current ratio is satisfactory but the acid test is below 1 : 1","B":"Both ratios are comfortably above 2 : 1","C":"Both ratios are below 1 : 1","D":"The acid-test ratio is higher than the current ratio"},"correctOption":"A","correctAnswer":"The current ratio is satisfactory but the acid test is below 1 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is $118,000 divided by $64,000, about 1.84 : 1, but the acid test is $60,000 divided by $64,000, about 0.94 : 1, so liquid cover is below 1 : 1.","distractor_reasons":{"A":"The current ratio is $118,000 divided by $64,000, about 1.84 : 1, but the acid test is $60,000 divided by $64,000, about 0.94 : 1, so liquid cover is below 1 : 1.","B":"A current ratio of about 1.84 : 1 is well below 2 : 1, and the acid-test ratio is about 0.94 : 1, so neither is comfortably above 2 : 1. The resulting figure therefore cannot be the correct answer to this question.","C":"The current ratio of about 1.84 : 1 is above 1 : 1, and only the acid-test ratio of about 0.94 : 1 falls below 1 : 1. The resulting figure therefore cannot be the correct answer to this question.","D":"The acid-test ratio is always lower than the current ratio when inventory is held, since inventory is subtracted. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1146","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1146","question":"Saltmarsh Florists is a sole trader, unlike a large public limited company. Which source of finance is available to this sole trader but not to the company?","options":{"A":"Retained profit","B":"A personal bank loan from the owner","C":"Trade credit","D":"A bank overdraft"},"correctOption":"B","correctAnswer":"A personal bank loan from the owner","questionType":"MCQ","explanation":{"correct_reason":"A sole trader is the owner personally and can borrow in their own name, whereas a public limited company must borrow in the company's name.","distractor_reasons":{"A":"Any profitable business, large or small, can keep back profit as retained profit for expansion. That is why this option does not answer the question correctly.","B":"A sole trader is the owner personally and can borrow in their own name, whereas a public limited company must borrow in the company's name.","C":"Trade credit is offered by suppliers to most trading organisations, regardless of their legal structure. That is why this option does not answer the question correctly.","D":"Banks offer overdrafts to both sole traders and large public limited companies with suitable accounts. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1147","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1147","question":"Alderston Toys Ltd forecasts a closing cash balance of -$12,000 for October. Which action would most directly correct this forecast deficit before the month begins?","options":{"A":"Increase the dividend paid to shareholders","B":"Buy more inventory for cash in October","C":"Arrange a short-term bank overdraft","D":"Offer customers longer credit terms"},"correctOption":"C","correctAnswer":"Arrange a short-term bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"An overdraft provides extra cash up to an agreed limit, which directly covers the forecast -$12,000 shortfall in October before the month begins.","distractor_reasons":{"A":"Paying a larger dividend takes more cash out of the business and deepens the negative balance. That is why this option does not answer the question correctly.","B":"Buying more inventory for cash increases the October outflow and worsens the deficit. That is why this option does not answer the question correctly.","C":"An overdraft provides extra cash up to an agreed limit, which directly covers the forecast -$12,000 shortfall in October before the month begins.","D":"Longer credit terms delay customer receipts, so cash arrives later and the deficit persists. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1148","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1148","question":"Grimsdale Chemicals Ltd reports revenue of $540,000, gross profit of $216,000 and expenses of $158,000. What is its profit for the year before interest and tax?","options":{"A":"$374,000","B":"$324,000","C":"$914,000","D":"$58,000"},"correctOption":"D","correctAnswer":"$58,000","questionType":"MCQ","explanation":{"correct_reason":"Profit before interest and tax is gross profit minus expenses, so $216,000 minus $158,000 equals $58,000 for Grimsdale Chemicals in the year.","distractor_reasons":{"A":"This adds the $158,000 expenses to the $216,000 gross profit instead of subtracting them, overstating profit. The resulting figure therefore cannot be the correct answer to this question.","B":"This deducts the $216,000 gross profit from revenue to leave $324,000, which is a deduction rather than the profit earned. The resulting figure therefore cannot be the correct answer to this question.","C":"This adds revenue, gross profit and expenses together rather than deducting expenses from gross profit. That is why this option does not answer the question correctly.","D":"Profit before interest and tax is gross profit minus expenses, so $216,000 minus $158,000 equals $58,000 for Grimsdale Chemicals in the year."}}},{"id":"P1_U5_MCQ_1149","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1149","question":"Fairholt Hotels Ltd is preparing its statement of financial position at the year end. Which item would appear in the equity section of that statement?","options":{"A":"Retained profit accumulated over past years","B":"A mortgage secured on the hotel buildings","C":"Trade payables owed to food suppliers","D":"Cash held in the hotel's bank account"},"correctOption":"A","correctAnswer":"Retained profit accumulated over past years","questionType":"MCQ","explanation":{"correct_reason":"Retained profit belongs to the shareholders and forms part of equity alongside share capital in the statement of financial position.","distractor_reasons":{"A":"Retained profit belongs to the shareholders and forms part of equity alongside share capital in the statement of financial position.","B":"A mortgage is borrowing owed to a lender, so it is a non-current liability rather than equity. That is why this option does not answer the question correctly.","C":"Trade payables are short-term debts owed to suppliers and are classified as current liabilities. That is why this option does not answer the question correctly.","D":"Cash is an asset the business owns, not a claim of the owners recorded within equity. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1150","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1150","question":"Miltonby Sports Ltd has current assets of $150,000, inventory of $60,000 and current liabilities of $90,000 at its year end. What is its acid-test ratio?","options":{"A":"1.67 : 1","B":"1.0 : 1","C":"0.6 : 1","D":"0.67 : 1"},"correctOption":"B","correctAnswer":"1.0 : 1","questionType":"MCQ","explanation":{"correct_reason":"Removing the $60,000 inventory leaves liquid assets of $90,000, which divided by current liabilities of $90,000 gives exactly 1.0 : 1.","distractor_reasons":{"A":"This is the current ratio, which includes the $60,000 inventory that the acid test excludes. The resulting figure therefore cannot be the correct answer to this question.","B":"Removing the $60,000 inventory leaves liquid assets of $90,000, which divided by current liabilities of $90,000 gives exactly 1.0 : 1.","C":"This inverts the ratio by dividing current liabilities of $90,000 by current assets of $150,000. The resulting figure therefore cannot be the correct answer to this question.","D":"This divides the $60,000 inventory by the $90,000 current liabilities, which measures inventory cover rather than liquid assets. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1151","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1151","question":"The owners of Oakenshaw Joinery, a small family firm, need $80,000 for new equipment. Why might they prefer a bank loan to issuing new shares?","options":{"A":"A loan never has to be repaid","B":"A loan carries no interest charge","C":"A loan keeps ownership and control within the family","D":"A loan increases the number of shareholders"},"correctOption":"C","correctAnswer":"A loan keeps ownership and control within the family","questionType":"MCQ","explanation":{"correct_reason":"Lenders such as banks gain no voting rights, so borrowing leaves the family's ownership and control of Oakenshaw Joinery unchanged.","distractor_reasons":{"A":"A bank loan must be repaid on the agreed date, usually with interest, so it is not permanent capital. That is why this option does not answer the question correctly.","B":"Interest is the price of a bank loan and is charged on the amount borrowed until it is repaid. That is why this option does not answer the question correctly.","C":"Lenders such as banks gain no voting rights, so borrowing leaves the family's ownership and control of Oakenshaw Joinery unchanged.","D":"A loan creates a liability to the bank rather than issuing shares, so no new shareholders are created. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1152","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1152","question":"Pindale Brewing Ltd has an opening cash balance of $12,000. It forecasts receipts of $88,000 and payments of $92,400 for November. What is its forecast closing balance?","options":{"A":"$4,400","B":"-$4,400","C":"$12,000","D":"$7,600"},"correctOption":"D","correctAnswer":"$7,600","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $88,000 minus $92,400, a deficit of $4,400, and subtracting this from the $12,000 opening balance leaves $7,600.","distractor_reasons":{"A":"This ignores the fact that payments exceed receipts, so the $4,400 net amount is a deficit rather than a surplus. The resulting figure therefore cannot be the correct answer to this question.","B":"This shows the net cash flow alone and forgets to add it to the $12,000 opening balance. The resulting figure therefore cannot be the correct answer to this question.","C":"This repeats the opening balance and ignores the $4,400 net outflow during November. The resulting figure therefore cannot be the correct answer to this question.","D":"Net cash flow is $88,000 minus $92,400, a deficit of $4,400, and subtracting this from the $12,000 opening balance leaves $7,600."}}},{"id":"P1_U5_MCQ_1153","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1153","question":"Wendlebury Ceramics Ltd is preparing its profit and loss account for the year. Which cost would be deducted after the gross profit has been calculated?","options":{"A":"Office administration salaries","B":"Clay used in making the pots","C":"Packaging for each pot sold","D":"Carriage inwards on raw materials"},"correctOption":"A","correctAnswer":"Office administration salaries","questionType":"MCQ","explanation":{"correct_reason":"Administration salaries are an operating expense, so they are deducted from gross profit to arrive at the operating profit for the year.","distractor_reasons":{"A":"Administration salaries are an operating expense, so they are deducted from gross profit to arrive at the operating profit for the year.","B":"Clay is a direct material consumed in production, so its cost forms part of cost of sales before gross profit. That is why this option does not answer the question correctly.","C":"Packaging for each pot sold is a direct selling cost included in cost of sales, not an administration expense. That is why this option does not answer the question correctly.","D":"Carriage inwards on raw materials is part of the cost of acquiring stock and is included in cost of sales. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1154","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1154","question":"Thackley Kitchens Ltd has current assets of $84,000, made up of inventory $36,000, trade receivables $40,000 and cash $8,000. Current liabilities are $39,000. What is its working capital?","options":{"A":"$84,000","B":"$45,000","C":"$123,000","D":"$39,000"},"correctOption":"B","correctAnswer":"$45,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so $84,000 minus $39,000 gives $45,000 of working capital for Thackley Kitchens Ltd.","distractor_reasons":{"A":"This is the total of current assets before the $39,000 of current liabilities is deducted. The resulting figure therefore cannot be the correct answer to this question.","B":"Working capital is current assets minus current liabilities, so $84,000 minus $39,000 gives $45,000 of working capital for Thackley Kitchens Ltd.","C":"This adds current liabilities to current assets instead of subtracting them from the total. That is why this option does not answer the question correctly.","D":"This repeats the current liabilities figure rather than the surplus of current assets over them. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1155","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1155","question":"Saxby Marine Ltd has calculated several ratios from its accounts. Why is it more useful to compare them with those of similar firms than to judge them in isolation?","options":{"A":"Ratios of other firms are always more accurate","B":"Ratios are meaningless without a cash flow forecast","C":"A ratio on its own does not show whether performance is good or poor","D":"Comparison removes the need for financial statements"},"correctOption":"C","correctAnswer":"A ratio on its own does not show whether performance is good or poor","questionType":"MCQ","explanation":{"correct_reason":"A single ratio has no benchmark, so comparing it with rivals in the same industry reveals whether the figure is relatively strong or weak.","distractor_reasons":{"A":"Other firms may use different accounting policies, so their ratios are not automatically more accurate. That is why this option does not answer the question correctly.","B":"Ratios can be interpreted without a cash flow forecast because they are calculated from the published statements. That is why this option does not answer the question correctly.","C":"A single ratio has no benchmark, so comparing it with rivals in the same industry reveals whether the figure is relatively strong or weak.","D":"Comparison uses the financial statements as its source and can never replace them. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1156","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1156","question":"Wexham Marine Ltd borrows $200,000 at 9% simple interest a year for four years to buy a boat. What total interest will it pay over the whole period?","options":{"A":"$18,000","B":"$36,000","C":"$218,000","D":"$72,000"},"correctOption":"D","correctAnswer":"$72,000","questionType":"MCQ","explanation":{"correct_reason":"Interest is $200,000 multiplied by 9%, which is $18,000 a year, and over four years the total charge is $72,000.","distractor_reasons":{"A":"This is the interest for a single year, so it ignores the remaining three years of the four-year loan. That is why this option does not answer the question correctly.","B":"This calculates interest for two years rather than the full four-year term of the loan. That is why this option does not answer the question correctly.","C":"This adds one year's interest to the principal instead of multiplying the annual interest by four. That is why this option does not answer the question correctly.","D":"Interest is $200,000 multiplied by 9%, which is $18,000 a year, and over four years the total charge is $72,000."}}},{"id":"P1_U5_MCQ_1157","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1157","question":"Coltonby Engineering Ltd is reviewing the risks to its cash flow for the coming year. Which event is least likely to cause a cash flow problem for the business?","options":{"A":"Receiving cash from the sale of new shares","B":"Allowing customers 90 days of credit","C":"Expanding output very quickly","D":"A seasonal fall in sales"},"correctOption":"A","correctAnswer":"Receiving cash from the sale of new shares","questionType":"MCQ","explanation":{"correct_reason":"Selling new shares brings a large cash inflow, so it eases a cash shortage rather than causing one for Coltonby Engineering Ltd.","distractor_reasons":{"A":"Selling new shares brings a large cash inflow, so it eases a cash shortage rather than causing one for Coltonby Engineering Ltd.","B":"Allowing 90 days of credit delays receipts and can leave the business short of cash while bills fall due. The resulting figure therefore cannot be the correct answer to this question.","C":"Rapid expansion usually requires heavy spending on materials and wages before extra sales revenue arrives. That is why this option does not answer the question correctly.","D":"A seasonal fall in sales reduces receipts while fixed payments such as rent and wages continue. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1158","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1158","question":"Fenby Glass Ltd has revenue of $250,000 and its cost of sales is 60% of revenue. Expenses are $45,000. What is its profit for the year?","options":{"A":"$100,000","B":"$55,000","C":"$150,000","D":"$45,000"},"correctOption":"B","correctAnswer":"$55,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is 60% of $250,000, which is $150,000, leaving gross profit of $100,000, and deducting $45,000 expenses gives $55,000.","distractor_reasons":{"A":"This is the gross profit, which deducts the $150,000 cost of sales but not the $45,000 of expenses. The resulting figure therefore cannot be the correct answer to this question.","B":"Cost of sales is 60% of $250,000, which is $150,000, leaving gross profit of $100,000, and deducting $45,000 expenses gives $55,000.","C":"This is the cost of sales figure and is a deduction from revenue, not the profit earned. That is why this option does not answer the question correctly.","D":"This repeats the expenses figure and ignores both revenue and cost of sales. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1159","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1159","question":"Havercroft Supplies Ltd pays a supplier $10,000 from its bank account. What is the immediate effect of this payment on its working capital at that moment?","options":{"A":"Working capital falls by $10,000","B":"Working capital rises by $10,000","C":"Working capital is unchanged","D":"Working capital falls by $20,000"},"correctOption":"C","correctAnswer":"Working capital is unchanged","questionType":"MCQ","explanation":{"correct_reason":"Cash falls by $10,000 and trade payables fall by the same $10,000, so current assets and current liabilities both drop and working capital is unchanged.","distractor_reasons":{"A":"Only the cash side of the transaction is considered, ignoring the equal fall in current liabilities. That is why this option does not answer the question correctly.","B":"Paying a supplier reduces both assets and liabilities, so working capital cannot rise. That is why this option does not answer the question correctly.","C":"Cash falls by $10,000 and trade payables fall by the same $10,000, so current assets and current liabilities both drop and working capital is unchanged.","D":"This treats the single $10,000 payment as though both assets and liabilities each fell twice. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1160","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1160","question":"Pennymoor Stores has a current ratio of 1.8 : 1 and an acid-test ratio of 0.7 : 1. What does this combination suggest about the business?","options":{"A":"It holds almost no inventory","B":"It has no current liabilities","C":"It is highly profitable","D":"It holds a large proportion of its current assets as inventory"},"correctOption":"D","correctAnswer":"It holds a large proportion of its current assets as inventory","questionType":"MCQ","explanation":{"correct_reason":"The big gap between the 1.8 current ratio and the 0.7 acid-test ratio shows that inventory makes up most of the current assets.","distractor_reasons":{"A":"If it held almost no inventory, the two ratios would be close together rather than far apart. That is why this option does not answer the question correctly.","B":"The business has current liabilities, since both ratios are calculated by dividing by them. That is why this option does not answer the question correctly.","C":"Liquidity ratios measure the ability to pay short-term debts and say nothing about profitability. That is why this option does not answer the question correctly.","D":"The big gap between the 1.8 current ratio and the 0.7 acid-test ratio shows that inventory makes up most of the current assets."}}},{"id":"P1_U5_MCQ_1161","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1161","question":"Millbrook Hardware is a growing retailer that buys stock from several suppliers. Which statement best explains why trade credit is a useful source of finance for this business?","options":{"A":"It delays payment for goods without charging interest","B":"It provides permanent capital that is never repaid","C":"It gives the supplier a share of the business","D":"It removes the need to hold any inventory"},"correctOption":"A","correctAnswer":"It delays payment for goods without charging interest","questionType":"MCQ","explanation":{"correct_reason":"Trade credit lets the retailer receive stock now and pay the supplier later, easing working capital without any interest charge.","distractor_reasons":{"A":"Trade credit lets the retailer receive stock now and pay the supplier later, easing working capital without any interest charge.","B":"Trade credit is a short-term debt that must be settled within the agreed period, not permanent capital. That is why this option does not answer the question correctly.","C":"Suppliers remain creditors and receive no ownership stake or voting rights in the retailer's business. That is why this option does not answer the question correctly.","D":"Trade credit finances the purchase of inventory but does not remove the need to hold stock. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1162","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1162","question":"Cranbourne Bakery has an opening balance of $4,000 on 1 September. September receipts are $30,000 and payments $27,000; October receipts are $25,000 and payments $29,500. What is the closing balance at 31 October?","options":{"A":"$7,000","B":"$2,500","C":"$1,000","D":"-$1,500"},"correctOption":"B","correctAnswer":"$2,500","questionType":"MCQ","explanation":{"correct_reason":"September adds $3,000 to give $7,000, and October's $4,500 deficit reduces that to a closing balance of $2,500 at 31 October.","distractor_reasons":{"A":"This is the closing balance at the end of September and ignores October's $4,500 net outflow. The resulting figure therefore cannot be the correct answer to this question.","B":"September adds $3,000 to give $7,000, and October's $4,500 deficit reduces that to a closing balance of $2,500 at 31 October.","C":"This subtracts September's $3,000 inflow from the opening balance instead of adding it. The resulting figure therefore cannot be the correct answer to this question.","D":"This shows only the combined net cash flow for the two months and omits the $4,000 opening balance. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1163","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1163","question":"Aldworth Engineering Ltd charges depreciation on its machinery each year. Which statement about the treatment of depreciation in its profit and loss account is correct?","options":{"A":"It reduces cash but does not reduce profit","B":"It increases both profit and cash","C":"It reduces profit but does not reduce cash","D":"It is only recorded when the asset is sold"},"correctOption":"C","correctAnswer":"It reduces profit but does not reduce cash","questionType":"MCQ","explanation":{"correct_reason":"Depreciation spreads the asset's cost as an expense, lowering reported profit, yet no money leaves the business when it is charged.","distractor_reasons":{"A":"Depreciation is a non-cash expense, so it lowers profit without any payment leaving the bank account. That is why this option does not answer the question correctly.","B":"Depreciation is a cost that reduces profit and has no effect at all on the cash balance. That is why this option does not answer the question correctly.","C":"Depreciation spreads the asset's cost as an expense, lowering reported profit, yet no money leaves the business when it is charged.","D":"Depreciation is charged each year over the asset's useful life, not only in the year of disposal. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1164","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1164","question":"Sandleigh Printers Ltd reports total assets of $500,000 and current assets of $120,000 in its statement of financial position. What is the value of its non-current assets?","options":{"A":"$620,000","B":"$120,000","C":"$500,000","D":"$380,000"},"correctOption":"D","correctAnswer":"$380,000","questionType":"MCQ","explanation":{"correct_reason":"Non-current assets are total assets minus current assets, so $500,000 minus $120,000 equals $380,000 for Sandleigh Printers Ltd at the year end.","distractor_reasons":{"A":"This adds current assets to total assets instead of subtracting them to isolate the non-current figure. That is why this option does not answer the question correctly.","B":"This repeats the current assets figure rather than the long-term assets that make up the balance. That is why this option does not answer the question correctly.","C":"This repeats total assets without removing the $120,000 of current assets. The resulting figure therefore cannot be the correct answer to this question.","D":"Non-current assets are total assets minus current assets, so $500,000 minus $120,000 equals $380,000 for Sandleigh Printers Ltd at the year end."}}},{"id":"P1_U5_MCQ_1165","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1165","question":"Kirby Mews Hotels Ltd reports a rising ROCE but a current ratio of only 0.6 : 1. What is the most appropriate interpretation of these two financial indicators?","options":{"A":"Profitability is improving while short-term liquidity is weak","B":"Both profitability and liquidity are strong","C":"Liquidity is strong but profitability is falling","D":"The business has no liabilities"},"correctOption":"A","correctAnswer":"Profitability is improving while short-term liquidity is weak","questionType":"MCQ","explanation":{"correct_reason":"A rising ROCE shows improving returns on capital, but a current ratio of 0.6 : 1 means current liabilities exceed current assets.","distractor_reasons":{"A":"A rising ROCE shows improving returns on capital, but a current ratio of 0.6 : 1 means current liabilities exceed current assets.","B":"A current ratio of 0.6 : 1 is well below the usual 1.5 to 2 : 1, so liquidity is weak rather than strong. The resulting figure therefore cannot be the correct answer to this question.","C":"The rising ROCE shows profitability is improving, while the low current ratio shows liquidity is poor. That is why this option does not answer the question correctly.","D":"A current ratio below 1 : 1 arises precisely because current liabilities exceed current assets. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1166","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1166","question":"Chelmsworth Fabrication Ltd buys premises for $600,000, paying a 25% deposit and funding the rest with a mortgage. How much does it borrow from the lender?","options":{"A":"$150,000","B":"$450,000","C":"$600,000","D":"$750,000"},"correctOption":"B","correctAnswer":"$450,000","questionType":"MCQ","explanation":{"correct_reason":"The deposit is 25% of $600,000, equal to $150,000, so the mortgage covers the remaining $450,000 of the purchase price.","distractor_reasons":{"A":"This is the 25% deposit paid up front, not the amount borrowed through the mortgage. The resulting figure therefore cannot be the correct answer to this question.","B":"The deposit is 25% of $600,000, equal to $150,000, so the mortgage covers the remaining $450,000 of the purchase price.","C":"This is the full purchase price, which ignores the $150,000 deposit already paid by the buyer. The resulting figure therefore cannot be the correct answer to this question.","D":"This adds the deposit to the price instead of deducting it from the amount that must be borrowed. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1167","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1167","question":"Wharfedale Couriers prepares a cash flow forecast for the year ahead. Why should it update the forecast every month rather than prepare it only once?","options":{"A":"The tax authorities require monthly forecasts","B":"Depreciation changes every month","C":"Actual receipts and payments differ from predictions, so figures need revising","D":"It replaces the need for a profit and loss account"},"correctOption":"C","correctAnswer":"Actual receipts and payments differ from predictions, so figures need revising","questionType":"MCQ","explanation":{"correct_reason":"Real receipts and payments rarely match forecasts, so monthly updates replace estimates with actual figures and give a more reliable view of future cash.","distractor_reasons":{"A":"Cash flow forecasts are a management planning tool and are not required monthly by tax authorities. That is why this option does not answer the question correctly.","B":"Depreciation is a non-cash item excluded from the forecast, so monthly changes in it are irrelevant. That is why this option does not answer the question correctly.","C":"Real receipts and payments rarely match forecasts, so monthly updates replace estimates with actual figures and give a more reliable view of future cash.","D":"The forecast covers cash movements while the profit and loss account measures profit, so they serve different purposes. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1168","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1168","question":"Lerwick Pottery Ltd wants to increase its gross profit without changing its selling prices or sales volume. Which change would achieve this aim for the coming year?","options":{"A":"Increasing the rent paid for the shop","B":"Paying higher wages to office staff","C":"Raising the interest rate on its loan","D":"Negotiating a lower price for clay"},"correctOption":"D","correctAnswer":"Negotiating a lower price for clay","questionType":"MCQ","explanation":{"correct_reason":"Clay is a direct material in cost of sales, so a lower purchase price reduces cost of sales and raises gross profit at unchanged revenue.","distractor_reasons":{"A":"Shop rent is an expense deducted after gross profit, so it does not change the gross profit figure. That is why this option does not answer the question correctly.","B":"Office salaries are administration expenses charged below gross profit, so they leave gross profit unaffected. That is why this option does not answer the question correctly.","C":"Loan interest is a finance cost deducted after expenses and has no effect on gross profit. That is why this option does not answer the question correctly.","D":"Clay is a direct material in cost of sales, so a lower purchase price reduces cost of sales and raises gross profit at unchanged revenue."}}},{"id":"P1_U5_MCQ_1169","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1169","question":"Wrekin Toys Ltd has total assets of $350,000 and total liabilities of $130,000 at its year end. What is the total equity of the business?","options":{"A":"$220,000","B":"$480,000","C":"$350,000","D":"$130,000"},"correctOption":"A","correctAnswer":"$220,000","questionType":"MCQ","explanation":{"correct_reason":"Equity is total assets minus total liabilities, so $350,000 minus $130,000 equals $220,000 of owners' capital in Wrekin Toys Ltd.","distractor_reasons":{"A":"Equity is total assets minus total liabilities, so $350,000 minus $130,000 equals $220,000 of owners' capital in Wrekin Toys Ltd.","B":"This adds liabilities to assets instead of subtracting what the business owes from what it owns. That is why this option does not answer the question correctly.","C":"This repeats total assets without deducting the $130,000 owed to lenders and creditors. The resulting figure therefore cannot be the correct answer to this question.","D":"This repeats the liabilities figure, which is a claim on the assets rather than the owners' equity. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1170","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1170","question":"Sparrowfield Foods Ltd has revenue of $480,000, cost of sales of $300,000 and operating profit of $36,000. What is its profit margin for the year, to one decimal place?","options":{"A":"13.3%","B":"7.5%","C":"0.75%","D":"37.5%"},"correctOption":"B","correctAnswer":"7.5%","questionType":"MCQ","explanation":{"correct_reason":"The profit margin divides operating profit by revenue, so $36,000 divided by $480,000 multiplied by 100 gives a margin of 7.5%.","distractor_reasons":{"A":"This inverts the calculation by dividing the $480,000 revenue by the $36,000 operating profit. The resulting figure therefore cannot be the correct answer to this question.","B":"The profit margin divides operating profit by revenue, so $36,000 divided by $480,000 multiplied by 100 gives a margin of 7.5%.","C":"This misplaces the decimal point when converting the ratio of 0.075 into a percentage figure. The resulting figure therefore cannot be the correct answer to this question.","D":"This calculates the gross profit margin from $180,000 gross profit rather than the profit margin from operating profit. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1171","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1171","question":"Woolmer Green Cafes Ltd needs $8,000 to cover a two-week gap before a busy festival period brings in cash. Which source of finance is most suitable for this shortfall?","options":{"A":"A 20-year mortgage","B":"Issuing ordinary shares","C":"A bank overdraft","D":"A debenture issue"},"correctOption":"C","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"A two-week gap needs very short-term flexible finance, and an overdraft can be cleared as soon as the festival cash arrives.","distractor_reasons":{"A":"A 20-year mortgage is long-term borrowing secured on property and is far too costly for a two-week need. The resulting figure therefore cannot be the correct answer to this question.","B":"Issuing ordinary shares raises permanent capital and is a slow, costly process for such a small temporary need. That is why this option does not answer the question correctly.","C":"A two-week gap needs very short-term flexible finance, and an overdraft can be cleared as soon as the festival cash arrives.","D":"A debenture is long-term debt with fixed interest, which does not match a two-week cash shortage. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1172","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1172","question":"Thornwick Motors Ltd is preparing a cash flow forecast for the next three months. Which transaction would appear as a cash payment in that forecast?","options":{"A":"Receiving a deposit from a customer","B":"Selling an old courtesy car","C":"Obtaining a bank loan","D":"Buying a diagnostic machine for cash"},"correctOption":"D","correctAnswer":"Buying a diagnostic machine for cash","questionType":"MCQ","explanation":{"correct_reason":"Paying cash for a diagnostic machine is money leaving the business, so it is recorded as a payment in the forecast.","distractor_reasons":{"A":"A customer deposit is money coming in and is therefore recorded as a receipt, not a payment. That is why this option does not answer the question correctly.","B":"Selling an old courtesy car brings cash into the business and is an inflow in the forecast. That is why this option does not answer the question correctly.","C":"Obtaining a bank loan increases the cash balance and appears as a financing inflow. That is why this option does not answer the question correctly.","D":"Paying cash for a diagnostic machine is money leaving the business, so it is recorded as a payment in the forecast."}}},{"id":"P1_U5_MCQ_1173","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1173","question":"Alderton Glass Ltd has gross profit of $160,000, expenses of $58,000 and interest payable of $7,000. What is its profit for the year after interest?","options":{"A":"$95,000","B":"$102,000","C":"$167,000","D":"$225,000"},"correctOption":"A","correctAnswer":"$95,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is $160,000 minus $58,000 minus $7,000, which equals $95,000 after deducting both expenses and interest payable.","distractor_reasons":{"A":"Profit for the year is $160,000 minus $58,000 minus $7,000, which equals $95,000 after deducting both expenses and interest payable.","B":"This deducts the $58,000 expenses but forgets to deduct the $7,000 of interest payable. The resulting figure therefore cannot be the correct answer to this question.","C":"This adds the interest to gross profit after deducting expenses instead of subtracting it. That is why this option does not answer the question correctly.","D":"This adds gross profit, expenses and interest together rather than deducting the costs. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1174","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1174","question":"Patterdale Engineering Ltd is preparing its statement of financial position at the year end. Which of the following would be classified as a non-current asset?","options":{"A":"Steel held for use in production","B":"Factory machinery used for ten years","C":"Cash in the business bank account","D":"Money owed by trade customers"},"correctOption":"B","correctAnswer":"Factory machinery used for ten years","questionType":"MCQ","explanation":{"correct_reason":"Factory machinery is bought for long-term use in production, so it is a non-current asset rather than inventory or cash.","distractor_reasons":{"A":"Steel held for production is inventory that will be consumed within the operating cycle, making it a current asset. That is why this option does not answer the question correctly.","B":"Factory machinery is bought for long-term use in production, so it is a non-current asset rather than inventory or cash.","C":"Cash at the bank is the most liquid current asset and is never treated as a non-current asset. That is why this option does not answer the question correctly.","D":"Money owed by customers is a trade receivable expected to be collected soon, so it is a current asset. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1175","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1175","question":"Ryedale Chemicals Ltd has operating profit of $84,000, revenue of $700,000 and capital employed of $560,000. What is its return on capital employed percentage for the year?","options":{"A":"12%","B":"6.7%","C":"15%","D":"80%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"ROCE divides operating profit by capital employed, so $84,000 divided by $560,000 multiplied by 100 equals a return of 15%.","distractor_reasons":{"A":"This is the profit margin, found by dividing the $84,000 operating profit by $700,000 of revenue. The resulting figure therefore cannot be the correct answer to this question.","B":"This inverts the ROCE calculation by dividing the $560,000 capital employed by operating profit. The resulting figure therefore cannot be the correct answer to this question.","C":"ROCE divides operating profit by capital employed, so $84,000 divided by $560,000 multiplied by 100 equals a return of 15%.","D":"This divides capital employed by revenue, which measures capital intensity rather than the return earned. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1176","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1176","question":"Seatonby Supplies Ltd is considering using a bank overdraft to cover a temporary cash shortage. Which is a disadvantage of this source of finance for the business?","options":{"A":"It dilutes the owners' control of the company","B":"It must be repaid over exactly ten years","C":"It cannot be used to cover wage payments","D":"It can be withdrawn when the bank demands repayment"},"correctOption":"D","correctAnswer":"It can be withdrawn when the bank demands repayment","questionType":"MCQ","explanation":{"correct_reason":"An overdraft is repayable on demand, so the bank can withdraw the facility at short notice and leave the business short of cash.","distractor_reasons":{"A":"An overdraft is borrowing from a bank and gives the lender no shares or voting rights in the company. That is why this option does not answer the question correctly.","B":"Overdrafts are short-term facilities with no fixed ten-year repayment schedule. That is why this option does not answer the question correctly.","C":"Overdraft cash can be used for any business payment, including wages, so this is not a restriction. That is why this option does not answer the question correctly.","D":"An overdraft is repayable on demand, so the bank can withdraw the facility at short notice and leave the business short of cash."}}},{"id":"P1_U5_MCQ_1177","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1177","question":"Fernhill Pottery is a new business seeking a bank loan to buy equipment. How does a well-prepared cash flow forecast help the business persuade the bank to lend?","options":{"A":"It demonstrates that cash shortages have been anticipated and planned for","B":"It guarantees that the business will make a profit","C":"It removes the need for any security on the loan","D":"It calculates the interest rate the bank should charge"},"correctOption":"A","correctAnswer":"It demonstrates that cash shortages have been anticipated and planned for","questionType":"MCQ","explanation":{"correct_reason":"Showing that shortfalls are forecast and how they will be covered reassures the lender that the borrower has planned responsibly.","distractor_reasons":{"A":"Showing that shortfalls are forecast and how they will be covered reassures the lender that the borrower has planned responsibly.","B":"A cash flow forecast deals with timing of cash, so it cannot guarantee that trading will be profitable. That is why this option does not answer the question correctly.","C":"Banks still require security or a guarantee, so the forecast does not remove that requirement. That is why this option does not answer the question correctly.","D":"Interest rates are set by the bank's policy, not calculated by the borrower's cash flow forecast. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1178","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1178","question":"Hurstbourne Motors Ltd sells a delivery van for $18,000, which is $3,000 above its book value. How should this transaction be treated in the accounts?","options":{"A":"As revenue from normal trading activity","B":"As a capital receipt, with the $3,000 gain increasing profit","C":"As a cost of sales deduction","D":"As an expense in the profit and loss account"},"correctOption":"B","correctAnswer":"As a capital receipt, with the $3,000 gain increasing profit","questionType":"MCQ","explanation":{"correct_reason":"Selling a non-current asset is a capital receipt, and the $3,000 excess over book value is a gain that raises profit.","distractor_reasons":{"A":"Revenue comes from selling goods or services in normal trading, not from disposing of a delivery van. That is why this option does not answer the question correctly.","B":"Selling a non-current asset is a capital receipt, and the $3,000 excess over book value is a gain that raises profit.","C":"A vehicle sale is not part of the cost of goods sold, so it cannot be deducted within cost of sales. That is why this option does not answer the question correctly.","D":"Only the $3,000 gain affects profit, so the full $18,000 cannot be recorded as an expense. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1179","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1179","question":"Ellershaw Engineering Ltd buys equipment for $240,000 and depreciates it evenly over eight years with no residual value. What is its net book value after two years?","options":{"A":"$210,000","B":"$60,000","C":"$180,000","D":"$240,000"},"correctOption":"C","correctAnswer":"$180,000","questionType":"MCQ","explanation":{"correct_reason":"Annual depreciation is $240,000 divided by eight, equal to $30,000, so after two years the $60,000 charged leaves a book value of $180,000.","distractor_reasons":{"A":"This deducts only one year's depreciation of $30,000 instead of the two years that have passed. The resulting figure therefore cannot be the correct answer to this question.","B":"This is the total depreciation for the two years, not the remaining net book value of the equipment. That is why this option does not answer the question correctly.","C":"Annual depreciation is $240,000 divided by eight, equal to $30,000, so after two years the $60,000 charged leaves a book value of $180,000.","D":"This repeats the original cost and ignores the depreciation charged over the two years. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1180","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1180","question":"Templetonby Retail Ltd has doubled its sales in a year, but its current ratio has fallen from 1.9 : 1 to 0.9 : 1. What does this pattern most likely indicate?","options":{"A":"The business has become more liquid as sales grew","B":"Its gross profit margin must have fallen sharply","C":"It has repaid all of its current liabilities","D":"Rapid growth has stretched working capital and created an overtrading risk"},"correctOption":"D","correctAnswer":"Rapid growth has stretched working capital and created an overtrading risk","questionType":"MCQ","explanation":{"correct_reason":"Fast sales growth often absorbs cash into inventory and receivables, so a current ratio falling to 0.9 : 1 signals that working capital is overstretched.","distractor_reasons":{"A":"A fall from 1.9 : 1 to 0.9 : 1 means liquidity has weakened, not improved. The resulting figure therefore cannot be the correct answer to this question.","B":"The current ratio measures liquidity, so it gives no direct evidence about the gross profit margin. That is why this option does not answer the question correctly.","C":"Repaying current liabilities would normally improve the current ratio rather than push it below 1 : 1. The resulting figure therefore cannot be the correct answer to this question.","D":"Fast sales growth often absorbs cash into inventory and receivables, so a current ratio falling to 0.9 : 1 signals that working capital is overstretched."}}},{"id":"P1_U5_MCQ_1181","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1181","question":"A very small weaving business in a low-income country needs a loan of just $600 to buy a loom, but ordinary banks will not lend such a small sum. Which source is designed for this need?","options":{"A":"Microfinance","B":"A debenture issue","C":"A stock exchange listing","D":"Leasing a factory"},"correctOption":"A","correctAnswer":"Microfinance","questionType":"MCQ","explanation":{"correct_reason":"Microfinance provides very small loans to low-income entrepreneurs who lack access to ordinary bank lending, which matches the $600 requirement.","distractor_reasons":{"A":"Microfinance provides very small loans to low-income entrepreneurs who lack access to ordinary bank lending, which matches the $600 requirement.","B":"A debenture issue raises large sums from investors and is far beyond the needs of a $600 weaving business. The resulting figure therefore cannot be the correct answer to this question.","C":"A stock exchange listing is available only to large public companies and would be impossible for this tiny firm. That is why this option does not answer the question correctly.","D":"Leasing a factory involves fixed rental payments for premises, not the small loan needed to buy a loom. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1182","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1182","question":"Oakhampton Dairy starts June with $20,000 cash. June receipts are $56,000 and payments are $63,000. What is the closing cash balance, and what does it show?","options":{"A":"-$7,000, an overdraft is needed","B":"$13,000, a positive balance","C":"$7,000, a positive balance","D":"$20,000, unchanged"},"correctOption":"B","correctAnswer":"$13,000, a positive balance","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $56,000 minus $63,000, a $7,000 deficit, and subtracting this from the $20,000 opening balance leaves $13,000.","distractor_reasons":{"A":"This shows the net outflow alone and ignores the $20,000 already held at the start of June. The resulting figure therefore cannot be the correct answer to this question.","B":"Net cash flow is $56,000 minus $63,000, a $7,000 deficit, and subtracting this from the $20,000 opening balance leaves $13,000.","C":"This treats the $7,000 net figure as a surplus and adds it, but payments exceeded receipts. The resulting figure therefore cannot be the correct answer to this question.","D":"This assumes receipts and payments cancel out and leaves the opening balance unchanged. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1183","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1183","question":"Bexleyheath Furniture Ltd has sales revenue of $420,000 and sales returns of $15,000. Its cost of sales is $210,000. What is its gross profit for the year?","options":{"A":"$210,000","B":"$180,000","C":"$195,000","D":"$405,000"},"correctOption":"C","correctAnswer":"$195,000","questionType":"MCQ","explanation":{"correct_reason":"Net revenue is $420,000 minus $15,000 returns, equal to $405,000, and deducting $210,000 cost of sales gives gross profit of $195,000.","distractor_reasons":{"A":"This deducts cost of sales from the $420,000 revenue but fails to remove the $15,000 of sales returns. The resulting figure therefore cannot be the correct answer to this question.","B":"This deducts the $15,000 sales returns twice, once from revenue and again from the resulting gross profit. The resulting figure therefore cannot be the correct answer to this question.","C":"Net revenue is $420,000 minus $15,000 returns, equal to $405,000, and deducting $210,000 cost of sales gives gross profit of $195,000.","D":"This deducts the $15,000 sales returns from revenue but forgets to deduct the $210,000 cost of sales. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1184","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1184","question":"Kemsing Chemicals Ltd prepares a statement of financial position showing both loans and equity. Why are bank loans shown separately from equity in that statement?","options":{"A":"Loans are owned by the business while equity is owed to lenders","B":"Equity must be repaid before loans","C":"Loans are current assets of the business","D":"Loans are external claims that must be repaid, while equity belongs to the owners"},"correctOption":"D","correctAnswer":"Loans are external claims that must be repaid, while equity belongs to the owners","questionType":"MCQ","explanation":{"correct_reason":"Lenders have a legal claim that must be repaid with interest, whereas equity represents the owners' residual stake in the business.","distractor_reasons":{"A":"This reverses the positions, since loans are owed to lenders and equity is the owners' claim on the business. That is why this option does not answer the question correctly.","B":"Equity is the owners' residual interest and is repaid last on winding up, after external creditors. That is why this option does not answer the question correctly.","C":"Bank loans are liabilities because they are owed, not assets that the business owns. That is why this option does not answer the question correctly.","D":"Lenders have a legal claim that must be repaid with interest, whereas equity represents the owners' residual stake in the business."}}},{"id":"P1_U5_MCQ_1185","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1185","question":"Chatteris Toys Ltd has a gross profit margin of 32%, while similar toy makers average 40%. What is the most likely explanation for this weaker margin?","options":{"A":"Its cost of sales is high relative to its revenue","B":"It has lower expenses than its competitors","C":"It charges higher prices than rivals","D":"It holds too much cash"},"correctOption":"A","correctAnswer":"Its cost of sales is high relative to its revenue","questionType":"MCQ","explanation":{"correct_reason":"The gross profit margin compares gross profit with revenue, so a 32% figure against a 40% average points to higher production or purchase costs.","distractor_reasons":{"A":"The gross profit margin compares gross profit with revenue, so a 32% figure against a 40% average points to higher production or purchase costs.","B":"Expenses are deducted after gross profit, so lower expenses would not explain a weak gross profit margin. That is why this option does not answer the question correctly.","C":"Higher prices would normally raise the gross profit margin, not push it below the industry average. That is why this option does not answer the question correctly.","D":"The cash balance affects liquidity and has no direct effect on the gross profit margin. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1186","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1186","question":"Ashby-de-la-Zouch Printers needs a new printing press but wants to avoid a large initial cash payment. Which is a main advantage of leasing the machinery rather than buying it outright?","options":{"A":"The firm owns the machine immediately","B":"It avoids a large initial cash payment","C":"No payments are required after year one","D":"The lease always works out cheaper than buying"},"correctOption":"B","correctAnswer":"It avoids a large initial cash payment","questionType":"MCQ","explanation":{"correct_reason":"Leasing spreads the cost into regular rental payments, so the business gains use of the machine without a large upfront cash outflow.","distractor_reasons":{"A":"The leased asset remains the property of the leasing company, so the firm does not own it immediately. That is why this option does not answer the question correctly.","B":"Leasing spreads the cost into regular rental payments, so the business gains use of the machine without a large upfront cash outflow.","C":"Rental payments continue throughout the lease term and do not stop after the first year. That is why this option does not answer the question correctly.","D":"Leasing can cost more in total than buying, so it is not always the cheaper option overall. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1187","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1187","question":"Sidcup Ceramics Ltd has reported both a profit for the year and a closing cash balance. Why can the closing cash balance differ from the profit for the year?","options":{"A":"Cash flow includes depreciation as a payment","B":"Profit is always lower than the cash balance","C":"Profit includes credit sales not yet received and deducts non-cash depreciation","D":"Cash flow records revenue when goods are delivered"},"correctOption":"C","correctAnswer":"Profit includes credit sales not yet received and deducts non-cash depreciation","questionType":"MCQ","explanation":{"correct_reason":"Profit records credit sales before cash arrives and deducts depreciation that uses no cash, so it cannot equal the movement in cash.","distractor_reasons":{"A":"Depreciation is a non-cash expense and is deliberately excluded from a cash flow forecast. That is why this option does not answer the question correctly.","B":"There is no fixed relationship, since a profitable firm can still have a lower cash balance. That is why this option does not answer the question correctly.","C":"Profit records credit sales before cash arrives and deducts depreciation that uses no cash, so it cannot equal the movement in cash.","D":"Cash flow records money when it is received or paid, not when goods are delivered on credit. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1188","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1188","question":"Dunwich Bakery Ltd is preparing the appropriation account section of its profit and loss account. Which item is deducted from profit after tax to calculate retained profit?","options":{"A":"Cost of sales","B":"Depreciation of the ovens","C":"Interest payable on loans","D":"Dividends paid to shareholders"},"correctOption":"D","correctAnswer":"Dividends paid to shareholders","questionType":"MCQ","explanation":{"correct_reason":"Dividends are paid out of profit after tax, so deducting them from that profit leaves the amount retained in the business.","distractor_reasons":{"A":"Cost of sales is deducted from revenue at the top of the profit and loss account, long before appropriation. That is why this option does not answer the question correctly.","B":"Depreciation is an expense deducted before profit for the year is calculated, not an appropriation of profit. That is why this option does not answer the question correctly.","C":"Interest payable is a finance cost deducted before profit after tax and is not part of the appropriation account. That is why this option does not answer the question correctly.","D":"Dividends are paid out of profit after tax, so deducting them from that profit leaves the amount retained in the business."}}},{"id":"P1_U5_MCQ_1189","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1189","question":"Rothbury Software Ltd has share capital of $300,000 and retained profit of $95,000. It has no other reserves. What is its total equity shown in the statement?","options":{"A":"$395,000","B":"$300,000","C":"$95,000","D":"$205,000"},"correctOption":"A","correctAnswer":"$395,000","questionType":"MCQ","explanation":{"correct_reason":"Equity is share capital plus retained profit, so $300,000 plus $95,000 equals $395,000 of owners' funds in Rothbury Software Ltd.","distractor_reasons":{"A":"Equity is share capital plus retained profit, so $300,000 plus $95,000 equals $395,000 of owners' funds in Rothbury Software Ltd.","B":"This is only the share capital and omits the $95,000 of profit retained in the business. The resulting figure therefore cannot be the correct answer to this question.","C":"This is only the retained profit and omits the $300,000 originally invested as share capital. The resulting figure therefore cannot be the correct answer to this question.","D":"This subtracts retained profit from share capital instead of adding the two sources of equity. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1190","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1190","question":"Sedgemoor Supplies Ltd has inventory of $90,000, trade receivables of $100,000, cash of $20,000 and current liabilities of $84,000 at the year end. What is its current ratio?","options":{"A":"1.43 : 1","B":"2.5 : 1","C":"0.4 : 1","D":"2.26 : 1"},"correctOption":"B","correctAnswer":"2.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Current assets total $90,000 plus $100,000 plus $20,000, equal to $210,000, and dividing by current liabilities of $84,000 gives 2.5 : 1.","distractor_reasons":{"A":"This is the acid-test ratio, which removes the $90,000 inventory before dividing $120,000 by $84,000. The resulting figure therefore cannot be the correct answer to this question.","B":"Current assets total $90,000 plus $100,000 plus $20,000, equal to $210,000, and dividing by current liabilities of $84,000 gives 2.5 : 1.","C":"This inverts the calculation by dividing current liabilities of $84,000 by current assets of $210,000. The resulting figure therefore cannot be the correct answer to this question.","D":"This leaves the $20,000 cash out of current assets and divides only $190,000 by $84,000. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1191","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1191","question":"Why might the directors of a large public limited company such as Marchington Chemicals choose to issue new shares rather than take another bank loan?","options":{"A":"Shareholders must be repaid within five years","B":"Dividends are a legal obligation every year","C":"Share capital does not have to be repaid and dividends are discretionary","D":"Shares carry a fixed rate of interest"},"correctOption":"C","correctAnswer":"Share capital does not have to be repaid and dividends are discretionary","questionType":"MCQ","explanation":{"correct_reason":"Share capital is permanent, and directors can decide whether to pay a dividend, so the company avoids compulsory repayments and fixed interest.","distractor_reasons":{"A":"Share capital is permanent and is not repaid at a fixed date while the company continues trading. That is why this option does not answer the question correctly.","B":"Dividends are paid only when profits allow and are never a legal obligation in a loss-making year. That is why this option does not answer the question correctly.","C":"Share capital is permanent, and directors can decide whether to pay a dividend, so the company avoids compulsory repayments and fixed interest.","D":"Ordinary shares do not carry interest; any return comes as a variable dividend declared from profit. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1192","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1192","question":"Wendover Marine Ltd starts July with $3,000 cash. It forecasts receipts of $48,500 and payments of $55,000 during July. What is its closing cash balance?","options":{"A":"-$6,500","B":"$3,500","C":"$55,000","D":"-$3,500"},"correctOption":"D","correctAnswer":"-$3,500","questionType":"MCQ","explanation":{"correct_reason":"July's payments exceed receipts by $6,500, and subtracting that deficit from the $3,000 opening balance leaves a negative closing balance of -$3,500.","distractor_reasons":{"A":"This shows only the July net outflow of $6,500 and ignores the $3,000 the business already held. The resulting figure therefore cannot be the correct answer to this question.","B":"This treats the $6,500 net deficit as a surplus and adds it to the opening balance rather than subtracting it. The resulting figure therefore cannot be the correct answer to this question.","C":"This repeats the payments figure without deducting any of the $48,500 of receipts. The resulting figure therefore cannot be the correct answer to this question.","D":"July's payments exceed receipts by $6,500, and subtracting that deficit from the $3,000 opening balance leaves a negative closing balance of -$3,500."}}},{"id":"P1_U5_MCQ_1193","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1193","question":"Bramfield Optics Ltd has revenue of $180,000 and its cost of sales is exactly one-third of revenue. What is its gross profit for the year?","options":{"A":"$120,000","B":"$60,000","C":"$240,000","D":"$90,000"},"correctOption":"A","correctAnswer":"$120,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is one-third of $180,000, equal to $60,000, so gross profit is $180,000 minus $60,000, which is $120,000.","distractor_reasons":{"A":"Cost of sales is one-third of $180,000, equal to $60,000, so gross profit is $180,000 minus $60,000, which is $120,000.","B":"This is the cost of sales figure itself, which must be deducted from revenue rather than reported as profit. That is why this option does not answer the question correctly.","C":"This adds cost of sales to revenue instead of subtracting the $60,000 from the $180,000. The resulting figure therefore cannot be the correct answer to this question.","D":"This divides revenue in half rather than using the stated one-third cost of sales proportion. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1194","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1194","question":"Ilmington Foodstores Ltd has prepared its statement of financial position at the end of the financial year. What does this statement reveal about the liquidity of the business?","options":{"A":"The amount of profit earned during the year","B":"The relationship between current assets and current liabilities","C":"The cash the business expects to receive next year","D":"The market value of the company's shares"},"correctOption":"B","correctAnswer":"The relationship between current assets and current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Current assets and current liabilities are both listed on the statement, so their relationship shows whether short-term obligations can be met.","distractor_reasons":{"A":"Profit for the year is reported in the profit and loss account, not in the statement of financial position. That is why this option does not answer the question correctly.","B":"Current assets and current liabilities are both listed on the statement, so their relationship shows whether short-term obligations can be met.","C":"Expected future receipts come from a cash flow forecast, not from the statement of financial position. That is why this option does not answer the question correctly.","D":"Share prices are set by the stock market and are not shown on the statement of financial position. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1195","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1195","question":"Hartfield Bakeries has revenue of $350,000, gross profit of $140,000 and expenses of $98,000 for the year. What is its profit margin as a percentage?","options":{"A":"40%","B":"28%","C":"12%","D":"1.2%"},"correctOption":"C","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Operating profit is $140,000 minus $98,000, equal to $42,000, and $42,000 divided by $350,000 gives a profit margin of 12%.","distractor_reasons":{"A":"This is the gross profit margin, calculated from $140,000 gross profit without deducting the $98,000 expenses. The resulting figure therefore cannot be the correct answer to this question.","B":"This divides the $98,000 expenses by revenue, which measures the expense ratio rather than profit. The resulting figure therefore cannot be the correct answer to this question.","C":"Operating profit is $140,000 minus $98,000, equal to $42,000, and $42,000 divided by $350,000 gives a profit margin of 12%.","D":"This misplaces the decimal point when converting the ratio of 0.12 into a percentage. The resulting figure therefore cannot be the correct answer to this question."}}},{"id":"P1_U5_MCQ_1196","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1196","question":"Thurlstone Engineering wants to fund a $2 million factory extension from retained profit. What is a limitation of using retained profit as a source of finance for this project?","options":{"A":"It must be repaid with interest","B":"It dilutes the owners' control","C":"It can only be used for short-term needs","D":"The amount available may be too small for a large project"},"correctOption":"D","correctAnswer":"The amount available may be too small for a large project","questionType":"MCQ","explanation":{"correct_reason":"Retained profit accumulates only from past earnings, so it may be far too limited to fund a major expansion such as a new factory.","distractor_reasons":{"A":"Retained profit is the owners' own money, so there is no lender to repay and no interest charge. That is why this option does not answer the question correctly.","B":"Keeping profit in the business creates no new shares, so the existing owners' control is unchanged. That is why this option does not answer the question correctly.","C":"Retained profit can fund long-term assets as well as short-term needs, so this is not a real limitation. That is why this option does not answer the question correctly.","D":"Retained profit accumulates only from past earnings, so it may be far too limited to fund a major expansion such as a new factory."}}},{"id":"P1_U5_MCQ_1197","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1197","question":"Middleton Press has both a cash flow forecast and a cash flow statement in its records. What distinguishes a cash flow forecast from the cash flow statement of the business?","options":{"A":"A forecast estimates future cash movements, while a statement records past ones","B":"A forecast records only cash payments","C":"A statement is prepared before the year begins","D":"A forecast includes depreciation but a statement does not"},"correctOption":"A","correctAnswer":"A forecast estimates future cash movements, while a statement records past ones","questionType":"MCQ","explanation":{"correct_reason":"A forecast looks forward and predicts expected receipts and payments, whereas a cash flow statement summarises cash movements that have already occurred.","distractor_reasons":{"A":"A forecast looks forward and predicts expected receipts and payments, whereas a cash flow statement summarises cash movements that have already occurred.","B":"A forecast records both expected receipts and expected payments, not payments alone. That is why this option does not answer the question correctly.","C":"The cash flow statement is prepared after the period ends to report what actually happened. That is why this option does not answer the question correctly.","D":"Depreciation is a non-cash item and is excluded from both a forecast and a cash flow statement. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1198","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1198","question":"Lytchett Ceramics has seen the cost of its raw materials rise while its selling prices stay the same. What happens to its gross profit as a result?","options":{"A":"Gross profit rises by the same amount","B":"Gross profit falls","C":"Gross profit stays unchanged","D":"Gross profit becomes zero"},"correctOption":"B","correctAnswer":"Gross profit falls","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, so a higher cost of sales against unchanged revenue must reduce the gross profit figure.","distractor_reasons":{"A":"A higher cost reduces profit, so it cannot increase gross profit by the same amount. That is why this option does not answer the question correctly.","B":"Gross profit is revenue minus cost of sales, so a higher cost of sales against unchanged revenue must reduce the gross profit figure.","C":"Only if cost of sales were unchanged would gross profit remain the same, which contradicts the scenario. That is why this option does not answer the question correctly.","D":"Gross profit falls but does not automatically become zero unless cost of sales equals total revenue. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1199","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1199","question":"Tinsbury Supplies Ltd has current assets of $95,000 and current liabilities of $120,000 at its year end. What is its working capital according to these figures?","options":{"A":"$25,000","B":"$215,000","C":"-$25,000","D":"$95,000"},"correctOption":"C","correctAnswer":"-$25,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so $95,000 minus $120,000 gives a negative working capital figure of -$25,000.","distractor_reasons":{"A":"This reverses the subtraction and reports the $25,000 gap as a positive surplus of assets over liabilities. The resulting figure therefore cannot be the correct answer to this question.","B":"This adds current liabilities to current assets instead of deducting them. That is why this option does not answer the question correctly.","C":"Working capital is current assets minus current liabilities, so $95,000 minus $120,000 gives a negative working capital figure of -$25,000.","D":"This repeats current assets alone without deducting the larger total of current liabilities. That is why this option does not answer the question correctly."}}},{"id":"P1_U5_MCQ_1200","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1200","question":"Birdsedge Engineering Ltd wants to compare its ratios with those of a rival firm in the same industry. Which is a genuine limitation of such a comparison?","options":{"A":"Ratios can only be calculated for public limited companies","B":"Ratios are always based on out-of-date information","C":"Ratios ignore the figures printed in the financial statements","D":"A ratio can be affected by different accounting policies between firms"},"correctOption":"D","correctAnswer":"A ratio can be affected by different accounting policies between firms","questionType":"MCQ","explanation":{"correct_reason":"Different depreciation or inventory valuation policies change reported figures, so identical performance can produce different ratios between two similar firms.","distractor_reasons":{"A":"Ratios can be calculated from any set of financial statements, including those of sole traders and partnerships. That is why this option does not answer the question correctly.","B":"Ratios are based on the latest published accounts, which are historical but not automatically out of date. That is why this option does not answer the question correctly.","C":"Ratios are derived entirely from the financial statements rather than ignoring the figures they contain. That is why this option does not answer the question correctly.","D":"Different depreciation or inventory valuation policies change reported figures, so identical performance can produce different ratios between two similar firms."}}},{"id":"P1_U5_MCQ_1201","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1201","question":"Harrowgate Pumps borrows $48,000 from its bank for 3 years at a simple interest rate of 6% a year. The principal is repaid in full only at the end of the term, and interest is paid annually. What total interest will Harrowgate Pumps pay over the whole 3-year period?","options":{"A":"$8,640","B":"$2,880","C":"$56,640","D":"$9,168.77"},"correctOption":"A","correctAnswer":"$8,640","questionType":"MCQ","explanation":{"correct_reason":"Simple interest is the principal multiplied by the rate and the number of years, so $48,000 x 6% x 3 equals $8,640 of total interest for Harrowgate Pumps.","distractor_reasons":{"A":"Simple interest is the principal multiplied by the rate and the number of years, so $48,000 x 6% x 3 equals $8,640 of total interest for Harrowgate Pumps.","B":"$2,880 is the interest for one year only at 6% on $48,000, but the loan runs for 3 years, so it understates the total interest Harrowgate Pumps must pay.","C":"$56,640 adds the $48,000 principal to the $8,640 interest, which gives the total repayment rather than the interest charge that the question asks for.","D":"$9,168.77 treats the interest as compound and charges interest on unpaid interest, but the question states simple interest, so this figure overstates the true cost to Harrowgate Pumps."}}},{"id":"P1_U5_MCQ_1202","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1202","question":"Rookwood Removals forecasts cash receipts of $96,000 and cash payments of $87,500 for the coming quarter. The business expects to start the quarter with a bank balance of $14,000. What is the forecast net cash flow for the quarter?","options":{"A":"$183,500","B":"$8,500","C":"$22,500","D":"$5,500"},"correctOption":"B","correctAnswer":"$8,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is total receipts minus total payments, so $96,000 less $87,500 gives a net inflow of $8,500 for Rookwood Removals this quarter.","distractor_reasons":{"A":"$183,500 adds receipts and payments together, but net cash flow requires the payments to be subtracted from the receipts, so this figure is far too high.","B":"Net cash flow is total receipts minus total payments, so $96,000 less $87,500 gives a net inflow of $8,500 for Rookwood Removals this quarter.","C":"$22,500 includes the $14,000 opening balance, so it is the forecast closing balance rather than the net cash flow generated during the quarter.","D":"$5,500 adds the payments to the opening balance and subtracts receipts, which reverses the correct treatment of the two cash flows."}}},{"id":"P1_U5_MCQ_1203","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1203","question":"Millrace Paper reports revenue of $240,000 for the year and cost of sales of $144,000. Operating expenses for the year were $62,000. What is the gross profit for the year?","options":{"A":"$34,000","B":"$384,000","C":"$96,000","D":"$178,000"},"correctOption":"C","correctAnswer":"$96,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, so $240,000 less $144,000 gives $96,000 for Millrace Paper, before operating expenses are deducted.","distractor_reasons":{"A":"$34,000 also deducts the $62,000 operating expenses, which gives the profit for the year rather than the gross profit of Millrace Paper.","B":"$384,000 adds cost of sales to revenue instead of subtracting it, which cannot produce the gross profit earned by Millrace Paper.","C":"Gross profit is revenue minus cost of sales, so $240,000 less $144,000 gives $96,000 for Millrace Paper, before operating expenses are deducted.","D":"$178,000 deducts operating expenses from revenue but ignores cost of sales entirely, so the two amounts have been mixed up."}}},{"id":"P1_U5_MCQ_1204","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1204","question":"Glasson Dock Fabricators reports current assets of $104,000 and current liabilities of $46,000 at its year end. The owner wants to know how much short-term finance is available to run the business. What is the working capital?","options":{"A":"$150,000","B":"$46,000","C":"$104,000","D":"$58,000"},"correctOption":"D","correctAnswer":"$58,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so $104,000 less $46,000 gives $58,000 for Glasson Dock Fabricators. That is the short-term finance available to the business.","distractor_reasons":{"A":"$150,000 adds current liabilities to current assets, but working capital requires the $46,000 to be deducted, so it overstates the figure.","B":"$46,000 is the current liabilities figure on its own, not the working capital left after deducting it from current assets.","C":"$104,000 is the current assets total before the $46,000 of current liabilities is deducted, so it overstates working capital. The working capital for Glasson Dock Fabricators is $58,000.","D":"Working capital is current assets minus current liabilities, so $104,000 less $46,000 gives $58,000 for Glasson Dock Fabricators. That is the short-term finance available to the business."}}},{"id":"P1_U5_MCQ_1205","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1205","question":"Brackenwood Books reports revenue of $280,000 and gross profit of $84,000 for the year. The owner is reviewing profitability. What is the gross profit margin? Give your answer to one decimal place.","options":{"A":"30.0%","B":"70.0%","C":"15.0%","D":"42.9%"},"correctOption":"A","correctAnswer":"30.0%","questionType":"MCQ","explanation":{"correct_reason":"The gross profit margin is gross profit divided by revenue, so $84,000/$280,000 x 100 gives 30.0% for Brackenwood Books. That is the share of sales left after cost of sales.","distractor_reasons":{"A":"The gross profit margin is gross profit divided by revenue, so $84,000/$280,000 x 100 gives 30.0% for Brackenwood Books. That is the share of sales left after cost of sales.","B":"70.0% is the cost of sales as a percentage of revenue, which is the complement of the gross profit margin for Brackenwood Books.","C":"15.0% is half the correct margin and does not come from dividing $84,000 by $280,000. The gross profit margin for Brackenwood Books is 30.0%.","D":"42.9% compares gross profit with cost of sales rather than with revenue, so it uses the wrong denominator for Brackenwood Books."}}},{"id":"P1_U5_MCQ_1206","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1206","question":"Silverbrook Optics is buying a delivery vehicle on hire purchase. The agreement requires a deposit of $3,500 followed by 24 monthly instalments of $420 each. What is the total cost of the vehicle under this hire purchase agreement?","options":{"A":"$10,080","B":"$13,580","C":"$3,920","D":"$13,160"},"correctOption":"B","correctAnswer":"$13,580","questionType":"MCQ","explanation":{"correct_reason":"The total hire purchase cost is the deposit plus every instalment, so $3,500 plus 24 payments of $420 equals $13,580 for Silverbrook Optics.","distractor_reasons":{"A":"$10,080 counts only the 24 monthly instalments and leaves out the $3,500 deposit, so it understates the total cost that Silverbrook Optics pays under the agreement.","B":"The total hire purchase cost is the deposit plus every instalment, so $3,500 plus 24 payments of $420 equals $13,580 for Silverbrook Optics.","C":"$3,920 adds just one instalment of $420 to the $3,500 deposit instead of all 24 instalments, so it is far below the true total for Silverbrook Optics.","D":"$13,160 includes only 23 instalments and omits the final payment of $420, but the agreement with Silverbrook Optics requires all 24 monthly payments."}}},{"id":"P1_U5_MCQ_1207","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1207","question":"Sandpiper Cruises expects to open July with a bank balance of $7,200. Forecast receipts for the month are $54,000 and forecast payments are $49,600. What closing bank balance should appear in the cash flow forecast for July?","options":{"A":"$110,800","B":"$4,400","C":"$11,600","D":"$2,800"},"correctOption":"C","correctAnswer":"$11,600","questionType":"MCQ","explanation":{"correct_reason":"The closing balance is the $7,200 opening balance plus $54,000 of receipts minus $49,600 of payments, giving $11,600 for Sandpiper Cruises at the end of July.","distractor_reasons":{"A":"$110,800 adds the payments instead of subtracting them, so it cannot be the closing bank balance that Sandpiper Cruises will actually hold.","B":"$4,400 is only the net cash flow for the month and leaves out the $7,200 that Sandpiper Cruises already holds at the start of July.","C":"The closing balance is the $7,200 opening balance plus $54,000 of receipts minus $49,600 of payments, giving $11,600 for Sandpiper Cruises at the end of July.","D":"$2,800 subtracts the net inflow from the opening balance instead of adding it, which moves the balance in the wrong direction."}}},{"id":"P1_U5_MCQ_1208","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1208","question":"Newtangent Media had opening inventory of $14,000, made purchases of $88,000 and held closing inventory of $19,000 at the year end. Revenue for the year was $132,000. What was the cost of sales for the year?","options":{"A":"$121,000","B":"$69,000","C":"$102,000","D":"$83,000"},"correctOption":"D","correctAnswer":"$83,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is opening inventory plus purchases minus closing inventory, so $14,000+$88,000-$19,000 equals $83,000 for Newtangent Media. That is the direct cost of the goods sold during the year.","distractor_reasons":{"A":"$121,000 adds the closing inventory instead of subtracting it, which double counts stock that Newtangent Media still holds at the year end.","B":"$69,000 ignores the $14,000 opening inventory, so it understates the goods that Newtangent Media actually consumed during the year. The cost of sales for Newtangent Media is $83,000.","C":"$102,000 leaves out the $19,000 closing inventory, so it fails to reduce cost of sales for stock that Newtangent Media still holds.","D":"Cost of sales is opening inventory plus purchases minus closing inventory, so $14,000+$88,000-$19,000 equals $83,000 for Newtangent Media. That is the direct cost of the goods sold during the year."}}},{"id":"P1_U5_MCQ_1209","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1209","question":"Haven Head Resorts holds inventory of $38,000, trade receivables of $26,000 and cash of $14,000 at the year end. It has no other current assets. What is the total of its current assets?","options":{"A":"$78,000","B":"$64,000","C":"$52,000","D":"$40,000"},"correctOption":"A","correctAnswer":"$78,000","questionType":"MCQ","explanation":{"correct_reason":"Current assets are added together, so $38,000+$26,000+$14,000 gives $78,000 for Haven Head Resorts. That is the total of the resources expected to turn into cash.","distractor_reasons":{"A":"Current assets are added together, so $38,000+$26,000+$14,000 gives $78,000 for Haven Head Resorts. That is the total of the resources expected to turn into cash.","B":"$64,000 leaves out the $14,000 of cash, which is a current asset and must be included in the total. The total current assets for Haven Head Resorts is $78,000.","C":"$52,000 omits the $26,000 owed by trade receivables, so it understates the current assets of Haven Head Resorts. The total current assets for Haven Head Resorts is $78,000.","D":"$40,000 leaves out the $38,000 of inventory held by Haven Head Resorts at the year end. The total current assets for Haven Head Resorts is $78,000."}}},{"id":"P1_U5_MCQ_1210","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1210","question":"Cloverhay Farms reports revenue of $450,000 and gross profit of $157,500 for the year. The owner is reviewing profitability. What is the gross profit margin? Give your answer to one decimal place.","options":{"A":"65.0%","B":"35.0%","C":"17.5%","D":"53.8%"},"correctOption":"B","correctAnswer":"35.0%","questionType":"MCQ","explanation":{"correct_reason":"The gross profit margin is gross profit divided by revenue, so $157,500/$450,000 x 100 gives 35.0% for Cloverhay Farms. That is the share of sales left after cost of sales.","distractor_reasons":{"A":"65.0% is the cost of sales as a percentage of revenue, which is the complement of the gross profit margin for Cloverhay Farms.","B":"The gross profit margin is gross profit divided by revenue, so $157,500/$450,000 x 100 gives 35.0% for Cloverhay Farms. That is the share of sales left after cost of sales.","C":"17.5% is half the correct margin and does not come from dividing $157,500 by $450,000. The gross profit margin for Cloverhay Farms is 35.0%.","D":"53.8% compares gross profit with cost of sales rather than with revenue, so it uses the wrong denominator for Cloverhay Farms."}}},{"id":"P1_U5_MCQ_1211","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1211","question":"Cindermoor Quarry leases a machine for 4 years. The annual lease payment is $18,000 and the annual maintenance contract costs a further $2,500. What is the total cost of leasing and maintaining the machine over the 4 years?","options":{"A":"$72,000","B":"$20,500","C":"$82,000","D":"$74,500"},"correctOption":"C","correctAnswer":"$82,000","questionType":"MCQ","explanation":{"correct_reason":"Each year costs $18,000 in lease payments plus $2,500 for maintenance, so the annual total of $20,500 multiplied by 4 years gives $82,000 for Cindermoor Quarry.","distractor_reasons":{"A":"$72,000 covers the lease payments but omits the $2,500 annual maintenance charge, so it understates the total cost of running the machine for 4 years.","B":"$20,500 is the cost of a single year only, but Cindermoor Quarry leases the machine for 4 years, so it ignores the remaining 3 years of payments.","C":"Each year costs $18,000 in lease payments plus $2,500 for maintenance, so the annual total of $20,500 multiplied by 4 years gives $82,000 for Cindermoor Quarry.","D":"$74,500 adds the maintenance charge only once instead of for each of the 4 years, so it understates the total paid by Cindermoor Quarry."}}},{"id":"P1_U5_MCQ_1212","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1212","question":"Tanglewood Trees forecasts a closing bank balance of $9,800 for September after receipts of $67,400 and payments of $63,000. What opening bank balance must the forecast show for the start of September?","options":{"A":"$14,200","B":"$4,400","C":"$140,200","D":"$5,400"},"correctOption":"D","correctAnswer":"$5,400","questionType":"MCQ","explanation":{"correct_reason":"The opening balance is the $9,800 closing figure minus the net inflow of $4,400, which gives $5,400 at the start of September for Tanglewood Trees.","distractor_reasons":{"A":"$14,200 adds the net inflow to the closing balance instead of subtracting it, so it moves the balance the wrong way.","B":"$4,400 is the net cash flow for September, not the balance that Tanglewood Trees held at the start of the month.","C":"$140,200 adds both receipts and payments to the closing balance, but payments reduce the balance and should be subtracted. The opening balance for Tanglewood Trees is $5,400.","D":"The opening balance is the $9,800 closing figure minus the net inflow of $4,400, which gives $5,400 at the start of September for Tanglewood Trees."}}},{"id":"P1_U5_MCQ_1213","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1213","question":"Oakenshaw Steel made a gross profit of $87,000 during the year. Operating expenses were $54,600 and there were no interest charges. What was the profit for the year?","options":{"A":"$32,400","B":"$141,600","C":"$54,600","D":"$87,000"},"correctOption":"A","correctAnswer":"$32,400","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is gross profit minus operating expenses, so $87,000 less $54,600 gives $32,400 for Oakenshaw Steel. That is the profit left after operating expenses.","distractor_reasons":{"A":"Profit for the year is gross profit minus operating expenses, so $87,000 less $54,600 gives $32,400 for Oakenshaw Steel. That is the profit left after operating expenses.","B":"$141,600 adds the expenses to gross profit instead of deducting them, which overstates the profit of Oakenshaw Steel for the year.","C":"$54,600 is just the operating expenses figure and says nothing about the profit that Oakenshaw Steel actually earned during the year.","D":"$87,000 is the gross profit before operating expenses are paid, so it overstates the profit for the year. The profit for the year for Oakenshaw Steel is $32,400."}}},{"id":"P1_U5_MCQ_1214","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1214","question":"Ironbridge Tools has current assets of $132,000, including inventory of $44,000, and current liabilities of $66,000. What is the current ratio? Give your answer to two decimal places.","options":{"A":"1.33 : 1","B":"2.00 : 1","C":"0.50 : 1","D":"0.67 : 1"},"correctOption":"B","correctAnswer":"2.00 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets divided by current liabilities, so $132,000/$66,000 gives 2.00 : 1 for Ironbridge Tools. That means the business holds this much in current assets for each dollar of current liabilities.","distractor_reasons":{"A":"1.33 : 1 is the acid test ratio, which removes the $44,000 inventory from current assets before dividing by current liabilities.","B":"The current ratio is current assets divided by current liabilities, so $132,000/$66,000 gives 2.00 : 1 for Ironbridge Tools. That means the business holds this much in current assets for each dollar of current liabilities.","C":"0.50 : 1 reverses the calculation by dividing current liabilities by current assets rather than the other way round. The current ratio for Ironbridge Tools is 2.00 : 1.","D":"0.67 : 1 divides current assets less inventory by current assets itself rather than by current liabilities. The current ratio for Ironbridge Tools is 2.00 : 1."}}},{"id":"P1_U5_MCQ_1215","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1215","question":"Dunmoor Distillery reports revenue of $380,000 and operating profit of $68,400 for the year. The owner is checking how much profit is kept from each dollar of sales. What is the profit margin? Give your answer to one decimal place.","options":{"A":"40.0%","B":"45.0%","C":"18.0%","D":"9.0%"},"correctOption":"C","correctAnswer":"18.0%","questionType":"MCQ","explanation":{"correct_reason":"The profit margin is operating profit divided by revenue, so $68,400/$380,000 x 100 gives 18.0% for Dunmoor Distillery. That is the share of sales kept as operating profit.","distractor_reasons":{"A":"40.0% is the gross profit margin, which uses gross profit rather than the $68,400 of operating profit earned by Dunmoor Distillery.","B":"45.0% divides operating profit by gross profit instead of by revenue, so it is not the profit margin of Dunmoor Distillery.","C":"The profit margin is operating profit divided by revenue, so $68,400/$380,000 x 100 gives 18.0% for Dunmoor Distillery. That is the share of sales kept as operating profit.","D":"9.0% is half the correct figure and has no basis in the $68,400 profit or the $380,000 revenue. The profit margin for Dunmoor Distillery is 18.0%."}}},{"id":"P1_U5_MCQ_1216","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1216","question":"Ashvale Marquees receives an invoice for $64,000 from a supplier that offers a cash discount of 2.5% for payment within ten days. Ashvale Marquees decides to pay within the discount period. How much money will the business save by paying early?","options":{"A":"$62,400","B":"$3,200","C":"$160","D":"$1,600"},"correctOption":"D","correctAnswer":"$1,600","questionType":"MCQ","explanation":{"correct_reason":"The saving is 2.5% of the $64,000 invoice, and $64,000 x 2.5% equals $1,600, which is the cash discount Ashvale Marquees gains by paying within ten days.","distractor_reasons":{"A":"$62,400 is the amount actually paid after deducting the discount, not the saving itself, so it answers a different question from the one asked.","B":"$3,200 applies the 2.5% discount twice to the same invoice, which no supplier would allow, so it doubles the true saving for Ashvale Marquees.","C":"$160 moves the decimal point one place too far when taking 2.5% of $64,000, so it is ten times smaller than the correct saving.","D":"The saving is 2.5% of the $64,000 invoice, and $64,000 x 2.5% equals $1,600, which is the cash discount Ashvale Marquees gains by paying within ten days."}}},{"id":"P1_U5_MCQ_1217","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1217","question":"Underhill Drains started the month with a bank balance of $5,600 and received $48,200 from customers. The forecast closing balance is $7,300. What total cash payments must the forecast show for the month?","options":{"A":"$46,500","B":"$61,100","C":"$49,900","D":"$35,300"},"correctOption":"A","correctAnswer":"$46,500","questionType":"MCQ","explanation":{"correct_reason":"Payments equal the $5,600 opening balance plus $48,200 received minus the $7,300 closing balance, which gives $46,500 of payments for Underhill Drains.","distractor_reasons":{"A":"Payments equal the $5,600 opening balance plus $48,200 received minus the $7,300 closing balance, which gives $46,500 of payments for Underhill Drains.","B":"$61,100 adds the closing balance instead of subtracting it, so it overstates the payments by twice the closing figure. The total payments for Underhill Drains is $46,500.","C":"$49,900 rearranges the figures incorrectly and produces a total that does not reconcile the opening and closing balances of Underhill Drains.","D":"$35,300 subtracts both the opening and closing balances from receipts, which is not how a cash flow forecast is balanced."}}},{"id":"P1_U5_MCQ_1218","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1218","question":"Pikefold Dairies reports revenue of $305,000 for the year and cost of sales of $183,000. Operating expenses for the year were $71,400. What is the gross profit for the year?","options":{"A":"$50,600","B":"$122,000","C":"$488,000","D":"$233,600"},"correctOption":"B","correctAnswer":"$122,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, so $305,000 less $183,000 gives $122,000 for Pikefold Dairies, before operating expenses are deducted.","distractor_reasons":{"A":"$50,600 also deducts the $71,400 operating expenses, which gives the profit for the year rather than the gross profit of Pikefold Dairies.","B":"Gross profit is revenue minus cost of sales, so $305,000 less $183,000 gives $122,000 for Pikefold Dairies, before operating expenses are deducted.","C":"$488,000 adds cost of sales to revenue instead of subtracting it, which cannot produce the gross profit earned by Pikefold Dairies.","D":"$233,600 deducts operating expenses from revenue but ignores cost of sales entirely, so the two amounts have been mixed up."}}},{"id":"P1_U5_MCQ_1219","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1219","question":"Jackdaw Music reports current assets of $150,000, which include inventory of $60,000, and current liabilities of $90,000. What is the acid test ratio? Give your answer to two decimal places.","options":{"A":"1.67 : 1","B":"0.67 : 1","C":"1.00 : 1","D":"2.33 : 1"},"correctOption":"C","correctAnswer":"1.00 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test removes inventory, so ($150,000-$60,000)/$90,000 gives 1.00 : 1 for Jackdaw Music. That is the liquidity measure that excludes inventory.","distractor_reasons":{"A":"1.67 : 1 is the current ratio, which includes the $60,000 of inventory that the acid test deliberately excludes. The acid test ratio for Jackdaw Music is 1.00 : 1.","B":"0.67 : 1 divides inventory by current liabilities, which is not the acid test calculation used to judge liquidity. The acid test ratio for Jackdaw Music is 1.00 : 1.","C":"The acid test removes inventory, so ($150,000-$60,000)/$90,000 gives 1.00 : 1 for Jackdaw Music. That is the liquidity measure that excludes inventory.","D":"2.33 : 1 adds inventory to current assets even though the acid test removes it before dividing. The acid test ratio for Jackdaw Music is 1.00 : 1."}}},{"id":"P1_U5_MCQ_1220","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1220","question":"Elmwood Engines reports operating profit of $96,000 for the year and capital employed of $640,000 at the year end. The owner wants to judge how well the capital has been used. What is the return on capital employed? Give your answer to one decimal place.","options":{"A":"13.0%","B":"17.6%","C":"7.5%","D":"15.0%"},"correctOption":"D","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"ROCE is operating profit divided by capital employed, so $96,000/$640,000 x 100 gives 15.0% for Elmwood Engines. That is the return earned on each dollar of capital employed.","distractor_reasons":{"A":"13.0% adds operating profit to capital employed in the denominator, which is not the ROCE formula. The return on capital employed for Elmwood Engines is 15.0%.","B":"17.6% deducts profit from capital employed before dividing, so the denominator is wrong. The return on capital employed for Elmwood Engines is 15.0%.","C":"7.5% is half the correct return and cannot be obtained from $96,000 and $640,000. The return on capital employed for Elmwood Engines is 15.0%.","D":"ROCE is operating profit divided by capital employed, so $96,000/$640,000 x 100 gives 15.0% for Elmwood Engines. That is the return earned on each dollar of capital employed."}}},{"id":"P1_U5_MCQ_1221","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1221","question":"Brimstone Cycles arranges a bank overdraft of $30,000 to cover a seasonal shortage. The overdraft carries interest at 9% a year, and Brimstone Cycles expects to use the full amount for 8 months. What interest will the business pay for this period?","options":{"A":"$1,800","B":"$2,700","C":"$21,600","D":"$31,800"},"correctOption":"A","correctAnswer":"$1,800","questionType":"MCQ","explanation":{"correct_reason":"The interest is $30,000 x 9% x 8/12, because the overdraft is used for 8 months of the year, giving $1,800 for Brimstone Cycles.","distractor_reasons":{"A":"The interest is $30,000 x 9% x 8/12, because the overdraft is used for 8 months of the year, giving $1,800 for Brimstone Cycles.","B":"$2,700 charges a full year of interest at 9%, but Brimstone Cycles only uses the overdraft for 8 months, so it overstates the interest cost.","C":"$21,600 multiplies the annual rate by 8 without dividing by twelve, so it treats the 8-month period as 8 whole years of borrowing.","D":"$31,800 adds the $30,000 borrowed to the $1,800 interest, which gives the total repaid rather than the interest charged to Brimstone Cycles."}}},{"id":"P1_U5_MCQ_1222","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1222","question":"Vestry Lane Cafe forecasts cash receipts of $31,400 and cash payments of $28,700 for the coming quarter. The business expects to start the quarter with a bank balance of $3,200. What is the forecast net cash flow for the quarter?","options":{"A":"$60,100","B":"$2,700","C":"$5,900","D":"$500"},"correctOption":"B","correctAnswer":"$2,700","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is total receipts minus total payments, so $31,400 less $28,700 gives a net inflow of $2,700 for Vestry Lane Cafe this quarter.","distractor_reasons":{"A":"$60,100 adds receipts and payments together, but net cash flow requires the payments to be subtracted from the receipts, so this figure is far too high.","B":"Net cash flow is total receipts minus total payments, so $31,400 less $28,700 gives a net inflow of $2,700 for Vestry Lane Cafe this quarter.","C":"$5,900 includes the $3,200 opening balance, so it is the forecast closing balance rather than the net cash flow generated during the quarter.","D":"$500 adds the payments to the opening balance and subtracts receipts, which reverses the correct treatment of the two cash flows."}}},{"id":"P1_U5_MCQ_1223","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1223","question":"Quarryman Ale began the year with inventory of $21,000, bought goods costing $118,000 and ended with inventory of $24,000. Revenue for the year was $168,000. What was the gross profit?","options":{"A":"$29,000","B":"$74,000","C":"$53,000","D":"$5,000"},"correctOption":"C","correctAnswer":"$53,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is $21,000+$118,000-$24,000 = $115,000, so revenue of $168,000 less $115,000 gives gross profit of $53,000 for Quarryman Ale.","distractor_reasons":{"A":"$29,000 uses opening inventory plus purchases as cost of sales and ignores the $24,000 closing inventory held by Quarryman Ale.","B":"$74,000 omits the $21,000 opening inventory from cost of sales, so the gross profit of Quarryman Ale is overstated. The gross profit for Quarryman Ale is $53,000.","C":"Cost of sales is $21,000+$118,000-$24,000 = $115,000, so revenue of $168,000 less $115,000 gives gross profit of $53,000 for Quarryman Ale.","D":"$5,000 adds closing inventory to cost of sales instead of subtracting it, so the gross profit is far too low."}}},{"id":"P1_U5_MCQ_1224","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1224","question":"Kingfisher Kayaks has non-current assets of $420,000, current assets of $118,000 and current liabilities of $56,000. The owner wants to know the total long-term finance invested in the business. What is the capital employed?","options":{"A":"$538,000","B":"$594,000","C":"$62,000","D":"$482,000"},"correctOption":"D","correctAnswer":"$482,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is non-current assets plus current assets minus current liabilities, so $420,000+$118,000-$56,000 gives $482,000 for Kingfisher Kayaks. That is the long-term finance invested in the business.","distractor_reasons":{"A":"$538,000 adds non-current and current assets but fails to deduct the $56,000 of current liabilities. The capital employed for Kingfisher Kayaks is $482,000.","B":"$594,000 adds current liabilities instead of deducting them, so the capital employed of Kingfisher Kayaks is overstated. The capital employed for Kingfisher Kayaks is $482,000.","C":"$62,000 is only the working capital and omits the $420,000 of non-current assets held by Kingfisher Kayaks. The capital employed for Kingfisher Kayaks is $482,000.","D":"Capital employed is non-current assets plus current assets minus current liabilities, so $420,000+$118,000-$56,000 gives $482,000 for Kingfisher Kayaks. That is the long-term finance invested in the business."}}},{"id":"P1_U5_MCQ_1225","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1225","question":"Fallowfield Foods reports current assets of $168,000, including inventory of $56,000, and current liabilities of $84,000. What is the current ratio? Give your answer to two decimal places.","options":{"A":"2.00 : 1","B":"1.33 : 1","C":"0.50 : 1","D":"2.67 : 1"},"correctOption":"A","correctAnswer":"2.00 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets divided by current liabilities, so $168,000/$84,000 gives 2.00 : 1 for Fallowfield Foods. That means the business holds this much in current assets for each dollar of current liabilities.","distractor_reasons":{"A":"The current ratio is current assets divided by current liabilities, so $168,000/$84,000 gives 2.00 : 1 for Fallowfield Foods. That means the business holds this much in current assets for each dollar of current liabilities.","B":"1.33 : 1 is the acid test ratio, which removes the $56,000 inventory before dividing. The current ratio for Fallowfield Foods is 2.00 : 1.","C":"0.50 : 1 reverses the calculation by dividing current liabilities by current assets. The current ratio for Fallowfield Foods is 2.00 : 1.","D":"2.67 : 1 adds inventory to current assets before dividing by current liabilities, which double counts the stock. The current ratio for Fallowfield Foods is 2.00 : 1."}}},{"id":"P1_U5_MCQ_1226","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1226","question":"Coppice Lane Studios is a private limited company raising expansion finance by issuing 50,000 new shares at $2.40 each. The share issue costs $15,000 in fees. What net amount will the business raise after paying the issue costs?","options":{"A":"$120,000","B":"$105,000","C":"$135,000","D":"$60,000"},"correctOption":"B","correctAnswer":"$105,000","questionType":"MCQ","explanation":{"correct_reason":"The gross proceeds are 50,000 shares x $2.40, which is $120,000, and subtracting the $15,000 issue costs leaves $105,000 raised by Coppice Lane Studios.","distractor_reasons":{"A":"$120,000 is the gross proceeds before the $15,000 of issue costs are paid, so it overstates the cash that Coppice Lane Studios actually receives.","B":"The gross proceeds are 50,000 shares x $2.40, which is $120,000, and subtracting the $15,000 issue costs leaves $105,000 raised by Coppice Lane Studios.","C":"$135,000 adds the issue costs to the proceeds instead of deducting them, which is the opposite of what happens when Coppice Lane Studios issues shares.","D":"$60,000 is exactly half of the gross proceeds and has no basis in the 50,000 shares, the $2.40 price or the $15,000 issue costs."}}},{"id":"P1_U5_MCQ_1227","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1227","question":"Willowmere Pools expects to open July with a bank balance of $18,600. Forecast receipts for the month are $72,000 and forecast payments are $68,400. What closing bank balance should appear in the cash flow forecast for July?","options":{"A":"$159,000","B":"$3,600","C":"$22,200","D":"$15,000"},"correctOption":"C","correctAnswer":"$22,200","questionType":"MCQ","explanation":{"correct_reason":"The closing balance is the $18,600 opening balance plus $72,000 of receipts minus $68,400 of payments, giving $22,200 for Willowmere Pools at the end of July.","distractor_reasons":{"A":"$159,000 adds the payments instead of subtracting them, so it cannot be the closing bank balance that Willowmere Pools will actually hold.","B":"$3,600 is only the net cash flow for the month and leaves out the $18,600 that Willowmere Pools already holds at the start of July.","C":"The closing balance is the $18,600 opening balance plus $72,000 of receipts minus $68,400 of payments, giving $22,200 for Willowmere Pools at the end of July.","D":"$15,000 subtracts the net inflow from the opening balance instead of adding it, which moves the balance in the wrong direction."}}},{"id":"P1_U5_MCQ_1228","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1228","question":"Rushmere Beds reports gross profit of $96,000 for the year. Operating expenses were $52,800 and interest payable on its bank loan was $6,400. What was the profit for the year?","options":{"A":"$43,200","B":"$49,600","C":"$155,200","D":"$36,800"},"correctOption":"D","correctAnswer":"$36,800","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year deducts both operating expenses and interest, so $96,000-$52,800-$6,400 gives $36,800 for Rushmere Beds. That is the profit left after expenses and interest.","distractor_reasons":{"A":"$43,200 deducts operating expenses but forgets the $6,400 of interest, so it overstates the profit of Rushmere Beds. The profit for the year for Rushmere Beds is $36,800.","B":"$49,600 adds interest back instead of deducting it, which treats a cost as income in the accounts of Rushmere Beds.","C":"$155,200 adds both costs to gross profit, which is the opposite of the correct treatment. The profit for the year for Rushmere Beds is $36,800.","D":"Profit for the year deducts both operating expenses and interest, so $96,000-$52,800-$6,400 gives $36,800 for Rushmere Beds. That is the profit left after expenses and interest."}}},{"id":"P1_U5_MCQ_1229","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1229","question":"Lanternfield Lighting reports total assets of $640,000 and total liabilities of $270,000 at the year end. The owner wants to see what the business is worth once every debt has been paid. What is the equity of the business?","options":{"A":"$370,000","B":"$910,000","C":"$270,000","D":"$640,000"},"correctOption":"A","correctAnswer":"$370,000","questionType":"MCQ","explanation":{"correct_reason":"Equity is total assets minus total liabilities, so $640,000 less $270,000 gives $370,000 for Lanternfield Lighting. That is the owners' stake in the business.","distractor_reasons":{"A":"Equity is total assets minus total liabilities, so $640,000 less $270,000 gives $370,000 for Lanternfield Lighting. That is the owners' stake in the business.","B":"$910,000 adds liabilities to assets instead of deducting them, which overstates the owners' stake in Lanternfield Lighting. The equity for Lanternfield Lighting is $370,000.","C":"$270,000 is the total liabilities figure, not the equity that belongs to the owners of Lanternfield Lighting. The equity for Lanternfield Lighting is $370,000.","D":"$640,000 is total assets before the $270,000 of liabilities is deducted, so it overstates equity. The equity for Lanternfield Lighting is $370,000."}}},{"id":"P1_U5_MCQ_1230","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1230","question":"Greenhythe Glass reports current assets of $225,000, of which inventory is $75,000, and current liabilities of $150,000. What is the acid test ratio? Give your answer to two decimal places.","options":{"A":"1.50 : 1","B":"1.00 : 1","C":"0.50 : 1","D":"2.00 : 1"},"correctOption":"B","correctAnswer":"1.00 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test removes inventory, so ($225,000-$75,000)/$150,000 gives 1.00 : 1 for Greenhythe Glass. That is the liquidity measure that excludes inventory.","distractor_reasons":{"A":"1.50 : 1 is the current ratio, which includes the $75,000 of inventory that the acid test excludes. The acid test ratio for Greenhythe Glass is 1.00 : 1.","B":"The acid test removes inventory, so ($225,000-$75,000)/$150,000 gives 1.00 : 1 for Greenhythe Glass. That is the liquidity measure that excludes inventory.","C":"0.50 : 1 divides inventory by current liabilities, which is not the acid test calculation. The acid test ratio for Greenhythe Glass is 1.00 : 1.","D":"2.00 : 1 adds inventory to current assets even though the acid test removes it. The acid test ratio for Greenhythe Glass is 1.00 : 1."}}},{"id":"P1_U5_MCQ_1231","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1231","question":"Draycott Alarms borrows $72,000 from its bank for 2 years at a simple interest rate of 5% a year. The principal is repaid in full only at the end of the term, and interest is paid annually. What total interest will Draycott Alarms pay over the whole 2-year period?","options":{"A":"$3,600","B":"$79,200","C":"$7,200","D":"$7,380"},"correctOption":"C","correctAnswer":"$7,200","questionType":"MCQ","explanation":{"correct_reason":"Simple interest is the principal multiplied by the rate and the number of years, so $72,000 x 5% x 2 equals $7,200 of total interest for Draycott Alarms.","distractor_reasons":{"A":"$3,600 is the interest for one year only at 5% on $72,000, but the loan runs for 2 years, so it understates the total interest Draycott Alarms must pay.","B":"$79,200 adds the $72,000 principal to the $7,200 interest, which gives the total repayment rather than the interest charge that the question asks for.","C":"Simple interest is the principal multiplied by the rate and the number of years, so $72,000 x 5% x 2 equals $7,200 of total interest for Draycott Alarms.","D":"$7,380 treats the interest as compound and charges interest on unpaid interest, but the question states simple interest, so this figure overstates the true cost to Draycott Alarms."}}},{"id":"P1_U5_MCQ_1232","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1232","question":"The cash flow forecast for Yarrowfield Seeds shows a closing balance of $8,400 for May. The owner then decides to pay $5,600 for a new oven but also expects an extra receipt of $2,300 from a customer. What closing balance should the revised forecast show?","options":{"A":"$500","B":"$11,700","C":"$16,300","D":"$5,100"},"correctOption":"D","correctAnswer":"$5,100","questionType":"MCQ","explanation":{"correct_reason":"The revised balance is the $8,400 original figure minus the $5,600 oven payment plus the $2,300 extra receipt, giving $5,100 for Yarrowfield Seeds.","distractor_reasons":{"A":"$500 subtracts the extra receipt as well as the oven payment, but the receipt is money coming in and increases the bank balance.","B":"$11,700 adds the oven payment instead of deducting it, which reverses the effect of buying the oven on Yarrowfield Seeds's cash.","C":"$16,300 adds both the payment and the receipt, but paying for the oven reduces the cash balance rather than raising it.","D":"The revised balance is the $8,400 original figure minus the $5,600 oven payment plus the $2,300 extra receipt, giving $5,100 for Yarrowfield Seeds."}}},{"id":"P1_U5_MCQ_1233","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1233","question":"Sablewood Toys made a profit before tax of $64,000 for the year. Corporation tax is charged at 25% of profit before tax. What was the profit after tax for the year?","options":{"A":"$48,000","B":"$64,000","C":"$80,000","D":"$16,000"},"correctOption":"A","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Tax is 25% of $64,000, which is $16,000, so profit after tax is $64,000-$16,000 = $48,000 for Sablewood Toys. That is the profit the owners keep after tax.","distractor_reasons":{"A":"Tax is 25% of $64,000, which is $16,000, so profit after tax is $64,000-$16,000 = $48,000 for Sablewood Toys. That is the profit the owners keep after tax.","B":"$64,000 is the profit before tax, so it ignores the $16,000 that Sablewood Toys must pay to the tax authority.","C":"$80,000 adds the tax to profit instead of subtracting it, which overstates the amount that the owners of Sablewood Toys keep.","D":"$16,000 is the tax charge itself, not the profit that remains after tax is paid by Sablewood Toys. The profit after tax for Sablewood Toys is $48,000."}}},{"id":"P1_U5_MCQ_1234","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1234","question":"Marsh End Motors has current assets of $84,000 and current liabilities of $52,000. It then buys inventory worth $12,000 on credit. What is the working capital immediately after this purchase?","options":{"A":"$44,000","B":"$32,000","C":"$20,000","D":"$12,000"},"correctOption":"B","correctAnswer":"$32,000","questionType":"MCQ","explanation":{"correct_reason":"Buying inventory on credit raises both current assets and current liabilities by $12,000, so working capital stays at $84,000-$52,000 = $32,000 for Marsh End Motors.","distractor_reasons":{"A":"$44,000 adds the purchase to working capital, but the matching increase in current liabilities cancels that effect. The working capital for Marsh End Motors is $32,000.","B":"Buying inventory on credit raises both current assets and current liabilities by $12,000, so working capital stays at $84,000-$52,000 = $32,000 for Marsh End Motors.","C":"$20,000 deducts the purchase twice, once through the extra inventory and again through the higher payables. The working capital for Marsh End Motors is $32,000.","D":"$12,000 is just the value of the inventory bought, not the working capital that Marsh End Motors has available. The working capital for Marsh End Motors is $32,000."}}},{"id":"P1_U5_MCQ_1235","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1235","question":"The gross profit margin of Hartshead Hotels was 30.0% in 2024 and 35.0% in 2025. By how many percentage points did the gross profit margin change between the two years?","options":{"A":"28.3 percentage points","B":"30.0%","C":"5.0 percentage points","D":"35.0%"},"correctOption":"C","correctAnswer":"5.0 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The margin moved from 30.0% to 35.0%, a change of 5.0 percentage points for Hartshead Hotels between 2024 and 2025.","distractor_reasons":{"A":"28.3 percentage points is the percentage growth in gross profit itself, not the change in the margin measured in percentage points.","B":"30.0% is the 2024 margin on its own, not the change in the margin between the two years. The change in the gross profit margin for Hartshead Hotels is 5.0 percentage points.","C":"The margin moved from 30.0% to 35.0%, a change of 5.0 percentage points for Hartshead Hotels between 2024 and 2025.","D":"35.0% is the 2025 margin on its own, not the change in the margin between the two years. The change in the gross profit margin for Hartshead Hotels is 5.0 percentage points."}}},{"id":"P1_U5_MCQ_1236","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1236","question":"Emberton Tiles is buying a delivery vehicle on hire purchase. The agreement requires a deposit of $1,200 followed by 18 monthly instalments of $680 each. What is the total cost of the vehicle under this hire purchase agreement?","options":{"A":"$12,240","B":"$1,880","C":"$12,760","D":"$13,440"},"correctOption":"D","correctAnswer":"$13,440","questionType":"MCQ","explanation":{"correct_reason":"The total hire purchase cost is the deposit plus every instalment, so $1,200 plus 18 payments of $680 equals $13,440 for Emberton Tiles.","distractor_reasons":{"A":"$12,240 counts only the 18 monthly instalments and leaves out the $1,200 deposit, so it understates the total cost that Emberton Tiles pays under the agreement.","B":"$1,880 adds just one instalment of $680 to the $1,200 deposit instead of all 18 instalments, so it is far below the true total for Emberton Tiles.","C":"$12,760 includes only 17 instalments and omits the final payment of $680, but the agreement with Emberton Tiles requires all 18 monthly payments.","D":"The total hire purchase cost is the deposit plus every instalment, so $1,200 plus 18 payments of $680 equals $13,440 for Emberton Tiles."}}},{"id":"P1_U5_MCQ_1237","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1237","question":"Zealots Sports forecasts a net inflow of $3,200 in October, a net outflow of $1,800 in November and a net inflow of $2,600 in December. The opening bank balance is $4,500. What is the forecast closing balance at the end of December?","options":{"A":"$8,500","B":"$5,900","C":"$4,000","D":"$12,100"},"correctOption":"A","correctAnswer":"$8,500","questionType":"MCQ","explanation":{"correct_reason":"Starting from $4,500, adding $3,200, subtracting the $1,800 November outflow and adding $2,600 gives $8,500 for Zealots Sports at the end of December.","distractor_reasons":{"A":"Starting from $4,500, adding $3,200, subtracting the $1,800 November outflow and adding $2,600 gives $8,500 for Zealots Sports at the end of December.","B":"$5,900 stops at the end of November and omits the $2,600 December inflow, so it understates the closing balance. The closing balance for Zealots Sports is $8,500.","C":"$4,000 combines the three monthly flows but leaves out the $4,500 that Zealots Sports already holds in the bank. The closing balance for Zealots Sports is $8,500.","D":"$12,100 adds the November outflow instead of subtracting it, which overstates the closing balance at the end of December. The closing balance for Zealots Sports is $8,500."}}},{"id":"P1_U5_MCQ_1238","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1238","question":"Thornfield Optics made a profit for the year of $54,000 and paid dividends of $18,000 to its shareholders. What amount of profit was retained in the business for the year?","options":{"A":"$72,000","B":"$36,000","C":"$18,000","D":"$54,000"},"correctOption":"B","correctAnswer":"$36,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is the $54,000 earned minus the $18,000 paid out as dividends, leaving $36,000 kept in Thornfield Optics. That is the profit kept inside the business.","distractor_reasons":{"A":"$72,000 adds the dividends to profit, but dividends are paid out and therefore reduce the amount retained by Thornfield Optics.","B":"Retained profit is the $54,000 earned minus the $18,000 paid out as dividends, leaving $36,000 kept in Thornfield Optics. That is the profit kept inside the business.","C":"$18,000 is the dividend paid to shareholders, not the profit that Thornfield Optics kept inside the business for the year.","D":"$54,000 ignores the $18,000 of dividends, so it overstates the profit retained by Thornfield Optics. The retained profit for Thornfield Optics is $36,000."}}},{"id":"P1_U5_MCQ_1239","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1239","question":"Nightingale Care has current assets of $176,000 and current liabilities of $80,000. It then uses $24,000 of cash to pay a supplier. What is the current ratio immediately after the payment? Give your answer to two decimal places.","options":{"A":"2.20 : 1","B":"3.14 : 1","C":"2.71 : 1","D":"1.90 : 1"},"correctOption":"C","correctAnswer":"2.71 : 1","questionType":"MCQ","explanation":{"correct_reason":"Paying the supplier reduces both figures by $24,000, so $152,000/$56,000 gives 2.71 : 1 for Nightingale Care. That is the ratio after the supplier has been paid.","distractor_reasons":{"A":"2.20 : 1 is the current ratio before the payment and ignores the equal reduction in cash and payables. The current ratio for Nightingale Care is 2.71 : 1.","B":"3.14 : 1 reduces only the liabilities and forgets that the $24,000 of cash has also left the business. The current ratio for Nightingale Care is 2.71 : 1.","C":"Paying the supplier reduces both figures by $24,000, so $152,000/$56,000 gives 2.71 : 1 for Nightingale Care. That is the ratio after the supplier has been paid.","D":"1.90 : 1 reduces only current assets and forgets that the payable to the supplier has been settled. The current ratio for Nightingale Care is 2.71 : 1."}}},{"id":"P1_U5_MCQ_1240","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1240","question":"Ingham Ironworks reports revenue of $320,000 and operating profit of $48,000 for the year. The owner is checking how much profit is kept from each dollar of sales. What is the profit margin? Give your answer to one decimal place.","options":{"A":"30.0%","B":"50.0%","C":"7.5%","D":"15.0%"},"correctOption":"D","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"The profit margin is operating profit divided by revenue, so $48,000/$320,000 x 100 gives 15.0% for Ingham Ironworks. That is the share of sales kept as operating profit.","distractor_reasons":{"A":"30.0% is the gross profit margin, which uses gross profit rather than the $48,000 of operating profit earned by Ingham Ironworks.","B":"50.0% divides operating profit by gross profit instead of by revenue, so it is not the profit margin of Ingham Ironworks.","C":"7.5% is half the correct figure and has no basis in the $48,000 profit or the $320,000 revenue. The profit margin for Ingham Ironworks is 15.0%.","D":"The profit margin is operating profit divided by revenue, so $48,000/$320,000 x 100 gives 15.0% for Ingham Ironworks. That is the share of sales kept as operating profit."}}},{"id":"P1_U5_MCQ_1241","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1241","question":"Farrowsby Gems leases a machine for 3 years. The annual lease payment is $9,500 and the annual maintenance contract costs a further $1,200. What is the total cost of leasing and maintaining the machine over the 3 years?","options":{"A":"$32,100","B":"$28,500","C":"$10,700","D":"$29,700"},"correctOption":"A","correctAnswer":"$32,100","questionType":"MCQ","explanation":{"correct_reason":"Each year costs $9,500 in lease payments plus $1,200 for maintenance, so the annual total of $10,700 multiplied by 3 years gives $32,100 for Farrowsby Gems.","distractor_reasons":{"A":"Each year costs $9,500 in lease payments plus $1,200 for maintenance, so the annual total of $10,700 multiplied by 3 years gives $32,100 for Farrowsby Gems.","B":"$28,500 covers the lease payments but omits the $1,200 annual maintenance charge, so it understates the total cost of running the machine for 3 years.","C":"$10,700 is the cost of a single year only, but Farrowsby Gems leases the machine for 3 years, so it ignores the remaining 2 years of payments.","D":"$29,700 adds the maintenance charge only once instead of for each of the 3 years, so it understates the total paid by Farrowsby Gems."}}},{"id":"P1_U5_MCQ_1242","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1242","question":"Ambergate Coaches forecasts cash receipts of $148,000 and cash payments of $132,500 for the coming quarter. The business expects to start the quarter with a bank balance of $11,500. What is the forecast net cash flow for the quarter?","options":{"A":"$280,500","B":"$15,500","C":"$27,000","D":"$-4,000"},"correctOption":"B","correctAnswer":"$15,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is total receipts minus total payments, so $148,000 less $132,500 gives a net inflow of $15,500 for Ambergate Coaches this quarter.","distractor_reasons":{"A":"$280,500 adds receipts and payments together, but net cash flow requires the payments to be subtracted from the receipts, so this figure is far too high.","B":"Net cash flow is total receipts minus total payments, so $148,000 less $132,500 gives a net inflow of $15,500 for Ambergate Coaches this quarter.","C":"$27,000 includes the $11,500 opening balance, so it is the forecast closing balance rather than the net cash flow generated during the quarter.","D":"$-4,000 adds the payments to the opening balance and subtracts receipts, which reverses the correct treatment of the two cash flows."}}},{"id":"P1_U5_MCQ_1243","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1243","question":"Upham Valley Cider recorded gross profit of $72,000 and a profit for the year of $28,500, with no interest charges. What were the operating expenses for the year?","options":{"A":"$100,500","B":"$28,500","C":"$43,500","D":"$72,000"},"correctOption":"C","correctAnswer":"$43,500","questionType":"MCQ","explanation":{"correct_reason":"Operating expenses are the gap between gross profit and profit for the year, so $72,000-$28,500 gives $43,500 for Upham Valley Cider.","distractor_reasons":{"A":"$100,500 adds the two figures together, which is not how the operating expenses of Upham Valley Cider are found from gross profit and profit.","B":"$28,500 is the profit for the year, not the operating expenses that were deducted to reach it in the accounts of Upham Valley Cider.","C":"Operating expenses are the gap between gross profit and profit for the year, so $72,000-$28,500 gives $43,500 for Upham Valley Cider.","D":"$72,000 is the gross profit itself, so it cannot also be the operating expenses of Upham Valley Cider. The operating expenses for Upham Valley Cider is $43,500."}}},{"id":"P1_U5_MCQ_1244","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1244","question":"Old Wharf Chandlers reports capital employed of $560,000 and equity of $340,000 at the year end. The owner is checking how the rest of the business is financed. What are the non-current liabilities of the business?","options":{"A":"$900,000","B":"$340,000","C":"$560,000","D":"$220,000"},"correctOption":"D","correctAnswer":"$220,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is equity plus non-current liabilities, so $560,000-$340,000 gives $220,000 of non-current liabilities for Old Wharf Chandlers. That is the long-term debt owed by the business.","distractor_reasons":{"A":"$900,000 adds equity to capital employed instead of deducting it, which overstates the liabilities of Old Wharf Chandlers. The non-current liabilities for Old Wharf Chandlers is $220,000.","B":"$340,000 is the equity belonging to the owners, not the non-current liabilities that Old Wharf Chandlers owes to lenders. The non-current liabilities for Old Wharf Chandlers is $220,000.","C":"$560,000 is the total capital employed, which includes the equity as well as the non-current liabilities. The non-current liabilities for Old Wharf Chandlers is $220,000.","D":"Capital employed is equity plus non-current liabilities, so $560,000-$340,000 gives $220,000 of non-current liabilities for Old Wharf Chandlers. That is the long-term debt owed by the business."}}},{"id":"P1_U5_MCQ_1245","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1245","question":"Jessamine Jams reports operating profit of $52,500 for the year and capital employed of $350,000 at the year end. The owner wants to judge how well the capital has been used. What is the return on capital employed? Give your answer to one decimal place.","options":{"A":"15.0%","B":"13.0%","C":"17.6%","D":"7.5%"},"correctOption":"A","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"ROCE is operating profit divided by capital employed, so $52,500/$350,000 x 100 gives 15.0% for Jessamine Jams. That is the return earned on each dollar of capital employed.","distractor_reasons":{"A":"ROCE is operating profit divided by capital employed, so $52,500/$350,000 x 100 gives 15.0% for Jessamine Jams. That is the return earned on each dollar of capital employed.","B":"13.0% adds operating profit to capital employed in the denominator, which is not the ROCE formula. The return on capital employed for Jessamine Jams is 15.0%.","C":"17.6% deducts profit from capital employed before dividing, so the denominator is wrong. The return on capital employed for Jessamine Jams is 15.0%.","D":"7.5% is half the correct return and cannot be obtained from $52,500 and $350,000. The return on capital employed for Jessamine Jams is 15.0%."}}},{"id":"P1_U5_MCQ_1246","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1246","question":"Gildermere Sails began the year with retained profit of $28,000. The business made a profit for the year of $41,000 and paid dividends of $9,000 to its owners. What retained profit is carried forward at the end of the year?","options":{"A":"$69,000","B":"$60,000","C":"$32,000","D":"$78,000"},"correctOption":"B","correctAnswer":"$60,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit carried forward is the opening $28,000 plus the $41,000 earned, less the $9,000 paid as dividends, giving $60,000 for Gildermere Sails.","distractor_reasons":{"A":"$69,000 adds the profit to the opening balance but fails to deduct the $9,000 of dividends, so it overstates the retained profit of Gildermere Sails.","B":"Retained profit carried forward is the opening $28,000 plus the $41,000 earned, less the $9,000 paid as dividends, giving $60,000 for Gildermere Sails.","C":"$32,000 is only the profit kept after dividends and ignores the $28,000 of retained profit that Gildermere Sails already held.","D":"$78,000 adds the dividends instead of subtracting them, which counts money twice even though it has left the business. The retained profit for Gildermere Sails is $60,000."}}},{"id":"P1_U5_MCQ_1247","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1247","question":"Bellhouse Brewing forecasts a closing bank balance of $6,400 for September after receipts of $71,300 and payments of $66,900. What opening bank balance must the forecast show for the start of September?","options":{"A":"$10,800","B":"$4,400","C":"$2,000","D":"$144,600"},"correctOption":"C","correctAnswer":"$2,000","questionType":"MCQ","explanation":{"correct_reason":"The opening balance is the $6,400 closing figure minus the net inflow of $4,400, which gives $2,000 at the start of September for Bellhouse Brewing.","distractor_reasons":{"A":"$10,800 adds the net inflow to the closing balance instead of subtracting it, so it moves the balance the wrong way.","B":"$4,400 is the net cash flow for September, not the balance that Bellhouse Brewing held at the start of the month.","C":"The opening balance is the $6,400 closing figure minus the net inflow of $4,400, which gives $2,000 at the start of September for Bellhouse Brewing.","D":"$144,600 adds both receipts and payments to the closing balance, but payments reduce the balance and should be subtracted. The opening balance for Bellhouse Brewing is $2,000."}}},{"id":"P1_U5_MCQ_1248","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1248","question":"Vantage Point Films reports gross profit of $63,000 for the year and cost of sales of $87,000. The owner wants to confirm the total sales revenue earned. What was the revenue for the year?","options":{"A":"$24,000","B":"$87,000","C":"$237,000","D":"$150,000"},"correctOption":"D","correctAnswer":"$150,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals gross profit plus cost of sales, so $63,000+$87,000 gives $150,000 of revenue for Vantage Point Films. That is the total sales revenue for the year.","distractor_reasons":{"A":"$24,000 subtracts gross profit from cost of sales, but revenue must be the sum of the two figures. The revenue for Vantage Point Films is $150,000.","B":"$87,000 is only the cost of sales, which is one component of revenue rather than the total earned by Vantage Point Films.","C":"$237,000 counts the cost of sales twice, which overstates the revenue of Vantage Point Films for the year. The revenue for Vantage Point Films is $150,000.","D":"Revenue equals gross profit plus cost of sales, so $63,000+$87,000 gives $150,000 of revenue for Vantage Point Films. That is the total sales revenue for the year."}}},{"id":"P1_U5_MCQ_1249","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1249","question":"Pinegrove Paints reports non-current assets of $285,000 and current assets of $95,000 at its year end. It has no other assets. What is the total of its assets?","options":{"A":"$380,000","B":"$190,000","C":"$95,000","D":"$475,000"},"correctOption":"A","correctAnswer":"$380,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are non-current assets plus current assets, so $285,000+$95,000 gives $380,000 for Pinegrove Paints. That is the total asset base of the business.","distractor_reasons":{"A":"Total assets are non-current assets plus current assets, so $285,000+$95,000 gives $380,000 for Pinegrove Paints. That is the total asset base of the business.","B":"$190,000 subtracts current assets from non-current assets, but both are assets and must be added together. The total assets for Pinegrove Paints is $380,000.","C":"$95,000 is only the current assets and ignores the $285,000 of non-current assets held by Pinegrove Paints. The total assets for Pinegrove Paints is $380,000.","D":"$475,000 counts the current assets twice, which overstates the total assets of Pinegrove Paints. The total assets for Pinegrove Paints is $380,000."}}},{"id":"P1_U5_MCQ_1250","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1250","question":"Kelbrook Kitchens reports revenue of $520,000 and gross profit of $182,000 for the year. The owner is reviewing profitability. What is the gross profit margin? Give your answer to one decimal place.","options":{"A":"65.0%","B":"35.0%","C":"17.5%","D":"53.8%"},"correctOption":"B","correctAnswer":"35.0%","questionType":"MCQ","explanation":{"correct_reason":"The gross profit margin is gross profit divided by revenue, so $182,000/$520,000 x 100 gives 35.0% for Kelbrook Kitchens. That is the share of sales left after cost of sales.","distractor_reasons":{"A":"65.0% is the cost of sales as a percentage of revenue, which is the complement of the gross profit margin for Kelbrook Kitchens.","B":"The gross profit margin is gross profit divided by revenue, so $182,000/$520,000 x 100 gives 35.0% for Kelbrook Kitchens. That is the share of sales left after cost of sales.","C":"17.5% is half the correct margin and does not come from dividing $182,000 by $520,000. The gross profit margin for Kelbrook Kitchens is 35.0%.","D":"53.8% compares gross profit with cost of sales rather than with revenue, so it uses the wrong denominator for Kelbrook Kitchens."}}},{"id":"P1_U5_MCQ_1251","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1251","question":"Hollowbrook Signs arranges a bank overdraft of $45,000 to cover a seasonal shortage. The overdraft carries interest at 7.5% a year, and Hollowbrook Signs expects to use the full amount for 6 months. What interest will the business pay for this period?","options":{"A":"$3,375","B":"$20,250","C":"$1,687.50","D":"$46,687.50"},"correctOption":"C","correctAnswer":"$1,687.50","questionType":"MCQ","explanation":{"correct_reason":"The interest is $45,000 x 7.5% x 6/12, because the overdraft is used for 6 months of the year, giving $1,687.50 for Hollowbrook Signs.","distractor_reasons":{"A":"$3,375 charges a full year of interest at 7.5%, but Hollowbrook Signs only uses the overdraft for 6 months, so it overstates the interest cost.","B":"$20,250 multiplies the annual rate by 6 without dividing by twelve, so it treats the 6-month period as 6 whole years of borrowing.","C":"The interest is $45,000 x 7.5% x 6/12, because the overdraft is used for 6 months of the year, giving $1,687.50 for Hollowbrook Signs.","D":"$46,687.50 adds the $45,000 borrowed to the $1,687.50 interest, which gives the total repaid rather than the interest charged to Hollowbrook Signs."}}},{"id":"P1_U5_MCQ_1252","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1252","question":"Corvid Couriers started the month with a bank balance of $9,800 and received $55,600 from customers. The forecast closing balance is $12,400. What total cash payments must the forecast show for the month?","options":{"A":"$77,800","B":"$58,200","C":"$33,400","D":"$53,000"},"correctOption":"D","correctAnswer":"$53,000","questionType":"MCQ","explanation":{"correct_reason":"Payments equal the $9,800 opening balance plus $55,600 received minus the $12,400 closing balance, which gives $53,000 of payments for Corvid Couriers.","distractor_reasons":{"A":"$77,800 adds the closing balance instead of subtracting it, so it overstates the payments by twice the closing figure. The total payments for Corvid Couriers is $53,000.","B":"$58,200 rearranges the figures incorrectly and produces a total that does not reconcile the opening and closing balances of Corvid Couriers.","C":"$33,400 subtracts both the opening and closing balances from receipts, which is not how a cash flow forecast is balanced.","D":"Payments equal the $9,800 opening balance plus $55,600 received minus the $12,400 closing balance, which gives $53,000 of payments for Corvid Couriers."}}},{"id":"P1_U5_MCQ_1253","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1253","question":"Westcliff Marine reports revenue of $420,000 for the year and cost of sales of $273,000. Operating expenses for the year were $91,000. What is the gross profit for the year?","options":{"A":"$147,000","B":"$56,000","C":"$693,000","D":"$329,000"},"correctOption":"A","correctAnswer":"$147,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, so $420,000 less $273,000 gives $147,000 for Westcliff Marine, before operating expenses are deducted.","distractor_reasons":{"A":"Gross profit is revenue minus cost of sales, so $420,000 less $273,000 gives $147,000 for Westcliff Marine, before operating expenses are deducted.","B":"$56,000 also deducts the $91,000 operating expenses, which gives the profit for the year rather than the gross profit of Westcliff Marine.","C":"$693,000 adds cost of sales to revenue instead of subtracting it, which cannot produce the gross profit earned by Westcliff Marine.","D":"$329,000 deducts operating expenses from revenue but ignores cost of sales entirely, so the two amounts have been mixed up."}}},{"id":"P1_U5_MCQ_1254","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1254","question":"Quayside Bistro reports current assets of $72,000 and current liabilities of $45,000 at its year end. The owner wants to know how much short-term finance is available to run the business. What is the working capital?","options":{"A":"$117,000","B":"$27,000","C":"$45,000","D":"$72,000"},"correctOption":"B","correctAnswer":"$27,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so $72,000 less $45,000 gives $27,000 for Quayside Bistro. That is the short-term finance available to the business.","distractor_reasons":{"A":"$117,000 adds current liabilities to current assets, but working capital requires the $45,000 to be deducted, so it overstates the figure.","B":"Working capital is current assets minus current liabilities, so $72,000 less $45,000 gives $27,000 for Quayside Bistro. That is the short-term finance available to the business.","C":"$45,000 is the current liabilities figure on its own, not the working capital left after deducting it from current assets.","D":"$72,000 is the current assets total before the $45,000 of current liabilities is deducted, so it overstates working capital. The working capital for Quayside Bistro is $27,000."}}},{"id":"P1_U5_MCQ_1255","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1255","question":"Larchfield Laundry reports revenue of $258,000 and operating profit of $38,700 for the year. The owner is checking how much profit is kept from each dollar of sales. What is the profit margin? Give your answer to one decimal place.","options":{"A":"35.0%","B":"42.9%","C":"15.0%","D":"7.5%"},"correctOption":"C","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"The profit margin is operating profit divided by revenue, so $38,700/$258,000 x 100 gives 15.0% for Larchfield Laundry. That is the share of sales kept as operating profit.","distractor_reasons":{"A":"35.0% is the gross profit margin, which uses gross profit rather than the $38,700 of operating profit earned by Larchfield Laundry.","B":"42.9% divides operating profit by gross profit instead of by revenue, so it is not the profit margin of Larchfield Laundry.","C":"The profit margin is operating profit divided by revenue, so $38,700/$258,000 x 100 gives 15.0% for Larchfield Laundry. That is the share of sales kept as operating profit.","D":"7.5% is half the correct figure and has no basis in the $38,700 profit or the $258,000 revenue. The profit margin for Larchfield Laundry is 15.0%."}}},{"id":"P1_U5_MCQ_1256","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1256","question":"Inkleby 3D Print is a private limited company raising expansion finance by issuing 80,000 new shares at $1.75 each. The share issue costs $22,000 in fees. What net amount will the business raise after paying the issue costs?","options":{"A":"$140,000","B":"$162,000","C":"$70,000","D":"$118,000"},"correctOption":"D","correctAnswer":"$118,000","questionType":"MCQ","explanation":{"correct_reason":"The gross proceeds are 80,000 shares x $1.75, which is $140,000, and subtracting the $22,000 issue costs leaves $118,000 raised by Inkleby 3D Print.","distractor_reasons":{"A":"$140,000 is the gross proceeds before the $22,000 of issue costs are paid, so it overstates the cash that Inkleby 3D Print actually receives.","B":"$162,000 adds the issue costs to the proceeds instead of deducting them, which is the opposite of what happens when Inkleby 3D Print issues shares.","C":"$70,000 is exactly half of the gross proceeds and has no basis in the 80,000 shares, the $1.75 price or the $22,000 issue costs.","D":"The gross proceeds are 80,000 shares x $1.75, which is $140,000, and subtracting the $22,000 issue costs leaves $118,000 raised by Inkleby 3D Print."}}},{"id":"P1_U5_MCQ_1257","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1257","question":"Dunlin Boatyard expects to open July with a bank balance of $26,400. Forecast receipts for the month are $91,500 and forecast payments are $98,700. What closing bank balance should appear in the cash flow forecast for July?","options":{"A":"$19,200","B":"$216,600","C":"$-7,200","D":"$33,600"},"correctOption":"A","correctAnswer":"$19,200","questionType":"MCQ","explanation":{"correct_reason":"The closing balance is the $26,400 opening balance plus $91,500 of receipts minus $98,700 of payments, giving $19,200 for Dunlin Boatyard at the end of July.","distractor_reasons":{"A":"The closing balance is the $26,400 opening balance plus $91,500 of receipts minus $98,700 of payments, giving $19,200 for Dunlin Boatyard at the end of July.","B":"$216,600 adds the payments instead of subtracting them, so it cannot be the closing bank balance that Dunlin Boatyard will actually hold.","C":"$-7,200 is only the net cash flow for the month and leaves out the $26,400 that Dunlin Boatyard already holds at the start of July.","D":"$33,600 subtracts the net inflow from the opening balance instead of adding it, which moves the balance in the wrong direction."}}},{"id":"P1_U5_MCQ_1258","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1258","question":"Xanthe Cosmetics began the year with inventory of $32,000, bought goods costing $146,000 and ended with inventory of $28,000. Revenue for the year was $210,000. What was the gross profit?","options":{"A":"$32,000","B":"$60,000","C":"$92,000","D":"$4,000"},"correctOption":"B","correctAnswer":"$60,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is $32,000+$146,000-$28,000 = $150,000, so revenue of $210,000 less $150,000 gives gross profit of $60,000 for Xanthe Cosmetics.","distractor_reasons":{"A":"$32,000 uses opening inventory plus purchases as cost of sales and ignores the $28,000 closing inventory held by Xanthe Cosmetics.","B":"Cost of sales is $32,000+$146,000-$28,000 = $150,000, so revenue of $210,000 less $150,000 gives gross profit of $60,000 for Xanthe Cosmetics.","C":"$92,000 omits the $32,000 opening inventory from cost of sales, so the gross profit of Xanthe Cosmetics is overstated. The gross profit for Xanthe Cosmetics is $60,000.","D":"$4,000 adds closing inventory to cost of sales instead of subtracting it, so the gross profit is far too low."}}},{"id":"P1_U5_MCQ_1259","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1259","question":"Redpoll Cycles holds inventory of $29,000, trade receivables of $33,000 and cash of $8,000 at the year end. It has no other current assets. What is the total of its current assets?","options":{"A":"$62,000","B":"$37,000","C":"$70,000","D":"$41,000"},"correctOption":"C","correctAnswer":"$70,000","questionType":"MCQ","explanation":{"correct_reason":"Current assets are added together, so $29,000+$33,000+$8,000 gives $70,000 for Redpoll Cycles. That is the total of the resources expected to turn into cash.","distractor_reasons":{"A":"$62,000 leaves out the $8,000 of cash, which is a current asset and must be included in the total. The total current assets for Redpoll Cycles is $70,000.","B":"$37,000 omits the $33,000 owed by trade receivables, so it understates the current assets of Redpoll Cycles. The total current assets for Redpoll Cycles is $70,000.","C":"Current assets are added together, so $29,000+$33,000+$8,000 gives $70,000 for Redpoll Cycles. That is the total of the resources expected to turn into cash.","D":"$41,000 leaves out the $29,000 of inventory held by Redpoll Cycles at the year end. The total current assets for Redpoll Cycles is $70,000."}}},{"id":"P1_U5_MCQ_1260","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1260","question":"Midgeley Motors reports operating profit of $84,000 for the year and capital employed of $560,000 at the year end. The owner wants to judge how well the capital has been used. What is the return on capital employed? Give your answer to one decimal place.","options":{"A":"13.0%","B":"17.6%","C":"7.5%","D":"15.0%"},"correctOption":"D","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"ROCE is operating profit divided by capital employed, so $84,000/$560,000 x 100 gives 15.0% for Midgeley Motors. That is the return earned on each dollar of capital employed.","distractor_reasons":{"A":"13.0% adds operating profit to capital employed in the denominator, which is not the ROCE formula. The return on capital employed for Midgeley Motors is 15.0%.","B":"17.6% deducts profit from capital employed before dividing, so the denominator is wrong. The return on capital employed for Midgeley Motors is 15.0%.","C":"7.5% is half the correct return and cannot be obtained from $84,000 and $560,000. The return on capital employed for Midgeley Motors is 15.0%.","D":"ROCE is operating profit divided by capital employed, so $84,000/$560,000 x 100 gives 15.0% for Midgeley Motors. That is the return earned on each dollar of capital employed."}}},{"id":"P1_U5_MCQ_1261","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1261","question":"Jetsam Salvage borrows $125,000 from its bank for 4 years at a simple interest rate of 4% a year. The principal is repaid in full only at the end of the term, and interest is paid annually. What total interest will Jetsam Salvage pay over the whole 4-year period?","options":{"A":"$20,000","B":"$5,000","C":"$145,000","D":"$21,232.32"},"correctOption":"A","correctAnswer":"$20,000","questionType":"MCQ","explanation":{"correct_reason":"Simple interest is the principal multiplied by the rate and the number of years, so $125,000 x 4% x 4 equals $20,000 of total interest for Jetsam Salvage.","distractor_reasons":{"A":"Simple interest is the principal multiplied by the rate and the number of years, so $125,000 x 4% x 4 equals $20,000 of total interest for Jetsam Salvage.","B":"$5,000 is the interest for one year only at 4% on $125,000, but the loan runs for 4 years, so it understates the total interest Jetsam Salvage must pay.","C":"$145,000 adds the $125,000 principal to the $20,000 interest, which gives the total repayment rather than the interest charge that the question asks for.","D":"$21,232.32 treats the interest as compound and charges interest on unpaid interest, but the question states simple interest, so this figure overstates the true cost to Jetsam Salvage."}}},{"id":"P1_U5_MCQ_1262","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1262","question":"Elderflower Events forecasts a net inflow of $5,400 in October, a net outflow of $2,900 in November and a net inflow of $3,600 in December. The opening bank balance is $6,800. What is the forecast closing balance at the end of December?","options":{"A":"$9,300","B":"$12,900","C":"$6,100","D":"$18,700"},"correctOption":"B","correctAnswer":"$12,900","questionType":"MCQ","explanation":{"correct_reason":"Starting from $6,800, adding $5,400, subtracting the $2,900 November outflow and adding $3,600 gives $12,900 for Elderflower Events at the end of December.","distractor_reasons":{"A":"$9,300 stops at the end of November and omits the $3,600 December inflow, so it understates the closing balance. The closing balance for Elderflower Events is $12,900.","B":"Starting from $6,800, adding $5,400, subtracting the $2,900 November outflow and adding $3,600 gives $12,900 for Elderflower Events at the end of December.","C":"$6,100 combines the three monthly flows but leaves out the $6,800 that Elderflower Events already holds in the bank. The closing balance for Elderflower Events is $12,900.","D":"$18,700 adds the November outflow instead of subtracting it, which overstates the closing balance at the end of December. The closing balance for Elderflower Events is $12,900."}}},{"id":"P1_U5_MCQ_1263","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1263","question":"Yewbarrow Furniture reports gross profit of $118,000 for the year. Operating expenses were $67,400 and interest payable on its bank loan was $8,600. What was the profit for the year?","options":{"A":"$50,600","B":"$59,200","C":"$42,000","D":"$194,000"},"correctOption":"C","correctAnswer":"$42,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year deducts both operating expenses and interest, so $118,000-$67,400-$8,600 gives $42,000 for Yewbarrow Furniture. That is the profit left after expenses and interest.","distractor_reasons":{"A":"$50,600 deducts operating expenses but forgets the $8,600 of interest, so it overstates the profit of Yewbarrow Furniture. The profit for the year for Yewbarrow Furniture is $42,000.","B":"$59,200 adds interest back instead of deducting it, which treats a cost as income in the accounts of Yewbarrow Furniture.","C":"Profit for the year deducts both operating expenses and interest, so $118,000-$67,400-$8,600 gives $42,000 for Yewbarrow Furniture. That is the profit left after expenses and interest.","D":"$194,000 adds both costs to gross profit, which is the opposite of the correct treatment. The profit for the year for Yewbarrow Furniture is $42,000."}}},{"id":"P1_U5_MCQ_1264","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1264","question":"Saltmarsh Shellfish reports current assets of $98,000, which include inventory of $32,000, and current liabilities of $49,000. What is the acid test ratio? Give your answer to two decimal places.","options":{"A":"2.00 : 1","B":"0.65 : 1","C":"2.65 : 1","D":"1.35 : 1"},"correctOption":"D","correctAnswer":"1.35 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test removes inventory, so ($98,000-$32,000)/$49,000 gives 1.35 : 1 for Saltmarsh Shellfish. That is the liquidity measure that excludes inventory.","distractor_reasons":{"A":"2.00 : 1 is the current ratio, which includes the $32,000 of inventory that the acid test deliberately excludes. The acid test ratio for Saltmarsh Shellfish is 1.35 : 1.","B":"0.65 : 1 divides inventory by current liabilities, which is not the acid test calculation used to judge liquidity. The acid test ratio for Saltmarsh Shellfish is 1.35 : 1.","C":"2.65 : 1 adds inventory to current assets even though the acid test removes it before dividing. The acid test ratio for Saltmarsh Shellfish is 1.35 : 1.","D":"The acid test removes inventory, so ($98,000-$32,000)/$49,000 gives 1.35 : 1 for Saltmarsh Shellfish. That is the liquidity measure that excludes inventory."}}},{"id":"P1_U5_MCQ_1265","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1265","question":"Netherton Nuts reports current assets of $96,000, including inventory of $32,000, and current liabilities of $64,000. What is the current ratio? Give your answer to two decimal places.","options":{"A":"1.50 : 1","B":"1.00 : 1","C":"0.67 : 1","D":"2.00 : 1"},"correctOption":"A","correctAnswer":"1.50 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets divided by current liabilities, so $96,000/$64,000 gives 1.50 : 1 for Netherton Nuts. That means the business holds this much in current assets for each dollar of current liabilities.","distractor_reasons":{"A":"The current ratio is current assets divided by current liabilities, so $96,000/$64,000 gives 1.50 : 1 for Netherton Nuts. That means the business holds this much in current assets for each dollar of current liabilities.","B":"1.00 : 1 is the acid test ratio, which removes the $32,000 inventory before dividing. The current ratio for Netherton Nuts is 1.50 : 1.","C":"0.67 : 1 reverses the calculation by dividing current liabilities by current assets. The current ratio for Netherton Nuts is 1.50 : 1.","D":"2.00 : 1 adds inventory to current assets before dividing by current liabilities, which double counts the stock. The current ratio for Netherton Nuts is 1.50 : 1."}}},{"id":"P1_U5_MCQ_1266","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1266","question":"Kippford Ropes receives an invoice for $88,000 from a supplier that offers a cash discount of 1.5% for payment within ten days. Kippford Ropes decides to pay within the discount period. How much money will the business save by paying early?","options":{"A":"$86,680","B":"$1,320","C":"$2,640","D":"$132"},"correctOption":"B","correctAnswer":"$1,320","questionType":"MCQ","explanation":{"correct_reason":"The saving is 1.5% of the $88,000 invoice, and $88,000 x 1.5% equals $1,320, which is the cash discount Kippford Ropes gains by paying within ten days.","distractor_reasons":{"A":"$86,680 is the amount actually paid after deducting the discount, not the saving itself, so it answers a different question from the one asked.","B":"The saving is 1.5% of the $88,000 invoice, and $88,000 x 1.5% equals $1,320, which is the cash discount Kippford Ropes gains by paying within ten days.","C":"$2,640 applies the 1.5% discount twice to the same invoice, which no supplier would allow, so it doubles the true saving for Kippford Ropes.","D":"$132 moves the decimal point one place too far when taking 1.5% of $88,000, so it is ten times smaller than the correct saving."}}},{"id":"P1_U5_MCQ_1267","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1267","question":"The cash flow forecast for Flintlock Forge shows a closing balance of $9,000 for May. The owner then decides to pay $4,800 for a new oven but also expects an extra receipt of $1,900 from a customer. What closing balance should the revised forecast show?","options":{"A":"$2,300","B":"$11,900","C":"$6,100","D":"$15,700"},"correctOption":"C","correctAnswer":"$6,100","questionType":"MCQ","explanation":{"correct_reason":"The revised balance is the $9,000 original figure minus the $4,800 oven payment plus the $1,900 extra receipt, giving $6,100 for Flintlock Forge.","distractor_reasons":{"A":"$2,300 subtracts the extra receipt as well as the oven payment, but the receipt is money coming in and increases the bank balance.","B":"$11,900 adds the oven payment instead of deducting it, which reverses the effect of buying the oven on Flintlock Forge's cash.","C":"The revised balance is the $9,000 original figure minus the $4,800 oven payment plus the $1,900 extra receipt, giving $6,100 for Flintlock Forge.","D":"$15,700 adds both the payment and the receipt, but paying for the oven reduces the cash balance rather than raising it."}}},{"id":"P1_U5_MCQ_1268","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1268","question":"Zephyr Wings made a profit before tax of $88,000 for the year. Corporation tax is charged at 22% of profit before tax. What was the profit after tax for the year?","options":{"A":"$88,000","B":"$107,360","C":"$19,360","D":"$68,640"},"correctOption":"D","correctAnswer":"$68,640","questionType":"MCQ","explanation":{"correct_reason":"Tax is 22% of $88,000, which is $19,360, so profit after tax is $88,000-$19,360 = $68,640 for Zephyr Wings. That is the profit the owners keep after tax.","distractor_reasons":{"A":"$88,000 is the profit before tax, so it ignores the $19,360 that Zephyr Wings must pay to the tax authority.","B":"$107,360 adds the tax to profit instead of subtracting it, which overstates the amount that the owners of Zephyr Wings keep.","C":"$19,360 is the tax charge itself, not the profit that remains after tax is paid by Zephyr Wings. The profit after tax for Zephyr Wings is $68,640.","D":"Tax is 22% of $88,000, which is $19,360, so profit after tax is $88,000-$19,360 = $68,640 for Zephyr Wings. That is the profit the owners keep after tax."}}},{"id":"P1_U5_MCQ_1269","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1269","question":"Tideswell Tearooms reports current assets of $126,000, which include inventory of $54,000, and current liabilities of $72,000. What is the acid test ratio? Give your answer to two decimal places.","options":{"A":"1.00 : 1","B":"1.75 : 1","C":"0.75 : 1","D":"2.50 : 1"},"correctOption":"A","correctAnswer":"1.00 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test removes inventory, so ($126,000-$54,000)/$72,000 gives 1.00 : 1 for Tideswell Tearooms. That is the liquidity measure that excludes inventory.","distractor_reasons":{"A":"The acid test removes inventory, so ($126,000-$54,000)/$72,000 gives 1.00 : 1 for Tideswell Tearooms. That is the liquidity measure that excludes inventory.","B":"1.75 : 1 is the current ratio, which includes the $54,000 of inventory that the acid test deliberately excludes. The acid test ratio for Tideswell Tearooms is 1.00 : 1.","C":"0.75 : 1 divides inventory by current liabilities, which is not the acid test calculation used to judge liquidity. The acid test ratio for Tideswell Tearooms is 1.00 : 1.","D":"2.50 : 1 adds inventory to current assets even though the acid test removes it before dividing. The acid test ratio for Tideswell Tearooms is 1.00 : 1."}}},{"id":"P1_U5_MCQ_1270","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1270","question":"Oxley Outdoors reports current assets of $144,000, of which inventory is $48,000, and current liabilities of $96,000. What is the acid test ratio? Give your answer to two decimal places.","options":{"A":"1.50 : 1","B":"1.00 : 1","C":"0.50 : 1","D":"2.00 : 1"},"correctOption":"B","correctAnswer":"1.00 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test removes inventory, so ($144,000-$48,000)/$96,000 gives 1.00 : 1 for Oxley Outdoors. That is the liquidity measure that excludes inventory.","distractor_reasons":{"A":"1.50 : 1 is the current ratio, which includes the $48,000 of inventory that the acid test excludes. The acid test ratio for Oxley Outdoors is 1.00 : 1.","B":"The acid test removes inventory, so ($144,000-$48,000)/$96,000 gives 1.00 : 1 for Oxley Outdoors. That is the liquidity measure that excludes inventory.","C":"0.50 : 1 divides inventory by current liabilities, which is not the acid test calculation. The acid test ratio for Oxley Outdoors is 1.00 : 1.","D":"2.00 : 1 adds inventory to current assets even though the acid test removes it. The acid test ratio for Oxley Outdoors is 1.00 : 1."}}},{"id":"P1_U5_MCQ_1271","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1271","question":"Lampwick Candles is buying a delivery vehicle on hire purchase. The agreement requires a deposit of $900 followed by 30 monthly instalments of $310 each. What is the total cost of the vehicle under this hire purchase agreement?","options":{"A":"$9,300","B":"$1,210","C":"$10,200","D":"$9,890"},"correctOption":"C","correctAnswer":"$10,200","questionType":"MCQ","explanation":{"correct_reason":"The total hire purchase cost is the deposit plus every instalment, so $900 plus 30 payments of $310 equals $10,200 for Lampwick Candles.","distractor_reasons":{"A":"$9,300 counts only the 30 monthly instalments and leaves out the $900 deposit, so it understates the total cost that Lampwick Candles pays under the agreement.","B":"$1,210 adds just one instalment of $310 to the $900 deposit instead of all 30 instalments, so it is far below the true total for Lampwick Candles.","C":"The total hire purchase cost is the deposit plus every instalment, so $900 plus 30 payments of $310 equals $10,200 for Lampwick Candles.","D":"$9,890 includes only 29 instalments and omits the final payment of $310, but the agreement with Lampwick Candles requires all 30 monthly payments."}}},{"id":"P1_U5_MCQ_1272","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1272","question":"Gorsewood Joinery forecasts cash receipts of $63,700 and cash payments of $58,900 for the coming quarter. The business expects to start the quarter with a bank balance of $5,200. What is the forecast net cash flow for the quarter?","options":{"A":"$122,600","B":"$10,000","C":"$400","D":"$4,800"},"correctOption":"D","correctAnswer":"$4,800","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is total receipts minus total payments, so $63,700 less $58,900 gives a net inflow of $4,800 for Gorsewood Joinery this quarter.","distractor_reasons":{"A":"$122,600 adds receipts and payments together, but net cash flow requires the payments to be subtracted from the receipts, so this figure is far too high.","B":"$10,000 includes the $5,200 opening balance, so it is the forecast closing balance rather than the net cash flow generated during the quarter.","C":"$400 adds the payments to the opening balance and subtracts receipts, which reverses the correct treatment of the two cash flows.","D":"Net cash flow is total receipts minus total payments, so $63,700 less $58,900 gives a net inflow of $4,800 for Gorsewood Joinery this quarter."}}},{"id":"P1_U5_MCQ_1273","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1273","question":"Alderfen Meats made a profit for the year of $47,500 and paid dividends of $12,500 to its shareholders. What amount of profit was retained in the business for the year?","options":{"A":"$35,000","B":"$60,000","C":"$12,500","D":"$47,500"},"correctOption":"A","correctAnswer":"$35,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is the $47,500 earned minus the $12,500 paid out as dividends, leaving $35,000 kept in Alderfen Meats. That is the profit kept inside the business.","distractor_reasons":{"A":"Retained profit is the $47,500 earned minus the $12,500 paid out as dividends, leaving $35,000 kept in Alderfen Meats. That is the profit kept inside the business.","B":"$60,000 adds the dividends to profit, but dividends are paid out and therefore reduce the amount retained by Alderfen Meats.","C":"$12,500 is the dividend paid to shareholders, not the profit that Alderfen Meats kept inside the business for the year.","D":"$47,500 ignores the $12,500 of dividends, so it overstates the profit retained by Alderfen Meats. The retained profit for Alderfen Meats is $35,000."}}},{"id":"P1_U5_MCQ_1274","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1274","question":"Umberleigh Upholstery has non-current assets of $196,000, current assets of $64,000 and current liabilities of $38,000. The owner wants to know the total long-term finance invested in the business. What is the capital employed?","options":{"A":"$260,000","B":"$222,000","C":"$298,000","D":"$26,000"},"correctOption":"B","correctAnswer":"$222,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is non-current assets plus current assets minus current liabilities, so $196,000+$64,000-$38,000 gives $222,000 for Umberleigh Upholstery. That is the long-term finance invested in the business.","distractor_reasons":{"A":"$260,000 adds non-current and current assets but fails to deduct the $38,000 of current liabilities. The capital employed for Umberleigh Upholstery is $222,000.","B":"Capital employed is non-current assets plus current assets minus current liabilities, so $196,000+$64,000-$38,000 gives $222,000 for Umberleigh Upholstery. That is the long-term finance invested in the business.","C":"$298,000 adds current liabilities instead of deducting them, so the capital employed of Umberleigh Upholstery is overstated. The capital employed for Umberleigh Upholstery is $222,000.","D":"$26,000 is only the working capital and omits the $196,000 of non-current assets held by Umberleigh Upholstery. The capital employed for Umberleigh Upholstery is $222,000."}}},{"id":"P1_U5_MCQ_1275","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1275","question":"The gross profit margin of Penrose Print was 30.0% in 2024 and 32.0% in 2025. By how many percentage points did the gross profit margin change between the two years?","options":{"A":"24.4 percentage points","B":"30.0%","C":"2.0 percentage points","D":"32.0%"},"correctOption":"C","correctAnswer":"2.0 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The margin moved from 30.0% to 32.0%, a change of 2.0 percentage points for Penrose Print between 2024 and 2025.","distractor_reasons":{"A":"24.4 percentage points is the percentage growth in gross profit itself, not the change in the margin measured in percentage points.","B":"30.0% is the 2024 margin on its own, not the change in the margin between the two years. The change in the gross profit margin for Penrose Print is 2.0 percentage points.","C":"The margin moved from 30.0% to 32.0%, a change of 2.0 percentage points for Penrose Print between 2024 and 2025.","D":"32.0% is the 2025 margin on its own, not the change in the margin between the two years. The change in the gross profit margin for Penrose Print is 2.0 percentage points."}}},{"id":"P1_U5_MCQ_1276","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1276","question":"Marrowgate Motors leases a machine for 2 years. The annual lease payment is $26,000 and the annual maintenance contract costs a further $4,800. What is the total cost of leasing and maintaining the machine over the 2 years?","options":{"A":"$52,000","B":"$30,800","C":"$56,800","D":"$61,600"},"correctOption":"D","correctAnswer":"$61,600","questionType":"MCQ","explanation":{"correct_reason":"Each year costs $26,000 in lease payments plus $4,800 for maintenance, so the annual total of $30,800 multiplied by 2 years gives $61,600 for Marrowgate Motors.","distractor_reasons":{"A":"$52,000 covers the lease payments but omits the $4,800 annual maintenance charge, so it understates the total cost of running the machine for 2 years.","B":"$30,800 is the cost of a single year only, but Marrowgate Motors leases the machine for 2 years, so it ignores the remaining 1 years of payments.","C":"$56,800 adds the maintenance charge only once instead of for each of the 2 years, so it understates the total paid by Marrowgate Motors.","D":"Each year costs $26,000 in lease payments plus $4,800 for maintenance, so the annual total of $30,800 multiplied by 2 years gives $61,600 for Marrowgate Motors."}}},{"id":"P1_U5_MCQ_1277","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1277","question":"Honeystone Hotels forecasts cash sales of $38,400, receipts from credit customers of $42,700 and a bank loan receipt of $6,900 during the next month. What total cash inflow should appear in the cash flow forecast?","options":{"A":"$88,000","B":"$81,100","C":"$45,300","D":"$49,600"},"correctOption":"A","correctAnswer":"$88,000","questionType":"MCQ","explanation":{"correct_reason":"Total inflows are the sum of all money coming in, so $38,400 plus $42,700 plus $6,900 equals $88,000 for Honeystone Hotels.","distractor_reasons":{"A":"Total inflows are the sum of all money coming in, so $38,400 plus $42,700 plus $6,900 equals $88,000 for Honeystone Hotels.","B":"$81,100 adds the trading receipts but omits the $6,900 loan receipt, so it understates the total cash inflow for Honeystone Hotels.","C":"$45,300 leaves out the $42,700 received from credit customers, which is still cash coming into the business during the month.","D":"$49,600 omits the $38,400 of cash sales, so it does not capture all of the money flowing into Honeystone Hotels."}}},{"id":"P1_U5_MCQ_1278","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1278","question":"Birchwood Boats recorded gross profit of $84,000 and a profit for the year of $31,600, with no interest charges. What were the operating expenses for the year?","options":{"A":"$115,600","B":"$52,400","C":"$31,600","D":"$84,000"},"correctOption":"B","correctAnswer":"$52,400","questionType":"MCQ","explanation":{"correct_reason":"Operating expenses are the gap between gross profit and profit for the year, so $84,000-$31,600 gives $52,400 for Birchwood Boats.","distractor_reasons":{"A":"$115,600 adds the two figures together, which is not how the operating expenses of Birchwood Boats are found from gross profit and profit.","B":"Operating expenses are the gap between gross profit and profit for the year, so $84,000-$31,600 gives $52,400 for Birchwood Boats.","C":"$31,600 is the profit for the year, not the operating expenses that were deducted to reach it in the accounts of Birchwood Boats.","D":"$84,000 is the gross profit itself, so it cannot also be the operating expenses of Birchwood Boats. The operating expenses for Birchwood Boats is $52,400."}}},{"id":"P1_U5_MCQ_1279","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1279","question":"Velvet Fox Fashion reports total assets of $485,000 and total liabilities of $214,000 at the year end. The owner wants to see what the business is worth once every debt has been paid. What is the equity of the business?","options":{"A":"$699,000","B":"$214,000","C":"$271,000","D":"$485,000"},"correctOption":"C","correctAnswer":"$271,000","questionType":"MCQ","explanation":{"correct_reason":"Equity is total assets minus total liabilities, so $485,000 less $214,000 gives $271,000 for Velvet Fox Fashion. That is the owners' stake in the business.","distractor_reasons":{"A":"$699,000 adds liabilities to assets instead of deducting them, which overstates the owners' stake in Velvet Fox Fashion. The equity for Velvet Fox Fashion is $271,000.","B":"$214,000 is the total liabilities figure, not the equity that belongs to the owners of Velvet Fox Fashion. The equity for Velvet Fox Fashion is $271,000.","C":"Equity is total assets minus total liabilities, so $485,000 less $214,000 gives $271,000 for Velvet Fox Fashion. That is the owners' stake in the business.","D":"$485,000 is total assets before the $214,000 of liabilities is deducted, so it overstates equity. The equity for Velvet Fox Fashion is $271,000."}}},{"id":"P1_U5_MCQ_1280","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1280","question":"Quarrendon Quilts reports revenue of $275,000 and gross profit of $96,250 for the year. The owner is reviewing profitability. What is the gross profit margin? Give your answer to one decimal place.","options":{"A":"65.0%","B":"17.5%","C":"53.8%","D":"35.0%"},"correctOption":"D","correctAnswer":"35.0%","questionType":"MCQ","explanation":{"correct_reason":"The gross profit margin is gross profit divided by revenue, so $96,250/$275,000 x 100 gives 35.0% for Quarrendon Quilts. That is the share of sales left after cost of sales.","distractor_reasons":{"A":"65.0% is the cost of sales as a percentage of revenue, which is the complement of the gross profit margin for Quarrendon Quilts.","B":"17.5% is half the correct margin and does not come from dividing $96,250 by $275,000. The gross profit margin for Quarrendon Quilts is 35.0%.","C":"53.8% compares gross profit with cost of sales rather than with revenue, so it uses the wrong denominator for Quarrendon Quilts.","D":"The gross profit margin is gross profit divided by revenue, so $96,250/$275,000 x 100 gives 35.0% for Quarrendon Quilts. That is the share of sales left after cost of sales."}}},{"id":"P1_U5_MCQ_1281","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1281","question":"Nettlebed Farms borrows $96,000 from its bank for 5 years at a simple interest rate of 3.5% a year. The principal is repaid in full only at the end of the term, and interest is paid annually. What total interest will Nettlebed Farms pay over the whole 5-year period?","options":{"A":"$16,800","B":"$3,360","C":"$112,800","D":"$18,017.89"},"correctOption":"A","correctAnswer":"$16,800","questionType":"MCQ","explanation":{"correct_reason":"Simple interest is the principal multiplied by the rate and the number of years, so $96,000 x 3.5% x 5 equals $16,800 of total interest for Nettlebed Farms.","distractor_reasons":{"A":"Simple interest is the principal multiplied by the rate and the number of years, so $96,000 x 3.5% x 5 equals $16,800 of total interest for Nettlebed Farms.","B":"$3,360 is the interest for one year only at 3.5% on $96,000, but the loan runs for 5 years, so it understates the total interest Nettlebed Farms must pay.","C":"$112,800 adds the $96,000 principal to the $16,800 interest, which gives the total repayment rather than the interest charge that the question asks for.","D":"$18,017.89 treats the interest as compound and charges interest on unpaid interest, but the question states simple interest, so this figure overstates the true cost to Nettlebed Farms."}}},{"id":"P1_U5_MCQ_1282","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1282","question":"Ivybridge Print's cash flow forecast for June lists wages of $26,500, materials of $34,800, rent of $7,200 and a loan repayment of $4,000. What total cash outflow should the forecast show for June?","options":{"A":"$68,500","B":"$72,500","C":"$65,300","D":"$61,300"},"correctOption":"B","correctAnswer":"$72,500","questionType":"MCQ","explanation":{"correct_reason":"Total outflows add every payment together, so $26,500 plus $34,800 plus $7,200 plus $4,000 gives $72,500 for Ivybridge Print in June.","distractor_reasons":{"A":"$68,500 leaves out the $4,000 loan repayment, which is still cash leaving the business in June and must be included.","B":"Total outflows add every payment together, so $26,500 plus $34,800 plus $7,200 plus $4,000 gives $72,500 for Ivybridge Print in June.","C":"$65,300 omits the $7,200 rent payment, so it understates the total cash outflow for Ivybridge Print in June. The total cash outflow for Ivybridge Print is $72,500.","D":"$61,300 covers only wages and materials and ignores both the rent and the loan repayment that Ivybridge Print must make."}}},{"id":"P1_U5_MCQ_1283","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1283","question":"Cobblefield Clothing reports revenue of $360,000 for the year and cost of sales of $216,000. It has no other trading costs before gross profit. What is the gross profit for the year?","options":{"A":"$576,000","B":"$216,000","C":"$144,000","D":"$360,000"},"correctOption":"C","correctAnswer":"$144,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, so $360,000 less $216,000 gives $144,000 for Cobblefield Clothing. That is the profit left before operating expenses are paid.","distractor_reasons":{"A":"$576,000 adds cost of sales to revenue instead of subtracting it, which cannot be the gross profit of Cobblefield Clothing.","B":"$216,000 is only the cost of sales and ignores the $360,000 of revenue that Cobblefield Clothing earned during the year.","C":"Gross profit is revenue minus cost of sales, so $360,000 less $216,000 gives $144,000 for Cobblefield Clothing. That is the profit left before operating expenses are paid.","D":"$360,000 is the revenue before any cost of sales is deducted, so it overstates the gross profit of Cobblefield Clothing."}}},{"id":"P1_U5_MCQ_1284","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1284","question":"Wrenbury Watches has current assets of $90,000 and current liabilities of $60,000. It then uses $15,000 of cash to pay a supplier. What is the current ratio immediately after the payment? Give your answer to two decimal places.","options":{"A":"1.50 : 1","B":"2.00 : 1","C":"1.25 : 1","D":"1.67 : 1"},"correctOption":"D","correctAnswer":"1.67 : 1","questionType":"MCQ","explanation":{"correct_reason":"Paying the supplier reduces both figures by $15,000, so $75,000/$45,000 gives 1.67 : 1 for Wrenbury Watches. That is the ratio after the supplier has been paid.","distractor_reasons":{"A":"1.50 : 1 is the current ratio before the payment and ignores the equal reduction in cash and payables. The current ratio for Wrenbury Watches is 1.67 : 1.","B":"2.00 : 1 reduces only the liabilities and forgets that the $15,000 of cash has also left the business. The current ratio for Wrenbury Watches is 1.67 : 1.","C":"1.25 : 1 reduces only current assets and forgets that the payable to the supplier has been settled. The current ratio for Wrenbury Watches is 1.67 : 1.","D":"Paying the supplier reduces both figures by $15,000, so $75,000/$45,000 gives 1.67 : 1 for Wrenbury Watches. That is the ratio after the supplier has been paid."}}},{"id":"P1_U5_MCQ_1285","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1285","question":"Riddlesworth Rugs reports operating profit of $45,600 for the year and capital employed of $380,000 at the year end. The owner wants to judge how well the capital has been used. What is the return on capital employed? Give your answer to one decimal place.","options":{"A":"12.0%","B":"10.7%","C":"13.6%","D":"6.0%"},"correctOption":"A","correctAnswer":"12.0%","questionType":"MCQ","explanation":{"correct_reason":"ROCE is operating profit divided by capital employed, so $45,600/$380,000 x 100 gives 12.0% for Riddlesworth Rugs. That is the return earned on each dollar of capital employed.","distractor_reasons":{"A":"ROCE is operating profit divided by capital employed, so $45,600/$380,000 x 100 gives 12.0% for Riddlesworth Rugs. That is the return earned on each dollar of capital employed.","B":"10.7% adds operating profit to capital employed in the denominator, which is not the ROCE formula. The return on capital employed for Riddlesworth Rugs is 12.0%.","C":"13.6% deducts profit from capital employed before dividing, so the denominator is wrong. The return on capital employed for Riddlesworth Rugs is 12.0%.","D":"6.0% is half the correct return and cannot be obtained from $45,600 and $380,000. The return on capital employed for Riddlesworth Rugs is 12.0%."}}},{"id":"P1_U5_MCQ_1286","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1286","question":"Ormsby Locks arranges a bank overdraft of $24,000 to cover a seasonal shortage. The overdraft carries interest at 8% a year, and Ormsby Locks expects to use the full amount for 9 months. What interest will the business pay for this period?","options":{"A":"$1,920","B":"$1,440","C":"$17,280","D":"$25,440"},"correctOption":"B","correctAnswer":"$1,440","questionType":"MCQ","explanation":{"correct_reason":"The interest is $24,000 x 8% x 9/12, because the overdraft is used for 9 months of the year, giving $1,440 for Ormsby Locks.","distractor_reasons":{"A":"$1,920 charges a full year of interest at 8%, but Ormsby Locks only uses the overdraft for 9 months, so it overstates the interest cost.","B":"The interest is $24,000 x 8% x 9/12, because the overdraft is used for 9 months of the year, giving $1,440 for Ormsby Locks.","C":"$17,280 multiplies the annual rate by 9 without dividing by twelve, so it treats the 9-month period as 9 whole years of borrowing.","D":"$25,440 adds the $24,000 borrowed to the $1,440 interest, which gives the total repaid rather than the interest charged to Ormsby Locks."}}},{"id":"P1_U5_MCQ_1287","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1287","question":"Juniper Rise Deli expects to open July with a bank balance of $4,100. Forecast receipts for the month are $29,800 and forecast payments are $31,200. What closing bank balance should appear in the cash flow forecast for July?","options":{"A":"$65,100","B":"$-1,400","C":"$2,700","D":"$5,500"},"correctOption":"C","correctAnswer":"$2,700","questionType":"MCQ","explanation":{"correct_reason":"The closing balance is the $4,100 opening balance plus $29,800 of receipts minus $31,200 of payments, giving $2,700 for Juniper Rise Deli at the end of July.","distractor_reasons":{"A":"$65,100 adds the payments instead of subtracting them, so it cannot be the closing bank balance that Juniper Rise Deli will actually hold.","B":"$-1,400 is only the net cash flow for the month and leaves out the $4,100 that Juniper Rise Deli already holds at the start of July.","C":"The closing balance is the $4,100 opening balance plus $29,800 of receipts minus $31,200 of payments, giving $2,700 for Juniper Rise Deli at the end of July.","D":"$5,500 subtracts the net inflow from the opening balance instead of adding it, which moves the balance in the wrong direction."}}},{"id":"P1_U5_MCQ_1288","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1288","question":"Dovetail Desks reports gross profit of $69,000 for the year. Operating expenses were $41,200 and interest payable on its bank loan was $3,800. What was the profit for the year?","options":{"A":"$27,800","B":"$31,600","C":"$114,000","D":"$24,000"},"correctOption":"D","correctAnswer":"$24,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year deducts both operating expenses and interest, so $69,000-$41,200-$3,800 gives $24,000 for Dovetail Desks. That is the profit left after expenses and interest.","distractor_reasons":{"A":"$27,800 deducts operating expenses but forgets the $3,800 of interest, so it overstates the profit of Dovetail Desks. The profit for the year for Dovetail Desks is $24,000.","B":"$31,600 adds interest back instead of deducting it, which treats a cost as income in the accounts of Dovetail Desks.","C":"$114,000 adds both costs to gross profit, which is the opposite of the correct treatment. The profit for the year for Dovetail Desks is $24,000.","D":"Profit for the year deducts both operating expenses and interest, so $69,000-$41,200-$3,800 gives $24,000 for Dovetail Desks. That is the profit left after expenses and interest."}}},{"id":"P1_U5_MCQ_1289","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1289","question":"Yarmouth Yachts reports capital employed of $720,000 and equity of $480,000 at the year end. The owner is checking how the rest of the business is financed. What are the non-current liabilities of the business?","options":{"A":"$240,000","B":"$1,200,000","C":"$480,000","D":"$720,000"},"correctOption":"A","correctAnswer":"$240,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is equity plus non-current liabilities, so $720,000-$480,000 gives $240,000 of non-current liabilities for Yarmouth Yachts. That is the long-term debt owed by the business.","distractor_reasons":{"A":"Capital employed is equity plus non-current liabilities, so $720,000-$480,000 gives $240,000 of non-current liabilities for Yarmouth Yachts. That is the long-term debt owed by the business.","B":"$1,200,000 adds equity to capital employed instead of deducting it, which overstates the liabilities of Yarmouth Yachts. The non-current liabilities for Yarmouth Yachts is $240,000.","C":"$480,000 is the equity belonging to the owners, not the non-current liabilities that Yarmouth Yachts owes to lenders. The non-current liabilities for Yarmouth Yachts is $240,000.","D":"$720,000 is the total capital employed, which includes the equity as well as the non-current liabilities. The non-current liabilities for Yarmouth Yachts is $240,000."}}},{"id":"P1_U5_MCQ_1290","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1290","question":"Stanmore Studios reports revenue of $420,000 and operating profit of $63,000 for the year. The owner is checking how much profit is kept from each dollar of sales. What is the profit margin? Give your answer to one decimal place.","options":{"A":"30.0%","B":"15.0%","C":"50.0%","D":"7.5%"},"correctOption":"B","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"The profit margin is operating profit divided by revenue, so $63,000/$420,000 x 100 gives 15.0% for Stanmore Studios. That is the share of sales kept as operating profit.","distractor_reasons":{"A":"30.0% is the gross profit margin, which uses gross profit rather than the $63,000 of operating profit earned by Stanmore Studios.","B":"The profit margin is operating profit divided by revenue, so $63,000/$420,000 x 100 gives 15.0% for Stanmore Studios. That is the share of sales kept as operating profit.","C":"50.0% divides operating profit by gross profit instead of by revenue, so it is not the profit margin of Stanmore Studios.","D":"7.5% is half the correct figure and has no basis in the $63,000 profit or the $420,000 revenue. The profit margin for Stanmore Studios is 15.0%."}}},{"id":"P1_U5_MCQ_1291","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1291","question":"Pennant Hill Bakery receives an invoice for $45,000 from a supplier that offers a cash discount of 4% for payment within ten days. Pennant Hill Bakery decides to pay within the discount period. How much money will the business save by paying early?","options":{"A":"$43,200","B":"$3,600","C":"$1,800","D":"$180"},"correctOption":"C","correctAnswer":"$1,800","questionType":"MCQ","explanation":{"correct_reason":"The saving is 4% of the $45,000 invoice, and $45,000 x 4% equals $1,800, which is the cash discount Pennant Hill Bakery gains by paying within ten days.","distractor_reasons":{"A":"$43,200 is the amount actually paid after deducting the discount, not the saving itself, so it answers a different question from the one asked.","B":"$3,600 applies the 4% discount twice to the same invoice, which no supplier would allow, so it doubles the true saving for Pennant Hill Bakery.","C":"The saving is 4% of the $45,000 invoice, and $45,000 x 4% equals $1,800, which is the cash discount Pennant Hill Bakery gains by paying within ten days.","D":"$180 moves the decimal point one place too far when taking 4% of $45,000, so it is ten times smaller than the correct saving."}}},{"id":"P1_U5_MCQ_1292","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1292","question":"Kestrel Down Eggs forecasts a closing bank balance of $11,200 for September after receipts of $84,600 and payments of $79,300. What opening bank balance must the forecast show for the start of September?","options":{"A":"$16,500","B":"$5,300","C":"$175,100","D":"$5,900"},"correctOption":"D","correctAnswer":"$5,900","questionType":"MCQ","explanation":{"correct_reason":"The opening balance is the $11,200 closing figure minus the net inflow of $5,300, which gives $5,900 at the start of September for Kestrel Down Eggs.","distractor_reasons":{"A":"$16,500 adds the net inflow to the closing balance instead of subtracting it, so it moves the balance the wrong way.","B":"$5,300 is the net cash flow for September, not the balance that Kestrel Down Eggs held at the start of the month.","C":"$175,100 adds both receipts and payments to the closing balance, but payments reduce the balance and should be subtracted. The opening balance for Kestrel Down Eggs is $5,900.","D":"The opening balance is the $11,200 closing figure minus the net inflow of $5,300, which gives $5,900 at the start of September for Kestrel Down Eggs."}}},{"id":"P1_U5_MCQ_1293","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1293","question":"Eastmoor Electrical began the year with inventory of $17,500, bought goods costing $97,000 and ended with inventory of $20,500. Revenue for the year was $140,000. What was the gross profit?","options":{"A":"$46,000","B":"$25,500","C":"$63,500","D":"$5,000"},"correctOption":"A","correctAnswer":"$46,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is $17,500+$97,000-$20,500 = $94,000, so revenue of $140,000 less $94,000 gives gross profit of $46,000 for Eastmoor Electrical.","distractor_reasons":{"A":"Cost of sales is $17,500+$97,000-$20,500 = $94,000, so revenue of $140,000 less $94,000 gives gross profit of $46,000 for Eastmoor Electrical.","B":"$25,500 uses opening inventory plus purchases as cost of sales and ignores the $20,500 closing inventory held by Eastmoor Electrical.","C":"$63,500 omits the $17,500 opening inventory from cost of sales, so the gross profit of Eastmoor Electrical is overstated. The gross profit for Eastmoor Electrical is $46,000.","D":"$5,000 adds closing inventory to cost of sales instead of subtracting it, so the gross profit is far too low."}}},{"id":"P1_U5_MCQ_1294","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1294","question":"Zonal Systems reports non-current assets of $340,000 and current assets of $126,000 at its year end. It has no other assets. What is the total of its assets?","options":{"A":"$214,000","B":"$466,000","C":"$126,000","D":"$592,000"},"correctOption":"B","correctAnswer":"$466,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are non-current assets plus current assets, so $340,000+$126,000 gives $466,000 for Zonal Systems. That is the total asset base of the business.","distractor_reasons":{"A":"$214,000 subtracts current assets from non-current assets, but both are assets and must be added together. The total assets for Zonal Systems is $466,000.","B":"Total assets are non-current assets plus current assets, so $340,000+$126,000 gives $466,000 for Zonal Systems. That is the total asset base of the business.","C":"$126,000 is only the current assets and ignores the $340,000 of non-current assets held by Zonal Systems. The total assets for Zonal Systems is $466,000.","D":"$592,000 counts the current assets twice, which overstates the total assets of Zonal Systems. The total assets for Zonal Systems is $466,000."}}},{"id":"P1_U5_MCQ_1295","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1295","question":"Turlock Transport reports current assets of $204,000, including inventory of $84,000, and current liabilities of $120,000. What is the current ratio? Give your answer to two decimal places.","options":{"A":"1.00 : 1","B":"0.59 : 1","C":"1.70 : 1","D":"2.40 : 1"},"correctOption":"C","correctAnswer":"1.70 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets divided by current liabilities, so $204,000/$120,000 gives 1.70 : 1 for Turlock Transport. That means the business holds this much in current assets for each dollar of current liabilities.","distractor_reasons":{"A":"1.00 : 1 is the acid test ratio, which removes the $84,000 inventory before dividing. The current ratio for Turlock Transport is 1.70 : 1.","B":"0.59 : 1 reverses the calculation by dividing current liabilities by current assets. The current ratio for Turlock Transport is 1.70 : 1.","C":"The current ratio is current assets divided by current liabilities, so $204,000/$120,000 gives 1.70 : 1 for Turlock Transport. That means the business holds this much in current assets for each dollar of current liabilities.","D":"2.40 : 1 adds inventory to current assets before dividing by current liabilities, which double counts the stock. The current ratio for Turlock Transport is 1.70 : 1."}}},{"id":"P1_U5_MCQ_1296","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1296","question":"Quilters Rest began the year with retained profit of $15,000. The business made a profit for the year of $26,000 and paid dividends of $4,000 to its owners. What retained profit is carried forward at the end of the year?","options":{"A":"$41,000","B":"$22,000","C":"$45,000","D":"$37,000"},"correctOption":"D","correctAnswer":"$37,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit carried forward is the opening $15,000 plus the $26,000 earned, less the $4,000 paid as dividends, giving $37,000 for Quilters Rest.","distractor_reasons":{"A":"$41,000 adds the profit to the opening balance but fails to deduct the $4,000 of dividends, so it overstates the retained profit of Quilters Rest.","B":"$22,000 is only the profit kept after dividends and ignores the $15,000 of retained profit that Quilters Rest already held.","C":"$45,000 adds the dividends instead of subtracting them, which counts money twice even though it has left the business. The retained profit for Quilters Rest is $37,000.","D":"Retained profit carried forward is the opening $15,000 plus the $26,000 earned, less the $4,000 paid as dividends, giving $37,000 for Quilters Rest."}}},{"id":"P1_U5_MCQ_1297","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1297","question":"Larkspur Florists started the month with a bank balance of $3,600 and received $41,500 from customers. The forecast closing balance is $8,900. What total cash payments must the forecast show for the month?","options":{"A":"$36,200","B":"$54,000","C":"$46,800","D":"$29,000"},"correctOption":"A","correctAnswer":"$36,200","questionType":"MCQ","explanation":{"correct_reason":"Payments equal the $3,600 opening balance plus $41,500 received minus the $8,900 closing balance, which gives $36,200 of payments for Larkspur Florists.","distractor_reasons":{"A":"Payments equal the $3,600 opening balance plus $41,500 received minus the $8,900 closing balance, which gives $36,200 of payments for Larkspur Florists.","B":"$54,000 adds the closing balance instead of subtracting it, so it overstates the payments by twice the closing figure. The total payments for Larkspur Florists is $36,200.","C":"$46,800 rearranges the figures incorrectly and produces a total that does not reconcile the opening and closing balances of Larkspur Florists.","D":"$29,000 subtracts both the opening and closing balances from receipts, which is not how a cash flow forecast is balanced."}}},{"id":"P1_U5_MCQ_1298","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1298","question":"Fernhill Pharmacy reports revenue of $286,000 for the year and cost of sales of $171,600. Operating expenses for the year were $63,800. What is the gross profit for the year?","options":{"A":"$50,600","B":"$114,400","C":"$457,600","D":"$222,200"},"correctOption":"B","correctAnswer":"$114,400","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, so $286,000 less $171,600 gives $114,400 for Fernhill Pharmacy, before operating expenses are deducted.","distractor_reasons":{"A":"$50,600 also deducts the $63,800 operating expenses, which gives the profit for the year rather than the gross profit of Fernhill Pharmacy.","B":"Gross profit is revenue minus cost of sales, so $286,000 less $171,600 gives $114,400 for Fernhill Pharmacy, before operating expenses are deducted.","C":"$457,600 adds cost of sales to revenue instead of subtracting it, which cannot produce the gross profit earned by Fernhill Pharmacy.","D":"$222,200 deducts operating expenses from revenue but ignores cost of sales entirely, so the two amounts have been mixed up."}}},{"id":"P1_U5_MCQ_1299","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1299","question":"Amberley Apiaries reports current assets of $88,000 and current liabilities of $55,000 at its year end. The owner wants to know how much short-term finance is available to run the business. What is the working capital?","options":{"A":"$143,000","B":"$55,000","C":"$33,000","D":"$88,000"},"correctOption":"C","correctAnswer":"$33,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so $88,000 less $55,000 gives $33,000 for Amberley Apiaries. That is the short-term finance available to the business.","distractor_reasons":{"A":"$143,000 adds current liabilities to current assets, but working capital requires the $55,000 to be deducted, so it overstates the figure.","B":"$55,000 is the current liabilities figure on its own, not the working capital left after deducting it from current assets.","C":"Working capital is current assets minus current liabilities, so $88,000 less $55,000 gives $33,000 for Amberley Apiaries. That is the short-term finance available to the business.","D":"$88,000 is the current assets total before the $55,000 of current liabilities is deducted, so it overstates working capital. The working capital for Amberley Apiaries is $33,000."}}},{"id":"P1_U5_MCQ_1300","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1300","question":"Ulverston Umbrellas reports revenue of $252,000 and gross profit of $88,200 for the year. The owner is reviewing profitability. What is the gross profit margin? Give your answer to one decimal place.","options":{"A":"65.0%","B":"17.5%","C":"53.8%","D":"35.0%"},"correctOption":"D","correctAnswer":"35.0%","questionType":"MCQ","explanation":{"correct_reason":"The gross profit margin is gross profit divided by revenue, so $88,200/$252,000 x 100 gives 35.0% for Ulverston Umbrellas. That is the share of sales left after cost of sales.","distractor_reasons":{"A":"65.0% is the cost of sales as a percentage of revenue, which is the complement of the gross profit margin for Ulverston Umbrellas.","B":"17.5% is half the correct margin and does not come from dividing $88,200 by $252,000. The gross profit margin for Ulverston Umbrellas is 35.0%.","C":"53.8% compares gross profit with cost of sales rather than with revenue, so it uses the wrong denominator for Ulverston Umbrellas.","D":"The gross profit margin is gross profit divided by revenue, so $88,200/$252,000 x 100 gives 35.0% for Ulverston Umbrellas. That is the share of sales left after cost of sales."}}},{"id":"P1_U5_MCQ_1301","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1301","question":"Harlow Printworks needs $60,000 for a new press. It already holds $22,000 of retained profit and will borrow the remainder through a five-year bank loan charged at 6% interest a year. What annual interest will the business pay on the money it borrows?","options":{"A":"$1,320","B":"$3,600","C":"$2,280","D":"$4,560"},"correctOption":"C","correctAnswer":"$2,280","questionType":"MCQ","explanation":{"correct_reason":"Only $38,000 is borrowed, because $60,000 less the $22,000 of retained profit leaves $38,000, and 6% of $38,000 is $2,280.","distractor_reasons":{"A":"$1,320 would be 6% of the $22,000 retained profit rather than of the $38,000 actually borrowed.","B":"$3,600 is 6% of the full $60,000 cost, but the retained profit reduces the sum that must be borrowed.","C":"Only $38,000 is borrowed, because $60,000 less the $22,000 of retained profit leaves $38,000, and 6% of $38,000 is $2,280.","D":"$4,560 doubles the correct interest charge and does not match 6% of the $38,000 borrowed."}}},{"id":"P1_U5_MCQ_1302","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1302","question":"Mistlebrook Bakery forecasts cash receipts of $96,000 and cash payments of $88,500 in May. Its opening bank balance on 1 May is $14,000. What is the forecast closing bank balance at the end of May?","options":{"A":"$21,500","B":"$7,500","C":"$14,000","D":"$184,500"},"correctOption":"A","correctAnswer":"$21,500","questionType":"MCQ","explanation":{"correct_reason":"The closing balance is the $14,000 opening balance plus the $7,500 net inflow, which gives $21,500 at the end of May.","distractor_reasons":{"A":"The closing balance is the $14,000 opening balance plus the $7,500 net inflow, which gives $21,500 at the end of May.","B":"$7,500 is only the net cash flow for May, so it ignores the $14,000 already in the bank at the start of the month.","C":"$14,000 is the opening balance and takes no account of the receipts and payments during May.","D":"$184,500 wrongly adds receipts to payments and then adds the opening balance instead of subtracting payments."}}},{"id":"P1_U5_MCQ_1303","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1303","question":"Brightwater Brewing reports revenue of $420,000, cost of sales of $260,000 and operating expenses of $95,000 for the year. What is the profit for the year?","options":{"A":"$160,000","B":"$95,000","C":"$420,000","D":"$65,000"},"correctOption":"D","correctAnswer":"$65,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is $420,000 revenue less $260,000 cost of sales less $95,000 operating expenses, which equals $65,000.","distractor_reasons":{"A":"$160,000 is the gross profit after deducting cost of sales only, so it ignores the $95,000 of operating expenses.","B":"$95,000 is the operating expenses figure and is not the profit earned by the business.","C":"$420,000 is total revenue, before any costs have been deducted.","D":"Profit for the year is $420,000 revenue less $260,000 cost of sales less $95,000 operating expenses, which equals $65,000."}}},{"id":"P1_U5_MCQ_1304","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1304","question":"Ravensworth Retail has current assets of $120,000 and current liabilities of $75,000 at the year end. What is the working capital of the business at 31 December?","options":{"A":"$195,000","B":"$45,000","C":"$120,000","D":"$75,000"},"correctOption":"B","correctAnswer":"$45,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so $120,000 less $75,000 gives $45,000.","distractor_reasons":{"A":"$195,000 wrongly adds current assets and current liabilities together instead of subtracting one from the other.","B":"Working capital is current assets minus current liabilities, so $120,000 less $75,000 gives $45,000.","C":"$120,000 is the total of current assets and has not had the current liabilities deducted.","D":"$75,000 is the current liabilities figure on its own and is not working capital."}}},{"id":"P1_U5_MCQ_1305","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1305","question":"Nettlebed Nutrition reports operating profit of $60,000 and capital employed of $400,000 for the year. What is its return on capital employed for the year?","options":{"A":"15%","B":"6.7%","C":"24%","D":"60%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, so $60,000 divided by $400,000 gives 15%.","distractor_reasons":{"A":"Return on capital employed is operating profit divided by capital employed, so $60,000 divided by $400,000 gives 15%.","B":"6.7% reverses the calculation by dividing $400,000 of capital employed by $60,000 of operating profit.","C":"24% comes from relating the $60,000 profit to about $250,000 rather than to the $400,000 employed.","D":"60% treats the $60,000 profit as a percentage of $100,000 rather than of capital employed."}}},{"id":"P1_U5_MCQ_1306","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1306","question":"Denby Kitchens is a partnership that needs $150,000 to open a second showroom. The two owners want to share the financial risk and bring in extra expertise, while keeping the business unincorporated. Which source of finance best fits their aims?","options":{"A":"A bank overdraft renewed each month","B":"Retained profit from the current year","C":"A new partner admitted to the partnership","D":"Extended trade credit from tile suppliers"},"correctOption":"C","correctAnswer":"A new partner admitted to the partnership","questionType":"MCQ","explanation":{"correct_reason":"Admitting a new partner brings in $150,000, spreads the financial risk between three owners and adds expertise, while the partnership stays unincorporated.","distractor_reasons":{"A":"An overdraft is short-term debt that must be renewed and repaid, and it brings no extra expertise or shared ownership.","B":"The partnership's retained profit is unlikely to reach $150,000 and using it would not bring in a new owner's expertise.","C":"Admitting a new partner brings in $150,000, spreads the financial risk between three owners and adds expertise, while the partnership stays unincorporated.","D":"Extended trade credit only delays payment for tiles and raises no $150,000, nor does it add a partner."}}},{"id":"P1_U5_MCQ_1307","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1307","question":"Cranbourne Couriers starts June with $9,200 in the bank. The forecast for the month shows a net cash outflow of $3,700. What is the forecast closing bank balance at the end of June?","options":{"A":"$3,700","B":"$5,500","C":"$12,900","D":"$13,000"},"correctOption":"B","correctAnswer":"$5,500","questionType":"MCQ","explanation":{"correct_reason":"A net outflow of $3,700 reduces the $9,200 opening balance to a closing balance of $5,500 at the end of June.","distractor_reasons":{"A":"$3,700 is the net cash outflow itself, not the balance remaining in the bank after it is deducted.","B":"A net outflow of $3,700 reduces the $9,200 opening balance to a closing balance of $5,500 at the end of June.","C":"$12,900 wrongly adds the $3,700 outflow to the opening balance instead of subtracting it.","D":"$13,000 does not follow from $9,200 less $3,700 and appears to be a rounding error."}}},{"id":"P1_U5_MCQ_1308","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1308","question":"Hollowbrook Beds has revenue of $210,000 and a gross profit of $84,000 for the year. What is its gross profit margin for the financial year just ended?","options":{"A":"25%","B":"60%","C":"84%","D":"40%"},"correctOption":"D","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"The gross profit margin is gross profit divided by revenue, so $84,000 divided by $210,000 gives 40%.","distractor_reasons":{"A":"25% does not come from $84,000 and $210,000 and would need a gross profit of about $52,500.","B":"60% is the cost of sales percentage, because cost of sales is $126,000 of the $210,000 revenue.","C":"84% repeats the gross profit figure as a percentage without dividing it by the $210,000 revenue.","D":"The gross profit margin is gross profit divided by revenue, so $84,000 divided by $210,000 gives 40%."}}},{"id":"P1_U5_MCQ_1309","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1309","question":"Sedgefield Saddlery holds inventory of $24,000, trade receivables of $18,000 and cash of $6,000. Its current liabilities are $32,000. What is its working capital at the end of the year?","options":{"A":"$16,000","B":"$24,000","C":"$32,000","D":"$48,000"},"correctOption":"A","correctAnswer":"$16,000","questionType":"MCQ","explanation":{"correct_reason":"Current assets total $24,000 plus $18,000 plus $6,000, which is $48,000, and deducting $32,000 of current liabilities leaves working capital of $16,000.","distractor_reasons":{"A":"Current assets total $24,000 plus $18,000 plus $6,000, which is $48,000, and deducting $32,000 of current liabilities leaves working capital of $16,000.","B":"$24,000 is only the inventory figure and ignores the receivables, cash and current liabilities.","C":"$32,000 is the current liabilities figure and is not the working capital.","D":"$48,000 is total current assets before the $32,000 of current liabilities is deducted."}}},{"id":"P1_U5_MCQ_1310","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1310","question":"Overton Outdoors has revenue of $480,000 and a gross profit of $120,000 for the year. What is its gross profit margin for the financial year just ended?","options":{"A":"12.5%","B":"25%","C":"40%","D":"75%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit divided by revenue, so $120,000 divided by $480,000 gives 25%.","distractor_reasons":{"A":"12.5% would need a gross profit of $60,000 on the $480,000 of revenue.","B":"Gross profit margin is gross profit divided by revenue, so $120,000 divided by $480,000 gives 25%.","C":"40% is the cost of sales percentage, since cost of sales is $360,000 of the $480,000 revenue.","D":"75% is the cost of sales share of revenue and is not the gross profit margin."}}},{"id":"P1_U5_MCQ_1311","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1311","question":"Sparrowdale Dairy receives an invoice for $45,000 from a feed supplier. The supplier offers a 2% discount if the invoice is settled within ten days instead of the usual thirty days. How much cash will the dairy save by paying early?","options":{"A":"$450","B":"$900","C":"$1,800","D":"$4,500"},"correctOption":"B","correctAnswer":"$900","questionType":"MCQ","explanation":{"correct_reason":"A 2% discount on the $45,000 invoice is $900, which is the cash the dairy saves by paying within ten days.","distractor_reasons":{"A":"$450 would be a 1% discount on the $45,000 invoice, not the 2% offered by the supplier.","B":"A 2% discount on the $45,000 invoice is $900, which is the cash the dairy saves by paying within ten days.","C":"$1,800 would be a 4% discount on the invoice and is double the rate offered.","D":"$4,500 is a 10% discount on the invoice, far above the 2% offered by the supplier."}}},{"id":"P1_U5_MCQ_1312","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1312","question":"Fallowfield Florists forecasts an opening balance of $6,000 and a closing balance of $5,500 for April. Cash receipts for the month are expected to be $42,000. What total cash payments are forecast for April?","options":{"A":"$36,500","B":"$41,500","C":"$48,000","D":"$42,500"},"correctOption":"D","correctAnswer":"$42,500","questionType":"MCQ","explanation":{"correct_reason":"Payments must equal the $42,000 of receipts plus the $6,000 opening balance less the $5,500 closing balance, which gives $42,500.","distractor_reasons":{"A":"$36,500 subtracts both the opening and closing balances from receipts, which double counts the fall in cash.","B":"$41,500 ignores the $500 fall in the bank balance between opening and closing.","C":"$48,000 adds the opening balance to receipts instead of allowing for the closing balance.","D":"Payments must equal the $42,000 of receipts plus the $6,000 opening balance less the $5,500 closing balance, which gives $42,500."}}},{"id":"P1_U5_MCQ_1313","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1313","question":"Marchmont Mowers has revenue of $150,000 and a gross profit margin of 30%. Its operating expenses are $28,000 for the year. What is the profit for the year?","options":{"A":"$17,000","B":"$45,000","C":"$28,000","D":"$122,000"},"correctOption":"A","correctAnswer":"$17,000","questionType":"MCQ","explanation":{"correct_reason":"A 30% gross profit margin on $150,000 revenue gives $45,000 gross profit, and deducting $28,000 of expenses leaves $17,000 profit.","distractor_reasons":{"A":"A 30% gross profit margin on $150,000 revenue gives $45,000 gross profit, and deducting $28,000 of expenses leaves $17,000 profit.","B":"$45,000 is the gross profit before the $28,000 of operating expenses is deducted.","C":"$28,000 is the operating expenses figure and is not a profit figure.","D":"$122,000 subtracts only the $28,000 expenses from revenue and ignores the cost of sales."}}},{"id":"P1_U5_MCQ_1314","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1314","question":"Tideswell Tiles reports total assets of $480,000 and total liabilities of $190,000 at the year end. What are the net assets of the business at the year end?","options":{"A":"$190,000","B":"$670,000","C":"$290,000","D":"$480,000"},"correctOption":"C","correctAnswer":"$290,000","questionType":"MCQ","explanation":{"correct_reason":"Net assets equal total assets minus total liabilities, so $480,000 less $190,000 gives $290,000.","distractor_reasons":{"A":"$190,000 is the total liabilities figure and is not the net assets of the business.","B":"$670,000 wrongly adds total assets and total liabilities together instead of subtracting them.","C":"Net assets equal total assets minus total liabilities, so $480,000 less $190,000 gives $290,000.","D":"$480,000 is total assets before any liabilities are deducted."}}},{"id":"P1_U5_MCQ_1315","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1315","question":"Papplewick Plastics has revenue of $300,000 and an operating profit of $45,000 for the year. What is its profit margin for the financial year just ended?","options":{"A":"6.7%","B":"15%","C":"30%","D":"45%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is operating profit divided by revenue, so $45,000 divided by $300,000 gives 15%.","distractor_reasons":{"A":"6.7% reverses the calculation by dividing the $300,000 of revenue by the $45,000 of operating profit.","B":"Profit margin is operating profit divided by revenue, so $45,000 divided by $300,000 gives 15%.","C":"30% is the share of revenue taken by cost of sales, which is not a profit margin.","D":"45% repeats the operating profit as a percentage of $100,000 rather than of the $300,000 revenue."}}},{"id":"P1_U5_MCQ_1316","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1316","question":"Quantock Optics wants $35,000 to upgrade its lens-cutting equipment. The owner prefers finance that involves no interest charges, no repayments and no new owners joining the business. Which source of finance meets all three conditions?","options":{"A":"Retained profit kept in the business","B":"A three-year bank loan","C":"An increased bank overdraft","D":"A share issue to a private investor"},"correctOption":"A","correctAnswer":"Retained profit kept in the business","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is internal finance, so the $35,000 upgrade carries no interest, needs no repayment and brings in no new shareholder.","distractor_reasons":{"A":"Retained profit is internal finance, so the $35,000 upgrade carries no interest, needs no repayment and brings in no new shareholder.","B":"A three-year bank loan charges interest and must be repaid, which breaks the condition of no interest and no repayments.","C":"An increased overdraft is borrowed money charged at variable interest and repayable on demand, so it fails the conditions.","D":"A share issue brings in an outside owner, which the owner has explicitly ruled out."}}},{"id":"P1_U5_MCQ_1317","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1317","question":"Netherby Motors prepares a six-month cash flow forecast before buying a second workshop. The forecast shows a deficit in February and a surplus from April onwards. What is the main benefit of this forecast to the owner?","options":{"A":"It shows the exact profit for each month","B":"It guarantees the bank will lend the money","C":"It removes the risk of bad debts","D":"It identifies the month when extra finance is needed"},"correctOption":"D","correctAnswer":"It identifies the month when extra finance is needed","questionType":"MCQ","explanation":{"correct_reason":"The forecast shows a February deficit and a later surplus, so it tells the owner when to arrange finance and when the surplus can repay it.","distractor_reasons":{"A":"A cash flow forecast records receipts and payments, not the profit earned in each month.","B":"A forecast may support a loan application but cannot guarantee that a bank will lend.","C":"Bad debts depend on customers' ability to pay and are not removed by forecasting cash.","D":"The forecast shows a February deficit and a later surplus, so it tells the owner when to arrange finance and when the surplus can repay it."}}},{"id":"P1_U5_MCQ_1318","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1318","question":"Quarryfield Stone reports revenue of $240,000 and a profit for the year of $36,000. What is its profit margin, to the nearest whole percentage for the year?","options":{"A":"6.7%","B":"24%","C":"15%","D":"36%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit divided by revenue, so $36,000 divided by $240,000 gives 15%.","distractor_reasons":{"A":"6.7% would need a profit of about $16,000 on the $240,000 of revenue.","B":"24% would need a profit of $57,600 on the $240,000 of revenue.","C":"Profit margin is profit divided by revenue, so $36,000 divided by $240,000 gives 15%.","D":"36% repeats the $36,000 profit figure as a percentage rather than dividing it by revenue."}}},{"id":"P1_U5_MCQ_1319","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1319","question":"Uppermill Umbrellas has share capital of $200,000, retained earnings of $85,000 and non-current liabilities of $60,000. What is its capital employed at the year end?","options":{"A":"$145,000","B":"$345,000","C":"$260,000","D":"$285,000"},"correctOption":"B","correctAnswer":"$345,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is equity plus non-current liabilities, so $200,000 plus $85,000 plus $60,000 gives $345,000.","distractor_reasons":{"A":"$145,000 adds only part of the equity to the non-current liabilities and leaves out the share capital.","B":"Capital employed is equity plus non-current liabilities, so $200,000 plus $85,000 plus $60,000 gives $345,000.","C":"$260,000 adds the share capital to the non-current liabilities but omits the retained earnings.","D":"$285,000 is the equity alone and leaves out the $60,000 of non-current liabilities."}}},{"id":"P1_U5_MCQ_1320","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1320","question":"Quendon Quilts has current assets of $90,000, including inventory of $36,000, and current liabilities of $45,000. What is its acid test ratio at the year end?","options":{"A":"1.20","B":"0.80","C":"1.50","D":"2.00"},"correctOption":"A","correctAnswer":"1.20","questionType":"MCQ","explanation":{"correct_reason":"The acid test removes the $36,000 of inventory from $90,000 of current assets, so $54,000 divided by $45,000 gives 1.20.","distractor_reasons":{"A":"The acid test removes the $36,000 of inventory from $90,000 of current assets, so $54,000 divided by $45,000 gives 1.20.","B":"0.80 would need liquid assets of $36,000, which equals the inventory rather than current assets less inventory.","C":"1.50 would need liquid assets of $67,500 rather than the $54,000 calculated.","D":"2.00 is the current ratio, using all $90,000 of current assets without removing inventory."}}},{"id":"P1_U5_MCQ_1321","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1321","question":"Wexley Marine borrows $80,000 for one year at a fixed interest rate of 7.5%. The loan is repaid in full at the end of the year. What is the total interest charge for the twelve months?","options":{"A":"$600","B":"$5,600","C":"$60,000","D":"$6,000"},"correctOption":"D","correctAnswer":"$6,000","questionType":"MCQ","explanation":{"correct_reason":"Interest is the $80,000 loan multiplied by the 7.5% annual rate, which gives $6,000 for the twelve months.","distractor_reasons":{"A":"$600 would be an interest rate of 0.75%, one tenth of the rate actually charged.","B":"$5,600 does not follow from 7.5% of $80,000 and seems to subtract the rate from the loan.","C":"$60,000 treats the 7.5% as $75 per $100 rather than $7.50 per $100.","D":"Interest is the $80,000 loan multiplied by the 7.5% annual rate, which gives $6,000 for the twelve months."}}},{"id":"P1_U5_MCQ_1322","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1322","question":"Ashcombe Studios forecasts a closing bank balance of minus $4,000 at the end of March. What does this figure indicate to the owner of the business?","options":{"A":"The business made a loss of $4,000 in March","B":"The business has $4,000 of retained profit","C":"The business will need $4,000 of additional cash or credit","D":"The business has overestimated its cash receipts"},"correctOption":"C","correctAnswer":"The business will need $4,000 of additional cash or credit","questionType":"MCQ","explanation":{"correct_reason":"A closing balance of minus $4,000 means the bank account would be overdrawn, so the owner must arrange at least $4,000 of extra cash or credit.","distractor_reasons":{"A":"The figure is a bank balance, not a profit or loss, so it does not show a $4,000 loss for March.","B":"A negative bank balance is an overdraft, not retained profit held by the business.","C":"A closing balance of minus $4,000 means the bank account would be overdrawn, so the owner must arrange at least $4,000 of extra cash or credit.","D":"The forecast may be accurate, so a negative balance does not prove that receipts were overestimated."}}},{"id":"P1_U5_MCQ_1323","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1323","question":"Silverdale Signage has revenue of $100,000, cost of sales of $55,000 and operating expenses of $25,000 for the year. What is its profit margin for the financial year just ended?","options":{"A":"20%","B":"25%","C":"45%","D":"55%"},"correctOption":"A","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $100,000 less $55,000, which is $45,000, and after $25,000 of expenses profit is $20,000, so the margin is 20%.","distractor_reasons":{"A":"Gross profit is $100,000 less $55,000, which is $45,000, and after $25,000 of expenses profit is $20,000, so the margin is 20%.","B":"25% would need a profit of $25,000 on the $100,000 of revenue.","C":"45% is the gross profit margin, not the profit margin after operating expenses.","D":"55% is the cost of sales share of revenue, not a profit margin."}}},{"id":"P1_U5_MCQ_1324","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1324","question":"Vernham Vintners has current assets of $96,000, including inventory of $30,000, and current liabilities of $44,000. What is its acid test ratio at the year end?","options":{"A":"0.68","B":"1.50","C":"1.00","D":"2.18"},"correctOption":"B","correctAnswer":"1.50","questionType":"MCQ","explanation":{"correct_reason":"The acid test uses current assets less inventory, so $96,000 less $30,000 gives $66,000, which divided by $44,000 is 1.50.","distractor_reasons":{"A":"0.68 divides the $30,000 of inventory by the $44,000 of current liabilities, which is not the acid test.","B":"The acid test uses current assets less inventory, so $96,000 less $30,000 gives $66,000, which divided by $44,000 is 1.50.","C":"1.00 would need liquid assets equal to the $44,000 of current liabilities.","D":"2.18 is the current ratio, using all $96,000 of current assets without removing inventory."}}},{"id":"P1_U5_MCQ_1325","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1325","question":"Rotherfield Roofing has operating profit of $63,000 and capital employed of $350,000. What is its return on capital employed, to the nearest whole percentage for the year?","options":{"A":"5.6%","B":"36%","C":"63%","D":"18%"},"correctOption":"D","correctAnswer":"18%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is $63,000 of operating profit divided by $350,000 of capital employed, which gives 18%.","distractor_reasons":{"A":"5.6% reverses the calculation by dividing capital employed by operating profit.","B":"36% comes from treating $63,000 as a share of $175,000 rather than of the $350,000 employed.","C":"63% repeats the operating profit as a percentage of $100,000 rather than of capital employed.","D":"Return on capital employed is $63,000 of operating profit divided by $350,000 of capital employed, which gives 18%."}}},{"id":"P1_U5_MCQ_1326","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1326","question":"Fennimore Ceramics must pay $28,000 for clay in March but will not receive payment from its customers until June. The gap is temporary and the amount needed varies each month. Which source of finance is most suitable for this short-term gap?","options":{"A":"A ten-year bank loan","B":"Issuing new shares","C":"A bank overdraft","D":"Selling the factory building"},"correctOption":"C","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"An overdraft suits a temporary, fluctuating gap because the business can borrow and repay as the clay payments and customer receipts move.","distractor_reasons":{"A":"A ten-year loan is long-term finance and would leave the business paying interest long after the gap has closed.","B":"Issuing shares raises permanent capital and brings in new owners, which is unsuitable for a short-term gap.","C":"An overdraft suits a temporary, fluctuating gap because the business can borrow and repay as the clay payments and customer receipts move.","D":"Selling the factory would remove a productive asset the business needs to make ceramics."}}},{"id":"P1_U5_MCQ_1327","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1327","question":"Wickham Spring Water starts April with $3,000 in the bank. Forecast net cash flow is an inflow of $8,000 in April and an outflow of $11,000 in May. What is the forecast closing balance at the end of May?","options":{"A":"$0","B":"-$8,000","C":"$3,000","D":"$8,000"},"correctOption":"A","correctAnswer":"$0","questionType":"MCQ","explanation":{"correct_reason":"The balance moves from $3,000 to $11,000 after April and then back to $0 after the $11,000 May outflow.","distractor_reasons":{"A":"The balance moves from $3,000 to $11,000 after April and then back to $0 after the $11,000 May outflow.","B":"-$8,000 wrongly ignores both the $3,000 opening balance and the $8,000 April inflow.","C":"$3,000 is the opening balance and ignores both months of forecast cash flow.","D":"$8,000 is the April inflow alone and does not include the May outflow."}}},{"id":"P1_U5_MCQ_1328","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1328","question":"Aldbourne Apiaries earns revenue of $84,000, a gross profit of $42,000 and operating expenses of $31,500. What is its profit margin for the financial year just ended?","options":{"A":"10.5%","B":"12.5%","C":"37.5%","D":"50%"},"correctOption":"B","correctAnswer":"12.5%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit of $42,000 less $31,500 of expenses leaves $10,500 profit, which is 12.5% of the $84,000 revenue.","distractor_reasons":{"A":"10.5% uses the $10,500 profit as a percentage of $100,000 rather than of the $84,000 revenue.","B":"Gross profit of $42,000 less $31,500 of expenses leaves $10,500 profit, which is 12.5% of the $84,000 revenue.","C":"37.5% is the operating expenses as a share of revenue, not the profit margin.","D":"50% is the gross profit margin, before the $31,500 of expenses is deducted."}}},{"id":"P1_U5_MCQ_1329","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1329","question":"Whitbourne Windows has current assets of $150,000 and current liabilities of $60,000 at the year end. What is its current ratio at the year end?","options":{"A":"0.40","B":"1.50","C":"2.00","D":"2.50"},"correctOption":"D","correctAnswer":"2.50","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets divided by current liabilities, so $150,000 divided by $60,000 gives 2.50.","distractor_reasons":{"A":"0.40 reverses the calculation by dividing the current liabilities by the current assets.","B":"1.50 would need current assets of $90,000 against the $60,000 of liabilities.","C":"2.00 would need current assets of $120,000 rather than the $150,000 reported.","D":"The current ratio is current assets divided by current liabilities, so $150,000 divided by $60,000 gives 2.50."}}},{"id":"P1_U5_MCQ_1330","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1330","question":"Staplehurst Steel had revenue of $400,000 and gross profit of $100,000 in 2024. In 2025 revenue was $500,000 and gross profit was $110,000. What was its gross profit margin in 2025?","options":{"A":"25%","B":"24%","C":"22%","D":"20%"},"correctOption":"C","correctAnswer":"22%","questionType":"MCQ","explanation":{"correct_reason":"The 2025 gross profit margin is $110,000 divided by $500,000, which gives 22%.","distractor_reasons":{"A":"25% is the 2024 margin, $100,000 divided by $400,000, not the 2025 figure.","B":"24% would need a gross profit of $120,000 on the $500,000 of revenue.","C":"The 2025 gross profit margin is $110,000 divided by $500,000, which gives 22%.","D":"20% divides the old $100,000 gross profit by the new $500,000 revenue."}}},{"id":"P1_U5_MCQ_1331","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1331","question":"Aldergrove Poultry, a sole trader, needs $200,000 to build a hatchery. The owner has no assets left to offer as security and does not want fixed monthly repayments. Which source of finance best matches these circumstances?","options":{"A":"Forming a private limited company and selling shares","B":"A personal bank loan","C":"A larger bank overdraft","D":"Trade credit from feed suppliers"},"correctOption":"A","correctAnswer":"Forming a private limited company and selling shares","questionType":"MCQ","explanation":{"correct_reason":"Selling shares in a private limited company raises $200,000 without security and without fixed monthly repayments, though the owner gives up some ownership.","distractor_reasons":{"A":"Selling shares in a private limited company raises $200,000 without security and without fixed monthly repayments, though the owner gives up some ownership.","B":"A personal bank loan usually requires security, which the owner no longer has, and it needs fixed monthly repayments.","C":"An overdraft is short-term, repayable on demand and unsuitable for a $200,000 hatchery building.","D":"Trade credit only delays payment for feed and cannot raise $200,000 for construction."}}},{"id":"P1_U5_MCQ_1332","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1332","question":"Redmarley Cafe is completing its cash flow forecast for July. Which of the following items would be recorded as a cash inflow in that month?","options":{"A":"Wages paid to two part-time staff","B":"Rent paid for the cafe premises","C":"Payment for a new refrigerator","D":"A bank loan received to buy a coffee machine"},"correctOption":"D","correctAnswer":"A bank loan received to buy a coffee machine","questionType":"MCQ","explanation":{"correct_reason":"Money coming into the business is an inflow, so the bank loan received for the coffee machine is recorded as a cash inflow in July.","distractor_reasons":{"A":"Wages paid to staff are money leaving the business, so they are recorded as a cash outflow.","B":"Rent paid for the premises is an outflow because cash leaves the bank account.","C":"Paying for a refrigerator is an outflow, not money received by the cafe.","D":"Money coming into the business is an inflow, so the bank loan received for the coffee machine is recorded as a cash inflow in July."}}},{"id":"P1_U5_MCQ_1333","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1333","question":"Crowhurst Coachworks raised its revenue from $200,000 to $220,000. Cost of sales stayed at $120,000 and operating expenses stayed at $60,000. By how much did the profit for the year increase?","options":{"A":"$2,000","B":"$20,000","C":"$10,000","D":"$40,000"},"correctOption":"B","correctAnswer":"$20,000","questionType":"MCQ","explanation":{"correct_reason":"Profit was $20,000 before ($200,000 less $120,000 less $60,000) and $40,000 after, so it increased by $20,000.","distractor_reasons":{"A":"$2,000 does not follow from the revenue change and the unchanged costs.","B":"Profit was $20,000 before ($200,000 less $120,000 less $60,000) and $40,000 after, so it increased by $20,000.","C":"$10,000 is half the actual increase in profit for the year.","D":"$40,000 is the new profit for the year, not the increase in profit."}}},{"id":"P1_U5_MCQ_1334","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1334","question":"Yoxall Yarns has total assets of $620,000, non-current liabilities of $140,000 and current liabilities of $110,000. What is the equity of the business at the year end?","options":{"A":"$250,000","B":"$480,000","C":"$370,000","D":"$510,000"},"correctOption":"C","correctAnswer":"$370,000","questionType":"MCQ","explanation":{"correct_reason":"Equity equals total assets less all liabilities, so $620,000 less $140,000 less $110,000 gives $370,000.","distractor_reasons":{"A":"$250,000 is the total of the two liability figures and is not the equity.","B":"$480,000 deducts only the non-current liabilities and ignores the $110,000 of current liabilities.","C":"Equity equals total assets less all liabilities, so $620,000 less $140,000 less $110,000 gives $370,000.","D":"$510,000 deducts only the current liabilities and ignores the $140,000 of non-current liabilities."}}},{"id":"P1_U5_MCQ_1335","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1335","question":"Tarporley Toys has revenue of $250,000 and a profit margin of 8% for the year. What is its operating profit for the financial year just ended?","options":{"A":"$20,000","B":"$8,000","C":"$31,250","D":"$200,000"},"correctOption":"A","correctAnswer":"$20,000","questionType":"MCQ","explanation":{"correct_reason":"Operating profit is 8% of the $250,000 revenue, which is $20,000.","distractor_reasons":{"A":"Operating profit is 8% of the $250,000 revenue, which is $20,000.","B":"$8,000 treats the 8% margin as a cash amount rather than as a percentage of revenue.","C":"$31,250 divides $250,000 by 8 instead of multiplying it by 0.08.","D":"$200,000 is revenue less the $20,000 profit, not the profit itself."}}},{"id":"P1_U5_MCQ_1336","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1336","question":"Thornleigh Rail takes out a $250,000 loan at 8% interest a year and also pays a one-off arrangement fee of $1,500. What is the total cost of this finance in the first year?","options":{"A":"$20,000","B":"$22,500","C":"$23,500","D":"$21,500"},"correctOption":"D","correctAnswer":"$21,500","questionType":"MCQ","explanation":{"correct_reason":"Interest is 8% of $250,000, which is $20,000, and adding the $1,500 arrangement fee gives a first-year cost of $21,500.","distractor_reasons":{"A":"$20,000 is the interest alone and leaves out the $1,500 arrangement fee.","B":"$22,500 adds $2,500 rather than the $1,500 fee to the $20,000 of interest.","C":"$23,500 charges interest on the loan plus the fee as well, so the fee is counted twice.","D":"Interest is 8% of $250,000, which is $20,000, and adding the $1,500 arrangement fee gives a first-year cost of $21,500."}}},{"id":"P1_U5_MCQ_1337","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1337","question":"Stowford Cider sells most of its bottles in December. Its cash flow forecast shows low receipts in October and November but large payments for extra bottles and seasonal staff. What should the owner expect in November?","options":{"A":"A large cash surplus from early sales","B":"A cash deficit requiring advance planning","C":"No change in the bank balance","D":"A fall in the number of bottles produced"},"correctOption":"B","correctAnswer":"A cash deficit requiring advance planning","questionType":"MCQ","explanation":{"correct_reason":"Large payments for stock and staff arrive before the December receipts, so November is likely to show a cash deficit that the owner must plan for.","distractor_reasons":{"A":"Receipts are described as low in November, so a large surplus is unlikely before the December sales.","B":"Large payments for stock and staff arrive before the December receipts, so November is likely to show a cash deficit that the owner must plan for.","C":"Large payments with low receipts will change the bank balance rather than leave it unchanged.","D":"The forecast concerns cash, not the physical number of bottles produced in November."}}},{"id":"P1_U5_MCQ_1338","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1338","question":"Draycott Detergents makes a profit for the year of $48,000. It pays 20% of this in tax and then pays dividends of $15,000. How much profit is retained in the business for the year?","options":{"A":"$28,800","B":"$33,000","C":"$23,400","D":"$38,400"},"correctOption":"C","correctAnswer":"$23,400","questionType":"MCQ","explanation":{"correct_reason":"Tax of 20% leaves $38,400, and paying $15,000 of dividends from that leaves $23,400 retained for the year.","distractor_reasons":{"A":"$28,800 deducts only the $15,000 of dividends from the $48,000 and ignores the 20% tax.","B":"$33,000 deducts $15,000 of tax rather than 20% of the profit, so the tax figure is wrong.","C":"Tax of 20% leaves $38,400, and paying $15,000 of dividends from that leaves $23,400 retained for the year.","D":"$38,400 is the profit after tax, before the $15,000 of dividends is paid."}}},{"id":"P1_U5_MCQ_1339","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1339","question":"Ashby Aquatics has inventory of $40,000, trade receivables of $25,000 and cash of $10,000. Its current liabilities are $50,000. What is its acid test ratio?","options":{"A":"0.70","B":"0.50","C":"1.43","D":"1.50"},"correctOption":"A","correctAnswer":"0.70","questionType":"MCQ","explanation":{"correct_reason":"Liquid assets are $25,000 of receivables plus $10,000 of cash, which is $35,000, and dividing by $50,000 of liabilities gives 0.70.","distractor_reasons":{"A":"Liquid assets are $25,000 of receivables plus $10,000 of cash, which is $35,000, and dividing by $50,000 of liabilities gives 0.70.","B":"0.50 would need liquid assets of $25,000, which ignores the $10,000 of cash.","C":"1.43 divides the $50,000 of liabilities by the $35,000 of liquid assets.","D":"1.50 is the current ratio, using all $75,000 of current assets including inventory."}}},{"id":"P1_U5_MCQ_1340","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1340","question":"Ulverston Utilities had operating profit of $56,000 and capital employed of $400,000 in 2024. In 2025 operating profit was $60,000 and capital employed was $600,000. What was its return on capital employed in 2025?","options":{"A":"6%","B":"14%","C":"60%","D":"10%"},"correctOption":"D","correctAnswer":"10%","questionType":"MCQ","explanation":{"correct_reason":"The 2025 return is $60,000 of operating profit divided by $600,000 of capital employed, which is 10%.","distractor_reasons":{"A":"6% divides the $36,000 rise in profit by $600,000 rather than using the full $60,000.","B":"14% is the 2024 return, before capital employed rose to $600,000.","C":"60% treats the $60,000 profit as a percentage of $100,000 instead of capital employed.","D":"The 2025 return is $60,000 of operating profit divided by $600,000 of capital employed, which is 10%."}}},{"id":"P1_U5_MCQ_1341","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1341","question":"Bexley Footwear asks its bank for a $120,000 loan to open a third shop. Which factor would most reduce the bank's willingness to lend the money?","options":{"A":"A detailed business plan with cash flow forecasts","B":"No security and a large existing overdraft","C":"A proven record of rising profits over five years","D":"Two experienced managers joining the business"},"correctOption":"B","correctAnswer":"No security and a large existing overdraft","questionType":"MCQ","explanation":{"correct_reason":"Lending $120,000 without security is risky for the bank, and an existing overdraft suggests the business already struggles to manage its cash.","distractor_reasons":{"A":"A detailed plan with cash flow forecasts would reassure the bank rather than reduce its willingness to lend.","B":"Lending $120,000 without security is risky for the bank, and an existing overdraft suggests the business already struggles to manage its cash.","C":"A record of rising profits gives the bank evidence that the loan can be repaid.","D":"Experienced managers joining the business strengthen confidence in the third shop's success."}}},{"id":"P1_U5_MCQ_1342","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1342","question":"Braithwaite Boats has an opening balance of $12,000 in April. Forecast net cash flows are an inflow of $4,000 in April, an outflow of $9,000 in May and an inflow of $2,000 in June. What is the balance at the end of June?","options":{"A":"$1,000","B":"$12,000","C":"$9,000","D":"$15,000"},"correctOption":"C","correctAnswer":"$9,000","questionType":"MCQ","explanation":{"correct_reason":"Starting at $12,000, adding $4,000 and $2,000 and deducting $9,000 leaves $9,000 at the end of June.","distractor_reasons":{"A":"$1,000 comes from adding only the $4,000 inflow and deducting the $9,000 outflow.","B":"$12,000 is the opening balance and ignores all three months of forecast flows.","C":"Starting at $12,000, adding $4,000 and $2,000 and deducting $9,000 leaves $9,000 at the end of June.","D":"$15,000 adds the $9,000 outflow instead of subtracting it from the other figures."}}},{"id":"P1_U5_MCQ_1343","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1343","question":"Eastrop Electrical has revenue of $180,000 and a gross profit margin of 25%. Its operating expenses are $33,000 for the year. What is the profit for the year?","options":{"A":"$33,000","B":"$45,000","C":"$147,000","D":"$12,000"},"correctOption":"D","correctAnswer":"$12,000","questionType":"MCQ","explanation":{"correct_reason":"A 25% margin on $180,000 revenue gives $45,000 gross profit, and deducting $33,000 of expenses leaves $12,000 profit.","distractor_reasons":{"A":"$33,000 is the operating expenses figure and is not a profit.","B":"$45,000 is the gross profit before operating expenses are deducted.","C":"$147,000 deducts only the $33,000 of expenses from revenue and ignores cost of sales.","D":"A 25% margin on $180,000 revenue gives $45,000 gross profit, and deducting $33,000 of expenses leaves $12,000 profit."}}},{"id":"P1_U5_MCQ_1344","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1344","question":"Broughton Bikes has non-current assets of $340,000 and current assets of $110,000. Its current liabilities are $60,000 and its non-current liabilities are $90,000. What are its net assets?","options":{"A":"$300,000","B":"$150,000","C":"$390,000","D":"$450,000"},"correctOption":"A","correctAnswer":"$300,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are $340,000 plus $110,000, which is $450,000, and deducting $60,000 and $90,000 of liabilities leaves net assets of $300,000.","distractor_reasons":{"A":"Total assets are $340,000 plus $110,000, which is $450,000, and deducting $60,000 and $90,000 of liabilities leaves net assets of $300,000.","B":"$150,000 is the total of the two liability figures and is not the net assets.","C":"$390,000 deducts only the $60,000 of current liabilities from total assets.","D":"$450,000 is total assets before any liabilities are deducted."}}},{"id":"P1_U5_MCQ_1345","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1345","question":"Ventnor Veneers had current assets of $120,000 and current liabilities of $60,000 in 2024. In 2025 current assets were $135,000 and current liabilities were $90,000. What was its current ratio in 2025?","options":{"A":"0.67","B":"1.50","C":"1.35","D":"2.00"},"correctOption":"B","correctAnswer":"1.50","questionType":"MCQ","explanation":{"correct_reason":"The 2025 current ratio is $135,000 of current assets divided by $90,000 of current liabilities, which gives 1.50.","distractor_reasons":{"A":"0.67 reverses the calculation by dividing current liabilities by current assets.","B":"The 2025 current ratio is $135,000 of current assets divided by $90,000 of current liabilities, which gives 1.50.","C":"1.35 uses the current assets figure as the ratio rather than dividing it by liabilities.","D":"2.00 is the 2024 current ratio of $120,000 divided by $60,000, not the 2025 figure."}}},{"id":"P1_U5_MCQ_1346","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1346","question":"Colwyn Packaging makes a profit for the year of $96,000. It pays $18,000 in tax and $30,000 in dividends to shareholders. How much profit is retained in the business for the year?","options":{"A":"$66,000","B":"$78,000","C":"$48,000","D":"$96,000"},"correctOption":"C","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is the $96,000 profit for the year less $18,000 of tax and $30,000 of dividends, which leaves $48,000.","distractor_reasons":{"A":"$66,000 deducts only the $30,000 of dividends and ignores the $18,000 of tax.","B":"$78,000 deducts only the $18,000 of tax and ignores the $30,000 of dividends.","C":"Retained profit is the $96,000 profit for the year less $18,000 of tax and $30,000 of dividends, which leaves $48,000.","D":"$96,000 is the profit before tax and dividends are deducted."}}},{"id":"P1_U5_MCQ_1347","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1347","question":"Elmbridge Interiors reports a profit of $18,000 for the year, yet its bank balance fell by $7,000. During the year it paid $25,000 in cash for new design software. Which statement best explains the fall in cash?","options":{"A":"Profit and cash are the same thing over a full year","B":"The business must have made a loss on its sales","C":"The bank balance always falls when profit is earned","D":"The software purchase used cash that was not deducted as a cost in full"},"correctOption":"D","correctAnswer":"The software purchase used cash that was not deducted as a cost in full","questionType":"MCQ","explanation":{"correct_reason":"The $25,000 software payment left the bank account but is treated as an asset and charged over several years, so cash fell while profit stayed positive.","distractor_reasons":{"A":"Profit and cash differ because cash paid for assets and cash from loans do not match the income and costs of the year.","B":"A profit of $18,000 rules out a loss on sales, so this cannot explain the fall in cash.","C":"Earning profit usually brings in cash, so the balance does not automatically fall.","D":"The $25,000 software payment left the bank account but is treated as an asset and charged over several years, so cash fell while profit stayed positive."}}},{"id":"P1_U5_MCQ_1348","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1348","question":"Foxcote Furniture has revenue of $220,000 and cost of sales of $132,000 for the year. What is its gross profit margin for the financial year just ended?","options":{"A":"40%","B":"33%","C":"60%","D":"88%"},"correctOption":"A","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $220,000 less $132,000, which is $88,000, and $88,000 divided by $220,000 gives a margin of 40%.","distractor_reasons":{"A":"Gross profit is $220,000 less $132,000, which is $88,000, and $88,000 divided by $220,000 gives a margin of 40%.","B":"33% is the cost of sales as a share of revenue, not the gross profit margin.","C":"60% is the cost of sales percentage, since $132,000 is 60% of $220,000.","D":"88% repeats the gross profit figure as a percentage without dividing by revenue."}}},{"id":"P1_U5_MCQ_1349","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1349","question":"Chaddleworth Cheese has equity of $180,000, non-current liabilities of $70,000, total assets of $330,000 and current liabilities of $80,000. What is its capital employed at the year end?","options":{"A":"$110,000","B":"$250,000","C":"$180,000","D":"$330,000"},"correctOption":"B","correctAnswer":"$250,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is equity plus non-current liabilities, so $180,000 plus $70,000 gives $250,000.","distractor_reasons":{"A":"$110,000 is total assets less equity, which is the total of all the liabilities.","B":"Capital employed is equity plus non-current liabilities, so $180,000 plus $70,000 gives $250,000.","C":"$180,000 is the equity alone and excludes the $70,000 of non-current liabilities.","D":"$330,000 is total assets before liabilities are deducted."}}},{"id":"P1_U5_MCQ_1350","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1350","question":"Waddesdon Wines has revenue of $350,000 and a gross profit margin of 40% for the year. What is its gross profit for the financial year just ended?","options":{"A":"$40,000","B":"$87,500","C":"$140,000","D":"$210,000"},"correctOption":"C","correctAnswer":"$140,000","questionType":"MCQ","explanation":{"correct_reason":"A 40% gross profit margin on $350,000 of revenue gives a gross profit of $140,000.","distractor_reasons":{"A":"$40,000 treats the 40% margin as a cash amount rather than a percentage of revenue.","B":"$87,500 divides $350,000 by 4 instead of multiplying it by 0.40.","C":"A 40% gross profit margin on $350,000 of revenue gives a gross profit of $140,000.","D":"$210,000 is the cost of sales, which is the remaining 60% of revenue."}}},{"id":"P1_U5_MCQ_1351","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1351","question":"Rivenhall Toys uses a $40,000 bank overdraft to cover seasonal stock purchases. The bank can demand repayment at any time and charges interest that rises with the base rate. Which disadvantage of this finance is described?","options":{"A":"It dilutes the owners' control of the business","B":"It can only be used to buy non-current assets","C":"It must be repaid in equal monthly instalments","D":"It is repayable on demand and carries variable interest"},"correctOption":"D","correctAnswer":"It is repayable on demand and carries variable interest","questionType":"MCQ","explanation":{"correct_reason":"An overdraft can be recalled at any time and its interest moves with the base rate, so the $40,000 facility is uncertain and its cost can rise.","distractor_reasons":{"A":"An overdraft is borrowed money and does not involve selling shares, so control is not diluted.","B":"Overdrafts are typically used for working capital such as stock, not restricted to non-current assets.","C":"An overdraft is flexible rather than repaid in equal monthly instalments.","D":"An overdraft can be recalled at any time and its interest moves with the base rate, so the $40,000 facility is uncertain and its cost can rise."}}},{"id":"P1_U5_MCQ_1352","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1352","question":"Tarnside Vets forecasts these payments for June: medicines $14,000, wages $22,000, rent $6,000, loan repayment $4,000 and equipment $9,000. What is the total forecast cash outflow for June?","options":{"A":"$55,000","B":"$46,000","C":"$51,000","D":"$64,000"},"correctOption":"A","correctAnswer":"$55,000","questionType":"MCQ","explanation":{"correct_reason":"Adding $14,000, $22,000, $6,000, $4,000 and $9,000 of payments gives total forecast outflows of $55,000.","distractor_reasons":{"A":"Adding $14,000, $22,000, $6,000, $4,000 and $9,000 of payments gives total forecast outflows of $55,000.","B":"$46,000 leaves out the $9,000 equipment payment from the total.","C":"$51,000 leaves out the $4,000 loan repayment from the total.","D":"$64,000 counts one or more payments twice and does not match the listed figures."}}},{"id":"P1_U5_MCQ_1353","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1353","question":"Glanville Glass reports operating profit of $54,000 for the year. It pays interest of $6,000 and tax of $12,000. What is the profit for the year?","options":{"A":"$48,000","B":"$42,000","C":"$36,000","D":"$54,000"},"correctOption":"C","correctAnswer":"$36,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is $54,000 operating profit less $6,000 of interest and $12,000 of tax, which leaves $36,000.","distractor_reasons":{"A":"$48,000 deducts only the $6,000 of interest and ignores the $12,000 of tax.","B":"$42,000 deducts only the $12,000 of tax and ignores the $6,000 of interest.","C":"Profit for the year is $54,000 operating profit less $6,000 of interest and $12,000 of tax, which leaves $36,000.","D":"$54,000 is the operating profit before interest and tax are deducted."}}},{"id":"P1_U5_MCQ_1354","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1354","question":"Danesford Drills has current assets of $80,000 and current liabilities of $50,000. It then buys inventory worth $12,000 on two months' credit. What is its working capital immediately after this purchase?","options":{"A":"$12,000","B":"$30,000","C":"$18,000","D":"$42,000"},"correctOption":"B","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"Inventory bought on credit raises current assets and current liabilities by $12,000 each, so working capital stays at $80,000 less $50,000, which is $30,000.","distractor_reasons":{"A":"$12,000 is the value of the inventory bought, not the working capital.","B":"Inventory bought on credit raises current assets and current liabilities by $12,000 each, so working capital stays at $80,000 less $50,000, which is $30,000.","C":"$18,000 wrongly deducts the $12,000 purchase from working capital.","D":"$42,000 adds the $12,000 to working capital as though only the assets changed."}}},{"id":"P1_U5_MCQ_1355","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1355","question":"Yelverton Yachts has operating profit of $90,000 and capital employed of $450,000. What is its return on capital employed for the financial year just ended?","options":{"A":"4.5%","B":"15%","C":"90%","D":"20%"},"correctOption":"D","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is $90,000 divided by $450,000, which gives 20%.","distractor_reasons":{"A":"4.5% reverses the calculation by dividing capital employed by operating profit.","B":"15% would need capital employed of $600,000 against the $90,000 of profit.","C":"90% repeats the operating profit as a percentage of $100,000 rather than of capital employed.","D":"Return on capital employed is $90,000 divided by $450,000, which gives 20%."}}},{"id":"P1_U5_MCQ_1356","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1356","question":"Skerrydale Fisheries is overdrawn by $18,000 for six months. The bank charges interest at 9% a year on the overdrawn balance. What interest does the business pay for this six-month period?","options":{"A":"$810","B":"$405","C":"$1,350","D":"$1,620"},"correctOption":"A","correctAnswer":"$810","questionType":"MCQ","explanation":{"correct_reason":"Annual interest on $18,000 at 9% is $1,620, so the six-month charge is half of that, which is $810.","distractor_reasons":{"A":"Annual interest on $18,000 at 9% is $1,620, so the six-month charge is half of that, which is $810.","B":"$405 is a quarter of the annual interest, not half of it.","C":"$1,350 comes from 9% of $15,000 rather than of the $18,000 overdrawn.","D":"$1,620 is the full year's interest and ignores that the overdraft lasts only six months."}}},{"id":"P1_U5_MCQ_1357","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1357","question":"Hobbs Lane Deli expects a cash deficit of $6,000 in August because it must pay for new refrigeration before its summer takings arrive. Which action would most directly solve this short-term deficit?","options":{"A":"Reduce the selling price of sandwiches","B":"Buy a second delivery bicycle","C":"Arrange a short-term bank overdraft","D":"Increase the wages of weekend staff"},"correctOption":"C","correctAnswer":"Arrange a short-term bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"An overdraft supplies cash quickly in August and can be repaid once the summer takings arrive, matching a short-term deficit.","distractor_reasons":{"A":"Cutting prices may raise sales but reduces the cash received on each sandwich, so it does not close a $6,000 gap.","B":"Buying another bicycle uses cash and would make the August deficit worse.","C":"An overdraft supplies cash quickly in August and can be repaid once the summer takings arrive, matching a short-term deficit.","D":"Raising wages increases cash payments and deepens the August deficit."}}},{"id":"P1_U5_MCQ_1358","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1358","question":"Hartley Hampers has revenue of $300,000, cost of sales of $180,000 and operating expenses of $84,000. What is its profit margin for the financial year just ended?","options":{"A":"28%","B":"12%","C":"36%","D":"40%"},"correctOption":"B","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $300,000 less $180,000, which is $120,000, and after $84,000 of expenses profit is $36,000, so the margin is 12%.","distractor_reasons":{"A":"28% is the operating expenses as a share of revenue, not the profit margin.","B":"Gross profit is $300,000 less $180,000, which is $120,000, and after $84,000 of expenses profit is $36,000, so the margin is 12%.","C":"36% comes from treating the $36,000 profit as a percentage of $100,000 rather than of revenue.","D":"40% is the gross profit margin, before operating expenses are deducted."}}},{"id":"P1_U5_MCQ_1359","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1359","question":"Ebberston Eggs holds inventory of $30,000, trade receivables of $22,000 and cash of $8,000. Its current liabilities are $40,000. What is its acid test ratio?","options":{"A":"0.55","B":"1.33","C":"1.50","D":"0.75"},"correctOption":"D","correctAnswer":"0.75","questionType":"MCQ","explanation":{"correct_reason":"Liquid assets are $22,000 of receivables plus $8,000 of cash, which is $30,000, and dividing by $40,000 of liabilities gives 0.75.","distractor_reasons":{"A":"0.55 would need liquid assets of $22,000, which leaves out the $8,000 of cash.","B":"1.33 divides the $40,000 of liabilities by the $30,000 of liquid assets.","C":"1.50 is the current ratio, using all $60,000 of current assets including inventory.","D":"Liquid assets are $22,000 of receivables plus $8,000 of cash, which is $30,000, and dividing by $40,000 of liabilities gives 0.75."}}},{"id":"P1_U5_MCQ_1360","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1360","question":"Zetland Zinc has revenue of $400,000 and a profit margin of 12%. Its capital employed is $320,000. What is its return on capital employed for the year?","options":{"A":"15%","B":"3.2%","C":"12%","D":"48%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"A 12% margin on $400,000 of revenue gives $48,000 profit, and $48,000 divided by $320,000 of capital employed is 15%.","distractor_reasons":{"A":"A 12% margin on $400,000 of revenue gives $48,000 profit, and $48,000 divided by $320,000 of capital employed is 15%.","B":"3.2% divides capital employed by revenue and does not use the profit figure at all.","C":"12% is the profit margin on revenue, not the return on capital employed.","D":"48% is the operating profit expressed as a percentage of $100,000 rather than of capital employed."}}},{"id":"P1_U5_MCQ_1361","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1361","question":"Mardenvale Salons needs $12,000 for new styling chairs. It owns a delivery van that is no longer used and could be sold for $14,000. Which source of finance does selling the van represent?","options":{"A":"External finance from a bank loan","B":"External finance from share capital","C":"Internal finance from the sale of an asset","D":"Internal finance from retained profit"},"correctOption":"C","correctAnswer":"Internal finance from the sale of an asset","questionType":"MCQ","explanation":{"correct_reason":"Selling the unused van raises $14,000 from inside the business, so it is internal finance from the sale of an asset rather than borrowed money.","distractor_reasons":{"A":"A bank loan is external finance and creates a liability, unlike selling an existing asset.","B":"Share capital comes from outside investors and is therefore external finance.","C":"Selling the unused van raises $14,000 from inside the business, so it is internal finance from the sale of an asset rather than borrowed money.","D":"Retained profit is internal, but the $14,000 comes from selling a van, not from past profits."}}},{"id":"P1_U5_MCQ_1362","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1362","question":"Keswick Outfitters makes 60% of its sales on credit. Credit customers always pay in the month after purchase. Sales in March were $70,000. How much cash from March credit sales is received in April?","options":{"A":"$21,000","B":"$42,000","C":"$28,000","D":"$70,000"},"correctOption":"B","correctAnswer":"$42,000","questionType":"MCQ","explanation":{"correct_reason":"Credit sales are 60% of $70,000, which is $42,000, and these customers pay in April, so $42,000 is received.","distractor_reasons":{"A":"$21,000 is 30% of March sales, not the 60% sold on credit.","B":"Credit sales are 60% of $70,000, which is $42,000, and these customers pay in April, so $42,000 is received.","C":"$28,000 is the 40% of sales made for cash in March, which is received in March.","D":"$70,000 is total March sales, including the cash sales already received."}}},{"id":"P1_U5_MCQ_1363","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1363","question":"Inversnaid Wool has revenue of $165,000 and a gross profit of $66,000 for the year. Its operating expenses are $44,000. What is its gross profit margin?","options":{"A":"40%","B":"25%","C":"60%","D":"66%"},"correctOption":"A","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is $66,000 divided by $165,000, which gives 40%.","distractor_reasons":{"A":"Gross profit margin is $66,000 divided by $165,000, which gives 40%.","B":"25% is the operating expenses as a share of revenue, not the gross profit margin.","C":"60% is the cost of sales share of revenue, not the gross profit margin.","D":"66% repeats the gross profit figure as a percentage without dividing by revenue."}}},{"id":"P1_U5_MCQ_1364","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1364","question":"Framlingham Fashions reports total assets of $700,000 and equity of $420,000. Its current liabilities are $130,000. What is the value of its non-current liabilities at the year end?","options":{"A":"$130,000","B":"$280,000","C":"$550,000","D":"$150,000"},"correctOption":"D","correctAnswer":"$150,000","questionType":"MCQ","explanation":{"correct_reason":"Non-current liabilities are total assets less equity and current liabilities, so $700,000 less $420,000 less $130,000 gives $150,000.","distractor_reasons":{"A":"$130,000 is the current liabilities figure and is not the non-current liabilities.","B":"$280,000 deducts the equity from total assets but forgets the $130,000 of current liabilities.","C":"$550,000 deducts only the $150,000 answer from total assets, which reverses the calculation.","D":"Non-current liabilities are total assets less equity and current liabilities, so $700,000 less $420,000 less $130,000 gives $150,000."}}},{"id":"P1_U5_MCQ_1365","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1365","question":"Amberley Ales had an acid test ratio of 1.4 in 2024. In 2025 its current assets were $132,000, including inventory of $44,000, and current liabilities were $80,000. What was its acid test ratio in 2025?","options":{"A":"0.55","B":"1.40","C":"1.10","D":"1.65"},"correctOption":"C","correctAnswer":"1.10","questionType":"MCQ","explanation":{"correct_reason":"The 2025 acid test is $132,000 less $44,000 of inventory, which is $88,000, divided by $80,000 of liabilities, giving 1.10.","distractor_reasons":{"A":"0.55 divides $44,000 of inventory by $80,000 of liabilities, which is not the acid test.","B":"1.40 is the 2024 ratio and has not been recalculated from the 2025 figures.","C":"The 2025 acid test is $132,000 less $44,000 of inventory, which is $88,000, divided by $80,000 of liabilities, giving 1.10.","D":"1.65 is the 2025 current ratio of $132,000 divided by $80,000, which includes inventory."}}},{"id":"P1_U5_MCQ_1366","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1366","question":"Penhallow Cycles buys a delivery van with a $4,000 deposit and 24 monthly payments of $450. The cash price of the van is $13,000. How much extra does the business pay by using this instalment arrangement?","options":{"A":"$800","B":"$1,800","C":"$10,800","D":"$14,800"},"correctOption":"B","correctAnswer":"$1,800","questionType":"MCQ","explanation":{"correct_reason":"The total paid is $4,000 plus 24 payments of $450, which is $14,800, so the extra over the $13,000 cash price is $1,800.","distractor_reasons":{"A":"$800 does not follow from the deposit, the monthly payments and the $13,000 cash price.","B":"The total paid is $4,000 plus 24 payments of $450, which is $14,800, so the extra over the $13,000 cash price is $1,800.","C":"$10,800 is the total of the 24 monthly payments alone and leaves out the $4,000 deposit.","D":"$14,800 is the total amount paid, not the extra cost compared with the cash price."}}},{"id":"P1_U5_MCQ_1367","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1367","question":"Pemberton Paints has an opening bank balance of $1,800. Its forecast net cash flow for October is an outflow of $2,500. What is the forecast closing balance for October?","options":{"A":"$700 overdrawn","B":"$700 in credit","C":"$2,500 overdrawn","D":"$4,300 in credit"},"correctOption":"A","correctAnswer":"$700 overdrawn","questionType":"MCQ","explanation":{"correct_reason":"Subtracting the $2,500 outflow from the $1,800 opening balance leaves minus $700, which means $700 overdrawn.","distractor_reasons":{"A":"Subtracting the $2,500 outflow from the $1,800 opening balance leaves minus $700, which means $700 overdrawn.","B":"$700 in credit ignores that the outflow is larger than the opening balance, so the account is overdrawn.","C":"$2,500 overdrawn ignores the $1,800 already held at the start of October.","D":"$4,300 in credit adds the outflow to the opening balance instead of subtracting it."}}},{"id":"P1_U5_MCQ_1368","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1368","question":"Jarrow Joinery's revenue fell from $250,000 to $200,000. Cost of sales fell from $150,000 to $120,000, while operating expenses stayed at $50,000. By how much did profit for the year fall?","options":{"A":"$10,000","B":"$30,000","C":"$50,000","D":"$20,000"},"correctOption":"D","correctAnswer":"$20,000","questionType":"MCQ","explanation":{"correct_reason":"Profit was $50,000 before ($250,000 less $150,000 less $50,000) and $30,000 after, so it fell by $20,000.","distractor_reasons":{"A":"$10,000 does not match the change between the two years' profit figures.","B":"$30,000 is the new profit for the year, not the amount by which profit fell.","C":"$50,000 is the previous profit for the year, not the fall in profit.","D":"Profit was $50,000 before ($250,000 less $150,000 less $50,000) and $30,000 after, so it fell by $20,000."}}},{"id":"P1_U5_MCQ_1369","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1369","question":"Gweek Garages has inventory of $55,000, trade receivables of $30,000 and cash of $15,000. Its current liabilities are $60,000. What is its current ratio at the year end?","options":{"A":"0.75","B":"1.25","C":"1.67","D":"1.50"},"correctOption":"C","correctAnswer":"1.67","questionType":"MCQ","explanation":{"correct_reason":"Current assets total $55,000 plus $30,000 plus $15,000, which is $100,000, and dividing by $60,000 of liabilities gives 1.67.","distractor_reasons":{"A":"0.75 is the acid test, which removes the $55,000 of inventory from current assets.","B":"1.25 would need current assets of $75,000 rather than the $100,000 calculated.","C":"Current assets total $55,000 plus $30,000 plus $15,000, which is $100,000, and dividing by $60,000 of liabilities gives 1.67.","D":"1.50 would need current assets of $90,000 rather than the $100,000 calculated."}}},{"id":"P1_U5_MCQ_1370","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1370","question":"Bircherley Bags has revenue of $200,000, gross profit of $70,000 and operating expenses of $46,000. What is its profit margin for the financial year just ended?","options":{"A":"24%","B":"12%","C":"35%","D":"23%"},"correctOption":"B","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit of $70,000 less $46,000 of expenses leaves $24,000 profit, which is 12% of the $200,000 revenue.","distractor_reasons":{"A":"24% repeats the $24,000 profit as a percentage of $100,000 rather than of the $200,000 revenue.","B":"Gross profit of $70,000 less $46,000 of expenses leaves $24,000 profit, which is 12% of the $200,000 revenue.","C":"35% is the gross profit margin, before the $46,000 of expenses is deducted.","D":"23% is the operating expenses as a share of revenue, not the profit margin."}}},{"id":"P1_U5_MCQ_1371","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1371","question":"Ormsby Fitness is a new gym with no trading record, no assets and no customers yet. The owner needs $25,000 for equipment before opening. Which source of finance is most likely to be available?","options":{"A":"The owner's personal savings","B":"Retained profit from previous years","C":"Trade credit from equipment suppliers","D":"A long-term bank loan"},"correctOption":"A","correctAnswer":"The owner's personal savings","questionType":"MCQ","explanation":{"correct_reason":"A new gym has no profit history or assets to support borrowing, so the owner's own savings are the most realistic source of the $25,000.","distractor_reasons":{"A":"A new gym has no profit history or assets to support borrowing, so the owner's own savings are the most realistic source of the $25,000.","B":"Retained profit only builds up from past profits, and this gym has not traded yet.","C":"Suppliers are unlikely to grant credit for equipment to a business with no trading record.","D":"Banks usually refuse long-term loans to a new business with no record and no security."}}},{"id":"P1_U5_MCQ_1372","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1372","question":"Saltmarsh Seafood sells to restaurants that pay 60 days after delivery, while its own suppliers demand payment within 14 days. Which change would improve the business's cash flow without borrowing?","options":{"A":"Allow restaurants 90 days to pay","B":"Pay suppliers earlier to earn their trust","C":"Increase the amount of stock held","D":"Offer restaurant customers a discount for paying within 14 days"},"correctOption":"D","correctAnswer":"Offer restaurant customers a discount for paying within 14 days","questionType":"MCQ","explanation":{"correct_reason":"Persuading restaurants to pay within 14 days brings cash in sooner, narrowing the gap with supplier payments without any borrowing.","distractor_reasons":{"A":"Allowing 90 days delays receipts further and widens the gap between paying suppliers and being paid.","B":"Paying suppliers even earlier takes cash out sooner and makes the cash flow problem worse.","C":"Holding more stock ties up cash in inventory and reduces the cash available to pay suppliers.","D":"Persuading restaurants to pay within 14 days brings cash in sooner, narrowing the gap with supplier payments without any borrowing."}}},{"id":"P1_U5_MCQ_1373","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1373","question":"Kemsley Kitchens makes a profit for the year of $30,000 and pays dividends of $12,000. Retained profit brought forward was $45,000. What is the retained profit carried forward?","options":{"A":"$57,000","B":"$63,000","C":"$75,000","D":"$87,000"},"correctOption":"B","correctAnswer":"$63,000","questionType":"MCQ","explanation":{"correct_reason":"Profit kept this year is $30,000 less $12,000, which is $18,000, and adding the $45,000 brought forward gives $63,000 carried forward.","distractor_reasons":{"A":"$57,000 adds only the $12,000 of dividends to the $45,000 brought forward.","B":"Profit kept this year is $30,000 less $12,000, which is $18,000, and adding the $45,000 brought forward gives $63,000 carried forward.","C":"$75,000 adds the full $30,000 profit to the $45,000 and ignores the dividends paid.","D":"$87,000 adds the profit and the dividends to the $45,000 brought forward."}}},{"id":"P1_U5_MCQ_1374","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1374","question":"Hanbury Hardware owns property worth $400,000 and equipment worth $120,000. It holds inventory of $60,000, receivables of $30,000 and cash of $10,000. Current liabilities are $70,000 and non-current liabilities are $150,000. What are its net assets?","options":{"A":"$220,000","B":"$470,000","C":"$400,000","D":"$620,000"},"correctOption":"C","correctAnswer":"$400,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are $400,000 plus $120,000 plus $60,000 plus $30,000 plus $10,000, which is $620,000, and deducting $220,000 of liabilities leaves $400,000.","distractor_reasons":{"A":"$220,000 is the total of the current and non-current liabilities, not the net assets.","B":"$470,000 uses only the non-current assets plus part of the current assets and is not a valid total.","C":"Total assets are $400,000 plus $120,000 plus $60,000 plus $30,000 plus $10,000, which is $620,000, and deducting $220,000 of liabilities leaves $400,000.","D":"$620,000 is total assets before any liabilities are deducted."}}},{"id":"P1_U5_MCQ_1375","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1375","question":"Cottesmore Cakes has operating profit of $36,000 and capital employed of $240,000. It then spends $60,000 of a new loan, raising operating profit to $39,000 and capital employed to $300,000. What is the new return on capital employed?","options":{"A":"13%","B":"12%","C":"15%","D":"16.25%"},"correctOption":"A","correctAnswer":"13%","questionType":"MCQ","explanation":{"correct_reason":"The new return is $39,000 of operating profit divided by $300,000 of capital employed, which gives 13%.","distractor_reasons":{"A":"The new return is $39,000 of operating profit divided by $300,000 of capital employed, which gives 13%.","B":"12% would need capital employed of $325,000 against the $39,000 of profit.","C":"15% is the old return of $36,000 divided by $240,000, before the extra spending.","D":"16.25% divides the $39,000 profit by $240,000 and ignores the rise in capital employed."}}},{"id":"P1_U5_MCQ_1376","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1376","question":"Weybridge Laundry receives a bill of $24,000 from its linen supplier. The supplier offers a 3% discount for payment within fourteen days. How much will the laundry save if it accepts this early-payment discount?","options":{"A":"$72","B":"$240","C":"$2,400","D":"$720"},"correctOption":"D","correctAnswer":"$720","questionType":"MCQ","explanation":{"correct_reason":"A 3% discount on the $24,000 bill is $720, which is the amount the laundry saves by paying within fourteen days.","distractor_reasons":{"A":"$72 would be a discount of 0.3%, one tenth of the 3% offered.","B":"$240 would be a 1% discount on the $24,000 bill, not the 3% offered.","C":"$2,400 is a 10% discount on the bill, far more than the supplier offers.","D":"A 3% discount on the $24,000 bill is $720, which is the amount the laundry saves by paying within fourteen days."}}},{"id":"P1_U5_MCQ_1377","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1377","question":"Wroxham Garden Centre had a bank balance of $25,000 on 1 January and $18,000 on 31 January. What was its net cash flow for January?","options":{"A":"$7,000 inflow","B":"$7,000 outflow","C":"$43,000 inflow","D":"$25,000 outflow"},"correctOption":"B","correctAnswer":"$7,000 outflow","questionType":"MCQ","explanation":{"correct_reason":"The balance fell from $25,000 to $18,000, a fall of $7,000, which is a net cash outflow of $7,000 for January.","distractor_reasons":{"A":"$7,000 is the correct size of the change, but the balance fell, so it is an outflow rather than an inflow.","B":"The balance fell from $25,000 to $18,000, a fall of $7,000, which is a net cash outflow of $7,000 for January.","C":"$43,000 wrongly adds the two balances together instead of finding the difference.","D":"$25,000 is the opening balance, not the change during January."}}},{"id":"P1_U5_MCQ_1378","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1378","question":"Lanacre Lighting has revenue of $240,000 and a profit margin of 8%. Its operating expenses are $28,800 for the year. What is its gross profit?","options":{"A":"$19,200","B":"$28,800","C":"$48,000","D":"$211,200"},"correctOption":"C","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"An 8% margin on $240,000 gives $19,200 profit, and adding back the $28,800 of expenses gives gross profit of $48,000.","distractor_reasons":{"A":"$19,200 is the profit for the year, before the $28,800 of expenses is added back.","B":"$28,800 is the operating expenses figure and is not the gross profit.","C":"An 8% margin on $240,000 gives $19,200 profit, and adding back the $28,800 of expenses gives gross profit of $48,000.","D":"$211,200 subtracts the $28,800 expenses from revenue and ignores the 8% profit margin."}}},{"id":"P1_U5_MCQ_1379","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1379","question":"Ide Ironworks has share capital of $250,000, retained earnings of $95,000 and non-current liabilities of $105,000. What is its capital employed at the year end?","options":{"A":"$450,000","B":"$200,000","C":"$250,000","D":"$345,000"},"correctOption":"A","correctAnswer":"$450,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is equity plus non-current liabilities, so $250,000 plus $95,000 plus $105,000 gives $450,000.","distractor_reasons":{"A":"Capital employed is equity plus non-current liabilities, so $250,000 plus $95,000 plus $105,000 gives $450,000.","B":"$200,000 adds the retained earnings to the non-current liabilities and omits the share capital.","C":"$250,000 is the share capital alone and leaves out both other figures.","D":"$345,000 is the equity alone and excludes the $105,000 of non-current liabilities."}}},{"id":"P1_U5_MCQ_1380","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1380","question":"Dolgellau Dyes has a current ratio of 1.8 and current liabilities of $50,000. Its inventory is valued at $30,000. What is its acid test ratio?","options":{"A":"0.60","B":"1.50","C":"1.80","D":"1.20"},"correctOption":"D","correctAnswer":"1.20","questionType":"MCQ","explanation":{"correct_reason":"Current assets are 1.8 times $50,000, which is $90,000, so liquid assets are $60,000 and the acid test is 1.20.","distractor_reasons":{"A":"0.60 divides the $30,000 of inventory by $50,000 of liabilities, which is not the acid test.","B":"1.50 would need liquid assets of $75,000 rather than the $60,000 calculated.","C":"1.80 is the current ratio given in the question and includes inventory.","D":"Current assets are 1.8 times $50,000, which is $90,000, so liquid assets are $60,000 and the acid test is 1.20."}}},{"id":"P1_U5_MCQ_1381","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1381","question":"Loxley Engraving is a family firm owned by two sisters. They need $90,000 and want to keep full control and all future profits within the family. Which source of finance best suits this aim?","options":{"A":"Selling shares to outside investors","B":"A bank loan repaid with interest","C":"Admitting a new partner","D":"Venture capital in exchange for a shareholding"},"correctOption":"B","correctAnswer":"A bank loan repaid with interest","questionType":"MCQ","explanation":{"correct_reason":"A bank loan provides $90,000 while the sisters keep every share, so control and future profits stay entirely within the family.","distractor_reasons":{"A":"Selling shares to outsiders gives them a say in decisions and a claim on future profits.","B":"A bank loan provides $90,000 while the sisters keep every share, so control and future profits stay entirely within the family.","C":"Admitting a partner shares both control and future profits with a third person.","D":"Venture capital comes with a shareholding and usually a say in how the firm is run."}}},{"id":"P1_U5_MCQ_1382","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1382","question":"Yarrowfield Farm Shop plans to pay $30,000 for a cold room in June, which would create a large deficit. Takings rise sharply in July when local fruit is harvested. Which action best improves the June cash position?","options":{"A":"Buy two cold rooms in June instead","B":"Reduce prices throughout the winter","C":"Delay the purchase until July when receipts are higher","D":"Pay suppliers in advance during May"},"correctOption":"C","correctAnswer":"Delay the purchase until July when receipts are higher","questionType":"MCQ","explanation":{"correct_reason":"Moving the $30,000 payment to July, when harvest takings arrive, avoids the June deficit without borrowing or cancelling the purchase.","distractor_reasons":{"A":"Buying two cold rooms in June doubles the payment and makes the deficit much larger.","B":"Cutting winter prices reduces receipts in the months before June and worsens the cash position.","C":"Moving the $30,000 payment to July, when harvest takings arrive, avoids the June deficit without borrowing or cancelling the purchase.","D":"Paying suppliers in advance takes cash out earlier and leaves less available for the cold room."}}},{"id":"P1_U5_MCQ_1383","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1383","question":"Medlar Press has revenue of $500,000 and a gross profit margin of 35%. Its operating expenses are $125,000 for the year. What is its profit margin?","options":{"A":"50%","B":"25%","C":"35%","D":"10%"},"correctOption":"D","correctAnswer":"10%","questionType":"MCQ","explanation":{"correct_reason":"A 35% margin gives $175,000 gross profit, and after $125,000 of expenses profit is $50,000, which is 10% of revenue.","distractor_reasons":{"A":"50% would need a profit of $250,000 on the $500,000 of revenue.","B":"25% is the operating expenses as a share of revenue, not the profit margin.","C":"35% is the gross profit margin, before the $125,000 of expenses is deducted.","D":"A 35% margin gives $175,000 gross profit, and after $125,000 of expenses profit is $50,000, which is 10% of revenue."}}},{"id":"P1_U5_MCQ_1384","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1384","question":"Jordans Jewellers has current assets of $84,000 and current liabilities of $56,000. It then receives a $20,000 long-term bank loan. What is its working capital immediately after receiving the loan?","options":{"A":"$48,000","B":"$8,000","C":"$28,000","D":"$76,000"},"correctOption":"A","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"The loan raises cash and current assets to $104,000 while current liabilities stay at $56,000, so working capital becomes $48,000.","distractor_reasons":{"A":"The loan raises cash and current assets to $104,000 while current liabilities stay at $56,000, so working capital becomes $48,000.","B":"$8,000 wrongly treats the $20,000 loan as a current liability and subtracts it from the old working capital.","C":"$28,000 is the working capital before the loan is received.","D":"$76,000 adds the $20,000 loan to the old working capital twice."}}},{"id":"P1_U5_MCQ_1385","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1385","question":"Edale Engines had a gross profit margin of 30% on revenue of $500,000. Its margin then fell to 24% while revenue stayed at $500,000. By how much did gross profit fall?","options":{"A":"$6,000","B":"$30,000","C":"$24,000","D":"$150,000"},"correctOption":"B","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit was $150,000 at 30% and $120,000 at 24%, so the fall is $30,000 on the unchanged $500,000 of revenue.","distractor_reasons":{"A":"$6,000 is the fall in the margin in percentage points, not in dollars of gross profit.","B":"Gross profit was $150,000 at 30% and $120,000 at 24%, so the fall is $30,000 on the unchanged $500,000 of revenue.","C":"$24,000 is the 24% margin expressed as a cash amount rather than the fall in profit.","D":"$150,000 is the original gross profit at 30%, not the amount by which it fell."}}},{"id":"P1_U5_MCQ_1386","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1386","question":"Camberwell Upholstery borrows $50,000 at 6% interest a year and pays an arrangement fee of $750. What is the total cost of this finance in the first year?","options":{"A":"$3,000","B":"$4,500","C":"$3,750","D":"$30,000"},"correctOption":"C","correctAnswer":"$3,750","questionType":"MCQ","explanation":{"correct_reason":"Interest is 6% of $50,000, which is $3,000, and adding the $750 arrangement fee gives a first-year cost of $3,750.","distractor_reasons":{"A":"$3,000 is the interest alone and leaves out the $750 arrangement fee.","B":"$4,500 adds $1,500 rather than $750 to the interest, so the fee is doubled.","C":"Interest is 6% of $50,000, which is $3,000, and adding the $750 arrangement fee gives a first-year cost of $3,750.","D":"$30,000 treats the 6% as $60 per $100 rather than $6 per $100."}}},{"id":"P1_U5_MCQ_1387","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1387","question":"Caldbeck Candles forecasts these receipts for November: cash sales $34,000, payments from credit customers $12,000 and a bank loan of $20,000. What is the total forecast cash inflow for November?","options":{"A":"$34,000","B":"$46,000","C":"$54,000","D":"$66,000"},"correctOption":"D","correctAnswer":"$66,000","questionType":"MCQ","explanation":{"correct_reason":"Total inflows are $34,000 of cash sales plus $12,000 from credit customers plus the $20,000 loan, which is $66,000.","distractor_reasons":{"A":"$34,000 counts only the cash sales and ignores the debtor receipts and the loan.","B":"$46,000 counts the cash and credit sales but leaves out the $20,000 loan.","C":"$54,000 counts the cash sales and the loan but leaves out the $12,000 from credit customers.","D":"Total inflows are $34,000 of cash sales plus $12,000 from credit customers plus the $20,000 loan, which is $66,000."}}},{"id":"P1_U5_MCQ_1388","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1388","question":"Northcote Nurseries has revenue of $130,000, cost of sales of $78,000 and operating expenses of $39,000. What is the profit for the financial year just ended?","options":{"A":"$13,000","B":"$39,000","C":"$52,000","D":"$91,000"},"correctOption":"A","correctAnswer":"$13,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $130,000 less $78,000, which is $52,000, and deducting $39,000 of expenses leaves $13,000 profit.","distractor_reasons":{"A":"Gross profit is $130,000 less $78,000, which is $52,000, and deducting $39,000 of expenses leaves $13,000 profit.","B":"$39,000 is the operating expenses figure and is not a profit.","C":"$52,000 is the gross profit before the $39,000 of expenses is deducted.","D":"$91,000 subtracts only the $39,000 of expenses from revenue and ignores cost of sales."}}},{"id":"P1_U5_MCQ_1389","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1389","question":"Kirtlington Kites has an acid test ratio of 0.8 and current liabilities of $50,000. Its inventory is valued at $20,000. What is its current ratio?","options":{"A":"0.50","B":"1.20","C":"0.80","D":"1.60"},"correctOption":"B","correctAnswer":"1.20","questionType":"MCQ","explanation":{"correct_reason":"Liquid assets are 0.8 times $50,000, which is $40,000, so adding the $20,000 of inventory gives current assets of $60,000 and a current ratio of 1.20.","distractor_reasons":{"A":"0.50 divides $25,000 by $50,000 and does not follow from the figures given.","B":"Liquid assets are 0.8 times $50,000, which is $40,000, so adding the $20,000 of inventory gives current assets of $60,000 and a current ratio of 1.20.","C":"0.80 is the acid test ratio already given, which leaves out inventory.","D":"1.60 would need current assets of $80,000 rather than the $60,000 calculated."}}},{"id":"P1_U5_MCQ_1390","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1390","question":"Finchingfield Fudge has revenue of $400,000 and operating profit of $44,000. Its capital employed is $220,000. What is its profit margin for the financial year just ended?","options":{"A":"5.5%","B":"20%","C":"11%","D":"44%"},"correctOption":"C","correctAnswer":"11%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is operating profit divided by revenue, so $44,000 divided by $400,000 gives 11%.","distractor_reasons":{"A":"5.5% is half the correct margin and does not come from $44,000 and $400,000.","B":"20% is the return on capital employed, $44,000 divided by $220,000.","C":"Profit margin is operating profit divided by revenue, so $44,000 divided by $400,000 gives 11%.","D":"44% repeats the operating profit as a percentage of $100,000 rather than of revenue."}}},{"id":"P1_U5_MCQ_1391","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1391","question":"Dunster Solar, a sole trader, needs $500,000 to build a solar farm that will operate for fifteen years. The owner wants the debt repaid gradually and refuses to sell any ownership. Which source is most suitable?","options":{"A":"An overdraft renewed monthly","B":"Selling shares to the public","C":"Extended trade credit","D":"A long-term bank loan"},"correctOption":"D","correctAnswer":"A long-term bank loan","questionType":"MCQ","explanation":{"correct_reason":"A long-term bank loan matches the fifteen-year life of the solar farm, is repaid gradually and does not require the owner to give up any ownership.","distractor_reasons":{"A":"An overdraft is short-term and repayable on demand, so it cannot fund a fifteen-year project.","B":"Selling shares would bring in outside owners, which the owner has refused.","C":"Trade credit only delays payment for supplies and cannot raise $500,000 for construction.","D":"A long-term bank loan matches the fifteen-year life of the solar farm, is repaid gradually and does not require the owner to give up any ownership."}}},{"id":"P1_U5_MCQ_1392","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1392","question":"Fenwick Framing forecasts net cash flows of $3,000 in July, minus $5,500 in August and $1,200 in September. What is the total net cash flow for the three months?","options":{"A":"-$1,300","B":"$1,300","C":"$9,700","D":"-$9,700"},"correctOption":"A","correctAnswer":"-$1,300","questionType":"MCQ","explanation":{"correct_reason":"Adding $3,000, minus $5,500 and $1,200 gives minus $1,300, so the quarter ends with a net cash outflow.","distractor_reasons":{"A":"Adding $3,000, minus $5,500 and $1,200 gives minus $1,300, so the quarter ends with a net cash outflow.","B":"$1,300 has the right size but the wrong sign, because the outflows exceed the inflows.","C":"$9,700 adds all three figures as positive amounts and ignores the August outflow.","D":"-$9,700 treats all three figures as outflows rather than including the two inflows."}}},{"id":"P1_U5_MCQ_1393","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1393","question":"Oakhanger Organics has revenue of $160,000, cost of sales of $96,000 and operating expenses of $40,000. It also receives rent of $8,000 from a sublet storeroom. What is its profit for the year?","options":{"A":"$16,000","B":"$24,000","C":"$32,000","D":"$40,000"},"correctOption":"C","correctAnswer":"$32,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $64,000, and after $40,000 of expenses the business has $24,000, to which the $8,000 of rent income is added, giving $32,000.","distractor_reasons":{"A":"$16,000 subtracts the rent income instead of adding it to the operating profit.","B":"$24,000 is the profit before the $8,000 of rent income is added.","C":"Gross profit is $64,000, and after $40,000 of expenses the business has $24,000, to which the $8,000 of rent income is added, giving $32,000.","D":"$40,000 is the operating expenses figure and is not a profit."}}},{"id":"P1_U5_MCQ_1394","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1394","question":"Lindfield Leather has total assets of $540,000, current liabilities of $90,000 and non-current liabilities of $160,000. What is its equity at the end of the financial year?","options":{"A":"$250,000","B":"$290,000","C":"$380,000","D":"$450,000"},"correctOption":"B","correctAnswer":"$290,000","questionType":"MCQ","explanation":{"correct_reason":"Equity is total assets less all liabilities, so $540,000 less $90,000 less $160,000 gives $290,000.","distractor_reasons":{"A":"$250,000 is the total of the two liability figures and is not the equity.","B":"Equity is total assets less all liabilities, so $540,000 less $90,000 less $160,000 gives $290,000.","C":"$380,000 deducts only the $160,000 of non-current liabilities.","D":"$450,000 deducts only the $90,000 of current liabilities."}}},{"id":"P1_U5_MCQ_1395","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1395","question":"Grimsdale Grills has current assets of $108,000, including inventory of $36,000, and current liabilities of $72,000. What is its acid test ratio at the year end?","options":{"A":"0.33","B":"0.67","C":"1.50","D":"1.00"},"correctOption":"D","correctAnswer":"1.00","questionType":"MCQ","explanation":{"correct_reason":"Removing $36,000 of inventory from $108,000 of current assets leaves $72,000, which divided by $72,000 of liabilities gives 1.00.","distractor_reasons":{"A":"0.33 divides the $36,000 of inventory by the $108,000 of current assets, which is not the acid test.","B":"0.67 divides the $36,000 of inventory by the $72,000 of liabilities and then misreads the result.","C":"1.50 is the current ratio, using all $108,000 of current assets without removing inventory.","D":"Removing $36,000 of inventory from $108,000 of current assets leaves $72,000, which divided by $72,000 of liabilities gives 1.00."}}},{"id":"P1_U5_MCQ_1396","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1396","question":"Ingleby Care has $30,000 of retained profit but needs $400,000 to buy two care homes. The owner wants to avoid borrowing and outside investors. Why is retained profit unsuitable here?","options":{"A":"The amount saved is far below the $400,000 needed","B":"It must be repaid to shareholders within a year","C":"It carries a high rate of interest","D":"It can only be spent on day-to-day expenses"},"correctOption":"A","correctAnswer":"The amount saved is far below the $400,000 needed","questionType":"MCQ","explanation":{"correct_reason":"Retained profit of $30,000 covers less than a tenth of the $400,000 purchase, so it cannot fund the two care homes on its own.","distractor_reasons":{"A":"Retained profit of $30,000 covers less than a tenth of the $400,000 purchase, so it cannot fund the two care homes on its own.","B":"Retained profit belongs to the business and is not repaid to shareholders within a year.","C":"Retained profit is internal finance and carries no interest charge at all.","D":"Retained profit can be spent on assets and expansion, not only on day-to-day expenses."}}},{"id":"P1_U5_MCQ_1397","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1397","question":"Larkspur Events records a profit of $9,000 for a wedding fair in May but its bank balance falls by $2,000. It paid a $15,000 venue deposit in May and will receive the balance in June. What explains this?","options":{"A":"The fair made a loss rather than a profit","B":"Profit is always lower than cash received","C":"Cash paid out in May exceeded cash received that month","D":"The venue deposit was not a business cost"},"correctOption":"C","correctAnswer":"Cash paid out in May exceeded cash received that month","questionType":"MCQ","explanation":{"correct_reason":"The $15,000 deposit left the bank account in May while the balance was still owed by the customer, so payments exceeded receipts even though the fair was profitable.","distractor_reasons":{"A":"A profit of $9,000 is recorded, so the fair did not make a loss on the event.","B":"Profit and cash are not ordered in that way; they measure different things.","C":"The $15,000 deposit left the bank account in May while the balance was still owed by the customer, so payments exceeded receipts even though the fair was profitable.","D":"The venue deposit is a genuine cost of running the fair, even though it is paid before the income arrives."}}},{"id":"P1_U5_MCQ_1398","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1398","question":"Prittlewell Pottery has revenue of $225,000 and a gross profit of $90,000. Next year revenue is expected to rise to $250,000 with the same gross profit margin. What gross profit is expected?","options":{"A":"$90,000","B":"$100,000","C":"$110,000","D":"$112,500"},"correctOption":"B","correctAnswer":"$100,000","questionType":"MCQ","explanation":{"correct_reason":"The current margin is $90,000 of $225,000, which is 40%, and 40% of the expected $250,000 revenue is $100,000.","distractor_reasons":{"A":"$90,000 keeps the old gross profit and ignores the rise in revenue.","B":"The current margin is $90,000 of $225,000, which is 40%, and 40% of the expected $250,000 revenue is $100,000.","C":"$110,000 would need a margin of 44% on the $250,000 of revenue.","D":"$112,500 is 45% of the expected revenue and is above the 40% margin."}}},{"id":"P1_U5_MCQ_1399","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1399","question":"Meonstoke Mills has inventory of $60,000, trade receivables of $28,000 and cash of $12,000. Its current liabilities are $50,000. What is its acid test ratio?","options":{"A":"1.20","B":"0.60","C":"1.40","D":"0.80"},"correctOption":"D","correctAnswer":"0.80","questionType":"MCQ","explanation":{"correct_reason":"Liquid assets are $28,000 of receivables plus $12,000 of cash, which is $40,000, and dividing by $50,000 of liabilities gives 0.80.","distractor_reasons":{"A":"1.20 would need liquid assets of $60,000, which is the inventory figure rather than the quick assets.","B":"0.60 divides the $60,000 of inventory by the $50,000 of liabilities and then halves it for no reason.","C":"1.40 would need liquid assets of $70,000 rather than the $40,000 calculated.","D":"Liquid assets are $28,000 of receivables plus $12,000 of cash, which is $40,000, and dividing by $50,000 of liabilities gives 0.80."}}},{"id":"P1_U5_MCQ_1400","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1400","question":"Hengistbury Hats has capital employed of $450,000 and a return on capital employed of 18% for the year. What is its operating profit for the financial year just ended?","options":{"A":"$81,000","B":"$8,100","C":"$25,000","D":"$45,000"},"correctOption":"A","correctAnswer":"$81,000","questionType":"MCQ","explanation":{"correct_reason":"Operating profit is 18% of the $450,000 of capital employed, which is $81,000.","distractor_reasons":{"A":"Operating profit is 18% of the $450,000 of capital employed, which is $81,000.","B":"$8,100 treats the 18% as 1.8% of capital employed, one tenth of the true rate.","C":"$25,000 divides the $450,000 of capital employed by 18 instead of multiplying it.","D":"$45,000 is 10% of capital employed, not the 18% return stated."}}},{"id":"P1_U5_MCQ_1401","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1401","question":"Alvercroft Bakery is a private limited company finalising its accounts for the year ended 31 December 2025. Current assets at the year end were $86,000 and current liabilities were $52,000. What is the working capital of the business?","options":{"A":"$138,000","B":"$34,000","C":"$52,000","D":"$86,000"},"correctOption":"B","correctAnswer":"$34,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital equals current assets of $86,000 minus current liabilities of $52,000, which gives $34,000; this is the money available to finance everyday operations.","distractor_reasons":{"A":"Adding current assets to current liabilities gives $138,000, but working capital is the surplus of liquid resources left after short-term debts are covered.","B":"Working capital equals current assets of $86,000 minus current liabilities of $52,000, which gives $34,000; this is the money available to finance everyday operations.","C":"The current liabilities of $52,000 are the obligations that must be settled, not the funds available for day-to-day operations.","D":"Current assets of $86,000 have not had the short-term debts deducted, so this overstates the money available for daily running costs."}}},{"id":"P1_U5_MCQ_1402","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1402","question":"Alverdale Timber prepares its annual accounts each year and is now reviewing the figures for the year just ended. Forecast cash inflows for the period are $96,000 and forecast cash outflows are $84,500. What is the net cash flow for the period?","options":{"A":"$11,500","B":"$180,500","C":"$84,500","D":"$96,000"},"correctOption":"A","correctAnswer":"$11,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is inflows of $96,000 minus outflows of $84,500, which gives $11,500, showing the movement in the cash balance for the period.","distractor_reasons":{"A":"Net cash flow is inflows of $96,000 minus outflows of $84,500, which gives $11,500, showing the movement in the cash balance for the period.","B":"Adding inflows to outflows gives $180,500, but net cash flow is found by subtracting payments from receipts rather than combining them.","C":"The payments of $84,500 are only one side of the forecast and must be set against the receipts to find the net movement.","D":"Receipts of $96,000 ignore the payments made in the same period, so this is not the net movement in cash."}}},{"id":"P1_U5_MCQ_1403","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1403","question":"Alverford Couriers has finished its trading year and its accountant is checking the main figures before they are published. Revenue for the year was $480,000 and cost of sales was $288,000. What is the gross profit for the year?","options":{"A":"$768,000","B":"$480,000","C":"$288,000","D":"$192,000"},"correctOption":"D","correctAnswer":"$192,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue of $480,000 minus cost of sales of $288,000, giving $192,000; it measures the profit from buying and selling before overhead expenses are charged.","distractor_reasons":{"A":"Adding revenue to cost of sales gives $768,000, but expenditure on goods sold must be deducted from revenue, not added to it.","B":"Revenue of $480,000 is total sales income and takes no account of the $288,000 spent on the goods that were sold.","C":"Cost of sales of $288,000 is the direct cost of the goods, so it is a deduction from revenue rather than a profit figure.","D":"Gross profit is revenue of $480,000 minus cost of sales of $288,000, giving $192,000; it measures the profit from buying and selling before overhead expenses are charged."}}},{"id":"P1_U5_MCQ_1404","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1404","question":"Alvergate Furniture is a private limited company finalising its accounts for the year ended 31 December 2025. Non-current assets are $640,000 and current assets are $260,000. What are the total assets shown in the statement of financial position?","options":{"A":"$380,000","B":"$260,000","C":"$900,000","D":"$640,000"},"correctOption":"C","correctAnswer":"$900,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are non-current assets of $640,000 plus current assets of $260,000, giving $900,000 of resources owned by the business.","distractor_reasons":{"A":"Subtracting current assets from non-current assets gives $380,000, but total assets add the two groups together.","B":"Current assets of $260,000 are only the short-term assets, so the non-current assets are left out.","C":"Total assets are non-current assets of $640,000 plus current assets of $260,000, giving $900,000 of resources owned by the business.","D":"Non-current assets of $640,000 are only the long-term assets, so the current assets are missing."}}},{"id":"P1_U5_MCQ_1405","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1405","question":"Alverholm Printing prepares its annual accounts each year and is now reviewing the figures for the year just ended. At the year end current assets were $240,000 and current liabilities were $150,000. What is the current ratio, to two decimal places?","options":{"A":"0.62 : 1","B":"1.60 : 1","C":"0.60 : 1","D":"0.38 : 1"},"correctOption":"B","correctAnswer":"1.60 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets of $240,000 divided by current liabilities of $150,000, which gives 1.60 : 1, showing how many dollars of short-term assets cover each dollar of short-term debt.","distractor_reasons":{"A":"This reverses the ratio by dividing liabilities by assets, but the current ratio compares assets with the liabilities they must cover.","B":"The current ratio is current assets of $240,000 divided by current liabilities of $150,000, which gives 1.60 : 1, showing how many dollars of short-term assets cover each dollar of short-term debt.","C":"This divides working capital by liabilities, which measures the surplus relative to debts rather than the ratio of assets to debts.","D":"This expresses working capital as a share of current assets, which is not the ratio of current assets to current liabilities."}}},{"id":"P1_U5_MCQ_1406","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1406","question":"Alvermere Hotels has finished its trading year and its accountant is checking the main figures before they are published. Current assets at the year end were $120,000 and current liabilities were $78,000. What is the working capital of the business?","options":{"A":"$42,000","B":"$198,000","C":"$78,000","D":"$120,000"},"correctOption":"A","correctAnswer":"$42,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital equals current assets of $120,000 minus current liabilities of $78,000, which gives $42,000; this is the money available to finance everyday operations.","distractor_reasons":{"A":"Working capital equals current assets of $120,000 minus current liabilities of $78,000, which gives $42,000; this is the money available to finance everyday operations.","B":"Adding current assets to current liabilities gives $198,000, but working capital is the surplus of liquid resources left after short-term debts are covered.","C":"The current liabilities of $78,000 are the obligations that must be settled, not the funds available for day-to-day operations.","D":"Current assets of $120,000 have not had the short-term debts deducted, so this overstates the money available for daily running costs."}}},{"id":"P1_U5_MCQ_1407","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1407","question":"Alverridge Foods is a private limited company finalising its accounts for the year ended 31 December 2025. Forecast cash inflows for the period are $182,000 and forecast cash outflows are $196,400. What is the net cash flow for the period?","options":{"A":"$378,400","B":"$196,400","C":"$182,000","D":"-$14,400"},"correctOption":"D","correctAnswer":"-$14,400","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is inflows of $182,000 minus outflows of $196,400, which gives -$14,400, showing the movement in the cash balance for the period.","distractor_reasons":{"A":"Adding inflows to outflows gives $378,400, but net cash flow is found by subtracting payments from receipts rather than combining them.","B":"The payments of $196,400 are only one side of the forecast and must be set against the receipts to find the net movement.","C":"Receipts of $182,000 ignore the payments made in the same period, so this is not the net movement in cash.","D":"Net cash flow is inflows of $182,000 minus outflows of $196,400, which gives -$14,400, showing the movement in the cash balance for the period."}}},{"id":"P1_U5_MCQ_1408","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1408","question":"Alvershaw Textiles prepares its annual accounts each year and is now reviewing the figures for the year just ended. Revenue for the year was $936,000 and cost of sales was $561,600. What is the gross profit for the year?","options":{"A":"$1,497,600","B":"$936,000","C":"$374,400","D":"$561,600"},"correctOption":"C","correctAnswer":"$374,400","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue of $936,000 minus cost of sales of $561,600, giving $374,400; it measures the profit from buying and selling before overhead expenses are charged.","distractor_reasons":{"A":"Adding revenue to cost of sales gives $1,497,600, but expenditure on goods sold must be deducted from revenue, not added to it.","B":"Revenue of $936,000 is total sales income and takes no account of the $561,600 spent on the goods that were sold.","C":"Gross profit is revenue of $936,000 minus cost of sales of $561,600, giving $374,400; it measures the profit from buying and selling before overhead expenses are charged.","D":"Cost of sales of $561,600 is the direct cost of the goods, so it is a deduction from revenue rather than a profit figure."}}},{"id":"P1_U5_MCQ_1409","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1409","question":"Alverwell Engineering has finished its trading year and its accountant is checking the main figures before they are published. Non-current assets are $1,240,000 and current assets are $480,000. What are the total assets shown in the statement of financial position?","options":{"A":"$760,000","B":"$1,720,000","C":"$480,000","D":"$1,240,000"},"correctOption":"B","correctAnswer":"$1,720,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are non-current assets of $1,240,000 plus current assets of $480,000, giving $1,720,000 of resources owned by the business.","distractor_reasons":{"A":"Subtracting current assets from non-current assets gives $760,000, but total assets add the two groups together.","B":"Total assets are non-current assets of $1,240,000 plus current assets of $480,000, giving $1,720,000 of resources owned by the business.","C":"Current assets of $480,000 are only the short-term assets, so the non-current assets are left out.","D":"Non-current assets of $1,240,000 are only the long-term assets, so the current assets are missing."}}},{"id":"P1_U5_MCQ_1410","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1410","question":"Alverwick Motors is a private limited company finalising its accounts for the year ended 31 December 2025. At the year end current assets were $315,000 and current liabilities were $126,000. What is the current ratio, to two decimal places?","options":{"A":"2.50 : 1","B":"0.40 : 1","C":"1.50 : 1","D":"0.60 : 1"},"correctOption":"A","correctAnswer":"2.50 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets of $315,000 divided by current liabilities of $126,000, which gives 2.50 : 1, showing how many dollars of short-term assets cover each dollar of short-term debt.","distractor_reasons":{"A":"The current ratio is current assets of $315,000 divided by current liabilities of $126,000, which gives 2.50 : 1, showing how many dollars of short-term assets cover each dollar of short-term debt.","B":"This reverses the ratio by dividing liabilities by assets, but the current ratio compares assets with the liabilities they must cover.","C":"This divides working capital by liabilities, which measures the surplus relative to debts rather than the ratio of assets to debts.","D":"This expresses working capital as a share of current assets, which is not the ratio of current assets to current liabilities."}}},{"id":"P1_U5_MCQ_1411","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1411","question":"Brindlecroft Cafes prepares its annual accounts each year and is now reviewing the figures for the year just ended. The business borrows $60,000 from its bank at a fixed annual interest rate of 7%. How much interest will it pay in the first year?","options":{"A":"$60,000","B":"$350.00","C":"$64,200","D":"$4,200"},"correctOption":"D","correctAnswer":"$4,200","questionType":"MCQ","explanation":{"correct_reason":"Annual interest is 7% of the $60,000 borrowed, which is $4,200; the principal itself is not an interest cost and is repaid separately.","distractor_reasons":{"A":"The sum of $60,000 is the amount borrowed, so it is the principal rather than the annual interest charge on the loan.","B":"This is one month of interest on the loan, but the question asks for the total interest charged across the whole first year.","C":"This figure includes repayment of the principal as well as the interest, so it is the total outflow rather than the interest cost alone.","D":"Annual interest is 7% of the $60,000 borrowed, which is $4,200; the principal itself is not an interest cost and is repaid separately."}}},{"id":"P1_U5_MCQ_1412","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1412","question":"Brindledale Clinics has finished its trading year and its accountant is checking the main figures before they are published. Forecast cash inflows for the period are $74,800 and forecast cash outflows are $61,300. What is the net cash flow for the period?","options":{"A":"$136,100","B":"$61,300","C":"$13,500","D":"$74,800"},"correctOption":"C","correctAnswer":"$13,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is inflows of $74,800 minus outflows of $61,300, which gives $13,500, showing the movement in the cash balance for the period.","distractor_reasons":{"A":"Adding inflows to outflows gives $136,100, but net cash flow is found by subtracting payments from receipts rather than combining them.","B":"The payments of $61,300 are only one side of the forecast and must be set against the receipts to find the net movement.","C":"Net cash flow is inflows of $74,800 minus outflows of $61,300, which gives $13,500, showing the movement in the cash balance for the period.","D":"Receipts of $74,800 ignore the payments made in the same period, so this is not the net movement in cash."}}},{"id":"P1_U5_MCQ_1413","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1413","question":"Brindleford Farms is a private limited company finalising its accounts for the year ended 31 December 2025. Revenue for the year was $1,250,000 and cost of sales was $812,500. What is the gross profit for the year?","options":{"A":"$2,062,500","B":"$437,500","C":"$1,250,000","D":"$812,500"},"correctOption":"B","correctAnswer":"$437,500","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue of $1,250,000 minus cost of sales of $812,500, giving $437,500; it measures the profit from buying and selling before overhead expenses are charged.","distractor_reasons":{"A":"Adding revenue to cost of sales gives $2,062,500, but expenditure on goods sold must be deducted from revenue, not added to it.","B":"Gross profit is revenue of $1,250,000 minus cost of sales of $812,500, giving $437,500; it measures the profit from buying and selling before overhead expenses are charged.","C":"Revenue of $1,250,000 is total sales income and takes no account of the $812,500 spent on the goods that were sold.","D":"Cost of sales of $812,500 is the direct cost of the goods, so it is a deduction from revenue rather than a profit figure."}}},{"id":"P1_U5_MCQ_1414","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1414","question":"Brindlegate Stores prepares its annual accounts each year and is now reviewing the figures for the year just ended. Non-current assets are $385,000 and current assets are $145,000. What are the total assets shown in the statement of financial position?","options":{"A":"$530,000","B":"$240,000","C":"$145,000","D":"$385,000"},"correctOption":"A","correctAnswer":"$530,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are non-current assets of $385,000 plus current assets of $145,000, giving $530,000 of resources owned by the business.","distractor_reasons":{"A":"Total assets are non-current assets of $385,000 plus current assets of $145,000, giving $530,000 of resources owned by the business.","B":"Subtracting current assets from non-current assets gives $240,000, but total assets add the two groups together.","C":"Current assets of $145,000 are only the short-term assets, so the non-current assets are left out.","D":"Non-current assets of $385,000 are only the long-term assets, so the current assets are missing."}}},{"id":"P1_U5_MCQ_1415","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1415","question":"Brindleholm Systems has finished its trading year and its accountant is checking the main figures before they are published. At the year end current assets were $168,000 and current liabilities were $140,000. What is the current ratio, to two decimal places?","options":{"A":"0.83 : 1","B":"0.20 : 1","C":"0.17 : 1","D":"1.20 : 1"},"correctOption":"D","correctAnswer":"1.20 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets of $168,000 divided by current liabilities of $140,000, which gives 1.20 : 1, showing how many dollars of short-term assets cover each dollar of short-term debt.","distractor_reasons":{"A":"This reverses the ratio by dividing liabilities by assets, but the current ratio compares assets with the liabilities they must cover.","B":"This divides working capital by liabilities, which measures the surplus relative to debts rather than the ratio of assets to debts.","C":"This expresses working capital as a share of current assets, which is not the ratio of current assets to current liabilities.","D":"The current ratio is current assets of $168,000 divided by current liabilities of $140,000, which gives 1.20 : 1, showing how many dollars of short-term assets cover each dollar of short-term debt."}}},{"id":"P1_U5_MCQ_1416","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1416","question":"Brindlemere Studios is a private limited company finalising its accounts for the year ended 31 December 2025. The business borrows $150,000 from its bank at a fixed annual interest rate of 6.5%. How much interest will it pay in the first year?","options":{"A":"$150,000","B":"$812.50","C":"$9,750","D":"$159,750"},"correctOption":"C","correctAnswer":"$9,750","questionType":"MCQ","explanation":{"correct_reason":"Annual interest is 6.5% of the $150,000 borrowed, which is $9,750; the principal itself is not an interest cost and is repaid separately.","distractor_reasons":{"A":"The sum of $150,000 is the amount borrowed, so it is the principal rather than the annual interest charge on the loan.","B":"This is one month of interest on the loan, but the question asks for the total interest charged across the whole first year.","C":"Annual interest is 6.5% of the $150,000 borrowed, which is $9,750; the principal itself is not an interest cost and is repaid separately.","D":"This figure includes repayment of the principal as well as the interest, so it is the total outflow rather than the interest cost alone."}}},{"id":"P1_U5_MCQ_1417","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1417","question":"Brindleridge Packaging prepares its annual accounts each year and is now reviewing the figures for the year just ended. The opening cash balance is $18,000 and the forecast net cash flow for the month is $11,500. What is the forecast closing cash balance?","options":{"A":"$6,500","B":"$29,500","C":"$11,500","D":"$18,000"},"correctOption":"B","correctAnswer":"$29,500","questionType":"MCQ","explanation":{"correct_reason":"The closing balance is the opening balance of $18,000 plus the net cash flow of $11,500, giving $29,500 at the end of the period.","distractor_reasons":{"A":"Subtracting the net cash flow of $11,500 reverses the movement, but a positive net cash flow should be added to the opening balance.","B":"The closing balance is the opening balance of $18,000 plus the net cash flow of $11,500, giving $29,500 at the end of the period.","C":"The net cash flow of $11,500 is only the change during the month, not the balance left at the end of it.","D":"The opening balance of $18,000 is the starting point, so leaving it unchanged ignores the month's cash movement."}}},{"id":"P1_U5_MCQ_1418","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1418","question":"Brindleshaw Chemicals has finished its trading year and its accountant is checking the main figures before they are published. Revenue for the year was $640,000 and gross profit was $224,000. What was the cost of sales?","options":{"A":"$416,000","B":"$864,000","C":"$224,000","D":"$640,000"},"correctOption":"A","correctAnswer":"$416,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is revenue of $640,000 minus gross profit of $224,000, which gives $416,000; this is the direct cost of the goods actually sold during the year.","distractor_reasons":{"A":"Cost of sales is revenue of $640,000 minus gross profit of $224,000, which gives $416,000; this is the direct cost of the goods actually sold during the year.","B":"Adding gross profit to revenue gives $864,000, which treats profit as a cost instead of deducting it.","C":"Gross profit of $224,000 is what remains after the direct cost, so it cannot also be the cost itself.","D":"Revenue of $640,000 is the total sales income before any direct cost of the goods is taken off."}}},{"id":"P1_U5_MCQ_1419","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1419","question":"Brindlewell Pharmacy is a private limited company finalising its accounts for the year ended 31 December 2025. Total assets are $860,000 and total liabilities are $345,000. What is the total equity of the business?","options":{"A":"$1,205,000","B":"$345,000","C":"$860,000","D":"$515,000"},"correctOption":"D","correctAnswer":"$515,000","questionType":"MCQ","explanation":{"correct_reason":"Total equity is total assets of $860,000 minus total liabilities of $345,000, giving $515,000, which is the owners' stake in the business.","distractor_reasons":{"A":"Adding liabilities to assets gives $1,205,000, but liabilities are claims on the assets and must be deducted.","B":"Total liabilities of $345,000 are what the business owes, not the owners' stake in the assets.","C":"Total assets of $860,000 include resources financed by lenders, so they overstate the owners' equity.","D":"Total equity is total assets of $860,000 minus total liabilities of $345,000, giving $515,000, which is the owners' stake in the business."}}},{"id":"P1_U5_MCQ_1420","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1420","question":"Brindlewick Fitness prepares its annual accounts each year and is now reviewing the figures for the year just ended. At the year end current assets were $432,000 and current liabilities were $180,000. What is the current ratio, to two decimal places?","options":{"A":"0.42 : 1","B":"1.40 : 1","C":"2.40 : 1","D":"0.58 : 1"},"correctOption":"C","correctAnswer":"2.40 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets of $432,000 divided by current liabilities of $180,000, which gives 2.40 : 1, showing how many dollars of short-term assets cover each dollar of short-term debt.","distractor_reasons":{"A":"This reverses the ratio by dividing liabilities by assets, but the current ratio compares assets with the liabilities they must cover.","B":"This divides working capital by liabilities, which measures the surplus relative to debts rather than the ratio of assets to debts.","C":"The current ratio is current assets of $432,000 divided by current liabilities of $180,000, which gives 2.40 : 1, showing how many dollars of short-term assets cover each dollar of short-term debt.","D":"This expresses working capital as a share of current assets, which is not the ratio of current assets to current liabilities."}}},{"id":"P1_U5_MCQ_1421","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1421","question":"Cothamcroft Nurseries has finished its trading year and its accountant is checking the main figures before they are published. A loan of $80,000 is taken out at 5% simple interest a year and is repaid in full after 3 years. What is the total amount repayable, including interest?","options":{"A":"$80,000","B":"$92,000","C":"$12,000","D":"$84,000"},"correctOption":"B","correctAnswer":"$92,000","questionType":"MCQ","explanation":{"correct_reason":"Interest is $80,000 x 5% x 3 years = $12,000, so the total repayable is the $80,000 loan plus $12,000, which is $92,000.","distractor_reasons":{"A":"This is only the original loan, so it omits the interest charged over the 3 years of the agreement.","B":"Interest is $80,000 x 5% x 3 years = $12,000, so the total repayable is the $80,000 loan plus $12,000, which is $92,000.","C":"This is the interest alone and leaves out the $80,000 of principal that must also be repaid at the end of the term.","D":"This adds only one year of interest to the loan, but interest is charged in each of the 3 years."}}},{"id":"P1_U5_MCQ_1422","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1422","question":"Cothamdale Builders is a private limited company finalising its accounts for the year ended 31 December 2025. The opening cash balance is $24,600 and the forecast net cash flow for the month is -$14,400. What is the forecast closing cash balance?","options":{"A":"$10,200","B":"$39,000","C":"-$14,400","D":"$24,600"},"correctOption":"A","correctAnswer":"$10,200","questionType":"MCQ","explanation":{"correct_reason":"The closing balance is the opening balance of $24,600 plus the net cash flow of -$14,400, giving $10,200 at the end of the period.","distractor_reasons":{"A":"The closing balance is the opening balance of $24,600 plus the net cash flow of -$14,400, giving $10,200 at the end of the period.","B":"Subtracting the net cash flow of -$14,400 reverses the movement, but a positive net cash flow should be added to the opening balance.","C":"The net cash flow of -$14,400 is only the change during the month, not the balance left at the end of it.","D":"The opening balance of $24,600 is the starting point, so leaving it unchanged ignores the month's cash movement."}}},{"id":"P1_U5_MCQ_1423","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1423","question":"Cothamford Energy prepares its annual accounts each year and is now reviewing the figures for the year just ended. Revenue for the year was $1,080,000 and gross profit was $405,000. What was the cost of sales?","options":{"A":"$1,485,000","B":"$405,000","C":"$1,080,000","D":"$675,000"},"correctOption":"D","correctAnswer":"$675,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is revenue of $1,080,000 minus gross profit of $405,000, which gives $675,000; this is the direct cost of the goods actually sold during the year.","distractor_reasons":{"A":"Adding gross profit to revenue gives $1,485,000, which treats profit as a cost instead of deducting it.","B":"Gross profit of $405,000 is what remains after the direct cost, so it cannot also be the cost itself.","C":"Revenue of $1,080,000 is the total sales income before any direct cost of the goods is taken off.","D":"Cost of sales is revenue of $1,080,000 minus gross profit of $405,000, which gives $675,000; this is the direct cost of the goods actually sold during the year."}}},{"id":"P1_U5_MCQ_1424","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1424","question":"Cothamgate Media has finished its trading year and its accountant is checking the main figures before they are published. Total assets are $1,450,000 and total liabilities are $612,000. What is the total equity of the business?","options":{"A":"$2,062,000","B":"$612,000","C":"$838,000","D":"$1,450,000"},"correctOption":"C","correctAnswer":"$838,000","questionType":"MCQ","explanation":{"correct_reason":"Total equity is total assets of $1,450,000 minus total liabilities of $612,000, giving $838,000, which is the owners' stake in the business.","distractor_reasons":{"A":"Adding liabilities to assets gives $2,062,000, but liabilities are claims on the assets and must be deducted.","B":"Total liabilities of $612,000 are what the business owes, not the owners' stake in the assets.","C":"Total equity is total assets of $1,450,000 minus total liabilities of $612,000, giving $838,000, which is the owners' stake in the business.","D":"Total assets of $1,450,000 include resources financed by lenders, so they overstate the owners' equity."}}},{"id":"P1_U5_MCQ_1425","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1425","question":"Cothamholm Toys is a private limited company finalising its accounts for the year ended 31 December 2025. Current assets are $240,000, including inventory of $90,000, and current liabilities are $150,000. What is the acid test ratio, to two decimal places?","options":{"A":"1.60 : 1","B":"1.00 : 1","C":"2.20 : 1","D":"0.60 : 1"},"correctOption":"B","correctAnswer":"1.00 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test ratio is current assets of $240,000 minus inventory of $90,000, divided by current liabilities of $150,000, giving 1.00 : 1.","distractor_reasons":{"A":"This is the current ratio, which includes inventory, but the acid test excludes stock because it may be slow to sell.","B":"The acid test ratio is current assets of $240,000 minus inventory of $90,000, divided by current liabilities of $150,000, giving 1.00 : 1.","C":"This adds inventory to current assets instead of removing it, which overstates the liquid assets available to pay debts.","D":"This compares inventory alone with liabilities, whereas the acid test compares the remaining liquid assets with liabilities."}}},{"id":"P1_U5_MCQ_1426","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1426","question":"Cothammere Travel prepares its annual accounts each year and is now reviewing the figures for the year just ended. A loan of $120,000 is taken out at 4.5% simple interest a year and is repaid in full after 4 years. What is the total amount repayable, including interest?","options":{"A":"$141,600","B":"$120,000","C":"$21,600","D":"$125,400"},"correctOption":"A","correctAnswer":"$141,600","questionType":"MCQ","explanation":{"correct_reason":"Interest is $120,000 x 4.5% x 4 years = $21,600, so the total repayable is the $120,000 loan plus $21,600, which is $141,600.","distractor_reasons":{"A":"Interest is $120,000 x 4.5% x 4 years = $21,600, so the total repayable is the $120,000 loan plus $21,600, which is $141,600.","B":"This is only the original loan, so it omits the interest charged over the 4 years of the agreement.","C":"This is the interest alone and leaves out the $120,000 of principal that must also be repaid at the end of the term.","D":"This adds only one year of interest to the loan, but interest is charged in each of the 4 years."}}},{"id":"P1_U5_MCQ_1427","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1427","question":"Cothamridge Salons has finished its trading year and its accountant is checking the main figures before they are published. The business begins the month with an overdraft, so its opening cash balance is -$6,500, and the forecast net cash flow for the month is $13,500. What is the forecast closing cash balance?","options":{"A":"-$20,000","B":"$13,500","C":"-$6,500","D":"$7,000"},"correctOption":"D","correctAnswer":"$7,000","questionType":"MCQ","explanation":{"correct_reason":"The closing balance is the opening balance of -$6,500 plus the net cash flow of $13,500, giving $7,000 at the end of the period.","distractor_reasons":{"A":"Subtracting the net cash flow of $13,500 reverses the movement, but a positive net cash flow should be added to the opening balance.","B":"The net cash flow of $13,500 is only the change during the month, not the balance left at the end of it.","C":"The opening balance of -$6,500 is the starting point, so leaving it unchanged ignores the month's cash movement.","D":"The closing balance is the opening balance of -$6,500 plus the net cash flow of $13,500, giving $7,000 at the end of the period."}}},{"id":"P1_U5_MCQ_1428","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1428","question":"Cothamshaw Dairy is a private limited company finalising its accounts for the year ended 31 December 2025. Revenue for the year was $750,000 and gross profit was $180,000. What was the cost of sales?","options":{"A":"$930,000","B":"$180,000","C":"$570,000","D":"$750,000"},"correctOption":"C","correctAnswer":"$570,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is revenue of $750,000 minus gross profit of $180,000, which gives $570,000; this is the direct cost of the goods actually sold during the year.","distractor_reasons":{"A":"Adding gross profit to revenue gives $930,000, which treats profit as a cost instead of deducting it.","B":"Gross profit of $180,000 is what remains after the direct cost, so it cannot also be the cost itself.","C":"Cost of sales is revenue of $750,000 minus gross profit of $180,000, which gives $570,000; this is the direct cost of the goods actually sold during the year.","D":"Revenue of $750,000 is the total sales income before any direct cost of the goods is taken off."}}},{"id":"P1_U5_MCQ_1429","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1429","question":"Cothamwell Brewing prepares its annual accounts each year and is now reviewing the figures for the year just ended. Total assets are $672,000 and total liabilities are $248,000. What is the total equity of the business?","options":{"A":"$920,000","B":"$424,000","C":"$248,000","D":"$672,000"},"correctOption":"B","correctAnswer":"$424,000","questionType":"MCQ","explanation":{"correct_reason":"Total equity is total assets of $672,000 minus total liabilities of $248,000, giving $424,000, which is the owners' stake in the business.","distractor_reasons":{"A":"Adding liabilities to assets gives $920,000, but liabilities are claims on the assets and must be deducted.","B":"Total equity is total assets of $672,000 minus total liabilities of $248,000, giving $424,000, which is the owners' stake in the business.","C":"Total liabilities of $248,000 are what the business owes, not the owners' stake in the assets.","D":"Total assets of $672,000 include resources financed by lenders, so they overstate the owners' equity."}}},{"id":"P1_U5_MCQ_1430","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1430","question":"Cothamwick Marine has finished its trading year and its accountant is checking the main figures before they are published. Current assets are $315,000, including inventory of $135,000, and current liabilities are $126,000. What is the acid test ratio, to two decimal places?","options":{"A":"1.43 : 1","B":"2.50 : 1","C":"3.57 : 1","D":"1.07 : 1"},"correctOption":"A","correctAnswer":"1.43 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test ratio is current assets of $315,000 minus inventory of $135,000, divided by current liabilities of $126,000, giving 1.43 : 1.","distractor_reasons":{"A":"The acid test ratio is current assets of $315,000 minus inventory of $135,000, divided by current liabilities of $126,000, giving 1.43 : 1.","B":"This is the current ratio, which includes inventory, but the acid test excludes stock because it may be slow to sell.","C":"This adds inventory to current assets instead of removing it, which overstates the liquid assets available to pay debts.","D":"This compares inventory alone with liabilities, whereas the acid test compares the remaining liquid assets with liabilities."}}},{"id":"P1_U5_MCQ_1431","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1431","question":"Dunmoorcroft Bakery needs a cutting machine costing $250,000 that will be used for about ten years, and it wants repayments spread over the whole life of the asset. Which source of finance is most suitable?","options":{"A":"A bank overdraft","B":"Trade credit from a supplier","C":"Selling part of its inventory","D":"A ten-year bank loan"},"correctOption":"D","correctAnswer":"A ten-year bank loan","questionType":"MCQ","explanation":{"correct_reason":"A ten-year bank loan matches the long life of the machine, spreads the $250,000 cost over the years that benefit from it and avoids the immediate repayment pressure of short-term borrowing.","distractor_reasons":{"A":"An overdraft is repayable on demand and is designed for short-term gaps, so funding a ten-year machine with it creates constant refinancing pressure.","B":"Trade credit only delays payment for supplies by a few weeks and could never cover the $250,000 cost of the machine.","C":"Selling stock raises only a limited one-off sum and would leave the business short of the goods it needs to trade.","D":"A ten-year bank loan matches the long life of the machine, spreads the $250,000 cost over the years that benefit from it and avoids the immediate repayment pressure of short-term borrowing."}}},{"id":"P1_U5_MCQ_1432","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1432","question":"Dunmoordale Timber prepares its annual accounts each year and is now reviewing the figures for the year just ended. The forecast shows cash sales of $68,000, a bank loan received of $25,000 and the sale of an old machine for $9,000. What are the total forecast cash inflows?","options":{"A":"$68,000","B":"$93,000","C":"$102,000","D":"$34,000"},"correctOption":"C","correctAnswer":"$102,000","questionType":"MCQ","explanation":{"correct_reason":"All three receipts are cash inflows, so $68,000 plus $25,000 plus $9,000 gives total inflows of $102,000.","distractor_reasons":{"A":"Cash sales of $68,000 are only one inflow, so the loan and the machine sale are left out of the total.","B":"This adds the sales and the loan but omits the $9,000 received from selling the old machine.","C":"All three receipts are cash inflows, so $68,000 plus $25,000 plus $9,000 gives total inflows of $102,000.","D":"This adds the loan and the machine sale but leaves out the $68,000 of cash sales from normal trading."}}},{"id":"P1_U5_MCQ_1433","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1433","question":"Dunmoorford Couriers has finished its trading year and its accountant is checking the main figures before they are published. Gross profit for the year was $192,000 and operating expenses totalled $126,000. What is the profit for the year?","options":{"A":"$318,000","B":"$66,000","C":"$192,000","D":"$126,000"},"correctOption":"B","correctAnswer":"$66,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is gross profit of $192,000 minus operating expenses of $126,000, giving $66,000 after all the overhead costs of running the business.","distractor_reasons":{"A":"Adding expenses to gross profit gives $318,000, but expenses reduce profit and must be subtracted.","B":"Profit for the year is gross profit of $192,000 minus operating expenses of $126,000, giving $66,000 after all the overhead costs of running the business.","C":"Gross profit of $192,000 is the figure before expenses, so it overstates the profit actually earned.","D":"Operating expenses of $126,000 are a cost of running the business, not the profit left for the owners."}}},{"id":"P1_U5_MCQ_1434","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1434","question":"Dunmoorgate Furniture is a private limited company finalising its accounts for the year ended 31 December 2025. Inventory is $96,000, trade receivables are $64,000 and cash at bank is $40,000. What are the total current assets?","options":{"A":"$200,000","B":"$160,000","C":"$104,000","D":"$96,000"},"correctOption":"A","correctAnswer":"$200,000","questionType":"MCQ","explanation":{"correct_reason":"Current assets are inventory of $96,000 plus receivables of $64,000 plus cash of $40,000, giving $200,000 of assets expected to turn into cash within a year.","distractor_reasons":{"A":"Current assets are inventory of $96,000 plus receivables of $64,000 plus cash of $40,000, giving $200,000 of assets expected to turn into cash within a year.","B":"This adds inventory and receivables but leaves out the $40,000 of cash at the bank.","C":"Receivables and cash are included, but the $96,000 of inventory is also a current asset and is omitted.","D":"Inventory of $96,000 is only one current asset, so receivables and cash are missing from the total."}}},{"id":"P1_U5_MCQ_1435","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1435","question":"Dunmoorholm Printing prepares its annual accounts each year and is now reviewing the figures for the year just ended. Current assets are $168,000, including inventory of $63,000, and current liabilities are $210,000. What is the acid test ratio, to two decimal places?","options":{"A":"0.80 : 1","B":"1.10 : 1","C":"0.30 : 1","D":"0.50 : 1"},"correctOption":"D","correctAnswer":"0.50 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test ratio is current assets of $168,000 minus inventory of $63,000, divided by current liabilities of $210,000, giving 0.50 : 1.","distractor_reasons":{"A":"This is the current ratio, which includes inventory, but the acid test excludes stock because it may be slow to sell.","B":"This adds inventory to current assets instead of removing it, which overstates the liquid assets available to pay debts.","C":"This compares inventory alone with liabilities, whereas the acid test compares the remaining liquid assets with liabilities.","D":"The acid test ratio is current assets of $168,000 minus inventory of $63,000, divided by current liabilities of $210,000, giving 0.50 : 1."}}},{"id":"P1_U5_MCQ_1436","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1436","question":"Dunmoormere Hotels is a sole trader that needs $30,000 for new equipment. The owner has $12,000 of personal savings, but the bank will not lend because the business has no trading record. Which source of finance is internal?","options":{"A":"A bank loan","B":"A share issue","C":"The owner's savings","D":"A debenture"},"correctOption":"C","correctAnswer":"The owner's savings","questionType":"MCQ","explanation":{"correct_reason":"The owner's own savings of $12,000 come from inside the business's owners rather than a lender, so they are internal finance that carries no interest charge.","distractor_reasons":{"A":"A bank loan is external finance provided by a lender, and the bank has already refused to lend without a trading record.","B":"A sole trader cannot issue shares to the public, so this source is not legally available to this form of business.","C":"The owner's own savings of $12,000 come from inside the business's owners rather than a lender, so they are internal finance that carries no interest charge.","D":"A debenture is a long-term loan raised by a company, not a source open to a sole trader with no trading history."}}},{"id":"P1_U5_MCQ_1437","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1437","question":"Dunmoorridge Foods is a private limited company finalising its accounts for the year ended 31 December 2025. The forecast shows cash sales of $145,000, a bank loan received of $40,000 and the sale of an old machine for $18,000. What are the total forecast cash inflows?","options":{"A":"$145,000","B":"$203,000","C":"$185,000","D":"$58,000"},"correctOption":"B","correctAnswer":"$203,000","questionType":"MCQ","explanation":{"correct_reason":"All three receipts are cash inflows, so $145,000 plus $40,000 plus $18,000 gives total inflows of $203,000.","distractor_reasons":{"A":"Cash sales of $145,000 are only one inflow, so the loan and the machine sale are left out of the total.","B":"All three receipts are cash inflows, so $145,000 plus $40,000 plus $18,000 gives total inflows of $203,000.","C":"This adds the sales and the loan but omits the $18,000 received from selling the old machine.","D":"This adds the loan and the machine sale but leaves out the $145,000 of cash sales from normal trading."}}},{"id":"P1_U5_MCQ_1438","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1438","question":"Dunmoorshaw Textiles prepares its annual accounts each year and is now reviewing the figures for the year just ended. Gross profit for the year was $374,400 and operating expenses totalled $214,400. What is the profit for the year?","options":{"A":"$160,000","B":"$588,800","C":"$374,400","D":"$214,400"},"correctOption":"A","correctAnswer":"$160,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is gross profit of $374,400 minus operating expenses of $214,400, giving $160,000 after all the overhead costs of running the business.","distractor_reasons":{"A":"Profit for the year is gross profit of $374,400 minus operating expenses of $214,400, giving $160,000 after all the overhead costs of running the business.","B":"Adding expenses to gross profit gives $588,800, but expenses reduce profit and must be subtracted.","C":"Gross profit of $374,400 is the figure before expenses, so it overstates the profit actually earned.","D":"Operating expenses of $214,400 are a cost of running the business, not the profit left for the owners."}}},{"id":"P1_U5_MCQ_1439","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1439","question":"Dunmoorwell Engineering has finished its trading year and its accountant is checking the main figures before they are published. Inventory is $180,000, trade receivables are $95,000 and cash at bank is $25,000. What are the total current assets?","options":{"A":"$275,000","B":"$120,000","C":"$180,000","D":"$300,000"},"correctOption":"D","correctAnswer":"$300,000","questionType":"MCQ","explanation":{"correct_reason":"Current assets are inventory of $180,000 plus receivables of $95,000 plus cash of $25,000, giving $300,000 of assets expected to turn into cash within a year.","distractor_reasons":{"A":"This adds inventory and receivables but leaves out the $25,000 of cash at the bank.","B":"Receivables and cash are included, but the $180,000 of inventory is also a current asset and is omitted.","C":"Inventory of $180,000 is only one current asset, so receivables and cash are missing from the total.","D":"Current assets are inventory of $180,000 plus receivables of $95,000 plus cash of $25,000, giving $300,000 of assets expected to turn into cash within a year."}}},{"id":"P1_U5_MCQ_1440","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1440","question":"Dunmoorwick Motors is a private limited company finalising its accounts for the year ended 31 December 2025. Current assets are $432,000, including inventory of $162,000, and current liabilities are $180,000. What is the acid test ratio, to two decimal places?","options":{"A":"2.40 : 1","B":"3.30 : 1","C":"1.50 : 1","D":"0.90 : 1"},"correctOption":"C","correctAnswer":"1.50 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test ratio is current assets of $432,000 minus inventory of $162,000, divided by current liabilities of $180,000, giving 1.50 : 1.","distractor_reasons":{"A":"This is the current ratio, which includes inventory, but the acid test excludes stock because it may be slow to sell.","B":"This adds inventory to current assets instead of removing it, which overstates the liquid assets available to pay debts.","C":"The acid test ratio is current assets of $432,000 minus inventory of $162,000, divided by current liabilities of $180,000, giving 1.50 : 1.","D":"This compares inventory alone with liabilities, whereas the acid test compares the remaining liquid assets with liabilities."}}},{"id":"P1_U5_MCQ_1441","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1441","question":"Elvercroft Cafes needs $20,000 for six weeks to pay wages before a large customer settles its invoice. Which source of finance is most appropriate for this short-term gap?","options":{"A":"A five-year bank loan","B":"A bank overdraft","C":"Issuing new shares","D":"A debenture"},"correctOption":"B","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"A bank overdraft is short-term, flexible finance that can cover the $20,000 wages gap for six weeks and be cleared once the customer pays.","distractor_reasons":{"A":"A five-year loan is long-term finance, so it would leave the business paying interest long after the six-week gap has closed.","B":"A bank overdraft is short-term, flexible finance that can cover the $20,000 wages gap for six weeks and be cleared once the customer pays.","C":"Issuing shares raises permanent capital and is far too slow and costly for a six-week shortage of $20,000.","D":"A debenture is a long-term secured loan, which is unsuitable for a short delay in receiving a customer payment."}}},{"id":"P1_U5_MCQ_1442","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1442","question":"Elverdale Clinics has finished its trading year and its accountant is checking the main figures before they are published. Forecast payments include wages of $42,000, raw materials of $31,000 and rent of $8,000. What are the total forecast cash outflows?","options":{"A":"$81,000","B":"$42,000","C":"$73,000","D":"$39,000"},"correctOption":"A","correctAnswer":"$81,000","questionType":"MCQ","explanation":{"correct_reason":"The three payments are all cash outflows, so $42,000 plus $31,000 plus $8,000 gives total outflows of $81,000.","distractor_reasons":{"A":"The three payments are all cash outflows, so $42,000 plus $31,000 plus $8,000 gives total outflows of $81,000.","B":"Wages of $42,000 cover only the staff cost, so materials and rent are missing from the total.","C":"This adds wages and materials but ignores the $8,000 of rent, which is also a cash payment.","D":"Materials and rent are included, but the $42,000 wage bill is left out of the outflow total."}}},{"id":"P1_U5_MCQ_1443","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1443","question":"Elverford Farms is a private limited company finalising its accounts for the year ended 31 December 2025. Gross profit for the year was $437,500 and operating expenses totalled $287,500. What is the profit for the year?","options":{"A":"$725,000","B":"$437,500","C":"$287,500","D":"$150,000"},"correctOption":"D","correctAnswer":"$150,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is gross profit of $437,500 minus operating expenses of $287,500, giving $150,000 after all the overhead costs of running the business.","distractor_reasons":{"A":"Adding expenses to gross profit gives $725,000, but expenses reduce profit and must be subtracted.","B":"Gross profit of $437,500 is the figure before expenses, so it overstates the profit actually earned.","C":"Operating expenses of $287,500 are a cost of running the business, not the profit left for the owners.","D":"Profit for the year is gross profit of $437,500 minus operating expenses of $287,500, giving $150,000 after all the overhead costs of running the business."}}},{"id":"P1_U5_MCQ_1444","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1444","question":"Elvergate Stores prepares its annual accounts each year and is now reviewing the figures for the year just ended. Inventory is $54,000, trade receivables are $38,000 and cash at bank is $12,000. What are the total current assets?","options":{"A":"$92,000","B":"$50,000","C":"$104,000","D":"$54,000"},"correctOption":"C","correctAnswer":"$104,000","questionType":"MCQ","explanation":{"correct_reason":"Current assets are inventory of $54,000 plus receivables of $38,000 plus cash of $12,000, giving $104,000 of assets expected to turn into cash within a year.","distractor_reasons":{"A":"This adds inventory and receivables but leaves out the $12,000 of cash at the bank.","B":"Receivables and cash are included, but the $54,000 of inventory is also a current asset and is omitted.","C":"Current assets are inventory of $54,000 plus receivables of $38,000 plus cash of $12,000, giving $104,000 of assets expected to turn into cash within a year.","D":"Inventory of $54,000 is only one current asset, so receivables and cash are missing from the total."}}},{"id":"P1_U5_MCQ_1445","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1445","question":"Elverholm Systems has finished its trading year and its accountant is checking the main figures before they are published. Operating profit was $120,000, capital employed was $600,000 and revenue was $1,200,000. What is the return on capital employed, to one decimal place?","options":{"A":"10.0%","B":"20.0%","C":"500.0%","D":"200.0%"},"correctOption":"B","correctAnswer":"20.0%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit of $120,000 divided by capital employed of $600,000, multiplied by 100, which gives 20.0%.","distractor_reasons":{"A":"This divides operating profit by revenue, which gives the profit margin rather than the return on the capital invested.","B":"Return on capital employed is operating profit of $120,000 divided by capital employed of $600,000, multiplied by 100, which gives 20.0%.","C":"This inverts the calculation by dividing capital employed by profit, so it does not measure the return earned on capital.","D":"This compares revenue with capital employed, which measures asset productivity rather than the profit returned to capital."}}},{"id":"P1_U5_MCQ_1446","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1446","question":"Elvermere Studios is a small manufacturer that buys packaging materials from a supplier and is allowed to pay 30 days after delivery rather than on receipt. What is this source of finance called?","options":{"A":"Trade credit","B":"A bank overdraft","C":"Leasing","D":"Retained profit"},"correctOption":"A","correctAnswer":"Trade credit","questionType":"MCQ","explanation":{"correct_reason":"Buying materials now and paying 30 days later is trade credit, a short-term source that eases cash flow while the finished goods are made and sold.","distractor_reasons":{"A":"Buying materials now and paying 30 days later is trade credit, a short-term source that eases cash flow while the finished goods are made and sold.","B":"An overdraft is a facility from a bank, whereas this arrangement comes from the supplier who provides the materials.","C":"Leasing is hiring an asset for a regular fee, not delaying payment for goods that have already been delivered.","D":"Retained profit is profit kept inside the business, not a delay in paying an outside supplier for materials."}}},{"id":"P1_U5_MCQ_1447","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1447","question":"Elverridge Packaging prepares its annual accounts each year and is now reviewing the figures for the year just ended. Forecast payments include wages of $66,000, raw materials of $58,000 and rent of $12,000. What are the total forecast cash outflows?","options":{"A":"$66,000","B":"$124,000","C":"$70,000","D":"$136,000"},"correctOption":"D","correctAnswer":"$136,000","questionType":"MCQ","explanation":{"correct_reason":"The three payments are all cash outflows, so $66,000 plus $58,000 plus $12,000 gives total outflows of $136,000.","distractor_reasons":{"A":"Wages of $66,000 cover only the staff cost, so materials and rent are missing from the total.","B":"This adds wages and materials but ignores the $12,000 of rent, which is also a cash payment.","C":"Materials and rent are included, but the $66,000 wage bill is left out of the outflow total.","D":"The three payments are all cash outflows, so $66,000 plus $58,000 plus $12,000 gives total outflows of $136,000."}}},{"id":"P1_U5_MCQ_1448","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1448","question":"Elvershaw Chemicals has finished its trading year and its accountant is checking the main figures before they are published. Revenue was $480,000 and gross profit was $192,000. What is the gross profit margin, to one decimal place?","options":{"A":"60.0%","B":"66.7%","C":"40.0%","D":"250.0%"},"correctOption":"C","correctAnswer":"40.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit of $192,000 divided by revenue of $480,000 and multiplied by 100, which gives 40.0% of sales retained as gross profit.","distractor_reasons":{"A":"This expresses cost of sales as a percentage of revenue, but the gross profit margin measures the profit share of revenue.","B":"This divides gross profit by cost of sales, which gives the mark-up on cost rather than the margin on revenue.","C":"Gross profit margin is gross profit of $192,000 divided by revenue of $480,000 and multiplied by 100, which gives 40.0% of sales retained as gross profit.","D":"This inverts the ratio by dividing revenue by gross profit, so it cannot be the margin earned on sales."}}},{"id":"P1_U5_MCQ_1449","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1449","question":"Elverwell Pharmacy is a private limited company finalising its accounts for the year ended 31 December 2025. Total assets are $990,000 and current assets are $370,000. What is the value of the non-current assets?","options":{"A":"$1,360,000","B":"$620,000","C":"$370,000","D":"$990,000"},"correctOption":"B","correctAnswer":"$620,000","questionType":"MCQ","explanation":{"correct_reason":"Non-current assets are total assets of $990,000 minus current assets of $370,000, giving $620,000 of long-term assets such as property and machinery.","distractor_reasons":{"A":"Adding the two figures gives $1,360,000, but current assets are already part of total assets.","B":"Non-current assets are total assets of $990,000 minus current assets of $370,000, giving $620,000 of long-term assets such as property and machinery.","C":"Current assets of $370,000 are the short-term assets, not the long-term assets being asked for.","D":"Total assets of $990,000 include the current assets, so this is not the non-current figure alone."}}},{"id":"P1_U5_MCQ_1450","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1450","question":"Elverwick Fitness prepares its annual accounts each year and is now reviewing the figures for the year just ended. Operating profit was $84,000, capital employed was $560,000 and revenue was $840,000. What is the return on capital employed, to one decimal place?","options":{"A":"15.0%","B":"10.0%","C":"666.7%","D":"150.0%"},"correctOption":"A","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit of $84,000 divided by capital employed of $560,000, multiplied by 100, which gives 15.0%.","distractor_reasons":{"A":"Return on capital employed is operating profit of $84,000 divided by capital employed of $560,000, multiplied by 100, which gives 15.0%.","B":"This divides operating profit by revenue, which gives the profit margin rather than the return on the capital invested.","C":"This inverts the calculation by dividing capital employed by profit, so it does not measure the return earned on capital.","D":"This compares revenue with capital employed, which measures asset productivity rather than the profit returned to capital."}}},{"id":"P1_U5_MCQ_1451","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1451","question":"Farnbycroft Nurseries has accumulated profits and wants to fund a new delivery van without paying interest or giving up any control. Which source of finance fits best?","options":{"A":"A bank loan","B":"Issuing new shares","C":"A debenture","D":"Retained profit"},"correctOption":"D","correctAnswer":"Retained profit","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is internal finance kept from earlier profits, so it funds the van without interest charges and without giving new shareholders a say.","distractor_reasons":{"A":"A bank loan would require regular interest payments and repayment of the principal, which the owner wants to avoid.","B":"Issuing shares would bring in outside owners and dilute the control that the present owners want to keep.","C":"A debenture is borrowed money carrying fixed interest and security over assets, so it fails both stated conditions.","D":"Retained profit is internal finance kept from earlier profits, so it funds the van without interest charges and without giving new shareholders a say."}}},{"id":"P1_U5_MCQ_1452","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1452","question":"Farnbydale Builders is a private limited company finalising its accounts for the year ended 31 December 2025. A forecast shows an opening cash balance of $12,000, cash outflows of $88,000 and a closing cash balance of $24,000. What must total cash inflows have been?","options":{"A":"$88,000","B":"$12,000","C":"$100,000","D":"$112,000"},"correctOption":"C","correctAnswer":"$100,000","questionType":"MCQ","explanation":{"correct_reason":"Inflows must cover outflows of $88,000 and still lift the balance from $12,000 to $24,000, so they total $100,000.","distractor_reasons":{"A":"Outflows of $88,000 are the payments side of the forecast, not the receipts needed to reach the closing balance.","B":"This is only the net increase in cash, so it ignores the $88,000 of payments that also had to be funded.","C":"Inflows must cover outflows of $88,000 and still lift the balance from $12,000 to $24,000, so they total $100,000.","D":"Adding outflows to the closing balance double counts the cash already held and overstates the receipts required."}}},{"id":"P1_U5_MCQ_1453","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1453","question":"Farnbyford Energy prepares its annual accounts each year and is now reviewing the figures for the year just ended. Revenue was $1,080,000 and gross profit was $405,000. What is the gross profit margin, to one decimal place?","options":{"A":"62.5%","B":"37.5%","C":"60.0%","D":"266.7%"},"correctOption":"B","correctAnswer":"37.5%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit of $405,000 divided by revenue of $1,080,000 and multiplied by 100, which gives 37.5% of sales retained as gross profit.","distractor_reasons":{"A":"This expresses cost of sales as a percentage of revenue, but the gross profit margin measures the profit share of revenue.","B":"Gross profit margin is gross profit of $405,000 divided by revenue of $1,080,000 and multiplied by 100, which gives 37.5% of sales retained as gross profit.","C":"This divides gross profit by cost of sales, which gives the mark-up on cost rather than the margin on revenue.","D":"This inverts the ratio by dividing revenue by gross profit, so it cannot be the margin earned on sales."}}},{"id":"P1_U5_MCQ_1454","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1454","question":"Farnbygate Media has finished its trading year and its accountant is checking the main figures before they are published. Total assets are $1,880,000 and current assets are $640,000. What is the value of the non-current assets?","options":{"A":"$1,240,000","B":"$2,520,000","C":"$640,000","D":"$1,880,000"},"correctOption":"A","correctAnswer":"$1,240,000","questionType":"MCQ","explanation":{"correct_reason":"Non-current assets are total assets of $1,880,000 minus current assets of $640,000, giving $1,240,000 of long-term assets such as property and machinery.","distractor_reasons":{"A":"Non-current assets are total assets of $1,880,000 minus current assets of $640,000, giving $1,240,000 of long-term assets such as property and machinery.","B":"Adding the two figures gives $2,520,000, but current assets are already part of total assets.","C":"Current assets of $640,000 are the short-term assets, not the long-term assets being asked for.","D":"Total assets of $1,880,000 include the current assets, so this is not the non-current figure alone."}}},{"id":"P1_U5_MCQ_1455","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1455","question":"Farnbyholm Toys is a private limited company finalising its accounts for the year ended 31 December 2025. Operating profit was $135,000, capital employed was $750,000 and revenue was $1,125,000. What is the return on capital employed, to one decimal place?","options":{"A":"12.0%","B":"555.6%","C":"150.0%","D":"18.0%"},"correctOption":"D","correctAnswer":"18.0%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit of $135,000 divided by capital employed of $750,000, multiplied by 100, which gives 18.0%.","distractor_reasons":{"A":"This divides operating profit by revenue, which gives the profit margin rather than the return on the capital invested.","B":"This inverts the calculation by dividing capital employed by profit, so it does not measure the return earned on capital.","C":"This compares revenue with capital employed, which measures asset productivity rather than the profit returned to capital.","D":"Return on capital employed is operating profit of $135,000 divided by capital employed of $750,000, multiplied by 100, which gives 18.0%."}}},{"id":"P1_U5_MCQ_1456","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1456","question":"Farnbymere Travel is a listed public limited company that needs $2,000,000 for a new factory and does not want to increase its borrowing. Which source is most suitable?","options":{"A":"A bank overdraft","B":"Trade credit","C":"Issuing new shares","D":"Retained profit of $200,000"},"correctOption":"C","correctAnswer":"Issuing new shares","questionType":"MCQ","explanation":{"correct_reason":"Issuing new shares on the stock exchange raises permanent capital of $2,000,000 without adding debt, which suits a listed company avoiding extra borrowing.","distractor_reasons":{"A":"An overdraft is short-term and repayable on demand, so it cannot fund a $2,000,000 factory that will be used for decades.","B":"Trade credit covers only the few weeks before suppliers are paid and raises nothing like the amount required for a factory.","C":"Issuing new shares on the stock exchange raises permanent capital of $2,000,000 without adding debt, which suits a listed company avoiding extra borrowing.","D":"Retained profit of $200,000 is far too small to meet the $2,000,000 needed for the new site."}}},{"id":"P1_U5_MCQ_1457","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1457","question":"Farnbyridge Salons has finished its trading year and its accountant is checking the main figures before they are published. A forecast shows an opening cash balance of $31,000, cash outflows of $142,000 and a closing cash balance of $47,000. What must total cash inflows have been?","options":{"A":"$142,000","B":"$158,000","C":"$16,000","D":"$189,000"},"correctOption":"B","correctAnswer":"$158,000","questionType":"MCQ","explanation":{"correct_reason":"Inflows must cover outflows of $142,000 and still lift the balance from $31,000 to $47,000, so they total $158,000.","distractor_reasons":{"A":"Outflows of $142,000 are the payments side of the forecast, not the receipts needed to reach the closing balance.","B":"Inflows must cover outflows of $142,000 and still lift the balance from $31,000 to $47,000, so they total $158,000.","C":"This is only the net increase in cash, so it ignores the $142,000 of payments that also had to be funded.","D":"Adding outflows to the closing balance double counts the cash already held and overstates the receipts required."}}},{"id":"P1_U5_MCQ_1458","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1458","question":"Farnbyshaw Dairy is a private limited company finalising its accounts for the year ended 31 December 2025. Revenue was $1,250,000 and gross profit was $437,500. What is the gross profit margin, to one decimal place?","options":{"A":"35.0%","B":"65.0%","C":"53.8%","D":"285.7%"},"correctOption":"A","correctAnswer":"35.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit of $437,500 divided by revenue of $1,250,000 and multiplied by 100, which gives 35.0% of sales retained as gross profit.","distractor_reasons":{"A":"Gross profit margin is gross profit of $437,500 divided by revenue of $1,250,000 and multiplied by 100, which gives 35.0% of sales retained as gross profit.","B":"This expresses cost of sales as a percentage of revenue, but the gross profit margin measures the profit share of revenue.","C":"This divides gross profit by cost of sales, which gives the mark-up on cost rather than the margin on revenue.","D":"This inverts the ratio by dividing revenue by gross profit, so it cannot be the margin earned on sales."}}},{"id":"P1_U5_MCQ_1459","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1459","question":"Farnbywell Brewing prepares its annual accounts each year and is now reviewing the figures for the year just ended. Total assets are $745,000 and current assets are $215,000. What is the value of the non-current assets?","options":{"A":"$960,000","B":"$215,000","C":"$745,000","D":"$530,000"},"correctOption":"D","correctAnswer":"$530,000","questionType":"MCQ","explanation":{"correct_reason":"Non-current assets are total assets of $745,000 minus current assets of $215,000, giving $530,000 of long-term assets such as property and machinery.","distractor_reasons":{"A":"Adding the two figures gives $960,000, but current assets are already part of total assets.","B":"Current assets of $215,000 are the short-term assets, not the long-term assets being asked for.","C":"Total assets of $745,000 include the current assets, so this is not the non-current figure alone.","D":"Non-current assets are total assets of $745,000 minus current assets of $215,000, giving $530,000 of long-term assets such as property and machinery."}}},{"id":"P1_U5_MCQ_1460","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1460","question":"Farnbywick Marine has finished its trading year and its accountant is checking the main figures before they are published. Operating profit was $99,000, capital employed was $660,000 and revenue was $900,000. What is the return on capital employed, to one decimal place?","options":{"A":"11.0%","B":"666.7%","C":"15.0%","D":"136.4%"},"correctOption":"C","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit of $99,000 divided by capital employed of $660,000, multiplied by 100, which gives 15.0%.","distractor_reasons":{"A":"This divides operating profit by revenue, which gives the profit margin rather than the return on the capital invested.","B":"This inverts the calculation by dividing capital employed by profit, so it does not measure the return earned on capital.","C":"Return on capital employed is operating profit of $99,000 divided by capital employed of $660,000, multiplied by 100, which gives 15.0%.","D":"This compares revenue with capital employed, which measures asset productivity rather than the profit returned to capital."}}},{"id":"P1_U5_MCQ_1461","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1461","question":"Gorsetcroft Bakery needs a delivery vehicle for three years but cannot afford the $28,000 purchase price, and it wants maintenance included. Which source is most suitable?","options":{"A":"A bank overdraft","B":"Leasing the vehicle","C":"Trade credit","D":"Issuing new shares"},"correctOption":"B","correctAnswer":"Leasing the vehicle","questionType":"MCQ","explanation":{"correct_reason":"Leasing gives three years of use of the vehicle for regular payments, avoids the $28,000 upfront cost and usually includes servicing and repairs.","distractor_reasons":{"A":"An overdraft must be repaid on demand and would not provide the three-year use of a vehicle with maintenance included.","B":"Leasing gives three years of use of the vehicle for regular payments, avoids the $28,000 upfront cost and usually includes servicing and repairs.","C":"Trade credit applies to goods bought from suppliers and does not give the business the use of a vehicle for three years.","D":"A small private company issuing shares to raise $28,000 would be slow, costly and would dilute ownership."}}},{"id":"P1_U5_MCQ_1462","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1462","question":"Gorsetdale Timber is preparing a cash flow forecast for the next six months. Which of the following would appear as a cash inflow in the forecast?","options":{"A":"A loan received from the bank","B":"Wages paid to staff","C":"Rent paid for a shop","D":"Payment for a new delivery van"},"correctOption":"A","correctAnswer":"A loan received from the bank","questionType":"MCQ","explanation":{"correct_reason":"A loan received brings cash into the business, so it is an inflow even though it must be repaid later with interest.","distractor_reasons":{"A":"A loan received brings cash into the business, so it is an inflow even though it must be repaid later with interest.","B":"Wages are money leaving the business, so they belong in the outflows section of the forecast.","C":"Rent is a regular payment made by the business, which makes it an outflow rather than a receipt.","D":"Buying a van uses cash, so it is recorded as an outflow in the month the payment is made."}}},{"id":"P1_U5_MCQ_1463","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1463","question":"Gorsetford Couriers has finished its trading year and its accountant is checking the main figures before they are published. Revenue for the year was $480,000 and profit for the year was $66,000. What is the profit margin, to one decimal place?","options":{"A":"15.9%","B":"86.2%","C":"0.1%","D":"13.8%"},"correctOption":"D","correctAnswer":"13.8%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year of $66,000 divided by revenue of $480,000, multiplied by 100, giving 13.8% of each sales dollar left as profit.","distractor_reasons":{"A":"This divides profit by the cost figure rather than by revenue, so it measures the return on costs instead of the margin on sales.","B":"This shows costs as a share of revenue, which is the complement of the profit margin rather than the margin itself.","C":"This divides profit by revenue but forgets to multiply by 100, so the answer is a decimal fraction rather than a percentage.","D":"Profit margin is profit for the year of $66,000 divided by revenue of $480,000, multiplied by 100, giving 13.8% of each sales dollar left as profit."}}},{"id":"P1_U5_MCQ_1464","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1464","question":"Gorsetgate Furniture is a private limited company finalising its accounts for the year ended 31 December 2025. Current liabilities are $120,000 and non-current liabilities are $225,000. What are the total liabilities?","options":{"A":"$105,000","B":"$120,000","C":"$345,000","D":"$225,000"},"correctOption":"C","correctAnswer":"$345,000","questionType":"MCQ","explanation":{"correct_reason":"Total liabilities are current liabilities of $120,000 plus non-current liabilities of $225,000, giving $345,000 owed to lenders and suppliers.","distractor_reasons":{"A":"Subtracting current from non-current liabilities gives $105,000, but both groups are owed and must be added.","B":"Current liabilities of $120,000 are only the debts due within a year, so the long-term debt is missing.","C":"Total liabilities are current liabilities of $120,000 plus non-current liabilities of $225,000, giving $345,000 owed to lenders and suppliers.","D":"Non-current liabilities of $225,000 are only the long-term debts, so the short-term debts are left out."}}},{"id":"P1_U5_MCQ_1465","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1465","question":"Gorsetholm Printing prepares its annual accounts each year and is now reviewing the figures for the year just ended. Revenue for the year was $1,200,000 and gross profit was $420,000. What is the gross profit margin, to one decimal place?","options":{"A":"53.8%","B":"35.0%","C":"65.0%","D":"285.7%"},"correctOption":"B","correctAnswer":"35.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit of $420,000 divided by revenue of $1,200,000, multiplied by 100, giving 35.0% of sales kept as gross profit.","distractor_reasons":{"A":"This divides gross profit by cost of sales, which gives the mark-up on cost rather than the margin on revenue.","B":"Gross profit margin is gross profit of $420,000 divided by revenue of $1,200,000, multiplied by 100, giving 35.0% of sales kept as gross profit.","C":"This shows cost of sales as a share of revenue, which is the opposite of the gross profit share.","D":"This divides revenue by gross profit, which inverts the ratio and cannot represent a percentage margin on sales."}}},{"id":"P1_U5_MCQ_1466","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1466","question":"Gorsetmere Hotels is reviewing its year-end statement of financial position with its accountant before applying for a bank loan. Which statement best defines the working capital of the business?","options":{"A":"Current assets minus current liabilities","B":"Total assets minus total liabilities","C":"Non-current assets plus inventory","D":"Cash held in the bank at the year end"},"correctOption":"A","correctAnswer":"Current assets minus current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, showing the short-term funds left to pay day-to-day bills once debts due within a year are covered.","distractor_reasons":{"A":"Working capital is current assets minus current liabilities, showing the short-term funds left to pay day-to-day bills once debts due within a year are covered.","B":"That calculation gives total equity, which includes long-term assets and is not the short-term funds used for daily trading.","C":"This mixes long-term assets with stock and ignores the short-term debts that must be paid within the year.","D":"Cash is only one part of current assets, so the bank balance alone ignores inventory, receivables and current liabilities."}}},{"id":"P1_U5_MCQ_1467","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1467","question":"Gorsetridge Foods is preparing a cash flow forecast for the next six months. Which of the following would appear as a cash outflow in the forecast?","options":{"A":"Cash sales in the shop","B":"A loan received from the bank","C":"The sale of an old machine","D":"Payment to a supplier for raw materials"},"correctOption":"D","correctAnswer":"Payment to a supplier for raw materials","questionType":"MCQ","explanation":{"correct_reason":"Paying a supplier takes cash out of the business, so it is recorded as an outflow in the month the payment is actually made.","distractor_reasons":{"A":"Cash sales bring money in over the counter, so they are inflows rather than payments.","B":"A loan received increases the cash balance and is therefore an inflow in the month it arrives.","C":"Selling a machine raises cash for the business, which makes it an inflow rather than an outflow.","D":"Paying a supplier takes cash out of the business, so it is recorded as an outflow in the month the payment is actually made."}}},{"id":"P1_U5_MCQ_1468","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1468","question":"Gorsetshaw Textiles prepares its annual accounts each year and is now reviewing the figures for the year just ended. Revenue for the year was $1,080,000 and profit for the year was $160,000. What is the profit margin, to one decimal place?","options":{"A":"17.4%","B":"85.2%","C":"14.8%","D":"0.1%"},"correctOption":"C","correctAnswer":"14.8%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year of $160,000 divided by revenue of $1,080,000, multiplied by 100, giving 14.8% of each sales dollar left as profit.","distractor_reasons":{"A":"This divides profit by the cost figure rather than by revenue, so it measures the return on costs instead of the margin on sales.","B":"This shows costs as a share of revenue, which is the complement of the profit margin rather than the margin itself.","C":"Profit margin is profit for the year of $160,000 divided by revenue of $1,080,000, multiplied by 100, giving 14.8% of each sales dollar left as profit.","D":"This divides profit by revenue but forgets to multiply by 100, so the answer is a decimal fraction rather than a percentage."}}},{"id":"P1_U5_MCQ_1469","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1469","question":"Gorsetwell Engineering has finished its trading year and its accountant is checking the main figures before they are published. Current liabilities are $280,000 and non-current liabilities are $302,000. What are the total liabilities?","options":{"A":"$22,000","B":"$582,000","C":"$280,000","D":"$302,000"},"correctOption":"B","correctAnswer":"$582,000","questionType":"MCQ","explanation":{"correct_reason":"Total liabilities are current liabilities of $280,000 plus non-current liabilities of $302,000, giving $582,000 owed to lenders and suppliers.","distractor_reasons":{"A":"Subtracting current from non-current liabilities gives $22,000, but both groups are owed and must be added.","B":"Total liabilities are current liabilities of $280,000 plus non-current liabilities of $302,000, giving $582,000 owed to lenders and suppliers.","C":"Current liabilities of $280,000 are only the debts due within a year, so the long-term debt is missing.","D":"Non-current liabilities of $302,000 are only the long-term debts, so the short-term debts are left out."}}},{"id":"P1_U5_MCQ_1470","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1470","question":"Gorsetwick Motors is a private limited company finalising its accounts for the year ended 31 December 2025. Revenue for the year was $840,000 and gross profit was $252,000. What is the gross profit margin, to one decimal place?","options":{"A":"30.0%","B":"42.9%","C":"70.0%","D":"333.3%"},"correctOption":"A","correctAnswer":"30.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit of $252,000 divided by revenue of $840,000, multiplied by 100, giving 30.0% of sales kept as gross profit.","distractor_reasons":{"A":"Gross profit margin is gross profit of $252,000 divided by revenue of $840,000, multiplied by 100, giving 30.0% of sales kept as gross profit.","B":"This divides gross profit by cost of sales, which gives the mark-up on cost rather than the margin on revenue.","C":"This shows cost of sales as a share of revenue, which is the opposite of the gross profit share.","D":"This divides revenue by gross profit, which inverts the ratio and cannot represent a percentage margin on sales."}}},{"id":"P1_U5_MCQ_1471","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1471","question":"Hazelcroft Cafes reported a profit for the year but its bank balance is now very low, because most sales were made on credit with 60-day terms. What is the most likely explanation?","options":{"A":"The business paid no wages during the year","B":"Its non-current assets fell in value","C":"It repaid no borrowings during the year","D":"Customers owe money that has not yet been collected"},"correctOption":"D","correctAnswer":"Customers owe money that has not yet been collected","questionType":"MCQ","explanation":{"correct_reason":"Credit sales with 60-day terms create trade receivables, so profit is recorded before the cash arrives and the business can be profitable yet short of cash.","distractor_reasons":{"A":"Wages are a cash cost, so not paying them would normally improve the cash balance rather than explain a shortage.","B":"A fall in the value of non-current assets is a book adjustment and does not by itself absorb cash from trading.","C":"Repaying no borrowings preserves cash, so it cannot explain why a profitable business is short of money.","D":"Credit sales with 60-day terms create trade receivables, so profit is recorded before the cash arrives and the business can be profitable yet short of cash."}}},{"id":"P1_U5_MCQ_1472","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1472","question":"Hazeldale Clinics is preparing a cash flow forecast because its bank balance is low and it wants to avoid a crisis. What is the main purpose of preparing this forecast?","options":{"A":"To calculate the profit earned for the year","B":"To value the non-current assets of the business","C":"To predict the timing of cash inflows and outflows and identify shortages in advance","D":"To record the transactions that have already happened"},"correctOption":"C","correctAnswer":"To predict the timing of cash inflows and outflows and identify shortages in advance","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast predicts when money will arrive and when it must be paid, so managers can arrange finance before a shortage becomes a crisis.","distractor_reasons":{"A":"Profit is calculated in the profit and loss account, which records revenue and expenses rather than the timing of cash.","B":"Asset valuation comes from the statement of financial position, not from a forecast of cash movements.","C":"A cash flow forecast predicts when money will arrive and when it must be paid, so managers can arrange finance before a shortage becomes a crisis.","D":"A forecast looks forward, so completed transactions belong in the cash book or statement of cash flows."}}},{"id":"P1_U5_MCQ_1473","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1473","question":"Hazelford Farms is a private limited company finalising its accounts for the year ended 31 December 2025. Revenue for the year was $750,000 and profit for the year was $150,000. What is the profit margin, to one decimal place?","options":{"A":"25.0%","B":"20.0%","C":"80.0%","D":"0.2%"},"correctOption":"B","correctAnswer":"20.0%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year of $150,000 divided by revenue of $750,000, multiplied by 100, giving 20.0% of each sales dollar left as profit.","distractor_reasons":{"A":"This divides profit by the cost figure rather than by revenue, so it measures the return on costs instead of the margin on sales.","B":"Profit margin is profit for the year of $150,000 divided by revenue of $750,000, multiplied by 100, giving 20.0% of each sales dollar left as profit.","C":"This shows costs as a share of revenue, which is the complement of the profit margin rather than the margin itself.","D":"This divides profit by revenue but forgets to multiply by 100, so the answer is a decimal fraction rather than a percentage."}}},{"id":"P1_U5_MCQ_1474","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1474","question":"Hazelgate Stores prepares its annual accounts each year and is now reviewing the figures for the year just ended. Current liabilities are $88,000 and non-current liabilities are $160,000. What are the total liabilities?","options":{"A":"$248,000","B":"$72,000","C":"$88,000","D":"$160,000"},"correctOption":"A","correctAnswer":"$248,000","questionType":"MCQ","explanation":{"correct_reason":"Total liabilities are current liabilities of $88,000 plus non-current liabilities of $160,000, giving $248,000 owed to lenders and suppliers.","distractor_reasons":{"A":"Total liabilities are current liabilities of $88,000 plus non-current liabilities of $160,000, giving $248,000 owed to lenders and suppliers.","B":"Subtracting current from non-current liabilities gives $72,000, but both groups are owed and must be added.","C":"Current liabilities of $88,000 are only the debts due within a year, so the long-term debt is missing.","D":"Non-current liabilities of $160,000 are only the long-term debts, so the short-term debts are left out."}}},{"id":"P1_U5_MCQ_1475","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1475","question":"Hazelholm Systems has finished its trading year and its accountant is checking the main figures before they are published. Revenue for the year was $1,125,000 and gross profit was $405,000. What is the gross profit margin, to one decimal place?","options":{"A":"56.2%","B":"64.0%","C":"277.8%","D":"36.0%"},"correctOption":"D","correctAnswer":"36.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit of $405,000 divided by revenue of $1,125,000, multiplied by 100, giving 36.0% of sales kept as gross profit.","distractor_reasons":{"A":"This divides gross profit by cost of sales, which gives the mark-up on cost rather than the margin on revenue.","B":"This shows cost of sales as a share of revenue, which is the opposite of the gross profit share.","C":"This divides revenue by gross profit, which inverts the ratio and cannot represent a percentage margin on sales.","D":"Gross profit margin is gross profit of $405,000 divided by revenue of $1,125,000, multiplied by 100, giving 36.0% of sales kept as gross profit."}}},{"id":"P1_U5_MCQ_1476","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1476","question":"Hazelmere Studios is considering raising long-term finance by issuing a debenture to investors rather than issuing shares. Which statement correctly describes a debenture issued by the business?","options":{"A":"A short-term overdraft repayable on demand","B":"Money provided by owners in exchange for shares","C":"A long-term loan paying a fixed rate of interest, often secured on the company's assets","D":"A delay in paying suppliers for delivered goods"},"correctOption":"C","correctAnswer":"A long-term loan paying a fixed rate of interest, often secured on the company's assets","questionType":"MCQ","explanation":{"correct_reason":"A debenture is long-term loan capital that pays a fixed rate of interest and is commonly secured against assets, so lenders rank ahead of shareholders.","distractor_reasons":{"A":"An overdraft is a bank facility repayable on demand, whereas a debenture is long-term borrowed capital.","B":"Share capital gives owners a stake in the company, but a debenture is a loan that must be repaid with interest.","C":"A debenture is long-term loan capital that pays a fixed rate of interest and is commonly secured against assets, so lenders rank ahead of shareholders.","D":"Delay in paying suppliers is trade credit, not a formal long-term loan secured on assets."}}},{"id":"P1_U5_MCQ_1477","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1477","question":"Hazelridge Packaging reported a profit for the year but its bank balance is now very low. Why can a profitable business still run out of cash even when it trades on credit?","options":{"A":"Profit is always lower than the cash balance","B":"Sales may be made on credit, so cash arrives later than the costs are paid","C":"Lenders take all of the profit as interest","D":"Assets are always worth less than their book value"},"correctOption":"B","correctAnswer":"Sales may be made on credit, so cash arrives later than the costs are paid","questionType":"MCQ","explanation":{"correct_reason":"Credit sales create receivables, so a business can record profit on a sale long before the customer pays, while wages and suppliers still need cash.","distractor_reasons":{"A":"Profit and cash are separate measures, and profit is not automatically smaller than the cash held at the bank.","B":"Credit sales create receivables, so a business can record profit on a sale long before the customer pays, while wages and suppliers still need cash.","C":"Interest is only one expense, so lenders do not normally absorb the whole profit of a trading business.","D":"Asset values affect the statement of financial position, not the timing of cash receipts from customers."}}},{"id":"P1_U5_MCQ_1478","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1478","question":"Hazelshaw Chemicals has finished its trading year and its accountant is checking the main figures before they are published. Profit for the year was $66,000 and dividends of $18,000 were paid to the shareholders. What is the retained profit for the year?","options":{"A":"$48,000","B":"$84,000","C":"$18,000","D":"$66,000"},"correctOption":"A","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is profit for the year of $66,000 minus dividends of $18,000, leaving $48,000 kept in the business to finance future investment.","distractor_reasons":{"A":"Retained profit is profit for the year of $66,000 minus dividends of $18,000, leaving $48,000 kept in the business to finance future investment.","B":"Adding dividends to profit gives $84,000, but dividends are paid out of profit and reduce what is kept.","C":"Dividends of $18,000 are the amount distributed, not the amount retained inside the business.","D":"Profit of $66,000 is the amount before dividends, so it ignores the $18,000 paid out to shareholders."}}},{"id":"P1_U5_MCQ_1479","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1479","question":"Hazelwell Pharmacy is a private limited company finalising its accounts for the year ended 31 December 2025. Current assets are $200,000 and current liabilities are $134,000. What is the working capital shown by these figures?","options":{"A":"$334,000","B":"$134,000","C":"$200,000","D":"$66,000"},"correctOption":"D","correctAnswer":"$66,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets of $200,000 minus current liabilities of $134,000, giving $66,000 available to fund day-to-day operations.","distractor_reasons":{"A":"Adding the two figures gives $334,000, which combines the assets with the debts instead of netting them.","B":"Current liabilities of $134,000 are the debts to be paid, not the funds available for daily operations.","C":"Current assets of $200,000 have not had the short-term debts deducted, so this overstates available working capital.","D":"Working capital is current assets of $200,000 minus current liabilities of $134,000, giving $66,000 available to fund day-to-day operations."}}},{"id":"P1_U5_MCQ_1480","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1480","question":"Hazelwick Fitness prepares its annual accounts each year and is now reviewing the figures for the year just ended. Revenue for the year was $900,000 and gross profit was $225,000. What is the gross profit margin, to one decimal place?","options":{"A":"33.3%","B":"75.0%","C":"25.0%","D":"400.0%"},"correctOption":"C","correctAnswer":"25.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit of $225,000 divided by revenue of $900,000, multiplied by 100, giving 25.0% of sales kept as gross profit.","distractor_reasons":{"A":"This divides gross profit by cost of sales, which gives the mark-up on cost rather than the margin on revenue.","B":"This shows cost of sales as a share of revenue, which is the opposite of the gross profit share.","C":"Gross profit margin is gross profit of $225,000 divided by revenue of $900,000, multiplied by 100, giving 25.0% of sales kept as gross profit.","D":"This divides revenue by gross profit, which inverts the ratio and cannot represent a percentage margin on sales."}}},{"id":"P1_U5_MCQ_1481","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1481","question":"Inkercroft Nurseries is a tiny business in a low-income country that needs a loan of $800 but has no collateral and no credit record. Which source of finance is most suitable?","options":{"A":"A debenture","B":"Microfinance from a specialist lender","C":"Issuing shares on a stock exchange","D":"Trade credit from a multinational supplier"},"correctOption":"B","correctAnswer":"Microfinance from a specialist lender","questionType":"MCQ","explanation":{"correct_reason":"Microfinance providers lend small sums such as $800 to entrepreneurs without collateral, often using group support instead of security.","distractor_reasons":{"A":"A debenture is a large long-term loan for companies and is not available to a tiny business with no collateral or credit history.","B":"Microfinance providers lend small sums such as $800 to entrepreneurs without collateral, often using group support instead of security.","C":"Stock exchange listing is expensive and reserved for large companies, so it is completely out of reach for this firm.","D":"A multinational supplier would not extend credit of $800 to an unknown tailor with no trading record."}}},{"id":"P1_U5_MCQ_1482","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1482","question":"Inkerdale Builders expects a cash shortage next month and wants to improve its closing cash balance. Which action would most directly improve its cash flow?","options":{"A":"Asking credit customers to pay earlier","B":"Offering customers longer credit terms","C":"Buying extra inventory for cash","D":"Paying suppliers earlier than agreed"},"correctOption":"A","correctAnswer":"Asking credit customers to pay earlier","questionType":"MCQ","explanation":{"correct_reason":"Persuading credit customers to pay earlier speeds up receipts, which raises the closing cash balance without adding any interest cost.","distractor_reasons":{"A":"Persuading credit customers to pay earlier speeds up receipts, which raises the closing cash balance without adding any interest cost.","B":"Longer credit delays receipts further, which worsens the cash position rather than improving it.","C":"Buying more stock uses cash immediately and only converts to receipts when the goods are eventually sold.","D":"Paying earlier takes cash out sooner and gives up the benefit of the credit period offered."}}},{"id":"P1_U5_MCQ_1483","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1483","question":"Inkerford Energy prepares its annual accounts each year and is now reviewing the figures for the year just ended. Profit for the year was $160,000 and dividends of $45,000 were paid to the shareholders. What is the retained profit for the year?","options":{"A":"$205,000","B":"$45,000","C":"$160,000","D":"$115,000"},"correctOption":"D","correctAnswer":"$115,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is profit for the year of $160,000 minus dividends of $45,000, leaving $115,000 kept in the business to finance future investment.","distractor_reasons":{"A":"Adding dividends to profit gives $205,000, but dividends are paid out of profit and reduce what is kept.","B":"Dividends of $45,000 are the amount distributed, not the amount retained inside the business.","C":"Profit of $160,000 is the amount before dividends, so it ignores the $45,000 paid out to shareholders.","D":"Retained profit is profit for the year of $160,000 minus dividends of $45,000, leaving $115,000 kept in the business to finance future investment."}}},{"id":"P1_U5_MCQ_1484","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1484","question":"Inkergate Media has finished its trading year and its accountant is checking the main figures before they are published. Current assets are $300,000 and current liabilities are $176,000. What is the working capital shown by these figures?","options":{"A":"$476,000","B":"$176,000","C":"$124,000","D":"$300,000"},"correctOption":"C","correctAnswer":"$124,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets of $300,000 minus current liabilities of $176,000, giving $124,000 available to fund day-to-day operations.","distractor_reasons":{"A":"Adding the two figures gives $476,000, which combines the assets with the debts instead of netting them.","B":"Current liabilities of $176,000 are the debts to be paid, not the funds available for daily operations.","C":"Working capital is current assets of $300,000 minus current liabilities of $176,000, giving $124,000 available to fund day-to-day operations.","D":"Current assets of $300,000 have not had the short-term debts deducted, so this overstates available working capital."}}},{"id":"P1_U5_MCQ_1485","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1485","question":"Inkerholm Toys is a private limited company finalising its accounts for the year ended 31 December 2025. Revenue was $1,600,000 and operating profit was $128,000. What is the profit margin, to one decimal place?","options":{"A":"8.7%","B":"8.0%","C":"0.1%","D":"92.0%"},"correctOption":"B","correctAnswer":"8.0%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is operating profit of $128,000 divided by revenue of $1,600,000, multiplied by 100, which gives 8.0% of sales left as operating profit.","distractor_reasons":{"A":"This divides profit by costs rather than by revenue, so it measures return on costs instead of the margin on sales.","B":"Profit margin is operating profit of $128,000 divided by revenue of $1,600,000, multiplied by 100, which gives 8.0% of sales left as operating profit.","C":"This divides profit by revenue but forgets to multiply by 100, so the result is a decimal fraction rather than a percentage.","D":"This reports costs as a percentage of revenue, which is the complement of the profit margin, not the margin itself."}}},{"id":"P1_U5_MCQ_1486","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1486","question":"Inkermere Travel wants $15,000 to develop a new app and hopes to collect small amounts from many supporters through a website in return for early access. Which source of finance is this?","options":{"A":"Crowdfunding","B":"A bank overdraft","C":"Leasing","D":"Trade credit"},"correctOption":"A","correctAnswer":"Crowdfunding","questionType":"MCQ","explanation":{"correct_reason":"Crowdfunding raises money by asking a large number of people to contribute small amounts online, often in exchange for rewards such as early access.","distractor_reasons":{"A":"Crowdfunding raises money by asking a large number of people to contribute small amounts online, often in exchange for rewards such as early access.","B":"An overdraft is lending from one bank and is repayable on demand, not money pledged by many individual supporters.","C":"Leasing is hiring a physical asset for regular payments and does not raise funds from the public for development work.","D":"Trade credit is a delay in paying suppliers, not a campaign that collects small contributions from many backers."}}},{"id":"P1_U5_MCQ_1487","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1487","question":"The cash flow forecast prepared by Inkerridge Salons for the next six months shows a negative closing balance in June. What does this indicate for the business?","options":{"A":"The business has made a loss for the period","B":"The business has too much working capital","C":"Its non-current assets have fallen in value","D":"The business is forecast to run out of cash and will need additional finance"},"correctOption":"D","correctAnswer":"The business is forecast to run out of cash and will need additional finance","questionType":"MCQ","explanation":{"correct_reason":"A negative closing balance means payments will exceed the money available, so the business must arrange an overdraft, delay payments or collect cash faster.","distractor_reasons":{"A":"A cash shortage is not the same as a loss, because the timing of receipts and payments differs from profit.","B":"A negative balance means too little cash, which is the opposite of holding excess working capital.","C":"The cash balance reflects receipts and payments, not changes in the book value of long-term assets.","D":"A negative closing balance means payments will exceed the money available, so the business must arrange an overdraft, delay payments or collect cash faster."}}},{"id":"P1_U5_MCQ_1488","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1488","question":"Inkershaw Dairy is a private limited company finalising its accounts for the year ended 31 December 2025. Profit for the year was $150,000 and dividends of $60,000 were paid to the shareholders. What is the retained profit for the year?","options":{"A":"$210,000","B":"$60,000","C":"$90,000","D":"$150,000"},"correctOption":"C","correctAnswer":"$90,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is profit for the year of $150,000 minus dividends of $60,000, leaving $90,000 kept in the business to finance future investment.","distractor_reasons":{"A":"Adding dividends to profit gives $210,000, but dividends are paid out of profit and reduce what is kept.","B":"Dividends of $60,000 are the amount distributed, not the amount retained inside the business.","C":"Retained profit is profit for the year of $150,000 minus dividends of $60,000, leaving $90,000 kept in the business to finance future investment.","D":"Profit of $150,000 is the amount before dividends, so it ignores the $60,000 paid out to shareholders."}}},{"id":"P1_U5_MCQ_1489","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1489","question":"Inkerwell Brewing prepares its annual accounts each year and is now reviewing the figures for the year just ended. Current assets are $104,000 and current liabilities are $86,000. What is the working capital shown by these figures?","options":{"A":"$190,000","B":"$18,000","C":"$86,000","D":"$104,000"},"correctOption":"B","correctAnswer":"$18,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets of $104,000 minus current liabilities of $86,000, giving $18,000 available to fund day-to-day operations.","distractor_reasons":{"A":"Adding the two figures gives $190,000, which combines the assets with the debts instead of netting them.","B":"Working capital is current assets of $104,000 minus current liabilities of $86,000, giving $18,000 available to fund day-to-day operations.","C":"Current liabilities of $86,000 are the debts to be paid, not the funds available for daily operations.","D":"Current assets of $104,000 have not had the short-term debts deducted, so this overstates available working capital."}}},{"id":"P1_U5_MCQ_1490","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1490","question":"Inkerwick Marine has finished its trading year and its accountant is checking the main figures before they are published. Revenue was $2,250,000 and operating profit was $202,500. What is the profit margin, to one decimal place?","options":{"A":"9.0%","B":"9.9%","C":"0.1%","D":"91.0%"},"correctOption":"A","correctAnswer":"9.0%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is operating profit of $202,500 divided by revenue of $2,250,000, multiplied by 100, which gives 9.0% of sales left as operating profit.","distractor_reasons":{"A":"Profit margin is operating profit of $202,500 divided by revenue of $2,250,000, multiplied by 100, which gives 9.0% of sales left as operating profit.","B":"This divides profit by costs rather than by revenue, so it measures return on costs instead of the margin on sales.","C":"This divides profit by revenue but forgets to multiply by 100, so the result is a decimal fraction rather than a percentage.","D":"This reports costs as a percentage of revenue, which is the complement of the profit margin, not the margin itself."}}},{"id":"P1_U5_MCQ_1491","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1491","question":"Loxleycroft Bakery owns a disused warehouse that it no longer needs and wants to raise cash without borrowing. Which internal source of finance is available?","options":{"A":"Issuing a debenture","B":"Increasing the bank overdraft","C":"Asking suppliers for trade credit","D":"Selling the unused warehouse"},"correctOption":"D","correctAnswer":"Selling the unused warehouse","questionType":"MCQ","explanation":{"correct_reason":"Selling the disused warehouse turns an idle non-current asset into cash, providing internal finance without any borrowing or interest cost.","distractor_reasons":{"A":"A debenture is borrowed money and would increase the company's debt, which the owners want to avoid.","B":"An overdraft is external borrowing that must be repaid with interest when the bank demands it.","C":"Trade credit only delays payment for supplies and raises no cash from an asset the business already owns.","D":"Selling the disused warehouse turns an idle non-current asset into cash, providing internal finance without any borrowing or interest cost."}}},{"id":"P1_U5_MCQ_1492","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1492","question":"Loxleydale Timber is considering delaying payments to suppliers in order to improve its cash balance. What is the main risk to the business of doing this?","options":{"A":"The business will immediately make a loss","B":"Its inventory will rise in value","C":"Suppliers may refuse further credit and early-payment discounts are lost","D":"Customers will pay more quickly"},"correctOption":"C","correctAnswer":"Suppliers may refuse further credit and early-payment discounts are lost","questionType":"MCQ","explanation":{"correct_reason":"Stretching supplier credit improves cash in the short term, but suppliers may stop supplying or withdraw discounts, which raises costs later.","distractor_reasons":{"A":"Delaying payment affects cash timing, not the profit already recorded on the sales and purchases made.","B":"Postponing payments does not change the cost or value of stock already received from suppliers.","C":"Stretching supplier credit improves cash in the short term, but suppliers may stop supplying or withdraw discounts, which raises costs later.","D":"Supplier payment terms have no direct effect on how quickly customers settle their own invoices."}}},{"id":"P1_U5_MCQ_1493","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1493","question":"Loxleyford Couriers has finished its trading year and its accountant is checking the main figures before they are published. Gross profit for the year was $560,000 and profit for the year was $224,000. What were the operating expenses?","options":{"A":"$784,000","B":"$336,000","C":"$224,000","D":"$560,000"},"correctOption":"B","correctAnswer":"$336,000","questionType":"MCQ","explanation":{"correct_reason":"Operating expenses are the fall from gross profit of $560,000 to profit for the year of $224,000, which equals $336,000 of overhead costs.","distractor_reasons":{"A":"Adding the two profit figures gives $784,000, which is not the cost incurred between gross and net profit.","B":"Operating expenses are the fall from gross profit of $560,000 to profit for the year of $224,000, which equals $336,000 of overhead costs.","C":"Profit for the year of $224,000 is the amount left after expenses, not the expenses themselves.","D":"Gross profit of $560,000 is the starting figure before expenses, so it cannot be the expense total."}}},{"id":"P1_U5_MCQ_1494","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1494","question":"Loxleygate Furniture is a private limited company finalising its accounts for the year ended 31 December 2025. Total equity is $515,000 and non-current liabilities are $225,000. What is the capital employed of the business?","options":{"A":"$740,000","B":"$290,000","C":"$515,000","D":"$225,000"},"correctOption":"A","correctAnswer":"$740,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is total equity of $515,000 plus non-current liabilities of $225,000, giving $740,000 of long-term finance invested in the business.","distractor_reasons":{"A":"Capital employed is total equity of $515,000 plus non-current liabilities of $225,000, giving $740,000 of long-term finance invested in the business.","B":"Subtracting long-term liabilities from equity gives $290,000, but capital employed adds the two sources of long-term finance.","C":"Equity of $515,000 is only the owners' stake, so it omits the long-term borrowed capital still in use.","D":"Non-current liabilities of $225,000 are borrowed funds only, so the owners' equity is left out."}}},{"id":"P1_U5_MCQ_1495","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1495","question":"Loxleyholm Printing prepares its annual accounts each year and is now reviewing the figures for the year just ended. Gross profit margin was 28.0% in 2024 and 33.5% in 2025. By how many percentage points did the margin change?","options":{"A":"A rise of 19.6 percentage points","B":"A rise of 5.5%","C":"A rise of 61.5 percentage points","D":"A rise of 5.5 percentage points"},"correctOption":"D","correctAnswer":"A rise of 5.5 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The margin rose from 28.0% to 33.5%, a change of 33.5 minus 28.0, which is a rise of 5.5 percentage points of revenue.","distractor_reasons":{"A":"This measures the relative increase as a percentage of the 2024 margin, not the simple change in percentage points.","B":"The margin moved 5.5 points of revenue, so describing it as a 5.5% rise confuses points with a relative percentage change.","C":"This adds the two margins together instead of subtracting the earlier margin from the later one.","D":"The margin rose from 28.0% to 33.5%, a change of 33.5 minus 28.0, which is a rise of 5.5 percentage points of revenue."}}},{"id":"P1_U5_MCQ_1496","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1496","question":"Loxleymere Hotels needs extra finance to cover a shortage that will last only a few weeks. Which of these is a short-term source of finance for the business?","options":{"A":"A ten-year bank loan","B":"Issuing new shares","C":"A bank overdraft","D":"A debenture repayable in 2035"},"correctOption":"C","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"A bank overdraft is a short-term facility that can be drawn and repaid within days or weeks, so it is used for brief cash shortfalls.","distractor_reasons":{"A":"A ten-year loan is long-term finance that is repaid over a decade, so it is not a short-term source.","B":"Share capital is permanent finance that stays in the business, making it a long-term source rather than a short-term one.","C":"A bank overdraft is a short-term facility that can be drawn and repaid within days or weeks, so it is used for brief cash shortfalls.","D":"A debenture maturing in 2035 is long-term debt and does not fall due within the coming year."}}},{"id":"P1_U5_MCQ_1497","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1497","question":"Loxleyridge Foods prepares both a cash flow forecast and a statement of cash flows each year. How do these two documents differ in what they show?","options":{"A":"A forecast records past cash, while a statement predicts future cash","B":"A forecast predicts future cash movements, while a statement records past ones","C":"A forecast includes only outflows, while a statement includes only inflows","D":"A forecast is prepared by the bank, while a statement is prepared by the owner"},"correctOption":"B","correctAnswer":"A forecast predicts future cash movements, while a statement records past ones","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast is forward looking and estimates future receipts and payments, whereas a statement of cash flows summarises cash movements that have already occurred.","distractor_reasons":{"A":"This reverses the two documents, since the forecast looks ahead and the statement reports what has already happened.","B":"A cash flow forecast is forward looking and estimates future receipts and payments, whereas a statement of cash flows summarises cash movements that have already occurred.","C":"Both documents record inflows and outflows, so neither is limited to one direction of cash movement.","D":"Both are internal management documents, so neither is prepared by the bank on the business's behalf."}}},{"id":"P1_U5_MCQ_1498","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1498","question":"Loxleyshaw Textiles prepares its annual accounts each year and is now reviewing the figures for the year just ended. Gross profit for the year was $918,000 and profit for the year was $306,000. What were the operating expenses?","options":{"A":"$612,000","B":"$1,224,000","C":"$306,000","D":"$918,000"},"correctOption":"A","correctAnswer":"$612,000","questionType":"MCQ","explanation":{"correct_reason":"Operating expenses are the fall from gross profit of $918,000 to profit for the year of $306,000, which equals $612,000 of overhead costs.","distractor_reasons":{"A":"Operating expenses are the fall from gross profit of $918,000 to profit for the year of $306,000, which equals $612,000 of overhead costs.","B":"Adding the two profit figures gives $1,224,000, which is not the cost incurred between gross and net profit.","C":"Profit for the year of $306,000 is the amount left after expenses, not the expenses themselves.","D":"Gross profit of $918,000 is the starting figure before expenses, so it cannot be the expense total."}}},{"id":"P1_U5_MCQ_1499","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1499","question":"Loxleywell Engineering has finished its trading year and its accountant is checking the main figures before they are published. Total equity is $838,000 and non-current liabilities are $302,000. What is the capital employed of the business?","options":{"A":"$536,000","B":"$838,000","C":"$302,000","D":"$1,140,000"},"correctOption":"D","correctAnswer":"$1,140,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is total equity of $838,000 plus non-current liabilities of $302,000, giving $1,140,000 of long-term finance invested in the business.","distractor_reasons":{"A":"Subtracting long-term liabilities from equity gives $536,000, but capital employed adds the two sources of long-term finance.","B":"Equity of $838,000 is only the owners' stake, so it omits the long-term borrowed capital still in use.","C":"Non-current liabilities of $302,000 are borrowed funds only, so the owners' equity is left out.","D":"Capital employed is total equity of $838,000 plus non-current liabilities of $302,000, giving $1,140,000 of long-term finance invested in the business."}}},{"id":"P1_U5_MCQ_1500","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1500","question":"Loxleywick Motors is a private limited company finalising its accounts for the year ended 31 December 2025. Profit margin was 12.5% in 2024 and 9.0% in 2025. By how many percentage points did the margin change?","options":{"A":"A fall of 28.0 percentage points","B":"A fall of 3.5%","C":"A fall of 3.5 percentage points","D":"A fall of 21.5 percentage points"},"correctOption":"C","correctAnswer":"A fall of 3.5 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The margin fell from 12.5% to 9.0%, a change of 12.5 minus 9.0, which is a fall of 3.5 percentage points of revenue.","distractor_reasons":{"A":"This expresses the change as a percentage of the earlier margin, which measures relative decline rather than points.","B":"The margin fell by 3.5 points of revenue, so calling it a 3.5% fall confuses points with a relative percentage change.","C":"The margin fell from 12.5% to 9.0%, a change of 12.5 minus 9.0, which is a fall of 3.5 percentage points of revenue.","D":"This adds the two margins rather than subtracting the 2025 figure from the 2024 figure."}}},{"id":"P1_U5_MCQ_1501","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1501","question":"Tarnfield Ceramics in Stoke-on-Trent has made steady profits for eight years and needs $25,000 to replace a kiln. The owner wants funding that adds no debt and keeps full control. Which source of finance fits best?","options":{"A":"Retained earnings ploughed back into the firm","B":"A bank loan secured against the workshop","C":"An invoice discounting arrangement","D":"Issuing ordinary shares to new investors"},"correctOption":"A","correctAnswer":"Retained earnings ploughed back into the firm","questionType":"MCQ","explanation":{"correct_reason":"Retained earnings are profits kept inside Tarnfield Ceramics rather than paid out, so the $25,000 kiln is funded internally without new debt or any outside shareholder diluting the owner's control.","distractor_reasons":{"A":"Retained earnings are profits kept inside Tarnfield Ceramics rather than paid out, so the $25,000 kiln is funded internally without new debt or any outside shareholder diluting the owner's control.","B":"A secured bank loan would create a debt of $25,000 that must be repaid with interest, and the workshop would be used as collateral, so it fails the owner's no-debt requirement.","C":"Invoice discounting raises cash against unpaid invoices and is a form of short-term borrowing, so it would add a liability and a fee rather than keeping Tarnfield Ceramics debt-free.","D":"Issuing ordinary shares to new investors would bring in the $25,000 but would give those investors ownership and voting rights, reducing the original owner's control of the business."}}},{"id":"P1_U5_MCQ_1502","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1502","question":"Ousebank Textiles in Faisalabad expects cash receipts of $96,000 and cash payments of $73,500 during May. Its opening bank balance is $9,000. What is the forecast net cash flow for May?","options":{"A":"$169,500","B":"$31,500","C":"$22,500","D":"$9,000"},"correctOption":"C","correctAnswer":"$22,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is cash inflows less cash outflows, so $96,000 of receipts minus $73,500 of payments gives Ousebank Textiles a forecast net cash inflow of $22,500 in May.","distractor_reasons":{"A":"$169,500 wrongly adds the $96,000 receipts to the $73,500 payments instead of subtracting one from the other, so it is not a net cash flow figure at all.","B":"$31,500 incorrectly includes the $9,000 opening bank balance in the net figure, but the opening balance is carried forward separately and is not part of May's cash flow.","C":"Net cash flow is cash inflows less cash outflows, so $96,000 of receipts minus $73,500 of payments gives Ousebank Textiles a forecast net cash inflow of $22,500 in May.","D":"$9,000 is simply the opening bank balance carried into May, not the change in cash during the month, which must compare receipts with payments."}}},{"id":"P1_U5_MCQ_1503","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1503","question":"Vellore Spice Mills in Chennai reports revenue of $210,000, cost of sales of $128,000 and operating expenses of $46,000. If operating expenses rise by $6,000 with nothing else changing, what happens?","options":{"A":"Gross profit falls by $6,000 and profit for the year is unchanged","B":"Gross profit is unchanged and profit for the year falls by $6,000","C":"Both gross profit and profit for the year fall by $6,000","D":"Neither gross profit nor profit for the year is affected"},"correctOption":"B","correctAnswer":"Gross profit is unchanged and profit for the year falls by $6,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit depends only on revenue less cost of sales, which stay at $210,000 and $128,000, so it remains $82,000; the extra $6,000 of operating expenses reduces profit for the year.","distractor_reasons":{"A":"Gross profit is found before operating expenses are deducted, so a $6,000 rise in expenses cannot reduce the $82,000 gross profit of Vellore Spice Mills.","B":"Gross profit depends only on revenue less cost of sales, which stay at $210,000 and $128,000, so it remains $82,000; the extra $6,000 of operating expenses reduces profit for the year.","C":"Cost of sales and revenue are unchanged at $128,000 and $210,000, so gross profit is unaffected; only profit for the year falls by the extra $6,000.","D":"Profit for the year is gross profit less operating expenses, so an additional $6,000 of expenses must reduce it from $36,000 to $30,000."}}},{"id":"P1_U5_MCQ_1504","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1504","question":"Ridgeway Joinery in Bristol lists inventory of $18,000, trade receivables of $12,000, cash of $5,000, trade payables of $9,000 and a five-year bank loan. Which item is a non-current liability?","options":{"A":"Trade payables of $9,000","B":"Inventory of $18,000","C":"Cash of $5,000","D":"The five-year bank loan"},"correctOption":"D","correctAnswer":"The five-year bank loan","questionType":"MCQ","explanation":{"correct_reason":"A bank loan repayable over five years is a non-current liability because it is not due within one year, unlike the $9,000 of trade payables which are short-term obligations.","distractor_reasons":{"A":"Trade payables of $9,000 are amounts owed to suppliers within a short period, so they are current liabilities rather than long-term obligations of Ridgeway Joinery.","B":"Inventory of $18,000 is a current asset, not a liability of any kind, because it is a stock item expected to be sold or used within the year.","C":"Cash of $5,000 is a current asset held by the business and cannot be a liability, since the joinery owns it rather than owing it to someone else.","D":"A bank loan repayable over five years is a non-current liability because it is not due within one year, unlike the $9,000 of trade payables which are short-term obligations."}}},{"id":"P1_U5_MCQ_1505","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1505","question":"Halden Outfitters in Bergen has current assets of $90,000 and current liabilities of $50,000, giving a current ratio of 1.8:1. What does this ratio mainly show about the business?","options":{"A":"The firm earns 1.8 cents of profit per dollar of sales","B":"The firm has $1.80 of current assets for every $1 of current liabilities","C":"The firm's profit rose by 1.8% during the year","D":"The firm owes $1.80 to suppliers for each dollar of sales"},"correctOption":"B","correctAnswer":"The firm has $1.80 of current assets for every $1 of current liabilities","questionType":"MCQ","explanation":{"correct_reason":"The current ratio compares current assets with current liabilities, so $90,000 divided by $50,000 equals 1.8:1, meaning Halden Outfitters holds $1.80 of short-term assets per $1 owed.","distractor_reasons":{"A":"Profit per dollar of sales is measured by a profit margin, not by the current ratio, which uses the $90,000 of current assets and $50,000 of current liabilities.","B":"The current ratio compares current assets with current liabilities, so $90,000 divided by $50,000 equals 1.8:1, meaning Halden Outfitters holds $1.80 of short-term assets per $1 owed.","C":"A percentage rise in profit is a comparison across two years, whereas the 1.8:1 figure here simply compares current assets of $90,000 with current liabilities of $50,000.","D":"The ratio does not compare amounts owed with sales; it divides $90,000 of current assets by $50,000 of current liabilities, so it is a liquidity measure."}}},{"id":"P1_U5_MCQ_1506","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1506","question":"Marlowe Printing in Leeds borrows $20,000 at a simple interest rate of 6% per year for three years. How much interest will the business pay in total over the three years?","options":{"A":"$3,600","B":"$1,200","C":"$21,200","D":"$23,600"},"correctOption":"A","correctAnswer":"$3,600","questionType":"MCQ","explanation":{"correct_reason":"Simple interest is principal times rate times years, so $20,000 at 6% for three years costs $1,200 each year, giving total interest of $3,600.","distractor_reasons":{"A":"Simple interest is principal times rate times years, so $20,000 at 6% for three years costs $1,200 each year, giving total interest of $3,600.","B":"$1,200 is only one year's interest on the $20,000 loan; the question asks for the total across all three years, which is $3,600.","C":"$21,200 adds one year's $1,200 interest to the $20,000 principal and ignores the interest due in the other two years.","D":"$23,600 is the full amount to be repaid, principal plus $3,600 interest, rather than the interest alone that the question asks for."}}},{"id":"P1_U5_MCQ_1507","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1507","question":"Kirmani Rugs in Istanbul opens June with a bank balance of $14,000. Its forecast net cash flow for June is negative $5,500. What is the forecast closing bank balance at the end of June?","options":{"A":"$19,500","B":"$5,500","C":"$14,000","D":"$8,500"},"correctOption":"D","correctAnswer":"$8,500","questionType":"MCQ","explanation":{"correct_reason":"Closing balance equals opening balance plus net cash flow, so $14,000 plus negative $5,500 gives Kirmani Rugs a forecast closing bank balance of $8,500 at the end of June.","distractor_reasons":{"A":"$19,500 wrongly adds the $5,500 outflow as if it were an inflow, but a negative net cash flow must reduce the $14,000 opening balance.","B":"$5,500 is the net cash outflow itself, not the remaining balance, which must start from the $14,000 brought forward into June.","C":"$14,000 is the opening balance carried into the month and ignores the $5,500 net outflow recorded during June. For Kirmani Rugs, option D is correct: $8,500.","D":"Closing balance equals opening balance plus net cash flow, so $14,000 plus negative $5,500 gives Kirmani Rugs a forecast closing bank balance of $8,500 at the end of June."}}},{"id":"P1_U5_MCQ_1508","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1508","question":"Alderney Foods in Jersey has revenue of $150,000 and cost of sales of $95,000. If cost of sales falls by $8,000 and revenue is unchanged, what is the effect on gross profit?","options":{"A":"Gross profit falls from $55,000 to $47,000","B":"Gross profit stays at $95,000","C":"Gross profit rises from $55,000 to $63,000","D":"Revenue rises by $8,000 as a result"},"correctOption":"C","correctAnswer":"Gross profit rises from $55,000 to $63,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit equals revenue minus cost of sales, so at $150,000 and $95,000 it is $55,000; cutting cost of sales by $8,000 raises gross profit to $63,000.","distractor_reasons":{"A":"A fall in cost of sales increases gross profit rather than reducing it; with revenue fixed at $150,000, the new gross profit is $63,000, not $47,000.","B":"$95,000 is the original cost of sales figure, not gross profit, and after the $8,000 reduction the cost of sales becomes $87,000.","C":"Gross profit equals revenue minus cost of sales, so at $150,000 and $95,000 it is $55,000; cutting cost of sales by $8,000 raises gross profit to $63,000.","D":"Revenue is stated to be unchanged at $150,000, so it cannot rise by $8,000; the change is in cost of sales, which affects gross profit."}}},{"id":"P1_U5_MCQ_1509","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1509","question":"Bellwether Toys in Copenhagen has total assets of $260,000 and total liabilities of $110,000 at the year end. Which statement about its statement of financial position is correct?","options":{"A":"Its equity is $370,000 because assets and liabilities are added","B":"Its liabilities exceed its assets by $150,000","C":"Its equity is $150,000 because assets equal liabilities plus equity","D":"Its total assets must fall to match its liabilities"},"correctOption":"C","correctAnswer":"Its equity is $150,000 because assets equal liabilities plus equity","questionType":"MCQ","explanation":{"correct_reason":"The accounting equation states that assets equal liabilities plus equity, so Bellwether Toys' $260,000 of assets less $110,000 of liabilities leaves $150,000 of equity.","distractor_reasons":{"A":"Adding $260,000 of assets to $110,000 of liabilities gives $370,000, but that is not equity; equity is the residual claim of $150,000.","B":"Assets of $260,000 are greater than liabilities of $110,000, so it is wrong to claim liabilities exceed assets; the difference of $150,000 is positive equity.","C":"The accounting equation states that assets equal liabilities plus equity, so Bellwether Toys' $260,000 of assets less $110,000 of liabilities leaves $150,000 of equity.","D":"There is no requirement for assets to fall: a healthy business simply records the $150,000 difference as equity owed to its owners."}}},{"id":"P1_U5_MCQ_1510","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1510","question":"Cedarline Hotels in Vancouver reports a current ratio of 2.1:1 but an acid test ratio of 1.3:1. What best explains the difference between these two figures?","options":{"A":"The business has no cash at all","B":"Its current liabilities have doubled since last year","C":"Its gross profit margin has fallen sharply","D":"It holds inventory that is excluded from the acid test"},"correctOption":"D","correctAnswer":"It holds inventory that is excluded from the acid test","questionType":"MCQ","explanation":{"correct_reason":"The acid test removes inventory from current assets, so the drop from 2.1:1 to 1.3:1 shows Cedarline Hotels holds stock that is less liquid than its other short-term assets.","distractor_reasons":{"A":"Having no cash would weaken both ratios, but the gap arises specifically because the acid test excludes inventory while the current ratio of 2.1:1 includes it.","B":"Current liabilities appear in the denominator of both ratios, so a change in them would not create the difference between 2.1:1 and 1.3:1.","C":"Gross profit margin comes from the income statement and does not affect either liquidity ratio, which compare current assets with current liabilities.","D":"The acid test removes inventory from current assets, so the drop from 2.1:1 to 1.3:1 shows Cedarline Hotels holds stock that is less liquid than its other short-term assets."}}},{"id":"P1_U5_MCQ_1511","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1511","question":"Drayton Engineering in Sheffield faces a seasonal cash shortfall of up to $18,000 for a few months each winter. Which source of finance is most suitable for this short-term, flexible need?","options":{"A":"A bank overdraft on its current account","B":"A 25-year mortgage on the factory","C":"Issuing new preference shares","D":"Retaining profits for five years"},"correctOption":"A","correctAnswer":"A bank overdraft on its current account","questionType":"MCQ","explanation":{"correct_reason":"An overdraft lets Drayton Engineering borrow up to $18,000 only when needed and repay as cash improves, making it the flexible short-term source for a winter shortfall.","distractor_reasons":{"A":"An overdraft lets Drayton Engineering borrow up to $18,000 only when needed and repay as cash improves, making it the flexible short-term source for a winter shortfall.","B":"A 25-year mortgage is long-term finance secured on property, far too rigid and slow for a temporary $18,000 seasonal shortfall at Drayton Engineering.","C":"Issuing preference shares raises permanent capital and creates dividend obligations, which is unsuitable for a short winter funding gap of about $18,000.","D":"Retaining profits would require surpluses built up over years, so it cannot provide the quick $18,000 needed during the winter months."}}},{"id":"P1_U5_MCQ_1512","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1512","question":"Elmfield Garage in Cork is preparing a monthly cash flow forecast. Which of the following should be recorded as a cash inflow in that forecast?","options":{"A":"Depreciation charged on the workshop equipment","B":"Cash received from customers for repairs","C":"Credit sales made on 30-day terms","D":"Outstanding invoices from unpaid suppliers"},"correctOption":"B","correctAnswer":"Cash received from customers for repairs","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast records actual cash movements, so cash received from customers for repairs is an inflow, unlike depreciation or credit sales which involve no immediate cash.","distractor_reasons":{"A":"Depreciation is a non-cash accounting charge for the wear of equipment, so it never appears as an inflow in Elmfield Garage's cash forecast.","B":"A cash flow forecast records actual cash movements, so cash received from customers for repairs is an inflow, unlike depreciation or credit sales which involve no immediate cash.","C":"A credit sale made on 30-day terms generates no cash at the moment of sale, so it cannot be recorded as an inflow until the customer actually pays.","D":"Outstanding supplier invoices represent amounts Elmfield Garage owes, not cash received, and would only appear as payments when they are settled."}}},{"id":"P1_U5_MCQ_1513","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1513","question":"Fernbank Clinic in Nairobi has revenue of $120,000, cost of sales of $48,000 and operating expenses of $39,000. Which figure represents its profit for the year?","options":{"A":"$48,000","B":"$72,000","C":"$39,000","D":"$33,000"},"correctOption":"D","correctAnswer":"$33,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is revenue minus cost of sales minus operating expenses, so $120,000 less $48,000 gives $72,000 gross profit, then less $39,000 leaves $33,000.","distractor_reasons":{"A":"$48,000 is the cost of sales, an expense rather than a profit, and it is deducted before profit for the year can be calculated.","B":"$72,000 is the gross profit of Fernbank Clinic, calculated before the $39,000 of operating expenses are deducted. For Fernbank Clinic, option D is correct: $33,000.","C":"$39,000 is the operating expenses figure on its own and is not a measure of the clinic's profit. For Fernbank Clinic, option D is correct: $33,000.","D":"Profit for the year is revenue minus cost of sales minus operating expenses, so $120,000 less $48,000 gives $72,000 gross profit, then less $39,000 leaves $33,000."}}},{"id":"P1_U5_MCQ_1514","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1514","question":"Grangeway Stores in Manchester reports current assets of $78,000 and current liabilities of $44,000 in its year-end statement of financial position. What is the working capital of the business?","options":{"A":"$34,000","B":"$122,000","C":"$44,000","D":"$78,000"},"correctOption":"A","correctAnswer":"$34,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so $78,000 less $44,000 leaves $34,000 for Grangeway Stores to fund its day-to-day operations.","distractor_reasons":{"A":"Working capital is current assets minus current liabilities, so $78,000 less $44,000 leaves $34,000 for Grangeway Stores to fund its day-to-day operations.","B":"$122,000 wrongly adds current assets and current liabilities instead of subtracting liabilities from assets. For Grangeway Stores, option A is correct: $34,000.","C":"$44,000 is simply the current liabilities figure and ignores the $78,000 of current assets held by Grangeway Stores. For Grangeway Stores, option A is correct: $34,000.","D":"$78,000 is the total current assets and does not deduct the $44,000 owed, so it cannot be the working capital."}}},{"id":"P1_U5_MCQ_1515","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1515","question":"Seabright Shellfish in Halifax saw its gross profit margin fall from 32% last year to 24% this year. Which change most directly explains this fall?","options":{"A":"Operating expenses were reduced by 10%","B":"Revenue grew while cost of sales stayed the same","C":"Cost of sales rose faster than revenue","D":"The business repaid a long-term loan"},"correctOption":"C","correctAnswer":"Cost of sales rose faster than revenue","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin compares gross profit with revenue, so a fall from 32% to 24% means cost of sales at Seabright Shellfish increased relative to the sales revenue earned.","distractor_reasons":{"A":"Operating expenses do not enter gross profit, so a 10% reduction there would affect profit for the year rather than the gross margin of 24%.","B":"If revenue rose while cost of sales was unchanged, gross profit margin would improve, not fall from 32% to 24%.","C":"Gross profit margin compares gross profit with revenue, so a fall from 32% to 24% means cost of sales at Seabright Shellfish increased relative to the sales revenue earned.","D":"Repaying a long-term loan changes the balance sheet and interest charge, not the relationship between revenue and cost of sales behind the margin."}}},{"id":"P1_U5_MCQ_1516","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1516","question":"Ivanhoe Motors in Perth wants to raise $300,000 while keeping its existing voting control. Which source of finance gives investors a fixed dividend but no ordinary voting rights?","options":{"A":"Ordinary shares","B":"Preference shares","C":"A bank overdraft","D":"Trade credit from suppliers"},"correctOption":"B","correctAnswer":"Preference shares","questionType":"MCQ","explanation":{"correct_reason":"Preference shares usually carry a fixed dividend and no ordinary voting rights, so Ivanhoe Motors can raise $300,000 without diluting the existing shareholders' control.","distractor_reasons":{"A":"Ordinary shares normally carry voting rights, so issuing them for $300,000 would dilute the current owners' control of Ivanhoe Motors.","B":"Preference shares usually carry a fixed dividend and no ordinary voting rights, so Ivanhoe Motors can raise $300,000 without diluting the existing shareholders' control.","C":"An overdraft is borrowed money that must be repaid and charges interest; it gives no dividend and does not give investors a share of ownership.","D":"Trade credit is simply delayed payment to suppliers and cannot raise $300,000 of permanent capital for the expansion. For Ivanhoe Motors, option B is correct: preference shares."}}},{"id":"P1_U5_MCQ_1517","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1517","question":"Juniper Gardens, a landscaping firm in Kyoto, is preparing a cash flow forecast for the next six months. What is the main purpose of such a forecast?","options":{"A":"To calculate the tax due on last year's profit","B":"To predict cash shortages and surpluses so funding can be planned","C":"To value the business's non-current assets","D":"To record the owners' drawings for the year"},"correctOption":"B","correctAnswer":"To predict cash shortages and surpluses so funding can be planned","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast predicts inflows and outflows so Juniper Gardens can spot a future cash shortage or surplus in advance and arrange finance or investment accordingly.","distractor_reasons":{"A":"Tax on last year's profit is based on historical accounts, not a forward-looking forecast of monthly cash receipts and payments.","B":"A cash flow forecast predicts inflows and outflows so Juniper Gardens can spot a future cash shortage or surplus in advance and arrange finance or investment accordingly.","C":"Valuing non-current assets belongs in the statement of financial position, not in a forecast of short-term cash movements. For Juniper Gardens, option B is correct: to predict cash shortages and surpluses so funding can be planned.","D":"Owners' drawings are recorded in accounting records, but they are only one possible cash outflow, not the purpose of the whole forecast."}}},{"id":"P1_U5_MCQ_1518","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1518","question":"Kingsway Bakeries in Melbourne recorded revenue of $240,000, cost of sales of $156,000 and operating expenses of $52,000. What was its profit for the year?","options":{"A":"$84,000","B":"$52,000","C":"$32,000","D":"$208,000"},"correctOption":"C","correctAnswer":"$32,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $240,000 less $156,000, or $84,000; deducting the $52,000 of operating expenses leaves Kingsway Bakeries with a profit for the year of $32,000.","distractor_reasons":{"A":"$84,000 is the gross profit before the $52,000 of operating expenses are taken away, not the final profit for the year.","B":"$52,000 is the operating expenses figure itself and is an amount deducted, not a profit earned by Kingsway Bakeries. For Kingsway Bakeries, option C is correct: $32,000.","C":"Gross profit is $240,000 less $156,000, or $84,000; deducting the $52,000 of operating expenses leaves Kingsway Bakeries with a profit for the year of $32,000.","D":"$208,000 wrongly adds cost of sales and operating expenses to revenue rather than subtracting expenses from revenue. For Kingsway Bakeries, option C is correct: $32,000."}}},{"id":"P1_U5_MCQ_1519","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1519","question":"Larkfield Builders in Dublin owns a crane bought for $90,000 that it expects to use for many years. How should the crane appear in the statement of financial position?","options":{"A":"As an expense in the period it was bought","B":"As a current asset because it is valuable","C":"As a current liability","D":"As a non-current asset, shown at cost less accumulated depreciation"},"correctOption":"D","correctAnswer":"As a non-current asset, shown at cost less accumulated depreciation","questionType":"MCQ","explanation":{"correct_reason":"A crane used over many years is a non-current asset, so Larkfield Builders records its $90,000 cost and reduces it each year by accumulated depreciation.","distractor_reasons":{"A":"Charging the whole $90,000 as an immediate expense would ignore the crane's benefit across several years and distort the year's profit.","B":"Being valuable does not make an item a current asset; the crane is not intended for sale within the year, so it is non-current.","C":"A crane owned by Larkfield Builders is an asset, not an amount owed, so it cannot be reported as a current liability.","D":"A crane used over many years is a non-current asset, so Larkfield Builders records its $90,000 cost and reduces it each year by accumulated depreciation."}}},{"id":"P1_U5_MCQ_1520","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1520","question":"Meridian Textiles in Lisbon reports that its profit margin has fallen from 9% to 5% even though revenue is unchanged. Which change best explains this?","options":{"A":"Operating expenses have risen sharply","B":"Cost of sales has fallen","C":"Current liabilities have decreased","D":"The company issued new shares"},"correctOption":"A","correctAnswer":"Operating expenses have risen sharply","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year divided by revenue, so with revenue unchanged a fall from 9% to 5% means operating expenses at Meridian Textiles have risen.","distractor_reasons":{"A":"Profit margin is profit for the year divided by revenue, so with revenue unchanged a fall from 9% to 5% means operating expenses at Meridian Textiles have risen.","B":"A fall in cost of sales would increase gross profit and raise the profit margin, not reduce it from 9% to 5%.","C":"Current liabilities affect liquidity ratios, not the profit margin, which compares profit with revenue. For Meridian Textiles, option A is correct: operating expenses have risen sharply.","D":"Issuing new shares changes the capital structure but does not by itself reduce the profit earned on each dollar of revenue."}}},{"id":"P1_U5_MCQ_1521","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1521","question":"Northgate Pharmacy in Oslo needs $120,000 to open a new branch. It wants a fixed repayment schedule and to keep full ownership. Which source of finance is most appropriate?","options":{"A":"Issuing ordinary shares to investors","B":"A ten-year bank loan","C":"An overdraft on the current account","D":"Factoring its receivables"},"correctOption":"B","correctAnswer":"A ten-year bank loan","questionType":"MCQ","explanation":{"correct_reason":"A ten-year bank loan provides the $120,000 with fixed repayments and leaves Northgate Pharmacy's ownership untouched, apart from the interest cost of the debt.","distractor_reasons":{"A":"Issuing ordinary shares would dilute the existing owners' control of Northgate Pharmacy, which conflicts with their wish to keep full ownership.","B":"A ten-year bank loan provides the $120,000 with fixed repayments and leaves Northgate Pharmacy's ownership untouched, apart from the interest cost of the debt.","C":"An overdraft is short-term and repayable on demand, so it cannot sensibly fund a new branch that will generate returns over ten years.","D":"Factoring receivables releases cash tied up in invoices but is costly and short-term, not suitable for $120,000 of long-term branch investment."}}},{"id":"P1_U5_MCQ_1522","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1522","question":"Orchardvale Creamery in Auckland wants to improve its monthly cash flow after a slow summer. Which of the following actions would most reliably increase its cash inflows in the short term?","options":{"A":"Offering discounts for prompt payment by customers","B":"Buying a new delivery van for cash","C":"Increasing stock levels of cheese","D":"Paying suppliers earlier than required"},"correctOption":"A","correctAnswer":"Offering discounts for prompt payment by customers","questionType":"MCQ","explanation":{"correct_reason":"Discounts for prompt payment encourage customers to settle invoices sooner, bringing cash into Orchardvale Creamery earlier and improving its short-term cash flow.","distractor_reasons":{"A":"Discounts for prompt payment encourage customers to settle invoices sooner, bringing cash into Orchardvale Creamery earlier and improving its short-term cash flow.","B":"Buying a van for cash is an outflow that reduces the bank balance, so it would worsen rather than improve short-term cash flow.","C":"Building up cheese stock ties up cash in inventory, delaying the conversion of purchases into sales revenue and weakening cash flow.","D":"Paying suppliers earlier accelerates cash outflows, which reduces the cash available to Orchardvale Creamery in the current month. For Orchardvale Creamery, option A is correct: offering discounts for prompt payment by customers."}}},{"id":"P1_U5_MCQ_1523","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1523","question":"Penrose Garments in Johannesburg had revenue of $180,000 before customer returns of $12,000. Cost of sales was $96,000. What is the correct gross profit figure?","options":{"A":"$84,000","B":"$96,000","C":"$12,000","D":"$72,000"},"correctOption":"D","correctAnswer":"$72,000","questionType":"MCQ","explanation":{"correct_reason":"Returns of $12,000 reduce revenue from $180,000 to $168,000, so gross profit is $168,000 less cost of sales of $96,000, giving $72,000 for Penrose Garments.","distractor_reasons":{"A":"$84,000 uses the original $180,000 revenue and ignores the $12,000 of returns that reduce sales at Penrose Garments. For Penrose Garments, option D is correct: $72,000.","B":"$96,000 is the cost of sales figure, an expense, and is not the gross profit earned by Penrose Garments. For Penrose Garments, option D is correct: $72,000.","C":"$12,000 is the value of goods returned by customers and is deducted from revenue, not a profit figure. For Penrose Garments, option D is correct: $72,000.","D":"Returns of $12,000 reduce revenue from $180,000 to $168,000, so gross profit is $168,000 less cost of sales of $96,000, giving $72,000 for Penrose Garments."}}},{"id":"P1_U5_MCQ_1524","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1524","question":"Quarryhill Aggregates in Glasgow has retained earnings of $45,000 and share capital of $80,000 at its year end. Where are these two amounts reported in its accounts?","options":{"A":"As current liabilities in the statement of financial position","B":"As operating expenses in the income statement","C":"As equity in the statement of financial position","D":"As non-current assets"},"correctOption":"C","correctAnswer":"As equity in the statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Share capital of $80,000 and retained earnings of $45,000 together form the equity section of Quarryhill Aggregates' statement of financial position, representing the owners' claim.","distractor_reasons":{"A":"Equity is not a liability: the $80,000 and $45,000 are owed to owners, not to outside creditors of Quarryhill Aggregates.","B":"These figures are balances built up over time and do not appear as operating expenses in the profit and loss account.","C":"Share capital of $80,000 and retained earnings of $45,000 together form the equity section of Quarryhill Aggregates' statement of financial position, representing the owners' claim.","D":"Share capital and retained earnings are claims on assets, not assets themselves such as the quarry's non-current equipment. For Quarryhill Aggregates, option C is correct: as equity in the statement of financial position."}}},{"id":"P1_U5_MCQ_1525","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1525","question":"Calderwood Hotels in Edinburgh has current assets of $120,000, of which $30,000 is inventory, and current liabilities of $60,000. What is its acid test ratio?","options":{"A":"2.0:1","B":"1.0:1","C":"1.5:1","D":"0.5:1"},"correctOption":"C","correctAnswer":"1.5:1","questionType":"MCQ","explanation":{"correct_reason":"Acid test is current assets minus inventory divided by current liabilities, so ($120,000 less $30,000) divided by $60,000 gives Calderwood Hotels an acid test ratio of 1.5:1.","distractor_reasons":{"A":"2.0:1 is the current ratio, calculated as $120,000 divided by $60,000, which incorrectly includes the $30,000 of inventory. For Calderwood Hotels, option C is correct: 1.5:1.","B":"1.0:1 would require liquid assets of $60,000, but excluding inventory leaves $90,000 for Calderwood Hotels. For Calderwood Hotels, option C is correct: 1.5:1.","C":"Acid test is current assets minus inventory divided by current liabilities, so ($120,000 less $30,000) divided by $60,000 gives Calderwood Hotels an acid test ratio of 1.5:1.","D":"0.5:1 wrongly divides only the $30,000 of inventory by $60,000 of liabilities rather than using the liquid current assets. For Calderwood Hotels, option C is correct: 1.5:1."}}},{"id":"P1_U5_MCQ_1526","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1526","question":"Sablefield Timber in Tallinn borrows $15,000 at 8% per year simple interest for two years to buy a saw. How much interest will it pay altogether?","options":{"A":"$1,200","B":"$17,400","C":"$15,000","D":"$2,400"},"correctOption":"D","correctAnswer":"$2,400","questionType":"MCQ","explanation":{"correct_reason":"Simple interest equals principal times rate times time, so $15,000 at 8% costs $1,200 a year and over two years Sablefield Timber pays $2,400 in interest.","distractor_reasons":{"A":"$1,200 is a single year's interest on $15,000 at 8%, but the loan runs for two years, so more interest is due.","B":"$17,400 is the total repaid, principal plus $2,400 interest, rather than the interest charge requested by the question. For Sablefield Timber, option D is correct: $2,400.","C":"$15,000 is the amount borrowed and ignores the interest that Sablefield Timber must pay over the two years. For Sablefield Timber, option D is correct: $2,400.","D":"Simple interest equals principal times rate times time, so $15,000 at 8% costs $1,200 a year and over two years Sablefield Timber pays $2,400 in interest."}}},{"id":"P1_U5_MCQ_1527","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1527","question":"Tidewater Fisheries in Reykjavik forecast cash receipts of $58,000 and cash payments of $64,000 for the month of July. What is its forecast net cash flow for July?","options":{"A":"Negative $6,000","B":"$6,000","C":"$122,000","D":"Negative $122,000"},"correctOption":"A","correctAnswer":"Negative $6,000","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is receipts less payments, so $58,000 minus $64,000 gives Tidewater Fisheries a negative net cash flow of $6,000 for July.","distractor_reasons":{"A":"Net cash flow is receipts less payments, so $58,000 minus $64,000 gives Tidewater Fisheries a negative net cash flow of $6,000 for July.","B":"$6,000 has the right size but the wrong sign, since outflows of $64,000 exceed inflows of $58,000 at Tidewater Fisheries.","C":"$122,000 wrongly adds receipts and payments and also has the wrong direction; net cash flow must subtract payments from receipts.","D":"A negative $122,000 adds the two figures and then applies a minus sign, but the shortfall is only the $6,000 difference."}}},{"id":"P1_U5_MCQ_1528","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1528","question":"Umber Printing in Turin buys paper worth $22,000 during the year. Its inventory of paper rose by $4,000. What is the cost of sales figure for paper?","options":{"A":"$22,000","B":"$18,000","C":"$26,000","D":"$4,000"},"correctOption":"B","correctAnswer":"$18,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales equals purchases plus opening inventory minus closing inventory, so the $4,000 rise in inventory means only $18,000 of the $22,000 purchased was used.","distractor_reasons":{"A":"$22,000 is the total purchases and ignores that $4,000 of paper remains in closing inventory at Umber Printing. For Umber Printing, option B is correct: $18,000.","B":"Cost of sales equals purchases plus opening inventory minus closing inventory, so the $4,000 rise in inventory means only $18,000 of the $22,000 purchased was used.","C":"$26,000 wrongly adds the $4,000 inventory increase to purchases, when an increase in stock should instead be deducted. For Umber Printing, option B is correct: $18,000.","D":"$4,000 is merely the increase in inventory, not the cost of paper consumed in printing during the year. For Umber Printing, option B is correct: $18,000."}}},{"id":"P1_U5_MCQ_1529","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1529","question":"Valeview Engineering in Birmingham owns land held for long-term expansion and also holds goods ready for sale. Which pair correctly classifies these two items in its accounts?","options":{"A":"Both are current assets","B":"Land is a current asset; goods for sale are non-current","C":"Both are non-current liabilities","D":"Land is a non-current asset; goods for sale are inventory, a current asset"},"correctOption":"D","correctAnswer":"Land is a non-current asset; goods for sale are inventory, a current asset","questionType":"MCQ","explanation":{"correct_reason":"Land kept for long-term expansion is a non-current asset, while goods held for sale are inventory and count as a current asset of Valeview Engineering.","distractor_reasons":{"A":"Land held for years is not a current asset, since it is not expected to be sold or consumed within the next twelve months.","B":"The classification is reversed: land is long-term and goods for sale are short-term inventory at Valeview Engineering. For Valeview Engineering, option D is correct: land is a non-current asset; goods for sale are inventory, a current asset.","C":"Neither item is a liability, because Valeview Engineering owns both the land and the goods rather than owing them to outsiders.","D":"Land kept for long-term expansion is a non-current asset, while goods held for sale are inventory and count as a current asset of Valeview Engineering."}}},{"id":"P1_U5_MCQ_1530","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1530","question":"Westbourne Clothing in Galway has seen its current ratio rise from 1.2:1 to 1.9:1 over two years. What is the most likely implication of this change?","options":{"A":"Short-term liquidity has improved","B":"Profit margins have definitely increased","C":"Long-term debt has certainly been repaid","D":"Inventory has certainly been reduced"},"correctOption":"A","correctAnswer":"Short-term liquidity has improved","questionType":"MCQ","explanation":{"correct_reason":"A higher current ratio from 1.2:1 to 1.9:1 means Westbourne Clothing now has more current assets relative to current liabilities, indicating improved short-term liquidity.","distractor_reasons":{"A":"A higher current ratio from 1.2:1 to 1.9:1 means Westbourne Clothing now has more current assets relative to current liabilities, indicating improved short-term liquidity.","B":"The current ratio uses current assets and liabilities, so it says nothing certain about the profit margin earned on sales.","C":"A rise in the ratio does not prove long-term debt was repaid, since it depends on current assets and current liabilities only.","D":"Inventory could have risen and still lifted the ratio, so a fall in inventory is not a necessary consequence of the change."}}},{"id":"P1_U5_MCQ_1531","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1531","question":"Xanthe Wines in Cape Town buys grapes from local growers but does not pay them until 60 days after delivery. What is this payment arrangement called?","options":{"A":"A bank overdraft","B":"Leasing","C":"Trade credit","D":"Preference shares"},"correctOption":"C","correctAnswer":"Trade credit","questionType":"MCQ","explanation":{"correct_reason":"Buying goods now and paying the supplier 60 days later is trade credit, which gives Xanthe Wines short-term interest-free use of the grapes before settlement.","distractor_reasons":{"A":"An overdraft is borrowing from a bank on the current account, not delayed payment to a grape supplier in Cape Town.","B":"Leasing involves renting an asset such as equipment, whereas Xanthe Wines is simply deferring payment for grapes already bought. For Xanthe Wines, option C is correct: trade credit.","C":"Buying goods now and paying the supplier 60 days later is trade credit, which gives Xanthe Wines short-term interest-free use of the grapes before settlement.","D":"Preference shares are an ownership investment paying a fixed dividend and are unrelated to the 60-day payment terms with growers."}}},{"id":"P1_U5_MCQ_1532","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1532","question":"Yarwood Joinery in Helsinki includes depreciation of $7,000 in its profit calculation. How should depreciation be treated in a cash flow forecast for the coming year?","options":{"A":"Added as a cash inflow of $7,000","B":"Excluded because it involves no cash movement","C":"Treated as a cash payment of $7,000","D":"Shown as an increase in the bank balance"},"correctOption":"B","correctAnswer":"Excluded because it involves no cash movement","questionType":"MCQ","explanation":{"correct_reason":"Depreciation is a non-cash charge allocating the cost of equipment over time, so the $7,000 must be left out of Yarwood Joinery's cash flow forecast.","distractor_reasons":{"A":"Depreciation does not generate any cash, so adding $7,000 as an inflow would overstate the actual cash receipts of Yarwood Joinery.","B":"Depreciation is a non-cash charge allocating the cost of equipment over time, so the $7,000 must be left out of Yarwood Joinery's cash flow forecast.","C":"No cash is paid when depreciation is charged, so recording $7,000 as an outflow would wrongly reduce the forecast bank balance.","D":"The bank balance only changes when cash actually moves, so a book entry of $7,000 cannot increase it. For Yarwood Joinery, option B is correct: excluded because it involves no cash movement."}}},{"id":"P1_U5_MCQ_1533","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1533","question":"Zephyr Sports in Taipei has gross profit of $66,000 and profit for the year of $18,000. What explains the difference of $48,000 between them in its accounts?","options":{"A":"Cost of sales of $48,000","B":"Operating expenses of $48,000","C":"Revenue of $48,000","D":"Tax of $48,000"},"correctOption":"B","correctAnswer":"Operating expenses of $48,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is gross profit less operating expenses, so the $48,000 gap between $66,000 and $18,000 represents Zephyr Sports' operating expenses.","distractor_reasons":{"A":"Cost of sales is deducted before gross profit of $66,000 is reached, so it cannot explain the difference from profit for the year.","B":"Profit for the year is gross profit less operating expenses, so the $48,000 gap between $66,000 and $18,000 represents Zephyr Sports' operating expenses.","C":"Revenue is the starting figure above gross profit and does not appear as a deduction between the two profit figures of Zephyr Sports.","D":"Tax may be one expense, but the whole $48,000 difference is the total operating expenses of Zephyr Sports, not tax alone."}}},{"id":"P1_U5_MCQ_1534","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1534","question":"Ashgrove Nurseries in Kampala, Uganda, reports current assets of $55,000 and current liabilities of $30,000 at the year end. What is the working capital available to Ashgrove Nurseries?","options":{"A":"$85,000","B":"$30,000","C":"$25,000","D":"$55,000"},"correctOption":"C","correctAnswer":"$25,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital equals current assets less current liabilities, so $55,000 minus $30,000 gives Ashgrove Nurseries $25,000 to support daily operations.","distractor_reasons":{"A":"$85,000 adds the two figures rather than subtracting the $30,000 owed from the $55,000 of current assets. For Ashgrove Nurseries, option C is correct: $25,000.","B":"$30,000 is only the current liabilities and leaves out the $55,000 of current assets available to Ashgrove Nurseries. For Ashgrove Nurseries, option C is correct: $25,000.","C":"Working capital equals current assets less current liabilities, so $55,000 minus $30,000 gives Ashgrove Nurseries $25,000 to support daily operations.","D":"$55,000 is the full current assets figure and fails to deduct the $30,000 owed by Ashgrove Nurseries. For Ashgrove Nurseries, option C is correct: $25,000."}}},{"id":"P1_U5_MCQ_1535","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1535","question":"Birchfield Motors in Bratislava reports a return on capital employed of 14% this year. What does this measure tell you about the performance of the business?","options":{"A":"The share of revenue retained as gross profit","B":"The percentage of current assets funded by liabilities","C":"The growth in sales compared with last year","D":"Operating profit as a percentage of capital employed"},"correctOption":"D","correctAnswer":"Operating profit as a percentage of capital employed","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed divides operating profit by capital employed, so Birchfield Motors' 14% shows how effectively its long-term capital generates operating profit.","distractor_reasons":{"A":"Gross profit as a share of revenue is the gross profit margin, not the 14% return on capital employed of Birchfield Motors.","B":"The funding of assets by liabilities is a liquidity or debt measure and is not the return earned on capital employed.","C":"Sales growth compares revenue over two years, whereas 14% relates operating profit to the capital invested in Birchfield Motors. For Birchfield Motors, option D is correct: operating profit as a percentage of capital employed.","D":"Return on capital employed divides operating profit by capital employed, so Birchfield Motors' 14% shows how effectively its long-term capital generates operating profit."}}},{"id":"P1_U5_MCQ_1536","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1536","question":"Crestline Hotels in Phuket needs delivery vehicles but wants to avoid a large upfront purchase. Which source of finance lets it use the vehicles while paying periodic rentals?","options":{"A":"Using retained earnings to buy them outright","B":"A five-year bank loan","C":"Leasing the vehicles","D":"Issuing ordinary shares"},"correctOption":"C","correctAnswer":"Leasing the vehicles","questionType":"MCQ","explanation":{"correct_reason":"Leasing lets Crestline Hotels use vehicles and pay regular rentals without buying them outright, preserving cash while spreading the cost over the lease term.","distractor_reasons":{"A":"Buying outright with retained earnings uses a large cash sum and leaves Crestline Hotels owning vehicles that may fall in value.","B":"A bank loan would still make Crestline Hotels the owner of the vehicles and would require interest and regular repayments.","C":"Leasing lets Crestline Hotels use vehicles and pay regular rentals without buying them outright, preserving cash while spreading the cost over the lease term.","D":"Issuing shares raises capital but still involves purchasing the vehicles, so it does not avoid the large upfront cost. For Crestline Hotels, option C is correct: leasing the vehicles."}}},{"id":"P1_U5_MCQ_1537","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1537","question":"Dunmore Textiles in Sofia begins August with $20,000 in the bank. It expects receipts of $76,000 and payments of $81,500 during August. What is the forecast closing balance?","options":{"A":"$14,500","B":"$25,500","C":"$5,500","D":"$97,500"},"correctOption":"A","correctAnswer":"$14,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $76,000 less $81,500, or negative $5,500, so the $20,000 opening balance falls to a forecast closing balance of $14,500.","distractor_reasons":{"A":"Net cash flow is $76,000 less $81,500, or negative $5,500, so the $20,000 opening balance falls to a forecast closing balance of $14,500.","B":"$25,500 wrongly adds the $5,500 shortfall to the opening balance instead of subtracting it from $20,000. For Dunmore Textiles, option A is correct: $14,500.","C":"$5,500 is the net outflow itself and ignores the $20,000 already held at the start of August. For Dunmore Textiles, option A is correct: $14,500.","D":"$97,500 adds receipts to the opening balance but fails to deduct the $81,500 of payments made during August. For Dunmore Textiles, option A is correct: $14,500."}}},{"id":"P1_U5_MCQ_1538","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1538","question":"Everly Foods in Porto reports revenue of $320,000 and cost of sales of $208,000 for the year. What is its gross profit for that year?","options":{"A":"$208,000","B":"$528,000","C":"$112,000","D":"$320,000"},"correctOption":"C","correctAnswer":"$112,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue less cost of sales, so Everly Foods' $320,000 of revenue minus $208,000 of cost of sales gives $112,000.","distractor_reasons":{"A":"$208,000 is the cost of sales, an expense deducted from revenue, and is not a profit figure for Everly Foods.","B":"$528,000 wrongly adds revenue and cost of sales rather than subtracting the $208,000 expense from the $320,000 revenue. For Everly Foods, option C is correct: $112,000.","C":"Gross profit is revenue less cost of sales, so Everly Foods' $320,000 of revenue minus $208,000 of cost of sales gives $112,000.","D":"$320,000 is the revenue figure before any costs are deducted, so it cannot be the gross profit of Everly Foods."}}},{"id":"P1_U5_MCQ_1539","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1539","question":"Fairholme Stores in Cardiff buys $15,000 of inventory from suppliers on credit. What is the immediate effect of this transaction on its statement of financial position?","options":{"A":"Current assets fall and current liabilities rise","B":"Current assets and current liabilities both rise by $15,000","C":"Non-current assets rise by $15,000","D":"Equity falls by $15,000"},"correctOption":"B","correctAnswer":"Current assets and current liabilities both rise by $15,000","questionType":"MCQ","explanation":{"correct_reason":"Buying inventory on credit increases stock, a current asset, by $15,000 and creates an equal trade payable, a current liability, leaving net assets unchanged.","distractor_reasons":{"A":"Inventory is an asset that increases, not falls, when Fairholme Stores buys $15,000 of stock on credit terms. For Fairholme Stores, option B is correct: current assets and current liabilities both rise by $15,000.","B":"Buying inventory on credit increases stock, a current asset, by $15,000 and creates an equal trade payable, a current liability, leaving net assets unchanged.","C":"Inventory held for resale is a current asset, not a non-current asset such as premises or equipment of Fairholme Stores.","D":"No owner's claim is reduced by buying stock on credit; equity changes only through profit or drawings. For Fairholme Stores, option B is correct: current assets and current liabilities both rise by $15,000."}}},{"id":"P1_U5_MCQ_1540","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1540","question":"Greenvale Farms in Nelson, New Zealand, has a current ratio of 4.2:1 at the year end. Which interpretation of this high figure is most valid for the business?","options":{"A":"The business is certainly highly profitable","B":"Its long-term loans must be very small","C":"Its acid test ratio must be higher than 4.2:1","D":"It may be holding idle current assets that could be used more productively"},"correctOption":"D","correctAnswer":"It may be holding idle current assets that could be used more productively","questionType":"MCQ","explanation":{"correct_reason":"A current ratio of 4.2:1 suggests Greenvale Farms may be tying up too much cash or stock in current assets instead of investing them in higher-return opportunities.","distractor_reasons":{"A":"A high current ratio is a liquidity measure and does not prove high profitability, which depends on revenue and costs.","B":"The ratio compares current assets with current liabilities, so it says nothing about the size of long-term loans. For Greenvale Farms, option D is correct: it may be holding idle current assets that could be used more productively.","C":"The acid test excludes inventory and is normally lower than the current ratio, not higher than 4.2:1. For Greenvale Farms, option D is correct: it may be holding idle current assets that could be used more productively.","D":"A current ratio of 4.2:1 suggests Greenvale Farms may be tying up too much cash or stock in current assets instead of investing them in higher-return opportunities."}}},{"id":"P1_U5_MCQ_1541","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1541","question":"Harrowgate Printers in Ripon has $30,000 of undistributed profit and wants to buy a press without borrowing. Which category of finance does this represent in accounting terms?","options":{"A":"External equity finance","B":"External debt finance","C":"Internal finance","D":"Bank finance"},"correctOption":"C","correctAnswer":"Internal finance","questionType":"MCQ","explanation":{"correct_reason":"Undistributed profit kept in the business is retained earnings, an internal source, so the $30,000 press can be bought without borrowing or issuing shares.","distractor_reasons":{"A":"External equity would involve new shareholders, but the $30,000 comes from profits already earned inside Harrowgate Printers. For Harrowgate Printers, option C is correct: internal finance.","B":"No borrowing takes place, so this is not external debt finance and no interest or repayment obligation arises. For Harrowgate Printers, option C is correct: internal finance.","C":"Undistributed profit kept in the business is retained earnings, an internal source, so the $30,000 press can be bought without borrowing or issuing shares.","D":"Bank finance would be a loan or overdraft, whereas Harrowgate Printers is using its own accumulated profits to buy the press."}}},{"id":"P1_U5_MCQ_1542","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1542","question":"Indera Textiles in Surabaya lists expected sales of $140,000 in its cash flow forecast. Why might actual cash received be lower than this figure in practice?","options":{"A":"Because depreciation is included","B":"Because all sales are for cash","C":"Because the forecast ignores outflows","D":"Because some customers may pay later than expected"},"correctOption":"D","correctAnswer":"Because some customers may pay later than expected","questionType":"MCQ","explanation":{"correct_reason":"Sales of $140,000 may be on credit, so if customers pay later than expected the actual cash received by Indera Textiles falls below the forecast figure.","distractor_reasons":{"A":"Depreciation is not a cash item and appears in neither cash receipts nor the reason customers pay late. For Indera Textiles, option D is correct: because some customers may pay later than expected.","B":"If all $140,000 of sales were for cash, receipts would match the forecast, not be lower than the predicted figure.","C":"Cash flow forecasts include both inflows and outflows, so ignoring outflows would not explain lower cash receipts at Indera Textiles.","D":"Sales of $140,000 may be on credit, so if customers pay later than expected the actual cash received by Indera Textiles falls below the forecast figure."}}},{"id":"P1_U5_MCQ_1543","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1543","question":"Jubilee Catering in Accra had revenue of $95,000, cost of sales of $52,000 and operating expenses of $28,000. What was its profit for the year?","options":{"A":"$15,000","B":"$43,000","C":"$28,000","D":"$175,000"},"correctOption":"A","correctAnswer":"$15,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $95,000 less $52,000, or $43,000; subtracting $28,000 of operating expenses leaves Jubilee Catering with a profit for the year of $15,000.","distractor_reasons":{"A":"Gross profit is $95,000 less $52,000, or $43,000; subtracting $28,000 of operating expenses leaves Jubilee Catering with a profit for the year of $15,000.","B":"$43,000 is gross profit before the $28,000 of operating expenses are deducted from Jubilee Catering's figures. For Jubilee Catering, option A is correct: $15,000.","C":"$28,000 is the operating expenses amount and is a deduction, not the profit earned by Jubilee Catering. For Jubilee Catering, option A is correct: $15,000.","D":"$175,000 adds revenue, cost of sales and expenses instead of subtracting costs from the $95,000 of revenue. For Jubilee Catering, option A is correct: $15,000."}}},{"id":"P1_U5_MCQ_1544","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1544","question":"Kestrel Outboards in Kingston has total assets of $310,000 and total liabilities of $175,000 at the year end. What is the value of total equity in the business?","options":{"A":"$485,000","B":"$135,000","C":"$175,000","D":"$310,000"},"correctOption":"B","correctAnswer":"$135,000","questionType":"MCQ","explanation":{"correct_reason":"Equity equals total assets less total liabilities, so Kestrel Outboards' $310,000 of assets minus $175,000 of liabilities leaves $135,000 belonging to the owners.","distractor_reasons":{"A":"$485,000 adds assets and liabilities, but equity is the residual after deducting liabilities from assets. For Kestrel Outboards, option B is correct: $135,000.","B":"Equity equals total assets less total liabilities, so Kestrel Outboards' $310,000 of assets minus $175,000 of liabilities leaves $135,000 belonging to the owners.","C":"$175,000 is the liabilities figure, not the owners' residual claim on Kestrel Outboards. For Kestrel Outboards, option B is correct: $135,000.","D":"$310,000 is total assets and ignores the $175,000 owed to creditors of Kestrel Outboards. For Kestrel Outboards, option B is correct: $135,000."}}},{"id":"P1_U5_MCQ_1545","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1545","question":"Lysander Foods in Nicosia has revenue of $250,000 and gross profit of $70,000 for the year. What is its gross profit margin expressed as a percentage?","options":{"A":"3.6%","B":"70%","C":"160%","D":"28%"},"correctOption":"D","correctAnswer":"28%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit divided by revenue times 100, so $70,000 over $250,000 gives Lysander Foods a gross profit margin of 28%.","distractor_reasons":{"A":"3.6% wrongly divides the $250,000 revenue by the $70,000 gross profit rather than gross profit by revenue. For Lysander Foods, option D is correct: 28%.","B":"70% incorrectly uses the $70,000 figure as a percentage without relating it to the $250,000 revenue of Lysander Foods. For Lysander Foods, option D is correct: 28%.","C":"160% incorrectly uses the revenue figure as the numerator, not the $70,000 gross profit earned by Lysander Foods. For Lysander Foods, option D is correct: 28%.","D":"Gross profit margin is gross profit divided by revenue times 100, so $70,000 over $250,000 gives Lysander Foods a gross profit margin of 28%."}}},{"id":"P1_U5_MCQ_1546","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1546","question":"Merton Ceramics in Derby borrows $25,000 at 5% per year simple interest over four years. What is the total interest payable on this loan in all?","options":{"A":"$5,000","B":"$1,250","C":"$30,000","D":"$25,000"},"correctOption":"A","correctAnswer":"$5,000","questionType":"MCQ","explanation":{"correct_reason":"Simple interest is principal times rate times years, so $25,000 at 5% costs $1,250 a year and over four years Merton Ceramics pays $5,000 in interest.","distractor_reasons":{"A":"Simple interest is principal times rate times years, so $25,000 at 5% costs $1,250 a year and over four years Merton Ceramics pays $5,000 in interest.","B":"$1,250 is one year's interest and ignores the three further years of the $25,000 loan to Merton Ceramics. For Merton Ceramics, option A is correct: $5,000.","C":"$30,000 is the principal plus $5,000 interest, the total repayment, not the interest charge asked for. For Merton Ceramics, option A is correct: $5,000.","D":"$25,000 is the amount borrowed and does not include the interest due over four years. For Merton Ceramics, option A is correct: $5,000."}}},{"id":"P1_U5_MCQ_1547","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1547","question":"Narvik Fishing in Narvik starts September with an overdrawn bank balance of $4,000 and forecasts a net cash inflow of $9,000. What is its closing bank balance?","options":{"A":"$13,000","B":"Negative $4,000","C":"$5,000","D":"$9,000"},"correctOption":"C","correctAnswer":"$5,000","questionType":"MCQ","explanation":{"correct_reason":"Starting from an overdraft of $4,000 and adding a $9,000 net inflow leaves Narvik Fishing with a positive closing bank balance of $5,000.","distractor_reasons":{"A":"$13,000 adds the $9,000 inflow to a $4,000 balance as if it were positive, but the opening balance was overdrawn.","B":"Negative $4,000 is only the opening overdraft and ignores the $9,000 of net cash received during September. For Narvik Fishing, option C is correct: $5,000.","C":"Starting from an overdraft of $4,000 and adding a $9,000 net inflow leaves Narvik Fishing with a positive closing bank balance of $5,000.","D":"$9,000 is the net inflow itself and fails to account for the $4,000 overdraft that must first be cleared. For Narvik Fishing, option C is correct: $5,000."}}},{"id":"P1_U5_MCQ_1548","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1548","question":"Orwell Computers in Ipswich made a profit of $40,000 but its bank balance fell during the year. Which explanation is most plausible given these figures?","options":{"A":"All sales were made for cash","B":"It bought significant equipment for cash","C":"It reduced its operating expenses","D":"Its revenue was unchanged"},"correctOption":"B","correctAnswer":"It bought significant equipment for cash","questionType":"MCQ","explanation":{"correct_reason":"Buying equipment for cash is an outflow that reduces the bank balance but is not an expense in the year, so Orwell Computers can be profitable while cash falls.","distractor_reasons":{"A":"If all $40,000 of profit came from cash sales, cash would tend to rise rather than fall during the year.","B":"Buying equipment for cash is an outflow that reduces the bank balance but is not an expense in the year, so Orwell Computers can be profitable while cash falls.","C":"Reducing operating expenses would increase profit and conserve cash, not cause the bank balance of Orwell Computers to fall. For Orwell Computers, option B is correct: it bought significant equipment for cash.","D":"Unchanged revenue does not explain a falling bank balance when a profit of $40,000 was reported by Orwell Computers. For Orwell Computers, option B is correct: it bought significant equipment for cash."}}},{"id":"P1_U5_MCQ_1549","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1549","question":"Pemberton Stores in Wellington repays a $20,000 bank loan using cash. What is the immediate effect on the statement of financial position of Pemberton Stores?","options":{"A":"Current assets and equity both increase","B":"Cash falls and liabilities fall by $20,000","C":"Non-current assets rise by $20,000","D":"Total assets remain unchanged"},"correctOption":"B","correctAnswer":"Cash falls and liabilities fall by $20,000","questionType":"MCQ","explanation":{"correct_reason":"Paying $20,000 of cash to settle a loan reduces the cash asset and removes the $20,000 liability, so both sides of Pemberton Stores' statement shrink.","distractor_reasons":{"A":"Using $20,000 of cash reduces assets, not increases them, and equity is unchanged by repaying a bank loan. For Pemberton Stores, option B is correct: cash falls and liabilities fall by $20,000.","B":"Paying $20,000 of cash to settle a loan reduces the cash asset and removes the $20,000 liability, so both sides of Pemberton Stores' statement shrink.","C":"Repaying a loan does not create a non-current asset; the cash outflow simply settles an existing obligation of Pemberton Stores.","D":"Total assets fall by the $20,000 of cash paid, so they cannot remain unchanged after the repayment. For Pemberton Stores, option B is correct: cash falls and liabilities fall by $20,000."}}},{"id":"P1_U5_MCQ_1550","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1550","question":"Quillon Electronics in Szeged has a current ratio of 1.6:1 and an acid test ratio of 0.7:1. What does the gap between these two figures indicate?","options":{"A":"The business has no trade payables at all","B":"Its revenue has doubled since last year","C":"A large share of current assets is tied up in inventory","D":"Its operating profit is falling sharply"},"correctOption":"C","correctAnswer":"A large share of current assets is tied up in inventory","questionType":"MCQ","explanation":{"correct_reason":"The acid test removes inventory, so a fall from 1.6:1 to 0.7:1 shows that much of Quillon Electronics' current assets are held as stock rather than liquid assets.","distractor_reasons":{"A":"Trade payables appear in the denominator of both ratios, so their absence would not create this difference. For Quillon Electronics, option C is correct: a large share of current assets is tied up in inventory.","B":"Revenue does not appear in either liquidity ratio, which compare current assets with current liabilities. For Quillon Electronics, option C is correct: a large share of current assets is tied up in inventory.","C":"The acid test removes inventory, so a fall from 1.6:1 to 0.7:1 shows that much of Quillon Electronics' current assets are held as stock rather than liquid assets.","D":"Operating profit is a profitability measure and is not used in calculating these two liquidity ratios. For Quillon Electronics, option C is correct: a large share of current assets is tied up in inventory."}}},{"id":"P1_U5_MCQ_1551","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1551","question":"Redwood Publishers in Montreal receives a government grant of $18,000 to buy new printing equipment. How is this grant best classified as a source of finance?","options":{"A":"A long-term liability","B":"A loan requiring interest payments","C":"A short-term bank overdraft","D":"A source of finance that does not require repayment"},"correctOption":"D","correctAnswer":"A source of finance that does not require repayment","questionType":"MCQ","explanation":{"correct_reason":"A government grant of $18,000 provides funds that need not be repaid, so it is a useful source of finance for Redwood Publishers' new equipment.","distractor_reasons":{"A":"A grant is not a liability because Redwood Publishers does not have to repay the $18,000 to the government. For Redwood Publishers, option D is correct: a source of finance that does not require repayment.","B":"Unlike a loan, the $18,000 grant carries no interest charge and no scheduled repayments for Redwood Publishers. For Redwood Publishers, option D is correct: a source of finance that does not require repayment.","C":"An overdraft is repayable on demand, whereas the grant gives Redwood Publishers permanent funds for the printing equipment. For Redwood Publishers, option D is correct: a source of finance that does not require repayment.","D":"A government grant of $18,000 provides funds that need not be repaid, so it is a useful source of finance for Redwood Publishers' new equipment."}}},{"id":"P1_U5_MCQ_1552","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1552","question":"Saltmarsh Foods in Poole is listing cash outflows for its weekly forecast. Which of these items is certainly a cash payment for the business in that week?","options":{"A":"Wages paid to hourly staff","B":"Depreciation of delivery vans","C":"Credit purchases not yet settled","D":"An unrealised gain on property"},"correctOption":"A","correctAnswer":"Wages paid to hourly staff","questionType":"MCQ","explanation":{"correct_reason":"Wages paid to staff involve actual cash leaving Saltmarsh Foods, so they belong among the cash payments in the weekly forecast of the business.","distractor_reasons":{"A":"Wages paid to staff involve actual cash leaving Saltmarsh Foods, so they belong among the cash payments in the weekly forecast of the business.","B":"Depreciation is a non-cash charge and does not appear among the cash payments of Saltmarsh Foods in the weekly forecast.","C":"Credit purchases not yet settled involve no cash outflow until Saltmarsh Foods actually pays the supplier. For Saltmarsh Foods, option A is correct: wages paid to hourly staff.","D":"An unrealised gain involves no cash transaction and would not be recorded in the cash flow forecast of Saltmarsh Foods."}}},{"id":"P1_U5_MCQ_1553","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1553","question":"Tamarind Spices in Kochi, India, earned revenue of $180,000 and incurred cost of sales of $117,000 during the year. What was its gross profit for that year?","options":{"A":"$63,000","B":"$117,000","C":"$297,000","D":"$180,000"},"correctOption":"A","correctAnswer":"$63,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, so Tamarind Spices' $180,000 less $117,000 leaves $63,000 before operating expenses are deducted.","distractor_reasons":{"A":"Gross profit is revenue minus cost of sales, so Tamarind Spices' $180,000 less $117,000 leaves $63,000 before operating expenses are deducted.","B":"$117,000 is the cost of sales figure and is an expense, not the gross profit earned by Tamarind Spices. For Tamarind Spices, option A is correct: $63,000.","C":"$297,000 wrongly adds revenue and cost of sales instead of subtracting the latter from the former. For Tamarind Spices, option A is correct: $63,000.","D":"$180,000 is revenue before any costs are deducted, so it cannot be the gross profit of Tamarind Spices. For Tamarind Spices, option A is correct: $63,000."}}},{"id":"P1_U5_MCQ_1554","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1554","question":"Underwood Interiors in Brighton owes $12,000 to a fabric supplier and is itself owed $7,000 by a customer. What are these two amounts in its accounts?","options":{"A":"Both are assets","B":"The $12,000 is an asset and the $7,000 a liability","C":"The $12,000 is a liability and the $7,000 an asset","D":"Both are liabilities"},"correctOption":"C","correctAnswer":"The $12,000 is a liability and the $7,000 an asset","questionType":"MCQ","explanation":{"correct_reason":"Money owed to the fabric supplier is a liability of $12,000, while the $7,000 owed by a customer is a trade receivable and therefore an asset.","distractor_reasons":{"A":"An amount owed to a supplier is not an asset, since Underwood Interiors must pay the $12,000 rather than receive it.","B":"The classification is reversed: the $12,000 payable is a liability and the $7,000 receivable is an asset of Underwood Interiors.","C":"Money owed to the fabric supplier is a liability of $12,000, while the $7,000 owed by a customer is a trade receivable and therefore an asset.","D":"The $7,000 due from the customer is an asset, not a liability, because Underwood Interiors expects to receive it. For Underwood Interiors, option C is correct: the $12,000 is a liability and the $7,000 an asset."}}},{"id":"P1_U5_MCQ_1555","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1555","question":"Verdant Gardens in Christchurch reports profit for the year of $24,000 on revenue of $160,000. What is the profit margin of the business for the year?","options":{"A":"6.7%","B":"24%","C":"160%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year divided by revenue times 100, so $24,000 over $160,000 gives Verdant Gardens a profit margin of 15%.","distractor_reasons":{"A":"6.7% results from dividing the $160,000 revenue by the $24,000 profit, which reverses the correct formula. For Verdant Gardens, option D is correct: 15%.","B":"24% wrongly treats the $24,000 profit as a percentage without comparing it with the $160,000 revenue of Verdant Gardens. For Verdant Gardens, option D is correct: 15%.","C":"160% incorrectly uses the revenue figure as the numerator, not the $24,000 profit earned by Verdant Gardens. For Verdant Gardens, option D is correct: 15%.","D":"Profit margin is profit for the year divided by revenue times 100, so $24,000 over $160,000 gives Verdant Gardens a profit margin of 15%."}}},{"id":"P1_U5_MCQ_1556","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1556","question":"Wexford Dairy in Wexford wants $400,000 for rapid expansion but cannot service large loan repayments. Which source of finance is designed for such growth businesses?","options":{"A":"A bank overdraft","B":"Venture capital","C":"Trade credit","D":"Retained earnings only"},"correctOption":"B","correctAnswer":"Venture capital","questionType":"MCQ","explanation":{"correct_reason":"Venture capital provides equity funding of about $400,000 to growing businesses that cannot yet afford heavy debt, in exchange for a share of ownership.","distractor_reasons":{"A":"An overdraft is short-term borrowing that would require repayment and interest, which Wexford Dairy cannot service. For Wexford Dairy, option B is correct: venture capital.","B":"Venture capital provides equity funding of about $400,000 to growing businesses that cannot yet afford heavy debt, in exchange for a share of ownership.","C":"Trade credit only delays supplier payments and cannot supply the $400,000 of expansion capital that Wexford Dairy needs. For Wexford Dairy, option B is correct: venture capital.","D":"Retained earnings alone are unlikely to provide $400,000 quickly for the rapid expansion planned by Wexford Dairy. For Wexford Dairy, option B is correct: venture capital."}}},{"id":"P1_U5_MCQ_1557","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1557","question":"Xplore Travel in Queenstown earns most of its cash in the ski season but pays fixed rent all year round. What problem is a cash flow forecast most likely to reveal?","options":{"A":"A cash shortage in the quiet summer months","B":"That depreciation is too high","C":"That its profit margin has fallen","D":"That its share price is overvalued"},"correctOption":"A","correctAnswer":"A cash shortage in the quiet summer months","questionType":"MCQ","explanation":{"correct_reason":"With rent paid year-round but receipts concentrated in the ski season, the forecast will show a summer cash shortage that Xplore Travel must plan to finance.","distractor_reasons":{"A":"With rent paid year-round but receipts concentrated in the ski season, the forecast will show a summer cash shortage that Xplore Travel must plan to finance.","B":"Depreciation is not a cash item and cannot cause the seasonal shortfall shown in the cash flow forecast of Xplore Travel.","C":"Profit margin is a profitability measure and does not track the timing of cash receipts and payments across the year.","D":"Share price is irrelevant to a private travel firm's cash flow forecast of seasonal inflows and outflows. For Xplore Travel, option A is correct: a cash shortage in the quiet summer months."}}},{"id":"P1_U5_MCQ_1558","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1558","question":"Yorkstone Joinery in York has revenue of $210,000 and cost of sales of $150,000. Which of these figures represents its gross profit for the year?","options":{"A":"$150,000","B":"$210,000","C":"$360,000","D":"$60,000"},"correctOption":"D","correctAnswer":"$60,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue less cost of sales, so Yorkstone Joinery's $210,000 less $150,000 gives $60,000 before any operating expenses are deducted.","distractor_reasons":{"A":"$150,000 is the cost of sales and is deducted from revenue, not a profit figure for Yorkstone Joinery. For Yorkstone Joinery, option D is correct: $60,000.","B":"$210,000 is revenue taken before costs, so it cannot be the gross profit of Yorkstone Joinery. For Yorkstone Joinery, option D is correct: $60,000.","C":"$360,000 adds revenue and cost of sales rather than subtracting the $150,000 expense from the $210,000 revenue. For Yorkstone Joinery, option D is correct: $60,000.","D":"Gross profit is revenue less cost of sales, so Yorkstone Joinery's $210,000 less $150,000 gives $60,000 before any operating expenses are deducted."}}},{"id":"P1_U5_MCQ_1559","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1559","question":"Zanussi Motors in Bologna has kept $85,000 of profit in the business rather than paying it to the owners. Where does this amount appear in the accounts?","options":{"A":"As a current liability","B":"As retained earnings within equity","C":"As a non-current asset","D":"As an operating expense"},"correctOption":"B","correctAnswer":"As retained earnings within equity","questionType":"MCQ","explanation":{"correct_reason":"Profit kept in the business is retained earnings and forms part of the equity section of Zanussi Motors' statement of financial position.","distractor_reasons":{"A":"Retained earnings are owed to the owners as residual claimants, not to outside creditors as a current liability. For Zanussi Motors, option B is correct: as retained earnings within equity.","B":"Profit kept in the business is retained earnings and forms part of the equity section of Zanussi Motors' statement of financial position.","C":"Retained earnings represent a claim on assets, not a physical non-current asset such as the machinery of Zanussi Motors. For Zanussi Motors, option B is correct: as retained earnings within equity.","D":"Retained earnings arise after expenses have been deducted and do not appear as an operating expense for Zanussi Motors. For Zanussi Motors, option B is correct: as retained earnings within equity."}}},{"id":"P1_U5_MCQ_1560","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1560","question":"Ashvale Nurseries in Canterbury increased its return on capital employed from 8% to 12% this year. What could best explain the improvement in this figure?","options":{"A":"Capital employed rose faster than operating profit","B":"Revenue fell sharply during the year","C":"Operating profit grew relative to capital employed","D":"Current liabilities doubled"},"correctOption":"C","correctAnswer":"Operating profit grew relative to capital employed","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, so a rise from 8% to 12% means operating profit grew faster than the capital used.","distractor_reasons":{"A":"If capital employed rose faster than operating profit, the return would fall, not rise from 8% to 12% at Ashvale Nurseries.","B":"A sharp fall in revenue would reduce operating profit and tend to lower the return on capital employed of Ashvale Nurseries.","C":"Return on capital employed is operating profit divided by capital employed, so a rise from 8% to 12% means operating profit grew faster than the capital used.","D":"Current liabilities are not part of the ROCE calculation, so doubling them cannot explain the improvement at Ashvale Nurseries. For Ashvale Nurseries, option C is correct: operating profit grew relative to capital employed."}}},{"id":"P1_U5_MCQ_1561","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1561","question":"Bayside Bicycles in Brighton raises $90,000 by selling new shares to outside investors. What is a significant disadvantage of this source of finance for the owners?","options":{"A":"The money must be repaid with high interest","B":"It creates a short-term liability","C":"It gives the business no permanent capital","D":"Existing owners' control may be diluted"},"correctOption":"D","correctAnswer":"Existing owners' control may be diluted","questionType":"MCQ","explanation":{"correct_reason":"Selling $90,000 of new shares brings in permanent capital but gives new shareholders voting rights, so the existing owners of Bayside Bicycles may lose control.","distractor_reasons":{"A":"Share capital does not have to be repaid and does not carry interest, unlike a bank loan of $90,000. For Bayside Bicycles, option D is correct: existing owners' control may be diluted.","B":"Shares are equity, not a short-term liability, so no repayment date is attached to the $90,000 raised by Bayside Bicycles.","C":"Equity finance is permanent capital, so issuing shares certainly provides Bayside Bicycles with long-term funding. For Bayside Bicycles, option D is correct: existing owners' control may be diluted.","D":"Selling $90,000 of new shares brings in permanent capital but gives new shareholders voting rights, so the existing owners of Bayside Bicycles may lose control."}}},{"id":"P1_U5_MCQ_1562","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1562","question":"Cedarwood Stores in Ottawa has an opening bank balance of $11,000, a net cash inflow of $4,000 and then pays a $6,000 dividend. What is its closing bank balance?","options":{"A":"$9,000","B":"$21,000","C":"$13,000","D":"$5,000"},"correctOption":"A","correctAnswer":"$9,000","questionType":"MCQ","explanation":{"correct_reason":"Starting with $11,000, adding the $4,000 net inflow gives $15,000, and paying the $6,000 dividend leaves Cedarwood Stores with a closing balance of $9,000.","distractor_reasons":{"A":"Starting with $11,000, adding the $4,000 net inflow gives $15,000, and paying the $6,000 dividend leaves Cedarwood Stores with a closing balance of $9,000.","B":"$21,000 adds both the inflow and the dividend instead of subtracting the $6,000 payment from Cedarwood Stores' balance. For Cedarwood Stores, option A is correct: $9,000.","C":"$13,000 adds the $4,000 inflow to $11,000 but forgets the $6,000 dividend paid out by Cedarwood Stores. For Cedarwood Stores, option A is correct: $9,000.","D":"$5,000 wrongly subtracts the $4,000 inflow as well as the $6,000 dividend from the $11,000 opening balance. For Cedarwood Stores, option A is correct: $9,000."}}},{"id":"P1_U5_MCQ_1563","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1563","question":"Doverdale Chemicals in Dover had opening inventory of $9,000, purchases of $74,000 and closing inventory of $13,000. What is its cost of sales for the year?","options":{"A":"$96,000","B":"$74,000","C":"$70,000","D":"$13,000"},"correctOption":"C","correctAnswer":"$70,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is opening inventory plus purchases less closing inventory, so $9,000 plus $74,000 less $13,000 gives $70,000 for Doverdale Chemicals.","distractor_reasons":{"A":"$96,000 wrongly adds closing inventory instead of subtracting it from the $74,000 purchases and $9,000 opening stock. For Doverdale Chemicals, option C is correct: $70,000.","B":"$74,000 is purchases alone and ignores the $9,000 opening and $13,000 closing inventory figures of Doverdale Chemicals. For Doverdale Chemicals, option C is correct: $70,000.","C":"Cost of sales is opening inventory plus purchases less closing inventory, so $9,000 plus $74,000 less $13,000 gives $70,000 for Doverdale Chemicals.","D":"$13,000 is only the closing inventory and is deducted, not the cost of sales itself for Doverdale Chemicals. For Doverdale Chemicals, option C is correct: $70,000."}}},{"id":"P1_U5_MCQ_1564","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1564","question":"Eastern Ports in Gdansk is owed $28,000 by a shipping client for work already completed. How should this outstanding amount be reported in its accounts?","options":{"A":"As a current asset called trade receivables","B":"As a non-current liability","C":"As revenue in the profit and loss account","D":"As part of equity"},"correctOption":"A","correctAnswer":"As a current asset called trade receivables","questionType":"MCQ","explanation":{"correct_reason":"The $28,000 owed by the client is a trade receivable, a current asset expected to be turned into cash within the normal operating cycle of Eastern Ports.","distractor_reasons":{"A":"The $28,000 owed by the client is a trade receivable, a current asset expected to be turned into cash within the normal operating cycle of Eastern Ports.","B":"An amount owed to Eastern Ports is an asset, not a liability that the business must pay to someone else.","C":"The work was completed, so revenue may already be recognised, but the $28,000 outstanding is a receivable until cash arrives.","D":"Equity represents the owners' claim, whereas this $28,000 is a claim of Eastern Ports on a customer for work done."}}},{"id":"P1_U5_MCQ_1565","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1565","question":"Fairview Clinics in Kuala Lumpur has a gross profit margin of 38% this year against 31% last year. Which conclusion from these figures is justified?","options":{"A":"Total revenue must have doubled","B":"A larger share of revenue is left as gross profit","C":"Operating expenses have certainly fallen","D":"Current liquidity has improved"},"correctOption":"B","correctAnswer":"A larger share of revenue is left as gross profit","questionType":"MCQ","explanation":{"correct_reason":"A rise in gross profit margin from 31% to 38% means Fairview Clinics keeps a greater proportion of each dollar of revenue as gross profit after cost of sales.","distractor_reasons":{"A":"A margin compares gross profit with revenue and does not show that revenue doubled at Fairview Clinics. For Fairview Clinics, option B is correct: a larger share of revenue is left as gross profit.","B":"A rise in gross profit margin from 31% to 38% means Fairview Clinics keeps a greater proportion of each dollar of revenue as gross profit after cost of sales.","C":"Operating expenses are deducted after gross profit, so they do not determine the gross profit margin of 38%. For Fairview Clinics, option B is correct: a larger share of revenue is left as gross profit.","D":"Liquidity is measured by current assets against current liabilities, not by the gross profit margin of Fairview Clinics. For Fairview Clinics, option B is correct: a larger share of revenue is left as gross profit."}}},{"id":"P1_U5_MCQ_1566","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1566","question":"Granite Quarries in Aberdeen needs a $200,000 excavator but wants to spread the cost and avoid owning equipment that may age. Which option fits its needs?","options":{"A":"Using retained earnings to buy it outright","B":"A five-year bank loan","C":"Leasing the excavator","D":"Issuing ordinary shares"},"correctOption":"C","correctAnswer":"Leasing the excavator","questionType":"MCQ","explanation":{"correct_reason":"Leasing gives Granite Quarries the use of the $200,000 excavator for regular rentals without ownership, so it avoids the risk of the machine becoming obsolete.","distractor_reasons":{"A":"Buying outright with retained earnings uses $200,000 of cash and leaves Granite Quarries owning equipment that may become outdated. For Granite Quarries, option C is correct: leasing the excavator.","B":"A bank loan would still make Granite Quarries the owner of the excavator and would require both interest and repayments.","C":"Leasing gives Granite Quarries the use of the $200,000 excavator for regular rentals without ownership, so it avoids the risk of the machine becoming obsolete.","D":"Issuing shares raises capital but still involves purchasing the excavator, so it does not address the obsolescence concern. For Granite Quarries, option C is correct: leasing the excavator."}}},{"id":"P1_U5_MCQ_1567","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1567","question":"Bosphorus Ferries in Sydney forecasts cash receipts of $135,000 and cash payments of $142,500 for October. What is its forecast net cash flow for the month?","options":{"A":"$277,500","B":"$7,500","C":"$135,000","D":"Negative $7,500"},"correctOption":"D","correctAnswer":"Negative $7,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is receipts minus payments, so Bosphorus Ferries' $135,000 less $142,500 produces a negative net cash flow of $7,500 for October.","distractor_reasons":{"A":"$277,500 adds receipts and payments instead of subtracting the $142,500 outflow from the $135,000 inflow. For Bosphorus Ferries, option D is correct: negative $7,500.","B":"$7,500 has the correct magnitude but the wrong sign, since payments exceed receipts by $7,500 at Bosphorus Ferries. For Bosphorus Ferries, option D is correct: negative $7,500.","C":"$135,000 is only the receipts figure and ignores the $142,500 paid out during October by Bosphorus Ferries. For Bosphorus Ferries, option D is correct: negative $7,500.","D":"Net cash flow is receipts minus payments, so Bosphorus Ferries' $135,000 less $142,500 produces a negative net cash flow of $7,500 for October."}}},{"id":"P1_U5_MCQ_1568","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1568","question":"Iona Textiles in Limerick has gross profit of $90,000 and operating expenses of $63,000. If expenses rise by $5,000, what happens to profit for the year?","options":{"A":"It falls from $27,000 to $22,000","B":"It rises from $27,000 to $32,000","C":"It stays at $90,000","D":"Gross profit falls by $5,000"},"correctOption":"A","correctAnswer":"It falls from $27,000 to $22,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is $90,000 less $63,000, or $27,000, so a $5,000 rise in operating expenses reduces it to $22,000 at Iona Textiles.","distractor_reasons":{"A":"Profit for the year is $90,000 less $63,000, or $27,000, so a $5,000 rise in operating expenses reduces it to $22,000 at Iona Textiles.","B":"Higher operating expenses reduce rather than increase profit for the year, which falls from $27,000 to $22,000 at Iona Textiles.","C":"$90,000 is the gross profit figure and ignores the $63,000 of operating expenses at Iona Textiles. For Iona Textiles, option A is correct: it falls from $27,000 to $22,000.","D":"Gross profit is calculated before operating expenses, so a $5,000 expense rise cannot change the $90,000 gross profit. For Iona Textiles, option A is correct: it falls from $27,000 to $22,000."}}},{"id":"P1_U5_MCQ_1569","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1569","question":"Jarrah Foods in Adelaide has current assets of $92,000 and current liabilities of $57,000 at its year end. What is the working capital of the business?","options":{"A":"$35,000","B":"$149,000","C":"$57,000","D":"$92,000"},"correctOption":"A","correctAnswer":"$35,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets less current liabilities, so $92,000 minus $57,000 gives Jarrah Foods $35,000 for day-to-day operations. For Jarrah Foods, option A is correct: $35,000.","distractor_reasons":{"A":"Working capital is current assets less current liabilities, so $92,000 minus $57,000 gives Jarrah Foods $35,000 for day-to-day operations. For Jarrah Foods, option A is correct: $35,000.","B":"$149,000 adds the two figures rather than subtracting the $57,000 owed from $92,000 of current assets. For Jarrah Foods, option A is correct: $35,000.","C":"$57,000 is only the current liabilities and ignores the $92,000 of current assets held by Jarrah Foods. For Jarrah Foods, option A is correct: $35,000.","D":"$92,000 is the full current assets figure and does not deduct the $57,000 owed by Jarrah Foods. For Jarrah Foods, option A is correct: $35,000."}}},{"id":"P1_U5_MCQ_1570","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1570","question":"Kingsley Hotels in Bath has a current ratio of 1.1:1 and an acid test ratio of 0.9:1. What can be concluded from these two liquidity figures?","options":{"A":"Its inventory is worth nothing at all","B":"Its current liabilities are falling","C":"It relies on inventory to meet short-term obligations","D":"Its profit margin is 0.9%"},"correctOption":"C","correctAnswer":"It relies on inventory to meet short-term obligations","questionType":"MCQ","explanation":{"correct_reason":"The acid test of 0.9:1 is below the current ratio of 1.1:1, showing Kingsley Hotels depends on selling inventory to cover its short-term liabilities.","distractor_reasons":{"A":"Inventory has some value, since the current ratio of 1.1:1 exceeds the acid test of 0.9:1 by 0.2:1. For Kingsley Hotels, option C is correct: it relies on inventory to meet short-term obligations.","B":"Both ratios use current liabilities at the same point in time, so a trend in liabilities is not shown by these figures.","C":"The acid test of 0.9:1 is below the current ratio of 1.1:1, showing Kingsley Hotels depends on selling inventory to cover its short-term liabilities.","D":"The 0.9 figure is a liquidity ratio, not a profit margin of 0.9% for Kingsley Hotels. For Kingsley Hotels, option C is correct: it relies on inventory to meet short-term obligations."}}},{"id":"P1_U5_MCQ_1571","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1571","question":"Lorimer Engineering in Dundee takes 90 days to pay its suppliers for materials. What is a likely disadvantage of relying on this trade credit for so long?","options":{"A":"It must pay high interest on the credit","B":"Suppliers may offer smaller discounts or refuse future credit","C":"It gives the business permanent capital","D":"It reduces the firm's current liabilities"},"correctOption":"B","correctAnswer":"Suppliers may offer smaller discounts or refuse future credit","questionType":"MCQ","explanation":{"correct_reason":"Taking 90 days to pay can strain supplier relationships, so Lorimer Engineering may lose early-payment discounts or find future credit limited.","distractor_reasons":{"A":"Trade credit is usually interest-free, so taking 90 days to pay does not normally create an interest charge for Lorimer Engineering.","B":"Taking 90 days to pay can strain supplier relationships, so Lorimer Engineering may lose early-payment discounts or find future credit limited.","C":"Trade credit is short-term finance and does not provide permanent capital to Lorimer Engineering in Dundee. For Lorimer Engineering, option B is correct: suppliers may offer smaller discounts or refuse future credit.","D":"Delaying payment for 90 days increases current liabilities rather than reducing them at Lorimer Engineering. For Lorimer Engineering, option B is correct: suppliers may offer smaller discounts or refuse future credit."}}},{"id":"P1_U5_MCQ_1572","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1572","question":"Meridian Cafe in Napier starts the month with $3,000 cash, receives $28,000 from customers and pays out $26,500. What is its forecast closing cash balance?","options":{"A":"$57,500","B":"$3,000","C":"$1,500","D":"$4,500"},"correctOption":"D","correctAnswer":"$4,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $28,000 less $26,500, or $1,500, so adding this to the $3,000 opening cash gives Meridian Cafe a closing balance of $4,500.","distractor_reasons":{"A":"$57,500 adds all three figures together instead of netting the $28,000 receipts against the $26,500 payments. For Meridian Cafe, option D is correct: $4,500.","B":"$3,000 is only the opening cash and ignores the $1,500 net inflow during the month at Meridian Cafe. For Meridian Cafe, option D is correct: $4,500.","C":"$1,500 is the net cash flow itself and fails to add the $3,000 brought forward into the month. For Meridian Cafe, option D is correct: $4,500.","D":"Net cash flow is $28,000 less $26,500, or $1,500, so adding this to the $3,000 opening cash gives Meridian Cafe a closing balance of $4,500."}}},{"id":"P1_U5_MCQ_1573","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1573","question":"Norwood Stores in Norwich has gross profit of $74,000 and profit for the year of $21,000. What is the most likely reason for the difference between them?","options":{"A":"Cost of sales of $53,000","B":"Operating expenses of $53,000","C":"Revenue of $53,000","D":"Inventory of $53,000"},"correctOption":"B","correctAnswer":"Operating expenses of $53,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year equals gross profit less operating expenses, so the $53,000 difference between $74,000 and $21,000 is Norwood Stores' operating expenses.","distractor_reasons":{"A":"Cost of sales is deducted before gross profit of $74,000 is calculated and cannot explain the later fall to $21,000.","B":"Profit for the year equals gross profit less operating expenses, so the $53,000 difference between $74,000 and $21,000 is Norwood Stores' operating expenses.","C":"Revenue would be larger than gross profit, not a deduction of $53,000 from the $74,000 earned by Norwood Stores. For Norwood Stores, option B is correct: operating expenses of $53,000.","D":"Inventory is an asset and is not subtracted from gross profit when arriving at profit for the year of Norwood Stores."}}},{"id":"P1_U5_MCQ_1574","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1574","question":"Orkney Fisheries in Kirkwall buys a boat for $60,000 and charges $6,000 of depreciation in its first year. What is the boat's carrying value at the year end?","options":{"A":"$54,000","B":"$60,000","C":"$66,000","D":"$6,000"},"correctOption":"A","correctAnswer":"$54,000","questionType":"MCQ","explanation":{"correct_reason":"Carrying value is cost less accumulated depreciation, so the $60,000 boat less $6,000 of first-year depreciation is shown at $54,000 by Orkney Fisheries.","distractor_reasons":{"A":"Carrying value is cost less accumulated depreciation, so the $60,000 boat less $6,000 of first-year depreciation is shown at $54,000 by Orkney Fisheries.","B":"$60,000 is the original cost and ignores the $6,000 of depreciation already charged against the boat. For Orkney Fisheries, option A is correct: $54,000.","C":"$66,000 wrongly adds depreciation to cost rather than deducting it from the value of the boat. For Orkney Fisheries, option A is correct: $54,000.","D":"$6,000 is the depreciation charge itself, not the remaining carrying value of the boat at the year end. For Orkney Fisheries, option A is correct: $54,000."}}},{"id":"P1_U5_MCQ_1575","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1575","question":"Palermo Foods in Palermo is comparing its current ratio with that of a rival business in the same market. What is the main purpose of this comparison?","options":{"A":"To calculate the tax owed","B":"To value the owner's drawings","C":"To measure employee productivity","D":"To assess liquidity against a benchmark"},"correctOption":"D","correctAnswer":"To assess liquidity against a benchmark","questionType":"MCQ","explanation":{"correct_reason":"Comparing its current ratio with a rival lets Palermo Foods judge whether its short-term liquidity is stronger or weaker than a similar business.","distractor_reasons":{"A":"Tax owed depends on taxable profit, not on a comparison of current ratios with another firm in the same market.","B":"Owner's drawings are recorded in equity and are unrelated to comparing the current ratio of Palermo Foods with a rival.","C":"Employee productivity is an operations measure and is not revealed by the current ratio of Palermo Foods. For Palermo Foods, option D is correct: to assess liquidity against a benchmark.","D":"Comparing its current ratio with a rival lets Palermo Foods judge whether its short-term liquidity is stronger or weaker than a similar business."}}},{"id":"P1_U5_MCQ_1576","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1576","question":"Quayside Logistics in Rotterdam plans to fund a new warehouse using retained earnings. What is a significant drawback of relying only on this source of finance?","options":{"A":"It creates high interest costs for the business","B":"It dilutes the owners' control of the company","C":"It may be too slow or too small to fund the whole project","D":"It must be repaid within one year"},"correctOption":"C","correctAnswer":"It may be too slow or too small to fund the whole project","questionType":"MCQ","explanation":{"correct_reason":"Retained earnings depend on past profits, so Quayside Logistics may not have enough accumulated cash, or may need years to build it, for the new warehouse.","distractor_reasons":{"A":"Retained earnings involve no borrowing and therefore create no interest cost for Quayside Logistics, unlike a bank loan for the warehouse.","B":"Using internal profits introduces no new shareholders, so the ownership and control of Quayside Logistics remain unchanged. For Quayside Logistics, option C is correct: it may be too slow or too small to fund the whole project.","C":"Retained earnings depend on past profits, so Quayside Logistics may not have enough accumulated cash, or may need years to build it, for the new warehouse.","D":"Retained profit is owners' money and does not have to be repaid on any fixed date, unlike a short-term bank loan."}}},{"id":"P1_U5_MCQ_1577","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1577","question":"Riverside Printers in Frankfurt finds that its actual bank balance is lower than the forecast predicted. Which of the following is a likely cause of this difference?","options":{"A":"Customers paid earlier than expected","B":"Depreciation was omitted from the forecast","C":"Unexpected repair bills had to be paid","D":"All sales were made on a cash basis"},"correctOption":"C","correctAnswer":"Unexpected repair bills had to be paid","questionType":"MCQ","explanation":{"correct_reason":"An unplanned repair is an extra cash outflow not included in the forecast, so Riverside Printers' actual bank balance ends up below the predicted figure.","distractor_reasons":{"A":"Customers paying earlier would raise cash above the forecast rather than leave Riverside Printers with a lower-than-predicted balance. For Riverside Printers, option C is correct: unexpected repair bills had to be paid.","B":"Depreciation is non-cash, so leaving it out of a cash forecast would not change the actual bank balance of Riverside Printers.","C":"An unplanned repair is an extra cash outflow not included in the forecast, so Riverside Printers' actual bank balance ends up below the predicted figure.","D":"Cash sales would make receipts more certain and would not cause the bank balance to fall below the forecast at Riverside Printers."}}},{"id":"P1_U5_MCQ_1578","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1578","question":"Sable Trading in Antwerp reports revenue of $400,000 and gross profit of $120,000. What is the cost of sales figure that must have been incurred during the year?","options":{"A":"$520,000","B":"$120,000","C":"$400,000","D":"$280,000"},"correctOption":"D","correctAnswer":"$280,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales equals revenue minus gross profit, so Sable Trading's $400,000 revenue less $120,000 gross profit gives $280,000 of cost of sales.","distractor_reasons":{"A":"$520,000 adds revenue and gross profit rather than subtracting gross profit from the $400,000 revenue of Sable Trading. For Sable Trading, option D is correct: $280,000.","B":"$120,000 is the gross profit figure reported by Sable Trading, not the cost of sales incurred during the year. For Sable Trading, option D is correct: $280,000.","C":"$400,000 is the revenue figure taken before deducting the $120,000 gross profit earned by Sable Trading. For Sable Trading, option D is correct: $280,000.","D":"Cost of sales equals revenue minus gross profit, so Sable Trading's $400,000 revenue less $120,000 gross profit gives $280,000 of cost of sales."}}},{"id":"P1_U5_MCQ_1579","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1579","question":"Trent Valley Foods in Nottingham has trade payables of $26,000, a tax bill due in three months of $8,000 and a loan due in eight years. Which are current liabilities?","options":{"A":"The $26,000 payables and the $8,000 tax bill","B":"Only the loan due in eight years","C":"All three of the amounts listed","D":"None of these amounts"},"correctOption":"A","correctAnswer":"The $26,000 payables and the $8,000 tax bill","questionType":"MCQ","explanation":{"correct_reason":"Current liabilities are obligations due within a year, so the $26,000 payables and $8,000 tax bill qualify, while the loan due in eight years is non-current.","distractor_reasons":{"A":"Current liabilities are obligations due within a year, so the $26,000 payables and $8,000 tax bill qualify, while the loan due in eight years is non-current.","B":"A loan due in eight years is long-term finance, not a current liability of Trent Valley Foods due within twelve months.","C":"The eight-year loan is not due within a year, so it is wrong to say that all three amounts are current liabilities.","D":"At least the $26,000 payables and $8,000 tax bill are due shortly, so none being current liabilities is incorrect. For Trent Valley Foods, option A is correct: the $26,000 payables and the $8,000 tax bill."}}},{"id":"P1_U5_MCQ_1580","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1580","question":"Umbra Electronics in Seoul has a current ratio of 2.3:1 but an acid test ratio of 0.8:1. What does this large gap suggest about the inventory held by the business?","options":{"A":"Much of its current assets are slow-moving stock","B":"Its inventory is very small in value","C":"Its inventory has no value at all","D":"Its current liabilities are overstated"},"correctOption":"A","correctAnswer":"Much of its current assets are slow-moving stock","questionType":"MCQ","explanation":{"correct_reason":"The large gap between 2.3:1 and 0.8:1 shows Umbra Electronics holds substantial inventory that is not included in the more cautious acid test measure.","distractor_reasons":{"A":"The large gap between 2.3:1 and 0.8:1 shows Umbra Electronics holds substantial inventory that is not included in the more cautious acid test measure.","B":"A small inventory holding would make the two ratios similar, not widely separated at 2.3:1 and 0.8:1. For Umbra Electronics, option A is correct: much of its current assets are slow-moving stock.","C":"Inventory still has value; the current ratio includes it while the acid test deliberately excludes it from current assets. For Umbra Electronics, option A is correct: much of its current assets are slow-moving stock.","D":"The same current liabilities figure appears in both ratios, so it cannot explain the gap between 2.3:1 and 0.8:1. For Umbra Electronics, option A is correct: much of its current assets are slow-moving stock."}}},{"id":"P1_U5_MCQ_1581","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1581","question":"Krauss Motors in Stuttgart wants to buy a factory and spread repayment over 20 years using the building itself as security. Which type of finance is being described?","options":{"A":"A bank overdraft","B":"Trade credit from suppliers","C":"A mortgage","D":"Venture capital"},"correctOption":"C","correctAnswer":"A mortgage","questionType":"MCQ","explanation":{"correct_reason":"A mortgage is a long-term loan secured on property, so Krauss Motors can buy the factory and repay over 20 years with the building as collateral.","distractor_reasons":{"A":"An overdraft is short-term and repayable on demand, unsuitable for buying a factory over a period of 20 years. For Krauss Motors, option C is correct: a mortgage.","B":"Trade credit only delays payment to suppliers and cannot provide the funds needed to purchase a factory in Stuttgart. For Krauss Motors, option C is correct: a mortgage.","C":"A mortgage is a long-term loan secured on property, so Krauss Motors can buy the factory and repay over 20 years with the building as collateral.","D":"Venture capital is equity investment and does not use the factory building as security for the finance provided. For Krauss Motors, option C is correct: a mortgage."}}},{"id":"P1_U5_MCQ_1582","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1582","question":"Willowdale Dairy in Winnipeg begins the month with $6,000 in cash and forecasts a net cash outflow of $2,500. What will its closing cash balance be at the end of the month?","options":{"A":"$8,500","B":"$3,500","C":"$6,000","D":"$2,500"},"correctOption":"B","correctAnswer":"$3,500","questionType":"MCQ","explanation":{"correct_reason":"A net outflow of $2,500 reduces Willowdale Dairy's $6,000 opening cash, leaving a forecast closing balance of $3,500 at the end of the month.","distractor_reasons":{"A":"$8,500 adds the $2,500 outflow to the $6,000 opening balance instead of subtracting the net cash outflow. For Willowdale Dairy, option B is correct: $3,500.","B":"A net outflow of $2,500 reduces Willowdale Dairy's $6,000 opening cash, leaving a forecast closing balance of $3,500 at the end of the month.","C":"$6,000 is only the opening cash balance and ignores the $2,500 net outflow during the month at Willowdale Dairy. For Willowdale Dairy, option B is correct: $3,500.","D":"$2,500 is the outflow itself and ignores the $6,000 already held by Willowdale Dairy at the start of the month."}}},{"id":"P1_U5_MCQ_1583","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1583","question":"Xerxes Printing in Athens reduces its cost of sales from $140,000 to $125,000 while revenue stays fixed at $200,000. What happens to its gross profit as a result?","options":{"A":"It falls from $75,000 to $60,000","B":"It stays at $60,000","C":"It rises to $325,000","D":"It rises from $60,000 to $75,000"},"correctOption":"D","correctAnswer":"It rises from $60,000 to $75,000","questionType":"MCQ","explanation":{"correct_reason":"With revenue fixed at $200,000, cutting cost of sales from $140,000 to $125,000 raises Xerxes Printing's gross profit from $60,000 to $75,000.","distractor_reasons":{"A":"Lower cost of sales increases gross profit, so it cannot fall from $75,000 to $60,000 at Xerxes Printing in Athens.","B":"Gross profit changes from $60,000 because the $140,000 cost of sales has fallen to $125,000 with revenue fixed at $200,000.","C":"$325,000 wrongly adds the $200,000 revenue and the new $125,000 cost of sales instead of subtracting the expense. For Xerxes Printing, option D is correct: it rises from $60,000 to $75,000.","D":"With revenue fixed at $200,000, cutting cost of sales from $140,000 to $125,000 raises Xerxes Printing's gross profit from $60,000 to $75,000."}}},{"id":"P1_U5_MCQ_1584","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1584","question":"Yarra Valley Wines in Canberra has non-current assets of $420,000 and current assets of $130,000. What is the total value of assets shown in its statement of financial position?","options":{"A":"$550,000","B":"$290,000","C":"$420,000","D":"$130,000"},"correctOption":"A","correctAnswer":"$550,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are the sum of non-current and current assets, so $420,000 plus $130,000 gives Yarra Valley Wines total assets of $550,000.","distractor_reasons":{"A":"Total assets are the sum of non-current and current assets, so $420,000 plus $130,000 gives Yarra Valley Wines total assets of $550,000.","B":"$290,000 wrongly subtracts the $130,000 current assets from the $420,000 non-current assets instead of adding them. For Yarra Valley Wines, option A is correct: $550,000.","C":"$420,000 is only the non-current assets and omits the $130,000 of current assets held by Yarra Valley Wines. For Yarra Valley Wines, option A is correct: $550,000.","D":"$130,000 is only the current assets and omits the $420,000 of long-term assets owned by Yarra Valley Wines. For Yarra Valley Wines, option A is correct: $550,000."}}},{"id":"P1_U5_MCQ_1585","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1585","question":"Zambezi Lodges in Harare has current assets of $96,000 and current liabilities of $40,000 at its year end. What is the current ratio of the business?","options":{"A":"2.4:1","B":"0.4:1","C":"1.4:1","D":"4.8:1"},"correctOption":"A","correctAnswer":"2.4:1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets divided by current liabilities, so $96,000 over $40,000 gives Zambezi Lodges a current ratio of 2.4:1.","distractor_reasons":{"A":"The current ratio is current assets divided by current liabilities, so $96,000 over $40,000 gives Zambezi Lodges a current ratio of 2.4:1.","B":"0.4:1 wrongly divides the $40,000 liabilities by the $96,000 assets, reversing the correct current ratio formula. For Zambezi Lodges, option A is correct: 2.4:1.","C":"1.4:1 does not follow from the figures: dividing $96,000 by $40,000 gives 2.4:1 for Zambezi Lodges. For Zambezi Lodges, option A is correct: 2.4:1.","D":"4.8:1 would require current assets of $192,000, double the $96,000 actually reported by Zambezi Lodges. For Zambezi Lodges, option A is correct: 2.4:1."}}},{"id":"P1_U5_MCQ_1586","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1586","question":"Ashcroft Engineering in Brno needs long-term funding but wishes to avoid giving investors any ownership stake. Which source of finance meets that requirement of the business?","options":{"A":"Issuing ordinary shares","B":"Issuing preference shares","C":"Venture capital","D":"A long-term bank loan"},"correctOption":"D","correctAnswer":"A long-term bank loan","questionType":"MCQ","explanation":{"correct_reason":"A long-term bank loan provides the needed funds without handing any ownership or voting rights to investors, so Ashcroft Engineering keeps full control.","distractor_reasons":{"A":"Ordinary shares give investors ownership and voting rights, which would dilute the control Ashcroft Engineering wants to keep for its owners.","B":"Preference shares may limit voting rights but still give investors an ownership stake and dividend claims on the Ashcroft Engineering business.","C":"Venture capital is equity finance that requires giving investors a share of Ashcroft Engineering, so it cannot meet the stated requirement.","D":"A long-term bank loan provides the needed funds without handing any ownership or voting rights to investors, so Ashcroft Engineering keeps full control."}}},{"id":"P1_U5_MCQ_1587","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1587","question":"Bloomfield Florists in Adelaide expects a cash surplus in March and a deficit in April. How should the business use the forecast to manage this situation?","options":{"A":"Ignore the March surplus because only April matters","B":"Plan to carry the March surplus forward to cover April","C":"Repay all borrowings immediately in March","D":"Increase spending in March to remove the surplus"},"correctOption":"B","correctAnswer":"Plan to carry the March surplus forward to cover April","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast allows Bloomfield Florists to plan ahead, so the March surplus can be retained and used to cover the expected April deficit without new borrowing.","distractor_reasons":{"A":"Ignoring the March surplus would waste the opportunity to use that cash for the April shortfall at Bloomfield Florists. For Bloomfield Florists, option B is correct: plan to carry the March surplus forward to cover April.","B":"A cash flow forecast allows Bloomfield Florists to plan ahead, so the March surplus can be retained and used to cover the expected April deficit without new borrowing.","C":"Repaying all borrowings in March would remove cash needed to cover the April deficit predicted by the forecast. For Bloomfield Florists, option B is correct: plan to carry the March surplus forward to cover April.","D":"Increasing spending in March would remove the surplus that Bloomfield Florists needs in order to meet its April cash deficit."}}},{"id":"P1_U5_MCQ_1588","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1588","question":"Ferndale Chemicals in Gdansk has revenue of $260,000, cost of sales of $170,000 and operating expenses of $55,000. What is its gross profit for the year?","options":{"A":"$35,000","B":"$55,000","C":"$90,000","D":"$260,000"},"correctOption":"C","correctAnswer":"$90,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue less cost of sales, so Ferndale Chemicals' $260,000 minus $170,000 gives $90,000 before the $55,000 of operating expenses is deducted.","distractor_reasons":{"A":"$35,000 is the profit for the year after deducting the $55,000 operating expenses, not the gross profit of Ferndale Chemicals.","B":"$55,000 is the operating expenses figure itself and is deducted, not earned as gross profit by Ferndale Chemicals. For Ferndale Chemicals, option C is correct: $90,000.","C":"Gross profit is revenue less cost of sales, so Ferndale Chemicals' $260,000 minus $170,000 gives $90,000 before the $55,000 of operating expenses is deducted.","D":"$260,000 is revenue before any costs are subtracted, so it cannot be the gross profit of Ferndale Chemicals. For Ferndale Chemicals, option C is correct: $90,000."}}},{"id":"P1_U5_MCQ_1589","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1589","question":"Dartmoor Dairy in Exeter has current assets of $46,000 and current liabilities of $28,000 at its year end. What is the working capital available to the business?","options":{"A":"$74,000","B":"$18,000","C":"$46,000","D":"$28,000"},"correctOption":"B","correctAnswer":"$18,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so $46,000 less $28,000 leaves Dartmoor Dairy with $18,000 for its day-to-day operations.","distractor_reasons":{"A":"$74,000 adds current assets and current liabilities rather than subtracting the $28,000 owed from the $46,000 held. For Dartmoor Dairy, option B is correct: $18,000.","B":"Working capital is current assets minus current liabilities, so $46,000 less $28,000 leaves Dartmoor Dairy with $18,000 for its day-to-day operations.","C":"$46,000 is the full current assets figure and fails to deduct the $28,000 owed by Dartmoor Dairy. For Dartmoor Dairy, option B is correct: $18,000.","D":"$28,000 is only the current liabilities figure and ignores the $46,000 of current assets held by Dartmoor Dairy. For Dartmoor Dairy, option B is correct: $18,000."}}},{"id":"P1_U5_MCQ_1590","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1590","question":"Eastwood Furniture in Bristol reports a profit margin of 6% this year, down from 11% last year, although revenue is unchanged. Which change is the most likely cause?","options":{"A":"Operating expenses rose significantly","B":"Cost of sales fell sharply","C":"Revenue increased dramatically","D":"The firm sold more shares"},"correctOption":"A","correctAnswer":"Operating expenses rose significantly","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year over revenue, so with revenue unchanged a fall from 11% to 6% points to higher operating expenses at Eastwood Furniture.","distractor_reasons":{"A":"Profit margin is profit for the year over revenue, so with revenue unchanged a fall from 11% to 6% points to higher operating expenses at Eastwood Furniture.","B":"Lower cost of sales would increase gross profit and raise the profit margin, not reduce it from 11% to 6%.","C":"Revenue is stated to be unchanged, so an increase in revenue cannot explain the fall in the profit margin of Eastwood Furniture.","D":"Selling more shares changes equity but does not reduce the profit earned on each dollar of revenue by Eastwood Furniture."}}},{"id":"P1_U5_MCQ_1591","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1591","question":"Kelso Textiles in Tirana wants to raise $50,000 for a short period and is happy to pay interest only on the amount actually used. Which source suits it best?","options":{"A":"A ten-year mortgage","B":"Issuing new ordinary shares","C":"Leasing equipment","D":"A bank overdraft"},"correctOption":"D","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"An overdraft charges interest only on the amount actually used, so it suits Kelso Textiles' short-term $50,000 need with interest paid only on the sum drawn.","distractor_reasons":{"A":"A ten-year mortgage is long-term secured borrowing with interest on the whole $50,000, not flexible for a short period. For Kelso Textiles, option D is correct: a bank overdraft.","B":"Ordinary shares raise permanent equity and dilute control, and they do not involve paying interest on the money used. For Kelso Textiles, option D is correct: a bank overdraft.","C":"Leasing is for using assets rather than raising $50,000 of cash for a short period at Kelso Textiles. For Kelso Textiles, option D is correct: a bank overdraft.","D":"An overdraft charges interest only on the amount actually used, so it suits Kelso Textiles' short-term $50,000 need with interest paid only on the sum drawn."}}},{"id":"P1_U5_MCQ_1592","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1592","question":"Glenmore Hotels in Inverness expects to receive $64,000 and pay out $70,500 in the coming month. Its opening balance is $12,000. What is the forecast closing bank balance?","options":{"A":"$18,500","B":"$6,500","C":"$12,000","D":"$5,500"},"correctOption":"D","correctAnswer":"$5,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $64,000 less $70,500, or negative $6,500, so the $12,000 opening balance falls to a forecast closing bank balance of $5,500.","distractor_reasons":{"A":"$18,500 wrongly adds the $6,500 shortfall to the $12,000 opening balance instead of subtracting it from that balance. For Glenmore Hotels, option D is correct: $5,500.","B":"$6,500 is the net cash outflow itself and ignores the $12,000 balance brought forward into the month. For Glenmore Hotels, option D is correct: $5,500.","C":"$12,000 is the opening balance only and ignores the $6,500 net outflow expected at Glenmore Hotels. For Glenmore Hotels, option D is correct: $5,500.","D":"Net cash flow is $64,000 less $70,500, or negative $6,500, so the $12,000 opening balance falls to a forecast closing bank balance of $5,500."}}},{"id":"P1_U5_MCQ_1593","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1593","question":"Hartwell Bakeries in Sheffield reports revenue of $175,000 and gross profit of $70,000. What was the cost of sales incurred by the business during the year?","options":{"A":"$245,000","B":"$70,000","C":"$105,000","D":"$175,000"},"correctOption":"C","correctAnswer":"$105,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales equals revenue minus gross profit, so Hartwell Bakeries' $175,000 of revenue less $70,000 gross profit gives $105,000 of cost of sales.","distractor_reasons":{"A":"$245,000 adds revenue and gross profit rather than subtracting the $70,000 profit from the $175,000 revenue. For Hartwell Bakeries, option C is correct: $105,000.","B":"$70,000 is the gross profit reported by Hartwell Bakeries, not the cost of sales incurred during the year. For Hartwell Bakeries, option C is correct: $105,000.","C":"Cost of sales equals revenue minus gross profit, so Hartwell Bakeries' $175,000 of revenue less $70,000 gross profit gives $105,000 of cost of sales.","D":"$175,000 is the revenue taken before deducting the $70,000 gross profit earned by Hartwell Bakeries. For Hartwell Bakeries, option C is correct: $105,000."}}},{"id":"P1_U5_MCQ_1594","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1594","question":"Invergordon Engineering in Inverness owns delivery vans bought for $80,000 with accumulated depreciation of $32,000. What is the carrying value of the vans in its accounts?","options":{"A":"$112,000","B":"$80,000","C":"$32,000","D":"$48,000"},"correctOption":"D","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Carrying value is cost less accumulated depreciation, so the $80,000 vans minus $32,000 of depreciation are shown at $48,000 in the accounts of Invergordon Engineering.","distractor_reasons":{"A":"$112,000 wrongly adds the $80,000 cost and $32,000 depreciation instead of deducting depreciation from the value of the vans. For Invergordon Engineering, option D is correct: $48,000.","B":"$80,000 is the original cost of the vans and ignores the $32,000 of accumulated depreciation already charged. For Invergordon Engineering, option D is correct: $48,000.","C":"$32,000 is the accumulated depreciation itself, not the remaining carrying value of the vans in the accounts. For Invergordon Engineering, option D is correct: $48,000.","D":"Carrying value is cost less accumulated depreciation, so the $80,000 vans minus $32,000 of depreciation are shown at $48,000 in the accounts of Invergordon Engineering."}}},{"id":"P1_U5_MCQ_1595","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1595","question":"Jarrow Motors in Newcastle reports a gross profit margin of 18% and a profit margin of 4%. What does the gap between these two percentages represent?","options":{"A":"The cost of sales incurred by Jarrow Motors","B":"The operating expenses as a share of revenue","C":"The current liabilities of the business","D":"The tax paid on its profits"},"correctOption":"B","correctAnswer":"The operating expenses as a share of revenue","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin of 18% is calculated before operating expenses, while profit margin of 4% is after them, so the 14% gap represents operating expenses as a share of revenue.","distractor_reasons":{"A":"Cost of sales is deducted before the 18% gross profit margin is reached, so it cannot explain the gap down to 4%.","B":"Gross profit margin of 18% is calculated before operating expenses, while profit margin of 4% is after them, so the 14% gap represents operating expenses as a share of revenue.","C":"Current liabilities are balance sheet items and do not appear in either the 18% or the 4% margin. For Jarrow Motors, option B is correct: the operating expenses as a share of revenue.","D":"Tax may be part of the difference, but the full 14% gap reflects all operating expenses of Jarrow Motors relative to revenue."}}},{"id":"P1_U5_MCQ_1596","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1596","question":"Sorrento Ceramics in Naples wants to expand but cannot afford regular interest payments. It is willing to share ownership with new investors. Which source of finance fits?","options":{"A":"A bank loan with monthly repayments","B":"Issuing ordinary shares to investors","C":"A short-term bank overdraft","D":"Trade credit from suppliers"},"correctOption":"B","correctAnswer":"Issuing ordinary shares to investors","questionType":"MCQ","explanation":{"correct_reason":"Ordinary shares raise equity capital that requires no interest or fixed repayments, though Sorrento Ceramics would share ownership and control with the new investors.","distractor_reasons":{"A":"A bank loan requires regular interest and capital repayments, which Sorrento Ceramics in Naples cannot afford alongside its planned expansion.","B":"Ordinary shares raise equity capital that requires no interest or fixed repayments, though Sorrento Ceramics would share ownership and control with the new investors.","C":"An overdraft is short-term borrowing repayable on demand and charges interest, so it does not avoid the regular payments Sorrento Ceramics wants to avoid.","D":"Trade credit from suppliers merely delays payments and cannot provide the substantial long-term expansion capital needed by Sorrento Ceramics for growth."}}},{"id":"P1_U5_MCQ_1597","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1597","question":"Killarney Coaches in Ireland forecasts cash receipts of $52,000 and cash payments of $55,000 for June. Its opening bank balance is $8,000. What is the forecast closing balance?","options":{"A":"$11,000","B":"$5,000","C":"$8,000","D":"$3,000"},"correctOption":"B","correctAnswer":"$5,000","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $52,000 less $55,000, or negative $3,000, so adding this to the $8,000 opening balance leaves Killarney Coaches with $5,000.","distractor_reasons":{"A":"$11,000 wrongly adds the $3,000 shortfall to the $8,000 opening balance rather than subtracting the net outflow. For Killarney Coaches, option B is correct: $5,000.","B":"Net cash flow is $52,000 less $55,000, or negative $3,000, so adding this to the $8,000 opening balance leaves Killarney Coaches with $5,000.","C":"$8,000 is only the opening balance and ignores the $3,000 net cash outflow forecast for June at Killarney Coaches. For Killarney Coaches, option B is correct: $5,000.","D":"$3,000 is the net cash outflow itself and fails to account for the $8,000 brought forward into June by Killarney Coaches."}}},{"id":"P1_U5_MCQ_1598","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1598","question":"Lisburn Foods in Lisburn has revenue of $190,000 and cost of sales of $118,000. Which figure is its gross profit before operating expenses are deducted?","options":{"A":"$72,000","B":"$118,000","C":"$190,000","D":"$308,000"},"correctOption":"A","correctAnswer":"$72,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, so Lisburn Foods' $190,000 less $118,000 gives $72,000 before any operating expenses are deducted.","distractor_reasons":{"A":"Gross profit is revenue minus cost of sales, so Lisburn Foods' $190,000 less $118,000 gives $72,000 before any operating expenses are deducted.","B":"$118,000 is the cost of sales and is subtracted from revenue, not a profit figure earned by Lisburn Foods in Lisburn.","C":"$190,000 is revenue taken before costs, so it cannot represent the gross profit of Lisburn Foods for the year. For Lisburn Foods, option A is correct: $72,000.","D":"$308,000 wrongly adds revenue and cost of sales instead of subtracting the $118,000 expense from the $190,000 revenue. For Lisburn Foods, option A is correct: $72,000."}}},{"id":"P1_U5_MCQ_1599","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1599","question":"Mallow Engineering in Mallow has inventory of $21,000, trade receivables of $14,000, a bank overdraft of $6,000 and equipment. Which items are current assets of the business?","options":{"A":"Only the equipment and the inventory","B":"The overdraft and the receivables","C":"The inventory and the trade receivables","D":"All four items listed"},"correctOption":"C","correctAnswer":"The inventory and the trade receivables","questionType":"MCQ","explanation":{"correct_reason":"Inventory of $21,000 and trade receivables of $14,000 are current assets, while the $6,000 overdraft is a current liability and equipment is non-current.","distractor_reasons":{"A":"Equipment is a non-current asset used over many years, so it is not a current asset of Mallow Engineering. For Mallow Engineering, option C is correct: the inventory and the trade receivables.","B":"A bank overdraft of $6,000 is an amount owed to the bank, making it a current liability rather than a current asset.","C":"Inventory of $21,000 and trade receivables of $14,000 are current assets, while the $6,000 overdraft is a current liability and equipment is non-current.","D":"The overdraft is a liability and the equipment is non-current, so not all four items can be current assets of Mallow Engineering."}}},{"id":"P1_U5_MCQ_1600","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1600","question":"Nenagh Retail in Ireland reports a current ratio of 1.4:1 this year and 0.9:1 last year. What is the best interpretation of this change in liquidity?","options":{"A":"The business is now less able to meet short-term debts","B":"Short-term liquidity has improved over the year","C":"Profit margins have certainly doubled","D":"Current liabilities have fallen to zero"},"correctOption":"B","correctAnswer":"Short-term liquidity has improved over the year","questionType":"MCQ","explanation":{"correct_reason":"A rise in the current ratio from 0.9:1 to 1.4:1 means Nenagh Retail now holds more current assets for each dollar of current liabilities, so liquidity improved.","distractor_reasons":{"A":"A higher ratio of 1.4:1 shows improved, not reduced, ability to meet short-term obligations at Nenagh Retail in Ireland. For Nenagh Retail, option B is correct: short-term liquidity has improved over the year.","B":"A rise in the current ratio from 0.9:1 to 1.4:1 means Nenagh Retail now holds more current assets for each dollar of current liabilities, so liquidity improved.","C":"Current ratios compare current assets with current liabilities and say nothing about the profit margins of Nenagh Retail. For Nenagh Retail, option B is correct: short-term liquidity has improved over the year.","D":"A ratio of 1.4:1 requires current liabilities to exist, so they cannot have fallen to zero at Nenagh Retail in Ireland."}}},{"id":"P1_U5_MCQ_1601","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1601","question":"Kestrel Ceramics Ltd in Stoke-on-Trent, United Kingdom, needs $180,000 for a new kiln. It holds $70,000 of retained profit and its bank has offered a $55,000 five-year loan. How much extra finance must the business still raise?","options":{"A":"$305,000","B":"$125,000","C":"$110,000","D":"$55,000"},"correctOption":"D","correctAnswer":"$55,000","questionType":"MCQ","explanation":{"correct_reason":"Subtract both available funds from the $180,000 kiln cost: $180,000 minus $70,000 retained profit minus the $55,000 bank loan leaves $55,000 of extra finance still needed.","distractor_reasons":{"A":"This adds all three figures together instead of subtracting available funds from the $180,000 cost. For Kestrel Ceramics Ltd, option D is correct: $55,000.","B":"This deducts only the $70,000 retained profit and ignores the $55,000 loan already offered, so the shortfall is overstated at $125,000.","C":"This deducts only the $55,000 loan and ignores the $70,000 retained profit, doubling the apparent gap. For Kestrel Ceramics Ltd, option D is correct: $55,000.","D":"Subtract both available funds from the $180,000 kiln cost: $180,000 minus $70,000 retained profit minus the $55,000 bank loan leaves $55,000 of extra finance still needed."}}},{"id":"P1_U5_MCQ_1602","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1602","question":"A wholesale fish merchant in Bergen, Norway, is preparing a cash flow forecast for the next quarter. Which of the following is the primary purpose of such a forecast for this business?","options":{"A":"To calculate the total profit for the quarter","B":"To determine the legal structure of the firm","C":"To identify the business's share of the local market","D":"To predict the timing and size of cash inflows and outflows"},"correctOption":"D","correctAnswer":"To predict the timing and size of cash inflows and outflows","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast for the Bergen fish merchant estimates when cash will enter and leave the business, helping it anticipate shortages or surpluses and plan borrowing. It tracks the timing and size of inflows and outflows rather than profit or market share.","distractor_reasons":{"A":"Profit is measured in a profit and loss account, not a cash flow forecast, because a forecast records cash movements rather than revenue matched with expenses.","B":"Legal structure is a matter of business organisation, not cash forecasting. For a wholesale fish merchant, option D is correct: to predict the timing and size of cash inflows and outflows.","C":"Market share requires external market data and is not calculated from a cash flow forecast. For a wholesale fish merchant, option D is correct: to predict the timing and size of cash inflows and outflows.","D":"A cash flow forecast for the Bergen fish merchant estimates when cash will enter and leave the business, helping it anticipate shortages or surpluses and plan borrowing. It tracks the timing and size of inflows and outflows rather than profit or market share."}}},{"id":"P1_U5_MCQ_1603","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1603","question":"A furniture maker in Tallinn, Estonia, wants to report profit from normal trading after deducting operating expenses but before interest and taxation are charged. Which figure in the profit and loss account should it use?","options":{"A":"Gross profit","B":"Total revenue","C":"Profit for the year","D":"Operating profit"},"correctOption":"D","correctAnswer":"Operating profit","questionType":"MCQ","explanation":{"correct_reason":"Operating profit is gross profit less operating expenses, calculated before interest and taxation. For the Tallinn furniture maker it measures the return from normal trading activities without the effects of financing decisions or tax charges.","distractor_reasons":{"A":"Gross profit is only revenue less cost of sales and still excludes operating expenses such as wages and rent. For a furniture maker, option D is correct: operating profit.","B":"Total revenue is sales income before any costs are deducted, so it cannot represent a profit figure. For a furniture maker, option D is correct: operating profit.","C":"Profit for the year is calculated after interest and taxation have been deducted, which is later than the stage the question specifies.","D":"Operating profit is gross profit less operating expenses, calculated before interest and taxation. For the Tallinn furniture maker it measures the return from normal trading activities without the effects of financing decisions or tax charges."}}},{"id":"P1_U5_MCQ_1604","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1604","question":"A cocoa processor in Accra, Ghana, lists its delivery vans, mixing machinery and factory building in its accounts. In a statement of financial position, how should these items be classified?","options":{"A":"Current liabilities","B":"Equity","C":"Current assets","D":"Non-current assets"},"correctOption":"D","correctAnswer":"Non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Delivery vans, mixing machinery and the factory building are long-lived resources used repeatedly in the Accra processor's operations. They are reported as non-current assets because they are not expected to be converted into cash within one year.","distractor_reasons":{"A":"Current liabilities are short-term debts such as payables or overdrafts, whereas vans and buildings are resources owned. For a cocoa processor, option D is correct: non-current assets.","B":"Equity represents the owners' claim on the business, not physical resources it owns. For a cocoa processor, option D is correct: non-current assets.","C":"Current assets are short-term items like stock, receivables and cash. Long-lived machinery and buildings in Accra do not fit that description.","D":"Delivery vans, mixing machinery and the factory building are long-lived resources used repeatedly in the Accra processor's operations. They are reported as non-current assets because they are not expected to be converted into cash within one year."}}},{"id":"P1_U5_MCQ_1605","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1605","question":"A supermarket chain in Nairobi, Kenya, reports current assets of $360,000 and current liabilities of $150,000. What is its current ratio, expressed to two decimal places?","options":{"A":"0.60 : 1","B":"0.42 : 1","C":"1.40 : 1","D":"2.40 : 1"},"correctOption":"D","correctAnswer":"2.40 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets divided by current liabilities, so $360,000 divided by $150,000 equals 2.40. Expressed as 2.40 : 1, it shows the Nairobi supermarket has $2.40 of current assets for every dollar of short-term debt.","distractor_reasons":{"A":"This divides current liabilities of $150,000 by an incorrect figure rather than $360,000 of current assets. For a supermarket chain, option D is correct: 2.40 : 1.","B":"This inverts the formula, dividing $150,000 of current liabilities by $360,000 of current assets. The current ratio places assets first, so this reciprocal cannot be the answer.","C":"This appears to subtract $150,000 from $360,000 and mishandle the remainder. The current ratio requires division of the two figures, not subtraction, so this value is wrong.","D":"The current ratio is current assets divided by current liabilities, so $360,000 divided by $150,000 equals 2.40. Expressed as 2.40 : 1, it shows the Nairobi supermarket has $2.40 of current assets for every dollar of short-term debt."}}},{"id":"P1_U5_MCQ_1606","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1606","question":"A craft brewery in Melbourne, Australia, is choosing between issuing new shares and taking a bank loan to fund expansion. Which statement about these two sources of finance is correct?","options":{"A":"Share issues must be repaid at a fixed future date","B":"Bank loans give the lender ownership of the brewery","C":"Dividends on shares are compulsory regardless of profit","D":"Bank loans must be repaid with interest, while dividends are paid only if profits allow"},"correctOption":"D","correctAnswer":"Bank loans must be repaid with interest, while dividends are paid only if profits allow","questionType":"MCQ","explanation":{"correct_reason":"A bank loan is debt that must be repaid with interest on agreed terms, whereas dividends on issued shares are paid at the directors' discretion and usually only when profits are sufficient. This distinction is central to the Melbourne brewery's financing choice.","distractor_reasons":{"A":"Share capital is equity and does not have to be repaid at a fixed date; unlike a loan, it remains in the business.","B":"A bank is a lender, not an owner, so it does not gain ownership of the Melbourne brewery. For a craft brewery, option D is correct: bank loans must be repaid with interest, while dividends are paid only if profits allow.","C":"Dividends are not compulsory and are normally paid out of profits when directors decide to do so. For a craft brewery, option D is correct: bank loans must be repaid with interest, while dividends are paid only if profits allow.","D":"A bank loan is debt that must be repaid with interest on agreed terms, whereas dividends on issued shares are paid at the directors' discretion and usually only when profits are sufficient. This distinction is central to the Melbourne brewery's financing choice."}}},{"id":"P1_U5_MCQ_1607","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1607","question":"A ski-equipment retailer in Innsbruck, Austria, expects most sales in December but must pay suppliers in September. Why is a cash flow forecast especially useful for this retailer?","options":{"A":"It guarantees the retailer will make a profit","B":"It fixes the prices charged to customers","C":"It shows when a temporary cash shortfall may occur so borrowing can be arranged","D":"It removes the need to keep any accounting records"},"correctOption":"C","correctAnswer":"It shows when a temporary cash shortfall may occur so borrowing can be arranged","questionType":"MCQ","explanation":{"correct_reason":"Because the Innsbruck retailer pays suppliers in September but receives sales cash in December, a forecast highlights months when outflows exceed inflows. This warning allows the business to arrange an overdraft or other short-term finance to cover the temporary shortfall.","distractor_reasons":{"A":"A cash flow forecast tracks money moving in and out, not profitability, and it cannot guarantee a profit. For a ski-equipment retailer, option C is correct: it shows when a temporary cash shortfall may occur so borrowing can be arranged.","B":"The forecast does not set selling prices; those are a pricing decision. For a ski-equipment retailer, option C is correct: it shows when a temporary cash shortfall may occur so borrowing can be arranged.","C":"Because the Innsbruck retailer pays suppliers in September but receives sales cash in December, a forecast highlights months when outflows exceed inflows. This warning allows the business to arrange an overdraft or other short-term finance to cover the temporary shortfall.","D":"A forecast supplements rather than replaces proper accounting records. For a ski-equipment retailer, option C is correct: it shows when a temporary cash shortfall may occur so borrowing can be arranged."}}},{"id":"P1_U5_MCQ_1608","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1608","question":"A tea exporter in Colombo, Sri Lanka, wants to measure the overall financial result for the year after all expenses, including interest and tax, have been deducted. Which figure should it use?","options":{"A":"Gross profit","B":"Operating profit","C":"Profit for the year","D":"Revenue"},"correctOption":"C","correctAnswer":"Profit for the year","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is the final figure in the profit and loss account once operating costs, interest and taxation have all been deducted. For the Colombo tea exporter it is the appropriate measure of the year's overall financial result.","distractor_reasons":{"A":"Gross profit is only revenue less cost of sales, so it ignores operating expenses, interest and tax. For a tea exporter, option C is correct: profit for the year.","B":"Operating profit is calculated before interest and taxation are deducted, so it is not the final figure requested. For a tea exporter, option C is correct: profit for the year.","C":"Profit for the year is the final figure in the profit and loss account once operating costs, interest and taxation have all been deducted. For the Colombo tea exporter it is the appropriate measure of the year's overall financial result.","D":"Revenue is total sales income before any costs are deducted and cannot represent profit. For a tea exporter, option C is correct: profit for the year."}}},{"id":"P1_U5_MCQ_1609","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1609","question":"A mobile phone repair shop in Manila, Philippines, recorded revenue of $96,000, cost of sales of $41,000, operating expenses of $28,000, interest of $3,000 and tax of $4,000. What was its profit for the year?","options":{"A":"$24,000","B":"$55,000","C":"$27,000","D":"$20,000"},"correctOption":"D","correctAnswer":"$20,000","questionType":"MCQ","explanation":{"correct_reason":"From $96,000 revenue deduct $41,000 cost of sales to get $55,000, then $28,000 expenses to get $27,000, then $3,000 interest and $4,000 tax, leaving profit for the year of $20,000 for the Manila shop.","distractor_reasons":{"A":"This deducts cost of sales, expenses and interest from $96,000 but forgets the $4,000 tax charge. For a mobile phone repair shop, option D is correct: $20,000.","B":"This is only gross profit from $96,000 revenue less $41,000 cost of sales. It ignores the $28,000 expenses, $3,000 interest and $4,000 tax that must also be deducted.","C":"This is the operating profit, reached after cost of sales and operating expenses but before the $3,000 interest and $4,000 tax are subtracted from the Manila shop's revenue.","D":"From $96,000 revenue deduct $41,000 cost of sales to get $55,000, then $28,000 expenses to get $27,000, then $3,000 interest and $4,000 tax, leaving profit for the year of $20,000 for the Manila shop."}}},{"id":"P1_U5_MCQ_1610","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1610","question":"An auditing assistant is comparing two rival bakeries in Krakow, Poland, using ratio analysis. Which of the following is a valid limitation of using ratios to assess a business's performance?","options":{"A":"Ratios never use figures from financial statements","B":"Ratios cannot be calculated for service businesses","C":"Ratios may be distorted by inflation and do not explain the causes behind the numbers","D":"Ratios always predict future profits accurately"},"correctOption":"C","correctAnswer":"Ratios may be distorted by inflation and do not explain the causes behind the numbers","questionType":"MCQ","explanation":{"correct_reason":"Ratios are calculated from historical financial statements, so price changes over time can distort comparisons, and a ratio highlights a symptom rather than explaining why it occurred. The Krakow assistant must investigate underlying causes before concluding.","distractor_reasons":{"A":"Ratios are derived directly from figures in financial statements such as the profit and loss account and statement of financial position.","B":"Ratios can be calculated for any business producing financial statements, including service firms like the Krakow bakeries. For an auditing assistant is comparing two rival bakeries, option C is correct: ratios may be distorted by inflation and do not explain the causes behind the numbers.","C":"Ratios are calculated from historical financial statements, so price changes over time can distort comparisons, and a ratio highlights a symptom rather than explaining why it occurred. The Krakow assistant must investigate underlying causes before concluding.","D":"Ratios describe past performance and cannot guarantee accurate forecasts of future profit. For an auditing assistant is comparing two rival bakeries, option C is correct: ratios may be distorted by inflation and do not explain the causes behind the numbers."}}},{"id":"P1_U5_MCQ_1611","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1611","question":"A family-owned hotel in Split, Croatia, funded a new roof using money accumulated from past profits rather than borrowing. What is this source of finance called?","options":{"A":"External debt","B":"Share issue","C":"Retained earnings","D":"Trade credit"},"correctOption":"C","correctAnswer":"Retained earnings","questionType":"MCQ","explanation":{"correct_reason":"Money kept in the business from previous years' profits is known as retained earnings or retained profit. Because the Split hotel generated it internally rather than borrowing, it is internal finance that carries no interest charge.","distractor_reasons":{"A":"External debt would involve borrowing from a bank and paying interest. For a family-owned hotel, option C is correct: retained earnings.","B":"A share issue raises fresh capital by selling ownership stakes to investors. For a family-owned hotel, option C is correct: retained earnings.","C":"Money kept in the business from previous years' profits is known as retained earnings or retained profit. Because the Split hotel generated it internally rather than borrowing, it is internal finance that carries no interest charge.","D":"Trade credit means delaying payment to suppliers, a short-term external source. For a family-owned hotel, option C is correct: retained earnings."}}},{"id":"P1_U5_MCQ_1612","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1612","question":"A courier firm in Turin, Italy, notes that its cash receipts during June exceeded its cash payments by $8,500. What does this indicate about the firm's net cash flow for the month?","options":{"A":"Net cash flow was negative $8,500","B":"Net cash flow cannot be determined from this information","C":"Net cash flow was exactly zero","D":"Net cash flow was positive $8,500"},"correctOption":"D","correctAnswer":"Net cash flow was positive $8,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is cash receipts minus cash payments. Since the Turin courier received $8,500 more than it paid out in June, net cash flow is a positive $8,500, meaning the firm's cash balance increased over the month.","distractor_reasons":{"A":"A negative net cash flow requires payments to exceed receipts, yet the Turin courier's receipts were higher by $8,500. For a courier firm, option D is correct: net cash flow was positive $8,500.","B":"The information supplied is sufficient because receipts minus payments gives net cash flow directly. For a courier firm, option D is correct: net cash flow was positive $8,500.","C":"Zero net cash flow would mean receipts exactly matched payments, but the stated $8,500 surplus shows they did not match.","D":"Net cash flow is cash receipts minus cash payments. Since the Turin courier received $8,500 more than it paid out in June, net cash flow is a positive $8,500, meaning the firm's cash balance increased over the month."}}},{"id":"P1_U5_MCQ_1613","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1613","question":"A hardware store in Vancouver, Canada, had an opening cash balance of $12,300 on 1 July. During July it received $57,000 and paid out $61,800. What was its closing cash balance on 31 July?","options":{"A":"$4,800","B":"$17,100","C":"$7,500","D":"$71,100"},"correctOption":"C","correctAnswer":"$7,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow for July is $57,000 receipts minus $61,800 payments, a net outflow of $4,800. Adding this to the $12,300 opening balance gives a closing cash balance of $7,500 on 31 July for the Vancouver store.","distractor_reasons":{"A":"This is only the net cash outflow for the month and ignores the $12,300 the store already held at the start of July, so it cannot be the closing balance.","B":"This adds the $4,800 net outflow to the opening balance instead of subtracting it. Payments exceeded receipts, so the Vancouver store's cash balance must have fallen, not risen.","C":"Net cash flow for July is $57,000 receipts minus $61,800 payments, a net outflow of $4,800. Adding this to the $12,300 opening balance gives a closing cash balance of $7,500 on 31 July for the Vancouver store.","D":"This adds $57,000 receipts to the $12,300 opening balance but ignores the $61,800 of payments made during July. For a hardware store, option C is correct: $7,500."}}},{"id":"P1_U5_MCQ_1614","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1614","question":"A boat builder in Gdansk, Poland, owes a supplier $18,000 for timber, payable within 30 days. How is this amount classified in the statement of financial position?","options":{"A":"Non-current liability","B":"Owner's capital","C":"Current asset","D":"Current liability"},"correctOption":"D","correctAnswer":"Current liability","questionType":"MCQ","explanation":{"correct_reason":"An amount owed to a supplier that must be settled within 30 days is a short-term obligation, so it is reported as a current liability. It is not a non-current liability because it is due well within one year, and it is not an asset.","distractor_reasons":{"A":"A non-current liability is a long-term debt repayable after more than a year, such as a ten-year loan. For a boat builder, option D is correct: current liability.","B":"Owner's capital represents the owner's investment and claim on the Gdansk business, not an amount payable to a supplier. For a boat builder, option D is correct: current liability.","C":"A current asset is something the business owns and expects to use or convert to cash shortly, not money owed to a supplier.","D":"An amount owed to a supplier that must be settled within 30 days is a short-term obligation, so it is reported as a current liability. It is not a non-current liability because it is due well within one year, and it is not an asset."}}},{"id":"P1_U5_MCQ_1615","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1615","question":"A financial analyst is comparing the gross profit margins of two rival electronics retailers in Seoul, South Korea. Why should the analyst be cautious when interpreting a difference between their ratios?","options":{"A":"Because all retailers must have identical margins","B":"Because ratios are never expressed as percentages","C":"Because the businesses may use different accounting policies or operate in different market segments","D":"Because gross profit margin ignores revenue entirely"},"correctOption":"C","correctAnswer":"Because the businesses may use different accounting policies or operate in different market segments","questionType":"MCQ","explanation":{"correct_reason":"Two businesses may classify costs differently, use different stock valuation methods or serve different customer segments, making their gross profit margins non-comparable. The analyst should investigate these differences before judging one Seoul retailer superior.","distractor_reasons":{"A":"Rivals in the same city need not have identical margins; pricing, cost structure and product mix are normal sources of difference.","B":"Gross profit margin is commonly expressed as a percentage, so saying ratios are never percentages is false. For a financial analyst is comparing the gross profit margins of two rival electronics retailers, option C is correct: because the businesses may use different accounting policies or operate in different market segments.","C":"Two businesses may classify costs differently, use different stock valuation methods or serve different customer segments, making their gross profit margins non-comparable. The analyst should investigate these differences before judging one Seoul retailer superior.","D":"Gross profit margin is calculated using gross profit and revenue as the denominator, so it does not ignore revenue. For a financial analyst is comparing the gross profit margins of two rival electronics retailers, option C is correct: because the businesses may use different accounting policies or operate in different market segments."}}},{"id":"P1_U5_MCQ_1616","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1616","question":"A fruit stall in Marrakesh, Morocco, needs short-term funds to buy stock before the weekend market. Which source of finance is most suitable for this temporary need?","options":{"A":"A 20-year mortgage","B":"Issuing new ordinary shares","C":"A bank overdraft","D":"A debenture repayable in 2035"},"correctOption":"C","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"A bank overdraft allows a business to borrow small amounts for a short period and repay when cash arrives, which suits the Marrakesh fruit stall's weekend stock purchase. Long-term options would be expensive and unnecessary for a temporary need.","distractor_reasons":{"A":"A twenty-year mortgage is designed for long-term property investment and would commit the stall for decades. For a fruit stall, option C is correct: a bank overdraft.","B":"Issuing shares raises permanent equity with legal costs and dilution of ownership. For a fruit stall, option C is correct: a bank overdraft.","C":"A bank overdraft allows a business to borrow small amounts for a short period and repay when cash arrives, which suits the Marrakesh fruit stall's weekend stock purchase. Long-term options would be expensive and unnecessary for a temporary need.","D":"A debenture repayable in 2035 is long-term debt, whereas the stall needs money for a few days. For a fruit stall, option C is correct: a bank overdraft."}}},{"id":"P1_U5_MCQ_1617","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1617","question":"A paper mill in Oulu, Finland, reports current assets of $420,000 and current liabilities of $255,000. What is its working capital? State your answer in dollars.","options":{"A":"$420,000","B":"$675,000","C":"$255,000","D":"$165,000"},"correctOption":"D","correctAnswer":"$165,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities. For the Oulu paper mill that is $420,000 less $255,000, which equals $165,000, the short-term funds available to support its day-to-day operations.","distractor_reasons":{"A":"This repeats current assets without deducting the $255,000 owed in the short term. For a paper mill, option D is correct: $165,000.","B":"This adds current assets and current liabilities together rather than finding the difference. For a paper mill, option D is correct: $165,000.","C":"This simply repeats the current liabilities figure and ignores the $420,000 of current assets. For a paper mill, option D is correct: $165,000.","D":"Working capital is current assets minus current liabilities. For the Oulu paper mill that is $420,000 less $255,000, which equals $165,000, the short-term funds available to support its day-to-day operations."}}},{"id":"P1_U5_MCQ_1618","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1618","question":"A computer shop in Bratislava, Slovakia, buys a printer for $120 and sells it for $150. The owner wants to express the profit as a percentage of the selling price. What is this measure called?","options":{"A":"Mark-up on cost","B":"Current ratio","C":"Gross profit margin","D":"Net cash flow"},"correctOption":"C","correctAnswer":"Gross profit margin","questionType":"MCQ","explanation":{"correct_reason":"Expressing the $30 profit as a percentage of the $150 selling price gives a gross profit margin of twenty per cent. A margin uses sales revenue as the base, whereas a mark-up would use the $120 cost instead.","distractor_reasons":{"A":"A mark-up on cost would divide the $30 profit by the $120 cost price, not by the $150 selling price. Since the owner wants a percentage of selling price, this is a margin.","B":"The current ratio compares current assets with current liabilities and has nothing to do with profit on a printer. For a computer shop, option C is correct: gross profit margin.","C":"Expressing the $30 profit as a percentage of the $150 selling price gives a gross profit margin of twenty per cent. A margin uses sales revenue as the base, whereas a mark-up would use the $120 cost instead.","D":"Net cash flow compares cash receipts with cash payments over a period and does not express profit as a percentage of selling price."}}},{"id":"P1_U5_MCQ_1619","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1619","question":"A dance studio in Seville, Spain, is listing the expected cash receipts for its monthly forecast. Which of the following items should be included as a cash inflow in that forecast?","options":{"A":"Payment of rent to the landlord","B":"Purchase of new mirrors","C":"Repayment of a bank loan","D":"Cash from students paying for classes"},"correctOption":"D","correctAnswer":"Cash from students paying for classes","questionType":"MCQ","explanation":{"correct_reason":"Cash received from students paying for classes is an inflow because it brings money into the Seville dance studio. Rent, loan repayments and buying mirrors are payments that take cash out, so they belong among the forecast's outflows.","distractor_reasons":{"A":"Paying rent sends cash out to the landlord, so it is a cash outflow. For a dance studio, option D is correct: cash from students paying for classes.","B":"Buying new mirrors requires paying a supplier, which is an outflow of cash. For a dance studio, option D is correct: cash from students paying for classes.","C":"Repaying a bank loan reduces the studio's cash balance, so it is recorded as an outflow. For a dance studio, option D is correct: cash from students paying for classes.","D":"Cash received from students paying for classes is an inflow because it brings money into the Seville dance studio. Rent, loan repayments and buying mirrors are payments that take cash out, so they belong among the forecast's outflows."}}},{"id":"P1_U5_MCQ_1620","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1620","question":"An investor is assessing a logistics firm in Rotterdam, Netherlands, and wants to know how efficiently the firm uses its capital to generate operating profit. Which ratio should be calculated?","options":{"A":"Current ratio","B":"Gross profit margin","C":"Return on capital employed","D":"Acid test ratio"},"correctOption":"C","correctAnswer":"Return on capital employed","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed divides operating profit by capital employed and shows how much operating profit is generated from each dollar invested. It is the appropriate ratio for judging how efficiently the Rotterdam firm uses its capital.","distractor_reasons":{"A":"The current ratio compares current assets with current liabilities and measures short-term liquidity. For an investor is assessing a logistics firm, option C is correct: return on capital employed.","B":"Gross profit margin compares gross profit with revenue, showing the trading margin on sales. For an investor is assessing a logistics firm, option C is correct: return on capital employed.","C":"Return on capital employed divides operating profit by capital employed and shows how much operating profit is generated from each dollar invested. It is the appropriate ratio for judging how efficiently the Rotterdam firm uses its capital.","D":"The acid test ratio is a stricter liquidity measure that excludes stock from current assets. For an investor is assessing a logistics firm, option C is correct: return on capital employed."}}},{"id":"P1_U5_MCQ_1621","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1621","question":"A textile dyeing plant in Surat, India, needs $320,000 for new equipment. It has $95,000 of retained profit and has been awarded a $75,000 government grant. How much must the plant borrow?","options":{"A":"$225,000","B":"$95,000","C":"$245,000","D":"$150,000"},"correctOption":"D","correctAnswer":"$150,000","questionType":"MCQ","explanation":{"correct_reason":"The Surat plant must cover a $320,000 equipment cost using $95,000 of retained profit and a $75,000 grant, leaving $320,000 minus $95,000 minus $75,000, which equals $150,000 to be borrowed.","distractor_reasons":{"A":"This deducts only the $95,000 retained profit from the $320,000 cost and overlooks the $75,000 grant. For a textile dyeing plant, option D is correct: $150,000.","B":"This repeats the retained profit figure rather than calculating the outstanding balance after both internal funds and the grant have been applied to the equipment cost.","C":"This deducts only the $75,000 grant and ignores the $95,000 of retained profit, so the amount said to be borrowed is too large.","D":"The Surat plant must cover a $320,000 equipment cost using $95,000 of retained profit and a $75,000 grant, leaving $320,000 minus $95,000 minus $75,000, which equals $150,000 to be borrowed."}}},{"id":"P1_U5_MCQ_1622","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1622","question":"A toy shop in Copenhagen, Denmark, sees its cash flow forecast predict a negative balance in February. What should the owner do first after seeing this warning?","options":{"A":"Ignore the forecast because it is only an estimate","B":"Stop preparing all future forecasts","C":"Arrange short-term finance or delay some payments before February","D":"Immediately sell the entire business"},"correctOption":"C","correctAnswer":"Arrange short-term finance or delay some payments before February","questionType":"MCQ","explanation":{"correct_reason":"A forecast showing a negative balance warns of a potential cash shortfall, so the prudent response is to arrange an overdraft, negotiate longer payment terms or delay discretionary spending before February. Acting early gives the Copenhagen shop time to secure funds.","distractor_reasons":{"A":"Ignoring a forecast because it is an estimate is risky; forecasts exist precisely to warn of problems in advance. For a toy shop, option C is correct: arrange short-term finance or delay some payments before February.","B":"Stopping future forecasts would remove a useful planning tool and leave the shop unprepared. For a toy shop, option C is correct: arrange short-term finance or delay some payments before February.","C":"A forecast showing a negative balance warns of a potential cash shortfall, so the prudent response is to arrange an overdraft, negotiate longer payment terms or delay discretionary spending before February. Acting early gives the Copenhagen shop time to secure funds.","D":"Selling the whole business is drastic and unjustified by a temporary predicted shortfall. For a toy shop, option C is correct: arrange short-term finance or delay some payments before February."}}},{"id":"P1_U5_MCQ_1623","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1623","question":"A bakery in Lisbon, Portugal, wants to calculate its cost of sales for the year. Which of the following should be included in that figure for the bakery?","options":{"A":"Interest paid on a bank loan","B":"Advertising expenditure","C":"Dividends paid to shareholders","D":"The cost of flour and ingredients used in production"},"correctOption":"D","correctAnswer":"The cost of flour and ingredients used in production","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales consists of the direct costs of producing the goods sold, such as the flour and ingredients the Lisbon bakery uses. Interest, dividends and advertising are finance costs or operating expenses and are not part of cost of sales.","distractor_reasons":{"A":"Interest on a bank loan is a finance cost shown after operating profit, not a direct production cost. For a bakery, option D is correct: the cost of flour and ingredients used in production.","B":"Advertising is an operating expense aimed at promoting sales, not a direct cost of producing loaves. For a bakery, option D is correct: the cost of flour and ingredients used in production.","C":"Dividends are distributions of profit to owners, not expenses incurred in making bread. For a bakery, option D is correct: the cost of flour and ingredients used in production.","D":"Cost of sales consists of the direct costs of producing the goods sold, such as the flour and ingredients the Lisbon bakery uses. Interest, dividends and advertising are finance costs or operating expenses and are not part of cost of sales."}}},{"id":"P1_U5_MCQ_1624","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1624","question":"A software company in Dublin, Ireland, has developed a patented program and holds the legal right to its brand name. How should these items be treated in the statement of financial position?","options":{"A":"As current liabilities","B":"As revenue","C":"As non-current assets","D":"As share capital"},"correctOption":"C","correctAnswer":"As non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Patents and legally protected brand names are non-current assets because they are long-lived resources controlled by the Dublin company that provide future economic benefits. They have no physical form, so they are often described as intangible non-current assets.","distractor_reasons":{"A":"Current liabilities are short-term debts, not valuable rights owned by the business. For a software company, option C is correct: as non-current assets.","B":"Revenue is income earned from sales during a period, not a resource owned at the reporting date. For a software company, option C is correct: as non-current assets.","C":"Patents and legally protected brand names are non-current assets because they are long-lived resources controlled by the Dublin company that provide future economic benefits. They have no physical form, so they are often described as intangible non-current assets.","D":"Share capital represents funds invested by shareholders, not separate resources developed by the company. For a software company, option C is correct: as non-current assets."}}},{"id":"P1_U5_MCQ_1625","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1625","question":"A cosmetics retailer in Prague, Czech Republic, recorded revenue of $250,000 and cost of sales of $160,000. What was its gross profit margin, to one decimal place?","options":{"A":"156.3%","B":"64.0%","C":"90.0%","D":"36.0%"},"correctOption":"D","correctAnswer":"36.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $250,000 revenue less $160,000 cost of sales, giving $90,000. Dividing $90,000 by $250,000 and multiplying by one hundred gives a gross profit margin of 36.0 per cent for the Prague retailer.","distractor_reasons":{"A":"This divides revenue of $250,000 by cost of sales of $160,000, inverting the correct relationship. For a cosmetics retailer, option D is correct: 36.0%.","B":"This expresses cost of sales of $160,000 as a percentage of the $250,000 revenue. The gross profit margin uses gross profit of $90,000 as the numerator, so this figure is incorrect.","C":"This mistakenly treats the $90,000 gross profit as a percentage without dividing by revenue. A margin must be calculated relative to sales, so ninety per cent is not supported.","D":"Gross profit is $250,000 revenue less $160,000 cost of sales, giving $90,000. Dividing $90,000 by $250,000 and multiplying by one hundred gives a gross profit margin of 36.0 per cent for the Prague retailer."}}},{"id":"P1_U5_MCQ_1626","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1626","question":"A stationery wholesaler in Buenos Aires, Argentina, receives stock from suppliers and is allowed 45 days to pay. What is this arrangement called in finance terms?","options":{"A":"Leasing","B":"Mortgage","C":"Trade credit","D":"Share issue"},"correctOption":"C","correctAnswer":"Trade credit","questionType":"MCQ","explanation":{"correct_reason":"When suppliers deliver goods and permit payment at a later date, the buyer is using trade credit. The Buenos Aires wholesaler gains short-term use of the stationery without paying immediately, which helps working capital, but should repay within 45 days.","distractor_reasons":{"A":"Leasing involves renting an asset such as a vehicle or machine for regular payments. For a stationery wholesaler, option C is correct: trade credit.","B":"A mortgage is a long-term loan secured on property and repaid over many years. For a stationery wholesaler, option C is correct: trade credit.","C":"When suppliers deliver goods and permit payment at a later date, the buyer is using trade credit. The Buenos Aires wholesaler gains short-term use of the stationery without paying immediately, which helps working capital, but should repay within 45 days.","D":"A share issue raises equity by selling ownership stakes to investors. For a stationery wholesaler, option C is correct: trade credit."}}},{"id":"P1_U5_MCQ_1627","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1627","question":"A garden centre in Bordeaux, France, buys plants in March but does not receive cash from customers until May. What problem does this timing difference most likely create?","options":{"A":"The business will definitely make a loss","B":"Its profit and loss account will be inaccurate","C":"The business will have too much cash in May","D":"A temporary cash shortfall may occur in March and April"},"correctOption":"D","correctAnswer":"A temporary cash shortfall may occur in March and April","questionType":"MCQ","explanation":{"correct_reason":"Paying for plants in March while receiving sales cash only in May creates a gap in which outflows exceed inflows. The Bordeaux garden centre may face a temporary cash shortfall in March and April even though the plants will eventually be sold profitably.","distractor_reasons":{"A":"A timing difference does not guarantee a loss; once customers pay in May, the centre can be profitable. For a garden centre, option D is correct: a temporary cash shortfall may occur in March and April.","B":"A timing difference does not make the profit and loss account inaccurate; that statement matches revenue with costs. For a garden centre, option D is correct: a temporary cash shortfall may occur in March and April.","C":"May may bring an inflow, but the issue concerns the earlier gap when payments came first. For a garden centre, option D is correct: a temporary cash shortfall may occur in March and April.","D":"Paying for plants in March while receiving sales cash only in May creates a gap in which outflows exceed inflows. The Bordeaux garden centre may face a temporary cash shortfall in March and April even though the plants will eventually be sold profitably."}}},{"id":"P1_U5_MCQ_1628","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1628","question":"A cinemas operator in Warsaw, Poland, wants to measure profit from its normal trading activities before interest and taxation. Which figure in the profit and loss account should it use?","options":{"A":"Gross profit","B":"Profit for the year","C":"Operating profit","D":"Total liabilities"},"correctOption":"C","correctAnswer":"Operating profit","questionType":"MCQ","explanation":{"correct_reason":"Operating profit is calculated from gross profit after deducting operating expenses, but before interest and tax are charged. For the Warsaw cinema operator it measures the profitability of normal trading without financing or tax effects.","distractor_reasons":{"A":"Gross profit is only revenue less cost of sales and still excludes operating expenses such as wages and rent. For a cinemas operator, option C is correct: operating profit.","B":"Profit for the year is calculated after interest and taxation, later than the stage requested. For a cinemas operator, option C is correct: operating profit.","C":"Operating profit is calculated from gross profit after deducting operating expenses, but before interest and tax are charged. For the Warsaw cinema operator it measures the profitability of normal trading without financing or tax effects.","D":"Total liabilities appear in the statement of financial position and are not a profit figure. For a cinemas operator, option C is correct: operating profit."}}},{"id":"P1_U5_MCQ_1629","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1629","question":"A firm in Ghent, Belgium, has non-current assets of $480,000, current assets of $150,000 and total liabilities of $230,000. What are its net assets? Show your answer in dollars.","options":{"A":"$170,000","B":"$630,000","C":"$860,000","D":"$400,000"},"correctOption":"D","correctAnswer":"$400,000","questionType":"MCQ","explanation":{"correct_reason":"Net assets equal total assets minus total liabilities. The Ghent firm's assets are $480,000 plus $150,000, giving $630,000. Subtracting $230,000 of liabilities leaves net assets of $400,000, which equals the shareholders' equity.","distractor_reasons":{"A":"This subtracts $230,000 from an incorrect base rather than from the $630,000 of total assets. For a firm, option D is correct: $400,000.","B":"This is the total of non-current and current assets but fails to deduct the $230,000 owed to creditors. Net assets are the residual after liabilities are subtracted.","C":"This adds liabilities to total assets instead of deducting them. Net assets represent what remains for owners after obligations, so this figure overstates the position.","D":"Net assets equal total assets minus total liabilities. The Ghent firm's assets are $480,000 plus $150,000, giving $630,000. Subtracting $230,000 of liabilities leaves net assets of $400,000, which equals the shareholders' equity."}}},{"id":"P1_U5_MCQ_1630","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1630","question":"A bank manager is reviewing the accounts of a hotel in Nice, France, over four years. Why is comparing the hotel's ratios across those years useful?","options":{"A":"It removes the need to prepare annual accounts","B":"It guarantees the hotel will earn a profit next year","C":"It reveals whether performance is improving or deteriorating over time","D":"It shows the exact market share of the hotel"},"correctOption":"C","correctAnswer":"It reveals whether performance is improving or deteriorating over time","questionType":"MCQ","explanation":{"correct_reason":"Comparing ratios over several years reveals trends, such as whether margins are widening or liquidity weakening, which a single year's figures cannot show. For the Nice hotel this trend evidence helps the bank manager judge the direction of performance.","distractor_reasons":{"A":"Trend analysis depends on having several years of accounts, so it increases rather than removes the need for statements. For a bank manager is reviewing the accounts of a hotel, option C is correct: it reveals whether performance is improving or deteriorating over time.","B":"Past ratios cannot guarantee future profit, since conditions and decisions may change. For a bank manager is reviewing the accounts of a hotel, option C is correct: it reveals whether performance is improving or deteriorating over time.","C":"Comparing ratios over several years reveals trends, such as whether margins are widening or liquidity weakening, which a single year's figures cannot show. For the Nice hotel this trend evidence helps the bank manager judge the direction of performance.","D":"Ratios from the hotel's own accounts describe financial performance, not its share of the local market. For a bank manager is reviewing the accounts of a hotel, option C is correct: it reveals whether performance is improving or deteriorating over time."}}},{"id":"P1_U5_MCQ_1631","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1631","question":"A furniture importer in Kuala Lumpur, Malaysia, is offered a bank loan secured against its warehouse. What does secured mean in this context for the importer?","options":{"A":"The loan carries no interest","B":"The lender becomes a shareholder","C":"The loan never has to be repaid","D":"The lender can seize the warehouse if repayments are not made"},"correctOption":"D","correctAnswer":"The lender can seize the warehouse if repayments are not made","questionType":"MCQ","explanation":{"correct_reason":"A secured loan gives the lender a legal claim on a specific asset, here the Kuala Lumpur importer's warehouse. If repayments are not made, the bank may repossess that asset to recover its money, which reduces the lender's risk.","distractor_reasons":{"A":"Secured does not mean interest-free; most loans charge interest and security simply protects the lender. For a furniture importer, option D is correct: the lender can seize the warehouse if repayments are not made.","B":"A bank lending against a warehouse remains a creditor, not an owner. For a furniture importer, option D is correct: the lender can seize the warehouse if repayments are not made.","C":"A loan must be repaid under the agreed terms whether secured or not. For a furniture importer, option D is correct: the lender can seize the warehouse if repayments are not made.","D":"A secured loan gives the lender a legal claim on a specific asset, here the Kuala Lumpur importer's warehouse. If repayments are not made, the bank may repossess that asset to recover its money, which reduces the lender's risk."}}},{"id":"P1_U5_MCQ_1632","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1632","question":"A restaurant in Athens, Greece, made a healthy profit last month but still struggled to pay its bills. Which explanation is most likely for the restaurant?","options":{"A":"Profit and cash are identical, so this is impossible","B":"The restaurant had too few expenses","C":"Customers had not yet paid their invoices, so cash inflows lagged behind sales","D":"Its profit and loss account must be wrong"},"correctOption":"C","correctAnswer":"Customers had not yet paid their invoices, so cash inflows lagged behind sales","questionType":"MCQ","explanation":{"correct_reason":"Profit is recorded when sales are made, but cash arrives only when customers pay. If the Athens restaurant's customers settled invoices late, reported profit could be high while the bank balance stayed low, causing difficulty paying bills.","distractor_reasons":{"A":"Profit and cash flow are different measures, so a profitable firm can lack cash. For a restaurant, option C is correct: customers had not yet paid their invoices, so cash inflows lagged behind sales.","B":"Few expenses would raise profit further and would not explain an inability to pay bills. For a restaurant, option C is correct: customers had not yet paid their invoices, so cash inflows lagged behind sales.","C":"Profit is recorded when sales are made, but cash arrives only when customers pay. If the Athens restaurant's customers settled invoices late, reported profit could be high while the bank balance stayed low, causing difficulty paying bills.","D":"A profitable restaurant can still have cash problems, so the accounts need not be wrong. For a restaurant, option C is correct: customers had not yet paid their invoices, so cash inflows lagged behind sales."}}},{"id":"P1_U5_MCQ_1633","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1633","question":"A printing firm in Brno, Czech Republic, forecasts cash inflows of $83,000 and cash outflows of $71,400 for August. What is its forecast net cash flow for the month?","options":{"A":"$11,400","B":"$154,400","C":"$71,400","D":"$11,600"},"correctOption":"D","correctAnswer":"$11,600","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow equals cash inflows minus cash outflows. For the Brno printer that is $83,000 less $71,400, giving a positive net cash flow of $11,600, meaning the firm's cash balance should rise during August.","distractor_reasons":{"A":"This uses an incorrect outflow figure instead of $71,400 when subtracting from $83,000. For a printing firm, option D is correct: $11,600.","B":"This adds inflows and outflows together rather than subtracting outflows from inflows. Net cash flow measures the change in cash, so a total of both sides cannot be correct.","C":"This repeats the outflow figure and ignores the $83,000 of inflows. Net cash flow requires comparing the two, so this value does not answer the question.","D":"Net cash flow equals cash inflows minus cash outflows. For the Brno printer that is $83,000 less $71,400, giving a positive net cash flow of $11,600, meaning the firm's cash balance should rise during August."}}},{"id":"P1_U5_MCQ_1634","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1634","question":"A toy manufacturer in Hue, Vietnam, lists cash, inventories and amounts owed by customers in its accounts. How should these be classified in the statement of financial position?","options":{"A":"Non-current assets","B":"Current liabilities","C":"Current assets","D":"Equity"},"correctOption":"C","correctAnswer":"Current assets","questionType":"MCQ","explanation":{"correct_reason":"Cash, inventories and trade receivables are expected to be converted into cash or used within one year, so they are reported as current assets. They are resources owned by the Hue toy maker, not amounts it owes to other parties.","distractor_reasons":{"A":"Non-current assets are long-lived items such as machinery and buildings used over many years. For a toy manufacturer, option C is correct: current assets.","B":"Current liabilities are amounts the business owes within a year, such as payables. For a toy manufacturer, option C is correct: current assets.","C":"Cash, inventories and trade receivables are expected to be converted into cash or used within one year, so they are reported as current assets. They are resources owned by the Hue toy maker, not amounts it owes to other parties.","D":"Equity represents the owners' claim after deducting liabilities, not individual resources. For a toy manufacturer, option C is correct: current assets."}}},{"id":"P1_U5_MCQ_1635","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1635","question":"A valuer is examining the statement of financial position of a warehouse operator in Hamburg, Germany, and notes that its land was bought twenty years ago. What limitation of accounts does this highlight?","options":{"A":"Accounts always use current market values for all assets","B":"Land never appears in financial statements","C":"Historical cost means asset values may be out of date","D":"The business cannot own land"},"correctOption":"C","correctAnswer":"Historical cost means asset values may be out of date","questionType":"MCQ","explanation":{"correct_reason":"Traditional accounts record assets at historical purchase cost rather than current market value. Land bought twenty years ago by the Hamburg operator may be shown far below its present worth, limiting the statement's usefulness for decision-making.","distractor_reasons":{"A":"Accounts generally use historical cost, not current market value, for most non-current assets. For a valuer is examining the statement of financial position of a warehouse operator, option C is correct: historical cost means asset values may be out of date.","B":"Land is a non-current asset and normally appears in the statement of financial position. For a valuer is examining the statement of financial position of a warehouse operator, option C is correct: historical cost means asset values may be out of date.","C":"Traditional accounts record assets at historical purchase cost rather than current market value. Land bought twenty years ago by the Hamburg operator may be shown far below its present worth, limiting the statement's usefulness for decision-making.","D":"A business can own land, and many warehouse operators do. For a valuer is examining the statement of financial position of a warehouse operator, option C is correct: historical cost means asset values may be out of date."}}},{"id":"P1_U5_MCQ_1636","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1636","question":"A technology startup in Tel Aviv, Israel, seeks finance from investors who accept high risk in return for a share of ownership and future profits. What is this source of finance called?","options":{"A":"Government grant","B":"Bank overdraft","C":"Trade credit","D":"Venture capital"},"correctOption":"D","correctAnswer":"Venture capital","questionType":"MCQ","explanation":{"correct_reason":"Venture capital is equity finance supplied by investors who take a significant risk on a young business in exchange for an ownership stake and a share of future gains. It matches the Tel Aviv startup's search for risk-taking investors rather than lenders.","distractor_reasons":{"A":"A government grant usually gives no ownership stake or share of profits. For a technology startup, option D is correct: venture capital.","B":"A bank overdraft is short-term debt with interest and no ownership. For a technology startup, option D is correct: venture capital.","C":"Trade credit is an agreement with suppliers to pay later and provides no equity. For a technology startup, option D is correct: venture capital.","D":"Venture capital is equity finance supplied by investors who take a significant risk on a young business in exchange for an ownership stake and a share of future gains. It matches the Tel Aviv startup's search for risk-taking investors rather than lenders."}}},{"id":"P1_U5_MCQ_1637","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1637","question":"A cafe in Wellington, New Zealand, had an opening cash balance of $9,400 on 1 May. During May it received $45,000 and paid out $38,700. What was its closing cash balance on 31 May?","options":{"A":"$3,300","B":"$6,300","C":"$15,700","D":"$54,400"},"correctOption":"C","correctAnswer":"$15,700","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow for May is $45,000 receipts minus $38,700 payments, a net inflow of $6,300. Adding this to the $9,400 opening balance gives the Wellington cafe a closing cash balance of $15,700 on 31 May.","distractor_reasons":{"A":"This subtracts the $6,300 inflow from the opening balance instead of adding it. Receipts exceeded payments, so the Wellington cafe's cash must have increased.","B":"This is only the net cash inflow of $6,300 and forgets to add the $9,400 already held at the start of May, so it cannot be the closing balance.","C":"Net cash flow for May is $45,000 receipts minus $38,700 payments, a net inflow of $6,300. Adding this to the $9,400 opening balance gives the Wellington cafe a closing cash balance of $15,700 on 31 May.","D":"This adds $45,000 receipts to $9,400 but ignores the $38,700 of payments. For a cafe, option C is correct: $15,700."}}},{"id":"P1_U5_MCQ_1638","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1638","question":"A gift shop in Reykjavik, Iceland, reports gross profit of $74,000 and profit for the year of $19,000. What best explains the difference between these two figures?","options":{"A":"Gross profit always equals profit for the year","B":"Revenue was lower than cost of sales","C":"The shop must have made a gross loss","D":"Operating expenses, interest and tax were deducted after gross profit"},"correctOption":"D","correctAnswer":"Operating expenses, interest and tax were deducted after gross profit","questionType":"MCQ","explanation":{"correct_reason":"Gross profit of $74,000 is revenue less cost of sales, while profit for the year of $19,000 remains after operating expenses, interest and taxation are deducted. The $55,000 gap represents those further costs and charges for the Reykjavik shop.","distractor_reasons":{"A":"Gross profit and profit for the year are different measures with different deductions. For a gift shop, option D is correct: operating expenses, interest and tax were deducted after gross profit.","B":"If revenue were lower than cost of sales, the shop would report a gross loss, not positive gross profit of $74,000.","C":"Gross profit was positive at $74,000, so a gross loss is impossible. For a gift shop, option D is correct: operating expenses, interest and tax were deducted after gross profit.","D":"Gross profit of $74,000 is revenue less cost of sales, while profit for the year of $19,000 remains after operating expenses, interest and taxation are deducted. The $55,000 gap represents those further costs and charges for the Reykjavik shop."}}},{"id":"P1_U5_MCQ_1639","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1639","question":"A printing company in Turin, Italy, has delivered invoices to customers who have not yet paid. In the statement of financial position, what are these amounts called?","options":{"A":"Trade payables","B":"Non-current liabilities","C":"Trade receivables","D":"Retained earnings"},"correctOption":"C","correctAnswer":"Trade receivables","questionType":"MCQ","explanation":{"correct_reason":"Amounts owed to a business by its customers are called trade receivables and appear as current assets. The Turin printer has supplied goods but not yet received payment, so it holds a short-term claim on those customers.","distractor_reasons":{"A":"Trade payables are amounts the business owes to its own suppliers, which are liabilities. For a printing company, option C is correct: trade receivables.","B":"Non-current liabilities are long-term debts repayable after more than a year, not money expected from customers. For a printing company, option C is correct: trade receivables.","C":"Amounts owed to a business by its customers are called trade receivables and appear as current assets. The Turin printer has supplied goods but not yet received payment, so it holds a short-term claim on those customers.","D":"Retained earnings are profits kept in the business and part of equity, not amounts due from customers. For a printing company, option C is correct: trade receivables."}}},{"id":"P1_U5_MCQ_1640","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1640","question":"An analyst wants a stricter test of liquidity than the current ratio for a pharmacy chain in Ottawa, Canada. Which ratio removes stock from current assets?","options":{"A":"Gross profit margin","B":"Profit margin","C":"Return on capital employed","D":"Acid test ratio"},"correctOption":"D","correctAnswer":"Acid test ratio","questionType":"MCQ","explanation":{"correct_reason":"The acid test ratio excludes inventories from current assets before comparing them with current liabilities. It is a tougher liquidity measure for the Ottawa pharmacy chain because stock may take time to turn into cash.","distractor_reasons":{"A":"Gross profit margin measures profitability by comparing gross profit with revenue. For an analyst wants a stricter test of liquidity than the current ratio for a pharmacy chain, option D is correct: acid test ratio.","B":"Profit margin compares profit with revenue and assesses profitability, not liquidity. For an analyst wants a stricter test of liquidity than the current ratio for a pharmacy chain, option D is correct: acid test ratio.","C":"Return on capital employed relates operating profit to capital invested. For an analyst wants a stricter test of liquidity than the current ratio for a pharmacy chain, option D is correct: acid test ratio.","D":"The acid test ratio excludes inventories from current assets before comparing them with current liabilities. It is a tougher liquidity measure for the Ottawa pharmacy chain because stock may take time to turn into cash."}}},{"id":"P1_U5_MCQ_1641","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1641","question":"A cafe in Lisbon, Portugal, borrows $40,000 at 6% per year simple interest for one year. What total interest will it pay over that year?","options":{"A":"$400","B":"$24,000","C":"$2,400","D":"$42,400"},"correctOption":"C","correctAnswer":"$2,400","questionType":"MCQ","explanation":{"correct_reason":"Simple interest is the amount borrowed multiplied by the rate and the time. Six per cent of $40,000 for one year is $2,400, which is the total interest the Lisbon cafe will pay on the loan.","distractor_reasons":{"A":"This divides $40,000 by one hundred but fails to multiply by the six per cent rate. The correct interest is six per cent of $40,000, not one per cent.","B":"This treats six per cent as sixty per cent of $40,000, giving a figure ten times too large. For a cafe, option C is correct: $2,400.","C":"Simple interest is the amount borrowed multiplied by the rate and the time. Six per cent of $40,000 for one year is $2,400, which is the total interest the Lisbon cafe will pay on the loan.","D":"This adds the $2,400 interest to the $40,000 borrowed, giving the total amount repayable rather than the interest alone. The question asks only for the interest paid."}}},{"id":"P1_U5_MCQ_1642","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1642","question":"A pet grooming salon in Zurich, Switzerland, uses a cash flow forecast to plan its borrowing. Which benefit of forecasting is most relevant to the salon?","options":{"A":"It guarantees higher sales","B":"It replaces the need for a bank account","C":"It sets the salaries of employees","D":"It helps the salon anticipate when it will need to borrow and for how long"},"correctOption":"D","correctAnswer":"It helps the salon anticipate when it will need to borrow and for how long","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast projects future inflows and outflows, showing when the Zurich salon may run short of cash and for how long. That allows the owner to arrange borrowing in advance and negotiate better terms rather than facing an unexpected overdraft.","distractor_reasons":{"A":"A forecast records expected cash movements; it does not create sales or guarantee higher revenue. For a pet grooming salon, option D is correct: it helps the salon anticipate when it will need to borrow and for how long.","B":"A salon still needs a bank account to handle transactions. For a pet grooming salon, option D is correct: it helps the salon anticipate when it will need to borrow and for how long.","C":"Salary levels are decided by management and employment agreements, not by a forecast. For a pet grooming salon, option D is correct: it helps the salon anticipate when it will need to borrow and for how long.","D":"A cash flow forecast projects future inflows and outflows, showing when the Zurich salon may run short of cash and for how long. That allows the owner to arrange borrowing in advance and negotiate better terms rather than facing an unexpected overdraft."}}},{"id":"P1_U5_MCQ_1643","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1643","question":"A museum shop in Florence, Italy, recorded higher revenue this year but a lower profit. Which explanation is most plausible for the shop given its trading results?","options":{"A":"Revenue and profit always move together","B":"The shop must have sold fewer items","C":"Costs rose faster than revenue, reducing the profit margin","D":"Profit is calculated before revenue"},"correctOption":"C","correctAnswer":"Costs rose faster than revenue, reducing the profit margin","questionType":"MCQ","explanation":{"correct_reason":"Profit equals revenue minus costs, so if the Florence shop's costs increased more quickly than its sales income, profit can fall even while revenue rises. This explains how higher turnover can coincide with a lower profit figure.","distractor_reasons":{"A":"Revenue and profit do not always move together because costs can change independently. For a museum shop, option C is correct: costs rose faster than revenue, reducing the profit margin.","B":"Higher revenue could come from higher prices, so fewer sales need not be the cause. For a museum shop, option C is correct: costs rose faster than revenue, reducing the profit margin.","C":"Profit equals revenue minus costs, so if the Florence shop's costs increased more quickly than its sales income, profit can fall even while revenue rises. This explains how higher turnover can coincide with a lower profit figure.","D":"Profit is calculated after subtracting costs from revenue, not before. For a museum shop, option C is correct: costs rose faster than revenue, reducing the profit margin."}}},{"id":"P1_U5_MCQ_1644","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1644","question":"A dairy farm in Christchurch, New Zealand, is preparing a statement of financial position. Which equation correctly links its assets, liabilities and owner's equity at the reporting date?","options":{"A":"Assets + Liabilities = Equity","B":"Assets = Equity minus Liabilities","C":"Liabilities minus Assets = Equity","D":"Assets minus Liabilities = Equity"},"correctOption":"D","correctAnswer":"Assets minus Liabilities = Equity","questionType":"MCQ","explanation":{"correct_reason":"The accounting equation states that assets equal liabilities plus equity. Rearranged, assets minus liabilities equals owner's equity, which represents the net assets of the Christchurch dairy farm after all obligations have been deducted.","distractor_reasons":{"A":"Adding liabilities to assets would overstate the owner's claim, since liabilities are deducted from assets. For a dairy farm, option D is correct: assets minus Liabilities = Equity.","B":"This rearrangement is incorrect: subtracting liabilities from equity does not give assets. For a dairy farm, option D is correct: assets minus Liabilities = Equity.","C":"Subtracting assets from liabilities would normally give a negative figure for a solvent farm. For a dairy farm, option D is correct: assets minus Liabilities = Equity.","D":"The accounting equation states that assets equal liabilities plus equity. Rearranged, assets minus liabilities equals owner's equity, which represents the net assets of the Christchurch dairy farm after all obligations have been deducted."}}},{"id":"P1_U5_MCQ_1645","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1645","question":"A firm in Malmo, Sweden, has current assets of $280,000, inventories of $80,000 and current liabilities of $100,000. What is its acid test ratio, to one decimal place?","options":{"A":"2.8 : 1","B":"0.5 : 1","C":"2.0 : 1","D":"1.8 : 1"},"correctOption":"C","correctAnswer":"2.0 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test ratio excludes inventories, so $280,000 of current assets less $80,000 of stock gives $200,000. Dividing $200,000 by $100,000 of current liabilities produces an acid test ratio of 2.0 : 1 for the Malmo firm.","distractor_reasons":{"A":"This divides the full $280,000 of current assets by $100,000, which is the current ratio. The acid test removes the $80,000 of inventories first, so this figure is too high.","B":"This inverts the relationship, dividing $100,000 of liabilities by $200,000 of liquid assets. The acid test compares liquid assets with liabilities in that order.","C":"The acid test ratio excludes inventories, so $280,000 of current assets less $80,000 of stock gives $200,000. Dividing $200,000 by $100,000 of current liabilities produces an acid test ratio of 2.0 : 1 for the Malmo firm.","D":"This subtracts $100,000 instead of the $80,000 of inventories from current assets before dividing. For a firm, option C is correct: 2.0 : 1."}}},{"id":"P1_U5_MCQ_1646","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1646","question":"A chemical company in Ludwigshafen, Germany, raises long-term finance by issuing a document that promises fixed interest and repayment on a set date. What is this instrument called?","options":{"A":"Ordinary share","B":"Trade credit","C":"Overdraft","D":"Debenture"},"correctOption":"D","correctAnswer":"Debenture","questionType":"MCQ","explanation":{"correct_reason":"A debenture is a long-term debt instrument issued by a company, usually promising fixed interest payments and repayment of the principal at a stated date. It suits the Ludwigshafen company's need for long-term borrowing without selling ownership.","distractor_reasons":{"A":"An ordinary share represents ownership and dividends that are not fixed or guaranteed. For a chemical company, option D is correct: debenture.","B":"Trade credit is a supplier's agreement to wait for payment of goods. For a chemical company, option D is correct: debenture.","C":"An overdraft is a flexible short-term facility repaid repeatedly. For a chemical company, option D is correct: debenture. That is the conclusion the information in the question supports.","D":"A debenture is a long-term debt instrument issued by a company, usually promising fixed interest payments and repayment of the principal at a stated date. It suits the Ludwigshafen company's need for long-term borrowing without selling ownership."}}},{"id":"P1_U5_MCQ_1647","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1647","question":"A car dealership in Bologna, Italy, allows customers 60 days to pay. When preparing its cash flow forecast, what should the dealership do about those sales?","options":{"A":"Record all sales as cash received in the month of sale","B":"Ignore credit sales completely","C":"Show the cash from those sales two months after the sale","D":"Treat the sales as payments"},"correctOption":"C","correctAnswer":"Show the cash from those sales two months after the sale","questionType":"MCQ","explanation":{"correct_reason":"Because customers pay after 60 days, the Bologna dealership should record the cash inflow in the month the money is actually received, roughly two months after the sale. Cash flow forecasts follow cash timing, not the date of the sale.","distractor_reasons":{"A":"Recording sales as cash in the month of sale assumes customers pay immediately, contradicting the 60-day terms. For a car dealership, option C is correct: show the cash from those sales two months after the sale.","B":"Credit sales still generate cash eventually and cannot be ignored. For a car dealership, option C is correct: show the cash from those sales two months after the sale.","C":"Because customers pay after 60 days, the Bologna dealership should record the cash inflow in the month the money is actually received, roughly two months after the sale. Cash flow forecasts follow cash timing, not the date of the sale.","D":"Sales bring money into the business, so they are receipts, not payments. For a car dealership, option C is correct: show the cash from those sales two months after the sale."}}},{"id":"P1_U5_MCQ_1648","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1648","question":"A hotel in Bangkok, Thailand, is reviewing costs that appear as operating expenses in its profit and loss account. Which item belongs in that category?","options":{"A":"Cost of food bought for guests' meals","B":"Interest on a bank loan","C":"Salary of the hotel manager","D":"Taxation paid to the government"},"correctOption":"C","correctAnswer":"Salary of the hotel manager","questionType":"MCQ","explanation":{"correct_reason":"The hotel manager's salary is an operating expense, a cost of running the business deducted from gross profit to reach operating profit. Interest and taxation appear later, while food for guests is a direct cost of sales.","distractor_reasons":{"A":"Food purchased for guests is a direct cost of the hotel's service, so it forms part of cost of sales.","B":"Interest on a bank loan is a finance cost charged after operating profit. For a hotel, option C is correct: salary of the hotel manager.","C":"The hotel manager's salary is an operating expense, a cost of running the business deducted from gross profit to reach operating profit. Interest and taxation appear later, while food for guests is a direct cost of sales.","D":"Taxation is charged on profit near the end of the profit and loss account, not as an operating expense. For a hotel, option C is correct: salary of the hotel manager."}}},{"id":"P1_U5_MCQ_1649","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1649","question":"A firm in Bilbao, Spain, has inventories of $95,000, trade receivables of $60,000, cash of $25,000 and current liabilities of $120,000. What is its working capital?","options":{"A":"$55,000","B":"$180,000","C":"$300,000","D":"$60,000"},"correctOption":"D","correctAnswer":"$60,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities. The Bilbao firm's current assets total $95,000 plus $60,000 plus $25,000, which is $180,000. Subtracting $120,000 of current liabilities leaves working capital of $60,000.","distractor_reasons":{"A":"This mishandles the $25,000 cash and the liabilities. For a firm, option D is correct: $60,000. That is the conclusion the information in the question supports.","B":"This is the total of the three current assets but ignores the $120,000 owed in the short term. Working capital is the net figure after deducting current liabilities.","C":"This adds current assets of $180,000 to current liabilities of $120,000. Working capital requires subtraction, not addition, so this total is incorrect.","D":"Working capital is current assets minus current liabilities. The Bilbao firm's current assets total $95,000 plus $60,000 plus $25,000, which is $180,000. Subtracting $120,000 of current liabilities leaves working capital of $60,000."}}},{"id":"P1_U5_MCQ_1650","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1650","question":"A financial adviser is assessing a company in Munich, Germany, that reports rising profits but a falling share price. Which concern might the adviser reasonably raise?","options":{"A":"Rising profits always raise the share price immediately","B":"The market may doubt the quality or sustainability of those profits","C":"Share prices are unrelated to company performance","D":"The company must have no liabilities"},"correctOption":"B","correctAnswer":"The market may doubt the quality or sustainability of those profits","questionType":"MCQ","explanation":{"correct_reason":"A falling share price despite rising reported profits may signal that investors question the quality of earnings, perhaps because they rely on one-off sales or the company is risky. The Munich adviser should investigate sustainability rather than assume profits guarantee value.","distractor_reasons":{"A":"Share prices do not always respond immediately to reported profits; expectations and market conditions matter. For a financial adviser is assessing a company, option B is correct: the market may doubt the quality or sustainability of those profits.","B":"A falling share price despite rising reported profits may signal that investors question the quality of earnings, perhaps because they rely on one-off sales or the company is risky. The Munich adviser should investigate sustainability rather than assume profits guarantee value.","C":"Share prices are influenced by company performance among other factors, so claiming no relationship is too strong. For a financial adviser is assessing a company, option B is correct: the market may doubt the quality or sustainability of those profits.","D":"A company with rising profits can still have liabilities, and most businesses do. For a financial adviser is assessing a company, option B is correct: the market may doubt the quality or sustainability of those profits."}}},{"id":"P1_U5_MCQ_1651","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1651","question":"A recycling plant in Lille, France, receives a payment from the regional government to install new equipment, with no obligation to repay it. What is this source of finance?","options":{"A":"A loan","B":"A grant","C":"A debenture","D":"Trade credit"},"correctOption":"B","correctAnswer":"A grant","questionType":"MCQ","explanation":{"correct_reason":"A grant is funding received from a government or other body that does not have to be repaid and usually gives the provider no ownership. The Lille recycling plant's regional payment is therefore grant finance rather than debt or equity.","distractor_reasons":{"A":"A loan must be repaid, typically with interest, whereas the Lille plant has no obligation to return the money. For a recycling plant, option B is correct: a grant.","B":"A grant is funding received from a government or other body that does not have to be repaid and usually gives the provider no ownership. The Lille recycling plant's regional payment is therefore grant finance rather than debt or equity.","C":"A debenture is long-term debt with fixed interest and a repayment date. For a recycling plant, option B is correct: a grant.","D":"Trade credit arises when suppliers allow delayed payment for goods. For a recycling plant, option B is correct: a grant."}}},{"id":"P1_U5_MCQ_1652","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1652","question":"A bookstore in Edinburgh, United Kingdom, prepares a monthly cash forecast and sees that its balance stays positive all year. What can the owner conclude?","options":{"A":"The business will never need finance again","B":"Its forecast suggests adequate liquidity, assuming the estimates prove accurate","C":"The business has no operating costs","D":"Profits must be falling"},"correctOption":"B","correctAnswer":"Its forecast suggests adequate liquidity, assuming the estimates prove accurate","questionType":"MCQ","explanation":{"correct_reason":"A forecast showing positive cash balances suggests the Edinburgh bookstore expects enough inflows to cover outflows, provided the estimates are realistic. It indicates likely liquidity, not certainty about future finance needs or profit.","distractor_reasons":{"A":"One year's forecast cannot guarantee the business will never need finance; conditions change and forecasts can be wrong. For a bookstore, option B is correct: its forecast suggests adequate liquidity, assuming the estimates prove accurate.","B":"A forecast showing positive cash balances suggests the Edinburgh bookstore expects enough inflows to cover outflows, provided the estimates are realistic. It indicates likely liquidity, not certainty about future finance needs or profit.","C":"A bookstore plainly has costs such as rent and stock. For a bookstore, option B is correct: its forecast suggests adequate liquidity, assuming the estimates prove accurate.","D":"A healthy cash balance gives no indication that profits are falling. For a bookstore, option B is correct: its forecast suggests adequate liquidity, assuming the estimates prove accurate."}}},{"id":"P1_U5_MCQ_1653","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1653","question":"A bakery in Madeira, Portugal, has gross profit of $120,000, operating expenses of $68,000 and interest of $7,000. What is its operating profit for the year?","options":{"A":"$45,000","B":"$52,000","C":"$120,000","D":"$68,000"},"correctOption":"B","correctAnswer":"$52,000","questionType":"MCQ","explanation":{"correct_reason":"Operating profit is gross profit less operating expenses, so $120,000 minus $68,000 equals $52,000 for the Madeira bakery. The $7,000 of interest is a finance cost deducted later, so it does not affect operating profit.","distractor_reasons":{"A":"This subtracts the $7,000 interest as well as the $68,000 expenses from gross profit. Interest is charged after operating profit, so this result is too low.","B":"Operating profit is gross profit less operating expenses, so $120,000 minus $68,000 equals $52,000 for the Madeira bakery. The $7,000 of interest is a finance cost deducted later, so it does not affect operating profit.","C":"This repeats gross profit and ignores the $68,000 operating expenses. For a bakery, option B is correct: $52,000. That is the conclusion the information in the question supports.","D":"This repeats the operating expenses rather than calculating profit. Operating profit is what remains after those expenses are taken from gross profit."}}},{"id":"P1_U5_MCQ_1654","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1654","question":"An analyst examining a factory in Bratislava, Slovakia, wants to identify the capital employed. Which of the following best describes it in this context for that business?","options":{"A":"The value of current assets only","B":"Non-current assets plus working capital","C":"Total sales revenue","D":"The amount owed to trade payables"},"correctOption":"B","correctAnswer":"Non-current assets plus working capital","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is the long-term funds invested in a business, commonly measured as non-current assets plus working capital, or total assets minus current liabilities. For the Bratislava factory it is the base against which returns are judged.","distractor_reasons":{"A":"Current assets alone ignore long-lived assets such as the factory building. For an analyst examining a factory, option B is correct: non-current assets plus working capital.","B":"Capital employed is the long-term funds invested in a business, commonly measured as non-current assets plus working capital, or total assets minus current liabilities. For the Bratislava factory it is the base against which returns are judged.","C":"Sales revenue is a flow over a period, not the capital invested at a point in time. For an analyst examining a factory, option B is correct: non-current assets plus working capital.","D":"Trade payables are short-term liabilities, not long-term invested funds. For an analyst examining a factory, option B is correct: non-current assets plus working capital."}}},{"id":"P1_U5_MCQ_1655","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1655","question":"A trade union representative wants to examine the accounts of a supermarket chain in Oslo, Norway, before wage negotiations. Which question are those accounts best able to answer?","options":{"A":"Whether the staff are happy at work","B":"Whether the company can afford higher wages","C":"What its competitors' market share is","D":"How many staff will be recruited next year"},"correctOption":"B","correctAnswer":"Whether the company can afford higher wages","questionType":"MCQ","explanation":{"correct_reason":"Published accounts show the Oslo supermarket chain's profitability and cash position, helping a union judge whether higher wage claims are affordable. They do not directly measure staff morale, competitors' market share or future recruitment plans.","distractor_reasons":{"A":"Accounts contain financial figures, not measures of employee satisfaction. For a trade union representative wants to examine the accounts of a supermarket chain, option B is correct: whether the company can afford higher wages.","B":"Published accounts show the Oslo supermarket chain's profitability and cash position, helping a union judge whether higher wage claims are affordable. They do not directly measure staff morale, competitors' market share or future recruitment plans.","C":"A company's own accounts do not reveal rivals' market share, which needs external market data. For a trade union representative wants to examine the accounts of a supermarket chain, option B is correct: whether the company can afford higher wages.","D":"Future recruitment plans are management decisions not normally in financial statements. For a trade union representative wants to examine the accounts of a supermarket chain, option B is correct: whether the company can afford higher wages."}}},{"id":"P1_U5_MCQ_1656","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1656","question":"A fashion retailer in Milan, Italy, is considering a new issue of ordinary shares to raise expansion capital. Which disadvantage of this source should the directors consider?","options":{"A":"The money must be repaid at a fixed date","B":"Existing shareholders' ownership may be diluted","C":"Interest payments must be made each month","D":"The retailer must sell its store buildings"},"correctOption":"B","correctAnswer":"Existing shareholders' ownership may be diluted","questionType":"MCQ","explanation":{"correct_reason":"Issuing new ordinary shares gives investors a claim on the business, so existing shareholders may find their percentage ownership and control reduced, a process called dilution. Unlike debt, share capital need not be repaid and carries no compulsory interest.","distractor_reasons":{"A":"Share capital is equity and does not have to be repaid at a fixed date. For a fashion retailer, option B is correct: existing shareholders' ownership may be diluted.","B":"Issuing new ordinary shares gives investors a claim on the business, so existing shareholders may find their percentage ownership and control reduced, a process called dilution. Unlike debt, share capital need not be repaid and carries no compulsory interest.","C":"Dividends on shares are not compulsory fixed monthly payments. For a fashion retailer, option B is correct: existing shareholders' ownership may be diluted.","D":"Issuing shares does not force the retailer to sell its buildings. For a fashion retailer, option B is correct: existing shareholders' ownership may be diluted."}}},{"id":"P1_U5_MCQ_1657","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1657","question":"A bookstore in Cork, Ireland, had an opening cash balance of $6,200 on 1 June. During June it received $33,000 and paid out $29,500. What was its closing cash balance on 30 June?","options":{"A":"$9,700","B":"$3,500","C":"$2,700","D":"$39,200"},"correctOption":"A","correctAnswer":"$9,700","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow for June is $33,000 receipts minus $29,500 payments, a net inflow of $3,500. Adding this to the $6,200 opening balance gives the Cork bookstore a closing cash balance of $9,700 on 30 June.","distractor_reasons":{"A":"Net cash flow for June is $33,000 receipts minus $29,500 payments, a net inflow of $3,500. Adding this to the $6,200 opening balance gives the Cork bookstore a closing cash balance of $9,700 on 30 June.","B":"This is only the net cash inflow of $3,500 and omits the $6,200 already held at the start of June, so it cannot be the closing balance.","C":"This subtracts the net inflow from the opening balance instead of adding it. For a bookstore, option A is correct: $9,700.","D":"This adds $33,000 receipts to $6,200 but ignores the $29,500 of payments. For a bookstore, option A is correct: $9,700."}}},{"id":"P1_U5_MCQ_1658","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1658","question":"A furniture maker in Krakow, Poland, wants to calculate gross profit for the year. Which pair of figures does it need from its accounts to perform that calculation?","options":{"A":"Revenue and operating expenses","B":"Revenue and cost of sales","C":"Operating profit and taxation","D":"Cash receipts and cash payments"},"correctOption":"B","correctAnswer":"Revenue and cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is calculated as revenue minus cost of sales, so the Krakow furniture maker needs those two figures. Operating expenses, interest and tax are deducted later to arrive at operating profit and profit for the year.","distractor_reasons":{"A":"Operating expenses are deducted after gross profit, so revenue and expenses do not produce gross profit. For a furniture maker, option B is correct: revenue and cost of sales.","B":"Gross profit is calculated as revenue minus cost of sales, so the Krakow furniture maker needs those two figures. Operating expenses, interest and tax are deducted later to arrive at operating profit and profit for the year.","C":"Operating profit and taxation are later items in the profit and loss account, not the inputs to gross profit. For a furniture maker, option B is correct: revenue and cost of sales.","D":"Cash receipts and payments relate to a cash flow forecast rather than the profit and loss account. For a furniture maker, option B is correct: revenue and cost of sales."}}},{"id":"P1_U5_MCQ_1659","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1659","question":"A caterer in Lyon, France, has not yet paid for groceries delivered last week. In the statement of financial position, what is this amount called?","options":{"A":"Trade receivable","B":"Trade payable","C":"Non-current asset","D":"Retained earnings"},"correctOption":"B","correctAnswer":"Trade payable","questionType":"MCQ","explanation":{"correct_reason":"Amounts a business owes to suppliers for goods received are called trade payables and appear as current liabilities. The Lyon caterer has received groceries but not yet paid, so it holds a short-term obligation to the supplier.","distractor_reasons":{"A":"A trade receivable is money owed to the business by customers, the opposite of this situation. For a caterer, option B is correct: trade payable.","B":"Amounts a business owes to suppliers for goods received are called trade payables and appear as current liabilities. The Lyon caterer has received groceries but not yet paid, so it holds a short-term obligation to the supplier.","C":"A non-current asset is a long-lived resource owned by the business, not an unpaid grocery bill. For a caterer, option B is correct: trade payable.","D":"Retained earnings are profits kept in the business and part of equity, not an unpaid supplier invoice. For a caterer, option B is correct: trade payable."}}},{"id":"P1_U5_MCQ_1660","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1660","question":"A builder's merchant in Leeds, United Kingdom, has a current ratio of 1.2 : 1. What does this most likely indicate about its short-term financial position?","options":{"A":"It has $1.20 of current assets for every $1 of current liabilities","B":"It has no current liabilities","C":"Its long-term debts are very low","D":"It is certain to go bankrupt"},"correctOption":"A","correctAnswer":"It has $1.20 of current assets for every $1 of current liabilities","questionType":"MCQ","explanation":{"correct_reason":"A current ratio of 1.2 : 1 means current assets are 1.2 times current liabilities, so the Leeds merchant holds $1.20 of short-term assets per dollar of short-term debt. This suggests a modest margin of safety, though asset quality also matters.","distractor_reasons":{"A":"A current ratio of 1.2 : 1 means current assets are 1.2 times current liabilities, so the Leeds merchant holds $1.20 of short-term assets per dollar of short-term debt. This suggests a modest margin of safety, though asset quality also matters.","B":"A ratio of 1.2 : 1 compares two figures, so current liabilities cannot be zero. For a builder's merchant, option A is correct: it has $1.20 of current assets for every $1 of current liabilities.","C":"The current ratio uses only current assets and liabilities and says nothing about long-term debt. For a builder's merchant, option A is correct: it has $1.20 of current assets for every $1 of current liabilities.","D":"A ratio above 1 : 1 means current assets exceed current liabilities, not imminent bankruptcy. For a builder's merchant, option A is correct: it has $1.20 of current assets for every $1 of current liabilities."}}},{"id":"P1_U5_MCQ_1661","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1661","question":"A bakery in Faro, Portugal, takes a $25,000 loan at 8% simple interest for two years. What is the total interest paid over the two years?","options":{"A":"$2,000","B":"$4,000","C":"$29,000","D":"$8,000"},"correctOption":"B","correctAnswer":"$4,000","questionType":"MCQ","explanation":{"correct_reason":"Simple interest equals principal times rate times time. Eight per cent of $25,000 is $2,000 for one year, and over two years the Faro bakery pays twice that, giving total interest of $4,000.","distractor_reasons":{"A":"This is the interest for just one year. Because the Faro loan runs for two years, the total interest is twice this amount, so the figure is incomplete.","B":"Simple interest equals principal times rate times time. Eight per cent of $25,000 is $2,000 for one year, and over two years the Faro bakery pays twice that, giving total interest of $4,000.","C":"This adds two years of interest to the principal and gives the total amount repayable, not the interest alone. The question asks specifically for interest paid.","D":"This treats eight per cent of $25,000 as $8,000, which is far too large. For a bakery, option B is correct: $4,000."}}},{"id":"P1_U5_MCQ_1662","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1662","question":"A bus operator in Cork, Ireland, sells an old bus for cash. How should this transaction appear in the cash flow forecast for next month?","options":{"A":"As a cash inflow in the month the sale proceeds are received","B":"As an operating expense","C":"As a current liability","D":"It should be omitted from the forecast"},"correctOption":"A","correctAnswer":"As a cash inflow in the month the sale proceeds are received","questionType":"MCQ","explanation":{"correct_reason":"Selling an old bus brings cash into the Cork operator's bank account, so the proceeds are recorded as a cash inflow, specifically from the sale of a non-current asset, in the month the money is received.","distractor_reasons":{"A":"Selling an old bus brings cash into the Cork operator's bank account, so the proceeds are recorded as a cash inflow, specifically from the sale of a non-current asset, in the month the money is received.","B":"An operating expense is a payment, whereas selling a bus generates cash. For a bus operator, option A is correct: as a cash inflow in the month the sale proceeds are received.","C":"A current liability is an amount owed to someone else, not cash received. For a bus operator, option A is correct: as a cash inflow in the month the sale proceeds are received.","D":"The sale should not be omitted because it affects the cash balance. For a bus operator, option A is correct: as a cash inflow in the month the sale proceeds are received."}}},{"id":"P1_U5_MCQ_1663","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1663","question":"A stationery firm in Plovdiv, Bulgaria, writes off a debt owed by a customer who has gone out of business. What is the effect on its profit for the year?","options":{"A":"Profit increases by the amount written off","B":"Profit decreases because the expected income is not received","C":"Profit is unaffected by bad debts","D":"Gross profit rises automatically"},"correctOption":"B","correctAnswer":"Profit decreases because the expected income is not received","questionType":"MCQ","explanation":{"correct_reason":"When a debt is written off, the firm acknowledges the receivable will not be collected, so the sale previously counted must be treated as lost income. This reduces the Plovdiv stationery firm's profit for the year.","distractor_reasons":{"A":"Writing off a debt does not create income; it removes an asset and reduces profit. For a stationery firm, option B is correct: profit decreases because the expected income is not received.","B":"When a debt is written off, the firm acknowledges the receivable will not be collected, so the sale previously counted must be treated as lost income. This reduces the Plovdiv stationery firm's profit for the year.","C":"Bad debts do affect profit because expected revenue is never received. For a stationery firm, option B is correct: profit decreases because the expected income is not received.","D":"An uncollected debt cannot improve gross profit or the overall result. For a stationery firm, option B is correct: profit decreases because the expected income is not received."}}},{"id":"P1_U5_MCQ_1664","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1664","question":"A hotel in Split, Croatia, spends money on both replacing a worn roof and buying cleaning supplies. Which item is capital expenditure in its accounts?","options":{"A":"Buying cleaning supplies","B":"Replacing the roof","C":"Paying weekly wages","D":"Paying the electricity bill"},"correctOption":"B","correctAnswer":"Replacing the roof","questionType":"MCQ","explanation":{"correct_reason":"Capital expenditure is spending on a long-lived asset that benefits the business over several years, such as replacing the Split hotel's roof. Cleaning supplies, wages and electricity are revenue expenditures used up in the current period.","distractor_reasons":{"A":"Cleaning supplies are consumed quickly in day-to-day operations, so they are revenue expenditure. For a hotel, option B is correct: replacing the roof.","B":"Capital expenditure is spending on a long-lived asset that benefits the business over several years, such as replacing the Split hotel's roof. Cleaning supplies, wages and electricity are revenue expenditures used up in the current period.","C":"Wages are a recurring operating cost used up as work is performed, not a long-term asset. For a hotel, option B is correct: replacing the roof.","D":"Electricity is a utility consumed during the period, so it is revenue expenditure. For a hotel, option B is correct: replacing the roof."}}},{"id":"P1_U5_MCQ_1665","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1665","question":"A company in Graz, Austria, has revenue of $500,000 and operating profit of $65,000. What is its profit margin, to one decimal place, for the year?","options":{"A":"13.0%","B":"7.7%","C":"65.0%","D":"87.0%"},"correctOption":"A","correctAnswer":"13.0%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is operating profit divided by revenue, multiplied by one hundred. For the Graz company that is $65,000 divided by $500,000, which equals 0.13 or a profit margin of 13.0 per cent.","distractor_reasons":{"A":"Profit margin is operating profit divided by revenue, multiplied by one hundred. For the Graz company that is $65,000 divided by $500,000, which equals 0.13 or a profit margin of 13.0 per cent.","B":"This inverts the calculation, dividing $500,000 into $65,000 rather than expressing profit as a percentage of revenue. For a company, option A is correct: 13.0%.","C":"This treats the $65,000 profit as a percentage without comparing it with $500,000 revenue. For a company, option A is correct: 13.0%.","D":"This expresses costs as a share of revenue, not profit. For a company, option A is correct: 13.0%. That is the conclusion the information in the question supports."}}},{"id":"P1_U5_MCQ_1666","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1666","question":"A family business in Seville, Spain, uses retained profit to buy new machinery instead of borrowing. Which opportunity cost should the owners consider in this decision?","options":{"A":"The interest the money could have earned if invested elsewhere","B":"The tax the firm will pay next year","C":"The wages paid to machine operators","D":"The price of the machinery itself"},"correctOption":"A","correctAnswer":"The interest the money could have earned if invested elsewhere","questionType":"MCQ","explanation":{"correct_reason":"Using retained profit ties up funds that could otherwise have been invested or deposited to earn interest. That foregone return is the opportunity cost for the Seville business and should be weighed against the benefit of avoiding loan interest.","distractor_reasons":{"A":"Using retained profit ties up funds that could otherwise have been invested or deposited to earn interest. That foregone return is the opportunity cost for the Seville business and should be weighed against the benefit of avoiding loan interest.","B":"Future tax depends on profits and tax rules, not directly on how the machinery is financed. For a family business, option A is correct: the interest the money could have earned if invested elsewhere.","C":"Operators' wages arise from installing the machinery under either financing method. For a family business, option A is correct: the interest the money could have earned if invested elsewhere.","D":"The price of the machinery is the same however it is financed, so it is not an opportunity cost of using retained earnings."}}},{"id":"P1_U5_MCQ_1667","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1667","question":"A market stall in Marrakesh, Morocco, must pay its supplier in advance but receives cash from customers only after each sale. What does this pattern create?","options":{"A":"A guaranteed profit","B":"A working-capital gap that may require short-term finance","C":"A current liability that never arises","D":"A fall in recorded revenue"},"correctOption":"B","correctAnswer":"A working-capital gap that may require short-term finance","questionType":"MCQ","explanation":{"correct_reason":"Paying the supplier before receiving sales cash means the stall funds stock in advance, creating a gap between outflows and inflows. The Marrakesh trader may need short-term finance, such as an overdraft, to bridge that working-capital gap.","distractor_reasons":{"A":"This pattern does not guarantee a profit, which depends on selling price versus cost. For a market stall, option B is correct: a working-capital gap that may require short-term finance.","B":"Paying the supplier before receiving sales cash means the stall funds stock in advance, creating a gap between outflows and inflows. The Marrakesh trader may need short-term finance, such as an overdraft, to bridge that working-capital gap.","C":"Paying in advance creates outflows, and other obligations may still arise. For a market stall, option B is correct: a working-capital gap that may require short-term finance.","D":"Revenue is earned from sales and is not reduced by paying a supplier earlier. For a market stall, option B is correct: a working-capital gap that may require short-term finance."}}},{"id":"P1_U5_MCQ_1668","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1668","question":"A cleaning company in Dublin, Ireland, reports higher profit than net cash inflow this year. Which explanation is plausible for the company given these reported figures?","options":{"A":"It paid suppliers and staff before collecting money from customers","B":"It sold no services at all","C":"Its costs were higher than its revenue","D":"It made a loss for the year"},"correctOption":"A","correctAnswer":"It paid suppliers and staff before collecting money from customers","questionType":"MCQ","explanation":{"correct_reason":"If the Dublin cleaning company paid wages and suppliers promptly but customers paid late, costs would be recorded and paid before the related cash arrived. Profit could therefore be positive while net cash inflow remained lower.","distractor_reasons":{"A":"If the Dublin cleaning company paid wages and suppliers promptly but customers paid late, costs would be recorded and paid before the related cash arrived. Profit could therefore be positive while net cash inflow remained lower.","B":"Selling no services would mean zero revenue and a loss, not higher profit. For a cleaning company, option A is correct: it paid suppliers and staff before collecting money from customers.","C":"Costs exceeding revenue would produce a loss, not the higher profit mentioned. For a cleaning company, option A is correct: it paid suppliers and staff before collecting money from customers.","D":"A loss is the opposite of the reported higher profit. For a cleaning company, option A is correct: it paid suppliers and staff before collecting money from customers."}}},{"id":"P1_U5_MCQ_1669","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1669","question":"A firm in Lyon, France, has current assets of $275,000 and current liabilities of $125,000. What is its working capital? Give your answer in dollars.","options":{"A":"$150,000","B":"$400,000","C":"$275,000","D":"$125,000"},"correctOption":"A","correctAnswer":"$150,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities. The Lyon firm's $275,000 of current assets less $125,000 of current liabilities equals $150,000, the net short-term funding available for its operations.","distractor_reasons":{"A":"Working capital is current assets minus current liabilities. The Lyon firm's $275,000 of current assets less $125,000 of current liabilities equals $150,000, the net short-term funding available for its operations.","B":"This adds current assets and current liabilities instead of subtracting them. For a firm, option A is correct: $150,000. That is the conclusion the information in the question supports.","C":"This repeats current assets and ignores the $125,000 owed in the short term. For a firm, option A is correct: $150,000.","D":"This repeats current liabilities without comparing them with the $275,000 of current assets. For a firm, option A is correct: $150,000."}}},{"id":"P1_U5_MCQ_1670","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1670","question":"A retail chain in Gothenburg, Sweden, sees its gross profit margin fall from 42% to 35% over two years. Which interpretation is most defensible from the figures?","options":{"A":"The chain's sales must have fallen","B":"Cost of sales is taking a larger share of revenue","C":"The chain has no operating expenses","D":"Profit for the year must have risen"},"correctOption":"B","correctAnswer":"Cost of sales is taking a larger share of revenue","questionType":"MCQ","explanation":{"correct_reason":"A falling gross profit margin means gross profit is a smaller percentage of revenue, implying cost of sales has risen relative to sales. The Gothenburg chain may face higher purchase costs or have cut prices, but the cost share increased.","distractor_reasons":{"A":"A margin is a percentage, so it can fall even if sales rise, provided costs rise faster. For a retail chain, option B is correct: cost of sales is taking a larger share of revenue.","B":"A falling gross profit margin means gross profit is a smaller percentage of revenue, implying cost of sales has risen relative to sales. The Gothenburg chain may face higher purchase costs or have cut prices, but the cost share increased.","C":"Operating expenses are deducted after gross profit and are not part of this margin. For a retail chain, option B is correct: cost of sales is taking a larger share of revenue.","D":"A lower gross margin need not raise profit for the year; it may reduce it. For a retail chain, option B is correct: cost of sales is taking a larger share of revenue."}}},{"id":"P1_U5_MCQ_1671","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1671","question":"A delivery firm in Antwerp, Belgium, needs vans but does not want to buy them outright. It rents them for fixed monthly payments with an option to purchase later. What is this called?","options":{"A":"Leasing","B":"Franchising","C":"Hire purchase only","D":"Overdraft"},"correctOption":"A","correctAnswer":"Leasing","questionType":"MCQ","explanation":{"correct_reason":"Leasing allows a business to use an asset such as a van while paying regular rentals, often with an option to buy at the end. The Antwerp delivery firm avoids a large upfront cost, though total lease payments may exceed the purchase price.","distractor_reasons":{"A":"Leasing allows a business to use an asset such as a van while paying regular rentals, often with an option to buy at the end. The Antwerp delivery firm avoids a large upfront cost, though total lease payments may exceed the purchase price.","B":"Franchising involves paying to trade under another business's brand and receiving support. For a delivery firm, option A is correct: leasing.","C":"Hire purchase transfers ownership after instalments, unlike a lease with continued rental. For a delivery firm, option A is correct: leasing.","D":"An overdraft is a short-term bank facility for day-to-day cash, not a way to obtain vans. For a delivery firm, option A is correct: leasing."}}},{"id":"P1_U5_MCQ_1672","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1672","question":"A cinema in Oslo, Norway, is listing next month's cash outflows. Which item should appear in that part of the forecast prepared by the cinema for next month?","options":{"A":"Ticket sales to customers","B":"Payment of staff wages","C":"Money borrowed from the bank","D":"Sale of old projector equipment"},"correctOption":"B","correctAnswer":"Payment of staff wages","questionType":"MCQ","explanation":{"correct_reason":"Paying staff wages takes cash out of the Oslo cinema, so it is a cash outflow. Ticket sales, new borrowing and selling equipment all bring cash into the business and belong among the inflows of the forecast.","distractor_reasons":{"A":"Ticket sales generate cash from customers, so they are inflows. For a cinema, option B is correct: payment of staff wages.","B":"Paying staff wages takes cash out of the Oslo cinema, so it is a cash outflow. Ticket sales, new borrowing and selling equipment all bring cash into the business and belong among the inflows of the forecast.","C":"Borrowing from a bank increases the cinema's cash, so it is an inflow. For a cinema, option B is correct: payment of staff wages.","D":"Selling old equipment produces cash from a buyer, making it an inflow. For a cinema, option B is correct: payment of staff wages."}}},{"id":"P1_U5_MCQ_1673","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1673","question":"A shop in Porto, Portugal, has cost of sales of $180,000 and gross profit of $120,000 for the year. What was its revenue? Show your answer in dollars.","options":{"A":"$300,000","B":"$60,000","C":"$180,000","D":"$120,000"},"correctOption":"A","correctAnswer":"$300,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals cost of sales plus gross profit. The Porto shop's cost of sales of $180,000 plus gross profit of $120,000 gives revenue of $300,000 for the year.","distractor_reasons":{"A":"Revenue equals cost of sales plus gross profit. The Porto shop's cost of sales of $180,000 plus gross profit of $120,000 gives revenue of $300,000 for the year.","B":"This subtracts gross profit from cost of sales rather than adding them. For a shop, option A is correct: $300,000.","C":"This repeats cost of sales and ignores the $120,000 gross profit earned on top. For a shop, option A is correct: $300,000.","D":"This repeats gross profit and leaves out the $180,000 cost of sales. For a shop, option A is correct: $300,000."}}},{"id":"P1_U5_MCQ_1674","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1674","question":"A technology firm in Tallinn, Estonia, receives cash from investors in exchange for ordinary shares. How is this recorded in the statement of financial position?","options":{"A":"As a current liability","B":"As share capital within equity","C":"As revenue","D":"As an expense"},"correctOption":"B","correctAnswer":"As share capital within equity","questionType":"MCQ","explanation":{"correct_reason":"Money received from issuing ordinary shares is recorded as share capital, part of the equity section of the statement of financial position. It represents the owners' claim on the Tallinn firm and need not be repaid like a liability.","distractor_reasons":{"A":"Shareholders are owners, not creditors, so their investment is not a liability. For a technology firm, option B is correct: as share capital within equity.","B":"Money received from issuing ordinary shares is recorded as share capital, part of the equity section of the statement of financial position. It represents the owners' claim on the Tallinn firm and need not be repaid like a liability.","C":"Issuing shares raises finance but is not a sale of goods, so it is not revenue. For a technology firm, option B is correct: as share capital within equity.","D":"Cash received is an inflow of finance, not an expense. For a technology firm, option B is correct: as share capital within equity."}}},{"id":"P1_U5_MCQ_1675","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1675","question":"A hotel group in Lisbon, Portugal, reports return on capital employed of 4% while the interest rate on its loans is 7%. What concern does this raise?","options":{"A":"The group is earning less on its capital than it pays to borrow","B":"The group has no shareholders","C":"Its current ratio must be below 1","D":"Its gross profit margin is 7%"},"correctOption":"A","correctAnswer":"The group is earning less on its capital than it pays to borrow","questionType":"MCQ","explanation":{"correct_reason":"If return on capital employed is 4% while borrowing costs 7%, the Lisbon hotel group generates a return below the price of its debt, which may reduce shareholder returns. This comparison highlights a concern about the effectiveness of its investment.","distractor_reasons":{"A":"If return on capital employed is 4% while borrowing costs 7%, the Lisbon hotel group generates a return below the price of its debt, which may reduce shareholder returns. This comparison highlights a concern about the effectiveness of its investment.","B":"Having loans does not mean there are no shareholders; most companies have both. For a hotel group, option A is correct: the group is earning less on its capital than it pays to borrow.","C":"ROCE says nothing about the current ratio, which uses current assets and liabilities. For a hotel group, option A is correct: the group is earning less on its capital than it pays to borrow.","D":"The 7% figure is the loan interest rate, not the gross profit margin. For a hotel group, option A is correct: the group is earning less on its capital than it pays to borrow."}}},{"id":"P1_U5_MCQ_1676","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1676","question":"A seasonal ice-cream producer in Valencia, Spain, needs extra funds for three months to build stock before summer. Which source of finance best matches this need for the business?","options":{"A":"A 25-year bond","B":"A bank overdraft","C":"A new issue of shares","D":"A mortgage on the factory"},"correctOption":"B","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"A bank overdraft provides flexible short-term borrowing that can be drawn and repaid within months, suiting the Valencia producer's temporary stock build. Long-term sources such as bonds, shares or mortgages would be costly for a three-month need.","distractor_reasons":{"A":"A twenty-five-year bond creates long-term debt far beyond the three-month need. For a seasonal ice-cream producer, option B is correct: a bank overdraft.","B":"A bank overdraft provides flexible short-term borrowing that can be drawn and repaid within months, suiting the Valencia producer's temporary stock build. Long-term sources such as bonds, shares or mortgages would be costly for a three-month need.","C":"Issuing shares creates permanent equity and legal costs. For a seasonal ice-cream producer, option B is correct: a bank overdraft.","D":"A mortgage is long-term borrowing for major investment, not a few months of stock financing. For a seasonal ice-cream producer, option B is correct: a bank overdraft."}}},{"id":"P1_U5_MCQ_1677","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1677","question":"A market stall in Ghent, Belgium, had opening cash of $4,800, cash receipts of $21,600 and cash payments of $17,900 in a month. What was its closing cash balance?","options":{"A":"$8,500","B":"$3,700","C":"$1,100","D":"$26,400"},"correctOption":"A","correctAnswer":"$8,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $21,600 receipts minus $17,900 payments, a net inflow of $3,700. Adding this to the $4,800 opening balance gives the Ghent stall a closing cash balance of $8,500 for the month.","distractor_reasons":{"A":"Net cash flow is $21,600 receipts minus $17,900 payments, a net inflow of $3,700. Adding this to the $4,800 opening balance gives the Ghent stall a closing cash balance of $8,500 for the month.","B":"This is only the net cash inflow of $3,700 and forgets the $4,800 held at the start. For a market stall, option A is correct: $8,500.","C":"This subtracts $3,700 from $4,800 instead of adding the net inflow. For a market stall, option A is correct: $8,500.","D":"This adds receipts to opening cash but ignores the $17,900 of payments. For a market stall, option A is correct: $8,500."}}},{"id":"P1_U5_MCQ_1678","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1678","question":"An investor is comparing the profit margins of two airlines, one based in Dublin, Ireland, and one in Milan, Italy, using published accounts. What should be checked first?","options":{"A":"Whether both use the same accounting policies and reporting periods","B":"Whether both have the same number of employees","C":"Whether both fly the same routes","D":"Whether both are listed on the same stock exchange"},"correctOption":"A","correctAnswer":"Whether both use the same accounting policies and reporting periods","questionType":"MCQ","explanation":{"correct_reason":"Comparability depends on consistent accounting policies and reporting periods. If one airline values costs differently or uses a different year-end, reported profit margins may not be directly comparable, so the Dublin and Milan accounts need careful assessment.","distractor_reasons":{"A":"Comparability depends on consistent accounting policies and reporting periods. If one airline values costs differently or uses a different year-end, reported profit margins may not be directly comparable, so the Dublin and Milan accounts need careful assessment.","B":"Employee numbers do not determine whether profit figures are comparable. Option A is correct: whether both use the same accounting policies and reporting periods, which the scenario supports.","C":"Flying identical routes is not necessary to compare financial performance. Option A is correct: whether both use the same accounting policies and reporting periods, which the scenario supports.","D":"Listing on the same exchange is not required for comparing accounts. Option A is correct: whether both use the same accounting policies and reporting periods, which the scenario supports."}}},{"id":"P1_U5_MCQ_1679","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1679","question":"A finance director in Bilbao, Spain, wants to explain what equity represents in the statement of financial position. Which description of it is correct for the firm's owners?","options":{"A":"The total value of the firm's current assets","B":"The owners' residual claim after liabilities are deducted","C":"The amount owed to suppliers and banks","D":"The sales revenue earned during the year"},"correctOption":"B","correctAnswer":"The owners' residual claim after liabilities are deducted","questionType":"MCQ","explanation":{"correct_reason":"Equity represents the owners' residual interest in the Bilbao business: what remains of the assets after all liabilities have been deducted. It includes share capital and retained earnings and is sometimes called net assets or shareholders' funds.","distractor_reasons":{"A":"Current assets are resources, not the owners' claim. For a finance director, option B is correct: the owners' residual claim after liabilities are deducted.","B":"Equity represents the owners' residual interest in the Bilbao business: what remains of the assets after all liabilities have been deducted. It includes share capital and retained earnings and is sometimes called net assets or shareholders' funds.","C":"Amounts owed to suppliers and banks are liabilities, the opposite of equity. For a finance director, option B is correct: the owners' residual claim after liabilities are deducted.","D":"Sales revenue is a flow in the profit and loss account, not a claim at a point in time. For a finance director, option B is correct: the owners' residual claim after liabilities are deducted."}}},{"id":"P1_U5_MCQ_1680","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1680","question":"An analyst is assessing a retailer in Leeds, United Kingdom, whose acid test ratio is much lower than its current ratio. What does this most likely suggest?","options":{"A":"The retailer holds a significant amount of stock","B":"The retailer has no current liabilities","C":"The retailer's long-term debts are tiny","D":"The retailer's gross profit margin has risen"},"correctOption":"A","correctAnswer":"The retailer holds a significant amount of stock","questionType":"MCQ","explanation":{"correct_reason":"The acid test removes inventories from current assets. A much lower acid test than current ratio for the Leeds retailer therefore indicates a large stockholding, because subtracting inventories substantially reduces the numerator.","distractor_reasons":{"A":"The acid test removes inventories from current assets. A much lower acid test than current ratio for the Leeds retailer therefore indicates a large stockholding, because subtracting inventories substantially reduces the numerator.","B":"Both ratios divide by current liabilities, so they cannot be calculated if liabilities were zero. For an analyst is assessing a retailer, option A is correct: the retailer holds a significant amount of stock.","C":"These liquidity ratios do not include long-term debt. For an analyst is assessing a retailer, option A is correct: the retailer holds a significant amount of stock.","D":"The gap between the two liquidity ratios says nothing about the gross profit margin. For an analyst is assessing a retailer, option A is correct: the retailer holds a significant amount of stock."}}},{"id":"P1_U5_MCQ_1681","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1681","question":"A company in Antwerp, Belgium, has 20,000 ordinary shares and declares a dividend of $1.50 per share. What is the total dividend paid to shareholders?","options":{"A":"$30,000","B":"$3,000","C":"$20,000","D":"$21,500"},"correctOption":"A","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"Total dividends equal the dividend per share multiplied by the number of shares. The Antwerp company pays $1.50 on each of 20,000 shares, which gives a total dividend of $30,000 to its shareholders.","distractor_reasons":{"A":"Total dividends equal the dividend per share multiplied by the number of shares. The Antwerp company pays $1.50 on each of 20,000 shares, which gives a total dividend of $30,000 to its shareholders.","B":"This treats the dividend as $0.15 per share rather than $1.50. For a company, option A is correct: $30,000. That is the conclusion the information in the question supports.","C":"This repeats the number of shares as though each received one dollar, ignoring the $1.50 rate. For a company, option A is correct: $30,000.","D":"This adds 20,000 shares and $1.50 as if they were amounts to combine. Multiplying is required, so this total is not the dividend paid."}}},{"id":"P1_U5_MCQ_1682","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1682","question":"A car wash in Malaga, Spain, assumes in its cash forecast that customers pay immediately. What assumption should it state explicitly about its customers in that forecast?","options":{"A":"That all sales are for cash with no credit period","B":"That no customers will ever arrive","C":"That its costs will be zero","D":"That it will close next year"},"correctOption":"A","correctAnswer":"That all sales are for cash with no credit period","questionType":"MCQ","explanation":{"correct_reason":"A forecast relies on stated assumptions, and assuming immediate payment means the car wash expects no credit sales. Making this explicit allows the Malaga owner to test how the forecast changes if some customers pay later.","distractor_reasons":{"A":"A forecast relies on stated assumptions, and assuming immediate payment means the car wash expects no credit sales. Making this explicit allows the Malaga owner to test how the forecast changes if some customers pay later.","B":"Assuming no customers would mean no sales income, not a realistic basis for a car wash forecast. For a car wash, option A is correct: that all sales are for cash with no credit period.","C":"Costs will not be zero; the forecast should include wages, water and supplies. For a car wash, option A is correct: that all sales are for cash with no credit period.","D":"Closing next year is not an assumption about payment timing. For a car wash, option A is correct: that all sales are for cash with no credit period."}}},{"id":"P1_U5_MCQ_1683","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1683","question":"A bookshop in Edinburgh, United Kingdom, wants to present its revenue, expenses and profit for the year. Which statement will show these figures most clearly for the owner?","options":{"A":"Statement of financial position","B":"Profit and loss account","C":"Cash flow forecast","D":"A list of non-current assets only"},"correctOption":"B","correctAnswer":"Profit and loss account","questionType":"MCQ","explanation":{"correct_reason":"The profit and loss account reports revenue, the expenses incurred and the resulting profit or loss for a period. For the Edinburgh bookshop it shows how the year's trading produced the final profit figure.","distractor_reasons":{"A":"The statement of financial position shows assets, liabilities and equity at a point in time, not revenue and expenses over a year.","B":"The profit and loss account reports revenue, the expenses incurred and the resulting profit or loss for a period. For the Edinburgh bookshop it shows how the year's trading produced the final profit figure.","C":"A cash flow forecast projects cash receipts and payments, not revenue matched with expenses. For a bookshop, option B is correct: profit and loss account.","D":"A list of non-current assets shows only one category of resource. For a bookshop, option B is correct: profit and loss account."}}},{"id":"P1_U5_MCQ_1684","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1684","question":"A ceramic manufacturer in Seto, Japan, is listing its resources. Which of the following is a non-current asset for the business in its statement of financial position?","options":{"A":"Cash in the bank","B":"A kiln expected to be used for ten years","C":"Stock of clay awaiting use","D":"Amounts owed by customers"},"correctOption":"B","correctAnswer":"A kiln expected to be used for ten years","questionType":"MCQ","explanation":{"correct_reason":"A kiln used for ten years is a long-lived resource that will benefit the Seto manufacturer over several accounting periods, so it is a non-current asset. Cash, stock and receivables are all current assets used or converted within a year.","distractor_reasons":{"A":"Cash in the bank is a current asset because it is already money and available immediately. For a ceramic manufacturer, option B is correct: a kiln expected to be used for ten years.","B":"A kiln used for ten years is a long-lived resource that will benefit the Seto manufacturer over several accounting periods, so it is a non-current asset. Cash, stock and receivables are all current assets used or converted within a year.","C":"Stock of clay is a current asset because it will be used up in production within a year. For a ceramic manufacturer, option B is correct: a kiln expected to be used for ten years.","D":"Amounts owed by customers are trade receivables and therefore current assets. For a ceramic manufacturer, option B is correct: a kiln expected to be used for ten years."}}},{"id":"P1_U5_MCQ_1685","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1685","question":"A company in Turin, Italy, has current assets of $410,000, inventory of $110,000 and current liabilities of $150,000. What is its acid test ratio, to two decimal places?","options":{"A":"2.73 : 1","B":"2.00 : 1","C":"1.00 : 1","D":"0.50 : 1"},"correctOption":"B","correctAnswer":"2.00 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test ratio removes inventory from current assets. The Turin company's $410,000 less $110,000 gives $300,000 of liquid assets, and dividing by $150,000 of current liabilities produces an acid test ratio of 2.00 : 1.","distractor_reasons":{"A":"This divides the full $410,000 of current assets by $150,000 without removing $110,000 of inventory, giving the current ratio instead. The acid test is a stricter measure.","B":"The acid test ratio removes inventory from current assets. The Turin company's $410,000 less $110,000 gives $300,000 of liquid assets, and dividing by $150,000 of current liabilities produces an acid test ratio of 2.00 : 1.","C":"This subtracts $110,000 and then divides by $300,000 rather than $150,000. For a company, option B is correct: 2.00 : 1.","D":"This inverts the ratio by dividing $150,000 of liabilities by $300,000 of liquid assets. The acid test expresses liquid assets relative to liabilities, not the reverse."}}},{"id":"P1_U5_MCQ_1686","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1686","question":"A retailing business in Krakow, Poland, wants the cheapest source of finance with no legal obligation to repay. Which source best fits these requirements for the business?","options":{"A":"Bank loan","B":"Retained earnings","C":"Debenture","D":"Overdraft"},"correctOption":"B","correctAnswer":"Retained earnings","questionType":"MCQ","explanation":{"correct_reason":"Retained earnings are profits already kept in the Krakow business, so they carry no interest charge, no legal duty to repay and no issue costs. The other listed sources are debts requiring repayment and usually interest.","distractor_reasons":{"A":"A bank loan must be repaid with interest and is a legal obligation. For a retailing business, option B is correct: retained earnings.","B":"Retained earnings are profits already kept in the Krakow business, so they carry no interest charge, no legal duty to repay and no issue costs. The other listed sources are debts requiring repayment and usually interest.","C":"A debenture is long-term debt with fixed interest and a repayment date. For a retailing business, option B is correct: retained earnings.","D":"An overdraft is short-term borrowing that must be repaid with interest. For a retailing business, option B is correct: retained earnings."}}},{"id":"P1_U5_MCQ_1687","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1687","question":"A museum in Vienna, Austria, forecasts a large cash surplus for the next six months. What should the finance manager consider doing with that surplus?","options":{"A":"Repay an expensive short-term loan or place the funds on deposit","B":"Immediately distribute all funds to visitors","C":"Ignore the surplus because cash has no cost","D":"Write off all the museum's assets"},"correctOption":"A","correctAnswer":"Repay an expensive short-term loan or place the funds on deposit","questionType":"MCQ","explanation":{"correct_reason":"A cash surplus can repay costly borrowing, reducing interest charges, or be deposited to earn a return until needed. The Vienna finance manager should consider these options rather than leaving idle cash or making inappropriate distributions.","distractor_reasons":{"A":"A cash surplus can repay costly borrowing, reducing interest charges, or be deposited to earn a return until needed. The Vienna finance manager should consider these options rather than leaving idle cash or making inappropriate distributions.","B":"Distributing cash to visitors is not a normal use of surplus funds and would not benefit the museum. For a museum, option A is correct: repay an expensive short-term loan or place the funds on deposit.","C":"Idle cash has an opportunity cost because it could earn interest or reduce borrowing. For a museum, option A is correct: repay an expensive short-term loan or place the funds on deposit.","D":"Writing off assets does not follow from having spare cash. For a museum, option A is correct: repay an expensive short-term loan or place the funds on deposit."}}},{"id":"P1_U5_MCQ_1688","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1688","question":"A clothing retailer in Plovdiv, Bulgaria, is preparing a profit and loss account. At which stage is gross profit calculated in that statement for the year?","options":{"A":"After operating expenses are deducted from revenue","B":"After interest and taxation have been charged","C":"When cost of sales is subtracted from revenue","D":"When cash receipts exceed cash payments"},"correctOption":"C","correctAnswer":"When cost of sales is subtracted from revenue","questionType":"MCQ","explanation":{"correct_reason":"Gross profit appears early in the profit and loss account as revenue minus cost of sales for the Plovdiv retailer. Operating expenses, interest and tax are deducted afterwards to reach operating profit and profit for the year.","distractor_reasons":{"A":"Operating expenses are deducted after gross profit has been calculated. For a clothing retailer, option C is correct: when cost of sales is subtracted from revenue.","B":"Interest and taxation are charged near the end of the account, long after gross profit. For a clothing retailer, option C is correct: when cost of sales is subtracted from revenue.","C":"Gross profit appears early in the profit and loss account as revenue minus cost of sales for the Plovdiv retailer. Operating expenses, interest and tax are deducted afterwards to reach operating profit and profit for the year.","D":"Cash receipts and payments belong in a cash flow forecast, not the profit and loss account. For a clothing retailer, option C is correct: when cost of sales is subtracted from revenue."}}},{"id":"P1_U5_MCQ_1689","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1689","question":"A firm in Porto, Portugal, has current assets of $340,000 and a current ratio of 2 : 1. What is the value of its current liabilities?","options":{"A":"$170,000","B":"$680,000","C":"$340,000","D":"$150,000"},"correctOption":"A","correctAnswer":"$170,000","questionType":"MCQ","explanation":{"correct_reason":"The current ratio equals current assets divided by current liabilities. Rearranging, current liabilities equal $340,000 divided by 2, which gives $170,000 for the Porto firm because current assets are twice its short-term debts.","distractor_reasons":{"A":"The current ratio equals current assets divided by current liabilities. Rearranging, current liabilities equal $340,000 divided by 2, which gives $170,000 for the Porto firm because current assets are twice its short-term debts.","B":"This multiplies $340,000 by 2 instead of dividing by the ratio. For a firm, option A is correct: $170,000. That is the conclusion the information in the question supports.","C":"This repeats current assets and ignores the 2 : 1 relationship. For a firm, option A is correct: $170,000. That is the conclusion the information in the question supports.","D":"This subtracts an arbitrary amount from $340,000 rather than halving it. The correct current liabilities are half of current assets, not $150,000."}}},{"id":"P1_U5_MCQ_1690","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1690","question":"A lender in Seoul, South Korea, is comparing the liquidity of two firms. Why might a high current ratio still leave a firm at risk?","options":{"A":"Because much of the stock may be slow to sell","B":"Because a high ratio always means the firm is profitable","C":"Because current ratios cannot be expressed as a ratio","D":"Because current liabilities are never included in the calculation"},"correctOption":"A","correctAnswer":"Because much of the stock may be slow to sell","questionType":"MCQ","explanation":{"correct_reason":"The current ratio includes inventories, which may be old or unsellable and cannot always be turned into cash quickly. A high ratio can therefore overstate true liquidity for the Seoul lender, who should also examine the acid test.","distractor_reasons":{"A":"The current ratio includes inventories, which may be old or unsellable and cannot always be turned into cash quickly. A high ratio can therefore overstate true liquidity for the Seoul lender, who should also examine the acid test.","B":"A high current ratio measures liquidity, not profitability. For a lender, option A is correct: because much of the stock may be slow to sell.","C":"The current ratio is expressly expressed in the form of a ratio. For a lender, option A is correct: because much of the stock may be slow to sell.","D":"Current liabilities are the denominator of the current ratio. For a lender, option A is correct: because much of the stock may be slow to sell."}}},{"id":"P1_U5_MCQ_1691","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1691","question":"A textile firm in Fes, Morocco, is comparing retained profit with a bank loan for expansion. Which advantage of retained profit over borrowing is correct?","options":{"A":"It must be repaid on a fixed date","B":"It carries no interest charge and no dilution of control","C":"It always raises more money than a loan","D":"It gives lenders a claim on the firm's assets"},"correctOption":"B","correctAnswer":"It carries no interest charge and no dilution of control","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is already owned by the Fes firm, so using it avoids interest payments and does not give any new investor a share of ownership or control. A bank loan, by contrast, requires interest and eventual repayment.","distractor_reasons":{"A":"Retained profit does not have to be repaid on a fixed date, unlike a loan. For a textile firm, option B is correct: it carries no interest charge and no dilution of control.","B":"Retained profit is already owned by the Fes firm, so using it avoids interest payments and does not give any new investor a share of ownership or control. A bank loan, by contrast, requires interest and eventual repayment.","C":"The amount available depends on past profits and need not exceed what a bank would lend. For a textile firm, option B is correct: it carries no interest charge and no dilution of control.","D":"Giving lenders a claim on assets is a feature of secured borrowing, not retained profit. For a textile firm, option B is correct: it carries no interest charge and no dilution of control."}}},{"id":"P1_U5_MCQ_1692","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1692","question":"A bakery in Seville, Spain, wants its cash flow forecast to be more reliable. Which action would most improve the accuracy of future forecasts for the bakery?","options":{"A":"Regularly compare actual cash flows with the forecast and update assumptions","B":"Prepare the forecast only once and never revise it","C":"Exclude all payments from the forecast","D":"Base the forecast on the owner's hopes rather than data"},"correctOption":"A","correctAnswer":"Regularly compare actual cash flows with the forecast and update assumptions","questionType":"MCQ","explanation":{"correct_reason":"Comparing actual cash flows with predictions reveals where assumptions were wrong, allowing the Seville bakery to refine estimates and improve later forecasts. Forecasting is an iterative process that should respond to new information and changing conditions.","distractor_reasons":{"A":"Comparing actual cash flows with predictions reveals where assumptions were wrong, allowing the Seville bakery to refine estimates and improve later forecasts. Forecasting is an iterative process that should respond to new information and changing conditions.","B":"Never revising a forecast ignores new information and reduces accuracy. For a bakery, option A is correct: regularly compare actual cash flows with the forecast and update assumptions.","C":"Excluding payments would make the forecast misleading and incomplete. For a bakery, option A is correct: regularly compare actual cash flows with the forecast and update assumptions.","D":"Forecasts based on hopes rather than data are unreliable. For a bakery, option A is correct: regularly compare actual cash flows with the forecast and update assumptions."}}},{"id":"P1_U5_MCQ_1693","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1693","question":"A firm in Braga, Portugal, has revenue of $360,000 and gross profit of $90,000 for the year. What was its cost of sales for that same period?","options":{"A":"$270,000","B":"$450,000","C":"$90,000","D":"$360,000"},"correctOption":"A","correctAnswer":"$270,000","questionType":"MCQ","explanation":{"correct_reason":"Since gross profit equals revenue minus cost of sales, cost of sales equals revenue minus gross profit. For the Braga firm that is $360,000 less $90,000, giving cost of sales of $270,000 for the year.","distractor_reasons":{"A":"Since gross profit equals revenue minus cost of sales, cost of sales equals revenue minus gross profit. For the Braga firm that is $360,000 less $90,000, giving cost of sales of $270,000 for the year.","B":"This adds revenue and gross profit rather than subtracting. For a firm, option A is correct: $270,000. That is the conclusion the information in the question supports.","C":"This repeats gross profit and ignores the $360,000 of revenue. For a firm, option A is correct: $270,000. That is the conclusion the information in the question supports.","D":"This repeats revenue and ignores the $90,000 gross profit. For a firm, option A is correct: $270,000. That is the conclusion the information in the question supports."}}},{"id":"P1_U5_MCQ_1694","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1694","question":"A firm in San Sebastian, Spain, buys a delivery van on credit. What is the immediate effect on its statement of financial position at the point of purchase?","options":{"A":"Assets increase and liabilities increase","B":"Assets increase and equity decreases","C":"Liabilities decrease and assets increase","D":"Both assets and liabilities are unchanged"},"correctOption":"A","correctAnswer":"Assets increase and liabilities increase","questionType":"MCQ","explanation":{"correct_reason":"Buying a van on credit gives the San Sebastian firm a new non-current asset while creating an obligation to pay the supplier. Assets and liabilities therefore both rise by the same amount, leaving the accounting equation balanced.","distractor_reasons":{"A":"Buying a van on credit gives the San Sebastian firm a new non-current asset while creating an obligation to pay the supplier. Assets and liabilities therefore both rise by the same amount, leaving the accounting equation balanced.","B":"Equity represents the owners' claim and is not reduced by purchasing an asset on credit. For a firm, option A is correct: assets increase and liabilities increase.","C":"Buying on credit creates a new liability rather than reducing an existing one. For a firm, option A is correct: assets increase and liabilities increase.","D":"acquiring a van and owing money must change the statement. For a firm, option A is correct: assets increase and liabilities increase."}}},{"id":"P1_U5_MCQ_1695","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1695","question":"An investor in Rotterdam, Netherlands, is comparing the return on capital employed of two firms. Why might the ratio alone be misleading when judging those firms?","options":{"A":"Because asset values may be based on old historical costs","B":"Because ROCE is never expressed as a percentage","C":"Because capital employed ignores operating profit","D":"Because ROCE cannot be compared between firms"},"correctOption":"A","correctAnswer":"Because asset values may be based on old historical costs","questionType":"MCQ","explanation":{"correct_reason":"ROCE divides operating profit by capital employed, and capital employed depends on recorded asset values. Older assets bought cheaply may make one Rotterdam firm's ratio look artificially high, so historical cost can distort comparisons.","distractor_reasons":{"A":"ROCE divides operating profit by capital employed, and capital employed depends on recorded asset values. Older assets bought cheaply may make one Rotterdam firm's ratio look artificially high, so historical cost can distort comparisons.","B":"ROCE is commonly expressed as a percentage. For an investor, option A is correct: because asset values may be based on old historical costs.","C":"Operating profit is the numerator of ROCE, so it is central to the ratio. For an investor, option A is correct: because asset values may be based on old historical costs.","D":"ROCE can be compared between firms, subject to the usual cautions. For an investor, option A is correct: because asset values may be based on old historical costs."}}},{"id":"P1_U5_MCQ_1696","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1696","question":"A firm in Lille, France, is comparing a bank loan with issuing shares. Which disadvantage of the loan should be highlighted in its financing decision for expansion?","options":{"A":"It gives new investors a share of ownership","B":"It creates an obligation to pay interest and repay the principal","C":"Dividends must be paid each year on the loan","D":"It cannot be used to fund long-term investment"},"correctOption":"B","correctAnswer":"It creates an obligation to pay interest and repay the principal","questionType":"MCQ","explanation":{"correct_reason":"A bank loan is debt, so the Lille firm must pay interest and return the borrowed principal on agreed terms, a burden that does not apply to share capital. This fixed commitment can strain cash flow if profits fall.","distractor_reasons":{"A":"A loan does not give lenders ownership; that would be a share issue. For a firm, option B is correct: it creates an obligation to pay interest and repay the principal.","B":"A bank loan is debt, so the Lille firm must pay interest and return the borrowed principal on agreed terms, a burden that does not apply to share capital. This fixed commitment can strain cash flow if profits fall.","C":"Dividends relate to shares, not loans, which pay interest. For a firm, option B is correct: it creates an obligation to pay interest and repay the principal.","D":"Loans are frequently used for long-term investment. For a firm, option B is correct: it creates an obligation to pay interest and repay the principal."}}},{"id":"P1_U5_MCQ_1697","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1697","question":"A cafe in Ghent, Belgium, had opening cash of $7,800, cash receipts of $28,400 and cash payments of $31,200 during a month. What was its closing cash balance?","options":{"A":"$5,000","B":"$2,800","C":"$10,600","D":"$36,200"},"correctOption":"A","correctAnswer":"$5,000","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $28,400 receipts minus $31,200 payments, a net outflow of $2,800. Subtracting this from the $7,800 opening balance gives the Ghent cafe a closing cash balance of $5,000 for the month.","distractor_reasons":{"A":"Net cash flow is $28,400 receipts minus $31,200 payments, a net outflow of $2,800. Subtracting this from the $7,800 opening balance gives the Ghent cafe a closing cash balance of $5,000 for the month.","B":"This is only the net cash outflow of $2,800 and forgets to adjust the $7,800 opening balance. For a cafe, option A is correct: $5,000.","C":"This adds the $2,800 outflow to the opening balance rather than subtracting it. For a cafe, option A is correct: $5,000.","D":"This adds receipts to opening cash but ignores the $31,200 of payments. For a cafe, option A is correct: $5,000."}}},{"id":"P1_U5_MCQ_1698","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1698","question":"A clothing retailer in Milan, Italy, wants to improve its gross profit margin. Which action would directly raise that margin for the retailer in the coming year?","options":{"A":"Reducing the purchase cost of the goods it sells","B":"Increasing the interest paid on its loans","C":"Paying higher dividends to shareholders","D":"Reducing the amount of cash it holds"},"correctOption":"A","correctAnswer":"Reducing the purchase cost of the goods it sells","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit divided by revenue. If the Milan retailer lowers the purchase cost of goods, cost of sales falls and gross profit rises for a given selling price, directly increasing the margin.","distractor_reasons":{"A":"Gross profit margin is gross profit divided by revenue. If the Milan retailer lowers the purchase cost of goods, cost of sales falls and gross profit rises for a given selling price, directly increasing the margin.","B":"Interest is a finance cost deducted after gross profit, so it cannot affect the gross margin. For a clothing retailer, option A is correct: reducing the purchase cost of the goods it sells.","C":"Dividends are distributions of profit, not costs affecting gross profit. For a clothing retailer, option A is correct: reducing the purchase cost of the goods it sells.","D":"The amount of cash held is a balance sheet matter and does not change the gross margin. For a clothing retailer, option A is correct: reducing the purchase cost of the goods it sells."}}},{"id":"P1_U5_MCQ_1699","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1699","question":"A company in Nice, France, is separating current assets from non-current assets. Which of the following is a current asset for that company in its statement of financial position?","options":{"A":"A warehouse building used for storage","B":"Inventories of finished goods","C":"A ten-year delivery vehicle","D":"Patents held for many years"},"correctOption":"B","correctAnswer":"Inventories of finished goods","questionType":"MCQ","explanation":{"correct_reason":"Inventories of finished goods are expected to be sold and converted into cash within a year, so they are current assets for the Nice company. The warehouse, vehicle and long-held patents are all long-lived non-current assets.","distractor_reasons":{"A":"A warehouse building is a long-lived resource used over many years. For a company, option B is correct: inventories of finished goods.","B":"Inventories of finished goods are expected to be sold and converted into cash within a year, so they are current assets for the Nice company. The warehouse, vehicle and long-held patents are all long-lived non-current assets.","C":"A ten-year delivery vehicle is a non-current asset used repeatedly. For a company, option B is correct: inventories of finished goods.","D":"Patents held for many years are intangible non-current assets. For a company, option B is correct: inventories of finished goods."}}},{"id":"P1_U5_MCQ_1700","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1700","question":"A financial analyst in Leeds, United Kingdom, is reviewing a firm's accounts. Why might ratio analysis alone be insufficient to judge the performance of that business?","options":{"A":"Ratios use only figures from financial statements and ignore wider context","B":"Ratios are impossible to calculate from published accounts","C":"Ratios never involve percentages or comparisons","D":"Ratios always give a complete picture of the business"},"correctOption":"A","correctAnswer":"Ratios use only figures from financial statements and ignore wider context","questionType":"MCQ","explanation":{"correct_reason":"Ratios summarise accounting numbers but cannot capture market conditions, management quality or non-financial factors. The Leeds analyst should combine ratio results with wider qualitative evidence before judging the firm's overall performance.","distractor_reasons":{"A":"Ratios summarise accounting numbers but cannot capture market conditions, management quality or non-financial factors. The Leeds analyst should combine ratio results with wider qualitative evidence before judging the firm's overall performance.","B":"Ratios are calculated from published financial statements. For a financial analyst, option A is correct: ratios use only figures from financial statements and ignore wider context.","C":"Ratios are frequently expressed as percentages or comparisons. For a financial analyst, option A is correct: ratios use only figures from financial statements and ignore wider context.","D":"Ratios do not give a complete picture on their own. For a financial analyst, option A is correct: ratios use only figures from financial statements and ignore wider context."}}},{"id":"P1_U5_MCQ_1701","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1701","question":"Suri Fish Processing Ltd in Surabaya, Indonesia, needs $400,000 to buy a new freezing line that will be used for eight years. The finance must be repaid over the same long period and the owners do not want to sell any shares. Which source of finance best matches this need?","options":{"A":"A term bank loan","B":"A bank overdraft","C":"Trade credit from suppliers","D":"Sale of old office furniture"},"correctOption":"A","correctAnswer":"A term bank loan","questionType":"MCQ","explanation":{"correct_reason":"A term bank loan provides a large sum repaid over several years, matching the eight-year life of the freezing line. It leaves ownership with the existing shareholders, unlike a share issue, and is not a short-term source such as an overdraft or trade credit.","distractor_reasons":{"A":"A term bank loan provides a large sum repaid over several years, matching the eight-year life of the freezing line. It leaves ownership with the existing shareholders, unlike a share issue, and is not a short-term source such as an overdraft or trade credit.","B":"Option B is wrong because a bank overdraft is short-term, repayable on demand and designed for temporary cash shortages. Surabaya's freezing line lasts eight years, so funding it with an overdraft would create a serious mismatch between the asset and its repayment.","C":"Option C is wrong because trade credit is a short-term spontaneous source used to delay payment for supplies, not to buy a major fixed asset. A processing line costing $400,000 needs structured long-term borrowing, not an extension of supplier payment terms.","D":"Option D is wrong because selling old office furniture would raise only a small amount and would not fund a $400,000 freezing line. The proceeds are one-off and far too modest for a long-lived asset in Surabaya."}}},{"id":"P1_U5_MCQ_1702","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1702","question":"Kiffa Bakeries in Nouakchott, Mauritania, expects cash inflows of $86,000 in March and cash outflows of $79,500, having opened the month with a cash balance of $4,200. What is the forecast closing cash balance at the end of March?","options":{"A":"$6,500","B":"$10,700","C":"$90,200","D":"$2,300"},"correctOption":"B","correctAnswer":"$10,700","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $86,000 inflows less $79,500 outflows, giving $6,500. Adding the opening balance of $4,200 produces a closing cash balance of $10,700 for Kiffa Bakeries at the end of March.","distractor_reasons":{"A":"Option A is wrong because $6,500 is only the net cash flow for March, the difference between inflows and outflows. The closing balance must also include the $4,200 opening cash, so the answer is higher.","B":"Net cash flow is $86,000 inflows less $79,500 outflows, giving $6,500. Adding the opening balance of $4,200 produces a closing cash balance of $10,700 for Kiffa Bakeries at the end of March.","C":"Option C is wrong because $90,200 adds the opening balance to inflows but ignores the $79,500 of outflows entirely. Outflows must be deducted before the closing cash position can be found.","D":"Option D is wrong because $2,300 comes from subtracting net cash flow from the opening balance, reversing the correct operation. Cash increased in March, so the closing figure must exceed $4,200."}}},{"id":"P1_U5_MCQ_1703","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1703","question":"At Lomba Textiles in Antananarivo, Madagascar, revenue for the year was $540,000 and cost of sales was $324,000. The accountant is preparing the profit and loss account. What was the gross profit for the year?","options":{"A":"$864,000","B":"$324,000","C":"$216,000","D":"$180,000"},"correctOption":"C","correctAnswer":"$216,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue of $540,000 minus cost of sales of $324,000, which equals $216,000. This is the surplus left after the direct costs of making the goods sold, before operating expenses are deducted.","distractor_reasons":{"A":"Option A is wrong because $864,000 adds revenue and cost of sales instead of subtracting them. Cost of sales is an expense to be deducted from revenue, not a figure to be added to it.","B":"Option B is wrong because $324,000 is the cost of sales itself, not the gross profit. Gross profit is what remains after that figure is taken away from the $540,000 of revenue.","C":"Gross profit is revenue of $540,000 minus cost of sales of $324,000, which equals $216,000. This is the surplus left after the direct costs of making the goods sold, before operating expenses are deducted.","D":"Option D is wrong because $180,000 does not result from any correct calculation using $540,000 and $324,000. The difference between the two given figures is $216,000."}}},{"id":"P1_U5_MCQ_1704","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1704","question":"Nzérékoré Timber Ltd in Guinea is listing the items in its statement of financial position before presenting it to the owners. Which one of the following would be classified as a non-current asset?","options":{"A":"Trade receivables","B":"Cash at bank","C":"Inventories of sawn timber","D":"A wood-processing mill"},"correctOption":"D","correctAnswer":"A wood-processing mill","questionType":"MCQ","explanation":{"correct_reason":"A wood-processing mill is a long-lived asset used repeatedly in the business and not intended for resale, so it is a non-current asset. Trade receivables, cash and inventories are all current assets because they are expected to be converted within a year.","distractor_reasons":{"A":"Option A is wrong because trade receivables are amounts owed by customers, normally settled within weeks or months. They are current assets, not long-lived resources used in production.","B":"Option B is wrong because cash at bank is the most liquid current asset available to Nzérékoré Timber. It is held for immediate use rather than for long-term productive purposes.","C":"Option C is wrong because inventories of sawn timber are held for sale and usually turn over within the trading year. Such stocks are current assets even if the timber itself is bulky.","D":"A wood-processing mill is a long-lived asset used repeatedly in the business and not intended for resale, so it is a non-current asset. Trade receivables, cash and inventories are all current assets because they are expected to be converted within a year."}}},{"id":"P1_U5_MCQ_1705","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1705","question":"Buyantu Retail Ltd in Ulaanbaatar, Mongolia, reports current assets of $360,000 and current liabilities of $150,000. The finance manager is reviewing liquidity ahead of a loan application. What is its current ratio?","options":{"A":"2.4 : 1","B":"0.4 : 1","C":"1.4 : 1","D":"2.1 : 1"},"correctOption":"A","correctAnswer":"2.4 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio divides current assets of $360,000 by current liabilities of $150,000, giving 2.4. Buyantu Retail therefore has $2.40 of current assets for every $1 of short-term obligations falling due.","distractor_reasons":{"A":"The current ratio divides current assets of $360,000 by current liabilities of $150,000, giving 2.4. Buyantu Retail therefore has $2.40 of current assets for every $1 of short-term obligations falling due.","B":"Option B is wrong because 0.4 results from dividing current liabilities by current assets, reversing the formula. A ratio below one would suggest liquidity problems that the reported figures do not show.","C":"Option C is wrong because 1.4 seems to come from subtracting the figures rather than dividing them. The current ratio is a quotient of the two balances, not their difference.","D":"Option D is wrong because 2.1 does not equal $360,000 divided by $150,000. Performing the division carefully gives 2.4, so this option miscalculates the relationship."}}},{"id":"P1_U5_MCQ_1706","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1706","question":"The owners of Argan Cosmetics in Essaouira, Morocco, have decided to fund a new range by reinvesting last year's profits rather than borrowing from a bank. Which advantage of this source of finance is being illustrated by their decision?","options":{"A":"It must be repaid with interest each month","B":"No interest or repayment obligation is created","C":"Ownership is immediately diluted","D":"It is only available to public limited companies"},"correctOption":"B","correctAnswer":"No interest or repayment obligation is created","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is internal finance, so using it creates no interest charge and no legal duty to repay. Argan Cosmetics keeps full control because the reinvested earnings already belong to the owners.","distractor_reasons":{"A":"Option A is wrong because an obligation to repay with interest applies to borrowed funds such as bank loans, not to retained profit. Reinvested earnings carry no such contractual schedule.","B":"Retained profit is internal finance, so using it creates no interest charge and no legal duty to repay. Argan Cosmetics keeps full control because the reinvested earnings already belong to the owners.","C":"Option C is wrong because issuing new shares would dilute ownership, but reinvesting existing profits does not create new shareholders. The current owners simply forgo a dividend.","D":"Option D is wrong because retained profit is available to sole traders, partnerships and private companies alike. It is not restricted to public limited companies."}}},{"id":"P1_U5_MCQ_1707","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1707","question":"Tsaang Metalworks in Kaohsiung, Taiwan, made a healthy accounting profit last year but still could not pay its suppliers on time. The finance director is investigating the cause. Which explanation is most likely?","options":{"A":"Profit and cash flow are always identical","B":"The firm sold too many goods for cash","C":"Most sales were on credit and cash had not yet been received","D":"The firm had no operating expenses"},"correctOption":"C","correctAnswer":"Most sales were on credit and cash had not yet been received","questionType":"MCQ","explanation":{"correct_reason":"Accounting profit is recognised when sales are made, but cash arrives only when credit customers pay. If Tsaang's sales were largely on credit, profit can look strong while the bank balance is too low to settle suppliers.","distractor_reasons":{"A":"Option A is wrong because profit and cash flow differ due to timing differences such as credit sales and stock purchases. A profitable firm can still suffer a cash shortage.","B":"Option B is wrong because cash sales would improve liquidity immediately, not create a payment problem. The difficulty arises when buyers delay payment rather than pay at the point of sale.","C":"Accounting profit is recognised when sales are made, but cash arrives only when credit customers pay. If Tsaang's sales were largely on credit, profit can look strong while the bank balance is too low to settle suppliers.","D":"Option D is wrong because a firm with no operating expenses would be even more cash-rich, all else equal. Expenses do not explain an inability to pay suppliers on time."}}},{"id":"P1_U5_MCQ_1708","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1708","question":"The gross profit margin of Ibuprofen Farmacêutica in São Paulo, Brazil, has fallen while revenue stayed the same. The management team wants to identify the direct cause. Which change most directly explains this fall?","options":{"A":"A fall in operating expenses","B":"A rise in the number of shares issued","C":"A decrease in interest rates","D":"An increase in the cost of raw materials"},"correctOption":"D","correctAnswer":"An increase in the cost of raw materials","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin compares gross profit with revenue, so if revenue is unchanged a rise in cost of sales must reduce the margin. Higher raw material prices raise cost of sales directly at Ibuprofen.","distractor_reasons":{"A":"Option A is wrong because operating expenses are deducted after gross profit, so changing them does not alter the gross profit margin. That margin stops at gross profit.","B":"Option B is wrong because issuing shares affects finance and ownership, not the trading figures of revenue and cost of sales that determine gross margin.","C":"Option C is wrong because interest rates influence borrowing costs, which are finance costs below gross profit. They do not change the cost of sales figure.","D":"Gross profit margin compares gross profit with revenue, so if revenue is unchanged a rise in cost of sales must reduce the margin. Higher raw material prices raise cost of sales directly at Ibuprofen."}}},{"id":"P1_U5_MCQ_1709","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1709","question":"Kumasi Agro Ltd in Ghana has current assets of $410,000 and current liabilities of $265,000. Its accountant wants a quick measure of short-term liquidity. What is its working capital?","options":{"A":"$145,000","B":"$675,000","C":"$265,000","D":"$410,000"},"correctOption":"A","correctAnswer":"$145,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities. Subtracting $265,000 from $410,000 gives $145,000, the net short-term resources available to Kumasi Agro for day-to-day trading.","distractor_reasons":{"A":"Working capital is current assets minus current liabilities. Subtracting $265,000 from $410,000 gives $145,000, the net short-term resources available to Kumasi Agro for day-to-day trading.","B":"Option B is wrong because $675,000 is the sum of current assets and current liabilities. Working capital is a net figure obtained by subtracting obligations from assets.","C":"Option C is wrong because $265,000 is simply the current liabilities figure. It is a component of the calculation, not the resulting net working capital.","D":"Option D is wrong because $410,000 is the current assets total before deducting what the business owes. Working capital must account for short-term debts."}}},{"id":"P1_U5_MCQ_1710","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1710","question":"Zeeland Dairy in Middelburg, Netherlands, has current assets of $280,000, of which $70,000 is inventory, and current liabilities of $140,000. A lender has asked for a stricter liquidity test. What is its acid test ratio?","options":{"A":"2.0 : 1","B":"1.5 : 1","C":"0.5 : 1","D":"1.0 : 1"},"correctOption":"B","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test excludes inventory, so liquid assets are $280,000 less $70,000, or $210,000. Dividing by $140,000 of current liabilities gives an acid test ratio of 1.5 : 1.","distractor_reasons":{"A":"Option A is wrong because 2.0 : 1 is the current ratio, using all $280,000 of current assets. The acid test deliberately removes the $70,000 of inventory first.","B":"The acid test excludes inventory, so liquid assets are $280,000 less $70,000, or $210,000. Dividing by $140,000 of current liabilities gives an acid test ratio of 1.5 : 1.","C":"Option C is wrong because 0.5 : 1 reverses the division or omits most current assets. Liquid assets of $210,000 exceed current liabilities of $140,000.","D":"Option D is wrong because 1.0 : 1 would require liquid assets of exactly $140,000. After excluding inventory, Zeeland Dairy holds $210,000, so the ratio is higher."}}},{"id":"P1_U5_MCQ_1711","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1711","question":"A tailor in Oaxaca, Mexico, needs short-term finance to buy fabric while waiting for a large order to be paid. The need will last only a few weeks. Which source of finance is most suitable for this temporary need?","options":{"A":"Issuing ordinary shares","B":"A twenty-year mortgage","C":"A bank overdraft","D":"Venture capital investment"},"correctOption":"C","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"A bank overdraft is a flexible short-term facility that lets the tailor borrow only when needed and repay as customers pay. It suits a brief working-capital gap far better than long-term or permanent finance.","distractor_reasons":{"A":"Option A is wrong because issuing shares is permanent equity finance used for long-term expansion. It is costly and complex for a simple temporary fabric purchase in Oaxaca.","B":"Option B is wrong because a twenty-year mortgage is designed to buy property over a long term. The tailor's need lasts only weeks, so such a long commitment is inappropriate.","C":"A bank overdraft is a flexible short-term facility that lets the tailor borrow only when needed and repay as customers pay. It suits a brief working-capital gap far better than long-term or permanent finance.","D":"Option D is wrong because venture capital is high-risk equity funding for growing businesses seeking large sums. It is unsuitable for a small short-term working-capital need."}}},{"id":"P1_U5_MCQ_1712","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1712","question":"In its June forecast, Vung Tau Seafoods in Vietnam expects cash inflows of $124,000 and cash outflows of $131,500. The finance team wants the overall cash movement for the month. What is the forecast net cash flow for June?","options":{"A":"$255,500","B":"$7,500","C":"$124,000","D":"-$7,500"},"correctOption":"D","correctAnswer":"-$7,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow equals inflows minus outflows. With $124,000 coming in and $131,500 going out, Vung Tau Seafoods has a net cash outflow of $7,500 in June.","distractor_reasons":{"A":"Option A is wrong because $255,500 adds inflows and outflows together. Net cash flow requires subtracting outflows from inflows, not combining the two totals.","B":"Option B is wrong because $7,500 is the correct magnitude but the wrong direction. Outflows exceed inflows, so the net cash flow is negative rather than positive.","C":"Option C is wrong because $124,000 is simply the inflow figure. Net cash flow must take account of the $131,500 paid out during June as well.","D":"Net cash flow equals inflows minus outflows. With $124,000 coming in and $131,500 going out, Vung Tau Seafoods has a net cash outflow of $7,500 in June."}}},{"id":"P1_U5_MCQ_1713","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1713","question":"Rift Valley Coffee in Eldoret, Kenya, reports gross profit of $380,000 and operating expenses of $215,000. There was no other income and no finance cost during the year. What is its profit for the year?","options":{"A":"$165,000","B":"$595,000","C":"$215,000","D":"$380,000"},"correctOption":"A","correctAnswer":"$165,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is gross profit less operating expenses. Deducting $215,000 from $380,000 leaves $165,000, the amount retained after all operating costs at Rift Valley Coffee.","distractor_reasons":{"A":"Profit for the year is gross profit less operating expenses. Deducting $215,000 from $380,000 leaves $165,000, the amount retained after all operating costs at Rift Valley Coffee.","B":"Option B is wrong because $595,000 adds gross profit and operating expenses. Expenses must be subtracted from gross profit, never added to it.","C":"Option C is wrong because $215,000 is the operating expenses total, an input to the calculation rather than the resulting profit.","D":"Option D is wrong because $380,000 is the gross profit before any operating expenses are deducted. Profit for the year is lower."}}},{"id":"P1_U5_MCQ_1714","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1714","question":"Volta Rubber Ltd in Accra, Ghana, is preparing its statement of financial position and the trainee accountant is unsure which formula to use. Which formula correctly calculates the capital employed of the business?","options":{"A":"Current assets minus current liabilities","B":"Total equity plus non-current liabilities","C":"Revenue minus cost of sales","D":"Cash plus trade receivables"},"correctOption":"B","correctAnswer":"Total equity plus non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Capital employed represents the long-term funds invested in a business, calculated as total equity plus non-current liabilities. It shows the total resources providers have committed to Volta Rubber.","distractor_reasons":{"A":"Option A is wrong because current assets minus current liabilities gives working capital, a short-term measure. Capital employed concerns long-term financing rather than day-to-day liquidity.","B":"Capital employed represents the long-term funds invested in a business, calculated as total equity plus non-current liabilities. It shows the total resources providers have committed to Volta Rubber.","C":"Option C is wrong because revenue minus cost of sales produces gross profit, which appears in the profit and loss account, not a measure of invested capital.","D":"Option D is wrong because cash plus receivables is only part of current assets. It ignores equity and long-term borrowing entirely."}}},{"id":"P1_U5_MCQ_1715","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1715","question":"Santa Marta Logistics in Colombia reports revenue of $2,000,000 and profit for the year of $180,000. An investor wants to know how much profit is earned from each dollar of sales. What is its profit margin?","options":{"A":"10.0%","B":"18.0%","C":"9.0%","D":"90.0%"},"correctOption":"C","correctAnswer":"9.0%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year divided by revenue, expressed as a percentage. $180,000 divided by $2,000,000 equals 0.09, so Santa Marta Logistics earns a 9.0% profit margin.","distractor_reasons":{"A":"Option A is wrong because 10.0% would require profit of $200,000 on revenue of $2,000,000. The actual profit is $180,000, giving a lower margin.","B":"Option B is wrong because 18.0% comes from dividing profit by a figure of $1,000,000 rather than the full $2,000,000 of revenue.","C":"Profit margin is profit for the year divided by revenue, expressed as a percentage. $180,000 divided by $2,000,000 equals 0.09, so Santa Marta Logistics earns a 9.0% profit margin.","D":"Option D is wrong because 90.0% confuses the decimal result with a percentage. $180,000 over $2,000,000 is 0.09, which is 9.0%."}}},{"id":"P1_U5_MCQ_1716","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1716","question":"A technology startup in Tallinn, Estonia, is considering raising $1 million by issuing new ordinary shares. The founders want to weigh the drawbacks before proceeding. Which disadvantage of this source should they weigh most carefully?","options":{"A":"The money must be repaid within twelve months","B":"Interest payments reduce cash flow","C":"It cannot be used by private companies","D":"Existing owners lose some control and ownership"},"correctOption":"D","correctAnswer":"Existing owners lose some control and ownership","questionType":"MCQ","explanation":{"correct_reason":"Issuing ordinary shares brings permanent capital with no repayment duty, but it dilutes the ownership and voting power of existing shareholders. The founders in Tallinn would share control with new investors.","distractor_reasons":{"A":"Option A is wrong because share capital is permanent and does not have to be repaid. A twelve-month repayment term describes short-term debt, not equity.","B":"Option B is wrong because dividends are discretionary and shares carry no contractual interest charge. Interest payments arise on borrowed finance, not on ordinary shares.","C":"Option C is wrong because private limited companies can issue shares to investors. The restriction suggested does not apply to ordinary share capital.","D":"Issuing ordinary shares brings permanent capital with no repayment duty, but it dilutes the ownership and voting power of existing shareholders. The founders in Tallinn would share control with new investors."}}},{"id":"P1_U5_MCQ_1717","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1717","question":"Makeni Chemicals in Sierra Leone had an opening cash balance of -$12,000. During April it recorded net cash inflow of $18,500. The treasurer wants to know the month-end position. What was the closing cash balance?","options":{"A":"$6,500","B":"$30,500","C":"-$12,000","D":"$18,500"},"correctOption":"A","correctAnswer":"$6,500","questionType":"MCQ","explanation":{"correct_reason":"Closing balance equals opening balance plus net cash flow. Starting from an overdrawn -$12,000 and adding $18,500 leaves Makeni Chemicals with a positive closing balance of $6,500.","distractor_reasons":{"A":"Closing balance equals opening balance plus net cash flow. Starting from an overdrawn -$12,000 and adding $18,500 leaves Makeni Chemicals with a positive closing balance of $6,500.","B":"Option B is wrong because $30,500 results from ignoring the negative sign on the opening balance. The overdraft must be cleared before the balance becomes positive.","C":"Option C is wrong because -$12,000 is the opening position, not the closing one. The net inflow of $18,500 changes the balance during April.","D":"Option D is wrong because $18,500 is only the net cash flow. The closing balance must also reflect the overdrawn position at the start of the month."}}},{"id":"P1_U5_MCQ_1718","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1718","question":"A furniture retailer in Ljubljana, Slovenia, increased revenue by 20% but its gross profit stayed flat. The owner is puzzled by this result. Which is the most plausible explanation for what happened?","options":{"A":"Operating expenses rose","B":"Cost of sales rose by a similar amount to revenue","C":"The firm stopped selling on credit","D":"Interest rates fell"},"correctOption":"B","correctAnswer":"Cost of sales rose by a similar amount to revenue","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue less cost of sales, so if both rise together the margin can remain unchanged. A 20% increase in cost of sales alongside a 20% rise in revenue would leave Ljubljana's gross profit flat.","distractor_reasons":{"A":"Option A is wrong because operating expenses are subtracted after gross profit, so a change there cannot leave gross profit flat while revenue grows.","B":"Gross profit is revenue less cost of sales, so if both rise together the margin can remain unchanged. A 20% increase in cost of sales alongside a 20% rise in revenue would leave Ljubljana's gross profit flat.","C":"Option C is wrong because the mix of cash and credit sales affects cash flow, not the recognition of revenue and cost of sales in the profit and loss account.","D":"Option D is wrong because interest rates affect finance costs below gross profit and would not explain an unchanged gross profit figure."}}},{"id":"P1_U5_MCQ_1719","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1719","question":"Dalat Vegetables in Vietnam has non-current assets of $720,000, current assets of $180,000 and current liabilities of $120,000. There are no non-current liabilities. What are its net assets?","options":{"A":"$900,000","B":"$1,020,000","C":"$780,000","D":"$600,000"},"correctOption":"C","correctAnswer":"$780,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are $720,000 plus $180,000, or $900,000. Subtracting $120,000 of current liabilities gives net assets of $780,000 for Dalat Vegetables.","distractor_reasons":{"A":"Option A is wrong because $900,000 is the total of non-current and current assets before any liabilities are deducted. Net assets are what remains after obligations.","B":"Option B is wrong because $1,020,000 adds current liabilities to total assets. Liabilities reduce, rather than increase, the net worth of the business.","C":"Total assets are $720,000 plus $180,000, or $900,000. Subtracting $120,000 of current liabilities gives net assets of $780,000 for Dalat Vegetables.","D":"Option D is wrong because $600,000 subtracts current liabilities only from non-current assets, ignoring the $180,000 of current assets. For Dalat Vegetables, option C is correct: $780,000."}}},{"id":"P1_U5_MCQ_1720","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1720","question":"Kabul Textiles in Afghanistan reports operating profit of $96,000 and capital employed of $640,000. The owners want to judge how well their investment is performing. What is its return on capital employed?","options":{"A":"6.7%","B":"9.6%","C":"66.7%","D":"15.0%"},"correctOption":"D","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, times one hundred. $96,000 over $640,000 equals 0.15, so Kabul Textiles earns 15.0% on the funds invested.","distractor_reasons":{"A":"Option A is wrong because 6.7% reverses the division, dividing capital employed by operating profit. The ratio must compare profit with the capital used to generate it.","B":"Option B is wrong because 9.6% appears to treat $96,000 as a percentage of $1,000,000 rather than of the stated $640,000 capital employed.","C":"Option C is wrong because 66.7% results from a misplaced decimal when dividing $96,000 by $640,000. Careful division gives 0.15, or 15.0%.","D":"Return on capital employed is operating profit divided by capital employed, times one hundred. $96,000 over $640,000 equals 0.15, so Kabul Textiles earns 15.0% on the funds invested."}}},{"id":"P1_U5_MCQ_1721","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1721","question":"A wholesaler in Guayaquil, Ecuador, is offered thirty days to pay for stock delivered today. The finance manager wants to identify which source of finance this arrangement represents. Which source best describes it?","options":{"A":"Trade credit","B":"A debenture","C":"A share issue","D":"A bank loan"},"correctOption":"A","correctAnswer":"Trade credit","questionType":"MCQ","explanation":{"correct_reason":"Being allowed thirty days to pay for goods is trade credit, a short-term source supplied by the seller. Guayaquil's wholesaler obtains use of the stock before paying, improving short-term cash flow.","distractor_reasons":{"A":"Being allowed thirty days to pay for goods is trade credit, a short-term source supplied by the seller. Guayaquil's wholesaler obtains use of the stock before paying, improving short-term cash flow.","B":"Option B is wrong because a debenture is a long-term debt instrument issued by companies, usually secured on assets. It is not created by a supplier's payment terms.","C":"Option C is wrong because a share issue raises permanent equity from investors, not an interest-free delay in paying for deliveries. No ownership changes here.","D":"Option D is wrong because a bank loan involves borrowing money from a bank with agreed interest and repayment. The wholesaler simply pays the supplier later."}}},{"id":"P1_U5_MCQ_1722","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1722","question":"A shop in Windhoek, Namibia, forecasts net cash flow of -$4,000 in May and -$1,500 in June, starting with $9,000 cash. The owner wants to see the running total. What is its cumulative cash balance at the end of June?","options":{"A":"$5,000","B":"$3,500","C":"$13,000","D":"-$5,500"},"correctOption":"B","correctAnswer":"$3,500","questionType":"MCQ","explanation":{"correct_reason":"Cumulative balance starts at $9,000, falls to $5,000 after May's -$4,000, then to $3,500 after June's -$1,500. The shop in Windhoek still has positive cash at the end of June.","distractor_reasons":{"A":"Option A is wrong because $5,000 is the balance after May only. It ignores June's further net outflow of $1,500, so it cannot be the end-June cumulative figure.","B":"Cumulative balance starts at $9,000, falls to $5,000 after May's -$4,000, then to $3,500 after June's -$1,500. The shop in Windhoek still has positive cash at the end of June.","C":"Option C is wrong because $13,000 adds the outflows instead of subtracting them. Two months of negative net cash flow must reduce the opening balance.","D":"Option D is wrong because -$5,500 sums only the two monthly outflows and ignores the $9,000 opening cash. Cumulative cash includes the starting balance."}}},{"id":"P1_U5_MCQ_1723","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1723","question":"A bakery in Kraków, Poland, has revenue of $250,000 and gross profit of $75,000. The owner wants to know the proportion of sales left after direct costs. What is its gross profit margin?","options":{"A":"25.0%","B":"33.3%","C":"30.0%","D":"75.0%"},"correctOption":"C","correctAnswer":"30.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit divided by revenue, multiplied by one hundred. $75,000 divided by $250,000 equals 0.30, giving a gross profit margin of 30.0% in Kraków.","distractor_reasons":{"A":"Option A is wrong because 25.0% would require gross profit of $62,500 on $250,000 revenue. The reported gross profit is higher at $75,000.","B":"Option B is wrong because 33.3% divides gross profit by the $225,000 that is not the revenue figure. The correct denominator is $250,000.","C":"Gross profit margin is gross profit divided by revenue, multiplied by one hundred. $75,000 divided by $250,000 equals 0.30, giving a gross profit margin of 30.0% in Kraków.","D":"Option D is wrong because 75.0% mistakes the gross profit amount in thousands for a percentage. The margin compares that profit with revenue."}}},{"id":"P1_U5_MCQ_1724","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1724","question":"A firm in Bilbao, Spain, is checking that its statement of financial position has been drawn up correctly. Which equation must always balance in a correctly prepared statement of financial position?","options":{"A":"Revenue = expenses + profit","B":"Gross profit = revenue - operating expenses","C":"Assets + liabilities = equity","D":"Assets = equity + liabilities"},"correctOption":"D","correctAnswer":"Assets = equity + liabilities","questionType":"MCQ","explanation":{"correct_reason":"The statement of financial position follows the accounting equation that assets equal equity plus liabilities. Every resource owned by the Bilbao firm is funded either by owners or by creditors.","distractor_reasons":{"A":"Option A is wrong because that relationship belongs to the profit and loss account, not the statement of financial position. It describes income measurement.","B":"Option B is wrong because gross profit equals revenue minus cost of sales, not operating expenses. It is also an income statement relationship.","C":"Option C is wrong because it places liabilities on the wrong side of the equation. Assets are financed by equity and liabilities combined, not the reverse.","D":"The statement of financial position follows the accounting equation that assets equal equity plus liabilities. Every resource owned by the Bilbao firm is funded either by owners or by creditors."}}},{"id":"P1_U5_MCQ_1725","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1725","question":"A company in Porto, Portugal, has a current ratio of 0.8 : 1. The management team wants to interpret what this means. What does this most clearly indicate about its short-term position?","options":{"A":"It may struggle to meet short-term debts from current assets","B":"It has no long-term liabilities","C":"Its profitability is poor","D":"It has excess cash"},"correctOption":"A","correctAnswer":"It may struggle to meet short-term debts from current assets","questionType":"MCQ","explanation":{"correct_reason":"A current ratio below one means current assets are less than current liabilities, so Porto's firm may struggle to settle near-term obligations from its current resources without extra finance.","distractor_reasons":{"A":"A current ratio below one means current assets are less than current liabilities, so Porto's firm may struggle to settle near-term obligations from its current resources without extra finance.","B":"Option B is wrong because the current ratio compares current assets with current liabilities and says nothing about long-term debt. That would require other figures.","C":"Option C is wrong because liquidity ratios measure short-term solvency, not profitability. A firm can be profitable yet illiquid, or the reverse.","D":"Option D is wrong because a ratio below one suggests scarce liquid resources rather than excess cash. Surplus cash would push the ratio well above one."}}},{"id":"P1_U5_MCQ_1726","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1726","question":"A farm cooperative in Nairobi, Kenya, uses money accumulated from past surpluses to buy a tractor. The members want to classify this source correctly. Which category of finance does this illustrate?","options":{"A":"External debt","B":"Internal finance","C":"Bank borrowing","D":"New equity"},"correctOption":"B","correctAnswer":"Internal finance","questionType":"MCQ","explanation":{"correct_reason":"Using accumulated past surpluses, or retained earnings, is internal finance because the funds come from within the cooperative. No outside lender or investor is involved in buying the tractor.","distractor_reasons":{"A":"Option A is wrong because external debt involves borrowing from banks or other lenders. Retained surpluses are already owned by the cooperative.","B":"Using accumulated past surpluses, or retained earnings, is internal finance because the funds come from within the cooperative. No outside lender or investor is involved in buying the tractor.","C":"Option C is wrong because bank borrowing creates a liability and interest charges, none of which arise when past profits are reinvested.","D":"Option D is wrong because new equity means issuing ownership stakes to investors. Reinvesting surpluses leaves the membership structure unchanged."}}},{"id":"P1_U5_MCQ_1727","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1727","question":"Why would a hotel in Varanasi, India, prepare a monthly cash flow forecast before the monsoon season? The manager wants to plan ahead for the quieter months.","options":{"A":"To calculate its annual profit exactly","B":"To determine its market share","C":"To anticipate periods when cash may run short","D":"To value its non-current assets"},"correctOption":"C","correctAnswer":"To anticipate periods when cash may run short","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast predicts inflows and outflows so the hotel can spot likely shortages before they happen. Seasonal demand swings make advance warning of tight cash especially valuable in Varanasi.","distractor_reasons":{"A":"Option A is wrong because a cash flow forecast tracks money moving in and out, not accounting profit. Profit is measured in the profit and loss account.","B":"Option B is wrong because market share concerns sales relative to competitors, a marketing matter unrelated to forecasting cash balances.","C":"A cash flow forecast predicts inflows and outflows so the hotel can spot likely shortages before they happen. Seasonal demand swings make advance warning of tight cash especially valuable in Varanasi.","D":"Option D is wrong because valuing non-current assets is an accounting measurement issue, not the purpose of projecting short-term cash movements."}}},{"id":"P1_U5_MCQ_1728","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1728","question":"Tashkent Foods in Uzbekistan has revenue of $960,000, cost of sales of $540,000 and profit for the year of $210,000. The accountant is reconstructing the profit and loss account. What are its operating expenses?","options":{"A":"$420,000","B":"$750,000","C":"$150,000","D":"$210,000"},"correctOption":"D","correctAnswer":"$210,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $960,000 less $540,000, or $420,000. Profit for the year is $210,000, so operating expenses of $210,000 were deducted between the two figures at Tashkent Foods.","distractor_reasons":{"A":"Option A is wrong because $420,000 is the gross profit, calculated before operating expenses. It is not the expense figure itself.","B":"Option B is wrong because $750,000 adds cost of sales and profit for the year, which has no meaning in the profit and loss layout.","C":"Option C is wrong because $150,000 would leave profit of $270,000 rather than the reported $210,000. The correct expenses are $210,000.","D":"Gross profit is $960,000 less $540,000, or $420,000. Profit for the year is $210,000, so operating expenses of $210,000 were deducted between the two figures at Tashkent Foods."}}},{"id":"P1_U5_MCQ_1729","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1729","question":"A retailer in Adelaide, Australia, has current assets of $330,000 and working capital of $95,000. Its bookkeeper wants to find the missing figure. What are its current liabilities?","options":{"A":"$235,000","B":"$425,000","C":"$95,000","D":"$330,000"},"correctOption":"A","correctAnswer":"$235,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital equals current assets minus current liabilities, so current liabilities are $330,000 minus $95,000, giving $235,000 for the Adelaide retailer.","distractor_reasons":{"A":"Working capital equals current assets minus current liabilities, so current liabilities are $330,000 minus $95,000, giving $235,000 for the Adelaide retailer.","B":"Option B is wrong because $425,000 adds working capital to current assets. The correct operation subtracts working capital to isolate the liabilities.","C":"Option C is wrong because $95,000 is the working capital itself, not the liabilities. It is the result of the subtraction, not an input.","D":"Option D is wrong because $330,000 is the current assets total. Liabilities must be lower for working capital to be positive."}}},{"id":"P1_U5_MCQ_1730","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1730","question":"A manufacturer in Monterrey, Mexico, has current assets of $960,000 and a current ratio of 1.6 : 1. The finance director needs the corresponding liability figure. What are its current liabilities?","options":{"A":"$1,536,000","B":"$960,000","C":"$600,000","D":"$160,000"},"correctOption":"C","correctAnswer":"$600,000","questionType":"MCQ","explanation":{"correct_reason":"Current liabilities equal current assets divided by the current ratio. $960,000 divided by 1.6 gives $600,000, the short-term obligations of the Monterrey manufacturer.","distractor_reasons":{"A":"Option A is wrong because $1,536,000 multiplies current assets by the ratio. To isolate liabilities, the ratio must be used as a divisor.","B":"Option B is wrong because $960,000 is the current assets figure. A ratio of 1.6 : 1 means liabilities are lower than assets.","C":"Current liabilities equal current assets divided by the current ratio. $960,000 divided by 1.6 gives $600,000, the short-term obligations of the Monterrey manufacturer.","D":"Option D is wrong because $160,000 does not equal $960,000 divided by 1.6. The correct result of that division is $600,000."}}},{"id":"P1_U5_MCQ_1731","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1731","question":"A courier firm in Cebu, Philippines, needs vans but wants to avoid a large immediate purchase and still use the vehicles. The manager is comparing finance options. Which source fits this requirement best?","options":{"A":"Issue of ordinary shares","B":"Retained profit","C":"Leasing","D":"Trade credit"},"correctOption":"C","correctAnswer":"Leasing","questionType":"MCQ","explanation":{"correct_reason":"Leasing lets the courier use vans while paying regular rentals, avoiding a large upfront cost. It is a form of medium-term finance suited to assets that the firm needs but does not wish to buy outright in Cebu.","distractor_reasons":{"A":"Option A is wrong because issuing shares raises permanent ownership finance for major expansion, not a way to obtain use of delivery vans without buying them.","B":"Option B is wrong because retained profit would require existing funds to purchase the vans outright, which is exactly the large immediate outlay the firm wants to avoid.","C":"Leasing lets the courier use vans while paying regular rentals, avoiding a large upfront cost. It is a form of medium-term finance suited to assets that the firm needs but does not wish to buy outright in Cebu.","D":"Option D is wrong because trade credit delays payment for goods from suppliers, but it does not provide ongoing use of vehicles under a rental agreement."}}},{"id":"P1_U5_MCQ_1732","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1732","question":"A workshop in Fez, Morocco, has an opening cash balance of $6,000, net cash inflow of $2,000 in July, and net outflow of $5,000 in August. What is the cumulative balance after August?","options":{"A":"$13,000","B":"$1,000","C":"$8,000","D":"$3,000"},"correctOption":"D","correctAnswer":"$3,000","questionType":"MCQ","explanation":{"correct_reason":"Starting with $6,000, July's $2,000 inflow raises the balance to $8,000, and August's $5,000 outflow reduces it to $3,000. That is the workshop's cumulative cash balance in Fez.","distractor_reasons":{"A":"Option A is wrong because $13,000 adds all the absolute amounts together. The August outflow must be subtracted, not added, to find the true cumulative position.","B":"Option B is wrong because $1,000 results from miscalculating the sequence of flows. Carefully applying July then August gives $3,000.","C":"Option C is wrong because $8,000 is the balance after July only. It ignores the subsequent $5,000 outflow in August.","D":"Starting with $6,000, July's $2,000 inflow raises the balance to $8,000, and August's $5,000 outflow reduces it to $3,000. That is the workshop's cumulative cash balance in Fez."}}},{"id":"P1_U5_MCQ_1733","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1733","question":"Which of the following would be included in the cost of sales of a clothing manufacturer in Izmir, Turkey? The accountant is separating direct and indirect costs.","options":{"A":"The cost of fabric used to make garments","B":"Advertising expenditure","C":"Interest on a bank loan","D":"Dividends paid to shareholders"},"correctOption":"A","correctAnswer":"The cost of fabric used to make garments","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales contains the direct costs of producing the goods sold, such as the fabric used in each garment. Advertising, interest and dividends are not direct production costs for Izmir's manufacturer.","distractor_reasons":{"A":"Cost of sales contains the direct costs of producing the goods sold, such as the fabric used in each garment. Advertising, interest and dividends are not direct production costs for Izmir's manufacturer.","B":"Option B is wrong because advertising is a selling expense deducted from gross profit as an operating expense, not part of the direct cost of making garments.","C":"Option C is wrong because interest is a finance cost charged after operating profit. It is not included in the cost of sales calculation.","D":"Option D is wrong because dividends are distributions of profit to owners, an appropriation shown after profit for the year, not a production cost."}}},{"id":"P1_U5_MCQ_1734","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1734","question":"A supermarket chain in Zagreb, Croatia, is classifying its obligations for the year-end accounts. The accountant wants a clear answer. Which item is a current liability for the business?","options":{"A":"A loan due in ten years","B":"Amounts owed to suppliers","C":"Land and buildings","D":"Share capital"},"correctOption":"B","correctAnswer":"Amounts owed to suppliers","questionType":"MCQ","explanation":{"correct_reason":"Amounts owed to suppliers, or trade payables, must normally be settled within a year, so they are current liabilities. The Zagreb supermarket expects to pay these from normal trading cash.","distractor_reasons":{"A":"Option A is wrong because a loan due in ten years is a non-current liability. Its long repayment term places it outside current obligations.","B":"Amounts owed to suppliers, or trade payables, must normally be settled within a year, so they are current liabilities. The Zagreb supermarket expects to pay these from normal trading cash.","C":"Option C is wrong because land and buildings are non-current assets owned by the business, not amounts owed to outsiders.","D":"Option D is wrong because share capital is equity, representing the owners' investment rather than a liability to be repaid."}}},{"id":"P1_U5_MCQ_1735","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1735","question":"A pharmaceutical firm in Basel, Switzerland, has current assets of $1,250,000 and current liabilities of $500,000. A bank is assessing its liquidity. What is its current ratio?","options":{"A":"0.4 : 1","B":"1.5 : 1","C":"2.5 : 1","D":"4.0 : 1"},"correctOption":"C","correctAnswer":"2.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Dividing current assets of $1,250,000 by current liabilities of $500,000 gives a current ratio of 2.5 : 1, meaning the Basel firm holds $2.50 of current assets per dollar of short-term debt.","distractor_reasons":{"A":"Option A is wrong because 0.4 : 1 reverses the formula, dividing liabilities by assets. That would wrongly imply a severe liquidity problem.","B":"Option B is wrong because 1.5 : 1 does not arise from dividing $1,250,000 by $500,000. The correct quotient of those figures is 2.5.","C":"Dividing current assets of $1,250,000 by current liabilities of $500,000 gives a current ratio of 2.5 : 1, meaning the Basel firm holds $2.50 of current assets per dollar of short-term debt.","D":"Option D is wrong because 4.0 : 1 would need current assets of $2,000,000. The stated current assets are lower, so the ratio is smaller."}}},{"id":"P1_U5_MCQ_1736","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1736","question":"A renewable energy firm in Santiago, Chile, receives a government payment to install solar panels, which it does not have to repay. What type of finance is this?","options":{"A":"A bank loan","B":"A debenture","C":"An overdraft","D":"A grant"},"correctOption":"D","correctAnswer":"A grant","questionType":"MCQ","explanation":{"correct_reason":"A grant is a sum received from government or an agency that need not be repaid, so it is a valuable source of finance for the Santiago solar project. It differs from loans and overdrafts.","distractor_reasons":{"A":"Option A is wrong because a bank loan must be repaid with interest, whereas the payment described requires no repayment at all.","B":"Option B is wrong because a debenture is a long-term debt security issued to investors and carries a duty to repay, unlike a grant.","C":"Option C is wrong because an overdraft is a repayable short-term facility, not a non-repayable contribution to the cost of solar panels.","D":"A grant is a sum received from government or an agency that need not be repaid, so it is a valuable source of finance for the Santiago solar project. It differs from loans and overdrafts."}}},{"id":"P1_U5_MCQ_1737","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1737","question":"A manufacturer in Gdańsk, Poland, wants to improve its cash flow quickly by changing how it manages working capital. Which action would help most directly to bring money into the business sooner?","options":{"A":"Offering early-payment discounts to credit customers","B":"Increasing the stock held in the warehouse","C":"Buying more raw materials on cash terms","D":"Paying suppliers earlier than required"},"correctOption":"A","correctAnswer":"Offering early-payment discounts to credit customers","questionType":"MCQ","explanation":{"correct_reason":"Early-payment discounts encourage credit customers to settle sooner, speeding up cash inflows for the Gdańsk manufacturer. The other options would either tie up cash or send it out earlier.","distractor_reasons":{"A":"Early-payment discounts encourage credit customers to settle sooner, speeding up cash inflows for the Gdańsk manufacturer. The other options would either tie up cash or send it out earlier.","B":"Option B is wrong because holding more stock ties up cash in inventories without generating an immediate return. It would worsen, not improve, cash flow.","C":"Option C is wrong because paying cash for raw materials sends money out immediately. Using available credit would preserve cash longer.","D":"Option D is wrong because paying suppliers earlier than required sends cash out sooner, reducing the firm's bank balance. Delaying payments would help, not paying promptly."}}},{"id":"P1_U5_MCQ_1738","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1738","question":"A confectionery maker in Turin, Italy, has cost of sales of $420,000 and gross profit of $280,000. The owner wants to find the total sales value. What is its revenue?","options":{"A":"$140,000","B":"$700,000","C":"$420,000","D":"$280,000"},"correctOption":"B","correctAnswer":"$700,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals cost of sales plus gross profit. Adding $420,000 and $280,000 gives $700,000, the total sales value recorded by the Turin confectionery maker during the year.","distractor_reasons":{"A":"Option A is wrong because $140,000 is the difference between the two figures. Revenue is found by adding cost of sales to gross profit, not subtracting.","B":"Revenue equals cost of sales plus gross profit. Adding $420,000 and $280,000 gives $700,000, the total sales value recorded by the Turin confectionery maker during the year.","C":"Option C is wrong because $420,000 is only the cost of sales. Revenue must cover both that cost and the gross profit earned.","D":"Option D is wrong because $280,000 is the gross profit alone, the surplus after costs, not the total sales revenue."}}},{"id":"P1_U5_MCQ_1739","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1739","question":"Which item forms part of the equity of a business in Bratislava, Slovakia? The bookkeeper is separating owners' claims from those of outside parties and wants to be sure. Which option is correct?","options":{"A":"Trade payables","B":"Bank overdraft","C":"Retained earnings","D":"Accrued expenses"},"correctOption":"C","correctAnswer":"Retained earnings","questionType":"MCQ","explanation":{"correct_reason":"Retained earnings are profits kept in the business and belong to the owners, so they are part of equity. Payables, overdrafts and accruals are all liabilities of the Bratislava business.","distractor_reasons":{"A":"Option A is wrong because trade payables are amounts owed to suppliers, a current liability, not a claim of the owners on the business.","B":"Option B is wrong because an overdraft is a short-term borrowing from a bank and must be repaid, making it a liability rather than equity.","C":"Retained earnings are profits kept in the business and belong to the owners, so they are part of equity. Payables, overdrafts and accruals are all liabilities of the Bratislava business.","D":"Option D is wrong because accrued expenses are costs incurred but not yet paid, so they represent a liability to other parties."}}},{"id":"P1_U5_MCQ_1740","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1740","question":"A hardware chain in Winnipeg, Canada, has current assets of $540,000 including $180,000 of inventory, and current liabilities of $240,000. A supplier wants a strict liquidity test. What is its acid test ratio?","options":{"A":"2.25 : 1","B":"0.75 : 1","C":"1.0 : 1","D":"1.5 : 1"},"correctOption":"D","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test removes inventory from current assets. Liquid assets are $540,000 less $180,000, or $360,000, and dividing by $240,000 of current liabilities gives 1.5 : 1 in Winnipeg.","distractor_reasons":{"A":"Option A is wrong because 2.25 : 1 is the current ratio using all current assets. The acid test excludes the $180,000 of stock first.","B":"Option B is wrong because 0.75 : 1 reverses the division or misuses the figures. Liquid assets of $360,000 exceed current liabilities of $240,000.","C":"Option C is wrong because 1.0 : 1 would require liquid assets equal to current liabilities. Here they are $360,000 against $240,000.","D":"The acid test removes inventory from current assets. Liquid assets are $540,000 less $180,000, or $360,000, and dividing by $240,000 of current liabilities gives 1.5 : 1 in Winnipeg."}}},{"id":"P1_U5_MCQ_1741","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1741","question":"A fast-growing software firm in Belgrade, Serbia, needs a large sum to expand internationally but cannot offer collateral. The founders are seeking outside investment. Which source is most likely to be interested?","options":{"A":"Venture capital","B":"A secured bank loan","C":"Trade credit","D":"A bank overdraft"},"correctOption":"A","correctAnswer":"Venture capital","questionType":"MCQ","explanation":{"correct_reason":"Venture capitalists provide equity finance to high-growth firms that lack collateral, taking a stake in return. That makes such investment suitable for the Belgrade software company's international expansion.","distractor_reasons":{"A":"Venture capitalists provide equity finance to high-growth firms that lack collateral, taking a stake in return. That makes such investment suitable for the Belgrade software company's international expansion.","B":"Option B is wrong because a secured bank loan requires collateral, which the firm cannot offer. Without assets to pledge, this route is closed.","C":"Option C is wrong because trade credit is a short-term supplier arrangement for buying goods, not a source of large expansion capital.","D":"Option D is wrong because an overdraft is a small short-term facility for temporary gaps, not the large long-term funding needed for overseas growth."}}},{"id":"P1_U5_MCQ_1742","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1742","question":"A café in Ljubljana, Slovenia, ended September with a cash balance of $8,400. During September it had net cash outflow of $1,900. The manager wants to reconstruct the start of the month. What was its opening cash balance?","options":{"A":"$6,500","B":"$10,300","C":"$8,400","D":"$1,900"},"correctOption":"B","correctAnswer":"$10,300","questionType":"MCQ","explanation":{"correct_reason":"Closing balance equals opening balance plus net cash flow. Rearranging, opening balance is $8,400 minus -$1,900, which is $10,300 for the Ljubljana café at the start of September.","distractor_reasons":{"A":"Option A is wrong because $6,500 subtracts the outflow magnitude from the closing balance. A net outflow means the opening balance was higher, not lower.","B":"Closing balance equals opening balance plus net cash flow. Rearranging, opening balance is $8,400 minus -$1,900, which is $10,300 for the Ljubljana café at the start of September.","C":"Option C is wrong because $8,400 is the closing balance, not the opening one. Cash fell during the month, so the earlier figure must be larger.","D":"Option D is wrong because $1,900 is simply the net outflow. It is a component of the calculation, not the opening cash position."}}},{"id":"P1_U5_MCQ_1743","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1743","question":"What is the key difference between gross profit and profit for the year in the accounts of a firm in Durban, South Africa? A new bookkeeper has asked for clarification.","options":{"A":"Gross profit includes finance costs but profit for the year does not","B":"They are always equal","C":"Gross profit is before operating expenses; profit for the year is after them","D":"Profit for the year is calculated before cost of sales"},"correctOption":"C","correctAnswer":"Gross profit is before operating expenses; profit for the year is after them","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, while profit for the year subtracts operating expenses and finance costs as well. The Durban firm's final profit is therefore lower than its gross profit.","distractor_reasons":{"A":"Option A is wrong because finance costs are deducted after operating profit, below gross profit, so gross profit excludes them while final profit includes them.","B":"Option B is wrong because the two figures differ whenever the business has operating expenses or finance costs. They are rarely equal.","C":"Gross profit is revenue minus cost of sales, while profit for the year subtracts operating expenses and finance costs as well. The Durban firm's final profit is therefore lower than its gross profit.","D":"Option D is wrong because cost of sales is deducted first in arriving at gross profit, so profit for the year is calculated after, not before, that deduction."}}},{"id":"P1_U5_MCQ_1744","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1744","question":"Which of these is a non-current liability for a construction company in Kraków, Poland? The accountant is sorting obligations by their repayment dates and needs one clear example. Which item fits?","options":{"A":"Trade payables","B":"Overdraft","C":"Accrued wages","D":"A mortgage due in 2035"},"correctOption":"D","correctAnswer":"A mortgage due in 2035","questionType":"MCQ","explanation":{"correct_reason":"A mortgage repayable in 2035 is a long-term obligation, so it is a non-current liability. Trade payables, overdrafts and accrued wages are all expected to be settled within a year.","distractor_reasons":{"A":"Option A is wrong because trade payables are usually settled within the normal trading cycle, making them current liabilities. Option D is correct: a mortgage due in 2035, which the scenario supports.","B":"Option B is wrong because an overdraft is repayable on demand and is treated as a short-term source of finance.","C":"Option C is wrong because accrued wages are costs owed to employees for the current period and must be paid shortly.","D":"A mortgage repayable in 2035 is a long-term obligation, so it is a non-current liability. Trade payables, overdrafts and accrued wages are all expected to be settled within a year."}}},{"id":"P1_U5_MCQ_1745","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1745","question":"A retailer in Kyoto, Japan, reported a profit margin of 8.5% last year and 6.0% this year. An analyst wants the absolute change. By how many percentage points did the margin fall?","options":{"A":"2.5 percentage points","B":"2.5%","C":"14.5 percentage points","D":"1.5 percentage points"},"correctOption":"A","correctAnswer":"2.5 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The change is found by subtracting this year's 6.0% from last year's 8.5%, a fall of 2.5 percentage points of revenue. This measures the absolute change in the Kyoto retailer's margin.","distractor_reasons":{"A":"The change is found by subtracting this year's 6.0% from last year's 8.5%, a fall of 2.5 percentage points of revenue. This measures the absolute change in the Kyoto retailer's margin.","B":"Option B is wrong because 2.5% would suggest a relative percentage change, not a change in percentage points. The absolute difference is 2.5 points.","C":"Option C is wrong because 14.5 percentage points adds the two margins instead of subtracting them. A fall requires taking one away from the other.","D":"Option D is wrong because 1.5 percentage points does not equal 8.5 minus 6.0. The correct difference between the two margins is 2.5 points."}}},{"id":"P1_U5_MCQ_1746","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1746","question":"A partnership in Cork, Ireland, is debating whether to use retained profit or a bank loan to fund new equipment. Which statement about these two sources of finance is correct?","options":{"A":"Both give the bank control over the business","B":"Retained profit is internal; a bank loan is external finance","C":"Neither has any cost to the business","D":"A bank loan dilutes the partners' ownership"},"correctOption":"B","correctAnswer":"Retained profit is internal; a bank loan is external finance","questionType":"MCQ","explanation":{"correct_reason":"Retained profit comes from within the business and is internal finance, whereas a bank loan is provided by an outside lender and is external. The distinction is about where the funds originate.","distractor_reasons":{"A":"Option A is wrong because retained profit involves no lender and gives the bank no control. Only the loan creates a relationship with the bank.","B":"Retained profit comes from within the business and is internal finance, whereas a bank loan is provided by an outside lender and is external. The distinction is about where the funds originate.","C":"Option C is wrong because a bank loan carries interest and retained profit has an opportunity cost, so neither source is truly cost-free.","D":"Option D is wrong because a bank loan is debt, not equity, so the partners' ownership stakes are unchanged by borrowing."}}},{"id":"P1_U5_MCQ_1747","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1747","question":"A business in Porto Alegre, Brazil, is selling plenty of goods but keeps running out of cash. The owner has asked the finance team to find the cause. Which explanation is most likely?","options":{"A":"It sells only for cash","B":"It has very low sales volume","C":"It offers long credit terms to customers","D":"It has no cost of sales"},"correctOption":"C","correctAnswer":"It offers long credit terms to customers","questionType":"MCQ","explanation":{"correct_reason":"Generating sales on long credit terms means cash arrives much later than the sale is recorded, so strong revenue can coexist with a cash squeeze. That fits the Porto Alegre firm's situation.","distractor_reasons":{"A":"Option A is wrong because cash sales bring money in immediately and would ease a cash shortage, not cause one.","B":"Option B is wrong because the firm is reported to be selling plenty, so low volume cannot explain its difficulty.","C":"Generating sales on long credit terms means cash arrives much later than the sale is recorded, so strong revenue can coexist with a cash squeeze. That fits the Porto Alegre firm's situation.","D":"Option D is wrong because having no cost of sales would leave more cash in the business, not less. It would improve liquidity."}}},{"id":"P1_U5_MCQ_1748","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1748","question":"An electronics shop in Taipei, Taiwan, had revenue of $730,000 and cost of sales of $438,000. The owner wants the surplus left before overheads. What was its gross profit?","options":{"A":"$1,168,000","B":"$438,000","C":"$365,000","D":"$292,000"},"correctOption":"D","correctAnswer":"$292,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue of $730,000 less cost of sales of $438,000, giving $292,000 for the Taipei electronics shop before operating expenses are subtracted.","distractor_reasons":{"A":"Option A is wrong because $1,168,000 adds the two figures. Cost of sales must be deducted from revenue, not added to it, to find gross profit.","B":"Option B is wrong because $438,000 is the cost of sales itself. It is the amount to be subtracted, not the resulting gross profit.","C":"Option C is wrong because $365,000 is half the revenue and does not follow from subtracting $438,000 from $730,000. For an electronics shop, option D is correct: $292,000.","D":"Gross profit is revenue of $730,000 less cost of sales of $438,000, giving $292,000 for the Taipei electronics shop before operating expenses are subtracted."}}},{"id":"P1_U5_MCQ_1749","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1749","question":"A logistics firm in Rotterdam, Netherlands, has non-current assets of $1,400,000 and current assets of $350,000. What is the total value of its assets on the statement of financial position?","options":{"A":"$1,750,000","B":"$1,050,000","C":"$350,000","D":"$1,400,000"},"correctOption":"A","correctAnswer":"$1,750,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are the sum of non-current and current assets. Adding $1,400,000 and $350,000 gives $1,750,000 for the Rotterdam logistics firm's statement of financial position.","distractor_reasons":{"A":"Total assets are the sum of non-current and current assets. Adding $1,400,000 and $350,000 gives $1,750,000 for the Rotterdam logistics firm's statement of financial position.","B":"Option B is wrong because $1,050,000 subtracts current assets from non-current assets. Total assets require the two categories to be added together.","C":"Option C is wrong because $350,000 is only the current assets figure and ignores the larger non-current asset base. For a logistics firm, option A is correct: $1,750,000.","D":"Option D is wrong because $1,400,000 covers only non-current assets. Total assets must also include current assets. For a logistics firm, option A is correct: $1,750,000."}}},{"id":"P1_U5_MCQ_1750","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1750","question":"A paper mill in Oulu, Finland, has capital employed of $800,000 and operating profit of $104,000. The board wants to see the return generated on the funds invested. What is its return on capital employed?","options":{"A":"7.7%","B":"13.0%","C":"76.9%","D":"10.4%"},"correctOption":"B","correctAnswer":"13.0%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, times one hundred. $104,000 over $800,000 equals 0.13, so Oulu's mill returns 13.0%.","distractor_reasons":{"A":"Option A is wrong because 7.7% reverses the division, putting capital employed over profit. The ratio should measure profit earned per unit of capital.","B":"Return on capital employed is operating profit divided by capital employed, times one hundred. $104,000 over $800,000 equals 0.13, so Oulu's mill returns 13.0%.","C":"Option C is wrong because 76.9% comes from an incorrect division and misplaced decimal point. The correct fraction is 104/800, which is 0.13.","D":"Option D is wrong because 10.4% treats $104,000 as a share of $1,000,000 rather than the actual $800,000 capital employed."}}},{"id":"P1_U5_MCQ_1751","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1751","question":"A large company in Antwerp, Belgium, wants to raise long-term debt from several investors without giving them voting rights. The finance director is comparing instruments. Which instrument is suitable?","options":{"A":"Ordinary shares","B":"Preference shares that carry votes","C":"Debentures","D":"Trade credit"},"correctOption":"C","correctAnswer":"Debentures","questionType":"MCQ","explanation":{"correct_reason":"Debentures are long-term debt securities that can be sold to many investors and do not confer voting rights, making them suitable for the Antwerp company's fundraising needs.","distractor_reasons":{"A":"Option A is wrong because ordinary shares are equity and give holders voting rights, the opposite of what the company wants.","B":"Option B is wrong because preference shares that carry votes would still give investors a say in the business, unlike pure debt finance.","C":"Debentures are long-term debt securities that can be sold to many investors and do not confer voting rights, making them suitable for the Antwerp company's fundraising needs.","D":"Option D is wrong because trade credit is short-term supplier finance and cannot supply long-term capital from several investors. For a large company, option C is correct: debentures."}}},{"id":"P1_U5_MCQ_1752","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1752","question":"A printing firm in Brno, Czechia, forecasts inflows of $58,000 and outflows of $66,500 for August. The manager wants the net movement for the month. What is its net cash flow?","options":{"A":"$124,500","B":"$8,500","C":"$58,000","D":"-$8,500"},"correctOption":"D","correctAnswer":"-$8,500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is inflows minus outflows. With $58,000 received and $66,500 paid, the Brno printing firm records a net cash outflow of $8,500 during August.","distractor_reasons":{"A":"Option A is wrong because $124,500 adds inflows and outflows. Net cash flow is the difference between them, not their combined total.","B":"Option B is wrong because $8,500 is the right magnitude but the wrong sign. Outflows exceed inflows, so the net figure is negative.","C":"Option C is wrong because $58,000 is only the inflow amount. The outflows of $66,500 must be taken into account.","D":"Net cash flow is inflows minus outflows. With $58,000 received and $66,500 paid, the Brno printing firm records a net cash outflow of $8,500 during August."}}},{"id":"P1_U5_MCQ_1753","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1753","question":"Which item would be classified as an operating expense in the profit and loss account of a hotel in Nice, France? The accountant is distinguishing overheads from direct costs.","options":{"A":"Salaries of reception staff","B":"The cost of food served to guests","C":"Purchase of a new hotel building","D":"Dividends to shareholders"},"correctOption":"A","correctAnswer":"Salaries of reception staff","questionType":"MCQ","explanation":{"correct_reason":"Reception staff salaries are overheads incurred in running the hotel, deducted from gross profit as operating expenses. Food costs are direct cost of sales, while buildings are assets.","distractor_reasons":{"A":"Reception staff salaries are overheads incurred in running the hotel, deducted from gross profit as operating expenses. Food costs are direct cost of sales, while buildings are assets.","B":"Option B is wrong because the cost of food served is a direct cost of the service provided, so it belongs in cost of sales, not operating expenses.","C":"Option C is wrong because buying a building acquires a non-current asset, not an expense in the profit and loss account for the period.","D":"Option D is wrong because dividends are appropriations of profit paid to owners after profit for the year has been calculated."}}},{"id":"P1_U5_MCQ_1754","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1754","question":"Which of the following is a current asset of a bookshop in Uppsala, Sweden? The owner is listing items in order of liquidity and wants one clear example. Which option fits?","options":{"A":"The shop's delivery van","B":"Unsold books in stock","C":"A loan due in 2030","D":"Share capital"},"correctOption":"B","correctAnswer":"Unsold books in stock","questionType":"MCQ","explanation":{"correct_reason":"Unsold books are inventories held for sale and are expected to be sold within the trading year, so they are current assets. The van is a non-current asset and the loan is a liability.","distractor_reasons":{"A":"Option A is wrong because a delivery van is used repeatedly over several years and is therefore a non-current asset of the Uppsala bookshop.","B":"Unsold books are inventories held for sale and are expected to be sold within the trading year, so they are current assets. The van is a non-current asset and the loan is a liability.","C":"Option C is wrong because a loan due in 2030 is a long-term liability, not an asset of any kind.","D":"Option D is wrong because share capital is equity, representing the owners' stake rather than an asset held by the business."}}},{"id":"P1_U5_MCQ_1755","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1755","question":"A manufacturer in Monterrey, Mexico, has current assets of $960,000 and a current ratio of 1.6 : 1. The analyst wants to recover the liability figure. What are its current liabilities?","options":{"A":"$1,536,000","B":"$960,000","C":"$600,000","D":"$160,000"},"correctOption":"C","correctAnswer":"$600,000","questionType":"MCQ","explanation":{"correct_reason":"Current liabilities equal current assets divided by the current ratio. $960,000 divided by 1.6 gives $600,000, the short-term obligations of the Monterrey manufacturer.","distractor_reasons":{"A":"Option A is wrong because $1,536,000 multiplies current assets by the ratio. To isolate liabilities, the ratio must be used as a divisor.","B":"Option B is wrong because $960,000 is the current assets figure. A ratio of 1.6 : 1 means liabilities are lower than assets.","C":"Current liabilities equal current assets divided by the current ratio. $960,000 divided by 1.6 gives $600,000, the short-term obligations of the Monterrey manufacturer.","D":"Option D is wrong because $160,000 does not equal $960,000 divided by 1.6. The correct result of that division is $600,000."}}},{"id":"P1_U5_MCQ_1756","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1756","question":"A company in Malmö, Sweden, earns $200,000 profit and pays $50,000 in dividends, keeping the rest for expansion. How much is retained in the business?","options":{"A":"$250,000","B":"$200,000","C":"$50,000","D":"$150,000"},"correctOption":"D","correctAnswer":"$150,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is profit for the year less dividends paid. Keeping $150,000 from $200,000 after a $50,000 dividend, the Malmö company strengthens its internal finance for future investment.","distractor_reasons":{"A":"Option A is wrong because $250,000 adds the dividend to profit. Dividends are paid out and must be deducted from profit to find the retained amount.","B":"Option B is wrong because $200,000 is the total profit before any distribution to shareholders. It ignores the $50,000 dividend.","C":"Option C is wrong because $50,000 is the dividend paid out, not the amount kept in the business. For a company, option D is correct: $150,000.","D":"Retained profit is profit for the year less dividends paid. Keeping $150,000 from $200,000 after a $50,000 dividend, the Malmö company strengthens its internal finance for future investment."}}},{"id":"P1_U5_MCQ_1757","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1757","question":"A farm in Nelson, New Zealand, opens June with $3,200 cash, expects inflows of $21,000 and outflows of $18,400. The manager wants the month-end forecast. What is the closing cash balance?","options":{"A":"$5,800","B":"$2,600","C":"$24,200","D":"$3,200"},"correctOption":"A","correctAnswer":"$5,800","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $21,000 less $18,400, or $2,600. Adding the opening balance of $3,200 gives a closing cash balance of $5,800 for the Nelson farm in June.","distractor_reasons":{"A":"Net cash flow is $21,000 less $18,400, or $2,600. Adding the opening balance of $3,200 gives a closing cash balance of $5,800 for the Nelson farm in June.","B":"Option B is wrong because $2,600 is only the net cash flow. The opening balance must also be included to get the closing position.","C":"Option C is wrong because $24,200 adds inflows to the opening balance but ignores the $18,400 of outflows. For a farm, option A is correct: $5,800.","D":"Option D is wrong because $3,200 is the opening balance. Cash increased in June, so the closing figure must be higher."}}},{"id":"P1_U5_MCQ_1758","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1758","question":"A café in Palermo, Italy, has gross profit of $145,000 and operating expenses of $88,000. The owner wants the final figure after all running costs. What is its profit for the year?","options":{"A":"$233,000","B":"$57,000","C":"$88,000","D":"$145,000"},"correctOption":"B","correctAnswer":"$57,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is gross profit of $145,000 minus operating expenses of $88,000, giving $57,000 for the Palermo café after all its running costs are covered.","distractor_reasons":{"A":"Option A is wrong because $233,000 adds expenses to gross profit. Costs must be subtracted from gross profit to arrive at the year's profit.","B":"Profit for the year is gross profit of $145,000 minus operating expenses of $88,000, giving $57,000 for the Palermo café after all its running costs are covered.","C":"Option C is wrong because $88,000 is the operating expenses total, an input to the calculation rather than the resulting profit.","D":"Option D is wrong because $145,000 is gross profit, measured before the operating expenses are deducted. For a café, option B is correct: $57,000."}}},{"id":"P1_U5_MCQ_1759","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1759","question":"A business in Edmonton, Canada, has current assets of $220,000 and current liabilities of $180,000. The owner wants to interpret its working capital. Which statement about it is correct?","options":{"A":"It has negative working capital of $40,000","B":"Working capital equals $400,000","C":"It has positive working capital of $40,000","D":"Working capital cannot be calculated"},"correctOption":"C","correctAnswer":"It has positive working capital of $40,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so $220,000 less $180,000 gives positive working capital of $40,000 for the Edmonton business.","distractor_reasons":{"A":"Option A is wrong because working capital is positive here, since current assets exceed current liabilities. The sign should be positive.","B":"Option B is wrong because $400,000 adds the two figures. Working capital is a net amount found by subtracting liabilities from assets.","C":"Working capital is current assets minus current liabilities, so $220,000 less $180,000 gives positive working capital of $40,000 for the Edmonton business.","D":"Option D is wrong because both required figures are provided, so working capital can be calculated directly and easily. For a business, option C is correct: it has positive working capital of $40,000."}}},{"id":"P1_U5_MCQ_1760","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1760","question":"A furniture firm in Johannesburg, South Africa, has revenue of $1,500,000 and profit for the year of $135,000. An investor wants the percentage of sales retained as profit. What is its profit margin?","options":{"A":"11.1%","B":"1.1%","C":"13.5%","D":"9.0%"},"correctOption":"D","correctAnswer":"9.0%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin equals profit for the year divided by revenue, times one hundred. $135,000 over $1,500,000 equals 0.09, so the Johannesburg firm's margin is 9.0%.","distractor_reasons":{"A":"Option A is wrong because 11.1% reverses the division, dividing revenue by profit. The margin measures profit as a share of sales.","B":"Option B is wrong because 1.1% comes from a misplaced decimal point when dividing $135,000 by $1,500,000. For a furniture firm, option D is correct: 9.0%.","C":"Option C is wrong because 13.5% would require profit of $202,500 on the stated revenue. The actual profit is lower.","D":"Profit margin equals profit for the year divided by revenue, times one hundred. $135,000 over $1,500,000 equals 0.09, so the Johannesburg firm's margin is 9.0%."}}},{"id":"P1_U5_MCQ_1761","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1761","question":"Which statement best distinguishes a bank overdraft from a term loan for a retailer in Adelaide, Australia? The owner is comparing short-term and long-term borrowing options.","options":{"A":"An overdraft is short-term and repayable on demand; a term loan has fixed long-term repayments","B":"Both are forms of equity finance","C":"A term loan is always cheaper than an overdraft","D":"An overdraft gives the bank ownership of the firm"},"correctOption":"A","correctAnswer":"An overdraft is short-term and repayable on demand; a term loan has fixed long-term repayments","questionType":"MCQ","explanation":{"correct_reason":"An overdraft is a flexible short-term facility repayable on demand, while a term loan is borrowed for a fixed period with scheduled repayments. The Adelaide retailer faces two very different commitments.","distractor_reasons":{"A":"An overdraft is a flexible short-term facility repayable on demand, while a term loan is borrowed for a fixed period with scheduled repayments. The Adelaide retailer faces two very different commitments.","B":"Option B is wrong because both overdrafts and term loans are debt, not equity. Neither gives lenders an ownership stake in the business.","C":"Option C is wrong because term loans are not always cheaper; overdraft rates vary and comparison depends on the amount and duration borrowed.","D":"Option D is wrong because an overdraft is a loan from the bank and does not transfer ownership of the retailer's firm to the bank."}}},{"id":"P1_U5_MCQ_1762","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1762","question":"A bakery in Dakar, Senegal, notices that its forecast shows a cash surplus in January but a deficit in February. The manager is deciding what action to take. What should it plan to do?","options":{"A":"Ignore the forecast until February","B":"Arrange short-term finance to cover the February shortfall","C":"Reduce sales in January","D":"Buy more equipment in February"},"correctOption":"B","correctAnswer":"Arrange short-term finance to cover the February shortfall","questionType":"MCQ","explanation":{"correct_reason":"Spotting a future deficit lets a business arrange overdraft or other short-term finance in advance. Planning ahead for February's shortfall is a practical use of the Dakar bakery's cash forecast.","distractor_reasons":{"A":"Option A is wrong because ignoring a predicted shortfall risks the bakery being unable to pay suppliers or wages when February arrives.","B":"Spotting a future deficit lets a business arrange overdraft or other short-term finance in advance. Planning ahead for February's shortfall is a practical use of the Dakar bakery's cash forecast.","C":"Option C is wrong because cutting sales would reduce cash inflows further and make the February position worse, not better.","D":"Option D is wrong because buying equipment in a month when cash is already short would deepen the deficit. For a bakery, option B is correct: arrange short-term finance to cover the February shortfall."}}},{"id":"P1_U5_MCQ_1763","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1763","question":"Why might a retailer in Helsinki, Finland, track its gross profit margin each month? The owner wants a reason connected to the profitability of sales.","options":{"A":"To measure how quickly it pays suppliers","B":"To calculate the tax paid by shareholders","C":"To spot changes in the profitability of its sales","D":"To value its land and buildings"},"correctOption":"C","correctAnswer":"To spot changes in the profitability of its sales","questionType":"MCQ","explanation":{"correct_reason":"The gross profit margin shows how much is earned on each dollar of sales after direct costs. Monitoring it monthly helps the Helsinki retailer detect changes in selling prices or cost of sales early.","distractor_reasons":{"A":"Option A is wrong because payment speed to suppliers concerns cash flow and payables, not the gross margin on sales.","B":"Option B is wrong because shareholders' tax is a personal matter unrelated to the retailer's gross trading margin. Option C is correct: to spot changes in the profitability of its sales, which the scenario supports.","C":"The gross profit margin shows how much is earned on each dollar of sales after direct costs. Monitoring it monthly helps the Helsinki retailer detect changes in selling prices or cost of sales early.","D":"Option D is wrong because valuing land and buildings is an asset measurement issue, not something the gross margin reveals."}}},{"id":"P1_U5_MCQ_1764","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1764","question":"A firm in Bratislava, Slovakia, has total equity of $610,000 and non-current liabilities of $240,000. The accountant wants the long-term funding total. What is its capital employed?","options":{"A":"$370,000","B":"$610,000","C":"$240,000","D":"$850,000"},"correctOption":"D","correctAnswer":"$850,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is total equity plus non-current liabilities. Adding $610,000 and $240,000 gives $850,000, the long-term finance invested in the Bratislava firm.","distractor_reasons":{"A":"Option A is wrong because $370,000 subtracts the liabilities from equity. Capital employed adds the two sources of long-term funding.","B":"Option B is wrong because $610,000 is equity alone and leaves out the $240,000 borrowed long term. For a firm, option D is correct: $850,000.","C":"Option C is wrong because $240,000 covers only non-current liabilities, ignoring the owners' investment. For a firm, option D is correct: $850,000.","D":"Capital employed is total equity plus non-current liabilities. Adding $610,000 and $240,000 gives $850,000, the long-term finance invested in the Bratislava firm."}}},{"id":"P1_U5_MCQ_1765","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1765","question":"A firm in Guadalajara, Mexico, has current assets of $420,000, inventory of $120,000 and current liabilities of $150,000. A lender wants a strict test of liquidity. What is its acid test ratio?","options":{"A":"2.0 : 1","B":"2.8 : 1","C":"1.2 : 1","D":"0.5 : 1"},"correctOption":"A","correctAnswer":"2.0 : 1","questionType":"MCQ","explanation":{"correct_reason":"Liquid assets are current assets of $420,000 less inventory of $120,000, or $300,000. Dividing by $150,000 of current liabilities gives an acid test ratio of 2.0 : 1 in Guadalajara.","distractor_reasons":{"A":"Liquid assets are current assets of $420,000 less inventory of $120,000, or $300,000. Dividing by $150,000 of current liabilities gives an acid test ratio of 2.0 : 1 in Guadalajara.","B":"Option B is wrong because 2.8 : 1 uses all current assets and is the current ratio. The acid test removes inventory first.","C":"Option C is wrong because 1.2 : 1 does not follow from $300,000 divided by $150,000. Careful division gives 2.0.","D":"Option D is wrong because 0.5 : 1 reverses the division. Liquid assets exceed current liabilities here. For a firm, option A is correct: 2.0 : 1."}}},{"id":"P1_U5_MCQ_1766","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1766","question":"A craft brewery in Plzeň, Czechia, raises small amounts from many people through an online platform in exchange for rewards. Which source of finance is this?","options":{"A":"A bank overdraft","B":"Crowdfunding","C":"A debenture","D":"Retained profit"},"correctOption":"B","correctAnswer":"Crowdfunding","questionType":"MCQ","explanation":{"correct_reason":"Crowdfunding gathers many small contributions from individuals via an online platform, often in return for rewards. It suits the Plzeň brewery's community-based fundraising approach.","distractor_reasons":{"A":"Option A is wrong because an overdraft is a bank facility, not a collection of small contributions from many supporters.","B":"Crowdfunding gathers many small contributions from individuals via an online platform, often in return for rewards. It suits the Plzeň brewery's community-based fundraising approach.","C":"Option C is wrong because a debenture is a formal debt security issued to investors, not small online pledges in exchange for rewards.","D":"Option D is wrong because retained profit comes from the brewery's own past earnings, not from outside contributors online. For a craft brewery, option B is correct: crowdfunding."}}},{"id":"P1_U5_MCQ_1767","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1767","question":"A trader in Kumasi, Ghana, has opening cash of -$3,000, net inflow of $7,500 in May and net outflow of $2,000 in June. What is the cumulative balance after June?","options":{"A":"$12,500","B":"$5,500","C":"$2,500","D":"-$3,000"},"correctOption":"C","correctAnswer":"$2,500","questionType":"MCQ","explanation":{"correct_reason":"Opening cash of -$3,000 plus May's $7,500 inflow gives $4,500, then June's $2,000 outflow leaves $2,500 as the trader's cumulative cash balance in Kumasi.","distractor_reasons":{"A":"Option A is wrong because $12,500 adds all the positive amounts and ignores the overdraft and outflow. The sign of each flow matters.","B":"Option B is wrong because $5,500 does not follow from applying May and June flows in order to the opening balance. The correct result is $2,500.","C":"Opening cash of -$3,000 plus May's $7,500 inflow gives $4,500, then June's $2,000 outflow leaves $2,500 as the trader's cumulative cash balance in Kumasi.","D":"Option D is wrong because -$3,000 is the opening position only. Subsequent net inflows and outflows change it. For a trader, option C is correct: $2,500."}}},{"id":"P1_U5_MCQ_1768","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1768","question":"A cosmetics maker in Lyon, France, reports revenue of $480,000 and gross profit of $144,000. The owner wants to know the margin earned on sales. What is its gross profit margin?","options":{"A":"3.0%","B":"44.0%","C":"25.0%","D":"30.0%"},"correctOption":"D","correctAnswer":"30.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit divided by revenue, times one hundred. $144,000 over $480,000 equals 0.30, so the Lyon cosmetics maker achieves a 30.0% margin.","distractor_reasons":{"A":"Option A is wrong because 3.0% comes from a misplaced decimal. The fraction 144/480 is 0.30, which is 30.0%. For a cosmetics maker, option D is correct: 30.0%.","B":"Option B is wrong because 44.0% uses an incorrect denominator rather than the stated $480,000 of revenue. For a cosmetics maker, option D is correct: 30.0%.","C":"Option C is wrong because 25.0% would require gross profit of $120,000. The actual gross profit is $144,000. For a cosmetics maker, option D is correct: 30.0%.","D":"Gross profit margin is gross profit divided by revenue, times one hundred. $144,000 over $480,000 equals 0.30, so the Lyon cosmetics maker achieves a 30.0% margin."}}},{"id":"P1_U5_MCQ_1769","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1769","question":"A firm in Tbilisi, Georgia, owes $90,000 to a supplier and has $210,000 invested by its owners. The bookkeeper wants the items classified correctly. Which statement is correct?","options":{"A":"The $90,000 is a liability and the $210,000 is equity","B":"Both amounts are assets","C":"The $90,000 is equity and the $210,000 is a liability","D":"Both amounts are revenue"},"correctOption":"A","correctAnswer":"The $90,000 is a liability and the $210,000 is equity","questionType":"MCQ","explanation":{"correct_reason":"Money owed to a supplier is a liability that must be paid, while funds invested by owners are equity. The Tbilisi firm therefore has $90,000 of liabilities and $210,000 of equity.","distractor_reasons":{"A":"Money owed to a supplier is a liability that must be paid, while funds invested by owners are equity. The Tbilisi firm therefore has $90,000 of liabilities and $210,000 of equity.","B":"Option B is wrong because neither amount is an asset; one is an obligation and the other is the owners' stake in the business.","C":"Option C is wrong because it swaps the two categories. Supplier amounts are liabilities and owner investment is equity. For a firm, option A is correct: the $90,000 is a liability and the $210,000 is equity.","D":"Option D is wrong because revenue arises from sales, not from amounts owed to suppliers or invested by owners. For a firm, option A is correct: the $90,000 is a liability and the $210,000 is equity."}}},{"id":"P1_U5_MCQ_1770","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1770","question":"Why might an investor compare the ratios of two rival firms in different countries, such as one in Dublin, Ireland, and one in Lisbon, Portugal? The aim is to assess performance.","options":{"A":"Because all their accounting policies are identical","B":"To judge relative performance despite different conditions","C":"Because ratios remove all business risk","D":"To calculate their market share exactly"},"correctOption":"B","correctAnswer":"To judge relative performance despite different conditions","questionType":"MCQ","explanation":{"correct_reason":"Comparing ratios helps assess how efficiently each firm performs, even when operating in different markets. The investor must still allow for local conditions and accounting policies in Dublin and Lisbon.","distractor_reasons":{"A":"Option A is wrong because accounting policies often differ between firms and countries, which is precisely why comparisons need care.","B":"Comparing ratios helps assess how efficiently each firm performs, even when operating in different markets. The investor must still allow for local conditions and accounting policies in Dublin and Lisbon.","C":"Option C is wrong because ratios do not eliminate business risk; they are summary measures of past performance with limitations.","D":"Option D is wrong because market share requires sales data for a whole market, not the accounting ratios of individual firms."}}},{"id":"P1_U5_MCQ_1771","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1771","question":"A business in Palermo, Italy, sells an unused warehouse to raise cash for its core operations. The directors want to classify this correctly. Which source of finance does this illustrate?","options":{"A":"Issuing new shares","B":"Bank borrowing","C":"Sale of assets","D":"Trade credit"},"correctOption":"C","correctAnswer":"Sale of assets","questionType":"MCQ","explanation":{"correct_reason":"Selling an unused warehouse converts a non-current asset into cash, providing internal finance without creating debt or new owners. This suits the Palermo business's need to fund core operations.","distractor_reasons":{"A":"Option A is wrong because issuing shares brings in new equity investors and dilutes ownership, unlike selling a property the business already owns.","B":"Option B is wrong because borrowing creates an obligation to repay with interest, whereas selling an asset raises cash outright.","C":"Selling an unused warehouse converts a non-current asset into cash, providing internal finance without creating debt or new owners. This suits the Palermo business's need to fund core operations.","D":"Option D is wrong because trade credit is a short-term arrangement with suppliers, not the disposal of a warehouse. For a business, option C is correct: sale of assets."}}},{"id":"P1_U5_MCQ_1772","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1772","question":"A firm in Inverness, Scotland, forecasts cash inflows of $47,000 and outflows of $39,800 in March. The finance manager wants the net movement for the month. What is its net cash flow?","options":{"A":"$86,800","B":"-$7,200","C":"$39,800","D":"$7,200"},"correctOption":"D","correctAnswer":"$7,200","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is inflows minus outflows. Subtracting $39,800 from $47,000 gives a positive net cash flow of $7,200 for the Inverness firm during March.","distractor_reasons":{"A":"Option A is wrong because $86,800 adds inflows and outflows. Net cash flow is the difference, not the sum, of the two figures.","B":"Option B is wrong because -$7,200 has the wrong sign. Inflows exceed outflows here, so the net flow is positive.","C":"Option C is wrong because $39,800 is the outflow total. It must be deducted from inflows to find the net cash movement.","D":"Net cash flow is inflows minus outflows. Subtracting $39,800 from $47,000 gives a positive net cash flow of $7,200 for the Inverness firm during March."}}},{"id":"P1_U5_MCQ_1773","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1773","question":"A retailer in Ghent, Belgium, has revenue of $620,000 and gross profit of $248,000. The accountant needs the direct cost figure. What is its cost of sales?","options":{"A":"$372,000","B":"$868,000","C":"$248,000","D":"$620,000"},"correctOption":"A","correctAnswer":"$372,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales equals revenue minus gross profit. Deducting $248,000 from $620,000 gives $372,000, the direct cost of the goods sold by the Ghent retailer.","distractor_reasons":{"A":"Cost of sales equals revenue minus gross profit. Deducting $248,000 from $620,000 gives $372,000, the direct cost of the goods sold by the Ghent retailer.","B":"Option B is wrong because $868,000 adds revenue and gross profit. Cost of sales is found by subtracting one from the other.","C":"Option C is wrong because $248,000 is the gross profit itself, the surplus remaining after costs are deducted. For a retailer, option A is correct: $372,000.","D":"Option D is wrong because $620,000 is revenue, the starting figure before the cost of sales is removed. For a retailer, option A is correct: $372,000."}}},{"id":"P1_U5_MCQ_1774","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1774","question":"Why must the statement of financial position of a firm in Ljubljana, Slovenia, always balance? A trainee has asked for an explanation of the accounting equation.","options":{"A":"Because profit equals revenue minus costs","B":"Because every asset is financed by either equity or liabilities","C":"Because cash always equals debt","D":"Because sales equal purchases"},"correctOption":"B","correctAnswer":"Because every asset is financed by either equity or liabilities","questionType":"MCQ","explanation":{"correct_reason":"The statement balances because every asset a business owns must have been funded by owners' equity or by liabilities. That double-entry relationship holds for the Ljubljana firm's figures.","distractor_reasons":{"A":"Option A is wrong because that equation describes the profit and loss account, not the balancing of assets and claims in the statement of financial position.","B":"The statement balances because every asset a business owns must have been funded by owners' equity or by liabilities. That double-entry relationship holds for the Ljubljana firm's figures.","C":"Option C is wrong because cash and debt are rarely equal; the accounting equation concerns all assets and all claims, not just these two items.","D":"Option D is wrong because sales rarely equal purchases, and that idea does not explain why the statement of financial position balances."}}},{"id":"P1_U5_MCQ_1775","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1775","question":"A company in Turku, Finland, has operating profit of $78,000 and capital employed of $650,000. The board wants to measure the return on the funds invested. What is its return on capital employed?","options":{"A":"1.2%","B":"8.3%","C":"12.0%","D":"83.0%"},"correctOption":"C","correctAnswer":"12.0%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, times one hundred. $78,000 over $650,000 equals 0.12, giving Turku's firm a 12.0% return.","distractor_reasons":{"A":"Option A is wrong because 1.2% results from a misplaced decimal when dividing $78,000 by $650,000. For a company, option C is correct: 12.0%.","B":"Option B is wrong because 8.3% reverses the division or uses the wrong denominator. The correct fraction is 78/650. For a company, option C is correct: 12.0%.","C":"Return on capital employed is operating profit divided by capital employed, times one hundred. $78,000 over $650,000 equals 0.12, giving Turku's firm a 12.0% return.","D":"Option D is wrong because 83.0% confuses the decimal 0.12 with a much larger percentage. The correct figure is 12.0%."}}},{"id":"P1_U5_MCQ_1776","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1776","question":"What is a key disadvantage of financing expansion through retained profit for a company in Seville, Spain? The directors are weighing the options before the next meeting.","options":{"A":"It must be repaid to a bank","B":"It gives new investors voting rights","C":"It always has higher interest than loans","D":"Shareholders receive lower dividends"},"correctOption":"D","correctAnswer":"Shareholders receive lower dividends","questionType":"MCQ","explanation":{"correct_reason":"Retaining more profit means less is available to pay dividends, so shareholders may be dissatisfied. Seville's company trades current shareholder returns for internally funded growth.","distractor_reasons":{"A":"Option A is wrong because retained profit is not borrowed and creates no duty of repayment to any bank. Option D is correct: shareholders receive lower dividends, which the scenario supports.","B":"Option B is wrong because using internal funds creates no new shares and therefore no new voting rights for investors.","C":"Option C is wrong because retained profit carries no contractual interest rate at all, so comparing interest levels is meaningless.","D":"Retaining more profit means less is available to pay dividends, so shareholders may be dissatisfied. Seville's company trades current shareholder returns for internally funded growth."}}},{"id":"P1_U5_MCQ_1777","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1777","question":"A workshop in Aleppo, Syria, opens April with $4,500 cash, receives $16,000 and pays out $13,700. The manager needs the forecast month-end position. What is its closing cash balance?","options":{"A":"$6,800","B":"$3,200","C":"$20,500","D":"$4,500"},"correctOption":"A","correctAnswer":"$6,800","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $16,000 less $13,700, or $2,300. Adding the $4,500 opening balance gives a closing cash balance of $6,800 for the Aleppo workshop.","distractor_reasons":{"A":"Net cash flow is $16,000 less $13,700, or $2,300. Adding the $4,500 opening balance gives a closing cash balance of $6,800 for the Aleppo workshop.","B":"Option B is wrong because $3,200 does not equal opening cash plus the net inflow. Recompute $4,500 plus $2,300 carefully.","C":"Option C is wrong because $20,500 adds inflows to the opening balance but fails to deduct the $13,700 of outflows.","D":"Option D is wrong because $4,500 is merely the opening balance. Cash rose during April, so the closing figure is higher."}}},{"id":"P1_U5_MCQ_1778","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1778","question":"A firm in Nagoya, Japan, delivers goods in November but receives payment in January. The accountant wants to know which period should show the sale. In which period is the revenue normally recognised?","options":{"A":"January, when cash is received","B":"November, when the sale is made","C":"Equally across both periods","D":"Only in the following financial year"},"correctOption":"B","correctAnswer":"November, when the sale is made","questionType":"MCQ","explanation":{"correct_reason":"Under accrual accounting, revenue is recognised when the sale is made and goods delivered, not when cash arrives. The Nagoya firm therefore records the sale in November.","distractor_reasons":{"A":"Option A is wrong because that is cash accounting. Accrual accounting recognises revenue at the point of sale regardless of when payment is received.","B":"Under accrual accounting, revenue is recognised when the sale is made and goods delivered, not when cash arrives. The Nagoya firm therefore records the sale in November.","C":"Option C is wrong because revenue is recognised in full in the period of sale, not spread across periods arbitrarily.","D":"Option D is wrong because the sale happened in November, so revenue belongs to that period even if cash arrives in January."}}},{"id":"P1_U5_MCQ_1779","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1779","question":"A firm in Marseille, France, has current assets of $475,000 and current liabilities of $290,000. The owners want a measure of short-term liquidity. What is its working capital?","options":{"A":"$765,000","B":"$290,000","C":"$185,000","D":"$475,000"},"correctOption":"C","correctAnswer":"$185,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities. Subtracting $290,000 from $475,000 gives $185,000 available to the Marseille firm for day-to-day operations.","distractor_reasons":{"A":"Option A is wrong because $765,000 adds the two figures. Working capital is a net amount obtained by subtracting obligations.","B":"Option B is wrong because $290,000 is the current liabilities figure alone, an input rather than the calculated result. For a firm, option C is correct: $185,000.","C":"Working capital is current assets minus current liabilities. Subtracting $290,000 from $475,000 gives $185,000 available to the Marseille firm for day-to-day operations.","D":"Option D is wrong because $475,000 is total current assets before deducting short-term debts. For a firm, option C is correct: $185,000."}}},{"id":"P1_U5_MCQ_1780","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1780","question":"A retailer in Aarhus, Denmark, has revenue of $2,400,000 and profit for the year of $216,000. An analyst wants the share of sales kept as profit. What is its profit margin?","options":{"A":"10.0%","B":"1.1%","C":"90.0%","D":"9.0%"},"correctOption":"D","correctAnswer":"9.0%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin equals profit for the year divided by revenue, times one hundred. $216,000 over $2,400,000 equals 0.09, so the Aarhus retailer's margin is 9.0%.","distractor_reasons":{"A":"Option A is wrong because 10.0% would require profit of $240,000. The stated profit is lower at $216,000. For a retailer, option D is correct: 9.0%.","B":"Option B is wrong because 1.1% comes from a misplaced decimal point in the division of $216,000 by $2,400,000. For a retailer, option D is correct: 9.0%.","C":"Option C is wrong because 90.0% mistakes the decimal result relationship. The correct margin is 9.0%. For a retailer, option D is correct: 9.0%.","D":"Profit margin equals profit for the year divided by revenue, times one hundred. $216,000 over $2,400,000 equals 0.09, so the Aarhus retailer's margin is 9.0%."}}},{"id":"P1_U5_MCQ_1781","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1781","question":"A business in Edinburgh, Scotland, has very little retained profit and few assets to sell. The owners are choosing how to fund expansion. Which constraint does it face when choosing finance?","options":{"A":"It has limited internal finance and may need external funding","B":"It can issue shares without any dilution","C":"It has no need for finance","D":"Banks are required to lend to it"},"correctOption":"A","correctAnswer":"It has limited internal finance and may need external funding","questionType":"MCQ","explanation":{"correct_reason":"With little retained profit and few saleable assets, the Edinburgh firm cannot rely on internal sources and must consider external finance such as loans or new equity. That is the key constraint.","distractor_reasons":{"A":"With little retained profit and few saleable assets, the Edinburgh firm cannot rely on internal sources and must consider external finance such as loans or new equity. That is the key constraint.","B":"Option B is wrong because issuing new shares always dilutes existing ownership; the firm cannot avoid that effect. For a business, option A is correct: it has limited internal finance and may need external funding.","C":"Option C is wrong because the scenario describes a business seeking finance, so claiming it has no need is contradicted by the facts.","D":"Option D is wrong because banks are not obliged to lend; they assess creditworthiness and may refuse. For a business, option A is correct: it has limited internal finance and may need external funding."}}},{"id":"P1_U5_MCQ_1782","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1782","question":"A studio in Reykjavík, Iceland, expects inflows of $33,500 and outflows of $28,900 in September. The manager wants the overall cash movement. What is its net cash flow?","options":{"A":"$62,400","B":"$4,600","C":"-$4,600","D":"$33,500"},"correctOption":"B","correctAnswer":"$4,600","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is inflows minus outflows. Subtracting $28,900 from $33,500 gives a positive net cash flow of $4,600 for the Reykjavík studio in September.","distractor_reasons":{"A":"Option A is wrong because $62,400 adds the two totals. Net cash flow requires subtracting outflows from inflows. For a studio, option B is correct: $4,600.","B":"Net cash flow is inflows minus outflows. Subtracting $28,900 from $33,500 gives a positive net cash flow of $4,600 for the Reykjavík studio in September.","C":"Option C is wrong because -$4,600 has the wrong sign. Inflows exceed outflows, so the net movement is positive. For a studio, option B is correct: $4,600.","D":"Option D is wrong because $33,500 is only the inflow figure and ignores the $28,900 paid out. For a studio, option B is correct: $4,600."}}},{"id":"P1_U5_MCQ_1783","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1783","question":"A gym in Beirut, Lebanon, has gross profit of $96,000 and operating expenses of $61,000. The owner wants the final surplus. What is its profit for the year?","options":{"A":"$157,000","B":"$61,000","C":"$35,000","D":"$96,000"},"correctOption":"C","correctAnswer":"$35,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is gross profit less operating expenses. $96,000 minus $61,000 leaves $35,000 for the Beirut gym after its overhead costs are met.","distractor_reasons":{"A":"Option A is wrong because $157,000 adds expenses to gross profit. Costs must be deducted to find the year's profit.","B":"Option B is wrong because $61,000 is the operating expenses amount, not the resulting profit. For a gym, option C is correct: $35,000.","C":"Profit for the year is gross profit less operating expenses. $96,000 minus $61,000 leaves $35,000 for the Beirut gym after its overhead costs are met.","D":"Option D is wrong because $96,000 is gross profit before operating expenses are subtracted. For a gym, option C is correct: $35,000."}}},{"id":"P1_U5_MCQ_1784","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1784","question":"Which item is a current asset of a travel agency in San José, Costa Rica? The bookkeeper is separating assets from liabilities and equity and wants one example. Which option qualifies?","options":{"A":"Its office building","B":"A loan due in 2032","C":"Share capital","D":"Cash in the till"},"correctOption":"D","correctAnswer":"Cash in the till","questionType":"MCQ","explanation":{"correct_reason":"Cash in the till is the most liquid current asset, available immediately for the travel agency's day-to-day spending. The building is non-current and the loan and share capital are not assets.","distractor_reasons":{"A":"Option A is wrong because an office building is used over many years and is classified as a non-current asset.","B":"Option B is wrong because a loan due in 2032 is a long-term liability, not an asset of the business.","C":"Option C is wrong because share capital is equity representing the owners' investment, not an asset held. Option D is correct: cash in the till, which the scenario supports.","D":"Cash in the till is the most liquid current asset, available immediately for the travel agency's day-to-day spending. The building is non-current and the loan and share capital are not assets."}}},{"id":"P1_U5_MCQ_1785","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1785","question":"A firm in Graz, Austria, has current assets of $720,000 and current liabilities of $300,000. A bank wants to assess its liquidity. What is its current ratio?","options":{"A":"2.4 : 1","B":"0.4 : 1","C":"1.4 : 1","D":"3.0 : 1"},"correctOption":"A","correctAnswer":"2.4 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio divides current assets by current liabilities. $720,000 over $300,000 equals 2.4, so the Graz firm has $2.40 of current assets per dollar of short-term debt.","distractor_reasons":{"A":"The current ratio divides current assets by current liabilities. $720,000 over $300,000 equals 2.4, so the Graz firm has $2.40 of current assets per dollar of short-term debt.","B":"Option B is wrong because 0.4 : 1 reverses the division, dividing liabilities by assets and suggesting a liquidity problem that does not exist.","C":"Option C is wrong because 1.4 : 1 does not equal $720,000 divided by $300,000. The correct result is 2.4.","D":"Option D is wrong because 3.0 : 1 would require current assets of $900,000. The stated figure is lower. For a firm, option A is correct: 2.4 : 1."}}},{"id":"P1_U5_MCQ_1786","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1786","question":"A farmer in Kampala, Uganda, borrows $24,000 at 6% per annum interest for one year. The bank has explained the rate but wants the farmer to confirm the cost. What total interest will be paid?","options":{"A":"$1,200","B":"$1,440","C":"$24,000","D":"$25,440"},"correctOption":"B","correctAnswer":"$1,440","questionType":"MCQ","explanation":{"correct_reason":"Interest is the principal of $24,000 multiplied by the 6% annual rate, giving $1,440 for the year. This is the cost the Kampala farmer pays for borrowing, excluding any fees.","distractor_reasons":{"A":"Option A is wrong because $1,200 is 5% of $24,000, not 6%. The stated rate must be applied correctly. For a farmer, option B is correct: $1,440.","B":"Interest is the principal of $24,000 multiplied by the 6% annual rate, giving $1,440 for the year. This is the cost the Kampala farmer pays for borrowing, excluding any fees.","C":"Option C is wrong because $24,000 is the amount borrowed, the principal, not the interest charged on it. For a farmer, option B is correct: $1,440.","D":"Option D is wrong because $25,440 is principal plus interest, the total to repay, rather than the interest cost itself."}}},{"id":"P1_U5_MCQ_1787","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1787","question":"A shop in Budapest, Hungary, bought new shelving for cash during the year. The manager wants to understand the effect on this year's figures. How does this affect cash flow compared with profit?","options":{"A":"It reduces profit but not cash flow","B":"It affects neither figure","C":"It reduces cash flow but is not an immediate expense in profit","D":"It increases cash flow"},"correctOption":"C","correctAnswer":"It reduces cash flow but is not an immediate expense in profit","questionType":"MCQ","explanation":{"correct_reason":"Paying cash for shelving sends money out now, reducing cash flow, but the cost is capitalised as an asset and expensed through depreciation over time. Profit is therefore not reduced by the full amount immediately.","distractor_reasons":{"A":"Option A is wrong because paying cash clearly reduces cash flow. It is profit that is not reduced by the full purchase cost at once.","B":"Option B is wrong because the cash outflow directly lowers the bank balance, so one of the figures is certainly affected.","C":"Paying cash for shelving sends money out now, reducing cash flow, but the cost is capitalised as an asset and expensed through depreciation over time. Profit is therefore not reduced by the full amount immediately.","D":"Option D is wrong because spending cash on shelving is an outflow, which reduces rather than increases cash flow. For a shop, option C is correct: it reduces cash flow but is not an immediate expense in profit."}}},{"id":"P1_U5_MCQ_1788","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1788","question":"A bakery in Fès, Morocco, has gross profit of $132,000 and cost of sales of $198,000. The owner wants the total sales value for the year. What is its revenue?","options":{"A":"$66,000","B":"$198,000","C":"$132,000","D":"$330,000"},"correctOption":"D","correctAnswer":"$330,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals gross profit plus cost of sales. Adding $132,000 and $198,000 gives $330,000, the total sales recorded by the Fès bakery during the year.","distractor_reasons":{"A":"Option A is wrong because $66,000 subtracts the two figures. Revenue is the sum of gross profit and cost of sales.","B":"Option B is wrong because $198,000 is only the cost of sales and ignores the gross profit earned on top.","C":"Option C is wrong because $132,000 is the gross profit alone, not the total sales revenue. For a bakery, option D is correct: $330,000.","D":"Revenue equals gross profit plus cost of sales. Adding $132,000 and $198,000 gives $330,000, the total sales recorded by the Fès bakery during the year."}}},{"id":"P1_U5_MCQ_1789","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1789","question":"What are net current assets of a firm in Basel, Switzerland, with current assets of $260,000 and current liabilities of $175,000? The accountant wants the short-term liquidity measure.","options":{"A":"$85,000","B":"$435,000","C":"$175,000","D":"$260,000"},"correctOption":"A","correctAnswer":"$85,000","questionType":"MCQ","explanation":{"correct_reason":"Net current assets, also called working capital, are current assets minus current liabilities. $260,000 less $175,000 gives $85,000 for the Basel firm.","distractor_reasons":{"A":"Net current assets, also called working capital, are current assets minus current liabilities. $260,000 less $175,000 gives $85,000 for the Basel firm.","B":"Option B is wrong because $435,000 adds the two figures. Net current assets require subtracting liabilities from assets. Option A is correct: $85,000, which the scenario supports.","C":"Option C is wrong because $175,000 is the current liabilities total, an input to the calculation rather than the result.","D":"Option D is wrong because $260,000 is current assets before deducting what the firm owes in the short term. Option A is correct: $85,000, which the scenario supports."}}},{"id":"P1_U5_MCQ_1790","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1790","question":"A company in Lyon, France, sees its return on capital employed fall from 14% to 9%. The shareholders want an explanation. What is the most likely explanation?","options":{"A":"Its sales revenue increased","B":"Profit fell relative to the capital invested","C":"Its share price rose","D":"It reduced its long-term borrowing"},"correctOption":"B","correctAnswer":"Profit fell relative to the capital invested","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed compares operating profit with capital employed, so a fall from 14% to 9% means less profit is being generated per dollar invested in the Lyon company.","distractor_reasons":{"A":"Option A is wrong because higher revenue alone need not lower the ratio; if profit also rose, ROCE could improve.","B":"Return on capital employed compares operating profit with capital employed, so a fall from 14% to 9% means less profit is being generated per dollar invested in the Lyon company.","C":"Option C is wrong because share price is a market measure and does not enter the ROCE calculation based on accounting profit and capital.","D":"Option D is wrong because reducing long-term borrowing would typically reduce capital employed and could raise, not lower, the ratio."}}},{"id":"P1_U5_MCQ_1791","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1791","question":"A manufacturer in Sheffield, England, is asked by a bank to pledge its factory as security for a loan. The finance director wants to identify the type of finance being offered. What kind of finance is this?","options":{"A":"Unsecured equity","B":"Trade credit","C":"Secured debt finance","D":"A grant"},"correctOption":"C","correctAnswer":"Secured debt finance","questionType":"MCQ","explanation":{"correct_reason":"A loan backed by pledged assets is secured debt finance. The bank can sell the Sheffield factory if repayments stop, which lowers the lender's risk and may reduce the interest rate.","distractor_reasons":{"A":"Option A is wrong because equity involves ownership stakes and no asset pledge. A bank loan with security is debt, not equity.","B":"Option B is wrong because trade credit is an arrangement with suppliers to delay payment, not a secured bank loan.","C":"A loan backed by pledged assets is secured debt finance. The bank can sell the Sheffield factory if repayments stop, which lowers the lender's risk and may reduce the interest rate.","D":"Option D is wrong because a grant is a non-repayable payment and does not require collateral or security. For a manufacturer, option C is correct: secured debt finance."}}},{"id":"P1_U5_MCQ_1792","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1792","question":"A café in Nice, France, has opening cash of $2,800, inflows of $14,600 and outflows of $16,900. The owner wants the forecast closing position. What is its closing cash balance?","options":{"A":"$34,300","B":"$1,500","C":"$2,800","D":"$500"},"correctOption":"D","correctAnswer":"$500","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $14,600 less $16,900, or -$2,300. Adding that to opening cash of $2,800 leaves a closing balance of $500 for the Nice café.","distractor_reasons":{"A":"Option A is wrong because $34,300 adds all three figures together. Outflows must be deducted from inflows before adjusting the opening balance.","B":"Option B is wrong because $1,500 does not equal $2,800 minus the $2,300 net outflow. Recomputing gives $500. For a café, option D is correct: $500.","C":"Option C is wrong because $2,800 is the opening balance only. A net outflow occurred during the period, so the closing figure is lower.","D":"Net cash flow is $14,600 less $16,900, or -$2,300. Adding that to opening cash of $2,800 leaves a closing balance of $500 for the Nice café."}}},{"id":"P1_U5_MCQ_1793","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1793","question":"A retailer in Bern, Switzerland, has gross profit of $390,000 and profit for the year of $102,000. The accountant wants the overhead total. What were its operating expenses?","options":{"A":"$288,000","B":"$492,000","C":"$102,000","D":"$390,000"},"correctOption":"A","correctAnswer":"$288,000","questionType":"MCQ","explanation":{"correct_reason":"Operating expenses equal gross profit minus profit for the year. $390,000 less $102,000 gives $288,000, the overheads deducted by the Bern retailer during the year.","distractor_reasons":{"A":"Operating expenses equal gross profit minus profit for the year. $390,000 less $102,000 gives $288,000, the overheads deducted by the Bern retailer during the year.","B":"Option B is wrong because $492,000 adds gross profit and final profit. Expenses must be subtracted from gross profit, not added.","C":"Option C is wrong because $102,000 is the profit for the year, the amount left after expenses, not the expenses themselves.","D":"Option D is wrong because $390,000 is gross profit, measured before operating expenses are deducted. For a retailer, option A is correct: $288,000."}}},{"id":"P1_U5_MCQ_1794","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1794","question":"Which figures are needed to calculate capital employed for a company in Vienna, Austria? The trainee accountant wants the correct formula inputs and has asked for guidance. Which pair should be used?","options":{"A":"Current assets and current liabilities","B":"Total equity and non-current liabilities","C":"Revenue and cost of sales","D":"Cash and inventories"},"correctOption":"B","correctAnswer":"Total equity and non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is the sum of total equity and non-current liabilities, representing long-term funding. For the Vienna company these two figures show the resources providers have committed.","distractor_reasons":{"A":"Option A is wrong because current assets minus current liabilities gives working capital, a short-term liquidity measure, not capital employed.","B":"Capital employed is the sum of total equity and non-current liabilities, representing long-term funding. For the Vienna company these two figures show the resources providers have committed.","C":"Option C is wrong because revenue and cost of sales determine gross profit in the income statement, not the capital invested.","D":"Option D is wrong because cash and inventories are current assets only and omit long-term finance entirely. Option B is correct: total equity and non-current liabilities, which the scenario supports."}}},{"id":"P1_U5_MCQ_1795","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1795","question":"A firm in Brno, Czechia, has current assets of $610,000, inventory of $220,000 and current liabilities of $260,000. A supplier wants a strict liquidity figure. What is its acid test ratio?","options":{"A":"2.35 : 1","B":"0.85 : 1","C":"1.5 : 1","D":"1.0 : 1"},"correctOption":"C","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Liquid assets are current assets of $610,000 less inventory of $220,000, or $390,000. Dividing by $260,000 of current liabilities gives an acid test ratio of 1.5 : 1 for Brno.","distractor_reasons":{"A":"Option A is wrong because 2.35 : 1 is the current ratio using all current assets. The acid test excludes inventory first.","B":"Option B is wrong because 0.85 : 1 does not follow from $390,000 divided by $260,000. The correct quotient is 1.5.","C":"Liquid assets are current assets of $610,000 less inventory of $220,000, or $390,000. Dividing by $260,000 of current liabilities gives an acid test ratio of 1.5 : 1 for Brno.","D":"Option D is wrong because 1.0 : 1 would require liquid assets equal to current liabilities, but here they are higher."}}},{"id":"P1_U5_MCQ_1796","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1796","question":"A startup in Vilnius, Lithuania, is comparing a bank loan with an issue of shares. The founders want to understand the cost of each. Which statement about the cost of these sources is correct?","options":{"A":"Loans and shares both require fixed interest payments","B":"Shares must be repaid at a set date","C":"Loans dilute the founders' control","D":"Loans carry interest; shares may require dividends"},"correctOption":"D","correctAnswer":"Loans carry interest; shares may require dividends","questionType":"MCQ","explanation":{"correct_reason":"Debt such as a bank loan requires regular interest payments, while equity may involve dividends that are discretionary. The Vilnius startup faces different cost patterns depending on its choice.","distractor_reasons":{"A":"Option A is wrong because shares do not require fixed interest; dividends are paid at the company's discretion and are not contractual.","B":"Option B is wrong because share capital is permanent and has no set repayment date, unlike a loan. For a startup, option D is correct: loans carry interest; shares may require dividends.","C":"Option C is wrong because a loan is debt and does not dilute ownership; issuing new shares is what reduces the founders' control.","D":"Debt such as a bank loan requires regular interest payments, while equity may involve dividends that are discretionary. The Vilnius startup faces different cost patterns depending on its choice."}}},{"id":"P1_U5_MCQ_1797","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1797","question":"A farm cooperative in Córdoba, Spain, forecasts net cash inflow of $9,000 in May and net outflow of $12,500 in June. What is the combined net cash flow for the two months?","options":{"A":"-$3,500","B":"$21,500","C":"$3,500","D":"$9,000"},"correctOption":"A","correctAnswer":"-$3,500","questionType":"MCQ","explanation":{"correct_reason":"Combining the two months, $9,000 inflow minus $12,500 outflow gives a net cash flow of -$3,500. The cooperative's cash falls overall across May and June in Córdoba.","distractor_reasons":{"A":"Combining the two months, $9,000 inflow minus $12,500 outflow gives a net cash flow of -$3,500. The cooperative's cash falls overall across May and June in Córdoba.","B":"Option B is wrong because $21,500 adds the absolute values of the flows. The June outflow must be subtracted from the May inflow.","C":"Option C is wrong because $3,500 is the correct magnitude but the wrong direction. Outflows exceed inflows over the two months.","D":"Option D is wrong because $9,000 is May's inflow only and ignores June's $12,500 outflow. For a farm cooperative, option A is correct: -$3,500."}}},{"id":"P1_U5_MCQ_1798","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1798","question":"A retailer in Osaka, Japan, sees its gross profit margin rise while revenue is unchanged. The owner wants to know what must have happened. Which change is consistent with this?","options":{"A":"Its operating expenses increased","B":"Its cost of sales fell","C":"It issued more shares","D":"It borrowed more money"},"correctOption":"B","correctAnswer":"Its cost of sales fell","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit over revenue, so with revenue fixed a higher margin means gross profit rose, which requires cost of sales to have fallen at the Osaka retailer.","distractor_reasons":{"A":"Option A is wrong because operating expenses are deducted after gross profit and do not affect the gross margin itself.","B":"Gross profit margin is gross profit over revenue, so with revenue fixed a higher margin means gross profit rose, which requires cost of sales to have fallen at the Osaka retailer.","C":"Option C is wrong because issuing shares changes finance and ownership, not the revenue and cost of sales that determine gross margin.","D":"Option D is wrong because borrowing affects finance costs below gross profit, not the cost of sales figure. For a retailer, option B is correct: its cost of sales fell."}}},{"id":"P1_U5_MCQ_1799","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1799","question":"A business in Porto, Portugal, has current assets of $520,000 and working capital of $130,000. The accountant needs the missing liability figure. What are its current liabilities?","options":{"A":"$650,000","B":"$130,000","C":"$390,000","D":"$520,000"},"correctOption":"C","correctAnswer":"$390,000","questionType":"MCQ","explanation":{"correct_reason":"Current liabilities equal current assets minus working capital. $520,000 less $130,000 gives $390,000 for the Porto business's short-term obligations. For a business, option C is correct: $390,000.","distractor_reasons":{"A":"Option A is wrong because $650,000 adds working capital to current assets. The correct operation subtracts it. For a business, option C is correct: $390,000.","B":"Option B is wrong because $130,000 is the working capital figure itself, not the liabilities. For a business, option C is correct: $390,000.","C":"Current liabilities equal current assets minus working capital. $520,000 less $130,000 gives $390,000 for the Porto business's short-term obligations. For a business, option C is correct: $390,000.","D":"Option D is wrong because $520,000 is total current assets before deducting the net working capital. For a business, option C is correct: $390,000."}}},{"id":"P1_U5_MCQ_1800","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1800","question":"A company in Haarlem, Netherlands, reported a current ratio of 1.8 : 1 last year and 1.3 : 1 this year. An investor wants the absolute change. By how much did the ratio change?","options":{"A":"A rise of 0.5","B":"A fall of 0.5 percentage points","C":"A rise of 0.5 : 1","D":"A fall of 0.5"},"correctOption":"D","correctAnswer":"A fall of 0.5","questionType":"MCQ","explanation":{"correct_reason":"The ratio fell from 1.8 : 1 to 1.3 : 1, a decrease of 0.5. Because it is a ratio rather than a percentage, the change is expressed simply as a fall of 0.5 for Haarlem's firm.","distractor_reasons":{"A":"Option A is wrong because the ratio declined, not rose. Subtracting 1.3 from 1.8 gives a fall of 0.5. For a company, option D is correct: a fall of 0.5.","B":"Option B is wrong because 'percentage points' applies to percentages, not to ratios expressed as x : 1. For a company, option D is correct: a fall of 0.5.","C":"Option C is wrong because the direction is wrong and the wording is awkward; the ratio fell rather than rose.","D":"The ratio fell from 1.8 : 1 to 1.3 : 1, a decrease of 0.5. Because it is a ratio rather than a percentage, the change is expressed simply as a fall of 0.5 for Haarlem's firm."}}},{"id":"P1_U5_MCQ_1801","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1801","question":"Chisomo Renewables is a solar installation firm in Lusaka, Zambia, planning a new warehouse and seeking long-term external finance. Its owners want to avoid short-term repayment pressure and do not want to rely only on retained profit. Which source best meets this need?","options":{"A":"A bank overdraft","B":"Issue of ordinary shares","C":"Trade credit from suppliers","D":"Retained profit"},"correctOption":"B","correctAnswer":"Issue of ordinary shares","questionType":"MCQ","explanation":{"correct_reason":"Chisomo Renewables needs long-term external finance for a warehouse, and issuing ordinary shares provides permanent capital that need not be repaid on a fixed short-term date, unlike the overdraft and trade credit listed.","distractor_reasons":{"A":"A bank overdraft is a short-term, repayable-on-demand facility suitable for temporary working capital, not for funding a long-life warehouse in Lusaka.","B":"Chisomo Renewables needs long-term external finance for a warehouse, and issuing ordinary shares provides permanent capital that need not be repaid on a fixed short-term date, unlike the overdraft and trade credit listed.","C":"Trade credit merely delays payment to suppliers for a few weeks; it cannot supply the substantial, long-term external funding a new warehouse demands.","D":"Retained profit is an internal source of finance, so it does not satisfy the stated requirement for external finance, however useful it might be."}}},{"id":"P1_U5_MCQ_1802","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1802","question":"Hoshina Seafoods in Osaka, Japan is preparing a three-month cash flow forecast before expanding its cold store. The finance manager wants a document that shows the timing of money moving in and out. What does a cash flow forecast mainly show?","options":{"A":"The profit earned during the financial year","B":"The value of all assets owned at year end","C":"The amount of tax owed to the government","D":"The expected cash inflows and outflows over a period"},"correctOption":"D","correctAnswer":"The expected cash inflows and outflows over a period","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast lists expected cash inflows and outflows month by month, showing Hoshina Seafoods when cash will be available or scarce. It is a planning tool about timing and liquidity, not a measure of profit.","distractor_reasons":{"A":"Profit for the year appears in the profit and loss account, not a cash flow forecast; a profitable firm can still run short of cash at the wrong moment.","B":"A list of assets at year end belongs in the statement of financial position, a snapshot, unlike a forecast that projects cash movements over time.","C":"Tax owed is a liability estimate; it is not the purpose of a cash flow forecast, whose focus is the pattern of expected cash receipts and payments.","D":"A cash flow forecast lists expected cash inflows and outflows month by month, showing Hoshina Seafoods when cash will be available or scarce. It is a planning tool about timing and liquidity, not a measure of profit."}}},{"id":"P1_U5_MCQ_1803","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1803","question":"Malgorzata owns Klodzko Kitchens, a fitted-kitchen retailer in Kraków, Poland. Last year sales revenue was $480,000 and the direct cost of buying and fitting the kitchens was $300,000. Which figure is the gross profit of the business?","options":{"A":"$180,000","B":"$300,000","C":"$480,000","D":"$780,000"},"correctOption":"A","correctAnswer":"$180,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit equals sales revenue minus the direct cost of sales. For Klodzko Kitchens that is $480,000 revenue less $300,000 cost of sales, giving $180,000, which remains before deducting overhead expenses such as rent.","distractor_reasons":{"A":"Gross profit equals sales revenue minus the direct cost of sales. For Klodzko Kitchens that is $480,000 revenue less $300,000 cost of sales, giving $180,000, which remains before deducting overhead expenses such as rent.","B":"$300,000 is the cost of sales itself, the direct expense of the kitchens sold; gross profit is what is left after subtracting that cost from revenue.","C":"$480,000 is the total sales revenue, not the profit; revenue must have the direct cost of sales deducted before gross profit can be found.","D":"$780,000 adds revenue and cost of sales, which has no meaning here; gross profit is found by subtracting cost of sales from revenue, not adding."}}},{"id":"P1_U5_MCQ_1804","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1804","question":"Afua Mensah runs Accra Packagers, a carton manufacturer in Accra, Ghana. She is listing the items for the business's statement of financial position and wants to classify a delivery van bought two years ago and still used for shipments. How should it be recorded?","options":{"A":"As a current asset","B":"As a current liability","C":"As a non-current asset","D":"As owners' equity"},"correctOption":"C","correctAnswer":"As a non-current asset","questionType":"MCQ","explanation":{"correct_reason":"The delivery van is a tangible item bought for long-term use in Accra Packagers' operations, not for resale, so it is a non-current asset. Its value appears among fixed assets and is gradually reduced through depreciation over its useful life.","distractor_reasons":{"A":"A current asset is cash or something converted to cash within a year, such as inventory; a delivery van held for years is not current.","B":"A current liability is a short-term debt owed to others; a van owned by the business is an asset, not an amount the business must pay.","C":"The delivery van is a tangible item bought for long-term use in Accra Packagers' operations, not for resale, so it is a non-current asset. Its value appears among fixed assets and is gradually reduced through depreciation over its useful life.","D":"Owners' equity represents the proprietor's claim on the business; the van itself is a resource owned, so it is classified as an asset instead."}}},{"id":"P1_U5_MCQ_1805","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1805","question":"Vera Silva manages a cosmetics shop in São Paulo, Brazil. Her current assets total $84,000 and current liabilities total $42,000. She wants to measure short-term liquidity using the current ratio. Which formula should she apply?","options":{"A":"Current assets divided by current liabilities","B":"Current liabilities divided by current assets","C":"Current assets minus current liabilities","D":"Non-current assets divided by current liabilities"},"correctOption":"A","correctAnswer":"Current assets divided by current liabilities","questionType":"MCQ","explanation":{"correct_reason":"The current ratio compares current assets with current liabilities to test liquidity. For the São Paulo shop it is $84,000 of current assets divided by $42,000 of current liabilities, giving 2 : 1, meaning assets comfortably cover short-term debts.","distractor_reasons":{"A":"The current ratio compares current assets with current liabilities to test liquidity. For the São Paulo shop it is $84,000 of current assets divided by $42,000 of current liabilities, giving 2 : 1, meaning assets comfortably cover short-term debts.","B":"Dividing current liabilities by current assets inverts the ratio, producing 0.5 : 1, which reverses the comparison and gives a misleading picture of liquidity.","C":"Subtracting gives $42,000 of working capital, a useful figure but a difference, not a ratio; the current ratio is a division of the two figures.","D":"Non-current assets are excluded from the current ratio because they cannot be quickly turned into cash to meet debts falling due within one year."}}},{"id":"P1_U5_MCQ_1806","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1806","question":"Ravi Patel runs a small printing firm in Pune, India and needs to pay for paper next week because a customer has delayed payment. He wants a flexible, short-term source that he can repay quickly once the customer settles. Which source is most appropriate?","options":{"A":"Issuing new ordinary shares","B":"A 20-year bank loan","C":"Retained profit from five years ago","D":"A bank overdraft"},"correctOption":"D","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"A bank overdraft lets Ravi's printing firm borrow up to an agreed limit for a short period and repay when cash arrives from the customer. It matches a temporary one-week working-capital gap in Pune far better than long-term or permanent finance.","distractor_reasons":{"A":"Issuing ordinary shares raises permanent long-term capital and dilutes ownership; it is far too slow and costly for a one-week paper bill.","B":"A 20-year bank loan commits the firm to long-term repayments and interest, which is unsuitable for a short-term gap that should close within a week.","C":"Retained profit from years ago would already have been spent or invested; it is not a readily available source for next week's urgent paper purchase.","D":"A bank overdraft lets Ravi's printing firm borrow up to an agreed limit for a short period and repay when cash arrives from the customer. It matches a temporary one-week working-capital gap in Pune far better than long-term or permanent finance."}}},{"id":"P1_U5_MCQ_1807","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1807","question":"A tailoring cooperative in Dakar, Senegal produced a large batch of uniforms in March but will not receive payment from the buyer until May. Its manager is confused why the March cash flow forecast shows a negative balance despite healthy sales. What is the most likely explanation?","options":{"A":"The forecast must contain an arithmetic error","B":"Sales on credit create profit before the cash is received","C":"The business has too many current assets","D":"Depreciation has reduced the cash balance"},"correctOption":"B","correctAnswer":"Sales on credit create profit before the cash is received","questionType":"MCQ","explanation":{"correct_reason":"When the Dakar cooperative sells uniforms on credit, the sale contributes to profit in March but the cash does not arrive until May, so the cash flow forecast shows a short-term deficit even though trading is profitable. Timing of receipts causes the gap.","distractor_reasons":{"A":"A negative cash balance caused by delayed customer payment is entirely normal and does not imply a mistake in the forecast's arithmetic or layout.","B":"When the Dakar cooperative sells uniforms on credit, the sale contributes to profit in March but the cash does not arrive until May, so the cash flow forecast shows a short-term deficit even though trading is profitable. Timing of receipts causes the gap.","C":"Holding many current assets is not the issue; the problem is the timing of cash inflows, with customers paying late relative to the outflows.","D":"Depreciation is a non-cash expense, so it does not remove cash from the bank account and cannot explain a negative cash flow balance."}}},{"id":"P1_U5_MCQ_1808","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1808","question":"Bergen Fjord Furniture in Bergen, Norway recorded revenue of $620,000 in 2026. Its cost of sales for the same year was $395,000. What was the gross profit of the business for 2026?","options":{"A":"$1,015,000","B":"$395,000","C":"$225,000","D":"$620,000"},"correctOption":"C","correctAnswer":"$225,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales. Bergen Fjord Furniture earned $620,000 of revenue and incurred $395,000 of direct costs, so $620,000 minus $395,000 equals $225,000 of gross profit before other expenses are deducted.","distractor_reasons":{"A":"$1,015,000 adds revenue and cost of sales together, a meaningless total; gross profit requires subtracting the direct costs from revenue.","B":"$395,000 is the cost of sales itself, the direct expense; gross profit is the amount left after that figure is deducted from the $620,000 revenue.","C":"Gross profit is revenue minus cost of sales. Bergen Fjord Furniture earned $620,000 of revenue and incurred $395,000 of direct costs, so $620,000 minus $395,000 equals $225,000 of gross profit before other expenses are deducted.","D":"$620,000 is the revenue, the starting point of the calculation; gross profit is the remainder after the $395,000 cost of sales is subtracted."}}},{"id":"P1_U5_MCQ_1809","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1809","question":"Nakuru Fresh Produce, a vegetable exporter in Nakuru, Kenya, owes suppliers $46,000 due within 30 days and holds $18,000 in the bank. Its owner wants to understand the firm's working capital position. What does working capital measure?","options":{"A":"The long-term loans of the business","B":"The total value of non-current assets","C":"The annual profit after tax","D":"Current assets minus current liabilities"},"correctOption":"D","correctAnswer":"Current assets minus current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Working capital measures short-term financial health as current assets minus current liabilities. For Nakuru Fresh Produce it compares resources like the $18,000 bank balance with the $46,000 due to suppliers, indicating whether short-term obligations can be met.","distractor_reasons":{"A":"Long-term loans are non-current liabilities and are excluded from working capital, which focuses only on obligations and resources falling due within one year.","B":"Non-current assets such as land and vehicles are not part of working capital because they cannot readily be used to settle debts due within a year.","C":"Annual profit after tax is a performance figure from the profit and loss account, not a measure of the firm's short-term liquidity position.","D":"Working capital measures short-term financial health as current assets minus current liabilities. For Nakuru Fresh Produce it compares resources like the $18,000 bank balance with the $46,000 due to suppliers, indicating whether short-term obligations can be met."}}},{"id":"P1_U5_MCQ_1810","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1810","question":"Katarzyna Nowak manages a food processing plant in Gdańsk, Poland. Operating profit was $240,000 and capital employed was $1,200,000. She wants to assess how efficiently the plant uses its long-term capital. Which measure should she calculate?","options":{"A":"Return on capital employed","B":"Current ratio","C":"Gross profit margin","D":"Acid test ratio"},"correctOption":"A","correctAnswer":"Return on capital employed","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed compares operating profit with the capital invested, so for the Gdańsk plant it is $240,000 divided by $1,200,000, or 20%. It directly measures how effectively long-term capital generates operating profit.","distractor_reasons":{"A":"Return on capital employed compares operating profit with the capital invested, so for the Gdańsk plant it is $240,000 divided by $1,200,000, or 20%. It directly measures how effectively long-term capital generates operating profit.","B":"The current ratio tests short-term liquidity using current assets and liabilities; it says nothing about how efficiently long-term capital earns operating profit.","C":"Gross profit margin compares gross profit with revenue and looks at trading profitability, not the return on the total capital employed in the plant.","D":"The acid test ratio is a stricter liquidity test excluding inventory; it does not measure the efficiency of long-term capital use."}}},{"id":"P1_U5_MCQ_1811","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1811","question":"Dang Phuong Designs, a furniture maker in Da Nang, Vietnam, has earned steady profits and kept $90,000 in the business rather than distributing it to the owner. What is the main advantage of using this retained profit to buy new machinery?","options":{"A":"It must be repaid within one year","B":"It dilutes the owner's control of the firm","C":"It carries no interest or dilution of ownership","D":"It is only available to public companies"},"correctOption":"C","correctAnswer":"It carries no interest or dilution of ownership","questionType":"MCQ","explanation":{"correct_reason":"The $90,000 retained by Dang Phuong Designs belongs to the business already, so using it to buy machinery avoids interest charges and does not require issuing shares that would dilute the owner's control. It is an internal, low-cost source of finance.","distractor_reasons":{"A":"Retained profit does not have to be repaid to anyone; only borrowed finance such as a loan carries a repayment obligation within a set period.","B":"Because no new shares are issued, retained profit leaves the owner's control untouched, unlike an ordinary share issue which brings in new shareholders.","C":"The $90,000 retained by Dang Phuong Designs belongs to the business already, so using it to buy machinery avoids interest charges and does not require issuing shares that would dilute the owner's control. It is an internal, low-cost source of finance.","D":"Retained profit is available to sole traders, partnerships and companies alike; it is not restricted to public limited companies, since any legal form may keep its earnings and reuse them."}}},{"id":"P1_U5_MCQ_1812","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1812","question":"Tallinn Bay Bakeries in Tallinn, Estonia expects cash inflows of $54,000 in June and cash outflows of $61,000 in the same month. What is the net cash flow for June?","options":{"A":"$115,000","B":"-$7,000","C":"$7,000","D":"-$115,000"},"correctOption":"B","correctAnswer":"-$7,000","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow equals total cash inflows minus total cash outflows. Tallinn Bay Bakeries expects $54,000 inflows and $61,000 outflows, so $54,000 minus $61,000 gives negative $7,000, meaning cash is expected to fall during June.","distractor_reasons":{"A":"$115,000 adds inflows and outflows; net cash flow is the difference between them, not their combined total, so this figure double counts the month's cash movements.","B":"Net cash flow equals total cash inflows minus total cash outflows. Tallinn Bay Bakeries expects $54,000 inflows and $61,000 outflows, so $54,000 minus $61,000 gives negative $7,000, meaning cash is expected to fall during June.","C":"$7,000 is the correct size but the wrong sign; because outflows exceed inflows, the net cash flow is a negative figure.","D":"Negative $115,000 wrongly adds rather than subtracts and then applies a minus sign; the calculation requires $61,000 subtracted from $54,000."}}},{"id":"P1_U5_MCQ_1813","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1813","question":"Lan Xang Textiles in Vientiane, Laos reports revenue, cost of sales, rent and wages. The management wants to know which items reduce profit after gross profit has been calculated. Which of these is an expense deducted at that stage?","options":{"A":"Rent on the factory building","B":"Cost of fabric used in production","C":"Sales revenue from customers","D":"The value of machinery owned"},"correctOption":"A","correctAnswer":"Rent on the factory building","questionType":"MCQ","explanation":{"correct_reason":"After gross profit, the profit and loss account deducts overhead expenses such as factory rent and wages. For Lan Xang Textiles the fabric cost is already inside cost of sales, so rent is an operating expense subtracted later to arrive at net profit.","distractor_reasons":{"A":"After gross profit, the profit and loss account deducts overhead expenses such as factory rent and wages. For Lan Xang Textiles the fabric cost is already inside cost of sales, so rent is an operating expense subtracted later to arrive at net profit.","B":"The cost of fabric is a direct cost included in cost of sales, so it is deducted earlier when calculating gross profit, not afterwards.","C":"Sales revenue is the starting point of the profit and loss account, not an expense; it is the income from which costs are subtracted.","D":"Machinery value is an asset shown in the statement of financial position; only its depreciation, not its full value, may appear as an expense."}}},{"id":"P1_U5_MCQ_1814","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1814","question":"Olamide Foods, a snack producer in Lagos, Nigeria, was started with $70,000 contributed by its owners and has since retained $35,000 of profit. Which figure represents total equity in the statement of financial position?","options":{"A":"$35,000","B":"$70,000","C":"$105,000 of liabilities","D":"$105,000"},"correctOption":"D","correctAnswer":"$105,000","questionType":"MCQ","explanation":{"correct_reason":"Total equity is the owners' original capital plus accumulated retained profit. Olamide Foods has $70,000 contributed plus $35,000 retained, giving $105,000, which represents the owners' claim on the net assets of the Lagos business.","distractor_reasons":{"A":"$35,000 is only the retained profit, one component of equity; the original capital contributed by the owners must be added to it.","B":"$70,000 is the initial capital alone; profits kept in the business since then also belong to the owners and form part of equity.","C":"Equity is not a liability; calling the $105,000 liabilities confuses the owners' stake with amounts the business owes to outside parties.","D":"Total equity is the owners' original capital plus accumulated retained profit. Olamide Foods has $70,000 contributed plus $35,000 retained, giving $105,000, which represents the owners' claim on the net assets of the Lagos business."}}},{"id":"P1_U5_MCQ_1815","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1815","question":"Petrov Plumbing Supply in Sofia, Bulgaria wants a stricter liquidity test than the current ratio. Its stock of pipes cannot always be sold quickly. Which ratio excludes inventory from current assets?","options":{"A":"Current ratio","B":"Gross profit margin","C":"Acid test ratio","D":"Return on capital employed"},"correctOption":"C","correctAnswer":"Acid test ratio","questionType":"MCQ","explanation":{"correct_reason":"The acid test, or quick ratio, deducts inventory from current assets before dividing by current liabilities, giving a tougher liquidity check. For Petrov Plumbing Supply this removes the slow-moving pipe stock that the ordinary current ratio would include.","distractor_reasons":{"A":"The current ratio includes all current assets, including inventory, so it is less strict and does not meet Petrov's requirement to exclude stock.","B":"Gross profit margin measures trading profitability by comparing gross profit with revenue; it says nothing about liquidity or the treatment of inventory.","C":"The acid test, or quick ratio, deducts inventory from current assets before dividing by current liabilities, giving a tougher liquidity check. For Petrov Plumbing Supply this removes the slow-moving pipe stock that the ordinary current ratio would include.","D":"Return on capital employed relates operating profit to capital invested; it is a profitability measure, not a test of short-term liquidity."}}},{"id":"P1_U5_MCQ_1816","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1816","question":"Mwangi Agro Supplies in Nairobi, Kenya borrows $40,000 at a simple interest rate of 8% per year for one year to buy fertiliser stock. How much interest will the business pay over the year?","options":{"A":"$4,800","B":"$3,200","C":"$320","D":"$32,000"},"correctOption":"B","correctAnswer":"$3,200","questionType":"MCQ","explanation":{"correct_reason":"Simple interest equals principal times rate times time. Mwangi Agro Supplies borrows $40,000 at 8% for one year, so $40,000 multiplied by 0.08 gives $3,200 of interest payable on the fertiliser loan.","distractor_reasons":{"A":"$4,800 would require a 12% rate on the $40,000 borrowed; at the stated 8% for one year the interest payable is only $3,200.","B":"Simple interest equals principal times rate times time. Mwangi Agro Supplies borrows $40,000 at 8% for one year, so $40,000 multiplied by 0.08 gives $3,200 of interest payable on the fertiliser loan.","C":"$320 results from using 0.8% instead of 8%, a decimal-place error in the rate; the correct 8% of the $40,000 loan is $3,200.","D":"$32,000 confuses 80% with 8% when applying the rate to $40,000; the true annual interest charge on the loan is actually $3,200."}}},{"id":"P1_U5_MCQ_1817","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1817","question":"A logistics firm in Veracruz, Mexico predicts higher outflows than inflows for three consecutive months. Its manager wants to avoid a cash shortfall. Which action would ease the immediate cash flow problem?","options":{"A":"Buy more delivery vehicles","B":"Increase long-term borrowing","C":"Delay a planned equipment purchase","D":"Reduce the detail in the forecast"},"correctOption":"C","correctAnswer":"Delay a planned equipment purchase","questionType":"MCQ","explanation":{"correct_reason":"Postponing a planned equipment purchase cuts a cash outflow, directly easing the three-month shortfall predicted for the Veracruz firm. Bringing spending into line with available cash is a practical short-term response to a forecast deficit.","distractor_reasons":{"A":"Buying more vehicles would increase cash outflows at exactly the time the forecast shows a shortage, making the liquidity problem worse.","B":"Additional long-term borrowing creates interest and repayment obligations that last for years; it is a slower and costlier response than simply delaying discretionary spending.","C":"Postponing a planned equipment purchase cuts a cash outflow, directly easing the three-month shortfall predicted for the Veracruz firm. Bringing spending into line with available cash is a practical short-term response to a forecast deficit.","D":"Reducing forecast detail hides the problem rather than solving it; the firm still faces the same gap between predicted inflows and outflows."}}},{"id":"P1_U5_MCQ_1818","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1818","question":"Café packaging maker Nestor works for a coffee roastery in Medellín, Colombia. The business sells jars at a price above their direct cost and expresses the profit as a percentage of the cost. What is this percentage called?","options":{"A":"Mark-up","B":"Gross profit margin","C":"Net profit margin","D":"Current ratio"},"correctOption":"A","correctAnswer":"Mark-up","questionType":"MCQ","explanation":{"correct_reason":"A mark-up expresses gross profit as a percentage of the cost of sales. If the Medellín roastery sells jars for more than their direct cost and states the profit relative to that cost, it is using mark-up pricing.","distractor_reasons":{"A":"A mark-up expresses gross profit as a percentage of the cost of sales. If the Medellín roastery sells jars for more than their direct cost and states the profit relative to that cost, it is using mark-up pricing.","B":"Gross profit margin expresses gross profit as a percentage of sales revenue, not of cost, so it is a different measure from the one described.","C":"Net profit margin compares net profit with revenue after all expenses, not a profit percentage based on the direct cost of the jars.","D":"The current ratio is a liquidity measure comparing current assets with current liabilities; it has nothing to do with setting a selling price."}}},{"id":"P1_U5_MCQ_1819","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1819","question":"Hanan Bakery, owned by a sole trader in Amman, Jordan, must pay its flour supplier within 20 days and has wages due next Friday. How should these obligations be classified in the statement of financial position?","options":{"A":"As non-current assets","B":"As current liabilities","C":"As owners' equity","D":"As non-current liabilities"},"correctOption":"B","correctAnswer":"As current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Amounts owed to the flour supplier and to employees, due within days or weeks, are current liabilities of Hanan Bakery. They are short-term obligations that must be settled within one year from the Amman bakery's normal trading cycle.","distractor_reasons":{"A":"Non-current assets are long-term resources such as ovens and delivery vans; amounts owed to suppliers and staff are the opposite, being obligations.","B":"Amounts owed to the flour supplier and to employees, due within days or weeks, are current liabilities of Hanan Bakery. They are short-term obligations that must be settled within one year from the Amman bakery's normal trading cycle.","C":"Owners' equity is the proprietor's stake in the business, whereas the supplier and wage amounts are claims by outside parties on the bakery.","D":"Non-current liabilities are debts due after more than a year, such as a long bank loan; the flour bill and wages fall due much sooner."}}},{"id":"P1_U5_MCQ_1820","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1820","question":"Fjord Optics, an eyewear retailer in Bergen, Norway, reports revenue of $500,000 and net profit of $45,000 for the year ended December 2026. The owner wants to know what percentage of each sales dollar remains as profit. What is its profit margin?","options":{"A":"9% of capital employed","B":"$455,000","C":"11.1%","D":"9%"},"correctOption":"D","correctAnswer":"9%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin equals net profit divided by revenue, multiplied by 100. Fjord Optics earns $45,000 net profit on $500,000 revenue, so 45,000 divided by 500,000 times 100 gives 9%.","distractor_reasons":{"A":"Nine percent of capital employed would be return on capital employed; the profit margin uses revenue of $500,000 as the denominator.","B":"$455,000 is revenue minus net profit, which is not a ratio at all; the profit margin is a percentage of the $500,000 revenue.","C":"11.1% comes from dividing revenue by profit instead of profit by revenue, inverting the correct calculation; the margin is 9%.","D":"Profit margin equals net profit divided by revenue, multiplied by 100. Fjord Optics earns $45,000 net profit on $500,000 revenue, so 45,000 divided by 500,000 times 100 gives 9%."}}},{"id":"P1_U5_MCQ_1821","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1821","question":"A craft brewery in Brno, Czech Republic normally lets customers pay within 30 days but offers wholesalers 90 days instead. What is the main benefit to the brewery of allowing trade credit?","options":{"A":"It removes all need for finance","B":"It can help build customer loyalty and sales","C":"It guarantees immediate cash payment","D":"It eliminates the cost of raw materials"},"correctOption":"B","correctAnswer":"It can help build customer loyalty and sales","questionType":"MCQ","explanation":{"correct_reason":"Granting trade credit lets wholesalers pay later, which can attract and retain customers and so raise sales for the Brno brewery. The benefit is commercial, though it also delays the brewery's own cash receipts.","distractor_reasons":{"A":"Trade credit does not remove the need for finance; the brewery still needs funds to produce beer before customers pay.","B":"Granting trade credit lets wholesalers pay later, which can attract and retain customers and so raise sales for the Brno brewery. The benefit is commercial, though it also delays the brewery's own cash receipts.","C":"Trade credit delays rather than guarantees immediate payment; cash arrives after the agreed credit period, not at the point of sale.","D":"The cost of raw materials is unchanged by payment terms; trade credit concerns when customers pay, not what the ingredients cost."}}},{"id":"P1_U5_MCQ_1822","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1822","question":"A hotel in Chiang Mai, Thailand opens the month with a cash balance of $12,000, records net cash inflow of $5,000 during the month, and expects no other movements. What is the closing cash balance?","options":{"A":"$7,000","B":"$12,000","C":"$5,000","D":"$17,000"},"correctOption":"D","correctAnswer":"$17,000","questionType":"MCQ","explanation":{"correct_reason":"Closing cash balance equals the opening balance plus net cash flow. The Chiang Mai hotel starts with $12,000 and gains a net $5,000 during the month, so $12,000 plus $5,000 gives a closing balance of $17,000.","distractor_reasons":{"A":"$7,000 comes from subtracting the net inflow from the opening balance; a positive net cash flow increases the balance rather than reducing it.","B":"$12,000 is only the opening balance and entirely ignores the $5,000 net cash inflow recorded during the month, so it cannot be the closing figure.","C":"$5,000 is the net cash flow itself, not the closing balance; it must be added to the opening $12,000 to give $17,000.","D":"Closing cash balance equals the opening balance plus net cash flow. The Chiang Mai hotel starts with $12,000 and gains a net $5,000 during the month, so $12,000 plus $5,000 gives a closing balance of $17,000."}}},{"id":"P1_U5_MCQ_1823","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1823","question":"Riga Woodcrafts in Riga, Latvia owns sanding machines expected to last five years. Each year the accountant records an annual charge that spreads the machine's cost over its working life. What is this charge called?","options":{"A":"Depreciation","B":"Amortisation of a liability","C":"A current liability","D":"Gross profit"},"correctOption":"A","correctAnswer":"Depreciation","questionType":"MCQ","explanation":{"correct_reason":"Depreciation allocates the cost of a non-current asset such as Riga Woodcrafts' sanding machines across their useful life, here five years. It matches the machines' cost to the periods that benefit from their use.","distractor_reasons":{"A":"Depreciation allocates the cost of a non-current asset such as Riga Woodcrafts' sanding machines across their useful life, here five years. It matches the machines' cost to the periods that benefit from their use.","B":"Amortisation of a liability is not the term for spreading an asset's cost; the machines are assets, not amounts the business owes.","C":"A current liability is a short-term debt; the annual charge for using a machine is an expense, not an obligation to pay an outside party.","D":"Gross profit is revenue minus cost of sales; it is not the yearly allocation of a machine's cost over five years."}}},{"id":"P1_U5_MCQ_1824","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1824","question":"Wetherby Print Studio, a commercial printing business in Leeds, England, has total equity of $260,000 and non-current liabilities of $140,000. Its accountant is preparing the year-end statement of financial position. Which figure represents its capital employed?","options":{"A":"$120,000","B":"$260,000","C":"$400,000","D":"$140,000"},"correctOption":"C","correctAnswer":"$400,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is total equity plus non-current liabilities, the long-term funds invested in the Leeds printer. Adding $260,000 of equity to $140,000 of long-term liabilities gives $400,000 of capital employed.","distractor_reasons":{"A":"$120,000 wrongly subtracts $140,000 from $260,000; the two long-term funding sources of equity and loans are added together, not subtracted.","B":"$260,000 is the equity alone; capital employed also includes the $140,000 of non-current liabilities that help fund the business's long-term assets.","C":"Capital employed is total equity plus non-current liabilities, the long-term funds invested in the Leeds printer. Adding $260,000 of equity to $140,000 of long-term liabilities gives $400,000 of capital employed.","D":"$140,000 is only the non-current liabilities; the owners' $260,000 stake must also be included to arrive at the full capital employed figure."}}},{"id":"P1_U5_MCQ_1825","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1825","question":"Alessi Stationery, a chain of three shops in Turin, Italy, has current assets of $96,000 and current liabilities of $60,000. The owner wants to check short-term liquidity before renewing a supplier contract. Calculate its current ratio.","options":{"A":"1.6 : 1","B":"0.6 : 1","C":"$36,000","D":"1.6%"},"correctOption":"A","correctAnswer":"1.6 : 1","questionType":"MCQ","explanation":{"correct_reason":"Current ratio is current assets divided by current liabilities. For the Turin stationery chain, $96,000 divided by $60,000 equals 1.6, so the current ratio is 1.6 : 1, meaning current assets exceed short-term debts.","distractor_reasons":{"A":"Current ratio is current assets divided by current liabilities. For the Turin stationery chain, $96,000 divided by $60,000 equals 1.6, so the current ratio is 1.6 : 1, meaning current assets exceed short-term debts.","B":"0.6 : 1 inverts the ratio by dividing current liabilities by current assets; the correct comparison places current assets first.","C":"$36,000 is the working capital difference between the two figures, not a ratio; the current ratio compares them by division.","D":"1.6% incorrectly treats the ratio as a percentage; the current ratio is expressed as a proportion such as 1.6 : 1."}}},{"id":"P1_U5_MCQ_1826","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1826","question":"Silesia Metalworks in Wrocław, Poland needs new presses costing $200,000 but wants to keep its cash for raw materials and avoid owning the machines after the agreement ends. Which method of finance fits these requirements best?","options":{"A":"A 15-year mortgage","B":"Issue of preference shares","C":"Retained profit from previous years","D":"Leasing the presses"},"correctOption":"D","correctAnswer":"Leasing the presses","questionType":"MCQ","explanation":{"correct_reason":"Leasing lets Silesia Metalworks use the $200,000 presses without paying the full price upfront, preserving cash for raw materials. Ownership usually stays with the lessor at the end, matching the firm's wish not to own the machines.","distractor_reasons":{"A":"A 15-year mortgage ties up the presses as security over a long period and does not address the wish to avoid ownership at the end of the agreement.","B":"Issuing preference shares raises permanent equity, brings in new investors and does not solve the need to conserve cash or avoid owning the presses.","C":"Retained profit from earlier years would use the firm's own cash, the very resource Silesia Metalworks wants to keep for buying raw materials.","D":"Leasing lets Silesia Metalworks use the $200,000 presses without paying the full price upfront, preserving cash for raw materials. Ownership usually stays with the lessor at the end, matching the firm's wish not to own the machines."}}},{"id":"P1_U5_MCQ_1827","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1827","question":"A rice mill in Can Tho, Vietnam is drafting its monthly cash flow forecast for the next quarter. The owner mainly wants to spot periods when cash might run out so action can be taken early. What is a key purpose of a cash flow forecast?","options":{"A":"Calculating annual tax liability","B":"Identifying possible future cash shortages","C":"Valuing the firm's non-current assets","D":"Determining the market share of the business"},"correctOption":"B","correctAnswer":"Identifying possible future cash shortages","questionType":"MCQ","explanation":{"correct_reason":"Forecasting expected receipts and payments lets the Can Tho mill see months where outflows may exceed inflows, so it can arrange finance or delay spending. Spotting possible future cash shortages before they happen is a central purpose of the forecast.","distractor_reasons":{"A":"Tax liability is worked out from profit figures in the profit and loss account, not from the timing of cash movements in a forecast.","B":"Forecasting expected receipts and payments lets the Can Tho mill see months where outflows may exceed inflows, so it can arrange finance or delay spending. Spotting possible future cash shortages before they happen is a central purpose of the forecast.","C":"Valuing non-current assets happens in the statement of financial position and does not depend on projecting monthly cash receipts and payments.","D":"Market share is a marketing measure comparing sales with the total market; it is unrelated to predicting the mill's cash position."}}},{"id":"P1_U5_MCQ_1828","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1828","question":"Cebu Coastal Crafts in Cebu, Philippines reports gross profit of $180,000 for the year. Operating expenses, including rent and salaries, totaled $95,000. What was the operating profit (net profit before tax) of the business?","options":{"A":"$275,000","B":"$95,000","C":"$85,000","D":"$180,000"},"correctOption":"C","correctAnswer":"$85,000","questionType":"MCQ","explanation":{"correct_reason":"Operating profit is gross profit minus operating expenses. Cebu Coastal Crafts earned $180,000 gross profit and spent $95,000 on rent and salaries, so $180,000 minus $95,000 gives $85,000 of operating profit before tax.","distractor_reasons":{"A":"$275,000 adds gross profit and expenses together; operating profit requires subtracting the $95,000 expenses from gross profit, not adding them.","B":"$95,000 is only the operating expenses themselves; the profit is the amount left after these costs are deducted from gross profit.","C":"Operating profit is gross profit minus operating expenses. Cebu Coastal Crafts earned $180,000 gross profit and spent $95,000 on rent and salaries, so $180,000 minus $95,000 gives $85,000 of operating profit before tax.","D":"$180,000 is the gross profit, the starting figure in the calculation; expenses of $95,000 must be subtracted before operating profit is reached."}}},{"id":"P1_U5_MCQ_1829","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1829","question":"A furniture retailer in Plovdiv, Bulgaria is preparing its statement of financial position. It has $30,000 owed by customers who bought on credit, $15,000 cash in hand and a warehouse worth $200,000. How should the $30,000 owed by customers be classified?","options":{"A":"As a non-current asset","B":"As a current liability","C":"As owners' equity","D":"As a current asset"},"correctOption":"D","correctAnswer":"As a current asset","questionType":"MCQ","explanation":{"correct_reason":"The $30,000 owed by credit customers is trade receivables, a current asset because it is expected to be collected within a year. It is part of the Plovdiv retailer's working capital, alongside the $15,000 cash held.","distractor_reasons":{"A":"A non-current asset is held for long-term use, such as the warehouse; money owed by customers is a short-term claim, so it is current.","B":"A current liability is money the business owes to others; receivables are amounts owed to the business, the opposite situation entirely.","C":"Owners' equity is the proprietor's stake after liabilities are deducted; amounts due from customers are assets, not part of the owners' claim.","D":"The $30,000 owed by credit customers is trade receivables, a current asset because it is expected to be collected within a year. It is part of the Plovdiv retailer's working capital, alongside the $15,000 cash held."}}},{"id":"P1_U5_MCQ_1830","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1830","question":"Slavyansk Snacks, a food manufacturer in Sofia, Bulgaria, had revenue of $300,000 and gross profit of $90,000 last year. What was its gross profit margin?","options":{"A":"30%","B":"3.3%","C":"$210,000","D":"70%"},"correctOption":"A","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin equals gross profit divided by revenue, multiplied by 100. Slavyansk Snacks made $90,000 gross profit on $300,000 revenue, so 90,000 divided by 300,000 times 100 gives 30%.","distractor_reasons":{"A":"Gross profit margin equals gross profit divided by revenue, multiplied by 100. Slavyansk Snacks made $90,000 gross profit on $300,000 revenue, so 90,000 divided by 300,000 times 100 gives 30%.","B":"3.3% comes from dividing revenue by gross profit, reversing the fraction; the margin is gross profit as a share of revenue.","C":"$210,000 is revenue minus gross profit, which is simply the cost of sales, not a percentage margin figure relating profit to the $300,000 revenue.","D":"70% is the cost of sales as a share of revenue; the gross profit margin is the remaining 30% of the revenue."}}},{"id":"P1_U5_MCQ_1831","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1831","question":"A software startup in Skopje, North Macedonia has a promising app but little trading history and cannot obtain a bank loan. It seeks investment from specialists who will take an equity stake and offer business expertise. Which source of finance is this?","options":{"A":"A bank overdraft","B":"Government grant","C":"Venture capital","D":"Trade credit"},"correctOption":"C","correctAnswer":"Venture capital","questionType":"MCQ","explanation":{"correct_reason":"Venture capital provides equity finance to young, high-growth firms like the Skopje app developer, usually with expert advice and no fixed repayment. It suits a business with little trading history that cannot secure a conventional bank loan.","distractor_reasons":{"A":"A bank overdraft is short-term debt requiring repayment and is unlikely to be offered to a startup with minimal trading history and no security.","B":"A government grant does not usually bring an equity stake or hands-on business expertise; the specialist investors described in the scenario take ownership.","C":"Venture capital provides equity finance to young, high-growth firms like the Skopje app developer, usually with expert advice and no fixed repayment. It suits a business with little trading history that cannot secure a conventional bank loan.","D":"Trade credit is simply delayed payment from suppliers; it cannot fund an app startup or provide the described equity investment and expertise."}}},{"id":"P1_U5_MCQ_1832","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1832","question":"A taxi firm in Antwerp, Belgium expects total cash inflows of $80,000 in July and total cash outflows of $68,000. What is its net cash flow for July?","options":{"A":"$148,000","B":"$12,000","C":"-$12,000","D":"$68,000"},"correctOption":"B","correctAnswer":"$12,000","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is total inflows minus total outflows. The Antwerp taxi firm expects $80,000 of inflows and $68,000 of outflows, so $80,000 minus $68,000 gives a positive net cash flow of $12,000 for July.","distractor_reasons":{"A":"$148,000 adds the two figures together; net cash flow is the difference between receipts and payments, not their combined sum for July.","B":"Net cash flow is total inflows minus total outflows. The Antwerp taxi firm expects $80,000 of inflows and $68,000 of outflows, so $80,000 minus $68,000 gives a positive net cash flow of $12,000 for July.","C":"Negative $12,000 uses the wrong sign in the answer; because the $80,000 inflows exceed the $68,000 outflows, the net cash flow is positive.","D":"$68,000 is only the outflows on their own; the net figure must compare those payments with the $80,000 of inflows expected during July."}}},{"id":"P1_U5_MCQ_1833","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1833","question":"A bakery in Graz, Austria reports gross profit of $120,000 and net profit of $28,000. The owner asks what explains the difference between the two figures. Which explanation is correct?","options":{"A":"Operating expenses and other costs were deducted from gross profit","B":"Gross profit always equals net profit","C":"The bakery sold more than it produced","D":"Net profit is calculated before cost of sales"},"correctOption":"A","correctAnswer":"Operating expenses and other costs were deducted from gross profit","questionType":"MCQ","explanation":{"correct_reason":"Net profit is lower than gross profit because overhead expenses such as rent, wages and interest are subtracted after gross profit. For the Graz bakery the fall from $120,000 to $28,000 reflects $92,000 of such expenses.","distractor_reasons":{"A":"Net profit is lower than gross profit because overhead expenses such as rent, wages and interest are subtracted after gross profit. For the Graz bakery the fall from $120,000 to $28,000 reflects $92,000 of such expenses.","B":"Gross profit and net profit are rarely equal; net profit is gross profit after deducting operating expenses, taxes and other charges.","C":"Whether the bakery sold more than it produced affects inventories, not the basic relationship between gross profit and net profit in the profit and loss account.","D":"Net profit is calculated after, not before, cost of sales; cost of sales is deducted first to reach gross profit, then expenses are subtracted."}}},{"id":"P1_U5_MCQ_1834","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1834","question":"A textile wholesaler in Izmir, Turkey lists total assets of $540,000 and total liabilities of $230,000 in its statement of financial position. What is the net assets figure?","options":{"A":"$770,000","B":"$230,000","C":"$540,000","D":"$310,000"},"correctOption":"D","correctAnswer":"$310,000","questionType":"MCQ","explanation":{"correct_reason":"Net assets equal total assets minus total liabilities. The Izmir wholesaler owns $540,000 of assets and owes $230,000, so $540,000 minus $230,000 gives $310,000 of net assets, which equals total equity.","distractor_reasons":{"A":"$770,000 adds assets and liabilities, which is meaningless; net assets are found by subtracting what is owed from what is owned.","B":"$230,000 is the total liabilities alone; net assets are the remainder left after these obligations are deducted from the $540,000 of assets.","C":"$540,000 is the total assets; the liabilities of $230,000 must be subtracted from that figure to find the owners' net claim on the business.","D":"Net assets equal total assets minus total liabilities. The Izmir wholesaler owns $540,000 of assets and owes $230,000, so $540,000 minus $230,000 gives $310,000 of net assets, which equals total equity."}}},{"id":"P1_U5_MCQ_1835","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1835","question":"Two retail chains in different countries report current ratios of 2.1 : 1 and 1.6 : 1. An analyst wants to compare their liquidity. What is a key limitation of using ratio analysis for this comparison?","options":{"A":"Ratios never involve percentages","B":"Both chains must have identical sales revenue","C":"Differences in accounting policies can distort comparisons","D":"The current ratio cannot be calculated for retailers"},"correctOption":"C","correctAnswer":"Differences in accounting policies can distort comparisons","questionType":"MCQ","explanation":{"correct_reason":"Ratios are only as reliable as the data behind them, and firms may value inventory or depreciate assets differently. Comparing the two chains' current ratios can therefore be distorted by differing accounting policies, a recognised limitation of ratio analysis.","distractor_reasons":{"A":"Many ratios, such as profit margin and return on capital employed, are expressed as percentages, so the claim that ratios never use percentages is false.","B":"Comparisons do not require identical sales revenue; ratios standardise figures precisely so firms of different sizes can be compared meaningfully.","C":"Ratios are only as reliable as the data behind them, and firms may value inventory or depreciate assets differently. Comparing the two chains' current ratios can therefore be distorted by differing accounting policies, a recognised limitation of ratio analysis.","D":"The current ratio is perfectly calculable for retailers, whose current assets and current liabilities are usually substantial and clearly reported."}}},{"id":"P1_U5_MCQ_1836","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1836","question":"A cake shop in Cork, Ireland is owed $25,000 by restaurant customers and needs cash immediately to pay a supplier. A finance company offers to buy these debts at a discount for prompt cash. What is this arrangement called?","options":{"A":"Overdraft protection","B":"Factoring","C":"Preference share issue","D":"Retained earnings"},"correctOption":"B","correctAnswer":"Factoring","questionType":"MCQ","explanation":{"correct_reason":"Factoring involves selling short-term receivables to a specialist for immediate cash, usually less a fee. For the Cork cake shop it converts the $25,000 owed by restaurants into cash sooner, helping pay the supplier without waiting for credit terms.","distractor_reasons":{"A":"Overdraft protection is a bank facility linked to an account; it does not involve selling the shop's outstanding customer debts to a finance company.","B":"Factoring involves selling short-term receivables to a specialist for immediate cash, usually less a fee. For the Cork cake shop it converts the $25,000 owed by restaurants into cash sooner, helping pay the supplier without waiting for credit terms.","C":"Issuing preference shares raises long-term equity capital from investors and does not convert the shop's existing receivables into immediate cash as described.","D":"Retained earnings are profits kept in the business, not a method of turning amounts owed by customers into cash at a discount."}}},{"id":"P1_U5_MCQ_1837","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1837","question":"A music school in Adelaide, Australia is listing the rows of its monthly cash flow forecast. Which of the following would correctly appear as a cash outflow in the forecast?","options":{"A":"Fees received from new students","B":"A bank loan received in March","C":"Payment of rent on the premises","D":"A grant from the local council"},"correctOption":"C","correctAnswer":"Payment of rent on the premises","questionType":"MCQ","explanation":{"correct_reason":"Cash outflows are payments made by the business, such as the rent the Adelaide music school pays on its premises. The other choices are all cash inflows, being receipts from students, a loan and a council grant.","distractor_reasons":{"A":"Fees from students are cash inflows, money coming into the school from customers, not payments made by the business to any supplier.","B":"A bank loan received is a cash inflow because it increases the school's bank balance, even though it creates a liability to repay later.","C":"Cash outflows are payments made by the business, such as the rent the Adelaide music school pays on its premises. The other choices are all cash inflows, being receipts from students, a loan and a council grant.","D":"A council grant is a receipt of cash, so it belongs among inflows rather than among the school's payments and outflows."}}},{"id":"P1_U5_MCQ_1838","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1838","question":"A hardware wholesaler in Monterrey, Mexico buys a batch of tools for $50,000 and sells the entire batch for $65,000. The finance assistant wants to express the gross profit as a percentage of the purchase cost. What is its mark-up on cost?","options":{"A":"30%","B":"23.1%","C":"$15,000","D":"15%"},"correctOption":"A","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Mark-up on cost is gross profit divided by cost of sales, times 100. The Monterrey wholesaler earns $15,000 gross profit on a $50,000 cost, so 15,000 divided by 50,000 times 100 gives a 30% mark-up.","distractor_reasons":{"A":"Mark-up on cost is gross profit divided by cost of sales, times 100. The Monterrey wholesaler earns $15,000 gross profit on a $50,000 cost, so 15,000 divided by 50,000 times 100 gives a 30% mark-up.","B":"23.1% expresses the $15,000 profit as a percentage of the $65,000 selling price, which is the gross profit margin, not the mark-up on cost.","C":"$15,000 is the gross profit in dollars, not a percentage; the question asks specifically for the mark-up on cost as a percentage.","D":"15% wrongly divides $15,000 by $100,000 or otherwise confuses the profit figure with a percentage; the correct mark-up on the $50,000 cost is 30%."}}},{"id":"P1_U5_MCQ_1839","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1839","question":"A travel agency in Wellington, New Zealand has several obligations: $8,000 due to an airline next week, a $120,000 loan due in ten years, and $4,000 of wages. Which item is a non-current liability?","options":{"A":"The $8,000 due to the airline","B":"The $120,000 loan due in ten years","C":"The $4,000 of wages","D":"All three obligations"},"correctOption":"B","correctAnswer":"The $120,000 loan due in ten years","questionType":"MCQ","explanation":{"correct_reason":"A non-current liability is due after more than one year, so the $120,000 loan repayable in ten years qualifies. The airline bill and wages are current liabilities because they must be settled within weeks in the Wellington agency.","distractor_reasons":{"A":"The $8,000 owed to the airline is due next week, so it is a current liability, not one falling due after a year.","B":"A non-current liability is due after more than one year, so the $120,000 loan repayable in ten years qualifies. The airline bill and wages are current liabilities because they must be settled within weeks in the Wellington agency.","C":"Wages of $4,000 are a short-term obligation payable almost immediately, so they are a current liability rather than a long-term one.","D":"The three obligations have very different due dates, so they cannot all be non-current; only the ten-year loan meets the definition."}}},{"id":"P1_U5_MCQ_1840","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1840","question":"A pharmacy chain in Malmö, Sweden has current assets of $120,000, including $30,000 of inventory, and current liabilities of $60,000. Calculate its acid test ratio.","options":{"A":"2 : 1","B":"0.5 : 1","C":"1 : 1","D":"1.5 : 1"},"correctOption":"D","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test ratio is current assets minus inventory, divided by current liabilities. For the Malmö chain that is $120,000 less $30,000, giving $90,000, divided by $60,000, which equals 1.5 : 1.","distractor_reasons":{"A":"2 : 1 is the current ratio, $120,000 divided by $60,000, which includes inventory; the acid test removes the $30,000 of stock.","B":"0.5 : 1 inverts the correct calculation and also ignores the inventory adjustment; the acid test is 1.5 : 1.","C":"1 : 1 would result from subtracting the $60,000 liabilities rather than the $30,000 inventory; the acid test deducts inventory only.","D":"The acid test ratio is current assets minus inventory, divided by current liabilities. For the Malmö chain that is $120,000 less $30,000, giving $90,000, divided by $60,000, which equals 1.5 : 1."}}},{"id":"P1_U5_MCQ_1841","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1841","question":"A ceramics studio in Valencia, Spain is comparing borrowing with issuing new shares to fund a kiln. Which of these is a disadvantage of borrowing rather than using equity finance?","options":{"A":"Interest must be paid even if the business makes a loss","B":"Existing owners keep full control","C":"No repayment of the principal is ever needed","D":"Profits do not have to be shared"},"correctOption":"A","correctAnswer":"Interest must be paid even if the business makes a loss","questionType":"MCQ","explanation":{"correct_reason":"Borrowing creates a contractual obligation to pay interest regardless of trading results, which is a drawback for the Valencia studio if profits fall. Equity finance does not force fixed interest payments, though it shares ownership and profits.","distractor_reasons":{"A":"Borrowing creates a contractual obligation to pay interest regardless of trading results, which is a drawback for the Valencia studio if profits fall. Equity finance does not force fixed interest payments, though it shares ownership and profits.","B":"Keeping full control is an advantage of borrowing, not a disadvantage, because no new shareholders are introduced to the business.","C":"Loan principal normally must be repaid, so saying no repayment is ever needed is incorrect and is certainly not a drawback of debt.","D":"Not having to share profits is an advantage of borrowing; it is shareholders who expect a share of profits through dividends."}}},{"id":"P1_U5_MCQ_1842","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1842","question":"A courier company in Turku, Finland expects a cash surplus in each of the next four months after preparing its forecast. What is a sensible use of that surplus?","options":{"A":"Increase monthly cash outflows immediately","B":"Ignore the forecast and spend freely","C":"Write off all current assets","D":"Repay part of an outstanding loan"},"correctOption":"D","correctAnswer":"Repay part of an outstanding loan","questionType":"MCQ","explanation":{"correct_reason":"A forecast surplus means cash is available after expected commitments, so repaying part of an outstanding loan reduces interest costs for the Turku courier. It is a productive use of spare cash rather than wasteful spending.","distractor_reasons":{"A":"Deliberately increasing outflows simply because cash is available wastes the surplus instead of using it to strengthen the firm's finances.","B":"Ignoring the forecast defeats the whole purpose of planning; a forecast surplus should be managed deliberately, not spent without thought or control.","C":"Writing off current assets would destroy valuable resources and does not represent a sensible use of a genuine cash surplus.","D":"A forecast surplus means cash is available after expected commitments, so repaying part of an outstanding loan reduces interest costs for the Turku courier. It is a productive use of spare cash rather than wasteful spending."}}},{"id":"P1_U5_MCQ_1843","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1843","question":"The accountant of a hotel in Split, Croatia has prepared a profit and loss account for the year. What does this financial statement mainly show?","options":{"A":"The financial performance over a period, showing income and expenses","B":"The cash balance at the end of each month","C":"The exact market value of the hotel building","D":"The number of shares issued to investors"},"correctOption":"A","correctAnswer":"The financial performance over a period, showing income and expenses","questionType":"MCQ","explanation":{"correct_reason":"A profit and loss account reports income and expenses over a period, showing how the Split hotel moved from revenue to gross profit and finally net profit. It measures financial performance rather than cash timing or asset valuations.","distractor_reasons":{"A":"A profit and loss account reports income and expenses over a period, showing how the Split hotel moved from revenue to gross profit and finally net profit. It measures financial performance rather than cash timing or asset valuations.","B":"Monthly cash balances are shown in a cash flow forecast, not in the profit and loss account, which covers a full accounting period.","C":"The market value of the building is not recorded in the profit and loss account; historical cost appears in the statement of financial position.","D":"The number of shares issued is a financing detail, not part of the profit and loss account's report of trading performance."}}},{"id":"P1_U5_MCQ_1844","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1844","question":"A bookshop chain in Utrecht, Netherlands reports current assets of $215,000 and current liabilities of $140,000. The finance director wants to measure the short-term funds left after meeting obligations due within a year. What is its working capital?","options":{"A":"$355,000","B":"$140,000","C":"$75,000","D":"$215,000"},"correctOption":"C","correctAnswer":"$75,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital equals current assets minus current liabilities. The Utrecht bookshop has $215,000 of current assets and $140,000 of current liabilities, so $215,000 minus $140,000 gives $75,000 of working capital.","distractor_reasons":{"A":"$355,000 adds the two figures together, but working capital is the difference between short-term assets and short-term debts, here $75,000.","B":"$140,000 is the current liabilities alone; working capital is what remains of the $215,000 current assets after these obligations are covered.","C":"Working capital equals current assets minus current liabilities. The Utrecht bookshop has $215,000 of current assets and $140,000 of current liabilities, so $215,000 minus $140,000 gives $75,000 of working capital.","D":"$215,000 is the current assets; the current liabilities of $140,000 must be deducted from that total to find the working capital of $75,000."}}},{"id":"P1_U5_MCQ_1845","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1845","question":"A clothing manufacturer in Dhaka, Bangladesh saw its gross profit margin fall from 35% to 26% while revenue stayed unchanged. What is the most likely explanation?","options":{"A":"The cost of sales rose relative to revenue","B":"The business sold fewer garments than before","C":"Its current ratio improved","D":"Operating expenses were reduced"},"correctOption":"A","correctAnswer":"The cost of sales rose relative to revenue","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit as a percentage of revenue. With revenue unchanged, a fall from 35% to 26% means gross profit shrank, most likely because the Dhaka manufacturer's cost of sales increased relative to sales.","distractor_reasons":{"A":"Gross profit margin is gross profit as a percentage of revenue. With revenue unchanged, a fall from 35% to 26% means gross profit shrank, most likely because the Dhaka manufacturer's cost of sales increased relative to sales.","B":"Revenue stayed the same, so a fall in units sold is inconsistent with the information; the margin fell despite unchanged revenue.","C":"The current ratio measures liquidity and does not explain a change in the gross profit margin derived from revenue and cost of sales.","D":"Reducing operating expenses would raise net profit, not lower the gross profit margin, which is calculated before such overhead expenses are deducted."}}},{"id":"P1_U5_MCQ_1846","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1846","question":"A florist in Pretoria, South Africa wants a new delivery van but cannot afford a large cash payment. It prefers fixed monthly payments and the option to own the van after the final payment. Which source of finance suits this?","options":{"A":"A government grant","B":"Issuing ordinary shares","C":"A bank overdraft","D":"Hire purchase"},"correctOption":"D","correctAnswer":"Hire purchase","questionType":"MCQ","explanation":{"correct_reason":"Hire purchase lets the Pretoria florist use the van immediately while paying in instalments, with ownership transferring after the last payment. It spreads the cost without the large upfront outlay the florist cannot afford.","distractor_reasons":{"A":"A government grant is not normally available for an ordinary delivery van and would not involve the agreed instalment payments described.","B":"Issuing shares raises permanent capital and dilutes existing ownership; it is an unsuitable and disproportionate way to fund just one delivery van.","C":"A bank overdraft is a short-term facility repayable on demand; it does not provide staged payments ending in ownership of a van.","D":"Hire purchase lets the Pretoria florist use the van immediately while paying in instalments, with ownership transferring after the last payment. It spreads the cost without the large upfront outlay the florist cannot afford."}}},{"id":"P1_U5_MCQ_1847","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1847","question":"A paper mill in Oulu, Finland is preparing a cash flow forecast. Which of the following should be recorded as a cash outflow in the forecast?","options":{"A":"Payment received from a customer","B":"Payment to a supplier of wood pulp","C":"A loan from the bank","D":"Interest received on deposits"},"correctOption":"B","correctAnswer":"Payment to a supplier of wood pulp","questionType":"MCQ","explanation":{"correct_reason":"Cash outflows record payments the business makes, such as the mill's payment to its wood pulp supplier in Oulu. The other options are receipts and therefore appear as inflows in the cash flow forecast.","distractor_reasons":{"A":"Cash from a customer is a receipt, so it is an inflow that increases the bank balance rather than an outflow.","B":"Cash outflows record payments the business makes, such as the mill's payment to its wood pulp supplier in Oulu. The other options are receipts and therefore appear as inflows in the cash flow forecast.","C":"A bank loan brings cash into the business; although it is a liability, the receipt itself is recorded as an inflow.","D":"Interest received on deposits is income in cash form, so it belongs among the mill's cash inflows, not among its payments and outflows."}}},{"id":"P1_U5_MCQ_1848","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1848","question":"A logistics company in Gdynia, Poland recorded gross profit of $320,000 during the year. Its operating expenses totaled $185,000. What was the company's operating profit?","options":{"A":"$505,000","B":"$185,000","C":"$135,000","D":"$320,000"},"correctOption":"C","correctAnswer":"$135,000","questionType":"MCQ","explanation":{"correct_reason":"Operating profit is gross profit minus operating expenses. The Gdynia logistics firm earned $320,000 gross profit and spent $185,000 on overheads, so $320,000 minus $185,000 gives $135,000 of operating profit.","distractor_reasons":{"A":"$505,000 adds the $320,000 gross profit and the $185,000 expenses together, but operating profit requires deducting those expenses from the gross profit.","B":"$185,000 is the operating expenses themselves; the operating profit is the balance left after paying them out of the $320,000 gross profit.","C":"Operating profit is gross profit minus operating expenses. The Gdynia logistics firm earned $320,000 gross profit and spent $185,000 on overheads, so $320,000 minus $185,000 gives $135,000 of operating profit.","D":"$320,000 is the gross profit, the starting point; the $185,000 of operating expenses must be subtracted from it before operating profit is found."}}},{"id":"P1_U5_MCQ_1849","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1849","question":"A gym in Melbourne, Australia buys new exercise equipment for $60,000, paying with a new eight-year bank loan. What is the immediate effect on its statement of financial position?","options":{"A":"Current assets and current liabilities both rise","B":"Owners' equity increases by $60,000","C":"Total assets fall by $60,000","D":"Non-current assets and non-current liabilities both rise"},"correctOption":"D","correctAnswer":"Non-current assets and non-current liabilities both rise","questionType":"MCQ","explanation":{"correct_reason":"Buying equipment adds a non-current asset of $60,000, while the eight-year loan creates a non-current liability of the same amount. Both sides of the Melbourne gym's statement of financial position therefore increase by $60,000.","distractor_reasons":{"A":"Neither the equipment nor the eight-year loan is short-term, so current assets and current liabilities are not the ones affected.","B":"A loan is not owners' equity; equity rises only from fresh owner investment or retained profit, never from borrowing money from a bank.","C":"Assets increase because the gym now owns the equipment; they do not fall, since the $60,000 cash inflow is immediately spent on the asset.","D":"Buying equipment adds a non-current asset of $60,000, while the eight-year loan creates a non-current liability of the same amount. Both sides of the Melbourne gym's statement of financial position therefore increase by $60,000."}}},{"id":"P1_U5_MCQ_1850","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1850","question":"A dairy farm in Waikato, New Zealand reports operating profit of $60,000 and capital employed of $400,000 for the latest financial year. Its adviser wants to know how much profit each dollar of long-term capital generates. Calculate its return on capital employed.","options":{"A":"15%","B":"6.7%","C":"$340,000","D":"66.7%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, times 100. The Waikato farm earns $60,000 on $400,000 of capital, so 60,000 divided by 400,000 times 100 gives 15%.","distractor_reasons":{"A":"Return on capital employed is operating profit divided by capital employed, times 100. The Waikato farm earns $60,000 on $400,000 of capital, so 60,000 divided by 400,000 times 100 gives 15%.","B":"6.7% comes from dividing capital employed by operating profit, reversing the formula; the return is profit per unit of capital.","C":"$340,000 is capital employed minus operating profit, a simple difference, not a percentage measuring the return earned on the capital.","D":"66.7% would require operating profit of about $267,000 on capital employed of $400,000; with profit of only $60,000 the actual return is 15%."}}},{"id":"P1_U5_MCQ_1851","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1851","question":"A food wholesaler in Bratislava, Slovakia owns an unused delivery depot that it no longer needs. The directors decide to sell the building and use the proceeds to fund a new refrigerated warehouse. Which source of finance does the sale represent?","options":{"A":"A bank overdraft","B":"Issuing ordinary shares","C":"Sale of assets","D":"Trade credit"},"correctOption":"C","correctAnswer":"Sale of assets","questionType":"MCQ","explanation":{"correct_reason":"Selling the unwanted depot converts an existing asset into cash, which is a source of finance known as disposal of assets. The Bratislava wholesaler raises funds for the refrigerated warehouse without borrowing or giving away any ownership.","distractor_reasons":{"A":"A bank overdraft is borrowed short-term finance that must be repaid; selling the depot raises the wholesaler's own cash instead.","B":"Issuing ordinary shares brings in new owners and fresh share capital; the described transaction simply converts one unwanted asset into cash for the firm.","C":"Selling the unwanted depot converts an existing asset into cash, which is a source of finance known as disposal of assets. The Bratislava wholesaler raises funds for the refrigerated warehouse without borrowing or giving away any ownership.","D":"Trade credit is delayed payment to suppliers and creates no cash from the firm's own resources, unlike selling a surplus building."}}},{"id":"P1_U5_MCQ_1852","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1852","question":"A pottery in Kuching, Malaysia starts April with a cash balance of $8,000. Its forecast shows net cash outflow of $3,000 during the month. What closing cash balance should the pottery record at the end of April?","options":{"A":"$11,000","B":"$5,000","C":"$3,000","D":"-$5,000"},"correctOption":"B","correctAnswer":"$5,000","questionType":"MCQ","explanation":{"correct_reason":"Closing cash balance is the opening balance plus net cash flow. The Kuching pottery begins with $8,000 and has a net outflow of $3,000, so $8,000 minus $3,000 gives a closing cash balance of $5,000 for April.","distractor_reasons":{"A":"$11,000 results from adding the $3,000 outflow to the opening cash, but an outflow reduces the balance, so subtraction is actually required.","B":"Closing cash balance is the opening balance plus net cash flow. The Kuching pottery begins with $8,000 and has a net outflow of $3,000, so $8,000 minus $3,000 gives a closing cash balance of $5,000 for April.","C":"$3,000 is the net outflow itself, not the closing balance; it must be deducted from the $8,000 opening cash to leave $5,000.","D":"Negative $5,000 wrongly treats the outflow as larger than the opening balance; $8,000 less $3,000 is still a positive $5,000."}}},{"id":"P1_U5_MCQ_1853","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1853","question":"A sports equipment maker in Guadalajara, Mexico is constructing its profit and loss account. The accountant wants to know which item must be deducted from sales revenue to arrive at gross profit. Which figure is it?","options":{"A":"Cost of sales","B":"Rent of the factory","C":"Interest on a loan","D":"Corporation tax"},"correctOption":"A","correctAnswer":"Cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is sales revenue minus the direct cost of sales. For the Guadalajara sports maker, the materials and labour directly used in producing the goods sold are deducted first, leaving gross profit before overheads such as rent or interest.","distractor_reasons":{"A":"Gross profit is sales revenue minus the direct cost of sales. For the Guadalajara sports maker, the materials and labour directly used in producing the goods sold are deducted first, leaving gross profit before overheads such as rent or interest.","B":"Factory rent is an overhead expense deducted after gross profit, not before it, because it is not a direct cost of each item sold.","C":"Interest on a loan is a finance cost subtracted later in the profit and loss account, after gross profit has been calculated.","D":"Corporation tax is charged on profit near the end of the profit and loss account and is not deducted from revenue to find gross profit."}}},{"id":"P1_U5_MCQ_1854","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1854","question":"A pharmaceutical firm in Basel, Switzerland has several assets: $400,000 of laboratory equipment, $60,000 of cash, $90,000 of inventory and a registered patent worth $150,000. Which item is an intangible non-current asset?","options":{"A":"The cash of $60,000","B":"The inventory of $90,000","C":"The laboratory equipment","D":"The registered patent"},"correctOption":"D","correctAnswer":"The registered patent","questionType":"MCQ","explanation":{"correct_reason":"A patent is a non-current asset without physical substance that gives the Basel firm exclusive rights over a period of years. It is therefore intangible and long-term, unlike the cash, inventory and equipment listed.","distractor_reasons":{"A":"Cash is a current asset with physical form in the sense of bank balances available immediately; it is neither intangible nor held for long-term use.","B":"Inventory is a current asset expected to be sold or used within a year, so it is not a non-current asset of any kind.","C":"Laboratory equipment is a tangible non-current asset because it has physical substance and can be touched, unlike the patent which is intangible.","D":"A patent is a non-current asset without physical substance that gives the Basel firm exclusive rights over a period of years. It is therefore intangible and long-term, unlike the cash, inventory and equipment listed."}}},{"id":"P1_U5_MCQ_1855","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1855","question":"A shoe manufacturer in León, Mexico reports revenue of $250,000 and gross profit of $50,000 for the most recent year. What is its gross profit margin?","options":{"A":"5%","B":"200%","C":"20%","D":"$200,000"},"correctOption":"C","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin equals gross profit divided by revenue, multiplied by 100. The León manufacturer earned $50,000 gross profit on $250,000 revenue, so 50,000 divided by 250,000 times 100 gives 20%.","distractor_reasons":{"A":"5% would require gross profit of only $12,500 on revenue of $250,000; the stated $50,000 profit gives a margin of 20%.","B":"200% reverses the fraction by dividing revenue by gross profit; the margin is gross profit as a share of revenue.","C":"Gross profit margin equals gross profit divided by revenue, multiplied by 100. The León manufacturer earned $50,000 gross profit on $250,000 revenue, so 50,000 divided by 250,000 times 100 gives 20%.","D":"$200,000 is revenue minus gross profit, which is the cost of sales, not a percentage margin figure comparing profit with the $250,000 revenue."}}},{"id":"P1_U5_MCQ_1856","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1856","question":"A recruitment agency in Vilnius, Lithuania wants to raise permanent capital by inviting investors to buy a share of the business. The new investors will expect a portion of future profits. Which source of finance is being used?","options":{"A":"A trade credit arrangement","B":"Issue of ordinary shares","C":"Retained profit","D":"A bank overdraft"},"correctOption":"B","correctAnswer":"Issue of ordinary shares","questionType":"MCQ","explanation":{"correct_reason":"Issuing ordinary shares raises permanent equity capital and gives investors an ownership stake with rights to dividends. It matches the Vilnius agency's plan to invite investors who will share in future profits.","distractor_reasons":{"A":"Trade credit is simply delayed payment to suppliers; it brings no new investors and does not create an ownership stake in the agency.","B":"Issuing ordinary shares raises permanent equity capital and gives investors an ownership stake with rights to dividends. It matches the Vilnius agency's plan to invite investors who will share in future profits.","C":"Retained profit uses profits already earned and kept in the business; it does not involve inviting outside investors to buy a share.","D":"A bank overdraft is short-term borrowed finance that must be repaid and does not give the lender an ownership stake or dividend rights."}}},{"id":"P1_U5_MCQ_1857","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1857","question":"A coach operator in Conakry, Guinea forecasts cash inflows of $120,000 and cash outflows of $135,000 for the next quarter. What net cash flow should be entered in the forecast?","options":{"A":"$255,000","B":"$15,000","C":"-$15,000","D":"$135,000"},"correctOption":"C","correctAnswer":"-$15,000","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is total inflows less total outflows. The Conakry coach operator expects $120,000 coming in and $135,000 going out, so $120,000 minus $135,000 equals negative $15,000 for the quarter.","distractor_reasons":{"A":"$255,000 adds the two figures together, but net cash flow is the difference between receipts and payments, not their combined total.","B":"$15,000 has the right magnitude but the wrong sign; since outflows exceed inflows, the resulting net cash flow is negative.","C":"Net cash flow is total inflows less total outflows. The Conakry coach operator expects $120,000 coming in and $135,000 going out, so $120,000 minus $135,000 equals negative $15,000 for the quarter.","D":"$135,000 is only the outflows; the net figure must set those payments against the $120,000 of expected inflows to give negative $15,000."}}},{"id":"P1_U5_MCQ_1858","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1858","question":"A furniture retailer in Bogotá, Colombia has seen net profit fall steadily even though sales revenue has barely changed. The accountant is examining why profit margin has declined. Which explanation is most plausible?","options":{"A":"Operating expenses have risen faster than revenue","B":"The business has stopped selling on credit","C":"Non-current assets have been revalued upward","D":"The current ratio has fallen"},"correctOption":"A","correctAnswer":"Operating expenses have risen faster than revenue","questionType":"MCQ","explanation":{"correct_reason":"If revenue is flat but net profit falls, costs must have increased. For the Bogotá retailer, higher overhead expenses such as rent, wages or interest reduce the share of revenue left as profit, pushing the net profit margin down.","distractor_reasons":{"A":"If revenue is flat but net profit falls, costs must have increased. For the Bogotá retailer, higher overhead expenses such as rent, wages or interest reduce the share of revenue left as profit, pushing the net profit margin down.","B":"Stopping credit sales changes when cash is received but does not by itself reduce profit margin when revenue is unchanged.","C":"Revaluing non-current assets affects the statement of financial position, not the profit and loss account or the net profit margin.","D":"The current ratio measures short-term liquidity and does not explain why net profit has declined relative to the steady revenue reported by the Bogotá firm."}}},{"id":"P1_U5_MCQ_1859","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1859","question":"A bookstore in Turku, Finland holds $40,000 of books for resale, $12,000 owed by customers, $9,000 in the bank and shelves worth $25,000. Which of these items is a current asset held for resale?","options":{"A":"The shelves worth $25,000","B":"The $40,000 of books for resale","C":"The $12,000 owed by customers","D":"The $9,000 in the bank"},"correctOption":"B","correctAnswer":"The $40,000 of books for resale","questionType":"MCQ","explanation":{"correct_reason":"Inventory consists of goods held for resale and is a current asset because the Turku bookstore expects to sell the $40,000 of books within a year. It differs from the shelves, which are used long-term rather than sold.","distractor_reasons":{"A":"The shelves are used in the shop over many years, making them a non-current asset rather than stock held for resale.","B":"Inventory consists of goods held for resale and is a current asset because the Turku bookstore expects to sell the $40,000 of books within a year. It differs from the shelves, which are used long-term rather than sold.","C":"The $12,000 owed by customers is trade receivables, a current asset, but it is money due rather than goods held for resale.","D":"The $9,000 in the bank is cash, a current asset, but it is money rather than inventory waiting to be sold."}}},{"id":"P1_U5_MCQ_1860","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1860","question":"A garden centre in Tampere, Finland reports current assets of $150,000 and current liabilities of $100,000 in its latest statement of financial position. Before negotiating a new supplier deal, the owner wants to assess liquidity. Calculate the current ratio.","options":{"A":"0.67 : 1","B":"$50,000","C":"1 : 1","D":"1.5 : 1"},"correctOption":"D","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Current ratio equals current assets divided by current liabilities. The Tampere garden centre has $150,000 of current assets and $100,000 of current liabilities, so 150,000 divided by 100,000 gives 1.5 : 1.","distractor_reasons":{"A":"0.67 : 1 inverts the ratio by dividing current liabilities by current assets; the current ratio places current assets first.","B":"$50,000 is the working capital difference between the two figures, not a ratio; the current ratio compares them by division instead.","C":"1 : 1 would require equal current assets and liabilities; here the $150,000 of assets clearly exceeds the $100,000 owed by the centre.","D":"Current ratio equals current assets divided by current liabilities. The Tampere garden centre has $150,000 of current assets and $100,000 of current liabilities, so 150,000 divided by 100,000 gives 1.5 : 1."}}},{"id":"P1_U5_MCQ_1861","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1861","question":"A construction company in Bilbao, Spain is deciding whether to fund an expansion through a new share issue rather than a bank loan. Which of these is a disadvantage of raising equity finance in this way?","options":{"A":"The capital must be repaid at a fixed date","B":"Ownership and control may be diluted","C":"Interest must be paid even when losses occur","D":"The firm must offer security for the funds"},"correctOption":"B","correctAnswer":"Ownership and control may be diluted","questionType":"MCQ","explanation":{"correct_reason":"A new share issue brings in investors who gain voting rights and a claim on profits, so the original owners of the Bilbao construction firm may lose some control. Unlike a loan, equity does not have to be repaid at a fixed date.","distractor_reasons":{"A":"Share capital is permanent and does not have a fixed repayment date; that feature belongs to loans and other debt finance.","B":"A new share issue brings in investors who gain voting rights and a claim on profits, so the original owners of the Bilbao construction firm may lose some control. Unlike a loan, equity does not have to be repaid at a fixed date.","C":"Interest payments arise on borrowed money; ordinary shareholders receive dividends only when profits allow, not a fixed interest charge that must always be met.","D":"Offering security is typical of secured lending, not of issuing shares, which raises equity capital from investors without pledging any business assets."}}},{"id":"P1_U5_MCQ_1862","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1862","question":"A tour operator in Palma, Spain has completed the cash flow forecast for May and is beginning the one for June. Which figure from the May forecast will be carried forward as the starting point for June?","options":{"A":"The total cash inflows for May","B":"The net cash flow for May","C":"The total cash outflows for May","D":"The closing cash balance for May"},"correctOption":"D","correctAnswer":"The closing cash balance for May","questionType":"MCQ","explanation":{"correct_reason":"The closing balance of one month becomes the opening balance of the next, linking the forecasts together. For the Palma tour operator, the cash left at the end of May is the amount available to start trading in June.","distractor_reasons":{"A":"Total inflows for May show receipts only; they do not represent the cash actually remaining to begin the following month.","B":"Net cash flow for May is the change in cash during the month, not the actual closing balance carried into June's forecast.","C":"Total outflows for May show payments only and cannot serve as the opening cash position for the next month's forecast.","D":"The closing balance of one month becomes the opening balance of the next, linking the forecasts together. For the Palma tour operator, the cash left at the end of May is the amount available to start trading in June."}}},{"id":"P1_U5_MCQ_1863","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1863","question":"A toy manufacturer in Nuremberg, Germany is classifying its production costs. The cost of plastic and wages paid to assembly workers directly making the toys is best described as which type of cost?","options":{"A":"Cost of sales","B":"Administrative expense","C":"Finance cost","D":"Distribution expense"},"correctOption":"A","correctAnswer":"Cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Materials and the wages of workers directly making the product are direct costs included in cost of sales. For the Nuremberg toy maker these costs are deducted from revenue to calculate gross profit before overheads are considered.","distractor_reasons":{"A":"Materials and the wages of workers directly making the product are direct costs included in cost of sales. For the Nuremberg toy maker these costs are deducted from revenue to calculate gross profit before overheads are considered.","B":"Administrative expenses such as office salaries are overheads, not the direct materials and assembly wages used to make each toy.","C":"Finance costs are charges such as loan interest; they are unrelated to the plastic and direct labour used in production.","D":"Distribution expenses cover delivery and marketing costs, whereas the described materials and assembly wages are incurred in actually manufacturing the toys."}}},{"id":"P1_U5_MCQ_1864","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1864","question":"A logistics firm in Rotterdam, Netherlands shows total equity of $310,000 and non-current liabilities of $190,000 in its most recent statement of financial position. Its management wants to know the total long-term finance invested. What is the capital employed by the business?","options":{"A":"$120,000","B":"$310,000","C":"$500,000","D":"$190,000"},"correctOption":"C","correctAnswer":"$500,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is the sum of total equity and non-current liabilities. The Rotterdam logistics firm has $310,000 of equity and $190,000 of long-term debt, so capital employed is $500,000 of long-term funding in use.","distractor_reasons":{"A":"$120,000 comes from subtracting the two figures; the sources of long-term finance, equity and loans, are added together, not subtracted.","B":"$310,000 is the equity alone; capital employed also counts the $190,000 of non-current liabilities, giving a total of $500,000 of long-term finance.","C":"Capital employed is the sum of total equity and non-current liabilities. The Rotterdam logistics firm has $310,000 of equity and $190,000 of long-term debt, so capital employed is $500,000 of long-term funding in use.","D":"$190,000 is only the non-current liabilities; the owners' $310,000 of equity must also be included to find the full capital employed."}}},{"id":"P1_U5_MCQ_1865","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1865","question":"A electronics retailer in Ljubljana, Slovenia saw its current ratio rise from 1.2 : 1 to 2.4 : 1 over two years. Which interpretation of this change is most likely correct?","options":{"A":"Short-term liquidity has improved","B":"The business is about to become insolvent","C":"Gross profit margin must have fallen","D":"Long-term debt has certainly increased"},"correctOption":"A","correctAnswer":"Short-term liquidity has improved","questionType":"MCQ","explanation":{"correct_reason":"A higher current ratio means current assets have grown relative to current liabilities, improving the Ljubljana retailer's ability to meet short-term debts. A rise from 1.2 : 1 to 2.4 : 1 suggests stronger liquidity, though very high ratios may indicate idle resources.","distractor_reasons":{"A":"A higher current ratio means current assets have grown relative to current liabilities, improving the Ljubljana retailer's ability to meet short-term debts. A rise from 1.2 : 1 to 2.4 : 1 suggests stronger liquidity, though very high ratios may indicate idle resources.","B":"Insolvency would be suggested by a falling ratio and weak liquidity, not by a current ratio that has doubled from 1.2 : 1 to 2.4 : 1.","C":"The current ratio uses balance sheet figures and says nothing directly about the gross profit margin from the profit and loss account.","D":"Long-term debt is a non-current liability and is excluded from the current ratio, so the change cannot be attributed to it."}}},{"id":"P1_U5_MCQ_1866","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1866","question":"A sole trader in Georgetown, Guyana uses $15,000 of personal savings to buy sewing machines for a new tailoring business. Which source of finance does this represent?","options":{"A":"A bank loan","B":"Leasing","C":"Trade credit","D":"Owner's capital"},"correctOption":"D","correctAnswer":"Owner's capital","questionType":"MCQ","explanation":{"correct_reason":"Money put into the business by the owner from personal savings is owner's capital, an internal source of equity finance. The Georgetown tailor therefore owes no interest and gives up no control by funding the machines this way.","distractor_reasons":{"A":"A bank loan is borrowed money that must be repaid with interest; the $15,000 came from the owner's own savings.","B":"Leasing means renting an asset and paying instalments to a lessor; here the trader buys the machines outright with personal funds.","C":"Trade credit involves delaying payment to suppliers for goods supplied, not investing the owner's personal savings into the tailoring business to buy machines.","D":"Money put into the business by the owner from personal savings is owner's capital, an internal source of equity finance. The Georgetown tailor therefore owes no interest and gives up no control by funding the machines this way."}}},{"id":"P1_U5_MCQ_1867","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1867","question":"A printing firm in Lusaka, Zambia is finalising its monthly cash flow forecast. Which of the following should NOT be included because it does not involve an actual movement of cash?","options":{"A":"Payment of wages to employees","B":"Depreciation of printing presses","C":"Cash received from customers","D":"Payment of rent on the premises"},"correctOption":"B","correctAnswer":"Depreciation of printing presses","questionType":"MCQ","explanation":{"correct_reason":"Depreciation is a non-cash expense that spreads an asset's cost over time; no money moves when it is recorded. The Lusaka printer's wages, customer receipts and rent all involve real cash movements and belong in the forecast.","distractor_reasons":{"A":"Wages are paid in cash to employees, so this is a genuine outflow that belongs in the printing firm's forecast.","B":"Depreciation is a non-cash expense that spreads an asset's cost over time; no money moves when it is recorded. The Lusaka printer's wages, customer receipts and rent all involve real cash movements and belong in the forecast.","C":"Cash received from customers is a real inflow that increases the bank balance and must be included in the forecast.","D":"Rent is paid in cash to the landlord, so it is an actual outflow that should appear in the monthly forecast."}}},{"id":"P1_U5_MCQ_1868","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1868","question":"A bicycle assembler in Da Nang, Vietnam recorded revenue of $720,000 and cost of sales of $430,000 during the year. What gross profit should appear in its profit and loss account?","options":{"A":"$1,150,000","B":"$430,000","C":"$290,000","D":"$720,000"},"correctOption":"C","correctAnswer":"$290,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit equals revenue minus cost of sales. The Da Nang assembler earned $720,000 of revenue and incurred $430,000 of direct costs, leaving gross profit of $290,000 before other expenses are deducted.","distractor_reasons":{"A":"$1,150,000 adds revenue and cost of sales; gross profit is instead found by subtracting the $430,000 direct costs from the $720,000 revenue.","B":"$430,000 is the cost of sales itself, the direct expense; gross profit is the amount remaining after deducting it from the $720,000 revenue.","C":"Gross profit equals revenue minus cost of sales. The Da Nang assembler earned $720,000 of revenue and incurred $430,000 of direct costs, leaving gross profit of $290,000 before other expenses are deducted.","D":"$720,000 is the revenue, the starting point of the calculation; the $430,000 cost of sales must be deducted to reach gross profit."}}},{"id":"P1_U5_MCQ_1869","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1869","question":"An interior design studio in Dublin, Ireland wants to see the financial position of the business at one particular date, listing its assets, liabilities and equity. Which financial statement should it prepare?","options":{"A":"A cash flow forecast","B":"A profit and loss account","C":"A sales ledger","D":"A statement of financial position"},"correctOption":"D","correctAnswer":"A statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"The statement of financial position lists assets, liabilities and equity at a specific date, giving a snapshot of financial position. For the Dublin studio this contrasts with the profit and loss account, which covers a period of trading.","distractor_reasons":{"A":"A cash flow forecast projects future cash movements over months, not the stock of assets and liabilities at a single date.","B":"A profit and loss account reports income and expenses over a period; it does not show the financial position at one particular date.","C":"A sales ledger records individual credit transactions with customers; it is an accounting record, not a financial statement of position.","D":"The statement of financial position lists assets, liabilities and equity at a specific date, giving a snapshot of financial position. For the Dublin studio this contrasts with the profit and loss account, which covers a period of trading."}}},{"id":"P1_U5_MCQ_1870","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1870","question":"A courier firm in Ghent, Belgium reports net profit of $36,000 and revenue of $400,000 for the year ended 31 December 2026. The owner wants to know what share of sales is retained as profit after all expenses. What is its profit margin?","options":{"A":"9%","B":"11.1%","C":"$364,000","D":"36%"},"correctOption":"A","correctAnswer":"9%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin equals net profit divided by revenue, multiplied by 100. The Ghent courier earned $36,000 net profit from $400,000 revenue, so 36,000 divided by 400,000 times 100 gives 9%.","distractor_reasons":{"A":"Profit margin equals net profit divided by revenue, multiplied by 100. The Ghent courier earned $36,000 net profit from $400,000 revenue, so 36,000 divided by 400,000 times 100 gives 9%.","B":"11.1% comes from dividing revenue by net profit, reversing the formula; the margin is profit as a share of revenue.","C":"$364,000 is simply revenue minus net profit, a difference in dollars, not a percentage margin measuring profit as a share of the $400,000 revenue.","D":"36% would require net profit of $144,000 on revenue of $400,000; the actual net profit reported by the Ghent courier is only $36,000."}}},{"id":"P1_U5_MCQ_1871","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1871","question":"A water utility in Tunis, Tunisia needs to fund a new pipeline over twenty years and plans to repay investors only when the bonds mature. Which category of finance does this represent?","options":{"A":"Short-term trade credit","B":"Owner's savings","C":"Long-term debt finance","D":"Issuing ordinary shares"},"correctOption":"C","correctAnswer":"Long-term debt finance","questionType":"MCQ","explanation":{"correct_reason":"Bonds that are repaid only at maturity after twenty years are long-term debt finance. The Tunis utility gains capital for the pipeline while keeping ownership with existing shareholders, but takes on a substantial long-term repayment obligation.","distractor_reasons":{"A":"Trade credit is short-term and arises from ordinary supplier payment terms; it cannot possibly fund a pipeline that will last for twenty years.","B":"Owner's savings are equity finance from the proprietor, not funds raised by selling bonds to investors with a maturity date.","C":"Bonds that are repaid only at maturity after twenty years are long-term debt finance. The Tunis utility gains capital for the pipeline while keeping ownership with existing shareholders, but takes on a substantial long-term repayment obligation.","D":"Issuing ordinary shares creates permanent equity ownership for investors, whereas bonds are borrowed money that must eventually be repaid to bondholders."}}},{"id":"P1_U5_MCQ_1872","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1872","question":"A hair salon in Port Vila, Vanuatu is putting together its cash flow forecast for the coming quarter. On what basis should the expected cash inflows and outflows be estimated?","options":{"A":"The profit shown in last year's accounts","B":"Reasonable estimates of future receipts and payments","C":"The market value of the salon's equipment","D":"The number of shareholders in the business"},"correctOption":"B","correctAnswer":"Reasonable estimates of future receipts and payments","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast is built from informed estimates of future cash receipts and payments, using past patterns and known commitments. For the Port Vila salon this forward-looking basis helps plan liquidity rather than report past profit.","distractor_reasons":{"A":"Last year's profit is a historical figure from the profit and loss account; a forecast is forward-looking and based on expected cash movements.","B":"A cash flow forecast is built from informed estimates of future cash receipts and payments, using past patterns and known commitments. For the Port Vila salon this forward-looking basis helps plan liquidity rather than report past profit.","C":"The market value of equipment is a valuation issue and does not provide the monthly cash inflows and outflows a forecast needs.","D":"The number of shareholders is a financing detail that has no bearing on estimating the salon's future cash receipts and payments."}}},{"id":"P1_U5_MCQ_1873","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1873","question":"A biscuit factory in Cairo, Egypt is identifying which costs form part of its cost of sales. Which of these is a direct cost of producing the biscuits?","options":{"A":"Flour and sugar used in the recipe","B":"The salary of the factory accountant","C":"Interest on the factory's loan","D":"Advertising on local radio"},"correctOption":"A","correctAnswer":"Flour and sugar used in the recipe","questionType":"MCQ","explanation":{"correct_reason":"Direct costs are materials and labour that can be traced to each unit produced. The flour and sugar in the Cairo factory's biscuits vary with output and form part of cost of sales, unlike overheads such as the accountant's salary.","distractor_reasons":{"A":"Direct costs are materials and labour that can be traced to each unit produced. The flour and sugar in the Cairo factory's biscuits vary with output and form part of cost of sales, unlike overheads such as the accountant's salary.","B":"The factory accountant's salary is an indirect overhead because it cannot be traced to individual biscuits and is not part of cost of sales.","C":"Interest on a loan is a finance cost charged after operating profit; it is not a production cost of the biscuits.","D":"Advertising is a selling and distribution expense aimed at promoting sales, not a direct cost incurred in manufacturing the biscuits at the Cairo factory."}}},{"id":"P1_U5_MCQ_1874","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1874","question":"A car rental company in San José, Costa Rica lists total assets of $780,000 and total liabilities of $310,000 in its statement of financial position. The directors want to confirm the owners' claim on the business. What are its net assets?","options":{"A":"$1,090,000","B":"$310,000","C":"$780,000","D":"$470,000"},"correctOption":"D","correctAnswer":"$470,000","questionType":"MCQ","explanation":{"correct_reason":"Net assets are total assets minus total liabilities. The San José car rental firm owns $780,000 of assets and owes $310,000, so $780,000 minus $310,000 gives $470,000 of net assets, equal to the owners' equity.","distractor_reasons":{"A":"$1,090,000 adds assets and liabilities together, which is meaningless; net assets are found by subtracting the $310,000 of obligations from the $780,000 of resources.","B":"$310,000 is the total liabilities on their own; net assets are what remains of the $780,000 assets after these debts are covered.","C":"$780,000 is the total assets; the $310,000 owed to outsiders must be deducted from it to find the owners' net claim on the business.","D":"Net assets are total assets minus total liabilities. The San José car rental firm owns $780,000 of assets and owes $310,000, so $780,000 minus $310,000 gives $470,000 of net assets, equal to the owners' equity."}}},{"id":"P1_U5_MCQ_1875","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1875","question":"An analyst is comparing the accounts of two hotel chains in Edinburgh, Scotland and has calculated several ratios. Which of these is a recognised limitation of relying on those ratios alone?","options":{"A":"Ratios are always calculated in the same way","B":"Ratios remove the need to read the accounts","C":"Ratios are based on historical data and may not predict the future","D":"Ratios can only be calculated for large companies"},"correctOption":"C","correctAnswer":"Ratios are based on historical data and may not predict the future","questionType":"MCQ","explanation":{"correct_reason":"Ratios are calculated from past financial statements, so they describe what has already happened rather than guaranteeing future performance. For the Edinburgh hotels being compared, changing conditions can make historic ratios poor predictors.","distractor_reasons":{"A":"Ratios are not always calculated consistently; firms may use different accounting policies for inventory or depreciation, which is itself a recognised limitation of comparison.","B":"Ratios support analysis but do not replace reading the accounts, which provide the context needed to interpret the figures properly.","C":"Ratios are calculated from past financial statements, so they describe what has already happened rather than guaranteeing future performance. For the Edinburgh hotels being compared, changing conditions can make historic ratios poor predictors.","D":"Ratios can be calculated for businesses of any size as long as the necessary financial figures are available to the analyst."}}},{"id":"P1_U5_MCQ_1876","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1876","question":"A sandwich shop in Port Louis, Mauritius needs to finance two weeks of bread and filling purchases and plans to pay the supplier after the sandwiches are sold. Which short-term source of finance fits this pattern?","options":{"A":"A 25-year mortgage","B":"Trade credit from the supplier","C":"Issuing new ordinary shares","D":"A government grant"},"correctOption":"B","correctAnswer":"Trade credit from the supplier","questionType":"MCQ","explanation":{"correct_reason":"Trade credit lets the Port Louis shop receive goods now and pay the supplier later, after the sandwiches have been sold. It is a short-term, interest-free source that matches the two-week gap between buying ingredients and receiving cash.","distractor_reasons":{"A":"A 25-year mortgage is long-term finance secured on property; it is inappropriate for a two-week purchase of bread and fillings.","B":"Trade credit lets the Port Louis shop receive goods now and pay the supplier later, after the sandwiches have been sold. It is a short-term, interest-free source that matches the two-week gap between buying ingredients and receiving cash.","C":"Issuing ordinary shares raises permanent capital and dilutes ownership; it is far too heavy a response to a routine two-week supply need.","D":"A government grant is not normally available to fund everyday ingredients and would not create the delayed payment arrangement described."}}},{"id":"P1_U5_MCQ_1877","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1877","question":"A computer repair shop in Bratislava, Slovakia expects cash inflows of $42,000 and cash outflows of $38,000 during September. What net cash flow should be recorded for the month?","options":{"A":"$80,000","B":"-$4,000","C":"$4,000","D":"$38,000"},"correctOption":"C","correctAnswer":"$4,000","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is total inflows minus total outflows. The Bratislava repair shop expects $42,000 of receipts and $38,000 of payments, so $42,000 minus $38,000 gives a positive net cash flow of $4,000 for September.","distractor_reasons":{"A":"$80,000 adds inflows and outflows together; net cash flow is the difference between the two figures, not their combined total for September.","B":"Negative $4,000 uses the wrong sign in the answer; inflows of $42,000 exceed outflows of $38,000, so the net cash flow for September is positive.","C":"Net cash flow is total inflows minus total outflows. The Bratislava repair shop expects $42,000 of receipts and $38,000 of payments, so $42,000 minus $38,000 gives a positive net cash flow of $4,000 for September.","D":"$38,000 is only the outflows on their own; the net figure must compare those payments with the $42,000 of expected inflows to give $4,000."}}},{"id":"P1_U5_MCQ_1878","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1878","question":"The owner of a laundry service in Phnom Penh, Cambodia wants to understand how net profit is derived in the profit and loss account. Which description of net profit is correct?","options":{"A":"Gross profit minus operating expenses and other charges","B":"Sales revenue minus cost of sales only","C":"The total cash held at the end of the year","D":"The value of all non-current assets owned"},"correctOption":"A","correctAnswer":"Gross profit minus operating expenses and other charges","questionType":"MCQ","explanation":{"correct_reason":"Net profit is what remains after all expenses and charges have been deducted from gross profit. For the Phnom Penh laundry this includes rent, wages, interest and tax, making it the final profit figure after revenue and direct costs are accounted for.","distractor_reasons":{"A":"Net profit is what remains after all expenses and charges have been deducted from gross profit. For the Phnom Penh laundry this includes rent, wages, interest and tax, making it the final profit figure after revenue and direct costs are accounted for.","B":"Sales revenue minus cost of sales gives gross profit, not net profit; further operating expenses must still be subtracted before net profit is reached.","C":"Cash held at year end is a balance sheet figure and does not equal net profit, which is measured over a period of trading.","D":"The value of non-current assets appears in the statement of financial position and is unrelated to the calculation of net profit."}}},{"id":"P1_U5_MCQ_1879","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1879","question":"A cosmetics wholesaler in Marseille, France owes $22,000 to suppliers for goods bought on credit, payable in 30 days. How should this amount be classified in the statement of financial position?","options":{"A":"As a current asset","B":"As a non-current asset","C":"As owners' equity","D":"As a current liability"},"correctOption":"D","correctAnswer":"As a current liability","questionType":"MCQ","explanation":{"correct_reason":"The $22,000 owed to suppliers is trade payables, a current liability because it must be settled within a year, here in 30 days. It represents a short-term claim on the Marseille wholesaler's resources by an outside party.","distractor_reasons":{"A":"A current asset is a resource such as cash or inventory; an amount owed to suppliers is the opposite, an obligation.","B":"Non-current assets are long-term resources like premises or vehicles; a payable is not an owned resource at all but a short-term debt owed. For a cosmetics wholesaler in Marseille, the correct answer is as a current liability.","C":"Owners' equity is the proprietors' residual claim on the business, whereas trade payables are claims by outside suppliers for goods supplied on credit. For a cosmetics wholesaler in Marseille, the correct answer is as a current liability.","D":"The $22,000 owed to suppliers is trade payables, a current liability because it must be settled within a year, here in 30 days. It represents a short-term claim on the Marseille wholesaler's resources by an outside party."}}},{"id":"P1_U5_MCQ_1880","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1880","question":"A furniture manufacturer in Bordeaux, France reports operating profit of $90,000 and capital employed of $600,000 in its latest accounts. The directors want to judge how productively that long-term capital is being used. Calculate its return on capital employed.","options":{"A":"15%","B":"6.7%","C":"$510,000","D":"66.7%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, multiplied by 100. The Bordeaux manufacturer earns $90,000 on $600,000 of capital, so 90,000 divided by 600,000 times 100 gives 15%.","distractor_reasons":{"A":"Return on capital employed is operating profit divided by capital employed, multiplied by 100. The Bordeaux manufacturer earns $90,000 on $600,000 of capital, so 90,000 divided by 600,000 times 100 gives 15%.","B":"6.7% comes from dividing capital employed by operating profit, reversing the formula; the return is profit earned per unit of capital.","C":"$510,000 is capital employed minus operating profit, a simple difference in dollars, not a percentage return measuring profit against the $600,000 capital. For a furniture manufacturer in Bordeaux, the correct answer is 15%.","D":"66.7% would require operating profit around $400,000 on capital of $600,000; the stated profit is only $90,000, giving a 15% return. For a furniture manufacturer in Bordeaux, the correct answer is 15%."}}},{"id":"P1_U5_MCQ_1881","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1881","question":"A hotel in Edinburgh, Scotland buys its premises for $1.2 million using a loan secured on that property, to be repaid over 25 years. What type of finance is this?","options":{"A":"An ordinary share issue","B":"A mortgage","C":"Trade credit","D":"Retained profit"},"correctOption":"B","correctAnswer":"A mortgage","questionType":"MCQ","explanation":{"correct_reason":"A mortgage is a long-term loan secured on a specific asset, here the Edinburgh hotel premises, with repayment spread over many years. It gives the lender security while allowing the hotel to buy the property without paying the full price immediately.","distractor_reasons":{"A":"An ordinary share issue raises equity from investors who gain ownership; it is not a secured loan backed by the property.","B":"A mortgage is a long-term loan secured on a specific asset, here the Edinburgh hotel premises, with repayment spread over many years. It gives the lender security while allowing the hotel to buy the property without paying the full price immediately.","C":"Trade credit is short-term delayed payment to suppliers for goods, not a 25-year loan secured on the hotel buildings bought by the business. For a hotel in Edinburgh, the correct answer is a mortgage.","D":"Retained profit uses the firm's own accumulated earnings and involves no borrowing at all, so there is no security given over the hotel premises. For a hotel in Edinburgh, the correct answer is a mortgage."}}},{"id":"P1_U5_MCQ_1882","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1882","question":"A textile exporter in Alexandria, Egypt prepared a cash flow forecast but actual receipts fell short because several customers paid later than expected. What does this show about cash flow forecasts?","options":{"A":"They are always completely accurate","B":"They only record past transactions","C":"They are estimates that can be affected by uncertainty","D":"They cannot include expected payments"},"correctOption":"C","correctAnswer":"They are estimates that can be affected by uncertainty","questionType":"MCQ","explanation":{"correct_reason":"Forecasts rely on assumptions about when customers pay, and the Alexandria exporter's late receipts show those assumptions can be wrong. Cash flow forecasts are therefore estimates subject to uncertainty, especially over the timing of inflows.","distractor_reasons":{"A":"The shortfall shows forecasts are not always accurate; unexpected delays in customer payments can cause actual cash to differ significantly from predictions. For a textile exporter in Alexandria, the correct answer is they are estimates that can be affected by uncertainty.","B":"Cash flow forecasts are forward-looking projections of expected receipts and payments, not records of past transactions, which appear in the accounting records. For a textile exporter in Alexandria, the correct answer is they are estimates that can be affected by uncertainty.","C":"Forecasts rely on assumptions about when customers pay, and the Alexandria exporter's late receipts show those assumptions can be wrong. Cash flow forecasts are therefore estimates subject to uncertainty, especially over the timing of inflows.","D":"Forecasts routinely include expected payments as outflows; the real issue here was the timing of customer receipts, not the omission of payments. For a textile exporter in Alexandria, the correct answer is they are estimates that can be affected by uncertainty."}}},{"id":"P1_U5_MCQ_1883","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1883","question":"A electronics retailer in Seoul, South Korea reports sales revenue of $900,000 and gross profit of $360,000. What figure for cost of sales should appear in the profit and loss account?","options":{"A":"$540,000","B":"$360,000","C":"$1,260,000","D":"$900,000"},"correctOption":"A","correctAnswer":"$540,000","questionType":"MCQ","explanation":{"correct_reason":"Because gross profit equals revenue minus cost of sales, cost of sales equals revenue minus gross profit. The Seoul retailer has $900,000 revenue and $360,000 gross profit, so cost of sales is $540,000.","distractor_reasons":{"A":"Because gross profit equals revenue minus cost of sales, cost of sales equals revenue minus gross profit. The Seoul retailer has $900,000 revenue and $360,000 gross profit, so cost of sales is $540,000.","B":"$360,000 is the gross profit; cost of sales is the direct cost deducted from revenue to arrive at that profit.","C":"$1,260,000 adds revenue and gross profit together, which is meaningless; cost of sales is found by subtracting gross profit from the $900,000 revenue. For a electronics retailer in Seoul, the correct answer is $540,000.","D":"$900,000 is the revenue; the $360,000 gross profit must be deducted from it to leave the $540,000 cost of sales in the account. For a electronics retailer in Seoul, the correct answer is $540,000."}}},{"id":"P1_U5_MCQ_1884","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1884","question":"A transport company in Addis Ababa, Ethiopia reports current assets of $180,000 and current liabilities of $125,000. Its finance manager wants to know the short-term funding left after settling obligations due within the year. What is its working capital?","options":{"A":"$305,000","B":"$125,000","C":"$55,000","D":"$180,000"},"correctOption":"C","correctAnswer":"$55,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities. The Addis Ababa transport firm has $180,000 of short-term assets and $125,000 of short-term debts, leaving $55,000 of working capital to support its operations.","distractor_reasons":{"A":"$305,000 adds the two figures together; working capital is the difference between short-term resources of $180,000 and short-term obligations of $125,000. For a transport company in Addis Ababa, the correct answer is $55,000.","B":"$125,000 is the current liabilities; working capital is what remains of the $180,000 current assets after these obligations are met. For a transport company in Addis Ababa, the correct answer is $55,000.","C":"Working capital is current assets minus current liabilities. The Addis Ababa transport firm has $180,000 of short-term assets and $125,000 of short-term debts, leaving $55,000 of working capital to support its operations.","D":"$180,000 is the current assets; the $125,000 owed to suppliers must be deducted from that figure to find the $55,000 working capital. For a transport company in Addis Ababa, the correct answer is $55,000."}}},{"id":"P1_U5_MCQ_1885","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1885","question":"A supermarket chain in Porto, Portugal has an acid test ratio of 1.4 : 1 and is comparing its liquidity with a rival. What does a relatively high acid test ratio generally indicate?","options":{"A":"Strong liquidity without relying on selling inventory","B":"The business must be making a loss","C":"All its assets are non-current","D":"Its gross profit margin is improving"},"correctOption":"A","correctAnswer":"Strong liquidity without relying on selling inventory","questionType":"MCQ","explanation":{"correct_reason":"The acid test excludes inventory from current assets, so a ratio of 1.4 : 1 means the Porto supermarket can cover current liabilities using liquid resources alone. It signals stronger short-term liquidity than a comparable current ratio might suggest.","distractor_reasons":{"A":"The acid test excludes inventory from current assets, so a ratio of 1.4 : 1 means the Porto supermarket can cover current liabilities using liquid resources alone. It signals stronger short-term liquidity than a comparable current ratio might suggest.","B":"Liquidity ratios say nothing directly about profit or loss; a firm can be profitable yet have weak liquidity, or the reverse.","C":"A high acid test ratio concerns current assets and liabilities, so it does not imply that all assets are non-current.","D":"The acid test is a liquidity measure and does not reveal whether the gross profit margin is improving over time."}}},{"id":"P1_U5_MCQ_1886","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1886","question":"A company in Turin, Italy raises $200,000 by issuing loan stock that pays investors a fixed annual interest rate. Existing shareholders keep their voting rights. What is this source of finance?","options":{"A":"Retained earnings","B":"A bank overdraft","C":"Preference share capital","D":"Debentures"},"correctOption":"D","correctAnswer":"Debentures","questionType":"MCQ","explanation":{"correct_reason":"Debentures are long-term debt securities issued to investors paying fixed interest, without giving them ownership or voting rights. The Turin company therefore raises $200,000 while existing shareholders retain control of the business.","distractor_reasons":{"A":"Retained earnings are profits kept inside the firm and do not involve paying any fixed interest to outside investors who have lent money. For a company in Turin, the correct answer is debentures.","B":"A bank overdraft is short-term, repayable on demand finance from a bank, not long-term loan stock with a fixed interest rate.","C":"Preference shares are a form of equity with no voting rights but they represent ownership, whereas debentures are borrowed money that must be repaid.","D":"Debentures are long-term debt securities issued to investors paying fixed interest, without giving them ownership or voting rights. The Turin company therefore raises $200,000 while existing shareholders retain control of the business."}}},{"id":"P1_U5_MCQ_1887","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1887","question":"A hire company in Perth, Australia expects a short-term cash shortage next month and has several customers who are two months late paying invoices. Which action would most quickly improve its cash position?","options":{"A":"Buy additional equipment","B":"Chase and collect the overdue receivables","C":"Extend credit terms to more customers","D":"Reduce the number of forecast rows"},"correctOption":"B","correctAnswer":"Chase and collect the overdue receivables","questionType":"MCQ","explanation":{"correct_reason":"Collecting the overdue invoices converts existing receivables into cash quickly, directly easing the Perth hire company's forecast shortage. It brings forward money the business has already earned rather than creating new costs or debts.","distractor_reasons":{"A":"Buying more equipment would require extra cash payments immediately and would worsen the very short-term shortage the forecast has already identified. For a hire company in Perth, the correct answer is chase and collect the overdue receivables.","B":"Collecting the overdue invoices converts existing receivables into cash quickly, directly easing the Perth hire company's forecast shortage. It brings forward money the business has already earned rather than creating new costs or debts.","C":"Extending credit terms lets customers wait even longer before paying, delaying the cash inflow and deepening the short-term liquidity problem. For a hire company in Perth, the correct answer is chase and collect the overdue receivables.","D":"Reducing the number of forecast rows merely hides the shortage rather than solving it; the underlying gap between cash inflows and outflows still remains. For a hire company in Perth, the correct answer is chase and collect the overdue receivables."}}},{"id":"P1_U5_MCQ_1888","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1888","question":"A paper manufacturer in Oulu, Finland has kept sales revenue unchanged but seen the direct cost of pulp rise sharply. What is the likely effect on gross profit, assuming nothing else changes?","options":{"A":"Gross profit will increase","B":"Gross profit will stay the same","C":"Gross profit will fall","D":"Gross profit will become negative automatically"},"correctOption":"C","correctAnswer":"Gross profit will fall","questionType":"MCQ","explanation":{"correct_reason":"Gross profit equals revenue minus cost of sales. With revenue unchanged at the Oulu mill, a rise in the direct cost of pulp increases cost of sales, so the remaining gross profit must fall by the amount of the cost increase.","distractor_reasons":{"A":"Higher direct costs cannot raise gross profit when revenue is fixed; gross profit is what remains after those costs are deducted.","B":"Gross profit will change because cost of sales has risen; only if revenue rose by the same amount would it stay constant.","C":"Gross profit equals revenue minus cost of sales. With revenue unchanged at the Oulu mill, a rise in the direct cost of pulp increases cost of sales, so the remaining gross profit must fall by the amount of the cost increase.","D":"Gross profit becomes negative only if costs exceed revenue; a rise in pulp costs reduces profit but does not guarantee that point."}}},{"id":"P1_U5_MCQ_1889","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1889","question":"An accountant in Nassau, Bahamas is checking that a company's statement of financial position balances. Which relationship must always hold between assets, liabilities and equity?","options":{"A":"Assets minus liabilities equal revenue","B":"Assets equal liabilities only","C":"Equity equals total assets plus liabilities","D":"Assets equal liabilities plus equity"},"correctOption":"D","correctAnswer":"Assets equal liabilities plus equity","questionType":"MCQ","explanation":{"correct_reason":"The accounting equation states that assets equal liabilities plus equity, because everything the Nassau company owns is financed either by borrowing or by the owners. This is why the statement of financial position must balance.","distractor_reasons":{"A":"Assets minus liabilities equal equity, not revenue; revenue belongs to the profit and loss account, which measures performance over a period. For an accountant in Nassau, the correct answer is assets equal liabilities plus equity.","B":"Assets are financed by both liabilities and equity, so saying they equal liabilities alone ignores the $420,000 owners' stake in the business. For an accountant in Nassau, the correct answer is assets equal liabilities plus equity.","C":"Equity equals assets minus liabilities, not assets plus liabilities; adding the two would double count the financing of the same resources. For an accountant in Nassau, the correct answer is assets equal liabilities plus equity.","D":"The accounting equation states that assets equal liabilities plus equity, because everything the Nassau company owns is financed either by borrowing or by the owners. This is why the statement of financial position must balance."}}},{"id":"P1_U5_MCQ_1890","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1890","question":"A stationery firm in Ljubljana, Slovenia has current assets of $180,000, of which $30,000 is inventory, and current liabilities of $120,000. Calculate the acid test ratio.","options":{"A":"1.25 : 1","B":"1.5 : 1","C":"0.67 : 1","D":"0.8 : 1"},"correctOption":"A","correctAnswer":"1.25 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test ratio is current assets minus inventory, divided by current liabilities. For the Ljubljana firm, $180,000 less $30,000 gives $150,000, and $150,000 divided by $120,000 equals 1.25 : 1.","distractor_reasons":{"A":"The acid test ratio is current assets minus inventory, divided by current liabilities. For the Ljubljana firm, $180,000 less $30,000 gives $150,000, and $150,000 divided by $120,000 equals 1.25 : 1.","B":"1.5 : 1 is the current ratio, $180,000 divided by $120,000, which still includes inventory; the acid test removes the $30,000 of stock.","C":"0.67 : 1 reverses the comparison by dividing current liabilities by current assets; the acid test is 1.25 : 1.","D":"0.8 : 1 would come from dividing the $120,000 liabilities by the $150,000 figure after inventory is removed, inverting the ratio."}}},{"id":"P1_U5_MCQ_1891","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1891","question":"A printing business in Montevideo, Uruguay uses $20,000 of profits it kept in the business rather than distributing them to buy a new press. Which source of finance is being used?","options":{"A":"A lease agreement","B":"A bank loan","C":"Retained profit","D":"Trade credit"},"correctOption":"C","correctAnswer":"Retained profit","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is earnings kept in the business instead of being paid out to owners. By using $20,000 of these accumulations to buy the press, the Montevideo printer funds the purchase internally without interest or dilution of control.","distractor_reasons":{"A":"A lease agreement involves renting an asset and paying a lessor; here the printer uses its own accumulated profits to buy the press.","B":"A bank loan is borrowed money with interest charges and fixed repayment dates, whereas the $20,000 comes from profits the printer has already earned. For a printing business in Montevideo, the correct answer is retained profit.","C":"Retained profit is earnings kept in the business instead of being paid out to owners. By using $20,000 of these accumulations to buy the press, the Montevideo printer funds the purchase internally without interest or dilution of control.","D":"Trade credit merely delays payment to suppliers; it does not involve using accumulated profits that the printing business has already retained. For a printing business in Montevideo, the correct answer is retained profit."}}},{"id":"P1_U5_MCQ_1892","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1892","question":"A bakery in Kigali, Rwanda opens a month with a bank balance of $25,000 and records a net cash outflow of $7,000. What closing cash balance should the forecast show?","options":{"A":"$32,000","B":"$18,000","C":"$7,000","D":"-$18,000"},"correctOption":"B","correctAnswer":"$18,000","questionType":"MCQ","explanation":{"correct_reason":"Closing balance equals opening balance plus net cash flow. The Kigali bakery starts with $25,000 and has a net outflow of $7,000, so $25,000 minus $7,000 gives a closing cash balance of $18,000.","distractor_reasons":{"A":"$32,000 adds the outflow to the opening balance, but an outflow reduces the bank balance, so the $7,000 must be subtracted instead. For a bakery in Kigali, the correct answer is $18,000.","B":"Closing balance equals opening balance plus net cash flow. The Kigali bakery starts with $25,000 and has a net outflow of $7,000, so $25,000 minus $7,000 gives a closing cash balance of $18,000.","C":"$7,000 is the net outflow itself, not the closing balance; it must be deducted from the $25,000 opening cash to leave $18,000. For a bakery in Kigali, the correct answer is $18,000.","D":"Negative $18,000 wrongly treats the outflow as larger than the opening balance; $25,000 less $7,000 remains a positive $18,000. For a bakery in Kigali, the correct answer is $18,000."}}},{"id":"P1_U5_MCQ_1893","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1893","question":"A drinks producer in Kampala, Uganda wants to raise its gross profit without increasing sales revenue. Assuming other things stay the same, which change would achieve this?","options":{"A":"Reduce the direct cost of production","B":"Increase rent on the factory","C":"Pay more interest on loans","D":"Increase advertising spending"},"correctOption":"A","correctAnswer":"Reduce the direct cost of production","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue minus cost of sales, so with revenue fixed the Kampala producer can raise gross profit only by lowering direct production costs. Cheaper ingredients or more efficient labour would increase the amount left over.","distractor_reasons":{"A":"Gross profit is revenue minus cost of sales, so with revenue fixed the Kampala producer can raise gross profit only by lowering direct production costs. Cheaper ingredients or more efficient labour would increase the amount left over.","B":"Higher factory rent is an overhead deducted after gross profit, so it would reduce net profit but not raise gross profit.","C":"Increased interest is a finance cost charged after operating profit and does not affect the calculation of gross profit, which comes earlier. For a drinks producer in Kampala, the correct answer is reduce the direct cost of production.","D":"More advertising is a selling expense deducted later in the account; it does not increase gross profit when revenue remains unchanged. For a drinks producer in Kampala, the correct answer is reduce the direct cost of production."}}},{"id":"P1_U5_MCQ_1894","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1894","question":"A consultancy in Canberra, Australia reports owners' equity of $420,000 and total liabilities of $180,000 in its statement of financial position. The partners want to confirm the total resources controlled by the business. What is the total value of its assets?","options":{"A":"$240,000","B":"$420,000","C":"$180,000","D":"$600,000"},"correctOption":"D","correctAnswer":"$600,000","questionType":"MCQ","explanation":{"correct_reason":"From the accounting equation, assets equal equity plus liabilities. The Canberra consultancy has $420,000 of equity and $180,000 of liabilities, so total assets are $600,000, which is how the statement balances.","distractor_reasons":{"A":"$240,000 comes from subtracting the $180,000 liabilities from the $420,000 equity, which gives net assets, not the total assets controlled. For a consultancy in Canberra, the correct answer is $600,000.","B":"$420,000 is the owners' equity alone; the total assets must also cover the additional $180,000 owed to outside creditors. For a consultancy in Canberra, the correct answer is $600,000.","C":"$180,000 is the liabilities alone; the owners' $420,000 stake must be added to it to find the total assets financed. For a consultancy in Canberra, the correct answer is $600,000.","D":"From the accounting equation, assets equal equity plus liabilities. The Canberra consultancy has $420,000 of equity and $180,000 of liabilities, so total assets are $600,000, which is how the statement balances."}}},{"id":"P1_U5_MCQ_1895","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1895","question":"A bakery chain in Wellington, New Zealand has seen its gross profit margin fall from 40% to 31% while revenue has grown. What does this most likely warn about?","options":{"A":"The chain has too much cash","B":"Its current liabilities have fallen","C":"Cost of sales is rising faster than revenue","D":"Its non-current assets are undervalued"},"correctOption":"C","correctAnswer":"Cost of sales is rising faster than revenue","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin measures gross profit as a share of revenue. A fall from 40% to 31% despite higher revenue means a smaller proportion of each sales dollar remains after direct costs, warning that the Wellington chain's cost of sales is growing faster than sales.","distractor_reasons":{"A":"Holding plenty of cash is a liquidity matter and does not explain why the gross profit margin has declined from 40% to 31%. For a bakery chain in Wellington, the correct answer is cost of sales is rising faster than revenue.","B":"Falling current liabilities would affect the current ratio, not the gross profit margin derived from revenue and cost of sales.","C":"Gross profit margin measures gross profit as a share of revenue. A fall from 40% to 31% despite higher revenue means a smaller proportion of each sales dollar remains after direct costs, warning that the Wellington chain's cost of sales is growing faster than sales.","D":"Asset valuation appears in the statement of financial position and has no bearing on the gross profit margin in the profit and loss account."}}},{"id":"P1_U5_MCQ_1896","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1896","question":"A retailer in Adelaide, Australia is considering a bank overdraft to cover seasonal working capital. Which of these is a disadvantage of using an overdraft for this purpose?","options":{"A":"It can be arranged very quickly","B":"Interest charges can be high and the bank can demand repayment","C":"It does not need to be repaid","D":"It gives the bank an ownership stake"},"correctOption":"B","correctAnswer":"Interest charges can be high and the bank can demand repayment","questionType":"MCQ","explanation":{"correct_reason":"Overdrafts are flexible but usually carry relatively high interest and can be withdrawn on demand by the bank, creating uncertainty for the Adelaide retailer. These features are the main drawbacks of relying on an overdraft for seasonal finance.","distractor_reasons":{"A":"Being arranged quickly is an advantage of an overdraft, not a disadvantage, and it genuinely helps with urgent seasonal working capital needs. For a retailer in Adelaide, the correct answer is interest charges can be high and the bank can demand repayment.","B":"Overdrafts are flexible but usually carry relatively high interest and can be withdrawn on demand by the bank, creating uncertainty for the Adelaide retailer. These features are the main drawbacks of relying on an overdraft for seasonal finance.","C":"An overdraft must be repaid, typically on demand whenever the bank asks, so saying it does not need repayment is quite incorrect. For a retailer in Adelaide, the correct answer is interest charges can be high and the bank can demand repayment.","D":"An overdraft is debt, not equity; the bank does not gain an ownership stake or voting rights in the retailer."}}},{"id":"P1_U5_MCQ_1897","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1897","question":"A printing firm in Helsinki, Finland is reading its cash flow forecast for the next quarter. Which statement correctly describes a cash surplus in a given month?","options":{"A":"Cash outflows exceed cash inflows","B":"The closing balance will be negative","C":"Cash inflows exceed cash outflows","D":"No cash movements are expected"},"correctOption":"C","correctAnswer":"Cash inflows exceed cash outflows","questionType":"MCQ","explanation":{"correct_reason":"A cash surplus occurs when expected cash inflows in a month are greater than the outflows, leaving a positive net cash flow. For the Helsinki printer this means more cash is entering the business than leaving during that period.","distractor_reasons":{"A":"When outflows exceed inflows the firm has a cash deficit, the exact opposite of the surplus described in the question about the Helsinki printer. For a printing firm in Helsinki, the correct answer is cash inflows exceed cash outflows.","B":"A negative closing balance would follow a deficit, not a surplus; a genuine cash surplus adds to the balance held at the bank. For a printing firm in Helsinki, the correct answer is cash inflows exceed cash outflows.","C":"A cash surplus occurs when expected cash inflows in a month are greater than the outflows, leaving a positive net cash flow. For the Helsinki printer this means more cash is entering the business than leaving during that period.","D":"If no cash movements were expected, net cash flow would be zero and there would be no surplus to describe."}}},{"id":"P1_U5_MCQ_1898","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1898","question":"A logistics firm in Djibouti City, Djibouti reports gross profit of $210,000 and total operating expenses of $140,000. What is its net profit before tax?","options":{"A":"$70,000","B":"$350,000","C":"$140,000","D":"$210,000"},"correctOption":"A","correctAnswer":"$70,000","questionType":"MCQ","explanation":{"correct_reason":"Net profit before tax is gross profit minus operating expenses. The Djibouti City logistics firm earns $210,000 gross profit and spends $140,000 on overheads, leaving $70,000 of net profit before tax is charged.","distractor_reasons":{"A":"Net profit before tax is gross profit minus operating expenses. The Djibouti City logistics firm earns $210,000 gross profit and spends $140,000 on overheads, leaving $70,000 of net profit before tax is charged.","B":"$350,000 adds gross profit and expenses together; net profit is the balance left after the $140,000 expenses are deducted from gross profit. For a logistics firm in Djibouti City, the correct answer is $70,000.","C":"$140,000 is the operating expenses themselves; the net profit is what remains after paying these costs out of the $210,000 gross profit. For a logistics firm in Djibouti City, the correct answer is $70,000.","D":"$210,000 is the gross profit, the starting figure; the $140,000 of operating expenses must be subtracted before net profit is found. For a logistics firm in Djibouti City, the correct answer is $70,000."}}},{"id":"P1_U5_MCQ_1899","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1899","question":"A supermarket in San Salvador, El Salvador owns a plot of land used as a customer car park for the last fifteen years. How should this land be classified in the statement of financial position?","options":{"A":"As a current asset","B":"As a current liability","C":"As owners' equity","D":"As a non-current asset"},"correctOption":"D","correctAnswer":"As a non-current asset","questionType":"MCQ","explanation":{"correct_reason":"Land held for long-term use in the business, such as the San Salvador supermarket's car park, is a non-current asset. It is not intended for resale within a year and will support operations over many future accounting periods.","distractor_reasons":{"A":"A current asset is cash or an item expected to be used or sold within a year; the car park land has been held for fifteen years.","B":"A current liability is a short-term debt owed to others; the land is a resource owned by the supermarket, not an obligation.","C":"Owners' equity represents the proprietors' claim on the net assets, while the car park land itself is one of the non-current assets owned. For a supermarket in San Salvador, the correct answer is as a non-current asset.","D":"Land held for long-term use in the business, such as the San Salvador supermarket's car park, is a non-current asset. It is not intended for resale within a year and will support operations over many future accounting periods."}}},{"id":"P1_U5_MCQ_1900","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1900","question":"A confectionery business in Port of Spain, Trinidad and Tobago reports net profit of $28,000 and revenue of $350,000 for the year. What is its profit margin?","options":{"A":"12.5%","B":"8.5%","C":"$322,000","D":"8%"},"correctOption":"D","correctAnswer":"8%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin equals net profit divided by revenue, multiplied by 100. The Port of Spain confectioner earns $28,000 net profit on $350,000 revenue, so 28,000 divided by 350,000 times 100 gives 8%.","distractor_reasons":{"A":"12.5% would require net profit of $43,750 on revenue of $350,000; the actual stated profit is only $28,000, giving a margin of 8%. For a confectionery business in Port of Spain, the correct answer is 8%.","B":"8.5% does not follow from the figures at all; dividing $28,000 by $350,000 gives exactly 0.08, which is a margin of 8%. For a confectionery business in Port of Spain, the correct answer is 8%.","C":"$322,000 is simply revenue minus net profit, a difference in dollars, not a percentage margin measuring profit against the $350,000 revenue. For a confectionery business in Port of Spain, the correct answer is 8%.","D":"Profit margin equals net profit divided by revenue, multiplied by 100. The Port of Spain confectioner earns $28,000 net profit on $350,000 revenue, so 28,000 divided by 350,000 times 100 gives 8%."}}},{"id":"P1_U5_MCQ_1901","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1901","question":"Kirrawill Boatworks in Newport, Wales, plans a $240,000 workshop extension. The owners will use $85,000 of retained profit already in the business and raise the remainder from a bank loan. How much external finance must the business obtain?","options":{"A":"$325,000","B":"$155,000","C":"$85,000","D":"$240,000"},"correctOption":"B","correctAnswer":"$155,000","questionType":"MCQ","explanation":{"correct_reason":"External finance needed is the $240,000 cost less the $85,000 of retained profit, which equals $155,000. Retained profit is internal finance, so only the shortfall of $155,000 has to be borrowed from the bank.","distractor_reasons":{"A":"Adding the $240,000 cost to the $85,000 of retained profit gives $325,000, but internal funds reduce the amount to be borrowed rather than increase it.","B":"External finance needed is the $240,000 cost less the $85,000 of retained profit, which equals $155,000. Retained profit is internal finance, so only the shortfall of $155,000 has to be borrowed from the bank.","C":"$85,000 is the internal retained profit already available, not the external borrowing; the bank loan covers the difference between cost and internal funds.","D":"$240,000 is the total cost of the extension, but part of it is funded internally, so the external finance required is smaller."}}},{"id":"P1_U5_MCQ_1902","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1902","question":"Tarnstead Bakery in Leeds, England, is preparing its cash flow forecast for March. The owner is listing expected movements of cash during the month. Which one of the following would be recorded as a cash outflow in the forecast?","options":{"A":"Receiving payment for a birthday cake","B":"Obtaining a bank overdraft facility","C":"Selling surplus baking equipment for cash","D":"Paying the monthly electricity bill for the ovens"},"correctOption":"D","correctAnswer":"Paying the monthly electricity bill for the ovens","questionType":"MCQ","explanation":{"correct_reason":"Paying the monthly electricity bill for the ovens is a cash outflow because money leaves the bakery bank account. In a cash flow forecast, only actual cash payments such as this reduce the cash balance during March, regardless of when the supply was used.","distractor_reasons":{"A":"Receiving payment from a customer is a cash inflow, increasing the bakery bank balance rather than reducing it, so it cannot appear as an outflow.","B":"Obtaining an overdraft facility is a source of finance and brings cash into the business when drawn, so it is treated as an inflow, not a payment.","C":"Selling surplus equipment generates cash from the sale, which is an inflow in the forecast, even though the old equipment is leaving the premises.","D":"Paying the monthly electricity bill for the ovens is a cash outflow because money leaves the bakery bank account. In a cash flow forecast, only actual cash payments such as this reduce the cash balance during March, regardless of when the supply was used."}}},{"id":"P1_U5_MCQ_1903","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1903","question":"Dunmere Textiles in Manchester, England, has prepared its profit and loss account for the year ended 30 June 2026. Revenue was $620,000 and cost of sales was $380,000. Which term describes the figure of $240,000 shown before operating expenses are deducted?","options":{"A":"Gross profit","B":"Profit for the year","C":"Operating expenses","D":"Revenue"},"correctOption":"A","correctAnswer":"Gross profit","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue of $620,000 less cost of sales of $380,000, giving $240,000. It is the figure calculated before operating expenses are deducted, so it appears above the line showing profit for the year.","distractor_reasons":{"A":"Gross profit is revenue of $620,000 less cost of sales of $380,000, giving $240,000. It is the figure calculated before operating expenses are deducted, so it appears above the line showing profit for the year.","B":"Profit for the year is calculated after subtracting operating expenses and other costs from gross profit, so it would be lower than the $240,000 figure.","C":"Operating expenses such as salaries and rent are deducted from gross profit, not equal to revenue less cost of sales of $620,000 and $380,000.","D":"Revenue of $620,000 is the total sales income before any costs are subtracted, so it is larger than the $240,000 figure being described."}}},{"id":"P1_U5_MCQ_1904","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1904","question":"Elmbridge Ceramics in Stoke-on-Trent, England, is reviewing its statement of financial position. Total equity is $460,000 and non-current liabilities are $180,000. What is the capital employed in the business?","options":{"A":"$280,000","B":"$460,000","C":"$640,000","D":"$180,000"},"correctOption":"C","correctAnswer":"$640,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is the sum of total equity of $460,000 and non-current liabilities of $180,000, giving $640,000. It represents the long-term funds invested in Elmbridge Ceramics and used to finance its assets.","distractor_reasons":{"A":"Subtracting $180,000 from $460,000 gives $280,000, but capital employed combines the two long-term sources of finance rather than comparing them.","B":"$460,000 is only the owners equity stake, so it omits the $180,000 of long-term borrowed capital still in use. For Elmbridge Ceramics, option C is correct: $640,000.","C":"Capital employed is the sum of total equity of $460,000 and non-current liabilities of $180,000, giving $640,000. It represents the long-term funds invested in Elmbridge Ceramics and used to finance its assets.","D":"$180,000 is non-current liabilities on their own, so it leaves out the $460,000 of equity that owners have invested. For Elmbridge Ceramics, option C is correct: $640,000."}}},{"id":"P1_U5_MCQ_1905","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1905","question":"Fenwick Foods in Bristol, England, has current assets of $360,000 and current liabilities of $240,000 as at 31 May 2026. What is the current ratio of the business, expressed to one decimal place?","options":{"A":"0.7 : 1","B":"1.5 : 1","C":"2.0 : 1","D":"1.2 : 1"},"correctOption":"B","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets divided by current liabilities, so $360,000 divided by $240,000 equals 1.5. This means Fenwick Foods has $1.50 of current assets for every $1 of short-term debts.","distractor_reasons":{"A":"Dividing $240,000 by $360,000 reverses the formula and gives about 0.7, but the current ratio must compare assets with liabilities in that order.","B":"The current ratio is current assets divided by current liabilities, so $360,000 divided by $240,000 equals 1.5. This means Fenwick Foods has $1.50 of current assets for every $1 of short-term debts.","C":"The difference between $360,000 and $240,000 is $120,000, not a ratio; simply using those round figures as 2.0 ignores the actual division.","D":"The working capital of $120,000 is the difference between the two figures, not a ratio; 1.2 does not result from dividing $360,000 by $240,000."}}},{"id":"P1_U5_MCQ_1906","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1906","question":"Hollinsgate Dairy in Cork, Ireland, buys milk cartons from a supplier and is allowed 45 days to pay the invoice. The supplier continues delivering cartons while the dairy holds on to its cash. Which source of finance does this arrangement represent?","options":{"A":"Trade credit","B":"Bank overdraft","C":"Share issue","D":"Leasing"},"correctOption":"A","correctAnswer":"Trade credit","questionType":"MCQ","explanation":{"correct_reason":"Trade credit is short-term finance supplied by a seller that allows the buyer to receive goods now and pay later. The 45-day terms from the carton supplier let Hollinsgate Dairy hold its cash while it uses the cartons.","distractor_reasons":{"A":"Trade credit is short-term finance supplied by a seller that allows the buyer to receive goods now and pay later. The 45-day terms from the carton supplier let Hollinsgate Dairy hold its cash while it uses the cartons.","B":"A bank overdraft is an agreement with a bank to overdraw the current account, not an arrangement with the supplier of the cartons being delivered.","C":"A share issue raises long-term equity finance by selling ownership stakes to investors, which is unrelated to the 45-day payment terms on cartons.","D":"Leasing involves renting an asset such as equipment for regular payments, rather than being given time to pay for goods already delivered."}}},{"id":"P1_U5_MCQ_1907","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1907","question":"Iverfield Stores in Nottingham, England, forecasts cash inflows of $94,000 and cash outflows of $112,000 for July 2026. What is the net cash flow for that month?","options":{"A":"$206,000 surplus","B":"$18,000 surplus","C":"$206,000 deficit","D":"$18,000 deficit"},"correctOption":"D","correctAnswer":"$18,000 deficit","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is inflows minus outflows, so $94,000 minus $112,000 gives a negative figure of $18,000. Iverfield Stores therefore has a cash deficit of $18,000 for July.","distractor_reasons":{"A":"Adding $94,000 and $112,000 gives $206,000, but net cash flow subtracts payments from receipts rather than combining the two totals.","B":"The difference between the two figures is $18,000, but because outflows of $112,000 exceed inflows of $94,000 the result is a deficit, not a surplus.","C":"$206,000 is the sum of all cash movements and describes total activity, not the net position, which is the $18,000 shortfall.","D":"Net cash flow is inflows minus outflows, so $94,000 minus $112,000 gives a negative figure of $18,000. Iverfield Stores therefore has a cash deficit of $18,000 for July."}}},{"id":"P1_U5_MCQ_1908","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1908","question":"Jarrow Print in Sunderland, England, has produced a profit and loss account for the year. The owner wants to know what this financial statement mainly shows. Which statement about its purpose is correct?","options":{"A":"It lists the assets and liabilities on a single date","B":"It records only the cash received during the year","C":"It shows income and costs to calculate profit over a period","D":"It forecasts future bank balances each month"},"correctOption":"C","correctAnswer":"It shows income and costs to calculate profit over a period","questionType":"MCQ","explanation":{"correct_reason":"A profit and loss account matches the income earned with the costs incurred over a period, such as a year, to calculate the profit or loss. For Jarrow Print it therefore reports financial performance rather than position at a point in time.","distractor_reasons":{"A":"A list of assets and liabilities at one date is the statement of financial position, not the profit and loss account prepared for Jarrow Print.","B":"Recording cash received would be a cash book or receipt record; the profit and loss account includes costs even where no cash has yet changed hands.","C":"A profit and loss account matches the income earned with the costs incurred over a period, such as a year, to calculate the profit or loss. For Jarrow Print it therefore reports financial performance rather than position at a point in time.","D":"Forecasting monthly bank balances is the role of a cash flow forecast, which deals with future timing, unlike the historical profit and loss account."}}},{"id":"P1_U5_MCQ_1909","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1909","question":"Kelthrop Motors in Derby, England, has share capital of $300,000 and retained profit of $175,000 as at 31 December 2026. What is the total equity of the company?","options":{"A":"$175,000","B":"$475,000","C":"$300,000","D":"$125,000"},"correctOption":"B","correctAnswer":"$475,000","questionType":"MCQ","explanation":{"correct_reason":"Total equity is share capital of $300,000 plus retained profit of $175,000, giving $475,000. These are both claims of the owners, so they are added together to show the owners stake in Kelthrop Motors.","distractor_reasons":{"A":"$175,000 is only the retained profit, so it omits the $300,000 originally invested by shareholders when the company was formed.","B":"Total equity is share capital of $300,000 plus retained profit of $175,000, giving $475,000. These are both claims of the owners, so they are added together to show the owners stake in Kelthrop Motors.","C":"$300,000 is the share capital alone; it ignores the $175,000 of profit that has been kept in the business rather than paid out.","D":"Subtracting $175,000 from $300,000 gives $125,000, but retained profit is part of equity and must be added, not deducted. For Kelthrop Motors, option B is correct: $475,000."}}},{"id":"P1_U5_MCQ_1910","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1910","question":"Loxmere Joinery in Exeter, England, expects to make a profit next month but has been warned that its bank balance may still fall. Which explanation for this difference is most likely to be correct?","options":{"A":"Profit and cash flow are always identical for a small business","B":"A profitable business can never run out of cash","C":"Cash flow forecasts only record sales made on credit","D":"Sales may be on credit, so profit is recorded before the cash arrives"},"correctOption":"D","correctAnswer":"Sales may be on credit, so profit is recorded before the cash arrives","questionType":"MCQ","explanation":{"correct_reason":"Credit sales are recorded as revenue when the customer is billed, so profit appears before the cash is received. Loxmere Joinery may report a profit while customers still owe money, leaving the bank balance lower than expected.","distractor_reasons":{"A":"Profit and cash flow are not identical; timing differences such as credit sales mean a profitable month can still produce a fall in the bank balance.","B":"A profitable business can still run short of cash if customers pay late, even though the profit and loss account shows a satisfactory result.","C":"Cash flow forecasts record all cash receipts and payments, not only credit sales, and would include cash from customers who pay immediately.","D":"Credit sales are recorded as revenue when the customer is billed, so profit appears before the cash is received. Loxmere Joinery may report a profit while customers still owe money, leaving the bank balance lower than expected."}}},{"id":"P1_U5_MCQ_1911","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1911","question":"Marchvale Pharma in Basel, Switzerland, wants to build a new research laboratory that will be used for at least twenty years. Which source of finance is most suitable for this long-term investment?","options":{"A":"A bank overdraft","B":"A long-term bank loan","C":"Trade credit from suppliers","D":"Retained cash from last month's sales"},"correctOption":"B","correctAnswer":"A long-term bank loan","questionType":"MCQ","explanation":{"correct_reason":"A laboratory used for twenty years needs finance that will be available for a similar period, so a long-term bank loan matches the life of the asset. Repayments can be spread over many years, avoiding pressure on short-term cash.","distractor_reasons":{"A":"A bank overdraft is repayable on demand and is intended for short-term working capital, making it unsuitable for a laboratory with a twenty-year life.","B":"A laboratory used for twenty years needs finance that will be available for a similar period, so a long-term bank loan matches the life of the asset. Repayments can be spread over many years, avoiding pressure on short-term cash.","C":"Trade credit finances the short gap between buying supplies and paying the invoice; it cannot fund a permanent building costing a large sum.","D":"Last month's retained cash is a small internal source that would be used up immediately, leaving the much larger laboratory cost unpaid."}}},{"id":"P1_U5_MCQ_1912","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1912","question":"Norbridge Plastics in Rotterdam, Netherlands, had an opening bank balance of -$25,000 at the start of August 2026. During August its net cash flow was $40,000. What was its closing bank balance?","options":{"A":"-$65,000","B":"$65,000","C":"-$15,000","D":"$15,000"},"correctOption":"D","correctAnswer":"$15,000","questionType":"MCQ","explanation":{"correct_reason":"Closing balance equals opening balance plus net cash flow, so -$25,000 plus $40,000 gives $15,000. The positive net cash flow more than covers the opening overdraft, leaving Norbridge Plastics with a small positive bank balance.","distractor_reasons":{"A":"Adding $25,000 and $40,000 as if both were outflows gives -$65,000, but the net cash flow of $40,000 is an inflow that improves the balance.","B":"$65,000 wrongly treats the opening overdraft as a positive amount; starting at -$25,000 means the business must first clear that debt.","C":"Subtracting $40,000 from -$25,000 would make the balance worse, while ignoring the full inflow; the correct closing balance is $15,000.","D":"Closing balance equals opening balance plus net cash flow, so -$25,000 plus $40,000 gives $15,000. The positive net cash flow more than covers the opening overdraft, leaving Norbridge Plastics with a small positive bank balance."}}},{"id":"P1_U5_MCQ_1913","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1913","question":"Penhollow Metals in Sheffield, England, recorded revenue of $540,000 and cost of sales of $324,000 for the year ended 30 September 2026. What was the gross profit for the year?","options":{"A":"$216,000","B":"$864,000","C":"$324,000","D":"$540,000"},"correctOption":"A","correctAnswer":"$216,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is revenue less cost of sales, so $540,000 minus $324,000 equals $216,000. This is the surplus left from sales after paying the direct costs of producing the metals sold.","distractor_reasons":{"A":"Gross profit is revenue less cost of sales, so $540,000 minus $324,000 equals $216,000. This is the surplus left from sales after paying the direct costs of producing the metals sold.","B":"Adding $540,000 and $324,000 gives $864,000, but cost of sales must be deducted from revenue when calculating gross profit. For Penhollow Metals, option A is correct: $216,000.","C":"$324,000 is the cost of sales itself, which is subtracted from revenue rather than being the resulting gross profit. For Penhollow Metals, option A is correct: $216,000.","D":"$540,000 is the total revenue before any production costs are removed, so it cannot be the gross profit figure. For Penhollow Metals, option A is correct: $216,000."}}},{"id":"P1_U5_MCQ_1914","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1914","question":"Quillbank Packaging in Hull, England, is listing the items that appear under current assets in its statement of financial position. The accountant is checking whether each item will be used, sold or converted to cash within twelve months. Which item should be included there?","options":{"A":"A factory building expected to be used for 30 years","B":"A loan due for repayment in five years","C":"Inventories of cardboard boxes held for sale","D":"Share capital issued last year"},"correctOption":"C","correctAnswer":"Inventories of cardboard boxes held for sale","questionType":"MCQ","explanation":{"correct_reason":"Inventories of cardboard boxes held for sale are current assets because they are expected to be sold or used within the next twelve months. Quillbank Packaging will convert them into cash or receivables during the normal trading cycle.","distractor_reasons":{"A":"A factory building used for thirty years is a non-current asset, since it is held for long-term use rather than for early resale.","B":"A loan repayable in five years is a non-current liability, representing a long-term obligation rather than an asset of the business.","C":"Inventories of cardboard boxes held for sale are current assets because they are expected to be sold or used within the next twelve months. Quillbank Packaging will convert them into cash or receivables during the normal trading cycle.","D":"Share capital is part of equity, showing the owners investment, and does not appear among the assets of Quillbank Packaging."}}},{"id":"P1_U5_MCQ_1915","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1915","question":"Rossmere Electronics in Gdansk, Poland, has current assets of $180,000, of which $60,000 is inventories, and current liabilities of $100,000. What is its acid test ratio?","options":{"A":"1.8 : 1","B":"1.2 : 1","C":"0.6 : 1","D":"3.0 : 1"},"correctOption":"B","correctAnswer":"1.2 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test ratio is current assets less inventories divided by current liabilities, so ($180,000 - $60,000) / $100,000 equals 1.2. It measures the ability to meet short-term debts without relying on selling stock.","distractor_reasons":{"A":"Dividing $180,000 by $100,000 gives 1.8, which is the current ratio; the acid test excludes the $60,000 of inventories from current assets.","B":"The acid test ratio is current assets less inventories divided by current liabilities, so ($180,000 - $60,000) / $100,000 equals 1.2. It measures the ability to meet short-term debts without relying on selling stock.","C":"$60,000 of inventories divided by $100,000 gives 0.6, but that is only the stock proportion, not a measure of liquid assets available.","D":"Adding $180,000 and $100,000 and dividing by $100,000 gives 2.8, not 3.0; in any case the acid test subtracts inventories rather than adding liabilities."}}},{"id":"P1_U5_MCQ_1916","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1916","question":"Selwick Timber in Vancouver, Canada, has $90,000 of retained profit and is considering whether to use it to buy a new saw. The finance director wants to know how this compares with borrowing from a bank. Which statement about retained profit is correct?","options":{"A":"It is internal finance and does not dilute the owners control","B":"It must be repaid with interest each month","C":"It gives lenders a claim on the assets","D":"It is only available to public limited companies"},"correctOption":"A","correctAnswer":"It is internal finance and does not dilute the owners control","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is internal finance because it comes from profits already earned by Selwick Timber and kept in the business. Using the $90,000 does not create new shares or give outsiders a claim, so the owners keep control.","distractor_reasons":{"A":"Retained profit is internal finance because it comes from profits already earned by Selwick Timber and kept in the business. Using the $90,000 does not create new shares or give outsiders a claim, so the owners keep control.","B":"Retained profit does not have to be repaid to a lender; unlike a bank loan, it is money already belonging to the business and its owners.","C":"A claim on assets is created by borrowing, not by retaining profit; the $90,000 is owners money with no outside security attached.","D":"Retained profit is available to sole traders, partnerships and companies alike, so it is not restricted to public limited companies."}}},{"id":"P1_U5_MCQ_1917","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1917","question":"Thornvale Toys in Warsaw, Poland, forecasts cash inflows of $76,000 and outflows of $63,000 for September 2026. What is the forecast net cash flow for September?","options":{"A":"$139,000","B":"$13,000 deficit","C":"$63,000","D":"$13,000 surplus"},"correctOption":"D","correctAnswer":"$13,000 surplus","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is cash inflows less cash outflows, so $76,000 minus $63,000 equals $13,000. Because inflows exceed outflows, Thornvale Toys expects a cash surplus of $13,000 in September.","distractor_reasons":{"A":"$139,000 is the total of $76,000 and $63,000, which measures overall cash activity rather than the net difference between receipts and payments.","B":"The $13,000 difference is a surplus, not a deficit, because the forecast inflows of $76,000 are greater than the outflows of $63,000.","C":"$63,000 is the forecast outflow total on its own; the net cash flow also takes account of the $76,000 expected to be received.","D":"Net cash flow is cash inflows less cash outflows, so $76,000 minus $63,000 equals $13,000. Because inflows exceed outflows, Thornvale Toys expects a cash surplus of $13,000 in September."}}},{"id":"P1_U5_MCQ_1918","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1918","question":"Umberfield Sports in Melbourne, Australia, is preparing a profit and loss account. The accountant is deciding where to record rent, electricity and delivery costs, which are not part of the direct cost of the goods sold. Which term describes these amounts?","options":{"A":"Cost of sales","B":"Revenue","C":"Operating expenses","D":"Current liabilities"},"correctOption":"C","correctAnswer":"Operating expenses","questionType":"MCQ","explanation":{"correct_reason":"Rent, electricity and delivery costs are operating expenses because they are not directly tied to producing each item sold. Umberfield Sports deducts them from gross profit to arrive at profit for the year.","distractor_reasons":{"A":"Cost of sales covers the direct costs of the goods sold, such as purchase costs, rather than overheads like rent and electricity.","B":"Revenue is the income from selling goods, so it is recorded at the top of the profit and loss account, not as a cost.","C":"Rent, electricity and delivery costs are operating expenses because they are not directly tied to producing each item sold. Umberfield Sports deducts them from gross profit to arrive at profit for the year.","D":"Current liabilities are debts owed, shown in the statement of financial position, whereas these costs appear in the profit and loss account."}}},{"id":"P1_U5_MCQ_1919","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1919","question":"Valecroft Hotels in Nairobi, Kenya, has current assets of $285,000 and current liabilities of $160,000 as at 31 October 2026. What is the working capital of the business?","options":{"A":"$445,000","B":"$125,000","C":"$160,000","D":"-$125,000"},"correctOption":"B","correctAnswer":"$125,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so $285,000 minus $160,000 equals $125,000. This positive figure shows Valecroft Hotels has enough short-term assets to cover its short-term obligations.","distractor_reasons":{"A":"Adding $285,000 and $160,000 gives $445,000, but working capital compares current assets with current liabilities by subtracting them. For Valecroft Hotels, option B is correct: $125,000.","B":"Working capital is current assets minus current liabilities, so $285,000 minus $160,000 equals $125,000. This positive figure shows Valecroft Hotels has enough short-term assets to cover its short-term obligations.","C":"$160,000 is only the current liabilities; the working capital figure also reflects the $285,000 of current assets held by the hotel.","D":"The result is positive because $285,000 exceeds $160,000; a negative $125,000 would mean current liabilities were larger than current assets."}}},{"id":"P1_U5_MCQ_1920","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1920","question":"Wrenford Logistics in Singapore has prepared a cash flow forecast for the next six months. The finance manager wants to brief the owners on how it will be used. What is the main purpose of producing such a forecast?","options":{"A":"To calculate the total profit earned during the period","B":"To value the non-current assets of the business","C":"To list every customer who owes money","D":"To predict cash shortfalls and plan borrowing in advance"},"correctOption":"D","correctAnswer":"To predict cash shortfalls and plan borrowing in advance","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast predicts future cash inflows and outflows so that Wrenford Logistics can see when a shortfall may occur and arrange borrowing in advance. It helps manage liquidity rather than measure profit.","distractor_reasons":{"A":"Profit is calculated in the profit and loss account by matching income with costs, not in a cash flow forecast that tracks actual cash movements.","B":"Valuing non-current assets is part of the statement of financial position or asset register, not the forward-looking cash flow forecast.","C":"Listing customers who owe money produces the receivables ledger; the cash forecast uses that information but does not itself list each debtor.","D":"A cash flow forecast predicts future cash inflows and outflows so that Wrenford Logistics can see when a shortfall may occur and arrange borrowing in advance. It helps manage liquidity rather than measure profit."}}},{"id":"P1_U5_MCQ_1921","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1921","question":"Zareldon Textiles in Casablanca, Morocco, is buying a $120,000 delivery van. The supplier requires a deposit of 20% of the price, and the balance will be financed by a bank loan. How much will the bank loan be?","options":{"A":"$24,000","B":"$96,000","C":"$120,000","D":"$100,000"},"correctOption":"B","correctAnswer":"$96,000","questionType":"MCQ","explanation":{"correct_reason":"A 20% deposit on the $120,000 van is $24,000, so the remaining 80% equals $96,000. Zareldon Textiles therefore borrows $96,000 from the bank to cover the balance of the purchase price.","distractor_reasons":{"A":"$24,000 is the deposit paid upfront, not the amount borrowed; the bank loan covers the rest of the $120,000 price.","B":"A 20% deposit on the $120,000 van is $24,000, so the remaining 80% equals $96,000. Zareldon Textiles therefore borrows $96,000 from the bank to cover the balance of the purchase price.","C":"$120,000 is the full price of the van, but the 20% deposit means only part of it needs to be financed externally.","D":"$100,000 would be the balance after a $20,000 deposit, but 20% of $120,000 is $24,000, leaving $96,000. For Zareldon Textiles, option B is correct: $96,000."}}},{"id":"P1_U5_MCQ_1922","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1922","question":"Beckvale Cafes in Lisbon, Portugal, is listing items for next month's cash flow forecast. Which one of the following should not be included because it involves no movement of cash?","options":{"A":"Cash paid to the electricity supplier","B":"Cash received from customers","C":"Cash payment for new coffee machines","D":"An annual charge for depreciation of equipment"},"correctOption":"D","correctAnswer":"An annual charge for depreciation of equipment","questionType":"MCQ","explanation":{"correct_reason":"Depreciation is an accounting charge that spreads the cost of equipment over its life; no cash moves when it is recorded. Beckvale Cafes should therefore exclude it from a cash flow forecast, which records only actual cash receipts and payments.","distractor_reasons":{"A":"Cash paid to the electricity supplier is a genuine cash outflow and must be included in the forecast because it reduces the bank balance.","B":"Cash received from customers is a cash inflow that increases the bank balance and belongs in the forecast for the month.","C":"Paying cash for new coffee machines is an outflow of cash, so it appears in the forecast even though the machines are assets.","D":"Depreciation is an accounting charge that spreads the cost of equipment over its life; no cash moves when it is recorded. Beckvale Cafes should therefore exclude it from a cash flow forecast, which records only actual cash receipts and payments."}}},{"id":"P1_U5_MCQ_1923","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1923","question":"Cliffgate Foods in Auckland, New Zealand, sells a hamper for $150 that cost the business $100 to buy. The owner says the markup is 50%. Which calculation supports this statement?","options":{"A":"($150 - $100) / $100 = 50%","B":"($150 - $100) / $150 = 33.3%","C":"$150 / $100 = 150%","D":"$100 / $150 = 66.7%"},"correctOption":"A","correctAnswer":"($150 - $100) / $100 = 50%","questionType":"MCQ","explanation":{"correct_reason":"Markup is calculated as gross profit divided by cost of sales. Here the gross profit is $150 minus $100, which is $50, and $50 divided by the $100 cost gives 50%, so the owner's statement is correct.","distractor_reasons":{"A":"Markup is calculated as gross profit divided by cost of sales. Here the gross profit is $150 minus $100, which is $50, and $50 divided by the $100 cost gives 50%, so the owner's statement is correct.","B":"Dividing the $50 profit by the $150 selling price gives 33.3%, which is the gross profit margin, not the markup on cost.","C":"$150 divided by $100 gives 150%, which compares selling price with cost but does not isolate the profit added. For Cliffgate Foods, option A is correct: ($150 - $100) / $100 = 50%.","D":"$100 divided by $150 gives 66.7%, the proportion of the selling price that is cost, rather than the markup. For Cliffgate Foods, option A is correct: ($150 - $100) / $100 = 50%."}}},{"id":"P1_U5_MCQ_1924","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1924","question":"Dalewick Ceramics in Valencia, Spain, holds non-current assets of $720,000 and current assets of $260,000. What is the total value of assets in its statement of financial position?","options":{"A":"$460,000","B":"$720,000","C":"$980,000","D":"$260,000"},"correctOption":"C","correctAnswer":"$980,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are non-current assets of $720,000 plus current assets of $260,000, giving $980,000. Both categories are resources controlled by Dalewick Ceramics, so they are added together in the statement of financial position.","distractor_reasons":{"A":"Subtracting $260,000 from $720,000 gives $460,000, but total assets add the two groups of resources rather than comparing them. For Dalewick Ceramics, option C is correct: $980,000.","B":"$720,000 covers only the non-current assets; the $260,000 of current assets must be included in the total. For Dalewick Ceramics, option C is correct: $980,000.","C":"Total assets are non-current assets of $720,000 plus current assets of $260,000, giving $980,000. Both categories are resources controlled by Dalewick Ceramics, so they are added together in the statement of financial position.","D":"$260,000 is the current assets alone and leaves out the longer-term resources worth $720,000 owned by the business. For Dalewick Ceramics, option C is correct: $980,000."}}},{"id":"P1_U5_MCQ_1925","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1925","question":"Evermere Stores in Oslo, Norway, reported profit for the year of $84,000 on revenue of $600,000. What was the profit margin for the year, to one decimal place?","options":{"A":"7.1%","B":"14.0%","C":"16.7%","D":"86.0%"},"correctOption":"B","correctAnswer":"14.0%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit for the year divided by revenue, multiplied by 100, so $84,000 divided by $600,000 equals 14.0%. This shows that Evermere Stores kept $14 of every $100 of sales as profit.","distractor_reasons":{"A":"Dividing $600,000 by $84,000 and reversing gives about 7.1%, which reverses the formula; profit margin compares profit with revenue. For Evermere Stores, option B is correct: 14.0%.","B":"Profit margin is profit for the year divided by revenue, multiplied by 100, so $84,000 divided by $600,000 equals 14.0%. This shows that Evermere Stores kept $14 of every $100 of sales as profit.","C":"Profit as a share of costs rather than revenue gives a different figure; the correct denominator is the $600,000 of revenue.","D":"86.0% is the proportion of revenue absorbed by costs, found by subtracting the margin from 100%, not the profit margin itself."}}},{"id":"P1_U5_MCQ_1926","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1926","question":"Falstock Motors in Turin, Italy, needs delivery vans but does not want to buy them outright. It agrees to make monthly payments for the use of the vans over four years. Which source of finance is this?","options":{"A":"Leasing","B":"Share capital","C":"Trade credit","D":"Retained profit"},"correctOption":"A","correctAnswer":"Leasing","questionType":"MCQ","explanation":{"correct_reason":"Leasing is a form of finance where the business rents an asset and pays regular instalments for its use without owning it. Falstock Motors keeps cash available while using the vans for the four-year term.","distractor_reasons":{"A":"Leasing is a form of finance where the business rents an asset and pays regular instalments for its use without owning it. Falstock Motors keeps cash available while using the vans for the four-year term.","B":"Share capital involves selling ownership in the company to investors, which does not describe renting vans through monthly payments. For Falstock Motors, option A is correct: leasing.","C":"Trade credit is time allowed by a supplier to pay for goods already delivered, not a contract to rent an asset over four years.","D":"Retained profit uses money already earned by the business; here Falstock Motors is obtaining the use of vans without spending its saved profits."}}},{"id":"P1_U5_MCQ_1927","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1927","question":"Glenbank Hotels in Edinburgh, Scotland, expects cash inflows of $58,000 and outflows of $71,000 in November 2026. What is the forecast net cash flow for November?","options":{"A":"$129,000","B":"$13,000 surplus","C":"$71,000","D":"$13,000 deficit"},"correctOption":"D","correctAnswer":"$13,000 deficit","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow equals inflows minus outflows, so $58,000 minus $71,000 gives -$13,000. Glenbank Hotels therefore forecasts a cash deficit of $13,000, meaning payments exceed receipts during November.","distractor_reasons":{"A":"$129,000 is the sum of $58,000 and $71,000 and shows total cash movements, not the net shortfall for the month.","B":"The difference of $13,000 is a deficit rather than a surplus because outflows of $71,000 are larger than inflows of $58,000.","C":"$71,000 is the outflow total; the net cash flow must also take the $58,000 of expected receipts into account. For Glenbank Hotels, option D is correct: $13,000 deficit.","D":"Net cash flow equals inflows minus outflows, so $58,000 minus $71,000 gives -$13,000. Glenbank Hotels therefore forecasts a cash deficit of $13,000, meaning payments exceed receipts during November."}}},{"id":"P1_U5_MCQ_1928","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1928","question":"Hurstvale Print in Toronto, Canada, is explaining the term cost of sales to a new bookkeeper. The figure appears as the first deduction from revenue in the profit and loss account. Which description is correct?","options":{"A":"All expenses including rent and advertising","B":"The amount of profit left after all costs","C":"The direct cost of the goods or services sold","D":"The total cash paid to suppliers during the year"},"correctOption":"C","correctAnswer":"The direct cost of the goods or services sold","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is the direct cost of producing or buying the goods and services that were sold during the period. Hurstvale Print deducts it from revenue to determine gross profit before other expenses are considered.","distractor_reasons":{"A":"Rent and advertising are operating expenses that appear after gross profit, rather than forming part of the direct cost of the printed items sold.","B":"Profit left after all costs is profit for the year, which is calculated after deducting both cost of sales and operating expenses.","C":"Cost of sales is the direct cost of producing or buying the goods and services that were sold during the period. Hurstvale Print deducts it from revenue to determine gross profit before other expenses are considered.","D":"Cash paid to suppliers may include payments for unsold materials or equipment, so it need not equal the cost of sales in the period."}}},{"id":"P1_U5_MCQ_1929","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1929","question":"Iverton Joinery in Dublin, Ireland, has total assets of $560,000 and total liabilities of $210,000 as at 31 March 2026. What is the total equity of the business?","options":{"A":"$770,000","B":"$350,000","C":"$210,000","D":"$560,000"},"correctOption":"B","correctAnswer":"$350,000","questionType":"MCQ","explanation":{"correct_reason":"The accounting equation states that assets equal liabilities plus equity, so equity is $560,000 minus $210,000, giving $350,000. This is the owners claim on the net assets of Iverton Joinery.","distractor_reasons":{"A":"Adding $560,000 and $210,000 gives $770,000, but the equation subtracts what is owed from what is owned to find the equity.","B":"The accounting equation states that assets equal liabilities plus equity, so equity is $560,000 minus $210,000, giving $350,000. This is the owners claim on the net assets of Iverton Joinery.","C":"$210,000 is the total liabilities; it is deducted from assets rather than being the residual claim of the owners. For Iverton Joinery, option B is correct: $350,000.","D":"$560,000 is the total assets and must cover both the $210,000 owed to others and the $350,000 belonging to owners."}}},{"id":"P1_U5_MCQ_1930","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1930","question":"Juniclare Fashion in Milan, Italy, is comparing its results with a rival business using accounting ratios. What is a valid limitation of comparing ratios between two different businesses?","options":{"A":"Ratios always give a complete picture of business performance","B":"Ratios use only cash transactions","C":"Ratios cannot be calculated from published accounts","D":"Different businesses may value assets or recognise costs differently"},"correctOption":"D","correctAnswer":"Different businesses may value assets or recognise costs differently","questionType":"MCQ","explanation":{"correct_reason":"Ratio comparisons can be distorted when businesses use different accounting policies, such as different depreciation methods or stock valuation. Juniclare Fashion should therefore treat a single ratio difference as a signal to investigate, not proof.","distractor_reasons":{"A":"Ratios do not give a complete picture; they simplify results and should be combined with other information about the business.","B":"Ratios are calculated from accounting figures, which include accruals and non-cash items, so they are not limited to cash transactions.","C":"Ratios can be calculated from published accounts such as the profit and loss account and statement of financial position. For Juniclare Fashion, option D is correct: different businesses may value assets or recognise costs differently.","D":"Ratio comparisons can be distorted when businesses use different accounting policies, such as different depreciation methods or stock valuation. Juniclare Fashion should therefore treat a single ratio difference as a signal to investigate, not proof."}}},{"id":"P1_U5_MCQ_1931","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1931","question":"Kirkfield Energy in Aberdeen, Scotland, has been offered a government grant towards the cost of installing solar panels. Which statement about a grant is correct?","options":{"A":"It must be repaid with interest like a bank loan","B":"It is external finance that usually does not dilute ownership","C":"It is a form of share capital issued to investors","D":"It can only be used to pay wages"},"correctOption":"B","correctAnswer":"It is external finance that usually does not dilute ownership","questionType":"MCQ","explanation":{"correct_reason":"A government grant is external finance provided by a public body, often to encourage investment such as solar panels. It does not normally require repayment or give outsiders ownership, so Kirkfield Energy keeps control.","distractor_reasons":{"A":"A grant is not a loan, so it does not carry interest or a repayment obligation of the kind attached to bank borrowing.","B":"A government grant is external finance provided by a public body, often to encourage investment such as solar panels. It does not normally require repayment or give outsiders ownership, so Kirkfield Energy keeps control.","C":"A grant is not share capital; issuing shares would dilute the existing owners, whereas a grant carries no ownership claim.","D":"Grants are awarded for specific purposes such as equipment or investment, and are not restricted to paying employees wages. For Kirkfield Energy, option B is correct: it is external finance that usually does not dilute ownership."}}},{"id":"P1_U5_MCQ_1932","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1932","question":"Larkbank Couriers in Kuala Lumpur, Malaysia, pays its drivers weekly but receives payment from customers 30 days after invoicing. What problem is the business most likely to face?","options":{"A":"It will always make a loss","B":"Its profit margin will fall to zero","C":"It will have too much inventory","D":"It may face a short-term cash shortage despite being profitable"},"correctOption":"D","correctAnswer":"It may face a short-term cash shortage despite being profitable","questionType":"MCQ","explanation":{"correct_reason":"Paying wages weekly while collecting cash after 30 days creates a timing gap. Larkbank Couriers can be profitable on paper yet still need cash to pay drivers before customers settle their invoices.","distractor_reasons":{"A":"A timing difference does not mean the business makes a loss; over time the revenue from customers should exceed the wage costs.","B":"Profit margin depends on prices and costs, not on when cash is received, so a 30-day collection period does not force the margin to zero.","C":"Inventory levels relate to stock held for sale, whereas this problem concerns the timing of payments to drivers and receipts from customers.","D":"Paying wages weekly while collecting cash after 30 days creates a timing gap. Larkbank Couriers can be profitable on paper yet still need cash to pay drivers before customers settle their invoices."}}},{"id":"P1_U5_MCQ_1933","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1933","question":"Mosswell Bakery in Paris, France, had gross profit of $210,000 and operating expenses of $138,000 for the year. What was its profit for the year before tax?","options":{"A":"$72,000","B":"$348,000","C":"$138,000","D":"$210,000"},"correctOption":"A","correctAnswer":"$72,000","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is gross profit minus operating expenses, so $210,000 minus $138,000 equals $72,000. This is the amount left for Mosswell Bakery after covering both direct and overhead costs.","distractor_reasons":{"A":"Profit for the year is gross profit minus operating expenses, so $210,000 minus $138,000 equals $72,000. This is the amount left for Mosswell Bakery after covering both direct and overhead costs.","B":"Adding $210,000 and $138,000 gives $348,000, but expenses must be deducted from gross profit rather than added to it. For Mosswell Bakery, option A is correct: $72,000.","C":"$138,000 is the total operating expenses, which are subtracted from gross profit, not the resulting profit. For Mosswell Bakery, option A is correct: $72,000.","D":"$210,000 is the gross profit before overheads; the $138,000 of expenses must be removed to find profit for the year."}}},{"id":"P1_U5_MCQ_1934","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1934","question":"Norvale Pharmaceuticals in Zurich, Switzerland, is explaining the meaning of equity in its statement of financial position. The finance team wants a clear definition for new shareholders. Which description is correct?","options":{"A":"The money owed to suppliers","B":"The value of equipment owned","C":"The owners claim on the net assets of the business","D":"The cash held in the bank account"},"correctOption":"C","correctAnswer":"The owners claim on the net assets of the business","questionType":"MCQ","explanation":{"correct_reason":"Equity represents the owners claim on the business after all liabilities have been deducted from assets. For Norvale Pharmaceuticals it includes share capital and retained profit, showing the stake belonging to shareholders.","distractor_reasons":{"A":"Money owed to suppliers is a current liability, so it is a claim by outsiders rather than part of the owners equity.","B":"Equipment is an asset; its value contributes to the business but does not by itself represent the shareholders claim. For Norvale Pharmaceuticals, option C is correct: the owners claim on the net assets of the business.","C":"Equity represents the owners claim on the business after all liabilities have been deducted from assets. For Norvale Pharmaceuticals it includes share capital and retained profit, showing the stake belonging to shareholders.","D":"Bank cash is one current asset among several, whereas equity is a residual claim on net assets after liabilities. For Norvale Pharmaceuticals, option C is correct: the owners claim on the net assets of the business."}}},{"id":"P1_U5_MCQ_1935","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1935","question":"Orchwell Media in Stockholm, Sweden, reported operating profit of $96,000 and capital employed of $600,000. What is its return on capital employed, to one decimal place?","options":{"A":"6.3%","B":"16.0%","C":"9.6%","D":"84.0%"},"correctOption":"B","correctAnswer":"16.0%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, multiplied by 100, so $96,000 divided by $600,000 gives 16.0%. It shows how effectively Orchwell Media uses its long-term funds to generate profit.","distractor_reasons":{"A":"Dividing $600,000 by $96,000 and inverting gives about 6.3%, which reverses the formula; the profit is divided by capital employed.","B":"Return on capital employed is operating profit divided by capital employed, multiplied by 100, so $96,000 divided by $600,000 gives 16.0%. It shows how effectively Orchwell Media uses its long-term funds to generate profit.","C":"Using $96,000 as a share of capital plus profit would give a smaller figure, but the denominator must be the $600,000 capital employed.","D":"84.0% is the complement of the return, not the return itself; it does not describe the profit earned per dollar of capital."}}},{"id":"P1_U5_MCQ_1936","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1936","question":"Pinefield Recycling in Copenhagen, Denmark, needs extra cash for three months to cover the gap between paying workers and receiving payment from the council. Which source of finance is most appropriate?","options":{"A":"A bank overdraft","B":"A new issue of shares","C":"A twenty-year mortgage","D":"A government bond"},"correctOption":"A","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"A bank overdraft provides flexible short-term finance that can be used for a few months and repaid when the council pays. Pinefield Recycling needs a temporary cash bridge, not a long-term commitment such as shares or a mortgage.","distractor_reasons":{"A":"A bank overdraft provides flexible short-term finance that can be used for a few months and repaid when the council pays. Pinefield Recycling needs a temporary cash bridge, not a long-term commitment such as shares or a mortgage.","B":"Issuing shares raises permanent equity meant for long-term growth, which is disproportionate to a three-month working capital gap. For Pinefield Recycling, option A is correct: a bank overdraft.","C":"A twenty-year mortgage is designed to fund property over decades, so it is far too long and rigid for a three-month cash need.","D":"A government bond is a long-term debt investment and is not a source that a small recycler would arrange for a short-term gap."}}},{"id":"P1_U5_MCQ_1937","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1937","question":"Quinbay Water in Cape Town, South Africa, began December 2026 with a bank balance of $12,000. Its net cash flow for the month was -$19,000. What was the closing bank balance?","options":{"A":"$31,000","B":"$7,000","C":"-$31,000","D":"-$7,000"},"correctOption":"D","correctAnswer":"-$7,000","questionType":"MCQ","explanation":{"correct_reason":"Closing balance equals opening balance plus net cash flow, so $12,000 plus -$19,000 gives -$7,000. The negative net cash flow exceeds the opening balance, leaving Quinbay Water with an overdraft of $7,000.","distractor_reasons":{"A":"Adding $12,000 and $19,000 as positives gives $31,000, but the net cash flow is negative and must reduce the balance.","B":"$7,000 ignores the sign; because the outflow exceeds the opening balance, the closing position is an overdraft, not a positive amount.","C":"-$31,000 treats both amounts as negative, yet the opening balance of $12,000 is a positive starting point. For Quinbay Water, option D is correct: -$7,000.","D":"Closing balance equals opening balance plus net cash flow, so $12,000 plus -$19,000 gives -$7,000. The negative net cash flow exceeds the opening balance, leaving Quinbay Water with an overdraft of $7,000."}}},{"id":"P1_U5_MCQ_1938","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1938","question":"Rosstock Footwear in Braga, Portugal, delivered shoes to a customer in December but did not receive payment until January. In which period should the sale be recorded in the profit and loss account?","options":{"A":"In January, when the cash arrives","B":"In neither period, because no invoice was sent","C":"In December, when the sale was made","D":"Equally across both periods"},"correctOption":"C","correctAnswer":"In December, when the sale was made","questionType":"MCQ","explanation":{"correct_reason":"The profit and loss account records revenue when the sale is earned, not when cash is received. Rosstock Footwear delivered the shoes in December, so the sale belongs in December figures under the matching concept.","distractor_reasons":{"A":"Recording revenue only when cash arrives confuses cash flow with profit; the January receipt is a cash inflow, not the point of sale.","B":"The delivery in December created the sale, so it must be recorded in that period whether or not an invoice was issued later.","C":"The profit and loss account records revenue when the sale is earned, not when cash is received. Rosstock Footwear delivered the shoes in December, so the sale belongs in December figures under the matching concept.","D":"Revenue is recognised in the period the goods are supplied, not spread evenly across periods on the basis of payment dates."}}},{"id":"P1_U5_MCQ_1939","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1939","question":"Selvale Logistics in Hamburg, Germany, has current liabilities of $145,000 and non-current liabilities of $230,000 as at 31 March 2026. What is the total liabilities figure for the business?","options":{"A":"$85,000","B":"$375,000","C":"$230,000","D":"$145,000"},"correctOption":"B","correctAnswer":"$375,000","questionType":"MCQ","explanation":{"correct_reason":"Total liabilities are current liabilities of $145,000 plus non-current liabilities of $230,000, giving $375,000. Both represent amounts owed by Selvale Logistics, whether due within a year or after a longer period.","distractor_reasons":{"A":"Subtracting $145,000 from $230,000 gives $85,000, but the two types of liability are added to show the total owed. For Selvale Logistics, option B is correct: $375,000.","B":"Total liabilities are current liabilities of $145,000 plus non-current liabilities of $230,000, giving $375,000. Both represent amounts owed by Selvale Logistics, whether due within a year or after a longer period.","C":"$230,000 is only the non-current portion; the $145,000 due within a year must also be included. For Selvale Logistics, option B is correct: $375,000.","D":"$145,000 covers just the short-term obligations and leaves out the $230,000 owed over the longer term. For Selvale Logistics, option B is correct: $375,000."}}},{"id":"P1_U5_MCQ_1940","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1940","question":"Thornbeck Plastics in Lyon, France, has calculated its current ratio for three consecutive years: 1.2, 1.5 and 1.9. What is the most reasonable interpretation of this trend?","options":{"A":"The business is becoming less profitable every year","B":"The business has no liabilities at all","C":"The ratio is irrelevant to liquidity","D":"Short-term liquidity appears to be improving over the three years"},"correctOption":"D","correctAnswer":"Short-term liquidity appears to be improving over the three years","questionType":"MCQ","explanation":{"correct_reason":"A rising current ratio from 1.2 to 1.5 and then 1.9 means current assets are growing relative to current liabilities. Thornbeck Plastics therefore appears to have improving short-term liquidity, although the quality of those assets should also be checked.","distractor_reasons":{"A":"The current ratio measures liquidity, not profitability; a fall in profit would be shown by the profit margin rather than this trend.","B":"A ratio of 1.2 already shows that current liabilities exist, because the figure compares current assets with the amount owed in the short term.","C":"The current ratio is a standard measure of liquidity, so it is relevant when assessing whether the business can meet short-term debts.","D":"A rising current ratio from 1.2 to 1.5 and then 1.9 means current assets are growing relative to current liabilities. Thornbeck Plastics therefore appears to have improving short-term liquidity, although the quality of those assets should also be checked."}}},{"id":"P1_U5_MCQ_1941","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1941","question":"Uldgate Timber in Helsinki, Finland, borrows $40,000 from a bank at an interest rate of 6% per year. What is the annual interest charge on the loan?","options":{"A":"$6,000","B":"$2,400","C":"$4,000","D":"$46,000"},"correctOption":"B","correctAnswer":"$2,400","questionType":"MCQ","explanation":{"correct_reason":"Annual interest is the loan amount multiplied by the rate, so $40,000 times 6% equals $2,400. Uldgate Timber must pay this amount each year in addition to repaying the $40,000 borrowed.","distractor_reasons":{"A":"$6,000 would be the interest if the rate were 15%, not 6%; the correct charge is 6% of the $40,000 loan.","B":"Annual interest is the loan amount multiplied by the rate, so $40,000 times 6% equals $2,400. Uldgate Timber must pay this amount each year in addition to repaying the $40,000 borrowed.","C":"$4,000 is 10% of $40,000, so it uses the wrong rate; interest must be calculated at the stated 6%. For Uldgate Timber, option B is correct: $2,400.","D":"$46,000 combines the $40,000 loan with a year interest charge, but the question asks only for the annual interest payment."}}},{"id":"P1_U5_MCQ_1942","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1942","question":"Valemere Hotels in Athens, Greece, is preparing a cash flow forecast that includes a cumulative cash flow line. The manager is unsure how it differs from the monthly net cash flow. What does the cumulative figure show?","options":{"A":"The profit earned in a single month","B":"The total sales invoiced to customers","C":"The cash balance only at the year end","D":"The running total of net cash flows over the forecast period"},"correctOption":"D","correctAnswer":"The running total of net cash flows over the forecast period","questionType":"MCQ","explanation":{"correct_reason":"Cumulative cash flow adds each month net cash flow to the previous total, giving a running figure across the forecast. Valemere Hotels can use it to see how the cash position builds up or declines over several months.","distractor_reasons":{"A":"Monthly profit is calculated in the profit and loss account and is not the same as a running total of cash movements.","B":"Sales invoiced appear in revenue; the cumulative line is based on cash receipts and payments, not on invoices raised. For Valemere Hotels, option D is correct: the running total of net cash flows over the forecast period.","C":"A year-end balance is only one point, whereas the cumulative line is updated for every period in the forecast. For Valemere Hotels, option D is correct: the running total of net cash flows over the forecast period.","D":"Cumulative cash flow adds each month net cash flow to the previous total, giving a running figure across the forecast. Valemere Hotels can use it to see how the cash position builds up or declines over several months."}}},{"id":"P1_U5_MCQ_1943","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1943","question":"Wrenstock Fashion in Madrid, Spain, sells jackets for $240 each that cost $180 to purchase. What is the gross profit margin on each jacket, to one decimal place?","options":{"A":"25.0%","B":"33.3%","C":"75.0%","D":"180%"},"correctOption":"A","correctAnswer":"25.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit per jacket is $240 minus $180, which is $60. The gross profit margin is $60 divided by the $240 selling price, giving 25.0%, the share of sales revenue left as gross profit.","distractor_reasons":{"A":"Gross profit per jacket is $240 minus $180, which is $60. The gross profit margin is $60 divided by the $240 selling price, giving 25.0%, the share of sales revenue left as gross profit.","B":"Dividing the $60 profit by the $180 cost gives 33.3%, which is markup, not the margin on selling price. For Wrenstock Fashion, option A is correct: 25.0%.","C":"75.0% is the proportion of the $240 price that represents cost; the margin is the remaining 25.0%. For Wrenstock Fashion, option A is correct: 25.0%.","D":"180% compares the $180 cost with a $100 base rather than with the selling price; the margin must use $240."}}},{"id":"P1_U5_MCQ_1944","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1944","question":"Yarstock Chemicals in Antwerp, Belgium, reports current assets of $410,000 and current liabilities of $265,000 as at 30 June 2026. What is its working capital?","options":{"A":"$675,000","B":"$265,000","C":"$145,000","D":"-$145,000"},"correctOption":"C","correctAnswer":"$145,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets less current liabilities, so $410,000 minus $265,000 equals $145,000. This positive amount indicates Yarstock Chemicals has a cushion of short-term assets over its short-term debts.","distractor_reasons":{"A":"Adding $410,000 and $265,000 gives $675,000, but working capital is found by subtracting what is owed from what is owned.","B":"$265,000 is the current liabilities on their own; the working capital figure also reflects the $410,000 of current assets. For Yarstock Chemicals, option C is correct: $145,000.","C":"Working capital is current assets less current liabilities, so $410,000 minus $265,000 equals $145,000. This positive amount indicates Yarstock Chemicals has a cushion of short-term assets over its short-term debts.","D":"A negative $145,000 would require liabilities to exceed assets, whereas here $410,000 is greater than $265,000. For Yarstock Chemicals, option C is correct: $145,000."}}},{"id":"P1_U5_MCQ_1945","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1945","question":"Zelcrest Ceramics in Prague, Czech Republic, has current assets of $312,000 and current liabilities of $195,000. What is its current ratio, to one decimal place?","options":{"A":"1.4 : 1","B":"1.6 : 1","C":"0.6 : 1","D":"2.6 : 1"},"correctOption":"B","correctAnswer":"1.6 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio divides current assets by current liabilities, so $312,000 divided by $195,000 equals 1.6. Zelcrest Ceramics therefore has $1.60 of current assets for every $1 of short-term obligations.","distractor_reasons":{"A":"Dividing $312,000 by $195,000 does not give 1.4; that figure would require a larger liability total than the $195,000 stated.","B":"The current ratio divides current assets by current liabilities, so $312,000 divided by $195,000 equals 1.6. Zelcrest Ceramics therefore has $1.60 of current assets for every $1 of short-term obligations.","C":"Dividing $195,000 by $312,000 gives about 0.6, which reverses the formula; assets must be divided by liabilities. For Zelcrest Ceramics, option B is correct: 1.6 : 1.","D":"Adding the two figures and dividing by $195,000 gives about 2.6, but the ratio compares assets with liabilities only. For Zelcrest Ceramics, option B is correct: 1.6 : 1."}}},{"id":"P1_U5_MCQ_1946","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1946","question":"Alderbank Foods in Bucharest, Romania, wants to raise a large amount of permanent capital to build two new factories. Which source of finance would provide this without creating a legal duty to repay?","options":{"A":"Ordinary share capital","B":"Trade credit","C":"Bank overdraft","D":"Leasing"},"correctOption":"A","correctAnswer":"Ordinary share capital","questionType":"MCQ","explanation":{"correct_reason":"Ordinary share capital is permanent equity finance: the money raised does not have to be repaid and no interest is compulsory. Alderbank Foods can fund its two factories over the long term, although existing owners may share control.","distractor_reasons":{"A":"Ordinary share capital is permanent equity finance: the money raised does not have to be repaid and no interest is compulsory. Alderbank Foods can fund its two factories over the long term, although existing owners may share control.","B":"Trade credit is short-term supplier finance for a few weeks or months, so it cannot provide the large permanent sum needed for two factories.","C":"A bank overdraft is repayable on demand and suitable for short-term gaps, not for long-term investment in factories. For Alderbank Foods, option A is correct: ordinary share capital.","D":"Leasing provides use of an asset for payments, but it does not raise a large lump sum of permanent capital for construction."}}},{"id":"P1_U5_MCQ_1947","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1947","question":"Branwell Logistics in Felixstowe, England, forecasts cash inflows of $132,000 and outflows of $98,500 for May 2026. What is the net cash flow for May?","options":{"A":"$230,500","B":"$33,500 deficit","C":"$98,500","D":"$33,500 surplus"},"correctOption":"D","correctAnswer":"$33,500 surplus","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is inflows minus outflows, so $132,000 minus $98,500 equals $33,500. Since inflows exceed outflows, Branwell Logistics expects a cash surplus of $33,500 for the month.","distractor_reasons":{"A":"$230,500 is the sum of the $132,000 receipts and $98,500 payments; net cash flow is the difference between them. For Branwell Logistics, option D is correct: $33,500 surplus.","B":"The $33,500 difference is a surplus, not a deficit, because the expected inflows of $132,000 exceed the outflows of $98,500.","C":"$98,500 is the outflow total alone; the net figure also takes account of the $132,000 expected to be received. For Branwell Logistics, option D is correct: $33,500 surplus.","D":"Net cash flow is inflows minus outflows, so $132,000 minus $98,500 equals $33,500. Since inflows exceed outflows, Branwell Logistics expects a cash surplus of $33,500 for the month."}}},{"id":"P1_U5_MCQ_1948","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1948","question":"Cobthorn Dairy in Wellington, New Zealand, has a gross profit of $160,000 and profit for the year of $40,000. What best explains the difference between these two figures?","options":{"A":"The business sold more than it produced","B":"Cost of sales was higher than revenue","C":"Operating expenses of $120,000 were deducted from gross profit","D":"The business received a government grant"},"correctOption":"C","correctAnswer":"Operating expenses of $120,000 were deducted from gross profit","questionType":"MCQ","explanation":{"correct_reason":"Profit for the year is gross profit less operating expenses, so $160,000 minus $40,000 leaves $120,000 of expenses. Cobthorn Dairy overheads such as wages, rent and delivery explain the gap between the two profit figures.","distractor_reasons":{"A":"Selling more than was produced relates to inventory levels, not to the difference between gross profit and profit for the year.","B":"If cost of sales exceeded revenue, gross profit would be negative; here gross profit is a positive $160,000. For Cobthorn Dairy, option C is correct: operating expenses of $120,000 were deducted from gross profit.","C":"Profit for the year is gross profit less operating expenses, so $160,000 minus $40,000 leaves $120,000 of expenses. Cobthorn Dairy overheads such as wages, rent and delivery explain the gap between the two profit figures.","D":"A government grant is not the reason here; the straightforward calculation shows $120,000 of expenses were deducted. For Cobthorn Dairy, option C is correct: operating expenses of $120,000 were deducted from gross profit."}}},{"id":"P1_U5_MCQ_1949","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1949","question":"Drayvale Packaging in Montreal, Canada, has total equity of $520,000 and non-current liabilities of $260,000 as at 31 July 2026. What is the capital employed in the business?","options":{"A":"$260,000","B":"$780,000","C":"$520,000","D":"$1,040,000"},"correctOption":"B","correctAnswer":"$780,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed is total equity of $520,000 plus non-current liabilities of $260,000, giving $780,000. It measures the long-term finance invested in Drayvale Packaging and used to acquire its assets.","distractor_reasons":{"A":"$260,000 is only the long-term borrowing and omits the $520,000 of equity invested by the owners. For Drayvale Packaging, option B is correct: $780,000.","B":"Capital employed is total equity of $520,000 plus non-current liabilities of $260,000, giving $780,000. It measures the long-term finance invested in Drayvale Packaging and used to acquire its assets.","C":"$520,000 is the equity stake alone; capital employed also includes the $260,000 of long-term borrowed funds. For Drayvale Packaging, option B is correct: $780,000.","D":"$1,040,000 would be twice the equity figure; the correct capital employed is the $520,000 equity plus $260,000 borrowed. For Drayvale Packaging, option B is correct: $780,000."}}},{"id":"P1_U5_MCQ_1950","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1950","question":"Everstock Motors in Seoul, South Korea, has improved its profit margin but wants to know whether a single ratio is enough to judge performance. The finance director wants to avoid a hasty conclusion. What is the best advice?","options":{"A":"One ratio always gives a complete judgement","B":"Ratios should never be used in business","C":"Only the current ratio matters","D":"Several ratios and comparisons over time should be considered together"},"correctOption":"D","correctAnswer":"Several ratios and comparisons over time should be considered together","questionType":"MCQ","explanation":{"correct_reason":"A single ratio highlights only one aspect of performance and can be misleading on its own. Everstock Motors should compare several ratios, such as margins and liquidity measures, and look at trends before reaching a conclusion.","distractor_reasons":{"A":"One ratio cannot give a complete judgement because it ignores other areas such as liquidity and the use of assets.","B":"Ratios are useful tools for summarising accounts; the issue is over-reliance on one measure, not using them at all. For Everstock Motors, option D is correct: several ratios and comparisons over time should be considered together.","C":"The current ratio covers liquidity only and says nothing about profitability, so it cannot be the sole measure. For Everstock Motors, option D is correct: several ratios and comparisons over time should be considered together.","D":"A single ratio highlights only one aspect of performance and can be misleading on its own. Everstock Motors should compare several ratios, such as margins and liquidity measures, and look at trends before reaching a conclusion."}}},{"id":"P1_U5_MCQ_1951","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1951","question":"Falhaven Textiles in Izmir, Turkey, is a young business with a new fabric process. It needs a substantial sum of risk capital and advice from experienced investors. Which source of finance fits this need?","options":{"A":"Trade credit","B":"Venture capital","C":"Bank overdraft","D":"Retained profit"},"correctOption":"B","correctAnswer":"Venture capital","questionType":"MCQ","explanation":{"correct_reason":"Venture capital provides risk finance to growing businesses from investors who often bring expertise and contacts. Falhaven Textiles needs both substantial funds and advice for its new process, which matches this source of equity finance.","distractor_reasons":{"A":"Trade credit is a short-term arrangement with suppliers for a few weeks and provides neither the large sum nor the specialist advice required.","B":"Venture capital provides risk finance to growing businesses from investors who often bring expertise and contacts. Falhaven Textiles needs both substantial funds and advice for its new process, which matches this source of equity finance.","C":"A bank overdraft is a short-term borrowing facility for day-to-day cash gaps, not a source of risk capital for expansion.","D":"Retained profit is limited to profits the business has already made; a young company may not have enough to fund a new process."}}},{"id":"P1_U5_MCQ_1952","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1952","question":"Glenstock Solar in Adelaide, Australia, installs panels for customers who pay after 60 days. The installer must buy panels immediately. Which statement about the cash flow forecast is correct?","options":{"A":"The forecast will show no outflows until customers pay","B":"Profit and cash flow will always be equal","C":"Paying for panels can be delayed until cash arrives","D":"The forecast will show cash outflows before the related inflows"},"correctOption":"D","correctAnswer":"The forecast will show cash outflows before the related inflows","questionType":"MCQ","explanation":{"correct_reason":"Panels must be paid for at purchase, while customers settle after 60 days, so the cash outflows occur first. Glenstock Solar forecast will therefore show negative cash flow early in the cycle even though sales are being made.","distractor_reasons":{"A":"Buying panels requires immediate cash, so outflows appear straight away in the forecast, not only when customers eventually pay. For Glenstock Solar, option D is correct: the forecast will show cash outflows before the related inflows.","B":"Profit is earned when the installation is completed, but cash arrives later, so the two figures need not be equal.","C":"Suppliers usually require payment for panels at purchase, so the business cannot simply delay paying until customers settle. For Glenstock Solar, option D is correct: the forecast will show cash outflows before the related inflows.","D":"Panels must be paid for at purchase, while customers settle after 60 days, so the cash outflows occur first. Glenstock Solar forecast will therefore show negative cash flow early in the cycle even though sales are being made."}}},{"id":"P1_U5_MCQ_1953","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1953","question":"Holkwell Brewing in Munich, Germany, had cost of sales of $270,000 and gross profit of $180,000 for the year ended 30 November 2026. What was its revenue?","options":{"A":"$450,000","B":"$90,000","C":"$270,000","D":"$180,000"},"correctOption":"A","correctAnswer":"$450,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals cost of sales plus gross profit, because gross profit is revenue minus cost of sales. Therefore $270,000 plus $180,000 gives $450,000 of sales income for Holkwell Brewing.","distractor_reasons":{"A":"Revenue equals cost of sales plus gross profit, because gross profit is revenue minus cost of sales. Therefore $270,000 plus $180,000 gives $450,000 of sales income for Holkwell Brewing.","B":"Subtracting $180,000 from $270,000 gives $90,000, but revenue is the starting figure before costs are deducted. For Holkwell Brewing, option A is correct: $450,000.","C":"$270,000 is the cost of sales; the $180,000 gross profit must be added back to arrive at revenue. For Holkwell Brewing, option A is correct: $450,000.","D":"$180,000 is the gross profit itself and is smaller than revenue because cost of sales of $270,000 is included in sales."}}},{"id":"P1_U5_MCQ_1954","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1954","question":"Inchvale Systems in Gothenburg, Sweden, is classifying the items in its statement of financial position. The accountant is considering an item that will be used in the business for many years. Which of the following is a non-current asset?","options":{"A":"Cash in the bank account","B":"Trade receivables due in 30 days","C":"A delivery vehicle expected to last eight years","D":"Inventories of spare parts"},"correctOption":"C","correctAnswer":"A delivery vehicle expected to last eight years","questionType":"MCQ","explanation":{"correct_reason":"A delivery vehicle expected to last eight years is a non-current asset because it is held for long-term use in the business rather than resale. Inchvale Systems will use it across several accounting periods.","distractor_reasons":{"A":"Cash in the bank is a current asset because it is already in its most liquid form and can be spent immediately.","B":"Receivables due in 30 days are current assets, as they will be converted into cash within the normal operating cycle.","C":"A delivery vehicle expected to last eight years is a non-current asset because it is held for long-term use in the business rather than resale. Inchvale Systems will use it across several accounting periods.","D":"Inventories of spare parts are current assets because they are held for use or sale within the next twelve months."}}},{"id":"P1_U5_MCQ_1955","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1955","question":"Jadecrest Care in Ottawa, Canada, has current assets of $150,000, including $30,000 of inventories, and current liabilities of $80,000. What is the acid test ratio?","options":{"A":"1.9 : 1","B":"1.5 : 1","C":"0.4 : 1","D":"2.3 : 1"},"correctOption":"B","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"The acid test ratio is current assets minus inventories divided by current liabilities, so ($150,000 - $30,000) divided by $80,000 equals 1.5. It tests liquidity without depending on the sale of stock.","distractor_reasons":{"A":"Dividing $150,000 by $80,000 gives 1.9, which is the current ratio; the acid test removes the $30,000 of inventories. For Jadecrest Care, option B is correct: 1.5 : 1.","B":"The acid test ratio is current assets minus inventories divided by current liabilities, so ($150,000 - $30,000) divided by $80,000 equals 1.5. It tests liquidity without depending on the sale of stock.","C":"$30,000 divided by $80,000 gives about 0.4, but that is the stock proportion, not the liquid assets available to pay debts.","D":"Adding $150,000 and $80,000 then dividing by $80,000 gives about 2.9, not 2.3; the acid test subtracts inventories instead. For Jadecrest Care, option B is correct: 1.5 : 1."}}},{"id":"P1_U5_MCQ_1956","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1956","question":"Knapfield Motors in Bratislava, Slovakia, is comparing a bank loan with issuing new shares. The owners want to keep control but are worried about regular interest payments. Which statement about these two sources of finance is correct?","options":{"A":"A loan must be repaid with interest, while shares do not require regular interest payments","B":"Shares must be repaid on a fixed date","C":"A loan gives lenders ownership of the business","D":"Shares always carry a higher interest rate than loans"},"correctOption":"A","correctAnswer":"A loan must be repaid with interest, while shares do not require regular interest payments","questionType":"MCQ","explanation":{"correct_reason":"A bank loan is debt that must be repaid with interest, creating a regular cash obligation. New shares are equity with no compulsory interest, but they dilute ownership; Knapfield Motors must weigh control against repayment pressure.","distractor_reasons":{"A":"A bank loan is debt that must be repaid with interest, creating a regular cash obligation. New shares are equity with no compulsory interest, but they dilute ownership; Knapfield Motors must weigh control against repayment pressure.","B":"Ordinary shares are permanent capital with no fixed repayment date, whereas the bank loan must be repaid under the agreed terms.","C":"A loan creates a debt claim, not ownership; only shareholders own part of Knapfield Motors and can influence decisions. For Knapfield Motors, option A is correct: a loan must be repaid with interest, while shares do not require regular interest payments.","D":"Shares do not carry an interest rate at all; dividends are paid at the directors discretion, so the comparison is incorrect."}}},{"id":"P1_U5_MCQ_1957","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1957","question":"Limebank Catering in Kampala, Uganda, forecasts cash inflows of $48,500 and outflows of $55,000 for January 2027. What is the forecast net cash flow for the month?","options":{"A":"$103,500","B":"$6,500 surplus","C":"$55,000","D":"$6,500 deficit"},"correctOption":"D","correctAnswer":"$6,500 deficit","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is inflows minus outflows, so $48,500 minus $55,000 gives -$6,500. Limebank Catering expects a cash deficit of $6,500 because its forecast payments exceed the cash it expects to receive.","distractor_reasons":{"A":"$103,500 is the total of $48,500 and $55,000 and represents overall cash movement rather than the net difference. For Limebank Catering, option D is correct: $6,500 deficit.","B":"The $6,500 gap is a deficit, not a surplus, since outflows of $55,000 are larger than inflows of $48,500. For Limebank Catering, option D is correct: $6,500 deficit.","C":"$55,000 is the outflow figure alone; the net cash flow also accounts for the $48,500 of expected receipts. For Limebank Catering, option D is correct: $6,500 deficit.","D":"Net cash flow is inflows minus outflows, so $48,500 minus $55,000 gives -$6,500. Limebank Catering expects a cash deficit of $6,500 because its forecast payments exceed the cash it expects to receive."}}},{"id":"P1_U5_MCQ_1958","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1958","question":"Merewell Publishing in Sydney, Australia, received its electricity bill in January for power used during December. The bill was unpaid at the year end. How should it be treated in the accounts?","options":{"A":"Ignored because no cash has been paid","B":"Recorded as revenue in January","C":"Included as an expense in December, with the amount owed shown as a liability","D":"Added to non-current assets"},"correctOption":"C","correctAnswer":"Included as an expense in December, with the amount owed shown as a liability","questionType":"MCQ","explanation":{"correct_reason":"Expenses are matched to the period in which they are incurred, so the December electricity belongs in December profit and loss account. Because it was unpaid, Merewell Publishing also records a current liability for the amount owed.","distractor_reasons":{"A":"Ignoring an unpaid bill would understate expenses and profit; the accounts must reflect costs incurred even if cash has not been paid.","B":"An electricity bill is an expense, not revenue, and it relates to December when the power was used. For Merewell Publishing, option C is correct: included as an expense in December, with the amount owed shown as a liability.","C":"Expenses are matched to the period in which they are incurred, so the December electricity belongs in December profit and loss account. Because it was unpaid, Merewell Publishing also records a current liability for the amount owed.","D":"An unpaid utility bill is a liability, not a non-current asset, because it is an obligation rather than a resource."}}},{"id":"P1_U5_MCQ_1959","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1959","question":"Norcrest Timber in Portland, Oregon, has equity of $340,000 and total liabilities of $190,000. According to the accounting equation, what is the total value of its assets?","options":{"A":"$150,000","B":"$530,000","C":"$340,000","D":"$190,000"},"correctOption":"B","correctAnswer":"$530,000","questionType":"MCQ","explanation":{"correct_reason":"Using the accounting equation, assets equal equity plus liabilities, so $340,000 plus $190,000 gives $530,000. Norcrest Timber must hold resources of that value to balance the claims of owners and lenders.","distractor_reasons":{"A":"Subtracting $190,000 from $340,000 gives $150,000, but the equation adds the claims to find the assets they finance. For Norcrest Timber, option B is correct: $530,000.","B":"Using the accounting equation, assets equal equity plus liabilities, so $340,000 plus $190,000 gives $530,000. Norcrest Timber must hold resources of that value to balance the claims of owners and lenders.","C":"$340,000 is the equity alone; the $190,000 owed to others also represents a claim on the business assets. For Norcrest Timber, option B is correct: $530,000.","D":"$190,000 is only the liabilities and leaves out the $340,000 of equity, both of which are financed by business assets."}}},{"id":"P1_U5_MCQ_1960","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1960","question":"Ormond Glass in Birmingham, England, has a profit margin of 8%, while the industry average is 12%. The finance director wants to avoid a hasty conclusion. What is the most cautious interpretation?","options":{"A":"Ormond Glass is certain to fail","B":"The average is always the correct target","C":"The business has no expenses","D":"Further investigation is needed into prices, costs and the mix of products sold"},"correctOption":"D","correctAnswer":"Further investigation is needed into prices, costs and the mix of products sold","questionType":"MCQ","explanation":{"correct_reason":"A lower margin than the industry average signals a question, not a verdict. Ormond Glass may sell cheaper products, face different costs or use different accounting policies, so the cause should be investigated before drawing conclusions.","distractor_reasons":{"A":"An 8% margin is still positive and does not mean the business will fail; many firms trade successfully below the average.","B":"An industry average is a useful benchmark but not a universal target, since businesses differ in size, products and strategy.","C":"A profit margin of 8% shows that expenses exist and absorbed the remaining revenue; it does not indicate they are absent.","D":"A lower margin than the industry average signals a question, not a verdict. Ormond Glass may sell cheaper products, face different costs or use different accounting policies, so the cause should be investigated before drawing conclusions."}}},{"id":"P1_U5_MCQ_1961","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1961","question":"Penhale Fisheries in Bergen, Norway, takes a one-year loan of $25,000 at 8% interest. If no repayments are made during the year, how much must be repaid at the end?","options":{"A":"$2,000","B":"$27,000","C":"$25,000","D":"$23,000"},"correctOption":"B","correctAnswer":"$27,000","questionType":"MCQ","explanation":{"correct_reason":"Interest for the year is 8% of $25,000, which is $2,000. Adding this to the $25,000 borrowed gives a total repayment of $27,000 at the end of the loan.","distractor_reasons":{"A":"$2,000 is only the interest charge; the original $25,000 borrowed must also be repaid to the lender. For Penhale Fisheries, option B is correct: $27,000.","B":"Interest for the year is 8% of $25,000, which is $2,000. Adding this to the $25,000 borrowed gives a total repayment of $27,000 at the end of the loan.","C":"$25,000 is the amount borrowed but ignores the $2,000 of interest that has accrued over the year. For Penhale Fisheries, option B is correct: $27,000.","D":"$23,000 would be the sum left after making a repayment, but no repayments were made during the year. For Penhale Fisheries, option B is correct: $27,000."}}},{"id":"P1_U5_MCQ_1962","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1962","question":"Quinstock Timber in Tallinn, Estonia, sees from its cash flow forecast that it will run short of cash for two months in winter. What action is most directly suggested by the forecast?","options":{"A":"Reduce the sales price immediately","B":"Stop trading until cash recovers","C":"Buy more timber with the remaining cash","D":"Arrange short-term borrowing before the shortfall occurs"},"correctOption":"D","correctAnswer":"Arrange short-term borrowing before the shortfall occurs","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast gives early warning of a shortfall, allowing Quinstock Timber to arrange an overdraft or other short-term facility in advance. Acting before the gap appears is more reliable than reacting once cash has run out.","distractor_reasons":{"A":"Cutting prices would reduce revenue further and is not the direct response to a short-term cash gap shown by the forecast.","B":"Stopping trading would destroy sales and is unnecessary when a temporary shortfall can be financed with short-term borrowing. For Quinstock Timber, option D is correct: arrange short-term borrowing before the shortfall occurs.","C":"Buying more timber would use up scarce cash and worsen the shortfall rather than solving the timing problem. For Quinstock Timber, option D is correct: arrange short-term borrowing before the shortfall occurs.","D":"A cash flow forecast gives early warning of a shortfall, allowing Quinstock Timber to arrange an overdraft or other short-term facility in advance. Acting before the gap appears is more reliable than reacting once cash has run out."}}},{"id":"P1_U5_MCQ_1963","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1963","question":"Rosvale Ceramics in Seville, Spain, reports revenue of $500,000 and gross profit of $200,000 as shown in the profit and loss account for the year. What was the cost of sales?","options":{"A":"$300,000","B":"$700,000","C":"$200,000","D":"$500,000"},"correctOption":"A","correctAnswer":"$300,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales is revenue minus gross profit, so $500,000 minus $200,000 equals $300,000. This is the direct cost of producing the ceramics that Rosvale Ceramics sold during the year.","distractor_reasons":{"A":"Cost of sales is revenue minus gross profit, so $500,000 minus $200,000 equals $300,000. This is the direct cost of producing the ceramics that Rosvale Ceramics sold during the year.","B":"Adding $500,000 and $200,000 gives $700,000, but cost of sales is the amount deducted from revenue to leave gross profit.","C":"$200,000 is the gross profit left after direct costs have been deducted, rather than the cost of sales itself. For Rosvale Ceramics, option A is correct: $300,000.","D":"$500,000 is the revenue before any costs; cost of sales must be smaller because gross profit is positive. For Rosvale Ceramics, option A is correct: $300,000."}}},{"id":"P1_U5_MCQ_1964","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1964","question":"Selcrest Hotels in Nice, France, has total assets of $950,000 and total equity of $620,000 as at 31 December 2026. What is the total liabilities of the business?","options":{"A":"$1,570,000","B":"$620,000","C":"$330,000","D":"$950,000"},"correctOption":"C","correctAnswer":"$330,000","questionType":"MCQ","explanation":{"correct_reason":"From the accounting equation, liabilities equal assets minus equity, so $950,000 minus $620,000 gives $330,000. This is the amount Selcrest Hotels owes to lenders and other creditors.","distractor_reasons":{"A":"Adding $950,000 and $620,000 gives $1,570,000, but the equation deducts equity from assets to find what is owed. For Selcrest Hotels, option C is correct: $330,000.","B":"$620,000 is the owners stake in the business; liabilities are the separate claim on the remaining assets. For Selcrest Hotels, option C is correct: $330,000.","C":"From the accounting equation, liabilities equal assets minus equity, so $950,000 minus $620,000 gives $330,000. This is the amount Selcrest Hotels owes to lenders and other creditors.","D":"$950,000 is the total assets, which must be split between the $620,000 of equity and the $330,000 owed to others."}}},{"id":"P1_U5_MCQ_1965","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1965","question":"Thornfield Media in Berlin, Germany, earned gross profit of $180,000 on revenue of $600,000. What was the gross profit margin for the year, to one decimal place?","options":{"A":"3.3%","B":"30.0%","C":"70.0%","D":"333.3%"},"correctOption":"B","correctAnswer":"30.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit divided by revenue, multiplied by 100, so $180,000 divided by $600,000 equals 30.0%. Thornfield Media keeps 30 cents of each sales dollar as gross profit before overheads.","distractor_reasons":{"A":"Dividing $600,000 by $180,000 and then reversing gives about 3.3%, but the margin divides gross profit by revenue. For Thornfield Media, option B is correct: 30.0%.","B":"Gross profit margin is gross profit divided by revenue, multiplied by 100, so $180,000 divided by $600,000 equals 30.0%. Thornfield Media keeps 30 cents of each sales dollar as gross profit before overheads.","C":"70.0% is the share of revenue taken by cost of sales, since $600,000 minus $180,000 is $420,000; it is not the margin.","D":"333.3% results from dividing the $600,000 revenue by the $180,000 gross profit, reversing the correct margin formula. For Thornfield Media, option B is correct: 30.0%."}}},{"id":"P1_U5_MCQ_1966","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1966","question":"Umberwell Energy in Stavanger, Norway, earned $200,000 profit and can either pay it to shareholders as dividends or keep it in the business. What is the effect of retaining it?","options":{"A":"It becomes internal finance that can be reinvested without creating a debt","B":"It must be repaid with interest next year","C":"It gives lenders a claim on the assets","D":"It reduces the owners stake in the company"},"correctOption":"A","correctAnswer":"It becomes internal finance that can be reinvested without creating a debt","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is kept in the business and becomes internal finance, available for reinvestment without interest or repayment. Umberwell Energy can fund new projects while the owners stake remains unchanged, unlike an issue of new shares.","distractor_reasons":{"A":"Retained profit is kept in the business and becomes internal finance, available for reinvestment without interest or repayment. Umberwell Energy can fund new projects while the owners stake remains unchanged, unlike an issue of new shares.","B":"Retained profit is not borrowing, so there is no interest charge or obligation to repay it to an outside lender.","C":"No lender gains a claim when profit is retained; the money already belongs to the owners of Umberwell Energy. For Umberwell Energy, option A is correct: it becomes internal finance that can be reinvested without creating a debt.","D":"Keeping profit does not reduce the owners stake; it increases the equity of the business rather than creating new shareholders."}}},{"id":"P1_U5_MCQ_1967","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1967","question":"Valecrest Print in Vilnius, Lithuania, started March 2027 with a bank overdraft of $8,000. During March its net cash flow was $21,000. What was its closing bank balance?","options":{"A":"$29,000","B":"-$29,000","C":"-$13,000","D":"$13,000"},"correctOption":"D","correctAnswer":"$13,000","questionType":"MCQ","explanation":{"correct_reason":"An overdraft of $8,000 is a negative opening balance, so -$8,000 plus the net cash flow of $21,000 gives $13,000. Valecrest Print ends March with a positive bank balance after clearing the overdraft.","distractor_reasons":{"A":"Adding $8,000 and $21,000 gives $29,000, but the opening overdraft is negative and must be repaid first. For Valecrest Print, option D is correct: $13,000.","B":"-$29,000 treats the net cash flow as negative, whereas $21,000 improves the bank position during March. For Valecrest Print, option D is correct: $13,000.","C":"-$13,000 assumes the inflow was smaller than the overdraft; in fact $21,000 exceeds the $8,000 owed. For Valecrest Print, option D is correct: $13,000.","D":"An overdraft of $8,000 is a negative opening balance, so -$8,000 plus the net cash flow of $21,000 gives $13,000. Valecrest Print ends March with a positive bank balance after clearing the overdraft."}}},{"id":"P1_U5_MCQ_1968","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1968","question":"Wrenlow Foods in Nicosia, Cyprus, buys ingredients worth $90,000 and uses them all in the year. It also pays $40,000 rent for its kitchen. Which amount forms part of cost of sales?","options":{"A":"The $40,000 rent only","B":"Both $90,000 and $40,000","C":"The $90,000 of ingredients only","D":"Neither amount"},"correctOption":"C","correctAnswer":"The $90,000 of ingredients only","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales consists of the direct costs of the goods sold, which for Wrenlow Foods is the $90,000 of ingredients used. Rent of $40,000 is an operating expense deducted later when calculating profit for the year.","distractor_reasons":{"A":"Rent is an indirect overhead, not a direct cost of the dishes produced, so it is not part of cost of sales.","B":"Including the $40,000 rent would mix direct costs with overheads; only the $90,000 of ingredients belongs in cost of sales.","C":"Cost of sales consists of the direct costs of the goods sold, which for Wrenlow Foods is the $90,000 of ingredients used. Rent of $40,000 is an operating expense deducted later when calculating profit for the year.","D":"The $90,000 of ingredients is a clear direct cost, so it must appear in cost of sales for the year."}}},{"id":"P1_U5_MCQ_1969","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1969","question":"Yarbridge Timber in Riga, Latvia, has current assets of $196,000 and current liabilities of $124,000 as at 30 September 2026. What is its working capital?","options":{"A":"$320,000","B":"$72,000","C":"$124,000","D":"-$72,000"},"correctOption":"B","correctAnswer":"$72,000","questionType":"MCQ","explanation":{"correct_reason":"Working capital is current assets minus current liabilities, so $196,000 minus $124,000 equals $72,000. The positive result shows Yarbridge Timber has more short-term assets than short-term obligations.","distractor_reasons":{"A":"Adding $196,000 and $124,000 gives $320,000, but working capital subtracts the amounts owed from the assets held. For Yarbridge Timber, option B is correct: $72,000.","B":"Working capital is current assets minus current liabilities, so $196,000 minus $124,000 equals $72,000. The positive result shows Yarbridge Timber has more short-term assets than short-term obligations.","C":"$124,000 is the current liabilities alone; the working capital figure also depends on the $196,000 of current assets. For Yarbridge Timber, option B is correct: $72,000.","D":"A negative $72,000 would require liabilities to exceed assets, which is not the case with $196,000 and $124,000. For Yarbridge Timber, option B is correct: $72,000."}}},{"id":"P1_U5_MCQ_1970","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1970","question":"Zelton Textiles in Shanghai, China, has a return on capital employed of 18%, compared with 11% two years ago. What does this most likely indicate?","options":{"A":"The business has stopped investing in assets","B":"Sales revenue has certainly doubled","C":"Liquidity must have improved","D":"Profits have grown relative to the long-term funds invested"},"correctOption":"D","correctAnswer":"Profits have grown relative to the long-term funds invested","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed compares operating profit with the long-term finance used to generate it. A rise from 11% to 18% suggests Zelton Textiles is earning more profit from each dollar of capital employed.","distractor_reasons":{"A":"A higher return does not prove that investment has stopped; it may reflect better use of existing assets or improved margins.","B":"The ratio compares profit with capital, so it cannot show that revenue has doubled without separate sales figures. For Zelton Textiles, option D is correct: profits have grown relative to the long-term funds invested.","C":"ROCE measures profitability rather than liquidity, so a current ratio would be needed to judge whether short-term liquidity improved. For Zelton Textiles, option D is correct: profits have grown relative to the long-term funds invested.","D":"Return on capital employed compares operating profit with the long-term finance used to generate it. A rise from 11% to 18% suggests Zelton Textiles is earning more profit from each dollar of capital employed."}}},{"id":"P1_U5_MCQ_1971","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1971","question":"Alderwick Pharma in Geneva, Switzerland, is choosing between new shares and a bank loan. The board is considering the effect on cash and ownership. Which statement about the loan is correct?","options":{"A":"It gives shareholders a larger stake","B":"It creates a fixed obligation to pay interest and repay the principal","C":"It never has to be repaid","D":"It is internal finance"},"correctOption":"B","correctAnswer":"It creates a fixed obligation to pay interest and repay the principal","questionType":"MCQ","explanation":{"correct_reason":"A bank loan is external debt finance that requires regular interest payments and repayment of the amount borrowed. Alderwick Pharma gains cash without giving away ownership, but takes on a fixed financial commitment.","distractor_reasons":{"A":"A loan does not give shareholders a larger stake; issuing new shares would do that, not borrowing from a bank.","B":"A bank loan is external debt finance that requires regular interest payments and repayment of the amount borrowed. Alderwick Pharma gains cash without giving away ownership, but takes on a fixed financial commitment.","C":"Unlike shares, a loan must be repaid on agreed terms, so it is incorrect to say it never has to be repaid.","D":"A loan from a bank is external finance because the funds come from outside the business, not from retained profits."}}},{"id":"P1_U5_MCQ_1972","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1972","question":"Branmere Aviation in Toulouse, France, has produced a cash flow forecast based on expected sales. What is a sensible caution about using this forecast when planning ahead?","options":{"A":"Forecasts are always accurate","B":"Cash flow forecasts contain no assumptions","C":"Actual cash flows can never differ from the forecast","D":"Actual results may differ if customers pay later than expected"},"correctOption":"D","correctAnswer":"Actual results may differ if customers pay later than expected","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast is built on assumptions about timing, especially when customers will pay. Branmere Aviation should treat it as a guide, because late payments would reduce inflows and could create an unexpected shortfall.","distractor_reasons":{"A":"Forecasts are estimates based on assumptions, not certainties, and actual cash flows frequently differ from the predicted figures. For Branmere Aviation, option D is correct: actual results may differ if customers pay later than expected.","B":"Forecasts necessarily contain assumptions about sales, costs and payment timing, so it is wrong to say they contain none. For Branmere Aviation, option D is correct: actual results may differ if customers pay later than expected.","C":"Actual cash flows can differ substantially from the forecast, especially if customers delay payment or costs rise unexpectedly. For Branmere Aviation, option D is correct: actual results may differ if customers pay later than expected.","D":"A cash flow forecast is built on assumptions about timing, especially when customers will pay. Branmere Aviation should treat it as a guide, because late payments would reduce inflows and could create an unexpected shortfall."}}},{"id":"P1_U5_MCQ_1973","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1973","question":"Cobvale Foods in Limerick, Ireland, buys a cake tin for $80 and sells it at a markup of 25% on cost. What is the selling price?","options":{"A":"$100","B":"$105","C":"$80","D":"$20"},"correctOption":"A","correctAnswer":"$100","questionType":"MCQ","explanation":{"correct_reason":"A markup of 25% on the $80 cost is $20, so the selling price is $80 plus $20, giving $100. Cobvale Foods adds this margin to the purchase cost to set the price.","distractor_reasons":{"A":"A markup of 25% on the $80 cost is $20, so the selling price is $80 plus $20, giving $100. Cobvale Foods adds this margin to the purchase cost to set the price.","B":"$105 would require a markup greater than 25%; on an $80 cost a 25% markup adds only $20. For Cobvale Foods, option A is correct: $100.","C":"$80 is the purchase cost, not the selling price; the markup must be added to determine what customers pay. For Cobvale Foods, option A is correct: $100.","D":"$20 is the markup added to the $80 cost, whereas the selling price includes both the cost and the markup."}}},{"id":"P1_U5_MCQ_1974","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1974","question":"Draymere Ceramics in Kyoto, Japan, wants to know the value of the business resources and claims on a particular date. Which financial statement provides this?","options":{"A":"The profit and loss account","B":"The cash flow forecast","C":"The statement of financial position","D":"The sales ledger"},"correctOption":"C","correctAnswer":"The statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"The statement of financial position lists assets, liabilities and equity at a specific date, giving a snapshot of what Draymere Ceramics owns and owes. It differs from the profit and loss account, which covers a period of time.","distractor_reasons":{"A":"The profit and loss account reports income and expenses over a period, not the financial position at one particular date.","B":"A cash flow forecast predicts future cash movements and does not list the assets and liabilities of the business. For Draymere Ceramics, option C is correct: the statement of financial position.","C":"The statement of financial position lists assets, liabilities and equity at a specific date, giving a snapshot of what Draymere Ceramics owns and owes. It differs from the profit and loss account, which covers a period of time.","D":"A sales ledger records amounts due from customers only, so it cannot show the full position of Draymere Ceramics. For Draymere Ceramics, option C is correct: the statement of financial position."}}},{"id":"P1_U5_MCQ_1975","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1975","question":"Everfield Hotels in Phuket, Thailand, reported revenue of $420,000 and cost of sales of $273,000. What was its gross profit margin, to one decimal place?","options":{"A":"27.3%","B":"35.0%","C":"65.0%","D":"153.8%"},"correctOption":"B","correctAnswer":"35.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $420,000 minus $273,000, which is $147,000. Dividing $147,000 by revenue of $420,000 gives a gross profit margin of 35.0% for Everfield Hotels.","distractor_reasons":{"A":"27.3% would result from dividing $273,000 by a much larger base; the margin uses gross profit of $147,000 over $420,000.","B":"Gross profit is $420,000 minus $273,000, which is $147,000. Dividing $147,000 by revenue of $420,000 gives a gross profit margin of 35.0% for Everfield Hotels.","C":"65.0% is the proportion of revenue absorbed by cost of sales, not the share left as gross profit. For Everfield Hotels, option B is correct: 35.0%.","D":"153.8% comes from dividing cost of sales by gross profit, which is not the formula for gross profit margin. For Everfield Hotels, option B is correct: 35.0%."}}},{"id":"P1_U5_MCQ_1976","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1976","question":"Falvale Motors in Stuttgart, Germany, needs $30,000 to replace some equipment and decides to use profits it earned last year that were kept in the business. Which source of finance is this?","options":{"A":"Retained profit","B":"Trade credit","C":"Venture capital","D":"A bank loan"},"correctOption":"A","correctAnswer":"Retained profit","questionType":"MCQ","explanation":{"correct_reason":"Using profits earned previously and kept in the business is retained profit, an internal source of finance. Falvale Motors does not need to borrow or issue shares, so no interest or dilution of ownership is involved.","distractor_reasons":{"A":"Using profits earned previously and kept in the business is retained profit, an internal source of finance. Falvale Motors does not need to borrow or issue shares, so no interest or dilution of ownership is involved.","B":"Trade credit comes from suppliers allowing delayed payment, not from profits the business has already earned and kept. For Falvale Motors, option A is correct: retained profit.","C":"Venture capital is external risk finance from investors; it is not the reinvestment of Falvale Motors own past profits. For Falvale Motors, option A is correct: retained profit.","D":"A bank loan would create a debt and interest charges, whereas the $30,000 comes from funds already owned by the business."}}},{"id":"P1_U5_MCQ_1977","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1977","question":"Glenvale Clothing in Dhaka, Bangladesh, began February 2027 with $5,000 in the bank. Its net cash flow for February was -$14,000. What was the closing balance?","options":{"A":"$19,000","B":"$9,000","C":"-$19,000","D":"-$9,000"},"correctOption":"D","correctAnswer":"-$9,000","questionType":"MCQ","explanation":{"correct_reason":"Closing balance equals opening balance plus net cash flow, so $5,000 plus -$14,000 gives -$9,000. Glenvale Clothing finishes February with an overdraft of $9,000 after more cash left than entered.","distractor_reasons":{"A":"$19,000 adds the two figures as positive amounts, but the net cash flow of -$14,000 reduces the opening balance. For Glenvale Clothing, option D is correct: -$9,000.","B":"$9,000 ignores the negative sign; because outflows exceeded the $5,000 opening balance, the result is an overdraft. For Glenvale Clothing, option D is correct: -$9,000.","C":"-$19,000 treats the opening $5,000 as negative too, but it was a positive balance at the start of February. For Glenvale Clothing, option D is correct: -$9,000.","D":"Closing balance equals opening balance plus net cash flow, so $5,000 plus -$14,000 gives -$9,000. Glenvale Clothing finishes February with an overdraft of $9,000 after more cash left than entered."}}},{"id":"P1_U5_MCQ_1978","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1978","question":"Holmcroft Toys in Reykjavik, Iceland, bought $120,000 of stock during the year but still holds $25,000 of it at the year end. What is the cost of sales for the year?","options":{"A":"$145,000","B":"$120,000","C":"$95,000","D":"$25,000"},"correctOption":"C","correctAnswer":"$95,000","questionType":"MCQ","explanation":{"correct_reason":"Cost of sales includes only the stock used or sold, so $120,000 of purchases less $25,000 of closing inventory gives $95,000. Holmcroft Toys excludes the unsold stock because it remains an asset at the year end.","distractor_reasons":{"A":"Adding $120,000 and $25,000 gives $145,000, but closing stock is deducted from purchases, not added, when finding cost of sales.","B":"$120,000 is the total purchased during the year; the $25,000 still held must be removed because it was not sold.","C":"Cost of sales includes only the stock used or sold, so $120,000 of purchases less $25,000 of closing inventory gives $95,000. Holmcroft Toys excludes the unsold stock because it remains an asset at the year end.","D":"$25,000 is the unsold inventory at the year end, which appears as a current asset rather than as an expense."}}},{"id":"P1_U5_MCQ_1979","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1979","question":"Inchcrest Print in Porto, Portugal, has total equity of $410,000 and non-current liabilities of $160,000 as at 31 July 2026. What is its capital employed?","options":{"A":"$250,000","B":"$570,000","C":"$410,000","D":"$160,000"},"correctOption":"B","correctAnswer":"$570,000","questionType":"MCQ","explanation":{"correct_reason":"Capital employed adds total equity of $410,000 to non-current liabilities of $160,000, giving $570,000. It represents the long-term funding used by Inchcrest Print to finance its operations and assets.","distractor_reasons":{"A":"Subtracting $160,000 from $410,000 gives $250,000, but capital employed combines the two long-term sources rather than subtracting them. For Inchcrest Print, option B is correct: $570,000.","B":"Capital employed adds total equity of $410,000 to non-current liabilities of $160,000, giving $570,000. It represents the long-term funding used by Inchcrest Print to finance its operations and assets.","C":"$410,000 is the owners equity alone; capital employed also includes the $160,000 borrowed on a long-term basis. For Inchcrest Print, option B is correct: $570,000.","D":"$160,000 is the long-term borrowing alone and leaves out the $410,000 of equity invested by the owners. For Inchcrest Print, option B is correct: $570,000."}}},{"id":"P1_U5_MCQ_1980","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1980","question":"Jadegate Hotels in Phnom Penh, Cambodia, has a current ratio of 0.8 while a rival has 1.6. What does this comparison most clearly suggest about Jadegate Hotels?","options":{"A":"It has more long-term debt than the rival","B":"Its profit margin must be twice as high","C":"It holds no inventories at all","D":"It may struggle to cover short-term obligations from current assets"},"correctOption":"D","correctAnswer":"It may struggle to cover short-term obligations from current assets","questionType":"MCQ","explanation":{"correct_reason":"A current ratio of 0.8 means current assets are worth less than current liabilities, unlike the rival ratio of 1.6. Jadegate Hotels may therefore find it harder to meet short-term debts as they fall due from its current assets.","distractor_reasons":{"A":"The current ratio compares short-term assets with short-term debts; it says nothing directly about long-term borrowing. For Jadegate Hotels, option D is correct: it may struggle to cover short-term obligations from current assets.","B":"Profit margin is a separate ratio based on profit and revenue, so it cannot be inferred from a current ratio of 0.8.","C":"A current ratio includes inventories within current assets, so it cannot show that the business holds no stock at all.","D":"A current ratio of 0.8 means current assets are worth less than current liabilities, unlike the rival ratio of 1.6. Jadegate Hotels may therefore find it harder to meet short-term debts as they fall due from its current assets."}}},{"id":"P1_U5_MCQ_1981","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1981","question":"Kelso Networks in Dublin, Ireland, needs to purchase computer servers that will be used for six years. It cannot afford the full price now but expects steady monthly cash. Which source of finance matches this need most closely?","options":{"A":"Trade credit for 30 days","B":"A six-year loan with monthly repayments","C":"An overdraft reviewed every month","D":"Issuing ordinary shares to new investors"},"correctOption":"B","correctAnswer":"A six-year loan with monthly repayments","questionType":"MCQ","explanation":{"correct_reason":"A six-year loan matches the life of the servers and spreads repayment into manageable monthly amounts that suit Kelso Networks steady cash flow. The term of the finance therefore corresponds to the period over which the asset is used.","distractor_reasons":{"A":"Thirty days trade credit covers only a brief gap before payment and cannot fund servers used over six years. For Kelso Networks, option B is correct: a six-year loan with monthly repayments.","B":"A six-year loan matches the life of the servers and spreads repayment into manageable monthly amounts that suit Kelso Networks steady cash flow. The term of the finance therefore corresponds to the period over which the asset is used.","C":"An overdraft reviewed every month is short-term and can be withdrawn, making it unsuitable for a six-year asset purchase. For Kelso Networks, option B is correct: a six-year loan with monthly repayments.","D":"Issuing shares would give away part of the ownership of Kelso Networks, which is unnecessary for financing a single server purchase."}}},{"id":"P1_U5_MCQ_1982","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1982","question":"Larkspur Catering in Manila, Philippines, includes a depreciation figure in its profit and loss account. When preparing a cash flow forecast, how should the depreciation figure be handled?","options":{"A":"Added to inflows because it creates cash","B":"Treated as a cash outflow each month","C":"Included only if the equipment is sold","D":"Excluded because it does not involve any cash payment"},"correctOption":"D","correctAnswer":"Excluded because it does not involve any cash payment","questionType":"MCQ","explanation":{"correct_reason":"Depreciation spreads the cost of an asset over time but involves no actual cash movement in the period. Larkspur Catering should leave depreciation out of the cash flow forecast, which records only real cash receipts and payments.","distractor_reasons":{"A":"Depreciation does not create cash, so it cannot be added to the inflows of a cash flow forecast. For Larkspur Catering, option D is correct: excluded because it does not involve any cash payment.","B":"There is no cash payment when depreciation is recorded, so it must not be treated as an outflow in the forecast.","C":"The forecast records cash movements, not accounting adjustments, so depreciation is excluded whether or not equipment is sold. For Larkspur Catering, option D is correct: excluded because it does not involve any cash payment.","D":"Depreciation spreads the cost of an asset over time but involves no actual cash movement in the period. Larkspur Catering should leave depreciation out of the cash flow forecast, which records only real cash receipts and payments."}}},{"id":"P1_U5_MCQ_1983","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1983","question":"Mossford Joinery in Vancouver, Canada, sells a table for $900 and makes a gross profit of $270 on it. What is the gross profit margin, to one decimal place?","options":{"A":"30.0%","B":"33.3%","C":"70.0%","D":"270%"},"correctOption":"A","correctAnswer":"30.0%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit margin is gross profit divided by selling price, so $270 divided by $900 equals 30.0%. Mossford Joinery keeps thirty cents of each sales dollar as gross profit before deducting overheads.","distractor_reasons":{"A":"Gross profit margin is gross profit divided by selling price, so $270 divided by $900 equals 30.0%. Mossford Joinery keeps thirty cents of each sales dollar as gross profit before deducting overheads.","B":"Dividing $270 by the $630 cost gives 42.9%, not 33.3%; in any case the margin must use the $900 selling price.","C":"70.0% is the share of the $900 price that is cost, leaving 30.0% as the gross profit margin. For Mossford Joinery, option A is correct: 30.0%.","D":"270% compares the profit with a $100 base rather than with the $900 selling price used in the margin formula."}}},{"id":"P1_U5_MCQ_1984","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1984","question":"Norbrook Systems in Helsinki, Finland, has non-current assets of $840,000, current assets of $215,000 and total liabilities of $390,000. What is the total equity of the business?","options":{"A":"$665,000","B":"$1,445,000","C":"$390,000","D":"$1,055,000"},"correctOption":"A","correctAnswer":"$665,000","questionType":"MCQ","explanation":{"correct_reason":"Total assets are $840,000 plus $215,000, giving $1,055,000, and equity is assets minus liabilities of $390,000, so $1,055,000 minus $390,000 equals $665,000 for Norbrook Systems.","distractor_reasons":{"A":"Total assets are $840,000 plus $215,000, giving $1,055,000, and equity is assets minus liabilities of $390,000, so $1,055,000 minus $390,000 equals $665,000 for Norbrook Systems.","B":"$1,445,000 adds the $390,000 of liabilities to total assets, but equity is the residual after subtracting what is owed. For Norbrook Systems, option A is correct: $665,000.","C":"$390,000 is the total liabilities and must be deducted from the $1,055,000 of assets to find the owners claim. For Norbrook Systems, option A is correct: $665,000.","D":"$1,055,000 is the total assets, which are shared between the $390,000 owed to others and the $665,000 of equity. For Norbrook Systems, option A is correct: $665,000."}}},{"id":"P1_U5_MCQ_1985","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1985","question":"Orchardbank Foods in Cape Town, South Africa, has current assets of $260,000 and current liabilities of $130,000 as at 31 May 2026. What is its current ratio?","options":{"A":"0.5 : 1","B":"2.0 : 1","C":"1.3 : 1","D":"3.0 : 1"},"correctOption":"B","correctAnswer":"2.0 : 1","questionType":"MCQ","explanation":{"correct_reason":"The current ratio is current assets divided by current liabilities, so $260,000 divided by $130,000 equals 2.0. Orchardbank Foods therefore has two dollars of current assets for every dollar of short-term debt.","distractor_reasons":{"A":"Dividing $130,000 by $260,000 gives 0.5, which reverses the formula; assets must be divided by liabilities. For Orchardbank Foods, option B is correct: 2.0 : 1.","B":"The current ratio is current assets divided by current liabilities, so $260,000 divided by $130,000 equals 2.0. Orchardbank Foods therefore has two dollars of current assets for every dollar of short-term debt.","C":"1.3 would require current assets of only $169,000 against $130,000, which is not the $260,000 stated in the question. For Orchardbank Foods, option B is correct: 2.0 : 1.","D":"Adding $260,000 and $130,000 and dividing by $130,000 gives 3.0, but the ratio compares assets with liabilities only. For Orchardbank Foods, option B is correct: 2.0 : 1."}}},{"id":"P1_U5_MCQ_1986","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1986","question":"Penhurst Travel in Nairobi, Kenya, currently pays its suppliers within 45 days. It is offered a discount for payment within 10 days but would need cash to do so. Which source would best cover this very short-term need?","options":{"A":"A twenty-year loan","B":"A bank overdraft","C":"A new issue of preference shares","D":"Venture capital investment"},"correctOption":"B","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"A bank overdraft is flexible short-term finance that can cover a gap of a few weeks until customers pay. Penhurst Travel can use it to take the early payment discount, then repay once cash arrives from its own sales.","distractor_reasons":{"A":"A twenty-year loan is far too long and carries a long commitment for a gap lasting only a few weeks.","B":"A bank overdraft is flexible short-term finance that can cover a gap of a few weeks until customers pay. Penhurst Travel can use it to take the early payment discount, then repay once cash arrives from its own sales.","C":"Preference shares are permanent equity and would give away a claim on profits for a very short-term cash need. For Penhurst Travel, option B is correct: a bank overdraft.","D":"Venture capital is risk finance for growing businesses and is inappropriate for a short gap of a few weeks. For Penhurst Travel, option B is correct: a bank overdraft."}}},{"id":"P1_U5_MCQ_1987","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1987","question":"Quillcrest Media in Lisbon, Portugal, forecasts closing bank balances each month for the next year. Which entry would increase the forecast cash balance in a given month?","options":{"A":"Payment of employees wages","B":"Repayment of a bank loan instalment","C":"Purchase of a new vehicle for cash","D":"Receipt of cash from a customer"},"correctOption":"D","correctAnswer":"Receipt of cash from a customer","questionType":"MCQ","explanation":{"correct_reason":"A receipt of cash from a customer is a cash inflow, which adds to the bank balance in the month it is received. Quillcrest Media records it among inflows in the cash flow forecast, raising the closing balance.","distractor_reasons":{"A":"Paying employees wages is a cash outflow that reduces the bank balance rather than increasing it. For Quillcrest Media, option D is correct: receipt of cash from a customer.","B":"Repaying a bank loan instalment sends cash out of the business, so it lowers the forecast balance in that month.","C":"Buying a vehicle for cash is an outflow; although the asset is gained, the bank balance falls when payment is made.","D":"A receipt of cash from a customer is a cash inflow, which adds to the bank balance in the month it is received. Quillcrest Media records it among inflows in the cash flow forecast, raising the closing balance."}}},{"id":"P1_U5_MCQ_1988","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1988","question":"Rosshire Clothing in Glasgow, Scotland, had revenue of $720,000, cost of sales of $396,000 and operating expenses of $180,000. What was its profit for the year?","options":{"A":"$144,000","B":"$324,000","C":"$540,000","D":"$900,000"},"correctOption":"A","correctAnswer":"$144,000","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $720,000 minus $396,000, which is $324,000, and profit for the year is $324,000 minus $180,000 of operating expenses, giving $144,000 for Rosshire Clothing.","distractor_reasons":{"A":"Gross profit is $720,000 minus $396,000, which is $324,000, and profit for the year is $324,000 minus $180,000 of operating expenses, giving $144,000 for Rosshire Clothing.","B":"$324,000 is the gross profit before the $180,000 of operating expenses are deducted. For Rosshire Clothing, option A is correct: $144,000.","C":"$540,000 is the revenue less cost of sales calculated incorrectly by adding costs; the correct gross profit is $324,000. For Rosshire Clothing, option A is correct: $144,000.","D":"$900,000 adds revenue to cost of sales, but costs must be subtracted from revenue when calculating profit. For Rosshire Clothing, option A is correct: $144,000."}}},{"id":"P1_U5_MCQ_1989","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1989","question":"Stonecrest Ceramics in Florence, Italy, has trade receivables of $95,000, inventories of $140,000, cash of $35,000 and current liabilities of $180,000. What is the value of its current assets?","options":{"A":"$180,000","B":"$270,000","C":"$235,000","D":"$450,000"},"correctOption":"B","correctAnswer":"$270,000","questionType":"MCQ","explanation":{"correct_reason":"Current assets are trade receivables of $95,000 plus inventories of $140,000 plus cash of $35,000, giving $270,000 in total for Stonecrest Ceramics. The $180,000 of current liabilities is a separate claim and is excluded.","distractor_reasons":{"A":"$180,000 is the current liabilities, which are deducted from current assets rather than forming part of them. For Stonecrest Ceramics, option B is correct: $270,000.","B":"Current assets are trade receivables of $95,000 plus inventories of $140,000 plus cash of $35,000, giving $270,000 in total for Stonecrest Ceramics. The $180,000 of current liabilities is a separate claim and is excluded.","C":"$235,000 would leave out the $35,000 of cash, but cash is a current asset and must be included in the total.","D":"$450,000 adds the $180,000 of liabilities to the $270,000 of assets, which is not how current assets are calculated. For Stonecrest Ceramics, option B is correct: $270,000."}}},{"id":"P1_U5_MCQ_1990","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1990","question":"Tarnfield Hotels in Vienna, Austria, has an acid test ratio of 0.6. The finance director is concerned about liquidity. What does this ratio most directly indicate?","options":{"A":"The business has no current liabilities","B":"Its gross profit margin is below average","C":"Liquid assets may be insufficient to pay short-term debts","D":"Its non-current assets have increased in value"},"correctOption":"C","correctAnswer":"Liquid assets may be insufficient to pay short-term debts","questionType":"MCQ","explanation":{"correct_reason":"An acid test ratio of 0.6 means liquid assets are only sixty per cent of current liabilities. Tarnfield Hotels may therefore struggle to pay short-term debts without selling inventory, which is why the finance director is concerned.","distractor_reasons":{"A":"A ratio of 0.6 compares liquid assets with current liabilities, so those liabilities must exist for the figure to be calculated.","B":"The acid test is a liquidity measure and says nothing about gross profit margin, which uses revenue and cost of sales.","C":"An acid test ratio of 0.6 means liquid assets are only sixty per cent of current liabilities. Tarnfield Hotels may therefore struggle to pay short-term debts without selling inventory, which is why the finance director is concerned.","D":"The ratio uses current assets and current liabilities, so it gives no information about the value of non-current assets. For Tarnfield Hotels, option C is correct: liquid assets may be insufficient to pay short-term debts."}}},{"id":"P1_U5_MCQ_1991","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1991","question":"Umbercrest Dairy in Krakow, Poland, wants to buy a milk processing line costing $500,000. The owners are unwilling to sell shares and prefer to spread repayment over ten years. Which source of finance best fits these requirements?","options":{"A":"A ten-year bank loan","B":"Trade credit from a supplier","C":"An issue of ordinary shares","D":"A three-month overdraft"},"correctOption":"A","correctAnswer":"A ten-year bank loan","questionType":"MCQ","explanation":{"correct_reason":"A ten-year bank loan provides the $500,000 needed without giving away ownership and allows repayment over a long period that suits a processing line. Umbercrest Dairy avoids dilution while matching the term of finance to the asset life.","distractor_reasons":{"A":"A ten-year bank loan provides the $500,000 needed without giving away ownership and allows repayment over a long period that suits a processing line. Umbercrest Dairy avoids dilution while matching the term of finance to the asset life.","B":"Trade credit covers only the short interval between delivery and payment of an invoice, not a $500,000 capital purchase. For Umbercrest Dairy, option A is correct: a ten-year bank loan.","C":"An issue of ordinary shares would give away ownership, which the owners of Umbercrest Dairy have said they do not want.","D":"A three-month overdraft is short-term and would leave the cost of the processing line unpaid after only a quarter. For Umbercrest Dairy, option A is correct: a ten-year bank loan."}}},{"id":"P1_U5_MCQ_1992","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1992","question":"Valefield Retail in Melbourne, Australia, expects a large cash surplus in December but a deficit in January. How can the cash flow forecast help management respond to this pattern?","options":{"A":"It proves the business will never need external finance","B":"It shows that December profit will equal January profit","C":"It removes the need to pay suppliers in January","D":"It highlights the January gap so funds can be set aside from December"},"correctOption":"D","correctAnswer":"It highlights the January gap so funds can be set aside from December","questionType":"MCQ","explanation":{"correct_reason":"A cash flow forecast shows the timing of surpluses and deficits across months. Valefield Retail can plan to retain some of December surplus to cover January shortfall, or arrange finance in advance, avoiding a sudden cash crisis.","distractor_reasons":{"A":"The forecast shows that external finance may be needed in January, so it does not prove the business will never borrow.","B":"The forecast tracks cash timing rather than profit, so it cannot show that December and January profits will be equal.","C":"Suppliers still expect payment in January; the forecast helps plan for that payment rather than removing the obligation. For Valefield Retail, option D is correct: it highlights the January gap so funds can be set aside from December.","D":"A cash flow forecast shows the timing of surpluses and deficits across months. Valefield Retail can plan to retain some of December surplus to cover January shortfall, or arrange finance in advance, avoiding a sudden cash crisis."}}},{"id":"P1_U5_MCQ_1993","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1993","question":"Westvale Foods in Auckland, New Zealand, reports cost of sales of $480,000 and a gross profit margin of 40%. What is its revenue, to the nearest dollar?","options":{"A":"$800,000","B":"$1,200,000","C":"$720,000","D":"$192,000"},"correctOption":"A","correctAnswer":"$800,000","questionType":"MCQ","explanation":{"correct_reason":"A gross profit margin of 40% means cost of sales is 60% of revenue. Therefore revenue is $480,000 divided by 0.6, which equals $800,000 for Westvale Foods, with gross profit of $320,000.","distractor_reasons":{"A":"A gross profit margin of 40% means cost of sales is 60% of revenue. Therefore revenue is $480,000 divided by 0.6, which equals $800,000 for Westvale Foods, with gross profit of $320,000.","B":"$1,200,000 would make cost of sales only 40% of revenue, which corresponds to a 60% margin, not the 40% stated.","C":"$720,000 would be obtained by adding 40% of $480,000, but the margin is based on revenue rather than on cost.","D":"$192,000 is 40% of the $480,000 cost, a markup calculation, not the revenue implied by a 40% margin. For Westvale Foods, option A is correct: $800,000."}}},{"id":"P1_U5_MCQ_1994","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1994","question":"Yewbank Logistics in Rotterdam, Netherlands, has total assets of $1,200,000, current liabilities of $180,000 and non-current liabilities of $340,000 as at 31 December 2026. What is its total equity?","options":{"A":"$1,720,000","B":"$680,000","C":"$520,000","D":"$1,020,000"},"correctOption":"B","correctAnswer":"$680,000","questionType":"MCQ","explanation":{"correct_reason":"Total liabilities are $180,000 plus $340,000, giving $520,000, and equity is total assets of $1,200,000 minus $520,000, which equals $680,000 for Yewbank Logistics under the accounting equation.","distractor_reasons":{"A":"$1,720,000 adds total liabilities of $520,000 to assets of $1,200,000, but equity is the residual after subtracting liabilities. For Yewbank Logistics, option B is correct: $680,000.","B":"Total liabilities are $180,000 plus $340,000, giving $520,000, and equity is total assets of $1,200,000 minus $520,000, which equals $680,000 for Yewbank Logistics under the accounting equation.","C":"$520,000 is the total owed to outsiders, which must be deducted from the $1,200,000 of assets to find the owners claim.","D":"$1,020,000 subtracts only the $180,000 of current liabilities, forgetting the $340,000 of long-term obligations. For Yewbank Logistics, option B is correct: $680,000."}}},{"id":"P1_U5_MCQ_1995","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1995","question":"Zephyra Systems in Dublin, Ireland, has operating profit of $140,000 and capital employed of $700,000 for the year ended 30 June 2026. What is its return on capital employed?","options":{"A":"20.0%","B":"5.0%","C":"80.0%","D":"25.0%"},"correctOption":"A","correctAnswer":"20.0%","questionType":"MCQ","explanation":{"correct_reason":"Return on capital employed is operating profit divided by capital employed, multiplied by 100, so $140,000 divided by $700,000 equals 20.0%. Zephyra Systems earns twenty cents of operating profit for each dollar of long-term capital.","distractor_reasons":{"A":"Return on capital employed is operating profit divided by capital employed, multiplied by 100, so $140,000 divided by $700,000 equals 20.0%. Zephyra Systems earns twenty cents of operating profit for each dollar of long-term capital.","B":"Dividing $700,000 by $140,000 gives five, but 5.0% reverses the formula; profit must be divided by capital employed. For Zephyra Systems, option A is correct: 20.0%.","C":"80.0% is the complement of the return, not the return itself, and does not measure profit per dollar of capital.","D":"25.0% would require operating profit of $175,000 on $700,000, which is not the $140,000 given in the question. For Zephyra Systems, option A is correct: 20.0%."}}},{"id":"P1_U5_MCQ_1996","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_1996","question":"Ashgrove Printing in Leeds, England, has kept $60,000 of profit in the business rather than distributing it. The owner wants to use it for a new press. Which statement about this decision is correct?","options":{"A":"It is retained profit and involves no interest charge","B":"It is a loan that must be repaid next year","C":"It gives a bank a claim on the printing press","D":"It reduces the amount of equity in the business"},"correctOption":"A","correctAnswer":"It is retained profit and involves no interest charge","questionType":"MCQ","explanation":{"correct_reason":"Keeping $60,000 of profit in the business creates internal finance known as retained profit. Ashgrove Printing can buy the press without paying interest or giving a lender any claim on its assets.","distractor_reasons":{"A":"Keeping $60,000 of profit in the business creates internal finance known as retained profit. Ashgrove Printing can buy the press without paying interest or giving a lender any claim on its assets.","B":"Retained profit is not a loan and has no repayment date, because the money already belongs to the owners of the business.","C":"No bank is involved and no security is created, so the bank gains no claim on the new printing press.","D":"Retaining profit increases equity rather than reducing it, since more earnings are kept inside Ashgrove Printing. For Ashgrove Printing, option A is correct: it is retained profit and involves no interest charge."}}},{"id":"P1_U5_MCQ_1997","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_1997","question":"Bellhaven Foods in Cork, Ireland, forecasts opening cash of $15,000, inflows of $64,000 and outflows of $79,000 for April 2027. What is the closing cash balance for April?","options":{"A":"$98,000","B":"$0","C":"$64,000","D":"$15,000"},"correctOption":"B","correctAnswer":"$0","questionType":"MCQ","explanation":{"correct_reason":"Net cash flow is $64,000 minus $79,000, giving a deficit of $15,000. Adding this to the $15,000 opening cash leaves a closing balance of $0 for Bellhaven Foods at the end of April.","distractor_reasons":{"A":"$98,000 adds the opening $15,000 to the $64,000 inflows but ignores the $79,000 of outflows entirely. For Bellhaven Foods, option B is correct: $0.","B":"Net cash flow is $64,000 minus $79,000, giving a deficit of $15,000. Adding this to the $15,000 opening cash leaves a closing balance of $0 for Bellhaven Foods at the end of April.","C":"$64,000 is the inflow total alone and ignores both the opening cash and the $79,000 paid out during April. For Bellhaven Foods, option B is correct: $0.","D":"The $15,000 figure is the opening cash and also the size of the net deficit, not the closing balance; that deficit uses up the opening cash so the balance ends at zero."}}},{"id":"P1_U5_MCQ_1998","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_1998","question":"Crestvale Bakery in Malaga, Spain, is comparing its profit and loss account with its cash flow forecast. Which item would appear in the profit and loss account but not as a cash movement in the forecast?","options":{"A":"Cash paid for flour","B":"Cash received from customers","C":"Depreciation of the ovens","D":"Payment of wages"},"correctOption":"C","correctAnswer":"Depreciation of the ovens","questionType":"MCQ","explanation":{"correct_reason":"Depreciation of the ovens is an accounting expense that spreads the cost of the asset over its useful life, but no cash is paid when it is recorded. Crestvale Bakery shows it in the profit and loss account, not in the cash forecast.","distractor_reasons":{"A":"Cash paid for flour is a genuine cash outflow that appears in both the profit and loss account and the cash flow forecast for the period.","B":"Cash received from customers is a cash inflow recorded in the forecast, so it is not an item that lacks a cash movement.","C":"Depreciation of the ovens is an accounting expense that spreads the cost of the asset over its useful life, but no cash is paid when it is recorded. Crestvale Bakery shows it in the profit and loss account, not in the cash forecast.","D":"Payment of wages involves cash leaving the business and is shown as an outflow in the forecast as well as an expense in the accounts."}}},{"id":"P1_U5_MCQ_1999","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_1999","question":"Duncraig Textiles in Perth, Australia, is listing the obligations that appear under current liabilities in its statement of financial position. The accountant is checking which debts must be settled within twelve months. Which item should be included?","options":{"A":"A loan due for repayment in eight years","B":"Trade payables due in 30 days","C":"Share capital issued to investors","D":"A delivery vehicle owned by the business"},"correctOption":"B","correctAnswer":"Trade payables due in 30 days","questionType":"MCQ","explanation":{"correct_reason":"Trade payables due in 30 days are current liabilities because they are debts that Duncraig Textiles must settle within the next twelve months. They arise from buying goods on credit from suppliers in the normal course of trading.","distractor_reasons":{"A":"A loan repayable in eight years is a non-current liability because it is a long-term obligation, not one falling due within a year.","B":"Trade payables due in 30 days are current liabilities because they are debts that Duncraig Textiles must settle within the next twelve months. They arise from buying goods on credit from suppliers in the normal course of trading.","C":"Share capital is part of equity representing the owners investment, so it is not a debt that the business must repay to outsiders.","D":"A delivery vehicle is a non-current asset owned by the business, not an obligation owed to another party. For Duncraig Textiles, option B is correct: trade payables due in 30 days."}}},{"id":"P1_U5_MCQ_2000","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_2000","question":"Eldermere Foods in Malmo, Sweden, has seen its gross profit margin fall from 32% to 24% over two years, while revenue has stayed the same. What is the most likely explanation for this change?","options":{"A":"The business has reduced its operating expenses","B":"The business has stopped selling on credit","C":"The value of non-current assets has risen","D":"Cost of sales has risen relative to revenue"},"correctOption":"D","correctAnswer":"Cost of sales has risen relative to revenue","questionType":"MCQ","explanation":{"correct_reason":"A falling gross profit margin with unchanged revenue means a larger share of each sales dollar is being absorbed by direct costs. Eldermere Foods has therefore seen cost of sales rise relative to revenue, perhaps through higher purchase prices.","distractor_reasons":{"A":"Reducing operating expenses affects profit for the year but not gross profit margin, which is calculated before overheads are deducted.","B":"Selling on credit affects the timing of cash receipts, not the gross profit margin calculated from revenue and cost of sales.","C":"Non-current asset values appear in the statement of financial position and do not affect the gross profit margin. For Eldermere Foods, option D is correct: cost of sales has risen relative to revenue.","D":"A falling gross profit margin with unchanged revenue means a larger share of each sales dollar is being absorbed by direct costs. Eldermere Foods has therefore seen cost of sales rise relative to revenue, perhaps through higher purchase prices."}}}];
